--
-- RETRATO DO SCHEMA DE PRODUÇÃO — SÓ LEITURA, NÃO APLICAR.
--
-- Gerado por `npm run db:esquema` (scripts/gerar-esquema-atual.mjs) a partir do banco, depois
-- de cada migration aplicada. Serve para ler e pesquisar o código vigente das funções e para o
-- diff do PR mostrar o que a migration mudou. Para mudar o banco, escreva uma migration.
--

--
-- PostgreSQL database dump
--

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: arquivo; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA arquivo;

--
-- Name: SCHEMA arquivo; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON SCHEMA arquivo IS 'Tabelas que saíram do sistema mas ainda não podem ser apagadas. Fora da Data API; sem acesso de anon/authenticated.';

--
-- Name: private; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA private;

--
-- Name: public; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA public;

--
-- Name: SCHEMA public; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON SCHEMA public IS 'standard public schema';

--
-- Name: FC_ABRIR_FICHAS(uuid, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ABRIR_FICHAS"(p_edital uuid, p_atribuicoes jsonb, p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_regra public."TB_REGRA_ANALISE";
  v_atrib jsonb := coalesce(p_atribuicoes, '[]'::jsonb);
  v_item record;
  v_criados uuid[] := '{}';
  v_saem integer := 0;
  v_voltam integer := 0;
  v_atribuidas integer := 0;
  v_regra_nova integer := 0;
  v_modalidade integer := 0;
  v_republicadas integer := 0;
  v_publicar record;
  v_ficha public."TB_FICHA_ANALISE";
  v_origem constant text := case when p_usuario is null then 'JOB' else 'TELA' end;
begin
  -- Uma abertura por edital de cada vez (job e tela não se atropelam).
  perform pg_advisory_xact_lock(hashtextextended('avaliacao-documental:fichas:' || p_edital::text, 0));
  select * into v_regra from public."TB_REGRA_ANALISE" where "CO_MONITORAMENTO" = p_edital;
  if v_regra."CO_REGRA_ANALISE" is null then
    raise exception 'O edital ainda não tem regra da avaliação' using errcode = '22023';
  end if;
  if jsonb_typeof(v_atrib) <> 'array' or jsonb_array_length(v_atrib) > 20000 then
    raise exception 'Atribuições inválidas (lista de até 20.000)' using errcode = '22023';
  end if;

  -- Seguem o último recálculo: a ficha ainda não concluída fica com a versão da regra da
  -- pré-classificação atual; a concluída mantém a versão com que foi analisada.
  update public."TB_FICHA_ANALISE" f
     set "NU_VERSAO_REGRA" = p."NU_VERSAO_REGRA", "DT_ATUALIZACAO" = now()
    from public."TB_PRE_CLASSIFICACAO" p
   where p."CO_MONITORAMENTO" = f."CO_MONITORAMENTO" and p."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
     and f."CO_MONITORAMENTO" = p_edital
     and f."TP_SITUACAO" <> 'CONCLUIDA'
     and f."NU_VERSAO_REGRA" is distinct from p."NU_VERSAO_REGRA";
  get diagnostics v_regra_nova = row_count;

  -- Saem do lote: eliminados (ou fora do recorte) com ficha aberta. A ficha fica, com o motivo.
  -- Fora do lote refeito (a execução da linha refez o lote): "Lote refeito em dd/mm", ação REFAZER_LOTE.
  -- O histórico (o mesmo de FC_HISTORICO_FICHA) sai no mesmo comando, com a ficha já atualizada.
  with alvo as (
    select f."CO_FICHA_ANALISE" as ficha, f."TP_SITUACAO" as situacao, f."CO_USUARIO_RESPONSAVEL" as responsavel,
           left(case when p."TP_SITUACAO" = 'RANQUEADO' and t."CO_EXECUCAO" is not null
                     then 'Lote refeito em ' || to_char(t."DT_INICIO" at time zone 'America/Sao_Paulo', 'DD/MM')
                     else coalesce(p."DS_MOTIVO_ELIMINACAO", 'Saiu do lote de convocação') end, 300) as motivo,
           case when p."TP_SITUACAO" = 'RANQUEADO' and t."CO_EXECUCAO" is not null
                then 'REFAZER_LOTE' else 'SAIR_LOTE' end as acao
      from public."TB_FICHA_ANALISE" f
      join public."TB_PRE_CLASSIFICACAO" p
        on p."CO_MONITORAMENTO" = f."CO_MONITORAMENTO" and p."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
      left join public."TL_PRE_CLASSIFICACAO" t on t."CO_EXECUCAO" = p."CO_EXECUCAO" and t."ST_REFAZER_LOTE" = 'S'
     where f."CO_MONITORAMENTO" = p_edital
       and f."TP_SITUACAO" in ('PENDENTE', 'EM_ANALISE', 'REVISAR')
       and p."TP_SITUACAO" in ('ELIMINADO', 'RANQUEADO')
  ),
  saiu as (
    update public."TB_FICHA_ANALISE" f set
      "TP_SITUACAO" = 'FORA_LOTE', "DS_MOTIVO_SAIDA" = a.motivo,
      "CO_USUARIO_RESERVA" = null, "DT_RESERVA" = null, "DT_RESERVA_EXPIRA" = null,
      "NU_VERSAO" = f."NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
      from alvo a
     where f."CO_FICHA_ANALISE" = a.ficha
    returning f."CO_FICHA_ANALISE" as ficha, f."NU_VERSAO" as versao, f."TP_SITUACAO" as situacao,
              f."CO_USUARIO_RESPONSAVEL" as responsavel, a.acao, a.situacao as situacao_anterior,
              a.responsavel as responsavel_anterior, a.motivo
  )
  insert into public."TH_FICHA_ANALISE"
    ("CO_FICHA_ANALISE", "NU_VERSAO", "TP_ACAO", "TP_SITUACAO_ANTERIOR", "TP_SITUACAO", "CO_USUARIO_RESP_ANTERIOR",
     "CO_USUARIO_RESPONSAVEL", "DS_MOTIVO", "TP_ORIGEM", "CO_USUARIO")
  select s.ficha, s.versao, s.acao, s.situacao_anterior, s.situacao, s.responsavel_anterior, s.responsavel,
         nullif(left(btrim(coalesce(s.motivo, '')), 2000), ''), v_origem, p_usuario
    from saiu s;
  get diagnostics v_saem = row_count;

  -- Voltam ao lote: quem saiu e está no lote de novo recomeça livre na fila.
  with alvo as (
    select f."CO_FICHA_ANALISE" as ficha, f."CO_USUARIO_RESPONSAVEL" as responsavel,
           coalesce('Voltou ao lote refeito em ' || to_char(t."DT_INICIO" at time zone 'America/Sao_Paulo', 'DD/MM'),
                    p."DS_MOTIVO_ENTRADA", 'Voltou ao lote de convocação') as motivo
      from public."TB_FICHA_ANALISE" f
      join public."TB_PRE_CLASSIFICACAO" p
        on p."CO_MONITORAMENTO" = f."CO_MONITORAMENTO" and p."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
      left join public."TL_PRE_CLASSIFICACAO" t on t."CO_EXECUCAO" = p."CO_EXECUCAO" and t."ST_REFAZER_LOTE" = 'S'
     where f."CO_MONITORAMENTO" = p_edital and f."TP_SITUACAO" = 'FORA_LOTE'
       and p."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO')
  ),
  voltou as (
    update public."TB_FICHA_ANALISE" f set
      "TP_SITUACAO" = 'PENDENTE', "DS_MOTIVO_SAIDA" = null, "CO_USUARIO_RESPONSAVEL" = null, "DT_ATRIBUICAO" = null,
      "NU_VERSAO" = f."NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
      from alvo a
     where f."CO_FICHA_ANALISE" = a.ficha
    returning f."CO_FICHA_ANALISE" as ficha, f."NU_VERSAO" as versao, f."TP_SITUACAO" as situacao,
              f."CO_USUARIO_RESPONSAVEL" as responsavel, a.responsavel as responsavel_anterior, a.motivo
  )
  insert into public."TH_FICHA_ANALISE"
    ("CO_FICHA_ANALISE", "NU_VERSAO", "TP_ACAO", "TP_SITUACAO_ANTERIOR", "TP_SITUACAO", "CO_USUARIO_RESP_ANTERIOR",
     "CO_USUARIO_RESPONSAVEL", "DS_MOTIVO", "TP_ORIGEM", "CO_USUARIO")
  select v.ficha, v.versao, 'VOLTAR_LOTE', 'FORA_LOTE', v.situacao, v.responsavel_anterior, v.responsavel,
         nullif(left(btrim(coalesce(v.motivo, '')), 2000), ''), v_origem, p_usuario
    from voltou v;
  get diagnostics v_voltam = row_count;

  -- As cotas seguem a pré-classificação (20261015020000; a lista desde 20261015150000): a ficha
  -- não concluída com lançamento gravado passa às cotas optadas de agora (DS_LANCAMENTO.modalidades,
  -- a principal primeiro, e .modalidade = a principal): o bloco de cota passa a valer para quem optou
  -- e deixa de valer para quem não optou, com o histórico (MODALIDADE). Só muda o que difere (o
  -- lançamento antigo sem a lista vale pela modalidade única, FC_MODALIDADES_DO_LANCAMENTO). A
  -- concluída fica como foi analisada (reabra para conferir a cota).
  with alvo as (
    select f."CO_FICHA_ANALISE" as ficha, f."TP_SITUACAO" as situacao, f."CO_USUARIO_RESPONSAVEL" as responsavel,
           private."FC_MODALIDADES_DO_LANCAMENTO"(f."DS_LANCAMENTO") as de,
           private."FC_MODALIDADES_DO_LANCAMENTO"(jsonb_build_object('modalidades', p."DS_MODALIDADES")) as para,
           coalesce(nullif(btrim(p."NO_MODALIDADE"), ''), 'AC') as principal
      from public."TB_FICHA_ANALISE" f
      join public."TB_PRE_CLASSIFICACAO" p
        on p."CO_MONITORAMENTO" = f."CO_MONITORAMENTO" and p."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
     where f."CO_MONITORAMENTO" = p_edital
       and f."TP_SITUACAO" <> 'CONCLUIDA'
       and jsonb_typeof(f."DS_LANCAMENTO") = 'object'
       and (private."FC_MODALIDADES_DO_LANCAMENTO"(f."DS_LANCAMENTO")
              is distinct from private."FC_MODALIDADES_DO_LANCAMENTO"(jsonb_build_object('modalidades', p."DS_MODALIDADES"))
            or coalesce(nullif(btrim(f."DS_LANCAMENTO" ->> 'modalidade'), ''), 'AC')
              is distinct from coalesce(nullif(btrim(p."NO_MODALIDADE"), ''), 'AC'))
  ),
  mudou as (
    update public."TB_FICHA_ANALISE" f set
      "DS_LANCAMENTO" = f."DS_LANCAMENTO" || jsonb_build_object('modalidade', a.principal, 'modalidades', to_jsonb(a.para)),
      "NU_VERSAO" = f."NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
      from alvo a
     where f."CO_FICHA_ANALISE" = a.ficha
    returning f."CO_FICHA_ANALISE" as ficha, f."NU_VERSAO" as versao, a.situacao, a.responsavel, a.de, a.para
  )
  insert into public."TH_FICHA_ANALISE"
    ("CO_FICHA_ANALISE", "NU_VERSAO", "TP_ACAO", "TP_SITUACAO_ANTERIOR", "TP_SITUACAO", "CO_USUARIO_RESP_ANTERIOR",
     "CO_USUARIO_RESPONSAVEL", "DS_MOTIVO", "TP_ORIGEM", "CO_USUARIO")
  select m.ficha, m.versao, 'MODALIDADE', m.situacao, m.situacao, m.responsavel, m.responsavel,
         'Modalidade da pré-classificação: ' || coalesce(nullif(array_to_string(m.de, ' + '), ''), 'AC')
           || ' → ' || coalesce(nullif(array_to_string(m.para, ' + '), ''), 'AC'), v_origem, p_usuario
    from mudou m;
  get diagnostics v_modalidade = row_count;

  -- A linha publicada (TB_ANALISE_CURRICULAR) com as cotas e o nome da vaga de agora (FC_MODALIDADES_DA_FICHA:
  -- as optadas antes da análise, as confirmadas depois): a ficha (qualquer situação) cuja linha
  -- MONITORA difere é publicada de novo.
  for v_publicar in
    select s.ficha
      from (select f."CO_FICHA_ANALISE" as ficha, a.modalidade_concorrencia, a.pcd, a.nome_vaga,
                   private."FC_MODALIDADES_DA_FICHA"(f."CO_FICHA_ANALISE") as cotas,
                   private."FC_NOME_VAGA_PUBLICADA"(f."CO_MONITORAMENTO", f."CO_VAGA") as nome_vaga_agora
              from public."TB_FICHA_ANALISE" f
              join public."TB_ANALISE_CURRICULAR" a
                on a.chave_natural = 'monitora|' || f."CO_MONITORAMENTO" || '|' || f."CO_EMPREGARE_CANDIDATO"
             where f."CO_MONITORAMENTO" = p_edital) s
     where s.modalidade_concorrencia is distinct from
             coalesce(private.normalizar_modalidade_concorrencia(private."FC_MODALIDADES_PUBLICADAS"(s.cotas)),
                      s.modalidade_concorrencia)
        or s.pcd is distinct from private."FC_PCD_DAS_MODALIDADES"(s.cotas)
        -- O nome da vaga (cargo e lotação) que chegou depois da publicação (20261015151000).
        or s.nome_vaga is distinct from coalesce(s.nome_vaga_agora, s.nome_vaga)
  loop
    perform private."FC_PUBLICAR_FICHA_ANALISE"(v_publicar.ficha);
    v_republicadas := v_republicadas + 1;
  end loop;

  -- Entram: quem está no lote e ainda não tem ficha (uma por inscrito; "a linha anda" cria ficha nova).
  with entra as (
    select p."CO_EMPREGARE_CANDIDATO" as candidato, p."CO_VAGA" as vaga, p."NU_VERSAO_REGRA" as versao,
           p."NU_LOTE" as lote, p."NU_POSICAO" as posicao,
           coalesce('Entrou no lote refeito em ' || to_char(t."DT_INICIO" at time zone 'America/Sao_Paulo', 'DD/MM'),
                    p."DS_MOTIVO_ENTRADA", 'Entrou no lote ' || p."NU_LOTE") as motivo
      from public."TB_PRE_CLASSIFICACAO" p
      left join public."TL_PRE_CLASSIFICACAO" t on t."CO_EXECUCAO" = p."CO_EXECUCAO" and t."ST_REFAZER_LOTE" = 'S'
     where p."CO_MONITORAMENTO" = p_edital and p."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO')
       and not exists (select 1 from public."TB_FICHA_ANALISE" f
                        where f."CO_MONITORAMENTO" = p_edital and f."CO_EMPREGARE_CANDIDATO" = p."CO_EMPREGARE_CANDIDATO")
  ),
  nova as (
    insert into public."TB_FICHA_ANALISE"
      ("CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO", "CO_VAGA", "CO_REGRA_ANALISE", "NU_VERSAO_REGRA", "NU_LOTE")
    select p_edital, e.candidato, e.vaga, v_regra."CO_REGRA_ANALISE", e.versao, e.lote
      from entra e
     order by e.posicao, e.vaga, e.candidato
    returning *
  ),
  historico as (
    insert into public."TH_FICHA_ANALISE"
      ("CO_FICHA_ANALISE", "NU_VERSAO", "TP_ACAO", "TP_SITUACAO_ANTERIOR", "TP_SITUACAO", "CO_USUARIO_RESP_ANTERIOR",
       "CO_USUARIO_RESPONSAVEL", "DS_MOTIVO", "TP_ORIGEM", "CO_USUARIO")
    select n."CO_FICHA_ANALISE", n."NU_VERSAO", 'CRIAR', null, n."TP_SITUACAO", null, n."CO_USUARIO_RESPONSAVEL",
           nullif(left(btrim(coalesce(e.motivo, '')), 2000), ''), v_origem, p_usuario
      from nova n
      join entra e on e.candidato = n."CO_EMPREGARE_CANDIDATO"
    returning 1
  )
  select coalesce(array_agg(n."CO_EMPREGARE_CANDIDATO"), '{}') into v_criados from nova n;

  -- As fichas novas que já vão para alguém (quem entra depois, para quem tem menos pendentes).
  begin
    for v_item in
      select (a ->> 'candidato')::uuid as candidato, (a ->> 'usuario')::uuid as usuario
        from jsonb_array_elements(v_atrib) a
    loop
      select * into v_ficha from public."TB_FICHA_ANALISE"
       where "CO_MONITORAMENTO" = p_edital and "CO_EMPREGARE_CANDIDATO" = v_item.candidato
       for update;
      if v_item.candidato is null or not (v_item.candidato = any (v_criados)) or v_ficha."CO_USUARIO_RESPONSAVEL" is not null then
        raise exception 'Atribuição recusada: só a ficha aberta agora, uma vez' using errcode = '22023';
      end if;
      if v_item.usuario is null or not private."FC_PODE_ANALISAR_VAGA"(p_edital, v_item.usuario, v_ficha."CO_VAGA") then
        raise exception 'Atribuição recusada: a pessoa não analisa a vaga %', v_ficha."CO_VAGA" using errcode = '22023';
      end if;
      update public."TB_FICHA_ANALISE" set
        "CO_USUARIO_RESPONSAVEL" = v_item.usuario, "DT_ATRIBUICAO" = now(),
        "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
       where "CO_FICHA_ANALISE" = v_ficha."CO_FICHA_ANALISE";
      perform private."FC_HISTORICO_FICHA"(v_ficha."CO_FICHA_ANALISE", 'DISTRIBUIR', 'PENDENTE', null,
                                           'Entrou depois: para quem tem menos pendentes', p_usuario);
      v_atribuidas := v_atribuidas + 1;
    end loop;
  exception when invalid_text_representation then
    raise exception 'Atribuição com id inválido' using errcode = '22023';
  end;

  return jsonb_build_object('criadas', cardinality(v_criados), 'atribuidas', v_atribuidas,
                            'fora_do_lote', v_saem, 'voltaram', v_voltam, 'regra_atualizada', v_regra_nova,
                            'modalidade_atualizada', v_modalidade, 'republicadas', v_republicadas);
end;
$$;

--
-- Name: FUNCTION "FC_ABRIR_FICHAS"(p_edital uuid, p_atribuicoes jsonb, p_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ABRIR_FICHAS"(p_edital uuid, p_atribuicoes jsonb, p_usuario uuid) IS 'Sincroniza as fichas do edital com a pré-classificação gravada: quem saiu do lote (eliminado) fica FORA_LOTE com o motivo e sem reserva — desde 20261013110000, quem ficou fora do lote refeito do zero fica FORA_LOTE com "Lote refeito em dd/mm" e histórico REFAZER_LOTE; quem voltou ao lote volta PENDENTE e livre; desde 20261015020000, a ficha não concluída com lançamento gravado passa à modalidade da pré-classificação (desde 20261015150000 às cotas optadas: DS_LANCAMENTO.modalidades e .modalidade; histórico MODALIDADE; modalidade_atualizada) e a linha publicada com modalidade ou PcD diferente das cotas da ficha (FC_MODALIDADES_DA_FICHA) ou, desde 20261015151000, com nome da vaga diferente (FC_NOME_VAGA_PUBLICADA) é publicada de novo (republicadas); quem está no lote sem ficha ganha uma (PENDENTE); a ficha não concluída segue a versão da regra do último recálculo (a concluída mantém a sua; regra_atualizada conta as que mudaram). p_atribuicoes [{candidato, usuario}] dá responsável só às fichas criadas agora, para analistas da vaga. p_usuario nulo = o job. Histórico de tudo. Em comandos de conjunto desde 20261014130000. Devolve as contagens.';

--
-- Name: FC_ACERTAR_AREA_EDITAL(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ACERTAR_AREA_EDITAL"(p_payload jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := nullif(btrim(p_payload ->> 'co_area'), '');
  v_id uuid := nullif(p_payload ->> 'id', '')::uuid;
  v_unidade text := nullif(btrim(p_payload ->> 'unidade'), '');
  v_area_atual text;
  v_unidade_atual text;
  v_da_unidade text;
  v_nome_area text;
begin
  -- Chamada sem área (front anterior): nada muda.
  if v_area is null then
    return null;
  end if;

  select a."NO_AREA" into v_nome_area from public."TB_AREA" a where a."CO_AREA" = v_area;
  if v_nome_area is null then
    raise exception 'Área inválida: %', v_area using errcode = '22023';
  end if;
  if not (v_area = any (private."FC_AREAS_USUARIO"())) then
    raise exception 'Sem permissão para editais desta área' using errcode = '42501';
  end if;

  if v_id is not null then
    select m."CO_AREA", m.unidade into v_area_atual, v_unidade_atual
      from public."TB_MONITORAMENTO_INDIGENA" m where m.id = v_id;
    if found then
      if v_area_atual is distinct from v_area then
        raise exception 'Este edital é da área %. Para mudar de área, peça a um administrador (Mover para outra área).',
          coalesce((select a."NO_AREA" from public."TB_AREA" a where a."CO_AREA" = v_area_atual), v_area_atual)
          using errcode = '22023';
      end if;
      -- Mesma unidade de antes: nada a conferir (o edital pode ter sido movido de área).
      if public.analises_norm_key(v_unidade_atual) is not distinct from public.analises_norm_key(v_unidade) then
        return v_area;
      end if;
    end if;
  end if;

  if v_unidade is null then
    return v_area;
  end if;

  v_da_unidade := private."FC_AREA_DA_UNIDADE"(v_unidade);
  if v_da_unidade is null then
    if length(v_unidade) > 150 then
      raise exception 'Nome de unidade longo demais (máximo de 150 caracteres)' using errcode = '22023';
    end if;
    insert into public."TA_UNIDADE_AREA"("NO_UNIDADE", "CO_AREA")
    values (v_unidade, v_area)
    on conflict ("NO_UNIDADE") do nothing;
  elsif v_da_unidade <> v_area then
    raise exception 'A unidade % é da área %; escolha uma unidade de % ou peça ao administrador para mover.',
      v_unidade,
      coalesce((select a."NO_AREA" from public."TB_AREA" a where a."CO_AREA" = v_da_unidade), v_da_unidade),
      v_nome_area
      using errcode = '22023';
  end if;
  return v_area;
end;
$$;

--
-- Name: FUNCTION "FC_ACERTAR_AREA_EDITAL"(p_payload jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ACERTAR_AREA_EDITAL"(p_payload jsonb) IS 'Salvar com área pretendida (p_payload.co_area): valida permissão, recusa unidade de outra área e registra em TA_UNIDADE_AREA a unidade que o banco não conhece. Sem co_area devolve NULL.';

--
-- Name: FC_ADMIN_GLOBAL_ATIVO(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ADMIN_GLOBAL_ATIVO"(p_usuario uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_usuario is not null and exists (
    select 1 from public."TB_PERFIL_USUARIO" p
      join public."TB_GRUPO_ACESSO" a on a."CO_GRUPO_ACESSO" = p.perfil
     where p.user_id = p_usuario and p.ativo is true and a."ST_ADMIN_GLOBAL");
$$;

--
-- Name: FUNCTION "FC_ADMIN_GLOBAL_ATIVO"(p_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ADMIN_GLOBAL_ATIVO"(p_usuario uuid) IS 'A pessoa (auth.users.id) tem perfil ativo de administrador global? (20261022210000)';

--
-- Name: FC_AGENDA_DAS_INSCRICOES(text, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AGENDA_DAS_INSCRICOES"(p_tarefa text, p_editais text, p_ate date) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if p_tarefa is null or p_tarefa !~ '^agsus_robo_inscricoes_[a-z0-9_]{1,40}$' then
    raise exception 'Tarefa da agenda das inscrições inválida' using errcode = '22023';
  end if;
  if p_ate is null or coalesce(btrim(p_editais), '') = '' then
    raise exception 'Informe os editais e a data final' using errcode = '22023';
  end if;
  -- Passou a data (Brasília): a tarefa desliga a si mesma e não pede nada.
  if (now() at time zone 'America/Sao_Paulo')::date > p_ate then
    if exists (select 1 from cron.job where jobname = p_tarefa) then
      perform cron.unschedule(p_tarefa);
    end if;
    return null;
  end if;
  -- O robô da Empregare, ao fim de uma carga normal, roda a pré-classificação dos
  -- editais carregados (robo-empregare.yml, --apos-robo), que grava o retrato.
  -- Edital com inscrições congeladas: o robô e a pré-classificação o pulam.
  return private."FC_DISPARAR_ROBO"('robo-empregare.yml',
    jsonb_build_object('modo', 'normal', 'editais', btrim(p_editais)), null, 'AGENDA');
end;
$_$;

--
-- Name: FUNCTION "FC_AGENDA_DAS_INSCRICOES"(p_tarefa text, p_editais text, p_ate date); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AGENDA_DAS_INSCRICOES"(p_tarefa text, p_editais text, p_ate date) IS 'Agenda das inscrições (20261009140000): chamada por uma tarefa agsus_robo_inscricoes_* do pg_cron, pede o robô da Empregare dos editais (modo normal; no fim ele roda a pré-classificação deles e o retrato das inscrições) por FC_DISPARAR_ROBO, com origem AGENDA (20261020170000), até p_ate (data de Brasília) e, no primeiro horário depois, desliga a própria tarefa (cron.unschedule) e devolve nulo. Edital com inscrições congeladas: o robô e a pré-classificação o pulam. Só o dono (pg_cron).';

--
-- Name: FC_AGENDA_ENTREVISTA_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AGENDA_ENTREVISTA_JSON"(p_edital uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
    'edital', (select json_build_object('id', m.id, 'edital', m.edital, 'unidade', m.unidade, 'area', m."CO_AREA")
                 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital),
    'pode_editar', private.pode_recurso('entrevistas', 2) or private.pode_recurso('classificacao', 2),
    'regra', private."FC_REGRA_AGENDA_JSON"(p_edital),
    'itens', coalesce((
      select json_agg(json_build_object(
               'analise_id', g."CO_ANALISE_CURRICULAR", 'nome', a.candidato, 'vaga', a.codigo_vaga,
               'cargo', a.nome_vaga, 'modalidade', a.modalidade_concorrencia,
               'data', g."DT_ENTREVISTA", 'inicio', to_char(g."HR_INICIO", 'HH24:MI'),
               'fim', to_char(g."HR_FIM", 'HH24:MI'), 'banca', g."NU_BANCA", 'origem', g."TP_ORIGEM",
               'atualizado_em', g."DT_ATUALIZACAO")
             order by g."DT_ENTREVISTA", g."HR_INICIO", g."NU_BANCA")
        from public."TB_AGENDA_ENTREVISTA" g
        join public."TB_ANALISE_CURRICULAR" a on a.id = g."CO_ANALISE_CURRICULAR"
       where g."CO_MONITORAMENTO" = p_edital), '[]'::json),
    'bancas', coalesce((
      select json_agg(json_build_object('banca', b.banca, 'membros', b.membros) order by b.banca)
        from (select v."NU_BANCA" as banca,
                     json_agg(json_build_object('nome', v."NO_AVALIADOR", 'origem', v."NO_ORIGEM")
                              order by v."NO_ORIGEM", v."NO_AVALIADOR") as membros
                from public."TB_ENTREVISTA_AVALIADOR" v
               where v."CO_MONITORAMENTO" = p_edital and v."ST_ATIVO" = 'S'
               group by v."NU_BANCA") b), '[]'::json),
    'ultimo_registro', (select h."CO_HISTORICO_AGENDA" from public."TH_AGENDA_ENTREVISTA" h
                         where h."CO_MONITORAMENTO" = p_edital
                         order by h."DT_REGISTRO" desc, h."CO_HISTORICO_AGENDA" limit 1),
    'historico', coalesce((
      select json_agg(json_build_object(
               'id', h."CO_HISTORICO_AGENDA", 'acao', h."TP_ACAO", 'em', h."DT_REGISTRO",
               'por', coalesce(p.nome, p.email), 'versao_regra', h."NU_VERSAO_REGRA",
               'lista', h."CO_LISTA_CLASSIFICACAO", 'itens', h."QT_ITEM", 'alteracoes', h."QT_ALTERACAO",
               'motivo', h."DS_MOTIVO")
             order by h."DT_REGISTRO" desc)
        from (select * from public."TH_AGENDA_ENTREVISTA" x
               where x."CO_MONITORAMENTO" = p_edital
               order by x."DT_REGISTRO" desc limit 20) h
        left join public."TB_PERFIL_USUARIO" p on p.user_id = h."CO_USUARIO"), '[]'::json)
  );
$$;

--
-- Name: FUNCTION "FC_AGENDA_ENTREVISTA_JSON"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AGENDA_ENTREVISTA_JSON"(p_edital uuid) IS 'A agenda do edital (json): regra vigente e versões, horários (com nome, vaga, cargo e modalidade da análise; sem CPF), membros ativos de cada banca, a última gravação e as 20 mais recentes. Sem checagem de permissão: só as RPCs chamam.';

--
-- Name: FC_AJUSTE_JUSTIFICADO(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AJUSTE_JUSTIFICADO"(p_regra jsonb, p_bloco jsonb, p_lancado jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(p_lancado -> 'edita_nota' = 'true'::jsonb, false)
     and (exists (select 1 from jsonb_array_elements_text(case when jsonb_typeof(p_lancado -> 'justificativas') = 'array'
                                                               then p_lancado -> 'justificativas' else '[]'::jsonb end) j where j <> 'OUTRO')
          or (coalesce(p_lancado -> 'justificativas', '[]'::jsonb) ? 'OUTRO'
              and length(btrim(coalesce(p_lancado ->> 'motivo_livre', ''))) >= 10)
          or (jsonb_array_length(case when jsonb_typeof(p_bloco -> 'motivos') = 'array' then p_bloco -> 'motivos' else '[]'::jsonb end) = 0
              and jsonb_array_length(case when jsonb_typeof(p_regra -> 'observacoes_prontas') = 'array' then p_regra -> 'observacoes_prontas' else '[]'::jsonb end) = 0
              and length(btrim(coalesce(p_lancado ->> 'justificativa_livre', ''))) >= 10));
$$;

--
-- Name: FC_AJUSTE_PONTUACAO_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AJUSTE_PONTUACAO_JSON"(p_ajuste uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
           'id', j."CO_AJUSTE_PONTUACAO", 'recurso_id', j."CO_RECURSO_CANDIDATO", 'numero', r."NU_RECURSO",
           'origem', r."CO_ORIGEM_RECURSO", 'analise_id', j."CO_ANALISE_CURRICULAR", 'versao', j."NU_VERSAO",
           'situacao', j."TP_SITUACAO", 'lista', j."TP_LISTA", 'justificativa', j."DS_JUSTIFICATIVA",
           'previa', j."DS_PREVIA", 'previa_aprovacao', j."DS_PREVIA_APROVACAO",
           'mudou_posicao', j."ST_MUDOU_POSICAO" = 'S',
           'proposto_em', j."DT_PROPOSTA", 'proposto_por', private."FC_NOME_USUARIO"(j."CO_USUARIO_PROPOSTA"),
           'aprovado_em', j."DT_APROVACAO", 'aprovado_por', private."FC_NOME_USUARIO"(j."CO_USUARIO_APROVACAO"),
           'cancelado_em', j."DT_CANCELAMENTO", 'cancelado_por', private."FC_NOME_USUARIO"(j."CO_USUARIO_CANCELAMENTO"),
           'motivo_cancelamento', j."DS_MOTIVO_CANCELAMENTO",
           'itens', coalesce((
             select json_agg(json_build_object('codigo', i."CO_ITEM", 'anterior', i."VL_ANTERIOR", 'novo', i."VL_NOVO",
                                               'justificativa', i."DS_JUSTIFICATIVA") order by i."NU_ORDEM")
               from public."TB_ITEM_AJUSTE_PONTUACAO" i
              where i."CO_AJUSTE_PONTUACAO" = j."CO_AJUSTE_PONTUACAO"), '[]'::json))
    from public."TB_AJUSTE_PONTUACAO_RECURSO" j
    join public."TB_RECURSO_CANDIDATO" r on r."CO_RECURSO_CANDIDATO" = j."CO_RECURSO_CANDIDATO"
   where j."CO_AJUSTE_PONTUACAO" = p_ajuste;
$$;

--
-- Name: FUNCTION "FC_AJUSTE_PONTUACAO_JSON"(p_ajuste uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AJUSTE_PONTUACAO_JSON"(p_ajuste uuid) IS 'Uma versão do ajuste da pontuação (json): recurso e número, situação, lista, justificativa, prévias, itens e quem/quando de cada passo.';

--
-- Name: FC_ALINHAR_TAREFAS_DAS_CHAVES(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ALINHAR_TAREFAS_DAS_CHAVES"(p_chave text DEFAULT NULL::text) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c_motivo constant text :=
    'O banco realinhou ao estado da chave as tarefas do pg_cron que estavam fora dele (FC_ALINHAR_TAREFAS_DAS_CHAVES).';
  v_tarefa record;
  v_mexidas text[] := '{}';
  v_por_chave jsonb := '{}'::jsonb;
  v_chave text;
begin
  -- As chaves ficam travadas para leitura: ninguém muda uma chave no meio do alinhamento.
  for v_tarefa in
    select j.jobid, j.jobname::text as jobname, c."CO_CHAVE" as chave, (c."ST_LIGADA" = 'S') as ligada
      from cron.job j
      join public."TB_CHAVE_AUTOMACAO" c on c."CO_CHAVE" = private."FC_CHAVE_DA_TAREFA"(j.jobname)
     where (p_chave is null or c."CO_CHAVE" = p_chave)
       and j.active is distinct from (c."ST_LIGADA" = 'S')
     order by j.jobname
     for share of c
  loop
    perform cron.alter_job(v_tarefa.jobid, active := v_tarefa.ligada);
    v_mexidas := v_mexidas || v_tarefa.jobname;
    v_por_chave := jsonb_set(v_por_chave, array[v_tarefa.chave],
                             coalesce(v_por_chave -> v_tarefa.chave, '[]'::jsonb) || to_jsonb(v_tarefa.jobname));
  end loop;

  -- A rodada sozinha (sem p_chave) deixa o acerto no histórico da chave; quem chama com a
  -- chave (alterar_chave_da_automacao) grava o próprio evento, com as tarefas devolvidas.
  if p_chave is null then
    for v_chave in select k from jsonb_object_keys(v_por_chave) k order by k loop
      insert into public."TH_CHAVE_AUTOMACAO" ("CO_CHAVE", "ST_LIGADA", "DS_MOTIVO", "CO_USUARIO", "DS_TAREFAS")
      select v_chave, c."ST_LIGADA", c_motivo, null,
             array(select jsonb_array_elements_text(v_por_chave -> v_chave))
        from public."TB_CHAVE_AUTOMACAO" c
       where c."CO_CHAVE" = v_chave;
    end loop;
  end if;
  return v_mexidas;
end;
$$;

--
-- Name: FUNCTION "FC_ALINHAR_TAREFAS_DAS_CHAVES"(p_chave text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ALINHAR_TAREFAS_DAS_CHAVES"(p_chave text) IS 'A chave da automação manda (20261109180000): põe cada tarefa do pg_cron com chave (FC_CHAVE_DA_TAREFA) no estado da chave (cron.alter_job active) e devolve as tarefas mexidas, em ordem de nome. Com p_chave, só as daquela chave (alterar_chave_da_automacao); sem, todas, e grava o acerto em TH_CHAVE_AUTOMACAO sem usuário (tarefa agsus_alinhar_chaves_da_automacao, a cada 5 min). Tarefa sem chave nunca é tocada. Só o dono.';

--
-- Name: FC_ALTERACOES_FICHA(jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ALTERACOES_FICHA"(p_regra jsonb, p_antes_lanc jsonb, p_antes_res jsonb, p_lanc jsonb, p_res jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with blocos as (
    select b ->> 'codigo' as codigo, coalesce(b ->> 'titulo', b ->> 'codigo') as titulo,
           private."FC_PARCIAL_DO_TIPO"(b ->> 'tipo') as parcial, o.n
      from jsonb_array_elements(coalesce(p_regra -> 'blocos', '[]'::jsonb)) with ordinality o(b, n)
  ),
  mudancas as (
    select x.n * 10 + x.k as ordem, x.alt
      from blocos bl,
           lateral (values
             (bl.n, 1, case when (p_antes_lanc #> array['blocos', bl.codigo, 'situacao']) is distinct from (p_lanc #> array['blocos', bl.codigo, 'situacao'])
                     then jsonb_build_object('campo', 'situacao', 'bloco', bl.codigo, 'rotulo', bl.titulo,
                                             'de', p_antes_lanc #>> array['blocos', bl.codigo, 'situacao'],
                                             'para', p_lanc #>> array['blocos', bl.codigo, 'situacao']) end),
             (bl.n, 2, case when coalesce(p_antes_lanc #> array['blocos', bl.codigo, 'motivos'], '[]') is distinct from coalesce(p_lanc #> array['blocos', bl.codigo, 'motivos'], '[]')
                       or coalesce(p_antes_lanc #>> array['blocos', bl.codigo, 'motivo_livre'], '') is distinct from coalesce(p_lanc #>> array['blocos', bl.codigo, 'motivo_livre'], '')
                     then jsonb_build_object('campo', 'motivos', 'bloco', bl.codigo, 'rotulo', bl.titulo || ' (motivo)',
                                             'de', p_antes_lanc #> array['blocos', bl.codigo, 'motivos'],
                                             'para', p_lanc #> array['blocos', bl.codigo, 'motivos']) end),
             (bl.n, 3, case when bl.parcial is not null and (p_antes_res #> array['parciais', bl.parcial]) is distinct from (p_res #> array['parciais', bl.parcial])
                     then jsonb_build_object('campo', 'parcial', 'bloco', bl.codigo, 'parcial', bl.parcial, 'rotulo', bl.titulo,
                                             'de', p_antes_res #> array['parciais', bl.parcial], 'para', p_res #> array['parciais', bl.parcial],
                                             'ajustada', p_lanc #> array['blocos', bl.codigo, 'nota_ajustada'],
                                             'justificativas', p_lanc #> array['blocos', bl.codigo, 'justificativas']) end),
             (bl.n, 4, case when coalesce(p_antes_lanc #> array['blocos', bl.codigo, 'justificativas'], '[]') is distinct from coalesce(p_lanc #> array['blocos', bl.codigo, 'justificativas'], '[]')
                       or coalesce(p_antes_lanc #>> array['blocos', bl.codigo, 'justificativa_livre'], '') is distinct from coalesce(p_lanc #>> array['blocos', bl.codigo, 'justificativa_livre'], '')
                     then jsonb_build_object('campo', 'justificativas', 'bloco', bl.codigo, 'rotulo', bl.titulo || ' (justificativa)',
                                             'de', p_antes_lanc #> array['blocos', bl.codigo, 'justificativas'],
                                             'para', p_lanc #> array['blocos', bl.codigo, 'justificativas']) end)
           ) x(n, k, alt)
    union all
    select 100000 + v.k, v.alt
      from (values
        (1, case when jsonb_array_length(coalesce(p_antes_lanc -> 'titulos', '[]')) <> jsonb_array_length(coalesce(p_lanc -> 'titulos', '[]'))
                 then jsonb_build_object('campo', 'itens', 'rotulo', 'Títulos', 'de', jsonb_array_length(coalesce(p_antes_lanc -> 'titulos', '[]')),
                                         'para', jsonb_array_length(coalesce(p_lanc -> 'titulos', '[]'))) end),
        (2, case when jsonb_array_length(coalesce(p_antes_lanc -> 'cursos', '[]')) <> jsonb_array_length(coalesce(p_lanc -> 'cursos', '[]'))
                 then jsonb_build_object('campo', 'itens', 'rotulo', 'Cursos', 'de', jsonb_array_length(coalesce(p_antes_lanc -> 'cursos', '[]')),
                                         'para', jsonb_array_length(coalesce(p_lanc -> 'cursos', '[]'))) end),
        (3, case when jsonb_array_length(coalesce(p_antes_lanc -> 'vinculos', '[]')) <> jsonb_array_length(coalesce(p_lanc -> 'vinculos', '[]'))
                 then jsonb_build_object('campo', 'itens', 'rotulo', 'Vínculos', 'de', jsonb_array_length(coalesce(p_antes_lanc -> 'vinculos', '[]')),
                                         'para', jsonb_array_length(coalesce(p_lanc -> 'vinculos', '[]'))) end),
        (4, case when coalesce(p_antes_lanc ->> 'observacoes', '') <> coalesce(p_lanc ->> 'observacoes', '')
                   or coalesce(p_antes_lanc -> 'observacoes_prontas', '[]') <> coalesce(p_lanc -> 'observacoes_prontas', '[]')
                 then jsonb_build_object('campo', 'observacoes', 'rotulo', 'Observações') end),
        (5, case when (p_antes_res -> 'resultado') is distinct from (p_res -> 'resultado')
                 then jsonb_build_object('campo', 'resultado', 'rotulo', 'Resultado', 'de', p_antes_res -> 'resultado', 'para', p_res -> 'resultado') end),
        (6, case when (p_antes_res -> 'nota_final') is distinct from (p_res -> 'nota_final')
                 then jsonb_build_object('campo', 'nota_final', 'rotulo', 'Nota final', 'de', p_antes_res -> 'nota_final', 'para', p_res -> 'nota_final') end),
        (7, case when coalesce(p_antes_lanc ->> 'nivel', '') <> coalesce(p_lanc ->> 'nivel', '')
                   or coalesce(p_antes_lanc -> 'indigena', 'false') <> coalesce(p_lanc -> 'indigena', 'false')
                   or coalesce(p_antes_lanc -> 'mora_aldeia', 'false') <> coalesce(p_lanc -> 'mora_aldeia', 'false')
                   or coalesce(p_antes_lanc -> 'aldeia_na_lista', 'false') <> coalesce(p_lanc -> 'aldeia_na_lista', 'false')
                 then jsonb_build_object('campo', 'candidato', 'rotulo', 'Nível, indígena ou aldeia') end)
      ) v(k, alt)
  )
  select coalesce(jsonb_agg(m.alt order by m.ordem), '[]'::jsonb)
    from (select * from mudancas where alt is not null order by ordem limit 60) m;
$$;

--
-- Name: FUNCTION "FC_ALTERACOES_FICHA"(p_regra jsonb, p_antes_lanc jsonb, p_antes_res jsonb, p_lanc jsonb, p_res jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ALTERACOES_FICHA"(p_regra jsonb, p_antes_lanc jsonb, p_antes_res jsonb, p_lanc jsonb, p_res jsonb) IS 'O que mudou entre dois lançamentos da ficha (para o histórico): situação e motivo de cada bloco, parcial de quanto para quanto (com a nota ajustada e as justificativas), justificativas, número de títulos/cursos/vínculos, observações, nível/indígena/aldeia, resultado e nota final. Até 60 itens.';

--
-- Name: FC_ANALISE_DO_EDITAL(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ANALISE_DO_EDITAL"(p_edital_analise text, p_edital text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select case
           when private."FC_NUMERO_EDITAL"(p_edital) is not null
             then coalesce(private."FC_NUMERO_EDITAL"(p_edital_analise) = private."FC_NUMERO_EDITAL"(p_edital), false)
           else nullif(btrim(coalesce(p_edital, '')), '') is not null
                and btrim(coalesce(p_edital_analise, '')) = btrim(p_edital)
         end;
$$;

--
-- Name: FUNCTION "FC_ANALISE_DO_EDITAL"(p_edital_analise text, p_edital text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ANALISE_DO_EDITAL"(p_edital_analise text, p_edital text) IS 'Se a análise (TB_ANALISE_CURRICULAR.edital) é do edital (TB_MONITORAMENTO_INDIGENA.edital): pelo número do edital (FC_NUMERO_EDITAL), como Classificação, Entrevistas e KPIs; edital sem número, pelo texto. A área se confere à parte.';

--
-- Name: FC_ANALISE_EH_TREINAMENTO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ANALISE_EH_TREINAMENTO"(p_origem_planilha text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select coalesce(p_origem_planilha, '') = 'treinamento';
$$;

--
-- Name: FUNCTION "FC_ANALISE_EH_TREINAMENTO"(p_origem_planilha text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ANALISE_EH_TREINAMENTO"(p_origem_planilha text) IS 'A análise curricular é fictícia do edital de treinamento (TB_ANALISE_CURRICULAR.origem_planilha = ''treinamento'')? A análise não tem o id do edital (liga pelo número), por isso a marca fica na origem.';

--
-- Name: FC_ANALISTAS_DO_EDITAL(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ANALISTAS_DO_EDITAL"(p_edital uuid, p_com_nome boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(x.obj order by x.usuario::text), '[]'::jsonb)
    from (
      select r."CO_USUARIO" as usuario,
             jsonb_build_object(
               'usuario', r."CO_USUARIO",
               'nome', case when p_com_nome then coalesce(min(u.nome), min(u.email)) end,
               'vagas', case when bool_or(r."CO_VAGA" is null) then null
                             else jsonb_agg(distinct r."CO_VAGA" order by r."CO_VAGA") end,
               'limite', min(r."QT_LIMITE_FICHA"),
               'pendentes', (select count(*) from public."TB_FICHA_ANALISE" f
                              where f."CO_MONITORAMENTO" = p_edital and f."CO_USUARIO_RESPONSAVEL" = r."CO_USUARIO"
                                and f."TP_SITUACAO" in ('PENDENTE', 'EM_ANALISE'))) as obj
        from public."RL_ANALISTA_EDITAL" r
        join public."TB_PERFIL_USUARIO" u on u.user_id = r."CO_USUARIO"
       where r."CO_MONITORAMENTO" = p_edital and r."TP_PAPEL" = 'ANALISTA' and r."ST_ATIVO" = 'S'
         and u.ativo
         and private."FC_NIVEL_AVALIACAO_DO_PERFIL"(u.id) >= 2
         and private."FC_PERFIL_VE_EDITAL"(u.id, p_edital)
       group by r."CO_USUARIO") x;
$$;

--
-- Name: FUNCTION "FC_ANALISTAS_DO_EDITAL"(p_edital uuid, p_com_nome boolean); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ANALISTAS_DO_EDITAL"(p_edital uuid, p_com_nome boolean) IS 'Os analistas que podem receber ficha no edital (FC_PODE_ANALISAR_VAGA), na ordem do id: vagas (nula = todas), limite da distribuição, quantas fichas pendentes ou em análise já têm e, com p_com_nome, o nome. Entrada da distribuição (src/lib/avaliacao-documental/distribuicao.js e o job Python).';

--
-- Name: FC_ANEXO_RECURSO_ORFAO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ANEXO_RECURSO_ORFAO"(p_caminho text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select not exists (
    select 1
    from public."TB_ANEXO_RECURSO" a
    where a."DS_CAMINHO" = p_caminho
  );
$$;

--
-- Name: FUNCTION "FC_ANEXO_RECURSO_ORFAO"(p_caminho text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ANEXO_RECURSO_ORFAO"(p_caminho text) IS 'Política de delete do bucket recursos-anexos: o caminho ainda não foi registrado em TB_ANEXO_RECURSO (SECURITY DEFINER: a RLS da tabela não esconde a linha de quem pede).';

--
-- Name: FC_ANOS_MESES_DIAS(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ANOS_MESES_DIAS"(p_dias integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object('anos', t / 365, 'meses', least((t % 365) / 30, 11),
                            'dias', (t % 365) - least((t % 365) / 30, 11) * 30)
    from (select greatest(coalesce(p_dias, 0), 0) as t) x;
$$;

--
-- Name: FC_APAGAR_DADOS_DO_TREINAMENTO(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_APAGAR_DADOS_DO_TREINAMENTO"(p_edital uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_numero text;
  v_qt jsonb := '{}'::jsonb;
  v_n integer;
begin
  -- A trava: a linha travada TEM de ser de treinamento. Nada é apagado antes disto.
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital for update;
  if v_m.id is null then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  if v_m."ST_TREINAMENTO" is distinct from 'S' then
    raise exception 'Só o edital de treinamento pode ser reiniciado: este edital é real e nada foi apagado'
      using errcode = '42501';
  end if;
  -- Vaga que veio do robô da Empregare (CO_SYNC) não é do treinamento: recusa.
  if exists (select 1 from public."TB_EMPREGARE_VAGA" v where v."CO_MONITORAMENTO" = p_edital and v."CO_SYNC" is not null) then
    raise exception 'O edital de treinamento tem vaga carregada pelo robô da Empregare; nada foi apagado' using errcode = '23514';
  end if;
  v_numero := private."FC_NUMERO_EDITAL"(v_m.edital);

  perform set_config('agsus.reinicio_treinamento', p_edital::text, true);

  -- Lista de aprovados, cartas e convocação.
  create temporary table if not exists tmp_treino_listas (id uuid primary key) on commit drop;
  truncate tmp_treino_listas;
  insert into tmp_treino_listas select l.id from public."TB_LISTA_APROVADO" l where l.edital_id = p_edital::text;
  delete from public."RL_CARTA_CANDIDATO" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_CANDIDATO_APROVADO" where lista_id in (select id from tmp_treino_listas);
  delete from public."TH_CANDIDATO_SUB_JUDICE" where "CO_LISTA" in (select id from tmp_treino_listas);
  delete from public."TH_CARTA_CONVOCACAO" h using public."TB_MODELO_CARTA_CONVOCACAO" m
   where h."CO_MODELO_CARTA" = m."CO_MODELO_CARTA" and m."CO_MONITORAMENTO" = p_edital;
  delete from public."TH_MODELO_CARTA_CONVOCACAO" h using public."TB_MODELO_CARTA_CONVOCACAO" m
   where h."CO_MODELO_CARTA" = m."CO_MODELO_CARTA" and m."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_MODELO_CARTA_CONVOCACAO" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_PUBLICACAO_APROVADO"
   where "CO_MONITORAMENTO" = p_edital
      or "CO_LISTA_APROVADO" in (select id from tmp_treino_listas)
      or "CO_LISTA_APROVADO_ANTERIOR" in (select id from tmp_treino_listas);
  delete from public."TB_CANDIDATO_APROVADO" where lista_id in (select id from tmp_treino_listas);
  delete from public."TB_LISTA_APROVADO" where id in (select id from tmp_treino_listas);
  get diagnostics v_n = row_count; v_qt := v_qt || jsonb_build_object('listas_aprovados', v_n);
  delete from public."TB_CONVOCACAO_EDITAL" where "CO_EDITAL" = p_edital::text;

  -- Recursos.
  delete from public."TH_ANEXO_RECURSO" h using public."TB_ANEXO_RECURSO" a, public."TB_RECURSO_CANDIDATO" r
   where h."CO_ANEXO_RECURSO" = a."CO_ANEXO_RECURSO" and a."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO"
     and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ANEXO_RECURSO" a using public."TB_RECURSO_CANDIDATO" r
   where a."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO" and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TH_RESPOSTA_RECURSO" h using public."TB_RESPOSTA_RECURSO" s, public."TB_RECURSO_CANDIDATO" r
   where h."CO_RESPOSTA_RECURSO" = s."CO_RESPOSTA_RECURSO" and s."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO"
     and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_RESPOSTA_RECURSO" s using public."TB_RECURSO_CANDIDATO" r
   where s."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO" and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ITEM_AJUSTE_PONTUACAO" i using public."TB_AJUSTE_PONTUACAO_RECURSO" j
   where i."CO_AJUSTE_PONTUACAO" = j."CO_AJUSTE_PONTUACAO" and j."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_AJUSTE_PONTUACAO_RECURSO" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_RECURSO_CANDIDATO" h using public."TB_RECURSO_CANDIDATO" r
   where h."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO" and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_RECURSO_CANDIDATO" where "CO_MONITORAMENTO" = p_edital;
  get diagnostics v_n = row_count; v_qt := v_qt || jsonb_build_object('recursos', v_n);

  -- Entrevistas e agenda.
  delete from public."TB_AGENDA_ENTREVISTA" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_AGENDA_ENTREVISTA" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_REGRA_AGENDA_ENTREVISTA" h using public."TB_REGRA_AGENDA_ENTREVISTA" r
   where h."CO_REGRA_AGENDA" = r."CO_REGRA_AGENDA" and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_REGRA_AGENDA_ENTREVISTA" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ENTREVISTA_AVALIACAO" x using public."TB_ENTREVISTA" e
   where x."CO_ENTREVISTA" = e."CO_ENTREVISTA" and e."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ENTREVISTA_NOTA" x using public."TB_ENTREVISTA" e
   where x."CO_ENTREVISTA" = e."CO_ENTREVISTA" and e."CO_MONITORAMENTO" = p_edital;
  delete from public."TH_ENTREVISTA_AVALIACAO" x using public."TB_ENTREVISTA" e
   where x."CO_ENTREVISTA" = e."CO_ENTREVISTA" and e."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ENTREVISTA" where "CO_MONITORAMENTO" = p_edital;
  get diagnostics v_n = row_count; v_qt := v_qt || jsonb_build_object('entrevistas', v_n);
  delete from public."TB_ENTREVISTA_AVALIADOR" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ENTREVISTA_EDITAL" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ENTREVISTA_VAGA" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ENTREVISTA_LIBERACAO" where "CO_MONITORAMENTO" = p_edital;

  -- Classificação.
  delete from public."TB_DESEMPATE_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_LISTA_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital;
  get diagnostics v_n = row_count; v_qt := v_qt || jsonb_build_object('listas_classificacao', v_n);
  delete from public."RL_REGRA_CRITERIO_DESEMPATE" x using public."TB_REGRA_CLASSIFICACAO" r
   where x."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO" and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TH_REGRA_CLASSIFICACAO" h using public."TB_REGRA_CLASSIFICACAO" r
   where h."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO" and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_REGRA_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital;

  -- Avaliação documental (gatilhos de imutabilidade: liberados só para este edital).
  delete from public."TL_ACESSO_FICHA_ANALISE" x using public."TB_FICHA_ANALISE" f
   where x."CO_FICHA_ANALISE" = f."CO_FICHA_ANALISE" and f."CO_MONITORAMENTO" = p_edital;
  delete from public."TH_FICHA_ANALISE" x using public."TB_FICHA_ANALISE" f
   where x."CO_FICHA_ANALISE" = f."CO_FICHA_ANALISE" and f."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_FICHA_ANALISE" where "CO_MONITORAMENTO" = p_edital;
  get diagnostics v_n = row_count; v_qt := v_qt || jsonb_build_object('fichas', v_n);
  delete from public."TH_DECISAO_LOTE" x using public."TB_DECISAO_LOTE" d
   where x."CO_DECISAO_LOTE" = d."CO_DECISAO_LOTE" and d."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_DECISAO_LOTE" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_PRE_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_PRE_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital;
  get diagnostics v_n = row_count; v_qt := v_qt || jsonb_build_object('pre_classificacao', v_n);
  delete from public."TB_PRE_CLASSIF_VAGA" where "CO_MONITORAMENTO" = p_edital;
  delete from public."RL_ANALISTA_EDITAL" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_REGRA_ANALISE" h using public."TB_REGRA_ANALISE" r
   where h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and r."CO_MONITORAMENTO" = p_edital;
  delete from public."TB_REGRA_ANALISE" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_ORIGEM_ANALISE_EDITAL" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_ORIGEM_ANALISE_EDITAL" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_EMPREGARE_CANDIDATO" c using public."TB_EMPREGARE_VAGA" v
   where c."CO_VAGA" = v."CO_VAGA" and v."CO_MONITORAMENTO" = p_edital and v."CO_SYNC" is null;
  get diagnostics v_n = row_count; v_qt := v_qt || jsonb_build_object('inscricoes', v_n);
  delete from public."TB_EMPREGARE_VAGA" where "CO_MONITORAMENTO" = p_edital and "CO_SYNC" is null;

  -- Avisos de conferência, quadro, cronograma (e o histórico dele).
  delete from public."TB_AVISO_CONFERENCIA" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_QUADRO_VAGA_EDITAL" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TB_LOCAL_VAGA_EDITAL" where "CO_MONITORAMENTO" = p_edital;
  delete from public."TH_CRONOGRAMA_MONIT_INDIG" where monitoramento_id = p_edital;
  delete from public."TB_CRONOGRAMA_MONIT_INDIG" where monitoramento_id = p_edital;

  -- As análises fictícias: só as de origem 'treinamento', da área e do número deste edital.
  delete from public."TB_ANALISE_CURRICULAR" a
   where private."FC_ANALISE_EH_TREINAMENTO"(a.origem_planilha)
     and a."CO_AREA" = v_m."CO_AREA"
     and private."FC_NUMERO_EDITAL"(a.edital) = v_numero;
  get diagnostics v_n = row_count; v_qt := v_qt || jsonb_build_object('analises', v_n);

  perform set_config('agsus.reinicio_treinamento', '', true);
  return v_qt;
end;
$$;

--
-- Name: FUNCTION "FC_APAGAR_DADOS_DO_TREINAMENTO"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_APAGAR_DADOS_DO_TREINAMENTO"(p_edital uuid) IS 'EXCEÇÃO à exclusão lógica (docs/banco-de-dados.md, seção 16): apaga fisicamente os dados do edital de TREINAMENTO (entrevistas, classificação, avaliação documental, inscrições fictícias, aprovados, recursos, cronograma, análises de origem treinamento). Trava a linha do edital e recusa (42501) se ST_TREINAMENTO não for S: nunca apaga dado de edital real. A linha do edital fica (mesmo id).';

--
-- Name: FC_APLICAR_COORDENADA_LOCAL(text, double precision, double precision, double precision, double precision, text, text, text, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_APLICAR_COORDENADA_LOCAL"(p_lugar text, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_acao text, p_conferido text, p_historico_desfeito bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_tolerancia constant double precision := 1e-9;
  v_existe boolean;
  v_lat double precision;
  v_lon double precision;
  v_lugar record;
  v_pendencia bigint;
  v_conferido_anterior text;
  v_conferido text;
  v_mudou boolean;
  v_historico bigint;
  v_agora timestamptz := clock_timestamp();
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode corrigir coordenadas.';
  end if;
  if p_acao is null or p_acao not in ('CORRECAO', 'CONFERENCIA', 'DESFAZER')
     or coalesce(p_conferido, 'S') not in ('S', 'N') then
    raise exception using errcode = '22023', message = 'Ação inválida.';
  end if;
  if p_latitude is null or p_longitude is null
     or not (p_latitude between -34.9 and 6.4)
     or not (p_longitude between -74.2 and -32) then
    raise exception using errcode = '22023', message = 'A coordenada deve ficar nos limites do Brasil.';
  end if;
  if p_motivo is null or length(btrim(p_motivo)) not between 10 and 1000 then
    raise exception using errcode = '22023', message = 'Descreva o motivo da correção (10 a 1000 caracteres).';
  end if;
  if p_lugar is null or p_lugar !~ '^(uf:[A-Z]{2}|[^/A-Z]{1,150}/[A-Z]{2})$' then
    raise exception using errcode = '22023', message = 'Lugar do mapa inválido.';
  end if;

  -- Uma gravação por lugar de cada vez (o lugar pode ainda não ter linha para travar).
  perform pg_advisory_xact_lock(hashtextextended('TB_COORDENADA_LOCAL_VAGA|' || p_lugar, 0));

  select true, c."CG_LATITUDE", c."CG_LONGITUDE" into v_existe, v_lat, v_lon
    from public."TB_COORDENADA_LOCAL_VAGA" c
   where c."DS_CHAVE_LUGAR" = p_lugar
   for update;
  v_existe := coalesce(v_existe, false);
  if not v_existe then
    select f.lugar, f.ibge, f.municipio, f.uf, f.so_uf into v_lugar
      from private."FC_LUGARES_VAGA_PROJETO"() f
     where f.lugar = p_lugar;
    if not found then
      raise exception using errcode = '22023', message = 'Lugar não encontrado nas vagas de Projetos.';
    end if;
  end if;

  -- Concorrência: a posição que a tela viu tem de ser a de agora (tolerância de JSON).
  if (v_lat is null) <> (p_latitude_anterior is null)
     or (v_lon is null) <> (p_longitude_anterior is null)
     or abs(v_lat - p_latitude_anterior) > v_tolerancia
     or abs(v_lon - p_longitude_anterior) > v_tolerancia then
    raise exception using errcode = 'PT409', message = 'O lugar mudou. Atualize o mapa e tente novamente.';
  end if;

  select p."CO_SEQ_PENDENCIA", p."ST_CONFERIDO" into v_pendencia, v_conferido_anterior
    from private."TB_PENDENCIA_COORDENADA_LOCAL" p
   where p."DS_CHAVE_LUGAR" = p_lugar
   for update;
  if p_acao = 'CONFERENCIA' then
    if v_pendencia is null then
      raise exception using errcode = '22023', message = 'Este lugar não tem pendência de localização.';
    elsif v_conferido_anterior = 'S' then
      raise exception using errcode = '22023', message = 'Este lugar já foi conferido.';
    end if;
  end if;
  v_conferido := case when v_pendencia is null then null else coalesce(p_conferido, v_conferido_anterior) end;
  v_mudou := v_lat is null
             or abs(v_lat - p_latitude) > v_tolerancia
             or abs(v_lon - p_longitude) > v_tolerancia;
  if not v_mudou and v_conferido is not distinct from v_conferido_anterior then
    raise exception using errcode = '22023', message = 'A coordenada não mudou.';
  end if;

  if v_mudou then
    if v_existe then
      update public."TB_COORDENADA_LOCAL_VAGA" c
         set "CG_LATITUDE" = p_latitude, "CG_LONGITUDE" = p_longitude, "TP_ORIGEM" = 'MANUAL',
             "DT_ATUALIZACAO" = v_agora, "CO_USUARIO_ATUALIZACAO" = auth.uid()
       where c."DS_CHAVE_LUGAR" = p_lugar;
    else
      insert into public."TB_COORDENADA_LOCAL_VAGA"
        ("DS_CHAVE_LUGAR", "CO_MUNICIPIO_IBGE", "NO_MUNICIPIO", "SG_UF", "CG_LATITUDE", "CG_LONGITUDE",
         "TP_ORIGEM", "DT_ATUALIZACAO", "CO_USUARIO_ATUALIZACAO")
      values (p_lugar, v_lugar.ibge, case when v_lugar.so_uf then null else v_lugar.municipio end, v_lugar.uf,
              p_latitude, p_longitude, 'MANUAL', v_agora, auth.uid());
    end if;
  end if;
  if v_conferido is distinct from v_conferido_anterior then
    update private."TB_PENDENCIA_COORDENADA_LOCAL" p
       set "ST_CONFERIDO" = v_conferido,
           "DT_CONFERENCIA" = case when v_conferido = 'S' then v_agora end,
           "CO_USUARIO_CONFERENCIA" = case when v_conferido = 'S' then auth.uid() end
     where p."CO_SEQ_PENDENCIA" = v_pendencia;
  end if;
  insert into private."TH_COORDENADA_LOCAL_VAGA"
    ("CO_USUARIO", "DS_CHAVE_LUGAR", "CG_LATITUDE_ANTERIOR", "CG_LONGITUDE_ANTERIOR", "CG_LATITUDE", "CG_LONGITUDE",
     "DS_MOTIVO", "TP_ACAO", "ST_CONFERIDO_ANTERIOR", "ST_CONFERIDO", "CO_HISTORICO_DESFEITO")
  values (auth.uid(), p_lugar, v_lat, v_lon, p_latitude, p_longitude,
          btrim(p_motivo), p_acao, v_conferido_anterior, v_conferido, p_historico_desfeito)
  returning "CO_SEQ_HISTORICO" into v_historico;

  return jsonb_build_object(
    'lugar', p_lugar, 'latitude', p_latitude, 'longitude', p_longitude,
    'conferido', case when v_conferido is null then null else to_jsonb(v_conferido = 'S') end,
    'historico', v_historico, 'alterado_em', v_agora);
end;
$_$;

--
-- Name: FUNCTION "FC_APLICAR_COORDENADA_LOCAL"(p_lugar text, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_acao text, p_conferido text, p_historico_desfeito bigint); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_APLICAR_COORDENADA_LOCAL"(p_lugar text, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_acao text, p_conferido text, p_historico_desfeito bigint) IS 'Grava uma alteração de coordenada de um lugar do mapa de Projetos (correção, conferência ou desfazer): administrador global ou gestor (FC_PODE_EDITAR_COORDENADA), limites do Brasil, motivo, lugar existente e posição anterior (tolerância 1e-9); atualiza a pendência e registra o histórico. Só chamada pelas RPCs do editor.';

--
-- Name: FC_APLICAR_COORDENADA_MAPA(jsonb, double precision, double precision, double precision, double precision, text, text, text, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_APLICAR_COORDENADA_MAPA"(p_alvo jsonb, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_acao text, p_conferido text, p_historico_desfeito bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_payload jsonb;
  v_ponto jsonb;
  v_caminho text[];
  v_fonte text := p_alvo ->> 'fonte';
  v_tipo text := p_alvo ->> 'tipo';
  v_dsei text := p_alvo ->> 'dsei';
  v_indice integer;
  v_dsei_indice integer;
  v_nome text;
  v_codigo text;
  v_lat double precision;
  v_lon double precision;
  v_pendencia bigint;
  v_conferido_anterior text;
  v_conferido text;
  v_mudou boolean;
  v_historico bigint;
  v_agora timestamptz := clock_timestamp();
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode corrigir coordenadas.';
  end if;
  if p_acao is null or p_acao not in ('CORRECAO', 'CONFERENCIA', 'DESFAZER')
     or coalesce(p_conferido, 'S') not in ('S', 'N') then
    raise exception using errcode = '22023', message = 'Ação inválida.';
  end if;
  if p_latitude is null or p_longitude is null
     or not (p_latitude between -34.9 and 6.4)
     or not (p_longitude between -74.2 and -32) then
    raise exception using errcode = '22023', message = 'A coordenada deve ficar nos limites do Brasil.';
  end if;
  if p_motivo is null or length(btrim(p_motivo)) not between 10 and 1000 then
    raise exception using errcode = '22023', message = 'Descreva o motivo da correção (10 a 1000 caracteres).';
  end if;
  if jsonb_typeof(p_alvo) is distinct from 'object'
     or v_fonte is null or v_tipo is null
     or not ((v_fonte = 'lmap' and v_tipo in ('sede', 'polo', 'casai'))
          or (v_fonte = 'rede_cnes' and v_tipo in ('u', 'c', 'nac')))
     or coalesce(p_alvo ->> 'indice', '') !~ '^[0-9]{1,6}$'
     or nullif(p_alvo ->> 'nome', '') is null then
    raise exception using errcode = '22023', message = 'Ponto do mapa inválido.';
  end if;
  v_indice := (p_alvo ->> 'indice')::integer;
  select c.payload into v_payload from public."TB_CONFIG_MAPA_SAUDE_INDIG" c
   where c.chave = v_fonte for update;
  if not found then raise exception 'Cadastro do mapa não encontrado.'; end if;
  if v_fonte = 'lmap' and v_tipo = 'sede' then
    v_caminho := array['dsei', v_indice::text];
    if (v_payload #> v_caminho) ->> 'k' is distinct from v_dsei then
      raise exception using errcode = 'PT409', message = 'O ponto mudou. Atualize o mapa e tente novamente.';
    end if;
  elsif v_fonte = 'lmap' and v_tipo = 'polo' then
    select (d.ordinality - 1)::integer into v_dsei_indice
      from jsonb_array_elements(v_payload -> 'dsei') with ordinality d
     where d.value ->> 'k' = v_dsei;
    if v_dsei_indice is null then raise exception 'DSEI não encontrado.'; end if;
    v_caminho := array['dsei', v_dsei_indice::text, 'polos', v_indice::text];
  elsif v_fonte = 'lmap' then
    v_caminho := array['casai', v_indice::text];
  elsif v_tipo = 'nac' then
    v_caminho := array['nac', v_indice::text];
  else
    if nullif(v_dsei, '') is null then raise exception 'DSEI não informado.'; end if;
    v_caminho := array['rede', v_dsei, v_tipo, v_indice::text];
  end if;
  v_ponto := v_payload #> v_caminho;
  if v_fonte = 'rede_cnes' then
    v_nome := v_ponto ->> 0;
    v_codigo := v_ponto ->> 1;
    v_lat := (v_ponto ->> 2)::double precision;
    v_lon := (v_ponto ->> 3)::double precision;
  else
    v_nome := v_ponto ->> 'n';
    v_codigo := case when v_tipo = 'polo' then v_ponto ->> 'cod' else null end;
    v_lat := (v_ponto ->> 'lat')::double precision;
    v_lon := (v_ponto ->> 'lon')::double precision;
  end if;
  if v_ponto is null or v_nome is distinct from p_alvo ->> 'nome'
     or v_codigo is distinct from p_alvo ->> 'codigo'
     -- Tolerância 1e-9 (como em Projetos): o jsonb arredonda o float gravado e o
     -- histórico guarda o valor inteiro; igualdade exata recusava o desfazer.
     or coalesce(abs(v_lat - p_latitude_anterior) > 1e-9, (v_lat is null) <> (p_latitude_anterior is null))
     or coalesce(abs(v_lon - p_longitude_anterior) > 1e-9, (v_lon is null) <> (p_longitude_anterior is null)) then
    raise exception using errcode = 'PT409', message = 'O ponto mudou. Atualize o mapa e tente novamente.';
  end if;

  select p."CO_SEQ_PENDENCIA", p."ST_CONFERIDO" into v_pendencia, v_conferido_anterior
    from private."TB_PENDENCIA_COORDENADA_MAPA" p
   where p."TP_FONTE" = v_fonte and p."TP_PONTO" = v_tipo
     and p."NO_DSEI" = v_dsei and p."CO_PONTO" = v_codigo
   for update;
  if p_acao = 'CONFERENCIA' then
    if v_pendencia is null then
      raise exception using errcode = '22023', message = 'Este ponto não tem pendência de localização.';
    elsif v_conferido_anterior = 'S' then
      raise exception using errcode = '22023', message = 'Este ponto já foi conferido.';
    end if;
  end if;
  v_conferido := case when v_pendencia is null then null else coalesce(p_conferido, v_conferido_anterior) end;
  v_mudou := coalesce(abs(v_lat - p_latitude) > 1e-9, (v_lat is null) <> (p_latitude is null))
           or coalesce(abs(v_lon - p_longitude) > 1e-9, (v_lon is null) <> (p_longitude is null));
  if not v_mudou and v_conferido is not distinct from v_conferido_anterior then
    raise exception using errcode = '22023', message = 'A coordenada não mudou.';
  end if;

  if v_mudou then
    if v_fonte = 'rede_cnes' then
      v_payload := jsonb_set(jsonb_set(v_payload, v_caminho || array['2'], to_jsonb(p_latitude), false),
        v_caminho || array['3'], to_jsonb(p_longitude), false);
    else
      v_payload := jsonb_set(jsonb_set(v_payload, v_caminho || array['lat'], to_jsonb(p_latitude), true),
        v_caminho || array['lon'], to_jsonb(p_longitude), true);
    end if;
    update public."TB_CONFIG_MAPA_SAUDE_INDIG" c set payload = v_payload, updated_at = v_agora
     where c.chave = v_fonte;
  end if;
  if v_conferido is distinct from v_conferido_anterior then
    update private."TB_PENDENCIA_COORDENADA_MAPA" p
       set "ST_CONFERIDO" = v_conferido,
           "DT_CONFERENCIA" = case when v_conferido = 'S' then v_agora end,
           "CO_USUARIO_CONFERENCIA" = case when v_conferido = 'S' then auth.uid() end
     where p."CO_SEQ_PENDENCIA" = v_pendencia;
  end if;
  insert into private."TH_COORDENADA_MAPA_SAUDE_INDIG"
    ("CO_USUARIO", "DS_ALVO", "CG_LATITUDE_ANTERIOR", "CG_LONGITUDE_ANTERIOR", "CG_LATITUDE", "CG_LONGITUDE",
     "DS_MOTIVO", "TP_ACAO", "ST_CONFERIDO_ANTERIOR", "ST_CONFERIDO", "CO_HISTORICO_DESFEITO")
  values (auth.uid(), p_alvo, v_lat, v_lon, p_latitude, p_longitude,
          btrim(p_motivo), p_acao, v_conferido_anterior, v_conferido, p_historico_desfeito)
  returning "CO_SEQ_HISTORICO" into v_historico;

  return jsonb_build_object(
    'alvo', p_alvo, 'latitude', p_latitude, 'longitude', p_longitude,
    'conferido', case when v_conferido is null then null else to_jsonb(v_conferido = 'S') end,
    'historico', v_historico, 'alterado_em', v_agora,
    'lmap', (select c.payload from public."TB_CONFIG_MAPA_SAUDE_INDIG" c where c.chave = 'lmap'),
    'rede_cnes', (select c.payload from public."TB_CONFIG_MAPA_SAUDE_INDIG" c where c.chave = 'rede_cnes'));
end;
$_$;

--
-- Name: FUNCTION "FC_APLICAR_COORDENADA_MAPA"(p_alvo jsonb, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_acao text, p_conferido text, p_historico_desfeito bigint); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_APLICAR_COORDENADA_MAPA"(p_alvo jsonb, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_acao text, p_conferido text, p_historico_desfeito bigint) IS 'Grava uma alteração de coordenada do mapa (correção, conferência ou desfazer): administrador global ou gestor (FC_PODE_EDITAR_COORDENADA), limites do Brasil, motivo, identidade e posição anterior; atualiza a pendência e registra o histórico. Só chamada pelas RPCs do editor.';

--
-- Name: FC_AREAS_DO_PERFIL(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AREAS_DO_PERFIL"(p_perfil_usuario uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when a."ST_ADMIN_GLOBAL" is true
      then (select coalesce(array_agg(x."CO_AREA" order by x."NU_ORDEM"), '{}') from public."TB_AREA" x)
    when u."CO_COORDENACAO" is not null
      then coalesce((select array[c."CO_AREA"] from public."TB_COORDENACAO" c where c."CO_COORDENACAO" = u."CO_COORDENACAO"), '{}')
    else coalesce((
      select array_agg(r."CO_AREA" order by x."NU_ORDEM")
        from public."RL_PERFIL_USUARIO_AREA" r
        join public."TB_AREA" x on x."CO_AREA" = r."CO_AREA"
       where r."CO_PERFIL_USUARIO" = u.id), '{}')
  end
  from public."TB_PERFIL_USUARIO" u
  left join public."TB_GRUPO_ACESSO" a on a."CO_GRUPO_ACESSO" = u.perfil
  where u.id = p_perfil_usuario and u.ativo;
$$;

--
-- Name: FUNCTION "FC_AREAS_DO_PERFIL"(p_perfil_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AREAS_DO_PERFIL"(p_perfil_usuario uuid) IS 'Áreas de um usuário ativo: todas (admin global); a da coordenação; senão as de RL_PERFIL_USUARIO_AREA.';

--
-- Name: FC_AREAS_USUARIO(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AREAS_USUARIO"() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when coalesce((select auth.role()) = 'service_role', false) or private.is_master()
      then (select coalesce(array_agg(a."CO_AREA" order by a."NU_ORDEM"), '{}') from public."TB_AREA" a)
    else coalesce((select private."FC_AREAS_DO_PERFIL"(p.id) from private.current_profile() p where p.ativo), '{}')
  end;
$$;

--
-- Name: FUNCTION "FC_AREAS_USUARIO"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AREAS_USUARIO"() IS 'Áreas que o usuário logado vê: todas para admin e service_role; a da coordenação; senão as de RL_PERFIL_USUARIO_AREA.';

--
-- Name: FC_AREA_DA_UNIDADE(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AREA_DA_UNIDADE"(p_unidade text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select r."CO_AREA" from public."TA_UNIDADE_AREA" r
      where public.analises_norm_key(r."NO_UNIDADE") = public.analises_norm_key(p_unidade)
      order by r."NO_UNIDADE" limit 1),
    (select 'saude-indigena' from public."TD_UNIDADE" u
      where public.analises_norm_key(u.nome_oficial) = public.analises_norm_key(p_unidade)
      limit 1)
  );
$$;

--
-- Name: FUNCTION "FC_AREA_DA_UNIDADE"(p_unidade text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AREA_DA_UNIDADE"(p_unidade text) IS 'Área conhecida de uma unidade: TA_UNIDADE_AREA; senão catálogo TD_UNIDADE (DSEI/CASAI) -> saude-indigena; senão NULL.';

--
-- Name: FC_AREA_EDITAL(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AREA_EDITAL"(p_responsavel text, p_unidade text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select r."CO_AREA" from public."TA_UNIDADE_AREA" r
      where public.analises_norm_key(r."NO_UNIDADE") = public.analises_norm_key(p_unidade)),
    case when upper(trim(coalesce(p_responsavel, ''))) = 'CORES' then 'sede' else 'saude-indigena' end
  );
$$;

--
-- Name: FUNCTION "FC_AREA_EDITAL"(p_responsavel text, p_unidade text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AREA_EDITAL"(p_responsavel text, p_unidade text) IS 'Área de um edital: unidade do CORES -> TA_UNIDADE_AREA; responsável CORES sem unidade conhecida -> sede; o resto -> saude-indigena.';

--
-- Name: FC_ARQUIVO_DO_LINK_EMPREGARE(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ARQUIVO_DO_LINK_EMPREGARE"(p_link text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select substring(p_link from '[?&]arquivo=([^&]*)');
$$;

--
-- Name: FUNCTION "FC_ARQUIVO_DO_LINK_EMPREGARE"(p_link text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ARQUIVO_DO_LINK_EMPREGARE"(p_link text) IS 'O parâmetro arquivo= do link Visualizar Arquivo da Empregare (o nome do arquivo guardado lá): diz se o arquivo de um anexo mudou, sem depender do token do link. Nulo se o link não tem o parâmetro.';

--
-- Name: FC_ATUALIZAR_CONTRATADOS_DO_EDITAL(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ATUALIZAR_CONTRATADOS_DO_EDITAL"(p_edital uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_qt integer;
begin
  if p_edital is null
     or not exists (select 1 from public."TB_LISTA_APROVADO" l where l.edital_id = p_edital::text) then
    return 0;
  end if;
  update public."TB_MONITORAMENTO_INDIGENA" m
     set contratados = n.qt, updated_at = now()
    from (select coalesce((count(c.id) filter (where c.status in ('Contratado', 'Migração') and not private."FC_EM_OUTRA_LISTA"(c.id)))::integer, 0) qt
            from public."TB_LISTA_APROVADO" l
            left join public."TB_CANDIDATO_APROVADO" c on c.lista_id = l.id and c.removido_em is null
           where l.edital_id = p_edital::text and l.vigente is true) n
   where m.id = p_edital and m.ativo and m.contratados is distinct from n.qt;
  get diagnostics v_qt = row_count;
  return v_qt;
end;
$$;

--
-- Name: FUNCTION "FC_ATUALIZAR_CONTRATADOS_DO_EDITAL"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ATUALIZAR_CONTRATADOS_DO_EDITAL"(p_edital uuid) IS 'Atualiza TB_MONITORAMENTO_INDIGENA.contratados de um edital ativo pela lista de aprovados vigente (Contratado ou Migração, menos os em outra lista); sem lista vigente, zera — só quando o edital já teve lista (20261030090000). Só grava se mudou.';

--
-- Name: FC_ATUALIZAR_FONTES_DAS_LEITURAS(boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ATUALIZAR_FONTES_DAS_LEITURAS"(p_gatilhos boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_leitura record;
  v_fontes text[];
  v_tabela text;
  v_rel regclass;
  v_citadas text;
  v_atributos smallint[];
  v_colunas text;
  v_upd record;
  v_gatilho text;
  v_novos text[] := '{}';
  v_contagem jsonb := '{}';
begin
  for v_leitura in select * from private."TD_LEITURA_POR_MARCA" l order by l."NO_LEITURA" loop
    select coalesce(array_agg(distinct x.f order by x.f), '{}') into v_fontes
      from (select f from private."FC_FONTES_PELO_CODIGO"(v_leitura."DS_FUNCOES") f
            union
            select unnest(v_leitura."DS_FONTES_EXTRAS")) x(f);
    delete from private."TD_FONTE_DA_LEITURA" f
     where f."NO_LEITURA" = v_leitura."NO_LEITURA" and f."NO_FONTE" <> all (v_fontes);
    insert into private."TD_FONTE_DA_LEITURA" ("NO_LEITURA", "NO_FONTE")
    select v_leitura."NO_LEITURA", u.f from unnest(v_fontes) u(f)
    on conflict do nothing;
    v_contagem := v_contagem || jsonb_build_object(v_leitura."NO_LEITURA", cardinality(v_fontes));

    -- Coluna fora da marca citada no código da leitura: a marca deixaria de mudar
    -- quando ela muda. Recusa (tire a coluna de TD_COLUNA_SEM_MARCA).
    if exists (select 1 from private."TD_COLUNA_SEM_MARCA" c where c."NO_FONTE" = any (v_fontes)) then
      select string_agg(c."NO_FONTE" || '.' || c."NO_COLUNA", ', ' order by c."NO_FONTE", c."NO_COLUNA")
        into v_citadas
        from private."TD_COLUNA_SEM_MARCA" c
       cross join (select private."FC_CODIGO_DA_LEITURA"(v_leitura."DS_FUNCOES") as codigo) x
       where c."NO_FONTE" = any (v_fontes)
         and x.codigo ~ ('\m' || c."NO_COLUNA" || '\M');
      if v_citadas is not null then
        raise exception 'A leitura % cita coluna(s) fora da marca: %. Tire de private."TD_COLUNA_SEM_MARCA".',
          v_leitura."NO_LEITURA", v_citadas using errcode = '22023';
      end if;
    end if;
  end loop;

  if p_gatilhos then
    -- O gatilho antigo (um só, por comando, sem tabela de transição: contava comando de 0 linhas).
    for v_rel in select t.tgrelid::regclass from pg_catalog.pg_trigger t where t.tgname = 'TG_VERSAO_FONTE' loop
      execute format('drop trigger "TG_VERSAO_FONTE" on %s', v_rel);
    end loop;
  end if;

  for v_tabela in select distinct f."NO_FONTE" from private."TD_FONTE_DA_LEITURA" f where p_gatilhos order by 1 loop
    v_rel := to_regclass(format('%I.%I', split_part(v_tabela, '.', 1), split_part(v_tabela, '.', 2)));
    if v_rel is null then
      raise exception 'Fonte inexistente: %', v_tabela using errcode = '42P01';
    end if;

    -- Com coluna fora da marca: UPDATE OF as outras colunas, por linha. Sem: por comando.
    v_atributos := null;
    v_colunas := null;
    if exists (select 1 from private."TD_COLUNA_SEM_MARCA" c
                 join pg_catalog.pg_attribute a
                   on a.attrelid = v_rel and a.attname = c."NO_COLUNA" and a.attnum > 0 and not a.attisdropped
                where c."NO_FONTE" = v_tabela) then
      select array_agg(a.attnum order by a.attnum),
             string_agg(format('%I', a.attname), ', ' order by a.attnum)
        into v_atributos, v_colunas
        from pg_catalog.pg_attribute a
       where a.attrelid = v_rel and a.attnum > 0 and not a.attisdropped
         and not exists (select 1 from private."TD_COLUNA_SEM_MARCA" c
                          where c."NO_FONTE" = v_tabela and c."NO_COLUNA" = a.attname);
    end if;

    -- O gatilho de UPDATE que não é o que devia ser (a lista de colunas mudou) sai e volta.
    select (t.tgtype & 1) = 1 as por_linha,
           array(select x from unnest(t.tgattr::smallint[]) x order by x) as atributos
      into v_upd
      from pg_catalog.pg_trigger t
     where t.tgrelid = v_rel and t.tgname = 'TG_VERSAO_FONTE_UPD';
    if found and (case when v_atributos is null then v_upd.por_linha or cardinality(v_upd.atributos) > 0
                       else not v_upd.por_linha or v_upd.atributos is distinct from v_atributos end) then
      execute format('drop trigger "TG_VERSAO_FONTE_UPD" on %s', v_rel);
    end if;

    foreach v_gatilho in array array['TG_VERSAO_FONTE_INS', 'TG_VERSAO_FONTE_UPD', 'TG_VERSAO_FONTE_DEL', 'TG_VERSAO_FONTE_TRUNC'] loop
      if not exists (select 1 from pg_catalog.pg_trigger t where t.tgrelid = v_rel and t.tgname = v_gatilho) then
        execute format('create trigger %I after %s on %s %s execute function private."FC_TG_VERSAO_FONTE"()',
          v_gatilho,
          case v_gatilho
            when 'TG_VERSAO_FONTE_INS' then 'insert'
            when 'TG_VERSAO_FONTE_DEL' then 'delete'
            when 'TG_VERSAO_FONTE_TRUNC' then 'truncate'
            else case when v_atributos is null then 'update' else 'update of ' || v_colunas end
          end,
          v_rel,
          case v_gatilho
            when 'TG_VERSAO_FONTE_INS' then 'referencing new table as novas for each statement'
            when 'TG_VERSAO_FONTE_DEL' then 'referencing old table as antigas for each statement'
            when 'TG_VERSAO_FONTE_TRUNC' then 'for each statement'
            else case when v_atributos is null then 'referencing new table as novas for each statement'
                      else 'for each row' end
          end);
        if not (v_tabela = any (v_novos)) then
          v_novos := v_novos || v_tabela;
        end if;
      end if;
      -- Vale também com session_replication_role = replica (correções de dados).
      if exists (select 1 from pg_catalog.pg_trigger t
                  where t.tgrelid = v_rel and t.tgname = v_gatilho and t.tgenabled <> 'A') then
        execute format('alter table %s enable always trigger %I', v_rel, v_gatilho);
      end if;
    end loop;
  end loop;

  return jsonb_build_object('leituras', v_contagem, 'gatilhos_novos', to_jsonb(v_novos));
end;
$$;

--
-- Name: FUNCTION "FC_ATUALIZAR_FONTES_DAS_LEITURAS"(p_gatilhos boolean); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ATUALIZAR_FONTES_DAS_LEITURAS"(p_gatilhos boolean) IS 'Recalcula TD_FONTE_DA_LEITURA pelo código (FC_FONTES_PELO_CODIGO das funções de cada leitura, mais as extras), recusa coluna de TD_COLUNA_SEM_MARCA citada no código de uma leitura e, com p_gatilhos, põe em toda fonte os gatilhos TG_VERSAO_FONTE_INS/UPD/DEL/TRUNC (ENABLE ALWAYS; o UPD é UPDATE OF as colunas da marca, por linha, quando a fonte tem coluna fora) e tira o TG_VERSAO_FONTE antigo (20261029170000; gatilhos por evento em 20261103150000). Rodar na migration que mudar uma função do fecho de uma leitura.';

--
-- Name: FC_ATUALIZAR_KPIS_PELA_SELECAO(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ATUALIZAR_KPIS_PELA_SELECAO"() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_qt integer;
begin
  with ed as materialized (
    select m.id, m."CO_AREA",
           coalesce(private."FC_NUMERO_EDITAL"(m.edital),
                    nullif('nome:' || private."FC_TEXTO_BUSCA_RECURSO"(m.edital), 'nome:')) as chave,
           exists (select 1 from public."TB_ORIGEM_ANALISE_EDITAL" o
                    where o."CO_MONITORAMENTO" = m.id and o."TP_ORIGEM" = 'MONITORA') as no_monitora
      from public."TB_MONITORAMENTO_INDIGENA" m
     where m.ativo
  ),
  -- A chave da análise só vale quando aponta para um edital só na área.
  chave_unica as (
    select e."CO_AREA", e.chave, min(e.id::text)::uuid as id
      from ed e
     where e.chave is not null
     group by 1, 2
    having count(*) = 1
  ),
  -- Fonte 1: avaliação documental nativa (resumo da última execução de cada vaga).
  pre as (
    select pv."CO_MONITORAMENTO" id,
           sum(pv."QT_INSCRITO")::integer inscritos,
           sum(pv."QT_LOTE" + pv."QT_ACIMA_CORTE")::integer aptos,
           sum(pv."QT_ELIMINADO")::integer total_eliminados,
           max(pv."DT_ATUALIZACAO") em
      from public."TB_PRE_CLASSIF_VAGA" pv
     where pv."CO_MONITORAMENTO" in (select id from ed)
     group by 1
  ),
  pre_cancelados as (
    select p."CO_MONITORAMENTO" id, count(*)::integer qt
      from public."TB_PRE_CLASSIFICACAO" p
     where p."CO_MONITORAMENTO" in (select id from pre)
       and p."TP_SITUACAO" = 'ELIMINADO' and p."CO_MOTIVO_ELIMINACAO" = 'CANCELADO'
     group by 1
  ),
  -- Fonte 1 sem resumo: o último retrato das inscrições de cada vaga.
  retrato as (
    select r."CO_MONITORAMENTO" id,
           sum(r."QT_INSCRITO")::integer inscritos,
           case when count(*) = count(r."QT_APTO") then sum(r."QT_APTO")::integer end aptos,
           case when count(*) = count(r."QT_ELIMINADO") then sum(r."QT_ELIMINADO")::integer end total_eliminados,
           max(r."DT_ATUALIZACAO") em
      from (select distinct on (t."CO_MONITORAMENTO", t."CO_VAGA") t.*
              from public."TH_INSCRICAO_VAGA_EDITAL" t
             where t."CO_MONITORAMENTO" in (select id from ed)
               and t."CO_MONITORAMENTO" not in (select id from pre)
             order by t."CO_MONITORAMENTO", t."CO_VAGA", t."DT_RETRATO" desc) r
     group by 1
  ),
  -- Avaliação no MONITORA: o resultado das fichas, pelo id do edital.
  fichas as (
    select f."CO_MONITORAMENTO" id,
           (count(*) filter (where f."TP_SITUACAO" = 'CONCLUIDA' and f."TP_RESULTADO" = 'APTO'))::integer aprovados,
           (count(*) filter (where f."TP_SITUACAO" = 'CONCLUIDA' and f."TP_RESULTADO" is distinct from 'APTO'))::integer reprovados
      from public."TB_FICHA_ANALISE" f
     where f."CO_MONITORAMENTO" in (select id from ed where no_monitora)
     group by 1
  ),
  -- Fonte 2: a Seleção, só quando coerente (aptos <= inscritos).
  sel as (
    select s."CO_MONITORAMENTO" id,
           sum(coalesce(s."QT_INSCRITO", 0))::integer inscritos,
           sum(coalesce(s."QT_APTO_ANALISE", 0))::integer aptos,
           sum(coalesce(s."QT_CANCELADO", 0))::integer cancelados,
           sum(coalesce(s."QT_ELIMINADO_NOTA", 0))::integer eliminados_nota,
           sum(coalesce(s."QT_REPROVADO_ANALISE", 0))::integer reprovados,
           sum(coalesce(s."QT_TOTAL_ELIMINADO", 0))::integer total_eliminados,
           -- Data dos dados (20261103150000): a última mudança nas vagas do edital, como
           -- nas outras fontes. Antes era a última carga concluída (de todas), e cada
           -- carga regravava os ~130 editais da Seleção com histórico sem mudar nada.
           max(s."DT_ATUALIZACAO") em
      from public."TB_SELECAO_VAGA" s
     where s."ST_REGISTRO_ATIVO" = 'S' and s."CO_MONITORAMENTO" in (select id from ed)
     group by 1
    having sum(coalesce(s."QT_APTO_ANALISE", 0)) <= sum(coalesce(s."QT_INSCRITO", 0))
  ),
  -- Fonte 3: as análises do edital (número ou nome único na área).
  aprov as (
    select u.id,
           (count(*) filter (where a.status_consolidado = 'Aprovado'))::integer qt,
           (count(*) filter (where a.status_consolidado = 'Reprovado'))::integer reprovados,
           count(*)::integer candidatos,
           max(a.updated_at) em
      from chave_unica u
      join public."TB_ANALISE_CURRICULAR" a
        on a."CO_AREA" = u."CO_AREA" and a.ativo
       and coalesce(private."FC_NUMERO_EDITAL"(a.edital),
                    nullif('nome:' || private."FC_TEXTO_BUSCA_RECURSO"(a.edital), 'nome:')) = u.chave
     group by 1
  ),
  -- Entrevistados: pessoas distintas (a entrevista vigente) que compareceram.
  entr as (
    select e."CO_MONITORAMENTO" id,
           (count(*) filter (where e."ST_COMPARECEU" = 'S'
                               or (e."ST_COMPARECEU" is null and e."TP_PARECER" in ('APTO', 'INAPTO'))))::integer qt
      from public."TB_ENTREVISTA" e
     where e."CO_ENTREVISTA" in (select v from private."FC_ENTREVISTAS_VIGENTES"(null) v)
       and e."CO_MONITORAMENTO" in (select id from ed)
     group by 1
  ),
  contr as (
    select l.edital_id::uuid id,
           (count(c.id) filter (where c.status in ('Contratado', 'Migração') and not private."FC_EM_OUTRA_LISTA"(c.id)))::integer qt
      from public."TB_LISTA_APROVADO" l
      left join public."TB_CANDIDATO_APROVADO" c on c.lista_id = l.id and c.removido_em is null
     where l.vigente is true and l.edital_id in (select id::text from ed)
     group by 1
  ),
  fonte as (
    select t.id, t.no_monitora,
           case when p.id is not null or r.id is not null then 'AVALIACAO_DOCUMENTAL'
                when s.id is not null then 'SELECAO'
                when a.id is not null then 'ANALISES' end as fonte
      from ed t
      left join pre p on p.id = t.id
      left join retrato r on r.id = t.id
      left join sel s on s.id = t.id
      left join aprov a on a.id = t.id
  ),
  novo as (
    select t.id, t.fonte,
           case t.fonte when 'AVALIACAO_DOCUMENTAL' then coalesce(p.inscritos, r.inscritos)
                        when 'SELECAO' then s.inscritos end inscritos,
           case t.fonte when 'AVALIACAO_DOCUMENTAL' then coalesce(p.aptos, r.aptos)
                        when 'SELECAO' then s.aptos
                        when 'ANALISES' then a.candidatos end aptos,
           case t.fonte when 'AVALIACAO_DOCUMENTAL' then case when p.id is not null then coalesce(pc.qt, 0) end
                        when 'SELECAO' then s.cancelados end cancelados,
           case t.fonte when 'SELECAO' then s.eliminados_nota end eliminados_nota,
           case t.fonte when 'AVALIACAO_DOCUMENTAL' then coalesce(p.total_eliminados, r.total_eliminados)
                        when 'SELECAO' then s.total_eliminados end total_eliminados,
           case t.fonte when 'AVALIACAO_DOCUMENTAL' then
                          case when t.no_monitora then coalesce(f.reprovados, 0) else a.reprovados end
                        when 'SELECAO' then s.reprovados
                        when 'ANALISES' then a.reprovados end reprovados,
           case t.fonte when 'AVALIACAO_DOCUMENTAL' then coalesce(p.em, r.em)
                        when 'SELECAO' then s.em
                        when 'ANALISES' then a.em end em,
           case when t.no_monitora then coalesce(f.aprovados, 0) else a.qt end aprovados,
           (a.id is not null or t.no_monitora) tem_aprovados,
           e.qt entrevistados, c.qt contratados
      from fonte t
      left join pre p on p.id = t.id
      left join pre_cancelados pc on pc.id = t.id
      left join retrato r on r.id = t.id
      left join fichas f on f.id = t.id
      left join sel s on s.id = t.id
      left join aprov a on a.id = t.id
      left join entr e on e.id = t.id
      left join contr c on c.id = t.id
     where t.fonte is not null or t.no_monitora or e.id is not null or c.id is not null
  ),
  -- Com fonte, todo campo do funil vem dela (ou nulo); sem fonte, o funil não muda.
  final as (
    select n.id,
           case when n.fonte is null then m.inscritos else n.inscritos end inscritos,
           case when n.fonte is null then m.aptos_analise else n.aptos end aptos_analise,
           case when n.fonte is null then m.cancelados else n.cancelados end cancelados,
           case when n.fonte is null then m.eliminados_nota else n.eliminados_nota end eliminados_nota,
           case when n.fonte is null then m.total_eliminados else n.total_eliminados end total_eliminados,
           case when n.fonte is null then m.reprovados_analise else n.reprovados end reprovados_analise,
           case when n.fonte is null then m."TP_FONTE_FUNIL" else n.fonte end fonte,
           case when n.fonte is null then m."DT_FONTE_FUNIL" else n.em end em,
           case when n.tem_aprovados then n.aprovados else m.aprovados_analise end aprovados_analise,
           coalesce(n.entrevistados, m.entrevistados) entrevistados,
           coalesce(n.contratados, m.contratados) contratados
      from novo n
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = n.id
  )
  update public."TB_MONITORAMENTO_INDIGENA" m
     set inscritos = f.inscritos,
         aptos_analise = f.aptos_analise,
         cancelados = f.cancelados,
         eliminados_nota = f.eliminados_nota,
         total_eliminados = f.total_eliminados,
         reprovados_analise = f.reprovados_analise,
         "TP_FONTE_FUNIL" = f.fonte,
         "DT_FONTE_FUNIL" = f.em,
         aprovados_analise = f.aprovados_analise,
         entrevistados = f.entrevistados,
         contratados = f.contratados,
         updated_at = now()
    from final f
   where m.id = f.id
     and (m.inscritos, m.aptos_analise, m.cancelados, m.eliminados_nota, m.total_eliminados,
          m.reprovados_analise, m."TP_FONTE_FUNIL", m."DT_FONTE_FUNIL", m.aprovados_analise,
          m.entrevistados, m.contratados)
         is distinct from
         (f.inscritos, f.aptos_analise, f.cancelados, f.eliminados_nota, f.total_eliminados,
          f.reprovados_analise, f.fonte, f.em, f.aprovados_analise, f.entrevistados, f.contratados);
  get diagnostics v_qt = row_count;
  return v_qt;
end;
$$;

--
-- Name: FUNCTION "FC_ATUALIZAR_KPIS_PELA_SELECAO"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_ATUALIZAR_KPIS_PELA_SELECAO"() IS 'Recalcula os KPIs de todo edital ativo (TB_MONITORAMENTO_INDIGENA). O funil (inscritos, aptos, cancelados, eliminados, reprovados) vem de UMA fonte, na ordem: avaliação documental nativa (TB_PRE_CLASSIF_VAGA; sem ela, o último TH_INSCRICAO_VAGA_EDITAL), Seleção coerente (pelo id), análises (aptos = candidatos; inscritos nulo); com fonte, campo sem valor nela fica nulo; sem fonte, o funil não muda. Grava TP_FONTE_FUNIL e DT_FONTE_FUNIL (Seleção: última mudança nas vagas do edital, 20261103150000). Aprovados: fichas (avaliação no MONITORA, pelo id) ou análises; entrevistados: pessoas distintas que compareceram (FC_ENTREVISTAS_VIGENTES); contratados: lista vigente. Só grava o que mudou; devolve quantos editais mudaram (20261022200000).';

--
-- Name: FC_AUTOMACAO_LIGADA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AUTOMACAO_LIGADA"(p_chave text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select c."ST_LIGADA" = 'S' from public."TB_CHAVE_AUTOMACAO" c where c."CO_CHAVE" = p_chave), true);
$$;

--
-- Name: FUNCTION "FC_AUTOMACAO_LIGADA"(p_chave text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AUTOMACAO_LIGADA"(p_chave text) IS 'true quando a chave da automação está ligada (ou não existe: chave nula ou fora da lista). 20261022190000.';

--
-- Name: FC_AVALIADOR_AVALIA(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AVALIADOR_AVALIA"(p_avaliador uuid, p_competencia uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- Sem vínculo com competência do mesmo roteiro = avalia todas; com vínculo, só as vinculadas.
  select not exists (
           select 1
             from public."TB_ENTREVISTA_AVALIADOR_COMPETENCIA" l
             join public."TB_ROTEIRO_COMPETENCIA" k on k."CO_COMPETENCIA" = l."CO_COMPETENCIA"
             join public."TB_ROTEIRO_COMPETENCIA" alvo on alvo."CO_COMPETENCIA" = p_competencia
            where l."CO_AVALIADOR" = p_avaliador and k."CO_ROTEIRO" = alvo."CO_ROTEIRO")
      or exists (
           select 1 from public."TB_ENTREVISTA_AVALIADOR_COMPETENCIA" l
            where l."CO_AVALIADOR" = p_avaliador and l."CO_COMPETENCIA" = p_competencia);
$$;

--
-- Name: FUNCTION "FC_AVALIADOR_AVALIA"(p_avaliador uuid, p_competencia uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AVALIADOR_AVALIA"(p_avaliador uuid, p_competencia uuid) IS 'O membro da banca avalia a competência? Sem vínculo (TB_ENTREVISTA_AVALIADOR_COMPETENCIA) com competência do mesmo roteiro, avalia todas.';

--
-- Name: FC_AVISOS_PARA_A_TELA(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_AVISOS_PARA_A_TELA"(p_avisos jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_avisos || jsonb_build_object('avisos', coalesce((
           select jsonb_agg(
                    jsonb_strip_nulls(
                      case
                        when exists (
                          select 1
                            from public."TB_CASO_AVISO_CONFERENCIA" c
                           where c."CO_AVISO_CONFERENCIA" = (a.aviso ->> 'id')::uuid)
                          then a.aviso - 'exemplos'
                        else a.aviso
                      end)
                    order by a.ordem)
             from jsonb_array_elements(p_avisos -> 'avisos') with ordinality a(aviso, ordem)
         ), '[]'::jsonb));
$$;

--
-- Name: FUNCTION "FC_AVISOS_PARA_A_TELA"(p_avisos jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_AVISOS_PARA_A_TELA"(p_avisos jsonb) IS 'listar_avisos_conferencia como a tela recebe: sem chaves nulas e sem exemplos em aviso com casos (20261015000000; separada em 20261029170000).';

--
-- Name: FC_BASE_DA_LISTA(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_BASE_DA_LISTA"(p_lista uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select md5(coalesce(string_agg(concat_ws('|', c.id, c.nome, c.codigo_vaga, c.classificacao, c.status,
                                            c.matricula, c.processo_sei, c.sub_judice, c.alterado_judicialmente,
                                            c."CO_ANALISE_CURRICULAR"), ',' order by c.id), ''))
    from public."TB_CANDIDATO_APROVADO" c
   where p_lista is not null and c.lista_id = p_lista and c.removido_em is null;
$$;

--
-- Name: FUNCTION "FC_BASE_DA_LISTA"(p_lista uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_BASE_DA_LISTA"(p_lista uuid) IS 'Assinatura (md5) do que o casamento lê da lista vigente: pessoas, posição, vaga, status, matrícula, processo, sub judice e análise. O plano só vale se ela não mudou. 20261030090000.';

--
-- Name: FC_BLOCO_DO_CARGO(jsonb, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_BLOCO_DO_CARGO"(p_bloco jsonb, p_sobrescrita jsonb, p_nivel text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_parte jsonb;
  v_bloco jsonb;
begin
  if jsonb_typeof(p_sobrescrita) is distinct from 'object' then
    return p_bloco;
  end if;
  v_parte := p_bloco #> array['por_nivel', coalesce(p_nivel, '')];
  v_bloco := (case when jsonb_typeof(v_parte) = 'object' then p_bloco || v_parte else p_bloco end) - 'por_nivel';
  if p_sobrescrita -> 'nao_se_aplica' = 'true'::jsonb then
    v_bloco := v_bloco || jsonb_build_object('nao_se_aplica', true);
  end if;
  if p_sobrescrita ? 'teto' then
    v_bloco := v_bloco || jsonb_build_object('teto', p_sobrescrita -> 'teto');
  end if;
  if jsonb_typeof(p_sobrescrita -> 'faixas') = 'array' and jsonb_array_length(p_sobrescrita -> 'faixas') > 0 then
    v_bloco := v_bloco || jsonb_build_object('faixas', p_sobrescrita -> 'faixas');
  end if;
  if jsonb_typeof(p_sobrescrita -> 'extras') = 'array' and jsonb_array_length(p_sobrescrita -> 'extras') > 0 then
    v_bloco := v_bloco || jsonb_build_object('extras', p_sobrescrita -> 'extras');
  end if;
  if jsonb_typeof(p_sobrescrita -> 'area') = 'string' and btrim(p_sobrescrita ->> 'area') <> '' then
    v_bloco := v_bloco || jsonb_build_object('area', btrim(p_sobrescrita ->> 'area'));
  end if;
  if jsonb_typeof(p_sobrescrita -> 'requisitos') = 'array' and jsonb_array_length(p_sobrescrita -> 'requisitos') > 0 then
    v_bloco := v_bloco || jsonb_build_object(
      'requisitos', p_sobrescrita -> 'requisitos',
      'motivos', (case when jsonb_typeof(p_bloco -> 'motivos') = 'array' then p_bloco -> 'motivos' else '[]'::jsonb end)
                 || (select jsonb_agg(jsonb_build_object(
                              'codigo', q -> 'codigo',
                              'texto', q -> 'motivo',
                              'item_edital', coalesce(nullif(q ->> 'item_edital', ''), nullif(p_bloco ->> 'item_edital', ''), ''),
                              'efeito', 'ELIMINA') order by n)
                       from jsonb_array_elements(p_sobrescrita -> 'requisitos') with ordinality x(q, n)));
  end if;
  return v_bloco;
end;
$$;

--
-- Name: FUNCTION "FC_BLOCO_DO_CARGO"(p_bloco jsonb, p_sobrescrita jsonb, p_nivel text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_BLOCO_DO_CARGO"(p_bloco jsonb, p_sobrescrita jsonb, p_nivel text) IS 'O bloco com a diferença do cargo por cima do nível (cargo > nível > padrão): por_nivel do nível por baixo (e sai), teto, faixas, extras, área exigida, requisitos (que viram motivos do bloco com efeito ELIMINA) e nao_se_aplica (o bloco não vale para a vaga, 20261014150000). Igual a blocoDoCargo (regra-por-cargo.ts).';

--
-- Name: FC_BLOCO_NAO_PONTUA_NO_NIVEL(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_BLOCO_NAO_PONTUA_NO_NIVEL"(p_bloco jsonb, p_nivel text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(
         coalesce(p_nivel, '') <> ''
     and coalesce(p_bloco ->> 'tipo', '') in ('TITULOS', 'CURSOS', 'VINCULOS')
     -- Sem efeito que mude o resultado, na situação ou nos motivos.
     and not exists (select 1 from jsonb_each(case when jsonb_typeof(p_bloco -> 'efeitos') = 'object'
                                                   then p_bloco -> 'efeitos' else '{}'::jsonb end) e
                      where jsonb_typeof(e.value) = 'string' and e.value #>> '{}' not in ('', 'SO_REGISTRO'))
     and not exists (select 1 from jsonb_array_elements(case when jsonb_typeof(p_bloco -> 'motivos') = 'array'
                                                             then p_bloco -> 'motivos' else '[]'::jsonb end) m
                      where jsonb_typeof(m -> 'efeito') = 'string' and m ->> 'efeito' not in ('', 'SO_REGISTRO'))
     -- Sem requisito do cargo, sem linha extra e sem experiência mínima.
     and coalesce(jsonb_array_length(case when jsonb_typeof(p_bloco -> 'requisitos') = 'array' then p_bloco -> 'requisitos' end), 0) = 0
     and coalesce(jsonb_array_length(case when jsonb_typeof(p_bloco -> 'extras') = 'array' then p_bloco -> 'extras' end), 0) = 0
     and coalesce(jsonb_array_length(case when jsonb_typeof(p_bloco #> array['por_nivel', p_nivel, 'extras']) = 'array'
                                          then p_bloco #> array['por_nivel', p_nivel, 'extras'] end), 0) = 0
     and not coalesce(jsonb_typeof(p_bloco -> 'minimo_meses') = 'number' and (p_bloco ->> 'minimo_meses')::numeric > 0, false)
     -- Teto 0 no nível ou, nos títulos por nível, sem tabela para o nível.
     and (coalesce(private."FC_TETO_DO_BLOCO"(p_bloco, p_nivel) = 0, false)
          or (p_bloco ->> 'tipo' = 'TITULOS'
              and jsonb_typeof(p_bloco -> 'pontos_por_nivel') = 'object'
              and exists (select 1 from jsonb_object_keys(p_bloco -> 'pontos_por_nivel'))
              and coalesce(jsonb_array_length(case when jsonb_typeof(p_bloco #> array['pontos_por_nivel', p_nivel]) = 'array'
                                                   then p_bloco #> array['pontos_por_nivel', p_nivel] end), 0) = 0)),
         false);
$$;

--
-- Name: FUNCTION "FC_BLOCO_NAO_PONTUA_NO_NIVEL"(p_bloco jsonb, p_nivel text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_BLOCO_NAO_PONTUA_NO_NIVEL"(p_bloco jsonb, p_nivel text) IS 'O bloco de títulos, cursos ou experiência não pontua no nível da vaga (teto 0 no nível ou, nos títulos por nível, sem tabela para ele) e não tem como mudar o resultado (sem efeito além de SO_REGISTRO, requisito, extra nem experiência mínima). Sem nível, pontua. Igual a blocoNaoPontuaNoNivel (ficha.js). 20261014210000.';

--
-- Name: FC_BLOCO_NO_NIVEL(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_BLOCO_NO_NIVEL"(p_bloco jsonb, p_nivel text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when jsonb_typeof(p_bloco #> array['por_nivel', coalesce(p_nivel, '')]) = 'object'
              then p_bloco || (p_bloco #> array['por_nivel', p_nivel]) else p_bloco end;
$$;

--
-- Name: FC_BLOCO_PELA_NOTA(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_BLOCO_PELA_NOTA"(p_bloco jsonb, p_lanc jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_bloco ->> 'tipo' = 'CURSOS'
     and not exists (
       select 1 from jsonb_array_elements(case when jsonb_typeof(p_lanc -> 'cursos') = 'array' then p_lanc -> 'cursos' else '[]'::jsonb end) i
        where jsonb_typeof(i) = 'object'
          and coalesce(i ->> 'do_arquivo', '') in ('', 'false')
          and coalesce(i -> 'aceito', 'true'::jsonb) <> 'false'::jsonb
          and private."FC_NUMERO_OU_ZERO"(i -> 'horas') > 0);
$$;

--
-- Name: FC_BLOCO_SE_APLICA(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_BLOCO_SE_APLICA"(p_bloco jsonb, p_lancamento jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
           when p_bloco -> 'nao_se_aplica' = 'true'::jsonb then false
           when private."FC_BLOCO_NAO_PONTUA_NO_NIVEL"(p_bloco, p_lancamento ->> 'nivel') then false
           when coalesce(p_bloco ->> 'condicao', case when p_bloco ->> 'tipo' = 'PONTUACAO' then 'INDIGENA' end) is null then true
           when coalesce(p_bloco ->> 'condicao', 'INDIGENA') = 'INDIGENA' then coalesce((p_lancamento ->> 'indigena')::boolean, false)
           else upper(btrim(split_part(p_bloco ->> 'condicao', '=', 2))) = any (private."FC_MODALIDADES_DO_LANCAMENTO"(p_lancamento))
         end;
$$;

--
-- Name: FUNCTION "FC_BLOCO_SE_APLICA"(p_bloco jsonb, p_lancamento jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_BLOCO_SE_APLICA"(p_bloco jsonb, p_lancamento jsonb) IS 'O bloco vale para o candidato (condição INDIGENA ou MODALIDADE=…; o critério étnico só para quem se declarou indígena; desde 20261015150000 o bloco de cota vale para quem optou pela cota, entre as várias do lançamento, FC_MODALIDADES_DO_LANCAMENTO; o bloco marcado nao_se_aplica pela diferença do cargo, FC_BLOCO_DO_CARGO, não vale; nem o que não pontua no nível da vaga, FC_BLOCO_NAO_PONTUA_NO_NIVEL, 20261014210000), como blocoSeAplica (ficha.js).';

--
-- Name: FC_BLOQUEIO_REINICIO_FICHAS(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_BLOQUEIO_REINICIO_FICHAS"(p_edital uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
           when private."FC_INSCRICOES_CONGELADAS"(p_edital)
             then 'As inscrições deste edital estão congeladas. Libere o congelamento na Pré-classificação antes de reiniciar as fichas.'
           when exists (select 1 from private."FC_EDITAIS_ENCERRADOS"() e where e."CO_MONITORAMENTO" = p_edital)
             then 'Este edital está encerrado (todas as fichas do lote concluídas). O reinício não é permitido.'
         end;
$$;

--
-- Name: FUNCTION "FC_BLOQUEIO_REINICIO_FICHAS"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_BLOQUEIO_REINICIO_FICHAS"(p_edital uuid) IS 'Por que o reinício das fichas do edital é recusado mesmo com dois administradores (20261022210000): inscrições congeladas (FC_INSCRICOES_CONGELADAS) ou edital encerrado (FC_EDITAIS_ENCERRADOS). Null quando pode.';

--
-- Name: FC_CACHE_DESATUALIZADO(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CACHE_DESATUALIZADO"(p_tipo text, p_area text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from private."TL_ALTERACAO_CACHE" t
     where t."TP_CACHE" = p_tipo and t."CO_AREA" = p_area
  );
$$;

--
-- Name: FUNCTION "FC_CACHE_DESATUALIZADO"(p_tipo text, p_area text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CACHE_DESATUALIZADO"(p_tipo text, p_area text) IS 'Verdadeiro quando há marca (TL_ALTERACAO_CACHE) para o cache p_tipo da área p_area: alguma tabela de origem mudou depois da última montagem.';

--
-- Name: FC_CALCULADO_DO_BLOCO(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CALCULADO_DO_BLOCO"(p_bloco jsonb, p_lanc jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_nivel text := p_lanc ->> 'nivel';
  v_lancado jsonb := p_lanc #> array['blocos', coalesce(p_bloco ->> 'codigo', '')];
  v_extras numeric;
  v_valores numeric[];
  v_total numeric;
  v_b jsonb;
begin
  if p_bloco ->> 'tipo' = 'VINCULOS' then
    return (private."FC_EXPERIENCIA_DA_FICHA"(p_bloco, p_lanc) ->> 'pontos')::numeric;
  end if;
  v_b := case when p_bloco ->> 'tipo' = 'CURSOS' then private."FC_BLOCO_NO_NIVEL"(p_bloco, v_nivel) else p_bloco end;
  -- As linhas extras do cargo marcadas (pontosDosExtras, regra-por-cargo.ts).
  select coalesce(sum(private."FC_NUMERO_OU_ZERO"(e -> 'pontos')), 0) into v_extras
    from jsonb_array_elements(case when jsonb_typeof(v_b -> 'extras') = 'array' then v_b -> 'extras' else '[]'::jsonb end) e
   where jsonb_typeof(e) = 'object' and v_lancado #> array['extras', coalesce(e ->> 'codigo', '')] = 'true'::jsonb;
  if p_bloco ->> 'tipo' = 'TITULOS' then
    select array_agg(coalesce((
             select private."FC_NUMERO_OU_ZERO"(x -> 'pontos')
               from jsonb_array_elements(case when jsonb_typeof(p_bloco #> array['pontos_por_nivel', coalesce(v_nivel, '')]) = 'array'
                                              then p_bloco #> array['pontos_por_nivel', v_nivel] else '[]'::jsonb end) with ordinality y(x, k)
              where x ->> 'titulo' = t ->> 'titulo'
              order by k limit 1), 0) order by n)
      into v_valores
      from jsonb_array_elements(case when jsonb_typeof(p_lanc -> 'titulos') = 'array' then p_lanc -> 'titulos' else '[]'::jsonb end)
           with ordinality z(t, n)
     where jsonb_typeof(t) = 'object' and coalesce(t -> 'aceito', 'true'::jsonb) <> 'false'::jsonb;
    if coalesce(cardinality(v_valores), 0) = 0 and v_extras = 0 then
      return 0;
    end if;
    v_total := case when coalesce(cardinality(v_valores), 0) = 0 then 0
                    when p_bloco -> 'cumulativa' = 'true'::jsonb then (select sum(v) from unnest(v_valores) v)
                    else (select max(v) from unnest(v_valores) v) end + v_extras;
  elsif p_bloco ->> 'tipo' = 'CURSOS' then
    select coalesce(sum(coalesce((
             select private."FC_NUMERO_OU_ZERO"(f -> 'pontos')
               from jsonb_array_elements(case when jsonb_typeof(v_b -> 'faixas') = 'array' then v_b -> 'faixas' else '[]'::jsonb end)
                    with ordinality y(f, k)
              where private."FC_NUMERO_OU_ZERO"(c -> 'horas') >= private."FC_NUMERO_OU_ZERO"(f -> 'min_horas')
                and (jsonb_typeof(f -> 'max_horas') is distinct from 'number'
                     or private."FC_NUMERO_OU_ZERO"(c -> 'horas') <= (f ->> 'max_horas')::numeric)
              order by k limit 1), 0)), 0) + v_extras
      into v_total
      from jsonb_array_elements(case when jsonb_typeof(p_lanc -> 'cursos') = 'array' then p_lanc -> 'cursos' else '[]'::jsonb end) c
     where jsonb_typeof(c) = 'object' and coalesce(c -> 'aceito', 'true'::jsonb) <> 'false'::jsonb;
    v_total := round(v_total, 4);
  else
    return null;
  end if;
  if jsonb_typeof(v_b -> 'teto') = 'number' then
    v_total := least(v_total, (v_b ->> 'teto')::numeric);
  end if;
  return round(v_total, 4);
end;
$$;

--
-- Name: FC_CALCULAR_ENTREVISTA(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CALCULAR_ENTREVISTA"(p_entrevista uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_e public."TB_ENTREVISTA";
  v_r public."TB_ROTEIRO_ENTREVISTA";
  v_avaliadores integer;
  v_total numeric := 0;
  v_bruto numeric := 0;
  v_soma numeric;
  v_falta boolean := false;
  v_reprova boolean := false;
  v_qt_aspectos integer;
  c record;
  v_media numeric;
  v_nota numeric;
  v_minimo numeric;
begin
  select * into v_e from public."TB_ENTREVISTA" where "CO_ENTREVISTA" = p_entrevista for update;
  if v_e."CO_ROTEIRO" is null then return; end if;
  select * into v_r from public."TB_ROTEIRO_ENTREVISTA" where "CO_ROTEIRO" = v_e."CO_ROTEIRO";
  select count(*) into v_qt_aspectos from public."TB_ROTEIRO_ASPECTO" s where s."CO_ROTEIRO" = v_r."CO_ROTEIRO";

  -- A média é de quem lançou e avalia a competência; com aspectos, de quem lançou todos os aspectos.
  for c in
    select k.*, row_number() over (order by k."NU_ORDEM") ord
      from public."TB_ROTEIRO_COMPETENCIA" k where k."CO_ROTEIRO" = v_r."CO_ROTEIRO" order by k."NU_ORDEM"
  loop
    if v_qt_aspectos > 0 then
      -- Nota do avaliador = média dos aspectos, sem arredondar; competência = média dos avaliadores.
      select avg(m.media), count(*) into v_media, v_avaliadores
        from (select avg(x."VL_NOTA") media
                from public."TB_ENTREVISTA_AVALIACAO_ASPECTO" x
                join public."TB_ROTEIRO_ASPECTO" s on s."CO_ASPECTO" = x."CO_ASPECTO" and s."CO_ROTEIRO" = v_r."CO_ROTEIRO"
               where x."CO_ENTREVISTA" = p_entrevista and x."CO_COMPETENCIA" = c."CO_COMPETENCIA"
                 and private."FC_AVALIADOR_AVALIA"(x."CO_AVALIADOR", c."CO_COMPETENCIA")
               group by x."CO_AVALIADOR"
              having count(*) = v_qt_aspectos) m;
    else
      select avg(a."VL_NOTA"), count(*) into v_media, v_avaliadores
        from public."TB_ENTREVISTA_AVALIACAO" a
       where a."CO_ENTREVISTA" = p_entrevista and a."CO_COMPETENCIA" = c."CO_COMPETENCIA"
         and private."FC_AVALIADOR_AVALIA"(a."CO_AVALIADOR", c."CO_COMPETENCIA");
    end if;
    if v_avaliadores = 0 then
      v_falta := true;
      update public."TB_ENTREVISTA_NOTA" set "VL_NOTA" = null
       where "CO_ENTREVISTA" = p_entrevista and "NU_ORDEM" = c.ord;
      continue;
    end if;
    v_nota := round(v_media * c."VL_PESO", 2);
    v_total := v_total + v_nota;
    v_bruto := v_bruto + v_media * c."VL_PESO";
    insert into public."TB_ENTREVISTA_NOTA" ("CO_ENTREVISTA", "NU_ORDEM", "DS_CRITERIO", "VL_NOTA")
    values (p_entrevista, c.ord, left(c."NO_COMPETENCIA", 600), v_nota)
    on conflict ("CO_ENTREVISTA", "NU_ORDEM") do update set "DS_CRITERIO" = excluded."DS_CRITERIO", "VL_NOTA" = excluded."VL_NOTA";
    if c."VL_MINIMO" is not null then
      v_minimo := case when c."TP_MINIMO" = 'PERCENTUAL'
                       then c."VL_NOTA_MAXIMA" * c."VL_PESO" * c."VL_MINIMO" / 100.0 else c."VL_MINIMO" end;
      if v_nota < v_minimo then v_reprova := true; end if;
    end if;
    -- Notas eliminatórias são valores exatos (ex.: 0 e 1): só sem aspectos (com aspectos vale o mínimo).
    if v_qt_aspectos = 0 and exists (select 1 from jsonb_array_elements_text(v_r."DS_NOTAS_ELIMINATORIAS") x
                where round(v_media, 2) = x::numeric) then
      v_reprova := true;
    end if;
  end loop;

  -- Sem aspectos: soma das competências (2 casas). Com aspectos: soma sem arredondar, 2 casas no fim.
  v_soma := case when v_qt_aspectos > 0 then round(v_bruto, 2) else round(v_total, 2) end;

  update public."TB_ENTREVISTA" set
    "VL_NOTA_TOTAL" = case when "ST_COMPARECEU" = 'N' then 0 when v_falta and v_soma = 0 then null else v_soma end,
    "TP_PARECER" = case
      when "ST_COMPARECEU" = 'N' and v_r."ST_AUSENCIA_ELIMINA" = 'S' then 'INAPTO'
      when "ST_COMPARECEU" is distinct from 'S' or v_falta then 'SEM_PARECER'
      when v_reprova or (v_r."VL_NOTA_MINIMA_TOTAL" is not null and v_soma < v_r."VL_NOTA_MINIMA_TOTAL") then 'INAPTO'
      else 'APTO' end,
    "DT_ATUALIZACAO" = now()
   where "CO_ENTREVISTA" = p_entrevista;
end;
$$;

--
-- Name: FUNCTION "FC_CALCULAR_ENTREVISTA"(p_entrevista uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CALCULAR_ENTREVISTA"(p_entrevista uuid) IS 'Recalcula uma entrevista feita no sistema: média × peso por competência (TB_ENTREVISTA_NOTA), total e parecer pelas regras do roteiro. A média é a dos avaliadores que avaliam a competência (private."FC_AVALIADOR_AVALIA"). Com aspectos: nota do avaliador = média dos aspectos (só com todos lançados), total = soma sem arredondar (2 casas no fim) e eliminação só pelo mínimo da competência.';

--
-- Name: FC_CALCULO_PELO_PYTHON(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CALCULO_PELO_PYTHON"() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(*) = 2 from public."TB_CHAVE_AUTOMACAO" c
   where c."CO_CHAVE" in ('classificacao', 'classificacao_calculo') and c."ST_LIGADA" = 'S';
$$;

--
-- Name: FUNCTION "FC_CALCULO_PELO_PYTHON"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CALCULO_PELO_PYTHON"() IS 'As chaves "Classificação em Python" (classificacao) e "Gerar listas pelo Python" (classificacao_calculo) estão as duas ligadas (20261024110000)? Qualquer uma desligada ou sem a linha na tabela: não (o padrão é o cálculo da tela). Só o dono (as RPCs da Classificação).';

--
-- Name: FC_CARGO_DA_GRAFIA(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CARGO_DA_GRAFIA"(p_texto text, p_area text DEFAULT 'saude-indigena'::text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with g as (select private."FC_NORMALIZAR_GRAFIA_CARGO"(p_texto) as grafia),
  achados as (
    select c."CO_CARGO"
      from public."TD_CARGO" c, g
     where c."ST_REGISTRO_ATIVO" = 'S'
       and (p_area is null or c."CO_AREA" = p_area)
       and private."FC_NORMALIZAR_GRAFIA_CARGO"(c."NO_CARGO") = g.grafia
    union
    select a."CO_CARGO"
      from public."TD_CARGO_APELIDO" a
      join public."TD_CARGO" c on c."CO_CARGO" = a."CO_CARGO" and c."ST_REGISTRO_ATIVO" = 'S', g
     where a."ST_REGISTRO_ATIVO" = 'S'
       and a."ST_CONFIRMADO" = 'S'
       and (p_area is null or a."CO_AREA" = p_area)
       and a."DS_GRAFIA_NORMALIZADA" = g.grafia
  )
  select case when count(*) = 1 then min("CO_CARGO") end from achados;
$$;

--
-- Name: FUNCTION "FC_CARGO_DA_GRAFIA"(p_texto text, p_area text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CARGO_DA_GRAFIA"(p_texto text, p_area text) IS 'Código do cargo (TD_CARGO.CO_CARGO) de uma grafia de texto livre, pelo nome oficial ou por apelido confirmado da área (padrão saude-indigena; nula = qualquer área). Nulo se não casar ou se casar com mais de um cargo. 20261104150000.';

--
-- Name: FC_CARGO_SOLICITACAO_ACESSO(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CARGO_SOLICITACAO_ACESSO"(p_area text, p_codigo text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select c.rotulo
    from (values
      ('AVALIADOR', 'Avaliador(a) da análise curricular', '{projetos,saude-indigena,sede}'::text[]),
      ('GESTOR', 'Gestor(a) de processo seletivo', '{projetos,saude-indigena,sede}'::text[]),
      ('CONTRATACAO', 'Contratação e admissão', '{projetos,saude-indigena,sede}'::text[]),
      ('COORDENACAO_DSEI', 'Coordenação de DSEI ou CASAI', '{saude-indigena}'::text[]),
      ('COORDENACAO_PROJETO', 'Coordenação de projeto', '{projetos}'::text[]),
      ('COORDENACAO_SEDE', 'Coordenação ou diretoria', '{sede}'::text[]),
      ('JURIDICO', 'Jurídico', '{sede}'::text[]),
      ('APOIO', 'Apoio administrativo', '{projetos,saude-indigena,sede}'::text[]),
      ('CONSULTA', 'Consulta e acompanhamento', '{projetos,saude-indigena,sede}'::text[]),
      ('OUTRO', 'Outro', '{projetos,saude-indigena,sede}'::text[])
    ) as c(codigo, rotulo, areas)
   where c.codigo = p_codigo and (p_area is null or p_area = any (c.areas));
$$;

--
-- Name: FUNCTION "FC_CARGO_SOLICITACAO_ACESSO"(p_area text, p_codigo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CARGO_SOLICITACAO_ACESSO"(p_area text, p_codigo text) IS 'Rótulo do cargo/função do pedido de acesso, se o código existe e vale para a área (área nula: só o código). A mesma lista de CARGOS_DA_SOLICITACAO (src/lib/solicitacao-de-acesso.ts).';

--
-- Name: FC_CHAVE_ALVO_COORDENADA(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CHAVE_ALVO_COORDENADA"(p_alvo jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'fonte', p_alvo ->> 'fonte', 'tipo', p_alvo ->> 'tipo', 'dsei', p_alvo ->> 'dsei',
    'indice', p_alvo ->> 'indice', 'codigo', p_alvo ->> 'codigo', 'nome', p_alvo ->> 'nome');
$$;

--
-- Name: FUNCTION "FC_CHAVE_ALVO_COORDENADA"(p_alvo jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CHAVE_ALVO_COORDENADA"(p_alvo jsonb) IS 'Identidade normalizada de um ponto do mapa (fonte, tipo, dsei, indice, codigo, nome) para achar o histórico dele.';

--
-- Name: FC_CHAVE_DA_TAREFA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CHAVE_DA_TAREFA"(p_tarefa text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select t."CO_CHAVE"
    from public."TB_TAREFA_AGENDADA" t
   where t."NO_TAREFA" = p_tarefa
      or (t."ST_PREFIXO" = 'S' and starts_with(p_tarefa, t."NO_TAREFA"))
   order by (t."NO_TAREFA" = p_tarefa) desc, length(t."NO_TAREFA") desc
   limit 1;
$$;

--
-- Name: FUNCTION "FC_CHAVE_DA_TAREFA"(p_tarefa text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CHAVE_DA_TAREFA"(p_tarefa text) IS 'Chave da automação (TB_CHAVE_AUTOMACAO) que liga e desliga a tarefa do pg_cron, pelo catálogo TB_TAREFA_AGENDADA (20261109180000; antes, lista fixa desde 20261022190000): o nome exato ganha do prefixo. Nulo = sempre ligada (ex.: agsus_robo_conferir_disparos) ou fora do catálogo.';

--
-- Name: FC_CHAVE_DO_WORKFLOW(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CHAVE_DO_WORKFLOW"(p_workflow text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select w."CO_CHAVE" from public."TB_ROBO_WORKFLOW" w where w."NO_WORKFLOW" = p_workflow;
$$;

--
-- Name: FUNCTION "FC_CHAVE_DO_WORKFLOW"(p_workflow text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CHAVE_DO_WORKFLOW"(p_workflow text) IS 'Chave da automação que manda nos pedidos da agenda (origem AGENDA) de um workflow, pelo catálogo TB_ROBO_WORKFLOW (20261109180000; antes, lista fixa desde 20261022190000). Nulo = sem chave ou fora do catálogo.';

--
-- Name: FC_CODIGO_DA_LEITURA(text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CODIGO_DA_LEITURA"(p_funcoes text[]) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_vistas_f text[] := '{}';
  v_vistas_r oid[] := '{}';
  v_fila_f text[] := coalesce(p_funcoes, '{}');
  v_fila_r oid[] := '{}';
  v_texto text;
  v_tudo text := '';
begin
  -- O mesmo fecho de private."FC_FONTES_PELO_CODIGO" (20261029170000), devolvendo o
  -- código (funções e views, sem comentários) em vez das tabelas.
  while cardinality(v_fila_f) > 0 or cardinality(v_fila_r) > 0 loop
    v_vistas_f := v_vistas_f || v_fila_f;
    v_vistas_r := v_vistas_r || v_fila_r;
    select coalesce(string_agg(p.prosrc, E'\n'), '') into v_texto
      from pg_catalog.pg_proc p
      join pg_catalog.pg_namespace n on n.oid = p.pronamespace
     where n.nspname in ('public', 'private') and p.proname = any (v_fila_f);
    v_texto := v_texto || E'\n' || coalesce((
      select string_agg(pg_catalog.pg_get_viewdef(c.oid), E'\n')
        from pg_catalog.pg_class c
       where c.oid = any (v_fila_r) and c.relkind in ('v', 'm')), '');
    v_texto := regexp_replace(regexp_replace(v_texto, '/\*.*?\*/', ' ', 'g'), '--[^\n]*', ' ', 'g');
    v_tudo := v_tudo || E'\n' || v_texto;
    select coalesce(array_agg(distinct p.proname::text), '{}') into v_fila_f
      from (select (regexp_matches(v_texto, '([A-Za-z_][A-Za-z0-9_]*)"?\s*\(', 'g'))[1] as t) x
      join pg_catalog.pg_proc p on p.proname = x.t
      join pg_catalog.pg_namespace n on n.oid = p.pronamespace and n.nspname in ('public', 'private')
     where not (p.proname::text = any (v_vistas_f));
    select coalesce(array_agg(distinct c.oid), '{}') into v_fila_r
      from (select distinct (regexp_matches(v_texto, '[A-Za-z_][A-Za-z0-9_]*', 'g'))[1] as t) x
      join pg_catalog.pg_class c on c.relname = x.t and c.relkind in ('r', 'p', 'v', 'm')
      join pg_catalog.pg_namespace n on n.oid = c.relnamespace and n.nspname in ('public', 'private')
     where not (c.oid = any (v_vistas_r));
  end loop;
  return v_tudo;
end;
$$;

--
-- Name: FUNCTION "FC_CODIGO_DA_LEITURA"(p_funcoes text[]); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CODIGO_DA_LEITURA"(p_funcoes text[]) IS 'O código (funções e views de public/private, sem comentários) do fecho de p_funcoes — o mesmo fecho de FC_FONTES_PELO_CODIGO (20261103150000). Usado para conferir que nenhuma leitura cita uma coluna de TD_COLUNA_SEM_MARCA.';

--
-- Name: FC_CODIGO_DE_COORDENACAO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CODIGO_DE_COORDENACAO"(p_nome text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_base text := left(btrim(regexp_replace(
    translate(lower(coalesce(p_nome, '')), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc'),
    '[^a-z0-9]+', '-', 'g'), '-'), 60);
  v_codigo text;
  v_n integer := 1;
begin
  if v_base = '' then v_base := 'coordenacao'; end if;
  v_base := btrim(v_base, '-');
  v_codigo := v_base;
  while exists (select 1 from public."TB_COORDENACAO" c where c."CO_COORDENACAO" = v_codigo) loop
    v_n := v_n + 1;
    v_codigo := v_base || '-' || v_n;
  end loop;
  return v_codigo;
end;
$$;

--
-- Name: FUNCTION "FC_CODIGO_DE_COORDENACAO"(p_nome text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CODIGO_DE_COORDENACAO"(p_nome text) IS 'Código livre para uma coordenação nova a partir do nome: minúsculas sem acento, hífen no lugar do resto, até 60 caracteres, com sufixo numérico se já existir em TB_COORDENACAO.';

--
-- Name: FC_COLUNAS_JSON(jsonb, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_COLUNAS_JSON"(p_linhas jsonb, p_dicionario text[] DEFAULT '{}'::text[]) RETURNS json
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  with l as (
    select t.e, t.o
      from jsonb_array_elements(case when jsonb_typeof(p_linhas) = 'array' then p_linhas else '[]'::jsonb end)
           with ordinality t(e, o)
     where jsonb_typeof(t.e) = 'object'
  ),
  c as (
    select coalesce(array_agg(x.k order by x.k), '{}'::text[]) as colunas
      from (select distinct jsonb_object_keys(l.e) as k from l) x
  ),
  d as (
    -- Os valores distintos de cada coluna do dicionário (o nulo também é um valor).
    select x.k, array_agg(x.v order by x.v) as valores
      from (select distinct u.k, coalesce(l.e -> u.k, 'null'::jsonb) as v
              from l, c, unnest(c.colunas) u(k)
             where u.k = any (coalesce(p_dicionario, '{}'::text[]))) x
     group by x.k
  )
  select json_build_object(
           'colunas', array_to_json(c.colunas),
           'dicionarios', coalesce((select json_object_agg(d.k, array_to_json(d.valores)) from d), '{}'::json),
           'linhas', ('[' || coalesce((
             select string_agg(
                      '[' || coalesce((
                        select string_agg(
                                 case when d.k is null then coalesce(l.e -> u.k, 'null'::jsonb)::text
                                      else (array_position(d.valores, coalesce(l.e -> u.k, 'null'::jsonb)) - 1)::text
                                 end, ',' order by u.n)
                          from unnest(c.colunas) with ordinality u(k, n)
                          left join d on d.k = u.k), '') || ']',
                      ',' order by l.o)
               from l), '') || ']')::json)
    from c;
$$;

--
-- Name: FUNCTION "FC_COLUNAS_JSON"(p_linhas jsonb, p_dicionario text[]); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_COLUNAS_JSON"(p_linhas jsonb, p_dicionario text[]) IS 'Uma lista de objetos em colunas (20261014230000): { colunas: [chaves em ordem], dicionarios: { coluna: [valores distintos] }, linhas: [[valor ou índice no dicionário, na ordem das colunas]] }. A tela refaz os objetos com linhasDoPacote (src/lib/avaliacao-documental/leitura-por-versao.ts).';

--
-- Name: FC_COMPACTAR_VERSAO_FONTE(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_COMPACTAR_VERSAO_FONTE"(p_fonte text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fonte text;
  v_juntadas integer;
  v_total integer := 0;
begin
  for v_fonte in
    select distinct v."NO_FONTE" from private."TL_VERSAO_FONTE" v
     where p_fonte is null or v."NO_FONTE" = p_fonte
     order by 1
  loop
    -- Uma compactação por fonte de cada vez (até o fim da transação): as linhas apagadas
    -- e a linha com a soma aparecem juntas, e a soma não muda. Linha de transação ainda
    -- aberta não é vista pelo delete e fica para a próxima.
    continue when not pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtext('agsus_versao_fonte:' || v_fonte));
    continue when (select count(*) from private."TL_VERSAO_FONTE" v where v."NO_FONTE" = v_fonte) < 2;
    with apagadas as (
      delete from private."TL_VERSAO_FONTE" v where v."NO_FONTE" = v_fonte returning v."QT_ALTERACAO"
    )
    insert into private."TL_VERSAO_FONTE" ("NO_FONTE", "QT_ALTERACAO")
    select v_fonte, sum(a."QT_ALTERACAO") from apagadas a having count(*) > 0;
    get diagnostics v_juntadas = row_count;
    v_total := v_total + v_juntadas;
  end loop;
  return v_total;
end;
$$;

--
-- Name: FUNCTION "FC_COMPACTAR_VERSAO_FONTE"(p_fonte text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_COMPACTAR_VERSAO_FONTE"(p_fonte text) IS 'Junta as linhas de TL_VERSAO_FONTE de cada fonte (ou só de p_fonte) numa linha com a mesma soma (20261029170000). Devolve quantas fontes juntou.';

--
-- Name: FC_CONFERENCIA_RECURSO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CONFERENCIA_RECURSO"(p_modulo text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_modulo
    when 'analises' then 'analises'
    when 'entrevistas' then 'entrevistas'
    when 'classificacao' then 'classificacao'
    when 'aprovados' then 'aprovados'
  end;
$$;

--
-- Name: FUNCTION "FC_CONFERENCIA_RECURSO"(p_modulo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CONFERENCIA_RECURSO"(p_modulo text) IS 'Módulo de permissão (pode_recurso) de cada módulo de aviso; cargas não tem: só o administrador global.';

--
-- Name: FC_CONFERIR_DISPAROS_ROBO(bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CONFERIR_DISPAROS_ROBO"(p_disparo bigint DEFAULT NULL::bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fechados integer := 0;
  v_sem_resposta integer := 0;
begin
  update public."TL_DISPARO_ROBO" d
     set "TP_SITUACAO" = case
           when r.status_code between 200 and 299 and not coalesce(r.timed_out, false) then 'ACEITO'
           else 'FALHOU' end,
         "NU_STATUS_HTTP" = case when r.status_code between 100 and 599 then r.status_code end,
         "DT_RESPOSTA" = coalesce(r.created, now()),
         "DS_MENSAGEM" = case
           when r.status_code between 200 and 299 and not coalesce(r.timed_out, false) then null
           when coalesce(r.timed_out, false) then 'Tempo esgotado esperando o GitHub.'
           when r.error_msg is not null then left('Erro de rede: ' || r.error_msg, 300)
           else left(coalesce(
             'GitHub ' || r.status_code || ': '
               || substring(r.content from '"message"\s*:\s*"([^"]{1,200})"'),
             'GitHub ' || coalesce(r.status_code::text, '?')), 300) end
    from net._http_response r
   where r.id = d."CO_PEDIDO_HTTP"
     and d."TP_SITUACAO" = 'PEDIDO'
     and (p_disparo is null or d."CO_DISPARO" = p_disparo);
  get diagnostics v_fechados = row_count;

  -- A resposta não veio (ou já saiu da tabela do pg_net): falha, para a tela avisar.
  update public."TL_DISPARO_ROBO" d
     set "TP_SITUACAO" = 'FALHOU',
         "DT_RESPOSTA" = now(),
         "DS_MENSAGEM" = 'Sem resposta do GitHub em 1 h.'
   where d."TP_SITUACAO" = 'PEDIDO'
     and d."DT_DISPARO" < now() - interval '1 hour'
     and (p_disparo is null or d."CO_DISPARO" = p_disparo);
  get diagnostics v_sem_resposta = row_count;

  if p_disparo is null then
    delete from public."TL_DISPARO_ROBO" d
     where d."DT_DISPARO" < now() - interval '30 days';
  end if;

  return v_fechados + v_sem_resposta;
end;
$$;

--
-- Name: FUNCTION "FC_CONFERIR_DISPAROS_ROBO"(p_disparo bigint); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CONFERIR_DISPAROS_ROBO"(p_disparo bigint) IS 'Agenda dos robôs (20261008140000): fecha os pedidos de TL_DISPARO_ROBO (todos, ou só p_disparo) pela resposta em net._http_response (2xx = ACEITO — o GitHub responde 204; outro código ou tempo esgotado = FALHOU, com a mensagem curta do GitHub), dá como FALHOU o pedido sem resposta há mais de 1 h e, na rodada geral, apaga as linhas com mais de 30 dias. Devolve quantos fechou. Só o dono (pg_cron a cada 5 min e situacao_do_disparo_robo).';

--
-- Name: FC_CONFIRMACAO_DO_EDITAL(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CONFIRMACAO_DO_EDITAL"(p_edital uuid, p_confirmacao text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select case
             when private."FC_NUMERO_EDITAL"(m.edital) is not null
               then private."FC_NUMERO_EDITAL"(p_confirmacao) = private."FC_NUMERO_EDITAL"(m.edital)
             else lower(btrim(coalesce(p_confirmacao, ''))) = lower(btrim(m.edital))
           end
      from public."TB_MONITORAMENTO_INDIGENA" m
     where m.id = p_edital), false);
$$;

--
-- Name: FUNCTION "FC_CONFIRMACAO_DO_EDITAL"(p_edital uuid, p_confirmacao text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CONFIRMACAO_DO_EDITAL"(p_edital uuid, p_confirmacao text) IS 'O texto digitado confere com o número do edital (FC_NUMERO_EDITAL dos dois; edital sem número: o nome, sem diferença de maiúsculas)? (20261022210000)';

--
-- Name: FC_CONVOCADOS_DA_LISTA(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CONVOCADOS_DA_LISTA"(p_lista uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select distinct (x.linha ->> 'analise_id')::uuid
    from public."TB_LISTA_CLASSIFICACAO" l
   cross join lateral jsonb_array_elements(
           case when jsonb_typeof(l."DS_RESULTADO" -> 'vagas') = 'array' then l."DS_RESULTADO" -> 'vagas' else '[]'::jsonb end) v(vaga)
   cross join lateral (
           select g.linha
             from jsonb_array_elements(
                    case when jsonb_typeof(v.vaga -> 'geral') = 'array' then v.vaga -> 'geral' else '[]'::jsonb end) g(linha)
           union all
           select m.linha
             from jsonb_each(
                    case when jsonb_typeof(v.vaga -> 'listas') = 'object' then v.vaga -> 'listas' else '{}'::jsonb end) e(codigo, linhas)
            cross join lateral jsonb_array_elements(
                    case when jsonb_typeof(e.linhas) = 'array' then e.linhas else '[]'::jsonb end) m(linha)) x
   where l."CO_LISTA_CLASSIFICACAO" = p_lista
     and coalesce(x.linha ->> 'analise_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
$_$;

--
-- Name: FUNCTION "FC_CONVOCADOS_DA_LISTA"(p_lista uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CONVOCADOS_DA_LISTA"(p_lista uuid) IS 'As análises (TB_ANALISE_CURRICULAR.id) de uma lista gerada: a classificação geral e as listas por modalidade de cada vaga do retrato (DS_RESULTADO); os eliminados não entram. Sem checagem de permissão: só as RPCs chamam.';

--
-- Name: FC_CONVOCAR_E_AGENDAR_TREINAMENTO(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CONVOCAR_E_AGENDAR_TREINAMENTO"(p_edital uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_uid uuid := coalesce((select auth.uid()), '00000000-0000-0000-0000-000000000000'::uuid);
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_roteiro uuid;
  v_lista uuid;
  v_regra uuid;
  v_dias date[];
  v_config jsonb;
  v_qt integer := 0;
begin
  if not private."FC_EDITAL_EH_TREINAMENTO"(p_edital) then
    raise exception 'Só o edital de treinamento é convocado e agendado por aqui' using errcode = '42501';
  end if;
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  select e."CO_ROTEIRO" into v_roteiro from public."TB_ENTREVISTA_EDITAL" e where e."CO_MONITORAMENTO" = p_edital;
  v_lista := private."FC_LISTA_CONVOCACAO_VIGENTE"(p_edital);
  if v_roteiro is null or v_lista is null then
    return 0;
  end if;

  -- Os convocados da lista viram entrevistas do sistema (como public.convocar_para_entrevista),
  -- na banca 1. Entrevistas já convocadas (talvez com notas do treino) ficam.
  if not exists (select 1 from public."TB_ENTREVISTA" e
                  where e."CO_MONITORAMENTO" = p_edital and e."TP_ORIGEM" = 'sistema') then
    insert into public."TB_ENTREVISTA" ("CO_AREA", "CO_MONITORAMENTO", "CO_ANALISE_CURRICULAR", "TP_LIGACAO_ANALISE",
      "NO_UNIDADE", "DS_EDITAL", "CO_VAGA", "NO_CANDIDATO", "CO_CANDIDATO", "DS_MODALIDADE", "NO_CARGO", "TP_PARECER",
      "TP_ORIGEM", "DS_CHAVE_ORIGEM", "CO_ROTEIRO", "ST_ATIVO", "NU_BANCA")
    select v_m."CO_AREA", p_edital, a.id, 'codigo', left(coalesce(v_m.unidade, ''), 200), left(v_m.edital, 120),
           left(a.codigo_vaga, 60), left(a.candidato, 200), left(a.id_origem, 60), left(a.modalidade_concorrencia, 300),
           left(a.nome_vaga, 400), 'SEM_PARECER', 'sistema', 'sistema|' || p_edital || '|' || a.id, v_roteiro, 'S', 1
      from private."FC_CONVOCADOS_DA_LISTA"(v_lista) c(analise)
      join public."TB_ANALISE_CURRICULAR" a on a.id = c.analise
     where a."CO_AREA" = v_m."CO_AREA" and a.ativo and private."FC_ANALISE_EH_TREINAMENTO"(a.origem_planilha)
       and private."FC_NUMERO_EDITAL"(a.edital) = private."FC_NUMERO_EDITAL"(v_m.edital)
    on conflict ("DS_CHAVE_ORIGEM") do nothing;
    get diagnostics v_qt = row_count;
    insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "DS_CAMPO", "DS_VALOR_NOVO", "CO_USUARIO")
    select e."CO_ENTREVISTA", 'convocacao', 'convocado pela lista ' || v_lista || ' (edital de treinamento)', (select auth.uid())
      from public."TB_ENTREVISTA" e
     where e."CO_MONITORAMENTO" = p_edital and e."TP_ORIGEM" = 'sistema';
  end if;

  -- A regra da agenda: hoje e os dias úteis seguintes, 30 minutos, uma banca.
  select array_agg(d order by d) into v_dias
    from (select v_hoje as d
          union all
          (select g::date from generate_series(v_hoje + 1, v_hoje + 14, interval '1 day') g
            where extract(isodow from g) < 6 order by g limit 4)) x;
  select r."CO_REGRA_AGENDA" into v_regra from public."TB_REGRA_AGENDA_ENTREVISTA" r where r."CO_MONITORAMENTO" = p_edital;
  if v_regra is null then
    v_config := jsonb_build_object(
      'schema', 1,
      'datas', jsonb_build_object('modo', 'LISTA', 'inicio', '', 'fim', '', 'so_dias_uteis', true,
                                  'dias', (select jsonb_agg(to_char(d, 'YYYY-MM-DD') order by d) from unnest(v_dias) d),
                                  'excluir', '[]'::jsonb),
      'periodos', jsonb_build_array(jsonb_build_object('inicio', '08:00', 'fim', '12:00'),
                                    jsonb_build_object('inicio', '14:00', 'fim', '18:00')),
      'duracao_min', 30, 'intervalo_min', 0, 'pausa', null, 'bancas', 1,
      'nomes_das_bancas', jsonb_build_array('Banca 1'), 'ordem', 'VAGA',
      'agrupar_por_cargo', true, 'reservar_primeiro_horario', false, 'fuso', 'America/Sao_Paulo');
    perform private."FC_VALIDAR_REGRA_AGENDA"(v_config);
    insert into public."TB_REGRA_AGENDA_ENTREVISTA" ("CO_MONITORAMENTO", "NU_VERSAO_VIGENTE", "CO_USUARIO_ATUALIZACAO")
    values (p_edital, 1, (select auth.uid()))
    returning "CO_REGRA_AGENDA" into v_regra;
    insert into public."TH_REGRA_AGENDA_ENTREVISTA" ("CO_REGRA_AGENDA", "NU_VERSAO", "DS_CONFIGURACAO", "DS_MOTIVO", "CO_USUARIO")
    values (v_regra, 1, v_config, 'Edital de treinamento: agenda de exemplo a partir de hoje', (select auth.uid()));
  end if;

  -- A agenda: 6 entrevistas hoje (09:00 às 12:00) e as demais, 8 por dia, nos dias úteis seguintes.
  if not exists (select 1 from public."TB_AGENDA_ENTREVISTA" g where g."CO_MONITORAMENTO" = p_edital) then
    insert into public."TB_AGENDA_ENTREVISTA" ("CO_MONITORAMENTO", "CO_ANALISE_CURRICULAR", "DT_ENTREVISTA", "HR_INICIO",
      "HR_FIM", "NU_BANCA", "TP_ORIGEM", "NU_VERSAO_REGRA", "CO_LISTA_CLASSIFICACAO", "CO_USUARIO_ATUALIZACAO")
    select p_edital, s.analise, s.dia, s.inicio, s.inicio + interval '30 minutes', 1, 'GERADA',
           (select r."NU_VERSAO_VIGENTE" from public."TB_REGRA_AGENDA_ENTREVISTA" r where r."CO_REGRA_AGENDA" = v_regra),
           v_lista, (select auth.uid())
      from (
        select o.analise,
               case when o.i < 6 then v_dias[1] else v_dias[least(2 + (o.i - 6) / 8, cardinality(v_dias))] end as dia,
               case when o.i < 6 then time '09:00' + o.i * interval '30 minutes'
                    else time '08:00' + ((o.i - 6) % 8) * interval '30 minutes' end as inicio
          from (select e."CO_ANALISE_CURRICULAR" as analise,
                       (row_number() over (order by e."CO_VAGA", e."NO_CANDIDATO", e."CO_ENTREVISTA") - 1)::integer as i
                  from public."TB_ENTREVISTA" e
                 where e."CO_MONITORAMENTO" = p_edital and e."TP_ORIGEM" = 'sistema' and e."ST_ATIVO" = 'S'
                   and e."CO_ANALISE_CURRICULAR" is not null) o
         where o.i < 6 + 8 * (cardinality(v_dias) - 1)
      ) s;
    get diagnostics v_qt = row_count;
    if v_qt > 0 then
      insert into public."TH_AGENDA_ENTREVISTA" ("CO_MONITORAMENTO", "TP_ACAO", "NU_VERSAO_REGRA", "CO_LISTA_CLASSIFICACAO",
        "QT_ITEM", "QT_ALTERACAO", "DS_ALTERACAO", "DS_MOTIVO", "CO_USUARIO")
      values (p_edital, 'GERAR', 1, v_lista, v_qt, v_qt, '[]'::jsonb,
              'Edital de treinamento: agenda de exemplo a partir de hoje', v_uid);
    end if;
  end if;
  return v_qt;
end;
$$;

--
-- Name: FUNCTION "FC_CONVOCAR_E_AGENDAR_TREINAMENTO"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CONVOCAR_E_AGENDAR_TREINAMENTO"(p_edital uuid) IS 'Edital de treinamento: os convocados da lista de convocação vigente viram entrevistas do sistema (banca 1) e a agenda é montada a partir de hoje (6 hoje, as demais 8 por dia nos dias úteis seguintes), com a regra da agenda (versão 1) e o registro no histórico. Não mexe no que já existe; recusa edital real (42501). Chamada só por private."FC_PREPARAR_EDITAL_TREINAMENTO".';

--
-- Name: FC_COORDENACAO_JSON(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_COORDENACAO_JSON"(p_coordenacao text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'codigo', c."CO_COORDENACAO", 'nome', c."NO_COORDENACAO", 'area', c."CO_AREA",
    'responsavel', c."TP_RESPONSAVEL", 'ativo', c."ST_ATIVO", 'revisao', c."NU_REVISAO",
    'unidades', coalesce((select jsonb_agg(u."NO_UNIDADE" order by u."NO_UNIDADE") from public."RL_COORDENACAO_UNIDADE" u
                           where u."CO_COORDENACAO" = c."CO_COORDENACAO"), '[]'::jsonb),
    'editais', coalesce((select jsonb_agg(e."CO_EDITAL"::text order by e."CO_EDITAL") from public."RL_COORDENACAO_EDITAL" e
                          where e."CO_COORDENACAO" = c."CO_COORDENACAO"), '[]'::jsonb),
    'usuarios', (select count(*) from public."TB_PERFIL_USUARIO" x where x."CO_COORDENACAO" = c."CO_COORDENACAO" and x.ativo))
  from public."TB_COORDENACAO" c where c."CO_COORDENACAO" = p_coordenacao;
$$;

--
-- Name: FUNCTION "FC_COORDENACAO_JSON"(p_coordenacao text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_COORDENACAO_JSON"(p_coordenacao text) IS 'Coordenação em JSON (código, nome, área, responsável, ativo, revisão, unidades e editais), como a tela de Acessos e o histórico TH_COORDENACAO a usam.';

--
-- Name: FC_COORDENACAO_USUARIO(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_COORDENACAO_USUARIO"() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when coalesce((select auth.role()) = 'service_role', false) or private.is_master() then null
    else (select p."CO_COORDENACAO" from private.current_profile() p where p.ativo)
  end;
$$;

--
-- Name: FUNCTION "FC_COORDENACAO_USUARIO"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_COORDENACAO_USUARIO"() IS 'Coordenação do usuário logado; null para admin, service_role ou quem não tem coordenação.';

--
-- Name: FC_COTAS_CONFIRMADAS(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_COTAS_CONFIRMADAS"(p_regra jsonb, p_lanc jsonb, p_cotas jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  with optadas as (
    select o.codigo, o.ordem
      from unnest(private."FC_MODALIDADES_DO_LANCAMENTO"(p_lanc)) with ordinality o(codigo, ordem)
  ),
  negadas as (
    select upper(btrim(split_part(b ->> 'condicao', '=', 2))) as codigo
      from jsonb_array_elements(case when jsonb_typeof(p_regra -> 'blocos') = 'array' then p_regra -> 'blocos' else '[]'::jsonb end) b
     where jsonb_typeof(b) = 'object'
       and upper(btrim(split_part(b ->> 'condicao', '=', 1))) = 'MODALIDADE'
       and coalesce(p_lanc #>> array['blocos', b ->> 'codigo', 'situacao'], '') in ('NAO_CONFORME', 'NAO_ENVIADO')
  )
  select coalesce(array_agg(o.codigo order by
           case when p_cotas ->> 'acumulo' = 'PCD_MAIS_UMA' and o.codigo = 'PCD' then 0 else 1 end,
           case when jsonb_typeof(p_cotas #> array['percentuais', o.codigo]) = 'number'
                then (p_cotas #>> array['percentuais', o.codigo])::numeric else 0 end desc,
           o.ordem), '{}'::text[])
    from optadas o
   where o.codigo not in (select n.codigo from negadas n);
$$;

--
-- Name: FUNCTION "FC_COTAS_CONFIRMADAS"(p_regra jsonb, p_lanc jsonb, p_cotas jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_COTAS_CONFIRMADAS"(p_regra jsonb, p_lanc jsonb, p_cotas jsonb) IS 'As cotas optadas que a ficha confirmou, a final primeiro: sai a cota com bloco (condição MODALIDADE=<cota>) Não conforme ou Não enviado no lançamento. Ordem pelo acúmulo da regra de classificação (p_cotas {acumulo, percentuais}, FC_DOCUMENTAL_DO_EDITAL): PCD_MAIS_UMA → PcD primeiro; depois o maior percentual (114/2026, 5.8.5); empate na ordem optada. {} = ampla. Como cotasConfirmadas (pontuacao.js) e cotas_confirmadas (pontuacao.py). Desde 20261015150000.';

--
-- Name: FC_CRITERIO_ENTREVISTA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_CRITERIO_ENTREVISTA"(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $_$
  -- Espaços simples e parênteses equilibrados: "(... em saúde)" e "(... em
  -- saúde))" são o mesmo critério (planilhas copiadas com um ")" a mais ou a menos).
  with t as (
    select regexp_replace(btrim(regexp_replace(coalesce(p_texto, ''), '[[:space:]]+', ' ', 'g')), '[)[:space:]]+$', '') as base
  )
  select t.base || repeat(')', greatest(
           length(t.base) - length(replace(t.base, '(', ''))
           - (length(t.base) - length(replace(t.base, ')', ''))), 0))
    from t;
$_$;

--
-- Name: FUNCTION "FC_CRITERIO_ENTREVISTA"(p_texto text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_CRITERIO_ENTREVISTA"(p_texto text) IS 'Texto canônico do critério da entrevista: espaços simples e parênteses de fechamento equilibrados.';

--
-- Name: FC_DADOS_CLASSIFICACAO_EDITAL(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_DADOS_CLASSIFICACAO_EDITAL"(p_edital uuid, p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := p_area;
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_numero text;
begin
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital;
  v_numero := private."FC_NUMERO_EDITAL"(v_m.edital);
  return json_build_object(
    'schema_version', 1,
    'gerado_em', now(),
    'edital', json_build_object('id', v_m.id, 'edital', v_m.edital, 'unidade', v_m.unidade, 'area', v_area, 'numero', v_numero,
                               'treinamento', private."FC_EH_TREINAMENTO"(v_m."ST_TREINAMENTO")),
    'pode_editar', private.pode_recurso('classificacao', 2),
    'regra', private."FC_REGRA_CLASSIFICACAO_JSON"(p_edital),
    'catalogo', (
      select json_agg(json_build_object('codigo', k."CO_CRITERIO", 'nome', k."NO_CRITERIO", 'tipo', k."TP_VALOR",
               'direcao', k."TP_DIRECAO_PADRAO", 'ativo', k."ST_ATIVO" = 'S') order by k."NU_ORDEM")
        from public."TB_CRITERIO_CLASSIFICACAO" k),
    'cronograma', coalesce((
      select json_agg(json_build_object('ordem', c.ordem, 'atividade', c.atividade, 'inicio', c.data_inicio, 'fim', c.data_fim)
             order by c.ordem)
        from public."TB_CRONOGRAMA_MONIT_INDIG" c where c.monitoramento_id = p_edital), '[]'::json),
    'quadro', coalesce((
      select json_agg(json_build_object('id', q."CO_QUADRO_VAGA", 'ordem', q."NU_ORDEM", 'cargo', q."NO_CARGO",
               'lotacao', q."NO_LOTACAO", 'modalidades', q."DS_MODALIDADE_VAGA", 'vagas_imediatas', q."QT_VAGA_IMEDIATA",
               'cadastro_reserva', q."ST_CADASTRO_RESERVA" = 'S') order by q."NU_ORDEM")
        from public."TB_QUADRO_VAGA_EDITAL" q
       where q."CO_MONITORAMENTO" = p_edital and q."ST_REGISTRO_ATIVO" = 'S'), '[]'::json),
    'candidatos', coalesce((
      with a as (
        select a.* from public."TB_ANALISE_CURRICULAR" a
         where a."CO_AREA" = v_area and a.ativo and private."FC_NUMERO_EDITAL"(a.edital) = v_numero
      ),
      vq as (
        select n.nome_vaga, private."FC_QUADRO_DA_VAGA"(p_edital, n.nome_vaga) as quadro
          from (select distinct a.nome_vaga from a) n
      )
      select json_agg(json_build_object(
               'analise_id', a.id, 'codigo', a.id_origem, 'nome', a.candidato, 'vaga', a.codigo_vaga,
               'cargo', a.nome_vaga, 'categoria', a.categoria, 'modalidade', a.modalidade_concorrencia, 'pcd', a.pcd,
               'data_nascimento', a.data_nascimento, 'nota_documental', a.nota_final_ajustada, 'nota_art', a.nota_empregare,
               'pontuacao_formacao', a.pontuacao_escolaridade, 'pontuacao_cursos', a.pontuacao_cursos_aperfeicoamento,
               'pontuacao_experiencia', a.pontuacao_experiencia_profissional, 'pontuacao_etnica', a.pontuacao_criterio_etnico,
               'exp_saude_indigena', a.experiencia_saude_indigena_total, 'exp_atencao_basica', a.experiencia_atencao_basica_total,
               'exp_profissional', a.experiencia_profissional_total, 'status', a.status_consolidado, 'etapa', a.etapa,
               'quadro', vq.quadro, 'hora_nascimento', to_char(h."HR_NASCIMENTO", 'HH24:MI:SS'))
             order by a.codigo_vaga, a.candidato)
        from a left join vq on vq.nome_vaga is not distinct from a.nome_vaga
               left join public."TB_HORA_NASCIMENTO_CANDIDATO" h on h."CO_ANALISE_CURRICULAR" = a.id), '[]'::json),
    'entrevistas', coalesce((
      select json_agg(json_build_object(
               'id', e."CO_ENTREVISTA", 'analise_id', e."CO_ANALISE_CURRICULAR", 'nome', e."NO_CANDIDATO",
               'vaga', e."CO_VAGA", 'nota', e."VL_NOTA_TOTAL", 'parecer', e."TP_PARECER", 'compareceu', e."ST_COMPARECEU",
               'ligacao', e."TP_LIGACAO_ANALISE", 'origem', e."TP_ORIGEM",
               'notas', coalesce((select json_agg(json_build_object('ordem', n."NU_ORDEM", 'criterio', n."DS_CRITERIO", 'nota', n."VL_NOTA")
                                         order by n."NU_ORDEM")
                                    from public."TB_ENTREVISTA_NOTA" n where n."CO_ENTREVISTA" = e."CO_ENTREVISTA"), '[]'::json))
             order by e."CO_VAGA", e."NO_CANDIDATO")
        from public."TB_ENTREVISTA" e
       where e."ST_ATIVO" = 'S'
         and (e."CO_MONITORAMENTO" = p_edital
              or (e."CO_MONITORAMENTO" is null and e."CO_AREA" = v_area
                  and private."FC_NUMERO_EDITAL"(e."DS_EDITAL") = v_numero))), '[]'::json),
    'listas', coalesce((
      select json_agg(private."FC_LISTA_CLASSIFICACAO_JSON"(l."CO_LISTA_CLASSIFICACAO") order by l."DT_GERACAO" desc)
        from (select l."CO_LISTA_CLASSIFICACAO", l."DT_GERACAO"
                from public."TB_LISTA_CLASSIFICACAO" l
               where l."CO_MONITORAMENTO" = p_edital
               order by l."DT_GERACAO" desc limit 60) l), '[]'::json),
    'desempates', coalesce((
      select json_agg(private."FC_DESEMPATE_CLASSIFICACAO_JSON"(d."CO_DESEMPATE_CLASSIFICACAO") order by d."DT_REGISTRO")
        from public."TB_DESEMPATE_CLASSIFICACAO" d
       where d."CO_MONITORAMENTO" = p_edital and d."ST_ATIVO" = 'S'), '[]'::json),
    'ajustes', coalesce((
      select json_agg(private."FC_AJUSTE_PONTUACAO_JSON"(j."CO_AJUSTE_PONTUACAO") order by j."DT_APROVACAO", j."CO_AJUSTE_PONTUACAO")
        from public."TB_AJUSTE_PONTUACAO_RECURSO" j
       where j."CO_MONITORAMENTO" = p_edital and j."TP_SITUACAO" = 'APROVADO'), '[]'::json),
    'ajustes_mudaram_em', (
      select greatest(max(j."DT_APROVACAO"), max(j."DT_CANCELAMENTO") filter (where j."DT_APROVACAO" is not null))
        from public."TB_AJUSTE_PONTUACAO_RECURSO" j
       where j."CO_MONITORAMENTO" = p_edital)
  );
end;
$$;

--
-- Name: FUNCTION "FC_DADOS_CLASSIFICACAO_EDITAL"(p_edital uuid, p_area text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_DADOS_CLASSIFICACAO_EDITAL"(p_edital uuid, p_area text) IS 'O que o motor de classificação precisa de um edital (json), sem conferir permissão: regra e versões, catálogo, cronograma, quadro, análises (sem CPF, com a hora de nascimento da certidão quando informada), entrevistas, listas, desempates, os ajustes da pontuação aprovados em recurso e quando eles mudaram por último. Usada por obter_classificacao_do_edital e obter_dados_previa_ajuste.';

--
-- Name: FC_DATA_DO_TEXTO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_DATA_DO_TEXTO"(p_texto text) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  -- Sem bloco de exceção (caro numa varredura): o dia é conferido contra o último do mês.
  select case when p_texto is null or p_texto !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$'
                   or substr(p_texto, 1, 4) = '0000'
              then null
              when substr(p_texto, 9, 2)::integer <= extract(day from (make_date(substr(p_texto, 1, 4)::integer,
                     substr(p_texto, 6, 2)::integer, 1) + interval '1 month - 1 day'))::integer
              then make_date(substr(p_texto, 1, 4)::integer, substr(p_texto, 6, 2)::integer, substr(p_texto, 9, 2)::integer) end;
$_$;

--
-- Name: FC_DEFINIR_AREA_ANALISE(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_DEFINIR_AREA_ANALISE"() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  select a."CO_AREA" into new."CO_AREA"
    from public."TB_AREA" a
   where public.analises_norm_key(a."NO_GRUPO_PLANILHA") = public.analises_norm_key(new.grupo);
  return new;
end;
$$;

--
-- Name: FUNCTION "FC_DEFINIR_AREA_ANALISE"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_DEFINIR_AREA_ANALISE"() IS 'Gatilho de TB_ANALISE_CURRICULAR: preenche CO_AREA pela área cujo NO_GRUPO_PLANILHA corresponde ao grupo da linha.';

--
-- Name: FC_DEFINIR_AREA_EDITAL(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_DEFINIR_AREA_EDITAL"() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new."CO_AREA" is null then
      new."CO_AREA" := private."FC_AREA_EDITAL"(new.responsavel, new.unidade);
    end if;
  elsif new."CO_AREA" is distinct from old."CO_AREA" then
    -- Mudança explícita (mover_edital_de_area, salvar com área): respeita.
    null;
  elsif new.responsavel is distinct from old.responsavel
     or new.unidade is distinct from old.unidade then
    new."CO_AREA" := private."FC_AREA_EDITAL"(new.responsavel, new.unidade);
  end if;
  return new;
end;
$$;

--
-- Name: FUNCTION "FC_DEFINIR_AREA_EDITAL"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_DEFINIR_AREA_EDITAL"() IS 'Gatilho de TB_MONITORAMENTO_INDIGENA: define CO_AREA na inclusão (por responsável e unidade) e o recalcula quando eles mudam; mudança explícita de CO_AREA é respeitada.';

--
-- Name: FC_DEFINIR_ORIGEM_ANALISE(uuid, text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_DEFINIR_ORIGEM_ANALISE"(p_edital uuid, p_origem text, p_motivo text, p_usuario uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_origem text := upper(btrim(coalesce(p_origem, '')));
  v_motivo text := btrim(coalesce(p_motivo, ''));
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_anterior text;
  v_ficha uuid;
  v_publicadas integer := 0;
  v_devolvidas integer := 0;
  v_decididas integer := 0;
  v_seq integer;
begin
  if v_origem not in ('PLANILHA', 'COMPARACAO', 'MONITORA') then
    raise exception 'Dono da avaliação: PLANILHA, COMPARACAO ou MONITORA' using errcode = '22023';
  end if;
  if length(v_motivo) not between 10 and 2000 then
    raise exception 'Diga o motivo da troca (10 a 2.000 caracteres)' using errcode = '22023';
  end if;
  if p_usuario is null then
    raise exception 'Sessão necessária' using errcode = '42501';
  end if;
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital;
  if not found then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;

  select o."TP_ORIGEM" into v_anterior
    from public."TB_ORIGEM_ANALISE_EDITAL" o where o."CO_MONITORAMENTO" = p_edital for update;
  if coalesce(v_anterior, 'PLANILHA') = v_origem then
    return json_build_object('edital', p_edital, 'origem', v_origem, 'anterior', coalesce(v_anterior, 'PLANILHA'),
                             'mudou', false, 'publicadas', 0, 'devolvidas', 0);
  end if;
  -- Edital já decidido pela planilha não vira MONITORA por aqui: as fichas (do início)
  -- adotariam as linhas e apagariam o resultado no painel. Essa virada é a da fase F8.
  if v_origem = 'MONITORA' then
    select count(*) into v_decididas
      from public."TB_ANALISE_CURRICULAR" a
     where a.ativo
       and a."TP_ORIGEM_REGISTRO" = 'PLANILHA'
       and a."CO_AREA" = v_m."CO_AREA"
       and private."FC_NUMERO_EDITAL"(a.edital) = private."FC_NUMERO_EDITAL"(v_m.edital)
       and a.status_consolidado in ('Aprovado', 'Reprovado', 'Revisar')
       and not private."FC_ANALISE_EH_TREINAMENTO"(a.origem_planilha);
    if v_decididas > 0 then
      raise exception 'O edital já tem % análise(s) decidida(s) pela planilha: a avaliação não passa para o MONITORA por aqui', v_decididas
        using errcode = '23514';
    end if;
  end if;

  insert into public."TB_ORIGEM_ANALISE_EDITAL" ("CO_MONITORAMENTO", "TP_ORIGEM", "CO_USUARIO_ATUALIZACAO", "DT_ATUALIZACAO")
  values (p_edital, v_origem, p_usuario, now())
  on conflict ("CO_MONITORAMENTO") do update set
    "TP_ORIGEM" = excluded."TP_ORIGEM",
    "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO",
    "DT_ATUALIZACAO" = excluded."DT_ATUALIZACAO";

  if v_origem = 'MONITORA' then
    -- As fichas que já existem passam a alimentar o painel (as da planilha do mesmo candidato são adotadas).
    for v_ficha in
      select f."CO_FICHA_ANALISE" from public."TB_FICHA_ANALISE" f
       where f."CO_MONITORAMENTO" = p_edital
       order by f."DT_CRIACAO", f."CO_FICHA_ANALISE"
    loop
      if private."FC_PUBLICAR_FICHA_ANALISE"(v_ficha) is not null then
        v_publicadas := v_publicadas + 1;
      end if;
    end loop;
  elsif v_anterior = 'MONITORA' then
    -- De volta à planilha: as linhas publicadas pelas fichas voltam a ser dela (a próxima carga manda).
    update public."TB_ANALISE_CURRICULAR" a
       set "TP_ORIGEM_REGISTRO" = 'PLANILHA', updated_at = now()
     where a."TP_ORIGEM_REGISTRO" = 'MONITORA'
       and a."CO_AREA" = v_m."CO_AREA"
       and private."FC_NUMERO_EDITAL"(a.edital) = private."FC_NUMERO_EDITAL"(v_m.edital);
    get diagnostics v_devolvidas = row_count;
  end if;

  select coalesce(max(h."NU_SEQUENCIA"), 0) + 1 into v_seq
    from public."TH_ORIGEM_ANALISE_EDITAL" h where h."CO_MONITORAMENTO" = p_edital;
  insert into public."TH_ORIGEM_ANALISE_EDITAL" ("CO_MONITORAMENTO", "NU_SEQUENCIA", "TP_ORIGEM_ANTERIOR", "TP_ORIGEM",
    "DS_MOTIVO", "DS_RESULTADO", "CO_USUARIO")
  values (p_edital, v_seq, v_anterior, v_origem, v_motivo,
          jsonb_build_object('publicadas', v_publicadas, 'devolvidas', v_devolvidas), p_usuario);

  -- A lista de editais do painel muda (o edital MONITORA entra com a janela própria).
  perform private."FC_MARCAR_CACHE"(array['ANALISES'], array[v_m."CO_AREA"], 'TB_ORIGEM_ANALISE_EDITAL');

  return json_build_object('edital', p_edital, 'origem', v_origem, 'anterior', coalesce(v_anterior, 'PLANILHA'),
                           'mudou', true, 'publicadas', v_publicadas, 'devolvidas', v_devolvidas);
end;
$$;

--
-- Name: FUNCTION "FC_DEFINIR_ORIGEM_ANALISE"(p_edital uuid, p_origem text, p_motivo text, p_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_DEFINIR_ORIGEM_ANALISE"(p_edital uuid, p_origem text, p_motivo text, p_usuario uuid) IS 'Troca o dono da avaliação documental do edital (PLANILHA, COMPARACAO ou MONITORA) com motivo de 10 a 2.000 e histórico em TH_ORIGEM_ANALISE_EDITAL (com o resumo). Para MONITORA, recusa (23514) o edital que já tem análise decidida pela planilha (Aprovado, Reprovado ou Revisar; a virada com adoção é da F8) e publica as fichas que já existem (FC_PUBLICAR_FICHA_ANALISE); saindo de MONITORA, as linhas MONITORA do edital voltam a ser da planilha. Mesmo dono: não muda nada. Quem chama informa o autor. Sem grant: public.definir_origem_analise e o SQL Editor.';

--
-- Name: FC_DEMANDA_INTERNA_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_DEMANDA_INTERNA_JSON"(p_demanda uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', d."CO_DEMANDA_INTERNA",
    'area', d."CO_AREA",
    'edital_id', d."CO_MONITORAMENTO",
    'edital', m.edital,
    'unidade', m.unidade,
    'titulo', d."NO_DEMANDA",
    'descricao', d."DS_DEMANDA",
    'data_inicio', d."DT_INICIO",
    'data_fim', d."DT_FIM",
    'concluida', d."ST_CONCLUIDA" = 'S',
    'concluida_em', d."DT_CONCLUSAO",
    'concluida_por', private."FC_NOME_USUARIO"(d."CO_USUARIO_CONCLUSAO"),
    'ativo', d."ST_ATIVO" = 'S',
    'criada_em', d."DT_CRIACAO",
    'criada_por', private."FC_NOME_USUARIO"(d."CO_USUARIO_CRIACAO"),
    'atualizada_em', d."DT_ATUALIZACAO",
    'atualizada_por', private."FC_NOME_USUARIO"(d."CO_USUARIO_ATUALIZACAO"),
    'responsaveis', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', u.id,
               'nome', coalesce(nullif(btrim(u.nome), ''), u.email))
             order by coalesce(nullif(btrim(u.nome), ''), u.email))
        from public."RL_DEMANDA_INTERNA_RESPONSAVEL" r
        join public."TB_PERFIL_USUARIO" u on u.id = r."CO_PERFIL_USUARIO"
       where r."CO_DEMANDA_INTERNA" = d."CO_DEMANDA_INTERNA"), '[]'::jsonb))
  from public."TB_DEMANDA_INTERNA" d
  left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = d."CO_MONITORAMENTO"
  where d."CO_DEMANDA_INTERNA" = p_demanda;
$$;

--
-- Name: FUNCTION "FC_DEMANDA_INTERNA_JSON"(p_demanda uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_DEMANDA_INTERNA_JSON"(p_demanda uuid) IS 'A demanda interna em json (com edital e responsáveis), para as RPCs e o histórico. 20261104120000.';

--
-- Name: FC_DESATIVAR_ENTREVISTAS_REPETIDAS(text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_DESATIVAR_ENTREVISTAS_REPETIDAS"(p_area text, p_edital uuid DEFAULT NULL::uuid, p_usuario uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_qt integer;
begin
  with repetidas as (
    select e."CO_ENTREVISTA", s."CO_ENTREVISTA" as do_sistema
      from public."TB_ENTREVISTA" e
      join lateral (
        select x."CO_ENTREVISTA" from public."TB_ENTREVISTA" x
         where x."CO_ANALISE_CURRICULAR" = e."CO_ANALISE_CURRICULAR"
           and x."TP_ORIGEM" = 'sistema' and x."ST_ATIVO" = 'S'
           and (p_edital is null or x."CO_MONITORAMENTO" = p_edital)
         order by x."DT_ATUALIZACAO" desc limit 1
      ) s on true
     where e."CO_AREA" = p_area and e."TP_ORIGEM" = 'planilha' and e."ST_ATIVO" = 'S'
       and e."CO_ANALISE_CURRICULAR" is not null
       and e."CO_ENTREVISTA" not in (select v from private."FC_ENTREVISTAS_VIGENTES"(p_area) v)
  ),
  desativadas as (
    update public."TB_ENTREVISTA" e set "ST_ATIVO" = 'N', "DT_ATUALIZACAO" = now()
      from repetidas r
     where e."CO_ENTREVISTA" = r."CO_ENTREVISTA"
    returning e."CO_ENTREVISTA", r.do_sistema
  )
  insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
  select d."CO_ENTREVISTA", 'repetida', 'S', 'N: a análise tem a entrevista do sistema ' || d.do_sistema, p_usuario
    from desativadas d;
  get diagnostics v_qt = row_count;
  return v_qt;
end;
$$;

--
-- Name: FUNCTION "FC_DESATIVAR_ENTREVISTAS_REPETIDAS"(p_area text, p_edital uuid, p_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_DESATIVAR_ENTREVISTAS_REPETIDAS"(p_area text, p_edital uuid, p_usuario uuid) IS 'Desativa (ST_ATIVO = N, com histórico "repetida") a entrevista da planilha cuja análise já tem entrevista ativa do sistema, quando a da planilha não é a vigente (FC_ENTREVISTAS_VIGENTES). Nunca desativa a do sistema. p_edital: só as do sistema desse edital. Devolve quantas desativou (20261022200000).';

