COMMENT ON FUNCTION private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital uuid, p_minimo integer) IS 'Barra (42501) quem não tem classificacao no nível pedido (1 leitor, 2 editor), a área ou o recorte da coordenação do edital; edital inexistente = 22023. Devolve a área do edital.';

--
-- Name: FC_EXIGIR_COORD_AVALIACAO(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_EXIGIR_COORD_AVALIACAO"(p_edital uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 3);
begin
  if private."FC_PAPEL_AVALIACAO"(p_edital) is distinct from 'COORDENADOR' then
    raise exception 'Só o gestor do edital ou a coordenação da avaliação muda a regra e a equipe' using errcode = '42501';
  end if;
  return v_area;
end;
$$;

--
-- Name: FUNCTION "FC_EXIGIR_COORD_AVALIACAO"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_EXIGIR_COORD_AVALIACAO"(p_edital uuid) IS 'Barra (42501) quem não coordena a avaliação documental do edital (Administrador em avaliacao_documental + gestor do edital, coordenador na equipe ou administrador global). Devolve a área do edital.';

--
-- Name: FC_EXIGIR_COORD_FICHAS(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_EXIGIR_COORD_FICHAS"(p_edital uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 3);
begin
  if private."FC_PAPEL_AVALIACAO"(p_edital) is distinct from 'COORDENADOR' then
    raise exception 'Só a coordenação do edital distribui as fichas, libera reservas de outras pessoas e manda para revisão' using errcode = '42501';
  end if;
  return v_area;
end;
$$;

