--
-- Name: FC_EXIGIR_EXECUCAO_CONFERENCIA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_EXIGIR_EXECUCAO_CONFERENCIA"(p_execucao text) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
begin
  if p_execucao is null or p_execucao !~ '^[A-Za-z0-9_-]{8,80}$' then
    raise exception 'Identificador de execução inválido' using errcode = '22023';
  end if;
  if not exists (select 1 from public."TL_CONFERENCIA" c
                  where c."CO_EXECUCAO" = p_execucao and c."TP_SITUACAO" = 'EM_ANDAMENTO') then
    raise exception 'Execução % não encontrada ou já fechada', p_execucao using errcode = '22023';
  end if;
end;
$_$;

--
-- Name: FUNCTION "FC_EXIGIR_EXECUCAO_CONFERENCIA"(p_execucao text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_EXIGIR_EXECUCAO_CONFERENCIA"(p_execucao text) IS 'Recusa (22023) identificador inválido ou execução de conferências que não está em andamento.';

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: TL_PRE_CLASSIFICACAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TL_PRE_CLASSIFICACAO" (
    "CO_EXECUCAO" text NOT NULL,
    "DT_INICIO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_FIM" timestamp with time zone,
    "TP_SITUACAO" character varying(12) DEFAULT 'EM_ANDAMENTO'::character varying NOT NULL,
    "TP_DISPARO" character varying(8) NOT NULL,
    "CO_USUARIO_DISPARO" uuid,
    "ST_REFAZER_LOTE" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "DS_PEDIDO" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "DS_EDITAL" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "QT_EDITAL" integer DEFAULT 0 NOT NULL,
    "QT_VAGA" integer DEFAULT 0 NOT NULL,
    "QT_INSCRITO" integer DEFAULT 0 NOT NULL,
    "QT_ELIMINADO" integer DEFAULT 0 NOT NULL,
    "QT_RANQUEADO" integer DEFAULT 0 NOT NULL,
    "QT_LOTE" integer DEFAULT 0 NOT NULL,
    "QT_DIVERGENCIA" integer DEFAULT 0 NOT NULL,
    "DS_MENSAGEM" character varying(2000),
    "DS_URL_EXECUCAO" character varying(300),
    CONSTRAINT "CK_TLPRECLASSIF_COEXECUCAO" CHECK (("CO_EXECUCAO" ~ '^[A-Za-z0-9_-]{8,80}$'::text)),
    CONSTRAINT "CK_TLPRECLASSIF_LISTAS" CHECK (((jsonb_typeof("DS_PEDIDO") = 'array'::text) AND (jsonb_typeof("DS_EDITAL") = 'array'::text))),
    CONSTRAINT "CK_TLPRECLASSIF_QT" CHECK ((("QT_EDITAL" >= 0) AND ("QT_VAGA" >= 0) AND ("QT_INSCRITO" >= 0) AND ("QT_ELIMINADO" >= 0) AND ("QT_RANQUEADO" >= 0) AND ("QT_LOTE" >= 0) AND ("QT_DIVERGENCIA" >= 0))),
    CONSTRAINT "CK_TLPRECLASSIF_STREFAZER" CHECK ((("ST_REFAZER_LOTE")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_TLPRECLASSIF_TPDISPARO" CHECK ((("TP_DISPARO")::text = ANY (ARRAY[('ROBO'::character varying)::text, ('MONITORA'::character varying)::text, ('GITHUB'::character varying)::text]))),
    CONSTRAINT "CK_TLPRECLASSIF_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY (ARRAY[('EM_ANDAMENTO'::character varying)::text, ('CONCLUIDA'::character varying)::text, ('PARCIAL'::character varying)::text, ('FALHOU'::character varying)::text]))),
    CONSTRAINT "CK_TLPRECLASSIF_URL" CHECK ((("DS_URL_EXECUCAO" IS NULL) OR (("DS_URL_EXECUCAO")::text ~ '^https://github\.com/'::text))),
    CONSTRAINT "CK_TLPRECLASSIF_USUARIO" CHECK (((("TP_DISPARO")::text = 'MONITORA'::text) = ("CO_USUARIO_DISPARO" IS NOT NULL)))
);

--
-- Name: TABLE "TL_PRE_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TL_PRE_CLASSIFICACAO" IS 'Log das execuções do job da pré-classificação (scripts/pre_classificacao/): uma linha por execução, só com códigos e contagens.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."CO_EXECUCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."CO_EXECUCAO" IS 'Identificador da execução (gerado pelo job: precl-<data>-<sufixo>).';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."DT_INICIO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."DT_INICIO" IS 'Início da execução.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."DT_FIM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."DT_FIM" IS 'Fechamento (finalizar_pre_classificacao). Nulo enquanto roda.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."TP_SITUACAO" IS 'EM_ANDAMENTO; CONCLUIDA (todos os editais pedidos foram tratados); PARCIAL (algum edital falhou); FALHOU (erro geral).';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."TP_DISPARO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."TP_DISPARO" IS 'Quem disparou: ROBO (ao fim do robô da Empregare), MONITORA (Recalcular ou Rodar agora) ou GITHUB (Run workflow).';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."CO_USUARIO_DISPARO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."CO_USUARIO_DISPARO" IS 'Usuário do MONITORA (auth.users.id) que pediu; nulo nos outros disparos.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."ST_REFAZER_LOTE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."ST_REFAZER_LOTE" IS 'S: o lote foi recortado do zero (só antes das fichas).';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."DS_PEDIDO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."DS_PEDIDO" IS 'Editais pedidos (ids ou números, lista json); vazia = os editais ativos com vagas da Empregare.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."DS_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."DS_EDITAL" IS 'Resultado por edital (lista json): edital, situação (PROCESSADO, SEM_REGRA, REGRA_NAO_CONFERIDA, SEM_VAGAS, FALHOU), vagas e contagens. Sem dado pessoal.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."QT_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."QT_EDITAL" IS 'Editais processados.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."QT_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."QT_VAGA" IS 'Vagas gravadas nesta execução.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."QT_INSCRITO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."QT_INSCRITO" IS 'Inscritos considerados nas vagas gravadas.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."QT_ELIMINADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."QT_ELIMINADO" IS 'Eliminados automáticos nas vagas gravadas.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."QT_RANQUEADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."QT_RANQUEADO" IS 'Inscritos na Provisória (não eliminados) nas vagas gravadas.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."QT_LOTE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."QT_LOTE" IS 'Inscritos no lote (NO_LOTE e ANALISADO) nas vagas gravadas.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."QT_DIVERGENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."QT_DIVERGENCIA" IS 'Inscritos com a ART diferente da nota declarada além da tolerância.';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."DS_MENSAGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."DS_MENSAGEM" IS 'Erro geral ou observação (sem dado pessoal).';

--
-- Name: COLUMN "TL_PRE_CLASSIFICACAO"."DS_URL_EXECUCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_PRE_CLASSIFICACAO"."DS_URL_EXECUCAO" IS 'Endereço da execução no GitHub Actions.';

--
-- Name: CONSTRAINT "CK_TLPRECLASSIF_COEXECUCAO" ON "TL_PRE_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_TLPRECLASSIF_COEXECUCAO" ON public."TL_PRE_CLASSIFICACAO" IS 'Identificador de 8 a 80 caracteres seguros.';

--
