--
-- Name: FC_EXIGIR_EXECUCAO_PRECLASSIF(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_EXIGIR_EXECUCAO_PRECLASSIF"(p_execucao text) RETURNS public."TL_PRE_CLASSIFICACAO"
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  v public."TL_PRE_CLASSIFICACAO";
begin
  if p_execucao is null or p_execucao !~ '^[A-Za-z0-9_-]{8,80}$' then
    raise exception 'Identificador de execução inválido' using errcode = '22023';
  end if;
  select * into v from public."TL_PRE_CLASSIFICACAO" t where t."CO_EXECUCAO" = p_execucao;
  if v."CO_EXECUCAO" is null or v."TP_SITUACAO" <> 'EM_ANDAMENTO' then
    raise exception 'Execução % não encontrada ou já fechada', p_execucao using errcode = '22023';
  end if;
  return v;
end;
$_$;

--
-- Name: FUNCTION "FC_EXIGIR_EXECUCAO_PRECLASSIF"(p_execucao text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_EXIGIR_EXECUCAO_PRECLASSIF"(p_execucao text) IS 'Recusa (22023) identificador inválido ou execução da pré-classificação que não está em andamento; devolve a execução.';

--
-- Name: TB_PERFIL_USUARIO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_PERFIL_USUARIO" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    email text,
    nome text,
    perfil text DEFAULT 'usuario'::text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    p_ind boolean DEFAULT false NOT NULL,
    p_cores boolean DEFAULT false NOT NULL,
    p_paineis boolean DEFAULT false NOT NULL,
    p_config boolean DEFAULT false NOT NULL,
    p_admin boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    avatar_source text DEFAULT 'INITIALS'::text NOT NULL,
    avatar_url text,
    avatar_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    google_avatar_url text,
    "CO_COORDENACAO" text,
    CONSTRAINT perfis_usuarios_avatar_source_check CHECK ((avatar_source = ANY (ARRAY['GOOGLE'::text, 'UPLOADED'::text, 'GENERATED'::text, 'INITIALS'::text])))
);

--
-- Name: COLUMN "TB_PERFIL_USUARIO"."CO_COORDENACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PERFIL_USUARIO"."CO_COORDENACAO" IS 'Coordenação do usuário (no máximo uma). Null: vê as áreas de RL_PERFIL_USUARIO_AREA inteiras.';

--
-- Name: FC_EXIGIR_GESTAO_DO_USUARIO(public."TB_PERFIL_USUARIO"); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_EXIGIR_GESTAO_DO_USUARIO"(p_alvo public."TB_PERFIL_USUARIO") RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_gestor text := private."FC_EXIGIR_GESTOR_DE_ACESSOS"();
begin
  if p_alvo.id is null then raise exception 'Usuário ativo não encontrado'; end if;
  if p_alvo.user_id = (select auth.uid())
     or lower(p_alvo.email) = lower(coalesce((select auth.jwt() ->> 'email'), '')) then
    raise exception 'Outra pessoa deve alterar seu acesso' using errcode = '42501';
  end if;
  if v_gestor = 'coordenador' then
    if p_alvo."CO_COORDENACAO" is distinct from private."FC_COORDENACAO_USUARIO"() then
      raise exception 'Usuário fora da sua coordenação' using errcode = '42501';
    end if;
    if exists (select 1 from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = p_alvo.perfil and a."ST_ADMIN_GLOBAL") then
      raise exception 'Só um administrador altera outro administrador' using errcode = '42501';
    end if;
  end if;
end;
$$;

--
-- Name: FUNCTION "FC_EXIGIR_GESTAO_DO_USUARIO"(p_alvo public."TB_PERFIL_USUARIO"); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_EXIGIR_GESTAO_DO_USUARIO"(p_alvo public."TB_PERFIL_USUARIO") IS 'Recusa (42501) a alteração de acesso quando quem pede não pode gerir o usuário alvo: o próprio acesso, ou coordenador fora da sua coordenação.';

--
-- Name: FC_EXIGIR_GESTOR_DE_ACESSOS(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_EXIGIR_GESTOR_DE_ACESSOS"() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v text := private."FC_GESTOR_DE_ACESSOS"();
begin
  if v is null then
    raise exception 'Somente administradores ou coordenadores podem gerenciar acessos' using errcode = '42501';
  end if;
  return v;
end;
$$;

--
-- Name: FUNCTION "FC_EXIGIR_GESTOR_DE_ACESSOS"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_EXIGIR_GESTOR_DE_ACESSOS"() IS 'Devolve o papel de gestor de acessos (admin ou coordenador) ou recusa (42501) quem não é nenhum dos dois.';

--
-- Name: TB_FICHA_ANALISE; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_FICHA_ANALISE" (
    "CO_FICHA_ANALISE" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_EMPREGARE_CANDIDATO" uuid NOT NULL,
    "CO_VAGA" character varying(20) NOT NULL,
    "CO_REGRA_ANALISE" uuid NOT NULL,
    "NU_VERSAO_REGRA" integer NOT NULL,
    "NU_LOTE" smallint NOT NULL,
    "TP_SITUACAO" character varying(12) DEFAULT 'PENDENTE'::character varying NOT NULL,
    "CO_USUARIO_RESPONSAVEL" uuid,
    "DT_ATRIBUICAO" timestamp with time zone,
    "CO_USUARIO_RESERVA" uuid,
    "DT_RESERVA" timestamp with time zone,
    "DT_RESERVA_EXPIRA" timestamp with time zone,
    "DS_MOTIVO_SAIDA" character varying(300),
    "NU_VERSAO" integer DEFAULT 1 NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DS_LANCAMENTO" jsonb,
    "DS_RESULTADO" jsonb,
    "DS_PARECER" text,
    "TP_RESULTADO" character varying(16),
    "VL_NOTA_APURADA" numeric(8,4),
    "VL_NOTA_FINAL" numeric(8,4),
    "CO_USUARIO_RASCUNHO" uuid,
    "DT_RASCUNHO" timestamp with time zone,
    "CO_USUARIO_CONCLUSAO" uuid,
    "DT_CONCLUSAO" timestamp with time zone,
    CONSTRAINT "CK_FICHAANALISE_CONCLUSAO" CHECK (((("TP_SITUACAO")::text <> 'CONCLUIDA'::text) OR (("TP_RESULTADO" IS NOT NULL) AND ("VL_NOTA_FINAL" IS NOT NULL) AND ("VL_NOTA_APURADA" IS NOT NULL) AND (length(btrim(COALESCE("DS_PARECER", ''::text))) > 0) AND ("DS_LANCAMENTO" IS NOT NULL) AND ("DS_RESULTADO" IS NOT NULL) AND ("DT_CONCLUSAO" IS NOT NULL) AND ((("TP_RESULTADO")::text <> 'INAPTO_REQUISITO'::text) OR ("VL_NOTA_FINAL" = (0)::numeric))))),
    CONSTRAINT "CK_FICHAANALISE_CONTEUDO" CHECK (((("DS_LANCAMENTO" IS NULL) OR ((jsonb_typeof("DS_LANCAMENTO") = 'object'::text) AND (length(("DS_LANCAMENTO")::text) <= 200000))) AND (("DS_RESULTADO" IS NULL) OR ((jsonb_typeof("DS_RESULTADO") = 'object'::text) AND (length(("DS_RESULTADO")::text) <= 100000))) AND (("DS_PARECER" IS NULL) OR (length("DS_PARECER") <= 8000)) AND ((COALESCE("VL_NOTA_APURADA", (0)::numeric) >= (0)::numeric) AND (COALESCE("VL_NOTA_APURADA", (0)::numeric) <= (1000)::numeric)) AND ((COALESCE("VL_NOTA_FINAL", (0)::numeric) >= (0)::numeric) AND (COALESCE("VL_NOTA_FINAL", (0)::numeric) <= (1000)::numeric)) AND (("CO_USUARIO_RASCUNHO" IS NULL) = ("DT_RASCUNHO" IS NULL)) AND (("CO_USUARIO_CONCLUSAO" IS NULL) = ("DT_CONCLUSAO" IS NULL)))),
    CONSTRAINT "CK_FICHAANALISE_FLUXO" CHECK ((((("TP_SITUACAO")::text <> 'EM_ANALISE'::text) OR ("CO_USUARIO_RESPONSAVEL" IS NOT NULL)) AND (("CO_USUARIO_RESPONSAVEL" IS NULL) = ("DT_ATRIBUICAO" IS NULL)) AND ((("TP_SITUACAO")::text = 'FORA_LOTE'::text) = ("DS_MOTIVO_SAIDA" IS NOT NULL)))),
    CONSTRAINT "CK_FICHAANALISE_NUMEROS" CHECK ((("NU_VERSAO" >= 1) AND ("NU_VERSAO_REGRA" >= 1) AND (("NU_LOTE" >= 1) AND ("NU_LOTE" <= 999)))),
    CONSTRAINT "CK_FICHAANALISE_RESERVA" CHECK (((("CO_USUARIO_RESERVA" IS NULL) = ("DT_RESERVA" IS NULL)) AND (("DT_RESERVA" IS NULL) = ("DT_RESERVA_EXPIRA" IS NULL)) AND (("CO_USUARIO_RESERVA" IS NULL) OR ((("TP_SITUACAO")::text = ANY (ARRAY[('EM_ANALISE'::character varying)::text, ('REVISAR'::character varying)::text])) AND ("DT_RESERVA_EXPIRA" > "DT_RESERVA"))))),
    CONSTRAINT "CK_FICHAANALISE_TPRESULTADO" CHECK ((("TP_RESULTADO" IS NULL) OR (("TP_RESULTADO")::text = ANY (ARRAY[('APTO'::character varying)::text, ('INAPTO_REQUISITO'::character varying)::text, ('INAPTO_NOTA'::character varying)::text])))),
    CONSTRAINT "CK_FICHAANALISE_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY (ARRAY[('PENDENTE'::character varying)::text, ('EM_ANALISE'::character varying)::text, ('REVISAR'::character varying)::text, ('CONCLUIDA'::character varying)::text, ('FORA_LOTE'::character varying)::text])))
);

--
-- Name: TABLE "TB_FICHA_ANALISE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_FICHA_ANALISE" IS 'Ficha da avaliação documental de um inscrito do lote de convocação: situação, responsável, reserva de 15 minutos, versão para o controle otimista e o conteúdo da análise (lançamento do analista, resultado da conta, nota e parecer). Criada pelo banco (FC_ABRIR_FICHAS) para quem está no lote; quem sai eliminado mantém a ficha como FORA_LOTE. Nada se apaga.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_FICHA_ANALISE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_FICHA_ANALISE" IS 'Identificador da ficha.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_EMPREGARE_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_EMPREGARE_CANDIDATO" IS 'Inscrito (TB_EMPREGARE_CANDIDATO; a linha da pré-classificação do edital).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_VAGA" IS 'Código da vaga da Empregare.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_REGRA_ANALISE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_REGRA_ANALISE" IS 'Regra da avaliação do edital (TB_REGRA_ANALISE).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."NU_VERSAO_REGRA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."NU_VERSAO_REGRA" IS 'Versão da regra: a com que o inscrito entrou no lote e, depois de concluída, a com que foi analisado (concluir_ficha grava a vigente). Pendente e em análise seguem a vigente (AM-2.3).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."NU_LOTE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."NU_LOTE" IS 'Lote em que o inscrito entrou (1 = inicial; 2, 3… = reposições).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."TP_SITUACAO" IS 'PENDENTE (na fila, com ou sem responsável), EM_ANALISE (o responsável abriu; rascunho), REVISAR (mandada para revisão), CONCLUIDA (concluir_ficha; só leitura até reabrir) ou FORA_LOTE (saiu do lote, eliminado; a ficha fica com o motivo).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_USUARIO_RESPONSAVEL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_USUARIO_RESPONSAVEL" IS 'Analista responsável (auth.users.id): quem pegou ou para quem a coordenação distribuiu. Nulo = livre na fila.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DT_ATRIBUICAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DT_ATRIBUICAO" IS 'Quando a ficha foi para o responsável atual.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_USUARIO_RESERVA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_USUARIO_RESERVA" IS 'Quem está com a ficha aberta (reserva); só essa pessoa grava. Vale até DT_RESERVA_EXPIRA.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DT_RESERVA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DT_RESERVA" IS 'Início da reserva ("Em uso por … desde HH:MM").';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DT_RESERVA_EXPIRA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DT_RESERVA_EXPIRA" IS 'Fim da reserva (15 minutos, renovada enquanto a pessoa trabalha). Vencida = livre.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DS_MOTIVO_SAIDA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DS_MOTIVO_SAIDA" IS 'Por que saiu do lote (o motivo da eliminação automática); só em FORA_LOTE.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."NU_VERSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."NU_VERSAO" IS 'Versão da ficha (controle otimista): sobe a cada mudança de situação, responsável, reserva ou conteúdo (rascunho); quem age com versão velha recebe 40001.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DT_CRIACAO" IS 'Quando a ficha foi aberta.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DT_ATUALIZACAO" IS 'Última mudança.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DS_LANCAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DS_LANCAMENTO" IS 'O que o analista lançou, no formato do candidato de src/lib/avaliacao-documental/pontuacao.js: nível, modalidade, indígena/aldeia, blocos {situação, motivos, motivo livre, nota ajustada, justificativas, complemento}, títulos, cursos, vínculos, estágio e observações. Sem CPF nem contato.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DS_RESULTADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DS_RESULTADO" IS 'O resultado da conta da tela (resumoParaGravar de src/lib/avaliacao-documental/ficha.js): resultado, nota apurada e final, nota mínima, parciais, calculadas e ajustadas, a declarada por parcial, motivos eliminatórios, encaminhamentos, observações e a experiência apurada.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DS_PARECER"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DS_PARECER" IS 'Parecer gerado pela regra a partir dos motivos, das justificativas e das observações (até 8.000 caracteres).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."TP_RESULTADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."TP_RESULTADO" IS 'APTO, INAPTO_REQUISITO (nota final 0) ou INAPTO_NOTA; gravado na conclusão.';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."VL_NOTA_APURADA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."VL_NOTA_APURADA" IS 'Soma das parciais apuradas (na conclusão).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."VL_NOTA_FINAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."VL_NOTA_FINAL" IS 'Nota final: a apurada, ou 0 se inapto por requisito (na conclusão).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_USUARIO_RASCUNHO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_USUARIO_RASCUNHO" IS 'Quem salvou o último rascunho (auth.users.id).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DT_RASCUNHO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DT_RASCUNHO" IS 'Último rascunho salvo ("Salvo às HH:MM").';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."CO_USUARIO_CONCLUSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."CO_USUARIO_CONCLUSAO" IS 'Quem concluiu (auth.users.id): o login, nada digitado (AM-12.6).';

--
-- Name: COLUMN "TB_FICHA_ANALISE"."DT_CONCLUSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_FICHA_ANALISE"."DT_CONCLUSAO" IS 'Quando foi concluída (a última vez, se reaberta e concluída de novo).';

--
-- Name: CONSTRAINT "CK_FICHAANALISE_CONCLUSAO" ON "TB_FICHA_ANALISE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_FICHAANALISE_CONCLUSAO" ON public."TB_FICHA_ANALISE" IS 'Concluída tem resultado, notas, parecer, lançamento, resultado da conta e data; inapto por requisito tem nota final 0.';

--
-- Name: CONSTRAINT "CK_FICHAANALISE_CONTEUDO" ON "TB_FICHA_ANALISE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_FICHAANALISE_CONTEUDO" ON public."TB_FICHA_ANALISE" IS 'Lançamento e resultado são objetos json de tamanho limitado; parecer até 8.000; notas de 0 a 1.000; rascunho e conclusão têm quem e quando.';

