COMMENT ON FUNCTION private."FC_MARCADORES_MODELO_RESPOSTA"() IS 'Marcadores aceitos no corpo dos modelos de resposta (os mesmos de src/lib/modelos-de-resposta.js).';

--
-- Name: FC_MARCAR_CACHE(text[], text[], text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MARCAR_CACHE"(p_tipos text[], p_areas text[], p_tabela text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into private."TL_ALTERACAO_CACHE" ("TP_CACHE", "CO_AREA", "NO_TABELA_ORIGEM")
  select t.tipo, a.area, left(p_tabela, 63)
    from unnest(p_tipos) as t(tipo)
   cross join (select distinct x from unnest(p_areas) as u(x) where x is not null) as a(area)
   order by 1, 2;
$$;

--
-- Name: FUNCTION "FC_MARCAR_CACHE"(p_tipos text[], p_areas text[], p_tabela text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MARCAR_CACHE"(p_tipos text[], p_areas text[], p_tabela text) IS 'Marca os caches p_tipos das áreas p_areas como a refazer (TL_ALTERACAO_CACHE). Chamada pelos gatilhos por comando das tabelas de origem.';

--
-- Name: FC_MARCA_DA_LEITURA(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MARCA_DA_LEITURA"(p_leitura text, p_chave text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select 'm1:' || md5(concat_ws('|',
           p_leitura,
           coalesce(p_chave, ''),
           coalesce((select auth.uid())::text, ''),
           lower(coalesce((select auth.jwt()) ->> 'email', '')),
           coalesce((select auth.role()), ''),
           -- TRUNCATE ou tabela recriada: as somas recomeçam, a marca não repete.
           pg_catalog.pg_relation_filenode('private."TL_VERSAO_FONTE"'::regclass)::text,
           string_agg(f."NO_FONTE" || '=' || coalesce(v.qt, 0)::text, ',' order by f."NO_FONTE")))
    from private."TD_FONTE_DA_LEITURA" f
    left join lateral (
      select sum(x."QT_ALTERACAO") as qt
        from private."TL_VERSAO_FONTE" x
       where x."NO_FONTE" = f."NO_FONTE") v on true
   where f."NO_LEITURA" = p_leitura
  having count(*) > 0;
$$;

--
-- Name: FUNCTION "FC_MARCA_DA_LEITURA"(p_leitura text, p_chave text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MARCA_DA_LEITURA"(p_leitura text, p_chave text) IS 'Marca barata de uma leitura (20261029170000): md5 da leitura, da chave (parâmetros), de quem lê (auth.uid, e-mail, papel) e da versão de cada fonte (TL_VERSAO_FONTE). Nula se a leitura não tem fontes.';

--
-- Name: FC_MARCA_DA_RPC(text, text, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MARCA_DA_RPC"(p_rpc text, p_area text DEFAULT NULL::text, p_edital uuid DEFAULT NULL::uuid, p_escopo text DEFAULT NULL::text, p_modulo text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text;
  v_escopo text;
  v_modulo text;
  v_pacote text;
begin
  -- A permissão de cada RPC é conferida aqui com os mesmos erros da função de sempre:
  -- a resposta `inalterado` não monta nada, mas também não sai para quem não pode ler.
  case p_rpc
  when 'get_analises_dashboard_payload_v2' then
    v_escopo := lower(btrim(coalesce(p_escopo, 'ativo')));
    v_area := lower(btrim(coalesce(p_area, 'saude-indigena')));
    if not private.pode_recurso('analises') then
      raise exception 'Sem permissão para este recurso' using errcode = '42501';
    end if;
    if v_escopo not in ('ativo', 'inativo', 'desativadas') then
      raise exception 'Escopo invalido. Use ativo, inativo ou desativadas.';
    end if;
    perform private."FC_GRUPOS_ANALISES_DA_AREA"(v_area);
    -- Sem recorte e com pacote de menos de 24 h, a função entrega o pacote e a área.
    if private."FC_EDITAIS_VISIVEIS"() is null then
      select concat_ws('|', (extract(epoch from c."DT_GERACAO") * 1000000)::bigint, c."DS_VERSAO_DADOS")
        into v_pacote
        from private."TA_PAINEL_ANALISE" c
       where c."CO_AREA" = v_area and c."TP_ESCOPO" = v_escopo
         and c."DT_GERACAO" > now() - interval '24 hours';
      if v_pacote is not null
         and not private."FC_CACHE_DESATUALIZADO"('ANALISES', v_area) then
        return private."FC_MARCA_DA_LEITURA"('analises_pacote', concat_ws('|', v_area, v_escopo, v_pacote));
      end if;
    end if;
    return private."FC_MARCA_DA_LEITURA"('analises_painel', concat_ws('|', v_area, v_escopo));

  when 'get_entrevistas_da_area' then
    if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
      raise exception 'Área inválida' using errcode = '22023';
    end if;
    if not private.pode_recurso('entrevistas', 1) then
      raise exception 'Sem permissão para Entrevistas' using errcode = '42501';
    end if;
    if not private."FC_PODE_AREA"(p_area) then
      raise exception 'Sem acesso a esta área' using errcode = '42501';
    end if;
    -- Sem recorte e com pacote, a função entrega o pacote como está (DS_PAYLOAD é not null).
    if private."FC_EDITAIS_VISIVEIS"() is null then
      select concat_ws('|', (extract(epoch from c."DT_GERACAO") * 1000000)::bigint, c."DS_VERSAO_DADOS")
        into v_pacote
        from private."TA_PAINEL_ENTREVISTA" c
       where c."CO_AREA" = p_area;
      if v_pacote is not null then
        return private."FC_MARCA_DA_LEITURA"('entrevistas_pacote', concat_ws('|', p_area, v_pacote));
      end if;
    end if;
    return private."FC_MARCA_DA_LEITURA"('entrevistas_area', p_area);

  when 'get_selecao_da_area' then
    if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
      raise exception 'Área inválida' using errcode = '22023';
    end if;
    if not private.pode_recurso('selecao', 1) then
      raise exception 'Sem permissão para Seleção' using errcode = '42501';
    end if;
    if not private."FC_PODE_AREA"(p_area) then
      raise exception 'Sem acesso a esta área' using errcode = '42501';
    end if;
    return private."FC_MARCA_DA_LEITURA"('selecao_area', p_area);

  when 'listar_acompanhamento_da_visao_geral' then
    v_area := lower(btrim(coalesce(p_area, '')));
    if not private.pode_recurso('dashboard') then
      raise exception 'Sem permissão para este recurso' using errcode = '42501';
    end if;
    if not (v_area = any ((select private."FC_AREAS_USUARIO"())::text[])) then
      raise exception 'Sem permissão para esta área' using errcode = '42501';
    end if;
    return private."FC_MARCA_DA_LEITURA"('acompanhamento_visao_geral', v_area);

  when 'obter_regra_analise' then
    perform private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
    return private."FC_MARCA_DA_LEITURA"('regra_analise', p_edital::text);

  when 'obter_classificacao_do_edital' then
    perform private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 1);
    return private."FC_MARCA_DA_LEITURA"('classificacao_edital', p_edital::text);

  when 'listar_avisos_conferencia' then
    v_area := nullif(lower(btrim(coalesce(p_area, ''))), '');
    v_modulo := nullif(lower(btrim(coalesce(p_modulo, ''))), '');
    if auth.uid() is null then
      raise exception 'Sessão necessária' using errcode = '42501';
    end if;
    if v_area is not null and not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
      raise exception 'Área inválida' using errcode = '22023';
    end if;
    if v_modulo is not null and v_modulo not in ('analises', 'entrevistas', 'classificacao', 'aprovados', 'cargas') then
      raise exception 'Módulo inválido' using errcode = '22023';
    end if;
    return private."FC_MARCA_DA_LEITURA"('avisos_conferencia', concat_ws('|', coalesce(v_area, ''), coalesce(v_modulo, '')));

  else
    raise exception 'RPC sem marca: %', p_rpc using errcode = '22023';
  end case;
end;
$$;

--
-- Name: FUNCTION "FC_MARCA_DA_RPC"(p_rpc text, p_area text, p_edital uuid, p_escopo text, p_modulo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MARCA_DA_RPC"(p_rpc text, p_area text, p_edital uuid, p_escopo text, p_modulo text) IS 'A marca da leitura de uma RPC por versão, depois de conferir a permissão dela com os mesmos erros (20261029170000). Análises e Entrevistas sem recorte com pacote pronto: marca da linha do pacote (DT_GERACAO, DS_VERSAO_DADOS) e das permissões.';

--
-- Name: FC_MARCA_DO_MONITORAMENTO_OPERACIONAL(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MARCA_DO_MONITORAMENTO_OPERACIONAL"() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- A view usa CURRENT_DATE (cronograma): a data entra na chave.
  select private."FC_MARCA_DA_LEITURA"('monitoramento_operacional', current_date::text);
$$;

--
-- Name: FUNCTION "FC_MARCA_DO_MONITORAMENTO_OPERACIONAL"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MARCA_DO_MONITORAMENTO_OPERACIONAL"() IS 'A marca barata da leitura monitoramento_operacional (fontes, quem lê e a data de hoje) para listar_monitoramento_operacional, que é security invoker (20261103171500).';

--
-- Name: FC_MODALIDADES_DA_FICHA(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MODALIDADES_DA_FICHA"(p_ficha uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_lista jsonb;
begin
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha;
  if not found then
    return '{}'::text[];
  end if;
  -- Analisada (com resultado, concluída ou em revisão): as cotas confirmadas pelo lançamento.
  if v_f."TP_RESULTADO" is not null and v_f."TP_SITUACAO" in ('CONCLUIDA', 'REVISAR') then
    return private."FC_COTAS_CONFIRMADAS"(
      (select r.p_configuracao from private."FC_REGRA_VIGENTE_FICHA"(p_ficha) r),
      v_f."DS_LANCAMENTO",
      private."FC_DOCUMENTAL_DO_EDITAL"(v_f."CO_MONITORAMENTO") -> 'cotas');
  end if;
  -- Antes da análise: as optadas na pré-classificação.
  select p."DS_MODALIDADES" into v_lista
    from public."TB_PRE_CLASSIFICACAO" p
   where p."CO_MONITORAMENTO" = v_f."CO_MONITORAMENTO" and p."CO_EMPREGARE_CANDIDATO" = v_f."CO_EMPREGARE_CANDIDATO";
  return private."FC_MODALIDADES_DO_LANCAMENTO"(jsonb_build_object('modalidades', coalesce(v_lista, '[]'::jsonb)));
end;
$$;

--
-- Name: FUNCTION "FC_MODALIDADES_DA_FICHA"(p_ficha uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MODALIDADES_DA_FICHA"(p_ficha uuid) IS 'As cotas da ficha para publicar, a final primeiro: antes da análise, as optadas na pré-classificação (DS_MODALIDADES); analisada (resultado, CONCLUIDA ou REVISAR), as confirmadas pelo lançamento (FC_COTAS_CONFIRMADAS com a regra da ficha e as cotas da regra de classificação). {} = ampla. Desde 20261015150000.';

--
-- Name: FC_MODALIDADES_DO_LANCAMENTO(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MODALIDADES_DO_LANCAMENTO"(p_lanc jsonb) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select coalesce(array_agg(d.codigo order by d.ordem), '{}'::text[])
    from (select distinct on (s.codigo) s.codigo, s.ordem
            from (select upper(btrim(x.valor)) as codigo, x.ordem
                    from jsonb_array_elements_text(
                           case when jsonb_typeof(p_lanc -> 'modalidades') = 'array' then p_lanc -> 'modalidades'
                                else jsonb_build_array(coalesce(p_lanc ->> 'modalidade', '')) end)
                         with ordinality x(valor, ordem)) s
           where s.codigo ~ '^[A-Z]{2,10}$' and s.codigo <> 'AC'
           order by s.codigo, s.ordem) d;
$_$;

--
-- Name: FUNCTION "FC_MODALIDADES_DO_LANCAMENTO"(p_lanc jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MODALIDADES_DO_LANCAMENTO"(p_lanc jsonb) IS 'As cotas do lançamento da ficha, na ordem (a principal primeiro): a lista modalidades ou, no lançamento antigo sem ela, a modalidade única; sem a ampla, sem repetir. {} = só a ampla. Como modalidadesDoLancamento (pontuacao.js) e modalidades_do_lancamento (pontuacao.py). Desde 20261015150000.';

--
-- Name: FC_MODALIDADES_PUBLICADAS(text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MODALIDADES_PUBLICADAS"(p_cotas text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when coalesce(cardinality(p_cotas), 0) = 0 then private."FC_MODALIDADE_PUBLICADA"('AC')
              else (select string_agg(private."FC_MODALIDADE_PUBLICADA"(c.codigo), ' | ' order by c.ordem)
                      from unnest(p_cotas) with ordinality c(codigo, ordem)) end;
$$;

--
-- Name: FUNCTION "FC_MODALIDADES_PUBLICADAS"(p_cotas text[]); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MODALIDADES_PUBLICADAS"(p_cotas text[]) IS 'As cotas (códigos) como a planilha de análises escreve modalidade_concorrencia, separadas por " | " ("Pretos e pardos | Pessoas com deficiência (PCD)"); nenhuma = "Ampla concorrência". Desde 20261015150000.';

--
-- Name: FC_MODALIDADE_PUBLICADA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MODALIDADE_PUBLICADA"(p_codigo text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case upper(btrim(coalesce(p_codigo, '')))
           when 'AC' then 'Ampla concorrência'
           when 'PP' then 'Pretos e pardos'
           when 'PI' then 'Indígenas'
           when 'PQ' then 'Quilombolas'
           when 'PCD' then 'Pessoas com deficiência (PCD)'
           else nullif(btrim(p_codigo), '')
         end;
$$;

--
-- Name: FUNCTION "FC_MODALIDADE_PUBLICADA"(p_codigo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MODALIDADE_PUBLICADA"(p_codigo text) IS 'O código de modalidade da pré-classificação (AC, PP, PI, PQ, PCD) como a planilha de análises escreve (modalidade_concorrencia); outro valor passa como está, vazio vira nulo.';

--
-- Name: FC_MONTAR_APROVADOS_AREA(text, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MONTAR_APROVADOS_AREA"(p_area text, p_editais uuid[], OUT p_listas json, OUT p_dicionarios json, OUT p_linhas json, OUT p_total integer) RETURNS record
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    SET work_mem TO '64MB'
    SET jit TO 'off'
    AS $$
begin
  with listas as (
    select l.id, l.edital_id, m.edital, m.unidade, l.ativo, l.arquivo_nome, l.importado_em,
           (row_number() over (order by m.edital, l.id) - 1)::integer as i
      from public."TB_LISTA_APROVADO" l
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
     where l.vigente is true
       and m."CO_AREA" = p_area
       and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
       and (p_editais is null or m.id = any (p_editais))
  ), cand as materialized (
    select c.id, li.i as lista, li.edital, c.cargo, c.classificacao, c.nota, c.nome,
           c.modalidade, c.status, c.processo_sei, c.matricula, c.sub_judice, c.codigo_vaga,
           c.alterado_judicialmente, c.nota_original, c.modalidade_original, c.classificacao_original
      from listas li
      join public."TB_CANDIDATO_APROVADO" c on c.lista_id = li.id
     where c.removido_em is null
  ), d_cargo as (
    select x.v, (row_number() over (order by x.v) - 1)::integer as i
      from (select distinct cargo as v from cand where cargo is not null) x
  ), d_modalidade as (
    select x.v, (row_number() over (order by x.v) - 1)::integer as i
      from (select distinct modalidade as v from cand where modalidade is not null) x
  ), d_status as (
    select x.v, (row_number() over (order by x.v) - 1)::integer as i
      from (select distinct status as v from cand where status is not null) x
  ), d_codigo as (
    select x.v, (row_number() over (order by x.v) - 1)::integer as i
      from (select distinct codigo_vaga as v from cand where codigo_vaga is not null) x
  )
  select
    (select coalesce(json_agg(json_build_array(
              li.id, li.edital_id, li.edital, li.unidade, li.ativo, li.arquivo_nome, li.importado_em
            ) order by li.i), '[]'::json)
       from listas li),
    json_build_object(
      'cargo', (select coalesce(json_agg(d.v order by d.i), '[]'::json) from d_cargo d),
      'modalidade', (select coalesce(json_agg(d.v order by d.i), '[]'::json) from d_modalidade d),
      'status', (select coalesce(json_agg(d.v order by d.i), '[]'::json) from d_status d),
      'codigo_vaga', (select coalesce(json_agg(d.v order by d.i), '[]'::json) from d_codigo d),
      -- Contratado em outra lista (20261024120000): id → [situação, motivo], só das linhas Contratado
      -- que o job decidiu (CONTRATACAO, OUTRA_LISTA ou AMBIGUO).
      'contratacao', (select coalesce(json_object_agg(x."CO_CANDIDATO_APROVADO", json_build_array(
                         x."TP_SITUACAO", x."DS_MOTIVO")), '{}'::json)
                        from public."TB_CONTRATACAO_APROVADO" x
                        join cand c on c.id = x."CO_CANDIDATO_APROVADO"
                       where c.status = 'Contratado')
    ),
    -- A ordem da função antiga; o id só desempata (antes o empate saía em qualquer ordem).
    (select coalesce(json_agg(
              case when c.alterado_judicialmente then json_build_array(
                c.id, c.lista, dc.i, c.classificacao, c.nota, c.nome, dm.i,
                ds.i, c.processo_sei, c.matricula, c.sub_judice, dv.i,
                true, c.nota_original, c.modalidade_original, c.classificacao_original
              ) else json_build_array(
                c.id, c.lista, dc.i, c.classificacao, c.nota, c.nome, dm.i,
                ds.i, c.processo_sei, c.matricula, c.sub_judice, dv.i
              ) end
            order by c.edital, c.cargo, c.classificacao nulls last, c.nome, c.id), '[]'::json)
       from cand c
       left join d_cargo dc on dc.v = c.cargo
       left join d_modalidade dm on dm.v = c.modalidade
       left join d_status ds on ds.v = c.status
       left join d_codigo dv on dv.v = c.codigo_vaga)
  into p_listas, p_dicionarios, p_linhas;

  p_total := json_array_length(p_linhas);
end;
$$;

--
-- Name: FUNCTION "FC_MONTAR_APROVADOS_AREA"(p_area text, p_editais uuid[], OUT p_listas json, OUT p_dicionarios json, OUT p_linhas json, OUT p_total integer); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MONTAR_APROVADOS_AREA"(p_area text, p_editais uuid[], OUT p_listas json, OUT p_dicionarios json, OUT p_linhas json, OUT p_total integer) IS 'Lista de aprovados da área no formato 2 (listas em array, dicionários, linhas com índices). p_editais nulo = área inteira. NÃO checa permissão.';

--
-- Name: FC_MONTAR_ENTREVISTAS_AREA(text, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MONTAR_ENTREVISTAS_AREA"(p_area text, p_editais uuid[]) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return (
    with e as (
      select e.*
        from public."TB_ENTREVISTA" e
       where e."CO_AREA" = p_area and e."ST_ATIVO" = 'S'
         and e."CO_ENTREVISTA" in (select v from private."FC_ENTREVISTAS_VIGENTES"(p_area) v)
         and not private."FC_EDITAL_EH_TREINAMENTO"(e."CO_MONITORAMENTO")
         and (e."CO_MONITORAMENTO" is null
              or exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m
                          where m.id = e."CO_MONITORAMENTO" and m.ativo))
         and (p_editais is null or e."CO_MONITORAMENTO" = any (p_editais))
    ),
    criterios as (
      select n."DS_CRITERIO" as criterio, row_number() over (order by min(n."NU_ORDEM"), n."DS_CRITERIO") - 1 as i
        from public."TB_ENTREVISTA_NOTA" n
        join e on e."CO_ENTREVISTA" = n."CO_ENTREVISTA"
       where n."VL_NOTA" is not null
       group by n."DS_CRITERIO"
    ),
    vagas as (
      select distinct e."CO_VAGA" from e
    ),
    sem_entrevista as (
      select a.id, a.candidato, a.id_origem, a.codigo_vaga, a.nome_vaga, a.edital, a.unidade,
             a.nota_final_ajustada, a.modalidade_concorrencia
        from public."TB_ANALISE_CURRICULAR" a
        join vagas v on v."CO_VAGA" = a.codigo_vaga
       where a."CO_AREA" = p_area and a.ativo
         and not private."FC_ANALISE_EH_TREINAMENTO"(a.origem_planilha)
         and a.status_consolidado = 'Aprovado'
         and not exists (select 1 from public."TB_ENTREVISTA" x
                          where x."CO_ANALISE_CURRICULAR" = a.id and x."ST_ATIVO" = 'S')
         and (p_editais is null or exists (
               select 1 from public."TB_MONITORAMENTO_INDIGENA" m
                where m.id = any (p_editais) and m."CO_AREA" = a."CO_AREA"
                  and private."FC_NUMERO_EDITAL"(m.edital) = private."FC_NUMERO_EDITAL"(a.edital)))
       order by a.edital, a.codigo_vaga, a.candidato
       limit 3000
    )
    select json_build_object(
      'schema_version', 1,
      'area', p_area,
      'gerado_em', now(),
      'ultima_carga', (
        select json_build_object('em', s."DT_FIM", 'linhas', s."QT_LINHA",
                                 'ligadas_analise', s."QT_LIGADA_ANALISE",
                                 'sem_analise', s."QT_SEM_ANALISE", 'sem_edital', s."QT_SEM_EDITAL")
          from public."TL_SYNC_ENTREVISTA" s
         where s."CO_AREA" = p_area and s."TP_SITUACAO" = 'CONCLUIDA'
         order by s."DT_FIM" desc limit 1
      ),
      'criterios', (select coalesce(json_agg(c.criterio order by c.i), '[]'::json) from criterios c),
      'entrevistas', (
        select coalesce(json_agg(json_build_object(
            'id', e."CO_ENTREVISTA",
            'edital_id', e."CO_MONITORAMENTO",
            'edital', coalesce(m.edital, e."DS_EDITAL"),
            'edital_planilha', e."DS_EDITAL",
            'unidade', coalesce(m.unidade, e."NO_UNIDADE"),
            'vaga', e."CO_VAGA",
            'cargo', coalesce(a.nome_vaga, e."NO_CARGO"),
            'candidato', e."NO_CANDIDATO",
            'codigo', e."CO_CANDIDATO",
            'modalidade', coalesce(a.modalidade_concorrencia, e."DS_MODALIDADE"),
            'nota', e."VL_NOTA_TOTAL",
            'parecer', e."TP_PARECER",
            'compareceu', e."ST_COMPARECEU",
            'origem', e."TP_ORIGEM",
            'atualizado_em', e."DT_ATUALIZACAO",
            'link', e."DS_LINK_PLANILHA",
            'notas', (
              select coalesce(json_agg(json_build_array(c.i, n."VL_NOTA") order by n."NU_ORDEM"), '[]'::json)
                from public."TB_ENTREVISTA_NOTA" n
                join criterios c on c.criterio = n."DS_CRITERIO"
               where n."CO_ENTREVISTA" = e."CO_ENTREVISTA" and n."VL_NOTA" is not null
            ),
            'analise', case when a.id is null then null else json_build_object(
              'id', a.id,
              'ligacao', e."TP_LIGACAO_ANALISE",
              'nota', a.nota_final_ajustada,
              'resultado', a.status_consolidado,
              'etapa', a.etapa,
              'responsavel', a.responsavel_analise,
              'ativo', a.ativo
            ) end
          ) order by coalesce(m.edital, e."DS_EDITAL"), e."CO_VAGA", e."VL_NOTA_TOTAL" desc nulls last, e."NO_CANDIDATO"), '[]'::json)
          from e
          left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = e."CO_MONITORAMENTO"
          left join public."TB_ANALISE_CURRICULAR" a on a.id = e."CO_ANALISE_CURRICULAR"
      ),
      'aprovados_sem_entrevista', (
        select coalesce(json_agg(json_build_object(
            'analise_id', s.id,
            'candidato', s.candidato,
            'codigo', s.id_origem,
            'vaga', s.codigo_vaga,
            'cargo', s.nome_vaga,
            'edital', s.edital,
            'unidade', s.unidade,
            'nota', s.nota_final_ajustada,
            'modalidade', s.modalidade_concorrencia
          )), '[]'::json)
          from sem_entrevista s
      )
    )
  );
end;
$$;

--
-- Name: FUNCTION "FC_MONTAR_ENTREVISTAS_AREA"(p_area text, p_editais uuid[]); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MONTAR_ENTREVISTAS_AREA"(p_area text, p_editais uuid[]) IS 'Monta o json da aba Entrevistas de uma área; p_editais nulo = todos os editais (pacote pronto), senão só os editais da lista (recorte da coordenação). Sem checagem de permissão: quem chama checa.';

--
-- Name: FC_MONTAR_PAINEL_ANALISE(text, text[], boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MONTAR_PAINEL_ANALISE"(p_area text, p_escopos text[], p_so_visiveis boolean DEFAULT false) RETURNS TABLE("TP_ESCOPO" text, "DS_LINHAS" json, "QT_LINHAS" integer, "DS_EDITAIS" json, "DT_ULTIMA_ATUALIZACAO" timestamp with time zone, "DS_CONCLUIDAS_POR_ANO" json)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    SET work_mem TO '64MB'
    SET jit TO 'off'
    AS $$
declare
  v_area text := lower(btrim(coalesce(p_area, 'saude-indigena')));
  v_grupo text;
  v_grupos_norm text[];
  v_editais json;
  v_restrito boolean;
  v_editais_norm text[];
  v_unidades_norm text[];
begin
  if p_escopos is null or cardinality(p_escopos) = 0
     or not (p_escopos <@ array['ativo', 'inativo', 'desativadas']) then
    raise exception 'Escopo invalido. Use ativo, inativo ou desativadas.';
  end if;

  select a."NO_GRUPO_PLANILHA" into v_grupo
    from public."TB_AREA" a
   where a."CO_AREA" = v_area;
  if not found then
    raise exception 'Área inválida: %', v_area using errcode = '22023';
  end if;

  -- O mesmo recorte de FC_GRUPOS_ANALISES_DA_AREA, sem a checagem de permissão.
  v_grupos_norm := array[public.analises_norm_key(v_grupo)];

  -- Recorte por coordenação só quando pedido (a RPC, para quem tem recorte);
  -- o pacote guardado é o da área inteira.
  v_restrito := coalesce(p_so_visiveis, false) and private."FC_EDITAIS_VISIVEIS"() is not null;
  if v_restrito then
    v_editais_norm := coalesce(private."FC_EDITAIS_NORM_VISIVEIS"(), '{}');
    v_unidades_norm := coalesce(private."FC_UNIDADES_NORM_VISIVEIS"(), '{}');
  end if;

  -- Os editais da planilha e (20261009200000) os editais com a avaliação no MONITORA
  -- que a planilha não tem: a janela deles é a da avaliação documental do edital.
  select coalesce(json_agg(x.edital_json order by x.unidade, x.edital), '[]'::json)
  into v_editais
  from (
    select json_build_object(
             'grupo', e.grupo,
             'unidade', e.unidade,
             'edital', e.edital,
             'ativo', e.ativo,
             'data_inicio_analise', e.data_inicio_analise,
             'data_fim_analise', e.data_fim_analise
           ) as edital_json, e.unidade, e.edital
      from public."TB_EDITAL_ANALISE" e
     where e.grupo_norm = any (v_grupos_norm)
       and (not v_restrito
         or e.edital_norm = any (v_editais_norm)
         or e.unidade_norm = any (v_unidades_norm))
    union all
    select json_build_object(
             'grupo', v_grupo,
             'unidade', m.unidade,
             'edital', m.edital,
             'ativo', true,
             'data_inicio_analise', j.inicio,
             'data_fim_analise', j.fim
           ), m.unidade, m.edital
      from public."TB_ORIGEM_ANALISE_EDITAL" o
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = o."CO_MONITORAMENTO"
      cross join lateral private."FC_JANELA_AVALIACAO_DOCUMENTAL"(m.id) j
     where o."TP_ORIGEM" = 'MONITORA'
       and m."CO_AREA" = v_area
       and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
       and not exists (select 1 from public."TB_EDITAL_ANALISE" e
                        where e.grupo_norm = any (v_grupos_norm)
                          and private."FC_NUMERO_EDITAL"(e.edital) = private."FC_NUMERO_EDITAL"(m.edital))
       and (not v_restrito
         or coalesce(public.analises_norm_key(m.edital), '') = any (v_editais_norm)
         or coalesce(public.analises_norm_key(m.unidade), '') = any (v_unidades_norm))
  ) x;

  -- Colunas na ordem de `columns` de get_analises_dashboard_payload_v2. A ordem
  -- das linhas é a de sempre, com o id no fim para desempatar (a mesma análise
  -- repetida para o candidato trocava de lugar entre uma montagem e outra).
  return query
  with linhas as materialized (
    select
      case
        when v.edital_ativo is false then 'inativo'
        when v.ativo is true then 'ativo'
        else 'desativadas'
      end as escopo,
      v.id, v.unidade, v.edital, v.codigo_vaga, v.candidato,
      v.status_consolidado, v.data_analise,
      coalesce(v.updated_at, v.ultima_atualizacao) as atualizado_em,
      json_build_array(
        v.id, v.unidade, v.edital, v.codigo_vaga, v.nome_vaga, v.candidato,
        v.categoria, v.modalidade_concorrencia, v.status_consolidado, v.etapa,
        v.responsavel_analise, v.data_analise, v.nota_final_ajustada,
        v.pdf_status, nullif(btrim(v.link_pdf), '') is not null
      ) as linha
    from public."VW_ANALISES_DASHBOARD_BASE_TODOS" v
    join public."TB_ANALISE_CURRICULAR" ac on ac.id = v.id
    where ac.grupo_norm = any (v_grupos_norm)
      and (not v_restrito
        or ac.edital_norm = any (v_editais_norm)
        or ac.unidade_norm = any (v_unidades_norm))
  ),
  agregado as (
    select l.escopo,
           json_agg(l.linha order by l.unidade, l.edital, l.codigo_vaga, l.candidato, l.id) as linhas,
           count(*)::integer as total,
           max(l.atualizado_em) as atualizado_em
      from linhas l
     where l.escopo = any (p_escopos)
     group by l.escopo
  ),
  concluidas as (
    select q.escopo, json_object_agg(q.ano, q.total order by q.ano) as por_ano
      from (
        select l.escopo,
               coalesce(extract(year from l.data_analise)::integer::text, 'sem_data') as ano,
               count(*)::integer as total
          from linhas l
         where l.escopo = any (p_escopos)
           and l.status_consolidado in ('Aprovado', 'Reprovado')
         group by 1, 2
      ) q
     group by q.escopo
  )
  select pedido.escopo, coalesce(a.linhas, '[]'::json), coalesce(a.total, 0), v_editais,
         a.atualizado_em, coalesce(c.por_ano, '{}'::json)
    from unnest(p_escopos) as pedido(escopo)
    left join agregado a on a.escopo = pedido.escopo
    left join concluidas c on c.escopo = pedido.escopo;
end;
$$;

--
-- Name: FUNCTION "FC_MONTAR_PAINEL_ANALISE"(p_area text, p_escopos text[], p_so_visiveis boolean); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MONTAR_PAINEL_ANALISE"(p_area text, p_escopos text[], p_so_visiveis boolean) IS 'Monta o painel de análises da área por escopo (linhas compactas, editais, total, última atualização e concluídas por ano). Sem checagem de permissão: só atualizar_cache_painel_analises e get_analises_dashboard_payload_v2 chamam.';

--
-- Name: FC_MOTIVO_COM_SENTIDO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MOTIVO_COM_SENTIDO"(p_motivo text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  with t as (select lower(btrim(coalesce(p_motivo, ''))) as m),
  p as (
    select regexp_replace(w, '[^[:alpha:]]', '', 'g') as letras
      from t, regexp_split_to_table(t.m, '\s+') w
     where w <> ''
  )
  select length(t.m) between 15 and 500
     and (select count(*) from p) >= 3
     and (select count(*) from p
           where length(p.letras) >= 3
             and p.letras ~ '[aeiouyáàâãäéèêëíìîïóòôõöúùûü]'
             and p.letras !~ '[^aeiouyáàâãäéèêëíìîïóòôõöúùûü]{5}'
             and p.letras !~ '(.)\1\1') >= 2
     and (select count(distinct c) from p, regexp_split_to_table(p.letras, '') c where c <> '') >= 5
    from t;
$$;

--
-- Name: FUNCTION "FC_MOTIVO_COM_SENTIDO"(p_motivo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MOTIVO_COM_SENTIDO"(p_motivo text) IS 'Motivo com sentido (20261103213000): 15 a 500 caracteres, 3 palavras ou mais, ao menos 2 palavras de verdade (3+ letras, com vogal, sem 5 consoantes nem 3 letras iguais seguidas) e 5 letras diferentes. Recusa teclado batido. A tela usa a mesma regra (src/lib/chaves-da-automacao.ts).';

--
-- Name: FC_MOTIVO_PARECE_TEXTO(text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MOTIVO_PARECE_TEXTO"(p_texto text, p_minimo_palavras integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select lower(coalesce(p_texto, '')) !~ '([[:alpha:]])\1{3,}'
     and (select count(distinct w)
            from regexp_split_to_table(lower(coalesce(p_texto, '')), '[^[:alpha:]]+') w
           where length(w) >= 2
             and (length(w) <= 3
                  or length(regexp_replace(w, '[^aeiouáàâãéêíóôõúü]', '', 'g')) * 5 >= length(w))
         ) >= coalesce(p_minimo_palavras, 1);
$$;

--
-- Name: FUNCTION "FC_MOTIVO_PARECE_TEXTO"(p_texto text, p_minimo_palavras integer); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MOTIVO_PARECE_TEXTO"(p_texto text, p_minimo_palavras integer) IS 'Motivo que parece texto (20261021110000): sem letra repetida 4 vezes seguidas e com pelo menos N palavras diferentes (2+ letras; até 3 letras ou vogais em 1 de cada 5). O mesmo que motivoPareceTexto (src/lib/avaliacao-documental/qualidade-do-motivo.ts).';

--
-- Name: FC_MOTIVO_REABERTURA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MOTIVO_REABERTURA"(p_codigo text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_codigo
    when 'EXPERIENCIA' then 'Correção de experiência'
    when 'CURSOS' then 'Correção de cursos'
    when 'FORMACAO' then 'Correção de formação/titulação'
    when 'REQUISITO' then 'Correção de escolaridade ou requisito do cargo'
    when 'IDENTIDADE' then 'Correção de documento de identificação'
    when 'COTA' then 'Correção de cota (PP/PI/PQ/PcD)'
    when 'ETNICO' then 'Correção do critério étnico'
    when 'DOCUMENTO_NOVO' then 'Documento novo da Empregare'
    when 'RECURSO' then 'Decisão de recurso'
    when 'COORDENACAO' then 'Pedido da coordenação ou revisão'
    when 'DIGITACAO' then 'Erro de digitação ou lançamento'
    when 'OUTRO' then 'Outro'
  end;
$$;

--
-- Name: FUNCTION "FC_MOTIVO_REABERTURA"(p_codigo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MOTIVO_REABERTURA"(p_codigo text) IS 'Rótulo do motivo de reabertura da ficha pelo código (lista fixa, 20261021110000), ou null fora da lista. Os mesmos de MOTIVOS_DA_REABERTURA (src/lib/avaliacao-documental/motivos-da-reabertura.ts).';

--
-- Name: FC_MOTIVO_RECUSA_SOLICITACAO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_MOTIVO_RECUSA_SOLICITACAO"(p_codigo text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select m.rotulo
    from (values
      ('FORA_DO_PUBLICO', 'Não faz parte do público do MONITORA'),
      ('VINCULO_NAO_CONFIRMADO', 'Vínculo com a área não confirmado'),
      ('AREA_OU_LOTACAO', 'Área ou lotação não confere'),
      ('JA_TEM_ACESSO', 'Já tem acesso por outra conta'),
      ('JUSTIFICATIVA_INSUFICIENTE', 'Justificativa insuficiente'),
      ('OUTRO', 'Outro')
    ) as m(codigo, rotulo)
   where m.codigo = p_codigo;
$$;

--
-- Name: FUNCTION "FC_MOTIVO_RECUSA_SOLICITACAO"(p_codigo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_MOTIVO_RECUSA_SOLICITACAO"(p_codigo text) IS 'Rótulo do motivo de recusa do pedido de acesso. A mesma lista de MOTIVOS_DE_RECUSA (src/lib/solicitacao-de-acesso.ts).';

--
-- Name: FC_NIVEL_AVALIACAO_DO_PERFIL(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NIVEL_AVALIACAO_DO_PERFIL"(p_perfil_usuario uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select private."FC_RANK_NIVEL"(private."FC_NIVEL_EFETIVO"(u.id, u.perfil, 'avaliacao_documental'))
      from public."TB_PERFIL_USUARIO" u
     where u.id = p_perfil_usuario and u.ativo), 0);
$$;

--
-- Name: FUNCTION "FC_NIVEL_AVALIACAO_DO_PERFIL"(p_perfil_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NIVEL_AVALIACAO_DO_PERFIL"(p_perfil_usuario uuid) IS 'Nível de um usuário ativo em avaliacao_documental: 0 sem acesso, 1 leitor, 2 editor, 3 administrador.';

--
-- Name: FC_NIVEL_DO_GRUPO(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NIVEL_DO_GRUPO"(p_grupo text, p_recurso text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select t."TP_NIVEL" from public."TA_GRUPO_ACESSO_RECURSO" t
      where t."CO_GRUPO_ACESSO" = p_grupo and t."NO_RECURSO" = p_recurso),
    'sem_acesso');
$$;

--
-- Name: FUNCTION "FC_NIVEL_DO_GRUPO"(p_grupo text, p_recurso text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NIVEL_DO_GRUPO"(p_grupo text, p_recurso text) IS 'Nível do módulo no grupo de acesso; sem linha (ou painel externo) = sem_acesso.';

--
-- Name: FC_NIVEL_EFETIVO(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NIVEL_EFETIVO"(p_perfil_usuario uuid, p_grupo text, p_recurso text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- Administrador global faz tudo: o maior nível, acima da permissão individual e do grupo.
  select case
    when exists (select 1 from public."TB_GRUPO_ACESSO" a
                  where a."CO_GRUPO_ACESSO" = p_grupo and a."ST_ADMIN_GLOBAL") then 'admin'
    else coalesce(
      (select g.nivel from public."TB_PERMISSAO_RECURSO" g
        where g.perfil_usuario_id = p_perfil_usuario and g.recurso = p_recurso),
      private."FC_NIVEL_DO_GRUPO"(p_grupo, p_recurso))
  end;
$$;

--
-- Name: FUNCTION "FC_NIVEL_EFETIVO"(p_perfil_usuario uuid, p_grupo text, p_recurso text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NIVEL_EFETIVO"(p_perfil_usuario uuid, p_grupo text, p_recurso text) IS 'Nível efetivo de um usuário: administrador global (grupo ST_ADMIN_GLOBAL) = admin; senão a exceção (TB_PERMISSAO_RECURSO) ?? o nível do grupo.';

--
-- Name: FC_NOME_DA_VERSAO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NOME_DA_VERSAO"(p_nome text) RETURNS character varying
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_nome text := nullif(regexp_replace(btrim(coalesce(p_nome, '')), '\s+', ' ', 'g'), '');
begin
  if v_nome is not null and length(v_nome) not between 3 and 80 then
    raise exception 'Nome da versão: de 3 a 80 caracteres.' using errcode = '22023';
  end if;
  return v_nome;
end;
$$;

--
-- Name: FUNCTION "FC_NOME_DA_VERSAO"(p_nome text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NOME_DA_VERSAO"(p_nome text) IS 'Nome da versão normalizado (sem espaço nas pontas, espaços seguidos viram um); vazio = nulo (sem nome). Fora de 3 a 80 caracteres = 22023.';

--
-- Name: FC_NOME_DO_RESPONSAVEL(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NOME_DO_RESPONSAVEL"(p_texto text, p_grupo text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_norm text := private."FC_NOME_NORMALIZADO"(p_texto);
  v_area text;
  v_nome text;
begin
  if v_norm is null then
    return p_texto;
  end if;
  select a."CO_AREA" into v_area
    from public."TB_AREA" a
   where private."FC_NOME_NORMALIZADO"(a."NO_GRUPO_PLANILHA") = private."FC_NOME_NORMALIZADO"(p_grupo)
   limit 1;
  -- 1. apelido ativo (o da área vence o geral).
  select p.nome into v_nome
    from public."TB_APELIDO_RESPONSAVEL" ap
    join public."TB_PERFIL_USUARIO" p on p.id = ap."CO_PERFIL_USUARIO"
   where ap."DS_APELIDO_NORMALIZADO" = v_norm
     and ap."ST_ATIVO" = 'S'
     and (ap."CO_AREA" is null or ap."CO_AREA" = v_area)
   order by ap."CO_AREA" is null
   limit 1;
  -- 2. nome completo idêntico ao de um (e só um) perfil ativo.
  if v_nome is null then
    select case when count(*) = 1 then min(p.nome) end into v_nome
      from public."TB_PERFIL_USUARIO" p
     where p.ativo and private."FC_NOME_NORMALIZADO"(p.nome) = v_norm;
  end if;
  -- 3. sem cadastro: o texto original.
  return coalesce(private."FC_NOME_E_SOBRENOME"(v_nome), p_texto);
end;
$$;

--
-- Name: FUNCTION "FC_NOME_DO_RESPONSAVEL"(p_texto text, p_grupo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NOME_DO_RESPONSAVEL"(p_texto text, p_grupo text) IS 'Responsável pela análise como o painel mostra: apelido de TB_APELIDO_RESPONSAVEL (da área do grupo ou geral) → nome e sobrenome do perfil; senão nome completo de um perfil ativo → nome e sobrenome; senão o texto original (nunca apaga). Desde 20261016120000.';

--
-- Name: FC_NOME_E_SOBRENOME(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NOME_E_SOBRENOME"(p_nome text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  with t as (
    select regexp_split_to_array(btrim(regexp_replace(p_nome, '\s+', ' ', 'g')), ' ') as a
  )
  select case
           when nullif(btrim(p_nome), '') is null then null
           else t.a[1] || coalesce(' ' || (
             select u.x
               from unnest(t.a) with ordinality as u(x, i)
              where u.i > 1 and lower(u.x) not in ('de', 'da', 'do', 'dos', 'das', 'e')
              order by u.i desc
              limit 1), '')
         end
    from t;
$$;

--
-- Name: FUNCTION "FC_NOME_E_SOBRENOME"(p_nome text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NOME_E_SOBRENOME"(p_nome text) IS 'Nome e sobrenome de um nome completo: o primeiro nome e o último sobrenome, sem partículas (de, da, do, dos, das, e). "Ana Lilian de Matos Pereira" → "Ana Pereira". Nulo se vazio. Desde 20261016120000.';

--
-- Name: FC_NOME_NORMALIZADO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NOME_NORMALIZADO"(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select nullif(btrim(regexp_replace(
           translate(lower(p_texto),
                     'áàâãäéèêëíìîïóòôõöúùûüçñ',
                     'aaaaaeeeeiiiiooooouuuucn'),
           '\s+', ' ', 'g')), '');
$$;

--
-- Name: FUNCTION "FC_NOME_NORMALIZADO"(p_texto text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NOME_NORMALIZADO"(p_texto text) IS 'Chave de comparação de nomes de pessoa: minúsculas, sem acento, espaços colapsados; nulo se vazio. Desde 20261016120000.';

--
-- Name: FC_NOME_USUARIO(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NOME_USUARIO"(p_usuario uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(nullif(btrim(p.nome), ''), p.email)
  from public."TB_PERFIL_USUARIO" p
  where p.user_id = p_usuario
  order by p.updated_at desc nulls last
  limit 1;
$$;

--
-- Name: FUNCTION "FC_NOME_USUARIO"(p_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NOME_USUARIO"(p_usuario uuid) IS 'Nome (ou e-mail) de quem tem o auth.users.id informado, para o histórico e as etapas do recurso.';

--
-- Name: FC_NOME_VAGA_PUBLICADA(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NOME_VAGA_PUBLICADA"(p_edital uuid, p_vaga text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select nullif(concat_ws(' - ', nullif(btrim(pv."NO_CARGO"), ''), nullif(btrim(pv."NO_LOTACAO"), '')), '')
    from public."TB_PRE_CLASSIF_VAGA" pv
   where pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" = p_vaga;
$$;

--
-- Name: FUNCTION "FC_NOME_VAGA_PUBLICADA"(p_edital uuid, p_vaga text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NOME_VAGA_PUBLICADA"(p_edital uuid, p_vaga text) IS 'O nome da vaga como a planilha de análises escreve (nome_vaga): "cargo - lotação" da pré-classificação da vaga (TB_PRE_CLASSIF_VAGA); nulo sem os dois. Desde 20261015151000.';

--
-- Name: FC_NORMALIZAR_GRAFIA_CARGO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NORMALIZAR_GRAFIA_CARGO"(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $_$
  select nullif(
    regexp_replace(
      regexp_replace(
        upper(translate(p_texto, E'áàâãäéèêëíìîïóòôõöúùûüçñýÿÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑÝºª–—‐‑−“”„‘’´\u00a0\u2007\u202f\u0009\u000d\u000a\u200b\u200c\u200d\ufeff\u00ad\u200e\u200f\u2060\u2063', 'aaaaaeeeeiiiiooooouuuucnyyAAAAAEEEEIIIIOOOOOUUUUCNYOA-----"""''''''      ')),
        ' {2,}', ' ', 'g'),
      '^[ .,;:_/|*"''`-]+|[ .,;:_/|*"''`-]+$', '', 'g'),
    '');
$_$;

--
-- Name: FUNCTION "FC_NORMALIZAR_GRAFIA_CARGO"(p_texto text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NORMALIZAR_GRAFIA_CARGO"(p_texto text) IS 'Grafia normalizada de um cargo: sem acento e cedilha, traços e aspas simples, invisíveis apagados, maiúsculas, espaços únicos, sem pontuação nas pontas (parênteses ficam); vazio vira nulo. Cópia fiel em python/monitora/cargos/normalizacao.py. 20261104150000.';

--
-- Name: FC_NOVOS_DA_CLASSIFICACAO(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NOVOS_DA_CLASSIFICACAO"(p_lista_classificacao uuid, p_lista_vigente uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_l public."TB_LISTA_CLASSIFICACAO";
  v_novos jsonb;
begin
  select * into v_l from public."TB_LISTA_CLASSIFICACAO" where "CO_LISTA_CLASSIFICACAO" = p_lista_classificacao;
  if v_l."CO_LISTA_CLASSIFICACAO" is null then
    raise exception 'Lista de classificação não encontrada' using errcode = '22023';
  end if;
  if v_l."TP_LISTA" <> 'FINAL' then
    raise exception 'Só o resultado final vira lista de aprovados.' using errcode = '22023';
  end if;
  if v_l."QT_PENDENCIA" > 0 then
    raise exception 'A lista tem empate pendente de sorteio ou decisão; resolva e gere de novo.' using errcode = '22023';
  end if;
  if exists (
    select 1 from public."TB_LISTA_CLASSIFICACAO" o
     where o."CO_MONITORAMENTO" = v_l."CO_MONITORAMENTO" and o."TP_LISTA" = 'FINAL'
       and o."DT_GERACAO" > v_l."DT_GERACAO"
  ) then
    raise exception 'Há um resultado final gerado depois deste; publique o mais recente.' using errcode = '22023';
  end if;
  if exists (select 1 from public."TB_LISTA_APROVADO" a
              where a.id = p_lista_vigente and a."CO_LISTA_CLASSIFICACAO" = p_lista_classificacao) then
    raise exception 'Este resultado final já é a lista de aprovados vigente.' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_CANDIDATOS_DO_EDITAL"(v_l."CO_MONITORAMENTO", v_l."DS_RESULTADO");

  -- Um por análise (a posição da geral; quem só está na lista da modalidade, a dela; a
  -- primeira vaga em que aparece) — a mesma montagem de antes (20261005160000).
  select coalesce(jsonb_agg(jsonb_build_object(
           'chave', y.analise_id::text, 'analise_id', y.analise_id, 'nome', y.nome, 'cargo', y.cargo,
           'codigo_vaga', y.codigo_vaga, 'posicao', y.posicao, 'nota', y.nota, 'situacao', y.situacao,
           'modalidade', y.modalidade, 'ordem', y.ordem) order by y.ordem), '[]'::jsonb)
    into v_novos
    from (
      select z.*, row_number() over (order by z.vaga_ordem, z.posicao, z.nome) as ordem
        from (
          select distinct on (x.analise_id)
                 x.analise_id, x.nome,
                 coalesce(x.cargo_vaga, nullif(btrim(a.nome_vaga), ''), 'Sem cargo') as cargo,
                 coalesce(x.codigo_vaga, nullif(btrim(a.codigo_vaga), ''), x.chave) as codigo_vaga,
                 x.posicao, x.nota, x.situacao,
                 coalesce(nullif(btrim(a.modalidade_concorrencia), ''), x.modalidades, 'Ampla Concorrência') as modalidade,
                 x.vaga_ordem
            from (
              select (f.linha ->> 'analise_id')::uuid as analise_id,
                     btrim(f.linha ->> 'nome') as nome,
                     nullif(btrim(v.vaga ->> 'cargo'), '') as cargo_vaga,
                     nullif(btrim(v.vaga ->> 'codigo'), '') as codigo_vaga,
                     v.vaga ->> 'chave' as chave,
                     case when jsonb_typeof(f.linha -> 'posicao') = 'number' then (f.linha ->> 'posicao')::numeric::integer end as posicao,
                     case when jsonb_typeof(f.linha -> 'nota') = 'number' then (f.linha ->> 'nota')::numeric end as nota,
                     case when f.linha ->> 'situacao' in ('VAGA', 'CR') then f.linha ->> 'situacao' end as situacao,
                     (select string_agg(coalesce(md.valor ->> 'nome', c.codigo), '; ' order by c.ordem)
                        from jsonb_array_elements_text(
                               case when jsonb_typeof(f.linha -> 'modalidades') = 'array' then f.linha -> 'modalidades' else '[]'::jsonb end
                             ) with ordinality c(codigo, ordem)
                        left join jsonb_array_elements(coalesce(v_l."DS_RESULTADO" -> 'modalidades', '[]'::jsonb)) md(valor)
                          on md.valor ->> 'codigo' = c.codigo
                       where c.codigo <> 'AC') as modalidades,
                     v.ordem as vaga_ordem,
                     f.fonte
                from jsonb_array_elements(v_l."DS_RESULTADO" -> 'vagas') with ordinality v(vaga, ordem)
                cross join lateral (
                  select 0 as fonte, g.linha
                    from jsonb_array_elements(coalesce(v.vaga -> 'geral', '[]'::jsonb)) g(linha)
                  union all
                  select 1, m.linha
                    from jsonb_each(coalesce(v.vaga -> 'listas', '{}'::jsonb)) e(codigo, linhas)
                    cross join lateral jsonb_array_elements(e.linhas) m(linha)
                ) f
               where f.linha ->> 'analise_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            ) x
            left join public."TB_ANALISE_CURRICULAR" a on a.id = x.analise_id
           order by x.analise_id, x.vaga_ordem, x.fonte, x.posicao nulls last
        ) z
    ) y;

  if jsonb_array_length(v_novos) = 0 then
    raise exception 'O resultado final não tem candidatos para publicar.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(v_novos) n(v)
              where (n.v ->> 'posicao') is null or (n.v ->> 'posicao')::integer < 1
                 or (n.v ->> 'nota') is null or (n.v ->> 'nota')::numeric < 0
                 or nullif(n.v ->> 'nome', '') is null) then
    raise exception 'O resultado final tem candidato sem posição, nota ou nome; gere de novo.' using errcode = '22023';
  end if;
  return v_novos;
end;
$_$;

--
-- Name: FUNCTION "FC_NOVOS_DA_CLASSIFICACAO"(p_lista_classificacao uuid, p_lista_vigente uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NOVOS_DA_CLASSIFICACAO"(p_lista_classificacao uuid, p_lista_vigente uuid) IS 'Quem entra pela Classificação, montado do retrato gravado do resultado final (um por análise), com as conferências de antes: só o FINAL mais recente, sem empate pendente, candidatos do edital, nem a lista que já é a vigente. 20261030090000.';

--
-- Name: FC_NO_NUCLEO_DA_FILA(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NO_NUCLEO_DA_FILA"(p_situacao_pre text, p_situacao_ficha text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(p_situacao_pre in ('NO_LOTE', 'ANALISADO'), false)
      or coalesce(p_situacao_ficha, 'FORA_LOTE') <> 'FORA_LOTE';
$$;

--
-- Name: FUNCTION "FC_NO_NUCLEO_DA_FILA"(p_situacao_pre text, p_situacao_ficha text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NO_NUCLEO_DA_FILA"(p_situacao_pre text, p_situacao_ficha text) IS 'Fila da avaliação documental: o inscrito está no núcleo (vai em toda leitura da fila) quando está no lote (NO_LOTE/ANALISADO) ou tem ficha que não está FORA_LOTE; os outros (eliminados e ranqueados sem ficha viva) vêm sob demanda por obter_fila_fora_do_lote.';

--
-- Name: FC_NUMERO_DO_CARGO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NUMERO_DO_CARGO"(p_texto text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select (substring(private."FC_TEXTO_DO_CARGO"(p_texto) from '^cargo (?:n |no )?([0-9]{1,3})(?: |$)'))::integer;
$_$;

--
-- Name: FUNCTION "FC_NUMERO_DO_CARGO"(p_texto text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NUMERO_DO_CARGO"(p_texto text) IS 'O número do cargo no começo do texto ("CARGO 15: MOTORISTA…", "Cargo nº 3 - …" → 15, 3); null sem número (20261013140000).';

--
-- Name: FC_NUMERO_EDITAL(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NUMERO_EDITAL"(p_texto text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  -- "06/2026", "6/2026 (sanitarista)", "Edital 06/2026" -> "6/2026"
  select ltrim(m[1], '0') || '/' || m[2]
    from regexp_match(coalesce(p_texto, ''), '(\d{1,4})\s*/\s*(\d{4})') m;
$$;

--
-- Name: FUNCTION "FC_NUMERO_EDITAL"(p_texto text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_NUMERO_EDITAL"(p_texto text) IS 'Número do edital sem zero à esquerda e sem complemento (06/2026 (sanitarista) -> 6/2026), para ligar textos de edital diferentes.';

--
-- Name: FC_NUMERO_OU_ZERO(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_NUMERO_OU_ZERO"(p_valor jsonb) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when jsonb_typeof(p_valor) = 'number' then (p_valor #>> '{}')::numeric else 0 end;
$$;

--
-- Name: FC_PAINEIS_RODADA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PAINEIS_RODADA"(p_cache text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c_workflow constant text := 'pacotes-dos-paineis.yml';
  v_vencida record;
  v_ultimo_situacao text;
  v_ultimo_em timestamptz;
  v_reserva text[] := '{}';
  v_pedir boolean := false;
  v_disparo bigint;
  v_situacao text;
  v_area text;
  v_resposta jsonb := '[]'::jsonb;
begin
  if p_cache is null or p_cache not in ('ANALISES', 'APROVADOS', 'ENTREVISTAS') then
    raise exception 'Cache desconhecido: %', p_cache using errcode = '22023';
  end if;

  -- O último pedido do job nos últimos 30 min.
  select d."TP_SITUACAO", d."DT_DISPARO" into v_ultimo_situacao, v_ultimo_em
    from public."TL_DISPARO_ROBO" d
   where d."NO_WORKFLOW" = c_workflow and d."DT_DISPARO" > now() - interval '30 minutes'
   order by d."DT_DISPARO" desc, d."CO_DISPARO" desc limit 1;

  for v_vencida in select * from private."FC_PAINEIS_VENCIDOS"(p_cache) loop
    -- Reserva: sem pacote (a tela montaria a cada abertura), o job não deu conta em 30 min
    -- (marca) ou em 1 h (pacote de mais de 24 h), ou o último pedido não chegou ao GitHub.
    if v_vencida."TP_MOTIVO" = 'SEM_PACOTE'
       or (v_vencida."TP_MOTIVO" = 'MARCA' and v_vencida."DT_DESDE" < now() - interval '30 minutes')
       or (v_vencida."TP_MOTIVO" = 'VELHO' and v_vencida."DT_DESDE" < now() - interval '25 hours')
       or coalesce(v_ultimo_situacao, '') in ('FALHOU', 'SEM_TOKEN') then
      v_reserva := v_reserva || v_vencida."CO_AREA";
    else
      v_pedir := true;
    end if;
  end loop;

  -- Pede o job (ele monta tudo o que estiver desatualizado), sem repetir um pedido de 4 min atrás.
  if v_pedir and not (coalesce(v_ultimo_situacao, '') in ('PEDIDO', 'ACEITO')
                      and v_ultimo_em > now() - interval '4 minutes') then
    v_disparo := private."FC_DISPARAR_ROBO"(c_workflow, '{"modo": "normal"}'::jsonb, p_origem => 'AGENDA');
    select d."TP_SITUACAO" into v_situacao from public."TL_DISPARO_ROBO" d where d."CO_DISPARO" = v_disparo;
    -- Sem a chave do GitHub ou com o pg_net recusando: a reserva monta já.
    if v_situacao in ('FALHOU', 'SEM_TOKEN') then
      select coalesce(array_agg(v."CO_AREA"), '{}') into v_reserva from private."FC_PAINEIS_VENCIDOS"(p_cache) v;
    end if;
  end if;

  -- A reserva: as montagens de sempre, no banco, só para as áreas da reserva. Com a trava da
  -- gravação do job (paineis_gravar_pacote) até o commit: uma gravação do job não passa no meio
  -- e a montagem que começa depois dela sempre é a mais nova.
  foreach v_area in array v_reserva loop
    perform pg_advisory_xact_lock(hashtext('paineis_gravar:' || p_cache || ':' || v_area)::bigint);
    v_resposta := v_resposta || case p_cache
      when 'ANALISES' then public.atualizar_cache_painel_analises(v_area)
      when 'APROVADOS' then public.atualizar_cache_aprovados(v_area)
      else coalesce(public.atualizar_cache_painel_entrevistas(v_area) -> 'falhas', '[]'::jsonb)
    end;
  end loop;

  return jsonb_build_object('cache', p_cache, 'pediu', v_pedir, 'disparo', v_disparo,
                            'situacao_do_pedido', v_situacao, 'reserva', to_jsonb(v_reserva),
                            'falhas', private."FC_FALHAS_DO_CACHE"(case when p_cache = 'ENTREVISTAS'
                                                                      then jsonb_build_object('falhas', v_resposta)
                                                                      else v_resposta end));
end;
$$;

--
-- Name: FUNCTION "FC_PAINEIS_RODADA"(p_cache text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PAINEIS_RODADA"(p_cache text) IS 'Uma rodada dos pacotes dos painéis: pede o job Python pacotes-dos-paineis.yml quando há área desatualizada (sem repetir pedido de 4 min); monta no banco (atualizar_cache_*) só na reserva — sem pacote, marca de mais de 30 min, pacote de mais de 25 h ou último pedido FALHOU/SEM_TOKEN. Devolve { pediu, disparo, situacao_do_pedido, reserva, falhas }. 20261029180000.';

--
-- Name: FC_PAINEIS_VENCIDOS(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PAINEIS_VENCIDOS"(p_cache text) RETURNS TABLE("CO_AREA" text, "TP_MOTIVO" text, "DT_DESDE" timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- O critério das rodadas de sempre (atualizar_cache_*_vencidos): marca, sem pacote (na
  -- análise, sem um dos três escopos) ou pacote de mais de 24 h. DT_DESDE: a marca mais antiga,
  -- ou a geração do pacote mais velho.
  with pacote as (
    select a."CO_AREA",
           case p_cache
             when 'ANALISES' then (select case when count(*) < 3 then null else min(c."DT_GERACAO") end
                                     from private."TA_PAINEL_ANALISE" c
                                    where c."CO_AREA" = a."CO_AREA"
                                      and c."TP_ESCOPO" in ('ativo', 'inativo', 'desativadas'))
             when 'APROVADOS' then (select c."DT_GERACAO" from private."TA_CANDIDATO_APROVADO_AREA" c
                                     where c."CO_AREA" = a."CO_AREA")
             when 'ENTREVISTAS' then (select c."DT_GERACAO" from private."TA_PAINEL_ENTREVISTA" c
                                       where c."CO_AREA" = a."CO_AREA")
           end as gerado_em,
           (select min(t."DT_ALTERACAO") from private."TL_ALTERACAO_CACHE" t
             where t."TP_CACHE" = p_cache and t."CO_AREA" = a."CO_AREA") as marca_desde
      from public."TB_AREA" a
     where p_cache in ('ANALISES', 'APROVADOS', 'ENTREVISTAS')
  )
  select p."CO_AREA",
         case when p.gerado_em is null then 'SEM_PACOTE'
              when p.marca_desde is not null then 'MARCA'
              else 'VELHO' end,
         case when p.gerado_em is null then null
              when p.marca_desde is not null then p.marca_desde
              else p.gerado_em end
    from pacote p
   where p.gerado_em is null
      or p.marca_desde is not null
      or p.gerado_em < now() - interval '24 hours'
   order by p."CO_AREA";
$$;

--
-- Name: FUNCTION "FC_PAINEIS_VENCIDOS"(p_cache text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PAINEIS_VENCIDOS"(p_cache text) IS 'Áreas com o pacote do painel desatualizado (ANALISES, APROVADOS ou ENTREVISTAS): SEM_PACOTE, MARCA (TL_ALTERACAO_CACHE; DT_DESDE = a mais antiga) ou VELHO (mais de 24 h; DT_DESDE = a geração). O critério das rodadas atualizar_cache_*_vencidos. 20261029180000.';

--
-- Name: FC_PAPEL_AVALIACAO(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PAPEL_AVALIACAO"(p_edital uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_perfil public."TB_PERFIL_USUARIO";
  v_nivel integer;
begin
  if (select auth.uid()) is null then return null; end if;
  if private.is_master() then return 'COORDENADOR'; end if;
  v_perfil := private.current_profile();
  if v_perfil.id is null or v_perfil.ativo is not true or not private."FC_PODE_VER_EDITAL"(p_edital) then
    return null;
  end if;
  v_nivel := private."FC_RANK_NIVEL"(private.nivel_recurso('avaliacao_documental'));
  if v_nivel >= 3 and (private."FC_GESTOR_DO_EDITAL"(v_perfil.id, p_edital)
                       or exists (select 1 from public."RL_ANALISTA_EDITAL" r
                                   where r."CO_MONITORAMENTO" = p_edital and r."CO_USUARIO" = v_perfil.user_id
                                     and r."TP_PAPEL" = 'COORDENADOR' and r."ST_ATIVO" = 'S')) then
    return 'COORDENADOR';
  end if;
  if v_nivel >= 2 then
    return (select r."TP_PAPEL" from public."RL_ANALISTA_EDITAL" r
             where r."CO_MONITORAMENTO" = p_edital and r."CO_USUARIO" = v_perfil.user_id
               and r."TP_PAPEL" in ('REVISOR', 'ANALISTA') and r."ST_ATIVO" = 'S'
             order by r."TP_PAPEL" = 'REVISOR' desc limit 1);
  end if;
  return null;
end;
$$;

--
-- Name: FUNCTION "FC_PAPEL_AVALIACAO"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PAPEL_AVALIACAO"(p_edital uuid) IS 'Papel de quem está logado na avaliação documental do edital: COORDENADOR (administrador global; ou Administrador que é gestor do edital ou coordenador na equipe), REVISOR, ANALISTA (com Editor e a linha na equipe) ou nulo.';

