                     when 'CURSOS' then 'CURSOS' when 'VINCULOS' then 'EXPERIENCIA' end;
$$;

--
-- Name: FUNCTION "FC_PARCIAL_DO_TIPO"(p_tipo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PARCIAL_DO_TIPO"(p_tipo text) IS 'A parcial que cada tipo de bloco pontua (PARCIAL_DO_TIPO de catalogo.js).';

--
-- Name: FC_PAYLOAD_EM_COLUNAS(jsonb, text, text[], text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PAYLOAD_EM_COLUNAS"(p_payload jsonb, p_campo text, p_dicionario text[], p_versao text) RETURNS json
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select json_object_agg(x.k, x.v)
    from (select e.key as k, e.value::json as v from jsonb_each(p_payload - p_campo) e
          union all
          select p_campo || '_em_colunas', private."FC_COLUNAS_JSON"(p_payload -> p_campo, p_dicionario)
          union all
          select 'versao', to_json(p_versao)) x
   where p_payload is not null;
$$;

--
-- Name: FUNCTION "FC_PAYLOAD_EM_COLUNAS"(p_payload jsonb, p_campo text, p_dicionario text[], p_versao text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PAYLOAD_EM_COLUNAS"(p_payload jsonb, p_campo text, p_dicionario text[], p_versao text) IS 'O payload com p_campo em colunas (<campo>_em_colunas, FC_COLUNAS_JSON) e versao = p_versao (20261029170000; o formato de FC_SE_MUDOU_EM_COLUNAS com a versão vinda da marca).';

