-- Name: FC_PCD_DAS_MODALIDADES(text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PCD_DAS_MODALIDADES"(p_cotas text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
