$$;

--
-- Name: FUNCTION "FC_PCD_DAS_MODALIDADES"(p_cotas text[]); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PCD_DAS_MODALIDADES"(p_cotas text[]) IS 'A coluna pcd da planilha de análises pelas cotas: SIM se a PcD está entre elas. Desde 20261015150000.';

--
-- Name: FC_PEDIR_CONTRATACAO_DOS_APROVADOS(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PEDIR_CONTRATACAO_DOS_APROVADOS"() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- A chave "Conferências" desligada: não pede (o job roda de novo junto com as conferências).
  if not private."FC_AUTOMACAO_LIGADA"(private."FC_CHAVE_DO_WORKFLOW"('contratacao-dos-aprovados.yml')) then
    return null;
  end if;
  return private."FC_DISPARAR_ROBO"('contratacao-dos-aprovados.yml', '{"modo": "normal"}'::jsonb, (select auth.uid()));
exception when others then
  -- Pedir o job nunca impede a mudança do status nem a lista nova.
  raise warning 'Contratado em outra lista: o job não foi pedido (%)', sqlstate;
  return null;
end;
$$;

--
-- Name: FUNCTION "FC_PEDIR_CONTRATACAO_DOS_APROVADOS"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PEDIR_CONTRATACAO_DOS_APROVADOS"() IS 'Pede o job "Contratado em outra lista" (contratacao-dos-aprovados.yml) com a chave Conferências ligada; nunca derruba quem chamou. 20261024120000.';

--
-- Name: FC_PEDIR_DESEMPATE(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PEDIR_DESEMPATE"(p_lista uuid, p_usuario uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_situacao text := 'PEDIDO';
  v_mensagem text;
  v_disparo bigint;
  v_estado text;
begin
  if not private."FC_AUTOMACAO_LIGADA"('classificacao') then
    v_situacao := 'DESLIGADA';
  else
    begin
      v_disparo := private."FC_DISPARAR_ROBO"(
        'classificacao.yml', jsonb_build_object('modo', 'desempate', 'listas', p_lista::text), p_usuario);
      select d."TP_SITUACAO" into v_estado from public."TL_DISPARO_ROBO" d where d."CO_DISPARO" = v_disparo;
      if v_estado is distinct from 'PEDIDO' then
        v_situacao := 'SEM_DISPARO';
        v_mensagem := 'O pedido ao GitHub não saiu (' || coalesce(v_estado, 'sem registro') || ').';
      end if;
    exception when others then
      -- Nunca derruba o registro da lista: só o código do erro.
      v_situacao := 'SEM_DISPARO';
      v_mensagem := 'O pedido ao GitHub não saiu (' || sqlstate || ').';
      v_disparo := null;
    end;
  end if;

  insert into public."TB_PREPARO_DESEMPATE" as p
    ("CO_LISTA_CLASSIFICACAO", "TP_SITUACAO", "DS_MENSAGEM", "CO_DISPARO", "DT_PEDIDO", "DT_ATUALIZACAO")
  values (p_lista, v_situacao, v_mensagem, v_disparo, now(), now())
  on conflict ("CO_LISTA_CLASSIFICACAO") do update
    set "TP_SITUACAO" = excluded."TP_SITUACAO", "DS_MENSAGEM" = excluded."DS_MENSAGEM",
        "CO_DISPARO" = excluded."CO_DISPARO", "CO_EXECUCAO" = null,
        "DT_PEDIDO" = now(), "DT_ATUALIZACAO" = now();
  return v_situacao;
end;
$$;

--
-- Name: FUNCTION "FC_PEDIR_DESEMPATE"(p_lista uuid, p_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PEDIR_DESEMPATE"(p_lista uuid, p_usuario uuid) IS 'Pede o relatório de desempate de uma lista gerada (20261023170000): com a chave "classificacao" ligada, pede classificacao.yml (modo desempate, a lista) por FC_DISPARAR_ROBO em nome de quem gerou; grava o preparo (PEDIDO, DESLIGADA ou SEM_DISPARO) em TB_PREPARO_DESEMPATE e devolve a situação. Nunca levanta erro. Só o dono (registrar_lista_classificacao).';

--
-- Name: FC_PENDENCIAS_FICHA(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PENDENCIAS_FICHA"(p_regra jsonb, p_lanc jsonb, p_res jsonb) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_bloco jsonb;
  v_l jsonb;
  v_parcial text;
  v_decl jsonb;
  v_apur jsonb;
  v_tem_opcoes boolean;
  v_itens text;
  v_pend text[] := '{}';
  v_titulo text;
  v_outro boolean;
  v_livre boolean;
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_exp jsonb;
  v_meses numeric;
  v_minimo_pend boolean;
  v_elimina_outro boolean;
  v_calc numeric;
  v_valor numeric;
begin
  for v_bloco in select b from jsonb_array_elements(coalesce(p_regra -> 'blocos', '[]'::jsonb)) b loop
    continue when v_bloco ->> 'tipo' = 'REGISTRO' or not private."FC_BLOCO_SE_APLICA"(v_bloco, p_lanc);
    v_l := coalesce(p_lanc #> array['blocos', v_bloco ->> 'codigo'], '{}'::jsonb);
    v_titulo := coalesce(v_bloco ->> 'titulo', v_bloco ->> 'codigo');
    if coalesce(v_l ->> 'situacao', '') = '' then
      v_pend := v_pend || (v_titulo || ': marque a situação');
    end if;
    -- "Outro motivo (descrever)" (20261015010000): OUTRO em motivos (Não confere,
    -- Não enviou) ou em justificativas (Conforme) pede o texto em motivo_livre, que
    -- vale como o motivo; no bloco sem motivos na regra, o texto é o motivo.
    v_livre := length(btrim(coalesce(v_l ->> 'motivo_livre', ''))) >= 10;
    v_outro := case
      when v_l ->> 'situacao' in ('NAO_CONFORME', 'NAO_ENVIADO') then coalesce(v_l -> 'motivos', '[]'::jsonb) ? 'OUTRO'
      when v_l ->> 'situacao' = 'CONFORME' then coalesce(v_l -> 'justificativas', '[]'::jsonb) ? 'OUTRO'
      else false end;
    if v_outro and not v_livre then
      v_pend := v_pend || (v_titulo || ': descreva o outro motivo (10 caracteres ou mais)');
    elsif v_l ->> 'situacao' in ('NAO_CONFORME', 'NAO_ENVIADO')
       and not exists (select 1 from jsonb_array_elements_text(coalesce(v_l -> 'motivos', '[]'::jsonb)) m where m <> 'OUTRO')
       and not v_outro
       and not (jsonb_array_length(coalesce(v_bloco -> 'motivos', '[]'::jsonb)) = 0 and v_livre) then
      v_pend := v_pend || (v_titulo || ': escolha o motivo');
    end if;
    -- Diferenças por cargo (20261013130000; faltasDoCargo em regra-por-cargo.ts).
    if v_l ->> 'situacao' = 'CONFORME' and jsonb_typeof(v_bloco -> 'requisitos') = 'array'
       and exists (select 1 from jsonb_array_elements(v_bloco -> 'requisitos') q
                    where (v_l #> array['requisitos', q ->> 'codigo']) is distinct from 'true'::jsonb) then
      v_pend := v_pend || (v_titulo || ': confira cada requisito do cargo');
    end if;
    if v_l ->> 'situacao' = 'CONFORME' and jsonb_typeof(v_l -> 'nota_ajustada') is distinct from 'number'
       and jsonb_typeof(v_bloco -> 'extras') = 'array' then
      v_pend := v_pend || coalesce((
        select array_agg(v_titulo || ': confira ' || (e ->> 'rotulo') order by n)
          from jsonb_array_elements(v_bloco -> 'extras') with ordinality x(e, n)
         where jsonb_typeof(v_l #> array['extras', e ->> 'codigo']) is distinct from 'boolean'), '{}'::text[]);
    end if;
    v_itens := case v_bloco ->> 'tipo' when 'TITULOS' then 'titulos' when 'CURSOS' then 'cursos' when 'VINCULOS' then 'vinculos' end;
    if v_itens is not null and exists (
         select 1 from jsonb_array_elements(coalesce(p_lanc -> v_itens, '[]'::jsonb)) i
          where i -> 'aceito' = 'false'::jsonb and coalesce(i ->> 'motivo', '') = '') then
      v_pend := v_pend || (v_titulo || ': item recusado sem motivo');
    end if;
    -- Datas dos vínculos aceitos (20261023090000; faltaNasDatasDoVinculo em
    -- datas-do-vinculo.ts): AAAA-MM-DD, fim depois do início, nada antes de 1960 e o fim
    -- até hoje (Brasília). A data limite da regra não recusa a linha: só corta a conta.
    if v_itens = 'vinculos' and exists (
         select 1 from jsonb_array_elements(coalesce(p_lanc -> 'vinculos', '[]'::jsonb)) i
          where coalesce(i -> 'aceito', 'true'::jsonb) <> 'false'::jsonb -- o recusado não conta: não pede as datas
            and (private."FC_DATA_DO_TEXTO"(i ->> 'inicio') is null or private."FC_DATA_DO_TEXTO"(i ->> 'fim') is null
                 or i ->> 'fim' < i ->> 'inicio')) then
      v_pend := v_pend || (v_titulo || ': vínculo com data inválida');
    elsif v_itens = 'vinculos' and exists (
         select 1 from jsonb_array_elements(coalesce(p_lanc -> 'vinculos', '[]'::jsonb)) i
          where coalesce(i -> 'aceito', 'true'::jsonb) <> 'false'::jsonb
            and private."FC_DATA_DO_TEXTO"(i ->> 'inicio') < date '1960-01-01') then
      v_pend := v_pend || (v_titulo || ': vínculo com data antes de 1960');
    elsif v_itens = 'vinculos' and exists (
         select 1 from jsonb_array_elements(coalesce(p_lanc -> 'vinculos', '[]'::jsonb)) i
          where coalesce(i -> 'aceito', 'true'::jsonb) <> 'false'::jsonb
            and private."FC_DATA_DO_TEXTO"(i ->> 'fim') > v_hoje) then
      v_pend := v_pend || (v_titulo || ': vínculo com fim depois de hoje');
    end if;
    -- A experiência e a pontuação dos itens são as do banco (20261023090000:
    -- FC_EXPERIENCIA_DA_FICHA e FC_CALCULADO_DO_BLOCO, a conta de calcularAvaliacao),
    -- não as que o cliente gravou em DS_RESULTADO.
    v_exp := null;
    v_meses := null;
    v_minimo_pend := false;
    if v_bloco ->> 'tipo' = 'VINCULOS' then
      v_exp := private."FC_EXPERIENCIA_DA_FICHA"(v_bloco, p_lanc);
      v_meses := (v_exp ->> case when v_bloco -> 'minimo_conta_estagio' = 'true'::jsonb
                                  then 'meses_considerados' else 'meses' end)::numeric;
    end if;
    -- Eliminado por OUTRO bloco (identidade, escolaridade, requisito…), a experiência é só
    -- informativa e o resultado não muda: o mínimo não pede nada (decisão de 22/10/2026).
    -- Continua valendo quando a única eliminação é a da própria experiência.
    v_elimina_outro := v_bloco ->> 'tipo' = 'VINCULOS' and exists (
      select 1 from jsonb_array_elements(coalesce(p_regra -> 'blocos', '[]'::jsonb)) o
       where o ->> 'codigo' is distinct from v_bloco ->> 'codigo'
         -- O efeito primeiro (barato); a aplicação só de quem elimina.
         and case when private."FC_EFEITO_DO_BLOCO"(o, p_lanc #> array['blocos', coalesce(o ->> 'codigo', '')]) = 'ELIMINA'
                  then private."FC_BLOCO_SE_APLICA"(o, p_lanc) else false end);
    -- Experiência Conforme abaixo do mínimo pelos vínculos aceitos eliminaria em silêncio:
    -- lance os vínculos ou marque Não conforme (pendenciasDaFicha, tipo minimo).
    if v_bloco ->> 'tipo' = 'VINCULOS' and v_l ->> 'situacao' = 'CONFORME' and not v_elimina_outro
       and jsonb_typeof(v_bloco -> 'minimo_meses') = 'number' and (v_bloco ->> 'minimo_meses')::numeric > 0
       and coalesce(v_bloco ->> 'efeito_minimo', 'ELIMINA') = 'ELIMINA'
       and v_meses < (v_bloco ->> 'minimo_meses')::numeric then
      v_minimo_pend := true;
      v_pend := v_pend || (v_titulo || ': experiência mínima de ' || (v_bloco ->> 'minimo_meses')
                           || ' meses não comprovada pelos vínculos aceitos');
    end if;
    -- Experiência Não conforme ou Não enviou com os vínculos aceitos cumprindo o mínimo
    -- (20261020100000; Não enviou em 20261023090000): o mínimo é pelos vínculos aceitos,
    -- então não eliminaria, só zeraria a experiência. Desmarque os vínculos não aceitos ou
    -- marque Confere (pendenciasDaFicha, tipo minimo).
    if v_bloco ->> 'tipo' = 'VINCULOS' and v_l ->> 'situacao' in ('NAO_CONFORME', 'NAO_ENVIADO') and not v_elimina_outro
       and jsonb_typeof(v_bloco -> 'minimo_meses') = 'number' and (v_bloco ->> 'minimo_meses')::numeric > 0
       and coalesce(v_bloco ->> 'efeito_minimo', 'ELIMINA') = 'ELIMINA'
       and v_meses >= (v_bloco ->> 'minimo_meses')::numeric then
      v_minimo_pend := true;
      v_pend := v_pend || (v_titulo || ': marcada como '
                           || case when v_l ->> 'situacao' = 'NAO_ENVIADO' then 'Não enviou' else 'Não confere' end
                           || ', mas os vínculos aceitos somam ' || trim_scale(v_meses)
                           || ' meses (mínimo ' || (v_bloco ->> 'minimo_meses')
                           || '): desmarque os vínculos não aceitos ou marque Confere');
    end if;
    -- Pontuação Conforme ACIMA do que os itens aceitos dão (20261020180000 para a
    -- experiência; 20261023090000: também títulos e cursos com a lista —
    -- pontuacaoAcimaDoComprovado em ficha.js). No Confere, a parcial é a declarada
    -- (nota_ajustada); abaixo dos itens não é falta (vale a declarada, decisão de
    -- 23/10/2026). Só vale com Editar nota e justificativa. Fora do inapto por requisito
    -- (pontuação só informativa, 20261021090000), dos cursos pela nota (sem itens) e
    -- quando a falta já é a do mínimo.
    v_parcial := private."FC_PARCIAL_DO_TIPO"(v_bloco ->> 'tipo');
    if v_itens is not null and v_l ->> 'situacao' = 'CONFORME' and not v_minimo_pend
       and coalesce(p_res ->> 'resultado', '') <> 'INAPTO_REQUISITO'
       and not private."FC_BLOCO_PELA_NOTA"(v_bloco, p_lanc)
       and jsonb_typeof(p_res #> array['parciais', v_parcial]) = 'number'
       and not private."FC_AJUSTE_JUSTIFICADO"(p_regra, v_bloco, v_l) then
      v_calc := coalesce(case when v_itens = 'vinculos' then (v_exp ->> 'pontos')::numeric
                              else private."FC_CALCULADO_DO_BLOCO"(v_bloco, p_lanc) end, 0);
      v_valor := (p_res #>> array['parciais', v_parcial])::numeric;
      if v_valor - v_calc > 0.0001 then
        v_pend := v_pend || (v_titulo || ': pontuação confirmada com ' || trim_scale(v_valor)
                             || ' pontos, acima do que '
                             || case v_itens when 'vinculos' then 'os vínculos aceitos comprovam ('
                                                    || coalesce(v_exp ->> 'meses_considerados', '0') || ' meses, '
                                             when 'titulos' then 'os títulos aceitos dão ('
                                             else 'os cursos aceitos dão (' end
                             || trim_scale(v_calc) || ' pontos): lance os itens que comprovam o declarado ou ajuste a pontuação em Editar nota, com justificativa');
      end if;
    end if;
    -- Nota diferente da declarada exige justificativa (fora do inapto por requisito).
    v_decl := p_res #> array['declarada', coalesce(v_parcial, '')];
    v_apur := p_res #> array['parciais', coalesce(v_parcial, '')];
    if v_parcial is not null and p_res ->> 'resultado' <> 'INAPTO_REQUISITO'
       and jsonb_typeof(v_decl) = 'number' and jsonb_typeof(v_apur) = 'number'
       and abs((v_decl #>> '{}')::numeric - (v_apur #>> '{}')::numeric) > 0.0001 then
      v_tem_opcoes := jsonb_array_length(coalesce(v_bloco -> 'motivos', '[]'::jsonb)) > 0
                      or jsonb_array_length(coalesce(p_regra -> 'observacoes_prontas', '[]'::jsonb)) > 0;
      if not exists (select 1 from jsonb_array_elements_text(coalesce(v_l -> 'justificativas', '[]'::jsonb)) j where j <> 'OUTRO')
         and not (coalesce(v_l -> 'justificativas', '[]'::jsonb) ? 'OUTRO' and v_livre)
         and not (v_outro and not v_livre) -- já pediu a descrição: uma falta só
         and not (v_l ->> 'situacao' in ('NAO_CONFORME', 'NAO_ENVIADO')
                  and (jsonb_array_length(coalesce(v_l -> 'motivos', '[]'::jsonb)) > 0 or length(btrim(coalesce(v_l ->> 'motivo_livre', ''))) >= 10))
         and not (not v_tem_opcoes and length(btrim(coalesce(v_l ->> 'justificativa_livre', ''))) >= 10) then
        v_pend := v_pend || (v_titulo || ': nota diferente da declarada sem justificativa');
      end if;
    end if;
  end loop;
  return v_pend;
end;
$$;

--
-- Name: FUNCTION "FC_PENDENCIAS_FICHA"(p_regra jsonb, p_lanc jsonb, p_res jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PENDENCIAS_FICHA"(p_regra jsonb, p_lanc jsonb, p_res jsonb) IS 'O que falta para concluir (pendenciasDaFicha de ficha.js): situação de cada bloco que se aplica, motivo do Não conforme/Não enviado, cada requisito do cargo conferido no bloco Conforme e cada item extra do cargo marcado na pontuação pelos itens (20261013130000), motivo do item recusado, datas dos vínculos, experiência Conforme abaixo do mínimo da regra pelos vínculos aceitos e justificativa de toda nota diferente da declarada (fora do inapto por requisito). Vazio = pode concluir. Desde 20261014191000, as datas só dos vínculos aceitos. Desde 20261015010000, o OUTRO em motivos (Não confere) ou em justificativas (Conforme) com motivo_livre de 10 caracteres ou mais vale como o motivo/justificativa; marcado sem o texto, "descreva o outro motivo". Desde 20261020100000, a experiência Não conforme com os vínculos aceitos cumprindo o mínimo que elimina (não eliminaria): desmarque os vínculos não aceitos ou marque Confere. Desde 20261020180000, a experiência Conforme com a parcial acima da calculada pelos vínculos aceitos (calculados), fora do abaixo do mínimo: só com Editar nota (edita_nota) e justificativa. Desde 20261021090000, a experiência acima do comprovado não vale no inapto por requisito (eliminado por outro critério).';

--
-- Name: TB_PENDENCIA_APROVADO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_PENDENCIA_APROVADO" (
    "CO_PENDENCIA_APROVADO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_AREA" text NOT NULL,
    "TP_PENDENCIA" character varying(30) NOT NULL,
    "DS_CHAVE" character varying(40) NOT NULL,
    "CO_CANDIDATO_APROVADO" uuid[] NOT NULL,
    "DS_DETALHE" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "TP_SITUACAO" character varying(10) DEFAULT 'ABERTA'::character varying NOT NULL,
    "DT_DETECCAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ULTIMA_DETECCAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_EXECUCAO" text NOT NULL,
    "TP_DECISAO" character varying(30),
    "DS_MOTIVO_DECISAO" character varying(500),
    "CO_USUARIO_DECISAO" uuid,
    "DT_RESOLUCAO" timestamp with time zone,
    CONSTRAINT "CK_PENDAPROV_CANDIDATOS" CHECK (((cardinality("CO_CANDIDATO_APROVADO") >= 1) AND (cardinality("CO_CANDIDATO_APROVADO") <= 50))),
    CONSTRAINT "CK_PENDAPROV_COEXECUCAO" CHECK (("CO_EXECUCAO" ~ '^pend-[0-9]{8}T[0-9]{6}-[0-9a-f]{8}$'::text)),
    CONSTRAINT "CK_PENDAPROV_DECISAO" CHECK (
CASE "TP_SITUACAO"
    WHEN 'ABERTA'::text THEN (("TP_DECISAO" IS NULL) AND ("DS_MOTIVO_DECISAO" IS NULL) AND ("CO_USUARIO_DECISAO" IS NULL) AND ("DT_RESOLUCAO" IS NULL))
    ELSE (("TP_DECISAO" IS NOT NULL) AND ("DT_RESOLUCAO" IS NOT NULL) AND ((("TP_DECISAO")::text = 'SANEADA'::text) = ("CO_USUARIO_DECISAO" IS NULL)) AND ((("TP_DECISAO")::text = 'SANEADA'::text) OR ((length(btrim(("DS_MOTIVO_DECISAO")::text)) >= 3) AND (length(btrim(("DS_MOTIVO_DECISAO")::text)) <= 500))))
END),
    CONSTRAINT "CK_PENDAPROV_DSCHAVE" CHECK ((("DS_CHAVE")::text ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT "CK_PENDAPROV_DSDETALHE" CHECK (((jsonb_typeof("DS_DETALHE") = 'object'::text) AND (length(("DS_DETALHE")::text) <= 1000) AND (("DS_DETALHE")::text !~ '@'::text) AND (("DS_DETALHE")::text !~ '[0-9]{11}'::text))),
    CONSTRAINT "CK_PENDAPROV_TPDECISAO" CHECK ((("TP_DECISAO" IS NULL) OR (("TP_DECISAO")::text = ANY ((ARRAY['VINCULO_ESCOLHIDO'::character varying, 'LISTA_ESCOLHIDA'::character varying, 'LINHA_MANTIDA'::character varying, 'PESSOAS_DIFERENTES'::character varying, 'EMPATE_PREVISTO'::character varying, 'POSICAO_CORRIGIDA'::character varying, 'DESFECHO_REGISTRADO'::character varying, 'NOVA_DATA'::character varying, 'SANEADA'::character varying])::text[])))),
    CONSTRAINT "CK_PENDAPROV_TPPENDENCIA" CHECK ((("TP_PENDENCIA")::text = ANY ((ARRAY['CONTRATADO_DUAS_MATRICULAS'::character varying, 'CONTRATADO_EM_DUAS_LISTAS'::character varying, 'PESSOA_REPETIDA'::character varying, 'POSICAO_REPETIDA'::character varying, 'CONVOCADO_SEM_DESFECHO'::character varying])::text[]))),
    CONSTRAINT "CK_PENDAPROV_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY ((ARRAY['ABERTA'::character varying, 'RESOLVIDA'::character varying])::text[])))
);

--
-- Name: TABLE "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_PENDENCIA_APROVADO" IS 'Pendências da lista de aprovados que o gestor do edital decide na tela (Lista de aprovados › Pendências): o instantâneo do job Python scripts/aprovados/pendencias.py, uma linha por tipo e chave, aberta ou resolvida (pela decisão, com motivo e autor, ou SANEADA quando sumiu da lista). Só pelas RPCs. 20261026190000.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."CO_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."CO_PENDENCIA_APROVADO" IS 'Identificador da pendência.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."CO_MONITORAMENTO" IS 'O edital (TB_MONITORAMENTO_INDIGENA) da lista vigente das linhas.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."CO_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."CO_AREA" IS 'A área do edital (o recorte da tela).';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."TP_PENDENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."TP_PENDENCIA" IS 'CONTRATADO_DUAS_MATRICULAS, CONTRATADO_EM_DUAS_LISTAS, PESSOA_REPETIDA, POSICAO_REPETIDA ou CONVOCADO_SEM_DESFECHO.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."DS_CHAVE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."DS_CHAVE" IS 'sha256 (40 hex) do que identifica a pendência (python/monitora/aprovados/pendencias.py, chave): a mesma pendência em rodadas seguidas.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."CO_CANDIDATO_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."CO_CANDIDATO_APROVADO" IS 'As linhas da lista de aprovados (TB_CANDIDATO_APROVADO.id) da pendência, em ordem.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."DS_DETALHE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."DS_DETALHE" IS 'O que motivou (linhas, vinculos, motivo da regra, posicao, convocado_em, dias, prazo). Sem nome, CPF, matrícula ou e-mail.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."TP_SITUACAO" IS 'ABERTA ou RESOLVIDA.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."DT_DETECCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."DT_DETECCAO" IS 'Quando o job achou a pendência pela primeira vez (ou a reabriu).';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."DT_ULTIMA_DETECCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."DT_ULTIMA_DETECCAO" IS 'Última rodada do job que a achou.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."CO_EXECUCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."CO_EXECUCAO" IS 'Última execução do job que a achou (pend-AAAAMMDDTHHMMSS-xxxxxxxx).';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."TP_DECISAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."TP_DECISAO" IS 'Como foi resolvida: VINCULO_ESCOLHIDO, LISTA_ESCOLHIDA, LINHA_MANTIDA, PESSOAS_DIFERENTES, EMPATE_PREVISTO, POSICAO_CORRIGIDA, DESFECHO_REGISTRADO, NOVA_DATA ou SANEADA (sumiu da lista, sem decisão aqui).';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."DS_MOTIVO_DECISAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."DS_MOTIVO_DECISAO" IS 'O motivo de quem decidiu (3 a 500 caracteres).';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."CO_USUARIO_DECISAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."CO_USUARIO_DECISAO" IS 'Quem decidiu (auth.users.id); nulo na SANEADA.';

--
-- Name: COLUMN "TB_PENDENCIA_APROVADO"."DT_RESOLUCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PENDENCIA_APROVADO"."DT_RESOLUCAO" IS 'Quando foi resolvida.';

--
-- Name: CONSTRAINT "CK_PENDAPROV_CANDIDATOS" ON "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PENDAPROV_CANDIDATOS" ON public."TB_PENDENCIA_APROVADO" IS 'De 1 a 50 linhas.';

--
-- Name: CONSTRAINT "CK_PENDAPROV_COEXECUCAO" ON "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PENDAPROV_COEXECUCAO" ON public."TB_PENDENCIA_APROVADO" IS 'Identificador da execução do job.';

--
-- Name: CONSTRAINT "CK_PENDAPROV_DECISAO" ON "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PENDAPROV_DECISAO" ON public."TB_PENDENCIA_APROVADO" IS 'Aberta sem decisão; resolvida com decisão e data; quem e o motivo em toda decisão que não é a SANEADA.';

--
-- Name: CONSTRAINT "CK_PENDAPROV_DSCHAVE" ON "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PENDAPROV_DSCHAVE" ON public."TB_PENDENCIA_APROVADO" IS 'Chave em 40 hex.';

--
-- Name: CONSTRAINT "CK_PENDAPROV_DSDETALHE" ON "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PENDAPROV_DSDETALHE" ON public."TB_PENDENCIA_APROVADO" IS 'Objeto json curto, sem e-mail nem 11 dígitos seguidos.';

--
-- Name: CONSTRAINT "CK_PENDAPROV_TPDECISAO" ON "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PENDAPROV_TPDECISAO" ON public."TB_PENDENCIA_APROVADO" IS 'Decisões válidas.';

--
-- Name: CONSTRAINT "CK_PENDAPROV_TPPENDENCIA" ON "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PENDAPROV_TPPENDENCIA" ON public."TB_PENDENCIA_APROVADO" IS 'Tipos válidos.';

--
-- Name: CONSTRAINT "CK_PENDAPROV_TPSITUACAO" ON "TB_PENDENCIA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PENDAPROV_TPSITUACAO" ON public."TB_PENDENCIA_APROVADO" IS 'Situações válidas.';

--
-- Name: FC_PENDENCIA_PARA_DECIDIR(uuid, text[], text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PENDENCIA_PARA_DECIDIR"(p_pendencia uuid, p_tipos text[], p_motivo text) RETURNS public."TB_PENDENCIA_APROVADO"
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_PENDENCIA_APROVADO"%rowtype;
begin
  select * into v from public."TB_PENDENCIA_APROVADO" p where p."CO_PENDENCIA_APROVADO" = p_pendencia for update;
  if not found then
    raise exception 'Pendência não encontrada' using errcode = 'P0002';
  end if;
  if not private."FC_PODE_DECIDIR_PENDENCIA"(v."CO_MONITORAMENTO") then
    raise exception 'Sem permissão para decidir as pendências deste edital' using errcode = '42501';
  end if;
  if not (v."TP_PENDENCIA" = any (p_tipos)) then
    raise exception 'Esta decisão não serve para esta pendência' using errcode = '22023';
  end if;
  if v."TP_SITUACAO" <> 'ABERTA' then
    raise exception 'Esta pendência já foi resolvida: atualize a tela' using errcode = '55000';
  end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then
    raise exception 'Informe o motivo (3 a 500 caracteres)' using errcode = '22023';
  end if;
  -- As linhas continuam na lista vigente do edital (sem remoção): senão a pendência mudou.
  if exists (select 1 from unnest(v."CO_CANDIDATO_APROVADO") c(id)
              where not exists (select 1 from public."TB_CANDIDATO_APROVADO" a
                                  join public."TB_LISTA_APROVADO" l on l.id = a.lista_id and l.vigente is true
                                 where a.id = c.id and a.removido_em is null
                                   and l.edital_id = v."CO_MONITORAMENTO"::text)) then
    raise exception 'As linhas desta pendência mudaram: atualize a tela' using errcode = '55000';
  end if;
  return v;
end;
$$;

--
-- Name: FUNCTION "FC_PENDENCIA_PARA_DECIDIR"(p_pendencia uuid, p_tipos text[], p_motivo text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PENDENCIA_PARA_DECIDIR"(p_pendencia uuid, p_tipos text[], p_motivo text) IS 'Abre a pendência para a decisão (trava a linha): existe, a pessoa decide neste edital (FC_PODE_DECIDIR_PENDENCIA), o tipo serve, está aberta, o motivo tem 3 a 500 caracteres e as linhas continuam na lista vigente. 20261026190000.';

--
-- Name: FC_PERFIL_FOTO_AO_LIGAR(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PERFIL_FOTO_AO_LIGAR"() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_foto text;
begin
  if new.user_id is not null then
    select private."FC_FOTO_DO_GOOGLE"(u.raw_user_meta_data)
      into v_foto
      from auth.users u
     where u.id = new.user_id;
    if v_foto is not null then
      new.google_avatar_url := v_foto;
    end if;
  end if;
  return new;
end;
$$;

--
-- Name: FUNCTION "FC_PERFIL_FOTO_AO_LIGAR"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PERFIL_FOTO_AO_LIGAR"() IS 'Gatilho no perfil: ao criar ou ligar ao usuário (user_id), preenche google_avatar_url com a foto do login.';

--
-- Name: FC_PERFIL_LIGAR_USUARIO_AUTH(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PERFIL_LIGAR_USUARIO_AUTH"() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.user_id is null and nullif(btrim(new.email), '') is not null then
    select u.id into new.user_id
      from auth.users u
     where lower(u.email) = lower(btrim(new.email))
       and not exists (select 1 from public."TB_PERFIL_USUARIO" o where o.user_id = u.id)
     limit 1;
  end if;
  return new;
end;
$$;

--
-- Name: FUNCTION "FC_PERFIL_LIGAR_USUARIO_AUTH"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PERFIL_LIGAR_USUARIO_AUTH"() IS 'Gatilho de TB_PERFIL_USUARIO (20261103213000): perfil sem user_id inserido ou com e-mail trocado é ligado à conta do auth.users com o mesmo e-mail (sem conta, fica nulo até o primeiro acesso, que public.link_auth_user_profile liga). Assim private.is_master() identifica só pelo user_id.';

--
-- Name: FC_PERFIL_PODE_SER_RESPONSAVEL(uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PERFIL_PODE_SER_RESPONSAVEL"(p_perfil uuid, p_area text, p_edital uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public."TB_PERFIL_USUARIO" u
     where u.id = p_perfil and u.ativo
       and p_area = any (coalesce(private."FC_AREAS_DO_PERFIL"(u.id), '{}'))
       and (p_edital is null or private."FC_PERFIL_VE_EDITAL"(u.id, p_edital)));
$$;

--
-- Name: FUNCTION "FC_PERFIL_PODE_SER_RESPONSAVEL"(p_perfil uuid, p_area text, p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PERFIL_PODE_SER_RESPONSAVEL"(p_perfil uuid, p_area text, p_edital uuid) IS 'O perfil está ativo e vê a área (e o edital, se houver): pode ser responsável. 20261104120000.';

--
-- Name: FC_PERFIL_VE_EDITAL(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PERFIL_VE_EDITAL"(p_perfil_usuario uuid, p_edital uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public."TB_PERFIL_USUARIO" u
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = p_edital
     where u.id = p_perfil_usuario and u.ativo
       and m."CO_AREA" = any (coalesce(private."FC_AREAS_DO_PERFIL"(u.id), '{}'))
       and (private."FC_EDITAIS_DA_COORDENACAO"(u."CO_COORDENACAO") is null
            or m.id = any (private."FC_EDITAIS_DA_COORDENACAO"(u."CO_COORDENACAO"))));
$$;

--
-- Name: FUNCTION "FC_PERFIL_VE_EDITAL"(p_perfil_usuario uuid, p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PERFIL_VE_EDITAL"(p_perfil_usuario uuid, p_edital uuid) IS 'Um usuário ativo (TB_PERFIL_USUARIO.id) vê o edital pela área e pelo recorte da coordenação? (a regra de FC_PODE_VER_EDITAL, para outra pessoa).';

--
-- Name: FC_PESSOA_DO_APROVADO(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PESSOA_DO_APROVADO"(p_id_origem text, p_nome text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce('cod:' || nullif(btrim(p_id_origem), ''),
                  'nome:' || nullif(lower(regexp_replace(btrim(p_nome), '\s+', ' ', 'g')), ''));
$$;

--
-- Name: FUNCTION "FC_PESSOA_DO_APROVADO"(p_id_origem text, p_nome text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PESSOA_DO_APROVADO"(p_id_origem text, p_nome text) IS 'Chave da pessoa na lista de aprovados: o código do candidato na Empregare ou, sem ele, o nome normalizado (a mesma de conferencia_ler_aprovados, antes do hash).';

--
-- Name: FC_PODE_ANALISAR_VAGA(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_ANALISAR_VAGA"(p_edital uuid, p_usuario uuid, p_vaga text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public."RL_ANALISTA_EDITAL" r
      join public."TB_PERFIL_USUARIO" u on u.user_id = r."CO_USUARIO"
     where r."CO_MONITORAMENTO" = p_edital and r."CO_USUARIO" = p_usuario
       and r."TP_PAPEL" = 'ANALISTA' and r."ST_ATIVO" = 'S'
       and (p_vaga is null or r."CO_VAGA" is null or r."CO_VAGA" = p_vaga)
       and u.ativo
       and private."FC_NIVEL_AVALIACAO_DO_PERFIL"(u.id) >= 2
       and private."FC_PERFIL_VE_EDITAL"(u.id, p_edital));
$$;

--
-- Name: FUNCTION "FC_PODE_ANALISAR_VAGA"(p_edital uuid, p_usuario uuid, p_vaga text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_ANALISAR_VAGA"(p_edital uuid, p_usuario uuid, p_vaga text) IS 'A pessoa (auth.users.id) analisa a vaga no edital: linha ANALISTA ativa na equipe (na vaga ou no edital todo), conta ativa, Editor em avaliacao_documental e vê o edital. p_vaga nula = qualquer vaga.';

--
-- Name: FC_PODE_ANEXO_RECURSO(text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_ANEXO_RECURSO"(p_caminho text, p_minimo integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select private.pode_recurso('recursos', p_minimo)
       and private."FC_PODE_VER_EDITAL"(r."CO_MONITORAMENTO")
    from public."TB_RECURSO_CANDIDATO" r
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id = r."CO_MONITORAMENTO"
    where cardinality(storage.foldername(p_caminho)) = 2
      and r."ST_ATIVO" = 'S'
      and r."CO_RECURSO_CANDIDATO"::text = (storage.foldername(p_caminho))[2]
      and m."CO_AREA" = (storage.foldername(p_caminho))[1]
  ), false);
$$;

--
-- Name: FUNCTION "FC_PODE_ANEXO_RECURSO"(p_caminho text, p_minimo integer); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_ANEXO_RECURSO"(p_caminho text, p_minimo integer) IS 'Política do bucket recursos-anexos: o caminho é <área>/<recurso>/<arquivo>, o recurso está ativo e é da área do caminho, e quem pede tem recursos no nível pedido e vê o edital (área e coordenação).';

--
-- Name: FC_PODE_AREA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_AREA"(p_area text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_area = any (private."FC_AREAS_USUARIO"());
$$;

--
-- Name: FUNCTION "FC_PODE_AREA"(p_area text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_AREA"(p_area text) IS 'O usuário logado vê a área? Usado pelas RPCs e policies para recortar dados por área.';

--
-- Name: FC_PODE_BAIXAR_ANEXO_RECURSO(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_BAIXAR_ANEXO_RECURSO"(p_caminho text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
      select 1
      from public."TB_ANEXO_RECURSO" a
      join public."TH_ANEXO_RECURSO" h on h."CO_ANEXO_RECURSO" = a."CO_ANEXO_RECURSO"
      where a."DS_CAMINHO" = p_caminho
        and h."TP_ACAO" = 'download'
        and h."CO_USUARIO" = (select auth.uid())
        and h."DT_ACAO" > now() - interval '5 minutes'
    )
    and private."FC_PODE_ANEXO_RECURSO"(p_caminho, 1);
$$;

--
-- Name: FUNCTION "FC_PODE_BAIXAR_ANEXO_RECURSO"(p_caminho text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_BAIXAR_ANEXO_RECURSO"(p_caminho text) IS 'Política de leitura do bucket recursos-anexos (é ela que libera a URL assinada): quem pede registrou o download do anexo pela RPC registrar_download_anexo_recurso nos últimos 5 minutos e continua com acesso ao recurso.';

--
-- Name: FC_PODE_DECIDIR_PENDENCIA(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_DECIDIR_PENDENCIA"(p_edital uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- O administrador global faz tudo, em qualquer área e edital (private.is_master). Fora ele, quem
  -- tem Editor ou acima no recurso "aprovados_pendencias" (grupo ou exceção da pessoa, na matriz de
  -- Acessos), com o edital no recorte (área e coordenação: FC_PODE_VER_EDITAL).
  select private.is_master()
      or (private.pode_recurso('aprovados_pendencias', 2)
          and coalesce(private."FC_PODE_VER_EDITAL"(p_edital), false));
$$;

--
-- Name: FUNCTION "FC_PODE_DECIDIR_PENDENCIA"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_DECIDIR_PENDENCIA"(p_edital uuid) IS 'Quem decide as pendências do edital: o administrador global (sempre, em qualquer área e edital); fora ele, quem tem Editor ou acima no recurso aprovados_pendencias (matriz de Acessos), com o edital na área e no recorte dele. 20261026190000.';

--
-- Name: FC_PODE_EDITAR_COORDENADA(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_EDITAR_COORDENADA"() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_master() or private.monitora_role() = 'edital_gestor';
$$;

--
-- Name: FUNCTION "FC_PODE_EDITAR_COORDENADA"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_EDITAR_COORDENADA"() IS 'Pode corrigir coordenadas dos mapas pelas RPCs do editor: administrador global ou grupo edital_gestor (Gestor) ativo. Espelho de podeEditarCoordenadas em src/lib/access-roles.js. A escrita direta em TB_CONFIG_MAPA_SAUDE_INDIG continua só do administrador global.';

--
-- Name: FC_PODE_EDITAR_CRONOGRAMA_AREA(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_EDITAR_CRONOGRAMA_AREA"(p_area text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_master()
      or ((private.pode_recurso('calendario', 2) or private.pode_recurso('nucleo', 2))
          and private."FC_PODE_AREA"(p_area));
$$;

--
-- Name: FUNCTION "FC_PODE_EDITAR_CRONOGRAMA_AREA"(p_area text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_EDITAR_CRONOGRAMA_AREA"(p_area text) IS 'Quem lê pode criar/editar demandas internas e responsáveis do edital na área: administrador global; ou editor em calendario/nucleo com acesso à área. 20261104120000.';

--
-- Name: FC_PODE_EDITAR_DEMANDA(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_EDITAR_DEMANDA"(p_area text, p_edital uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_master()
      or (private."FC_PODE_EDITAR_CRONOGRAMA_AREA"(p_area)
          and (p_edital is null or private."FC_PODE_VER_EDITAL"(p_edital)));
$$;

--
-- Name: FUNCTION "FC_PODE_EDITAR_DEMANDA"(p_area text, p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_EDITAR_DEMANDA"(p_area text, p_edital uuid) IS 'Quem lê edita a demanda interna: administrador global; ou editor da área que também vê o edital ligado. 20261104120000.';

--
-- Name: FC_PODE_IGNORAR_AVISO(text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_IGNORAR_AVISO"(p_modulo text, p_area text, p_edital uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_master()
      or (private."FC_PODE_VER_AVISO"(p_modulo, p_area, p_edital)
          and private.pode_recurso(
                private."FC_CONFERENCIA_RECURSO"(p_modulo),
                case private."FC_CONFERENCIA_RECURSO"(p_modulo) when 'classificacao' then 2 else 3 end));
$$;

--
-- Name: FUNCTION "FC_PODE_IGNORAR_AVISO"(p_modulo text, p_area text, p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_IGNORAR_AVISO"(p_modulo text, p_area text, p_edital uuid) IS 'Quem chama pode ignorar o aviso? Administrador global, ou quem vê o aviso e administra o módulo (nível admin; na classificação, editor, o nível mais alto dela).';

--
-- Name: FC_PODE_PARECER_RECURSO(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_PARECER_RECURSO"() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.pode_recurso('recursos_parecer', 2);
$$;

--
-- Name: FUNCTION "FC_PODE_PARECER_RECURSO"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_PARECER_RECURSO"() IS 'Quem está logado tem o parecer jurídico dos recursos (recursos_parecer = editor)?';

--
-- Name: FC_PODE_SUBSTITUIR_LISTA(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_SUBSTITUIR_LISTA"() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private."FC_ADMIN_GLOBAL_ATIVO"((select auth.uid())) or private.pode_recurso('importacao', 3);
$$;

--
-- Name: FUNCTION "FC_PODE_SUBSTITUIR_LISTA"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_SUBSTITUIR_LISTA"() IS 'Quem substitui, publica de novo ou remove a lista de aprovados de um edital: o administrador global, ou quem tem Importação nível 3 na matriz de Acessos (grupo ou permissão individual). 20261030090000.';

--
-- Name: FC_PODE_VER_ANALISE_DO_AVISO(text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_VER_ANALISE_DO_AVISO"(p_area text, p_edital_norm text, p_unidade_norm text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_master()
      or (p_area is not null
          and private."FC_PODE_AREA"(p_area)
          and (private."FC_EDITAIS_VISIVEIS"() is null
               or p_edital_norm = any (coalesce(private."FC_EDITAIS_NORM_VISIVEIS"(), '{}'))
               or p_unidade_norm = any (coalesce(private."FC_UNIDADES_NORM_VISIVEIS"(), '{}'))));
$$;

--
-- Name: FUNCTION "FC_PODE_VER_ANALISE_DO_AVISO"(p_area text, p_edital_norm text, p_unidade_norm text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_VER_ANALISE_DO_AVISO"(p_area text, p_edital_norm text, p_unidade_norm text) IS 'Quem chama vê os dados (nome, vaga, responsável) desta análise num caso de aviso? Administrador global sempre; os demais com a área da análise e, com recorte por coordenação, o edital ou a unidade no recorte (o mesmo do painel das análises).';

--
-- Name: FC_PODE_VER_AVISO(text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_VER_AVISO"(p_modulo text, p_area text, p_edital uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_recurso text := private."FC_CONFERENCIA_RECURSO"(p_modulo);
begin
  if private.is_master() then
    return true;
  end if;
  if v_recurso is null or p_area is null or not private.pode_recurso(v_recurso, 1) then
    return false;
  end if;
  if not private."FC_PODE_AREA"(p_area) then
    return false;
  end if;
  if p_edital is null then
    return private."FC_EDITAIS_VISIVEIS"() is null;
  end if;
  return private."FC_PODE_VER_EDITAL"(p_edital);
end;
$$;

--
-- Name: FUNCTION "FC_PODE_VER_AVISO"(p_modulo text, p_area text, p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_VER_AVISO"(p_modulo text, p_area text, p_edital uuid) IS 'Quem chama vê o aviso? Administrador global sempre; os demais com o módulo (leitor), a área e o edital no recorte (aviso de área inteira: só sem recorte de coordenação). Cargas e avisos sem área: só o administrador global.';

--
-- Name: FC_PODE_VER_DEMANDA(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_VER_DEMANDA"(p_area text, p_edital uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_master()
      or (private.pode_recurso('calendario', 1)
          and private."FC_PODE_AREA"(p_area)
          and (p_edital is null or private."FC_PODE_VER_EDITAL"(p_edital)));
$$;

--
-- Name: FUNCTION "FC_PODE_VER_DEMANDA"(p_area text, p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_VER_DEMANDA"(p_area text, p_edital uuid) IS 'Quem lê vê a demanda interna: administrador global; ou leitor em calendario com acesso à área e, se houver, ao edital. 20261104120000.';

--
-- Name: FC_PODE_VER_EDITAL(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_PODE_VER_EDITAL"(p_edital uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public."TB_MONITORAMENTO_INDIGENA" m
     where m.id = p_edital
       and m."CO_AREA" = any (private."FC_AREAS_USUARIO"())
       and (private."FC_EDITAIS_VISIVEIS"() is null or m.id = any (private."FC_EDITAIS_VISIVEIS"()))
  );
$$;

--
-- Name: FUNCTION "FC_PODE_VER_EDITAL"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_PODE_VER_EDITAL"(p_edital uuid) IS 'O usuário logado vê o edital (área + coordenação)? Edital inexistente = false.';

