--
-- Name: FC_QUADRO_DA_VAGA_EMPREGARE(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_QUADRO_DA_VAGA_EMPREGARE"(p_edital uuid, p_vaga text) RETURNS public."TB_QUADRO_VAGA_EDITAL"
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select q.*
    from (select coalesce(
                   (select v.quadro_id
                      from private."FC_EMPREGARE_VAGAS_DO_QUADRO"(p_vaga) v
                      join public."TB_QUADRO_VAGA_EDITAL" l
                        on l."CO_QUADRO_VAGA" = v.quadro_id and l."CO_MONITORAMENTO" = p_edital and l."ST_REGISTRO_ATIVO" = 'S'
                     where v.edital_id = p_edital
                     limit 1),
                   private."FC_QUADRO_PELO_TITULO_EMPREGARE"(p_edital, p_vaga)) as id) x
    join public."TB_QUADRO_VAGA_EDITAL" q
      on q."CO_QUADRO_VAGA" = x.id and q."CO_MONITORAMENTO" = p_edital and q."ST_REGISTRO_ATIVO" = 'S';
$$;

--
-- Name: FUNCTION "FC_QUADRO_DA_VAGA_EMPREGARE"(p_edital uuid, p_vaga text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_QUADRO_DA_VAGA_EMPREGARE"(p_edital uuid, p_vaga text) IS 'A linha do quadro de vagas de uma vaga da Empregare no edital: pelo nome_vaga da análise curricular (planilha, FC_EMPREGARE_VAGAS_DO_QUADRO) e, sem ele, pelo título da vaga na Empregare (FC_QUADRO_PELO_TITULO_EMPREGARE, desde 20261013140000). Usada pelo job da pré-classificação (cargo e nível) e pela gravação de cada vaga (NO_CARGO, NO_LOTACAO, quadro).';

--
-- Name: FC_QUADRO_PELO_TITULO_EMPREGARE(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_QUADRO_PELO_TITULO_EMPREGARE"(p_edital uuid, p_vaga text) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_titulo text;
  v_numero integer;
  v_linhas uuid[];
  v_pelo_nome uuid;
  v_escolha jsonb;
begin
  select private."FC_TITULO_DA_VAGA_EMPREGARE"(v."NO_ARQUIVO") into v_titulo
    from public."TB_EMPREGARE_VAGA" v
   where v."CO_MONITORAMENTO" = p_edital and v."CO_VAGA" = p_vaga;
  if v_titulo is null then
    return null;
  end if;
  v_numero := private."FC_NUMERO_DO_CARGO"(v_titulo);
  v_pelo_nome := private."FC_QUADRO_DA_VAGA"(p_edital, v_titulo);
  if v_numero is null then
    return v_pelo_nome; -- sem "CARGO N": o casamento por palavras de sempre
  end if;

  select coalesce(array_agg(q."CO_QUADRO_VAGA" order by q."NU_ORDEM"), '{}') into v_linhas
    from public."TB_QUADRO_VAGA_EDITAL" q
   where q."CO_MONITORAMENTO" = p_edital and q."ST_REGISTRO_ATIVO" = 'S'
     and private."FC_NUMERO_DO_CARGO"(q."NO_CARGO") = v_numero;
  if cardinality(v_linhas) = 0 then
    return null;
  end if;
  if cardinality(v_linhas) = 1 then
    return v_linhas[1];
  end if;
  -- O mesmo cargo em mais de uma lotação: a lotação escrita no título decide.
  if v_pelo_nome = any (v_linhas) then
    return v_pelo_nome;
  end if;

  -- Sem a lotação no título: a UF dos inscritos de cada vaga irmã.
  with linhas as (
    select q."CO_QUADRO_VAGA" as id, private."FC_UF_DA_LOTACAO"(q."NO_LOTACAO") as uf
      from public."TB_QUADRO_VAGA_EDITAL" q
     where q."CO_QUADRO_VAGA" = any (v_linhas)
  ),
  irmas as (
    select v."CO_VAGA" as vaga
      from public."TB_EMPREGARE_VAGA" v
     where v."CO_MONITORAMENTO" = p_edital
       and private."FC_NUMERO_DO_CARGO"(private."FC_TITULO_DA_VAGA_EMPREGARE"(v."NO_ARQUIVO")) = v_numero
  ),
  contagem as (
    select i.vaga, l.id, l.uf,
           (select count(*) from public."TB_EMPREGARE_CANDIDATO" c
             where c."CO_VAGA" = i.vaga and c."ST_REGISTRO_ATIVO" = 'S'
               and upper(btrim(coalesce(c."DS_COLUNA_ORIGINAL" ->> 'ESTADO', ''))) = l.uf) as n
      from irmas i cross join linhas l
  ),
  nota as (
    select c.vaga, c.id, (c.n + 1)::numeric / (sum(c.n) over (partition by c.id) + 2) as s
      from contagem c
  ),
  melhor as (
    select n.vaga, n.id,
           n.s = max(n.s) over (partition by n.vaga) as topo,
           count(*) filter (where true) over (partition by n.vaga, n.s) as empates
      from nota n
  ),
  escolha as (
    select m.vaga, m.id from melhor m where m.topo and m.empates = 1
  )
  select jsonb_build_object(
           'ok', (select count(*) from linhas) = (select count(*) from irmas)
                 and (select count(distinct uf) from linhas where uf is not null) = (select count(*) from linhas)
                 and (select count(*) from escolha) = (select count(*) from irmas)
                 and (select count(distinct id) from escolha) = (select count(*) from linhas),
           'id', (select e.id from escolha e where e.vaga = p_vaga))
    into v_escolha;
  return case when (v_escolha ->> 'ok')::boolean then (v_escolha ->> 'id')::uuid end;
end;
$$;

--
-- Name: FUNCTION "FC_QUADRO_PELO_TITULO_EMPREGARE"(p_edital uuid, p_vaga text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_QUADRO_PELO_TITULO_EMPREGARE"(p_edital uuid, p_vaga text) IS 'A linha do quadro de uma vaga da Empregare pelo título da vaga (nome do arquivo da carga): o número do CARGO; com o mesmo cargo em mais de uma lotação, a lotação do título ou, sem ela, a UF da lotação pela UF dos inscritos das vagas irmãs (uma lotação para cada vaga, senão null). Para os editais cuja análise não vem da planilha (nome_vaga nulo), desde 20261013140000.';

--
-- Name: FC_RANK_NIVEL(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RANK_NIVEL"(p_nivel text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_nivel when 'admin' then 3 when 'editor' then 2 when 'leitor' then 1 else 0 end;
$$;

--
-- Name: FUNCTION "FC_RANK_NIVEL"(p_nivel text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RANK_NIVEL"(p_nivel text) IS 'Ordem numérica do nível de acesso para comparação: admin 3, editor 2, leitor 1, outro 0.';

--
-- Name: FC_RECOLOCAR_NA_CLASSIFICACAO(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RECOLOCAR_NA_CLASSIFICACAO"(p_candidato uuid, p_modalidade_anterior text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_CANDIDATO_APROVADO"%rowtype;
  v_vaga_unica text;
  v_vaga text;
  v_por_modalidade boolean;
  v_ref integer;
  v_posicao integer;
begin
  select * into v from public."TB_CANDIDATO_APROVADO" c where c.id = p_candidato;
  if v.id is null then return null; end if;
  v_ref := coalesce(v.classificacao_original, v.classificacao, 2147483647);

  -- A vaga, como a convocação resolve: o código, ou o único código do cargo.
  select min(btrim(c.codigo_vaga)) into v_vaga_unica
    from public."TB_CANDIDATO_APROVADO" c
   where c.lista_id = v.lista_id and c.cargo = v.cargo and c.removido_em is null
     and nullif(btrim(c.codigo_vaga), '') is not null
  having count(distinct btrim(c.codigo_vaga)) = 1;
  v_vaga := coalesce(nullif(btrim(v.codigo_vaga), ''), v_vaga_unica, '');

  -- Os outros da mesma vaga, na ordem de agora.
  create temporary table if not exists tmp_escala_da_classificacao (
    id uuid, modalidade text, classificacao integer, nota numeric, ref integer, nome text
  ) on commit drop;
  truncate pg_temp.tmp_escala_da_classificacao;
  insert into pg_temp.tmp_escala_da_classificacao
  select c.id, c.modalidade, c.classificacao, c.nota,
         coalesce(c.classificacao_original, c.classificacao, 2147483647), c.nome
    from public."TB_CANDIDATO_APROVADO" c
   where c.lista_id = v.lista_id and c.cargo = v.cargo and c.removido_em is null
     and c.id <> v.id
     and coalesce(nullif(btrim(c.codigo_vaga), ''), v_vaga_unica, '') = v_vaga;

  -- A planilha classificou por modalidade (mesmo número em modalidades diferentes)?
  select exists (
    select 1
      from pg_temp.tmp_escala_da_classificacao a
      join pg_temp.tmp_escala_da_classificacao b
        on a.classificacao = b.classificacao and a.id < b.id
       and a.modalidade is distinct from b.modalidade
  ) into v_por_modalidade;

  -- A escala do candidato: renumera e abre a posição da nota dele.
  with escala as (
    select e.id, e.nota, e.ref,
           (row_number() over (order by e.classificacao nulls last, e.nome, e.id))::integer as posicao
      from pg_temp.tmp_escala_da_classificacao e
     where not v_por_modalidade or e.modalidade is not distinct from v.modalidade
  )
  select case when v.removido_em is not null then null
              else coalesce(min(x.posicao) filter (where x.nota < v.nota or (x.nota = v.nota and x.ref > v_ref)),
                            count(*) + 1)::integer end
    into v_posicao
    from escala x;

  with escala as (
    select e.id,
           (row_number() over (order by e.classificacao nulls last, e.nome, e.id))::integer as posicao
      from pg_temp.tmp_escala_da_classificacao e
     where not v_por_modalidade or e.modalidade is not distinct from v.modalidade
  ), nova as (
    select x.id, case when v_posicao is not null and x.posicao >= v_posicao then x.posicao + 1 else x.posicao end as posicao
      from escala x
  )
  update public."TB_CANDIDATO_APROVADO" c set classificacao = n.posicao
    from nova n
   where c.id = n.id and c.classificacao is distinct from n.posicao;

  if v_posicao is not null then
    update public."TB_CANDIDATO_APROVADO" c set classificacao = v_posicao
     where c.id = v.id and c.classificacao is distinct from v_posicao;
  end if;

  -- Trocou de modalidade numa escala por modalidade: fecha o buraco na de antes.
  if v_por_modalidade and p_modalidade_anterior is distinct from v.modalidade then
    with escala as (
      select e.id,
             (row_number() over (order by e.classificacao nulls last, e.nome, e.id))::integer as posicao
        from pg_temp.tmp_escala_da_classificacao e
       where e.modalidade is not distinct from p_modalidade_anterior
    )
    update public."TB_CANDIDATO_APROVADO" c set classificacao = x.posicao
      from escala x
     where c.id = x.id and c.classificacao is distinct from x.posicao;
  end if;

  return v_posicao;
end;
$$;

--
-- Name: FUNCTION "FC_RECOLOCAR_NA_CLASSIFICACAO"(p_candidato uuid, p_modalidade_anterior text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RECOLOCAR_NA_CLASSIFICACAO"(p_candidato uuid, p_modalidade_anterior text) IS 'Põe o candidato na posição da nota atual dentro da escala dele (cargo e vaga da lista; por modalidade quando a planilha classificou assim) e renumera a escala, mantendo a ordem dos outros; removido só fecha o buraco. Sem checagem: quem chama checa.';

--
-- Name: FC_RECONTAR_PRE_CLASSIF_VAGA(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RECONTAR_PRE_CLASSIF_VAGA"(p_edital uuid, p_vaga text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public."TB_PRE_CLASSIF_VAGA" pv set
    "QT_ELIMINADO" = s.eliminados, "QT_RANQUEADO" = s.ranqueados, "QT_LOTE" = s.lote, "DT_ATUALIZACAO" = now()
    from (select count(*) filter (where a."TP_SITUACAO" = 'ELIMINADO') as eliminados,
                 count(*) filter (where a."TP_SITUACAO" <> 'ELIMINADO') as ranqueados,
                 count(*) filter (where a."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO')) as lote
            from public."TB_PRE_CLASSIFICACAO" a
           where a."CO_MONITORAMENTO" = p_edital and a."CO_VAGA" = p_vaga) s
   where pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" = p_vaga;
$$;

--
-- Name: FUNCTION "FC_RECONTAR_PRE_CLASSIF_VAGA"(p_edital uuid, p_vaga text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RECONTAR_PRE_CLASSIF_VAGA"(p_edital uuid, p_vaga text) IS 'Reconta eliminados, ranqueados e lote (regra + decisão) do resumo da vaga (TB_PRE_CLASSIF_VAGA) depois de uma decisão da coordenação pela tela; o próximo recálculo grava o resumo completo.';

--
-- Name: FC_RECURSOS_MODULO(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RECURSOS_MODULO"() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array['dashboard','analises','nucleo','calendario','aprovados','importacao','paineis','configuracoes','acessos','recursos','entrevistas','selecao','recursos_parecer','classificacao','chat','avaliacao_documental','aprovados_pendencias']::text[];
$$;

--
-- Name: FUNCTION "FC_RECURSOS_MODULO"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RECURSOS_MODULO"() IS 'Módulos da matriz de permissões (espelho de RESOURCES em src/lib/permissoes-recursos.js).';

--
-- Name: FC_REFERENCIA_DO_CASO(text, text, text, text, uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REFERENCIA_DO_CASO"(p_modulo text, p_conferencia text, p_tipo text, p_referencia text, p_analise uuid, p_area text, p_edital uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_tipo text := p_tipo;
  v_uuid uuid;
  r record;
begin
  if p_referencia ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_uuid := p_referencia::uuid;
  end if;
  -- Caso gravado antes do tipo: o código da conferência diz o que é a referência.
  if v_tipo is null then
    v_tipo := case
      when p_modulo = 'aprovados' then 'candidato_aprovado'
      when p_conferencia = 'ENTREVISTA_NOTA_FORA_DA_ESCALA' then 'entrevista'
      when p_conferencia = 'CLASSIFICACAO_LISTA_FINAL_DESATUALIZADA' then 'lista_classificacao'
      when p_conferencia = 'CLASSIFICACAO_EMPATE_PENDENTE' then
        case when v_uuid is not null then 'lista_classificacao' else 'vaga' end
      when p_conferencia = 'CLASSIFICACAO_VAGA_SEM_QUADRO' then 'vaga'
      when p_conferencia = 'CLASSIFICACAO_AJUSTE_APOS_LISTA' then 'ajuste_recurso'
      when p_conferencia = 'CARGA_VARIACAO_BRUSCA' then 'vaga_empregare'
      when p_modulo = 'entrevistas' and p_analise is not null then 'entrevista'
    end;
  end if;
  if v_tipo is null or (p_referencia is null and not (v_tipo = 'entrevista' and p_analise is not null)) then
    return null;
  end if;

  if v_tipo = 'candidato_aprovado' then
    if v_uuid is null then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'removido');
    end if;
    select c.id, c.nome, c.status, c.codigo_vaga, c.cargo, c."DT_CONVOCACAO" as convocacao,
           c.removido_em, l.id as lista, m.id as edital_id, m.edital, m."CO_AREA" as area,
           nullif(btrim(a.id_origem), '') as codigo
      into r
      from public."TB_CANDIDATO_APROVADO" c
      left join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
      left join public."TB_MONITORAMENTO_INDIGENA" m
        on m.id = case when l.edital_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                       then l.edital_id::uuid end
      left join public."TB_ANALISE_CURRICULAR" a on a.id = c."CO_ANALISE_CURRICULAR"
     where c.id = v_uuid;
    if not found or r.removido_em is not null or r.lista is null then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'removido');
    end if;
    if not private."FC_PODE_VER_AVISO"('aprovados', r.area, r.edital_id) then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'sem_acesso');
    end if;
    return jsonb_build_object(
      'tipo', v_tipo, 'resolucao', 'ok', 'aprovado_id', r.id, 'nome', r.nome, 'codigo', r.codigo,
      'edital', r.edital, 'edital_id', r.edital_id, 'codigo_vaga', r.codigo_vaga, 'nome_vaga', r.cargo,
      'status', r.status, 'data_convocacao', r.convocacao,
      'data_contratacao', (select max(h.alterado_em) from public."TH_CANDIDATO_APROVADO" h
                            where h.candidato_id = r.id and h.status_novo = 'Contratado'));
  end if;

  if v_tipo = 'entrevista' then
    if v_uuid is not null then
      select e."CO_ENTREVISTA" as id, e."NO_CANDIDATO" as nome, nullif(btrim(e."CO_CANDIDATO"), '') as codigo,
             e."CO_VAGA" as codigo_vaga, e."NO_CARGO" as cargo, e."VL_NOTA_TOTAL" as nota,
             e."TP_PARECER" as parecer, e."ST_COMPARECEU" as compareceu, e."ST_ATIVO" as ativo,
             e."CO_AREA" as area, e."CO_MONITORAMENTO" as edital_id, coalesce(m.edital, e."DS_EDITAL") as edital
        into r
        from public."TB_ENTREVISTA" e
        left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = e."CO_MONITORAMENTO"
       where e."CO_ENTREVISTA" = v_uuid;
      if not found then
        return jsonb_build_object('tipo', v_tipo, 'resolucao', 'removido');
      end if;
    elsif p_referencia is null then
      -- Caso de entrevista pela análise: a entrevista ativa dela no edital do aviso.
      select e."CO_ENTREVISTA" as id, e."NO_CANDIDATO" as nome, nullif(btrim(e."CO_CANDIDATO"), '') as codigo,
             e."CO_VAGA" as codigo_vaga, e."NO_CARGO" as cargo, e."VL_NOTA_TOTAL" as nota,
             e."TP_PARECER" as parecer, e."ST_COMPARECEU" as compareceu, e."ST_ATIVO" as ativo,
             e."CO_AREA" as area, e."CO_MONITORAMENTO" as edital_id, coalesce(m.edital, e."DS_EDITAL") as edital
        into r
        from public."TB_ENTREVISTA" e
        left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = e."CO_MONITORAMENTO"
       where e."CO_ANALISE_CURRICULAR" = p_analise
         and coalesce(e."ST_ATIVO", 'S') = 'S'
         and (p_edital is null or e."CO_MONITORAMENTO" = p_edital)
       order by e."DT_ATUALIZACAO" desc nulls last, e."CO_ENTREVISTA"
       limit 1;
      if not found then
        return null;
      end if;
    else
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'removido');
    end if;
    if coalesce(r.ativo, 'S') <> 'S' then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'removido');
    end if;
    if not private."FC_PODE_VER_AVISO"('entrevistas', r.area, r.edital_id) then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'sem_acesso');
    end if;
    return jsonb_build_object(
      'tipo', v_tipo, 'resolucao', 'ok', 'entrevista_id', r.id, 'nome', r.nome, 'codigo', r.codigo,
      'edital', r.edital, 'edital_id', r.edital_id, 'codigo_vaga', r.codigo_vaga, 'nome_vaga', r.cargo,
      'status', r.parecer, 'nota', r.nota, 'compareceu', r.compareceu);
  end if;

  if v_tipo = 'lista_classificacao' then
    select l."CO_LISTA_CLASSIFICACAO" as id, l."TP_LISTA" as tipo_lista, l."DT_GERACAO" as gerada_em,
           l."QT_PENDENCIA" as pendencias, l."ST_PUBLICADA" as publicada,
           m.id as edital_id, m.edital, m."CO_AREA" as area
      into r
      from public."TB_LISTA_CLASSIFICACAO" l
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = l."CO_MONITORAMENTO"
     where l."CO_LISTA_CLASSIFICACAO" = v_uuid;
    if not found then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'removido');
    end if;
    if not private."FC_PODE_VER_AVISO"('classificacao', r.area, r.edital_id) then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'sem_acesso');
    end if;
    return jsonb_build_object(
      'tipo', v_tipo, 'resolucao', 'ok', 'edital', r.edital, 'edital_id', r.edital_id,
      'lista', jsonb_build_object('tipo', r.tipo_lista, 'gerada_em', r.gerada_em,
                                  'pendencias', r.pendencias, 'publicada', r.publicada = 'S'));
  end if;

  if v_tipo = 'ajuste_recurso' then
    select j."CO_AJUSTE_PONTUACAO" as id, j."TP_SITUACAO" as situacao, j."TP_LISTA" as tipo_lista,
           j."DT_APROVACAO" as aprovado_em, m.id as edital_id, m.edital, m."CO_AREA" as area,
           a.id as analise_id, a.candidato, nullif(btrim(a.id_origem), '') as codigo, a.codigo_vaga, a.nome_vaga
      into r
      from public."TB_AJUSTE_PONTUACAO_RECURSO" j
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = j."CO_MONITORAMENTO"
      left join public."TB_ANALISE_CURRICULAR" a on a.id = j."CO_ANALISE_CURRICULAR"
     where j."CO_AJUSTE_PONTUACAO" = v_uuid;
    if not found then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'removido');
    end if;
    if not private."FC_PODE_VER_AVISO"('classificacao', r.area, r.edital_id) then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'sem_acesso');
    end if;
    return jsonb_build_object(
      'tipo', v_tipo, 'resolucao', 'ok', 'analise_id', r.analise_id, 'nome', r.candidato, 'codigo', r.codigo,
      'edital', r.edital, 'edital_id', r.edital_id, 'codigo_vaga', r.codigo_vaga, 'nome_vaga', r.nome_vaga,
      'status', r.situacao, 'lista', jsonb_build_object('tipo', r.tipo_lista, 'aprovado_em', r.aprovado_em));
  end if;

  if v_tipo = 'vaga' then
    -- A vaga do edital do aviso: quem chama já vê o aviso (a leitura só resolve casos de avisos visíveis).
    return jsonb_build_object(
      'tipo', v_tipo, 'resolucao', 'ok', 'edital_id', p_edital,
      'edital', (select m.edital from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital),
      'codigo_vaga', case when p_referencia = 'sem-codigo' then null else p_referencia end,
      'nome_vaga', (select a.nome_vaga from public."TB_ANALISE_CURRICULAR" a
                     where a.codigo_vaga = p_referencia and a."CO_AREA" = p_area and a.ativo is true
                       and nullif(btrim(a.nome_vaga), '') is not null
                     limit 1));
  end if;

  if v_tipo = 'vaga_empregare' then
    select v."CO_VAGA" as codigo, v."QT_CANDIDATO_ATIVO" as ativos, m.id as edital_id, m.edital,
           coalesce(m."CO_AREA", p_area) as area
      into r
      from public."TB_EMPREGARE_VAGA" v
      left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = v."CO_MONITORAMENTO"
     where v."CO_VAGA" = p_referencia;
    if not found then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'removido');
    end if;
    if not private."FC_PODE_VER_AVISO"('cargas', r.area, r.edital_id) then
      return jsonb_build_object('tipo', v_tipo, 'resolucao', 'sem_acesso');
    end if;
    return jsonb_build_object(
      'tipo', v_tipo, 'resolucao', 'ok', 'edital', r.edital, 'edital_id', r.edital_id,
      'codigo_vaga', r.codigo, 'candidatos', r.ativos,
      'nome_vaga', (select a.nome_vaga from public."TB_ANALISE_CURRICULAR" a
                     where a.codigo_vaga = r.codigo and a.ativo is true
                       and nullif(btrim(a.nome_vaga), '') is not null
                     limit 1));
  end if;

  return null;
end;
$_$;

--
-- Name: FUNCTION "FC_REFERENCIA_DO_CASO"(p_modulo text, p_conferencia text, p_tipo text, p_referencia text, p_analise uuid, p_area text, p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REFERENCIA_DO_CASO"(p_modulo text, p_conferencia text, p_tipo text, p_referencia text, p_analise uuid, p_area text, p_edital uuid) IS 'Resolve a referência de um caso de aviso (aprovado, entrevista, lista, ajuste, vaga) com a permissão do módulo de quem chama sobre o REGISTRO (FC_PODE_VER_AVISO com a área e o edital dele): nome, código, edital, vaga, situação, datas, nota. resolucao = ok, removido (não existe mais) ou sem_acesso (sem nenhum dado). Sem tipo gravado, deduz pelo código da conferência. Sem CPF.';

--
-- Name: FC_REGISTRAR_LISTA_CLASSIFICACAO(uuid, text, integer, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGISTRAR_LISTA_CLASSIFICACAO"(p_edital uuid, p_tipo text, p_versao integer, p_resultado jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_regra public."TB_REGRA_CLASSIFICACAO";
  v_id uuid;
  v_totais jsonb := coalesce(p_resultado -> 'totais', '{}'::jsonb);
  v_qt integer[];
begin
  if p_tipo is null or p_tipo not in ('PRELIMINAR', 'CONVOCACAO', 'ENTREVISTA', 'FINAL') then
    raise exception 'Tipo de lista inválido' using errcode = '22023';
  end if;
  select * into v_regra from public."TB_REGRA_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital;
  if v_regra."CO_REGRA_CLASSIFICACAO" is null then
    raise exception 'Salve a regra do edital antes de gerar a lista.' using errcode = '22023';
  end if;
  if p_versao is distinct from v_regra."NU_VERSAO_VIGENTE" then
    raise exception 'A regra mudou (versão %); gere de novo.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
  end if;
  if jsonb_typeof(p_resultado) is distinct from 'object' or jsonb_typeof(p_resultado -> 'vagas') is distinct from 'array'
     or p_resultado ->> 'tipo' is distinct from p_tipo then
    raise exception 'Lista inválida.' using errcode = '22023';
  end if;
  if pg_column_size(p_resultado) > 8000000 then
    raise exception 'Lista grande demais para registrar.' using errcode = '22023';
  end if;
  -- Os candidatos do retrato são análises ativas deste edital (20261006070000).
  perform private."FC_EXIGIR_CANDIDATOS_DO_EDITAL"(p_edital, p_resultado);
  select array_agg(case when jsonb_typeof(v_totais -> k) = 'number'
                        then greatest(0, least(1000000, (v_totais ->> k)::numeric))::integer else 0 end order by o)
    into v_qt
    from unnest(array['elegiveis', 'eliminados', 'avisos', 'pendencias']) with ordinality t(k, o);

  insert into public."TB_LISTA_CLASSIFICACAO"
    ("CO_MONITORAMENTO", "TP_LISTA", "CO_REGRA_CLASSIFICACAO", "NU_VERSAO_REGRA", "DS_RESULTADO", "DS_HASH",
     "QT_ELEGIVEL", "QT_ELIMINADO", "QT_AVISO", "QT_PENDENCIA", "CO_USUARIO")
  values (p_edital, p_tipo, v_regra."CO_REGRA_CLASSIFICACAO", v_regra."NU_VERSAO_VIGENTE", p_resultado,
          private."FC_HASH_RETRATO_CLASSIFICACAO"(p_resultado),
          v_qt[1], v_qt[2], v_qt[3], v_qt[4], (select auth.uid()))
  returning "CO_LISTA_CLASSIFICACAO" into v_id;

  -- O relatório de desempate desta lista, pelo Python (20261023170000).
  perform private."FC_PEDIR_DESEMPATE"(v_id, (select auth.uid()));

  return v_id;
end;
$$;

--
-- Name: FUNCTION "FC_REGISTRAR_LISTA_CLASSIFICACAO"(p_edital uuid, p_tipo text, p_versao integer, p_resultado jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REGISTRAR_LISTA_CLASSIFICACAO"(p_edital uuid, p_tipo text, p_versao integer, p_resultado jsonb) IS 'Registra uma lista gerada (20261023200000; o corpo de registrar_lista_classificacao de 20261023170000): confere o tipo, a versão vigente da regra (PT409), a forma, o tamanho e os candidatos do retrato, grava com o hash SHA-256 do conteúdo calculado aqui (FC_HASH_RETRATO_CLASSIFICACAO, 20261024130000) e pede o relatório de desempate (FC_PEDIR_DESEMPATE). Devolve o id da lista. Sem porteiro: só o dono (registrar_lista_classificacao e registrar_lista_calculada, que conferem a permissão).';

--
-- Name: FC_REGRA_AGENDA_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGRA_AGENDA_JSON"(p_edital uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
           'versao', r."NU_VERSAO_VIGENTE",
           'configuracao', v."DS_CONFIGURACAO",
           'atualizado_em', v."DT_CRIACAO",
           'por', coalesce(p.nome, p.email),
           'versoes', coalesce((
             select json_agg(json_build_object(
                      'versao', h."NU_VERSAO", 'em', h."DT_CRIACAO", 'por', coalesce(pu.nome, pu.email),
                      'motivo', h."DS_MOTIVO")
                    order by h."NU_VERSAO" desc)
               from public."TH_REGRA_AGENDA_ENTREVISTA" h
               left join public."TB_PERFIL_USUARIO" pu on pu.user_id = h."CO_USUARIO"
              where h."CO_REGRA_AGENDA" = r."CO_REGRA_AGENDA"), '[]'::json))
    from public."TB_REGRA_AGENDA_ENTREVISTA" r
    join public."TH_REGRA_AGENDA_ENTREVISTA" v
      on v."CO_REGRA_AGENDA" = r."CO_REGRA_AGENDA" and v."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
    left join public."TB_PERFIL_USUARIO" p on p.user_id = v."CO_USUARIO"
   where r."CO_MONITORAMENTO" = p_edital;
$$;

--
-- Name: FUNCTION "FC_REGRA_AGENDA_JSON"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REGRA_AGENDA_JSON"(p_edital uuid) IS 'Regra da agenda vigente do edital (versão, configuração, quem e quando) e o histórico de versões; null sem regra.';

--
-- Name: FC_REGRA_ANALISE_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGRA_ANALISE_JSON"(p_edital uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
           'versao', r."NU_VERSAO_VIGENTE",
           'nome', v."NO_VERSAO",
           'situacao', r."TP_SITUACAO",
           'modelo_origem', r."CO_MODELO_ORIGEM",
           'configuracao', v."DS_CONFIGURACAO",
           'hash', v."DS_HASH",
           'atualizado_em', v."DT_CRIACAO",
           'por', coalesce(p.nome, p.email),
           'conferida_em', r."DT_CONFERENCIA",
           'conferida_por', coalesce(pc.nome, pc.email),
           'conferir_pede_outra_pessoa',
             coalesce(v."CO_USUARIO" = (select auth.uid()), false) and not private.is_master(),
           'versoes', coalesce((
             select json_agg(json_build_object(
                      'versao', h."NU_VERSAO", 'nome', h."NO_VERSAO", 'em', h."DT_CRIACAO", 'por', coalesce(pu.nome, pu.email),
                      'motivo', h."DS_MOTIVO", 'hash', h."DS_HASH", 'configuracao', h."DS_CONFIGURACAO",
                      'renomeacoes', private."FC_RENOMEACOES_JSON"('ANALISE', h."CO_REGRA_ANALISE", h."NU_VERSAO"))
                    order by h."NU_VERSAO" desc)
               from public."TH_REGRA_ANALISE" h
               left join public."TB_PERFIL_USUARIO" pu on pu.user_id = h."CO_USUARIO"
              where h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE"), '[]'::json))
    from public."TB_REGRA_ANALISE" r
    join public."TH_REGRA_ANALISE" v
      on v."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and v."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
    left join public."TB_PERFIL_USUARIO" p on p.user_id = v."CO_USUARIO"
    left join public."TB_PERFIL_USUARIO" pc on pc.user_id = r."CO_USUARIO_CONFERENCIA"
   where r."CO_MONITORAMENTO" = p_edital;
$$;

--
-- Name: FUNCTION "FC_REGRA_ANALISE_JSON"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REGRA_ANALISE_JSON"(p_edital uuid) IS 'Regra da avaliação vigente do edital (versão, nome da versão, situação, configuração, hash, quem e quando, conferência, e se quem está logado precisa de outra pessoa para conferir: salvou a versão vigente e não é administrador global) e o histórico de versões (com o nome e as trocas de nome); null sem regra.';

--
-- Name: FC_REGRA_CLASSIFICACAO_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGRA_CLASSIFICACAO_JSON"(p_edital uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
           'versao', r."NU_VERSAO_VIGENTE",
           'nome', v."NO_VERSAO",
           'configuracao', v."DS_CONFIGURACAO",
           'atualizado_em', v."DT_CRIACAO",
           'por', coalesce(p.nome, p.email),
           'versoes', coalesce((
             select json_agg(json_build_object(
                      'versao', h."NU_VERSAO", 'nome', h."NO_VERSAO", 'em', h."DT_CRIACAO", 'por', coalesce(pu.nome, pu.email),
                      'motivo', h."DS_MOTIVO", 'empate_final', h."TP_EMPATE_FINAL", 'configuracao', h."DS_CONFIGURACAO",
                      'renomeacoes', private."FC_RENOMEACOES_JSON"('CLASSIFICACAO', h."CO_REGRA_CLASSIFICACAO", h."NU_VERSAO"))
                    order by h."NU_VERSAO" desc)
               from public."TH_REGRA_CLASSIFICACAO" h
               left join public."TB_PERFIL_USUARIO" pu on pu.user_id = h."CO_USUARIO"
              where h."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO"), '[]'::json))
    from public."TB_REGRA_CLASSIFICACAO" r
    join public."TH_REGRA_CLASSIFICACAO" v
      on v."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO" and v."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
    left join public."TB_PERFIL_USUARIO" p on p.user_id = v."CO_USUARIO"
   where r."CO_MONITORAMENTO" = p_edital;
$$;

--
-- Name: FUNCTION "FC_REGRA_CLASSIFICACAO_JSON"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REGRA_CLASSIFICACAO_JSON"(p_edital uuid) IS 'Regra de classificação vigente do edital (versão, nome da versão, configuração, quem e quando) e o histórico de versões (com o nome e as trocas de nome); null sem regra.';

--
-- Name: FC_REGRA_COM_DATA_LIMITE(jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGRA_COM_DATA_LIMITE"(p_configuracao jsonb, p_edital uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_fim date;
begin
  if jsonb_typeof(p_configuracao -> 'blocos') is distinct from 'array'
     or not exists (select 1 from jsonb_array_elements(p_configuracao -> 'blocos') b
                     where b ->> 'tipo' = 'VINCULOS' and coalesce(b ->> 'data_limite', '') = '') then
    return p_configuracao;
  end if;
  v_fim := private."FC_FIM_DAS_INSCRICOES"(p_edital);
  if v_fim is null then
    return p_configuracao;
  end if;
  return jsonb_set(p_configuracao, '{blocos}', (
    select jsonb_agg(case when b ->> 'tipo' = 'VINCULOS' and coalesce(b ->> 'data_limite', '') = ''
                          then b || jsonb_build_object('data_limite', to_char(v_fim, 'YYYY-MM-DD')) else b end order by n)
      from jsonb_array_elements(p_configuracao -> 'blocos') with ordinality x(b, n)));
end;
$$;

--
-- Name: FC_REGRA_DA_VAGA(jsonb, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGRA_DA_VAGA"(p_regra jsonb, p_vaga text, p_cargo text, p_nivel text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_diferenca jsonb := private."FC_DIFERENCA_DA_VAGA"(p_regra, p_vaga, p_cargo);
begin
  if v_diferenca is null or jsonb_typeof(p_regra -> 'blocos') is distinct from 'array' then
    return p_regra;
  end if;
  return p_regra || jsonb_build_object(
    'por_cargo', '[]'::jsonb,
    'cargo', jsonb_build_object('codigo', v_diferenca -> 'codigo', 'rotulo', v_diferenca -> 'rotulo'),
    'blocos', coalesce((
      select jsonb_agg(case when jsonb_typeof(b) = 'object'
                            then private."FC_BLOCO_DO_CARGO"(b, v_diferenca #> array['blocos', b ->> 'codigo'], p_nivel)
                            else b end order by n)
        from jsonb_array_elements(p_regra -> 'blocos') with ordinality x(b, n)), '[]'::jsonb));
end;
$$;

--
-- Name: FUNCTION "FC_REGRA_DA_VAGA"(p_regra jsonb, p_vaga text, p_cargo text, p_nivel text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REGRA_DA_VAGA"(p_regra jsonb, p_vaga text, p_cargo text, p_nivel text) IS 'A regra que vale para a ficha: a diferença do cargo da vaga (regra.por_cargo) aplicada a cada bloco, por_cargo vazio e cargo = {codigo, rotulo}. Sem diferença, a própria regra. Igual a regraDaVaga (regra-por-cargo.ts) e regra_da_vaga (pontuacao.py); salvar_rascunho_ficha e concluir_ficha validam contra ela.';

--
-- Name: FC_REGRA_DO_TREINAMENTO(uuid, jsonb, text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGRA_DO_TREINAMENTO"(p_edital uuid, p_config jsonb, p_situacao text, p_motivo text, p_uid uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_regra public."TB_REGRA_ANALISE";
  v_vigente jsonb;
  v_versao integer;
begin
  if not private."FC_EDITAL_EH_TREINAMENTO"(p_edital) then
    raise exception 'Só o edital de treinamento recebe regra copiada por aqui' using errcode = '42501';
  end if;
  perform private."FC_VALIDAR_REGRA_ANALISE"(p_config);
  select * into v_regra from public."TB_REGRA_ANALISE" r where r."CO_MONITORAMENTO" = p_edital for update;
  if v_regra."CO_REGRA_ANALISE" is null then
    insert into public."TB_REGRA_ANALISE" ("CO_MONITORAMENTO", "NU_VERSAO_VIGENTE", "TP_SITUACAO", "CO_MODELO_ORIGEM",
      "CO_USUARIO_ATUALIZACAO", "CO_USUARIO_CONFERENCIA", "DT_CONFERENCIA")
    values (p_edital, 1, p_situacao, p_config ->> 'modelo', p_uid,
            case when p_situacao = 'CONFERIDA' then p_uid end, case when p_situacao = 'CONFERIDA' then now() end)
    returning * into v_regra;
    insert into public."TH_REGRA_ANALISE" ("CO_REGRA_ANALISE", "NU_VERSAO", "DS_CONFIGURACAO", "DS_HASH", "DS_MOTIVO", "CO_USUARIO")
    values (v_regra."CO_REGRA_ANALISE", 1, p_config, encode(sha256(convert_to(p_config::text, 'UTF8')), 'hex'), p_motivo, p_uid);
    return 1;
  end if;
  select h."DS_CONFIGURACAO" into v_vigente
    from public."TH_REGRA_ANALISE" h
   where h."CO_REGRA_ANALISE" = v_regra."CO_REGRA_ANALISE" and h."NU_VERSAO" = v_regra."NU_VERSAO_VIGENTE";
  -- A vigente já é deste modelo (talvez editada no treino): fica como está.
  if v_vigente ->> 'modelo' is not distinct from p_config ->> 'modelo' then
    return v_regra."NU_VERSAO_VIGENTE";
  end if;
  select coalesce(max(h."NU_VERSAO"), 0) + 1 into v_versao
    from public."TH_REGRA_ANALISE" h where h."CO_REGRA_ANALISE" = v_regra."CO_REGRA_ANALISE";
  insert into public."TH_REGRA_ANALISE" ("CO_REGRA_ANALISE", "NU_VERSAO", "DS_CONFIGURACAO", "DS_HASH", "DS_MOTIVO", "CO_USUARIO")
  values (v_regra."CO_REGRA_ANALISE", v_versao, p_config, encode(sha256(convert_to(p_config::text, 'UTF8')), 'hex'), p_motivo, p_uid);
  update public."TB_REGRA_ANALISE" set
    "NU_VERSAO_VIGENTE" = v_versao, "TP_SITUACAO" = p_situacao, "CO_MODELO_ORIGEM" = p_config ->> 'modelo',
    "CO_USUARIO_ATUALIZACAO" = p_uid,
    "CO_USUARIO_CONFERENCIA" = case when p_situacao = 'CONFERIDA' then p_uid end,
    "DT_CONFERENCIA" = case when p_situacao = 'CONFERIDA' then now() end,
    "DT_ATUALIZACAO" = now()
   where "CO_REGRA_ANALISE" = v_regra."CO_REGRA_ANALISE";
  return v_versao;
end;
$$;

--
-- Name: FUNCTION "FC_REGRA_DO_TREINAMENTO"(p_edital uuid, p_config jsonb, p_situacao text, p_motivo text, p_uid uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REGRA_DO_TREINAMENTO"(p_edital uuid, p_config jsonb, p_situacao text, p_motivo text, p_uid uuid) IS 'Edital de treinamento: grava a regra da avaliação documental copiada (só o JSON; cópia independente do edital real de origem). Sem regra: versão 1; vigente de outro modelo: versão seguinte; do mesmo modelo: não mexe. Recusa edital real.';

--
-- Name: FC_REGRA_TRIAGEM_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGRA_TRIAGEM_JSON"(p_edital uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
           'versao', r."NU_VERSAO_VIGENTE",
           'nome', h."NO_VERSAO",
           'situacao', r."TP_SITUACAO",
           'configuracao', h."DS_CONFIGURACAO",
           'hash', h."DS_HASH",
           'atualizada_em', r."DT_ATUALIZACAO",
           'conferida_em', r."DT_CONFERENCIA",
           'versoes', coalesce((
             select json_agg(json_build_object('versao', v."NU_VERSAO", 'nome', v."NO_VERSAO", 'motivo', v."DS_MOTIVO",
                                               'criada_em', v."DT_CRIACAO", 'origem', v."DS_ORIGEM")
                    order by v."NU_VERSAO" desc)
               from public."TH_REGRA_TRIAGEM" v where v."CO_REGRA_TRIAGEM" = r."CO_REGRA_TRIAGEM"), '[]'::json))
    from public."TB_REGRA_TRIAGEM" r
    join public."TH_REGRA_TRIAGEM" h
      on h."CO_REGRA_TRIAGEM" = r."CO_REGRA_TRIAGEM" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
   where r."CO_MONITORAMENTO" = p_edital;
$$;

--
-- Name: FC_REGRA_VIGENTE_FICHA(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REGRA_VIGENTE_FICHA"(p_ficha uuid, OUT p_versao integer, OUT p_situacao text, OUT p_configuracao jsonb) RETURNS record
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select h."NU_VERSAO", case when h."NU_VERSAO" = r."NU_VERSAO_VIGENTE" then r."TP_SITUACAO" else 'CONFERIDA' end,
         private."FC_REGRA_COM_DATA_LIMITE"(h."DS_CONFIGURACAO", f."CO_MONITORAMENTO")
    from public."TB_FICHA_ANALISE" f
    join public."TB_REGRA_ANALISE" r on r."CO_REGRA_ANALISE" = f."CO_REGRA_ANALISE"
    join public."TH_REGRA_ANALISE" h
      on h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE"
     and h."NU_VERSAO" = case when f."TP_SITUACAO" = 'CONCLUIDA' then f."NU_VERSAO_REGRA" else r."NU_VERSAO_VIGENTE" end
   where f."CO_FICHA_ANALISE" = p_ficha;
$$;

--
-- Name: FUNCTION "FC_REGRA_VIGENTE_FICHA"(p_ficha uuid, OUT p_versao integer, OUT p_situacao text, OUT p_configuracao jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REGRA_VIGENTE_FICHA"(p_ficha uuid, OUT p_versao integer, OUT p_situacao text, OUT p_configuracao jsonb) IS 'A regra com que a ficha é analisada (AM-2.3): a versão gravada se concluída; senão a vigente do edital (com a situação Conferir/Conferida).';

--
-- Name: FC_REINICIAR_FICHAS_DO_EDITAL(uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REINICIAR_FICHAS_DO_EDITAL"(p_edital uuid, p_motivo text, p_usuario uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_motivo text := btrim(coalesce(p_motivo, ''));
  v_f public."TB_FICHA_ANALISE";
  v_para text;
  v_antes jsonb := '{}'::jsonb;
  v_reiniciadas integer := 0;
  v_no_inicio integer := 0;
  v_fora integer := 0;
  v_bloqueio text;
begin
  if length(v_motivo) not between 10 and 2000 then
    raise exception 'Informe o motivo para reiniciar as fichas (10 a 2.000 caracteres).' using errcode = '22023';
  end if;
  if not private."FC_ADMIN_GLOBAL_ATIVO"(p_usuario) then
    raise exception 'Só o administrador global reinicia as fichas do edital' using errcode = '42501';
  end if;
  -- Trava o edital: ninguém abre fichas novas dele enquanto o reinício corre.
  perform 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital for update;
  if not found then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  -- Edital congelado ou encerrado: por nenhum caminho (20261022210000).
  v_bloqueio := private."FC_BLOQUEIO_REINICIO_FICHAS"(p_edital);
  if v_bloqueio is not null then
    raise exception '%', v_bloqueio using errcode = '55000';
  end if;

  for v_f in
    select * from public."TB_FICHA_ANALISE" f
     where f."CO_MONITORAMENTO" = p_edital
     order by f."CO_FICHA_ANALISE"
       for update
  loop
    -- A mesma régua do refazer do lote: campos ou histórico depois do último REINICIAR.
    if not private."FC_FICHA_INICIADA"(v_f) then
      if v_f."TP_SITUACAO" = 'FORA_LOTE' then
        v_fora := v_fora + 1;
      else
        v_no_inicio := v_no_inicio + 1;
      end if;
      continue;
    end if;
    -- Fora do lote continua fora (com o motivo da saída); o resto volta a PENDENTE.
    v_para := case when v_f."TP_SITUACAO" = 'FORA_LOTE' then 'FORA_LOTE' else 'PENDENTE' end;

    update public."TB_FICHA_ANALISE" set
      "TP_SITUACAO" = v_para,
      "CO_USUARIO_RESPONSAVEL" = null, "DT_ATRIBUICAO" = null,
      "CO_USUARIO_RESERVA" = null, "DT_RESERVA" = null, "DT_RESERVA_EXPIRA" = null,
      "DS_LANCAMENTO" = null, "DS_RESULTADO" = null, "DS_PARECER" = null, "TP_RESULTADO" = null,
      "VL_NOTA_APURADA" = null, "VL_NOTA_FINAL" = null,
      "CO_USUARIO_RASCUNHO" = null, "DT_RASCUNHO" = null,
      "CO_USUARIO_CONCLUSAO" = null, "DT_CONCLUSAO" = null,
      "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
     where "CO_FICHA_ANALISE" = v_f."CO_FICHA_ANALISE";

    insert into public."TH_FICHA_ANALISE"
      ("CO_FICHA_ANALISE", "NU_VERSAO", "TP_ACAO", "TP_SITUACAO_ANTERIOR", "TP_SITUACAO", "CO_USUARIO_RESP_ANTERIOR",
       "CO_USUARIO_RESPONSAVEL", "DS_MOTIVO", "TP_ORIGEM", "CO_USUARIO", "TP_RESULTADO", "VL_NOTA_FINAL", "DS_ALTERACAO")
    select v_f."CO_FICHA_ANALISE", v_f."NU_VERSAO" + 1, 'REINICIAR', v_f."TP_SITUACAO", v_para,
           v_f."CO_USUARIO_RESPONSAVEL", null, v_motivo, 'TELA', p_usuario, null, null,
           coalesce(jsonb_agg(jsonb_build_object('campo', a.campo, 'de', a.de, 'para', a.para) order by a.ordem), '[]'::jsonb)
      from (values
              (1, 'situacao', to_jsonb(v_f."TP_SITUACAO"), to_jsonb(v_para)),
              (2, 'responsavel', to_jsonb(v_f."CO_USUARIO_RESPONSAVEL"), null),
              (3, 'reserva', to_jsonb(v_f."CO_USUARIO_RESERVA"), null),
              (4, 'resultado', to_jsonb(v_f."TP_RESULTADO"), null),
              (5, 'nota_apurada', to_jsonb(v_f."VL_NOTA_APURADA"), null),
              (6, 'nota_final', to_jsonb(v_f."VL_NOTA_FINAL"), null),
              (7, 'lancamento', v_f."DS_LANCAMENTO", null),
              (8, 'resultado_da_conta', v_f."DS_RESULTADO", null),
              (9, 'parecer', to_jsonb(v_f."DS_PARECER"), null),
              (10, 'rascunho', to_jsonb(v_f."DT_RASCUNHO"), null),
              (11, 'conclusao', to_jsonb(v_f."DT_CONCLUSAO"), null)
           ) as a(ordem, campo, de, para)
     where a.de is distinct from a.para;

    v_reiniciadas := v_reiniciadas + 1;
    v_antes := jsonb_set(v_antes, array[v_f."TP_SITUACAO"]::text[],
                         to_jsonb(coalesce((v_antes ->> v_f."TP_SITUACAO")::integer, 0) + 1));
  end loop;

  return json_build_object('edital', p_edital, 'reiniciadas', v_reiniciadas, 'por_situacao_anterior', v_antes,
                           'ja_no_inicio', v_no_inicio, 'fora_do_lote', v_fora, 'reiniciado_em', now());
end;
$$;

--
-- Name: FUNCTION "FC_REINICIAR_FICHAS_DO_EDITAL"(p_edital uuid, p_motivo text, p_usuario uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REINICIAR_FICHAS_DO_EDITAL"(p_edital uuid, p_motivo text, p_usuario uuid) IS 'Volta ao início toda ficha iniciada do edital (FC_FICHA_INICIADA: campos ou histórico depois do último REINICIAR): a do lote volta a PENDENTE; a FORA_LOTE continua FORA_LOTE. Sem responsável, reserva, lançamento, resultado, parecer, notas, rascunho e conclusão; versão + 1; histórico REINICIAR com o motivo (10 a 2.000), o autor (admin global ativo, 42501) e o que foi limpo. Recusa (55000) edital com inscrições congeladas ou encerrado (FC_BLOQUEIO_REINICIO_FICHAS, 20261022210000). Sem grant: chamado por reiniciar_fichas_do_edital (edital sem ficha trabalhada) e aprovar_reinicio_fichas_do_edital (dois administradores).';

--
-- Name: FC_REINICIO_TREINAMENTO_PERMITE(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_REINICIO_TREINAMENTO_PERMITE"(p_tabela text, p_linha jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_alvo text := nullif(current_setting('agsus.reinicio_treinamento', true), '');
  v_edital uuid;
begin
  if v_alvo is null or v_alvo !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return false;
  end if;
  v_edital := v_alvo::uuid;
  if not private."FC_EDITAL_EH_TREINAMENTO"(v_edital) then
    return false;
  end if;
  if p_linha ? 'CO_MONITORAMENTO' then
    return p_linha ->> 'CO_MONITORAMENTO' = v_edital::text;
  end if;
  -- Linhas sem o edital: confere pelo pai (que ainda existe: filhos saem antes).
  return case p_tabela
    when 'TH_FICHA_ANALISE' then exists (select 1 from public."TB_FICHA_ANALISE" f
      where f."CO_FICHA_ANALISE"::text = p_linha ->> 'CO_FICHA_ANALISE' and f."CO_MONITORAMENTO" = v_edital)
    when 'TL_ACESSO_FICHA_ANALISE' then exists (select 1 from public."TB_FICHA_ANALISE" f
      where f."CO_FICHA_ANALISE"::text = p_linha ->> 'CO_FICHA_ANALISE' and f."CO_MONITORAMENTO" = v_edital)
    when 'TH_DECISAO_LOTE' then exists (select 1 from public."TB_DECISAO_LOTE" d
      where d."CO_DECISAO_LOTE"::text = p_linha ->> 'CO_DECISAO_LOTE' and d."CO_MONITORAMENTO" = v_edital)
    when 'TH_REGRA_ANALISE' then exists (select 1 from public."TB_REGRA_ANALISE" r
      where r."CO_REGRA_ANALISE"::text = p_linha ->> 'CO_REGRA_ANALISE' and r."CO_MONITORAMENTO" = v_edital)
    when 'TB_ITEM_AJUSTE_PONTUACAO' then exists (select 1 from public."TB_AJUSTE_PONTUACAO_RECURSO" j
      where j."CO_AJUSTE_PONTUACAO"::text = p_linha ->> 'CO_AJUSTE_PONTUACAO' and j."CO_MONITORAMENTO" = v_edital)
    else false
  end;
end;
$_$;

--
-- Name: FUNCTION "FC_REINICIO_TREINAMENTO_PERMITE"(p_tabela text, p_linha jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_REINICIO_TREINAMENTO_PERMITE"(p_tabela text, p_linha jsonb) IS 'Os gatilhos de imutabilidade deixam apagar a linha? Só quando a transação marcou agsus.reinicio_treinamento com o id de um edital de TREINAMENTO e a linha é desse edital (direto ou pelo pai). Quem marca é só private."FC_APAGAR_DADOS_DO_TREINAMENTO".';

--
-- Name: FC_RENOMEACOES_JSON(text, uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RENOMEACOES_JSON"(p_tipo text, p_regra uuid, p_versao integer) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(json_agg(json_build_object(
           'em', n."DT_CRIACAO", 'por', coalesce(u.nome, u.email),
           'de', n."NO_VERSAO_ANTERIOR", 'para', n."NO_VERSAO_NOVO", 'motivo', n."DS_MOTIVO")
         order by n."DT_CRIACAO" desc), '[]'::json)
    from public."TH_NOME_VERSAO_REGRA" n
    left join public."TB_PERFIL_USUARIO" u on u.user_id = n."CO_USUARIO"
   where n."TP_REGRA" = p_tipo and n."CO_REGRA" = p_regra and n."NU_VERSAO" = p_versao;
$$;

--
-- Name: FUNCTION "FC_RENOMEACOES_JSON"(p_tipo text, p_regra uuid, p_versao integer); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RENOMEACOES_JSON"(p_tipo text, p_regra uuid, p_versao integer) IS 'As trocas de nome de uma versão de regra (mais recente primeiro): em, por, de, para, motivo.';

--
-- Name: FC_RESERVAR_FICHA(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RESERVAR_FICHA"(p_ficha uuid, p_usuario uuid, p_acao text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_antes public."TB_FICHA_ANALISE";
begin
  select * into v_antes from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha for update;
  update public."TB_FICHA_ANALISE" set
    "CO_USUARIO_RESPONSAVEL" = coalesce("CO_USUARIO_RESPONSAVEL", p_usuario),
    "DT_ATRIBUICAO" = coalesce("DT_ATRIBUICAO", now()),
    "TP_SITUACAO" = case when "TP_SITUACAO" = 'PENDENTE' then 'EM_ANALISE' else "TP_SITUACAO" end,
    "CO_USUARIO_RESERVA" = p_usuario, "DT_RESERVA" = now(),
    "DT_RESERVA_EXPIRA" = now() + private."FC_PRAZO_RESERVA_FICHA"(),
    "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
   where "CO_FICHA_ANALISE" = p_ficha;
  perform private."FC_HISTORICO_FICHA"(p_ficha, p_acao, v_antes."TP_SITUACAO", v_antes."CO_USUARIO_RESPONSAVEL", null, p_usuario);
end;
$$;

--
-- Name: FUNCTION "FC_RESERVAR_FICHA"(p_ficha uuid, p_usuario uuid, p_acao text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RESERVAR_FICHA"(p_ficha uuid, p_usuario uuid, p_acao text) IS 'Reserva a ficha (já travada e conferida por quem chama) para a pessoa por 15 minutos: vira responsável se não houver, PENDENTE passa a EM_ANALISE, a versão sobe e o histórico registra PEGAR ou RESERVAR.';

--
-- Name: FC_RESPONSAVEIS_DO_EDITAL_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RESPONSAVEIS_DO_EDITAL_JSON"(p_edital uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select jsonb_agg(jsonb_build_object('id', u.id, 'nome', coalesce(nullif(btrim(u.nome), ''), u.email))
                     order by coalesce(nullif(btrim(u.nome), ''), u.email), u.id)
      from public."RL_RESPONSAVEL_EDITAL" r
      join public."TB_PERFIL_USUARIO" u on u.id = r."CO_PERFIL_USUARIO"
     where r."CO_MONITORAMENTO" = p_edital), '[]'::jsonb);
$$;

--
-- Name: FUNCTION "FC_RESPONSAVEIS_DO_EDITAL_JSON"(p_edital uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RESPONSAVEIS_DO_EDITAL_JSON"(p_edital uuid) IS 'Responsáveis pelo edital em json ([{id, nome}]), para a leitura e o histórico. 20261104120000.';

--
-- Name: FC_RESPOSTAS_DA_FICHA(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RESPOSTAS_DA_FICHA"(p_candidato uuid, p_regra jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with textos as (
    select jsonb_array_elements_text(b -> 'perguntas') as t
      from jsonb_array_elements(case when jsonb_typeof(p_regra -> 'blocos') = 'array' then p_regra -> 'blocos' else '[]'::jsonb end) b
     where jsonb_typeof(b -> 'perguntas') = 'array'
    union all
    select case when jsonb_typeof(d -> 'pergunta') = 'string' then d ->> 'pergunta' end
      from jsonb_array_elements(case when jsonb_typeof(p_regra #> '{provisoria,nota_declarada}') = 'array'
                                     then p_regra #> '{provisoria,nota_declarada}' else '[]'::jsonb end) d
    union all
    select a
      from jsonb_array_elements(case when jsonb_typeof(p_regra #> '{provisoria,nota_declarada}') = 'array'
                                     then p_regra #> '{provisoria,nota_declarada}' else '[]'::jsonb end) d,
           lateral jsonb_array_elements_text(case when jsonb_typeof(d -> 'pergunta') = 'array' then d -> 'pergunta' else '[]'::jsonb end) a
    union all
    select case when jsonb_typeof(p_regra #> '{provisoria,pergunta_experiencia}') = 'string'
                then p_regra #>> '{provisoria,pergunta_experiencia}' end
    union all
    select a from jsonb_array_elements_text(case when jsonb_typeof(p_regra #> '{provisoria,pergunta_experiencia}') = 'array'
                                                 then p_regra #> '{provisoria,pergunta_experiencia}' else '[]'::jsonb end) a
  ),
  alvos as (
    select distinct private."FC_TEXTO_COMPARAVEL"(t) as alvo from textos where coalesce(btrim(t), '') <> ''
  ),
  colunas as (
    select k.key as coluna, k.value as valor, private."FC_TEXTO_COMPARAVEL"(k.key) as nome
      from public."TB_EMPREGARE_CANDIDATO" c,
           lateral jsonb_each(c."DS_COLUNA_ORIGINAL") k
     where c."CO_EMPREGARE_CANDIDATO" = p_candidato and k.key ~* '^\s*pergunta'
  )
  select coalesce(jsonb_object_agg(k.coluna, k.valor), '{}'::jsonb)
    from colunas k
   where exists (
     select 1 from alvos a
      where a.alvo <> ''
        and (left(k.nome, length(a.alvo)) = a.alvo
             or left(regexp_replace(k.nome, '^pergunta ?[0-9]+ ?[-–—] ?', ''), length(a.alvo)) = a.alvo));
$$;

--
-- Name: FUNCTION "FC_RESPOSTAS_DA_FICHA"(p_candidato uuid, p_regra jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RESPOSTAS_DA_FICHA"(p_candidato uuid, p_regra jsonb) IS 'As respostas da Empregare do inscrito (DS_COLUNA_ORIGINAL) só das colunas "Pergunta N - …" que a regra usa: as perguntas dos blocos, da nota declarada e da experiência, casadas pelo começo do nome ou do enunciado como colunasDaPergunta (nota-declarada.js). Nunca as colunas de cadastro nem as perguntas que a regra não liga.';

--
-- Name: FC_RESPOSTA_VIGENTE_EMPREGARE(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_RESPOSTA_VIGENTE_EMPREGARE"(p_candidato uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  -- A mais nova com pergunta lida (id da Empregare sequencial; o JSON não traz data de envio);
  -- a resposta vazia (questionário retificado não respondido) só vale se não houver outra.
  select r."CO_EMPREGARE_RESPOSTA"
    from public."TB_EMPREGARE_RESPOSTA" r
   where r."CO_EMPREGARE_CANDIDATO" = p_candidato
   order by (r."QT_PERGUNTA" > 0) desc, r."CO_RESPOSTA_QUESTIONARIO"::numeric desc
   limit 1;
$$;

--
-- Name: FUNCTION "FC_RESPOSTA_VIGENTE_EMPREGARE"(p_candidato uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_RESPOSTA_VIGENTE_EMPREGARE"(p_candidato uuid) IS 'A resposta vigente do questionário de um candidato (TB_EMPREGARE_RESPOSTA): a de maior CO_RESPOSTA_QUESTIONARIO (numérico; o id da Empregare é sequencial e GetRespostaDetails não traz data de envio) entre as que têm pergunta lida (QT_PERGUNTA > 0); só se nenhuma tiver, a de maior id. Null sem resposta.';

--
-- Name: FC_ROTEIRO_JSON(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_ROTEIRO_JSON"(p_roteiro uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
    'id', r."CO_ROTEIRO", 'origem', r."CO_ROTEIRO_ORIGEM", 'versao', r."NU_VERSAO", 'area', r."CO_AREA",
    'nome', r."NO_ROTEIRO", 'nome_versao', r."NO_VERSAO", 'descricao', r."DS_DESCRICAO", 'etapa', r."NO_ETAPA",
    'escala', r."TP_ESCALA", 'passo', r."VL_PASSO", 'notas_permitidas', r."DS_NOTAS_PERMITIDAS",
    'nota_minima_total', r."VL_NOTA_MINIMA_TOTAL", 'notas_eliminatorias', r."DS_NOTAS_ELIMINATORIAS",
    'ausencia_elimina', r."ST_AUSENCIA_ELIMINA" = 'S', 'desempate', r."DS_DESEMPATE",
    'soma_analise', r."ST_SOMA_ANALISE" = 'S', 'convocacao_padrao', r."DS_CONVOCACAO_PADRAO",
    'banca_padrao', r."DS_BANCA_PADRAO", 'ativo', r."ST_ATIVO" = 'S', 'criado_em', r."DT_CRIACAO",
    'competencias', coalesce((select json_agg(json_build_object(
        'id', k."CO_COMPETENCIA", 'ordem', k."NU_ORDEM", 'nome', k."NO_COMPETENCIA", 'descricao', k."DS_DESCRICAO",
        'nota_maxima', k."VL_NOTA_MAXIMA", 'peso', k."VL_PESO", 'minimo', k."VL_MINIMO",
        'tipo_minimo', k."TP_MINIMO", 'avaliacao', k."TP_AVALIACAO") order by k."NU_ORDEM")
      from public."TB_ROTEIRO_COMPETENCIA" k where k."CO_ROTEIRO" = r."CO_ROTEIRO"), '[]'::json),
    'niveis', coalesce((select json_agg(json_build_object('nota', n."VL_NOTA", 'nome', n."NO_NIVEL", 'descricao', n."DS_DESCRICAO") order by n."VL_NOTA")
      from public."TB_ROTEIRO_NIVEL" n where n."CO_ROTEIRO" = r."CO_ROTEIRO"), '[]'::json),
    'aspectos', coalesce((select json_agg(json_build_object('id', s."CO_ASPECTO", 'ordem', s."NU_ORDEM", 'nome', s."NO_ASPECTO") order by s."NU_ORDEM")
      from public."TB_ROTEIRO_ASPECTO" s where s."CO_ROTEIRO" = r."CO_ROTEIRO"), '[]'::json),
    'renomeacoes', private."FC_RENOMEACOES_JSON"('ROTEIRO', r."CO_ROTEIRO_ORIGEM", r."NU_VERSAO"),
    'editais_em_uso', (select count(*) from public."TB_ENTREVISTA_EDITAL" e where e."CO_ROTEIRO" = r."CO_ROTEIRO"))
  from public."TB_ROTEIRO_ENTREVISTA" r where r."CO_ROTEIRO" = p_roteiro;
$$;

