--
-- Name: FC_SE_MUDOU(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_SE_MUDOU"(p_payload jsonb, p_versao text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
           when p_payload is null then null
           when p_versao is not null and p_versao = x.versao
             then jsonb_build_object('inalterado', true, 'versao', x.versao)
           else p_payload || jsonb_build_object('versao', x.versao)
         end
    from (
      select md5((p_payload - array['gerado_em', 'generated_at', 'cache']::text[])::text) as versao
    ) x;
$$;

--
-- Name: FUNCTION "FC_SE_MUDOU"(p_payload jsonb, p_versao text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_SE_MUDOU"(p_payload jsonb, p_versao text) IS 'Payload com versão dos dados (md5 sem gerado_em, generated_at e cache), ou só { inalterado, versao } quando a versão é atual (20261013190000). Metadados preservados na resposta completa.';

--
-- Name: FC_SE_MUDOU_EM_COLUNAS(jsonb, text, text, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_SE_MUDOU_EM_COLUNAS"(p_payload jsonb, p_versao text, p_campo text, p_dicionario text[]) RETURNS json
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_versao text;
begin
  if p_payload is null then
    return null;
  end if;
  -- A versão é a do payload de sempre (a mesma conta de private."FC_SE_MUDOU"): a conversão
  -- em colunas só roda quando ela mudou.
  v_versao := md5((p_payload - array['gerado_em', 'generated_at', 'cache']::text[])::text);
  if p_versao is not null and p_versao = v_versao then
    return json_build_object('inalterado', true, 'versao', v_versao);
  end if;
  return (
    select json_object_agg(x.k, x.v)
      from (select e.key as k, e.value::json as v from jsonb_each(p_payload - p_campo) e
            union all
            select p_campo || '_em_colunas', private."FC_COLUNAS_JSON"(p_payload -> p_campo, p_dicionario)
            union all
            select 'versao', to_json(v_versao)) x);
end;
$$;

--
-- Name: FUNCTION "FC_SE_MUDOU_EM_COLUNAS"(p_payload jsonb, p_versao text, p_campo text, p_dicionario text[]); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_SE_MUDOU_EM_COLUNAS"(p_payload jsonb, p_versao text, p_campo text, p_dicionario text[]) IS 'O payload com versao (md5 sem gerado_em, generated_at e cache) e o campo p_campo em colunas (<campo>_em_colunas, FC_COLUNAS_JSON), ou só { inalterado, versao } quando p_versao é a atual (20261014230000).';

--
-- Name: FC_STATUS_PELA_PENDENCIA(uuid, text, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_STATUS_PELA_PENDENCIA"(p_candidato uuid, p_status text, p_matricula text, p_data date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_CANDIDATO_APROVADO"%rowtype;
  v_matricula text := nullif(btrim(coalesce(p_matricula, '')), '');
  v_data date;
begin
  select * into v from public."TB_CANDIDATO_APROVADO" c where c.id = p_candidato and c.removido_em is null for update;
  if not found then
    raise exception 'As linhas desta pendência mudaram: atualize a tela' using errcode = '55000';
  end if;
  v_matricula := case when p_status in ('Contratado', 'Migração', 'Contratado em outra lista') then v_matricula end;
  v_data := case when p_status = 'Convocado' then p_data
                 when p_status is null then null
                 else v."DT_CONVOCACAO" end;
  -- O mesmo histórico do status da tela (o gatilho do "Contratado em outra lista" refaz a decisão do job).
  insert into public."TH_CANDIDATO_APROVADO" (
    candidato_id, lista_id, status_anterior, status_novo, processo_sei, matricula, alterado_por, "DT_CONVOCACAO")
  values (v.id, v.lista_id, v.status, p_status, v.processo_sei, v_matricula, (select auth.uid()), v_data);
  update public."TB_CANDIDATO_APROVADO"
     set status = p_status, matricula = v_matricula, "DT_CONVOCACAO" = v_data,
         updated_by = (select auth.uid()), updated_at = now()
   where id = v.id;
  return jsonb_build_object('candidato', v.id, 'campo', 'status', 'antes', v.status, 'depois', p_status);
end;
$$;

--
-- Name: FUNCTION "FC_STATUS_PELA_PENDENCIA"(p_candidato uuid, p_status text, p_matricula text, p_data date); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_STATUS_PELA_PENDENCIA"(p_candidato uuid, p_status text, p_matricula text, p_data date) IS 'Muda o status de uma linha pela decisão da pendência, com o histórico do status (TH_CANDIDATO_APROVADO): matrícula só em Contratado, Migração e Contratado em outra lista; a data só no Convocado. Devolve a alteração para o histórico da pendência. 20261026190000.';

