--
-- Name: FC_TG_EQUIPE_COM_FICHAS(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_TG_EQUIPE_COM_FICHAS"() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_qt integer;
  v_nome text;
begin
  if old."ST_ATIVO" = 'S' and new."ST_ATIVO" = 'N' and new."TP_PAPEL" = 'ANALISTA' then
    select count(*) into v_qt
      from public."TB_FICHA_ANALISE" f
     where f."CO_MONITORAMENTO" = new."CO_MONITORAMENTO" and f."CO_USUARIO_RESPONSAVEL" = new."CO_USUARIO"
       and f."TP_SITUACAO" in ('PENDENTE', 'EM_ANALISE')
       and not exists (select 1 from public."RL_ANALISTA_EDITAL" r
                        where r."CO_MONITORAMENTO" = f."CO_MONITORAMENTO" and r."CO_USUARIO" = f."CO_USUARIO_RESPONSAVEL"
                          and r."TP_PAPEL" = 'ANALISTA' and r."ST_ATIVO" = 'S'
                          and (r."CO_VAGA" is null or r."CO_VAGA" = f."CO_VAGA"));
    if v_qt > 0 then
      select coalesce(u.nome, u.email) into v_nome from public."TB_PERFIL_USUARIO" u where u.user_id = new."CO_USUARIO";
      raise exception '% tem % ficha(s) em aberto neste edital: redistribua ou devolva à fila (aba Fila) antes de tirar da equipe.',
        coalesce(v_nome, 'A pessoa'), v_qt using errcode = '22023';
    end if;
  end if;
  return null;
end;
$$;

--
-- Name: FUNCTION "FC_TG_EQUIPE_COM_FICHAS"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_TG_EQUIPE_COM_FICHAS"() IS 'Gatilho (adiado para o fim da transação) de RL_ANALISTA_EDITAL: recusa tirar da equipe o analista que ainda tem fichas pendentes ou em análise numa vaga que ele deixa de cobrir (AM-3.3).';

--
-- Name: FC_TG_FECHAR_CARGAS_PRESAS(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_TG_FECHAR_CARGAS_PRESAS"() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if TG_TABLE_NAME = 'TL_SYNC_ENTREVISTA' then
    update public."TL_SYNC_ENTREVISTA" s
       set "TP_SITUACAO" = 'FALHOU',
           "DT_FIM" = coalesce(s."DT_FIM", now()),
           "DS_MENSAGEM" = concat_ws(' | ', nullif(s."DS_MENSAGEM", ''),
                                     'Substituída pela carga ' || NEW."CO_SYNC" || ' (ficou em andamento: o robô parou no meio).')
     where s."TP_SITUACAO" = 'EM_ANDAMENTO'
       and s."CO_SYNC" <> NEW."CO_SYNC"
       and s."CO_AREA" is not distinct from NEW."CO_AREA"
       and s."DT_INICIO" < now() - interval '3 hours';
  else
    update public."TL_SYNC_SELECAO" s
       set "TP_SITUACAO" = 'FALHOU',
           "DT_FIM" = coalesce(s."DT_FIM", now()),
           "DS_MENSAGEM" = concat_ws(' | ', nullif(s."DS_MENSAGEM", ''),
                                     'Substituída pela carga ' || NEW."CO_SYNC" || ' (ficou em andamento: o robô parou no meio).')
     where s."TP_SITUACAO" = 'EM_ANDAMENTO'
       and s."CO_SYNC" <> NEW."CO_SYNC"
       and s."DT_INICIO" < now() - interval '3 hours';
  end if;
  return null;
end;
$$;

--
-- Name: FUNCTION "FC_TG_FECHAR_CARGAS_PRESAS"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_TG_FECHAR_CARGAS_PRESAS"() IS 'Gatilho (20261015141500): ao abrir uma carga de planilha, marca FALHOU as anteriores do mesmo escopo (área, nas entrevistas) ainda EM_ANDAMENTO há mais de 3 h.';

--
-- Name: FC_TG_FICHA_IMUTAVEL(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_TG_FICHA_IMUTAVEL"() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and private."FC_REINICIO_TREINAMENTO_PERMITE"(tg_table_name, to_jsonb(old)) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'Registro da avaliação documental não se apaga (%)', tg_table_name using errcode = '42501';
  end if;
  raise exception 'Histórico não muda (%)', tg_table_name using errcode = '42501';
end;
$$;

--
-- Name: FUNCTION "FC_TG_FICHA_IMUTAVEL"(); Type: COMMENT; Schema: private; Owner: -
