--
-- Name: FC_TG_REGRA_ANALISE_F2(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_TG_REGRA_ANALISE_F2"() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_desempate jsonb := new."DS_CONFIGURACAO" -> 'provisoria' -> 'desempate';
  v_pergunta jsonb := new."DS_CONFIGURACAO" -> 'provisoria' -> 'pergunta_experiencia';
  v_por_vaga jsonb := new."DS_CONFIGURACAO" -> 'lote' -> 'por_vaga';
begin
  if v_desempate is not null and jsonb_typeof(v_desempate) <> 'null' then
    if jsonb_typeof(v_desempate) <> 'array' or jsonb_array_length(v_desempate) > 5
       or exists (select 1 from jsonb_array_elements(v_desempate) d
                   where jsonb_typeof(d) <> 'string'
                      or d #>> '{}' not in ('IDOSO', 'EXPERIENCIA_DECLARADA', 'MAIOR_IDADE', 'MAIS_VELHO', 'CANDIDATURA'))
       or (select count(distinct d #>> '{}') from jsonb_array_elements(v_desempate) d) <> jsonb_array_length(v_desempate) then
      raise exception 'Desempate da Provisória: IDOSO, EXPERIENCIA_DECLARADA, MAIOR_IDADE, MAIS_VELHO ou CANDIDATURA, sem repetir.' using errcode = '22023';
    end if;
  end if;
  if not private."FC_JSON_PERGUNTA_OK"(v_pergunta, false) then
    raise exception 'Pergunta da experiência declarada: texto ou lista de 1 a 10 textos de até 200 caracteres.' using errcode = '22023';
  end if;
  if v_desempate @> '["EXPERIENCIA_DECLARADA"]'::jsonb and not private."FC_JSON_PERGUNTA_OK"(v_pergunta, true) then
    raise exception 'Desempate pela experiência declarada: informe a pergunta da experiência.' using errcode = '22023';
  end if;
  if v_por_vaga is not null and jsonb_typeof(v_por_vaga) <> 'null' then
    if jsonb_typeof(v_por_vaga) <> 'object'
       or (select count(*) from jsonb_object_keys(v_por_vaga)) > 500
       or exists (select 1 from jsonb_each(v_por_vaga) p
                   where p.key !~ '^[0-9]{1,20}$'
                      or case when jsonb_typeof(p.value) <> 'number' then true
                              else (p.value #>> '{}')::numeric <> trunc((p.value #>> '{}')::numeric)
                                   or (p.value #>> '{}')::numeric not between 1 and 100000 end) then
      raise exception 'Lote por vaga: código da vaga (só dígitos) e tamanho inteiro de 1 a 100.000.' using errcode = '22023';
    end if;
  end if;
  return new;
end;
$_$;

--
-- Name: FUNCTION "FC_TG_REGRA_ANALISE_F2"(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private."FC_TG_REGRA_ANALISE_F2"() IS 'Gatilho de TH_REGRA_ANALISE: confere os campos que FC_VALIDAR_REGRA_ANALISE não conhece — provisoria.desempate (IDOSO, EXPERIENCIA_DECLARADA, MAIOR_IDADE — o mesmo que MAIS_VELHO —, MAIS_VELHO, CANDIDATURA, sem repetir), provisoria.pergunta_experiencia (texto até 200 ou lista de 1 a 10 alternativas, obrigatória com EXPERIENCIA_DECLARADA) e lote.por_vaga (código da vaga → tamanho inteiro de 1 a 100.000). 22023 com a mensagem do formulário.';

--
-- Name: FC_TG_REGRA_ANALISE_IMUTAVEL(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private."FC_TG_REGRA_ANALISE_IMUTAVEL"() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' and private."FC_REINICIO_TREINAMENTO_PERMITE"(tg_table_name, to_jsonb(old)) then
    return old;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'Registro da avaliação documental não se apaga (%): desative ou crie outra versão', tg_table_name using errcode = '42501';
  end if;
  -- Renomear a versão: só o NO_VERSAO muda (configuração, hash, motivo, autor e data ficam).
  if tg_table_name = 'TH_REGRA_ANALISE' and (to_jsonb(new) - 'NO_VERSAO') = (to_jsonb(old) - 'NO_VERSAO') then
    return new;
  end if;
  if tg_table_name in ('TH_REGRA_ANALISE', 'TH_ORIGEM_ANALISE_EDITAL') then
    raise exception 'Histórico não muda (%): crie outra versão', tg_table_name using errcode = '42501';
  end if;
  return new;
end;
$$;

