--
-- Name: baixar_anexo_candidato_aprovado(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.baixar_anexo_candidato_aprovado(p_anexo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_nome text;
  v_arquivo bytea;
begin
  if not (private.pode_recurso('aprovados',1)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;

  select a."NO_ARQUIVO", a."IM_ARQUIVO" into v_nome, v_arquivo
    from public."TB_ANEXO_CANDIDATO_APROVADO" a
    join public."TB_CANDIDATO_APROVADO" c on c.id = a."CO_CANDIDATO"
    join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
   where a."CO_ANEXO" = p_anexo_id
     and l.vigente is true
     and c.removido_em is null
     and m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
      and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]));
  if not found then raise exception 'Anexo não encontrado'; end if;

  -- encode quebra a linha a cada 76 caracteres; o navegador quer uma só.
  return jsonb_build_object(
    'arquivo_nome', v_nome,
    'arquivo_base64', translate(encode(v_arquivo, 'base64'), E'\n', '')
  );
end;
$$;

--
-- Name: buscar_candidatos_recurso(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.buscar_candidatos_recurso(p_edital_id uuid, p_busca text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_edital text;
  v_area text;
  v_busca text := btrim(coalesce(p_busca, ''));
  v_texto text;
begin
  select m.edital, m."CO_AREA" into v_edital, v_area
  from public."TB_MONITORAMENTO_INDIGENA" m
  where m.id = p_edital_id;
  if v_area is null then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_RECURSOS_NA_AREA"(v_area, 2);
  perform private."FC_EXIGIR_AREA_EDITAL"(p_edital_id::text);
  if length(v_busca) < 2 then
    return '[]'::json;
  end if;
  v_texto := private."FC_TEXTO_BUSCA_RECURSO"(left(v_busca, 100));
  return (
    select coalesce(json_agg(json_build_object(
        'id', x.id,
        'candidato', x.candidato,
        'codigo', x.id_origem,
        'vaga', x.codigo_vaga,
        'cargo', x.nome_vaga,
        'nota', x.nota_final_ajustada,
        'resultado', x.status_consolidado,
        'responsavel', x.responsavel_analise,
        'modalidade', x.modalidade_concorrencia,
        'ativo', x.ativo
      ) order by x.ativo desc, x.candidato, x.codigo_vaga), '[]'::json)
    from (
      select a.id, a.candidato, a.id_origem, a.codigo_vaga, a.nome_vaga,
             a.nota_final_ajustada, a.status_consolidado, a.responsavel_analise,
             a.modalidade_concorrencia, a.ativo
      from public."TB_ANALISE_CURRICULAR" a
      where private."FC_ANALISE_DO_EDITAL"(a.edital, v_edital)
        and a."CO_AREA" = v_area
        and (strpos(private."FC_TEXTO_BUSCA_RECURSO"(a.candidato), v_texto) > 0
             or a.id_origem = v_busca)
      order by a.ativo desc, a.candidato, a.codigo_vaga
      limit 20
    ) x
  );
end;
$$;

--
-- Name: FUNCTION buscar_candidatos_recurso(p_edital_id uuid, p_busca text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.buscar_candidatos_recurso(p_edital_id uuid, p_busca text) IS 'Candidatos das análises curriculares do edital (mesmo edital e área), por parte do nome (sem acento) ou pelo código exato; até 20. Exige recursos >= editor e a área do edital.';

--
-- Name: cancelar_ajuste_pontuacao(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_ajuste_pontuacao(p_ajuste uuid, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_j public."TB_AJUSTE_PONTUACAO_RECURSO";
begin
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  select * into v_j from public."TB_AJUSTE_PONTUACAO_RECURSO" where "CO_AJUSTE_PONTUACAO" = p_ajuste;
  if v_j."CO_AJUSTE_PONTUACAO" is null then
    raise exception 'Ajuste não encontrado' using errcode = 'P0002';
  end if;
  perform private."FC_EXIGIR_RECURSO_ACESSIVEL"(v_j."CO_RECURSO_CANDIDATO", 1);
  perform private."FC_EXIGIR_PARECER_RECURSO"();
  if length(coalesce(v_motivo, '')) not between 3 and 2000 then
    raise exception 'Informe o motivo (3 a 2.000 caracteres)' using errcode = '22023';
  end if;

  perform 1 from public."TB_RECURSO_CANDIDATO" where "CO_RECURSO_CANDIDATO" = v_j."CO_RECURSO_CANDIDATO" for update;
  select * into v_j from public."TB_AJUSTE_PONTUACAO_RECURSO" where "CO_AJUSTE_PONTUACAO" = p_ajuste for update;
  if v_j."TP_SITUACAO" not in ('PROPOSTO', 'APROVADO') then
    raise exception 'O ajuste já foi cancelado' using errcode = '22023';
  end if;

  update public."TB_AJUSTE_PONTUACAO_RECURSO" set
    "TP_SITUACAO" = 'CANCELADO', "DT_CANCELAMENTO" = now(), "CO_USUARIO_CANCELAMENTO" = v_uid,
    "DS_MOTIVO_CANCELAMENTO" = v_motivo
  where "CO_AJUSTE_PONTUACAO" = p_ajuste;

  if v_j."TP_SITUACAO" = 'APROVADO' then
    perform set_config('monitora.ajuste_pontuacao', 'S', true);
    update public."TB_RECURSO_CANDIDATO" set
      "ST_MUDOU_CLASSIFICACAO" = 'N',
      "NU_REVISAO" = "NU_REVISAO" + 1,
      "DT_ATUALIZACAO" = now(),
      "CO_USUARIO_ATUALIZACAO" = v_uid
    where "CO_RECURSO_CANDIDATO" = v_j."CO_RECURSO_CANDIDATO";
    perform set_config('monitora.ajuste_pontuacao', 'N', true);
  end if;

  insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "DS_MOTIVO", "CO_USUARIO")
  values (v_j."CO_RECURSO_CANDIDATO", 'ajuste', 'cancelar', v_j."TP_SITUACAO", 'CANCELADO',
          format('Versão %s. %s', v_j."NU_VERSAO", v_motivo), v_uid);

  return public.obter_ajustes_pontuacao_recurso(v_j."CO_RECURSO_CANDIDATO");
end;
$$;

--
-- Name: FUNCTION cancelar_ajuste_pontuacao(p_ajuste uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancelar_ajuste_pontuacao(p_ajuste uuid, p_motivo text) IS 'Cancela o ajuste da pontuação proposto ou aprovado, com motivo (3 a 2.000 caracteres); cancelar o aprovado tira o ajuste da Classificação e desmarca "O recurso mudou a classificação". Só o parecer jurídico (42501). Histórico em TH_RECURSO_CANDIDATO (ajuste).';

--
-- Name: cancelar_minha_solicitacao_acesso(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_minha_solicitacao_acesso() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_id uuid;
begin
  if v_uid is null then raise exception 'Usuário não autenticado' using errcode = '42501'; end if;
  update public."TB_SOLICITACAO_ACESSO"
     set status = 'cancelado', updated_at = now()
   where user_id = v_uid and status = 'pendente'
  returning id into v_id;
  if v_id is null then
    raise exception 'Nenhum pedido pendente para cancelar.' using errcode = '22023';
  end if;
  return jsonb_build_object('ok', true, 'id', v_id, 'status', 'cancelado');
end;
$$;

--
-- Name: FUNCTION cancelar_minha_solicitacao_acesso(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancelar_minha_solicitacao_acesso() IS 'Cancela o pedido de acesso pendente de quem está autenticado (status cancelado).';

--
-- Name: cancelar_reinicio_fichas_do_edital(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_reinicio_fichas_do_edital(p_pedido bigint) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_usuario uuid := (select auth.uid());
  v_p public."TB_PEDIDO_REINICIO_FICHA";
begin
  if not private."FC_ADMIN_GLOBAL_ATIVO"(v_usuario) then
    raise exception 'Só o administrador global cancela o pedido de reinício.' using errcode = '42501';
  end if;
  select * into v_p from public."TB_PEDIDO_REINICIO_FICHA" p where p."CO_PEDIDO_REINICIO" = p_pedido for update;
  if not found then
    raise exception 'Pedido de reinício não encontrado.' using errcode = '22023';
  end if;
  if v_p."CO_USUARIO_PEDIDO" <> v_usuario then
    raise exception 'Só quem pediu cancela o pedido. Para negar, use Recusar.' using errcode = '42501';
  end if;
  if v_p."TP_SITUACAO" <> 'PENDENTE' then
    raise exception 'Este pedido de reinício não está mais pendente (%).', lower(v_p."TP_SITUACAO") using errcode = '55000';
  end if;

  update public."TB_PEDIDO_REINICIO_FICHA" set
    "TP_SITUACAO" = 'CANCELADO', "CO_USUARIO_DECISAO" = v_usuario, "DT_DECISAO" = now()
   where "CO_PEDIDO_REINICIO" = p_pedido;
  insert into public."TH_PEDIDO_REINICIO_FICHA" ("CO_PEDIDO_REINICIO", "CO_MONITORAMENTO", "TP_EVENTO", "CO_USUARIO")
  values (p_pedido, v_p."CO_MONITORAMENTO", 'CANCELAR', v_usuario);

  return private."FC_LER_REINICIO_FICHAS"(v_p."CO_MONITORAMENTO", v_usuario);
end;
$$;

--
-- Name: FUNCTION cancelar_reinicio_fichas_do_edital(p_pedido bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancelar_reinicio_fichas_do_edital(p_pedido bigint) IS 'Quem pediu o reinício desiste do pedido pendente (20261022210000): outro administrador recebe 42501 (deve recusar). Marca CANCELADO e grava CANCELAR.';

--
-- Name: casamento_ler_pedidos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.casamento_ler_pedidos(p_pedido uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object('schema_version', 1, 'pedidos', coalesce(json_agg(json_build_object(
           'pedido', p."CO_PEDIDO",
           'novos', p."DS_NOVOS",
           'manuais', p."DS_MANUAIS",
           'anteriores', (select coalesce(json_agg(json_build_object(
                             'id', c.id, 'analise_id', c."CO_ANALISE_CURRICULAR", 'nome', c.nome, 'cargo', c.cargo,
                             'codigo_vaga', c.codigo_vaga, 'classificacao', c.classificacao, 'status', c.status,
                             'matricula', c.matricula, 'processo_sei', c.processo_sei, 'sub_judice', c.sub_judice,
                             'alterado_judicialmente', c.alterado_judicialmente)
                           order by c.cargo, c.classificacao nulls last, c.nome, c.id), '[]'::json)
                            from public."TB_CANDIDATO_APROVADO" c
                           where c.lista_id = p."CO_LISTA_APROVADO_ANTERIOR" and c.removido_em is null))
         order by p."DT_PEDIDO"), '[]'::json))
    from (select * from public."TB_PEDIDO_CASAMENTO_LISTA" x
           where x."TP_SITUACAO" = 'PENDENTE' and x."CO_LISTA_APROVADO_ANTERIOR" is not null
             and (p_pedido is null or x."CO_PEDIDO" = p_pedido)
           order by x."DT_PEDIDO" limit 20) p;
$$;

--
-- Name: FUNCTION casamento_ler_pedidos(p_pedido uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.casamento_ler_pedidos(p_pedido uuid) IS 'Job do casamento (Python, só service_role): os pedidos pendentes (ou o p_pedido), com quem entra, a revisão à mão e a lista vigente (na ordem da tela). 20261030090000.';

--
-- Name: classificacao_gravar_calculo(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classificacao_gravar_calculo(p_execucao text, p_pedido uuid, p_retrato jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v public."TB_PEDIDO_CALCULO_CLASSIFICACAO";
  v_vigente integer;
  v_hash text;
begin
  if coalesce(p_execucao, '') !~ '^[A-Za-z0-9_.:-]{1,80}$' then
    raise exception 'Execução inválida' using errcode = '22023';
  end if;
  select * into v from public."TB_PEDIDO_CALCULO_CLASSIFICACAO" p where p."CO_PEDIDO_CALCULO" = p_pedido for update;
  if v."CO_PEDIDO_CALCULO" is null then
    raise exception 'Pedido de cálculo não encontrado' using errcode = '22023';
  end if;
  if v."TP_SITUACAO" not in ('PEDIDO', 'CALCULANDO') then
    raise exception 'O pedido já saiu da fila (%)', lower(v."TP_SITUACAO") using errcode = '55000';
  end if;
  if p_retrato is null or jsonb_typeof(p_retrato) <> 'object'
     or p_retrato ->> 'tipo' is distinct from v."TP_LISTA"
     or coalesce(jsonb_typeof(p_retrato -> 'vagas'), '') <> 'array'
     or coalesce(jsonb_typeof(p_retrato -> 'totais'), '') <> 'object'
     or coalesce(jsonb_typeof(p_retrato -> 'regra_versao'), '') <> 'number'
     or (p_retrato ->> 'regra_versao')::numeric <> v."NU_VERSAO_REGRA" then
    raise exception 'Retrato inválido (tipo, vagas, totais ou versão da regra)' using errcode = '22023';
  end if;
  if pg_column_size(p_retrato) > 8000000 then
    raise exception 'Retrato grande demais.' using errcode = '22023';
  end if;
  select r."NU_VERSAO_VIGENTE" into v_vigente from public."TB_REGRA_CLASSIFICACAO" r where r."CO_MONITORAMENTO" = v."CO_MONITORAMENTO";
  if v_vigente is distinct from v."NU_VERSAO_REGRA" then
    raise exception 'A regra do edital mudou desde o pedido; gere de novo.' using errcode = 'PT409';
  end if;
  -- Os candidatos do retrato são análises ativas deste edital (a mesma conferência do registro).
  perform private."FC_EXIGIR_CANDIDATOS_DO_EDITAL"(v."CO_MONITORAMENTO", p_retrato);

  v_hash := private."FC_HASH_RETRATO_CLASSIFICACAO"(p_retrato);
  update public."TB_PEDIDO_CALCULO_CLASSIFICACAO"
     set "TP_SITUACAO" = 'PRONTO', "DS_RETRATO" = p_retrato, "DS_HASH" = v_hash, "DS_MENSAGEM" = null,
         "CO_EXECUCAO" = p_execucao, "DT_ATUALIZACAO" = now()
   where "CO_PEDIDO_CALCULO" = p_pedido;
  return jsonb_build_object('pedido', p_pedido, 'situacao', 'PRONTO', 'hash', v_hash);
end;
$_$;

--
-- Name: FUNCTION classificacao_gravar_calculo(p_execucao text, p_pedido uuid, p_retrato jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classificacao_gravar_calculo(p_execucao text, p_pedido uuid, p_retrato jsonb) IS 'Job da classificação em Python (--calculo, 20261023200000): grava o retrato calculado pelo Python num pedido que espera (PEDIDO ou CALCULANDO; senão 55000), confere a forma (tipo, vagas, totais), a versão da regra do pedido e a vigente (PT409), o tamanho e os candidatos do edital (FC_EXIGIR_CANDIDATOS_DO_EDITAL), calcula o hash SHA-256 do conteúdo (FC_HASH_RETRATO_CLASSIFICACAO, 20261024130000: o mesmo que a lista registrada receberá) e marca PRONTO. Só service_role.';

--
-- Name: classificacao_gravar_desempate(text, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classificacao_gravar_desempate(p_execucao text, p_lista uuid, p_hash text, p_relatorio jsonb, p_texto text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_lista public."TB_LISTA_CLASSIFICACAO";
  v_versao smallint;
  v_grupos integer;
  v_empatados integer;
  v_pendentes integer;
  v_fora integer;
begin
  if coalesce(p_execucao, '') !~ '^[A-Za-z0-9_.:-]{1,80}$' then
    raise exception 'Execução inválida' using errcode = '22023';
  end if;
  select * into v_lista from public."TB_LISTA_CLASSIFICACAO" l where l."CO_LISTA_CLASSIFICACAO" = p_lista;
  if v_lista."CO_LISTA_CLASSIFICACAO" is null then
    raise exception 'Lista não encontrada' using errcode = '22023';
  end if;
  if p_hash is distinct from v_lista."DS_HASH" then
    raise exception 'A lista mudou desde o cálculo do relatório (hash diferente)' using errcode = '22023';
  end if;
  if p_relatorio is null or jsonb_typeof(p_relatorio) <> 'object'
     or coalesce(jsonb_typeof(p_relatorio->'versao'), '') <> 'number'
     or (p_relatorio->>'versao') not in ('1', '2')
     or p_relatorio->>'tipo' is distinct from v_lista."TP_LISTA"
     or coalesce(jsonb_typeof(p_relatorio->'vagas'), '') <> 'array'
     or coalesce(jsonb_typeof(p_relatorio->'totais'), '') <> 'object' then
    raise exception 'Relatório de desempate inválido (versão, tipo ou forma)' using errcode = '22023';
  end if;
  v_versao := (p_relatorio->>'versao')::smallint;
  if coalesce(p_texto, '') = '' or octet_length(p_texto) > 8000000 or octet_length(p_relatorio::text) > 8000000 then
    raise exception 'Relatório de desempate vazio ou grande demais' using errcode = '22023';
  end if;
  -- Sem contato nem documento: nada de e-mail nem 11 dígitos seguidos (fora os ids das análises).
  if regexp_replace(p_relatorio::text || p_texto, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', '', 'g')
     ~ '@|[0-9]{11}' then
    raise exception 'Relatório de desempate com dado que parece pessoal (@ ou 11 dígitos)' using errcode = '22023';
  end if;
  -- Cada candidato do relatório está na lista gerada.
  select count(*) into v_fora
    from jsonb_path_query(p_relatorio, '$.vagas[*].grupos[*].candidatos[*].analiseId') r(id)
   where not exists (
     select 1 from jsonb_path_query(v_lista."DS_RESULTADO", '$.vagas[*].geral[*].analise_id') g(id) where g.id = r.id
     union all
     select 1 from jsonb_path_query(v_lista."DS_RESULTADO", '$.vagas[*].listas.*[*].analise_id') m(id) where m.id = r.id);
  if v_fora > 0 then
    raise exception 'Relatório de desempate com % candidato(s) fora da lista', v_fora using errcode = '22023';
  end if;
  select count(*) into v_grupos from jsonb_path_query(p_relatorio, '$.vagas[*].grupos[*]');
  v_empatados := coalesce((p_relatorio#>>'{totais,empatadosAteOFim}')::integer, -1);
  v_pendentes := coalesce((p_relatorio#>>'{totais,pendentes}')::integer, -1);
  if v_grupos is distinct from (p_relatorio#>>'{totais,grupos}')::integer or v_empatados < 0 or v_pendentes < 0 then
    raise exception 'Totais do relatório de desempate não batem com os grupos' using errcode = '22023';
  end if;

  insert into public."TB_RELATORIO_DESEMPATE" as r
    ("CO_LISTA_CLASSIFICACAO", "NU_VERSAO_RELATORIO", "DS_RELATORIO", "DS_TEXTO", "DS_HASH_LISTA",
     "QT_GRUPO", "QT_EMPATE_FINAL", "QT_PENDENCIA", "CO_EXECUCAO", "DT_GERACAO")
  values (p_lista, v_versao, p_relatorio, p_texto, p_hash, v_grupos, v_empatados, v_pendentes, p_execucao, now())
  on conflict ("CO_LISTA_CLASSIFICACAO") do update
    set "NU_VERSAO_RELATORIO" = excluded."NU_VERSAO_RELATORIO", "DS_RELATORIO" = excluded."DS_RELATORIO",
        "DS_TEXTO" = excluded."DS_TEXTO", "DS_HASH_LISTA" = excluded."DS_HASH_LISTA",
        "QT_GRUPO" = excluded."QT_GRUPO", "QT_EMPATE_FINAL" = excluded."QT_EMPATE_FINAL",
        "QT_PENDENCIA" = excluded."QT_PENDENCIA", "CO_EXECUCAO" = excluded."CO_EXECUCAO", "DT_GERACAO" = now();

  -- O preparo da lista fica pronto (20261023170000).
  insert into public."TB_PREPARO_DESEMPATE" as p
    ("CO_LISTA_CLASSIFICACAO", "TP_SITUACAO", "DS_MENSAGEM", "CO_EXECUCAO", "DT_PEDIDO", "DT_ATUALIZACAO")
  values (p_lista, 'PRONTO', null, p_execucao, now(), now())
  on conflict ("CO_LISTA_CLASSIFICACAO") do update
    set "TP_SITUACAO" = 'PRONTO', "DS_MENSAGEM" = null, "CO_EXECUCAO" = excluded."CO_EXECUCAO", "DT_ATUALIZACAO" = now();

  return jsonb_build_object('lista', p_lista, 'versao', v_versao, 'grupos', v_grupos, 'empatados', v_empatados,
                            'pendentes', v_pendentes);
end;
$_$;

--
-- Name: FUNCTION classificacao_gravar_desempate(p_execucao text, p_lista uuid, p_hash text, p_relatorio jsonb, p_texto text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classificacao_gravar_desempate(p_execucao text, p_lista uuid, p_hash text, p_relatorio jsonb, p_texto text) IS 'Job da classificação em Python: grava (ou troca) o relatório de desempate de uma lista gerada, nas versões 1 ou 2 do formato (gravada em NU_VERSAO_RELATORIO; 20261023230000), e marca o preparo PRONTO (TB_PREPARO_DESEMPATE, 20261023170000). Confere o hash da lista, a versão e o tipo do relatório, que cada candidato está na lista, os totais e a ausência de contato ou documento (@ ou 11 dígitos fora dos ids). Só service_role.';

--
-- Name: classificacao_ler_edital(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classificacao_ler_edital(p_edital uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text;
  v_dados jsonb;
begin
  select m."CO_AREA" into v_area from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  if v_area is null then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  v_dados := private."FC_DADOS_CLASSIFICACAO_EDITAL"(p_edital, v_area)::jsonb;

  return jsonb_build_object(
    'schema_version', 2,
    'gerado_em', now(),
    'edital', v_dados->'edital',
    'regra', case when v_dados->'regra' is null or jsonb_typeof(v_dados->'regra') = 'null' then null
                  else jsonb_build_object('versao', v_dados#>'{regra,versao}', 'configuracao', v_dados#>'{regra,configuracao}') end,
    'cronograma', v_dados->'cronograma',
    'quadro', v_dados->'quadro',
    -- Os nomes reais (o motor ordena por eles no desempate final e o retrato os leva).
    'candidatos', coalesce(v_dados->'candidatos', '[]'::jsonb),
    'entrevistas', coalesce(v_dados->'entrevistas', '[]'::jsonb),
    'desempates', coalesce((
      select jsonb_agg(d.value - 'por' order by d.ordinality)
        from jsonb_array_elements(coalesce(v_dados->'desempates', '[]'::jsonb)) with ordinality d), '[]'::jsonb),
    'ajustes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', j.value->'id', 'recurso_id', j.value->'recurso_id', 'numero', j.value->'numero',
               'analise_id', j.value->'analise_id', 'aprovado_em', j.value->'aprovado_em',
               'itens', coalesce((select jsonb_agg(i.value - 'justificativa' order by i.ordinality)
                                    from jsonb_array_elements(coalesce(j.value->'itens', '[]'::jsonb)) with ordinality i), '[]'::jsonb))
             order by j.ordinality)
        from jsonb_array_elements(coalesce(v_dados->'ajustes', '[]'::jsonb)) with ordinality j), '[]'::jsonb),
    'listas', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', l."CO_LISTA_CLASSIFICACAO", 'tipo', l."TP_LISTA", 'versao_regra', l."NU_VERSAO_REGRA",
               'hash', l."DS_HASH", 'gerada_em', l."DT_GERACAO", 'publicada', l."ST_PUBLICADA" = 'S')
             order by l."DT_GERACAO" desc)
        from public."TB_LISTA_CLASSIFICACAO" l
       where l."CO_MONITORAMENTO" = p_edital), '[]'::jsonb),
    'convocacao', jsonb_build_object(
      'configuracoes', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'edital_id', c."CO_EDITAL",
                 'proporcionalidade', c."TP_CONVOCACAO" = 'COM_PROPORCIONALIDADE',
                 'modelo_id', c."CO_MODELO",
                 'padrao_imediata', c."QT_PADRAO_IMEDIATA",
                 'vagas', coalesce((
                   select jsonb_agg(jsonb_build_object(
                            'codigo_vaga', v."CO_VAGA", 'cargo', v."NO_CARGO", 'imediatas', v."QT_VAGA_IMEDIATA",
                            'manual', v."ST_QUADRO_MANUAL" = 'S', 'quadro', v."DS_QUADRO_MANUAL")
                          order by v."CO_VAGA")
                     from public."TB_VAGA_IMEDIATA" v
                    where v."CO_EDITAL" = c."CO_EDITAL"), '[]'::jsonb)))
          from public."TB_CONVOCACAO_EDITAL" c
         where c."CO_EDITAL" = p_edital::text), '[]'::jsonb),
      'modelos', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'modelo_id', m."CO_MODELO",
                 'nome', m."NO_MODELO",
                 'distribuicao', lower(m."TP_DISTRIBUICAO"),
                 'cota_multipla', lower(m."TP_COTA_MULTIPLA"),
                 'categorias', coalesce((
                   select jsonb_agg(jsonb_build_object(
                            'id', k."CO_CATEGORIA", 'rotulo', k."NO_CATEGORIA", 'sigla', k."SG_CATEGORIA",
                            'ampla', k."ST_AMPLA" = 'S', 'acumulavel', k."ST_ACUMULAVEL" = 'S',
                            'percentual', k."TX_RESERVA", 'arredondamento', lower(k."TP_ARREDONDAMENTO"),
                            'teto', k."TX_TETO", 'minimo', k."QT_MINIMA_RESERVA", 'termos', k."DS_TERMO",
                            'posicoes', k."DS_POSICAO", 'intervalo', k."QT_INTERVALO", 'cascata', k."DS_CASCATA")
                          order by k."NU_ORDEM", k."CO_CATEGORIA")
                     from public."TB_CATEGORIA_CONVOCACAO" k
                    where k."CO_MODELO" = m."CO_MODELO"), '[]'::jsonb))
               order by m."NO_MODELO")
          from public."TB_MODELO_CONVOCACAO" m
         where m."CO_MODELO" in (select c."CO_MODELO" from public."TB_CONVOCACAO_EDITAL" c where c."CO_EDITAL" = p_edital::text)),
        '[]'::jsonb)));
end;
$$;

--
-- Name: FUNCTION classificacao_ler_edital(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classificacao_ler_edital(p_edital uuid) IS 'Job da classificação em Python (scripts/classificacao/): o json de obter_classificacao_do_edital com os nomes reais dos candidatos (decisão de 23/10/2026: a ordem alfabética do desempate final é calculada no Python, como o motor.ts; os nomes não vão para o log), sem o conteúdo das listas geradas (id, tipo, hash), sem quem registrou desempates nem autores e justificativas dos ajustes, e com a configuração de convocação do edital. Só service_role.';

--
-- Name: classificacao_ler_lista(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classificacao_ler_lista(p_lista uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_LISTA_CLASSIFICACAO";
  v_nome text;
begin
  select * into v from public."TB_LISTA_CLASSIFICACAO" l where l."CO_LISTA_CLASSIFICACAO" = p_lista;
  if v."CO_LISTA_CLASSIFICACAO" is null then
    raise exception 'Lista não encontrada' using errcode = '22023';
  end if;
  -- Nome e sobrenome do cadastro de quem gerou; nada que pareça e-mail.
  select private."FC_NOME_E_SOBRENOME"(p.nome) into v_nome
    from public."TB_PERFIL_USUARIO" p where p.user_id = v."CO_USUARIO" limit 1;
  return jsonb_build_object(
    'id', v."CO_LISTA_CLASSIFICACAO",
    'edital', v."CO_MONITORAMENTO",
    'tipo', v."TP_LISTA",
    'versao_regra', v."NU_VERSAO_REGRA",
    'hash', v."DS_HASH",
    'gerada_em', v."DT_GERACAO",
    'gerada_por', case when v_nome ~ '@' then null else left(v_nome, 120) end,
    'resultado', v."DS_RESULTADO");
end;
$$;

--
-- Name: FUNCTION classificacao_ler_lista(p_lista uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classificacao_ler_lista(p_lista uuid) IS 'Job da classificação em Python (--desempate, 20261023170000): a lista gerada como foi registrada — o retrato (DS_RESULTADO, com os nomes), o hash, o tipo, a versão da regra, o edital, quando e por quem foi gerada (gerada_por: nome e sobrenome do cadastro, FC_NOME_E_SOBRENOME; nulo sem cadastro ou com "@"; 20261023230000) — para conferir com o cálculo do Python antes de gravar o relatório de desempate. Só service_role.';

--
-- Name: classificacao_ler_pedidos_calculo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classificacao_ler_pedidos_calculo() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'pedido', p."CO_PEDIDO_CALCULO", 'edital', p."CO_MONITORAMENTO", 'tipo', p."TP_LISTA",
           'versao_regra', p."NU_VERSAO_REGRA", 'situacao', p."TP_SITUACAO", 'pedido_em', p."DT_PEDIDO")
         order by p."DT_PEDIDO", p."CO_PEDIDO_CALCULO"), '[]'::jsonb)
    from (select * from public."TB_PEDIDO_CALCULO_CLASSIFICACAO" x
           where x."TP_SITUACAO" in ('PEDIDO', 'CALCULANDO')
             and x."DT_PEDIDO" > now() - interval '30 minutes'
           order by x."DT_PEDIDO"
           limit 20) p;
$$;

--
-- Name: FUNCTION classificacao_ler_pedidos_calculo(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classificacao_ler_pedidos_calculo() IS 'Job da classificação em Python (--calculo, 20261023200000): os pedidos de cálculo que esperam (PEDIDO ou CALCULANDO dos últimos 30 min; a tela desiste antes), com o edital, o tipo e a versão da regra; no máximo 20, do mais antigo ao mais novo. Toda execução do job lê esta fila (o GitHub guarda uma execução só na fila do grupo). Só service_role.';

--
-- Name: classificacao_ler_pedidos_desempate(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classificacao_ler_pedidos_desempate(p_listas uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'lista', l."CO_LISTA_CLASSIFICACAO", 'edital', l."CO_MONITORAMENTO", 'tipo', l."TP_LISTA",
           'situacao', p."TP_SITUACAO", 'pedido_em', p."DT_PEDIDO")
         order by coalesce(p."DT_PEDIDO", l."DT_GERACAO"), l."CO_LISTA_CLASSIFICACAO"), '[]'::jsonb)
    from (
      select l.*
        from public."TB_LISTA_CLASSIFICACAO" l
       -- As pedidas (input "listas"), em qualquer situação, e todas as que esperam (2 dias):
       -- o GitHub guarda só uma execução na fila do grupo, então cada execução leva as pendentes.
       where l."CO_LISTA_CLASSIFICACAO" = any (coalesce(p_listas, '{}'::uuid[]))
          or exists (select 1 from public."TB_PREPARO_DESEMPATE" x
                      where x."CO_LISTA_CLASSIFICACAO" = l."CO_LISTA_CLASSIFICACAO"
                        and x."TP_SITUACAO" in ('PEDIDO', 'PREPARANDO', 'SEM_DISPARO')
                        and x."DT_PEDIDO" > now() - interval '2 days')
       order by l."DT_GERACAO"
       limit 50
    ) l
    left join public."TB_PREPARO_DESEMPATE" p on p."CO_LISTA_CLASSIFICACAO" = l."CO_LISTA_CLASSIFICACAO";
$$;

--
-- Name: FUNCTION classificacao_ler_pedidos_desempate(p_listas uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classificacao_ler_pedidos_desempate(p_listas uuid[]) IS 'Job da classificação em Python (20261023170000): as listas a preparar — as pedidas (p_listas, em qualquer situação) e todas as que esperam (PEDIDO, PREPARANDO e, desde 20261023200000, SEM_DISPARO, nos últimos 2 dias; o GitHub guarda só uma execução na fila do grupo, então cada execução leva as pendentes) — com o edital, o tipo e a situação; no máximo 50, da mais antiga à mais nova. Só service_role.';

--
-- Name: classificacao_marcar_calculo(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classificacao_marcar_calculo(p_execucao text, p_pedido uuid, p_situacao text, p_mensagem text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_mensagem text := nullif(btrim(coalesce(p_mensagem, '')), '');
  v_atual text;
begin
  if coalesce(p_execucao, '') !~ '^[A-Za-z0-9_.:-]{1,80}$' then
    raise exception 'Execução inválida' using errcode = '22023';
  end if;
  if p_situacao is null or p_situacao not in ('CALCULANDO', 'FALHOU') then
    raise exception 'Situação inválida (CALCULANDO ou FALHOU)' using errcode = '22023';
  end if;
  if v_mensagem is not null and (length(v_mensagem) > 300 or v_mensagem ~ '@|[0-9]{11}') then
    raise exception 'Mensagem longa demais ou com dado que parece pessoal' using errcode = '22023';
  end if;
  select p."TP_SITUACAO" into v_atual from public."TB_PEDIDO_CALCULO_CLASSIFICACAO" p
   where p."CO_PEDIDO_CALCULO" = p_pedido for update;
  if v_atual is null then
    raise exception 'Pedido de cálculo não encontrado' using errcode = '22023';
  end if;
  if v_atual not in ('PEDIDO', 'CALCULANDO') then
    raise exception 'O pedido já saiu da fila (%)', lower(v_atual) using errcode = '55000';
  end if;
  update public."TB_PEDIDO_CALCULO_CLASSIFICACAO"
     set "TP_SITUACAO" = p_situacao, "DS_MENSAGEM" = v_mensagem, "CO_EXECUCAO" = p_execucao, "DT_ATUALIZACAO" = now()
   where "CO_PEDIDO_CALCULO" = p_pedido;
  return jsonb_build_object('pedido', p_pedido, 'situacao', p_situacao);
end;
$_$;

--
-- Name: FUNCTION classificacao_marcar_calculo(p_execucao text, p_pedido uuid, p_situacao text, p_mensagem text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classificacao_marcar_calculo(p_execucao text, p_pedido uuid, p_situacao text, p_mensagem text) IS 'Job da classificação em Python (--calculo, 20261023200000): marca o pedido de cálculo CALCULANDO (começou) ou FALHOU, com mensagem curta (até 300, sem "@" nem 11 dígitos), só enquanto ele espera (PEDIDO ou CALCULANDO; senão 55000). PRONTO só pela gravação do retrato. Só service_role.';

--
-- Name: classificacao_marcar_preparo(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classificacao_marcar_preparo(p_execucao text, p_lista uuid, p_situacao text, p_mensagem text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_mensagem text := nullif(btrim(coalesce(p_mensagem, '')), '');
begin
  if coalesce(p_execucao, '') !~ '^[A-Za-z0-9_.:-]{1,80}$' then
    raise exception 'Execução inválida' using errcode = '22023';
  end if;
  if p_situacao is null or p_situacao not in ('PREPARANDO', 'NAO_CONFERE', 'FALHOU') then
    raise exception 'Situação inválida (PREPARANDO, NAO_CONFERE ou FALHOU)' using errcode = '22023';
  end if;
  if v_mensagem is not null and (length(v_mensagem) > 300 or v_mensagem ~ '@|[0-9]{11}') then
    raise exception 'Mensagem longa demais ou com dado que parece pessoal' using errcode = '22023';
  end if;
  if not exists (select 1 from public."TB_LISTA_CLASSIFICACAO" l where l."CO_LISTA_CLASSIFICACAO" = p_lista) then
    raise exception 'Lista não encontrada' using errcode = '22023';
  end if;
  insert into public."TB_PREPARO_DESEMPATE" as p
    ("CO_LISTA_CLASSIFICACAO", "TP_SITUACAO", "DS_MENSAGEM", "CO_EXECUCAO", "DT_PEDIDO", "DT_ATUALIZACAO")
  values (p_lista, p_situacao, v_mensagem, p_execucao, now(), now())
  on conflict ("CO_LISTA_CLASSIFICACAO") do update
    set "TP_SITUACAO" = excluded."TP_SITUACAO", "DS_MENSAGEM" = excluded."DS_MENSAGEM",
        "CO_EXECUCAO" = excluded."CO_EXECUCAO", "DT_ATUALIZACAO" = now();
  return jsonb_build_object('lista', p_lista, 'situacao', p_situacao);
end;
$_$;

--
-- Name: FUNCTION classificacao_marcar_preparo(p_execucao text, p_lista uuid, p_situacao text, p_mensagem text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.classificacao_marcar_preparo(p_execucao text, p_lista uuid, p_situacao text, p_mensagem text) IS 'Job da classificação em Python (--desempate, 20261023170000): marca o preparo do relatório de desempate de uma lista — PREPARANDO (começou), NAO_CONFERE (o retrato calculado não é o registrado) ou FALHOU — com mensagem curta (até 300, sem "@" nem 11 dígitos). PRONTO só pela gravação do relatório. Só service_role.';

--
-- Name: comparar_analises_incremental(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comparar_analises_incremental(p_itens jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '10s'
    SET lock_timeout TO '1s'
    AS $_$
declare
  v_total integer;
  v_invalidos integer;
  v_alterados integer;
  v_linhas jsonb;
begin
  if p_itens is null or jsonb_typeof(p_itens) <> 'array' then
    raise exception 'p_itens deve ser um array JSON.';
  end if;
  v_total := jsonb_array_length(p_itens);
  if v_total > 500 then raise exception 'Maximo de 500 itens por comparacao.'; end if;
  if v_total = 0 then return jsonb_build_object('ok',true,'total',0,'alterados',0,'linhas_alteradas','[]'::jsonb); end if;

  with itens as (
    select value as j
    from jsonb_array_elements(p_itens)
  )
  select count(*)::integer into v_invalidos
  from itens
  where coalesce(j->>'linha_origem','') !~ '^[1-9][0-9]*$'
     or nullif(btrim(j->>'chave_natural'),'') is null
     or nullif(btrim(j->>'hash_registro'),'') is null;
  if v_invalidos > 0 then raise exception 'Manifesto incremental contem % item(ns) invalido(s).',v_invalidos; end if;

  with itens as (
    select (j->>'linha_origem')::integer as linha_origem,
           j->>'chave_natural' as chave_natural,
           j->>'hash_registro' as hash_registro
    from jsonb_array_elements(p_itens) j
  ), diffs as (
    select i.linha_origem
    from itens i
    left join public."TB_ANALISE_CURRICULAR" a on a.chave_natural=i.chave_natural
    where a.id is null
       or a.hash_registro is distinct from i.hash_registro
       or a.ativo is not true
  )
  select count(*)::integer,
         coalesce(jsonb_agg(linha_origem order by linha_origem),'[]'::jsonb)
    into v_alterados,v_linhas
  from diffs;

  return jsonb_build_object('ok',true,'total',v_total,'alterados',v_alterados,'linhas_alteradas',v_linhas);
end;
$_$;

--
-- Name: comparar_analises_incremental_v2(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comparar_analises_incremental_v2(p_sync_id uuid, p_itens jsonb, p_reiniciar boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '10s'
    SET lock_timeout TO '1s'
    AS $_$
begin
  if p_sync_id is null then raise exception 'p_sync_id obrigatorio'; end if;
  if not exists (select 1 from public."TL_SYNC_ANALISE"
                  where sync_id = p_sync_id and modo = 'INCREMENTAL_ACTIVE'
                    and status in ('iniciado', 'carregado', 'processando')) then
    raise exception 'Sync incremental % nao esta em andamento.', p_sync_id;
  end if;
  -- [nao-trava] sinal de vida no log (no máximo 1 vez por minuto): a comparação é progresso.
  update public."TL_SYNC_ANALISE"
     set updated_at = now()
   where sync_id = p_sync_id and modo = 'INCREMENTAL_ACTIVE'
     and status in ('iniciado', 'carregado', 'processando')
     and updated_at < now() - interval '1 minute';
  if p_reiniciar then
    delete from public."TM_MANIFESTO_ANALISE" where "CO_SYNC" = p_sync_id;
  end if;
  -- A v1 valida o lote (até 500 itens, linha e chave preenchidas) e compara.
  if p_itens is not null and jsonb_typeof(p_itens) = 'array' and jsonb_array_length(p_itens) between 1 and 500 then
    insert into public."TM_MANIFESTO_ANALISE" ("CO_SYNC", "NU_LINHA_ORIGEM", "DS_CHAVE_NATURAL")
    select p_sync_id, (j->>'linha_origem')::integer, j->>'chave_natural'
      from jsonb_array_elements(p_itens) j
     where coalesce(j->>'linha_origem', '') ~ '^[1-9][0-9]*$'
       and nullif(btrim(j->>'chave_natural'), '') is not null
    on conflict ("CO_SYNC", "NU_LINHA_ORIGEM") do update set "DS_CHAVE_NATURAL" = excluded."DS_CHAVE_NATURAL";
  end if;
  return public.comparar_analises_incremental(p_itens);
end;
$_$;

--
-- Name: FUNCTION comparar_analises_incremental_v2(p_sync_id uuid, p_itens jsonb, p_reiniciar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.comparar_analises_incremental_v2(p_sync_id uuid, p_itens jsonb, p_reiniciar boolean) IS 'Compara um lote do manifesto incremental (como a v1) e anota as linhas no manifesto do sync, para o finalizar desativar quem saiu da planilha. p_reiniciar=true no primeiro lote.';

--
-- Name: concluir_demanda_interna(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.concluir_demanda_interna(p_id uuid, p_concluida boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
declare
  v_usuario uuid := (select auth.uid());
  v_atual public."TB_DEMANDA_INTERNA";
  v_antes jsonb;
  v_depois jsonb;
  v_concluir boolean := coalesce(p_concluida, true);
begin
  if v_usuario is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;
  select * into v_atual from public."TB_DEMANDA_INTERNA" d
   where d."CO_DEMANDA_INTERNA" = p_id for update;
  if v_atual."CO_DEMANDA_INTERNA" is null or v_atual."ST_ATIVO" <> 'S' then
    raise exception 'Demanda não encontrada.' using errcode = 'P0002';
  end if;
  if not private."FC_PODE_EDITAR_DEMANDA"(v_atual."CO_AREA", v_atual."CO_MONITORAMENTO") then
    raise exception 'Sem permissão para esta demanda.' using errcode = '42501';
  end if;

  if (v_atual."ST_CONCLUIDA" = 'S') = v_concluir then
    return private."FC_DEMANDA_INTERNA_JSON"(p_id) || jsonb_build_object('pode_editar', true);
  end if;

  v_antes := private."FC_DEMANDA_INTERNA_JSON"(p_id);
  update public."TB_DEMANDA_INTERNA" d
     set "ST_CONCLUIDA" = case when v_concluir then 'S' else 'N' end,
         "DT_CONCLUSAO" = case when v_concluir then now() end,
         "CO_USUARIO_CONCLUSAO" = case when v_concluir then v_usuario end,
         "CO_USUARIO_ATUALIZACAO" = v_usuario,
         "DT_ATUALIZACAO" = now()
   where d."CO_DEMANDA_INTERNA" = p_id;
  v_depois := private."FC_DEMANDA_INTERNA_JSON"(p_id);
  insert into public."TH_DEMANDA_INTERNA" ("CO_DEMANDA_INTERNA", "TP_ACAO", "DS_ANTES", "DS_DEPOIS", "CO_USUARIO")
  values (p_id, case when v_concluir then 'CONCLUSAO' else 'REABERTURA' end, v_antes, v_depois, v_usuario);

  return v_depois || jsonb_build_object('pode_editar', true);
end;
$$;

--
-- Name: FUNCTION concluir_demanda_interna(p_id uuid, p_concluida boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.concluir_demanda_interna(p_id uuid, p_concluida boolean) IS 'Conclui (true) ou reabre (false) uma demanda interna, com quem e quando. Gestor da área ou administrador global; grava TH_DEMANDA_INTERNA. 20261104120000.';

--
-- Name: concluir_ficha(uuid, integer, integer, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.concluir_ficha(p_ficha uuid, p_versao integer, p_versao_regra integer, p_lancamento jsonb, p_resultado jsonb, p_parecer text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_uid uuid := (select auth.uid());
  v_regra record;
  v_alt jsonb;
  v_cargo text;
  v_conf jsonb;
  v_pend text[];
  v_parecer text := btrim(coalesce(p_parecer, ''));
begin
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha for update;
  perform private."FC_EXIGIR_GRAVAR_FICHA"(v_f, p_versao);
  select * into v_regra from private."FC_REGRA_VIGENTE_FICHA"(p_ficha);
  -- A vaga e o cargo são os da ficha (o lançamento grava os dois) e a regra é a
  -- da vaga: a diferença do cargo por cima do nível (20261013130000).
  v_cargo := (select pv."NO_CARGO" from public."TB_PRE_CLASSIF_VAGA" pv
               where pv."CO_MONITORAMENTO" = v_f."CO_MONITORAMENTO" and pv."CO_VAGA" = v_f."CO_VAGA");
  if jsonb_typeof(p_lancamento) = 'object' then
    p_lancamento := p_lancamento || jsonb_build_object('vaga', v_f."CO_VAGA", 'cargo', v_cargo);
  end if;
  v_conf := private."FC_REGRA_DA_VAGA"(v_regra.p_configuracao, v_f."CO_VAGA", v_cargo, p_lancamento ->> 'nivel');
  if p_versao_regra is distinct from v_regra.p_versao then
    raise exception 'A regra mudou (versão %): a ficha foi recalculada; confira e conclua de novo.', v_regra.p_versao using errcode = 'PT409';
  end if;
  if v_regra.p_situacao <> 'CONFERIDA' then
    raise exception 'A versão % da regra ainda não foi conferida pela coordenação: dá para salvar o rascunho, mas não concluir.', v_regra.p_versao
      using errcode = '22023';
  end if;
  perform private."FC_VALIDAR_LANCAMENTO_FICHA"(v_conf, p_lancamento);
  perform private."FC_VALIDAR_RESULTADO_FICHA"(v_conf, p_lancamento, p_resultado,
                                                private."FC_DOCUMENTAL_DO_EDITAL"(v_f."CO_MONITORAMENTO"));
  v_pend := private."FC_PENDENCIAS_FICHA"(v_conf, p_lancamento, p_resultado);
  if cardinality(v_pend) > 0 then
    raise exception 'Falta para concluir: %.', array_to_string(v_pend[1:5], '; ') using errcode = '22023';
  end if;
  if length(v_parecer) not between 1 and 8000 then
    raise exception 'O parecer é obrigatório (até 8.000 caracteres).' using errcode = '22023';
  end if;
  v_alt := private."FC_ALTERACOES_FICHA"(v_conf, v_f."DS_LANCAMENTO", v_f."DS_RESULTADO", p_lancamento, p_resultado);
  update public."TB_FICHA_ANALISE" set
    "TP_SITUACAO" = 'CONCLUIDA', "NU_VERSAO_REGRA" = v_regra.p_versao,
    "DS_LANCAMENTO" = p_lancamento, "DS_RESULTADO" = p_resultado, "DS_PARECER" = v_parecer,
    "TP_RESULTADO" = p_resultado ->> 'resultado',
    "VL_NOTA_APURADA" = (p_resultado ->> 'nota_apurada')::numeric, "VL_NOTA_FINAL" = (p_resultado ->> 'nota_final')::numeric,
    "CO_USUARIO_CONCLUSAO" = v_uid, "DT_CONCLUSAO" = now(),
    "CO_USUARIO_RASCUNHO" = v_uid, "DT_RASCUNHO" = now(),
    "CO_USUARIO_RESERVA" = null, "DT_RESERVA" = null, "DT_RESERVA_EXPIRA" = null,
    "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
   where "CO_FICHA_ANALISE" = p_ficha;
  perform private."FC_HISTORICO_CONTEUDO_FICHA"(p_ficha, 'CONCLUIR', v_f."TP_SITUACAO", null, v_uid, v_alt,
    jsonb_build_object('lancamento', p_lancamento, 'resultado', p_resultado, 'parecer', v_parecer, 'versao_regra', v_regra.p_versao));
  return json_build_object('versao', v_f."NU_VERSAO" + 1, 'resultado', p_resultado ->> 'resultado',
                           'nota_final', (p_resultado ->> 'nota_final')::numeric, 'versao_regra', v_regra.p_versao);
end;
$$;

--
-- Name: FUNCTION concluir_ficha(p_ficha uuid, p_versao integer, p_versao_regra integer, p_lancamento jsonb, p_resultado jsonb, p_parecer text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.concluir_ficha(p_ficha uuid, p_versao integer, p_versao_regra integer, p_lancamento jsonb, p_resultado jsonb, p_parecer text) IS 'Conclui a ficha: confere a reserva, a versão da ficha (40001), a versão da regra (tem de ser a vigente, 40001, e conferida, 22023), a estrutura e a coerência do resultado e o que falta (situação, motivos, requisitos e extras do cargo, itens recusados, datas e justificativa de nota diferente da declarada) contra a regra da vaga (FC_REGRA_DA_VAGA, 20261013130000); grava o lançamento com a vaga e o cargo da ficha, resultado, notas, parecer, a versão da regra usada (AM-2.3), quem e quando (o login, AM-12.6); libera a reserva; histórico CONCLUIR com o retrato. A conta é a da tela, reconferida em lote pelo Python.';

--
-- Name: conferencia_ler_analises(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferencia_ler_analises(p_apos uuid DEFAULT NULL::uuid, p_limite integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limite integer := least(greatest(coalesce(p_limite, 5000), 1), 10000);
  v_linhas jsonb;
  v_ultimo uuid;
  v_qt integer;
begin
  -- 20261103181500: "vaga" e "nome_vaga" para o robô conferir a vaga sem quadro aqui.
  with pagina as (
    select a.id, a."CO_AREA" as area, private."FC_NUMERO_EDITAL"(a.edital) as numero, a.id_origem,
           a.status_consolidado, a.nota_final_ajustada, a.pontuacao_escolaridade,
           a.pontuacao_cursos_aperfeicoamento, a.pontuacao_experiencia_profissional,
           a.pontuacao_criterio_etnico, a.data_analise, a.updated_at, a.codigo_vaga, a.nome_vaga
      from public."TB_ANALISE_CURRICULAR" a
     where a.ativo and not private."FC_ANALISE_EH_TREINAMENTO"(a.origem_planilha)
       and (p_apos is null or a.id > p_apos)
     order by a.id
     limit v_limite
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', p.id, 'area', p.area, 'edital', e.edital_id, 'numero', p.numero,
           'codigo', nullif(btrim(p.id_origem), ''), 'status', p.status_consolidado,
           'nota', p.nota_final_ajustada, 'formacao', p.pontuacao_escolaridade,
           'cursos', p.pontuacao_cursos_aperfeicoamento, 'experiencia', p.pontuacao_experiencia_profissional,
           'etnico', p.pontuacao_criterio_etnico, 'data_analise', p.data_analise,
           'inscricao', (select (min(c."DT_CANDIDATURA") at time zone 'America/Sao_Paulo')::date
                           from public."TB_EMPREGARE_CANDIDATO" c
                          where c."CO_CANDIDATO_EMPREGARE" = nullif(btrim(p.id_origem), '')),
           'atualizado', p.updated_at,
           'vaga', nullif(btrim(p.codigo_vaga), ''),
           'nome_vaga', case when nullif(btrim(p.nome_vaga), '') is not null then p.nome_vaga end) order by p.id), '[]'::jsonb),
         max(p.id::text)::uuid, count(*)
    into v_linhas, v_ultimo, v_qt
    from pagina p
    left join private."FC_EDITAIS_POR_NUMERO"() e on e.area = p.area and e.numero = p.numero;

  return jsonb_build_object(
    'schema_version', 1,
    'linhas', v_linhas,
    'proximo', case when v_qt = v_limite then v_ultimo end);
end;
$$;

--
-- Name: FUNCTION conferencia_ler_analises(p_apos uuid, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferencia_ler_analises(p_apos uuid, p_limite integer) IS 'Conferências (job Python): uma página (até 10000, pela ordem do id, depois de p_apos) das análises curriculares ativas, só com id, área, edital, código do candidato, status, notas, datas, a data da candidatura na Empregare e o código e o nome da vaga (20261103181500). Sem nome nem CPF. proximo = cursor da página seguinte (nulo na última). Só service_role.';

--
-- Name: conferencia_ler_aprovados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferencia_ler_aprovados() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  with vigentes as (
    select l.id, l.edital_id, l."TP_ORIGEM",
           case when l.edital_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                then l.edital_id::uuid end as edital
      from public."TB_LISTA_APROVADO" l
     where l.vigente is true and coalesce(l.ativo, true)
       and not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" t
                        where t.id::text = l.edital_id and private."FC_EH_TREINAMENTO"(t."ST_TREINAMENTO"))
  ),
  candidatos as (
    select c.id, c.lista_id, v.edital, m."CO_AREA" as area, c.status, c."DT_CONVOCACAO",
           encode(sha256(convert_to('conferencia:' || coalesce(
             'cod:' || nullif(btrim(a.id_origem), ''),
             'nome:' || lower(regexp_replace(btrim(c.nome), '\s+', ' ', 'g'))), 'UTF8')), 'hex') as pessoa,
           -- O vínculo é a matrícula (uma por contratação), em hash: a matrícula não sai do banco.
           encode(sha256(convert_to('vinculo:' || nullif(ltrim(upper(
             regexp_replace(coalesce(c.matricula, ''), '[^0-9A-Za-z]', '', 'g')), '0'), ''), 'UTF8')), 'hex') as vinculo
      from public."TB_CANDIDATO_APROVADO" c
      join vigentes v on v.id = c.lista_id
      left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = v.edital
      left join public."TB_ANALISE_CURRICULAR" a on a.id = c."CO_ANALISE_CURRICULAR"
     where c.removido_em is null and c.status in ('Convocado', 'Contratado')
       -- A linha que o job dá como "em outra lista" (20261024120000) não é mais contratação.
       and not private."FC_EM_OUTRA_LISTA"(c.id)
  ),
  publicacoes as (
    select distinct on (h."CO_LISTA_APROVADO") h."CO_LISTA_APROVADO", h."DS_PENDENCIA"
      from public."TH_PUBLICACAO_APROVADO" h
      join vigentes v on v.id = h."CO_LISTA_APROVADO"
     where v."TP_ORIGEM" = 'CLASSIFICACAO'
     order by h."CO_LISTA_APROVADO", h."DT_PUBLICACAO" desc
  )
  select jsonb_build_object(
    'schema_version', 1,
    'candidatos', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', c.id, 'lista', c.lista_id, 'edital', c.edital, 'area', c.area, 'status', c.status,
          'convocado_em', c."DT_CONVOCACAO", 'pessoa', c.pessoa, 'vinculo', c.vinculo)), '[]'::jsonb)
        from candidatos c
    ),
    'pendencias', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'lista', p."CO_LISTA_APROVADO", 'edital', v.edital, 'area', m."CO_AREA",
          'candidatos', (
            select coalesce(jsonb_agg(o.id order by o.id), '[]'::jsonb)
              from jsonb_array_elements(p."DS_PENDENCIA") x
              join public."TB_CANDIDATO_APROVADO" o
                on o.id::text = x ->> 'candidato_id'
             where o.removido_em is null
               and (o.status is not null or nullif(btrim(coalesce(o.matricula, '')), '') is not null
                    or nullif(btrim(coalesce(o.processo_sei, '')), '') is not null)
               and not exists (select 1 from public."TB_CANDIDATO_APROVADO" n
                                where n.lista_id = p."CO_LISTA_APROVADO" and n.removido_em is null
                                  and n."CO_CANDIDATO_ANTERIOR" = o.id)))), '[]'::jsonb)
        from publicacoes p
        join vigentes v on v.id = p."CO_LISTA_APROVADO"
        left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = v.edital
    )
  );
$_$;

--
-- Name: FUNCTION conferencia_ler_aprovados(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferencia_ler_aprovados() IS 'Conferências (job Python): convocados e contratados das listas de aprovados vigentes (id, lista, edital, status, data da convocação, um hash da pessoa — código do candidato ou nome normalizado — e um hash do vínculo — a matrícula normalizada —, para achar a mesma pessoa com duas matrículas no mesmo edital e a mesma matrícula em duas linhas) e, das listas publicadas pela Classificação, as pendências da publicação ainda sem desfecho (ids). Sem nome, CPF nem matrícula. Só service_role.';

--
-- Name: conferencia_ler_cargas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferencia_ler_cargas() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'schema_version', 1,
    'vagas', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'vaga', v."CO_VAGA", 'edital', v."CO_MONITORAMENTO", 'area', m."CO_AREA",
          'situacao', v."TP_SITUACAO", 'ativos', v."QT_CANDIDATO_ATIVO", 'arquivo', v."QT_LINHA_ARQUIVO",
          'novos', (select count(*) from public."TB_EMPREGARE_CANDIDATO" c
                     where c."CO_VAGA" = v."CO_VAGA" and c."ST_REGISTRO_ATIVO" = 'S' and c."DT_CRIACAO" >= s."DT_INICIO"),
          'saidas', (select count(*) from public."TB_EMPREGARE_CANDIDATO" c
                      where c."CO_VAGA" = v."CO_VAGA" and c."DT_DESATIVACAO" >= s."DT_INICIO"),
          'carga_em', coalesce(v."DT_ULTIMA_CARGA", v."DT_ATUALIZACAO"))), '[]'::jsonb)
        from public."TB_EMPREGARE_VAGA" v
        join public."TL_SYNC_EMPREGARE" s on s."CO_SYNC" = v."CO_SYNC"
        left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = v."CO_MONITORAMENTO"
       where v."DT_ATUALIZACAO" >= now() - interval '30 days'
    )
  );
$$;

--
-- Name: FUNCTION conferencia_ler_cargas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferencia_ler_cargas() IS 'Conferências (job Python): para cada vaga da Empregare carregada nos últimos 30 dias, a situação da última carga, os candidatos ativos, os do arquivo, os que entraram e os que saíram nela (para achar variação brusca). Sem dado pessoal. Só service_role.';

--
-- Name: conferencia_ler_contexto(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferencia_ler_contexto() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'schema_version', 1,
    'gerado_em', now(),
    'hoje', (now() at time zone 'America/Sao_Paulo')::date,
    'editais', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', m.id, 'numero', private."FC_NUMERO_EDITAL"(m.edital), 'area', m."CO_AREA",
          'ativo', coalesce(m.ativo, false), 'status', m.status) order by m."CO_AREA", m.edital), '[]'::jsonb)
        from public."TB_MONITORAMENTO_INDIGENA" m
    ),
    'regras', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'edital', r."CO_MONITORAMENTO",
          'versao', r."NU_VERSAO_VIGENTE",
          'nota_minima', h."DS_CONFIGURACAO" #> '{documental,nota_minima}',
          'teto_experiencia', h."DS_CONFIGURACAO" #> '{documental,teto_experiencia}')), '[]'::jsonb)
        from public."TB_REGRA_CLASSIFICACAO" r
        join public."TH_REGRA_CLASSIFICACAO" h
          on h."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
    )
  );
$$;

--
-- Name: FUNCTION conferencia_ler_contexto(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferencia_ler_contexto() IS 'Conferências (job Python): editais (id, número, área, ativo), o dia de hoje em Brasília e a regra de classificação vigente de cada edital (nota mínima documental e teto de experiência, quando a regra tiver). Sem dado pessoal. Só service_role.';

--
-- Name: conferencia_ler_entrevistas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferencia_ler_entrevistas() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with entrevistas as (
    select e."CO_ENTREVISTA", e."CO_MONITORAMENTO", e."CO_AREA", e."CO_ANALISE_CURRICULAR",
           e."TP_ORIGEM", e."VL_NOTA_TOTAL", e."ST_COMPARECEU", e."TP_PARECER", e."DT_ATUALIZACAO"
      from public."TB_ENTREVISTA" e
     where coalesce(e."ST_ATIVO", 'S') = 'S'
       and not private."FC_EDITAL_EH_TREINAMENTO"(e."CO_MONITORAMENTO")
  ),
  editais_do_sistema as (
    select distinct e."CO_MONITORAMENTO" as edital
      from entrevistas e
     where e."TP_ORIGEM" = 'sistema' and e."CO_MONITORAMENTO" is not null
  )
  select jsonb_build_object(
    'schema_version', 1,
    'entrevistas', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', e."CO_ENTREVISTA", 'edital', e."CO_MONITORAMENTO", 'area', e."CO_AREA",
          'analise', e."CO_ANALISE_CURRICULAR", 'origem', e."TP_ORIGEM", 'nota', e."VL_NOTA_TOTAL",
          'compareceu', e."ST_COMPARECEU", 'parecer', e."TP_PARECER")), '[]'::jsonb)
        from entrevistas e
    ),
    'agenda', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', g."CO_AGENDA_ENTREVISTA", 'edital', g."CO_MONITORAMENTO", 'area', m."CO_AREA",
          'analise', g."CO_ANALISE_CURRICULAR", 'codigo', nullif(btrim(a.id_origem), ''),
          'data', g."DT_ENTREVISTA", 'inicio', g."HR_INICIO", 'fim', g."HR_FIM")), '[]'::jsonb)
        from public."TB_AGENDA_ENTREVISTA" g
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = g."CO_MONITORAMENTO"
        left join public."TB_ANALISE_CURRICULAR" a on a.id = g."CO_ANALISE_CURRICULAR"
       where not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
    ),
    'avaliacoes', (
      -- Roteiro com aspectos: confere a nota de cada aspecto (a do avaliador é a média deles).
      select coalesce(jsonb_agg(jsonb_build_object(
          'entrevista', n.entrevista, 'competencia', n.competencia, 'nota', n.nota)), '[]'::jsonb)
        from (
          select v."CO_ENTREVISTA" as entrevista, v."CO_COMPETENCIA" as competencia, v."VL_NOTA" as nota
            from public."TB_ENTREVISTA_AVALIACAO" v
            join entrevistas e on e."CO_ENTREVISTA" = v."CO_ENTREVISTA"
            join public."TB_ROTEIRO_COMPETENCIA" k on k."CO_COMPETENCIA" = v."CO_COMPETENCIA"
           where not exists (select 1 from public."TB_ROTEIRO_ASPECTO" s where s."CO_ROTEIRO" = k."CO_ROTEIRO")
          union all
          select y."CO_ENTREVISTA", y."CO_COMPETENCIA", y."VL_NOTA"
            from public."TB_ENTREVISTA_AVALIACAO_ASPECTO" y
            join entrevistas e on e."CO_ENTREVISTA" = y."CO_ENTREVISTA"
        ) n
    ),
    'competencias', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', c."CO_COMPETENCIA", 'roteiro', c."CO_ROTEIRO", 'maxima', c."VL_NOTA_MAXIMA")), '[]'::jsonb)
        from public."TB_ROTEIRO_COMPETENCIA" c
    ),
    'roteiros', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', r."CO_ROTEIRO", 'escala', r."TP_ESCALA", 'passo', r."VL_PASSO",
          'permitidas', r."DS_NOTAS_PERMITIDAS",
          'niveis', (select coalesce(jsonb_agg(n."VL_NOTA" order by n."VL_NOTA"), '[]'::jsonb)
                       from public."TB_ROTEIRO_NIVEL" n where n."CO_ROTEIRO" = r."CO_ROTEIRO"))), '[]'::jsonb)
        from public."TB_ROTEIRO_ENTREVISTA" r
    ),
    'convocacao', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'edital', x.edital, 'lista', x.lista,
          'analises', (select coalesce(jsonb_agg(c), '[]'::jsonb)
                         from private."FC_CONVOCADOS_DA_LISTA"(x.lista) c))), '[]'::jsonb)
        from (select s.edital, private."FC_LISTA_CONVOCACAO_VIGENTE"(s.edital) as lista
                from editais_do_sistema s) x
    )
  );
$$;

--
-- Name: FUNCTION conferencia_ler_entrevistas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferencia_ler_entrevistas() IS 'Conferências (job Python): entrevistas ativas (id, edital, análise, origem, nota, comparecimento), a agenda (data e horário por análise, com o código do candidato), as notas de cada avaliador (roteiro com aspectos: a nota de cada aspecto), a escala de cada roteiro e a lista de convocação vigente (análises) dos editais com convocados pelo sistema. Sem nome nem CPF. Só service_role.';

--
-- Name: conferencia_ler_fichas(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferencia_ler_fichas(p_apos uuid DEFAULT NULL::uuid, p_limite integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limite integer := least(greatest(coalesce(p_limite, 500), 1), 1000);
  v_linhas jsonb;
  v_regras jsonb;
  v_ultimo uuid;
  v_qt integer;
begin
  with pagina as (
    select f."CO_FICHA_ANALISE" as ficha, f."CO_MONITORAMENTO" as edital, f."CO_EMPREGARE_CANDIDATO" as candidato,
           f."CO_REGRA_ANALISE" as regra, f."NU_VERSAO_REGRA" as versao, f."NU_VERSAO" as versao_ficha,
           f."DS_LANCAMENTO" as lancamento, f."DS_RESULTADO" as resultado, f."DS_PARECER" as parecer
      from public."TB_FICHA_ANALISE" f
     where f."TP_SITUACAO" = 'CONCLUIDA'
       and (p_apos is null or f."CO_FICHA_ANALISE" > p_apos)
       and not private."FC_EDITAL_EH_TREINAMENTO"(f."CO_MONITORAMENTO")
     order by f."CO_FICHA_ANALISE"
     limit v_limite
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'ficha', p.ficha,
           'analise', (select a.id from public."TB_ANALISE_CURRICULAR" a
                        where a.chave_natural = 'monitora|' || p.edital || '|' || p.candidato),
           'edital', p.edital, 'area', m."CO_AREA",
           'regra', p.regra, 'versao_regra', p.versao,
           -- A versão da ficha: o job de conferências manda para revisão só a que não mudou (20261023090000).
           'versao', p.versao_ficha,
           'lancamento', p.lancamento, 'resultado', p.resultado, 'parecer', p.parecer,
           'documental', private."FC_DOCUMENTAL_DO_EDITAL"(p.edital)) order by p.ficha), '[]'::jsonb),
         coalesce((select jsonb_agg(jsonb_build_object('regra', h."CO_REGRA_ANALISE", 'versao', h."NU_VERSAO",
                                                       'configuracao', private."FC_REGRA_COM_DATA_LIMITE"(h."DS_CONFIGURACAO", rg."CO_MONITORAMENTO")))
                     from public."TH_REGRA_ANALISE" h
                     join public."TB_REGRA_ANALISE" rg on rg."CO_REGRA_ANALISE" = h."CO_REGRA_ANALISE"
                    where (h."CO_REGRA_ANALISE", h."NU_VERSAO") in (select distinct x.regra, x.versao from pagina x)), '[]'::jsonb),
         max(p.ficha::text)::uuid, count(*)
    into v_linhas, v_regras, v_ultimo, v_qt
    from pagina p
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id = p.edital;

  return jsonb_build_object(
    'schema_version', 1,
    'linhas', v_linhas,
    'regras', v_regras,
    'proximo', case when v_qt = v_limite then v_ultimo end);
end;
$$;

--
-- Name: FUNCTION conferencia_ler_fichas(p_apos uuid, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferencia_ler_fichas(p_apos uuid, p_limite integer) IS 'Conferências (job Python): uma página (até 1000, pela ordem do id, depois de p_apos) das fichas CONCLUIDA da avaliação documental fora dos editais de treinamento, com a análise publicada, edital, área, regra e versão, lançamento, resultado, parecer e nota mínima de agora; em regras, a configuração de cada versão usada na página. Sem nome nem CPF. proximo = cursor da página seguinte (nulo na última). Só service_role.';

--
-- Name: conferencia_ler_listas_e_quadros(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferencia_ler_listas_e_quadros() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- 20261103181500: a leitura da classificação das conferências sem as análises. A última
  -- atualização das análises e as vagas sem quadro saem das páginas de conferencia_ler_analises,
  -- no robô (scripts/conferencias/regras.py, python/monitora/classificacao/quadro_da_vaga.py).
  with ultimas as (
    select distinct on (l."CO_MONITORAMENTO", l."TP_LISTA")
           l."CO_LISTA_CLASSIFICACAO", l."CO_MONITORAMENTO", l."TP_LISTA", l."DT_GERACAO",
           l."QT_PENDENCIA", l."ST_PUBLICADA", l."DS_RESULTADO"
      from public."TB_LISTA_CLASSIFICACAO" l
     where not private."FC_EDITAL_EH_TREINAMENTO"(l."CO_MONITORAMENTO")
     order by l."CO_MONITORAMENTO", l."TP_LISTA", l."DT_GERACAO" desc, l."CO_LISTA_CLASSIFICACAO" desc
  )
  select jsonb_build_object(
    'schema_version', 1,
    'listas', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', u."CO_LISTA_CLASSIFICACAO", 'edital', u."CO_MONITORAMENTO", 'area', m."CO_AREA",
          'tipo', u."TP_LISTA", 'gerada_em', u."DT_GERACAO", 'pendencias', u."QT_PENDENCIA",
          'publicada', u."ST_PUBLICADA" = 'S',
          'vagas_pendentes', (select coalesce(jsonb_agg(distinct p ->> 'vaga'), '[]'::jsonb)
                                from jsonb_array_elements(case when jsonb_typeof(u."DS_RESULTADO" -> 'pendencias') = 'array'
                                                               then u."DS_RESULTADO" -> 'pendencias' else '[]'::jsonb end) p
                               where p ->> 'vaga' is not null))), '[]'::jsonb)
        from ultimas u
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = u."CO_MONITORAMENTO"
    ),
    'ajustes', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', j."CO_AJUSTE_PONTUACAO", 'edital', j."CO_MONITORAMENTO", 'area', m."CO_AREA",
          'tipo', j."TP_LISTA", 'aprovado_em', j."DT_APROVACAO")), '[]'::jsonb)
        from public."TB_AJUSTE_PONTUACAO_RECURSO" j
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = j."CO_MONITORAMENTO"
       where j."TP_SITUACAO" = 'APROVADO'
         and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
    ),
    'quadros', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', q."CO_QUADRO_VAGA", 'edital', q."CO_MONITORAMENTO", 'cargo', q."NO_CARGO", 'lotacao', q."NO_LOTACAO")
          order by q."CO_MONITORAMENTO", q."CO_QUADRO_VAGA"), '[]'::jsonb)
        from public."TB_QUADRO_VAGA_EDITAL" q
       where q."ST_REGISTRO_ATIVO" = 'S'
    )
  );
$$;

--
-- Name: FUNCTION conferencia_ler_listas_e_quadros(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferencia_ler_listas_e_quadros() IS 'Conferências (job Python, só service_role): a última lista de classificação de cada edital e tipo (fora do treinamento) com as vagas com empate pendente, os ajustes de recurso aprovados e as linhas ativas do quadro de vagas (id, edital, cargo, lotação), cruas. A vaga sem linha no quadro e a lista final desatualizada são conferidas no robô, com as páginas de conferencia_ler_analises (20261103181500).';

--
-- Name: conferir_eliminados_pre_classificacao(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferir_eliminados_pre_classificacao(p_edital uuid, p_chaves text[]) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
begin
  if cardinality(p_chaves) > 10000 then
    raise exception 'No máximo 10.000 por vez.' using errcode = '22023';
  end if;
  return (
    with pedidas as (
      select split_part(k, '|', 1) as vaga, split_part(k, '|', 2) as codigo
        from unnest(coalesce(p_chaves, '{}')) k
    ),
    linhas as (
      select a."CO_VAGA"::text as vaga, c."CO_CANDIDATO_EMPREGARE"::text as codigo, c."NO_CANDIDATO" as nome,
             a."TP_SITUACAO" as situacao, a."DS_MOTIVO_ELIMINACAO" as motivo, a."CO_MOTIVO_ELIMINACAO" as motivo_codigo,
             a."NO_MODALIDADE" as modalidade, a."VL_ART" as art, a."VL_NOTA_DECLARADA" as declarada,
             a."VL_NOTA_ORDEM" as nota, a."TP_ORIGEM_NOTA" as origem_nota
        from pedidas p
        join public."TB_EMPREGARE_CANDIDATO" c on c."CO_VAGA" = p.vaga and c."CO_CANDIDATO_EMPREGARE"::text = p.codigo
        join public."TB_PRE_CLASSIFICACAO" a
          on a."CO_MONITORAMENTO" = p_edital and a."CO_EMPREGARE_CANDIDATO" = c."CO_EMPREGARE_CANDIDATO"
    )
    select json_build_object(
      'schema_version', 1,
      'edital', p_edital,
      'candidatos', coalesce((select json_agg(row_to_json(l)) from linhas l), '[]'::json),
      'vagas', coalesce((
        select json_agg(json_build_object('codigo', pv."CO_VAGA", 'cargo', pv."NO_CARGO"))
          from public."TB_PRE_CLASSIF_VAGA" pv
         where pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" in (select distinct l.vaga from linhas l)), '[]'::json)));
end;
$$;

--
-- Name: FUNCTION conferir_eliminados_pre_classificacao(p_edital uuid, p_chaves text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferir_eliminados_pre_classificacao(p_edital uuid, p_chaves text[]) IS 'Comunicados de eliminação: a situação de agora só dos marcados (chaves vaga|código) e o cargo das vagas deles, em vez de reler a pré-classificação inteira. Coordenação do edital.';

--
-- Name: conferir_regra_analise(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferir_regra_analise(p_edital uuid, p_versao integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_regra public."TB_REGRA_ANALISE";
  v_autor uuid;
begin
  select * into v_regra from public."TB_REGRA_ANALISE" where "CO_MONITORAMENTO" = p_edital for update;
  if v_regra."CO_REGRA_ANALISE" is null then
    raise exception 'O edital ainda não tem regra.' using errcode = '22023';
  end if;
  if p_versao is distinct from v_regra."NU_VERSAO_VIGENTE" then
    raise exception 'A regra mudou (versão %); confira de novo.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
  end if;
  if v_regra."TP_SITUACAO" <> 'CONFERIDA' then
    select h."CO_USUARIO" into v_autor
      from public."TH_REGRA_ANALISE" h
     where h."CO_REGRA_ANALISE" = v_regra."CO_REGRA_ANALISE" and h."NU_VERSAO" = v_regra."NU_VERSAO_VIGENTE";
    if v_autor = (select auth.uid()) and not private.is_master() then
      raise exception 'Dupla conferência: quem salvou a versão % não pode conferi-la. Peça a outra pessoa da coordenação do edital.', v_regra."NU_VERSAO_VIGENTE"
        using errcode = '42501';
    end if;
    update public."TB_REGRA_ANALISE"
       set "TP_SITUACAO" = 'CONFERIDA', "CO_USUARIO_CONFERENCIA" = (select auth.uid()), "DT_CONFERENCIA" = now(), "DT_ATUALIZACAO" = now()
     where "CO_REGRA_ANALISE" = v_regra."CO_REGRA_ANALISE";
  end if;
  return json_build_object('regra', private."FC_REGRA_ANALISE_JSON"(p_edital), 'fichas_afetadas', '[]'::json);
end;
$$;

--
-- Name: FUNCTION conferir_regra_analise(p_edital uuid, p_versao integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conferir_regra_analise(p_edital uuid, p_versao integer) IS 'Marca a versão vigente da regra como conferida (quem e quando). Dupla conferência: quem salvou a versão vigente não confere (42501), salvo o administrador global. p_versao tem de ser a vigente (senão 40001). Salvar uma versão nova volta para Conferir. Só a coordenação do edital.';

--
-- Name: conferir_regra_triagem(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conferir_regra_triagem(p_edital uuid, p_versao integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_regra public."TB_REGRA_TRIAGEM";
  v_autor uuid;
begin
  select * into v_regra from public."TB_REGRA_TRIAGEM" where "CO_MONITORAMENTO" = p_edital for update;
  if v_regra."CO_REGRA_TRIAGEM" is null then
    raise exception 'O edital ainda não tem regra da Triagem.' using errcode = '22023';
  end if;
  if p_versao is distinct from v_regra."NU_VERSAO_VIGENTE" then
    raise exception 'A regra da Triagem mudou (versão %); confira de novo.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
  end if;
  if v_regra."TP_SITUACAO" <> 'CONFERIDA' then
    select h."CO_USUARIO" into v_autor
      from public."TH_REGRA_TRIAGEM" h
     where h."CO_REGRA_TRIAGEM" = v_regra."CO_REGRA_TRIAGEM" and h."NU_VERSAO" = v_regra."NU_VERSAO_VIGENTE";
    if v_autor = (select auth.uid()) and not private.is_master() then
      raise exception 'Dupla conferência: quem salvou a versão % não pode conferi-la. Peça a outra pessoa da coordenação do edital.', v_regra."NU_VERSAO_VIGENTE"
        using errcode = '42501';
    end if;
    update public."TB_REGRA_TRIAGEM"
       set "TP_SITUACAO" = 'CONFERIDA', "CO_USUARIO_CONFERENCIA" = (select auth.uid()), "DT_CONFERENCIA" = now(), "DT_ATUALIZACAO" = now()
     where "CO_REGRA_TRIAGEM" = v_regra."CO_REGRA_TRIAGEM";
  end if;
  return json_build_object('regra', private."FC_REGRA_TRIAGEM_JSON"(p_edital));
end;
$$;

--
-- Name: configurar_entrevista_edital(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.configurar_entrevista_edital(p_edital uuid, p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_ENTREVISTAS_EDITAL"(p_edital, 2);
  v_roteiro uuid := nullif(p_dados ->> 'roteiro', '')::uuid;
  b jsonb;
  v_av uuid;
  v_nome text;
  v_comps uuid[];
  v_qt_roteiro integer;
  v_banca smallint;
  v_competencia text;
begin
  if v_roteiro is null or not exists (select 1 from public."TB_ROTEIRO_ENTREVISTA" r where r."CO_ROTEIRO" = v_roteiro) then
    raise exception 'Escolha um roteiro' using errcode = '22023';
  end if;
  if exists (select 1 from public."TB_ENTREVISTA" e join public."TB_ENTREVISTA_AVALIACAO" x on x."CO_ENTREVISTA" = e."CO_ENTREVISTA"
              where e."CO_MONITORAMENTO" = p_edital and e."CO_ROTEIRO" is distinct from v_roteiro) then
    raise exception 'Já há notas lançadas com outro roteiro neste edital; o roteiro não pode mais ser trocado' using errcode = '23514';
  end if;
  select count(*) into v_qt_roteiro from public."TB_ROTEIRO_COMPETENCIA" k where k."CO_ROTEIRO" = v_roteiro;

  -- A convocação é a lista da Classificação: DS_CONVOCACAO não é mais gravada (fica o que havia).
  insert into public."TB_ENTREVISTA_EDITAL" ("CO_MONITORAMENTO", "CO_ROTEIRO", "DS_BANCA", "TP_LANCAMENTO", "CO_USUARIO_ATUALIZACAO")
  values (p_edital, v_roteiro, coalesce(p_dados -> 'banca', '[]'),
          coalesce(nullif(p_dados ->> 'lancamento', ''), 'SECRETARIA'), (select auth.uid()))
  on conflict ("CO_MONITORAMENTO") do update set
    "CO_ROTEIRO" = excluded."CO_ROTEIRO", "DS_BANCA" = excluded."DS_BANCA",
    "TP_LANCAMENTO" = excluded."TP_LANCAMENTO", "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO";

  update public."TB_ENTREVISTA" set "CO_ROTEIRO" = v_roteiro
   where "CO_MONITORAMENTO" = p_edital and "TP_ORIGEM" = 'sistema' and "CO_ROTEIRO" is distinct from v_roteiro;

  -- Outro roteiro, outras competências: os vínculos com as do roteiro anterior saem (o membro volta a avaliar todas).
  delete from public."TB_ENTREVISTA_AVALIADOR_COMPETENCIA" l
   using public."TB_ENTREVISTA_AVALIADOR" a, public."TB_ROTEIRO_COMPETENCIA" k
   where l."CO_AVALIADOR" = a."CO_AVALIADOR" and a."CO_MONITORAMENTO" = p_edital
     and k."CO_COMPETENCIA" = l."CO_COMPETENCIA" and k."CO_ROTEIRO" <> v_roteiro;

  -- Banca: membros enviados (com id = atualiza; sem id = novo); os que não vieram saem (ST_ATIVO N).
  if jsonb_typeof(p_dados -> 'avaliadores') = 'array' then
    update public."TB_ENTREVISTA_AVALIADOR" a set "ST_ATIVO" = 'N'
     where a."CO_MONITORAMENTO" = p_edital and a."ST_ATIVO" = 'S'
       and not exists (select 1 from jsonb_array_elements(p_dados -> 'avaliadores') x where nullif(x ->> 'id', '')::uuid = a."CO_AVALIADOR");
    for b in select value from jsonb_array_elements(p_dados -> 'avaliadores') loop
      v_av := null;
      if nullif(b ->> 'id', '') is not null then
        update public."TB_ENTREVISTA_AVALIADOR" set "NO_AVALIADOR" = btrim(b ->> 'nome'), "NO_ORIGEM" = btrim(b ->> 'origem'),
               "NU_BANCA" = coalesce(nullif(b ->> 'banca', '')::smallint, 1), "CO_PERFIL_USUARIO" = nullif(b ->> 'perfil', '')::uuid, "ST_ATIVO" = 'S'
         where "CO_AVALIADOR" = (b ->> 'id')::uuid and "CO_MONITORAMENTO" = p_edital
        returning "CO_AVALIADOR" into v_av;
      else
        insert into public."TB_ENTREVISTA_AVALIADOR" ("CO_MONITORAMENTO", "NO_AVALIADOR", "NO_ORIGEM", "NU_BANCA", "CO_PERFIL_USUARIO")
        values (p_edital, btrim(b ->> 'nome'), btrim(b ->> 'origem'), coalesce(nullif(b ->> 'banca', '')::smallint, 1), nullif(b ->> 'perfil', '')::uuid)
        returning "CO_AVALIADOR" into v_av;
      end if;

      -- Competências do membro (avaliador por competência): nulo = todas; lista = só estas. Sem a chave, fica como estava.
      if v_av is null or not (b ? 'competencias') then continue; end if;
      if jsonb_typeof(b -> 'competencias') = 'array' then
        begin
          select coalesce(array_agg(distinct x::uuid), '{}') into v_comps from jsonb_array_elements_text(b -> 'competencias') x;
        exception when invalid_text_representation then
          raise exception 'Competência inválida para %', btrim(b ->> 'nome') using errcode = '22023';
        end;
        if cardinality(v_comps) = 0 then
          raise exception 'Marque ao menos uma competência para %', btrim(b ->> 'nome') using errcode = '22023';
        end if;
        if exists (select 1 from unnest(v_comps) c
                    where not exists (select 1 from public."TB_ROTEIRO_COMPETENCIA" k where k."CO_COMPETENCIA" = c and k."CO_ROTEIRO" = v_roteiro)) then
          raise exception 'Competência não é do roteiro deste edital' using errcode = '22023';
        end if;
        if cardinality(v_comps) = v_qt_roteiro then v_comps := '{}'; end if; -- todas = sem vínculo
      elsif jsonb_typeof(b -> 'competencias') = 'null' then
        v_comps := '{}';
      else
        raise exception 'Competências do membro: informe uma lista ou nulo' using errcode = '22023';
      end if;
      -- Não tira de alguém a competência em que ele já deu nota.
      v_nome := null;
      select k."NO_COMPETENCIA" into v_nome
        from public."TB_ENTREVISTA_AVALIACAO" x
        join public."TB_ROTEIRO_COMPETENCIA" k on k."CO_COMPETENCIA" = x."CO_COMPETENCIA"
       where x."CO_AVALIADOR" = v_av and cardinality(v_comps) > 0 and not (x."CO_COMPETENCIA" = any (v_comps))
       order by k."NU_ORDEM" limit 1;
      if v_nome is not null then
        raise exception '% já tem nota em "%": apague essas notas antes de tirar a competência dele', btrim(b ->> 'nome'), v_nome using errcode = '23514';
      end if;
      delete from public."TB_ENTREVISTA_AVALIADOR_COMPETENCIA" l
       where l."CO_AVALIADOR" = v_av and not (l."CO_COMPETENCIA" = any (v_comps));
      insert into public."TB_ENTREVISTA_AVALIADOR_COMPETENCIA" ("CO_AVALIADOR", "CO_COMPETENCIA", "CO_USUARIO_CRIACAO")
      select v_av, c, (select auth.uid()) from unnest(v_comps) c
      on conflict ("CO_AVALIADOR", "CO_COMPETENCIA") do nothing;
    end loop;

    -- Em cada banca com membros, toda competência do roteiro precisa de ao menos um avaliador.
    select bb."NU_BANCA", k."NO_COMPETENCIA" into v_banca, v_competencia
      from (select distinct a."NU_BANCA" from public."TB_ENTREVISTA_AVALIADOR" a
             where a."CO_MONITORAMENTO" = p_edital and a."ST_ATIVO" = 'S') bb
      join public."TB_ROTEIRO_COMPETENCIA" k on k."CO_ROTEIRO" = v_roteiro
     where not exists (select 1 from public."TB_ENTREVISTA_AVALIADOR" a
                        where a."CO_MONITORAMENTO" = p_edital and a."ST_ATIVO" = 'S' and a."NU_BANCA" = bb."NU_BANCA"
                          and private."FC_AVALIADOR_AVALIA"(a."CO_AVALIADOR", k."CO_COMPETENCIA"))
     order by bb."NU_BANCA", k."NU_ORDEM" limit 1;
    if v_competencia is not null then
      raise exception 'Na banca %, ninguém avalia "%": marque essa competência para ao menos um membro', v_banca, v_competencia using errcode = '22023';
    end if;
  end if;

  return public.obter_entrevistas_do_edital(p_edital);
end;
$$;

--
-- Name: FUNCTION configurar_entrevista_edital(p_edital uuid, p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.configurar_entrevista_edital(p_edital uuid, p_dados jsonb) IS 'Grava a configuração da entrevista do edital: roteiro, composição da banca, modo de lançamento e membros da banca, com as competências de cada um (avaliadores[].competencias: nulo = todas; lista = só estas; sem a chave, fica como estava). Recusa competência de fora do roteiro, lista vazia e banca com competência sem avaliador (22023), tirar competência de quem já deu nota nela e trocar o roteiro com notas (23514). A convocação e as vagas são as da Classificação. entrevistas >= editor e o edital.';

--
-- Name: confirmar_empate_da_posicao(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirmar_empate_da_posicao(p_pendencia uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private."FC_PENDENCIA_PARA_DECIDIR"(p_pendencia, array['POSICAO_REPETIDA'], p_motivo);
  return private."FC_FECHAR_PENDENCIA"(p_pendencia, 'EMPATE_PREVISTO', p_motivo, '[]'::jsonb);
end;
$$;

--
-- Name: FUNCTION confirmar_empate_da_posicao(p_pendencia uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirmar_empate_da_posicao(p_pendencia uuid, p_motivo text) IS 'Pendência "Posição repetida": o gestor confirma o empate previsto no edital; a mesma pendência (as mesmas linhas na mesma posição) não volta. Quem decide (FC_PODE_DECIDIR_PENDENCIA), com motivo e histórico. 20261026190000.';

--
-- Name: contratacao_ler_aprovados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contratacao_ler_aprovados() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with vigentes as (
    select l.id, l.edital_id::uuid as edital, m."CO_AREA" as area
      from public."TB_LISTA_APROVADO" l
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
     where l.vigente is true
       and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
  )
  select jsonb_build_object(
    'schema_version', 1,
    -- Toda linha com status das listas vigentes (ativas ou não: o KPI conta as duas): as Contratado
    -- com o vínculo e o candidato anterior; as outras, para o alcance da convocação de cada vaga.
    'linhas', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'id', c.id, 'lista', c.lista_id, 'edital', v.edital, 'area', v.area,
          'vaga', c.codigo_vaga, 'modalidade', c.modalidade, 'classificacao', c.classificacao,
          'status', c.status,
          'vinculo', case when c.status = 'Contratado' then private."FC_VINCULO_DA_MATRICULA"(c.matricula) end,
          'anterior', case when c.status = 'Contratado' then c."CO_CANDIDATO_ANTERIOR" end)
          order by c.id), '[]'::jsonb)
        from public."TB_CANDIDATO_APROVADO" c
        join vigentes v on v.id = c.lista_id
       where c.removido_em is null and c.status is not null
    ),
    'instantaneo', (
      select coalesce(jsonb_agg(jsonb_build_object(
          'candidato', x."CO_CANDIDATO_APROVADO", 'edital', x."CO_MONITORAMENTO", 'vinculo', x."DS_VINCULO",
          'situacao', x."TP_SITUACAO", 'contratacao', x."CO_CANDIDATO_CONTRATACAO", 'motivo', x."TP_MOTIVO",
          'texto', x."DS_MOTIVO", 'base', x."DS_BASE", 'versao', x."NU_VERSAO_REGRA")
          order by x."CO_CANDIDATO_APROVADO"), '[]'::jsonb)
        from public."TB_CONTRATACAO_APROVADO" x
    )
  );
$$;

--
-- Name: FUNCTION contratacao_ler_aprovados(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contratacao_ler_aprovados() IS 'Job "Contratado em outra lista" (Python, só service_role): as linhas com status das listas de aprovados vigentes (id, lista, edital, área, vaga, modalidade, posição, status; nas Contratado, o hash da matrícula e o candidato anterior) e o instantâneo TB_CONTRATACAO_APROVADO. Sem nome, CPF nem matrícula. 20261024120000.';

--
-- Name: convocar_para_entrevista(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convocar_para_entrevista(p_edital uuid, p_lista uuid, p_analises uuid[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_ENTREVISTAS_EDITAL"(p_edital, 2);
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_roteiro uuid;
  v_vigente uuid;
  v_fora integer;
  v_qt integer;
begin
  select "CO_ROTEIRO" into v_roteiro from public."TB_ENTREVISTA_EDITAL" where "CO_MONITORAMENTO" = p_edital;
  if v_roteiro is null then raise exception 'Configure a entrevista do edital antes de convocar' using errcode = '23514'; end if;
  if coalesce(cardinality(p_analises), 0) not between 1 and 2000 then raise exception 'Escolha de 1 a 2000 candidatos' using errcode = '22023'; end if;

  -- Uma convocação por vez no edital; a tela tem de estar na lista vigente.
  perform pg_advisory_xact_lock(hashtextextended('convocacao_entrevista:' || p_edital::text, 0));
  v_vigente := private."FC_LISTA_CONVOCACAO_VIGENTE"(p_edital);
  if v_vigente is null then
    raise exception 'Gere a lista de convocação na Classificação antes de convocar' using errcode = '23514';
  end if;
  if p_lista is distinct from v_vigente then
    raise exception 'A lista de convocação mudou na Classificação; recarregue' using errcode = 'PT409';
  end if;
  select count(*) into v_fora
    from (select distinct x.analise from unnest(p_analises) x(analise)) s
   where s.analise is null
      or not exists (select 1 from private."FC_CONVOCADOS_DA_LISTA"(v_vigente) c(analise) where c.analise = s.analise);
  if v_fora > 0 then
    raise exception '% candidato(s) fora da lista de convocação vigente da Classificação', v_fora using errcode = '23514';
  end if;

  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital;
  insert into public."TB_ENTREVISTA" as e ("CO_AREA", "CO_MONITORAMENTO", "CO_ANALISE_CURRICULAR", "TP_LIGACAO_ANALISE",
    "NO_UNIDADE", "DS_EDITAL", "CO_VAGA", "NO_CANDIDATO", "CO_CANDIDATO", "DS_MODALIDADE", "NO_CARGO", "TP_PARECER",
    "TP_ORIGEM", "DS_CHAVE_ORIGEM", "CO_ROTEIRO", "ST_ATIVO")
  select v_area, p_edital, a.id, 'codigo', left(coalesce(v_m.unidade, ''), 200), left(v_m.edital, 120), left(a.codigo_vaga, 60),
         left(a.candidato, 200), left(a.id_origem, 60), left(a.modalidade_concorrencia, 300), left(a.nome_vaga, 400), 'SEM_PARECER',
         'sistema', 'sistema|' || p_edital || '|' || a.id, v_roteiro, 'S'
    from public."TB_ANALISE_CURRICULAR" a
   where a.id = any (p_analises) and a."CO_AREA" = v_area
     and private."FC_NUMERO_EDITAL"(a.edital) = private."FC_NUMERO_EDITAL"(v_m.edital)
  on conflict ("DS_CHAVE_ORIGEM") do update set "ST_ATIVO" = 'S', "CO_ROTEIRO" = excluded."CO_ROTEIRO", "DT_ATUALIZACAO" = now();
  get diagnostics v_qt = row_count;

  insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "DS_CAMPO", "DS_VALOR_NOVO", "CO_USUARIO")
  select e."CO_ENTREVISTA", 'convocacao', 'convocado pela lista ' || v_vigente, (select auth.uid())
    from public."TB_ENTREVISTA" e where e."DS_CHAVE_ORIGEM" = any (select 'sistema|' || p_edital || '|' || x from unnest(p_analises) x);

  -- A linha da planilha da mesma análise não fica ativa ao lado da do sistema (20261022200000).
  perform private."FC_DESATIVAR_ENTREVISTAS_REPETIDAS"(v_area, p_edital, (select auth.uid()));

  return json_build_object('convocados', v_qt, 'lista', v_vigente, 'dados', public.obter_entrevistas_do_edital(p_edital));
end;
$$;

--
-- Name: FUNCTION convocar_para_entrevista(p_edital uuid, p_lista uuid, p_analises uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.convocar_para_entrevista(p_edital uuid, p_lista uuid, p_analises uuid[]) IS 'Registra para a ficha de notas (TB_ENTREVISTA, TP_ORIGEM sistema) convocados da lista de convocação vigente da Classificação (p_lista = a última CONVOCACAO gerada, senão 40001); candidato fora da lista ou sem lista gerada = 23514; sem configuração = 23514. Idempotente; nada é apagado. entrevistas >= editor e o edital.';

--
-- Name: copiar_modelo_regra_analise(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copiar_modelo_regra_analise(p_edital uuid, p_modelo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_modelo public."TB_REGRA_ANALISE_MODELO";
  v_config jsonb;
  v_numero text;
  v_regra uuid;
  v_uid uuid := (select auth.uid());
begin
  select * into v_modelo from public."TB_REGRA_ANALISE_MODELO" where "CO_MODELO" = p_modelo and "ST_ATIVO" = 'S';
  if v_modelo."CO_MODELO" is null then
    raise exception 'Modelo não encontrado' using errcode = '22023';
  end if;
  if exists (select 1 from public."TB_REGRA_ANALISE" where "CO_MONITORAMENTO" = p_edital) then
    raise exception 'O edital já tem regra: carregue o modelo no formulário e salve uma versão nova com o motivo.' using errcode = '23505';
  end if;
  -- O rótulo do parecer: o número do edital ("Edital 93/2026") ou, sem número, o nome cadastrado.
  select coalesce(private."FC_NUMERO_EDITAL"(m.edital), nullif(left(btrim(m.edital), 100), ''))
    into v_numero from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  v_config := v_modelo."DS_CONFIGURACAO" || jsonb_build_object('modelo', v_modelo."CO_MODELO");
  if coalesce(btrim(v_config ->> 'edital_rotulo'), '') = '' and v_numero is not null then
    v_config := v_config || jsonb_build_object('edital_rotulo', 'Edital ' || v_numero);
  end if;
  perform private."FC_VALIDAR_REGRA_ANALISE"(v_config);

  insert into public."TB_REGRA_ANALISE" ("CO_MONITORAMENTO", "NU_VERSAO_VIGENTE", "CO_MODELO_ORIGEM", "CO_USUARIO_ATUALIZACAO")
  values (p_edital, 1, v_modelo."CO_MODELO", v_uid)
  returning "CO_REGRA_ANALISE" into v_regra;
  insert into public."TH_REGRA_ANALISE" ("CO_REGRA_ANALISE", "NU_VERSAO", "DS_CONFIGURACAO", "DS_HASH", "DS_MOTIVO", "CO_USUARIO")
  values (v_regra, 1, v_config, encode(sha256(convert_to(v_config::text, 'UTF8')), 'hex'),
          'Copiada do modelo ' || v_modelo."CO_MODELO", v_uid);

  return json_build_object('regra', private."FC_REGRA_ANALISE_JSON"(p_edital), 'fichas_afetadas', '[]'::json);
end;
$$;

--
-- Name: FUNCTION copiar_modelo_regra_analise(p_edital uuid, p_modelo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.copiar_modelo_regra_analise(p_edital uuid, p_modelo text) IS 'Cria a versão 1 da regra do edital copiando um modelo (situação Conferir; o rótulo do edital vem do número quando o modelo não traz). Edital que já tem regra: 23505 (carregue o modelo no formulário e salve uma versão). Só a coordenação do edital.';

--
-- Name: corrigir_experiencia_da_ficha(uuid, integer, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.corrigir_experiencia_da_ficha(p_ficha uuid, p_versao integer, p_experiencia jsonb, p_motivo text, p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_cargo text;
  v_lanc jsonb;
  v_exp jsonb;
  v_novo jsonb;
  v_motivo text := btrim(coalesce(p_motivo, ''));
begin
  if length(v_motivo) not between 10 and 2000 then
    raise exception 'Motivo da correção com 10 a 2.000 caracteres.' using errcode = '22023';
  end if;
  if not exists (select 1 from public."TB_PERFIL_USUARIO" u where u.user_id = p_usuario) then
    raise exception 'Quem assina a correção não tem cadastro.' using errcode = '22023';
  end if;
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha for update;
  if v_f."CO_FICHA_ANALISE" is null or v_f."TP_SITUACAO" <> 'CONCLUIDA' then
    raise exception 'Só a ficha concluída tem a experiência corrigida.' using errcode = '22023';
  end if;
  if v_f."NU_VERSAO" is distinct from p_versao then
    raise exception 'A ficha mudou desde a leitura; rode de novo.' using errcode = 'PT409';
  end if;
  v_cargo := (select pv."NO_CARGO" from public."TB_PRE_CLASSIF_VAGA" pv
               where pv."CO_MONITORAMENTO" = v_f."CO_MONITORAMENTO" and pv."CO_VAGA" = v_f."CO_VAGA");
  v_lanc := v_f."DS_LANCAMENTO" || jsonb_build_object('vaga', v_f."CO_VAGA", 'cargo', v_cargo);
  select private."FC_EXPERIENCIA_DA_FICHA"(x.b, v_lanc) into v_exp
    from private."FC_REGRA_VIGENTE_FICHA"(p_ficha) r
    cross join lateral jsonb_array_elements(
      private."FC_REGRA_DA_VAGA"(r.p_configuracao, v_f."CO_VAGA", v_cargo, v_lanc ->> 'nivel') -> 'blocos')
      with ordinality x(b, n)
   where x.b ->> 'tipo' = 'VINCULOS'
   order by x.n desc limit 1;
  if v_exp is null then
    raise exception 'A regra da ficha não tem bloco de vínculos.' using errcode = '22023';
  end if;
  if jsonb_typeof(p_experiencia) is distinct from 'object'
     or (p_experiencia -> 'dias_total') is distinct from (v_exp -> 'dias_total')
     or (p_experiencia -> 'meses') is distinct from (v_exp -> 'meses')
     or (p_experiencia -> 'meses_considerados') is distinct from (v_exp -> 'meses_considerados') then
    raise exception 'A experiência enviada (% dias) não é a que o banco calcula (% dias).',
      p_experiencia ->> 'dias_total', v_exp ->> 'dias_total' using errcode = '22023';
  end if;
  if (v_f."DS_RESULTADO" #> '{calculados,EXPERIENCIA}') is distinct from (v_exp -> 'pontos') then
    raise exception 'Com a experiência corrigida a pontuação mudaria (% → %): a ficha vai para revisão, não para correção.',
      v_f."DS_RESULTADO" #>> '{calculados,EXPERIENCIA}', v_exp ->> 'pontos' using errcode = '22023';
  end if;
  v_novo := v_f."DS_RESULTADO" || jsonb_build_object('experiencia', coalesce(v_f."DS_RESULTADO" -> 'experiencia', '{}'::jsonb)
    || jsonb_build_object('dias_total', v_exp -> 'dias_total', 'meses', v_exp -> 'meses',
                          'meses_considerados', v_exp -> 'meses_considerados', 'por_categoria', v_exp -> 'por_categoria'));
  update public."TB_FICHA_ANALISE" set
    "DS_RESULTADO" = v_novo, "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
   where "CO_FICHA_ANALISE" = p_ficha;
  perform private."FC_HISTORICO_CONTEUDO_FICHA"(p_ficha, 'CORRIGIR', 'CONCLUIDA', v_motivo, p_usuario,
    jsonb_build_array(jsonb_build_object('campo', 'experiencia_dias', 'rotulo', 'Experiência (dias)',
      'de', v_f."DS_RESULTADO" #> '{experiencia,dias_total}', 'para', v_exp -> 'dias_total')),
    jsonb_build_object('resultado', v_novo));
  -- O painel (experiencia_profissional_total): a publicação só roda sozinha quando muda a nota ou a situação.
  perform private."FC_PUBLICAR_FICHA_ANALISE"(p_ficha);
  return jsonb_build_object('versao', v_f."NU_VERSAO" + 1,
                            'dias_antes', v_f."DS_RESULTADO" #> '{experiencia,dias_total}', 'dias_depois', v_exp -> 'dias_total');
end;
$$;

--
-- Name: FUNCTION corrigir_experiencia_da_ficha(p_ficha uuid, p_versao integer, p_experiencia jsonb, p_motivo text, p_usuario uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.corrigir_experiencia_da_ficha(p_ficha uuid, p_versao integer, p_experiencia jsonb, p_motivo text, p_usuario uuid) IS 'Correção de dados (service_role): troca só DS_RESULTADO.experiencia da ficha CONCLUIDA pela que o banco calcula (a enviada precisa bater), se a pontuação não muda; histórico CORRIGIR assinado por p_usuario e republicação no painel.';

--
-- Name: corrigir_posicao_da_pendencia(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.corrigir_posicao_da_pendencia(p_pendencia uuid, p_candidato uuid, p_posicao integer, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_PENDENCIA_APROVADO"%rowtype;
  v_antes integer;
  v_resolve boolean;
begin
  v := private."FC_PENDENCIA_PARA_DECIDIR"(p_pendencia, array['POSICAO_REPETIDA'], p_motivo);
  if p_posicao is null or p_posicao not between 1 and 100000 then
    raise exception 'Posição inválida (1 a 100000)' using errcode = '22023';
  end if;
  select c.classificacao into v_antes from public."TB_CANDIDATO_APROVADO" c
   where c.id = p_candidato and c.id = any (v."CO_CANDIDATO_APROVADO") for update;
  if not found then
    raise exception 'Escolha uma das linhas da pendência' using errcode = '22023';
  end if;
  if v_antes is not distinct from p_posicao then
    raise exception 'A posição nova é igual à atual' using errcode = '22023';
  end if;
  update public."TB_CANDIDATO_APROVADO"
     set classificacao = p_posicao, updated_by = (select auth.uid()), updated_at = now()
   where id = p_candidato;
  -- Resolve quando as linhas da pendência deixam de dividir a posição; senão fica a correção registrada.
  select count(distinct c.classificacao) = count(*) into v_resolve
    from public."TB_CANDIDATO_APROVADO" c
   where c.id = any (v."CO_CANDIDATO_APROVADO") and c.removido_em is null;
  return private."FC_FECHAR_PENDENCIA"(
    p_pendencia, 'POSICAO_CORRIGIDA', p_motivo,
    jsonb_build_array(jsonb_build_object('candidato', p_candidato, 'campo', 'posicao', 'antes', v_antes, 'depois', p_posicao)),
    v_resolve);
end;
$$;

--
-- Name: FUNCTION corrigir_posicao_da_pendencia(p_pendencia uuid, p_candidato uuid, p_posicao integer, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.corrigir_posicao_da_pendencia(p_pendencia uuid, p_candidato uuid, p_posicao integer, p_motivo text) IS 'Pendência "Posição repetida": corrige a posição (classificação) de uma das linhas, com o antes e o depois no histórico; resolve quando as linhas deixam de dividir a posição. Quem decide (FC_PODE_DECIDIR_PENDENCIA), com motivo. 20261026190000.';

