--
-- Name: definir_lista_aprovados_ativa(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.definir_lista_aprovados_ativa(p_lista_id uuid, p_ativo boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_edital_id text;
  v_vencimento date;
begin
  -- Admin global passa; os outros, pela matriz de Acessos (Importação nível 2) e pela área.
  if not private."FC_ADMIN_GLOBAL_ATIVO"((select auth.uid())) then
    perform private."FC_EXIGIR_AREA_EDITAL"((select l.edital_id from public."TB_LISTA_APROVADO" l where l.id = p_lista_id));
    if not private.pode_recurso('importacao', 2) then
      raise exception 'Sem permissão para este recurso' using errcode = '42501';
    end if;
  end if;

  if coalesce(p_ativo, false) then
    select private."FC_VENCIMENTO_DO_EDITAL"(m.data_fim::date, m."NU_ANOS_VALIDADE",
                                             m."NU_MESES_VALIDADE", m."ST_PRORROGADO")
      into v_vencimento
      from public."TB_LISTA_APROVADO" l
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
     where l.id = p_lista_id;
    if v_vencimento < (now() at time zone 'America/Sao_Paulo')::date then
      raise exception 'O prazo de validade do processo seletivo venceu em %. Prorrogue o edital para reativar a lista.',
        to_char(v_vencimento, 'DD/MM/YYYY') using errcode = '22023';
    end if;
  end if;

  update public."TB_LISTA_APROVADO"
  set ativo = coalesce(p_ativo, false), updated_at = now()
  where id = p_lista_id and vigente is true
  returning edital_id into v_edital_id;
  if not found then raise exception 'Lista vigente nao encontrada'; end if;
  perform private."FC_ATUALIZAR_CONTRATADOS_DO_EDITAL"(v_edital_id::uuid);
  return jsonb_build_object('ok', true, 'lista_id', p_lista_id, 'edital_id', v_edital_id, 'ativo', coalesce(p_ativo, false));
end;
$$;

--
-- Name: definir_modelo_carta_ativo(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.definir_modelo_carta_ativo(p_modelo uuid, p_ativo boolean, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_modelo public."TB_MODELO_CARTA_CONVOCACAO";
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
begin
  if not private.pode_recurso('aprovados', 2) then
    raise exception 'Sem permissão para editar os modelos da carta' using errcode = '42501';
  end if;
  if p_ativo is null then
    raise exception 'Informe se o modelo fica ativo.' using errcode = '22023';
  end if;
  if v_motivo is null or length(v_motivo) not between 3 and 500 then
    raise exception 'Informe o motivo (3 a 500 caracteres).' using errcode = '22023';
  end if;
  select * into v_modelo from public."TB_MODELO_CARTA_CONVOCACAO"
   where "CO_MODELO_CARTA" = p_modelo for update;
  if v_modelo."CO_MODELO_CARTA" is null then
    raise exception 'Modelo não encontrado' using errcode = '22023';
  end if;
  if not (v_modelo."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])) then
    raise exception 'Sem permissão para esta área' using errcode = '42501';
  end if;
  perform private."FC_EXIGIR_AREA_EDITAL"(v_modelo."CO_MONITORAMENTO"::text);
  if v_modelo."ST_ATIVO" = p_ativo then
    return json_build_object('modelo_id', v_modelo."CO_MODELO_CARTA", 'ativo', p_ativo, 'mudou', false);
  end if;
  if p_ativo and exists (select 1 from public."TB_MODELO_CARTA_CONVOCACAO" t
                          where t."ST_ATIVO" and t."CO_MODELO_CARTA" <> v_modelo."CO_MODELO_CARTA"
                            and t."CO_AREA" = v_modelo."CO_AREA"
                            and t."CO_MONITORAMENTO" is not distinct from v_modelo."CO_MONITORAMENTO"
                            and lower(btrim(t."NO_MODELO")) = lower(btrim(v_modelo."NO_MODELO"))) then
    raise exception 'Já existe um modelo ativo com este nome.' using errcode = '23505';
  end if;
  update public."TB_MODELO_CARTA_CONVOCACAO"
     set "ST_ATIVO" = p_ativo, "DS_MOTIVO_SITUACAO" = v_motivo,
         "CO_USUARIO_ATUALIZACAO" = (select auth.uid()), "DT_ATUALIZACAO" = now()
   where "CO_MODELO_CARTA" = v_modelo."CO_MODELO_CARTA";
  return json_build_object('modelo_id', v_modelo."CO_MODELO_CARTA", 'ativo', p_ativo, 'mudou', true);
end;
$$;

--
-- Name: FUNCTION definir_modelo_carta_ativo(p_modelo uuid, p_ativo boolean, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.definir_modelo_carta_ativo(p_modelo uuid, p_ativo boolean, p_motivo text) IS 'Inativa ou reativa um modelo da carta de convocação, com motivo (3 a 500); nada se apaga e as cartas emitidas continuam no histórico. Aprovados >= editor e a área (e o recorte do edital).';

--
-- Name: definir_origem_analise(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.definir_origem_analise(p_edital uuid, p_origem text, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  return private."FC_DEFINIR_ORIGEM_ANALISE"(p_edital, p_origem, p_motivo, (select auth.uid()));
end;
$$;

--
-- Name: FUNCTION definir_origem_analise(p_edital uuid, p_origem text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.definir_origem_analise(p_edital uuid, p_origem text, p_motivo text) IS 'A coordenação da avaliação do edital (gestor, coordenador da equipe ou admin global; 42501) troca o dono da avaliação documental: MONITORA (as fichas alimentam o Painel das análises e a Classificação) ou PLANILHA, com motivo de 10 a 2.000 e histórico (FC_DEFINIR_ORIGEM_ANALISE).';

--
-- Name: definir_previsao_entrevista_edital(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.definir_previsao_entrevista_edital(p_edital uuid, p_situacao text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_antes text;
  v_motivo text:=btrim(coalesce(p_motivo,''));
  v_entrevistados integer;
begin
  if not private.is_master() then
    raise exception 'Apenas administrador global pode confirmar a etapa de entrevista' using errcode='42501';
  end if;
  if p_edital is null or p_situacao is null or
     p_situacao not in ('PREVISTA','NAO_PREVISTA','NAO_INFORMADA') then
    raise exception 'Edital ou situação inválidos' using errcode='22023';
  end if;
  if char_length(v_motivo) < 5 or char_length(v_motivo) > 500 then
    raise exception 'Justificativa obrigatória entre 5 e 500 caracteres' using errcode='22023';
  end if;
  select coalesce(m.entrevistados,0) into v_entrevistados
    from public."TB_MONITORAMENTO_INDIGENA" m where m.id=p_edital for update;
  if not found then raise exception 'Edital não encontrado' using errcode='22023'; end if;
  if p_situacao='NAO_PREVISTA' and (
      v_entrevistados>0
      or exists(select 1 from public."TB_ENTREVISTA" e where e."CO_MONITORAMENTO"=p_edital)
      or exists(select 1 from public."TB_ENTREVISTA_EDITAL" x where x."CO_MONITORAMENTO"=p_edital)
     ) then
    raise exception 'Edital possui entrevistas registradas ou configuração: não pode ser marcado como não previsto'
       using errcode='23514';
  end if;
  select x."TP_PREVISAO" into v_antes
    from public."TB_PREVISAO_ENTREVISTA_EDITAL" x where x."CO_MONITORAMENTO"=p_edital for update;
  v_antes:=coalesce(v_antes,'NAO_INFORMADA');
  if v_antes=p_situacao then
    raise exception 'Situação já registrada; nenhuma alteração necessária' using errcode='22023';
  end if;
  insert into public."TB_PREVISAO_ENTREVISTA_EDITAL"
    ("CO_MONITORAMENTO","TP_PREVISAO","DS_MOTIVO","CO_USUARIO")
  values (p_edital,p_situacao,v_motivo,auth.uid())
  on conflict ("CO_MONITORAMENTO") do update
     set "TP_PREVISAO"=excluded."TP_PREVISAO",
         "DS_MOTIVO"=excluded."DS_MOTIVO",
         "CO_USUARIO"=excluded."CO_USUARIO",
         "DT_ATUALIZACAO"=now();
  insert into public."TH_PREVISAO_ENTREVISTA_EDITAL"
    ("CO_MONITORAMENTO","TP_ANTES","TP_DEPOIS","DS_MOTIVO","CO_USUARIO")
  values (p_edital,v_antes,p_situacao,v_motivo,auth.uid());
  return jsonb_build_object('situacao',p_situacao,'motivo',v_motivo,'pode_alterar',true);
end;
$$;

--
-- Name: desativar_acesso_usuario(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desativar_acesso_usuario(p_perfil_usuario_id uuid, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
declare
  v_email text;
  v_nome text;
  v_paineis integer := 0;
begin
  if auth.uid() is null then raise exception 'Usuario nao autenticado'; end if;
  if not private.is_master() then raise exception 'Somente perfil master pode desativar acesso'; end if;
  if p_perfil_usuario_id is null then raise exception 'Perfil de usuario nao informado'; end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then
    raise exception 'Informe o motivo da desativação (3 a 500 caracteres)' using errcode = '22023';
  end if;

  update public."TB_PERFIL_USUARIO"
     set ativo = false, p_ind = false, p_cores = false, p_paineis = false,
         p_config = false, p_admin = false, updated_at = now()
   where id = p_perfil_usuario_id
     and ativo
     and coalesce(user_id, '00000000-0000-0000-0000-000000000000'::uuid) <> auth.uid()
  returning email, nome into v_email, v_nome;
  if not found then
    raise exception 'Perfil de usuario nao encontrado, ja desativado ou tentativa de auto-desativacao';
  end if;

  update public."RL_PERFIL_USUARIO_PAINEL_EXT"
     set ativo = false, updated_at = now()
   where perfil_usuario_id = p_perfil_usuario_id and ativo is true;
  get diagnostics v_paineis = row_count;

  insert into public."TH_PERMISSAO_RECURSO"(perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
  values (p_perfil_usuario_id, '#conta', 'ativa', 'desativada', auth.uid(), btrim(p_motivo));

  return jsonb_build_object('ok', true, 'perfil_usuario_id', p_perfil_usuario_id, 'email', v_email,
    'nome', v_nome, 'paineis_revogados', v_paineis, 'motivo', btrim(p_motivo));
end;
$$;

--
-- Name: FUNCTION desativar_acesso_usuario(p_perfil_usuario_id uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.desativar_acesso_usuario(p_perfil_usuario_id uuid, p_motivo text) IS 'Desativa acesso do usuario no AgSUS Monitora sem apagar auth.users nem historico. Remove permissoes internas e paineis externos.';

--
-- Name: desativar_coordenacao(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desativar_coordenacao(p_codigo text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_antes jsonb;
begin
  if not private.is_master() then raise exception 'Somente administradores gerenciam coordenações' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then raise exception 'Informe um motivo entre 3 e 500 caracteres'; end if;
  v_antes := private."FC_COORDENACAO_JSON"(p_codigo);
  if v_antes is null then raise exception 'Coordenação não encontrada'; end if;
  if exists (select 1 from public."TB_PERFIL_USUARIO" u where u."CO_COORDENACAO" = p_codigo and u.ativo) then
    raise exception 'Há usuários nesta coordenação. Mude-os de coordenação antes de desativar.';
  end if;
  update public."TB_COORDENACAO" set "ST_ATIVO" = false, "NU_REVISAO" = "NU_REVISAO" + 1, "DT_ATUALIZACAO" = now()
   where "CO_COORDENACAO" = p_codigo;
  insert into public."TH_COORDENACAO" ("CO_COORDENACAO", "JS_ANTES", "JS_DEPOIS", "CO_ALTERADO_POR", "DS_MOTIVO")
  values (p_codigo, v_antes, private."FC_COORDENACAO_JSON"(p_codigo), (select auth.uid()), btrim(p_motivo));
  return private."FC_COORDENACAO_JSON"(p_codigo);
end;
$$;

--
-- Name: descartar_rascunho_regra(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.descartar_rascunho_regra(p_tipo text, p_edital uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_apagados integer;
begin
  if v_uid is null then
    raise exception 'Sessão expirada' using errcode = '42501';
  end if;
  if p_tipo is null or p_tipo not in ('ANALISE', 'CLASSIFICACAO') then
    raise exception 'Tipo de regra inválido' using errcode = '22023';
  end if;
  delete from public."TB_RASCUNHO_REGRA"
   where "TP_REGRA" = p_tipo and "CO_MONITORAMENTO" = p_edital and "CO_USUARIO" = v_uid;
  get diagnostics v_apagados = row_count;
  return json_build_object('descartado', v_apagados > 0);
end;
$$;

--
-- Name: FUNCTION descartar_rascunho_regra(p_tipo text, p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.descartar_rascunho_regra(p_tipo text, p_edital uuid) IS 'Apaga o rascunho não salvo de quem chama para a regra do tipo no edital (depois de salvar a versão nova ou ao descartar). Só o próprio rascunho; não exige a permissão de editar.';

--
-- Name: descongelar_declarada_pre_classificacao(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.descongelar_declarada_pre_classificacao(p_edital uuid, p_motivo text, p_vaga text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_motivo text := btrim(coalesce(p_motivo, ''));
  v_qt integer;
begin
  perform private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  if length(v_motivo) not between 10 and 250 then
    raise exception 'Diga o motivo (de 10 a 250 caracteres).' using errcode = '22023';
  end if;
  if p_vaga is not null and not exists (select 1 from public."TB_EMPREGARE_VAGA" v
                                         where v."CO_VAGA" = p_vaga and v."CO_MONITORAMENTO" = p_edital) then
    raise exception 'A vaga % não é do edital', p_vaga using errcode = '22023';
  end if;
  if exists (select 1 from public."TL_PRE_CLASSIFICACAO" t
              where t."TP_SITUACAO" = 'EM_ANDAMENTO' and t."DT_INICIO" > now() - interval '1 hour') then
    raise exception 'Há uma pré-classificação rodando: descongele quando ela terminar.' using errcode = '55P03';
  end if;

  -- O histórico primeiro (a situação e o lote de agora, com o motivo e quem pediu).
  insert into public."TH_PRE_CLASSIFICACAO"
    ("CO_EXECUCAO", "CO_USUARIO", "CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO", "CO_VAGA", "TP_SITUACAO_ANTERIOR",
     "TP_SITUACAO", "NU_LOTE_ANTERIOR", "NU_LOTE", "NU_POSICAO", "DS_MOTIVO")
  select null, (select auth.uid()), a."CO_MONITORAMENTO", a."CO_EMPREGARE_CANDIDATO", a."CO_VAGA", a."TP_SITUACAO",
         a."TP_SITUACAO", a."NU_LOTE", a."NU_LOTE", a."NU_POSICAO",
         left('Nota declarada descongelada (era ' || trim_scale(a."VL_DECLARADA_CONGELADA") || '): ' || v_motivo, 300)
    from public."TB_PRE_CLASSIFICACAO" a
   where a."CO_MONITORAMENTO" = p_edital and a."VL_DECLARADA_CONGELADA" is not null
     and (p_vaga is null or a."CO_VAGA" = p_vaga);
  get diagnostics v_qt = row_count;

  update public."TB_PRE_CLASSIFICACAO" a set
    "VL_DECLARADA_CONGELADA" = null, "DS_DECLARADA_CONGELADA" = null, "DT_CONGELAMENTO_DECLARADA" = null,
    "DT_ATUALIZACAO" = now()
   where a."CO_MONITORAMENTO" = p_edital and a."VL_DECLARADA_CONGELADA" is not null
     and (p_vaga is null or a."CO_VAGA" = p_vaga);

  return json_build_object('descongeladas', v_qt);
end;
$$;

--
-- Name: FUNCTION descongelar_declarada_pre_classificacao(p_edital uuid, p_motivo text, p_vaga text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.descongelar_declarada_pre_classificacao(p_edital uuid, p_motivo text, p_vaga text) IS 'Descongela a nota declarada dos inscritos do edital (ou de uma vaga): apaga o valor congelado e grava no histórico (TH_PRE_CLASSIFICACAO, com o usuário e o motivo, de 10 a 250 caracteres) o valor que era; o próximo recálculo usa as respostas de agora e congela de novo. Só a coordenação da avaliação do edital (FC_EXIGIR_COORD_AVALIACAO); recusa (55P03) com pré-classificação rodando. Devolve quantos foram descongelados.';

--
-- Name: desconvocar_da_entrevista(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desconvocar_da_entrevista(p_entrevista uuid, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_edital uuid;
begin
  select "CO_MONITORAMENTO" into v_edital from public."TB_ENTREVISTA" where "CO_ENTREVISTA" = p_entrevista and "TP_ORIGEM" = 'sistema';
  if v_edital is null then raise exception 'Convocação não encontrada' using errcode = '22023'; end if;
  perform private."FC_EXIGIR_ENTREVISTAS_EDITAL"(v_edital, 2);
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then raise exception 'Informe o motivo (3 a 500 caracteres)' using errcode = '22023'; end if;
  if exists (select 1 from public."TB_ENTREVISTA_AVALIACAO" x where x."CO_ENTREVISTA" = p_entrevista) then
    raise exception 'Este candidato já tem notas lançadas; não pode ser desconvocado' using errcode = '23514';
  end if;
  update public."TB_ENTREVISTA" set "ST_ATIVO" = 'N', "DT_ATUALIZACAO" = now() where "CO_ENTREVISTA" = p_entrevista;
  insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "DS_CAMPO", "DS_VALOR_NOVO", "CO_USUARIO")
  values (p_entrevista, 'desconvocacao', btrim(p_motivo), (select auth.uid()));
  return public.obter_entrevistas_do_edital(v_edital);
end;
$$;

--
-- Name: FUNCTION desconvocar_da_entrevista(p_entrevista uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.desconvocar_da_entrevista(p_entrevista uuid, p_motivo text) IS 'Retira um convocado sem notas (exclusão lógica, com motivo). entrevistas >= editor.';

--
-- Name: desfazer_alteracao_sub_judice(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desfazer_alteracao_sub_judice(p_candidato_id uuid, p_observacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_CANDIDATO_APROVADO"%rowtype;
  v_ativo boolean;
  v_posicao integer;
begin
  perform private."FC_EXIGIR_AREA_EDITAL"((select l.edital_id from public."TB_CANDIDATO_APROVADO" c join public."TB_LISTA_APROVADO" l on l.id = c.lista_id where c.id = p_candidato_id));
  if not (private.pode_recurso('aprovados', 3)) then
    raise exception 'Só o administrador da lista de aprovados desfaz a alteração judicial' using errcode = '42501';
  end if;
  if length(coalesce(p_observacao, '')) > 1000 then
    raise exception 'Observação com mais de 1000 caracteres' using errcode = '22023';
  end if;

  select c.* into v
    from public."TB_CANDIDATO_APROVADO" c
    join public."TB_LISTA_APROVADO" l on l.id = c.lista_id and l.vigente is true
   where c.id = p_candidato_id and c.removido_em is null and c.alterado_judicialmente is true
     for update of c, l;
  if not found then raise exception 'Candidato com alteração judicial nao encontrado'; end if;
  select l.ativo into v_ativo from public."TB_LISTA_APROVADO" l where l.id = v.lista_id;
  if not v_ativo then raise exception 'A lista esta inativa e nao permite alterar candidato'; end if;

  -- Volta à nota, modalidade e posição do resultado publicado; depois recoloca.
  update public."TB_CANDIDATO_APROVADO" c set
    nota = c.nota_original,
    modalidade = c.modalidade_original,
    classificacao = coalesce(c.classificacao_original, c.classificacao),
    sub_judice = coalesce(c.sub_judice_original, false),
    alterado_judicialmente = false,
    updated_by = (select auth.uid()),
    updated_at = now()
   where c.id = p_candidato_id;

  v_posicao := private."FC_RECOLOCAR_NA_CLASSIFICACAO"(p_candidato_id, v.modalidade);

  update public."TB_CANDIDATO_APROVADO" c set
    nota_original = null, modalidade_original = null,
    classificacao_original = null, sub_judice_original = null
   where c.id = p_candidato_id;

  insert into public."TH_CANDIDATO_SUB_JUDICE" (
    "CO_CANDIDATO", "CO_LISTA", "TP_EVENTO", "VL_NOTA_ANTERIOR", "VL_NOTA_NOVA",
    "DS_MODALIDADE_ANTERIOR", "DS_MODALIDADE_NOVA", "NU_CLASSIFICACAO_ANTERIOR", "NU_CLASSIFICACAO_NOVA",
    "DS_OBSERVACAO", "CO_USUARIO"
  ) values (
    p_candidato_id, v.lista_id, 'DESFAZER', v.nota, v.nota_original, v.modalidade, v.modalidade_original,
    v.classificacao, v_posicao, nullif(btrim(coalesce(p_observacao, '')), ''), (select auth.uid())
  );

  return jsonb_build_object('ok', true, 'candidato_id', p_candidato_id, 'lista_id', v.lista_id,
                            'nota', v.nota_original, 'modalidade', v.modalidade_original, 'classificacao', v_posicao);
end;
$$;

--
-- Name: FUNCTION desfazer_alteracao_sub_judice(p_candidato_id uuid, p_observacao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.desfazer_alteracao_sub_judice(p_candidato_id uuid, p_observacao text) IS 'Desfaz a alteração judicial: volta à nota, modalidade e classificação do resultado publicado, recoloca na classificação e grava o histórico. Só aprovados = administrador e a área do edital.';

--
-- Name: desfazer_coordenada_mapa_projetos(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desfazer_coordenada_mapa_projetos(p_historico bigint, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v private."TH_COORDENADA_LOCAL_VAGA"%rowtype;
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode corrigir coordenadas.';
  end if;
  select h.* into v from private."TH_COORDENADA_LOCAL_VAGA" h
   where h."CO_SEQ_HISTORICO" = p_historico for update;
  if not found then
    raise exception using errcode = '22023', message = 'Correção não encontrada.';
  end if;
  if v."TP_ACAO" = 'DESFAZER' then
    raise exception using errcode = '22023', message = 'Um desfazer não se desfaz; corrija a posição.';
  end if;
  if exists (select 1 from private."TH_COORDENADA_LOCAL_VAGA" h
              where h."DS_CHAVE_LUGAR" = v."DS_CHAVE_LUGAR"
                and h."CO_SEQ_HISTORICO" > v."CO_SEQ_HISTORICO") then
    raise exception using errcode = 'PT409', message = 'Só a última correção do lugar pode ser desfeita. Atualize o mapa.';
  end if;
  if v."CG_LATITUDE_ANTERIOR" is null or v."CG_LONGITUDE_ANTERIOR" is null then
    raise exception using errcode = '22023', message = 'O lugar não tinha coordenada antes; corrija a posição.';
  end if;
  return private."FC_APLICAR_COORDENADA_LOCAL"(
    v."DS_CHAVE_LUGAR", v."CG_LATITUDE_ANTERIOR", v."CG_LONGITUDE_ANTERIOR", v."CG_LATITUDE", v."CG_LONGITUDE",
    p_motivo, 'DESFAZER', v."ST_CONFERIDO_ANTERIOR", v."CO_SEQ_HISTORICO");
end;
$$;

--
-- Name: FUNCTION desfazer_coordenada_mapa_projetos(p_historico bigint, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.desfazer_coordenada_mapa_projetos(p_historico bigint, p_motivo text) IS 'Volta a última alteração de um lugar do mapa de Projetos (posição e conferência) como uma alteração nova, com motivo; nada do histórico é apagado. Só administrador global ou gestor.';

--
-- Name: desfazer_coordenada_mapa_saude_indigena(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desfazer_coordenada_mapa_saude_indigena(p_historico bigint, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v private."TH_COORDENADA_MAPA_SAUDE_INDIG"%rowtype;
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode corrigir coordenadas.';
  end if;
  select h.* into v from private."TH_COORDENADA_MAPA_SAUDE_INDIG" h
   where h."CO_SEQ_HISTORICO" = p_historico for update;
  if not found then
    raise exception using errcode = '22023', message = 'Correção não encontrada.';
  end if;
  if v."TP_ACAO" = 'DESFAZER' then
    raise exception using errcode = '22023', message = 'Um desfazer não se desfaz; corrija a posição.';
  end if;
  if exists (select 1 from private."TH_COORDENADA_MAPA_SAUDE_INDIG" h
              where h."CO_SEQ_HISTORICO" > v."CO_SEQ_HISTORICO"
                and private."FC_CHAVE_ALVO_COORDENADA"(h."DS_ALVO") = private."FC_CHAVE_ALVO_COORDENADA"(v."DS_ALVO")) then
    raise exception using errcode = 'PT409', message = 'Só a última correção do ponto pode ser desfeita. Atualize o mapa.';
  end if;
  if v."CG_LATITUDE_ANTERIOR" is null or v."CG_LONGITUDE_ANTERIOR" is null then
    raise exception using errcode = '22023', message = 'O ponto não tinha coordenada antes; corrija a posição.';
  end if;
  return private."FC_APLICAR_COORDENADA_MAPA"(
    v."DS_ALVO", v."CG_LATITUDE_ANTERIOR", v."CG_LONGITUDE_ANTERIOR", v."CG_LATITUDE", v."CG_LONGITUDE",
    p_motivo, 'DESFAZER', v."ST_CONFERIDO_ANTERIOR", v."CO_SEQ_HISTORICO");
end;
$$;

--
-- Name: FUNCTION desfazer_coordenada_mapa_saude_indigena(p_historico bigint, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.desfazer_coordenada_mapa_saude_indigena(p_historico bigint, p_motivo text) IS 'Volta a última alteração de um ponto do mapa (posição e conferência) como uma alteração nova, com motivo; nada do histórico é apagado. Só administrador global ou gestor.';

--
-- Name: disparar_robo(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disparar_robo(p_robo text, p_inputs jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  c_robos constant jsonb := jsonb_build_object(
    'empregare', jsonb_build_object('nome', 'Robô da Empregare', 'workflow', 'robo-empregare.yml',
      'modos', jsonb_build_array('normal', 'seco', 'fumaca', 'forcar', 'sondar', 'anexos'),
      'editais', 'numero', 'vagas', true, 'limite', true, 'anexos', true, 'candidatos', true, 'seco', true,
      'forcar_congelado', true, 'motivo', true, 'modos_que_gravam', jsonb_build_array('normal', 'forcar'),
      'modos_que_gravam_sem_seco', jsonb_build_array('anexos')),
    'selecao', jsonb_build_object('nome', 'Seleção', 'workflow', 'sincronizar-selecao.yml',
      'modos', jsonb_build_array('normal')),
    'entrevistas', jsonb_build_object('nome', 'Entrevistas', 'workflow', 'sincronizar-entrevistas.yml',
      'modos', jsonb_build_array('normal')),
    'conferencias', jsonb_build_object('nome', 'Conferências de consistência', 'workflow', 'conferencias.yml',
      'modos', jsonb_build_array('normal', 'seco')),
    'pre_classificacao', jsonb_build_object('nome', 'Pré-classificação (Avaliação documental)', 'workflow', 'pre-classificacao.yml',
      'modos', jsonb_build_array('normal', 'seco', 'refazer_lote'),
      'editais', 'numero_ou_id', 'por_edital', true,
      'forcar_congelado', true, 'motivo', true, 'modos_que_gravam', jsonb_build_array('normal', 'refazer_lote')),
    -- [classificacao-python] (20261023200000) reprocessa os relatórios de desempate e os cálculos pendentes.
    'classificacao_desempate', jsonb_build_object('nome', 'Relatório de desempate (Classificação em Python)',
      'workflow', 'classificacao.yml', 'modos', jsonb_build_array('normal')));
  c_uuid constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_uid uuid := (select auth.uid());
  v_robo jsonb := c_robos -> p_robo;
  v_in jsonb := coalesce(p_inputs, '{}'::jsonb);
  v_chave text;
  v_valor jsonb;
  v_itens text[];
  v_item text;
  v_modo text;
  v_editais text[] := '{}';
  v_vagas text[] := '{}';
  v_candidatos text[] := '{}';
  v_limite integer;
  v_anexos boolean;
  v_seco boolean;
  v_saida jsonb;
  v_forcar_congelado boolean := false;
  v_motivo text;
  v_congelados uuid[] := '{}';
  v_rotulos text;
  v_liberacao uuid;
  v_disparo bigint;
  v_grava boolean;
begin
  if v_uid is null then
    raise exception 'Entre no MONITORA de novo para rodar a carga.' using errcode = '28000';
  end if;
  if v_robo is null then
    raise exception 'Carga desconhecida.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_in) <> 'object' then
    raise exception 'Opções inválidas.' using errcode = '22023';
  end if;

  -- Opção que o robô não aceita (vazia passa, como em validarOpcoes).
  for v_chave, v_valor in select * from jsonb_each(v_in) loop
    if v_chave not in ('modo', 'editais', 'vagas', 'limite', 'anexos', 'candidatos', 'seco', 'forcar_congelado', 'motivo')
       or (v_chave <> 'modo' and v_robo -> v_chave is null
           and not (jsonb_typeof(v_valor) = 'null'
                    or v_valor in ('""'::jsonb, '[]'::jsonb, 'false'::jsonb, '"false"'::jsonb))) then
      raise exception '% não aceita “%”.', v_robo ->> 'nome', left(v_chave, 30) using errcode = '22023';
    end if;
  end loop;

  -- Modo
  if jsonb_typeof(v_in -> 'modo') not in ('string', 'null') then
    raise exception 'Modo inválido para este robô.' using errcode = '22023';
  end if;
  v_modo := coalesce(nullif(btrim(v_in ->> 'modo'), ''), 'normal');
  if not ((v_robo -> 'modos') ? v_modo) then
    raise exception 'Modo inválido para este robô.' using errcode = '22023';
  end if;

  -- Editais: número (93/2026) ou, na pré-classificação, também o id.
  if v_robo ? 'editais' and coalesce(jsonb_typeof(v_in -> 'editais'), 'null') <> 'null' then
    v_valor := v_in -> 'editais';
    if jsonb_typeof(v_valor) = 'array' then
      if exists (select 1 from jsonb_array_elements(v_valor) e where jsonb_typeof(e) <> 'string') then
        raise exception 'Edital inválido.' using errcode = '22023';
      end if;
      select coalesce(array_agg(e), '{}') into v_itens from jsonb_array_elements_text(v_valor) e;
    elsif jsonb_typeof(v_valor) = 'string' then
      v_itens := string_to_array(v_valor #>> '{}', ',');
    else
      raise exception 'Edital inválido.' using errcode = '22023';
    end if;
    foreach v_item in array v_itens loop
      v_item := btrim(v_item);
      continue when v_item = '';
      if lower(v_item) ~ c_uuid and v_robo ->> 'editais' = 'numero_ou_id' then
        v_item := lower(v_item);
      elsif v_item !~ '^\d{1,4}/\d{4}$' then
        raise exception 'Edital inválido: %.', left(v_item, 40) using errcode = '22023';
      end if;
      if not v_item = any (v_editais) then
        v_editais := v_editais || v_item;
      end if;
    end loop;
    if cardinality(v_editais) > 100 then
      raise exception 'No máximo 100 editais por vez.' using errcode = '22023';
    end if;
  end if;

  -- Vagas: códigos da Empregare, só dígitos.
  if v_robo ? 'vagas' and coalesce(jsonb_typeof(v_in -> 'vagas'), 'null') <> 'null' then
    v_valor := v_in -> 'vagas';
    if jsonb_typeof(v_valor) = 'array' then
      if exists (select 1 from jsonb_array_elements(v_valor) e where jsonb_typeof(e) <> 'string') then
        raise exception 'Código de vaga inválido (só dígitos).' using errcode = '22023';
      end if;
      select coalesce(array_agg(e), '{}') into v_itens from jsonb_array_elements_text(v_valor) e;
    elsif jsonb_typeof(v_valor) = 'string' then
      v_itens := regexp_split_to_array(v_valor #>> '{}', '[\s,;]+');
    else
      raise exception 'Código de vaga inválido (só dígitos).' using errcode = '22023';
    end if;
    foreach v_item in array v_itens loop
      v_item := btrim(v_item);
      continue when v_item = '';
      if v_item !~ '^\d{1,20}$' then
        raise exception 'Código de vaga inválido: % (só dígitos).', left(v_item, 30) using errcode = '22023';
      end if;
      if not v_item = any (v_vagas) then
        v_vagas := v_vagas || v_item;
      end if;
    end loop;
    if cardinality(v_vagas) > 500 then
      raise exception 'No máximo 500 vagas por vez.' using errcode = '22023';
    end if;
  end if;

  -- Candidatos (modo anexos): códigos da Empregare, só dígitos.
  if v_robo ? 'candidatos' and coalesce(jsonb_typeof(v_in -> 'candidatos'), 'null') <> 'null' then
    v_valor := v_in -> 'candidatos';
    if jsonb_typeof(v_valor) = 'array' then
      if exists (select 1 from jsonb_array_elements(v_valor) e where jsonb_typeof(e) <> 'string') then
        raise exception 'Código de candidato inválido (só dígitos).' using errcode = '22023';
      end if;
      select coalesce(array_agg(e), '{}') into v_itens from jsonb_array_elements_text(v_valor) e;
    elsif jsonb_typeof(v_valor) = 'string' then
      v_itens := regexp_split_to_array(v_valor #>> '{}', '[\s,;]+');
    else
      raise exception 'Código de candidato inválido (só dígitos).' using errcode = '22023';
    end if;
    foreach v_item in array v_itens loop
      v_item := btrim(v_item);
      continue when v_item = '';
      if v_item !~ '^\d{1,20}$' then
        raise exception 'Código de candidato inválido: % (só dígitos).', left(v_item, 30) using errcode = '22023';
      end if;
      if not v_item = any (v_candidatos) then
        v_candidatos := v_candidatos || v_item;
      end if;
    end loop;
    if cardinality(v_candidatos) > 1000 then
      raise exception 'No máximo 1.000 candidatos por vez.' using errcode = '22023';
    end if;
  end if;

  -- Limite: 1 a 500 vagas.
  if v_robo ? 'limite' and coalesce(jsonb_typeof(v_in -> 'limite'), 'null') <> 'null'
     and btrim(v_in ->> 'limite') <> '' then
    if btrim(v_in ->> 'limite') !~ '^\d{1,3}$'
       or (btrim(v_in ->> 'limite'))::integer not between 1 and 500 then
      raise exception 'Limite de 1 a 500 vagas.' using errcode = '22023';
    end if;
    v_limite := (btrim(v_in ->> 'limite'))::integer;
  end if;

  -- Anexos (robô da Empregare): true/false ou "true"/"false"; só nos modos normal e forcar.
  if v_robo ? 'anexos' and coalesce(jsonb_typeof(v_in -> 'anexos'), 'null') <> 'null' then
    if v_in -> 'anexos' in ('true'::jsonb, '"true"'::jsonb) then
      v_anexos := true;
    elsif v_in -> 'anexos' in ('false'::jsonb, '"false"'::jsonb, '""'::jsonb) then
      v_anexos := false;
    else
      raise exception 'Opção “anexos” inválida (sim ou não).' using errcode = '22023';
    end if;
    if v_anexos and v_modo not in ('normal', 'forcar') then
      raise exception 'Guardar os links dos anexos só nos modos Normal e Forçar.' using errcode = '22023';
    end if;
  end if;

  -- Seco (modo anexos): true/false ou "true"/"false".
  if v_robo ? 'seco' and coalesce(jsonb_typeof(v_in -> 'seco'), 'null') <> 'null' then
    if v_in -> 'seco' in ('true'::jsonb, '"true"'::jsonb) then
      v_seco := true;
    elsif v_in -> 'seco' in ('false'::jsonb, '"false"'::jsonb, '""'::jsonb) then
      v_seco := false;
    else
      raise exception 'Opção “seco” inválida (sim ou não).' using errcode = '22023';
    end if;
  end if;

  -- Forçar edital congelado (20261020170000): true/false ou "true"/"false", com motivo.
  if v_robo ? 'forcar_congelado' and coalesce(jsonb_typeof(v_in -> 'forcar_congelado'), 'null') <> 'null' then
    if v_in -> 'forcar_congelado' in ('true'::jsonb, '"true"'::jsonb) then
      v_forcar_congelado := true;
    elsif v_in -> 'forcar_congelado' not in ('false'::jsonb, '"false"'::jsonb, '""'::jsonb) then
      raise exception 'Opção “forcar_congelado” inválida (sim ou não).' using errcode = '22023';
    end if;
  end if;
  if v_robo ? 'motivo' and coalesce(jsonb_typeof(v_in -> 'motivo'), 'null') <> 'null' then
    if jsonb_typeof(v_in -> 'motivo') <> 'string' then
      raise exception 'Motivo inválido.' using errcode = '22023';
    end if;
    v_motivo := nullif(btrim(v_in ->> 'motivo'), '');
  end if;
  if v_motivo is not null and not v_forcar_congelado then
    raise exception 'O motivo só vale com “Forçar edital com inscrições congeladas”.' using errcode = '22023';
  end if;

  -- Só anexos: relê os anexos do questionário sem exportar; pede vagas ou editais.
  if v_modo = 'anexos' then
    if cardinality(v_vagas) = 0 and cardinality(v_editais) = 0 then
      raise exception 'O modo Só anexos pede vagas ou editais.' using errcode = '22023';
    end if;
  elsif cardinality(v_candidatos) > 0 or coalesce(v_seco, false) then
    raise exception 'Candidatos e "só comparar" só no modo Só anexos.' using errcode = '22023';
  end if;

  -- Sondar (como o workflow exige): uma única vaga, sem editais, limite de 1 a 3 candidatos.
  if v_modo = 'sondar' then
    if cardinality(v_vagas) <> 1 or cardinality(v_editais) > 0 then
      raise exception 'O modo Sondar pede um único código de vaga (sem editais).' using errcode = '22023';
    end if;
    if v_limite is not null and v_limite > 3 then
      raise exception 'No modo Sondar, o limite é de 1 a 3 candidatos.' using errcode = '22023';
    end if;
  end if;

  -- Quem pode (o banco decide, como em api/rodar-carga.js).
  if not public.pode_disparar_carga() then
    if not coalesce((v_robo ->> 'por_edital')::boolean, false) then
      raise exception 'Só o administrador global roda as cargas.' using errcode = '42501';
    end if;
    if v_modo <> 'normal' or cardinality(v_vagas) > 0 or v_limite is not null or v_forcar_congelado
       or cardinality(v_editais) <> 1 or v_editais[1] !~ c_uuid then
      raise exception 'Só o administrador global roda as cargas com opções.' using errcode = '42501';
    end if;
    if not public.pode_recalcular_pre_classificacao(v_editais[1]::uuid) then
      raise exception 'Só a coordenação da avaliação do edital recalcula a pré-classificação.' using errcode = '42501';
    end if;
  end if;

  -- Duplo clique: o mesmo robô pedido há menos de 2 min (e ainda não recusado).
  if exists (
    select 1 from public."TL_DISPARO_ROBO" d
     where d."NO_WORKFLOW" = v_robo ->> 'workflow'
       and d."TP_SITUACAO" in ('PEDIDO', 'ACEITO')
       and d."DT_DISPARO" > now() - interval '2 minutes') then
    raise exception 'Esta carga acabou de ser pedida. Aguarde alguns minutos.' using errcode = '55006';
  end if;

  -- [pendente-no-grupo] (20261022170000) O GitHub guarda UMA execução esperando por grupo de
  -- concorrência: um pedido novo cancela, sem aviso, o que já esperava. Com uma execução
  -- rodando e outra já pedida depois dela, recusa em vez de trocar uma pela outra.
  if private."FC_EXECUCAO_PENDENTE_NO_GRUPO"(v_robo ->> 'workflow') then
    raise exception 'Já há uma execução desta carga esperando a que está rodando terminar; um pedido novo cancelaria aquela. Aguarde.'
      using errcode = '55006';
  end if;

  -- [congeladas] Inscrições congeladas (20261020170000): nos modos que gravam, o edital ou a
  -- vaga pedidos explicitamente de edital congelado são recusados; o administrador global
  -- pode forçar, com motivo (a LIBERACAO vale 12 h e vai ao workflow como forcar_congelado).
  -- Sem edital nem vaga, o robô e a pré-classificação pulam os congelados sozinhos.
  -- (20261022170000) O Só anexos grava também (respostas e anexos): só com a liberação, ou
  -- com "só comparar" (seco), que não grava nada.
  v_grava := (v_robo -> 'modos_que_gravam') ? v_modo
             or ((v_robo -> 'modos_que_gravam_sem_seco') ? v_modo and not coalesce(v_seco, false));
  if v_grava then
    select coalesce(array_agg(distinct m.id), '{}'),
           string_agg(distinct coalesce(private."FC_NUMERO_EDITAL"(m.edital), m.edital), ', ')
      into v_congelados, v_rotulos
      from public."TB_CONGELAMENTO_INSCRICAO" c
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = c."CO_MONITORAMENTO"
     where c."ST_INSCRICOES_CONGELADAS" = 'S'
       and (m.id::text = any (v_editais)
            or private."FC_NUMERO_EDITAL"(m.edital) = any (v_editais)
            or exists (select 1 from public."TB_EMPREGARE_VAGA" v
                        where v."CO_MONITORAMENTO" = m.id and v."CO_VAGA" = any (v_vagas)));
    if cardinality(v_congelados) > 0 and not v_forcar_congelado and v_modo = 'anexos' then
      raise exception 'Inscrições congeladas: %. O Só anexos só grava neste edital com a liberação do administrador global (com motivo); para conferir sem gravar, use "só comparar".', v_rotulos
        using errcode = '55000';
    end if;
    if cardinality(v_congelados) > 0 and not v_forcar_congelado then
      raise exception 'Inscrições congeladas: %. O robô e a pré-classificação não mexem neste edital; tire-o do pedido (só o administrador global força, com motivo).', v_rotulos
        using errcode = '55000';
    end if;
    if v_forcar_congelado then
      if not public.pode_disparar_carga() then
        raise exception 'Só o administrador global força edital com inscrições congeladas.' using errcode = '42501';
      end if;
      if v_motivo is null or length(v_motivo) not between 10 and 500 then
        raise exception 'Informe o motivo para forçar (10 a 500 caracteres).' using errcode = '22023';
      end if;
      if cardinality(v_congelados) = 0 then
        raise exception 'Nenhum edital ou vaga pedida está com as inscrições congeladas.' using errcode = '22023';
      end if;
      v_liberacao := gen_random_uuid();
      insert into public."TH_CONGELAMENTO_INSCRICAO"
             ("CO_MONITORAMENTO", "TP_EVENTO", "DS_MOTIVO", "CO_USUARIO", "CO_LIBERACAO", "DT_VALIDADE")
      select x, 'LIBERACAO', v_motivo, v_uid, v_liberacao, now() + interval '12 hours'
        from unnest(v_congelados) x;
    end if;
  elsif v_forcar_congelado then
    raise exception 'Forçar edital congelado só nos modos que gravam (no Só anexos, sem "só comparar").' using errcode = '22023';
  end if;

  v_saida := jsonb_build_object('modo', v_modo);
  if coalesce((v_robo ->> 'por_edital')::boolean, false) or cardinality(v_editais) > 0 then
    v_saida := v_saida || jsonb_build_object('editais', array_to_string(v_editais, ','));
  end if;
  if cardinality(v_vagas) > 0 then
    v_saida := v_saida || jsonb_build_object('vagas', array_to_string(v_vagas, ','));
  end if;
  if v_limite is not null then
    v_saida := v_saida || jsonb_build_object('limite', v_limite::text);
  end if;
  if v_anexos is not null then
    v_saida := v_saida || jsonb_build_object('anexos', case when v_anexos then 'true' else 'false' end);
  end if;
  if cardinality(v_candidatos) > 0 then
    v_saida := v_saida || jsonb_build_object('candidatos', array_to_string(v_candidatos, ','));
  end if;
  if v_modo = 'anexos' then
    v_saida := v_saida || jsonb_build_object('seco', case when coalesce(v_seco, false) then 'true' else 'false' end);
  end if;

  if v_liberacao is not null then
    v_saida := v_saida || jsonb_build_object('forcar_congelado', v_liberacao::text);
  end if;

  v_disparo := private."FC_DISPARAR_ROBO"(v_robo ->> 'workflow', v_saida, v_uid);
  if v_liberacao is not null then
    update public."TH_CONGELAMENTO_INSCRICAO" h set "CO_DISPARO" = v_disparo
     where h."CO_LIBERACAO" = v_liberacao and h."TP_EVENTO" = 'LIBERACAO';
  end if;
  return v_disparo;
end;
$_$;

--
-- Name: FUNCTION disparar_robo(p_robo text, p_inputs jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.disparar_robo(p_robo text, p_inputs jsonb) IS 'Rodar agora, Opções (Status das atualizações) e Recalcular (pré-classificação) pelo banco (20261008140000; substitui api/rodar-carga.js): confere quem pede (administrador global: qualquer robô e opções; coordenação: só a pré-classificação de um edital pelo id, modo normal), a lista branca do robô (modo, editais, vagas, limite, anexos; no robô da Empregare o modo "anexos" — só relê os anexos do questionário, sem exportar nem pré-classificar; pede vagas ou editais — com "candidatos" e "seco", que só valem nele; desde 20261023200000, o relatório de desempate da Classificação em Python, "classificacao_desempate", só no modo normal: prepara os relatórios e os cálculos pendentes), o pedido repetido em 2 min (55006) e, desde 20261022170000, a execução que já espera a vez no grupo de concorrência do GitHub (55006: o pedido novo a cancelaria). Inscrições congeladas (20261020170000): nos modos que gravam (robô: normal, forcar e, desde 20261022170000, anexos sem "seco"; pré-classificação: normal e refazer_lote), edital ou vaga pedidos de edital congelado dão 55000, salvo forcar_congelado = true com motivo (10 a 500), só do administrador global — grava a LIBERACAO em TH_CONGELAMENTO_INSCRICAO (12 h) e manda o token como forcar_congelado. Pede o workflow por FC_DISPARAR_ROBO com disparado_por = id de quem pediu e devolve o CO_DISPARO de TL_DISPARO_ROBO (acompanhe por situacao_do_disparo_robo). 28000 sem sessão, 42501 sem permissão, 22023 para opção inválida.';

--
-- Name: distribuir_fichas(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distribuir_fichas(p_edital uuid, p_atribuicoes jsonb, p_motivo text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_FICHAS"(p_edital);
  v_uid uuid := (select auth.uid());
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_item record;
  v_f public."TB_FICHA_ANALISE";
  v_acao text;
  v_qt integer;
  v_alteradas integer := 0;
  v_codigo text;
begin
  if jsonb_typeof(p_atribuicoes) is distinct from 'array' or jsonb_array_length(p_atribuicoes) not between 1 and 5000 then
    raise exception 'Escolha de 1 a 5.000 fichas.' using errcode = '22023';
  end if;
  if v_motivo is not null and length(v_motivo) > 2000 then
    raise exception 'Motivo com até 2.000 caracteres.' using errcode = '22023';
  end if;
  begin
    -- Controle otimista: alguma ficha mudou desde que a tela leu? Nada é gravado.
    select count(*) into v_qt
      from jsonb_to_recordset(p_atribuicoes) x(ficha uuid, versao integer, usuario uuid)
      left join public."TB_FICHA_ANALISE" f on f."CO_FICHA_ANALISE" = x.ficha and f."CO_MONITORAMENTO" = p_edital
     where f."CO_FICHA_ANALISE" is null or f."NU_VERSAO" is distinct from x.versao;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'Atribuição com id ou versão inválida' using errcode = '22023';
  end;
  if v_qt > 0 then
    raise exception '% ficha(s) mudaram desde que você abriu a fila; atualize e confira.', v_qt using errcode = 'PT409';
  end if;

  for v_item in
    select x.ficha, x.usuario from jsonb_to_recordset(p_atribuicoes) x(ficha uuid, versao integer, usuario uuid) order by x.ficha
  loop
    select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = v_item.ficha for update;
    select c."CO_CANDIDATO_EMPREGARE" into v_codigo from public."TB_EMPREGARE_CANDIDATO" c
     where c."CO_EMPREGARE_CANDIDATO" = v_f."CO_EMPREGARE_CANDIDATO";
    if v_f."TP_SITUACAO" in ('CONCLUIDA', 'FORA_LOTE') then
      raise exception 'A ficha % está %: não é redistribuída (AM-6.3).', v_codigo,
        case v_f."TP_SITUACAO" when 'CONCLUIDA' then 'concluída' else 'fora do lote' end using errcode = '22023';
    end if;
    continue when v_item.usuario is not distinct from v_f."CO_USUARIO_RESPONSAVEL"
                  and not (v_item.usuario is null and v_f."TP_SITUACAO" = 'REVISAR');
    if v_item.usuario is not null and not private."FC_PODE_ANALISAR_VAGA"(p_edital, v_item.usuario, v_f."CO_VAGA") then
      raise exception 'A pessoa escolhida para a ficha % não analisa a vaga % (equipe do edital, papel Analista, Editor).', v_codigo, v_f."CO_VAGA"
        using errcode = '22023';
    end if;
    v_acao := case when v_item.usuario is null then 'DEVOLVER_FILA'
                   when v_f."CO_USUARIO_RESPONSAVEL" is null then 'DISTRIBUIR' else 'REDISTRIBUIR' end;
    if v_acao <> 'DISTRIBUIR' and (v_motivo is null or length(v_motivo) < 10 or not private."FC_MOTIVO_PARECE_TEXTO"(v_motivo, 2)) then
      raise exception 'Informe o motivo para redistribuir ou devolver à fila (10 a 2.000 caracteres, com pelo menos 2 palavras).' using errcode = '22023';
    end if;
    update public."TB_FICHA_ANALISE" set
      "CO_USUARIO_RESPONSAVEL" = v_item.usuario,
      "DT_ATRIBUICAO" = case when v_item.usuario is null then null else now() end,
      "TP_SITUACAO" = case when v_item.usuario is null then 'PENDENTE' else "TP_SITUACAO" end,
      "CO_USUARIO_RESERVA" = null, "DT_RESERVA" = null, "DT_RESERVA_EXPIRA" = null,
      "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
     where "CO_FICHA_ANALISE" = v_item.ficha;
    perform private."FC_HISTORICO_FICHA"(v_item.ficha, v_acao, v_f."TP_SITUACAO", v_f."CO_USUARIO_RESPONSAVEL", v_motivo, v_uid);
    v_alteradas := v_alteradas + 1;
  end loop;
  return json_build_object('alteradas', v_alteradas);
end;
$$;

--
-- Name: FUNCTION distribuir_fichas(p_edital uuid, p_atribuicoes jsonb, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.distribuir_fichas(p_edital uuid, p_atribuicoes jsonb, p_motivo text) IS 'Distribuição inicial, redistribuição e devolução à fila pela coordenação (a prévia é da tela: src/lib/avaliacao-documental/distribuicao.js). p_atribuicoes [{ficha, versao, usuario}] (usuario nulo = devolver à fila): confere a versão de todas antes (40001, nada grava), recusa ficha concluída ou fora do lote (AM-6.3) e pessoa que não analisa a vaga; redistribuir e devolver exigem motivo (10 a 2.000); a reserva cai; tudo vai ao histórico. Só a coordenação do edital.';

--
-- Name: escolher_lista_da_contratacao(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escolher_lista_da_contratacao(p_pendencia uuid, p_candidato uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_PENDENCIA_APROVADO"%rowtype;
  v_alteracoes jsonb := '[]'::jsonb;
  r record;
begin
  v := private."FC_PENDENCIA_PARA_DECIDIR"(p_pendencia, array['CONTRATADO_EM_DUAS_LISTAS'], p_motivo);
  if not exists (select 1 from public."TB_CANDIDATO_APROVADO" c
                  where c.id = p_candidato and c.id = any (v."CO_CANDIDATO_APROVADO") and c.status = 'Contratado') then
    raise exception 'Escolha uma das linhas Contratado da pendência' using errcode = '22023';
  end if;
  -- As outras ficam "Contratado em outra lista" explícito (o status, com a matrícula): sobrepõe a regra.
  for r in select c.id, c.matricula from public."TB_CANDIDATO_APROVADO" c
            where c.id = any (v."CO_CANDIDATO_APROVADO") and c.id <> p_candidato and c.status = 'Contratado'
            order by c.id loop
    v_alteracoes := v_alteracoes || private."FC_STATUS_PELA_PENDENCIA"(r.id, 'Contratado em outra lista', r.matricula, null);
  end loop;
  return private."FC_FECHAR_PENDENCIA"(p_pendencia, 'LISTA_ESCOLHIDA', p_motivo, v_alteracoes);
end;
$$;

--
-- Name: FUNCTION escolher_lista_da_contratacao(p_pendencia uuid, p_candidato uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.escolher_lista_da_contratacao(p_pendencia uuid, p_candidato uuid, p_motivo text) IS 'Pendência "Contratado em duas listas" (o AMBIGUO do job): a linha escolhida é a contratação; as outras linhas Contratado ficam "Contratado em outra lista" explícito. Quem decide (FC_PODE_DECIDIR_PENDENCIA), com motivo; histórico, contratados e avisos. 20261026190000.';

--
-- Name: escolher_vinculo_do_contratado(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escolher_vinculo_do_contratado(p_pendencia uuid, p_candidato uuid, p_status_das_outras text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_PENDENCIA_APROVADO"%rowtype;
  v_vinculo text;
  v_outras text := btrim(coalesce(p_status_das_outras, ''));
  v_alteracoes jsonb := '[]'::jsonb;
  r record;
begin
  v := private."FC_PENDENCIA_PARA_DECIDIR"(p_pendencia, array['CONTRATADO_DUAS_MATRICULAS'], p_motivo);
  if v_outras not in ('Contratado em outra lista', 'Desistente', 'Sem status') then
    raise exception 'Escolha o desfecho das outras linhas: Contratado em outra lista, Desistente ou Sem status'
      using errcode = '22023';
  end if;
  select private."FC_VINCULO_DA_MATRICULA"(c.matricula) into v_vinculo
    from public."TB_CANDIDATO_APROVADO" c
   where c.id = p_candidato and c.id = any (v."CO_CANDIDATO_APROVADO") and c.status = 'Contratado';
  if v_vinculo is null then
    raise exception 'Escolha uma das linhas Contratado da pendência' using errcode = '22023';
  end if;
  -- As outras linhas Contratado: a mesma matrícula é a mesma contratação (em outra lista); a outra
  -- matrícula recebe o desfecho escolhido.
  for r in select c.id, private."FC_VINCULO_DA_MATRICULA"(c.matricula) as vinculo, c.matricula
             from public."TB_CANDIDATO_APROVADO" c
            where c.id = any (v."CO_CANDIDATO_APROVADO") and c.id <> p_candidato and c.status = 'Contratado'
            order by c.id loop
    v_alteracoes := v_alteracoes || private."FC_STATUS_PELA_PENDENCIA"(
      r.id,
      case when r.vinculo = v_vinculo then 'Contratado em outra lista'
           when v_outras = 'Sem status' then null else v_outras end,
      r.matricula, null);
  end loop;
  return private."FC_FECHAR_PENDENCIA"(p_pendencia, 'VINCULO_ESCOLHIDO', p_motivo, v_alteracoes);
end;
$$;

--
-- Name: FUNCTION escolher_vinculo_do_contratado(p_pendencia uuid, p_candidato uuid, p_status_das_outras text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.escolher_vinculo_do_contratado(p_pendencia uuid, p_candidato uuid, p_status_das_outras text, p_motivo text) IS 'Pendência "Contratado com duas matrículas": a linha escolhida fica Contratado; as outras linhas Contratado da pessoa no edital ficam "Contratado em outra lista" (mesma matrícula) ou com o desfecho escolhido (Contratado em outra lista, Desistente ou Sem status). Quem decide (FC_PODE_DECIDIR_PENDENCIA), com motivo; histórico, contratados e avisos. 20261026190000.';

--
-- Name: excluir_demanda_interna(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.excluir_demanda_interna(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
declare
  v_usuario uuid := (select auth.uid());
  v_atual public."TB_DEMANDA_INTERNA";
  v_antes jsonb;
begin
  if v_usuario is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;
  select * into v_atual from public."TB_DEMANDA_INTERNA" d
   where d."CO_DEMANDA_INTERNA" = p_id for update;
  if v_atual."CO_DEMANDA_INTERNA" is null or v_atual."ST_ATIVO" <> 'S' then
    raise exception 'Demanda não encontrada.' using errcode = 'P0002';
  end if;
  if not private."FC_PODE_EDITAR_DEMANDA"(v_atual."CO_AREA", v_atual."CO_MONITORAMENTO") then
    raise exception 'Sem permissão para esta demanda.' using errcode = '42501';
  end if;

  v_antes := private."FC_DEMANDA_INTERNA_JSON"(p_id);
  update public."TB_DEMANDA_INTERNA" d
     set "ST_ATIVO" = 'N',
         "CO_USUARIO_ATUALIZACAO" = v_usuario,
         "DT_ATUALIZACAO" = now()
   where d."CO_DEMANDA_INTERNA" = p_id;
  insert into public."TH_DEMANDA_INTERNA" ("CO_DEMANDA_INTERNA", "TP_ACAO", "DS_ANTES", "DS_DEPOIS", "CO_USUARIO")
  values (p_id, 'EXCLUSAO', v_antes, private."FC_DEMANDA_INTERNA_JSON"(p_id), v_usuario);

  return jsonb_build_object('ok', true, 'id', p_id);
end;
$$;

--
-- Name: FUNCTION excluir_demanda_interna(p_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.excluir_demanda_interna(p_id uuid) IS 'Exclusão lógica (ST_ATIVO = N) de uma demanda interna. Gestor da área ou administrador global; grava TH_DEMANDA_INTERNA. 20261104120000.';

--
-- Name: excluir_filtro_fila(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.excluir_filtro_fila(p_filtro uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null or not private.pode_recurso('avaliacao_documental', 1) then
    raise exception 'Sem permissão para a Avaliação documental' using errcode = '42501';
  end if;
  update public."TB_FILTRO_FILA_ANALISE" set "ST_ATIVO" = 'N', "DT_ATUALIZACAO" = now()
   where "CO_FILTRO_FILA" = p_filtro and "CO_USUARIO" = v_uid and "ST_ATIVO" = 'S';
  if not found then
    raise exception 'Filtro não encontrado.' using errcode = '22023';
  end if;
  return private."FC_FILTROS_FILA_JSON"(v_uid);
end;
$$;

--
-- Name: FUNCTION excluir_filtro_fila(p_filtro uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.excluir_filtro_fila(p_filtro uuid) IS 'Exclui (desativa) um filtro salvo de quem chama. Devolve os filtros salvos. Exige avaliacao_documental >= leitor.';

--
-- Name: excluir_recurso_candidato(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.excluir_recurso_candidato(p_id uuid, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_edital uuid;
  v_situacao text;
  v_area text;
begin
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then
    raise exception 'Informe um motivo entre 3 e 500 caracteres' using errcode = '22023';
  end if;
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  select r."CO_MONITORAMENTO", r."TP_SITUACAO" into v_edital, v_situacao
  from public."TB_RECURSO_CANDIDATO" r
  where r."CO_RECURSO_CANDIDATO" = p_id and r."ST_ATIVO" = 'S'
  for update;
  if v_edital is null then
    raise exception 'Recurso não encontrado' using errcode = 'P0002';
  end if;
  select m."CO_AREA" into v_area from public."TB_MONITORAMENTO_INDIGENA" m where m.id = v_edital;
  perform private."FC_EXIGIR_RECURSOS_NA_AREA"(v_area, 2);
  perform private."FC_EXIGIR_AREA_EDITAL"(v_edital::text);
  if v_situacao in ('DEFERIDO', 'INDEFERIDO', 'PARCIALMENTE_INDEFERIDO') then
    perform private."FC_EXIGIR_PARECER_RECURSO"();
  end if;
  update public."TB_RECURSO_CANDIDATO" set
    "ST_ATIVO" = 'N',
    "NU_REVISAO" = "NU_REVISAO" + 1,
    "DT_ATUALIZACAO" = now(),
    "CO_USUARIO_ATUALIZACAO" = v_uid
  where "CO_RECURSO_CANDIDATO" = p_id;
  insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "DS_MOTIVO", "CO_USUARIO")
  values (p_id, 'exclusao', 'S', 'N', btrim(p_motivo), v_uid);
  return json_build_object('id', p_id, 'excluido', true);
end;
$$;

--
-- Name: FUNCTION excluir_recurso_candidato(p_id uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.excluir_recurso_candidato(p_id uuid, p_motivo text) IS 'Exclusão lógica (ST_ATIVO = N) de um recurso cadastrado por engano, com motivo no histórico. Exige recursos >= editor, a área e a coordenação do edital; recurso decidido, também o parecer jurídico.';

--
-- Name: fechar_vaga_empregare(text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fechar_vaga_empregare(p_sync text, p_vaga text, p_colunas jsonb, p_arquivo text DEFAULT NULL::text, p_vaga_interno text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_situacao text;
  v_desativadas integer;
  v_ativos integer;
  v_recebidas integer;
  -- Identificador fora do formato (ou só o código numérico) é ignorado: fica o anterior.
  v_interno text := case
    when btrim(p_vaga_interno) ~ '^[A-Za-z0-9_.~=-]{1,96}[|]{0,3}$' and btrim(p_vaga_interno) !~ '^[0-9]+[|]*$'
    then btrim(p_vaga_interno) end;
begin
  perform private."FC_EMPREGARE_EXIGIR_SYNC"(p_sync);
  if p_vaga is null or p_vaga !~ '^[0-9]{1,20}$' then
    raise exception 'Código de vaga inválido' using errcode = '22023';
  end if;
  if jsonb_typeof(p_colunas) is distinct from 'array' or jsonb_array_length(p_colunas) > 2000 then
    raise exception 'Colunas em lista de até 2000 nomes' using errcode = '22023';
  end if;

  -- Arquivo sem nenhum candidato não passou por gravar_lote: a trava vale aqui.
  v_situacao := private."FC_EMPREGARE_ABRIR_VAGA"(p_sync, p_vaga, 0);

  -- O identificador da vaga não é dado de candidato: grava mesmo se a trava recusar o arquivo.
  if v_interno is not null then
    update public."TB_EMPREGARE_VAGA" set "CO_VAGA_INTERNO" = v_interno, "DT_CAPTURA_LINK" = now()
     where "CO_VAGA" = p_vaga;
  end if;

  if v_situacao = 'RECUSADA' then
    return jsonb_build_object('situacao', 'RECUSADA',
      'mensagem', (select v."DS_MENSAGEM" from public."TB_EMPREGARE_VAGA" v where v."CO_VAGA" = p_vaga));
  end if;
  if v_situacao <> 'EM_CARGA' then
    raise exception 'Vaga % já fechada nesta execução', p_vaga using errcode = '22023';
  end if;

  update public."TB_EMPREGARE_CANDIDATO" c set
    "ST_REGISTRO_ATIVO" = 'N', "DT_DESATIVACAO" = now(), "DT_ATUALIZACAO" = now()
   where c."CO_VAGA" = p_vaga and c."ST_REGISTRO_ATIVO" = 'S' and c."CO_SYNC" is distinct from p_sync;
  get diagnostics v_desativadas = row_count;

  select count(*) into v_ativos
    from public."TB_EMPREGARE_CANDIDATO" c
   where c."CO_VAGA" = p_vaga and c."ST_REGISTRO_ATIVO" = 'S';

  update public."TB_EMPREGARE_VAGA" set
    "TP_SITUACAO" = 'GRAVADA', "DS_COLUNA" = p_colunas, "NO_ARQUIVO" = left(p_arquivo, 300),
    "QT_CANDIDATO_ATIVO" = v_ativos, "DS_MENSAGEM" = null, "DT_ULTIMA_CARGA" = now(), "DT_ATUALIZACAO" = now()
   where "CO_VAGA" = p_vaga
  returning "QT_RECEBIDA" into v_recebidas;

  update public."TL_SYNC_EMPREGARE" set "QT_DESATIVADA" = "QT_DESATIVADA" + v_desativadas where "CO_SYNC" = p_sync;
  return jsonb_build_object('situacao', 'GRAVADA', 'recebidas', v_recebidas, 'ativos', v_ativos, 'desativadas', v_desativadas,
                            'vaga_interno', v_interno is not null);
end;
$_$;

--
-- Name: FUNCTION fechar_vaga_empregare(p_sync text, p_vaga text, p_colunas jsonb, p_arquivo text, p_vaga_interno text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fechar_vaga_empregare(p_sync text, p_vaga text, p_colunas jsonb, p_arquivo text, p_vaga_interno text) IS 'Fecha a vaga na execução: desativa (ST_REGISTRO_ATIVO = N) quem não veio no arquivo e grava colunas, arquivo e ativos em TB_EMPREGARE_VAGA. Vaga recusada pela trava não muda. Arquivo sem candidatos passa pela trava aqui. p_vaga_interno (opcional): o identificador interno da vaga na Empregare, gravado em CO_VAGA_INTERNO quando válido (mesmo com a trava). Só service_role.';

--
-- Name: finalizar_conferencia(text, text[], text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalizar_conferencia(p_execucao text, p_conferencias text[], p_falhas text[] DEFAULT '{}'::text[], p_erro text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_mensagem text := nullif(left(btrim(coalesce(p_erro, '')), 2000), '');
  v_conferencias text[] := coalesce(p_conferencias, '{}');
  v_falhas text[] := coalesce(p_falhas, '{}');
  v_resolvidos integer := 0;
  v_abertos integer;
  v_situacao text;
begin
  perform private."FC_EXIGIR_EXECUCAO_CONFERENCIA"(p_execucao);
  if exists (select 1 from unnest(v_conferencias || v_falhas) c where c is null or c !~ '^[A-Z][A-Z0-9_]{2,59}$') then
    raise exception 'Código de conferência inválido' using errcode = '22023';
  end if;
  if v_mensagem is not null and not private."FC_TEXTO_SEGURO_DO_AVISO"(v_mensagem) then
    v_mensagem := 'Erro geral (a mensagem foi omitida por parecer ter dado pessoal).';
  end if;

  -- Só conferência que rodou até o fim resolve: a que falhou deixa os avisos como estavam.
  if v_mensagem is null then
    update public."TB_AVISO_CONFERENCIA" set
      "TP_SITUACAO" = 'RESOLVIDO', "DT_RESOLUCAO" = now(),
      "CO_USUARIO_IGNORADO" = null, "DT_IGNORADO" = null, "DS_MOTIVO_IGNORADO" = null, "QT_OCORRENCIA_IGNORADA" = null
     where "CO_CONFERENCIA" = any (v_conferencias)
       and not ("CO_CONFERENCIA" = any (v_falhas))
       and "TP_SITUACAO" in ('ABERTO', 'IGNORADO')
       and "CO_EXECUCAO" <> p_execucao;
    get diagnostics v_resolvidos = row_count;
  end if;

  select count(*) into v_abertos from public."TB_AVISO_CONFERENCIA" a where a."TP_SITUACAO" = 'ABERTO';
  v_situacao := case
    when v_mensagem is not null then 'FALHOU'
    when cardinality(v_falhas) > 0 then 'PARCIAL'
    else 'CONCLUIDA' end;

  update public."TL_CONFERENCIA" set
    "TP_SITUACAO" = v_situacao, "DT_FIM" = now(),
    "DS_CONFERENCIA" = to_jsonb(v_conferencias), "DS_FALHA" = to_jsonb(v_falhas),
    "QT_AVISO_ABERTO" = v_abertos, "QT_AVISO_RESOLVIDO" = v_resolvidos, "DS_MENSAGEM" = v_mensagem
   where "CO_EXECUCAO" = p_execucao;

  return jsonb_build_object(
    'situacao', v_situacao, 'abertos', v_abertos, 'resolvidos', v_resolvidos,
    'novos', (select c."QT_AVISO_NOVO" from public."TL_CONFERENCIA" c where c."CO_EXECUCAO" = p_execucao));
end;
$_$;

--
-- Name: FUNCTION finalizar_conferencia(p_execucao text, p_conferencias text[], p_falhas text[], p_erro text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalizar_conferencia(p_execucao text, p_conferencias text[], p_falhas text[], p_erro text) IS 'Fecha a execução das conferências: os avisos abertos ou ignorados das conferências que rodaram até o fim e não foram achados de novo viram RESOLVIDO; com p_erro, nada é resolvido e a execução FALHOU; com falhas, PARCIAL. Só service_role.';

--
-- Name: finalizar_pre_classificacao(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalizar_pre_classificacao(p_execucao text, p_editais jsonb DEFAULT '[]'::jsonb, p_erro text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_exec public."TL_PRE_CLASSIFICACAO" := private."FC_EXIGIR_EXECUCAO_PRECLASSIF"(p_execucao);
  v_mensagem text := nullif(left(btrim(coalesce(p_erro, '')), 2000), '');
  v_editais jsonb := coalesce(p_editais, '[]'::jsonb);
  v_situacao text;
begin
  if jsonb_typeof(v_editais) <> 'array' or jsonb_array_length(v_editais) > 500
     or exists (select 1 from jsonb_array_elements(v_editais) e
                 where jsonb_typeof(e) <> 'object'
                    or coalesce(e ->> 'edital', '') !~ '^[0-9a-f-]{36}$'
                    or coalesce(e ->> 'situacao', '') !~ '^[A-Z][A-Z_]{1,29}$'
                    or length(e::text) > 4000
                    -- O id do edital (uuid) pode ter 11 dígitos seguidos: confere o resto.
                    or not private."FC_TEXTO_SEGURO_DO_AVISO"((e - 'edital')::text)) then
    raise exception 'Resultado por edital inválido (até 500, com edital, situação e só códigos e contagens)' using errcode = '22023';
  end if;
  if v_mensagem is not null and not private."FC_TEXTO_SEGURO_DO_AVISO"(v_mensagem) then
    v_mensagem := 'Erro geral (a mensagem foi omitida por parecer ter dado pessoal).';
  end if;
  v_situacao := case
    when v_mensagem is not null then 'FALHOU'
    when exists (select 1 from jsonb_array_elements(v_editais) e where e ->> 'situacao' = 'FALHOU') then 'PARCIAL'
    else 'CONCLUIDA' end;

  update public."TL_PRE_CLASSIFICACAO" t set
    "TP_SITUACAO" = v_situacao, "DT_FIM" = now(), "DS_MENSAGEM" = v_mensagem, "DS_EDITAL" = v_editais,
    "QT_EDITAL" = (select count(*) from jsonb_array_elements(v_editais) e where e ->> 'situacao' = 'PROCESSADO'),
    "QT_VAGA" = r.vagas, "QT_INSCRITO" = r.inscritos, "QT_ELIMINADO" = r.eliminados,
    "QT_RANQUEADO" = r.ranqueados, "QT_LOTE" = r.lote, "QT_DIVERGENCIA" = r.divergencias
    from (select count(*)::integer as vagas, coalesce(sum(v."QT_INSCRITO"), 0)::integer as inscritos,
                 coalesce(sum(v."QT_ELIMINADO"), 0)::integer as eliminados, coalesce(sum(v."QT_RANQUEADO"), 0)::integer as ranqueados,
                 coalesce(sum(v."QT_LOTE"), 0)::integer as lote, coalesce(sum(v."QT_DIVERGENCIA"), 0)::integer as divergencias
            from public."TB_PRE_CLASSIF_VAGA" v where v."CO_EXECUCAO" = p_execucao) r
   where t."CO_EXECUCAO" = v_exec."CO_EXECUCAO";

  return (select jsonb_build_object('situacao', t."TP_SITUACAO", 'editais', t."QT_EDITAL", 'vagas', t."QT_VAGA",
                                    'inscritos', t."QT_INSCRITO", 'lote', t."QT_LOTE")
            from public."TL_PRE_CLASSIFICACAO" t where t."CO_EXECUCAO" = p_execucao);
end;
$_$;

--
-- Name: FUNCTION finalizar_pre_classificacao(p_execucao text, p_editais jsonb, p_erro text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalizar_pre_classificacao(p_execucao text, p_editais jsonb, p_erro text) IS 'Fecha a execução da pré-classificação: o resultado por edital (só códigos e contagens; recusa texto com @ ou CPF), as contagens somadas das vagas gravadas nesta execução e a situação (FALHOU com p_erro; PARCIAL se algum edital falhou; CONCLUIDA). Só service_role.';

--
-- Name: finalizar_sync_analises_incremental(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalizar_sync_analises_incremental(p_sync_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '30s'
    SET lock_timeout TO '2s'
    SET work_mem TO '8MB'
    SET jit TO 'off'
    AS $$
declare
  v_cursor integer:=0;
  v_max integer:=0;
  v_total_staging integer:=0;
  v_esperado integer:=0;
  v_total_fato integer:=0;
  v_total_editais integer:=0;
  v_editais_upsert integer:=0;
  v_editais_inativados integer:=0;
  v_editais_monitora integer:=0;
  v_removido integer:=0;
  v_total_ativos_local integer:=0;
  v_result jsonb;
  v_planilha text;
  v_conflitos integer:=0;
  v_duplicadas integer:=0;
  v_ausentes jsonb;
begin
  if p_sync_id is null then raise exception 'p_sync_id obrigatorio'; end if;
  -- [por-planilha]
  v_planilha := public."FC_PLANILHA_DO_SYNC_ANALISE"(p_sync_id);
  if v_planilha is null then raise exception 'Sync incremental nao esta pronto para finalizacao.'; end if;
  if not pg_try_advisory_xact_lock(hashtext('public.processar_sync_analises:'||v_planilha)::bigint) then
    raise exception 'Outro processamento de analises esta em andamento.';
  end if;

  select coalesce(nullif(resultado->>'lote_cursor','')::integer,0),
         coalesce(linhas_staging,0),
         coalesce(nullif(resultado->>'incremental_total_ativos_local','')::integer,0)
    into v_cursor,v_esperado,v_total_ativos_local
  from public."TL_SYNC_ANALISE"
  where sync_id=p_sync_id and modo='INCREMENTAL_ACTIVE' and status in ('carregado','processando')
    and coalesce((resultado->>'incremental_preparado')::boolean,false)=true
  order by id desc limit 1;
  if not found then raise exception 'Sync incremental nao esta pronto para finalizacao.'; end if;

  select coalesce(max(linha_origem) filter(where entidade='FATO_ANALISES'),0),
         count(*)::integer,
         count(*) filter(where entidade='FATO_ANALISES')::integer,
         count(*) filter(where entidade='DIM_EDITAIS')::integer
    into v_max,v_total_staging,v_total_fato,v_total_editais
  from public."TM_ANALISE_CURRICULAR"
  where sync_id=p_sync_id;

  if v_total_staging <> v_esperado then raise exception 'Staging incremental divergente: esperado %, encontrado %.',v_esperado,v_total_staging; end if;
  if v_cursor < v_max then raise exception 'Ainda existem linhas FATO incrementais pendentes: cursor %, max %.',v_cursor,v_max; end if;
  if v_total_editais < 1 then raise exception 'DIM_EDITAIS ausente no incremental.'; end if;

  -- [por-planilha] porteiro antes de gravar editais.
  perform public."FC_VALIDAR_GRUPO_STAGING_ANALISE"(p_sync_id, v_planilha);

  create temporary table tmp_editais_incremental on commit drop as
  with x as (
    select s.id,s.linha_origem,
      public.jsonb_text_or_null(s.payload,'grupo') as grupo,
      coalesce(public.jsonb_text_or_null(s.payload,'unidade'),'Nao informada') as unidade,
      coalesce(public.jsonb_text_or_null(s.payload,'edital'),'Sem edital') as edital,
      coalesce(public.jsonb_bool_or_null(s.payload,'ativo'),true) as ativo,
      public.jsonb_date_or_null(s.payload,'data_inicio_analise') as data_inicio_analise,
      public.jsonb_date_or_null(s.payload,'data_fim_analise') as data_fim_analise
    from public."TM_ANALISE_CURRICULAR" s
    where s.sync_id=p_sync_id and s.entidade='DIM_EDITAIS'
  ), ranked as (
    select *,row_number() over(partition by coalesce(public.analises_norm_key(grupo),''),coalesce(public.analises_norm_key(unidade),''),coalesce(public.analises_norm_key(edital),'') order by coalesce(linha_origem,2147483647),id) rn
    from x
  )
  select grupo,unidade,edital,ativo,data_inicio_analise,data_fim_analise
  from ranked where rn=1;

  -- [monitora] o edital com a avaliação no MONITORA não é cadastrado nem mudado pela planilha.
  delete from tmp_editais_incremental x where public."FC_EDITAL_ANALISE_NO_MONITORA"(v_planilha, x.edital);
  get diagnostics v_editais_monitora=row_count;

  -- [por-planilha] edital já cadastrado por outra planilha: recusa.
  select count(*)::integer into v_conflitos
  from public."TB_EDITAL_ANALISE" e
  join tmp_editais_incremental x
    on e.grupo_norm=coalesce(public.analises_norm_key(x.grupo),'')
   and e.unidade_norm=coalesce(public.analises_norm_key(x.unidade),'')
   and e.edital_norm=coalesce(public.analises_norm_key(x.edital),'')
  where e."CO_PLANILHA"<>v_planilha;
  if v_conflitos>0 then
    raise exception 'Sync % recusado: % edital(is) do envio ja pertencem a outra planilha.',p_sync_id,v_conflitos
      using errcode = '22023';
  end if;

  insert into public."TB_EDITAL_ANALISE"(grupo,unidade,edital,ativo,data_inicio_analise,data_fim_analise,"CO_PLANILHA")
  select grupo,unidade,edital,ativo,data_inicio_analise,data_fim_analise,v_planilha
  from tmp_editais_incremental
  -- Pela chave normalizada (uq_analises_editais_norm): "DSEI  Parintins" e
  -- "DSEI Parintins" são o mesmo edital; o texto passa a ser o da planilha.
  on conflict(grupo_norm,unidade_norm,edital_norm) do update set
    grupo=excluded.grupo,
    unidade=excluded.unidade,
    edital=excluded.edital,
    ativo=excluded.ativo,
    data_inicio_analise=excluded.data_inicio_analise,
    data_fim_analise=excluded.data_fim_analise,
    updated_at=now()
  where "TB_EDITAL_ANALISE"."CO_PLANILHA"=excluded."CO_PLANILHA"
    -- Só o edital que mudou (20261007220000): regravar os iguais a cada sync
    -- gerava WAL e remontava o painel de análises à toa.
    and ("TB_EDITAL_ANALISE".grupo,"TB_EDITAL_ANALISE".unidade,"TB_EDITAL_ANALISE".edital,
         "TB_EDITAL_ANALISE".ativo,"TB_EDITAL_ANALISE".data_inicio_analise,"TB_EDITAL_ANALISE".data_fim_analise)
        is distinct from
        (excluded.grupo,excluded.unidade,excluded.edital,
         excluded.ativo,excluded.data_inicio_analise,excluded.data_fim_analise);
  get diagnostics v_editais_upsert=row_count;

  -- [por-planilha] só desativa editais desta planilha.
  -- [monitora] nem o edital com a avaliação no MONITORA.
  update public."TB_EDITAL_ANALISE" e
  set ativo=false,updated_at=now()
  where e.ativo is true
    and e."CO_PLANILHA"=v_planilha
    and not public."FC_EDITAL_ANALISE_NO_MONITORA"(v_planilha, e.edital)
    and not exists(select 1 from tmp_editais_incremental x
      where e.grupo_norm=coalesce(public.analises_norm_key(x.grupo),'')
        and e.unidade_norm=coalesce(public.analises_norm_key(x.unidade),'')
        and e.edital_norm=coalesce(public.analises_norm_key(x.edital),''));
  get diagnostics v_editais_inativados=row_count;

  -- [por-planilha] Mesmo candidato (id_origem) duas vezes na mesma vaga e edital:
  -- fica ativo só o registro mais recente. O incremental só envia o que mudou;
  -- quando o nome é corrigido na planilha, a chave natural muda, entra um
  -- registro novo e o antigo ficava ativo como "Pendente" (14 casos em 30/09).
  -- [monitora] a linha publicada pela ficha não entra nessa conta.
  with r as (
    select a.id,
           row_number() over (partition by a.edital_norm, a.codigo_vaga, a.id_origem
                              order by a.updated_at desc, a.id desc) as rn
      from public."TB_ANALISE_CURRICULAR" a
     where a.ativo
       and a."CO_PLANILHA" = v_planilha
       and a."TP_ORIGEM_REGISTRO" = 'PLANILHA'
       and nullif(btrim(a.id_origem), '') is not null
       and nullif(btrim(a.codigo_vaga), '') is not null
  )
  update public."TB_ANALISE_CURRICULAR" a
     set ativo = false, updated_at = now()
    from r
   where a.id = r.id and r.rn > 1;
  get diagnostics v_duplicadas=row_count;

  -- Quem saiu da planilha (manifesto da comparação): ver 20261001140000.
  v_ausentes := public."FC_DESATIVAR_AUSENTES_DA_PLANILHA"(p_sync_id, v_planilha, v_total_ativos_local);
  delete from public."TM_MANIFESTO_ANALISE" where "CO_SYNC" = p_sync_id or "DT_CRIACAO" < now() - interval '2 days';

  delete from public."TM_ANALISE_CURRICULAR" where sync_id=p_sync_id;
  get diagnostics v_removido=row_count;

  v_result=jsonb_build_object(
    'ok',true,
    'sync_id',p_sync_id,
    'modo_processamento','incremental',
    'planilha',v_planilha,
    'total_ativos_local',v_total_ativos_local,
    'fato_analises_enviadas',v_total_fato,
    'analises_editais_recebidos',v_total_editais,
    'analises_editais_upsert',v_editais_upsert,
    'analises_editais_inativados',v_editais_inativados,
    'analises_editais_monitora_ignorados',v_editais_monitora,
    'staging',v_total_staging,
    'staging_removido',v_removido,
    'historico_inativado',coalesce((v_ausentes->>'desativadas')::integer,0),
    'ausentes',v_ausentes,
    'analises_duplicadas_inativadas',v_duplicadas
  );

  update public."TL_SYNC_ANALISE"
  set status='processado',resultado=v_result,erro=null,total_processados=v_total_fato,
      finished_at=now(),updated_at=now()
  where sync_id=p_sync_id and modo='INCREMENTAL_ACTIVE';

  return v_result;
end;
$$;

--
-- Name: finalizar_sync_analises_lotes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalizar_sync_analises_lotes(p_sync_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    SET statement_timeout TO '30s'
    SET lock_timeout TO '2s'
    SET work_mem TO '8MB'
    SET jit TO 'off'
    AS $$
declare
  v_cursor integer:=0;
  v_max integer:=0;
  v_total_staging integer:=0;
  v_total_fato integer:=0;
  v_total_editais integer:=0;
  v_normalizados integer:=0;
  v_inativados integer:=0;
  v_editais integer:=0;
  v_editais_inativados integer:=0;
  v_editais_monitora integer:=0;
  v_removido integer:=0;
  v_alteradas integer:=0;
  v_result jsonb;
  v_planilha text;
  v_conflitos integer:=0;
  v_modo text;
begin
  if p_sync_id is null then raise exception 'p_sync_id obrigatorio'; end if;
  -- [por-planilha]
  v_planilha := public."FC_PLANILHA_DO_SYNC_ANALISE"(p_sync_id);
  if v_planilha is null then raise exception 'Sync % nao esta em processamento por lotes.',p_sync_id; end if;
  if not pg_try_advisory_xact_lock(hashtext('public.processar_sync_analises:'||v_planilha)::bigint) then
    raise exception 'Outro processamento de analises ja esta em andamento.';
  end if;

  select coalesce(nullif(resultado->>'lote_cursor','')::integer,0),
         coalesce(nullif(resultado->>'lote_alteradas','')::integer,0),
         modo
    into v_cursor,v_alteradas,v_modo
  from public."TL_SYNC_ANALISE"
  where sync_id=p_sync_id and status='processando'
  order by id desc limit 1;
  if not found then raise exception 'Sync % nao esta em processamento por lotes.',p_sync_id; end if;

  -- [so-full] (20261022140000) A finalização FULL desativa o que não está no staging. Num sync
  -- INCREMENTAL_ACTIVE o staging tem só as linhas alteradas: finalizar como FULL desativaria o
  -- resto da planilha. O incremental finaliza por finalizar_sync_analises_incremental.
  if coalesce(v_modo, 'FULL') <> 'FULL' then
    raise exception 'Sync % é % e não é finalizado pelo fluxo FULL (finalizar_sync_analises_lotes). O incremental usa finalizar_sync_analises_incremental.', p_sync_id, v_modo
      using errcode = '22023';
  end if;

  select coalesce(max(linha_origem) filter(where entidade='FATO_ANALISES'),0),
         count(*)::integer,
         count(*) filter(where entidade='FATO_ANALISES')::integer,
         count(*) filter(where entidade='DIM_EDITAIS')::integer
    into v_max,v_total_staging,v_total_fato,v_total_editais
  from public."TM_ANALISE_CURRICULAR"
  where sync_id=p_sync_id;

  if v_cursor<v_max then
    raise exception 'Ainda existem linhas FATO pendentes: cursor %, max %.',v_cursor,v_max;
  end if;

  -- [por-planilha] porteiro antes de qualquer desativação.
  perform public."FC_VALIDAR_GRUPO_STAGING_ANALISE"(p_sync_id, v_planilha);

  create temporary table tmp_keys on commit drop as
  select distinct public.analises_make_chave_natural(
    public.jsonb_text_or_null(s.payload,'grupo'),
    coalesce(public.jsonb_text_or_null(s.payload,'unidade'),'Nao informada'),
    coalesce(public.jsonb_text_or_null(s.payload,'edital'),'Sem edital'),
    public.jsonb_text_or_null(s.payload,'codigo_vaga'),
    public.jsonb_text_or_null(s.payload,'id'),
    public.jsonb_text_or_null(s.payload,'candidato')) as chave_natural
  from public."TM_ANALISE_CURRICULAR" s
  where s.sync_id=p_sync_id and s.entidade='FATO_ANALISES';

  select count(*)::integer into v_normalizados from tmp_keys;
  create unique index tmp_keys_idx on tmp_keys(chave_natural);
  analyze tmp_keys;

  -- [por-planilha] só desativa análises desta planilha.
  -- [monitora] nunca a linha publicada pela ficha (TP_ORIGEM_REGISTRO MONITORA).
  update public."TB_ANALISE_CURRICULAR" a
  set ativo=false,updated_at=now()
  where a.ativo is true
    and a."CO_PLANILHA"=v_planilha
    and a."TP_ORIGEM_REGISTRO"='PLANILHA'
    and not private."FC_ANALISE_EH_TREINAMENTO"(a.origem_planilha)
    and not exists(select 1 from tmp_keys k where k.chave_natural=a.chave_natural);
  get diagnostics v_inativados=row_count;

  create temporary table tmp_editais on commit drop as
  with x as (
    select s.id,s.linha_origem,
      public.jsonb_text_or_null(s.payload,'grupo') as grupo,
      coalesce(public.jsonb_text_or_null(s.payload,'unidade'),'Nao informada') as unidade,
      coalesce(public.jsonb_text_or_null(s.payload,'edital'),'Sem edital') as edital,
      coalesce(public.jsonb_bool_or_null(s.payload,'ativo'),true) as ativo,
      public.jsonb_date_or_null(s.payload,'data_inicio_analise') as data_inicio_analise,
      public.jsonb_date_or_null(s.payload,'data_fim_analise') as data_fim_analise
    from public."TM_ANALISE_CURRICULAR" s
    where s.sync_id=p_sync_id and s.entidade='DIM_EDITAIS'
  ), ranked as (
    select *,row_number() over(partition by grupo,unidade,edital order by coalesce(linha_origem,2147483647),id) rn
    from x
  )
  select grupo,unidade,edital,ativo,data_inicio_analise,data_fim_analise
  from ranked where rn=1;

  -- [monitora] o edital com a avaliação no MONITORA não é cadastrado nem mudado pela planilha.
  delete from tmp_editais x where public."FC_EDITAL_ANALISE_NO_MONITORA"(v_planilha, x.edital);
  get diagnostics v_editais_monitora=row_count;

  if v_total_editais>0 then
    -- [por-planilha] edital já cadastrado por outra planilha: recusa.
    select count(*)::integer into v_conflitos
    from public."TB_EDITAL_ANALISE" e
    join tmp_editais x
      on e.grupo_norm=coalesce(public.analises_norm_key(x.grupo),'')
     and e.unidade_norm=coalesce(public.analises_norm_key(x.unidade),'')
     and e.edital_norm=coalesce(public.analises_norm_key(x.edital),'')
    where e."CO_PLANILHA"<>v_planilha;
    if v_conflitos>0 then
      raise exception 'Sync % recusado: % edital(is) do envio ja pertencem a outra planilha.',p_sync_id,v_conflitos
        using errcode = '22023';
    end if;

    insert into public."TB_EDITAL_ANALISE"(grupo,unidade,edital,ativo,data_inicio_analise,data_fim_analise,"CO_PLANILHA")
    select grupo,unidade,edital,ativo,data_inicio_analise,data_fim_analise,v_planilha
    from tmp_editais
    on conflict(grupo,unidade,edital) do update set
      ativo=excluded.ativo,
      data_inicio_analise=excluded.data_inicio_analise,
      data_fim_analise=excluded.data_fim_analise,
      updated_at=now()
    where "TB_EDITAL_ANALISE"."CO_PLANILHA"=excluded."CO_PLANILHA";
    get diagnostics v_editais=row_count;

    -- [por-planilha] só desativa editais desta planilha.
    -- [monitora] nem o edital com a avaliação no MONITORA.
    update public."TB_EDITAL_ANALISE" e
    set ativo=false,updated_at=now()
    where e.ativo is true
      and e."CO_PLANILHA"=v_planilha
      and not public."FC_EDITAL_ANALISE_NO_MONITORA"(v_planilha, e.edital)
      and not exists(select 1 from tmp_editais x
        where e.grupo is not distinct from x.grupo
          and e.unidade=x.unidade
          and e.edital=x.edital);
    get diagnostics v_editais_inativados=row_count;
  end if;

  delete from public."TM_ANALISE_CURRICULAR" where sync_id=p_sync_id;
  get diagnostics v_removido=row_count;

  v_result=jsonb_build_object(
    'ok',true,
    'sync_id',p_sync_id,
    'modo_processamento','lotes',
    'planilha',v_planilha,
    'staging',v_total_staging,
    'fato_analises_recebidas',v_total_fato,
    'fato_analises_normalizadas',v_normalizados,
    'fato_analises_upsert',v_alteradas,
    'fato_analises_inativadas',v_inativados,
    'analises_editais_recebidos',v_total_editais,
    'analises_editais_upsert',v_editais,
    'analises_editais_inativados',v_editais_inativados,
    'analises_editais_monitora_ignorados',v_editais_monitora,
    'staging_removido',v_removido);

  update public."TL_SYNC_ANALISE"
  set status='processado',
      resultado=v_result,
      erro=null,
      total_processados=v_normalizados,
      finished_at=now(),
      updated_at=now()
  where sync_id=p_sync_id;

  return v_result;
end;
$$;

--
-- Name: finalizar_sync_empregare(text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalizar_sync_empregare(p_sync text, p_vagas_baixadas integer, p_vagas_falha integer, p_erro text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_sync public."TL_SYNC_EMPREGARE";
  v_situacao text;
  v_mensagem text := nullif(left(btrim(coalesce(p_erro, '')), 2000), '');
  v_incompletas integer;
begin
  perform private."FC_EMPREGARE_EXIGIR_SYNC"(p_sync);
  if coalesce(p_vagas_baixadas, -1) < 0 or coalesce(p_vagas_falha, -1) < 0 then
    raise exception 'Contagens de vagas inválidas' using errcode = '22023';
  end if;

  -- Vaga que ficou no meio (a execução caiu entre um lote e o fechamento): nada foi desativado nela.
  update public."TB_EMPREGARE_VAGA" set
    "TP_SITUACAO" = 'INCOMPLETA', "DT_ATUALIZACAO" = now(),
    "DS_MENSAGEM" = 'A execução terminou no meio da vaga: ninguém foi desativado.'
   where "CO_SYNC" = p_sync and "TP_SITUACAO" = 'EM_CARGA';
  get diagnostics v_incompletas = row_count;

  select * into v_sync from public."TL_SYNC_EMPREGARE" s where s."CO_SYNC" = p_sync for update;
  v_situacao := case
    when v_mensagem is not null then 'FALHOU'
    when v_sync."QT_VAGA_PEDIDA" > 0 and p_vagas_baixadas = 0 then 'FALHOU'
    when p_vagas_falha > 0 or v_sync."QT_VAGA_RECUSADA" > 0 or v_incompletas > 0 then 'PARCIAL'
    else 'CONCLUIDA' end;
  if v_situacao = 'FALHOU' and v_mensagem is null then
    v_mensagem := 'Nenhuma vaga foi baixada da Empregare.';
  end if;

  update public."TL_SYNC_EMPREGARE" set
    "TP_SITUACAO" = v_situacao, "DT_FIM" = now(),
    "QT_VAGA_BAIXADA" = p_vagas_baixadas, "QT_VAGA_FALHA" = p_vagas_falha,
    "DS_MENSAGEM" = coalesce(v_mensagem, case when v_sync."ST_FORCADA" = 'S' then 'Rodou com forçar.' end)
   where "CO_SYNC" = p_sync;

  return jsonb_build_object(
    'situacao', v_situacao, 'pedidas', v_sync."QT_VAGA_PEDIDA", 'baixadas', p_vagas_baixadas,
    'falhas', p_vagas_falha, 'recusadas', v_sync."QT_VAGA_RECUSADA", 'incompletas', v_incompletas,
    'linhas', v_sync."QT_LINHA", 'desativadas', v_sync."QT_DESATIVADA");
end;
$$;

--
-- Name: FUNCTION finalizar_sync_empregare(p_sync text, p_vagas_baixadas integer, p_vagas_falha integer, p_erro text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalizar_sync_empregare(p_sync text, p_vagas_baixadas integer, p_vagas_falha integer, p_erro text) IS 'Fecha a execução do robô da Empregare: CONCLUIDA, PARCIAL (falha, recusa ou vaga incompleta) ou FALHOU (p_erro, ou nada baixado). Vaga que ficou no meio vira INCOMPLETA, sem desativar ninguém. Só service_role.';

--
-- Name: finalizar_sync_entrevistas(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalizar_sync_entrevistas(p_sync text, p_area text, p_forcar boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '30s'
    AS $$
declare
  v_sync public."TL_SYNC_ENTREVISTA";
  v_ativas integer;
  v_desativadas integer;
  v_repetidas integer;
  v_ligadas integer;
  v_sem_analise integer;
  v_sem_edital integer;
begin
  select * into v_sync from public."TL_SYNC_ENTREVISTA" s where s."CO_SYNC" = p_sync for update;
  if v_sync."CO_SYNC" is null or v_sync."CO_AREA" <> p_area or v_sync."TP_SITUACAO" <> 'EM_ANDAMENTO' then
    raise exception 'Carga % não encontrada, de outra área ou já fechada', p_sync using errcode = '22023';
  end if;

  select count(*) into v_ativas from public."TB_ENTREVISTA" e
   where e."CO_AREA" = p_area and e."TP_ORIGEM" = 'planilha' and e."ST_ATIVO" = 'S';
  if not coalesce(p_forcar, false) and v_ativas > 0 and v_sync."QT_LINHA" * 2 < v_ativas then
    update public."TL_SYNC_ENTREVISTA" set "TP_SITUACAO" = 'RECUSADA', "DT_FIM" = now(),
      "DS_MENSAGEM" = format('Carga com %s linhas e %s ativas no banco: menos da metade. Nada foi desativado; confira a planilha ou rode com forçar.', v_sync."QT_LINHA", v_ativas)
     where "CO_SYNC" = p_sync;
    delete from private."TL_CHAVE_DA_CARGA" k
     where k."TP_CARGA" = 'ENTREVISTA'
       and not exists (select 1 from public."TL_SYNC_ENTREVISTA" t
                        where t."CO_SYNC" = k."CO_SYNC" and t."TP_SITUACAO" = 'EM_ANDAMENTO');
    return jsonb_build_object('situacao', 'RECUSADA', 'linhas', v_sync."QT_LINHA", 'ativas', v_ativas);
  end if;

  -- Sai quem não veio nesta carga (20261103150000): a linha que veio igual não é
  -- regravada (fica com o CO_SYNC antigo); a chave dela está em TL_CHAVE_DA_CARGA.
  update public."TB_ENTREVISTA" e set "ST_ATIVO" = 'N', "DT_ATUALIZACAO" = now()
   where e."CO_AREA" = p_area and e."TP_ORIGEM" = 'planilha' and e."ST_ATIVO" = 'S'
     and e."CO_SYNC" is distinct from p_sync
     and not exists (select 1 from private."TL_CHAVE_DA_CARGA" k
                      where k."TP_CARGA" = 'ENTREVISTA' and k."CO_SYNC" = p_sync
                        and k."DS_CHAVE_ORIGEM" = e."DS_CHAVE_ORIGEM");
  get diagnostics v_desativadas = row_count;

  -- Edital: número + área; com mais de um, o ATIVO e, entre eles, o da mesma unidade (20261022200000).
  with ent as materialized (
    select e."CO_ENTREVISTA", e."CO_MONITORAMENTO",
           private."FC_NUMERO_EDITAL"(e."DS_EDITAL") as num,
           private."FC_TEXTO_BUSCA_RECURSO"(e."NO_UNIDADE") as uni
      from public."TB_ENTREVISTA" e
     where e."CO_AREA" = p_area and e."ST_ATIVO" = 'S'
  ), m as materialized (
    select m1.id, private."FC_NUMERO_EDITAL"(m1.edital) as num,
           private."FC_TEXTO_BUSCA_RECURSO"(m1.unidade) as uni, m1.ativo
      from public."TB_MONITORAMENTO_INDIGENA" m1
     where m1."CO_AREA" = p_area
  ), alvo as (
    select distinct on (ent."CO_ENTREVISTA") ent."CO_ENTREVISTA", ent."CO_MONITORAMENTO" as atual, m.id
      from ent
      left join m on m.num = ent.num
     order by ent."CO_ENTREVISTA", m.ativo desc nulls last, (m.uni = ent.uni) desc nulls last
  )
  update public."TB_ENTREVISTA" e set "CO_MONITORAMENTO" = alvo.id
    from alvo
   where e."CO_ENTREVISTA" = alvo."CO_ENTREVISTA"
     and alvo.atual is distinct from alvo.id;

  -- Análise: código do candidato + vaga; senão nome sem acento + vaga.
  with ent as materialized (
    select e."CO_ENTREVISTA", e."CO_ANALISE_CURRICULAR" as atual, e."TP_LIGACAO_ANALISE" as modo_atual,
           e."CO_VAGA", e."CO_CANDIDATO",
           private."FC_NUMERO_EDITAL"(e."DS_EDITAL") as num,
           private."FC_TEXTO_BUSCA_RECURSO"(e."NO_CANDIDATO") as nome
      from public."TB_ENTREVISTA" e
     where e."CO_AREA" = p_area and e."ST_ATIVO" = 'S'
  ), an as materialized (
    select a.id, a.codigo_vaga, a.id_origem, a.ativo,
           private."FC_NUMERO_EDITAL"(a.edital) as num,
           private."FC_TEXTO_BUSCA_RECURSO"(a.candidato) as nome
      from public."TB_ANALISE_CURRICULAR" a
     where a."CO_AREA" = p_area
       and a.codigo_vaga in (select distinct ent."CO_VAGA" from ent)
  ), cand as (
    select ent."CO_ENTREVISTA", an.id,
           case when ent."CO_CANDIDATO" is not null and an.id_origem = ent."CO_CANDIDATO" then 'codigo' else 'nome' end as modo,
           an.num = ent.num as mesmo_edital, an.ativo
      from ent
      join an on an.codigo_vaga = ent."CO_VAGA"
             and ((ent."CO_CANDIDATO" is not null and an.id_origem = ent."CO_CANDIDATO") or an.nome = ent.nome)
  ), melhor as (
    select distinct on (c."CO_ENTREVISTA") c."CO_ENTREVISTA", c.id, c.modo
      from cand c
     order by c."CO_ENTREVISTA", (c.modo = 'codigo') desc, c.mesmo_edital desc nulls last, c.ativo desc
  ), alvo as (
    select ent."CO_ENTREVISTA", ent.atual, ent.modo_atual, melhor.id, melhor.modo
      from ent left join melhor on melhor."CO_ENTREVISTA" = ent."CO_ENTREVISTA"
  )
  update public."TB_ENTREVISTA" e set "CO_ANALISE_CURRICULAR" = alvo.id, "TP_LIGACAO_ANALISE" = alvo.modo
    from alvo
   where e."CO_ENTREVISTA" = alvo."CO_ENTREVISTA"
     and (alvo.atual is distinct from alvo.id or alvo.modo_atual is distinct from alvo.modo);

  -- A linha da planilha cuja análise já tem a entrevista do sistema sai (20261022200000).
  v_repetidas := private."FC_DESATIVAR_ENTREVISTAS_REPETIDAS"(p_area, null, null);

  select count(*) filter (where e."CO_ANALISE_CURRICULAR" is not null),
         count(*) filter (where e."CO_ANALISE_CURRICULAR" is null),
         count(*) filter (where e."CO_MONITORAMENTO" is null)
    into v_ligadas, v_sem_analise, v_sem_edital
    from public."TB_ENTREVISTA" e
   where e."CO_AREA" = p_area and e."ST_ATIVO" = 'S';

  update public."TL_SYNC_ENTREVISTA" set
    "TP_SITUACAO" = 'CONCLUIDA', "DT_FIM" = now(),
    "QT_LIGADA_ANALISE" = v_ligadas, "QT_SEM_ANALISE" = v_sem_analise,
    "QT_SEM_EDITAL" = v_sem_edital, "QT_DESATIVADA" = v_desativadas + v_repetidas,
    "DS_MENSAGEM" = case when coalesce(p_forcar, false) then 'Fechada com forçar.' end
   where "CO_SYNC" = p_sync;

  -- As chaves só valem enquanto a carga está aberta.
  delete from private."TL_CHAVE_DA_CARGA" k
   where k."TP_CARGA" = 'ENTREVISTA'
     and not exists (select 1 from public."TL_SYNC_ENTREVISTA" t
                      where t."CO_SYNC" = k."CO_SYNC" and t."TP_SITUACAO" = 'EM_ANDAMENTO');

  return jsonb_build_object('situacao', 'CONCLUIDA', 'linhas', v_sync."QT_LINHA",
    'ligadas_analise', v_ligadas, 'sem_analise', v_sem_analise,
    'sem_edital', v_sem_edital, 'desativadas', v_desativadas, 'repetidas', v_repetidas);
end;
$$;

--
-- Name: FUNCTION finalizar_sync_entrevistas(p_sync text, p_area text, p_forcar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalizar_sync_entrevistas(p_sync text, p_area text, p_forcar boolean) IS 'Fecha uma carga de entrevistas: desativa (ST_ATIVO = N) o que saiu da planilha (CO_SYNC diferente e chave fora de TL_CHAVE_DA_CARGA, 20261103150000), liga edital e análise, grava os totais no log e apaga as chaves das cargas fechadas. Recusa carga com menos da metade das linhas ativas sem p_forcar. Só service_role.';

--
-- Name: finalizar_sync_selecao(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalizar_sync_selecao(p_sync text, p_forcar boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_sync public."TL_SYNC_SELECAO";
  v_ativas integer;
  v_desativadas integer;
  v_sem_edital integer;
  v_kpis integer;
begin
  select * into v_sync from public."TL_SYNC_SELECAO" s where s."CO_SYNC" = p_sync for update;
  if v_sync."CO_SYNC" is null or v_sync."TP_SITUACAO" <> 'EM_ANDAMENTO' then
    raise exception 'Carga % não encontrada ou já fechada', p_sync using errcode = '22023';
  end if;

  select count(*) into v_ativas from public."TB_SELECAO_VAGA" s where s."ST_REGISTRO_ATIVO" = 'S';
  if not coalesce(p_forcar, false) and v_ativas > 0 and v_sync."QT_LINHA" * 2 < v_ativas then
    update public."TL_SYNC_SELECAO" set "TP_SITUACAO" = 'RECUSADA', "DT_FIM" = now(),
      "DS_MENSAGEM" = format('Carga com %s linhas e %s ativas no banco: menos da metade. Nada foi desativado; confira a planilha ou rode com forçar.', v_sync."QT_LINHA", v_ativas)
     where "CO_SYNC" = p_sync;
    delete from private."TL_CHAVE_DA_CARGA" k
     where k."TP_CARGA" = 'SELECAO'
       and not exists (select 1 from public."TL_SYNC_SELECAO" t
                        where t."CO_SYNC" = k."CO_SYNC" and t."TP_SITUACAO" = 'EM_ANDAMENTO');
    return jsonb_build_object('situacao', 'RECUSADA', 'linhas', v_sync."QT_LINHA", 'ativas', v_ativas);
  end if;

  -- Sai quem não veio nesta carga (20261103150000): a linha que veio igual não é
  -- regravada (fica com o CO_SYNC antigo); a chave dela está em TL_CHAVE_DA_CARGA.
  update public."TB_SELECAO_VAGA" s set "ST_REGISTRO_ATIVO" = 'N', "DT_ATUALIZACAO" = now()
   where s."ST_REGISTRO_ATIVO" = 'S' and s."CO_SYNC" is distinct from p_sync
     and not exists (select 1 from private."TL_CHAVE_DA_CARGA" k
                      where k."TP_CARGA" = 'SELECAO' and k."CO_SYNC" = p_sync
                        and k."DS_CHAVE_ORIGEM" = s."DS_CHAVE_ORIGEM");
  get diagnostics v_desativadas = row_count;

  perform private."FC_LIGAR_SELECAO_AOS_EDITAIS"();

  select count(*) filter (where s."CO_MONITORAMENTO" is null) into v_sem_edital
    from public."TB_SELECAO_VAGA" s where s."ST_REGISTRO_ATIVO" = 'S';

  -- Os KPIs da Visão geral já com a carga nova (o mesmo lock do pg_cron).
  if pg_try_advisory_xact_lock(hashtext('agsus_kpis_do_edital_pela_selecao')) then
    v_kpis := private."FC_ATUALIZAR_KPIS_PELA_SELECAO"();
  end if;

  update public."TL_SYNC_SELECAO" set
    "TP_SITUACAO" = 'CONCLUIDA', "DT_FIM" = now(),
    "QT_SEM_EDITAL" = v_sem_edital, "QT_DESATIVADA" = v_desativadas,
    "DS_MENSAGEM" = case when coalesce(p_forcar, false) then 'Fechada com forçar.' end
   where "CO_SYNC" = p_sync;

  -- As chaves só valem enquanto a carga está aberta.
  delete from private."TL_CHAVE_DA_CARGA" k
   where k."TP_CARGA" = 'SELECAO'
     and not exists (select 1 from public."TL_SYNC_SELECAO" t
                      where t."CO_SYNC" = k."CO_SYNC" and t."TP_SITUACAO" = 'EM_ANDAMENTO');

  return jsonb_build_object('situacao', 'CONCLUIDA', 'linhas', v_sync."QT_LINHA",
    'sem_edital', v_sem_edital, 'desativadas', v_desativadas, 'kpis', v_kpis);
end;
$$;

--
-- Name: FUNCTION finalizar_sync_selecao(p_sync text, p_forcar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalizar_sync_selecao(p_sync text, p_forcar boolean) IS 'Fecha uma carga da aba Seleção: desativa (ST_REGISTRO_ATIVO = N) o que saiu da planilha (CO_SYNC diferente e chave fora de TL_CHAVE_DA_CARGA, 20261103150000), liga o edital e acerta a área (FC_LIGAR_SELECAO_AOS_EDITAIS: DSEI/CASAI só na Saúde Indígena), recalcula os KPIs dos editais (FC_ATUALIZAR_KPIS_PELA_SELECAO), grava os totais no log e apaga as chaves das cargas fechadas. Recusa carga com menos da metade das linhas ativas sem p_forcar. Só service_role.';

--
-- Name: fn_registrar_historico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_registrar_historico() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_usuario_id    uuid;
  v_usuario_email text;
  v_evento        text;
begin
  v_usuario_id := auth.uid();

  if v_usuario_id is not null then
    select u.email
      into v_usuario_email
    from auth.users u
    where u.id = v_usuario_id
    limit 1;
  end if;

  if TG_OP = 'INSERT' then
    v_evento := 'criado';

    insert into public."TH_MONITORAMENTO"
      (id_registro, usuario_id, usuario_email, evento, snapshot_json)
    values
      (NEW.id, v_usuario_id, v_usuario_email, v_evento, to_jsonb(NEW));

  elsif TG_OP = 'UPDATE' then
    if OLD is distinct from NEW then
      v_evento := case
        when NEW.ativo = false and OLD.ativo = true then 'desativado'
        else 'atualizado'
      end;

      insert into public."TH_MONITORAMENTO"
        (id_registro, usuario_id, usuario_email, evento, snapshot_json)
      values
        (NEW.id, v_usuario_id, v_usuario_email, v_evento, to_jsonb(NEW));
    end if;
  end if;

  return NEW;
end;
$$;

--
-- Name: get_analise_detalhe_do_painel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analise_detalhe_do_painel(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $_$
declare
  v_id uuid;
  v_analise text;
  v_chave text;
  v_grupo_norm text;
  v_origem text;
  v_area text;
  v_detalhe jsonb;
  v_ficha uuid;
  v_espelho jsonb;
begin
  if not (private.pode_recurso('analises')) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;

  select a.id, a.analise, a.chave_natural, a.grupo_norm, a."TP_ORIGEM_REGISTRO"
    into v_id, v_analise, v_chave, v_grupo_norm, v_origem
    from public."TB_ANALISE_CURRICULAR" a
   where a.id = p_id;

  if not found then
    return null;
  end if;

  select ar."CO_AREA" into v_area
    from public."TB_AREA" ar
   where public.analises_norm_key(ar."NO_GRUPO_PLANILHA") = v_grupo_norm;

  if not (private.is_master() or (v_area is not null and private."FC_PODE_AREA"(v_area)
      and (private."FC_EDITAIS_VISIVEIS"() is null or exists (
        select 1 from public."TB_ANALISE_CURRICULAR" x
         where x.id = v_id
           and (x.edital_norm = any (private."FC_EDITAIS_NORM_VISIVEIS"())
                or x.unidade_norm = any (private."FC_UNIDADES_NORM_VISIVEIS"())))))) then
    raise exception 'Sem permissão para as análises desta área' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'grupo', v.grupo,
    'nota_final_ajustada', v.nota_final_ajustada,
    'pontuacao_escolaridade', v.pontuacao_escolaridade,
    'pontuacao_cursos_aperfeicoamento', v.pontuacao_cursos_aperfeicoamento,
    'pontuacao_experiencia_profissional', v.pontuacao_experiencia_profissional,
    'pontuacao_criterio_etnico', v.pontuacao_criterio_etnico,
    'experiencia_saude_indigena_total', v.experiencia_saude_indigena_total,
    'experiencia_atencao_basica_total', v.experiencia_atencao_basica_total,
    'experiencia_profissional_anos', ac.experiencia_profissional_anos,
    'experiencia_profissional_meses', ac.experiencia_profissional_meses,
    'experiencia_profissional_dias', ac.experiencia_profissional_dias,
    'experiencia_profissional_total', ac.experiencia_profissional_total,
    'link_pdf', v.link_pdf,
    'pdf_status', v.pdf_status,
    'erro_pdf', v.erro_pdf,
    'origem_arquivo_id', v.origem_arquivo_id,
    'data_inicio_analise', v.data_inicio_analise,
    'data_fim_analise', v.data_fim_analise,
    'data_validacao_status', v.data_validacao_status,
    'edital_status', v.edital_status,
    'updated_at', v.updated_at,
    'ultima_atualizacao', v.ultima_atualizacao
  )
  into v_detalhe
  from public."VW_ANALISES_DASHBOARD_BASE_TODOS" v
  join public."TB_ANALISE_CURRICULAR" ac on ac.id = v.id
  where v.id = v_id;

  -- A ficha da linha: a da chave natural da ficha, ou a que adotou a linha da planilha.
  if v_chave ~* '^monitora\|[0-9a-f-]{36}\|[0-9a-f-]{36}$' then
    select f."CO_FICHA_ANALISE" into v_ficha
      from public."TB_FICHA_ANALISE" f
     where f."CO_MONITORAMENTO" = split_part(v_chave, '|', 2)::uuid
       and f."CO_EMPREGARE_CANDIDATO" = split_part(v_chave, '|', 3)::uuid;
  elsif v_origem = 'MONITORA' then
    select f."CO_FICHA_ANALISE" into v_ficha
      from public."TB_ANALISE_CURRICULAR" a
      join public."TB_EMPREGARE_CANDIDATO" c on c."CO_CANDIDATO_EMPREGARE" = btrim(a.id_origem)
      join public."TB_FICHA_ANALISE" f
        on f."CO_EMPREGARE_CANDIDATO" = c."CO_EMPREGARE_CANDIDATO" and f."CO_VAGA" = a.codigo_vaga
      join public."TB_MONITORAMENTO_INDIGENA" m
        on m.id = f."CO_MONITORAMENTO" and m."CO_AREA" = a."CO_AREA"
     where a.id = v_id
       and private."FC_NUMERO_EDITAL"(m.edital) = private."FC_NUMERO_EDITAL"(a.edital)
     order by f."CO_FICHA_ANALISE"
     limit 1;
  end if;

  -- A entrada do espelho de nota (a mesma de obter_espelhos_de_nota), só da ficha concluída.
  if v_ficha is not null then
    select jsonb_build_object(
             'schema_version', 1,
             'ficha', jsonb_build_object(
               'id', f."CO_FICHA_ANALISE",
               'vaga', f."CO_VAGA",
               'art', pc."VL_ART",
               'resultado', f."TP_RESULTADO",
               'nota_final', f."VL_NOTA_FINAL",
               'regra', f."CO_REGRA_ANALISE" || ':' || f."NU_VERSAO_REGRA",
               'declarada', case when jsonb_typeof(f."DS_RESULTADO" -> 'declarada') = 'object'
                                 then f."DS_RESULTADO" -> 'declarada' else '{}'::jsonb end,
               'lancamento', private."FC_LANCAMENTO_DO_ESPELHO"(f."DS_LANCAMENTO")),
             'regra', h."DS_CONFIGURACAO",
             'documental', private."FC_DOCUMENTAL_DO_EDITAL"(f."CO_MONITORAMENTO"),
             'edital', jsonb_build_object('id', m.id, 'rotulo', private."FC_ROTULO_DO_EDITAL"(m.edital),
                                          'area', m."CO_AREA"))
      into v_espelho
      from public."TB_FICHA_ANALISE" f
      join public."TH_REGRA_ANALISE" h
        on h."CO_REGRA_ANALISE" = f."CO_REGRA_ANALISE" and h."NU_VERSAO" = f."NU_VERSAO_REGRA"
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = f."CO_MONITORAMENTO"
      left join public."TB_PRE_CLASSIFICACAO" pc
        on pc."CO_MONITORAMENTO" = f."CO_MONITORAMENTO" and pc."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
     where f."CO_FICHA_ANALISE" = v_ficha
       and f."TP_SITUACAO" = 'CONCLUIDA';
  end if;

  return coalesce(v_detalhe, '{}'::jsonb) || jsonb_build_object(
    'id', v_id,
    'area', v_area,
    'analise', v_analise,
    'chave_natural', v_chave,
    'espelho', v_espelho
  );
end;
$_$;

--
-- Name: FUNCTION get_analise_detalhe_do_painel(p_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_analise_detalhe_do_painel(p_id uuid) IS 'Detalhamento de uma linha do Painel das análises ao abrir a gaveta (parecer, pontuações, experiências, links, datas). Desde 20261020150000, "espelho": para a linha publicada pela ficha CONCLUÍDA da Avaliação documental (chave monitora|edital|candidato, ou a linha da planilha adotada), a entrada da montagem do espelho de nota (a mesma de obter_espelhos_de_nota: resultado, nota final, ART, declarada por critério, lançamento sem empregador nem nome de curso, configuração da versão da regra e documental do edital); null nas demais. Permissão: pode_recurso(analises) e a área/recorte da linha (42501). Não grava nada.';

--
-- Name: get_analises_dashboard_payload_v2(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analises_dashboard_payload_v2(p_scope text DEFAULT 'ativo'::text, p_area text DEFAULT 'saude-indigena'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    SET statement_timeout TO '15s'
    SET lock_timeout TO '3s'
    SET work_mem TO '64MB'
    SET jit TO 'off'
    AS $$
declare
  v_scope text := lower(btrim(coalesce(p_scope, 'ativo')));
  v_area text := lower(btrim(coalesce(p_area, 'saude-indigena')));
  v_area_nome text;
  v_grupo text;
  v_columns json := json_build_array(
    'id', 'unidade', 'edital', 'codigo_vaga', 'nome_vaga', 'candidato',
    'categoria', 'modalidade_concorrencia', 'status_consolidado', 'etapa',
    'responsavel_analise', 'data_analise', 'nota_final_ajustada',
    'pdf_status', 'tem_pdf'
  );
  v_cache private."TA_PAINEL_ANALISE";
  v_tem_cache boolean := false;
  v_hit boolean := false;
  v_rows json;
  v_editais json;
  v_total integer;
  v_atualizado_em timestamptz;
  v_gerado_em timestamptz := now();
begin
  if not (private.pode_recurso('analises')) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;

  -- "Todos" é montado no navegador com os três escopos.
  if v_scope not in ('ativo', 'inativo', 'desativadas') then
    raise exception 'Escopo invalido. Use ativo, inativo ou desativadas.';
  end if;

  -- Área válida e do usuário (ou admin): 22023/42501 antes de qualquer leitura.
  perform private."FC_GRUPOS_ANALISES_DA_AREA"(v_area);
  select a."NO_AREA", a."NO_GRUPO_PLANILHA" into v_area_nome, v_grupo
    from public."TB_AREA" a where a."CO_AREA" = v_area;

  -- Quem tem recorte por coordenação não usa o pronto (que é da área inteira).
  if private."FC_EDITAIS_VISIVEIS"() is null then
    select * into v_cache
      from private."TA_PAINEL_ANALISE" c
     where c."CO_AREA" = v_area and c."TP_ESCOPO" = v_scope;
    v_tem_cache := found;

    if v_tem_cache and v_cache."DT_GERACAO" > now() - interval '24 hours'
       and not private."FC_CACHE_DESATUALIZADO"('ANALISES', v_area) then
      -- Sempre entrega o guardado, mesmo de antes da última mudança: quem remonta
      -- é o agendamento (a cada 2 min, só a área com marca em TL_ALTERACAO_CACHE).
      v_hit := not private."FC_CACHE_DESATUALIZADO"('ANALISES', v_area);
    elsif pg_try_advisory_xact_lock(hashtext('painel_analise:' || v_area || ':' || v_scope)::bigint) then
      -- Sem guardado (ou agendamento parado há um dia): remonta só este
      -- escopo e grava. Se a gravação falhar, monta na hora, abaixo.
      perform public.atualizar_cache_painel_analises(v_area, array[v_scope]);
      select * into v_cache
        from private."TA_PAINEL_ANALISE" c
       where c."CO_AREA" = v_area and c."TP_ESCOPO" = v_scope;
      v_tem_cache := found and v_cache."DT_GERACAO" > now() - interval '1 hour';
      v_hit := v_tem_cache;
    else
      -- Outra abertura já está remontando: o guardado anterior serve por ora.
      v_hit := false;
    end if;
  end if;

  -- Não servir pacote marcado como sujo, inclusive se a remontagem falhar
  -- ou houver concorrência. Nessa situação, consulta os dados atuais.
  if v_tem_cache and private."FC_CACHE_DESATUALIZADO"('ANALISES', v_area) then
    v_tem_cache := false;
    v_hit := false;
  end if;

  if v_tem_cache then
    v_rows := v_cache."DS_LINHAS";
    v_editais := v_cache."DS_EDITAIS";
    v_total := v_cache."QT_LINHAS";
    v_atualizado_em := v_cache."DT_ULTIMA_ATUALIZACAO";
    v_gerado_em := v_cache."DT_GERACAO";
  else
    select m."DS_LINHAS", m."DS_EDITAIS", m."QT_LINHAS", m."DT_ULTIMA_ATUALIZACAO"
      into v_rows, v_editais, v_total, v_atualizado_em
      from private."FC_MONTAR_PAINEL_ANALISE"(v_area, array[v_scope], true) m;
  end if;

  return json_build_object(
    'schema_version', 4,
    'scope', v_scope,
    'area', v_area,
    'area_nome', v_area_nome,
    'grupo', v_grupo,
    'edital_status', case when v_scope = 'inativo' then 'Inativo' else 'Ativo' end,
    'columns', v_columns,
    'rows', v_rows,
    'editais', v_editais,
    'total', v_total,
    'textos_sob_demanda', true,
    'detalhe_sob_demanda', true,
    'versao_dados', case when v_tem_cache then v_cache."DS_VERSAO_DADOS" end,
    'atualizado_em', v_atualizado_em,
    'generated_at', v_gerado_em,
    'cache', json_build_object('hit', v_hit, 'refreshed_at', v_gerado_em)
  );
end;
$$;

--
-- Name: get_analises_dashboard_payload_v2_se_mudou(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analises_dashboard_payload_v2_se_mudou(p_scope text DEFAULT 'ativo'::text, p_area text DEFAULT NULL::text, p_versao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET work_mem TO '16MB'
    AS $$
declare
  v_marca constant text := private."FC_MARCA_DA_RPC"('get_analises_dashboard_payload_v2', p_area => p_area, p_escopo => p_scope);
begin
  if v_marca is null then
    return private."FC_SE_MUDOU"(public.get_analises_dashboard_payload_v2(p_scope, p_area)::jsonb, p_versao);
  end if;
  if p_versao = v_marca then
    return jsonb_build_object('inalterado', true, 'versao', v_marca);
  end if;
  return public.get_analises_dashboard_payload_v2(p_scope, p_area)::jsonb || jsonb_build_object('versao', v_marca);
end;
$$;

--
-- Name: FUNCTION get_analises_dashboard_payload_v2_se_mudou(p_scope text, p_area text, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_analises_dashboard_payload_v2_se_mudou(p_scope text, p_area text, p_versao text) IS 'get_analises_dashboard_payload_v2 com versão: a marca (FC_MARCA_DA_RPC; sem recorte, a do pacote pronto) sai antes de montar; p_versao igual devolve só { inalterado, versao } (20261029170000). Mesma permissão.';

--
-- Name: get_analises_texto_do_painel(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_analises_texto_do_painel(p_scope text DEFAULT 'ativo'::text, p_area text DEFAULT 'saude-indigena'::text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    SET statement_timeout TO '15s'
    SET work_mem TO '64MB'
    SET jit TO 'off'
    AS $$
declare
  v_scope text := lower(btrim(coalesce(p_scope, 'ativo')));
  v_area text := lower(btrim(coalesce(p_area, 'saude-indigena')));
  v_grupos_norm text[];
  v_rows json;
begin
  if not (private.pode_recurso('analises')) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;

  if v_scope not in ('ativo', 'inativo', 'desativadas', 'todos') then
    raise exception 'Escopo invalido. Use ativo, inativo, desativadas ou todos.';
  end if;

  v_grupos_norm := private."FC_GRUPOS_ANALISES_DA_AREA"(v_area);

  select coalesce(json_agg(json_build_array(
    v.id, v.analise, v.link_pdf,
    ac.experiencia_profissional_anos, ac.experiencia_profissional_meses,
    ac.experiencia_profissional_dias, ac.experiencia_profissional_total
  )), '[]'::json)
  into v_rows
  from public."VW_ANALISES_DASHBOARD_BASE_TODOS" v
  join public."TB_ANALISE_CURRICULAR" ac on ac.id = v.id
  where case
    when v_scope = 'ativo' then v.ativo is true and v.edital_ativo is true
    when v_scope = 'inativo' then v.edital_ativo is false
    when v_scope = 'desativadas' then v.ativo is not true and v.edital_ativo is true
    else true
  end
    and ac.grupo_norm = any (v_grupos_norm)
    and ((select private."FC_EDITAIS_VISIVEIS"()) is null
      or ac.edital_norm = any ((select private."FC_EDITAIS_NORM_VISIVEIS"())::text[])
      or ac.unidade_norm = any ((select private."FC_UNIDADES_NORM_VISIVEIS"())::text[]))
    -- Linha sem nada disso não precisa vir: o front a completa com null.
    and (v.analise is not null
      or v.link_pdf is not null
      or ac.experiencia_profissional_anos is not null
      or ac.experiencia_profissional_meses is not null
      or ac.experiencia_profissional_dias is not null
      or ac.experiencia_profissional_total is not null);

  return json_build_object(
    'scope', v_scope,
    'area', v_area,
    'columns', json_build_array(
      'id', 'analise', 'link_pdf',
      'experiencia_profissional_anos', 'experiencia_profissional_meses',
      'experiencia_profissional_dias', 'experiencia_profissional_total'
    ),
    'rows', v_rows,
    'total', json_array_length(v_rows),
    'generated_at', now()
  );
end;
$$;

--
-- Name: get_configuracoes_historico(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_configuracoes_historico(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 100);
begin
  if not (private.pode_recurso('configuracoes')) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not private.pode_recurso('configuracoes') then
    raise exception 'Sem permissao para consultar historico de "TB_CONFIGURACAO"';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', v.id,
      'acao', v.acao,
      'motivo', v.motivo,
      'created_by', v.created_by,
      'created_by_email', v.created_by_email,
      'restaurada_de', v.restaurada_de,
      'alteracoes', v.alteracoes,
      'total_alteracoes', v.total_alteracoes,
      'created_at', v.created_at
    ) order by v.created_at desc)
    from (
      select *
      from public."TH_CONFIGURACAO"
      order by created_at desc
      limit v_limit
    ) v
  ), '[]'::jsonb);
end;
$$;

--
-- Name: get_configuracoes_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_configuracoes_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
begin
  if not (private.pode_recurso('configuracoes')) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;

  -- `configuracoes` é a chave que config-governance.js lê; a renomeação de
  -- 20260918160000 a tinha trocado por '"TB_CONFIGURACAO"' e a revisão mostrava
  -- toda configuração como "(vazio) → valor". A chave antiga fica por ora.
  return jsonb_build_object(
    'configuracoes', private.snapshot_configuracoes(),
    '"TB_CONFIGURACAO"', private.snapshot_configuracoes(),
    'paineis', private.snapshot_paineis_externos(),
    'gerado_em', now()
  );
end;
$$;

--
-- Name: get_entrevistas_da_area(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_entrevistas_da_area(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_editais uuid[];
  v_payload json;
begin
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if not private.pode_recurso('entrevistas', 1) then
    raise exception 'Sem permissão para Entrevistas' using errcode = '42501';
  end if;
  if not private."FC_PODE_AREA"(p_area) then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;
  v_editais := (select private."FC_EDITAIS_VISIVEIS"())::uuid[];

  -- Vê todos os editais: o pacote pronto (o pg_cron remonta em até 2 min
  -- depois de uma mudança). Recorte de coordenação: montado na hora.
  if v_editais is null then
    select c."DS_PAYLOAD" into v_payload
      from private."TA_PAINEL_ENTREVISTA" c where c."CO_AREA" = p_area;
    if v_payload is not null then
      return v_payload;
    end if;
  end if;
  return private."FC_MONTAR_ENTREVISTAS_AREA"(p_area, v_editais);
end;
$$;

--
-- Name: FUNCTION get_entrevistas_da_area(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_entrevistas_da_area(p_area text) IS 'Leitura da aba Entrevistas de uma área (json): entrevistas ativas com as notas por critério (índice em "criterios"), a análise ligada e os aprovados na análise, nas vagas com entrevista, sem entrevista registrada. Exige entrevistas >= leitor, a área e o recorte da coordenação.';

--
-- Name: get_entrevistas_da_area_se_mudou(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_entrevistas_da_area_se_mudou(p_area text, p_versao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_marca constant text := private."FC_MARCA_DA_RPC"('get_entrevistas_da_area', p_area => p_area);
begin
  if v_marca is null then
    return private."FC_SE_MUDOU"(public.get_entrevistas_da_area(p_area)::jsonb, p_versao);
  end if;
  if p_versao = v_marca then
    return jsonb_build_object('inalterado', true, 'versao', v_marca);
  end if;
  return public.get_entrevistas_da_area(p_area)::jsonb || jsonb_build_object('versao', v_marca);
end;
$$;

--
-- Name: FUNCTION get_entrevistas_da_area_se_mudou(p_area text, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_entrevistas_da_area_se_mudou(p_area text, p_versao text) IS 'get_entrevistas_da_area com versão: a marca (FC_MARCA_DA_RPC; sem recorte, a do pacote pronto) sai antes de montar; p_versao igual devolve só { inalterado, versao } (20261029170000). Mesma permissão.';

--
-- Name: get_monitoramento_cronograma(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_monitoramento_cronograma(p_monitoramento_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not ((private.pode_recurso('dashboard') or private.pode_recurso('nucleo') or private.pode_recurso('calendario') or private.pode_recurso('aprovados') or private.pode_recurso('importacao'))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not ((private.pode_recurso('dashboard') or private.pode_recurso('nucleo') or private.pode_recurso('calendario') or private.pode_recurso('aprovados') or private.pode_recurso('importacao'))) then
    raise exception 'Sem permissao para consultar cronograma';
  end if;

  if exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_monitoramento_id and not private."FC_PODE_VER_EDITAL"(m.id)) then
    raise exception 'Sem permissão para editais desta área' using errcode='42501';
  end if;

  return jsonb_build_object(
    'monitoramento', (
      select jsonb_build_object(
        'id', m.id,
        'edital', m.edital,
        'unidade', m.unidade,
        'cronograma_automatico', m.cronograma_automatico,
        'cronograma_origem', m.cronograma_origem,
        'cronograma_revisado_at', m.cronograma_revisado_at,
        'status_override', m.status_override,
        'etapa_override', m.etapa_override,
        'status_override_motivo', m.status_override_motivo,
        'status_override_data', m.status_override_data,
        'status_override_previsao_retomada', m.status_override_previsao_retomada,
        'cronograma_ultima_errata', m.cronograma_ultima_errata
      )
      from public."TB_MONITORAMENTO_INDIGENA" m
      where m.id = p_monitoramento_id
    ),
    'estado', public.get_monitoramento_cronograma_estado(p_monitoramento_id, (now() at time zone 'America/Sao_Paulo')::date),
    'etapas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id,
        'ordem', c.ordem,
        'atividade', c.atividade,
        'tipo_atividade', c.tipo_atividade,
        'data_inicio', c.data_inicio,
        'data_fim', c.data_fim,
        'concluida', c.concluida,
        'observacao', c.observacao,
        'origem', c.origem,
        'confianca_extracao', c.confianca_extracao
      ) order by c.ordem)
      from public."TB_CRONOGRAMA_MONIT_INDIG" c
      where c.monitoramento_id = p_monitoramento_id
    ), '[]'::jsonb),
    'historico', public.get_monitoramento_cronograma_historico(p_monitoramento_id, 20)
  );
end;
$$;

--
-- Name: get_monitoramento_cronograma_estado(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_monitoramento_cronograma_estado(p_monitoramento_id uuid, p_data date DEFAULT ((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
begin
  if not ((private.pode_recurso('dashboard') or private.pode_recurso('nucleo') or private.pode_recurso('calendario') or private.pode_recurso('aprovados') or private.pode_recurso('importacao'))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  return private."FC_ESTADO_DO_CRONOGRAMA"(p_monitoramento_id, p_data);
end;
$$;

--
-- Name: get_monitoramento_cronograma_historico(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_monitoramento_cronograma_historico(p_monitoramento_id uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
begin
  if not ((private.pode_recurso('dashboard') or private.pode_recurso('nucleo') or private.pode_recurso('calendario') or private.pode_recurso('aprovados') or private.pode_recurso('importacao'))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not ((private.pode_recurso('dashboard') or private.pode_recurso('nucleo') or private.pode_recurso('calendario') or private.pode_recurso('aprovados') or private.pode_recurso('importacao'))) then
    raise exception 'Sem permissao para consultar historico do cronograma';
  end if;

  if exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_monitoramento_id and not private."FC_PODE_VER_EDITAL"(m.id)) then
    raise exception 'Sem permissão para editais desta área' using errcode='42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', v.id,
      'acao', v.acao,
      'motivo', v.motivo,
      'numero_errata', v.numero_errata,
      'created_by_email', v.created_by_email,
      'alteracoes', v.alteracoes,
      'total_alteracoes', v.total_alteracoes,
      'created_at', v.created_at
    ) order by v.created_at desc)
    from (
      select *
      from public."TH_CRONOGRAMA_MONIT_INDIG"
      where monitoramento_id = p_monitoramento_id
      order by created_at desc
      limit least(greatest(coalesce(p_limit, 20), 1), 100)
    ) v
  ), '[]'::jsonb);
end;
$$;

--
-- Name: get_nucleo_cronograma_resumo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_nucleo_cronograma_resumo() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not ((private.pode_recurso('dashboard') or private.pode_recurso('nucleo') or private.pode_recurso('calendario') or private.pode_recurso('aprovados') or private.pode_recurso('importacao'))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not ((private.pode_recurso('dashboard') or private.pode_recurso('nucleo') or private.pode_recurso('calendario') or private.pode_recurso('aprovados') or private.pode_recurso('importacao'))) then
    raise exception 'Sem permissao para consultar resumo da Equipe Nucleo';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', m.id,
      'edital', m.edital,
      'unidade', m.unidade,
      'status', e ->> 'status',
      'etapa', e ->> 'etapa',
      'cronograma_automatico', m.cronograma_automatico,
      'cronograma_total', coalesce(c.total, 0),
      'tem_resultado_final', coalesce(c.tem_resultado_final, false),
      'percentual', coalesce((e ->> 'percentual')::numeric, 0),
      'proxima_atividade', e ->> 'proxima_atividade',
      'proxima_data', e ->> 'proxima_data',
      'dias_para_proxima', (e ->> 'dias_para_proxima')::integer,
      'status_override', m.status_override,
      'alerta_tipo', case
        when nullif(m.status_override, '') is not null then 'excepcional'
        when not m.cronograma_automatico or coalesce(c.total, 0) = 0 then 'sem_cronograma'
        when coalesce(c.total, 0) < 2 or not coalesce(c.tem_resultado_final, false) then 'incompleto'
        when (e ->> 'dias_para_proxima')::integer between 0 and 3 then 'proxima_3d'
        when (e ->> 'dias_para_proxima')::integer between 4 and 7 then 'proxima_7d'
        else 'ok'
      end
    ) order by m.unidade, m.edital)
    from public."TB_MONITORAMENTO_INDIGENA" m
    cross join lateral public.get_monitoramento_cronograma_estado(m.id, (now() at time zone 'America/Sao_Paulo')::date) e
    left join lateral (
      select
        count(*)::integer as total,
        bool_or(lower(atividade) like '%resultado final%') as tem_resultado_final
      from public."TB_CRONOGRAMA_MONIT_INDIG" c
      where c.monitoramento_id = m.id
    ) c on true
    where m.ativo is true
      and m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
      and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
  ), '[]'::jsonb);
end;
$$;

--
-- Name: get_painel_dos_robos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_painel_dos_robos() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_master() then
    raise exception 'Somente o administrador global vê o painel dos robôs' using errcode = '42501';
  end if;

  return json_build_object(
    'schema_version', 1,
    'gerado_em', now(),
    'areas', (
      select coalesce(json_agg(json_build_object('area', a."CO_AREA", 'nome', a."NO_AREA")
               order by a."NU_ORDEM"), '[]'::json)
        from public."TB_AREA" a
    ),
    'editais', (
      select coalesce(json_agg(json_build_object(
               'id', m.id, 'edital', m.edital, 'numero', private."FC_NUMERO_EDITAL"(m.edital),
               'area', m."CO_AREA", 'unidade', m.unidade, 'ativo', m.ativo, 'status', m.status,
               'treinamento', private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO"))
             order by m."CO_AREA", private."FC_NUMERO_EDITAL"(m.edital) desc nulls last), '[]'::json)
        from public."TB_MONITORAMENTO_INDIGENA" m
       where private."FC_NUMERO_EDITAL"(m.edital) is not null
    ),
    'empregare', (
      select coalesce(json_agg(json_build_object(
               'id', e."CO_SYNC",
               'inicio', e."DT_INICIO", 'fim', e."DT_FIM", 'situacao', e."TP_SITUACAO",
               'disparo', e."TP_DISPARO",
               'quem', case when e."CO_USUARIO_DISPARO" is null then null
                            else coalesce(nullif(btrim(p.nome), ''), 'Usuário do MONITORA') end,
               'filtro', e."DS_FILTRO", 'forcada', e."ST_FORCADA" = 'S',
               'vagas_pedidas', e."QT_VAGA_PEDIDA", 'vagas_baixadas', e."QT_VAGA_BAIXADA",
               'vagas_falha', e."QT_VAGA_FALHA", 'vagas_recusadas', e."QT_VAGA_RECUSADA",
               'linhas', e."QT_LINHA", 'desativadas', e."QT_DESATIVADA",
               'mensagem', e."DS_MENSAGEM", 'execucao', e."DS_URL_EXECUCAO",
               'por_vaga', (
                 select coalesce(json_agg(json_build_object(
                          'vaga', v."CO_VAGA", 'situacao', v."TP_SITUACAO",
                          'arquivo', v."QT_LINHA_ARQUIVO", 'ativos', v."QT_CANDIDATO_ATIVO",
                          'com_link', (select count(*) from public."TB_EMPREGARE_CANDIDATO" c
                                        where c."CO_VAGA" = v."CO_VAGA" and c."ST_REGISTRO_ATIVO" = 'S'
                                          and c."DS_LINK_DETALHE" is not null),
                          'mensagem', left(v."DS_MENSAGEM", 300))
                        order by v."CO_VAGA"), '[]'::json)
                   from public."TB_EMPREGARE_VAGA" v
                  where v."CO_SYNC" = e."CO_SYNC"
               )
             ) order by e."DT_INICIO" desc), '[]'::json)
        from (select * from public."TL_SYNC_EMPREGARE" t order by t."DT_INICIO" desc limit 8) e
        left join public."TB_PERFIL_USUARIO" p on p.user_id = e."CO_USUARIO_DISPARO"
    ),
    'pre_classificacao', (
      select coalesce(json_agg(json_build_object(
               'id', x."CO_EXECUCAO",
               'inicio', x."DT_INICIO", 'fim', x."DT_FIM", 'situacao', x."TP_SITUACAO",
               'disparo', x."TP_DISPARO",
               'quem', case when x."CO_USUARIO_DISPARO" is null then null
                            else coalesce(nullif(btrim(p.nome), ''), 'Usuário do MONITORA') end,
               'pedido', x."DS_PEDIDO", 'refazer', x."ST_REFAZER_LOTE" = 'S',
               'editais', x."QT_EDITAL", 'vagas', x."QT_VAGA", 'inscritos', x."QT_INSCRITO",
               'lote', x."QT_LOTE", 'mensagem', x."DS_MENSAGEM", 'execucao', x."DS_URL_EXECUCAO"
             ) order by x."DT_INICIO" desc), '[]'::json)
        from (select * from public."TL_PRE_CLASSIFICACAO" t where not private."FC_EXECUCAO_EH_TREINAMENTO"(t."CO_EXECUCAO") order by t."DT_INICIO" desc limit 8) x
        left join public."TB_PERFIL_USUARIO" p on p.user_id = x."CO_USUARIO_DISPARO"
    )
  );
end;
$$;

--
-- Name: FUNCTION get_painel_dos_robos(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_painel_dos_robos() IS 'Painel dos robôs (Configurações › Status das atualizações, só administrador global): áreas, editais (com status, para a regra de vigente) e as 8 últimas execuções do robô da Empregare (filtro, quem pediu, contagens e, por vaga, situação, candidatos e quantos com link) e da pré-classificação (pedido, quem pediu, contagens). Nenhum dado de candidato. Só leitura.';

--
-- Name: get_recurso_candidato_detalhe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recurso_candidato_detalhe(p_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text;
begin
  select m."CO_AREA" into v_area
  from public."TB_RECURSO_CANDIDATO" r
  join public."TB_MONITORAMENTO_INDIGENA" m on m.id = r."CO_MONITORAMENTO"
  where r."CO_RECURSO_CANDIDATO" = p_id and r."ST_ATIVO" = 'S';
  if v_area is null then
    raise exception 'Recurso não encontrado' using errcode = 'P0002';
  end if;
  perform private."FC_EXIGIR_RECURSOS_NA_AREA"(v_area, 1);
  perform private."FC_EXIGIR_AREA_EDITAL"((select r."CO_MONITORAMENTO"::text from public."TB_RECURSO_CANDIDATO" r where r."CO_RECURSO_CANDIDATO" = p_id));
  return (
    select json_build_object(
      'id', r."CO_RECURSO_CANDIDATO",
      'eu', (select auth.uid()),
      'observacao', r."DS_OBSERVACAO",
      'modalidade', a.modalidade_concorrencia,
      'responsavel_analise', a.responsavel_analise,
      'analise_ativa', a.ativo,
      'nome_informado', r."NO_CANDIDATO_INFORMADO",
      'codigo_informado', r."CO_CANDIDATO_INFORMADO",
      'cargo_informado', r."NO_CARGO_INFORMADO",
      'vaga_informada', r."CO_VAGA_INFORMADA",
      'criado_por', private."FC_NOME_USUARIO"(r."CO_USUARIO_CRIACAO"),
      'decisao_por', private."FC_NOME_USUARIO"(r."CO_USUARIO_DECISAO"),
      'parecer', r."DS_PARECER_JURIDICO",
      'parecer_enviado_em', r."DT_ENVIO_PARECER",
      'parecer_enviado_por', private."FC_NOME_USUARIO"(r."CO_USUARIO_ENVIO_PARECER"),
      'devolvido_em', r."DT_DEVOLUCAO",
      'devolvido_por', private."FC_NOME_USUARIO"(r."CO_USUARIO_DEVOLUCAO"),
      'comentario_devolucao', r."DS_COMENTARIO_DEVOLUCAO",
      'etapas', json_build_object(
        'download_empregare', private."FC_NOME_USUARIO"(r."CO_USUARIO_DOWNLOAD_EMPREGARE"),
        'processo_sei', private."FC_NOME_USUARIO"(r."CO_USUARIO_PROCESSO_SEI"),
        'upload_sei', private."FC_NOME_USUARIO"(r."CO_USUARIO_UPLOAD_SEI"),
        'resposta_candidato', private."FC_NOME_USUARIO"(r."CO_USUARIO_RESPOSTA_CANDIDATO")
      ),
      'historico', (
        select coalesce(json_agg(json_build_object(
            'em', h."DT_ALTERACAO",
            'acao', h."TP_ACAO",
            'campo', h."DS_CAMPO",
            'anterior', h."DS_VALOR_ANTERIOR",
            'novo', h."DS_VALOR_NOVO",
            'motivo', h."DS_MOTIVO",
            'autor', private."FC_NOME_USUARIO"(h."CO_USUARIO")
          ) order by h."DT_ALTERACAO" desc, h."CO_HISTORICO_RECURSO" desc), '[]'::json)
        from public."TH_RECURSO_CANDIDATO" h
        where h."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO"
      ),
      'anexos', (
        select coalesce(json_agg(json_build_object(
            'id', x."CO_ANEXO_RECURSO",
            'tipo', x."TP_ANEXO",
            'nome', x."NO_ARQUIVO",
            'bytes', x."QT_BYTES",
            'mime', x."DS_MIME",
            'ativo', x."ST_ATIVO" = 'S',
            'resposta_id', x."CO_RESPOSTA_RECURSO",
            'incluido_em', x."DT_INCLUSAO",
            'incluido_por', private."FC_NOME_USUARIO"(x."CO_USUARIO_INCLUSAO"),
            'arquivado_em', x."DT_ARQUIVAMENTO",
            'arquivado_por', private."FC_NOME_USUARIO"(x."CO_USUARIO_ARQUIVAMENTO"),
            'motivo_arquivamento', x."DS_MOTIVO_ARQUIVAMENTO"
          ) order by x."ST_ATIVO" desc, x."DT_INCLUSAO" desc), '[]'::json)
        from public."TB_ANEXO_RECURSO" x
        where x."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO"
      ),
      'resposta', (
        select json_build_object(
          'id', s."CO_RESPOSTA_RECURSO",
          'modelo_id', s."CO_MODELO_RESPOSTA",
          'modelo_versao', s."NU_VERSAO_MODELO",
          'modelo_nome', t."NO_MODELO",
          'modelo_situacao', t."TP_SITUACAO",
          'modelo_vigente', t."ST_VIGENTE" = 'S',
          'modelo_corpo', t."DS_CORPO",
          'fundamentacao', s."DS_FUNDAMENTACAO",
          'texto_final', s."DS_TEXTO_FINAL",
          'estado', s."TP_ESTADO",
          'passou_revisao', s."ST_PASSOU_REVISAO" = 'S',
          'autor_id', s."CO_USUARIO_AUTOR",
          'autor', private."FC_NOME_USUARIO"(s."CO_USUARIO_AUTOR"),
          'envio_revisao_em', s."DT_ENVIO_REVISAO",
          'envio_revisao_por_id', s."CO_USUARIO_ENVIO_REVISAO",
          'envio_revisao_por', private."FC_NOME_USUARIO"(s."CO_USUARIO_ENVIO_REVISAO"),
          'revisor_id', s."CO_USUARIO_REVISOR",
          'revisor', private."FC_NOME_USUARIO"(s."CO_USUARIO_REVISOR"),
          'revisao_em', s."DT_REVISAO",
          'comentario_revisao', s."DS_COMENTARIO_REVISAO",
          'enviada_em', s."DT_ENVIO",
          'enviada_por', private."FC_NOME_USUARIO"(s."CO_USUARIO_ENVIO"),
          'revisao', s."NU_REVISAO",
          'criado_em', s."DT_CRIACAO",
          'atualizado_em', s."DT_ATUALIZACAO",
          'historico', (
            select coalesce(json_agg(json_build_object(
                'em', h."DT_ACAO",
                'acao', h."TP_ACAO",
                'anterior', h."TP_ESTADO_ANTERIOR",
                'novo', h."TP_ESTADO_NOVO",
                'comentario', h."DS_COMENTARIO",
                'versao_modelo', h."NU_VERSAO_MODELO",
                'autor', private."FC_NOME_USUARIO"(h."CO_USUARIO")
              ) order by h."DT_ACAO" desc, h."CO_HISTORICO_RESPOSTA" desc), '[]'::json)
            from public."TH_RESPOSTA_RECURSO" h
            where h."CO_RESPOSTA_RECURSO" = s."CO_RESPOSTA_RECURSO"
          )
        )
        from public."TB_RESPOSTA_RECURSO" s
        join public."TB_MODELO_RESPOSTA_RECURSO" t
          on t."CO_MODELO_RESPOSTA" = s."CO_MODELO_RESPOSTA" and t."NU_VERSAO" = s."NU_VERSAO_MODELO"
        where s."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO"
      )
    )
    from public."TB_RECURSO_CANDIDATO" r
    left join public."TB_ANALISE_CURRICULAR" a on a.id = r."CO_ANALISE_CURRICULAR"
    where r."CO_RECURSO_CANDIDATO" = p_id
  );
end;
$$;

--
-- Name: FUNCTION get_recurso_candidato_detalhe(p_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_recurso_candidato_detalhe(p_id uuid) IS 'Detalhe de um recurso: observação, quem fez cada etapa, o parecer jurídico (envio, devolução, decisão e texto), o histórico, os anexos, a resposta (com o histórico dela) e o id de quem pede. Mesma permissão da leitura da aba, na área e na coordenação do edital.';

--
-- Name: get_recursos_da_area(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recursos_da_area(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_pode_editar boolean;
begin
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_RECURSOS_NA_AREA"(p_area, 1);
  v_pode_editar := private.pode_recurso('recursos', 2);
  return (
    with recursos as (
      select r.*, m.edital, m.unidade,
             a.candidato, a.id_origem, a.nome_vaga, a.codigo_vaga,
             a.nota_final_ajustada, a.status_consolidado,
             (select s."TP_ESTADO" from public."TB_RESPOSTA_RECURSO" s
               where s."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO") as resposta_estado,
             (select count(*) from public."TB_ANEXO_RECURSO" x
               where x."CO_RECURSO_CANDIDATO" = r."CO_RECURSO_CANDIDATO" and x."ST_ATIVO" = 'S') as qt_anexos
      from public."TB_RECURSO_CANDIDATO" r
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = r."CO_MONITORAMENTO"
      left join public."TB_ANALISE_CURRICULAR" a on a.id = r."CO_ANALISE_CURRICULAR"
      where m."CO_AREA" = p_area
        and r."ST_ATIVO" = 'S'
        and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
    )
    select json_build_object(
      'schema_version', 1,
      'area', p_area,
      'pode_editar', v_pode_editar,
      'pode_decidir', private."FC_PODE_PARECER_RECURSO"(),
      'pode_administrar_modelos', private.pode_recurso('recursos', 3),
      'gerado_em', now(),
      'origens', (
        select coalesce(json_agg(json_build_object(
            'id', o."CO_ORIGEM_RECURSO",
            'rotulo', o."NO_ORIGEM_RECURSO",
            'ativo', o."ST_ATIVO" = 'S'
          ) order by o."NU_ORDEM"), '[]'::json)
        from public."TB_ORIGEM_RECURSO" o
      ),
      'editais', case when v_pode_editar then (
        select coalesce(json_agg(json_build_object(
            'id', m.id,
            'edital', m.edital,
            'unidade', m.unidade,
            'status', m.status,
            'tem_analises', exists (
              select 1 from public."TB_ANALISE_CURRICULAR" a
              where a.edital = m.edital and a."CO_AREA" = m."CO_AREA"
            )
          ) order by m.edital), '[]'::json)
        from public."TB_MONITORAMENTO_INDIGENA" m
        where m."CO_AREA" = p_area
          and m.ativo
          and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
      ) else '[]'::json end,
      'modelos', case when v_pode_editar then (
        select coalesce(json_agg(json_build_object(
            'id', t."CO_MODELO_RESPOSTA",
            'versao', t."NU_VERSAO",
            'area', t."CO_AREA",
            'origem', t."CO_ORIGEM_RECURSO",
            'situacao', t."TP_SITUACAO",
            'nome', t."NO_MODELO",
            'corpo', t."DS_CORPO"
          ) order by t."NO_MODELO"), '[]'::json)
        from public."TB_MODELO_RESPOSTA_RECURSO" t
        where t."ST_VIGENTE" = 'S'
          and t."ST_ATIVO" = 'S'
          and (t."CO_AREA" is null or t."CO_AREA" = p_area)
      ) else '[]'::json end,
      'recursos', (
        select coalesce(json_agg(json_build_object(
            'id', r."CO_RECURSO_CANDIDATO",
            'nu', r."NU_RECURSO",
            'edital_id', r."CO_MONITORAMENTO",
            'edital', r.edital,
            'unidade', r.unidade,
            'origem', r."CO_ORIGEM_RECURSO",
            'analise_id', r."CO_ANALISE_CURRICULAR",
            'fora_analise', r."ST_FORA_ANALISE" = 'S',
            'candidato', coalesce(r.candidato, r."NO_CANDIDATO_INFORMADO"),
            'codigo', coalesce(r.id_origem, r."CO_CANDIDATO_INFORMADO"),
            'cargo', coalesce(r.nome_vaga, r."NO_CARGO_INFORMADO"),
            'vaga', coalesce(r.codigo_vaga, r."CO_VAGA_INFORMADA"),
            'nota_anterior', r."VL_NOTA_ANTERIOR",
            'nota_atual', r.nota_final_ajustada,
            'resultado_anterior', r."DS_RESULTADO_ANTERIOR",
            'resultado_atual', r.status_consolidado,
            'analista', r."NO_ANALISTA",
            'situacao', r."TP_SITUACAO",
            'processo_sei', r."NU_PROCESSO_SEI",
            'mudou_classificacao', r."ST_MUDOU_CLASSIFICACAO" = 'S',
            'download_empregare_em', r."DT_DOWNLOAD_EMPREGARE",
            'processo_sei_em', r."DT_PROCESSO_SEI",
            'upload_sei_em', r."DT_UPLOAD_SEI",
            'resposta_candidato_em', r."DT_RESPOSTA_CANDIDATO",
            'decisao_em', r."DT_DECISAO",
            'parecer_enviado_em', r."DT_ENVIO_PARECER",
            'devolvido_em', r."DT_DEVOLUCAO",
            'criado_em', r."DT_CRIACAO",
            'atualizado_em', r."DT_ATUALIZACAO",
            'revisao', r."NU_REVISAO",
            'resposta_estado', r.resposta_estado,
            'qt_anexos', r.qt_anexos
          ) order by r."NU_RECURSO" desc), '[]'::json)
        from recursos r
      ),
      'cronogramas', (
        select coalesce(json_agg(json_build_object(
            'edital_id', c.monitoramento_id,
            'ordem', c.ordem,
            'atividade', c.atividade,
            'inicio', c.data_inicio,
            'fim', c.data_fim
          ) order by c.monitoramento_id, c.ordem), '[]'::json)
        from public."TB_CRONOGRAMA_MONIT_INDIG" c
        where c.monitoramento_id in (select r."CO_MONITORAMENTO" from recursos r)
      )
    )
  );
end;
$$;

--
-- Name: FUNCTION get_recursos_da_area(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_recursos_da_area(p_area text) IS 'Aba Recursos de uma área (json): recursos ativos (com o estado da resposta, o nº de anexos, o envio para parecer e a última devolução), origens, editais e modelos (quem edita), as etapas do cronograma e as permissões (pode_editar, pode_decidir = recursos_parecer, pode_administrar_modelos). Exige recursos >= leitor, a área e o recorte da coordenação.';

--
-- Name: get_saude_das_cargas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_saude_das_cargas() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tarefas json;
  v_chave_cadastrada boolean;
begin
  if not private.is_master() then
    raise exception 'Somente o administrador global vê a saúde das cargas' using errcode = '42501';
  end if;

  -- pg_cron pode não estar acessível: a seção mostra "indisponível" nessa parte.
  begin
    select coalesce(json_agg(json_build_object(
        'nome', j.jobname,
        'agenda', j.schedule,
        'ativa', j.active,
        'execucoes', (
          select coalesce(json_agg(json_build_object(
              'inicio', d.start_time,
              'fim', d.end_time,
              'situacao', d.status,
              'mensagem', left(d.return_message, 500)
            ) order by d.start_time desc), '[]'::json)
            from (select * from cron.job_run_details r
                   where r.jobid = j.jobid
                   order by r.start_time desc limit 10) d
        )
      ) order by j.jobname), '[]'::json)
      into v_tarefas
      from cron.job j
     where left(j.jobname, 6) = 'agsus_';
  exception when others then
    v_tarefas := null;
  end;

  -- [agenda-dos-robos] só se a chave existe (nunca o valor); null se o Vault não deixar ver.
  begin
    select exists (select 1 from vault.secrets s where s.name = 'github_disparo_robos')
      into v_chave_cadastrada;
  exception when others then
    v_chave_cadastrada := null;
  end;

  return json_build_object(
    'schema_version', 1,
    'gerado_em', now(),
    'analises', (
      select coalesce(json_agg(json_build_object(
          'origem', o."CO_ORIGEM",
          'area', p."CO_AREA",
          'planilha', p."NO_PLANILHA",
          'tipo', o."TP_CARGA",
          'execucoes', (
            select coalesce(json_agg(json_build_object(
                'inicio', x.j ->> 'started_at',
                'fim', x.j ->> 'finished_at',
                'situacao', x.j ->> 'status',
                'linhas', coalesce(x.j ->> 'total_processados', x.j ->> 'total_lidos', x.j ->> 'linhas_staging'),
                'mensagem', left(coalesce(x.j ->> 'erro', x.j ->> 'mensagem'), 500),
                -- [nao-trava] encerrada por inatividade (20261007170000)
                'encerrada_por_inatividade', coalesce((x.j -> 'resultado' ->> 'encerrada_por_inatividade')::boolean, false)
              ) order by x.inicio desc nulls last), '[]'::json)
              from (select to_jsonb(s) as j, s.started_at as inicio
                      from public."TL_SYNC_ANALISE" s
                     where s.origem = o."CO_ORIGEM"
                     order by s.started_at desc nulls last
                     limit 10) x
          )
        ) order by p."CO_AREA", o."TP_CARGA" desc), '[]'::json)
        from public."TA_ORIGEM_ANALISE" o
        join public."TB_PLANILHA_ANALISE" p on p."CO_PLANILHA" = o."CO_PLANILHA"
    ),
    'entrevistas', (
      select coalesce(json_agg(json_build_object(
          'inicio', e."DT_INICIO",
          'fim', e."DT_FIM",
          'situacao', e."TP_SITUACAO",
          'linhas', e."QT_LINHA",
          'mensagem', e."DS_MENSAGEM",
          'area', e."CO_AREA"
        ) order by e."DT_INICIO" desc), '[]'::json)
        from (select * from public."TL_SYNC_ENTREVISTA" t order by t."DT_INICIO" desc limit 10) e
    ),
    'selecao', (
      select coalesce(json_agg(json_build_object(
          'inicio', e."DT_INICIO",
          'fim', e."DT_FIM",
          'situacao', e."TP_SITUACAO",
          'linhas', e."QT_LINHA",
          'mensagem', e."DS_MENSAGEM"
        ) order by e."DT_INICIO" desc), '[]'::json)
        from (select * from public."TL_SYNC_SELECAO" t order by t."DT_INICIO" desc limit 10) e
    ),
    'empregare', (
      select coalesce(json_agg(json_build_object(
          'inicio', e."DT_INICIO",
          'fim', e."DT_FIM",
          'situacao', e."TP_SITUACAO",
          'linhas', e."QT_LINHA",
          'mensagem', e."DS_MENSAGEM",
          'disparo', e."TP_DISPARO",
          'vagas_pedidas', e."QT_VAGA_PEDIDA",
          'vagas_baixadas', e."QT_VAGA_BAIXADA",
          'vagas_falha', e."QT_VAGA_FALHA",
          'vagas_recusadas', e."QT_VAGA_RECUSADA",
          'desativadas', e."QT_DESATIVADA",
          'execucao', e."DS_URL_EXECUCAO"
        ) order by e."DT_INICIO" desc), '[]'::json)
        from (select * from public."TL_SYNC_EMPREGARE" t order by t."DT_INICIO" desc limit 10) e
    ),
    'conferencias', (
      select coalesce(json_agg(json_build_object(
          'inicio', c."DT_INICIO",
          'fim', c."DT_FIM",
          'situacao', c."TP_SITUACAO",
          'linhas', c."QT_AVISO_ABERTO",
          'mensagem', c."DS_MENSAGEM",
          'disparo', c."TP_DISPARO",
          'novos', c."QT_AVISO_NOVO",
          'abertos', c."QT_AVISO_ABERTO",
          'resolvidos', c."QT_AVISO_RESOLVIDO",
          'falhas', c."DS_FALHA",
          'execucao', c."DS_URL_EXECUCAO"
        ) order by c."DT_INICIO" desc), '[]'::json)
        from (select * from public."TL_CONFERENCIA" t order by t."DT_INICIO" desc limit 10) c
    ),
    'pre_classificacao', (
      select coalesce(json_agg(json_build_object(
          'inicio', p."DT_INICIO",
          'fim', p."DT_FIM",
          'situacao', p."TP_SITUACAO",
          'linhas', p."QT_INSCRITO",
          'mensagem', p."DS_MENSAGEM",
          'disparo', p."TP_DISPARO",
          'editais', p."QT_EDITAL",
          'vagas', p."QT_VAGA",
          'lote', p."QT_LOTE",
          'refazer', p."ST_REFAZER_LOTE" = 'S',
          'execucao', p."DS_URL_EXECUCAO"
        ) order by p."DT_INICIO" desc), '[]'::json)
        from (select * from public."TL_PRE_CLASSIFICACAO" t where not private."FC_EXECUCAO_EH_TREINAMENTO"(t."CO_EXECUCAO") order by t."DT_INICIO" desc limit 10) p
    ),
    -- [agenda-dos-robos] os pedidos do banco ao GitHub (20261008140000)
    'agenda_dos_robos', json_build_object(
      'chave_cadastrada', v_chave_cadastrada,
      'ultimo_aceito', (select max(d."DT_DISPARO") from public."TL_DISPARO_ROBO" d where d."TP_SITUACAO" = 'ACEITO'),
      'falhas_24h', (select count(*) from public."TL_DISPARO_ROBO" d
                      where d."TP_SITUACAO" = 'FALHOU' and d."DT_DISPARO" > now() - interval '24 hours'),
      'sem_chave_24h', (select count(*) from public."TL_DISPARO_ROBO" d
                         where d."TP_SITUACAO" = 'SEM_TOKEN' and d."DT_DISPARO" > now() - interval '24 hours'),
      'disparos', (
        select coalesce(json_agg(json_build_object(
            'workflow', x."NO_WORKFLOW",
            'origem', x."TP_ORIGEM",
            'inicio', x."DT_DISPARO",
            'fim', x."DT_RESPOSTA",
            'situacao', x."TP_SITUACAO",
            'http', x."NU_STATUS_HTTP",
            'mensagem', x."DS_MENSAGEM",
            -- [disparos-externos] quem iniciou no GitHub e o link da execução (20261020170000)
            'ator', x."NO_ATOR_GITHUB",
            'execucao', x."DS_URL_EXECUCAO"
          ) order by x."DT_DISPARO" desc, x."CO_DISPARO" desc), '[]'::json)
          from (select * from public."TL_DISPARO_ROBO" t
                 order by t."DT_DISPARO" desc, t."CO_DISPARO" desc limit 20) x
      )
    ),
    -- [classificacao-python] o relatório de desempate e o cálculo das listas pelo Python (20261023200000)
    'classificacao_python', json_build_object(
      'relatorios', (
        select coalesce(json_agg(json_build_object(
            'inicio', p."DT_PEDIDO",
            'fim', p."DT_ATUALIZACAO",
            'situacao', p."TP_SITUACAO",
            'mensagem', p."DS_MENSAGEM",
            'edital', coalesce(private."FC_NUMERO_EDITAL"(m.edital), m.edital),
            'tipo', l."TP_LISTA"
          ) order by p."DT_ATUALIZACAO" desc), '[]'::json)
          from (select * from public."TB_PREPARO_DESEMPATE" t
                 where t."TP_SITUACAO" <> 'DESLIGADA'
                 order by t."DT_ATUALIZACAO" desc limit 20) p
          join public."TB_LISTA_CLASSIFICACAO" l on l."CO_LISTA_CLASSIFICACAO" = p."CO_LISTA_CLASSIFICACAO"
          join public."TB_MONITORAMENTO_INDIGENA" m on m.id = l."CO_MONITORAMENTO"
      ),
      'calculos', (
        select coalesce(json_agg(json_build_object(
            'inicio', p."DT_PEDIDO",
            'fim', p."DT_ATUALIZACAO",
            'situacao', p."TP_SITUACAO",
            'mensagem', p."DS_MENSAGEM",
            'edital', coalesce(private."FC_NUMERO_EDITAL"(m.edital), m.edital),
            'tipo', p."TP_LISTA"
          ) order by p."DT_ATUALIZACAO" desc), '[]'::json)
          from (select * from public."TB_PEDIDO_CALCULO_CLASSIFICACAO" t
                 where t."TP_SITUACAO" <> 'SUBSTITUIDO'
                 order by t."DT_ATUALIZACAO" desc limit 20) p
          join public."TB_MONITORAMENTO_INDIGENA" m on m.id = p."CO_MONITORAMENTO"
      )
    ),
    'tarefas', v_tarefas
  );
end;
$$;

--
-- Name: FUNCTION get_saude_das_cargas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_saude_das_cargas() IS 'Saúde das cargas (Configurações, só administrador global): as últimas 10 execuções de cada carga das análises (por origem, com encerrada_por_inatividade — 20261007170000), das entrevistas, da seleção, do robô da Empregare (com vagas pedidas/baixadas/falhas/recusadas e quem disparou), das conferências de consistência (avisos novos, abertos e resolvidos), da pré-classificação da Avaliação documental (editais, vagas, inscritos e lote), do expurgo diário dos anexos do chat (lotes, removidos, confirmados, falhas e pendentes — 20261007250000), da agenda dos robôs pelo banco (chave cadastrada, último disparo aceito, falhas e sem chave em 24 h, os 20 últimos pedidos — 20261008140000) e das tarefas agsus_* do pg_cron (nulas sem acesso ao pg_cron). Só leitura.';

--
-- Name: get_selecao_da_area(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_selecao_da_area(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_editais uuid[];
begin
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if not private.pode_recurso('selecao', 1) then
    raise exception 'Sem permissão para Seleção' using errcode = '42501';
  end if;
  if not private."FC_PODE_AREA"(p_area) then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;
  v_editais := (select private."FC_EDITAIS_VISIVEIS"())::uuid[];

  return (
    with s as (
      select s.*, private."FC_NUMERO_EDITAL"(s."DS_EDITAL") as numero
        from public."TB_SELECAO_VAGA" s
       where s."CO_AREA" = p_area and s."ST_REGISTRO_ATIVO" = 'S'
         and (v_editais is null or s."CO_MONITORAMENTO" = any (v_editais))
    ),
    -- Convocados: a entrevista vigente de cada pessoa (FC_ENTREVISTAS_VIGENTES) por edital e vaga.
    convocados as (
      select private."FC_NUMERO_EDITAL"(e."DS_EDITAL") as numero, e."CO_VAGA" as vaga, count(*)::integer as qt
        from public."TB_ENTREVISTA" e
       where e."CO_AREA" = p_area and e."ST_ATIVO" = 'S'
         and e."CO_ENTREVISTA" in (select v from private."FC_ENTREVISTAS_VIGENTES"(p_area) v)
       group by 1, 2
    ),
    editais_com_entrevista as (
      select distinct c.numero from convocados c where c.numero is not null
    ),
    -- Lista de aprovados vigente dos editais ligados.
    listas as (
      select l.id, l.edital_id
        from public."TB_LISTA_APROVADO" l
       where l.vigente is true
         and l.edital_id in (select s."CO_MONITORAMENTO"::text from s where s."CO_MONITORAMENTO" is not null)
    ),
    aprovados as (
      select l.edital_id, regexp_replace(coalesce(c.codigo_vaga, ''), '[^0-9]', '', 'g') as vaga,
             count(*)::integer as total,
             (count(*) filter (where c.status in ('Contratado', 'Migração') and not private."FC_EM_OUTRA_LISTA"(c.id)))::integer as contratados
        from listas l
        join public."TB_CANDIDATO_APROVADO" c on c.lista_id = l.id and c.removido_em is null
       group by 1, 2
    ),
    -- Outras bancas (CESPE, FGV…): sem código numérico, o "id da vaga" da lista é
    -- o nome do cargo. Chave: o texto sem acento, caixa nem pontuação.
    aprovados_por_cargo as (
      select l.edital_id,
             btrim(regexp_replace(private."FC_TEXTO_BUSCA_RECURSO"(c.codigo_vaga), '[^a-z0-9]+', ' ', 'g')) as cargo,
             count(*)::integer as total,
             (count(*) filter (where c.status in ('Contratado', 'Migração') and not private."FC_EM_OUTRA_LISTA"(c.id)))::integer as contratados
        from listas l
        join public."TB_CANDIDATO_APROVADO" c on c.lista_id = l.id and c.removido_em is null
       group by 1, 2
    ),
    linhas as (
      select s.*,
             m.edital as edital_cadastrado,
             (s.numero is not null and s.numero in (select x.numero from editais_com_entrevista x)) as usa_entrevistas,
             cv.qt as qt_convocado_entrevistas,
             exists (select 1 from listas l where l.edital_id = s."CO_MONITORAMENTO"::text) as tem_lista,
             coalesce(ap.total, apc.total) as qt_aprovado,
             coalesce(ap.contratados, apc.contratados) as qt_contratado
        from s
        left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = s."CO_MONITORAMENTO"
        left join convocados cv on cv.numero = s.numero and cv.vaga = s."CO_VAGA"
        -- A 2ª vaga de mesmo código (chave com #2…) não recebe de novo os mesmos aprovados (20261022200000).
        left join aprovados ap
          on ap.edital_id = s."CO_MONITORAMENTO"::text and ap.vaga = s."CO_VAGA"
         and s."DS_CHAVE_ORIGEM" !~ '#[0-9]+$'
        -- Vaga sem código (outra banca): pelo nome do cargo; a 2ª vaga de mesmo nome
        -- (chave com #2…) não recebe de novo os mesmos aprovados.
        left join aprovados_por_cargo apc
          on s."CO_VAGA" is null
         and s."DS_CHAVE_ORIGEM" !~ '#[0-9]+$'
         and apc.edital_id = s."CO_MONITORAMENTO"::text
         and apc.cargo = btrim(regexp_replace(private."FC_TEXTO_BUSCA_RECURSO"(s."DS_VAGA_PLANILHA"), '[^a-z0-9]+', ' ', 'g'))
    )
    select json_build_object(
      'schema_version', 1,
      'area', p_area,
      'gerado_em', now(),
      'ultima_carga', (
        select json_build_object('em', t."DT_FIM", 'linhas', t."QT_LINHA", 'sem_edital', t."QT_SEM_EDITAL")
          from public."TL_SYNC_SELECAO" t
         where t."TP_SITUACAO" = 'CONCLUIDA'
         order by t."DT_FIM" desc limit 1
      ),
      'vagas', (
        select coalesce(json_agg(json_build_object(
            'id', l."CO_SELECAO_VAGA",
            'edital_id', l."CO_MONITORAMENTO",
            'edital', coalesce(l.edital_cadastrado, l."DS_EDITAL"),
            'edital_planilha', l."DS_EDITAL",
            'unidade', l."NO_UNIDADE",
            'vaga', l."CO_VAGA",
            'vaga_planilha', l."DS_VAGA_PLANILHA",
            'cargo', l."NO_CARGO",
            'inscritos', l."QT_INSCRITO",
            'aptos', l."QT_APTO_ANALISE",
            'cancelados', l."QT_CANCELADO",
            'reprovados_questionario', l."QT_REPROVADO_QUESTIONARIO",
            'eliminados_nota', l."QT_ELIMINADO_NOTA",
            'reprovados_analise', l."QT_REPROVADO_ANALISE",
            'triados', l."QT_TRIADO",
            'total_eliminados', l."QT_TOTAL_ELIMINADO",
            'observacao', l."DS_OBSERVACAO",
            'convocados', case when l.usa_entrevistas then coalesce(l.qt_convocado_entrevistas, 0)
                               else l."QT_CONVOCADO_PLANILHA" end,
            'origem_convocados', case when l.usa_entrevistas then 'entrevistas' else 'planilha' end,
            'aprovados', case when l.tem_lista then coalesce(l.qt_aprovado, 0) end,
            'contratados', case when l.tem_lista then coalesce(l.qt_contratado, 0) end,
            'nao_contratados', case when l.tem_lista then coalesce(l.qt_aprovado, 0) - coalesce(l.qt_contratado, 0) end
          ) order by coalesce(l.edital_cadastrado, l."DS_EDITAL"), l."NO_UNIDADE", l."NO_CARGO", l."CO_VAGA"), '[]'::json)
          from linhas l
      )
    )
  );
end;
$_$;

--
-- Name: FUNCTION get_selecao_da_area(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_selecao_da_area(p_area text) IS 'Leitura da aba Seleção de uma área (json): o funil de cada vaga (aba Resultado da Auditoria), os convocados (entrevistas vigentes, FC_ENTREVISTAS_VIGENTES, quando o edital tem entrevista; senão o V da planilha) e aprovados/contratados/não contratados da lista vigente (a 2ª vaga de mesmo código ou cargo não repete os aprovados). Exige selecao >= leitor, a área e o recorte da coordenação.';

--
-- Name: get_selecao_da_area_se_mudou(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_selecao_da_area_se_mudou(p_area text, p_versao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_marca constant text := private."FC_MARCA_DA_RPC"('get_selecao_da_area', p_area => p_area);
begin
  if v_marca is null then
    return private."FC_SE_MUDOU"(public.get_selecao_da_area(p_area)::jsonb, p_versao);
  end if;
  if p_versao = v_marca then
    return jsonb_build_object('inalterado', true, 'versao', v_marca);
  end if;
  return public.get_selecao_da_area(p_area)::jsonb || jsonb_build_object('versao', v_marca);
end;
$$;

--
-- Name: FUNCTION get_selecao_da_area_se_mudou(p_area text, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_selecao_da_area_se_mudou(p_area text, p_versao text) IS 'get_selecao_da_area com versão: a marca das fontes (FC_MARCA_DA_RPC) sai antes de montar; p_versao igual devolve só { inalterado, versao } (20261029170000). Mesma permissão.';

--
-- Name: gravar_anexos_empregare(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_anexos_empregare(p_sync text, p_vaga text, p_respostas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_r jsonb;
  v_cand uuid;
  v_resp uuid;
  v_impressao text;
  v_respostas integer := 0;
  v_anexos integer := 0;
  v_qt integer;
  v_sem_candidato integer := 0;
  v_antigos jsonb;
  v_apagadas integer;
  v_invalidadas integer := 0;
  v_edital uuid;
begin
  perform private."FC_EMPREGARE_EXIGIR_SYNC"(p_sync);
  if p_vaga is null or p_vaga !~ '^[0-9]{1,20}$' then
    raise exception 'Código de vaga inválido' using errcode = '22023';
  end if;
  -- [congeladas-anexos] (20261022170000) Edital com inscrições congeladas: só a execução que
  -- registrou o uso da liberação do administrador global grava respostas e anexos (vale para
  -- a carga e para o modo Só anexos, que antes passava).
  select v."CO_MONITORAMENTO" into v_edital from public."TB_EMPREGARE_VAGA" v where v."CO_VAGA" = p_vaga;
  if v_edital is null then
    select q.edital_id into v_edital from private."FC_EMPREGARE_VAGAS_DO_QUADRO"(p_vaga) q limit 1;
  end if;
  if v_edital is not null and private."FC_INSCRICOES_CONGELADAS"(v_edital)
     and not private."FC_EXECUCAO_LIBERADA_NO_CONGELAMENTO"(p_sync, v_edital) then
    raise exception 'Inscrições congeladas no edital da vaga %: anexos não gravados (só com a liberação do administrador global).', p_vaga
      using errcode = '55000';
  end if;
  if jsonb_typeof(p_respostas) is distinct from 'array' or jsonb_array_length(p_respostas) not between 1 and 500 then
    raise exception 'Envie de 1 a 500 respostas por lote' using errcode = '22023';
  end if;

  for v_r in select x from jsonb_array_elements(p_respostas) x loop
    continue when coalesce(v_r ->> 'resposta', '') !~ '^[0-9]{1,20}$';
    select c."CO_EMPREGARE_CANDIDATO" into v_cand
      from public."TB_EMPREGARE_CANDIDATO" c
     where c."CO_VAGA" = p_vaga and c."CO_CANDIDATO_EMPREGARE" = btrim(v_r ->> 'codigo');
    if v_cand is null then
      v_sem_candidato := v_sem_candidato + 1;
      continue;
    end if;
    -- Link fora do formato vira nulo (impressão) ou fica de fora (anexo).
    v_impressao := case when v_r ->> 'impressao' ~ '^https://corporate\.empregare\.com/Company/VacancyTests/PrintResult\?[A-Za-z0-9_.~=&%|+/:-]+$'
                        and length(v_r ->> 'impressao') <= 1500 then v_r ->> 'impressao' end;
    insert into public."TB_EMPREGARE_RESPOSTA" as x (
      "CO_EMPREGARE_CANDIDATO", "CO_RESPOSTA_QUESTIONARIO", "DS_LINK_IMPRESSAO", "QT_PERGUNTA", "CO_SYNC", "DT_CAPTURA")
    values (v_cand, v_r ->> 'resposta', v_impressao,
            least(greatest(coalesce((v_r ->> 'perguntas')::integer, 0), 0), 10000), p_sync, now())
    on conflict ("CO_EMPREGARE_CANDIDATO", "CO_RESPOSTA_QUESTIONARIO") do update set
      "DS_LINK_IMPRESSAO" = coalesce(excluded."DS_LINK_IMPRESSAO", x."DS_LINK_IMPRESSAO"),
      "QT_PERGUNTA" = excluded."QT_PERGUNTA",
      "CO_SYNC" = excluded."CO_SYNC",
      "DT_CAPTURA" = excluded."DT_CAPTURA"
    returning x."CO_EMPREGARE_RESPOSTA" into v_resp;
    v_respostas := v_respostas + 1;

    -- O arquivo de cada anexo antes da troca ("pergunta:número" → arquivo= do link).
    select coalesce(jsonb_object_agg(a."CO_PERGUNTA_EMPREGARE" || ':' || a."NU_ARQUIVO",
                                     coalesce(private."FC_ARQUIVO_DO_LINK_EMPREGARE"(a."DS_LINK"), a."DS_LINK")), '{}'::jsonb)
      into v_antigos
      from public."TB_EMPREGARE_ANEXO" a
     where a."CO_EMPREGARE_RESPOSTA" = v_resp;

    -- A resposta relida fica só com os anexos lidos agora.
    delete from public."TB_EMPREGARE_ANEXO" a where a."CO_EMPREGARE_RESPOSTA" = v_resp;
    insert into public."TB_EMPREGARE_ANEXO" (
      "CO_EMPREGARE_RESPOSTA", "CO_PERGUNTA_EMPREGARE", "NU_ARQUIVO", "NU_ORDEM", "DS_ENUNCIADO", "DS_COLUNA", "DS_LINK",
      "DT_CAPTURA")
    select distinct on (an.pergunta, an.arquivo)
           v_resp, an.pergunta, an.arquivo::smallint,
           case when an.ordem between 1 and 999 then an.ordem::smallint end,
           nullif(left(btrim(regexp_replace(an.enunciado, '\s+', ' ', 'g')), 2000), ''),
           nullif(left(btrim(an.coluna), 1000), ''),
           an.link, now()
      from jsonb_to_recordset(coalesce(v_r -> 'anexos', '[]'::jsonb))
           as an(pergunta text, arquivo integer, ordem integer, enunciado text, coluna text, link text)
     where an.pergunta ~ '^[0-9]{1,20}$'
       and an.arquivo between 1 and 50
       and length(an.link) <= 1500
       and an.link ~ '^https://corporate\.empregare\.com/Company/VacancyTests/GetViewerLogArquivo\?[A-Za-z0-9_.~=&%|+/:-]+$'
     order by an.pergunta, an.arquivo;
    get diagnostics v_qt = row_count;
    update public."TB_EMPREGARE_RESPOSTA" set "QT_ANEXO" = v_qt where "CO_EMPREGARE_RESPOSTA" = v_resp;
    v_anexos := v_anexos + v_qt;

    -- Arquivo trocado (ou que não estava gravado) na mesma pergunta e número: a leitura
    -- automática era do arquivo antigo. Sai, e o robô da leitura lê o novo ("nunca lido").
    delete from public."TB_LEITURA_ARQUIVO" l
     using public."TB_EMPREGARE_ANEXO" a
     where l."CO_EMPREGARE_RESPOSTA" = v_resp
       and a."CO_EMPREGARE_RESPOSTA" = v_resp
       and a."CO_PERGUNTA_EMPREGARE" = l."CO_PERGUNTA_EMPREGARE"
       and a."NU_ARQUIVO" = l."NU_ARQUIVO"
       and (v_antigos ->> (a."CO_PERGUNTA_EMPREGARE" || ':' || a."NU_ARQUIVO"))
           is distinct from coalesce(private."FC_ARQUIVO_DO_LINK_EMPREGARE"(a."DS_LINK"), a."DS_LINK");
    get diagnostics v_apagadas = row_count;
    v_invalidadas := v_invalidadas + v_apagadas;
  end loop;

  return jsonb_build_object('recebidas', jsonb_array_length(p_respostas), 'respostas', v_respostas,
                            'anexos', v_anexos, 'sem_candidato', v_sem_candidato,
                            'leituras_invalidadas', v_invalidadas);
end;
$_$;

--
-- Name: FUNCTION gravar_anexos_empregare(p_sync text, p_vaga text, p_respostas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_anexos_empregare(p_sync text, p_vaga text, p_respostas jsonb) IS 'Recebe (até 500 por lote) as respostas de questionário dos candidatos de uma vaga, lidas pelo robô da Empregare em GetRespostaDetails: [{codigo, resposta, impressao, perguntas, anexos: [{pergunta, arquivo, ordem, enunciado, coluna, link}]}]. Faz upsert em TB_EMPREGARE_RESPOSTA e troca os anexos da resposta em TB_EMPREGARE_ANEXO; quando o arquivo de um anexo (mesma resposta, pergunta e número, pelo arquivo= do link) muda ou aparece, apaga a leitura automática dele em TB_LEITURA_ARQUIVO (o robô da leitura lê o novo). Só candidatos da vaga; link fora do formato fica de fora. Só service_role, com a execução em andamento. {recebidas, respostas, anexos, sem_candidato, leituras_invalidadas}.';

--
-- Name: gravar_avisos_conferencia(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_avisos_conferencia(p_execucao text, p_avisos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_aviso jsonb;
  v_atual public."TB_AVISO_CONFERENCIA";
  v_id uuid;
  v_conferencia text;
  v_escopo text;
  v_gravidade text;
  v_modulo text;
  v_area text;
  v_edital uuid;
  v_qt integer;
  v_exemplos jsonb;
  v_casos jsonb;
  v_resumo text;
  v_novos integer := 0;
  v_reabertos integer := 0;
  v_mantidos integer := 0;
begin
  perform private."FC_EXIGIR_EXECUCAO_CONFERENCIA"(p_execucao);
  if jsonb_typeof(p_avisos) is distinct from 'array' or jsonb_array_length(p_avisos) > 1000 then
    raise exception 'Envie até 1000 avisos por chamada, em lista' using errcode = '22023';
  end if;

  for v_aviso in select x from jsonb_array_elements(p_avisos) x loop
    v_conferencia := v_aviso ->> 'conferencia';
    v_escopo := v_aviso ->> 'escopo';
    v_gravidade := v_aviso ->> 'gravidade';
    v_modulo := v_aviso ->> 'modulo';
    v_area := nullif(v_aviso ->> 'area', '');
    v_exemplos := coalesce(v_aviso -> 'exemplos', '[]'::jsonb);
    v_casos := v_aviso -> 'casos';
    v_resumo := btrim(coalesce(v_aviso ->> 'resumo', ''));

    if v_conferencia is null or v_conferencia !~ '^[A-Z][A-Z0-9_]{2,59}$' then
      raise exception 'Código de conferência inválido' using errcode = '22023';
    end if;
    if v_escopo is null or v_escopo !~ '^[a-z_]{2,20}:[A-Za-z0-9._:/|-]{1,170}$' then
      raise exception 'Escopo inválido em %', v_conferencia using errcode = '22023';
    end if;
    if v_gravidade is null or v_gravidade not in ('CRITICA', 'ATENCAO', 'INFORMATIVO') then
      raise exception 'Gravidade inválida em %', v_conferencia using errcode = '22023';
    end if;
    if v_modulo is null or v_modulo not in ('analises', 'entrevistas', 'classificacao', 'aprovados', 'cargas') then
      raise exception 'Módulo inválido em %', v_conferencia using errcode = '22023';
    end if;
    if v_area is not null and not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
      raise exception 'Área inválida em %', v_conferencia using errcode = '22023';
    end if;
    begin
      v_edital := nullif(v_aviso ->> 'edital', '')::uuid;
      v_qt := (v_aviso ->> 'quantidade')::integer;
    exception when others then
      raise exception 'Edital ou quantidade inválidos em %', v_conferencia using errcode = '22023';
    end;
    if v_edital is not null and not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = v_edital) then
      raise exception 'Edital inexistente em %', v_conferencia using errcode = '22023';
    end if;
    if v_qt is null or v_qt < 1 then
      raise exception 'Quantidade inválida em %', v_conferencia using errcode = '22023';
    end if;
    if jsonb_typeof(v_exemplos) <> 'array' or jsonb_array_length(v_exemplos) > 20
       or exists (select 1 from jsonb_array_elements(v_exemplos) e
                   where jsonb_typeof(e) <> 'string'
                      or (e #>> '{}') !~ '^[A-Za-z0-9._:/-]{1,80}$'
                      or (e #>> '{}') ~ '[0-9]{11}') then
      raise exception 'Exemplos de % só com ids e códigos (até 20, sem espaço, sem @, sem 11 dígitos)', v_conferencia
        using errcode = '22023';
    end if;
    -- Casos: até 5000 objetos, cada um com análise (uuid), código ou referência
    -- (identificadores), o tipo da referência e o detalhe (objeto de valores
    -- simples, sem dado pessoal).
    if v_casos is not null and (
         jsonb_typeof(v_casos) <> 'array' or jsonb_array_length(v_casos) > 5000
         or exists (
           select 1 from jsonb_array_elements(v_casos) c
            where jsonb_typeof(c) <> 'object'
               or (c ? 'analise' and jsonb_typeof(c -> 'analise') <> 'null'
                   and coalesce(c ->> 'analise', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
               or (c ? 'codigo' and jsonb_typeof(c -> 'codigo') <> 'null'
                   and (coalesce(c ->> 'codigo', '') !~ '^[A-Za-z0-9._:/-]{1,80}$' or (c ->> 'codigo') ~ '[0-9]{11}'))
               or (c ? 'referencia' and jsonb_typeof(c -> 'referencia') <> 'null'
                   and (coalesce(c ->> 'referencia', '') !~ '^[A-Za-z0-9._:/-]{1,80}$' or (c ->> 'referencia') ~ '[0-9]{11}'))
               or (c ? 'tipo' and jsonb_typeof(c -> 'tipo') <> 'null'
                   and coalesce(c ->> 'tipo', '') not in ('candidato_aprovado', 'entrevista', 'lista_classificacao',
                                                          'ajuste_recurso', 'vaga', 'vaga_empregare'))
               or num_nonnulls(nullif(c ->> 'analise', ''), nullif(c ->> 'codigo', ''), nullif(c ->> 'referencia', '')) = 0
               or (c ? 'detalhe' and (
                     jsonb_typeof(c -> 'detalhe') <> 'object'
                     or exists (select 1 from jsonb_each(c -> 'detalhe') d
                                 where d.key !~ '^[a-z_]{1,30}$'
                                    or jsonb_typeof(d.value) not in ('string', 'number', 'boolean', 'null')
                                    or (jsonb_typeof(d.value) = 'string' and (d.value #>> '{}') !~ '^[A-Za-z0-9._:/-]{0,40}$')
                                    or (d.value #>> '{}') ~ '[0-9]{11}')
                     or length((c -> 'detalhe')::text) > 1000))
         )) then
      raise exception 'Casos de % só com ids, códigos, tipo conhecido e detalhe simples (até 5000, sem nome, @ ou 11 dígitos)', v_conferencia
        using errcode = '22023';
    end if;
    if length(v_resumo) not between 3 and 300 or not private."FC_TEXTO_SEGURO_DO_AVISO"(v_resumo) then
      raise exception 'Resumo de % vazio, longo ou com cara de dado pessoal', v_conferencia using errcode = '22023';
    end if;

    select * into v_atual from public."TB_AVISO_CONFERENCIA" a
     where a."CO_CONFERENCIA" = v_conferencia and a."DS_ESCOPO" = v_escopo
     for update;

    if v_atual."CO_AVISO_CONFERENCIA" is null then
      insert into public."TB_AVISO_CONFERENCIA" (
        "CO_CONFERENCIA", "DS_ESCOPO", "TP_GRAVIDADE", "CO_MODULO", "CO_AREA", "CO_MONITORAMENTO",
        "QT_OCORRENCIA", "DS_EXEMPLO", "DS_RESUMO", "CO_EXECUCAO")
      values (v_conferencia, v_escopo, v_gravidade, v_modulo, v_area, v_edital, v_qt, v_exemplos, v_resumo, p_execucao)
      returning "CO_AVISO_CONFERENCIA" into v_id;
      v_novos := v_novos + 1;
    elsif v_atual."TP_SITUACAO" = 'RESOLVIDO'
       or (v_atual."TP_SITUACAO" = 'IGNORADO' and v_qt > v_atual."QT_OCORRENCIA_IGNORADA") then
      v_id := v_atual."CO_AVISO_CONFERENCIA";
      update public."TB_AVISO_CONFERENCIA" set
        "TP_GRAVIDADE" = v_gravidade, "CO_MODULO" = v_modulo, "CO_AREA" = v_area, "CO_MONITORAMENTO" = v_edital,
        "QT_OCORRENCIA" = v_qt, "DS_EXEMPLO" = v_exemplos, "DS_RESUMO" = v_resumo, "CO_EXECUCAO" = p_execucao,
        "TP_SITUACAO" = 'ABERTO', "DT_ULTIMA_VEZ" = now(), "DT_RESOLUCAO" = null,
        "DT_PRIMEIRA_VEZ" = case when v_atual."TP_SITUACAO" = 'RESOLVIDO' then now() else "DT_PRIMEIRA_VEZ" end,
        "CO_USUARIO_IGNORADO" = null, "DT_IGNORADO" = null, "DS_MOTIVO_IGNORADO" = null, "QT_OCORRENCIA_IGNORADA" = null
       where "CO_AVISO_CONFERENCIA" = v_id;
      v_reabertos := v_reabertos + 1;
    else
      v_id := v_atual."CO_AVISO_CONFERENCIA";
      update public."TB_AVISO_CONFERENCIA" set
        "TP_GRAVIDADE" = v_gravidade, "CO_MODULO" = v_modulo, "CO_AREA" = v_area, "CO_MONITORAMENTO" = v_edital,
        "QT_OCORRENCIA" = v_qt, "DS_EXEMPLO" = v_exemplos, "DS_RESUMO" = v_resumo, "CO_EXECUCAO" = p_execucao,
        "DT_ULTIMA_VEZ" = now()
       where "CO_AVISO_CONFERENCIA" = v_id;
      v_mantidos := v_mantidos + 1;
    end if;

    -- Com 'casos', os do aviso são trocados pelos desta execução.
    if v_casos is not null then
      delete from public."TB_CASO_AVISO_CONFERENCIA" k where k."CO_AVISO_CONFERENCIA" = v_id;
      insert into public."TB_CASO_AVISO_CONFERENCIA" (
        "CO_AVISO_CONFERENCIA", "NU_CASO", "CO_ANALISE_CURRICULAR", "CO_CANDIDATO_EMPREGARE", "DS_REFERENCIA",
        "TP_REFERENCIA", "DS_DETALHE")
      select v_id, x.ordem::integer, nullif(x.caso ->> 'analise', '')::uuid,
             nullif(x.caso ->> 'codigo', ''), nullif(x.caso ->> 'referencia', ''), nullif(x.caso ->> 'tipo', ''),
             coalesce(case when jsonb_typeof(x.caso -> 'detalhe') = 'object' then x.caso -> 'detalhe' end, '{}'::jsonb)
        from jsonb_array_elements(v_casos) with ordinality as x(caso, ordem);
    end if;
  end loop;

  update public."TL_CONFERENCIA" set "QT_AVISO_NOVO" = "QT_AVISO_NOVO" + v_novos + v_reabertos
   where "CO_EXECUCAO" = p_execucao;
  return jsonb_build_object('novos', v_novos, 'reabertos', v_reabertos, 'mantidos', v_mantidos);
end;
$_$;

--
-- Name: FUNCTION gravar_avisos_conferencia(p_execucao text, p_avisos jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_avisos_conferencia(p_execucao text, p_avisos jsonb) IS 'Grava até 1000 avisos de uma execução (um por conferência + escopo): novo abre; resolvido reabre; ignorado reabre só se a quantidade passou da ignorada; aberto atualiza quantidade e exemplos. Com ''casos'' (até 5000: análise, código do candidato, referência, tipo da referência e o detalhe que motivou), troca os casos do aviso. Recusa (22023) exemplo ou caso que não seja id ou código (espaço, @, 11 dígitos), tipo desconhecido e resumo com cara de dado pessoal. Só service_role.';

--
-- Name: gravar_casamento_da_lista(text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_casamento_da_lista(p_execucao text, p_pedido uuid, p_plano jsonb, p_erro text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_p public."TB_PEDIDO_CASAMENTO_LISTA";
  v_vinculos jsonb;
  v_falha text;
begin
  if p_execucao is null or p_execucao !~ '^casam-[0-9]{8}T[0-9]{6}-[0-9a-f]{8}$' then
    raise exception 'Execução inválida.' using errcode = '22023';
  end if;
  select * into v_p from public."TB_PEDIDO_CASAMENTO_LISTA" where "CO_PEDIDO" = p_pedido for update;
  if v_p."CO_PEDIDO" is null then
    raise exception 'Pedido não encontrado.' using errcode = '22023';
  end if;
  -- Já respondido (ou descartado): não muda nada.
  if v_p."TP_SITUACAO" <> 'PENDENTE' then
    return json_build_object('ok', false, 'situacao', v_p."TP_SITUACAO");
  end if;

  if nullif(btrim(coalesce(p_erro, '')), '') is not null then
    v_falha := left(btrim(p_erro), 300);
  elsif private."FC_BASE_DA_LISTA"(v_p."CO_LISTA_APROVADO_ANTERIOR") is distinct from v_p."DS_BASE"
        or not exists (select 1 from public."TB_LISTA_APROVADO" l
                        where l.id = v_p."CO_LISTA_APROVADO_ANTERIOR" and l.vigente is true) then
    v_falha := 'A lista vigente mudou desde o pedido; peça a prévia de novo.';
  elsif jsonb_typeof(p_plano) is distinct from 'object' or (p_plano ->> 'versao') is distinct from '1'
        or jsonb_typeof(p_plano -> 'vinculos') is distinct from 'array'
        or jsonb_typeof(p_plano -> 'resumo') is distinct from 'object'
        or jsonb_typeof(p_plano -> 'pendencias') is distinct from 'array'
        or jsonb_typeof(p_plano -> 'mudam') is distinct from 'array'
        or jsonb_typeof(p_plano -> 'revisar') is distinct from 'array'
        or exists (select 1 from jsonb_each(p_plano -> 'resumo') r
                    where r.key not in ('casados', 'entram', 'sem_par', 'sem_dono', 'preservados', 'mudam',
                                        'sub_judice_mantidos', 'ambiguos')
                       or jsonb_typeof(r.value) <> 'number' or (r.value)::text::numeric < 0) then
    raise exception 'Plano em formato desconhecido.' using errcode = '22023';
  end if;

  if v_falha is not null then
    update public."TB_PEDIDO_CASAMENTO_LISTA"
       set "TP_SITUACAO" = 'ERRO', "DS_ERRO" = v_falha, "CO_EXECUCAO" = p_execucao, "DT_CALCULO" = now()
     where "CO_PEDIDO" = p_pedido;
    return json_build_object('ok', false, 'situacao', 'ERRO');
  end if;

  -- Os vínculos, conferidos: cada um da lista vigente e de quem entra, uma vez, na forma certa,
  -- e a revisão à mão respeitada.
  v_vinculos := p_plano -> 'vinculos';
  if exists (select 1 from jsonb_array_elements(v_vinculos) v(x)
              where jsonb_typeof(v.x) <> 'object'
                 or (v.x ->> 'candidato_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 or nullif(v.x ->> 'chave', '') is null
                 or (v.x ->> 'forma') not in ('ANALISE', 'NOME', 'NOME_VAGA', 'MANUAL')) then
    raise exception 'Vínculo inválido.' using errcode = '22023';
  end if;
  if (select count(*) <> count(distinct v.x ->> 'candidato_id') or count(*) <> count(distinct v.x ->> 'chave')
        from jsonb_array_elements(v_vinculos) v(x)) then
    raise exception 'Cada pessoa só pode ser vinculada uma vez.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(v_vinculos) v(x)
              where not exists (select 1 from public."TB_CANDIDATO_APROVADO" c
                                 where c.id = (v.x ->> 'candidato_id')::uuid
                                   and c.lista_id = v_p."CO_LISTA_APROVADO_ANTERIOR" and c.removido_em is null)) then
    raise exception 'Vínculo com candidato que não está na lista vigente.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(v_vinculos) v(x)
              where not exists (select 1 from jsonb_array_elements(v_p."DS_NOVOS") n(y)
                                 where n.y ->> 'chave' = v.x ->> 'chave')) then
    raise exception 'Vínculo com candidato que não está na lista nova.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(v_vinculos) v(x)
               join public."TB_CANDIDATO_APROVADO" c on c.id = (v.x ->> 'candidato_id')::uuid
              where v.x ->> 'forma' = 'ANALISE'
                and c."CO_ANALISE_CURRICULAR"::text is distinct from (
                      select n.y ->> 'analise_id' from jsonb_array_elements(v_p."DS_NOVOS") n(y)
                       where n.y ->> 'chave' = v.x ->> 'chave' limit 1)) then
    raise exception 'Vínculo pela análise com análise diferente.' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_each_text(v_p."DS_MANUAIS") m
              where (m.value = '' and exists (select 1 from jsonb_array_elements(v_vinculos) v(x)
                                                where v.x ->> 'candidato_id' = m.key))
                 or (m.value <> '' and exists (select 1 from jsonb_array_elements(v_p."DS_NOVOS") n(y)
                                                 where n.y ->> 'chave' = m.value)
                     and not exists (select 1 from jsonb_array_elements(v_vinculos) v(x)
                                      where v.x ->> 'candidato_id' = m.key and v.x ->> 'chave' = m.value
                                        and v.x ->> 'forma' = 'MANUAL'))) then
    raise exception 'O plano não respeita a revisão à mão.' using errcode = '22023';
  end if;
  if ((p_plano -> 'resumo' ->> 'casados')::integer) <> jsonb_array_length(v_vinculos) then
    raise exception 'O resumo não bate com os vínculos.' using errcode = '22023';
  end if;

  update public."TB_PEDIDO_CASAMENTO_LISTA"
     set "TP_SITUACAO" = 'CALCULADO', "DS_PLANO" = p_plano, "CO_EXECUCAO" = p_execucao, "DT_CALCULO" = now()
   where "CO_PEDIDO" = p_pedido;
  return json_build_object('ok', true, 'situacao', 'CALCULADO', 'casados', jsonb_array_length(v_vinculos));
end;
$_$;

--
-- Name: FUNCTION gravar_casamento_da_lista(p_execucao text, p_pedido uuid, p_plano jsonb, p_erro text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_casamento_da_lista(p_execucao text, p_pedido uuid, p_plano jsonb, p_erro text) IS 'Job do casamento (Python, só service_role): grava o plano do pedido pendente — ou o erro. Só valida (formato, cada vínculo da lista vigente e de quem entra, uma vez, análise igual na forma ANALISE, revisão à mão respeitada, lista vigente igual à do pedido) e guarda. 20261030090000.';

--
-- Name: gravar_contratacao_dos_aprovados(text, jsonb, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_contratacao_dos_aprovados(p_execucao text, p_decisoes jsonb, p_remover uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_decisoes jsonb := coalesce(p_decisoes, '[]'::jsonb);
  v_editais uuid[];
  v_gravadas integer := 0;
  v_removidas integer := 0;
  v_invalida text;
begin
  if p_execucao is null or p_execucao !~ '^contr-[0-9]{8}T[0-9]{6}-[0-9a-f]{8}$' then
    raise exception 'Execução inválida' using errcode = '22023';
  end if;
  if jsonb_typeof(v_decisoes) <> 'array' or jsonb_array_length(v_decisoes) > 2000
     or coalesce(array_length(p_remover, 1), 0) > 5000 then
    raise exception 'Lote inválido (até 2000 decisões e 5000 remoções)' using errcode = '22023';
  end if;

  drop table if exists t_decisao;
  create temporary table t_decisao on commit drop as
    select (d ->> 'candidato')::uuid as candidato, (d ->> 'edital')::uuid as edital, d ->> 'vinculo' as vinculo,
           d ->> 'situacao' as situacao, (d ->> 'contratacao')::uuid as contratacao, d ->> 'motivo' as motivo,
           d ->> 'texto' as texto, d ->> 'base' as base, (d ->> 'versao')::smallint as versao
      from jsonb_array_elements(v_decisoes) d;

  -- O banco só valida: cada linha é Contratado numa lista vigente do edital, com aquela
  -- matrícula, e a base é o conjunto de hoje das linhas Contratado da matrícula no edital.
  with atuais as (
    select c.id, l.edital_id::uuid as edital, private."FC_VINCULO_DA_MATRICULA"(c.matricula) as vinculo
      from public."TB_CANDIDATO_APROVADO" c
      join public."TB_LISTA_APROVADO" l on l.id = c.lista_id and l.vigente is true
     where c.removido_em is null and c.status = 'Contratado'
       and l.edital_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ), bases as (
    select a.edital, a.vinculo, string_agg(a.id::text, ',' order by a.id::text) as base
      from atuais a
     where (a.edital, a.vinculo) in (select edital, vinculo from t_decisao)
     group by 1, 2
  )
  select coalesce(
           (select 'duplicada' from t_decisao group by candidato having count(*) > 1 limit 1),
           (select 'campos' from t_decisao
             where candidato is null or edital is null or vinculo is null or situacao is null or motivo is null
                or texto is null or base is null or versao is distinct from 1 limit 1),
           (select 'linha' from t_decisao d
             where not exists (select 1 from atuais a
                                where a.id = d.candidato and a.edital = d.edital and a.vinculo = d.vinculo) limit 1),
           (select 'base' from t_decisao d
             where d.base is distinct from (select b.base from bases b where b.edital = d.edital and b.vinculo = d.vinculo)
                or position(',' in d.base) = 0 limit 1),
           (select 'escolha' from t_decisao d
             where d.contratacao is not null
               and not exists (select 1 from atuais a
                                where a.id = d.contratacao and a.edital = d.edital and a.vinculo = d.vinculo) limit 1),
           (select 'grupo' from t_decisao d
             group by d.edital, d.vinculo
            having count(distinct coalesce(d.contratacao::text, '-')) > 1
                or count(distinct d.motivo) > 1
                or count(*) <> cardinality(string_to_array(min(d.base), ',')) limit 1))
    into v_invalida;
  if v_invalida is not null then
    raise exception 'Decisão recusada (%)', v_invalida using errcode = '22023';
  end if;

  select array_agg(distinct e) into v_editais from (
    select x."CO_MONITORAMENTO" as e from public."TB_CONTRATACAO_APROVADO" x
     where x."CO_CANDIDATO_APROVADO" = any (coalesce(p_remover, '{}'))
    union select edital from t_decisao) s;

  delete from public."TB_CONTRATACAO_APROVADO" x where x."CO_CANDIDATO_APROVADO" = any (coalesce(p_remover, '{}'));
  get diagnostics v_removidas = row_count;

  -- Os CHECK da tabela recusam situação, motivo e escolha que não combinam.
  insert into public."TB_CONTRATACAO_APROVADO" as x (
    "CO_CANDIDATO_APROVADO", "CO_MONITORAMENTO", "DS_VINCULO", "TP_SITUACAO", "CO_CANDIDATO_CONTRATACAO",
    "TP_MOTIVO", "DS_MOTIVO", "DS_BASE", "NU_VERSAO_REGRA", "CO_EXECUCAO", "DT_DECISAO")
  select d.candidato, d.edital, d.vinculo, d.situacao, d.contratacao, d.motivo, btrim(d.texto), d.base, d.versao,
         p_execucao, now()
    from t_decisao d
  on conflict ("CO_CANDIDATO_APROVADO") do update set
    "CO_MONITORAMENTO" = excluded."CO_MONITORAMENTO", "DS_VINCULO" = excluded."DS_VINCULO",
    "TP_SITUACAO" = excluded."TP_SITUACAO", "CO_CANDIDATO_CONTRATACAO" = excluded."CO_CANDIDATO_CONTRATACAO",
    "TP_MOTIVO" = excluded."TP_MOTIVO", "DS_MOTIVO" = excluded."DS_MOTIVO", "DS_BASE" = excluded."DS_BASE",
    "NU_VERSAO_REGRA" = excluded."NU_VERSAO_REGRA", "CO_EXECUCAO" = excluded."CO_EXECUCAO",
    "DT_DECISAO" = excluded."DT_DECISAO";
  get diagnostics v_gravadas = row_count;

  -- Os contratados dos editais tocados e o pacote da Lista de aprovados das áreas deles.
  perform private."FC_ATUALIZAR_CONTRATADOS_DO_EDITAL"(e) from unnest(coalesce(v_editais, '{}')) e;
  perform private."FC_MARCAR_CACHE"(
    array['APROVADOS'],
    array(select distinct m."CO_AREA" from public."TB_MONITORAMENTO_INDIGENA" m where m.id = any (coalesce(v_editais, '{}'))),
    'TB_CONTRATACAO_APROVADO');

  return jsonb_build_object('ok', true, 'gravadas', v_gravadas, 'removidas', v_removidas,
                            'editais', coalesce(cardinality(v_editais), 0));
end;
$_$;

--
-- Name: FUNCTION gravar_contratacao_dos_aprovados(p_execucao text, p_decisoes jsonb, p_remover uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_contratacao_dos_aprovados(p_execucao text, p_decisoes jsonb, p_remover uuid[]) IS 'Job "Contratado em outra lista" (Python, só service_role): grava as decisões no instantâneo TB_CONTRATACAO_APROVADO e tira as de p_remover. Só valida — cada linha Contratado na lista vigente do edital, com aquele vínculo, a base igual ao conjunto de hoje, a escolha do mesmo grupo — e guarda; recalcula os contratados dos editais tocados e marca o pacote da Lista de aprovados. 20261024120000.';

--
-- Name: gravar_leituras_de_arquivos(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_leituras_de_arquivos(p_execucao text, p_leituras jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v jsonb;
  v_gravadas integer := 0;
  v_fora integer := 0;
  v_bool text;
  v_trocadas integer := 0;
begin
  if coalesce(p_execucao, '') !~ '^[A-Za-z0-9_.:-]{1,60}$' then
    raise exception 'Execução inválida' using errcode = '22023';
  end if;
  if jsonb_typeof(p_leituras) is distinct from 'array' or jsonb_array_length(p_leituras) > 200 then
    raise exception 'Envie até 200 leituras por vez' using errcode = '22023';
  end if;
  for v in select x from jsonb_array_elements(p_leituras) x loop
    -- Só anexo que existe (resposta, pergunta, arquivo); o resto é contado e ignorado.
    if coalesce(v ->> 'resposta', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(v ->> 'pergunta', '') !~ '^[0-9]{1,20}$' or coalesce(v ->> 'arquivo', '') !~ '^[0-9]{1,2}$'
       or not exists (select 1 from public."TB_EMPREGARE_ANEXO" a
                       where a."CO_EMPREGARE_RESPOSTA" = (v ->> 'resposta')::uuid
                         and a."CO_PERGUNTA_EMPREGARE" = v ->> 'pergunta'
                         and a."NU_ARQUIVO" = (v ->> 'arquivo')::smallint) then
      v_fora := v_fora + 1;
      continue;
    end if;
    -- [arquivo-trocado] (20261022170000) A leitura diz de qual arquivo é (hash_link_arquivo: sha256
    -- do arquivo= do link baixado). Se o robô da Empregare trocou o anexo enquanto a leitura
    -- rodava, ela é do arquivo antigo: fica de fora e o novo volta para a fila.
    if nullif(v ->> 'hash_link_arquivo', '') is not null and not exists (
         select 1 from public."TB_EMPREGARE_ANEXO" a
          where a."CO_EMPREGARE_RESPOSTA" = (v ->> 'resposta')::uuid
            and a."CO_PERGUNTA_EMPREGARE" = v ->> 'pergunta'
            and a."NU_ARQUIVO" = (v ->> 'arquivo')::smallint
            and encode(sha256(convert_to(coalesce(private."FC_ARQUIVO_DO_LINK_EMPREGARE"(a."DS_LINK"), a."DS_LINK"), 'UTF8')), 'hex')
                = v ->> 'hash_link_arquivo') then
      v_trocadas := v_trocadas + 1;
      v_fora := v_fora + 1;
      continue;
    end if;
    perform private."FC_VALIDAR_LEITURA_ARQUIVO"(v);
    insert into public."TB_LEITURA_ARQUIVO" (
      "CO_EMPREGARE_RESPOSTA", "CO_PERGUNTA_EMPREGARE", "NU_ARQUIVO", "TP_SITUACAO", "TP_METODO", "TP_FORMATO",
      "TP_DOCUMENTO", "QT_PAGINA", "VL_CONFIANCA_OCR", "ST_NOME_CONFERE", "ST_CPF_CONFERE", "DS_ITEM", "DS_ALERTA",
      "DS_RESUMO", "CO_ERRO", "DS_HASH_ARQUIVO", "NU_VERSAO_EXTRATOR", "CO_EXECUCAO", "DT_LEITURA")
    values (
      (v ->> 'resposta')::uuid, v ->> 'pergunta', (v ->> 'arquivo')::smallint, v ->> 'situacao', v ->> 'metodo',
      v ->> 'formato', v ->> 'documento', (v ->> 'paginas')::numeric::smallint, round((v ->> 'confianca')::numeric, 3),
      case v -> 'nome_confere' when 'true'::jsonb then 'S' when 'false'::jsonb then 'N' end,
      case v -> 'cpf_confere' when 'true'::jsonb then 'S' when 'false'::jsonb then 'N' end,
      coalesce(v -> 'itens', '[]'::jsonb), coalesce(v -> 'alertas', '[]'::jsonb), nullif(v ->> 'resumo', ''),
      v ->> 'erro', v ->> 'hash', v ->> 'versao', p_execucao, now())
    on conflict ("CO_EMPREGARE_RESPOSTA", "CO_PERGUNTA_EMPREGARE", "NU_ARQUIVO") do update set
      "TP_SITUACAO" = excluded."TP_SITUACAO", "TP_METODO" = excluded."TP_METODO", "TP_FORMATO" = excluded."TP_FORMATO",
      "TP_DOCUMENTO" = excluded."TP_DOCUMENTO", "QT_PAGINA" = excluded."QT_PAGINA",
      "VL_CONFIANCA_OCR" = excluded."VL_CONFIANCA_OCR", "ST_NOME_CONFERE" = excluded."ST_NOME_CONFERE",
      "ST_CPF_CONFERE" = excluded."ST_CPF_CONFERE", "DS_ITEM" = excluded."DS_ITEM", "DS_ALERTA" = excluded."DS_ALERTA",
      "DS_RESUMO" = excluded."DS_RESUMO", "CO_ERRO" = excluded."CO_ERRO", "DS_HASH_ARQUIVO" = excluded."DS_HASH_ARQUIVO",
      "NU_VERSAO_EXTRATOR" = excluded."NU_VERSAO_EXTRATOR", "CO_EXECUCAO" = excluded."CO_EXECUCAO",
      "DT_LEITURA" = excluded."DT_LEITURA";
    v_gravadas := v_gravadas + 1;
  end loop;
  return jsonb_build_object('recebidas', jsonb_array_length(p_leituras), 'gravadas', v_gravadas, 'fora', v_fora,
                            'trocadas', v_trocadas);
end;
$_$;

--
-- Name: FUNCTION gravar_leituras_de_arquivos(p_execucao text, p_leituras jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_leituras_de_arquivos(p_execucao text, p_leituras jsonb) IS 'Recebe do robô da leitura dos arquivos (Python) até 200 leituras: [{resposta, pergunta, arquivo, situacao, metodo, formato, documento, paginas, confianca, nome_confere, cpf_confere, itens, alertas, resumo, erro, hash, versao}]. Só anexo que existe em TB_EMPREGARE_ANEXO; cada leitura conferida por FC_VALIDAR_LEITURA_ARQUIVO; troca a leitura anterior do mesmo anexo. Só service_role.';

--
-- Name: gravar_lote_empregare(text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_lote_empregare(p_sync text, p_vaga text, p_total integer, p_linhas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET work_mem TO '32MB'
    AS $_$
declare
  v_situacao text;
  v_qt integer;
  v_com_link integer;
begin
  perform private."FC_EMPREGARE_EXIGIR_SYNC"(p_sync);
  if p_vaga is null or p_vaga !~ '^[0-9]{1,20}$' then
    raise exception 'Código de vaga inválido' using errcode = '22023';
  end if;
  if coalesce(p_total, -1) not between 1 and 50000 then
    raise exception 'Total de candidatos fora de 1 a 50000' using errcode = '22023';
  end if;
  if jsonb_typeof(p_linhas) is distinct from 'array' or jsonb_array_length(p_linhas) not between 1 and 1000 then
    raise exception 'Envie de 1 a 1000 linhas por lote' using errcode = '22023';
  end if;

  v_situacao := private."FC_EMPREGARE_ABRIR_VAGA"(p_sync, p_vaga, p_total);
  if v_situacao <> 'EM_CARGA' then
    return jsonb_build_object('situacao', v_situacao, 'gravadas', 0);
  end if;

  with lote as materialized (
    select distinct on (l.chave)
           l.chave, l.tipo,
           nullif(left(btrim(l.codigo), 60), '') as codigo,
           nullif(left(btrim(l.nome), 300), '') as nome,
           nullif(left(lower(btrim(l.email)), 320), '') as email,
           case when l.cpf ~ '^[0-9]{11}$' then l.cpf end as cpf,
           nullif(left(btrim(l.telefone), 60), '') as telefone,
           private."FC_EMPREGARE_DATA"(l.nascimento) as nascimento,
           nullif(left(btrim(l.situacao), 200), '') as situacao,
           private."FC_EMPREGARE_MOMENTO"(l.candidatura) as candidatura,
           l.colunas,
           encode(sha256(convert_to(l.colunas::text, 'UTF8')), 'hex') as hash,
           -- Link fora do formato (outro site, javascript:, aspas) vira nulo: mantém o anterior.
           case when l.link ~ '^https://corporate\.empregare\.com/empresa/curriculo/detalhes\?[A-Za-z0-9_.~=&%|+/:-]+$'
                     and length(l.link) <= 600
                then l.link end as link
      from jsonb_to_recordset(p_linhas) as l(
        chave text, tipo text, codigo text, nome text, email text, cpf text, telefone text,
        nascimento text, situacao text, candidatura text, colunas jsonb, link text)
     where l.chave ~ '^(cod:[A-Za-z0-9._-]{1,60}|cpf:[0-9a-f]{64}|email:[0-9a-f]{64})$'
       and l.tipo in ('CODIGO', 'CPF', 'EMAIL')
       and jsonb_typeof(l.colunas) = 'object'
     order by l.chave
  ),
  gravadas as (
    insert into public."TB_EMPREGARE_CANDIDATO" as c (
      "CO_VAGA", "DS_CHAVE_CANDIDATO", "TP_CHAVE", "CO_CANDIDATO_EMPREGARE", "NO_CANDIDATO", "DS_EMAIL",
      "NU_CPF", "NU_TELEFONE", "DT_NASCIMENTO", "DS_SITUACAO_EMPREGARE", "DT_CANDIDATURA",
      "DS_COLUNA_ORIGINAL", "DS_HASH_LINHA", "CO_SYNC", "ST_REGISTRO_ATIVO", "DS_LINK_DETALHE", "DT_CAPTURA_LINK")
    select p_vaga, t.chave, t.tipo, t.codigo, t.nome, t.email, t.cpf, t.telefone, t.nascimento,
           t.situacao, t.candidatura, t.colunas, t.hash, p_sync, 'S', t.link,
           case when t.link is not null then now() end
      from lote t
    on conflict ("CO_VAGA", "DS_CHAVE_CANDIDATO") do update set
      "TP_CHAVE" = excluded."TP_CHAVE",
      "CO_CANDIDATO_EMPREGARE" = excluded."CO_CANDIDATO_EMPREGARE",
      "NO_CANDIDATO" = excluded."NO_CANDIDATO",
      "DS_EMAIL" = excluded."DS_EMAIL",
      "NU_CPF" = excluded."NU_CPF",
      "NU_TELEFONE" = excluded."NU_TELEFONE",
      "DT_NASCIMENTO" = excluded."DT_NASCIMENTO",
      "DS_SITUACAO_EMPREGARE" = excluded."DS_SITUACAO_EMPREGARE",
      "DT_CANDIDATURA" = excluded."DT_CANDIDATURA",
      -- Mesmo hash: mantém o valor gravado (o TOAST anterior é reaproveitado, nada de reescrever ~3 KB).
      "DS_COLUNA_ORIGINAL" = case
        when c."DS_HASH_LINHA" is distinct from excluded."DS_HASH_LINHA" then excluded."DS_COLUNA_ORIGINAL"
        else c."DS_COLUNA_ORIGINAL" end,
      "DS_HASH_LINHA" = excluded."DS_HASH_LINHA",
      "CO_SYNC" = excluded."CO_SYNC",
      "DT_ATUALIZACAO" = case
        when c."DS_HASH_LINHA" is distinct from excluded."DS_HASH_LINHA" or c."ST_REGISTRO_ATIVO" = 'N' then now()
        else c."DT_ATUALIZACAO" end,
      "DT_CONFERENCIA" = now(),
      "ST_REGISTRO_ATIVO" = 'S',
      "DT_DESATIVACAO" = null,
      "DS_LINK_DETALHE" = coalesce(excluded."DS_LINK_DETALHE", c."DS_LINK_DETALHE"),
      "DT_CAPTURA_LINK" = coalesce(excluded."DT_CAPTURA_LINK", c."DT_CAPTURA_LINK")
    returning 1
  )
  select (select count(*) from gravadas), count(*) filter (where t.link is not null)
    into v_qt, v_com_link
    from lote t;

  update public."TB_EMPREGARE_VAGA" set "QT_RECEBIDA" = "QT_RECEBIDA" + v_qt, "DT_ATUALIZACAO" = now()
   where "CO_VAGA" = p_vaga;
  update public."TL_SYNC_EMPREGARE" set "QT_LINHA" = "QT_LINHA" + v_qt where "CO_SYNC" = p_sync;
  return jsonb_build_object('situacao', 'EM_CARGA', 'recebidas', jsonb_array_length(p_linhas), 'gravadas', v_qt,
                            'com_link', v_com_link);
end;
$_$;

--
-- Name: FUNCTION gravar_lote_empregare(p_sync text, p_vaga text, p_total integer, p_linhas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_lote_empregare(p_sync text, p_vaga text, p_total integer, p_linhas jsonb) IS 'Recebe um lote (até 1000; o robô manda 200) de candidatos de uma vaga e faz upsert em TB_EMPREGARE_CANDIDATO pela chave natural (o hash da linha diz se mudou; mesmo hash não reescreve o questionário). Cada linha aceita "link" (opcional): o link da página de detalhes do candidato na Empregare, gravado em DS_LINK_DETALHE quando válido; sem link, fica o anterior. p_total = candidatos do arquivo inteiro: no primeiro lote da vaga, a trava recusa (RECUSADA, nada gravado) o arquivo com menos da metade dos ativos sem forçar. Os ausentes só saem em fechar_vaga_empregare, no fim da vaga. work_mem de 32 MB só nesta função. Só service_role.';

--
-- Name: gravar_pendencias_do_edital(text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_pendencias_do_edital(p_execucao text, p_lido_em timestamp with time zone, p_pendencias jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_pendencias jsonb := coalesce(p_pendencias, '[]'::jsonb);
  v_invalida text;
  v_novas integer := 0;
  v_mantidas integer := 0;
  v_reabertas integer := 0;
  v_permanentes integer := 0;
  v_saneadas integer := 0;
begin
  if p_execucao is null or p_execucao !~ '^pend-[0-9]{8}T[0-9]{6}-[0-9a-f]{8}$' then
    raise exception 'Execução inválida' using errcode = '22023';
  end if;
  if p_lido_em is null or p_lido_em > now() or p_lido_em < now() - interval '1 day' then
    raise exception 'Leitura inválida (de quando o job leu as listas, no último dia)' using errcode = '22023';
  end if;
  if jsonb_typeof(v_pendencias) <> 'array' or jsonb_array_length(v_pendencias) > 5000 then
    raise exception 'Lote inválido (até 5000 pendências)' using errcode = '22023';
  end if;

  drop table if exists t_pendencia;
  create temporary table t_pendencia on commit drop as
    select p ->> 'tipo' as tipo, (p ->> 'edital')::uuid as edital, p ->> 'chave' as chave,
           array(select (c #>> '{}')::uuid from jsonb_array_elements(coalesce(p -> 'candidatos', '[]'::jsonb)) c
                  order by 1) as candidatos,
           coalesce(p -> 'detalhe', '{}'::jsonb) as detalhe
      from jsonb_array_elements(v_pendencias) p;

  -- O banco só valida: tipo, chave e detalhe no formato; cada linha numa lista vigente do edital.
  select coalesce(
           (select 'duplicada' from t_pendencia group by tipo, chave having count(*) > 1 limit 1),
           (select 'campos' from t_pendencia
             where tipo is null or edital is null or chave is null
                or tipo not in ('CONTRATADO_DUAS_MATRICULAS', 'CONTRATADO_EM_DUAS_LISTAS', 'PESSOA_REPETIDA',
                                'POSICAO_REPETIDA', 'CONVOCADO_SEM_DESFECHO')
                or chave !~ '^[0-9a-f]{40}$'
                or cardinality(candidatos) not between 1 and 50
                or jsonb_typeof(detalhe) <> 'object' or length(detalhe::text) > 1000
                or detalhe::text ~ '@' or detalhe::text ~ '[0-9]{11}' limit 1),
           (select 'edital' from t_pendencia t
             where not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = t.edital) limit 1),
           (select 'linha' from t_pendencia t cross join unnest(t.candidatos) c(id)
             where not exists (select 1 from public."TB_CANDIDATO_APROVADO" a
                                 join public."TB_LISTA_APROVADO" l on l.id = a.lista_id and l.vigente is true
                                where a.id = c.id and a.removido_em is null and l.edital_id = t.edital::text) limit 1))
    into v_invalida;
  if v_invalida is not null then
    raise exception 'Pendências recusadas (%)', v_invalida using errcode = '22023';
  end if;

  -- A aberta que sumiu da lista: resolvida fora daqui (SANEADA).
  with saneadas as (
    update public."TB_PENDENCIA_APROVADO" p
       set "TP_SITUACAO" = 'RESOLVIDA', "TP_DECISAO" = 'SANEADA', "DT_RESOLUCAO" = now()
     where p."TP_SITUACAO" = 'ABERTA'
       and not exists (select 1 from t_pendencia t where t.tipo = p."TP_PENDENCIA" and t.chave = p."DS_CHAVE")
    returning p."CO_PENDENCIA_APROVADO"
  )
  insert into public."TH_PENDENCIA_APROVADO" ("CO_PENDENCIA_APROVADO", "TP_EVENTO", "TP_DECISAO", "CO_EXECUCAO")
  select s."CO_PENDENCIA_APROVADO", 'SANEADA', 'SANEADA', p_execucao from saneadas s;
  get diagnostics v_saneadas = row_count;

  -- A aberta que continua: o detalhe e as linhas de hoje.
  update public."TB_PENDENCIA_APROVADO" p
     set "CO_CANDIDATO_APROVADO" = t.candidatos, "DS_DETALHE" = t.detalhe, "DT_ULTIMA_DETECCAO" = now(),
         "CO_EXECUCAO" = p_execucao
    from t_pendencia t
   where t.tipo = p."TP_PENDENCIA" and t.chave = p."DS_CHAVE" and p."TP_SITUACAO" = 'ABERTA';
  get diagnostics v_mantidas = row_count;

  -- O empate confirmado e as pessoas diferentes não voltam; a resolvida depois da leitura do job também não.
  update public."TB_PENDENCIA_APROVADO" p
     set "DT_ULTIMA_DETECCAO" = now(), "CO_EXECUCAO" = p_execucao
    from t_pendencia t
   where t.tipo = p."TP_PENDENCIA" and t.chave = p."DS_CHAVE" and p."TP_SITUACAO" = 'RESOLVIDA'
     and (p."TP_DECISAO" in ('EMPATE_PREVISTO', 'PESSOAS_DIFERENTES') or p."DT_RESOLUCAO" >= p_lido_em);
  get diagnostics v_permanentes = row_count;

  -- A resolvida que voltou: reabre.
  with reabertas as (
    update public."TB_PENDENCIA_APROVADO" p
       set "TP_SITUACAO" = 'ABERTA', "TP_DECISAO" = null, "DS_MOTIVO_DECISAO" = null, "CO_USUARIO_DECISAO" = null,
           "DT_RESOLUCAO" = null, "CO_CANDIDATO_APROVADO" = t.candidatos, "DS_DETALHE" = t.detalhe,
           "DT_DETECCAO" = now(), "DT_ULTIMA_DETECCAO" = now(), "CO_EXECUCAO" = p_execucao
      from t_pendencia t
     where t.tipo = p."TP_PENDENCIA" and t.chave = p."DS_CHAVE" and p."TP_SITUACAO" = 'RESOLVIDA'
       and p."TP_DECISAO" not in ('EMPATE_PREVISTO', 'PESSOAS_DIFERENTES') and p."DT_RESOLUCAO" < p_lido_em
    returning p."CO_PENDENCIA_APROVADO"
  )
  insert into public."TH_PENDENCIA_APROVADO" ("CO_PENDENCIA_APROVADO", "TP_EVENTO", "CO_EXECUCAO")
  select r."CO_PENDENCIA_APROVADO", 'REABERTA', p_execucao from reabertas r;
  get diagnostics v_reabertas = row_count;

  -- As novas.
  with novas as (
    insert into public."TB_PENDENCIA_APROVADO" (
      "CO_MONITORAMENTO", "CO_AREA", "TP_PENDENCIA", "DS_CHAVE", "CO_CANDIDATO_APROVADO", "DS_DETALHE", "CO_EXECUCAO")
    select t.edital, m."CO_AREA", t.tipo, t.chave, t.candidatos, t.detalhe, p_execucao
      from t_pendencia t
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = t.edital
     where not exists (select 1 from public."TB_PENDENCIA_APROVADO" p
                        where p."TP_PENDENCIA" = t.tipo and p."DS_CHAVE" = t.chave)
    returning "CO_PENDENCIA_APROVADO"
  )
  insert into public."TH_PENDENCIA_APROVADO" ("CO_PENDENCIA_APROVADO", "TP_EVENTO", "CO_EXECUCAO")
  select n."CO_PENDENCIA_APROVADO", 'ABERTA', p_execucao from novas n;
  get diagnostics v_novas = row_count;

  return jsonb_build_object('ok', true, 'novas', v_novas, 'mantidas', v_mantidas, 'reabertas', v_reabertas,
                            'permanentes', v_permanentes, 'saneadas', v_saneadas);
end;
$_$;

--
-- Name: FUNCTION gravar_pendencias_do_edital(p_execucao text, p_lido_em timestamp with time zone, p_pendencias jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_pendencias_do_edital(p_execucao text, p_lido_em timestamp with time zone, p_pendencias jsonb) IS 'Job "Pendências do edital" (Python, só service_role): grava o instantâneo de hoje (todas as pendências detectadas). Só valida — tipo, chave, detalhe e cada linha numa lista vigente do edital — e guarda: abre as novas, mantém as abertas, reabre a resolvida que voltou (não o empate confirmado, as pessoas diferentes nem a resolvida depois de p_lido_em) e dá como SANEADA a aberta que sumiu. Histórico em TH_PENDENCIA_APROVADO. 20261026190000.';

--
-- Name: gravar_pre_classificacao_vaga(text, uuid, text, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_pre_classificacao_vaga(p_execucao text, p_edital uuid, p_vaga text, p_versao_regra integer, p_resumo jsonb, p_linhas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '30s'
    AS $_$
declare
  v_exec public."TL_PRE_CLASSIFICACAO" := private."FC_EXIGIR_EXECUCAO_PRECLASSIF"(p_execucao);
  v_refazer boolean := v_exec."ST_REFAZER_LOTE" = 'S';
  v_quadro public."TB_QUADRO_VAGA_EDITAL";
  v_qt integer;
  v_erro text;
  v_mudancas integer;
  v_avisos jsonb := coalesce(p_resumo -> 'avisos', '[]'::jsonb);
  v_ant jsonb;
  v_iniciadas integer;
  v_quadro_id uuid;
begin
  -- A regra usada é a vigente e está conferida.
  if not exists (select 1 from public."TB_REGRA_ANALISE" r
                  where r."CO_MONITORAMENTO" = p_edital and r."NU_VERSAO_VIGENTE" = p_versao_regra
                    and r."TP_SITUACAO" = 'CONFERIDA') then
    raise exception 'A regra do edital mudou ou não está conferida; rode de novo' using errcode = 'PT409';
  end if;
  -- Refazer o lote do zero só com TODAS as fichas do edital intocadas: PENDENTE (ou FORA_LOTE),
  -- nunca atribuídas, reservadas, salvas nem concluídas, e no histórico só as ações do lote
  -- (FC_FICHA_INICIADA). A trava é a mesma da abertura das fichas (20261013110000).
  if v_refazer then
    perform pg_advisory_xact_lock(hashtextextended('avaliacao-documental:fichas:' || p_edital::text, 0));
    v_iniciadas := private."FC_FICHAS_INICIADAS"(p_edital);
    if v_iniciadas > 0 then
      raise exception 'Lote não refeito: o lote já está em análise: % fichas iniciadas', v_iniciadas
        using errcode = '55000';
    end if;
  end if;
  if not exists (select 1 from public."TB_EMPREGARE_VAGA" v where v."CO_VAGA" = p_vaga and v."CO_MONITORAMENTO" = p_edital) then
    raise exception 'A vaga % não é do edital', p_vaga using errcode = '22023';
  end if;
  if jsonb_typeof(p_linhas) is distinct from 'array' or jsonb_array_length(p_linhas) > 20000 then
    raise exception 'Linhas inválidas (lista de até 20000)' using errcode = '22023';
  end if;
  if jsonb_typeof(p_resumo) is distinct from 'object' or jsonb_typeof(v_avisos) <> 'array' or jsonb_array_length(v_avisos) > 50
     or exists (select 1 from jsonb_array_elements(v_avisos) a where jsonb_typeof(a) <> 'string' or a #>> '{}' !~ '^[A-Z][A-Z0-9_:]{1,59}$')
     or length(coalesce(p_resumo ->> 'descricao', '')) > 200
     or (p_resumo -> 'tamanho' is not null and jsonb_typeof(p_resumo -> 'tamanho') not in ('number', 'null'))
     or (p_resumo -> 'por_modalidade' is not null and jsonb_typeof(p_resumo -> 'por_modalidade') not in ('object', 'null'))
     or (p_resumo ? 'quadro' and jsonb_typeof(p_resumo -> 'quadro') not in ('string', 'null')) then
    raise exception 'Resumo da vaga inválido' using errcode = '22023';
  end if;

  -- As linhas lidas do JSON UMA vez (antes, cada conferência relia o p_linhas inteiro).
  drop table if exists pg_temp.t_linhas_vaga;
  begin
    create temporary table t_linhas_vaga on commit drop as
      select * from private."FC_LINHAS_PRE_CLASSIF"(p_linhas);
  exception when invalid_text_representation or numeric_value_out_of_range or datatype_mismatch then
    raise exception 'Linha com tipo inválido (id, nota, posição ou lote)' using errcode = '22023';
  end;
  analyze pg_temp.t_linhas_vaga;

  -- A forma do resultado (as mesmas regras das CK_, com mensagem clara).
  select case
    when exists (select 1 from pg_temp.t_linhas_vaga t where t.id is null) then 'linha sem id'
    when (select count(*) from pg_temp.t_linhas_vaga) <> (select count(distinct t.id) from pg_temp.t_linhas_vaga t) then 'inscrito repetido'
    when exists (select 1 from pg_temp.t_linhas_vaga t
                  where not exists (select 1 from public."TB_EMPREGARE_CANDIDATO" c
                                     where c."CO_EMPREGARE_CANDIDATO" = t.id and c."CO_VAGA" = p_vaga)) then 'inscrito que não é da vaga'
    when exists (select 1 from public."TB_PRE_CLASSIFICACAO" a
                  where a."CO_MONITORAMENTO" = p_edital and a."CO_VAGA" = p_vaga
                    and not exists (select 1 from pg_temp.t_linhas_vaga t where t.id = a."CO_EMPREGARE_CANDIDATO")) then 'faltam inscritos já pré-classificados'
    when exists (select 1 from pg_temp.t_linhas_vaga t where t.situacao is null or t.situacao not in ('ELIMINADO', 'RANQUEADO', 'NO_LOTE', 'ANALISADO')) then 'situação inválida'
    when exists (select 1 from pg_temp.t_linhas_vaga t
                  where (t.situacao = 'ELIMINADO') <> (t.motivo_codigo is not null)
                     or (t.motivo_codigo is not null and (t.motivo_codigo !~ '^[A-Z][A-Z0-9_]{1,29}$'
                         or coalesce(length(btrim(t.motivo)), 0) not between 1 and 200))) then 'eliminado sem motivo (ou motivo fora de eliminado)'
    when exists (select 1 from pg_temp.t_linhas_vaga t
                  where (t.situacao = 'ELIMINADO' and (t.posicao is not null or t.posicao_modalidade is not null))
                     or (t.situacao <> 'ELIMINADO' and (coalesce(t.posicao, 0) < 1 or coalesce(t.posicao_modalidade, 0) < 1))) then 'posição inválida'
    when (select count(*) from pg_temp.t_linhas_vaga t where t.situacao <> 'ELIMINADO')
         <> coalesce((select max(t.posicao) from pg_temp.t_linhas_vaga t where t.situacao <> 'ELIMINADO'), 0)
      or (select count(distinct t.posicao) from pg_temp.t_linhas_vaga t where t.situacao <> 'ELIMINADO')
         <> (select count(*) from pg_temp.t_linhas_vaga t where t.situacao <> 'ELIMINADO') then 'posições não vão de 1 a N sem repetir'
    when exists (select 1 from pg_temp.t_linhas_vaga t
                  where case when t.situacao in ('NO_LOTE', 'ANALISADO')
                             then coalesce(t.lote, 0) not between 1 and 999
                                  or coalesce(t.lista_lote, '') !~ '^(GERAL|[A-Z]{2,10})$'
                                  or coalesce(t.entrada, '') not in ('INICIAL', 'REPOSICAO', 'AMPLIACAO', 'DECISAO')
                                  or length(coalesce(t.motivo_entrada, '')) > 300
                             else t.lote is not null or t.lista_lote is not null or t.entrada is not null end) then 'lote inválido'
    when exists (select 1 from pg_temp.t_linhas_vaga t
                  where coalesce(t.origem_nota, 'ART') not in ('ART', 'DECLARADA')
                     or t.modalidade !~ '^[A-Z]{2,10}$'
                     -- As cotas optadas (20261015150000): códigos sem a ampla, a principal primeiro.
                     or jsonb_typeof(t.modalidades) is distinct from 'array'
                     or jsonb_array_length(t.modalidades) > 10
                     or exists (select 1 from jsonb_array_elements(t.modalidades) m
                                 where jsonb_typeof(m) <> 'string' or m #>> '{}' !~ '^[A-Z]{2,10}$' or m #>> '{}' = 'AC')
                     or (t.modalidade = 'AC') <> (jsonb_array_length(t.modalidades) = 0)
                     or (t.modalidade <> 'AC' and t.modalidades ->> 0 is distinct from t.modalidade)
                     or abs(coalesce(t.art, 0)) > 1000 or abs(coalesce(t.nota, 0)) > 1000 or abs(coalesce(t.declarada, 0)) > 1000
                     or t.sem_mapa not between 0 and 100) then 'nota, origem ou modalidade inválida'
    -- A declarada congelada: completa, com o total igual à declarada da linha.
    when exists (select 1 from pg_temp.t_linhas_vaga t
                  where t.declarada_congelada is not null
                    and (jsonb_typeof(t.declarada_congelada -> 'total') is distinct from 'number'
                         or (t.declarada_congelada ->> 'total')::numeric not between 0 and 1000
                         or (t.declarada_congelada ->> 'total')::numeric is distinct from t.declarada
                         or t.declarada_completa is not true
                         or jsonb_typeof(coalesce(t.declarada_congelada -> 'respostas', '[]'::jsonb)) <> 'array'
                         or jsonb_array_length(coalesce(t.declarada_congelada -> 'respostas', '[]'::jsonb)) > 20
                         or length(t.declarada_congelada::text) > 20000)) then 'declarada congelada inválida'
    else null end
    into v_erro;
  if v_erro is not null then
    raise exception 'Resultado da vaga % recusado: %', p_vaga, v_erro using errcode = '22023';
  end if;

  -- A situação de antes de cada inscrito (para as travas e o histórico).
  select coalesce(jsonb_object_agg(a."CO_EMPREGARE_CANDIDATO",
                                   jsonb_build_object('s', a."TP_SITUACAO", 'l', a."NU_LOTE", 'e', a."TP_ENTRADA_LOTE")), '{}'::jsonb)
    into v_ant
    from public."TB_PRE_CLASSIFICACAO" a
   where a."CO_MONITORAMENTO" = p_edital and a."CO_VAGA" = p_vaga;

  -- As decisões da coordenação (TB_DECISAO_LOTE): toda decisão vigente aplicada (no lote) e só
  -- entra por decisão quem tem decisão vigente, com o mesmo motivo.
  select case
    when exists (select 1 from pg_temp.t_linhas_vaga t
                   join public."TB_DECISAO_LOTE" d
                     on d."CO_MONITORAMENTO" = p_edital and d."CO_EMPREGARE_CANDIDATO" = t.id and d."ST_ATIVO" = 'S'
                  where t.situacao = 'RANQUEADO'
                     or (t.situacao = 'ELIMINADO' and t.motivo_codigo is distinct from 'SAIU_DA_EMPREGARE')) then 'decisão da coordenação não aplicada'
    when exists (select 1 from pg_temp.t_linhas_vaga t
                  where t.entrada = 'DECISAO'
                    and not exists (select 1 from public."TB_DECISAO_LOTE" d
                                     where d."CO_MONITORAMENTO" = p_edital and d."CO_EMPREGARE_CANDIDATO" = t.id and d."ST_ATIVO" = 'S'
                                       and btrim(d."DS_MOTIVO") = btrim(coalesce(t.motivo_entrada, '')))) then 'entrada por decisão sem decisão vigente'
    else null end
    into v_erro;
  if v_erro is not null then
    raise exception 'Resultado da vaga % recusado: %', p_vaga, v_erro using errcode = '22023';
  end if;

  -- A declarada congelada não muda: só a coordenação descongela (descongelar_declarada_pre_classificacao).
  if exists (select 1 from pg_temp.t_linhas_vaga t
               join public."TB_PRE_CLASSIFICACAO" a
                 on a."CO_MONITORAMENTO" = p_edital and a."CO_EMPREGARE_CANDIDATO" = t.id
              where a."VL_DECLARADA_CONGELADA" is not null and t.declarada is not null
                and t.declarada is distinct from a."VL_DECLARADA_CONGELADA") then
    raise exception 'Resultado da vaga % recusado: a nota declarada congelada não muda (descongele antes)', p_vaga using errcode = '22023';
  end if;

  -- Quem tem ficha (ANALISADO) não muda; ANALISADO só vem do banco (fase F3).
  if exists (select 1 from pg_temp.t_linhas_vaga t
               cross join lateral (select v_ant -> t.id::text ->> 's' as ant_situacao, (v_ant -> t.id::text ->> 'l')::integer as ant_lote) h
              where (h.ant_situacao is not distinct from 'ANALISADO') <> (t.situacao = 'ANALISADO')
                 or (h.ant_situacao = 'ANALISADO' and h.ant_lote is distinct from t.lote)) then
    raise exception 'Resultado da vaga % recusado: quem já tem ficha não muda', p_vaga using errcode = '22023';
  end if;
  -- Quem está no lote só sai eliminado (a não ser que a execução refaça o lote); quem entrou
  -- por decisão da coordenação já revogada sai.
  if not v_refazer and exists (
      select 1 from pg_temp.t_linhas_vaga t
       cross join lateral (select v_ant -> t.id::text ->> 's' as ant_situacao, (v_ant -> t.id::text ->> 'l')::integer as ant_lote,
                                  v_ant -> t.id::text ->> 'e' as ant_entrada) h
       where h.ant_situacao = 'NO_LOTE'
         and not (t.situacao = 'ELIMINADO' or (t.situacao = 'NO_LOTE' and t.lote = h.ant_lote))
         and not (h.ant_entrada = 'DECISAO'
                  and not exists (select 1 from public."TB_DECISAO_LOTE" d
                                   where d."CO_MONITORAMENTO" = p_edital and d."CO_EMPREGARE_CANDIDATO" = t.id and d."ST_ATIVO" = 'S'))) then
    raise exception 'Resultado da vaga % recusado: quem está no lote só sai eliminado (AM-5.5)', p_vaga using errcode = '22023';
  end if;

  -- Grava o resultado (rodar de novo atualiza a mesma linha: AM-4.2).
  insert into public."TB_PRE_CLASSIFICACAO" as a
    ("CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO", "CO_VAGA", "NU_VERSAO_REGRA", "TP_SITUACAO",
     "CO_MOTIVO_ELIMINACAO", "DS_MOTIVO_ELIMINACAO", "VL_ART", "VL_NOTA_ORDEM", "TP_ORIGEM_NOTA",
     "VL_NOTA_DECLARADA", "DS_NOTA_DECLARADA", "ST_DIVERGENTE", "NO_MODALIDADE", "NU_POSICAO",
     "NU_POSICAO_MODALIDADE", "NU_LOTE", "CO_LISTA_LOTE", "TP_ENTRADA_LOTE", "DS_MOTIVO_ENTRADA",
     "DT_ENTRADA_LOTE", "CO_EXECUCAO", "VL_DECLARADA_CONGELADA", "DS_DECLARADA_CONGELADA", "DT_CONGELAMENTO_DECLARADA",
     "DS_MODALIDADES")
  select p_edital, t.id, p_vaga, p_versao_regra, t.situacao,
         t.motivo_codigo, left(btrim(t.motivo), 200), t.art, t.nota, t.origem_nota,
         t.declarada,
         case when t.declarada is null then null
              else jsonb_build_object('parciais', coalesce(t.declarada_parciais, '{}'::jsonb), 'sem_mapa', t.sem_mapa,
                                      'completa', t.declarada_completa) end,
         case when t.divergente then 'S' else 'N' end, t.modalidade, t.posicao,
         t.posicao_modalidade, t.lote, t.lista_lote, t.entrada, nullif(left(btrim(t.motivo_entrada), 300), ''),
         case when t.lote is not null then now() end, p_execucao,
         (t.declarada_congelada ->> 'total')::numeric,
         case when t.declarada_congelada is not null
              then (t.declarada_congelada - 'total') || jsonb_build_object('versao_regra', p_versao_regra) end,
         case when t.declarada_congelada is not null then now() end,
         t.modalidades
    from pg_temp.t_linhas_vaga t
  on conflict ("CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO") do update set
    "NU_VERSAO_REGRA" = excluded."NU_VERSAO_REGRA",
    "TP_SITUACAO" = excluded."TP_SITUACAO",
    "CO_MOTIVO_ELIMINACAO" = excluded."CO_MOTIVO_ELIMINACAO",
    "DS_MOTIVO_ELIMINACAO" = excluded."DS_MOTIVO_ELIMINACAO",
    "VL_ART" = excluded."VL_ART",
    "VL_NOTA_ORDEM" = excluded."VL_NOTA_ORDEM",
    "TP_ORIGEM_NOTA" = excluded."TP_ORIGEM_NOTA",
    "VL_NOTA_DECLARADA" = excluded."VL_NOTA_DECLARADA",
    "DS_NOTA_DECLARADA" = excluded."DS_NOTA_DECLARADA",
    "ST_DIVERGENTE" = excluded."ST_DIVERGENTE",
    "NO_MODALIDADE" = excluded."NO_MODALIDADE",
    "DS_MODALIDADES" = excluded."DS_MODALIDADES",
    "NU_POSICAO" = excluded."NU_POSICAO",
    "NU_POSICAO_MODALIDADE" = excluded."NU_POSICAO_MODALIDADE",
    "NU_LOTE" = excluded."NU_LOTE",
    "CO_LISTA_LOTE" = excluded."CO_LISTA_LOTE",
    "TP_ENTRADA_LOTE" = excluded."TP_ENTRADA_LOTE",
    "DS_MOTIVO_ENTRADA" = excluded."DS_MOTIVO_ENTRADA",
    -- Quem continua no mesmo lote guarda a data de entrada.
    "DT_ENTRADA_LOTE" = case when excluded."NU_LOTE" is null then null
                             when a."NU_LOTE" is not distinct from excluded."NU_LOTE" then a."DT_ENTRADA_LOTE"
                             else now() end,
    "CO_EXECUCAO" = excluded."CO_EXECUCAO",
    -- A congelada fica como estava; só entra quando ainda não há.
    "VL_DECLARADA_CONGELADA" = coalesce(a."VL_DECLARADA_CONGELADA", excluded."VL_DECLARADA_CONGELADA"),
    "DS_DECLARADA_CONGELADA" = case when a."VL_DECLARADA_CONGELADA" is not null then a."DS_DECLARADA_CONGELADA"
                                    else excluded."DS_DECLARADA_CONGELADA" end,
    "DT_CONGELAMENTO_DECLARADA" = case when a."VL_DECLARADA_CONGELADA" is not null then a."DT_CONGELAMENTO_DECLARADA"
                                       else excluded."DT_CONGELAMENTO_DECLARADA" end,
    "DT_ATUALIZACAO" = now();

  -- Histórico: entrada na lista, troca de situação ou de lote (com o motivo).
  insert into public."TH_PRE_CLASSIFICACAO"
    ("CO_EXECUCAO", "CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO", "CO_VAGA", "TP_SITUACAO_ANTERIOR",
     "TP_SITUACAO", "NU_LOTE_ANTERIOR", "NU_LOTE", "NU_POSICAO", "DS_MOTIVO")
  select p_execucao, p_edital, t.id, p_vaga, h.ant_situacao, t.situacao, h.ant_lote, t.lote, t.posicao,
         left(case when t.situacao = 'ELIMINADO' then t.motivo
                   when t.entrada = 'DECISAO' and h.ant_entrada is distinct from 'DECISAO'
                     then 'Incluído no lote por decisão da coordenação: ' || t.motivo_entrada
                   when h.ant_entrada = 'DECISAO' and t.lote is null
                     then 'Saiu do lote: a decisão da coordenação foi revogada'
                   when t.lote is not null and t.lote is distinct from h.ant_lote then t.motivo_entrada
                   when h.ant_situacao = 'NO_LOTE' and t.situacao = 'RANQUEADO' then 'Saiu do lote: o recorte foi refeito'
                   when h.ant_situacao is null then 'Entrou na Provisória'
                   else null end, 300)
    from pg_temp.t_linhas_vaga t
   cross join lateral (select v_ant -> t.id::text ->> 's' as ant_situacao, (v_ant -> t.id::text ->> 'l')::integer as ant_lote,
                              v_ant -> t.id::text ->> 'e' as ant_entrada) h
   where h.ant_situacao is null
      or h.ant_situacao is distinct from t.situacao
      or h.ant_lote is distinct from t.lote
      or h.ant_entrada is distinct from t.entrada;
  get diagnostics v_mudancas = row_count;

  -- O resumo da vaga: contagens feitas aqui. A linha do quadro é a que o job leu nesta execução
  -- (pre_classificacao_ler_candidatos, p_resumo.quadro; nula = vaga sem quadro), conferida aqui
  -- (do edital e ativa); sem a chave, o banco acha a linha (FC_QUADRO_DA_VAGA_EMPREGARE, até 1,8 s).
  if p_resumo ? 'quadro' then
    if jsonb_typeof(p_resumo -> 'quadro') = 'string' then
      begin
        v_quadro_id := (p_resumo ->> 'quadro')::uuid;
      exception when invalid_text_representation then
        raise exception 'Resumo da vaga inválido (quadro)' using errcode = '22023';
      end;
      select * into v_quadro from public."TB_QUADRO_VAGA_EDITAL" q
       where q."CO_QUADRO_VAGA" = v_quadro_id and q."CO_MONITORAMENTO" = p_edital and q."ST_REGISTRO_ATIVO" = 'S';
      if not found then
        raise exception 'Resumo da vaga % recusado: a linha do quadro não é do edital (ou não está ativa)', p_vaga
          using errcode = '22023';
      end if;
    end if;
  else
    v_quadro := private."FC_QUADRO_DA_VAGA_EMPREGARE"(p_edital, p_vaga);
  end if;
  select count(*) into v_qt from pg_temp.t_linhas_vaga;
  insert into public."TB_PRE_CLASSIF_VAGA" as pv
    ("CO_MONITORAMENTO", "CO_VAGA", "CO_EXECUCAO", "NU_VERSAO_REGRA", "CO_QUADRO_VAGA", "NO_CARGO", "NO_LOTACAO",
     "QT_VAGA_IMEDIATA", "ST_CADASTRO_RESERVA", "QT_INSCRITO", "QT_ELIMINADO", "QT_RANQUEADO", "QT_LOTE",
     "QT_TAMANHO_LOTE", "DS_TAMANHO_LOTE", "DS_TAMANHO_MODALIDADE", "VL_ART_CORTE", "QT_DIVERGENCIA", "QT_SEM_ART",
     "QT_ACIMA_CORTE", "NU_ULTIMO_LOTE", "DS_AVISO")
  select p_edital, p_vaga, p_execucao, p_versao_regra, v_quadro."CO_QUADRO_VAGA", v_quadro."NO_CARGO", v_quadro."NO_LOTACAO",
         v_quadro."QT_VAGA_IMEDIATA", coalesce(v_quadro."ST_CADASTRO_RESERVA", 'N'), v_qt,
         count(*) filter (where t.situacao = 'ELIMINADO'),
         count(*) filter (where t.situacao <> 'ELIMINADO'),
         count(*) filter (where t.situacao in ('NO_LOTE', 'ANALISADO')),
         case when jsonb_typeof(p_resumo -> 'tamanho') = 'number'
              then greatest(0, least(100000, (p_resumo ->> 'tamanho')::numeric))::integer end,
         nullif(left(btrim(coalesce(p_resumo ->> 'descricao', '')), 200), ''),
         case when jsonb_typeof(p_resumo -> 'por_modalidade') = 'object' then p_resumo -> 'por_modalidade' end,
         -- A linha de corte só com os da regra (quem entrou por decisão fica fora).
         min(t.nota) filter (where t.situacao in ('NO_LOTE', 'ANALISADO') and t.entrada is distinct from 'DECISAO'),
         count(*) filter (where t.divergente),
         count(*) filter (where t.situacao <> 'ELIMINADO' and t.art is null),
         case when jsonb_typeof(p_resumo -> 'acima_do_corte') = 'number'
              then greatest(0, least(100000, (p_resumo ->> 'acima_do_corte')::numeric))::integer else 0 end,
         coalesce(max(t.lote), 0),
         v_avisos
    from pg_temp.t_linhas_vaga t
  on conflict ("CO_MONITORAMENTO", "CO_VAGA") do update set
    "CO_EXECUCAO" = excluded."CO_EXECUCAO",
    "NU_VERSAO_REGRA" = excluded."NU_VERSAO_REGRA",
    "CO_QUADRO_VAGA" = excluded."CO_QUADRO_VAGA",
    "NO_CARGO" = excluded."NO_CARGO",
    "NO_LOTACAO" = excluded."NO_LOTACAO",
    "QT_VAGA_IMEDIATA" = excluded."QT_VAGA_IMEDIATA",
    "ST_CADASTRO_RESERVA" = excluded."ST_CADASTRO_RESERVA",
    "QT_INSCRITO" = excluded."QT_INSCRITO",
    "QT_ELIMINADO" = excluded."QT_ELIMINADO",
    "QT_RANQUEADO" = excluded."QT_RANQUEADO",
    "QT_LOTE" = excluded."QT_LOTE",
    "QT_TAMANHO_LOTE" = excluded."QT_TAMANHO_LOTE",
    "DS_TAMANHO_LOTE" = excluded."DS_TAMANHO_LOTE",
    "DS_TAMANHO_MODALIDADE" = excluded."DS_TAMANHO_MODALIDADE",
    "VL_ART_CORTE" = excluded."VL_ART_CORTE",
    "QT_DIVERGENCIA" = excluded."QT_DIVERGENCIA",
    "QT_SEM_ART" = excluded."QT_SEM_ART",
    "QT_ACIMA_CORTE" = excluded."QT_ACIMA_CORTE",
    "NU_ULTIMO_LOTE" = greatest(pv."NU_ULTIMO_LOTE", excluded."NU_ULTIMO_LOTE"),
    "DS_AVISO" = excluded."DS_AVISO",
    "DT_ATUALIZACAO" = now();

  return jsonb_build_object('vaga', p_vaga, 'inscritos', v_qt, 'mudancas', v_mudancas);
end;
$_$;

--
-- Name: FUNCTION gravar_pre_classificacao_vaga(p_execucao text, p_edital uuid, p_vaga text, p_versao_regra integer, p_resumo jsonb, p_linhas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_pre_classificacao_vaga(p_execucao text, p_edital uuid, p_vaga text, p_versao_regra integer, p_resumo jsonb, p_linhas jsonb) IS 'Grava a pré-classificação PRONTA de uma vaga (calculada pelo job Python): confere a regra vigente e conferida (40001), que os inscritos são da vaga, que nenhum já gravado falta, a forma (eliminado com motivo, posições de 1 a N, lote com número, lista e entrada; desde 20261015150000 as cotas optadas — modalidades, sem a ampla, a principal primeiro — gravadas em DS_MODALIDADES), que quem tem ficha não muda, que quem está no lote só sai eliminado (salvo execução que refaz o lote — desde 20261013110000 só com todas as fichas do edital intocadas, senão 55000 "o lote já está em análise: N fichas iniciadas" — ou, desde 20261007200000, quem entrou por decisão já revogada), que a nota declarada congelada não muda e, desde 20261007200000, que toda decisão vigente da coordenação (TB_DECISAO_LOTE) foi aplicada e só entra por decisão (entrada DECISAO, com o motivo da decisão) quem a tem; grava o histórico das mudanças com o motivo e o resumo da vaga (contagens feitas no banco, a linha de corte só com os da regra). Desde 20261014130000 o p_linhas é lido uma vez e a linha do quadro vem do job (p_resumo.quadro: id lido em pre_classificacao_ler_candidatos, conferido do edital e ativo; nulo = sem quadro; sem a chave, lida no banco). Limite de 30 s (statement_timeout). 22023 com o motivo da recusa. Só service_role.';

--
-- Name: gravar_resumo_pergunta_edital(uuid, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_resumo_pergunta_edital(p_edital uuid, p_hash text, p_perguntas jsonb, p_candidatos integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ruins integer;
begin
  if not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital) then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  if coalesce(p_candidatos, -1) < 0 then
    raise exception 'Contagem de candidatos inválida' using errcode = '22023';
  end if;
  if jsonb_typeof(p_perguntas) is distinct from 'array' or jsonb_array_length(p_perguntas) > 500 then
    raise exception 'Resumo: lista de até 500 perguntas' using errcode = '22023';
  end if;

  -- O formato e a privacidade: só colunas de pergunta; até 30 respostas, cada uma com 2+ ocorrências e até 200 caracteres.
  select count(*) into v_ruins
    from jsonb_array_elements(p_perguntas) p
   where case
           when jsonb_typeof(p) <> 'object'
             or jsonb_typeof(p -> 'coluna') is distinct from 'string'
             or jsonb_typeof(p -> 'respostas') is distinct from 'array'
             or jsonb_typeof(p -> 'outras') is distinct from 'number'
             or jsonb_typeof(p -> 'distintas') is distinct from 'number' then true
           when not (p ->> 'coluna' ilike 'Pergunta %') or length(p ->> 'coluna') > 1000
             or jsonb_array_length(p -> 'respostas') > 30
             or (p ->> 'outras')::numeric < 0
             or (p ->> 'distintas')::numeric < jsonb_array_length(p -> 'respostas') + (p ->> 'outras')::numeric then true
           else exists (
             select 1 from jsonb_array_elements(p -> 'respostas') r
              where case
                      when jsonb_typeof(r) <> 'object'
                        or jsonb_typeof(r -> 'valor') is distinct from 'string'
                        or jsonb_typeof(r -> 'quantidade') is distinct from 'number' then true
                      else length(r ->> 'valor') not between 1 and 200 or (r ->> 'quantidade')::numeric < 2
                    end)
         end;
  if v_ruins > 0 then
    raise exception 'Resumo fora do formato (% pergunta(s))', v_ruins using errcode = '22023';
  end if;

  if p_hash is distinct from private."FC_HASH_VAGA_EDITAL"(p_edital) then
    raise exception 'A carga do edital mudou desde a leitura; o resumo fica para a próxima vez' using errcode = 'PT409';
  end if;

  insert into public."TB_RESUMO_PERGUNTA_EDITAL" as r
    ("CO_MONITORAMENTO", "DS_PERGUNTA", "QT_CANDIDATO", "DS_HASH_VAGA", "DT_ATUALIZACAO")
  values (p_edital, p_perguntas, p_candidatos, p_hash, now())
  on conflict ("CO_MONITORAMENTO") do update set
    "DS_PERGUNTA" = excluded."DS_PERGUNTA", "QT_CANDIDATO" = excluded."QT_CANDIDATO",
    "DS_HASH_VAGA" = excluded."DS_HASH_VAGA", "DT_ATUALIZACAO" = excluded."DT_ATUALIZACAO";
  return jsonb_build_object('edital', p_edital, 'perguntas', jsonb_array_length(p_perguntas), 'candidatos', p_candidatos);
end;
$$;

--
-- Name: FUNCTION gravar_resumo_pergunta_edital(p_edital uuid, p_hash text, p_perguntas jsonb, p_candidatos integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_resumo_pergunta_edital(p_edital uuid, p_hash text, p_perguntas jsonb, p_candidatos integer) IS 'Robô da Empregare (resumo_das_perguntas.py): grava o resumo das perguntas da carga do edital calculado em Python. Confere o formato e a privacidade (só colunas "Pergunta N", até 30 respostas por pergunta, cada uma com 2+ ocorrências e até 200 caracteres) e a assinatura das vagas lida (p_hash; mudou = 40001). Só service_role.';

--
-- Name: gravar_retrato_inscricoes(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_retrato_inscricoes(p_execucao text, p_edital uuid, p_vagas jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_exec public."TL_PRE_CLASSIFICACAO" := private."FC_EXIGIR_EXECUCAO_PRECLASSIF"(p_execucao);
  v_hoje constant date := (now() at time zone 'America/Sao_Paulo')::date;
  v_qt integer;
begin
  if jsonb_typeof(p_vagas) is distinct from 'array' or jsonb_array_length(p_vagas) > 1000 then
    raise exception 'Retrato inválido (lista de até 1000 vagas)' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_vagas) e
     where jsonb_typeof(e) <> 'object'
        or coalesce(e ->> 'vaga', '') !~ '^[0-9]{1,20}$'
        or jsonb_typeof(e -> 'inscritos') is distinct from 'number'
        or exists (select 1 from unnest(array['finalizados', 'aptos', 'eliminados']) k
                    where jsonb_typeof(coalesce(e -> k, 'null'::jsonb)) not in ('number', 'null'))
        or jsonb_typeof(coalesce(e -> 'previa', 'false'::jsonb)) <> 'boolean') then
    raise exception 'Retrato inválido: cada vaga leva o código e as contagens' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_vagas) e
              where not exists (select 1 from public."TB_EMPREGARE_VAGA" v
                                 where v."CO_VAGA" = e ->> 'vaga' and v."CO_MONITORAMENTO" = p_edital)) then
    raise exception 'Há vaga no retrato que não é do edital' using errcode = '22023';
  end if;
  if (select count(distinct e ->> 'vaga') from jsonb_array_elements(p_vagas) e) <> jsonb_array_length(p_vagas) then
    raise exception 'Vaga repetida no retrato' using errcode = '22023';
  end if;

  begin
    insert into public."TH_INSCRICAO_VAGA_EDITAL" as t
      ("CO_MONITORAMENTO", "CO_VAGA", "DT_RETRATO", "QT_INSCRITO", "QT_FINALIZADO", "QT_APTO", "QT_ELIMINADO",
       "ST_PREVIA", "CO_EXECUCAO")
    select p_edital, e ->> 'vaga', v_hoje, (e ->> 'inscritos')::integer, (e ->> 'finalizados')::integer,
           (e ->> 'aptos')::integer, (e ->> 'eliminados')::integer,
           case when coalesce((e ->> 'previa')::boolean, false) then 'S' else 'N' end, v_exec."CO_EXECUCAO"
      from jsonb_array_elements(p_vagas) e
    on conflict ("CO_MONITORAMENTO", "CO_VAGA", "DT_RETRATO") do update
       set "QT_INSCRITO" = excluded."QT_INSCRITO", "QT_FINALIZADO" = excluded."QT_FINALIZADO",
           "QT_APTO" = excluded."QT_APTO", "QT_ELIMINADO" = excluded."QT_ELIMINADO",
           "ST_PREVIA" = excluded."ST_PREVIA", "CO_EXECUCAO" = excluded."CO_EXECUCAO", "DT_ATUALIZACAO" = now();
    get diagnostics v_qt = row_count;
  exception when check_violation or invalid_text_representation or numeric_value_out_of_range then
    raise exception 'Retrato inválido: contagem fora do intervalo' using errcode = '22023';
  end;
  return json_build_object('vagas', v_qt, 'dia', v_hoje);
end;
$_$;

--
-- Name: FUNCTION gravar_retrato_inscricoes(p_execucao text, p_edital uuid, p_vagas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_retrato_inscricoes(p_execucao text, p_edital uuid, p_vagas jsonb) IS 'Job da pré-classificação (service_role, 20261009140000): grava o retrato do dia (Brasília) das vagas do edital em TH_INSCRICAO_VAGA_EDITAL — p_vagas = [{vaga, inscritos, finalizados, aptos, eliminados, previa}], só contagens. Exige a execução aberta (FC_EXIGIR_EXECUCAO_PRECLASSIF) e vagas do edital; o retrato do mesmo dia é substituído. Devolve {vagas, dia}. 22023 para retrato inválido.';

--
-- Name: gravar_sugestoes_da_ficha(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gravar_sugestoes_da_ficha(p_execucao text, p_edital uuid, p_vaga text, p_sugestoes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_regra jsonb;
  v_s jsonb;
  v_blocos jsonb;
  v_candidatos integer := 0;
  v_fora integer := 0;
begin
  perform private."FC_EXIGIR_EXECUCAO_PRECLASSIF"(p_execucao);
  if p_vaga is null or p_vaga !~ '^[0-9]{1,20}$'
     or not exists (select 1 from public."TB_EMPREGARE_VAGA" v where v."CO_VAGA" = p_vaga and v."CO_MONITORAMENTO" = p_edital) then
    raise exception 'A vaga % não é do edital', p_vaga using errcode = '22023';
  end if;
  if jsonb_typeof(p_sugestoes) is distinct from 'array' or jsonb_array_length(p_sugestoes) > 5000 then
    raise exception 'Envie até 5.000 sugestões por vaga' using errcode = '22023';
  end if;
  select h."DS_CONFIGURACAO" into v_regra
    from public."TB_REGRA_ANALISE" r
    join public."TH_REGRA_ANALISE" h on h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
   where r."CO_MONITORAMENTO" = p_edital;

  -- A vaga recalculada fica só com as sugestões de agora.
  delete from public."TB_SUGESTAO_FICHA" s
   using public."TB_EMPREGARE_CANDIDATO" c
   where s."CO_MONITORAMENTO" = p_edital and c."CO_EMPREGARE_CANDIDATO" = s."CO_EMPREGARE_CANDIDATO"
     and c."CO_VAGA" = p_vaga;

  for v_s in select x from jsonb_array_elements(p_sugestoes) x loop
    if coalesce(v_s ->> 'id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or not exists (select 1 from public."TB_EMPREGARE_CANDIDATO" c
                       where c."CO_EMPREGARE_CANDIDATO" = (v_s ->> 'id')::uuid and c."CO_VAGA" = p_vaga) then
      v_fora := v_fora + 1;
      continue;
    end if;
    -- Só os blocos de títulos, cursos e vínculos da regra; até 20 itens limpos por bloco.
    select coalesce(jsonb_object_agg(b.codigo, b.itens), '{}'::jsonb) into v_blocos
      from (
        select e.key as codigo,
               (select jsonb_agg(i.limpo order by i.n)
                  from (select private."FC_ITEM_SUGERIDO"(
                                 case rb ->> 'tipo' when 'TITULOS' then 'titulos' when 'CURSOS' then 'cursos'
                                                    when 'VINCULOS' then 'vinculos' end, it.valor) as limpo, it.n
                          from jsonb_array_elements(e.value) with ordinality as it(valor, n)
                         where it.n <= 20) i
                 where i.limpo is not null) as itens
          from jsonb_each(case when jsonb_typeof(v_s -> 'blocos') = 'object' then v_s -> 'blocos' else '{}'::jsonb end) e
          join lateral (select x as rb from jsonb_array_elements(coalesce(v_regra -> 'blocos', '[]'::jsonb)) x
                         where x ->> 'codigo' = e.key and x ->> 'tipo' in ('TITULOS', 'CURSOS', 'VINCULOS')
                         limit 1) r on true
         where jsonb_typeof(e.value) = 'array'
      ) b
     where b.itens is not null;
    continue when v_blocos = '{}'::jsonb;
    insert into public."TB_SUGESTAO_FICHA" ("CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO", "DS_SUGESTAO", "CO_EXECUCAO", "DT_CALCULO")
    values (p_edital, (v_s ->> 'id')::uuid, v_blocos, p_execucao, now())
    on conflict ("CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO") do update set
      "DS_SUGESTAO" = excluded."DS_SUGESTAO", "CO_EXECUCAO" = excluded."CO_EXECUCAO", "DT_CALCULO" = excluded."DT_CALCULO";
    v_candidatos := v_candidatos + 1;
  end loop;

  return jsonb_build_object('recebidas', jsonb_array_length(p_sugestoes), 'candidatos', v_candidatos, 'fora_da_vaga', v_fora);
end;
$_$;

--
-- Name: FUNCTION gravar_sugestoes_da_ficha(p_execucao text, p_edital uuid, p_vaga text, p_sugestoes jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gravar_sugestoes_da_ficha(p_execucao text, p_edital uuid, p_vaga text, p_sugestoes jsonb) IS 'Recebe do job da pré-classificação (Python) as sugestões da ficha de uma vaga: [{id, blocos: {"<BLOCO>": [itens]}}]. Troca as da vaga inteira em TB_SUGESTAO_FICHA; só inscritos da vaga, só blocos de títulos, cursos e vínculos da regra do edital, até 20 itens limpos por bloco (FC_ITEM_SUGERIDO). Só service_role, com a execução da pré-classificação em andamento.';

--
-- Name: ignorar_aviso_conferencia(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ignorar_aviso_conferencia(p_id uuid, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_aviso public."TB_AVISO_CONFERENCIA";
  v_motivo text := btrim(coalesce(p_motivo, ''));
begin
  if auth.uid() is null then
    raise exception 'Sessão necessária' using errcode = '42501';
  end if;
  if length(v_motivo) not between 10 and 500 then
    raise exception 'Escreva o motivo (10 a 500 caracteres)' using errcode = '22023';
  end if;
  select * into v_aviso from public."TB_AVISO_CONFERENCIA" a where a."CO_AVISO_CONFERENCIA" = p_id for update;
  if v_aviso."CO_AVISO_CONFERENCIA" is null
     or not private."FC_PODE_VER_AVISO"(v_aviso."CO_MODULO", v_aviso."CO_AREA", v_aviso."CO_MONITORAMENTO") then
    raise exception 'Aviso não encontrado' using errcode = '22023';
  end if;
  if not private."FC_PODE_IGNORAR_AVISO"(v_aviso."CO_MODULO", v_aviso."CO_AREA", v_aviso."CO_MONITORAMENTO") then
    raise exception 'Só o gestor do módulo ou o administrador global ignora avisos' using errcode = '42501';
  end if;
  if v_aviso."TP_SITUACAO" <> 'ABERTO' then
    raise exception 'Só aviso aberto pode ser ignorado' using errcode = '22023';
  end if;

  update public."TB_AVISO_CONFERENCIA" set
    "TP_SITUACAO" = 'IGNORADO', "CO_USUARIO_IGNORADO" = auth.uid(), "DT_IGNORADO" = now(),
    "DS_MOTIVO_IGNORADO" = v_motivo, "QT_OCORRENCIA_IGNORADA" = "QT_OCORRENCIA"
   where "CO_AVISO_CONFERENCIA" = p_id;

  return json_build_object('id', p_id, 'situacao', 'IGNORADO', 'ignorado_em', now());
end;
$$;

--
-- Name: FUNCTION ignorar_aviso_conferencia(p_id uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ignorar_aviso_conferencia(p_id uuid, p_motivo text) IS 'Ignora um aviso de conferência aberto, com motivo (10 a 500 caracteres): administrador global ou quem vê o aviso e administra o módulo (classificação: editor). O aviso volta a ABERTO se a quantidade crescer.';

--
-- Name: incluir_no_lote_por_decisao(uuid, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.incluir_no_lote_por_decisao(p_edital uuid, p_codigos text[], p_motivo text, p_vaga text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_motivo text := btrim(coalesce(p_motivo, ''));
  v_uid uuid := (select auth.uid());
  v_item record;
  v_a public."TB_PRE_CLASSIFICACAO";
  v_decisao uuid;
  v_lote integer;
  v_lista text;
  v_posicao integer;
  v_posicao_mod integer;
  v_vagas text[] := '{}';
  v_vaga text;
  v_qt integer := 0;
  v_fichas jsonb;
begin
  perform private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  if length(v_motivo) not between 5 and 250 then
    raise exception 'Diga o motivo da decisão (de 5 a 250 caracteres).' using errcode = '22023';
  end if;
  if exists (select 1 from public."TL_PRE_CLASSIFICACAO" t
              where t."TP_SITUACAO" = 'EM_ANDAMENTO' and t."DT_INICIO" > now() - interval '1 hour') then
    raise exception 'Há uma pré-classificação rodando: inclua quando ela terminar.' using errcode = '55P03';
  end if;
  -- As mesmas travas da abertura das fichas (job e tela não se atropelam).
  perform pg_advisory_xact_lock(hashtextextended('avaliacao-documental:fichas:' || p_edital::text, 0));

  for v_item in select * from private."FC_INSCRITOS_DA_DECISAO"(p_edital, p_codigos, p_vaga) loop
    select * into v_a from public."TB_PRE_CLASSIFICACAO"
     where "CO_MONITORAMENTO" = p_edital and "CO_EMPREGARE_CANDIDATO" = v_item.candidato
     for update;
    if v_a."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO') then
      raise exception 'O candidato % já está no lote.', v_item.codigo using errcode = '22023';
    end if;
    if v_a."CO_MOTIVO_ELIMINACAO" = 'SAIU_DA_EMPREGARE' then
      raise exception 'O candidato % saiu do arquivo da Empregare: não entra no lote.', v_item.codigo using errcode = '22023';
    end if;
    if exists (select 1 from public."TB_DECISAO_LOTE" d
                where d."CO_MONITORAMENTO" = p_edital and d."CO_EMPREGARE_CANDIDATO" = v_item.candidato and d."ST_ATIVO" = 'S') then
      raise exception 'O candidato % já tem decisão vigente.', v_item.codigo using errcode = '22023';
    end if;

    insert into public."TB_DECISAO_LOTE"
      ("CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO", "CO_VAGA", "DS_MOTIVO", "CO_USUARIO_DECISAO",
       "TP_SITUACAO_REGRA", "CO_MOTIVO_ELIMINACAO_REGRA", "DS_MOTIVO_ELIMINACAO_REGRA")
    values (p_edital, v_item.candidato, v_a."CO_VAGA", v_motivo, v_uid,
            v_a."TP_SITUACAO", v_a."CO_MOTIVO_ELIMINACAO", v_a."DS_MOTIVO_ELIMINACAO")
    returning "CO_DECISAO_LOTE" into v_decisao;
    insert into public."TH_DECISAO_LOTE" ("CO_DECISAO_LOTE", "TP_ACAO", "DS_MOTIVO", "CO_USUARIO")
    values (v_decisao, 'INCLUIR', v_motivo, v_uid);

    -- O lote da vaga (o último), a lista (a da modalidade, se a vaga tem listas por modalidade)
    -- e, para o eliminado, a posição depois do último da Provisória (o job reordena ao recalcular).
    select greatest(1, coalesce(max(a."NU_LOTE"), 0),
                    coalesce((select pv."NU_ULTIMO_LOTE" from public."TB_PRE_CLASSIF_VAGA" pv
                               where pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" = v_a."CO_VAGA"), 0)),
           case when bool_or(a."CO_LISTA_LOTE" is not null and a."CO_LISTA_LOTE" <> 'GERAL')
                then case when bool_or(a."CO_LISTA_LOTE" = v_a."NO_MODALIDADE") then v_a."NO_MODALIDADE" else 'AC' end
                else 'GERAL' end,
           coalesce(max(a."NU_POSICAO"), 0) + 1,
           coalesce(max(a."NU_POSICAO_MODALIDADE") filter (where a."NO_MODALIDADE" = v_a."NO_MODALIDADE"), 0) + 1
      into v_lote, v_lista, v_posicao, v_posicao_mod
      from public."TB_PRE_CLASSIFICACAO" a
     where a."CO_MONITORAMENTO" = p_edital and a."CO_VAGA" = v_a."CO_VAGA";

    update public."TB_PRE_CLASSIFICACAO" set
      "TP_SITUACAO" = 'NO_LOTE', "CO_MOTIVO_ELIMINACAO" = null, "DS_MOTIVO_ELIMINACAO" = null,
      "NU_POSICAO" = coalesce("NU_POSICAO", v_posicao),
      "NU_POSICAO_MODALIDADE" = coalesce("NU_POSICAO_MODALIDADE", v_posicao_mod),
      "NU_LOTE" = v_lote, "CO_LISTA_LOTE" = v_lista, "TP_ENTRADA_LOTE" = 'DECISAO',
      "DS_MOTIVO_ENTRADA" = v_motivo, "DT_ENTRADA_LOTE" = now(), "DT_ATUALIZACAO" = now()
     where "CO_MONITORAMENTO" = p_edital and "CO_EMPREGARE_CANDIDATO" = v_item.candidato
    returning * into v_a;

    insert into public."TH_PRE_CLASSIFICACAO"
      ("CO_EXECUCAO", "CO_USUARIO", "CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO", "CO_VAGA", "TP_SITUACAO_ANTERIOR",
       "TP_SITUACAO", "NU_LOTE_ANTERIOR", "NU_LOTE", "NU_POSICAO", "DS_MOTIVO")
    select null, v_uid, p_edital, v_item.candidato, v_a."CO_VAGA", d."TP_SITUACAO_REGRA", 'NO_LOTE', null, v_a."NU_LOTE",
           v_a."NU_POSICAO", left('Incluído no lote por decisão da coordenação: ' || v_motivo, 300)
      from public."TB_DECISAO_LOTE" d where d."CO_DECISAO_LOTE" = v_decisao;

    if not (v_a."CO_VAGA" = any (v_vagas)) then
      v_vagas := v_vagas || v_a."CO_VAGA"::text;
    end if;
    v_qt := v_qt + 1;
  end loop;

  foreach v_vaga in array v_vagas loop
    perform private."FC_RECONTAR_PRE_CLASSIF_VAGA"(p_edital, v_vaga);
  end loop;
  -- A ficha abre normalmente (livre na fila).
  v_fichas := private."FC_ABRIR_FICHAS"(p_edital, '[]'::jsonb, v_uid);
  return json_build_object('incluidos', v_qt, 'fichas_criadas', coalesce((v_fichas ->> 'criadas')::integer, 0),
                           'fichas_voltaram', coalesce((v_fichas ->> 'voltaram')::integer, 0));
end;
$$;

--
-- Name: FUNCTION incluir_no_lote_por_decisao(p_edital uuid, p_codigos text[], p_motivo text, p_vaga text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.incluir_no_lote_por_decisao(p_edital uuid, p_codigos text[], p_motivo text, p_vaga text) IS 'A coordenação da avaliação do edital inclui no lote de convocação, por decisão, candidatos que a regra deixa fora (eliminados pela regra ou abaixo do corte): grava a decisão (TB_DECISAO_LOTE, com o motivo de 5 a 250 caracteres — ex.: "Critério CORES" —, quem, quando e a situação pela regra) e o histórico, põe o inscrito no lote na hora (NO_LOTE, entrada DECISAO, no último lote da vaga; o eliminado ganha posição depois do último da Provisória) e abre a ficha (FC_ABRIR_FICHAS). Os recálculos mantêm a decisão até ela ser revogada (revogar_decisao_lote). p_codigos: códigos da Empregare (1 a 200); p_vaga opcional. Recusa (22023) quem já está no lote, saiu da Empregare ou já tem decisão; 55P03 com pré-classificação rodando. Só a coordenação (FC_EXIGIR_COORD_AVALIACAO).';

--
-- Name: incluir_sub_judice(text, text, text, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.incluir_sub_judice(p_edital_id text, p_cargo text, p_nome text, p_nota numeric, p_modalidade text DEFAULT NULL::text, p_processo text DEFAULT NULL::text, p_observacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lista public."TB_LISTA_APROVADO"%rowtype;
  v_candidato_id uuid;
  v_modalidade text := nullif(btrim(coalesce(p_modalidade, '')), '');
  v_posicao integer;
begin
  perform private."FC_EXIGIR_AREA_EDITAL"(p_edital_id);
  if not (private.pode_recurso('aprovados', 2)) then raise exception 'Sem permissão para este recurso' using errcode = '42501'; end if;
  if nullif(btrim(coalesce(p_cargo, '')), '') is null then raise exception 'Cargo obrigatorio'; end if;
  if nullif(btrim(coalesce(p_nome, '')), '') is null then raise exception 'Nome obrigatorio'; end if;
  if p_nota is null or p_nota < 0 then raise exception 'Nota invalida'; end if;
  if length(coalesce(p_processo, '')) > 100 or length(coalesce(p_observacao, '')) > 1000 then
    raise exception 'Processo (até 100) ou observação (até 1000 caracteres) longos demais' using errcode = '22023';
  end if;

  select * into v_lista from public."TB_LISTA_APROVADO"
   where edital_id = p_edital_id and vigente is true for update;
  if not found then raise exception 'O edital ainda nao possui lista vigente'; end if;
  if not v_lista.ativo then raise exception 'A lista esta inativa e nao permite incluir sub judice'; end if;

  if not exists (
    select 1 from public."TB_CANDIDATO_APROVADO"
     where lista_id = v_lista.id and removido_em is null and cargo = btrim(p_cargo)
  ) then
    raise exception 'Cargo nao pertence a lista vigente deste edital';
  end if;

  insert into public."TB_CANDIDATO_APROVADO" (
    lista_id, cargo, nota, nome, modalidade, sub_judice, created_by, updated_by
  ) values (
    v_lista.id, btrim(p_cargo), p_nota, btrim(p_nome), v_modalidade, true,
    (select auth.uid()), (select auth.uid())
  ) returning id into v_candidato_id;

  v_posicao := private."FC_RECOLOCAR_NA_CLASSIFICACAO"(v_candidato_id, v_modalidade);

  insert into public."TH_CANDIDATO_SUB_JUDICE" (
    "CO_CANDIDATO", "CO_LISTA", "TP_EVENTO", "VL_NOTA_NOVA", "DS_MODALIDADE_NOVA",
    "NU_CLASSIFICACAO_NOVA", "NU_PROCESSO_JUDICIAL", "DS_OBSERVACAO", "CO_USUARIO"
  ) values (
    v_candidato_id, v_lista.id, 'INCLUSAO', p_nota, v_modalidade, v_posicao,
    nullif(btrim(coalesce(p_processo, '')), ''), nullif(btrim(coalesce(p_observacao, '')), ''),
    (select auth.uid())
  );

  return jsonb_build_object('ok', true, 'candidato_id', v_candidato_id, 'lista_id', v_lista.id,
                            'sub_judice', true, 'classificacao', v_posicao);
end;
$$;

--
-- Name: FUNCTION incluir_sub_judice(p_edital_id text, p_cargo text, p_nome text, p_nota numeric, p_modalidade text, p_processo text, p_observacao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.incluir_sub_judice(p_edital_id text, p_cargo text, p_nome text, p_nota numeric, p_modalidade text, p_processo text, p_observacao text) IS 'Inclui candidato sub judice na lista vigente e ativa do edital (cargo já existente), com modalidade, processo e observação opcionais; entra na classificação pela nota e fica no histórico. aprovados >= editor e a área do edital.';

--
-- Name: iniciar_conferencia(text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.iniciar_conferencia(p_execucao text, p_disparo text, p_usuario uuid DEFAULT NULL::uuid, p_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_interrompidas integer;
begin
  if p_execucao is null or p_execucao !~ '^[A-Za-z0-9_-]{8,80}$' then
    raise exception 'Identificador de execução inválido' using errcode = '22023';
  end if;
  if p_disparo is null or p_disparo not in ('AGENDA', 'MONITORA', 'GITHUB') then
    raise exception 'Disparo inválido: AGENDA, MONITORA ou GITHUB' using errcode = '22023';
  end if;
  if (p_disparo = 'MONITORA') <> (p_usuario is not null) then
    raise exception 'Usuário só (e sempre) no disparo pelo MONITORA' using errcode = '22023';
  end if;

  -- Execução que morreu sem fechar (o workflow tem tempo limite de 20 min) não segura as próximas.
  update public."TL_CONFERENCIA" set
    "TP_SITUACAO" = 'FALHOU', "DT_FIM" = now(),
    "DS_MENSAGEM" = 'Interrompida: a execução terminou sem fechar.'
   where "TP_SITUACAO" = 'EM_ANDAMENTO' and "DT_INICIO" < now() - interval '1 hour';
  get diagnostics v_interrompidas = row_count;

  if exists (select 1 from public."TL_CONFERENCIA" c where c."TP_SITUACAO" = 'EM_ANDAMENTO') then
    raise exception 'Já há uma execução das conferências em andamento' using errcode = '55P03';
  end if;

  insert into public."TL_CONFERENCIA" ("CO_EXECUCAO", "TP_DISPARO", "CO_USUARIO_DISPARO", "DS_URL_EXECUCAO")
  values (p_execucao, p_disparo, p_usuario, p_url);

  return jsonb_build_object('execucao', p_execucao, 'interrompidas', v_interrompidas);
end;
$_$;

--
-- Name: FUNCTION iniciar_conferencia(p_execucao text, p_disparo text, p_usuario uuid, p_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.iniciar_conferencia(p_execucao text, p_disparo text, p_usuario uuid, p_url text) IS 'Abre uma execução das conferências em TL_CONFERENCIA (quem disparou e o endereço da execução). Fecha como FALHOU a execução esquecida há mais de 1 h e recusa (55P03) se outra estiver em andamento. Só service_role.';

--
-- Name: iniciar_pre_classificacao(text, text, uuid, text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.iniciar_pre_classificacao(p_execucao text, p_disparo text, p_usuario uuid DEFAULT NULL::uuid, p_url text DEFAULT NULL::text, p_refazer boolean DEFAULT false, p_pedido jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_interrompidas integer;
begin
  if p_execucao is null or p_execucao !~ '^[A-Za-z0-9_-]{8,80}$' then
    raise exception 'Identificador de execução inválido' using errcode = '22023';
  end if;
  if p_disparo is null or p_disparo not in ('ROBO', 'MONITORA', 'GITHUB') then
    raise exception 'Disparo inválido: ROBO, MONITORA ou GITHUB' using errcode = '22023';
  end if;
  if (p_disparo = 'MONITORA') <> (p_usuario is not null) then
    raise exception 'Usuário só (e sempre) no disparo pelo MONITORA' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_pedido, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_pedido, '[]'::jsonb)) > 100
     or exists (select 1 from jsonb_array_elements(coalesce(p_pedido, '[]'::jsonb)) e
                 where jsonb_typeof(e) <> 'string' or length(e #>> '{}') > 100
                    or not private."FC_TEXTO_SEGURO_DO_AVISO"(e #>> '{}')) then
    raise exception 'Pedido inválido: até 100 editais (id, número ou nome)' using errcode = '22023';
  end if;

  -- Execução que morreu sem fechar (o workflow tem tempo limite de 20 min) não segura as próximas.
  update public."TL_PRE_CLASSIFICACAO" set
    "TP_SITUACAO" = 'FALHOU', "DT_FIM" = now(),
    "DS_MENSAGEM" = 'Interrompida: a execução terminou sem fechar.'
   where "TP_SITUACAO" = 'EM_ANDAMENTO' and "DT_INICIO" < now() - interval '1 hour';
  get diagnostics v_interrompidas = row_count;

  if exists (select 1 from public."TL_PRE_CLASSIFICACAO" t where t."TP_SITUACAO" = 'EM_ANDAMENTO') then
    raise exception 'Já há uma pré-classificação em andamento' using errcode = '55P03';
  end if;

  insert into public."TL_PRE_CLASSIFICACAO"
    ("CO_EXECUCAO", "TP_DISPARO", "CO_USUARIO_DISPARO", "DS_URL_EXECUCAO", "ST_REFAZER_LOTE", "DS_PEDIDO")
  values (p_execucao, p_disparo, p_usuario, left(p_url, 300),
          case when coalesce(p_refazer, false) then 'S' else 'N' end, coalesce(p_pedido, '[]'::jsonb));

  return jsonb_build_object('execucao', p_execucao, 'interrompidas', v_interrompidas);
end;
$_$;

--
-- Name: FUNCTION iniciar_pre_classificacao(p_execucao text, p_disparo text, p_usuario uuid, p_url text, p_refazer boolean, p_pedido jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.iniciar_pre_classificacao(p_execucao text, p_disparo text, p_usuario uuid, p_url text, p_refazer boolean, p_pedido jsonb) IS 'Abre uma execução da pré-classificação em TL_PRE_CLASSIFICACAO (quem disparou, se refaz o lote, os editais pedidos, o endereço da execução). Fecha como FALHOU a esquecida há mais de 1 h e recusa (55P03) se outra estiver em andamento. Só service_role.';

--
-- Name: iniciar_sync_analises_incremental(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.iniciar_sync_analises_incremental(p_sync_id uuid, p_origem text DEFAULT 'apps_script_analises_incremental_v1'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '5s'
    SET lock_timeout TO '1s'
    AS $$
declare
  v_row public."TL_SYNC_ANALISE"%rowtype;
  v_planilha text;
  v_encerradas jsonb;
  v_pendente record;
begin
  if p_sync_id is null then raise exception 'p_sync_id obrigatorio'; end if;
  -- [por-planilha] origem cadastrada e de carga incremental; lock por planilha.
  v_planilha := public."FC_PLANILHA_DA_ORIGEM_ANALISE"(p_origem, 'INCREMENTAL');
  if not pg_try_advisory_xact_lock(hashtext('public.processar_sync_analises:'||v_planilha)::bigint) then
    raise exception 'Outro processamento de analises esta em andamento.';
  end if;

  select * into v_row from public."TL_SYNC_ANALISE" where sync_id=p_sync_id order by id desc limit 1;
  if found then
    if coalesce(v_row.modo,'') <> 'INCREMENTAL_ACTIVE' then
      raise exception 'sync_id ja existe com modo diferente: %',coalesce(v_row.modo,'<null>');
    end if;
    if v_row."CO_PLANILHA" is distinct from v_planilha then
      raise exception 'sync_id ja existe para outra planilha: %',coalesce(v_row."CO_PLANILHA",'<null>');
    end if;
    return jsonb_build_object('ok',true,'sync_id',p_sync_id,'status',v_row.status,'existing',true,'resultado',v_row.resultado);
  end if;

  -- [nao-trava] execução desta planilha parada há mais de 30 min sai como 'erro' (20261007170000).
  v_encerradas := public."FC_ENCERRAR_SYNC_ANALISE_INATIVO"(v_planilha, 30);

  -- [por-planilha] só um sync pendente por planilha.
  select l.sync_id, l.status, greatest(l.updated_at, l.started_at, l.created_at) as ultima
    into v_pendente
    from public."TL_SYNC_ANALISE" l
   where l.status in ('carregado','processando') and l."CO_PLANILHA"=v_planilha
   order by l.id desc
   limit 1;
  if found then
    raise exception 'Existe outro sync de Analises pendente para a planilha % (sync_id %, status %, ultimo sinal %). Ele sera encerrado por inatividade depois de 30 min sem progresso.',
      v_planilha, v_pendente.sync_id, v_pendente.status, v_pendente.ultima;
  end if;

  insert into public."TL_SYNC_ANALISE"(sync_id,origem,modo,status,linhas_staging,started_at,resultado)
  values(p_sync_id,p_origem,'INCREMENTAL_ACTIVE','carregado',0,now(),jsonb_build_object(
    'modo_processamento','incremental',
    'incremental_preparado',false,
    'incremental_cursor',0,
    'incremental_iniciado_em',now(),
    'planilha',v_planilha
  ));

  return jsonb_build_object('ok',true,'sync_id',p_sync_id,'status','carregado','existing',false,
    'encerradas_por_inatividade',v_encerradas->'encerradas');
end;
$$;

--
-- Name: iniciar_sync_empregare(text, text, uuid, jsonb, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.iniciar_sync_empregare(p_sync text, p_disparo text, p_usuario uuid DEFAULT NULL::uuid, p_filtro jsonb DEFAULT '{}'::jsonb, p_vagas_pedidas integer DEFAULT 0, p_url text DEFAULT NULL::text, p_forcar boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_interrompidas integer;
begin
  if p_sync is null or p_sync !~ '^[A-Za-z0-9_-]{8,80}$' then
    raise exception 'Identificador de execução inválido' using errcode = '22023';
  end if;
  if p_disparo is null or p_disparo not in ('AGENDA', 'MONITORA', 'GITHUB') then
    raise exception 'Disparo inválido: AGENDA, MONITORA ou GITHUB' using errcode = '22023';
  end if;
  if (p_disparo = 'MONITORA') <> (p_usuario is not null) then
    raise exception 'Usuário só (e sempre) no disparo pelo MONITORA' using errcode = '22023';
  end if;
  if coalesce(p_vagas_pedidas, -1) not between 0 and 500 then
    raise exception 'Vagas pedidas fora de 0 a 500' using errcode = '22023';
  end if;

  -- Execução que morreu sem fechar (o workflow tem tempo limite de 2 h) não segura as próximas.
  update public."TL_SYNC_EMPREGARE" set
    "TP_SITUACAO" = 'FALHOU', "DT_FIM" = now(),
    "DS_MENSAGEM" = 'Interrompida: a execução terminou sem fechar a carga.'
   where "TP_SITUACAO" = 'EM_ANDAMENTO' and "DT_INICIO" < now() - interval '3 hours';
  get diagnostics v_interrompidas = row_count;

  if exists (select 1 from public."TL_SYNC_EMPREGARE" s where s."TP_SITUACAO" = 'EM_ANDAMENTO') then
    raise exception 'Já há uma execução do robô da Empregare em andamento' using errcode = '55P03';
  end if;

  insert into public."TL_SYNC_EMPREGARE" (
    "CO_SYNC", "TP_DISPARO", "CO_USUARIO_DISPARO", "ST_FORCADA", "DS_FILTRO", "QT_VAGA_PEDIDA", "DS_URL_EXECUCAO")
  values (
    p_sync, p_disparo, p_usuario, case when coalesce(p_forcar, false) then 'S' else 'N' end,
    case when jsonb_typeof(p_filtro) = 'object' then p_filtro else '{}'::jsonb end,
    p_vagas_pedidas, p_url);

  return jsonb_build_object('sync', p_sync, 'interrompidas', v_interrompidas);
end;
$_$;

--
-- Name: FUNCTION iniciar_sync_empregare(p_sync text, p_disparo text, p_usuario uuid, p_filtro jsonb, p_vagas_pedidas integer, p_url text, p_forcar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.iniciar_sync_empregare(p_sync text, p_disparo text, p_usuario uuid, p_filtro jsonb, p_vagas_pedidas integer, p_url text, p_forcar boolean) IS 'Abre uma execução do robô da Empregare em TL_SYNC_EMPREGARE (quem disparou, filtro, vagas pedidas, endereço da execução, forçar). Fecha como FALHOU a execução esquecida há mais de 3 h e recusa (55P03) se outra estiver em andamento. Só service_role.';

--
-- Name: jsonb_bool_or_null(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jsonb_bool_or_null(p_payload jsonb, p_key text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v text;
begin
  v := upper(trim(both from public.jsonb_text_or_null(p_payload, p_key)));

  if v is null or v = '' then
    return null;
  end if;

  v := translate(v, 'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ', 'AAAAAEEEEIIIIOOOOOUUUUC');

  if v in ('TRUE', 'T', 'YES', 'Y', 'SIM', 'S', '1') then
    return true;
  end if;

  if v in ('FALSE', 'F', 'NO', 'N', 'NAO', '0') then
    return false;
  end if;

  return null;
end;
$$;

--
-- Name: jsonb_date_or_null(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jsonb_date_or_null(p_payload jsonb, p_key text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v text := public.jsonb_text_or_null(p_payload, p_key);
begin
  if v is null then return null; end if;
  return v::date;
exception when others then
  return null;
end;
$$;

--
-- Name: jsonb_int_or_null(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jsonb_int_or_null(p_payload jsonb, p_key text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v text := public.jsonb_text_or_null(p_payload, p_key);
begin
  if v is null then return null; end if;
  return round(replace(v, ',', '.')::numeric)::integer;
exception when others then
  return null;
end;
$$;

