--
-- Name: jsonb_text_or_null(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jsonb_text_or_null(p_payload jsonb, p_key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select nullif(btrim(coalesce(p_payload ->> p_key, '')), '')
$$;

