--
-- Name: lancar_notas_entrevista(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lancar_notas_entrevista(p_entrevista uuid, p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_e public."TB_ENTREVISTA";
  v_cfg public."TB_ENTREVISTA_EDITAL";
  v_r public."TB_ROTEIRO_ENTREVISTA";
  v_eu uuid;
  v_admin boolean := private.is_master();
  x jsonb;
  y jsonb;
  v_comp public."TB_ROTEIRO_COMPETENCIA";
  v_av public."TB_ENTREVISTA_AVALIADOR";
  v_nota numeric;
  v_ant numeric;
  v_comp_novo text := nullif(p_dados ->> 'compareceu', '');
  v_qt_aspectos integer;
  v_aspectos jsonb;
  v_aspecto uuid;
  v_ant_txt text;
  v_novo_txt text;
  v_obs_ant text;
  v_obs_nova text;
  v_just_nova text;
  v_final public."TB_ENTREVISTA";
begin
  select * into v_e from public."TB_ENTREVISTA" where "CO_ENTREVISTA" = p_entrevista and "TP_ORIGEM" = 'sistema' and "ST_ATIVO" = 'S';
  if v_e."CO_ENTREVISTA" is null then raise exception 'Convocado não encontrado' using errcode = '22023'; end if;
  perform private."FC_EXIGIR_ENTREVISTAS_EDITAL"(v_e."CO_MONITORAMENTO", 2);
  select * into v_cfg from public."TB_ENTREVISTA_EDITAL" where "CO_MONITORAMENTO" = v_e."CO_MONITORAMENTO";
  select * into v_r from public."TB_ROTEIRO_ENTREVISTA" where "CO_ROTEIRO" = v_e."CO_ROTEIRO";
  select p.id into v_eu from private.current_profile() p;
  select count(*) into v_qt_aspectos from public."TB_ROTEIRO_ASPECTO" s where s."CO_ROTEIRO" = v_e."CO_ROTEIRO";

  -- Banca da entrevista: grava mesmo sem mudar o comparecimento.
  if nullif(p_dados ->> 'banca', '') is not null
     and (p_dados ->> 'banca')::smallint is distinct from v_e."NU_BANCA" then
    update public."TB_ENTREVISTA" set "NU_BANCA" = (p_dados ->> 'banca')::smallint where "CO_ENTREVISTA" = p_entrevista;
  end if;

  if v_comp_novo is not null then
    if v_comp_novo not in ('S', 'N') then raise exception 'Comparecimento inválido' using errcode = '22023'; end if;
    if v_comp_novo is distinct from v_e."ST_COMPARECEU" then
      update public."TB_ENTREVISTA" set "ST_COMPARECEU" = v_comp_novo, "NU_BANCA" = coalesce(nullif(p_dados ->> 'banca', '')::smallint, "NU_BANCA")
       where "CO_ENTREVISTA" = p_entrevista;
      insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
      values (p_entrevista, 'compareceu', v_e."ST_COMPARECEU", v_comp_novo, (select auth.uid()));
    end if;
  end if;

  for x in select value from jsonb_array_elements(coalesce(p_dados -> 'notas', '[]')) loop
    select * into v_comp from public."TB_ROTEIRO_COMPETENCIA" where "CO_COMPETENCIA" = (x ->> 'competencia')::uuid and "CO_ROTEIRO" = v_e."CO_ROTEIRO";
    if v_comp."CO_COMPETENCIA" is null then raise exception 'Competência não é do roteiro deste edital' using errcode = '22023'; end if;
    select * into v_av from public."TB_ENTREVISTA_AVALIADOR" where "CO_AVALIADOR" = (x ->> 'avaliador')::uuid and "CO_MONITORAMENTO" = v_e."CO_MONITORAMENTO" and "ST_ATIVO" = 'S';
    if v_av."CO_AVALIADOR" is null then raise exception 'Avaliador não é da banca deste edital' using errcode = '22023'; end if;
    if v_cfg."TP_LANCAMENTO" = 'AVALIADOR' and not v_admin and v_av."CO_PERFIL_USUARIO" is distinct from v_eu then
      raise exception 'Neste edital cada avaliador lança a própria nota' using errcode = '42501';
    end if;

    if v_qt_aspectos > 0 then
      -- Roteiro com aspectos: {aspectos: [{aspecto, nota}]} com todos os aspectos, ou nulo para apagar.
      if nullif(x ->> 'nota', '') is not null and not (x ? 'aspectos') then
        raise exception 'Este roteiro avalia por aspectos: informe a nota de cada aspecto' using errcode = '22023';
      end if;
      if x ? 'aspectos' and jsonb_typeof(x -> 'aspectos') not in ('array', 'null') then
        raise exception 'Aspectos: informe uma lista' using errcode = '22023';
      end if;
      v_aspectos := case when jsonb_typeof(x -> 'aspectos') = 'array' then x -> 'aspectos' end;
      select string_agg(trim_scale(a."VL_NOTA")::text, '; ' order by s."NU_ORDEM") into v_ant_txt
        from public."TB_ENTREVISTA_AVALIACAO_ASPECTO" a
        join public."TB_ROTEIRO_ASPECTO" s on s."CO_ASPECTO" = a."CO_ASPECTO"
       where a."CO_ENTREVISTA" = p_entrevista and a."CO_COMPETENCIA" = v_comp."CO_COMPETENCIA" and a."CO_AVALIADOR" = v_av."CO_AVALIADOR";
      if v_aspectos is null or not exists (select 1 from jsonb_array_elements(v_aspectos) z where nullif(z ->> 'nota', '') is not null) then
        -- Apagar: a nota do avaliador sai e leva as dos aspectos (on delete cascade).
        delete from public."TB_ENTREVISTA_AVALIACAO"
         where "CO_ENTREVISTA" = p_entrevista and "CO_COMPETENCIA" = v_comp."CO_COMPETENCIA" and "CO_AVALIADOR" = v_av."CO_AVALIADOR";
        if found then
          insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
          values (p_entrevista, v_comp."CO_COMPETENCIA", v_av."CO_AVALIADOR", 'aspectos', v_ant_txt, null, (select auth.uid()));
        end if;
        continue;
      end if;
      if not private."FC_AVALIADOR_AVALIA"(v_av."CO_AVALIADOR", v_comp."CO_COMPETENCIA") then
        raise exception '% não avalia "%" neste edital (a configuração da banca define as competências de cada avaliador)',
          v_av."NO_AVALIADOR", v_comp."NO_COMPETENCIA" using errcode = '23514';
      end if;
      for y in select value from jsonb_array_elements(v_aspectos) loop
        v_aspecto := nullif(y ->> 'aspecto', '')::uuid;
        if v_aspecto is null or not exists (select 1 from public."TB_ROTEIRO_ASPECTO" s
                                             where s."CO_ASPECTO" = v_aspecto and s."CO_ROTEIRO" = v_e."CO_ROTEIRO") then
          raise exception 'Aspecto não é do roteiro deste edital' using errcode = '22023';
        end if;
        v_nota := nullif(y ->> 'nota', '')::numeric;
        if v_nota is null then
          raise exception 'Informe a nota de todos os aspectos de % (ou apague todas)', v_comp."NO_COMPETENCIA" using errcode = '22023';
        end if;
        perform private."FC_EXIGIR_NOTA_NA_ESCALA"(v_e."CO_ROTEIRO", v_comp."CO_COMPETENCIA", v_nota);
      end loop;
      if jsonb_array_length(v_aspectos) <> v_qt_aspectos
         or (select count(distinct z ->> 'aspecto') from jsonb_array_elements(v_aspectos) z) <> v_qt_aspectos then
        raise exception 'Informe a nota de cada um dos % aspectos de %', v_qt_aspectos, v_comp."NO_COMPETENCIA" using errcode = '22023';
      end if;
      select string_agg(trim_scale((z ->> 'nota')::numeric)::text, '; ' order by s."NU_ORDEM"), round(avg((z ->> 'nota')::numeric), 2)
        into v_novo_txt, v_nota
        from jsonb_array_elements(v_aspectos) z
        join public."TB_ROTEIRO_ASPECTO" s on s."CO_ASPECTO" = (z ->> 'aspecto')::uuid;
      if v_ant_txt is not distinct from v_novo_txt then continue; end if;
      insert into public."TB_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR", "VL_NOTA", "CO_USUARIO_ATUALIZACAO")
      values (p_entrevista, v_comp."CO_COMPETENCIA", v_av."CO_AVALIADOR", v_nota, (select auth.uid()))
      on conflict ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR") do update set
        "VL_NOTA" = excluded."VL_NOTA", "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO";
      insert into public."TB_ENTREVISTA_AVALIACAO_ASPECTO" ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR", "CO_ASPECTO", "VL_NOTA", "CO_USUARIO_ATUALIZACAO")
      select p_entrevista, v_comp."CO_COMPETENCIA", v_av."CO_AVALIADOR", (z ->> 'aspecto')::uuid, (z ->> 'nota')::numeric, (select auth.uid())
        from jsonb_array_elements(v_aspectos) z
      on conflict ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR", "CO_ASPECTO") do update set
        "VL_NOTA" = excluded."VL_NOTA", "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO";
      insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
      values (p_entrevista, v_comp."CO_COMPETENCIA", v_av."CO_AVALIADOR", 'aspectos', v_ant_txt, v_novo_txt, (select auth.uid()));
      continue;
    end if;

    -- Roteiro sem aspectos: uma nota por avaliador (como antes).
    if jsonb_typeof(x -> 'aspectos') = 'array' and jsonb_array_length(x -> 'aspectos') > 0 then
      raise exception 'Este roteiro não avalia por aspectos' using errcode = '22023';
    end if;
    v_nota := nullif(x ->> 'nota', '')::numeric;
    if v_nota is null then
      select "VL_NOTA" into v_ant from public."TB_ENTREVISTA_AVALIACAO"
       where "CO_ENTREVISTA" = p_entrevista and "CO_COMPETENCIA" = v_comp."CO_COMPETENCIA" and "CO_AVALIADOR" = v_av."CO_AVALIADOR";
      if found then
        delete from public."TB_ENTREVISTA_AVALIACAO"
         where "CO_ENTREVISTA" = p_entrevista and "CO_COMPETENCIA" = v_comp."CO_COMPETENCIA" and "CO_AVALIADOR" = v_av."CO_AVALIADOR";
        insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
        values (p_entrevista, v_comp."CO_COMPETENCIA", v_av."CO_AVALIADOR", 'nota', v_ant::text, null, (select auth.uid()));
      end if;
      continue;
    end if;
    if not private."FC_AVALIADOR_AVALIA"(v_av."CO_AVALIADOR", v_comp."CO_COMPETENCIA") then
      raise exception '% não avalia "%" neste edital (a configuração da banca define as competências de cada avaliador)',
        v_av."NO_AVALIADOR", v_comp."NO_COMPETENCIA" using errcode = '23514';
    end if;
    perform private."FC_EXIGIR_NOTA_NA_ESCALA"(v_e."CO_ROTEIRO", v_comp."CO_COMPETENCIA", v_nota);
    select "VL_NOTA" into v_ant from public."TB_ENTREVISTA_AVALIACAO"
     where "CO_ENTREVISTA" = p_entrevista and "CO_COMPETENCIA" = v_comp."CO_COMPETENCIA" and "CO_AVALIADOR" = v_av."CO_AVALIADOR";
    if v_ant is not distinct from v_nota then continue; end if;
    insert into public."TB_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR", "VL_NOTA", "CO_USUARIO_ATUALIZACAO")
    values (p_entrevista, v_comp."CO_COMPETENCIA", v_av."CO_AVALIADOR", v_nota, (select auth.uid()))
    on conflict ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR") do update set
      "VL_NOTA" = excluded."VL_NOTA", "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO";
    insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "CO_COMPETENCIA", "CO_AVALIADOR", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
    values (p_entrevista, v_comp."CO_COMPETENCIA", v_av."CO_AVALIADOR", 'nota', v_ant::text, v_nota::text, (select auth.uid()));
  end loop;

  -- Observação do avaliador (opcional; uma por avaliador na entrevista): {observacoes: [{avaliador, texto|null}]}.
  for x in select value from jsonb_array_elements(coalesce(p_dados -> 'observacoes', '[]')) loop
    select * into v_av from public."TB_ENTREVISTA_AVALIADOR"
     where "CO_AVALIADOR" = nullif(x ->> 'avaliador', '')::uuid and "CO_MONITORAMENTO" = v_e."CO_MONITORAMENTO";
    if v_av."CO_AVALIADOR" is null then raise exception 'Avaliador não é da banca deste edital' using errcode = '22023'; end if;
    v_obs_nova := nullif(btrim(x ->> 'texto'), '');
    if length(v_obs_nova) > 1000 then
      raise exception 'Observação de %: até 1.000 caracteres', v_av."NO_AVALIADOR" using errcode = '22023';
    end if;
    v_obs_ant := null;
    select o."DS_OBSERVACAO" into v_obs_ant from public."TB_ENTREVISTA_OBSERVACAO_AVALIADOR" o
     where o."CO_ENTREVISTA" = p_entrevista and o."CO_AVALIADOR" = v_av."CO_AVALIADOR";
    if v_obs_ant is not distinct from v_obs_nova then continue; end if;
    if v_cfg."TP_LANCAMENTO" = 'AVALIADOR' and not v_admin and v_av."CO_PERFIL_USUARIO" is distinct from v_eu then
      raise exception 'Neste edital cada avaliador escreve a própria observação' using errcode = '42501';
    end if;
    if v_obs_nova is null then
      delete from public."TB_ENTREVISTA_OBSERVACAO_AVALIADOR"
       where "CO_ENTREVISTA" = p_entrevista and "CO_AVALIADOR" = v_av."CO_AVALIADOR";
    else
      insert into public."TB_ENTREVISTA_OBSERVACAO_AVALIADOR" ("CO_ENTREVISTA", "CO_AVALIADOR", "DS_OBSERVACAO", "CO_USUARIO_ATUALIZACAO")
      values (p_entrevista, v_av."CO_AVALIADOR", v_obs_nova, (select auth.uid()))
      on conflict ("CO_ENTREVISTA", "CO_AVALIADOR") do update set
        "DS_OBSERVACAO" = excluded."DS_OBSERVACAO", "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO";
    end if;
    insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "CO_AVALIADOR", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
    values (p_entrevista, v_av."CO_AVALIADOR", 'observacao', v_obs_ant, v_obs_nova, (select auth.uid()));
  end loop;

  -- Justificativa da banca (opcional na chamada; sem a chave, fica como está).
  if p_dados ? 'justificativa' then
    v_just_nova := nullif(btrim(p_dados ->> 'justificativa'), '');
    if length(v_just_nova) > 4000 then
      raise exception 'Justificativa da banca: até 4.000 caracteres' using errcode = '22023';
    end if;
    if v_just_nova is distinct from (select e."DS_JUSTIFICATIVA_BANCA" from public."TB_ENTREVISTA" e where e."CO_ENTREVISTA" = p_entrevista) then
      insert into public."TH_ENTREVISTA_AVALIACAO" ("CO_ENTREVISTA", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
      select p_entrevista, 'justificativa', e."DS_JUSTIFICATIVA_BANCA", v_just_nova, (select auth.uid())
        from public."TB_ENTREVISTA" e where e."CO_ENTREVISTA" = p_entrevista;
      update public."TB_ENTREVISTA" set "DS_JUSTIFICATIVA_BANCA" = v_just_nova where "CO_ENTREVISTA" = p_entrevista;
    end if;
  end if;

  perform private."FC_CALCULAR_ENTREVISTA"(p_entrevista);

  -- Inapto ou Faltou pede a justificativa da banca. Vale para cada gravação nova (a regra está aqui,
  -- no lançamento): as entrevistas já gravadas não mudam e a carga da planilha não passa por aqui.
  select * into v_final from public."TB_ENTREVISTA" where "CO_ENTREVISTA" = p_entrevista;
  if (v_final."TP_PARECER" = 'INAPTO' or v_final."ST_COMPARECEU" = 'N') and v_final."DS_JUSTIFICATIVA_BANCA" is null then
    raise exception '%', case when v_final."ST_COMPARECEU" = 'N'
        then 'Escreva a justificativa da banca: ela é obrigatória quando o candidato falta'
        else 'Escreva a justificativa da banca: ela é obrigatória quando o parecer é Inapto' end
      using errcode = '23514', hint = 'Preencha "Justificativa da banca" na ficha de notas e salve de novo.';
  end if;
  return public.obter_entrevistas_do_edital(v_e."CO_MONITORAMENTO");
end;
$$;

--
-- Name: FUNCTION lancar_notas_entrevista(p_entrevista uuid, p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lancar_notas_entrevista(p_entrevista uuid, p_dados jsonb) IS 'Lança/corrige notas ({notas:[{competencia, avaliador, nota|null}]}; roteiro com aspectos: {competencia, avaliador, aspectos:[{aspecto, nota}]|null}, todos os aspectos), o comparecimento ({compareceu:S|N, banca}), as observações dos avaliadores ({observacoes:[{avaliador, texto|null}]}, até 1.000 caracteres) e a justificativa da banca ({justificativa}, até 4.000) de um convocado, valida a escala do roteiro, recusa (23514) a nota de avaliador em competência que não é dele e a gravação que termina INAPTO ou com Faltou sem justificativa, grava o histórico e recalcula o resultado. entrevistas >= editor; no modo AVALIADOR, só a própria nota e a própria observação.';

--
-- Name: ler_respostas_pergunta_vaga(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ler_respostas_pergunta_vaga(p_vaga text, p_compacto boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with linhas as (
    select (select jsonb_object_agg(e.key, left(btrim(e.value), 200))
              from jsonb_each_text(c."DS_COLUNA_ORIGINAL") e
             where e.key ilike 'Pergunta %' and coalesce(btrim(e.value), '') <> '') as linha
      from public."TB_EMPREGARE_CANDIDATO" c
     where c."CO_VAGA" = p_vaga and c."ST_REGISTRO_ATIVO" = 'S'
  ), nomes as (
    select coalesce(array_agg(distinct k.nome order by k.nome), '{}') as lista
      from linhas x cross join lateral jsonb_object_keys(x.linha) k(nome)
     where coalesce(p_compacto, false)
  )
  select case when coalesce(p_compacto, false) then
           jsonb_build_object(
             'vaga', p_vaga,
             'candidatos', (select count(*) from linhas),
             'colunas', to_jsonb(n.lista),
             -- [enxuto] Cada linha: os valores na ordem de "colunas" (null = sem resposta).
             'linhas', coalesce((
               select jsonb_agg((select jsonb_agg(x.linha -> u.nome order by u.i)
                                   from unnest(n.lista) with ordinality u(nome, i)))
                 from linhas x where x.linha is not null), '[]'::jsonb))
         else
           jsonb_build_object(
             'vaga', p_vaga,
             'candidatos', (select count(*) from linhas),
             'linhas', coalesce((select jsonb_agg(x.linha) from linhas x where x.linha is not null), '[]'::jsonb))
         end
    from nomes n;
$$;

--
-- Name: FUNCTION ler_respostas_pergunta_vaga(p_vaga text, p_compacto boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ler_respostas_pergunta_vaga(p_vaga text, p_compacto boolean) IS 'Resumo das perguntas da carga (robô da Empregare): as respostas dos candidatos ativos da vaga, só as colunas "Pergunta …", sem espaços nas pontas e até 200 caracteres. Sem p_compacto: "linhas" = [{coluna: resposta}]. Com p_compacto (desde 20261014220000): "colunas" = os nomes uma vez e "linhas" = [[valor na ordem de colunas, null = sem resposta]]. Só service_role.';

--
-- Name: liberar_entrevista_edital(uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.liberar_entrevista_edital(p_edital uuid, p_ate date, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  if not private.is_master() then
    raise exception 'Só o administrador global libera editais fora da janela' using errcode = '42501';
  end if;
  if not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital) then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then
    raise exception 'Informe o motivo (3 a 500 caracteres)' using errcode = '22023';
  end if;
  if p_ate is not null and p_ate not between v_hoje and v_hoje + 180 then
    raise exception 'A liberação vai de hoje até no máximo 180 dias' using errcode = '22023';
  end if;

  update public."TB_ENTREVISTA_LIBERACAO"
     set "ST_REGISTRO_ATIVO" = 'N', "DT_DESATIVACAO" = now(), "CO_USUARIO_DESATIVACAO" = (select auth.uid())
   where "CO_MONITORAMENTO" = p_edital and "ST_REGISTRO_ATIVO" = 'S';
  if p_ate is not null then
    insert into public."TB_ENTREVISTA_LIBERACAO" ("CO_MONITORAMENTO", "DT_LIBERADO_ATE", "DS_MOTIVO", "CO_USUARIO")
    values (p_edital, p_ate, btrim(p_motivo), (select auth.uid()));
  end if;
  return json_build_object('edital', p_edital, 'liberado_ate', p_ate);
end;
$$;

--
-- Name: FUNCTION liberar_entrevista_edital(p_edital uuid, p_ate date, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.liberar_entrevista_edital(p_edital uuid, p_ate date, p_motivo text) IS 'Administrador global: libera o edital em "Conduzir entrevistas" até p_ate (máx. 180 dias), com motivo; p_ate nulo encerra a liberação vigente.';

--
-- Name: liberar_reserva(uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.liberar_reserva(p_edital uuid, p_fichas uuid[], p_motivo text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 2);
  v_uid uuid := (select auth.uid());
  v_coord boolean := coalesce(private."FC_PAPEL_AVALIACAO"(p_edital) = 'COORDENADOR', false);
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_item record;
  v_liberadas integer := 0;
begin
  if p_fichas is null or cardinality(p_fichas) not between 1 and 5000 then
    raise exception 'Escolha de 1 a 5.000 fichas.' using errcode = '22023';
  end if;
  if v_motivo is not null and length(v_motivo) > 2000 then
    raise exception 'Motivo com até 2.000 caracteres.' using errcode = '22023';
  end if;
  for v_item in
    select f."CO_FICHA_ANALISE" as ficha, f."CO_USUARIO_RESERVA" as reserva, f."TP_SITUACAO" as situacao,
           f."CO_USUARIO_RESPONSAVEL" as responsavel
      from public."TB_FICHA_ANALISE" f
     where f."CO_MONITORAMENTO" = p_edital and f."CO_FICHA_ANALISE" = any (p_fichas)
       and f."DT_RESERVA_EXPIRA" > now()
     order by f."CO_FICHA_ANALISE"
     for update
  loop
    if v_item.reserva <> v_uid then
      if not v_coord then
        raise exception 'Só a coordenação libera a reserva de outra pessoa' using errcode = '42501';
      end if;
      if v_motivo is null or length(v_motivo) < 10 or not private."FC_MOTIVO_PARECE_TEXTO"(v_motivo, 2) then
        raise exception 'Informe o motivo para liberar a reserva de outra pessoa (10 a 2.000 caracteres, com pelo menos 2 palavras).' using errcode = '22023';
      end if;
    end if;
    update public."TB_FICHA_ANALISE" set
      "CO_USUARIO_RESERVA" = null, "DT_RESERVA" = null, "DT_RESERVA_EXPIRA" = null,
      "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
     where "CO_FICHA_ANALISE" = v_item.ficha;
    perform private."FC_HISTORICO_FICHA"(v_item.ficha, case when v_item.reserva = v_uid then 'LIBERAR' else 'LIBERAR_RESERVA' end,
                                         v_item.situacao, v_item.responsavel,
                                         case when v_item.reserva = v_uid then null else v_motivo end, v_uid);
    v_liberadas := v_liberadas + 1;
  end loop;
  return json_build_object('liberadas', v_liberadas);
end;
$$;

--
-- Name: FUNCTION liberar_reserva(p_edital uuid, p_fichas uuid[], p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.liberar_reserva(p_edital uuid, p_fichas uuid[], p_motivo text) IS 'Libera reservas vigentes de fichas do edital: a sua (ao fechar ou concluir), sem motivo; a de outra pessoa (reserva presa), só a coordenação e com motivo de 10 a 2.000. A situação e o responsável não mudam. Fichas sem reserva vigente são ignoradas. Devolve quantas foram liberadas.';

--
-- Name: limpar_eventos_acesso_retencao(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.limpar_eventos_acesso_retencao(p_heartbeat_dias integer DEFAULT 30, p_eventos_dias integer DEFAULT 365) RETURNS TABLE(objeto text, criterio text, removidos integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_heartbeat_dias integer := least(greatest(coalesce(p_heartbeat_dias, 30), 7), 365);
  v_eventos_dias integer := least(greatest(coalesce(p_eventos_dias, 365), 30), 1825);
  v_count integer;
begin
  delete from public."TL_EVENTO_ACESSO"
  where evento = 'heartbeat'
    and created_at < now() - make_interval(days => v_heartbeat_dias);
  get diagnostics v_count = row_count;
  objeto := '"TL_EVENTO_ACESSO"';
  criterio := 'heartbeat_' || v_heartbeat_dias || '_dias';
  removidos := v_count;
  return next;

  delete from public."TL_EVENTO_ACESSO"
  where evento <> 'heartbeat'
    and created_at < now() - make_interval(days => v_eventos_dias);
  get diagnostics v_count = row_count;
  objeto := '"TL_EVENTO_ACESSO"';
  criterio := 'eventos_' || v_eventos_dias || '_dias';
  removidos := v_count;
  return next;
end;
$$;

--
-- Name: link_auth_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_auth_user_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  update public."TB_PERFIL_USUARIO"
  set user_id = new.id,
      updated_at = now()
  where user_id is null
    and lower(email) = lower(new.email);

  return new;
end;
$$;

--
-- Name: listar_abas_do_menu(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_abas_do_menu() RETURNS json
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(json_agg(json_build_object(
      'co_aba', a."CO_ABA",
      'no_aba', a."NO_ABA",
      'ds_icone', a."DS_ICONE",
      'nu_ordem', a."NU_ORDEM",
      'co_view', a."CO_VIEW",
      'co_recurso', a."CO_RECURSO",
      'tp_aba', a."TP_ABA",
      'st_beta', a."ST_BETA" = 'S',
      'tp_situacao', a."TP_SITUACAO",
      'ds_mensagem', a."DS_MENSAGEM_MANUTENCAO",
      'dt_previsao', a."DT_PREVISAO_RETORNO",
      'areas', coalesce((
        select json_agg(json_build_object(
            'co_area', r."CO_AREA",
            'nu_ordem', coalesce(r."NU_ORDEM", a."NU_ORDEM"),
            'co_view', coalesce(r."CO_VIEW", a."CO_VIEW"),
            'ds_icone', coalesce(r."DS_ICONE", a."DS_ICONE"),
            'tp_situacao', r."TP_SITUACAO",
            'ds_mensagem', r."DS_MENSAGEM_MANUTENCAO",
            'dt_previsao', r."DT_PREVISAO_RETORNO"
          ) order by ar."NU_ORDEM", r."CO_AREA")
        from public."RL_ABA_AREA" r
        join public."TB_AREA" ar on ar."CO_AREA" = r."CO_AREA"
        where r."CO_ABA" = a."CO_ABA"
          and r."ST_ATIVO" = 'S'
          and ar."ST_ATIVO" = 'S'
      ), '[]'::json)
    ) order by a."NU_ORDEM", a."CO_ABA"), '[]'::json)
  from public."TB_ABA" a
  where a."ST_ATIVO" = 'S';
$$;

--
-- Name: FUNCTION listar_abas_do_menu(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_abas_do_menu() IS 'Catálogo ativo do menu lateral: abas com rótulo, ícone, ordem, view e recurso, e as áreas em que aparecem (ordem, view e ícone já resolvidos por área). Sem permissão por perfil: quem filtra é o front, como antes.';

--
-- Name: listar_acompanhamento_da_visao_geral(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_acompanhamento_da_visao_geral(p_area text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
declare
  v_area text := lower(btrim(coalesce(p_area, '')));
  v_editais uuid[];
begin
  if not private.pode_recurso('dashboard') then
    raise exception 'Sem permissão para este recurso' using errcode = '42501';
  end if;
  if not (v_area = any ((select private."FC_AREAS_USUARIO"())::text[])) then
    raise exception 'Sem permissão para esta área' using errcode = '42501';
  end if;

  select coalesce(array_agg(m.id), '{}') into v_editais
    from public."TB_MONITORAMENTO_INDIGENA" m
   where m.ativo
     and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
     and m."CO_AREA" = v_area
     and ((select private."FC_EDITAIS_VISIVEIS"()) is null
          or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]));

  return jsonb_build_object(
    'etapas', coalesce((
      select jsonb_agg(jsonb_build_object(
               'monitoramento_id', c.monitoramento_id,
               'ordem', c.ordem,
               'atividade', c.atividade,
               'data_inicio', c.data_inicio,
               'data_fim', c.data_fim
             ) order by c.monitoramento_id, c.data_inicio, c.ordem)
        from public."TB_CRONOGRAMA_MONIT_INDIG" c
       where c.monitoramento_id = any (v_editais)
    ), '[]'::jsonb),
    'listas', coalesce((
      select jsonb_agg(jsonb_build_object(
               'monitoramento_id', r.edital_id,
               'aprovados', r.aprovados,
               'com_status', r.com_status,
               'contratados', r.contratados,
               'desistentes', r.desistentes
             ) order by r.edital_id)
        from (
          select l.edital_id,
                 count(c.id)::integer as aprovados,
                 (count(c.id) filter (where nullif(btrim(c.status), '') is not null))::integer as com_status,
                 (count(c.id) filter (where c.status in ('Contratado', 'Migração') and not private."FC_EM_OUTRA_LISTA"(c.id)))::integer as contratados,
                 (count(c.id) filter (where c.status = 'Desistente'))::integer as desistentes
            from public."TB_LISTA_APROVADO" l
            left join public."TB_CANDIDATO_APROVADO" c on c.lista_id = l.id and c.removido_em is null
           where l.vigente is true
             and l.edital_id = any (select unnest(v_editais)::text)
           group by l.edital_id
        ) r
    ), '[]'::jsonb)
  );
end;
$$;

--
-- Name: FUNCTION listar_acompanhamento_da_visao_geral(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_acompanhamento_da_visao_geral(p_area text) IS 'Visão geral de uma área (só leitura): as etapas do cronograma e, por edital com lista de aprovados vigente, as contagens de aprovados, com status, contratados (Contratado/Migração) e desistentes. Recurso dashboard, área do usuário e recorte da coordenação.';

--
-- Name: listar_acompanhamento_da_visao_geral_se_mudou(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_acompanhamento_da_visao_geral_se_mudou(p_area text, p_versao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_marca constant text := private."FC_MARCA_DA_RPC"('listar_acompanhamento_da_visao_geral', p_area => p_area);
begin
  if v_marca is null then
    return private."FC_SE_MUDOU"(public.listar_acompanhamento_da_visao_geral(p_area), p_versao);
  end if;
  if p_versao = v_marca then
    return jsonb_build_object('inalterado', true, 'versao', v_marca);
  end if;
  return public.listar_acompanhamento_da_visao_geral(p_area) || jsonb_build_object('versao', v_marca);
end;
$$;

--
-- Name: FUNCTION listar_acompanhamento_da_visao_geral_se_mudou(p_area text, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_acompanhamento_da_visao_geral_se_mudou(p_area text, p_versao text) IS 'listar_acompanhamento_da_visao_geral com versão: a marca das fontes (FC_MARCA_DA_RPC) sai antes de montar; p_versao igual devolve só { inalterado, versao } (20261029170000). Mesma permissão.';

--
-- Name: listar_anexos_candidatos_aprovados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_anexos_candidatos_aprovados() RETURNS TABLE(anexo_id uuid, candidato_id uuid, arquivo_nome text, tamanho integer, incluido_em timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not (private.pode_recurso('aprovados',1)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  return query
  select a."CO_ANEXO", a."CO_CANDIDATO", a."NO_ARQUIVO",
         a."QT_TAMANHO_BYTES", a."DT_INCLUSAO"
    from public."TB_ANEXO_CANDIDATO_APROVADO" a
    join public."TB_CANDIDATO_APROVADO" c on c.id = a."CO_CANDIDATO"
    join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
   where l.vigente is true
     and c.removido_em is null
     and m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
      and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
   order by a."CO_CANDIDATO", a."DT_INCLUSAO";
end;
$$;

--
-- Name: listar_anexos_empregare(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_anexos_empregare(p_vaga text, p_codigos text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_codigos text[] := array(select distinct btrim(x) from unnest(coalesce(p_codigos, '{}'::text[])) x where btrim(x) <> '');
begin
  if p_vaga is null or p_vaga !~ '^[0-9]{1,20}$' then
    raise exception 'Código de vaga inválido' using errcode = '22023';
  end if;
  if cardinality(v_codigos) > 1000 or exists (select 1 from unnest(v_codigos) x where x !~ '^[0-9]{1,20}$') then
    raise exception 'Até 1.000 códigos de candidato, só dígitos' using errcode = '22023';
  end if;

  return (
    with ativos as (
      select c."CO_EMPREGARE_CANDIDATO" as id, btrim(c."CO_CANDIDATO_EMPREGARE") as codigo,
             private."FC_LIMITE_DA_RESPOSTA_EMPREGARE"(c."DS_COLUNA_ORIGINAL") as limite,
             (select max(r."DT_CAPTURA") from public."TB_EMPREGARE_RESPOSTA" r
               where r."CO_EMPREGARE_CANDIDATO" = c."CO_EMPREGARE_CANDIDATO") as capturado_em
        from public."TB_EMPREGARE_CANDIDATO" c
       where c."CO_VAGA" = p_vaga and c."ST_REGISTRO_ATIVO" = 'S' and c."CO_CANDIDATO_EMPREGARE" is not null
         and (cardinality(v_codigos) = 0 or btrim(c."CO_CANDIDATO_EMPREGARE") = any (v_codigos))
    ),
    marcados as (
      select a.*, (a.limite is not null and a.capturado_em is not null and a.capturado_em < a.limite) as suspeito
        from ativos a
    ),
    -- Com códigos, todos os pedidos; sem códigos, só os suspeitos (a lista fica pequena).
    escolhidos as (
      select m.* from marcados m where cardinality(v_codigos) > 0 or m.suspeito
    )
    select jsonb_build_object(
      'vaga', p_vaga,
      'conhecida', ev."CO_VAGA" is not null,
      'vaga_interno', ev."CO_VAGA_INTERNO",
      'colunas', coalesce(ev."DS_COLUNA", '[]'::jsonb),
      'ativos', (select count(*) from marcados),
      'suspeitos', (select count(*) from marcados where suspeito),
      'sem_captura', (select count(*) from marcados where capturado_em is null),
      'nao_encontrados', coalesce((select jsonb_agg(x order by x) from unnest(v_codigos) x
                                    where not exists (select 1 from ativos a where a.codigo = x)), '[]'::jsonb),
      'candidatos', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'codigo', e.codigo,
                 'suspeito', e.suspeito,
                 'releitura_desde', e.limite,
                 'capturado_em', e.capturado_em,
                 'respostas', coalesce((
                   select jsonb_agg(jsonb_build_object(
                            'resposta', r."CO_RESPOSTA_QUESTIONARIO",
                            'perguntas', r."QT_PERGUNTA",
                            'capturado_em', r."DT_CAPTURA",
                            -- [pergunta, número, hash do arquivo=, hash do link]: nada que abra o arquivo.
                            'anexos', coalesce((
                              select jsonb_agg(jsonb_build_array(
                                       an."CO_PERGUNTA_EMPREGARE", an."NU_ARQUIVO",
                                       left(encode(sha256(convert_to(coalesce(private."FC_ARQUIVO_DO_LINK_EMPREGARE"(an."DS_LINK"), an."DS_LINK"), 'UTF8')), 'hex'), 16),
                                       left(encode(sha256(convert_to(an."DS_LINK", 'UTF8')), 'hex'), 16))
                                     order by an."CO_PERGUNTA_EMPREGARE", an."NU_ARQUIVO")
                                from public."TB_EMPREGARE_ANEXO" an
                               where an."CO_EMPREGARE_RESPOSTA" = r."CO_EMPREGARE_RESPOSTA"), '[]'::jsonb))
                          order by r."CO_RESPOSTA_QUESTIONARIO")
                     from public."TB_EMPREGARE_RESPOSTA" r
                    where r."CO_EMPREGARE_CANDIDATO" = e.id), '[]'::jsonb))
               order by e.codigo)
          from escolhidos e), '[]'::jsonb))
      from (select 1) u
      left join public."TB_EMPREGARE_VAGA" ev on ev."CO_VAGA" = p_vaga
  );
end;
$_$;

--
-- Name: FUNCTION listar_anexos_empregare(p_vaga text, p_codigos text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_anexos_empregare(p_vaga text, p_codigos text[]) IS 'Para o modo "anexos" do robô da Empregare (e o ensaio seco): o que está gravado dos anexos do questionário dos candidatos ativos da vaga — com p_codigos (até 1.000 códigos da Empregare), os pedidos; sem, só os suspeitos (captura antes de FC_LIMITE_DA_RESPOSTA_EMPREGARE: resposta editada depois da captura). Por candidato: suspeito, releitura_desde, capturado_em e as respostas [{resposta, perguntas, capturado_em, anexos: [[pergunta, número, hash16 do arquivo=, hash16 do link]]}] — sem link, nome de arquivo nem token. Mais: conhecida, vaga_interno, colunas da última exportação, ativos, suspeitos, sem_captura e nao_encontrados. Só leitura; só service_role.';

--
-- Name: listar_anexos_para_leitura(text[], text, boolean, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_anexos_para_leitura(p_editais text[], p_versao text, p_forcar boolean, p_limite integer, p_sal text, p_so_relidos boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_pedidos text[] := array(select btrim(x) from unnest(coalesce(p_editais, '{}')) x where btrim(x) <> '');
  v_ids uuid[];
begin
  if cardinality(v_pedidos) > 100 then
    raise exception 'Até 100 editais por execução' using errcode = '22023';
  end if;
  if coalesce(p_versao, '') !~ '^[0-9A-Za-z._-]{1,20}$' then
    raise exception 'Versão do extrator inválida' using errcode = '22023';
  end if;
  if p_limite is null or p_limite not between 1 and 2000 then
    raise exception 'Limite de 1 a 2.000 anexos' using errcode = '22023';
  end if;
  -- O sal é sorteado pelo robô a cada execução: o hash do CPF não serve fora dela.
  if coalesce(p_sal, '') !~ '^[A-Za-z0-9_-]{16,128}$' then
    raise exception 'Sal inválido' using errcode = '22023';
  end if;
  if cardinality(v_pedidos) > 0 then
    -- Cada pedido é o id do edital, o número ("93/2026") ou, sem número, o nome.
    select coalesce(array_agg(distinct m.id), '{}') into v_ids
      from public."TB_MONITORAMENTO_INDIGENA" m
      join unnest(v_pedidos) p(texto)
        on m.id::text = lower(p.texto)
        or private."FC_NUMERO_EDITAL"(m.edital) = p.texto
        or lower(btrim(m.edital)) = lower(p.texto);
  else
    -- Sem pedido: os editais ativos (fora os de treinamento) com vagas da Empregare e regra.
    select coalesce(array_agg(distinct v."CO_MONITORAMENTO"), '{}') into v_ids
      from public."TB_EMPREGARE_VAGA" v
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = v."CO_MONITORAMENTO"
      join public."TB_REGRA_ANALISE" r on r."CO_MONITORAMENTO" = m.id
     where coalesce(m.ativo, false) and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO");
  end if;

  return (
    with anexos as (
      select a."CO_EMPREGARE_RESPOSTA" as resposta, a."CO_PERGUNTA_EMPREGARE" as pergunta, a."NU_ARQUIVO" as arquivo,
             a."NU_ORDEM" as ordem, a."DS_ENUNCIADO" as enunciado, a."DS_COLUNA" as coluna, a."DS_LINK" as link,
             v."CO_MONITORAMENTO" as edital, v."CO_VAGA" as vaga, c."CO_EMPREGARE_CANDIDATO" as candidato,
             c."NO_CANDIDATO" as nome,
             -- O CPF do cadastro ou, sem ele, a resposta à pergunta do CPF no Excel (só dígitos).
             coalesce(nullif(regexp_replace(coalesce(c."NU_CPF", ''), '\D', '', 'g'), ''),
                      (select regexp_replace(e.value #>> '{}', '\D', '', 'g')
                         from jsonb_each(c."DS_COLUNA_ORIGINAL") e
                        where e.key ~* 'cpf' and jsonb_typeof(e.value) = 'string'
                        order by e.key limit 1)) as cpf,
             exists (select 1 from public."TB_FICHA_ANALISE" f
                      where f."CO_MONITORAMENTO" = v."CO_MONITORAMENTO"
                        and f."CO_EMPREGARE_CANDIDATO" = c."CO_EMPREGARE_CANDIDATO") as com_ficha,
             l."TP_SITUACAO" as situacao, l."NU_VERSAO_EXTRATOR" as versao
        from public."TB_EMPREGARE_VAGA" v
        join public."TB_EMPREGARE_CANDIDATO" c on c."CO_VAGA" = v."CO_VAGA" and c."ST_REGISTRO_ATIVO" = 'S'
        join public."TB_EMPREGARE_ANEXO" a
          on a."CO_EMPREGARE_RESPOSTA" = private."FC_RESPOSTA_VIGENTE_EMPREGARE"(c."CO_EMPREGARE_CANDIDATO")
        left join public."TB_LEITURA_ARQUIVO" l
          on l."CO_EMPREGARE_RESPOSTA" = a."CO_EMPREGARE_RESPOSTA" and l."CO_PERGUNTA_EMPREGARE" = a."CO_PERGUNTA_EMPREGARE"
         and l."NU_ARQUIVO" = a."NU_ARQUIVO"
       where v."CO_MONITORAMENTO" = any (v_ids)
    ),
    pendentes as (
      select * from anexos
       where (coalesce(p_forcar, false) or situacao is null or versao <> p_versao or situacao = 'ERRO')
         -- Só relidos: o que já foi lido (com outra versão, com erro ou, com p_forcar, todos); nunca o novo.
         and (not coalesce(p_so_relidos, false) or situacao is not null)
    )
    select jsonb_build_object(
      'nao_encontrados', coalesce((
        select jsonb_agg(p.texto order by p.texto)
          from unnest(v_pedidos) p(texto)
         where not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m
                            where m.id::text = lower(p.texto)
                               or private."FC_NUMERO_EDITAL"(m.edital) = p.texto
                               or lower(btrim(m.edital)) = lower(p.texto))), '[]'::jsonb),
      'editais', coalesce((
        select jsonb_agg(jsonb_build_object('id', m.id, 'rotulo', private."FC_ROTULO_DO_EDITAL"(m.edital),
                                            'regra', private."FC_REGRA_COM_DATA_LIMITE"(h."DS_CONFIGURACAO", m.id)) order by m.id)
          from public."TB_MONITORAMENTO_INDIGENA" m
          left join public."TB_REGRA_ANALISE" r on r."CO_MONITORAMENTO" = m.id
          left join public."TH_REGRA_ANALISE" h on h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
         where m.id = any (v_ids)), '[]'::jsonb),
      'total', (select count(*) from anexos),
      'pendentes', (select count(*) from pendentes),
      -- Primeiro o já lido com extrator de outra versão (a releitura troca o dado antigo), depois quem
      -- tem ficha, o que nunca foi lido e, por último, erro.
      'anexos', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'resposta', x.resposta, 'pergunta', x.pergunta, 'arquivo', x.arquivo, 'ordem', x.ordem,
                 'enunciado', x.enunciado, 'coluna', x.coluna, 'link', x.link, 'edital', x.edital, 'vaga', x.vaga,
                 'candidato', x.candidato, 'com_ficha', x.com_ficha, 'nome', x.nome,
                 'cpf', case when length(coalesce(x.cpf, '')) between 9 and 11
                             then encode(sha256(convert_to(p_sal || lpad(x.cpf, 11, '0'), 'UTF8')), 'hex')
                        end)
               order by x.n)
          from (select pd.*, row_number() over (
                         order by coalesce(pd.situacao <> 'ERRO' and pd.versao <> p_versao, false) desc,
                                  pd.com_ficha desc, (pd.situacao is null) desc, (pd.situacao = 'ERRO'),
                                  pd.candidato, pd.ordem nulls last, pd.pergunta, pd.arquivo) as n
                  from pendentes pd) x
         where x.n <= p_limite), '[]'::jsonb)
    )
  );
end;
$_$;

--
-- Name: FUNCTION listar_anexos_para_leitura(p_editais text[], p_versao text, p_forcar boolean, p_limite integer, p_sal text, p_so_relidos boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_anexos_para_leitura(p_editais text[], p_versao text, p_forcar boolean, p_limite integer, p_sal text, p_so_relidos boolean) IS 'Para o robô da leitura dos arquivos (Python): os anexos da resposta vigente do questionário (FC_RESPOSTA_VIGENTE_EMPREGARE) dos inscritos ativos dos editais pedidos (id, número ou nome; sem pedido, os ativos com vagas da Empregare e regra) lidos com extrator de outra versão (primeiro: a releitura troca o dado antigo), ainda não lidos ou com erro (todos, com p_forcar), depois os de quem tem ficha; com p_so_relidos, só os já lidos (nunca um anexo novo); até p_limite. Cada anexo vem com o link, a pergunta, o nome do inscrito e o CPF (o do cadastro ou a resposta à pergunta do CPF) só como sha256(p_sal || 11 dígitos), para o robô conferir sem ver o número. Traz a regra vigente de cada edital (o robô liga a pergunta ao item da ficha). Só service_role.';

--
-- Name: listar_aprovados_da_api(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_aprovados_da_api() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '15s'
    AS $$
  select jsonb_build_object('linhas', coalesce((
    select jsonb_agg(jsonb_build_object(
        'edital_id', m.id,
        'edital', m.edital,
        'unidade', m.unidade,
        'area', a."NO_AREA",
        'cargo', c.cargo,
        'classificacao', c.classificacao,
        'nota', c.nota,
        'nome', c.nome,
        'modalidade', c.modalidade,
        'status', c.status,
        'matricula', c.matricula,
        'processo_sei', c.processo_sei,
        'codigo_vaga', c.codigo_vaga,
        'sub_judice', c.sub_judice
      ) order by m.unidade, m.edital, c.cargo, c.classificacao nulls last, c.nome)
      from public."TB_LISTA_APROVADO" l
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
      left join public."TB_AREA" a on a."CO_AREA" = m."CO_AREA"
      join public."TB_CANDIDATO_APROVADO" c on c.lista_id = l.id
     where l.vigente is true
       and m.ativo is true
       and c.removido_em is null), '[]'::jsonb));
$$;

--
-- Name: FUNCTION listar_aprovados_da_api(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_aprovados_da_api() IS 'API de aprovados para outro sistema (/api/aprovados, 20261105150000; área em 20261105190000): { linhas } com edital_id, edital, unidade, area, cargo, classificacao, nota, nome, modalidade, status, matricula, processo_sei, codigo_vaga e sub_judice da lista vigente de cada edital ativo (candidatos não removidos). area = TB_AREA.NO_AREA. Dados pessoais: só service_role.';

--
-- Name: listar_avisos_conferencia(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_avisos_conferencia(p_area text DEFAULT NULL::text, p_modulo text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := nullif(lower(btrim(coalesce(p_area, ''))), '');
  v_modulo text := nullif(lower(btrim(coalesce(p_modulo, ''))), '');
begin
  if auth.uid() is null then
    raise exception 'Sessão necessária' using errcode = '42501';
  end if;
  if v_area is not null and not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if v_modulo is not null and v_modulo not in ('analises', 'entrevistas', 'classificacao', 'aprovados', 'cargas') then
    raise exception 'Módulo inválido' using errcode = '22023';
  end if;

  return json_build_object(
    'schema_version', 1,
    'gerado_em', now(),
    'ultima_execucao', (
      select json_build_object('inicio', c."DT_INICIO", 'fim', c."DT_FIM", 'situacao', c."TP_SITUACAO")
        from public."TL_CONFERENCIA" c
       where c."TP_SITUACAO" <> 'EM_ANDAMENTO'
       order by c."DT_INICIO" desc
       limit 1
    ),
    'avisos', (
      select coalesce(json_agg(json_build_object(
          'id', a."CO_AVISO_CONFERENCIA",
          'conferencia', a."CO_CONFERENCIA",
          'escopo', a."DS_ESCOPO",
          'gravidade', a."TP_GRAVIDADE",
          'modulo', a."CO_MODULO",
          'area', a."CO_AREA",
          'edital_id', a."CO_MONITORAMENTO",
          'edital', m.edital,
          'quantidade', a."QT_OCORRENCIA",
          'exemplos', a."DS_EXEMPLO",
          'resumo', a."DS_RESUMO",
          'situacao', a."TP_SITUACAO",
          'primeira_vez', a."DT_PRIMEIRA_VEZ",
          'ultima_vez', a."DT_ULTIMA_VEZ",
          'ignorado_em', a."DT_IGNORADO",
          'motivo', a."DS_MOTIVO_IGNORADO",
          'pode_ignorar', a."TP_SITUACAO" = 'ABERTO'
                          and private."FC_PODE_IGNORAR_AVISO"(a."CO_MODULO", a."CO_AREA", a."CO_MONITORAMENTO")
        ) order by case a."TP_SITUACAO" when 'ABERTO' then 0 else 1 end,
                   case a."TP_GRAVIDADE" when 'CRITICA' then 0 when 'ATENCAO' then 1 else 2 end,
                   a."DT_PRIMEIRA_VEZ"), '[]'::json)
        from public."TB_AVISO_CONFERENCIA" a
        left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = a."CO_MONITORAMENTO"
       where a."TP_SITUACAO" in ('ABERTO', 'IGNORADO')
         and (v_area is null or a."CO_AREA" = v_area)
         and (v_modulo is null or a."CO_MODULO" = v_modulo)
         and private."FC_PODE_VER_AVISO"(a."CO_MODULO", a."CO_AREA", a."CO_MONITORAMENTO")
    )
  );
end;
$$;

--
-- Name: FUNCTION listar_avisos_conferencia(p_area text, p_modulo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_avisos_conferencia(p_area text, p_modulo text) IS 'Avisos de conferência abertos e ignorados (json) que quem chama pode ver: o módulo (leitor), a área e o edital no recorte; cargas e avisos sem área, só o administrador global. Filtra por área e módulo (opcionais). pode_ignorar diz se a pessoa pode ignorar cada aviso aberto.';

--
-- Name: listar_avisos_conferencia_se_mudou(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_avisos_conferencia_se_mudou(p_area text DEFAULT NULL::text, p_modulo text DEFAULT NULL::text, p_versao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_marca constant text := private."FC_MARCA_DA_RPC"('listar_avisos_conferencia', p_area => p_area, p_modulo => p_modulo);
begin
  if v_marca is null then
    return private."FC_SE_MUDOU"(private."FC_AVISOS_PARA_A_TELA"(public.listar_avisos_conferencia(p_area, p_modulo)::jsonb), p_versao);
  end if;
  if p_versao = v_marca then
    return jsonb_build_object('inalterado', true, 'versao', v_marca);
  end if;
  return private."FC_AVISOS_PARA_A_TELA"(public.listar_avisos_conferencia(p_area, p_modulo)::jsonb)
         || jsonb_build_object('versao', v_marca);
end;
$$;

--
-- Name: FUNCTION listar_avisos_conferencia_se_mudou(p_area text, p_modulo text, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_avisos_conferencia_se_mudou(p_area text, p_modulo text, p_versao text) IS 'listar_avisos_conferencia com versão, sem nulos e sem exemplos em aviso com casos (FC_AVISOS_PARA_A_TELA): a marca das fontes (FC_MARCA_DA_RPC) sai antes de montar; p_versao igual devolve só { inalterado, versao } (20261029170000).';

--
-- Name: listar_candidatos_aprovados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_candidatos_aprovados() RETURNS TABLE(candidato_id uuid, lista_id uuid, edital_id text, edital text, unidade text, cargo text, classificacao integer, nota numeric, nome text, modalidade text, status text, processo_sei text, matricula text, sub_judice boolean, lista_ativa boolean, arquivo_nome text, importado_em timestamp with time zone, codigo_vaga text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not (private.pode_recurso('aprovados',1)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if private.papel_recurso('aprovados') = '' then
    raise exception 'Perfil sem acesso ao sistema';
  end if;
  return query
  select c.id, l.id, l.edital_id, m.edital, m.unidade, c.cargo, c.classificacao,
         c.nota, c.nome, c.modalidade, c.status, c.processo_sei, c.matricula,
         c.sub_judice, l.ativo, l.arquivo_nome, l.importado_em, c.codigo_vaga
  from public."TB_LISTA_APROVADO" l
  join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
  join public."TB_CANDIDATO_APROVADO" c on c.lista_id = l.id
  where l.vigente is true
    and m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
      and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
    and c.removido_em is null
  order by m.edital, c.cargo, c.classificacao nulls last, c.nome;
end;
$$;

--
-- Name: listar_candidatos_aprovados_compacto(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_candidatos_aprovados_compacto(p_area text DEFAULT NULL::text, p_versao text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET work_mem TO '64MB'
    SET jit TO 'off'
    AS $$
declare
  v_listas json;
  v_linhas json;
  v_area text;
  v_visiveis uuid[];
  v_versao text;
  v_cache private."TA_CANDIDATO_APROVADO_AREA";
  v_tem_cache boolean := false;
  v_sujo boolean;
  v_dicionarios json;
  v_total integer;
  v_gerado_em timestamptz := now();
begin
  if not (private.pode_recurso('aprovados',1)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if private.papel_recurso('aprovados') = '' then
    raise exception 'Perfil sem acesso ao sistema';
  end if;

  -- Sem área: a resposta de antes (formato 1), para o front publicado até o deploy.
  if p_area is null then
    -- Dados da lista vão uma vez por lista (≈110), não repetidos em cada candidato.
    select coalesce(json_object_agg(l.id, json_build_array(
             l.edital_id, m.edital, m.unidade, l.ativo, l.arquivo_nome, l.importado_em
           )), '{}'::json)
      into v_listas
    from public."TB_LISTA_APROVADO" l
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
    where l.vigente is true
      and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
      and m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
        and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]));

    select coalesce(json_agg(
             case when c.alterado_judicialmente then json_build_array(
               c.id, l.id, c.cargo, c.classificacao, c.nota, c.nome, c.modalidade,
               c.status, c.processo_sei, c.matricula, c.sub_judice, c.codigo_vaga,
               true, c.nota_original, c.modalidade_original, c.classificacao_original
             ) else json_build_array(
               c.id, l.id, c.cargo, c.classificacao, c.nota, c.nome, c.modalidade,
               c.status, c.processo_sei, c.matricula, c.sub_judice, c.codigo_vaga
             ) end
           order by m.edital, c.cargo, c.classificacao nulls last, c.nome), '[]'::json)
      into v_linhas
    from public."TB_LISTA_APROVADO" l
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
    join public."TB_CANDIDATO_APROVADO" c on c.lista_id = l.id
    where l.vigente is true
      and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
      and m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
        and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
      and c.removido_em is null;

    return json_build_object(
      'colunas_da_lista', json_build_array(
        'edital_id', 'edital', 'unidade', 'lista_ativa', 'arquivo_nome', 'importado_em'
      ),
      'listas', v_listas,
      'colunas', json_build_array(
        'candidato_id', 'lista_id', 'cargo', 'classificacao', 'nota', 'nome',
        'modalidade', 'status', 'processo_sei', 'matricula', 'sub_judice',
        'codigo_vaga', 'alterado_judicialmente', 'nota_original',
        'modalidade_original', 'classificacao_original'
      ),
      'linhas', v_linhas,
      'total', json_array_length(v_linhas)
    );
  end if;

  -- Área válida e do usuário: 22023/42501 antes de qualquer leitura.
  v_area := lower(btrim(p_area));
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Área inválida: %', p_area using errcode = '22023';
  end if;
  if not (v_area = any ((select private."FC_AREAS_USUARIO"())::text[])) then
    raise exception 'Sem permissão para a lista de aprovados desta área' using errcode = '42501';
  end if;

  v_visiveis := private."FC_EDITAIS_VISIVEIS"();
  select * into v_cache from private."TA_CANDIDATO_APROVADO_AREA" c where c."CO_AREA" = v_area;
  v_tem_cache := found;
  v_sujo := private."FC_CACHE_DESATUALIZADO"('APROVADOS', v_area);

  -- Quem vê a área inteira e encontrou o pacote vencido (ou sem pacote) remonta e
  -- grava. Falhou a gravação (transação só de leitura, trava), monta na hora abaixo.
  if v_visiveis is null and (v_sujo or not v_tem_cache)
     and pg_try_advisory_xact_lock(hashtext('aprovados_area:' || v_area)::bigint) then
    perform public.atualizar_cache_aprovados(v_area);
    select * into v_cache from private."TA_CANDIDATO_APROVADO_AREA" c where c."CO_AREA" = v_area;
    v_tem_cache := found;
    v_sujo := private."FC_CACHE_DESATUALIZADO"('APROVADOS', v_area);
  end if;

  -- Versão: a do pacote; com mudança pendente, mais a contagem e a última marca
  -- (a cópia do navegador não vale); com recorte por coordenação, mais o recorte.
  v_versao := coalesce(v_cache."DS_VERSAO_DADOS", '0')
    || case when v_sujo then
         '+' || (select count(*)::text || '.' || max(t."CO_ALTERACAO_CACHE")::text
                   from private."TL_ALTERACAO_CACHE" t
                  where t."TP_CACHE" = 'APROVADOS' and t."CO_AREA" = v_area)
       else '' end
    || case when v_visiveis is null then ''
            else ':' || md5(array(select x from unnest(v_visiveis) x order by x)::text) end;

  if p_versao is not null and p_versao = v_versao then
    return json_build_object('formato', 2, 'area', v_area, 'versao', v_versao, 'inalterado', true);
  end if;

  if v_visiveis is null and v_tem_cache and not v_sujo then
    v_listas := v_cache."DS_LISTAS";
    v_dicionarios := v_cache."DS_DICIONARIOS";
    v_linhas := v_cache."DS_LINHAS";
    v_total := v_cache."QT_CANDIDATOS";
    v_gerado_em := v_cache."DT_GERACAO";
  else
    -- Com recorte, ou pacote ainda sem a mudança de agora: montada na hora.
    v_tem_cache := false;
    select m.p_listas, m.p_dicionarios, m.p_linhas, m.p_total
      into v_listas, v_dicionarios, v_linhas, v_total
      from private."FC_MONTAR_APROVADOS_AREA"(v_area, v_visiveis) m;
  end if;

  return json_build_object(
    'formato', 2,
    'area', v_area,
    'versao', v_versao,
    'inalterado', false,
    'cache', json_build_object('hit', v_tem_cache, 'gerado_em', v_gerado_em),
    'colunas_da_lista', json_build_array(
      'lista_id', 'edital_id', 'edital', 'unidade', 'lista_ativa', 'arquivo_nome', 'importado_em'
    ),
    'listas', v_listas,
    'colunas', json_build_array(
      'candidato_id', 'lista_id', 'cargo', 'classificacao', 'nota', 'nome',
      'modalidade', 'status', 'processo_sei', 'matricula', 'sub_judice',
      'codigo_vaga', 'alterado_judicialmente', 'nota_original',
      'modalidade_original', 'classificacao_original'
    ),
    'dicionarios', v_dicionarios,
    'linhas', v_linhas,
    'total', v_total
  );
end;
$$;

--
-- Name: FUNCTION listar_candidatos_aprovados_compacto(p_area text, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_candidatos_aprovados_compacto(p_area text, p_versao text) IS 'Candidatos vigentes das listas de aprovados numa chamada só. Com p_area: só a área (formato 2: dicionários + índices, pacote pronto para quem vê a área inteira, versão para a cópia do navegador; p_versao igual = inalterado). Sem p_area: formato 1, todas as áreas do usuário. Mesma permissão e recortes de listar_candidatos_aprovados.';

--
-- Name: listar_cargos(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_cargos(p_area text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;

  return jsonb_build_object(
    'cargos', coalesce((
      select jsonb_agg(jsonb_build_object(
               'codigo', c."CO_CARGO",
               'codigo_sip', c."CO_CARGO_SIP",
               'nome', c."NO_CARGO",
               'area', c."CO_AREA",
               'sintetico', c."ST_SINTETICO" = 'S',
               'ativo', c."ST_REGISTRO_ATIVO" = 'S',
               'apelidos', (select count(*) from public."TD_CARGO_APELIDO" a
                             where a."CO_CARGO" = c."CO_CARGO" and a."ST_REGISTRO_ATIVO" = 'S'
                               and a."ST_CONFIRMADO" = 'S'))
             order by c."CO_AREA", c."NO_CARGO")
        from public."TD_CARGO" c
       where (p_area is null or c."CO_AREA" = p_area)
         and (private.is_master() or private."FC_PODE_AREA"(c."CO_AREA"))), '[]'::jsonb),
    'apelidos_pendentes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', a."CO_CARGO_APELIDO",
               'area', a."CO_AREA",
               'grafia', a."DS_GRAFIA_NORMALIZADA",
               'codigo', a."CO_CARGO",
               'cargo', c."NO_CARGO",
               'origem', a."TP_ORIGEM",
               'regra', a."TP_REGRA",
               'confianca', a."VL_CONFIANCA",
               'criado_em', a."DT_CRIACAO")
             order by a."CO_AREA", a."VL_CONFIANCA" desc nulls last, a."DS_GRAFIA_NORMALIZADA")
        from public."TD_CARGO_APELIDO" a
        join public."TD_CARGO" c on c."CO_CARGO" = a."CO_CARGO"
       where a."ST_CONFIRMADO" = 'N' and a."ST_REGISTRO_ATIVO" = 'S'
         and (p_area is null or a."CO_AREA" = p_area)
         and (private.is_master() or private."FC_PODE_AREA"(a."CO_AREA"))), '[]'::jsonb));
end;
$$;

--
-- Name: FUNCTION listar_cargos(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_cargos(p_area text) IS 'Cargos oficiais (com o número de apelidos confirmados) e apelidos pendentes de confirmação, da área pedida ou de todas (nula), só das áreas que quem lê vê; o administrador global vê todas. Para a tela da fase 2. 20261104150000.';

--
-- Name: listar_cartas_do_candidato(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_cartas_do_candidato(p_candidato uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_edital uuid;
  v_data date;
begin
  if not private.pode_recurso('aprovados', 1) then
    raise exception 'Sem permissão para este recurso' using errcode = '42501';
  end if;
  select m.id, c."DT_CONVOCACAO" into v_edital, v_data
    from public."TB_CANDIDATO_APROVADO" c
    join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
   where c.id = p_candidato;
  if v_edital is null then
    raise exception 'Candidato não encontrado' using errcode = '22023';
  end if;
  if not private."FC_PODE_VER_EDITAL"(v_edital) then
    raise exception 'Sem permissão para editais desta área ou coordenação' using errcode = '42501';
  end if;

  return json_build_object(
    'data_convocacao', v_data,
    'cartas', coalesce((
      with recursive anteriores(id, nivel) as (
        select p_candidato, 0
        union all
        select c."CO_CANDIDATO_ANTERIOR", a.nivel + 1
          from anteriores a
          join public."TB_CANDIDATO_APROVADO" c on c.id = a.id
         where c."CO_CANDIDATO_ANTERIOR" is not null and a.nivel < 50
      )
      select json_agg(json_build_object(
               'carta_id', e."CO_CARTA_CONVOCACAO",
               'emitida_em', e."DT_EMISSAO",
               'usuario', coalesce(e."NO_USUARIO", e."DS_EMAIL_USUARIO"),
               'modelo', t."NO_MODELO",
               'versao', e."NU_VERSAO_MODELO",
               'agrupamento', e."TP_AGRUPAMENTO",
               'saida', e."TP_SAIDA",
               'data_limite', e."DT_LIMITE",
               'candidatos', e."QT_CANDIDATO",
               'status_na_emissao', r."DS_STATUS_ANTERIOR",
               'convocacao_marcada', r."DT_CONVOCACAO_MARCADA")
             order by e."DT_EMISSAO" desc)
        from public."RL_CARTA_CANDIDATO" r
        join public."TH_CARTA_CONVOCACAO" e on e."CO_CARTA_CONVOCACAO" = r."CO_CARTA_CONVOCACAO"
        join public."TH_MODELO_CARTA_CONVOCACAO" t
          on t."CO_MODELO_CARTA" = e."CO_MODELO_CARTA" and t."NU_VERSAO" = e."NU_VERSAO_MODELO"
       where r."CO_CANDIDATO_APROVADO" in (select a.id from anteriores a)
    ), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION listar_cartas_do_candidato(p_candidato uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_cartas_do_candidato(p_candidato uuid) IS 'As cartas de convocação emitidas para o candidato (também nas listas anteriores do edital, por CO_CANDIDATO_ANTERIOR), da mais recente: quando, quem, modelo e versão, saída, data limite, quantos receberam a mesma carta e se a convocação foi marcada por ela; e a data da convocação atual. Aprovados >= leitor e o recorte do edital.';

--
-- Name: listar_casos_aviso_conferencia(uuid, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_casos_aviso_conferencia(p_aviso uuid DEFAULT NULL::uuid, p_busca text DEFAULT NULL::text, p_area text DEFAULT NULL::text, p_modulo text DEFAULT NULL::text, p_limite integer DEFAULT 50, p_deslocamento integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '15s'
    AS $_$
declare
  v_area text := nullif(lower(btrim(coalesce(p_area, ''))), '');
  v_modulo text := nullif(lower(btrim(coalesce(p_modulo, ''))), '');
  v_busca text := nullif(private."FC_TEXTO_DE_BUSCA"(left(coalesce(p_busca, ''), 80)), '');
  v_limite integer := least(greatest(coalesce(p_limite, 50), 1), 1000);
  v_deslocamento integer := greatest(coalesce(p_deslocamento, 0), 0);
  v_total integer;
  v_casos json;
begin
  if auth.uid() is null then
    raise exception 'Sessão necessária' using errcode = '42501';
  end if;
  if v_area is not null and not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if v_modulo is not null and v_modulo not in ('analises', 'entrevistas', 'classificacao', 'aprovados', 'cargas') then
    raise exception 'Módulo inválido' using errcode = '22023';
  end if;
  if p_aviso is null and v_busca is null then
    raise exception 'Informe o aviso ou o que buscar' using errcode = '22023';
  end if;
  if p_aviso is not null and not exists (
       select 1 from public."TB_AVISO_CONFERENCIA" a
        where a."CO_AVISO_CONFERENCIA" = p_aviso
          and a."TP_SITUACAO" in ('ABERTO', 'IGNORADO')
          and private."FC_PODE_VER_AVISO"(a."CO_MODULO", a."CO_AREA", a."CO_MONITORAMENTO")) then
    raise exception 'Aviso não encontrado' using errcode = '22023';
  end if;

  with avisos as (
    select a."CO_AVISO_CONFERENCIA" as id, a."CO_CONFERENCIA" as conferencia, a."CO_MODULO" as modulo,
           a."CO_AREA" as area, a."CO_MONITORAMENTO" as edital
      from public."TB_AVISO_CONFERENCIA" a
     where a."TP_SITUACAO" in ('ABERTO', 'IGNORADO')
       and (p_aviso is null or a."CO_AVISO_CONFERENCIA" = p_aviso)
       and (v_area is null or a."CO_AREA" = v_area)
       and (v_modulo is null or a."CO_MODULO" = v_modulo)
       and private."FC_PODE_VER_AVISO"(a."CO_MODULO", a."CO_AREA", a."CO_MONITORAMENTO")
  ),
  casos as materialized (
    select av.id as aviso, av.conferencia, k."NU_CASO" as ordem,
           k."CO_ANALISE_CURRICULAR" as analise_do_caso, k."CO_CANDIDATO_EMPREGARE" as codigo_do_caso,
           k."DS_REFERENCIA" as referencia_do_caso, k."DS_DETALHE" as detalhe,
           an.id as an_id, nullif(btrim(an.id_origem), '') as an_codigo, an.candidato as an_nome,
           an.edital as an_edital, an.codigo_vaga as an_codigo_vaga, an.nome_vaga as an_nome_vaga,
           an.responsavel_analise, an.status_consolidado as an_status, an.data_analise,
           private."FC_REFERENCIA_DO_CASO"(av.modulo, av.conferencia, k."TP_REFERENCIA", k."DS_REFERENCIA",
                                           k."CO_ANALISE_CURRICULAR", av.area, av.edital) as r
      from avisos av
      join public."TB_CASO_AVISO_CONFERENCIA" k on k."CO_AVISO_CONFERENCIA" = av.id
      left join lateral (
        (select x.id, x.id_origem, x.candidato, x.edital, x.codigo_vaga, x.nome_vaga,
                x.responsavel_analise, x.status_consolidado, x.data_analise
           from public."TB_ANALISE_CURRICULAR" x
          where x.id = k."CO_ANALISE_CURRICULAR"
            and private."FC_PODE_VER_ANALISE_DO_AVISO"(x."CO_AREA", x.edital_norm, x.unidade_norm))
        union all
        (select x.id, x.id_origem, x.candidato, x.edital, x.codigo_vaga, x.nome_vaga,
                x.responsavel_analise, x.status_consolidado, x.data_analise
           from public."TB_ANALISE_CURRICULAR" x
          where k."CO_ANALISE_CURRICULAR" is null
            and x.ativo is true
            and x.id_origem = k."CO_CANDIDATO_EMPREGARE"
            and private."FC_PODE_VER_ANALISE_DO_AVISO"(x."CO_AREA", x.edital_norm, x.unidade_norm)
          order by x.edital, x.id
          limit 1)
        limit 1
      ) an on true
  ),
  resolvidos as materialized (
    select c.*,
           coalesce(c.an_nome, c.r ->> 'nome') as nome,
           coalesce(c.codigo_do_caso, c.an_codigo, c.r ->> 'codigo') as codigo,
           coalesce(c.an_edital, c.r ->> 'edital') as edital,
           coalesce(c.an_codigo_vaga, c.r ->> 'codigo_vaga') as codigo_vaga,
           coalesce(c.an_nome_vaga, c.r ->> 'nome_vaga') as nome_vaga,
           coalesce(c.r ->> 'status', c.an_status) as status,
           c.r ->> 'tipo' as tipo,
           case
             when c.an_id is not null or c.r ->> 'resolucao' = 'ok' then 'ok'
             when c.r ? 'resolucao' then c.r ->> 'resolucao'
             when c.analise_do_caso is not null then
               case when exists (select 1 from public."TB_ANALISE_CURRICULAR" x where x.id = c.analise_do_caso)
                    then 'sem_acesso' else 'removido' end
             when c.codigo_do_caso is not null then
               case when exists (select 1 from public."TB_ANALISE_CURRICULAR" x
                                  where x.ativo is true and x.id_origem = c.codigo_do_caso)
                    then 'sem_acesso' else 'removido' end
             when c.referencia_do_caso ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then 'removido'
             else 'ok'
           end as resolucao,
           -- A referência só sai quando é um código (vaga, lista do job antigo), nunca um UUID.
           case when c.referencia_do_caso ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                then null else c.referencia_do_caso end as referencia,
           case when c.r ->> 'tipo' = 'candidato_aprovado'
                 and c.referencia_do_caso ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                then c.referencia_do_caso::uuid end as aprovado_do_caso
      from casos c
  ),
  filtrados as (
    select f.* from resolvidos f
     where v_busca is null
        or private."FC_TEXTO_DE_BUSCA"(coalesce(f.codigo, '')) like '%' || v_busca || '%'
        or private."FC_TEXTO_DE_BUSCA"(coalesce(f.referencia, '')) like '%' || v_busca || '%'
        or private."FC_TEXTO_DE_BUSCA"(coalesce(f.nome, '')) like '%' || v_busca || '%'
        or private."FC_TEXTO_DE_BUSCA"(coalesce(f.codigo_vaga, '')) like '%' || v_busca || '%'
        or private."FC_TEXTO_DE_BUSCA"(coalesce(f.nome_vaga, '')) like '%' || v_busca || '%'
  ),
  numerados as (
    select f.*,
           row_number() over (order by f.nome is null, private."FC_TEXTO_DE_BUSCA"(f.nome),
                                       f.codigo, f.codigo_vaga, f.conferencia, f.ordem) as posicao,
           count(*) over () as total
      from filtrados f
  ),
  pagina as materialized (
    select n.*,
           case when n.aprovado_do_caso is not null
                then private."FC_VINCULOS_DO_APROVADO"(n.aprovado_do_caso) end as vinculos
      from numerados n
     where n.posicao > v_deslocamento and n.posicao <= v_deslocamento + v_limite
  )
  select (select max(n.total) from numerados n)::integer,
         json_agg(json_build_object(
           'aviso_id', p.aviso,
           'conferencia', p.conferencia,
           'ordem', p.ordem,
           'tipo', p.tipo,
           'resolucao', p.resolucao,
           'analise_id', coalesce(p.an_id::text, p.r ->> 'analise_id'),
           'aprovado_id', p.r ->> 'aprovado_id',
           'entrevista_id', p.r ->> 'entrevista_id',
           'edital_id', p.r ->> 'edital_id',
           'codigo', p.codigo,
           'nome', p.nome,
           'edital', p.edital,
           'codigo_vaga', p.codigo_vaga,
           'nome_vaga', p.nome_vaga,
           'responsavel', p.responsavel_analise,
           'status', p.status,
           'data_analise', p.data_analise,
           'nota', p.r -> 'nota',
           'compareceu', p.r ->> 'compareceu',
           'data_convocacao', p.r ->> 'data_convocacao',
           'data_contratacao', p.r ->> 'data_contratacao',
           'candidatos', p.r -> 'candidatos',
           'lista', p.r -> 'lista',
           'referencia', p.referencia,
           'detalhe', p.detalhe,
           'vinculos', p.vinculos -> 'vinculos',
           'analises', case when p.analise_do_caso is null and p.codigo_do_caso is not null then (
             select coalesce(json_agg(json_build_object(
                      'id', x.id, 'edital', x.edital, 'codigo_vaga', x.codigo_vaga, 'nome_vaga', x.nome_vaga,
                      'status', x.status_consolidado, 'responsavel', x.responsavel_analise,
                      'data_analise', x.data_analise) order by x.edital, x.codigo_vaga, x.id), '[]'::json)
               from public."TB_ANALISE_CURRICULAR" x
              where x.ativo is true and x.id_origem = p.codigo_do_caso
                and private."FC_PODE_VER_ANALISE_DO_AVISO"(x."CO_AREA", x.edital_norm, x.unidade_norm)) end,
           'fora_do_acesso', case
             when p.analise_do_caso is null and p.codigo_do_caso is not null then (
               select count(*)::integer
                 from public."TB_ANALISE_CURRICULAR" x
                where x.ativo is true and x.id_origem = p.codigo_do_caso
                  and not private."FC_PODE_VER_ANALISE_DO_AVISO"(x."CO_AREA", x.edital_norm, x.unidade_norm))
             when p.vinculos is not null then (p.vinculos ->> 'fora')::integer end
         ) order by p.posicao)
    into v_total, v_casos
    from pagina p;

  return json_build_object(
    'schema_version', 2,
    'total', coalesce(v_total, 0),
    'limite', v_limite,
    'deslocamento', v_deslocamento,
    'casos', coalesce(v_casos, '[]'::json));
end;
$_$;

--
-- Name: FUNCTION listar_casos_aviso_conferencia(p_aviso uuid, p_busca text, p_area text, p_modulo text, p_limite integer, p_deslocamento integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_casos_aviso_conferencia(p_aviso uuid, p_busca text, p_area text, p_modulo text, p_limite integer, p_deslocamento integer) IS 'Casos (json, em páginas de até 1000) de um aviso de conferência, ou de todos os avisos abertos e ignorados que quem chama vê (área e módulo opcionais; exige p_busca). Busca por código do candidato, nome, código ou nome da vaga e referência (sem acento e sem caixa). Cada caso: tipo e resolução (ok, removido, sem_acesso), código, nome, edital, vaga, situação e datas — da análise (área e recorte de quem lê) ou do registro do módulo (aprovado, entrevista, lista, ajuste, vaga) com a permissão daquele módulo —, o detalhe que motivou o aviso, as análises do candidato em dois editais e as vagas da pessoa nas listas de aprovados (com quantas ficaram fora do acesso). A referência só sai quando não é UUID. Sem CPF.';

--
-- Name: listar_configuracao_convocacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_configuracao_convocacao() RETURNS TABLE(edital_id text, proporcionalidade boolean, modelo_id uuid, padrao_imediata integer, vagas jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not ((private.pode_recurso('aprovados') or private.pode_recurso('importacao',2))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if private.monitora_role() = '' then
    raise exception 'Perfil sem acesso ao sistema';
  end if;
  return query
  select c."CO_EDITAL",
         c."TP_CONVOCACAO" = 'COM_PROPORCIONALIDADE',
         c."CO_MODELO",
         c."QT_PADRAO_IMEDIATA",
         coalesce(
           (
             select jsonb_agg(
               jsonb_build_object(
                 'codigo_vaga', v."CO_VAGA",
                 'cargo', v."NO_CARGO",
                 'imediatas', v."QT_VAGA_IMEDIATA",
                 'manual', v."ST_QUADRO_MANUAL" = 'S',
                 'quadro', v."DS_QUADRO_MANUAL"
               )
               order by v."CO_VAGA"
             )
             from public."TB_VAGA_IMEDIATA" v
             where v."CO_EDITAL" = c."CO_EDITAL"
           ),
           '[]'::jsonb
         )
  from public."TB_CONVOCACAO_EDITAL" c
  where c."CO_EDITAL" in (
    select m.id::text from public."TB_MONITORAMENTO_INDIGENA" m
     where m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
      and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
  )
  order by c."CO_EDITAL";
end;
$$;

--
-- Name: listar_contas_desativadas(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_contas_desativadas(p_busca text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_busca text := left(coalesce(p_busca, ''), 100);
begin
  if not private.is_master() then
    raise exception 'Somente o administrador global vê as contas desativadas' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'contas', coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', u.id, 'email', u.email, 'nome', u.nome,
          'grupo', u.perfil,
          'grupo_nome', (select g."NO_GRUPO_ACESSO" from public."TB_GRUPO_ACESSO" g where g."CO_GRUPO_ACESSO" = u.perfil),
          'coordenacao', u."CO_COORDENACAO",
          'areas', coalesce((select jsonb_agg(r."CO_AREA" order by r."CO_AREA")
                               from public."RL_PERFIL_USUARIO_AREA" r where r."CO_PERFIL_USUARIO" = u.id), '[]'::jsonb),
          'desativada_em', coalesce(h.alterado_em, u.updated_at),
          'desativada_por', h.autor,
          'motivo', h.motivo,
          'pedido_pendente', exists (
            select 1 from public."TB_SOLICITACAO_ACESSO" s
             where s.status = 'pendente'
               and ((u.user_id is not null and s.user_id = u.user_id) or lower(s.email) = lower(u.email))),
          'ultimo_acesso', private."FC_ULTIMO_ACESSO"(u.user_id, u.email)
        ) order by coalesce(h.alterado_em, u.updated_at) desc)
        from public."TB_PERFIL_USUARIO" u
        left join lateral (
          select t.alterado_em, t.motivo,
                 (select a.email from public."TB_PERFIL_USUARIO" a where a.user_id = t.alterado_por limit 1) autor
            from public."TH_PERMISSAO_RECURSO" t
           where t.perfil_usuario_id = u.id and t.recurso = '#conta'
           order by t.alterado_em desc limit 1) h on true
       where not u.ativo
         and (coalesce(u.nome, '') ilike '%' || v_busca || '%' or u.email ilike '%' || v_busca || '%')
    ), '[]'::jsonb)
  );
end;
$$;

--
-- Name: FUNCTION listar_contas_desativadas(p_busca text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_contas_desativadas(p_busca text) IS 'Aba Desativadas de Acessos (só administrador global): quando, por quem e por que cada conta foi desativada, grupo/coordenação/áreas de antes, se há pedido de reativação pendente e o último acesso real (private."FC_ULTIMO_ACESSO").';

--
-- Name: listar_convocacoes_aprovados(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_convocacoes_aprovados(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := lower(btrim(coalesce(p_area, '')));
begin
  if not private.pode_recurso('aprovados', 1) then
    raise exception 'Sem permissão para este recurso' using errcode = '42501';
  end if;
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Área inválida: %', p_area using errcode = '22023';
  end if;
  if not (v_area = any ((select private."FC_AREAS_USUARIO"())::text[])) then
    raise exception 'Sem permissão para a lista de aprovados desta área' using errcode = '42501';
  end if;

  return coalesce((
    with recursive herdeiros(origem, atual, nivel) as (
      select distinct r."CO_CANDIDATO_APROVADO", r."CO_CANDIDATO_APROVADO", 0
        from public."RL_CARTA_CANDIDATO" r
      union all
      select h.origem, c.id, h.nivel + 1
        from herdeiros h
        join public."TB_CANDIDATO_APROVADO" c on c."CO_CANDIDATO_ANTERIOR" = h.atual
       where h.nivel < 50
    ),
    cartas as (
      select h.atual as candidato, count(distinct r."CO_CARTA_CONVOCACAO") as qt, max(e."DT_EMISSAO") as ultima
        from herdeiros h
        join public."RL_CARTA_CANDIDATO" r on r."CO_CANDIDATO_APROVADO" = h.origem
        join public."TH_CARTA_CONVOCACAO" e on e."CO_CARTA_CONVOCACAO" = r."CO_CARTA_CONVOCACAO"
       group by h.atual
    ),
    vivos as (
      select c.id, c."DT_CONVOCACAO"
        from public."TB_CANDIDATO_APROVADO" c
        join public."TB_LISTA_APROVADO" l on l.id = c.lista_id and l.vigente is true
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
       where m."CO_AREA" = v_area and c.removido_em is null
         and (c."DT_CONVOCACAO" is not null or c.id in (select k.candidato from cartas k))
         and ((select private."FC_EDITAIS_VISIVEIS"()) is null
              or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
    )
    select json_agg(json_build_object(
             'candidato_id', v.id, 'data_convocacao', v."DT_CONVOCACAO",
             'cartas', coalesce(k.qt, 0), 'ultima_carta', k.ultima))
      from vivos v
      left join cartas k on k.candidato = v.id
  ), '[]'::json);
end;
$$;

--
-- Name: FUNCTION listar_convocacoes_aprovados(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_convocacoes_aprovados(p_area text) IS 'Os candidatos das listas vigentes da área com data da convocação ou carta emitida (também nas listas anteriores): candidato_id, data_convocacao, quantas cartas e a última emissão. Aprovados >= leitor, a área do usuário e o recorte da coordenação.';

--
-- Name: listar_cronograma_da_api(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_cronograma_da_api() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '15s'
    AS $$
  select jsonb_build_object('linhas', coalesce((
    select jsonb_agg(jsonb_build_object(
        'edital_id', m.id,
        'edital', m.edital,
        'unidade', m.unidade,
        'area', a."NO_AREA",
        'ordem', c.ordem,
        'atividade', c.atividade,
        'data_inicio', c.data_inicio,
        'data_fim', c.data_fim
      ) order by m.unidade, m.edital, c.ordem)
      from public."TB_CRONOGRAMA_MONIT_INDIG" c
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = c.monitoramento_id
      left join public."TB_AREA" a on a."CO_AREA" = m."CO_AREA"
     where m.ativo is true), '[]'::jsonb));
$$;

--
-- Name: FUNCTION listar_cronograma_da_api(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_cronograma_da_api() IS 'API de cronograma para outro sistema (/api/cronograma, 20261105150000; área em 20261105190000): { linhas } com edital_id, edital, unidade, area, ordem, atividade, data_inicio e data_fim das etapas de cada edital ativo. area = TB_AREA.NO_AREA. Só service_role.';

--
-- Name: listar_demandas_internas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_demandas_internas() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;

  return jsonb_build_object(
    'pode_criar_em', coalesce((
      select jsonb_agg(a."CO_AREA" order by a."NU_ORDEM")
        from public."TB_AREA" a
       where private."FC_PODE_EDITAR_CRONOGRAMA_AREA"(a."CO_AREA")), '[]'::jsonb),
    'demandas', coalesce((
      select jsonb_agg(
               private."FC_DEMANDA_INTERNA_JSON"(d."CO_DEMANDA_INTERNA")
               || jsonb_build_object('pode_editar',
                    private."FC_PODE_EDITAR_DEMANDA"(d."CO_AREA", d."CO_MONITORAMENTO"))
             order by d."DT_INICIO", d."NO_DEMANDA")
        from public."TB_DEMANDA_INTERNA" d
       where d."ST_ATIVO" = 'S'
         and private."FC_PODE_VER_DEMANDA"(d."CO_AREA", d."CO_MONITORAMENTO")), '[]'::jsonb));
end;
$$;

--
-- Name: FUNCTION listar_demandas_internas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_demandas_internas() IS 'Demandas internas ativas que quem lê vê, com responsáveis e pode_editar, e as áreas onde pode criar (pode_criar_em). Tela Cronograma. 20261104120000.';

--
-- Name: listar_editais_avaliacao(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_editais_avaliacao(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_editais uuid[];
begin
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if not private.pode_recurso('avaliacao_documental', 1) then
    raise exception 'Sem permissão para a Avaliação documental' using errcode = '42501';
  end if;
  if not private."FC_PODE_AREA"(p_area) then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;
  v_editais := (select private."FC_EDITAIS_VISIVEIS"())::uuid[];

  return json_build_object(
    'area', p_area,
    'nivel', private.nivel_recurso('avaliacao_documental'),
    'editais', coalesce((
      select json_agg(json_build_object(
               'id', m.id, 'edital', m.edital, 'unidade', m.unidade, 'ativo', m.ativo, 'status', m.status,
               'treinamento', private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO"),
               'numero', private."FC_NUMERO_EDITAL"(m.edital),
               'versao_regra', r."NU_VERSAO_VIGENTE", 'nome_regra', h."NO_VERSAO", 'situacao_regra', r."TP_SITUACAO",
               'origem', coalesce(o."TP_ORIGEM", 'PLANILHA'),
               'papel', private."FC_PAPEL_AVALIACAO"(m.id),
               -- Andamento das fichas do lote (fora do lote não conta); nulo sem fichas.
               'fichas', case when fx.total > 0 then json_build_object(
                 'concluidas', fx.concluidas, 'pendentes', fx.pendentes, 'em_analise', fx.em_analise,
                 'minhas_em_analise', fx.minhas_em_analise) end)
             order by m.ativo desc, r."NU_VERSAO_VIGENTE" is null, m.edital)
        from public."TB_MONITORAMENTO_INDIGENA" m
        left join public."TB_REGRA_ANALISE" r on r."CO_MONITORAMENTO" = m.id
        left join public."TH_REGRA_ANALISE" h
          on h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
        left join public."TB_ORIGEM_ANALISE_EDITAL" o on o."CO_MONITORAMENTO" = m.id
        -- IN_FICHAANALISE_FILA (CO_MONITORAMENTO, TP_SITUACAO, CO_VAGA): as contagens
        -- saem do índice; as minhas leem só as EM_ANALISE do edital.
        cross join lateral (
          select count(*) as total,
                 count(*) filter (where f."TP_SITUACAO" = 'CONCLUIDA') as concluidas,
                 count(*) filter (where f."TP_SITUACAO" in ('PENDENTE', 'REVISAR')) as pendentes,
                 count(*) filter (where f."TP_SITUACAO" = 'EM_ANALISE') as em_analise,
                 (select count(*) from public."TB_FICHA_ANALISE" g
                   where g."CO_MONITORAMENTO" = m.id and g."TP_SITUACAO" = 'EM_ANALISE'
                     and g."CO_USUARIO_RESPONSAVEL" = (select auth.uid())) as minhas_em_analise
            from public."TB_FICHA_ANALISE" f
           where f."CO_MONITORAMENTO" = m.id
             and f."TP_SITUACAO" in ('PENDENTE', 'EM_ANALISE', 'REVISAR', 'CONCLUIDA')) fx
       where m."CO_AREA" = p_area and (v_editais is null or m.id = any (v_editais))), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION listar_editais_avaliacao(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_editais_avaliacao(p_area text) IS 'Editais da área para a Avaliação documental (json): status do edital (a tela mostra só os vigentes, src/lib/avaliacao-documental/editais.js), treinamento, versão, nome da versão e situação da regra, dono da avaliação (PLANILHA, COMPARACAO, MONITORA) e o papel de quem está logado. Desde 20261016130000, fichas = {concluidas, pendentes (PENDENTE e REVISAR), em_analise, minhas_em_analise (EM_ANALISE com responsável = quem está logado)} das fichas do lote (FORA_LOTE não conta; nulo sem fichas). Exige avaliacao_documental >= leitor, a área e o recorte da coordenação.';

--
-- Name: listar_editais_classificacao(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_editais_classificacao(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_editais uuid[];
begin
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if not private.pode_recurso('classificacao', 1) then
    raise exception 'Sem permissão para Classificação' using errcode = '42501';
  end if;
  if not private."FC_PODE_AREA"(p_area) then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;
  v_editais := (select private."FC_EDITAIS_VISIVEIS"())::uuid[];

  return json_build_object(
    'area', p_area,
    'pode_editar', private.pode_recurso('classificacao', 2),
    'editais', (
      with m as (
        select m.id, m.edital, m.unidade, m.ativo, private."FC_NUMERO_EDITAL"(m.edital) as numero,
               private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO") as treinamento,
               coalesce(m.status, '') in ('Concluído', 'Cancelado') as encerrado
          from public."TB_MONITORAMENTO_INDIGENA" m
         where m."CO_AREA" = p_area and (v_editais is null or m.id = any (v_editais))
      ),
      an as (
        select private."FC_NUMERO_EDITAL"(a.edital) as numero, count(*)::integer as qt
          from public."TB_ANALISE_CURRICULAR" a
         where a."CO_AREA" = p_area and a.ativo
         group by 1
      ),
      ul as (
        select distinct on (l."CO_MONITORAMENTO") l."CO_MONITORAMENTO" as id,
               json_build_object('tipo', l."TP_LISTA", 'em', l."DT_GERACAO", 'publicada', l."ST_PUBLICADA" = 'S') as lista
          from public."TB_LISTA_CLASSIFICACAO" l
         where l."CO_MONITORAMENTO" in (select m.id from m)
         order by l."CO_MONITORAMENTO", l."DT_GERACAO" desc
      )
      select coalesce(json_agg(json_build_object(
               'id', m.id, 'edital', m.edital, 'unidade', m.unidade, 'ativo', m.ativo,
               'treinamento', m.treinamento,
               'candidatos', coalesce(an.qt, 0),
               'versao_regra', r."NU_VERSAO_VIGENTE",
               'nome_regra', h."NO_VERSAO",
               'ultima_lista', ul.lista)
             order by m.ativo desc, m.treinamento, m.encerrado, m.edital), '[]'::json)
        from m
        left join an on an.numero = m.numero
        left join ul on ul.id = m.id
        left join public."TB_REGRA_CLASSIFICACAO" r on r."CO_MONITORAMENTO" = m.id
        left join public."TH_REGRA_CLASSIFICACAO" h
          on h."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
       where coalesce(an.qt, 0) > 0 or ul.id is not null
    )
  );
end;
$$;

--
-- Name: FUNCTION listar_editais_classificacao(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_editais_classificacao(p_area text) IS 'Editais da área para a aba Classificação (json): só os que têm análise curricular ativa (qualquer origem) ou lista de classificação gerada; candidatos nas análises, treinamento, versão e nome da versão da regra e a última lista gerada. Ordem: ativo, fora do treinamento, em andamento antes de encerrado, número. Exige classificacao >= leitor, a área e o recorte da coordenação (20261023120000).';

--
-- Name: listar_editais_da_api(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_editais_da_api() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '15s'
    AS $$
  select jsonb_build_object('linhas', coalesce((
    select jsonb_agg(jsonb_build_object(
        'id', m.id,
        'unidade', m.unidade,
        'area', a."NO_AREA",
        'edital', m.edital,
        'status', coalesce(e.estado ->> 'status', m.status, ''),
        'etapa', coalesce(e.estado ->> 'etapa', m.etapa, ''),
        'vagas_total', m.vagas_total,
        'contratados', m.contratados,
        'vagas_ociosas', m.vagas_ociosas,
        'risco', m.risco,
        'link_edital', m.link_edital
      ) order by m.unidade, m.edital)
      from public."TB_MONITORAMENTO_INDIGENA" m
      left join public."TB_AREA" a on a."CO_AREA" = m."CO_AREA"
     cross join lateral private."FC_ESTADO_DO_CRONOGRAMA"(m.id, ((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date) e(estado)
     where m.ativo is true), '[]'::jsonb));
$$;

--
-- Name: FUNCTION listar_editais_da_api(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_editais_da_api() IS 'API de editais para outro sistema (/api/editais, 20261105170000; área em 20261105190000): { linhas } com id, unidade, area, edital, status, etapa, vagas_total, contratados, vagas_ociosas, risco e link_edital dos editais ativos (todas as áreas). status e etapa como na VW_MONITORAMENTO_INDIGENA_OPERACIONAL (estado do cronograma no dia de Brasília). area = TB_AREA.NO_AREA (Saúde Indígena, SEDE, Projetos). Só service_role.';

--
-- Name: listar_editais_entrevista(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_editais_entrevista(p_area text, p_todos boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_editais uuid[];
  v_admin boolean := private.is_master();
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if not private.pode_recurso('entrevistas', 1) then
    raise exception 'Sem permissão para Entrevistas' using errcode = '42501';
  end if;
  if not private."FC_PODE_AREA"(p_area) then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;
  v_editais := (select private."FC_EDITAIS_VISIVEIS"())::uuid[];
  return json_build_object(
    'admin_global', v_admin,
    'hoje', v_hoje,
    'editais', coalesce((
      select json_agg(json_build_object(
          'id', x.id, 'edital', x.edital, 'unidade', x.unidade, 'treinamento', x.treinamento,
          'configurado', x.configurado, 'convocados', x.convocados, 'pendentes', x.pendentes,
          'janela_inicio', x.inicio, 'janela_fim', x.fim, 'na_janela', x.na_janela,
          'liberado_ate', x.liberado_ate, 'motivo_liberacao', x.motivo,
          'visivel_por', case when x.na_janela then 'janela' when x.liberado_ate is not null then 'liberado'
                              when x.pendentes > 0 then 'convocados' else 'admin' end)
          order by x.edital)
        from (
          select m.id, m.edital, m.unidade, private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO") as treinamento, j.inicio, j.fim,
                 coalesce(v_hoje between j.inicio and j.fim, false) na_janela,
                 exists (select 1 from public."TB_ENTREVISTA_EDITAL" c where c."CO_MONITORAMENTO" = m.id) configurado,
                 (select count(*) from public."TB_ENTREVISTA" e
                   where e."CO_MONITORAMENTO" = m.id and e."TP_ORIGEM" = 'sistema' and e."ST_ATIVO" = 'S') convocados,
                 (select count(*) from public."TB_ENTREVISTA" e
                   where e."CO_MONITORAMENTO" = m.id and e."TP_ORIGEM" = 'sistema' and e."ST_ATIVO" = 'S'
                     and e."TP_PARECER" = 'SEM_PARECER') pendentes,
                 l."DT_LIBERADO_ATE" liberado_ate, l."DS_MOTIVO" motivo
            from public."TB_MONITORAMENTO_INDIGENA" m
            cross join lateral private."FC_JANELA_ENTREVISTA"(m.id) j
            left join public."TB_ENTREVISTA_LIBERACAO" l
              on l."CO_MONITORAMENTO" = m.id and l."ST_REGISTRO_ATIVO" = 'S' and l."DT_LIBERADO_ATE" >= v_hoje
           where m."CO_AREA" = p_area and m.ativo
             and (v_editais is null or m.id = any (v_editais))
        ) x
       where (p_todos and v_admin) or x.na_janela or x.liberado_ate is not null or x.pendentes > 0), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION listar_editais_entrevista(p_area text, p_todos boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_editais_entrevista(p_area text, p_todos boolean) IS 'Editais da área (recorte da coordenação) para conduzir entrevistas: na janela do cronograma, liberados pelo administrador global ou com convocado sem parecer; p_todos (só administrador global) traz todos. entrevistas >= leitor.';

--
-- Name: listar_eliminados_fila(uuid, text, text, text, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_eliminados_fila(p_edital uuid, p_vaga text DEFAULT NULL::text, p_modalidade text DEFAULT NULL::text, p_busca text DEFAULT NULL::text, p_ordem text DEFAULT NULL::text, p_sentido text DEFAULT 'asc'::text, p_apos jsonb DEFAULT NULL::jsonb, p_limite integer DEFAULT 50) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
  v_papel text := private."FC_PAPEL_AVALIACAO"(p_edital);
  v_uid uuid := (select auth.uid());
  v_ordem text := lower(coalesce(p_ordem, ''));
  v_desc boolean := lower(coalesce(p_sentido, 'asc')) = 'desc';
  v_busca text := nullif(btrim(private."FC_TEXTO_DE_BUSCA"(p_busca)), '');
  v_limite integer := least(greatest(coalesce(p_limite, 50), 1), 2000);
  v_vagas text[];
  v_ids uuid[];
  v_linhas json;
  v_ultimo jsonb;
  v_n integer;
  v_total integer;
begin
  if v_ordem not in ('', 'codigo', 'nome', 'vaga', 'motivo', 'art') then
    raise exception 'Ordem inválida: %', p_ordem using errcode = '22023';
  end if;
  if coalesce(v_papel, '') = 'ANALISTA' then
    v_vagas := private."FC_VAGAS_DO_ANALISTA"(p_edital, v_uid);
  end if;

  -- Uma consulta só (função STABLE, sem tabela temporária), montada com o sentido da ordem:
  -- o recorte é lido uma vez e dele saem o total e a página (cursor: chave, código, id).
  execute format($sql$
    with recorte as materialized (
      select a."CO_EMPREGARE_CANDIDATO" as id,
             -- A chave da ordem, em texto comparável (números com zeros à esquerda).
             (case $1
                when 'codigo' then ''
                when 'nome' then private."FC_TEXTO_DE_BUSCA"(c."NO_CANDIDATO")
                when 'motivo' then private."FC_TEXTO_DE_BUSCA"(a."DS_MOTIVO_ELIMINACAO")
                when 'art' then case when a."VL_ART" is null then '' else to_char(a."VL_ART" + 100000, 'FM000000000.0000') end
                else lpad(a."CO_VAGA"::text, 20, '0')
              end) collate "C" as chave,
             lpad(coalesce(c."CO_CANDIDATO_EMPREGARE"::text, ''), 20, '0') collate "C" as codigo
        from public."TB_PRE_CLASSIFICACAO" a
        join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = a."CO_EMPREGARE_CANDIDATO"
       where a."CO_MONITORAMENTO" = $2
         and a."TP_SITUACAO" = 'ELIMINADO'
         and ($3 is null or a."CO_VAGA" = any ($3))
         and ($4 is null or a."CO_VAGA" = $4)
         and ($5 is null or a."NO_MODALIDADE" = $5)
         and ($6 is null
              or private."FC_TEXTO_DE_BUSCA"(concat_ws(' ', c."CO_CANDIDATO_EMPREGARE", c."NO_CANDIDATO")) like '%%' || $6 || '%%')
    ),
    pagina as (
      select r.*, row_number() over (order by r.chave %1$s, r.codigo %1$s, r.id %1$s) as n
        from recorte r
       where $7 is null
          or (r.chave, r.codigo, r.id) %2$s (($7 ->> 'chave') collate "C", ($7 ->> 'codigo') collate "C", ($7 ->> 'id')::uuid)
       order by r.chave %1$s, r.codigo %1$s, r.id %1$s
       limit $8
    )
    select (select count(*) from recorte),
           (select array_agg(p.id order by p.n) from pagina p),
           (select jsonb_build_object('chave', p.chave, 'codigo', p.codigo, 'id', p.id) from pagina p order by p.n desc limit 1),
           (select count(*) from pagina)
  $sql$, case when v_desc then 'desc' else 'asc' end, case when v_desc then '<' else '>' end)
  into v_total, v_ids, v_ultimo, v_n
  using v_ordem, p_edital, v_vagas, p_vaga, p_modalidade, v_busca, p_apos, v_limite;

  -- As linhas no formato da fila (com a ficha, quando houver), na ordem da página.
  select coalesce(json_agg(l.linha order by array_position(v_ids, l.id)), '[]'::json)
    into v_linhas
    from (select * from private."FC_LINHAS_DA_FILA"(p_edital, v_vagas, false, null, null, coalesce(v_ids, '{}'))
          union all
          select * from private."FC_LINHAS_DA_FILA"(p_edital, v_vagas, true, null, null, coalesce(v_ids, '{}'))) l;

  return json_build_object(
    'schema_version', 1,
    'edital', p_edital,
    'area', v_area,
    'candidatos', v_linhas,
    'total', v_total,
    'proximo', case when v_n = v_limite then v_ultimo end
  );
end;
$_$;

--
-- Name: FUNCTION listar_eliminados_fila(p_edital uuid, p_vaga text, p_modalidade text, p_busca text, p_ordem text, p_sentido text, p_apos jsonb, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_eliminados_fila(p_edital uuid, p_vaga text, p_modalidade text, p_busca text, p_ordem text, p_sentido text, p_apos jsonb, p_limite integer) IS 'Aba Eliminados da fila em páginas (a tela pede 50): vaga, modalidade, busca e ordem no banco, cursor estável, total do recorte; linhas no formato da fila. Leitor da Avaliação documental (analista: só as vagas dele).';

--
-- Name: listar_etapas_do_cronograma(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_etapas_do_cronograma() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    AS $$
begin
  if not private.has_perm('cores') then
    raise exception 'Sem permissao para consultar cronograma';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'monitoramento_id', c.monitoramento_id,
      'ordem', c.ordem,
      'atividade', c.atividade,
      'data_inicio', c.data_inicio,
      'data_fim', c.data_fim
    ) order by c.monitoramento_id, c.ordem)
    from public."TB_CRONOGRAMA_MONIT_INDIG" c
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id = c.monitoramento_id
    where m.ativo
      and m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
      and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
  ), '[]'::jsonb);
end;
$$;

--
-- Name: listar_historico_coordenada_mapa_projetos(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_historico_coordenada_mapa_projetos(p_lugar text, p_limite integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode ver o histórico das coordenadas.';
  end if;
  if nullif(btrim(p_lugar), '') is null then
    raise exception using errcode = '22023', message = 'Lugar do mapa inválido.';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', h."CO_SEQ_HISTORICO",
             'em', h."DT_ALTERACAO",
             'por', coalesce(u.nome, u.email),
             'acao', h."TP_ACAO",
             'latitude_anterior', h."CG_LATITUDE_ANTERIOR",
             'longitude_anterior', h."CG_LONGITUDE_ANTERIOR",
             'latitude', h."CG_LATITUDE",
             'longitude', h."CG_LONGITUDE",
             'motivo', h."DS_MOTIVO",
             'conferido', case h."ST_CONFERIDO" when 'S' then true when 'N' then false end,
             'desfaz', h."CO_HISTORICO_DESFEITO",
             'desfeito', exists (select 1 from private."TH_COORDENADA_LOCAL_VAGA" d
                                  where d."CO_HISTORICO_DESFEITO" = h."CO_SEQ_HISTORICO"))
           order by h."CO_SEQ_HISTORICO" desc)
      from (select t.* from private."TH_COORDENADA_LOCAL_VAGA" t
             where t."DS_CHAVE_LUGAR" = p_lugar
             order by t."CO_SEQ_HISTORICO" desc
             limit least(greatest(coalesce(p_limite, 5), 1), 50)) h
      left join public."TB_PERFIL_USUARIO" u on u.user_id = h."CO_USUARIO"), '[]'::jsonb);
end;
$$;

--
-- Name: FUNCTION listar_historico_coordenada_mapa_projetos(p_lugar text, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_historico_coordenada_mapa_projetos(p_lugar text, p_limite integer) IS 'Últimas alterações de um lugar do mapa de Projetos (quem, quando, de/para, motivo, ação, se foi desfeita). Só administrador global ou gestor.';

--
-- Name: listar_historico_coordenada_mapa_saude_indigena(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_historico_coordenada_mapa_saude_indigena(p_alvo jsonb, p_limite integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode ver o histórico das coordenadas.';
  end if;
  if jsonb_typeof(p_alvo) is distinct from 'object' then
    raise exception using errcode = '22023', message = 'Ponto do mapa inválido.';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', h."CO_SEQ_HISTORICO",
             'em', h."DT_ALTERACAO",
             'por', coalesce(u.nome, u.email),
             'acao', h."TP_ACAO",
             'latitude_anterior', h."CG_LATITUDE_ANTERIOR",
             'longitude_anterior', h."CG_LONGITUDE_ANTERIOR",
             'latitude', h."CG_LATITUDE",
             'longitude', h."CG_LONGITUDE",
             'motivo', h."DS_MOTIVO",
             'conferido', case h."ST_CONFERIDO" when 'S' then true when 'N' then false end,
             'desfaz', h."CO_HISTORICO_DESFEITO",
             'desfeito', exists (select 1 from private."TH_COORDENADA_MAPA_SAUDE_INDIG" d
                                  where d."CO_HISTORICO_DESFEITO" = h."CO_SEQ_HISTORICO"))
           order by h."CO_SEQ_HISTORICO" desc)
      from (select t.* from private."TH_COORDENADA_MAPA_SAUDE_INDIG" t
             where private."FC_CHAVE_ALVO_COORDENADA"(t."DS_ALVO") = private."FC_CHAVE_ALVO_COORDENADA"(p_alvo)
             order by t."CO_SEQ_HISTORICO" desc
             limit least(greatest(coalesce(p_limite, 5), 1), 50)) h
      left join public."TB_PERFIL_USUARIO" u on u.user_id = h."CO_USUARIO"), '[]'::jsonb);
end;
$$;

--
-- Name: FUNCTION listar_historico_coordenada_mapa_saude_indigena(p_alvo jsonb, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_historico_coordenada_mapa_saude_indigena(p_alvo jsonb, p_limite integer) IS 'Últimas alterações de um ponto do mapa (quem, quando, de/para, motivo, ação, se foi desfeita). Só administrador global ou gestor.';

--
-- Name: listar_listas_aprovados(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_listas_aprovados() RETURNS TABLE(lista_id uuid, edital_id text, edital text, unidade text, ativo boolean, arquivo_nome text, arquivo_path text, importado_em timestamp with time zone, total_candidatos bigint, importado_por_email text, importado_por_nome text, origem text, lista_classificacao_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not ((private.pode_recurso('aprovados') or private.pode_recurso('importacao',2))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  -- A contagem por lista pelo índice IN_CANDAPROVADO_LISTAVIVA (20261103171500).
  return query
  select l.id, l.edital_id, m.edital, m.unidade, l.ativo, l.arquivo_nome,
         l.arquivo_path, l.importado_em,
         (select count(*) from public."TB_CANDIDATO_APROVADO" c
           where c.lista_id = l.id and c.removido_em is null),
         l."DS_EMAIL_IMPORTACAO"::text, l."NO_USUARIO_IMPORTACAO"::text,
         l."TP_ORIGEM"::text, l."CO_LISTA_CLASSIFICACAO"
  from public."TB_LISTA_APROVADO" l
  join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
  where l.vigente is true
    and m."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])
      and ((select private."FC_EDITAIS_VISIVEIS"()) is null or m.id = any ((select private."FC_EDITAIS_VISIVEIS"())::uuid[]))
  order by m.edital, m.unidade;
end;
$$;

--
-- Name: FUNCTION listar_listas_aprovados(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_listas_aprovados() IS 'Listas de aprovados vigentes dos editais das áreas do usuário (com o recorte da coordenação): situação, arquivo, total de candidatos, quem importou, a origem (XLSX ou CLASSIFICACAO) e a lista de classificação publicada.';

--
-- Name: listar_mapa_da_saude_indigena(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_mapa_da_saude_indigena(p_versao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select private."FC_SE_MUDOU"(jsonb_build_object('linhas', coalesce((
    select jsonb_agg(jsonb_build_object('chave', m.chave, 'payload', m.payload) order by m.chave)
      from public."TB_CONFIG_MAPA_SAUDE_INDIG" m
     where m.chave in ('lmap', 'rede_cnes')
  ), '[]'::jsonb)), p_versao);
$$;

--
-- Name: FUNCTION listar_mapa_da_saude_indigena(p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_mapa_da_saude_indigena(p_versao text) IS 'O mapa da Saúde Indígena (lmap e rede_cnes de TB_CONFIG_MAPA_SAUDE_INDIG) como { linhas: [{ chave, payload }], versao }; p_versao igual à atual devolve só { inalterado, versao } (FC_SE_MUDOU, 20261015000100). SECURITY INVOKER: a RLS da tabela.';

--
-- Name: listar_modelos_carta_convocacao(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_modelos_carta_convocacao(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := lower(btrim(coalesce(p_area, '')));
begin
  if not private.pode_recurso('aprovados', 1) then
    raise exception 'Sem permissão para este recurso' using errcode = '42501';
  end if;
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Área inválida: %', p_area using errcode = '22023';
  end if;
  if not (v_area = any ((select private."FC_AREAS_USUARIO"())::text[])) then
    raise exception 'Sem permissão para esta área' using errcode = '42501';
  end if;

  return json_build_object(
    'pode_editar', private.pode_recurso('aprovados', 2),
    'modelos', coalesce((
      select json_agg(json_build_object(
               'modelo_id', t."CO_MODELO_CARTA",
               'area', t."CO_AREA",
               'edital_id', t."CO_MONITORAMENTO",
               'edital', m.edital,
               'unidade', m.unidade,
               'nome', t."NO_MODELO",
               'ativo', t."ST_ATIVO",
               'motivo_situacao', t."DS_MOTIVO_SITUACAO",
               'versao', t."NU_VERSAO_VIGENTE",
               'atualizado_em', t."DT_ATUALIZACAO",
               'vigente', (select json_build_object(
                              'titulo', v."DS_TITULO", 'texto', v."DS_TEXTO", 'local', v."DS_LOCAL",
                              'documentos', v."DS_DOCUMENTOS", 'contato', v."DS_CONTATO",
                              'prazo_dias', v."NU_PRAZO_DIAS", 'usuario', v."NO_USUARIO", 'salvo_em', v."DT_CRIACAO")
                             from public."TH_MODELO_CARTA_CONVOCACAO" v
                            where v."CO_MODELO_CARTA" = t."CO_MODELO_CARTA" and v."NU_VERSAO" = t."NU_VERSAO_VIGENTE"),
               'versoes', (select coalesce(json_agg(json_build_object(
                                     'versao', v."NU_VERSAO", 'motivo', v."DS_MOTIVO",
                                     'usuario', coalesce(v."NO_USUARIO", v."DS_EMAIL_USUARIO"), 'salvo_em', v."DT_CRIACAO")
                                   order by v."NU_VERSAO" desc), '[]'::json)
                             from (select * from public."TH_MODELO_CARTA_CONVOCACAO" h
                                    where h."CO_MODELO_CARTA" = t."CO_MODELO_CARTA"
                                    order by h."NU_VERSAO" desc limit 20) v),
               'cartas', (select count(*) from public."TH_CARTA_CONVOCACAO" e where e."CO_MODELO_CARTA" = t."CO_MODELO_CARTA"))
             order by t."ST_ATIVO" desc, (t."CO_MONITORAMENTO" is null), lower(t."NO_MODELO"))
        from public."TB_MODELO_CARTA_CONVOCACAO" t
        left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = t."CO_MONITORAMENTO"
       where t."CO_AREA" = v_area
         and (t."CO_MONITORAMENTO" is null or private."FC_PODE_VER_EDITAL"(t."CO_MONITORAMENTO"))
    ), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION listar_modelos_carta_convocacao(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_modelos_carta_convocacao(p_area text) IS 'Os modelos da carta de convocação da área (ativos e inativos; os de edital só se a pessoa vê o edital): a versão vigente com o texto e os valores padrão, as últimas 20 versões (motivo, quem, quando), quantas cartas saíram de cada um e pode_editar. Aprovados >= leitor e a área do usuário.';

--
-- Name: listar_modelos_convocacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_modelos_convocacao() RETURNS TABLE(modelo_id uuid, nome text, distribuicao text, cota_multipla text, editais bigint, categorias jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not ((private.pode_recurso('aprovados') or private.pode_recurso('importacao',2))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if private.monitora_role() = '' then
    raise exception 'Perfil sem acesso ao sistema';
  end if;
  return query
  select m."CO_MODELO",
         m."NO_MODELO",
         lower(m."TP_DISTRIBUICAO"),
         lower(m."TP_COTA_MULTIPLA"),
         (
           select count(*)
           from public."TB_CONVOCACAO_EDITAL" e
           where e."CO_MODELO" = m."CO_MODELO"
         ),
         coalesce(
           (
             select jsonb_agg(
               jsonb_build_object(
                 'id', c."CO_CATEGORIA",
                 'rotulo', c."NO_CATEGORIA",
                 'sigla', c."SG_CATEGORIA",
                 'ampla', c."ST_AMPLA" = 'S',
                 'acumulavel', c."ST_ACUMULAVEL" = 'S',
                 'percentual', c."TX_RESERVA",
                 'arredondamento', lower(c."TP_ARREDONDAMENTO"),
                 'teto', c."TX_TETO",
                 'minimo', c."QT_MINIMA_RESERVA",
                 'termos', c."DS_TERMO",
                 'posicoes', c."DS_POSICAO",
                 'intervalo', c."QT_INTERVALO",
                 'cascata', c."DS_CASCATA"
               )
               order by c."NU_ORDEM", c."CO_CATEGORIA"
             )
             from public."TB_CATEGORIA_CONVOCACAO" c
             where c."CO_MODELO" = m."CO_MODELO"
           ),
           '[]'::jsonb
         )
  from public."TB_MODELO_CONVOCACAO" m
  order by m."NO_MODELO";
end;
$$;

--
-- Name: listar_modelos_resposta_recurso(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_modelos_resposta_recurso() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.pode_recurso('recursos', 3) then
    raise exception 'Só a administração de Recursos gerencia os modelos de resposta' using errcode = '42501';
  end if;
  return json_build_object(
    'marcadores', to_json(private."FC_MARCADORES_MODELO_RESPOSTA"()),
    'areas', (
      select coalesce(json_agg(json_build_object('id', a."CO_AREA", 'rotulo', a."NO_AREA") order by a."NU_ORDEM"), '[]'::json)
      from public."TB_AREA" a
      where private."FC_PODE_AREA"(a."CO_AREA")
    ),
    'origens', (
      select coalesce(json_agg(json_build_object('id', o."CO_ORIGEM_RECURSO", 'rotulo', o."NO_ORIGEM_RECURSO", 'ativo', o."ST_ATIVO" = 'S') order by o."NU_ORDEM"), '[]'::json)
      from public."TB_ORIGEM_RECURSO" o
    ),
    'modelos', (
      select coalesce(json_agg(json_build_object(
          'id', t."CO_MODELO_RESPOSTA",
          'versao', t."NU_VERSAO",
          'area', t."CO_AREA",
          'origem', t."CO_ORIGEM_RECURSO",
          'situacao', t."TP_SITUACAO",
          'nome', t."NO_MODELO",
          'corpo', t."DS_CORPO",
          'ativo', t."ST_ATIVO" = 'S',
          'motivo_arquivamento', t."DS_MOTIVO_ARQUIVAMENTO",
          'arquivado_em', t."DT_ARQUIVAMENTO",
          'arquivado_por', private."FC_NOME_USUARIO"(t."CO_USUARIO_ARQUIVAMENTO"),
          'criado_em', t."DT_CRIACAO",
          'criado_por', private."FC_NOME_USUARIO"(t."CO_USUARIO_CRIACAO"),
          'em_uso', (select count(*) from public."TB_RESPOSTA_RECURSO" s where s."CO_MODELO_RESPOSTA" = t."CO_MODELO_RESPOSTA"),
          'versoes', (
            select coalesce(json_agg(json_build_object(
                'versao', v."NU_VERSAO",
                'criado_em', v."DT_CRIACAO",
                'criado_por', private."FC_NOME_USUARIO"(v."CO_USUARIO_CRIACAO")
              ) order by v."NU_VERSAO" desc), '[]'::json)
            from public."TB_MODELO_RESPOSTA_RECURSO" v
            where v."CO_MODELO_RESPOSTA" = t."CO_MODELO_RESPOSTA"
          )
        ) order by t."ST_ATIVO" desc, t."NO_MODELO"), '[]'::json)
      from public."TB_MODELO_RESPOSTA_RECURSO" t
      where t."ST_VIGENTE" = 'S'
        and (t."CO_AREA" is null or private."FC_PODE_AREA"(t."CO_AREA"))
    )
  );
end;
$$;

--
-- Name: FUNCTION listar_modelos_resposta_recurso(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_modelos_resposta_recurso() IS 'Modelos de resposta (versão vigente, ativos e arquivados) com as versões anteriores, as áreas, as origens e os marcadores aceitos. Exige recursos = admin.';

--
-- Name: listar_monitoramento_operacional(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_monitoramento_operacional(p_versao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  -- Marca barata com a data de hoje na chave (20261103171500).
  v_marca constant text := private."FC_MARCA_DO_MONITORAMENTO_OPERACIONAL"();
  v_payload jsonb;
begin
  if v_marca is not null and p_versao = v_marca then
    return jsonb_build_object('inalterado', true, 'versao', v_marca);
  end if;
  v_payload := jsonb_build_object('linhas', coalesce((
    select jsonb_agg(to_jsonb(l) order by l.unidade, l.edital)
      from (
        select v.aprovados_analise, v.aprovados_prova, v.aptos_analise, v.ativo,
               v.cancelados, v.cargos, v.ciclo, v.contratados,
               v.cronograma_atividade_atual, v.cronograma_automatico,
               v.cronograma_dias_para_proxima, v.cronograma_percentual,
               v.cronograma_proxima_atividade, v.cronograma_proxima_data,
               v.data_fim, v.data_inicio, v.edital, v.eliminados_nota,
               v.entrevistados, v.etapa, v.id, v.id_unidade, v.inscritos,
               v.link_edital, v.observacoes, v.observacoes_internas, v.processo,
               v.reprovados_analise, v.responsavel, v.risco, v.sigla_unidade,
               v.status, v.tipo_unidade, v.total_eliminados, v.uf, v.unidade,
               v.vagas_ociosas, v.vagas_total, v."CO_AREA", v."ST_TREINAMENTO",
               v."TP_FONTE_FUNIL", v."DT_FONTE_FUNIL"
          from public."VW_MONITORAMENTO_INDIGENA_OPERACIONAL" v
         where v.ativo is true
      ) l), '[]'::jsonb));
  if v_marca is null then
    return private."FC_SE_MUDOU"(v_payload, p_versao);
  end if;
  return v_payload || jsonb_build_object('versao', v_marca);
end;
$$;

--
-- Name: FUNCTION listar_monitoramento_operacional(p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_monitoramento_operacional(p_versao text) IS 'As linhas ativas da VW_MONITORAMENTO_INDIGENA_OPERACIONAL (security_invoker), por versão: com p_versao igual à marca barata monitoramento_operacional (fontes da view e das políticas de RLS, quem lê e a data de hoje), { inalterado, versao } sem montar (20261103171500); senão { linhas, versao }. Sem fontes registradas, FC_SE_MUDOU (md5 do payload), como antes.';

--
-- Name: listar_municipios_das_vagas_da_area(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_municipios_das_vagas_da_area(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    SET statement_timeout TO '5s'
    AS $_$
declare
  v_grupos_norm text[];
  v_area text := lower(btrim(coalesce(p_area, '')));
begin
  if not private.pode_recurso('dashboard') then
    raise exception 'Sem permissão para este recurso' using errcode = '42501';
  end if;

  -- Valida a área e confere se ela é do usuário (ou se ele é admin).
  v_grupos_norm := private."FC_GRUPOS_ANALISES_DA_AREA"(p_area);

  return coalesce((
    with
    -- Os locais publicados nos editais da área.
    loc as (
      select l."CO_MONITORAMENTO" as id,
             m.edital,
             m.unidade as projeto,
             private."FC_NUMERO_EDITAL"(m.edital) as numero,
             l."CO_MUNICIPIO_IBGE" as ibge,
             l."NO_MUNICIPIO" as municipio,
             l."SG_UF" as uf,
             case when l."CO_MUNICIPIO_IBGE" is null then 'uf:' || l."SG_UF"
                  else private."FC_TEXTO_BUSCA_RECURSO"(l."NO_MUNICIPIO") || '/' || l."SG_UF" end as chave,
             l."QT_VAGA" as qt,
             l."ST_CADASTRO_RESERVA" = 'S' as cr,
             l."NO_LOTACAO" as lotacao,
             l."TP_ORIGEM" as origem
        from public."TB_LOCAL_VAGA_EDITAL" l
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = l."CO_MONITORAMENTO"
       where l."ST_REGISTRO_ATIVO" = 'S'
         and m."CO_AREA" = v_area
         and m.ativo is not false
    ),
    -- Um edital da área por número (o ativo primeiro), para dar nome às análises.
    edital_da_area as (
      select distinct on (private."FC_NUMERO_EDITAL"(m.edital))
             m.id, m.edital, m.unidade, private."FC_NUMERO_EDITAL"(m.edital) as numero
        from public."TB_MONITORAMENTO_INDIGENA" m
       where m."CO_AREA" = v_area
         and private."FC_NUMERO_EDITAL"(m.edital) is not null
       order by private."FC_NUMERO_EDITAL"(m.edital), m.ativo desc nulls last, m.id
    ),
    -- Análises da área no recorte "ativo" do painel: pela área da análise
    -- (CO_AREA, a fonte canônica) ou pelo grupo da planilha, como antes.
    analise as (
      select ac.id, ac.codigo_vaga, ac.nome_vaga, ac.status_consolidado, ac.unidade, ac.edital,
             private."FC_NUMERO_EDITAL"(ac.edital) as numero
        from public."TB_ANALISE_CURRICULAR" ac
        left join public."TB_EDITAL_ANALISE" e
          on e.grupo_norm = ac.grupo_norm
         and e.unidade_norm = ac.unidade_norm
         and e.edital_norm = ac.edital_norm
       where (ac."CO_AREA" = v_area or ac.grupo_norm = any (v_grupos_norm))
         and ac.ativo is true
         and coalesce(e.ativo, true) is true
    ),
    -- Cada análise no seu município: "UBS móvel <Município>/<UF>" no nome da
    -- vaga, ou o nome de um município de local do mesmo edital (palavra inteira).
    -- O texto de busca sai uma vez por município e uma vez por análise (antes,
    -- uma vez por par análise × município); o strpos descarta, antes da
    -- expressão regular, o par que ela nunca casaria — só quando o nome do
    -- município não tem caractere especial de expressão regular (20261103171500).
    municipio_do_edital as materialized (
      select x.numero, x.chave, x.municipio, x.uf, x.texto,
             x.texto !~ '^[a-z0-9 ''-]*$' as especial
        from (select distinct l.numero, l.chave, l.municipio, l.uf,
                     private."FC_TEXTO_BUSCA_RECURSO"(l.municipio) as texto
                from loc l
               where l.ibge is not null) x
    ),
    texto_da_analise as materialized (
      select a.id, a.codigo_vaga, a.status_consolidado, a.numero, a.unidade, a.edital,
             private."FC_TEXTO_BUSCA_RECURSO"(a.nome_vaga) as texto
        from analise a
       where a.numero in (select m.numero from municipio_do_edital m)
    ),
    casada as (
      select a.id, a.codigo_vaga, a.status_consolidado, a.numero, a.unidade, a.edital,
             private."FC_TEXTO_BUSCA_RECURSO"(btrim(mu.partes[1])) || '/' || mu.partes[2] as chave,
             btrim(mu.partes[1]) as municipio, mu.partes[2] as uf
        from analise a
       cross join lateral regexp_match(a.nome_vaga, 'UBS m[óo]vel ([^/]+)/([A-Z]{2})') as mu(partes)
       where a.nome_vaga like '%UBS m%'
         and btrim(mu.partes[1]) <> ''
      union
      select t.id, t.codigo_vaga, t.status_consolidado, t.numero, t.unidade, t.edital,
             l.chave, l.municipio, l.uf
        from texto_da_analise t
        join municipio_do_edital l
          on l.numero = t.numero
         and (l.especial or strpos(t.texto, l.texto) > 0)
         and t.texto ~ ('(^|[^a-z0-9])' || l.texto || '($|[^a-z0-9])')
    ),
    estatistica as (
      select chave,
             min(municipio) as municipio,
             min(uf) as uf,
             count(distinct codigo_vaga) as vagas,
             count(distinct id) as candidatos,
             count(distinct id) filter (where status_consolidado ilike 'aprovad%') as aprovados,
             count(distinct id) filter (where status_consolidado ilike 'reprovad%') as reprovados
        from casada
       group by chave
    ),
    -- Os editais de cada lugar: o que veio da tabela e o que veio das análises.
    edital_do_local as (
      select chave, numero, id, edital, projeto, qt, cr, lotacao, origem from loc
      union all
      select c.chave, c.numero, e.id, coalesce(e.edital, c.edital), coalesce(e.unidade, c.unidade),
             null::integer, false, null::varchar, 'NOME_VAGA'
        from (select chave, numero, min(unidade) as unidade, min(edital) as edital
                from casada group by chave, numero) c
        left join edital_da_area e on e.numero = c.numero
    ),
    por_edital as (
      select chave, numero,
             coalesce((array_agg(id) filter (where origem <> 'NOME_VAGA' and id is not null))[1],
                      (array_agg(id) filter (where id is not null))[1]) as id,
             coalesce(min(edital) filter (where origem <> 'NOME_VAGA'), min(edital)) as edital,
             coalesce(min(projeto) filter (where origem <> 'NOME_VAGA'), min(projeto)) as projeto,
             sum(qt) as vagas,
             coalesce(bool_or(cr), false) as cr,
             array_agg(distinct origem order by origem) as origens,
             coalesce(array_agg(distinct lotacao order by lotacao) filter (where lotacao is not null), '{}') as lotacoes
        from edital_do_local
       group by chave, numero
    ),
    lugar as (
      select chave, min(ibge) as ibge, min(municipio) as municipio, min(uf) as uf
        from loc
       group by chave
    ),
    chaves as (
      select chave from loc
      union
      select chave from casada
    ),
    linha as (
      select k.chave,
             k.chave like 'uf:%' as so_uf,
             coalesce(l.municipio, s.municipio) as municipio,
             coalesce(l.uf, s.uf) as uf,
             l.ibge,
             s.vagas, s.candidatos, s.aprovados, s.reprovados,
             c."CG_LATITUDE" as latitude,
             c."CG_LONGITUDE" as longitude,
             c."TP_ORIGEM" as coordenada_origem
        from chaves k
        left join lugar l on l.chave = k.chave
        left join estatistica s on s.chave = k.chave
        left join public."TB_COORDENADA_LOCAL_VAGA" c on c."DS_CHAVE_LUGAR" = k.chave
    )
    select json_agg(json_build_object(
      'lugar', r.chave,
      'municipio_uf', case when r.so_uf then null else r.municipio || '/' || r.uf end,
      'municipio', case when r.so_uf then null else r.municipio end,
      'uf', r.uf,
      'codigo_ibge', r.ibge,
      'nivel', case when r.so_uf then 'uf' else 'municipio' end,
      'latitude', r.latitude,
      'longitude', r.longitude,
      'coordenada_origem', r.coordenada_origem,
      'vagas', coalesce(r.vagas, 0),
      'candidatos', coalesce(r.candidatos, 0),
      'aprovados', coalesce(r.aprovados, 0),
      'reprovados', coalesce(r.reprovados, 0),
      'vagas_edital', (select sum(p.vagas) from por_edital p where p.chave = r.chave),
      'cadastro_reserva', coalesce((select bool_or(p.cr) from por_edital p where p.chave = r.chave), false),
      'projetos', coalesce((select json_agg(distinct p.projeto) from por_edital p
                             where p.chave = r.chave and p.projeto is not null), '[]'::json),
      'editais', coalesce((select json_agg(json_build_object(
                             'id', p.id,
                             'edital', p.edital,
                             'projeto', p.projeto,
                             'vagas', p.vagas,
                             'cadastro_reserva', p.cr,
                             'origens', p.origens,
                             'lotacoes', p.lotacoes) order by p.projeto, p.numero)
                             from por_edital p where p.chave = r.chave), '[]'::json)
    ) order by r.uf, r.so_uf desc, r.municipio)
    from linha r
  ), '[]'::json);
end;
$_$;

--
-- Name: FUNCTION listar_municipios_das_vagas_da_area(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_municipios_das_vagas_da_area(p_area text) IS 'Lugares das vagas da área (TB_LOCAL_VAGA_EDITAL + UBS móvel no nome da vaga): chave do lugar, município ou UF, coordenada do banco (TB_COORDENADA_LOCAL_VAGA; nula se o lugar ainda não tem), projetos e editais de cada um, vagas publicadas, vagas nas análises, candidatos, aprovados e reprovados. Mapa da Visão geral de Projetos.';

--
-- Name: listar_opcoes_da_solicitacao_acesso(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_opcoes_da_solicitacao_acesso() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Usuário não autenticado' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'areas', coalesce((
      select jsonb_agg(jsonb_build_object('codigo', a."CO_AREA", 'nome', a."NO_AREA") order by a."NU_ORDEM")
        from public."TB_AREA" a), '[]'::jsonb),
    'unidades', coalesce((
      select jsonb_agg(u.item order by u.area, u.tipo, u.nome)
        from (
          select 'saude-indigena' as area, t.tipo, t.nome_oficial as nome,
                 jsonb_build_object('area', 'saude-indigena', 'nome', t.nome_oficial, 'sigla', t.sigla, 'tipo', t.tipo) as item
            from public."TD_UNIDADE" t
           where t.ativo
          union all
          select 'projetos', '', x."NO_UNIDADE",
                 jsonb_build_object('area', 'projetos', 'nome', x."NO_UNIDADE", 'sigla', null, 'tipo', null)
            from public."TA_UNIDADE_AREA" x
           where x."CO_AREA" = 'projetos'
        ) u), '[]'::jsonb),
    'coordenacoes', coalesce((
      select jsonb_agg(jsonb_build_object('codigo', c."CO_COORDENACAO", 'nome', c."NO_COORDENACAO", 'area', c."CO_AREA")
                       order by c."NO_COORDENACAO")
        from public."TB_COORDENACAO" c
       where c."ST_ATIVO"), '[]'::jsonb));
end;
$$;

--
-- Name: FUNCTION listar_opcoes_da_solicitacao_acesso(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_opcoes_da_solicitacao_acesso() IS 'Opções da tela de solicitação de acesso (autenticado, mesmo sem perfil): áreas, unidades (DSEI/CASAI de TD_UNIDADE; projetos de TA_UNIDADE_AREA) e coordenações ativas.';

--
-- Name: listar_pendencias_coordenada_mapa_projetos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_pendencias_coordenada_mapa_projetos() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode ver as pendências das coordenadas.';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'lugar', p."DS_CHAVE_LUGAR", 'nome', p."NO_LUGAR", 'uf', p."SG_UF", 'codigo_ibge', p."CO_MUNICIPIO_IBGE",
             'motivo_tipo', p."TP_MOTIVO", 'motivo', p."DS_MOTIVO",
             'conferido', p."ST_CONFERIDO" = 'S', 'conferido_em', p."DT_CONFERENCIA",
             'candidatos', p."DS_CANDIDATO")
           order by p."SG_UF", p."NO_LUGAR")
      from private."TB_PENDENCIA_COORDENADA_LOCAL" p), '[]'::jsonb);
end;
$$;

--
-- Name: FUNCTION listar_pendencias_coordenada_mapa_projetos(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_pendencias_coordenada_mapa_projetos() IS 'Pendências de localização dos lugares do mapa de Projetos, com candidatos e situação. Só administrador global ou gestor.';

--
-- Name: listar_pendencias_coordenada_mapa_saude_indigena(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_pendencias_coordenada_mapa_saude_indigena() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode ver as pendências das coordenadas.';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'fonte', p."TP_FONTE", 'tipo', p."TP_PONTO", 'dsei', p."NO_DSEI", 'codigo', p."CO_PONTO",
             'nome', p."NO_PONTO", 'municipio', p."NO_MUNICIPIO",
             'motivo_tipo', p."TP_MOTIVO", 'motivo', p."DS_MOTIVO",
             'conferido', p."ST_CONFERIDO" = 'S', 'conferido_em', p."DT_CONFERENCIA",
             'candidatos', p."DS_CANDIDATO")
           order by p."NO_DSEI", p."NO_PONTO")
      from private."TB_PENDENCIA_COORDENADA_MAPA" p), '[]'::jsonb);
end;
$$;

--
-- Name: FUNCTION listar_pendencias_coordenada_mapa_saude_indigena(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_pendencias_coordenada_mapa_saude_indigena() IS 'Pendências de localização do mapa (pontos não confirmados pela auditoria), com candidatos e situação. Só administrador global ou gestor.';

--
-- Name: listar_pendencias_do_edital(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_pendencias_do_edital(p_area text, p_edital uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- O administrador global lê qualquer área; os outros, com Aprovados e a área.
  if not private.is_master() and not private.pode_recurso('aprovados', 1) then
    raise exception 'Sem permissão para a Lista de aprovados' using errcode = '42501';
  end if;
  if p_area is null or not (private.is_master() or private."FC_PODE_AREA"(p_area)) then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;

  return (
    with pend as (
      select p.*, m.edital as numero, m.unidade,
             private."FC_PODE_DECIDIR_PENDENCIA"(p."CO_MONITORAMENTO") as pode_decidir
        from public."TB_PENDENCIA_APROVADO" p
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = p."CO_MONITORAMENTO"
       where p."CO_AREA" = p_area
         and (p_edital is null or p."CO_MONITORAMENTO" = p_edital)
         and (p."TP_SITUACAO" = 'ABERTA' or p."DT_RESOLUCAO" > now() - interval '30 days')
         and (private.is_master() or private."FC_PODE_VER_EDITAL"(p."CO_MONITORAMENTO"))
    )
    select jsonb_build_object(
      'schema_version', 1,
      'area', p_area,
      'gerado_em', now(),
      'pendencias', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'id', p."CO_PENDENCIA_APROVADO",
                 'tipo', p."TP_PENDENCIA",
                 'situacao', p."TP_SITUACAO",
                 'edital_id', p."CO_MONITORAMENTO",
                 'edital', p.numero,
                 'unidade', p.unidade,
                 'detalhe', p."DS_DETALHE",
                 'detectada_em', p."DT_DETECCAO",
                 'decisao', p."TP_DECISAO",
                 'motivo', p."DS_MOTIVO_DECISAO",
                 'decidida_em', p."DT_RESOLUCAO",
                 'decidida_por', (select coalesce(nullif(btrim(u.nome), ''), u.email)
                                    from public."TB_PERFIL_USUARIO" u
                                   where u.user_id = p."CO_USUARIO_DECISAO"
                                   order by u.updated_at desc nulls last limit 1),
                 'pode_decidir', p.pode_decidir,
                 'linhas', (
                   select coalesce(jsonb_agg(jsonb_build_object(
                            'id', c.id, 'nome', c.nome, 'cargo', c.cargo, 'vaga', c.codigo_vaga,
                            'modalidade', c.modalidade, 'posicao', c.classificacao, 'nota', c.nota,
                            'status', c.status, 'matricula', c.matricula, 'convocado_em', c."DT_CONVOCACAO",
                            'lista_ativa', coalesce(l.ativo, false), 'removida', c.removido_em is not null)
                          order by c.classificacao nulls last, c.nome, c.id), '[]'::jsonb)
                     from public."TB_CANDIDATO_APROVADO" c
                     join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
                    where c.id = any (p."CO_CANDIDATO_APROVADO")),
                 'historico', (
                   select coalesce(jsonb_agg(jsonb_build_object(
                            'evento', h."TP_EVENTO", 'decisao', h."TP_DECISAO", 'motivo', h."DS_MOTIVO",
                            'alteracoes', h."DS_ALTERACAO", 'por', coalesce(nullif(btrim(h."NO_USUARIO"), ''), h."DS_EMAIL_USUARIO"),
                            'em', h."DT_EVENTO") order by h."DT_EVENTO" desc), '[]'::jsonb)
                     from (select * from public."TH_PENDENCIA_APROVADO" h
                            where h."CO_PENDENCIA_APROVADO" = p."CO_PENDENCIA_APROVADO"
                            order by h."DT_EVENTO" desc limit 20) h))
               order by case p."TP_SITUACAO" when 'ABERTA' then 0 else 1 end, p.numero, p."TP_PENDENCIA",
                        p."DT_DETECCAO", p."CO_PENDENCIA_APROVADO")
          from (select * from pend order by case "TP_SITUACAO" when 'ABERTA' then 0 else 1 end, "DT_DETECCAO"
                 limit 2000) p), '[]'::jsonb)
    )
  );
end;
$$;

--
-- Name: FUNCTION listar_pendencias_do_edital(p_area text, p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_pendencias_do_edital(p_area text, p_edital uuid) IS 'Tela Lista de aprovados › Pendências: as pendências da área (e do edital, se pedido) no recorte de quem lê — abertas e as resolvidas nos últimos 30 dias — com as linhas (nome, vaga, modalidade, posição, nota, status, matrícula, data da convocação), quem pode decidir e o histórico. Aprovados >= leitor. 20261026190000.';

--
-- Name: listar_pessoas_da_area(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_pessoas_da_area(p_area text, p_edital uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;
  if not private."FC_PODE_EDITAR_CRONOGRAMA_AREA"(p_area) then
    raise exception 'Sem permissão para esta área.' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object('id', u.id, 'nome', coalesce(nullif(btrim(u.nome), ''), u.email))
                     order by coalesce(nullif(btrim(u.nome), ''), u.email))
      from public."TB_PERFIL_USUARIO" u
     where u.ativo
       and private."FC_PERFIL_PODE_SER_RESPONSAVEL"(u.id, p_area, p_edital)), '[]'::jsonb);
end;
$$;

--
-- Name: FUNCTION listar_pessoas_da_area(p_area text, p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_pessoas_da_area(p_area text, p_edital uuid) IS 'Pessoas ativas que veem a área (e o edital, se informado): as opções de responsável. Só para quem edita na área. 20261104120000.';

--
-- Name: listar_pre_classificacao(uuid, text, text, text, jsonb, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_pre_classificacao(p_edital uuid, p_vaga text DEFAULT NULL::text, p_grupo text DEFAULT 'CLASSIFICADOS'::text, p_busca text DEFAULT NULL::text, p_apos jsonb DEFAULT NULL::jsonb, p_limite integer DEFAULT 50, p_motivo text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_grupo text := upper(coalesce(p_grupo, 'CLASSIFICADOS'));
  v_busca text := nullif(btrim(private."FC_TEXTO_DE_BUSCA"(p_busca)), '');
  v_limite integer := least(greatest(coalesce(p_limite, 50), 1), 500);
  v_apos_vaga text := p_apos ->> 'vaga';
  v_apos_grupo integer := (p_apos ->> 'grupo')::integer;
  v_apos_posicao integer := (p_apos ->> 'posicao')::integer;
  v_apos_codigo text := p_apos ->> 'codigo';
  v_linhas jsonb;
  v_ultimo jsonb;
  v_n integer;
  v_total integer;
  v_por_vaga jsonb;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_por_motivo jsonb;
begin
  if v_grupo not in ('CLASSIFICADOS', 'ELIMINADOS', 'PODE_INCLUIR') then
    raise exception 'Grupo inválido: %', p_grupo using errcode = '22023';
  end if;

  -- Uma consulta só (função STABLE, sem tabela temporária): o recorte é lido uma vez e dele
  -- saem o total, quantos por vaga e a página.
  with recorte as materialized (
    select a."CO_EMPREGARE_CANDIDATO" as id, a."CO_VAGA"::text as vaga,
           -- No lote antes de fora do lote; eliminados num grupo só.
           case when a."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO') then 0
                when a."TP_SITUACAO" = 'RANQUEADO' then 1 else 2 end as grupo,
           case when v_grupo = 'ELIMINADOS' then 0 else coalesce(a."NU_POSICAO", 2147483647) end as posicao,
           coalesce(c."CO_CANDIDATO_EMPREGARE"::text, '') collate "C" as codigo,
           a."CO_MOTIVO_ELIMINACAO" as motivo_codigo, a."DS_MOTIVO_ELIMINACAO" as motivo
      from public."TB_PRE_CLASSIFICACAO" a
      join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = a."CO_EMPREGARE_CANDIDATO"
     where a."CO_MONITORAMENTO" = p_edital
       and (p_vaga is null or a."CO_VAGA" = p_vaga)
       and case v_grupo
             when 'CLASSIFICADOS' then a."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO', 'RANQUEADO')
             when 'ELIMINADOS' then a."TP_SITUACAO" = 'ELIMINADO'
             else a."TP_SITUACAO" = 'RANQUEADO'
                  or (a."TP_SITUACAO" = 'ELIMINADO' and a."CO_MOTIVO_ELIMINACAO" is distinct from 'SAIU_DA_EMPREGARE')
           end
       and (v_busca is null
            or private."FC_TEXTO_DE_BUSCA"(concat_ws(' ', c."CO_CANDIDATO_EMPREGARE", c."NO_CANDIDATO")) like '%' || v_busca || '%')
  ),
  -- O motivo (só nos eliminados) recorta a lista; as opções do filtro contam sem ele.
  filtrado as materialized (
    select r.* from recorte r
     where v_motivo is null or r.motivo_codigo = v_motivo
  ),
  pagina as (
    select r.*
      from filtrado r
     where p_apos is null
        or (r.vaga collate "C", r.grupo, r.posicao, r.codigo)
           > (v_apos_vaga collate "C", v_apos_grupo, v_apos_posicao, v_apos_codigo collate "C")
     order by r.vaga collate "C", r.grupo, r.posicao, r.codigo
     limit v_limite
  ),
  linhas as (
    select p.vaga, p.grupo, p.posicao, p.codigo,
           jsonb_strip_nulls(jsonb_build_object(
             'id', a."CO_EMPREGARE_CANDIDATO", 'vaga', a."CO_VAGA",
             'codigo', c."CO_CANDIDATO_EMPREGARE", 'nome', c."NO_CANDIDATO",
             'situacao', a."TP_SITUACAO", 'motivo_codigo', a."CO_MOTIVO_ELIMINACAO", 'motivo', a."DS_MOTIVO_ELIMINACAO",
             'art', a."VL_ART", 'nota', a."VL_NOTA_ORDEM", 'origem_nota', a."TP_ORIGEM_NOTA",
             'declarada', a."VL_NOTA_DECLARADA", 'divergente', a."ST_DIVERGENTE" = 'S', 'modalidade', a."NO_MODALIDADE",
             'declarada_congelada', a."VL_DECLARADA_CONGELADA", 'congelada_em', a."DT_CONGELAMENTO_DECLARADA",
             'posicao', a."NU_POSICAO", 'lote', a."NU_LOTE", 'entrada', a."TP_ENTRADA_LOTE",
             'motivo_entrada', a."DS_MOTIVO_ENTRADA",
             'decisao', case when d."CO_DECISAO_LOTE" is not null then jsonb_build_object(
               'motivo', d."DS_MOTIVO", 'por', coalesce(ud.nome, ud.email), 'em', d."DT_DECISAO",
               'situacao_regra', d."TP_SITUACAO_REGRA", 'motivo_regra', d."DS_MOTIVO_ELIMINACAO_REGRA") end)) as linha
      from pagina p
      join public."TB_PRE_CLASSIFICACAO" a on a."CO_MONITORAMENTO" = p_edital and a."CO_EMPREGARE_CANDIDATO" = p.id
      join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = a."CO_EMPREGARE_CANDIDATO"
      left join public."TB_DECISAO_LOTE" d
        on d."CO_MONITORAMENTO" = a."CO_MONITORAMENTO" and d."CO_EMPREGARE_CANDIDATO" = a."CO_EMPREGARE_CANDIDATO" and d."ST_ATIVO" = 'S'
      left join public."TB_PERFIL_USUARIO" ud on ud.user_id = d."CO_USUARIO_DECISAO"
  )
  select (select count(*) from filtrado),
         case when p_vaga is null then
           (select coalesce(jsonb_object_agg(x.vaga, x.n), '{}'::jsonb)
              from (select r.vaga, count(*) as n from filtrado r group by r.vaga) x) end,
         case when v_grupo = 'ELIMINADOS' then
           (select coalesce(jsonb_agg(jsonb_build_object('codigo', x.motivo_codigo, 'motivo', x.motivo, 'total', x.n)
                                      order by x.n desc, x.motivo_codigo), '[]'::jsonb)
              from (select r.motivo_codigo, min(r.motivo) as motivo, count(*) as n
                      from recorte r where r.motivo_codigo is not null group by r.motivo_codigo) x) end,
         (select coalesce(jsonb_agg(l.linha order by l.vaga collate "C", l.grupo, l.posicao, l.codigo), '[]'::jsonb) from linhas l),
         (select jsonb_build_object('vaga', l.vaga, 'grupo', l.grupo, 'posicao', l.posicao, 'codigo', l.codigo)
            from linhas l order by l.vaga collate "C" desc, l.grupo desc, l.posicao desc, l.codigo desc limit 1),
         (select count(*) from linhas)
    into v_total, v_por_vaga, v_por_motivo, v_linhas, v_ultimo, v_n;

  return json_build_object(
    'schema_version', 1,
    'edital', p_edital,
    'vaga', p_vaga,
    'grupo', v_grupo,
    'candidatos', v_linhas,
    'total', v_total,
    'por_vaga', v_por_vaga,
    -- Só nos eliminados: quantos por motivo no recorte (vaga e busca), sem o filtro de motivo.
    'por_motivo', v_por_motivo,
    'motivo', v_motivo,
    -- Página cheia: pode haver mais (a próxima chamada passa p_apos = proximo).
    'proximo', case when v_n = v_limite then v_ultimo end
  );
end;
$$;

--
-- Name: FUNCTION listar_pre_classificacao(p_edital uuid, p_vaga text, p_grupo text, p_busca text, p_apos jsonb, p_limite integer, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_pre_classificacao(p_edital uuid, p_vaga text, p_grupo text, p_busca text, p_apos jsonb, p_limite integer, p_motivo text) IS 'Inscritos da pré-classificação em páginas (até 500; a tela pede 50) por cursor estável: CLASSIFICADOS, ELIMINADOS ou PODE_INCLUIR, de uma vaga ou do edital, com busca e total; nos eliminados, p_motivo (código do motivo) recorta e por_motivo conta as opções (20261029210000). Coordenação do edital.';

--
-- Name: listar_presenca_online_monitora(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_presenca_online_monitora() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_user_id uuid := (select auth.uid());
  v_email text := coalesce((select auth.jwt() ->> 'email'), '');
begin
  if v_user_id is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;

  if not (
    private.is_master()
    or exists (
      select 1 from public."TB_PERFIL_USUARIO" p
       where p.ativo is true
         and lower(coalesce(p.perfil, '')) = 'edital_gestor'
         and (p.user_id = v_user_id or lower(p.email) = lower(v_email))
    )
  ) then
    raise exception 'Acesso restrito ao administrador global e ao Gestor.'
      using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(person) order by person."fullName", person."userId"), '[]'::jsonb)
    into v_result
    from (
      select po.user_id as "userId",
             coalesce(nullif(trim(p.nome), ''), split_part(coalesce(p.email, ''), '@', 1), 'Usuário AgSUS') as "fullName",
             coalesce(case when p.avatar_source in ('GOOGLE', 'UPLOADED') then p.avatar_url end,
                      p.google_avatar_url) as "avatarUrl",
             initcap(coalesce(nullif(p.perfil, ''), 'Usuário')) as "profileLabel",
             po.current_view as "currentView",
             po.seen_at as "onlineAt"
        from public."TB_PRESENCA_ONLINE_MONITORA" po
        join lateral (
          select profile.* from public."TB_PERFIL_USUARIO" profile
           where profile.ativo is true
             and (profile.user_id = po.user_id
                  or lower(profile.email) = lower(coalesce(
                    (select email from auth.users where id = po.user_id), '')))
           order by case when profile.user_id = po.user_id then 0 else 1 end,
                    profile.updated_at desc nulls last
           limit 1
        ) p on true
       where po.seen_at > timezone('utc', now()) - interval '6 minutes'
       order by po.seen_at desc
       limit 200
    ) person;
  return v_result;
end;
$$;

--
-- Name: FUNCTION listar_presenca_online_monitora(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_presenca_online_monitora() IS 'Quem está online agora: presença nos últimos 6 min (a batida é a cada 150 s; uma perdida não derruba ninguém). Só administrador global ou Gestor.';

--
-- Name: listar_prioridade_anexos_empregare(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_prioridade_anexos_empregare(p_vaga text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  -- As colunas "SITUAÇÃO - <questionário>" da exportação são as mesmas em toda a vaga:
  -- lidas uma vez (jsonb_each_text em cada linha custa ~0,7 ms com ~80 colunas).
  with chaves as (
    select coalesce(array_agg(k.key), '{}'::text[]) as questionario
      from (select c."DS_COLUNA_ORIGINAL" as col
              from public."TB_EMPREGARE_CANDIDATO" c
             where c."CO_VAGA" = p_vaga and c."ST_REGISTRO_ATIVO" = 'S'
             order by c."DT_ATUALIZACAO" desc
             limit 1) u,
           lateral jsonb_object_keys(coalesce(u.col, '{}'::jsonb)) k(key)
     where k.key ilike 'SITUAÇÃO - %'
  ),
  candidatos as (
    select c."CO_EMPREGARE_CANDIDATO" as id,
           btrim(c."CO_CANDIDATO_EMPREGARE") as codigo,
           (select count(*) from jsonb_object_keys(coalesce(c."DS_COLUNA_ORIGINAL", '{}'::jsonb)) pk(key)
             where pk.key ilike 'Pergunta%') as perguntas,
           private."FC_LIMITE_DA_RESPOSTA_EMPREGARE"(c."DS_COLUNA_ORIGINAL") as limite,
           upper(btrim(coalesce(c."DS_COLUNA_ORIGINAL" ->> 'SITUAÇÃO', ''))) as situacao,
           (select array_agg(upper(btrim(c."DS_COLUNA_ORIGINAL" ->> q.chave)))
              from unnest(h.questionario) q(chave)
             where c."DS_COLUNA_ORIGINAL" ? q.chave) as questionarios
      from public."TB_EMPREGARE_CANDIDATO" c
      cross join chaves h
     where p_vaga ~ '^[0-9]{1,20}$'
       and c."CO_VAGA" = p_vaga
       and c."ST_REGISTRO_ATIVO" = 'S'
       and c."CO_CANDIDATO_EMPREGARE" is not null
  ),
  pre as (
    select p."CO_EMPREGARE_CANDIDATO" as id,
           bool_or(p."TP_SITUACAO" = 'NO_LOTE') as no_lote,
           bool_or(p."TP_SITUACAO" = 'RANQUEADO') as ranqueado,
           bool_or(p."TP_SITUACAO" = 'ELIMINADO' and p."CO_MOTIVO_ELIMINACAO" in ('QUESTIONARIO', 'CANCELADO')) as sem_questionario
      from public."TB_PRE_CLASSIFICACAO" p
     where p."CO_EMPREGARE_CANDIDATO" in (select k.id from candidatos k)
     group by 1
  ),
  fichas as (
    select distinct f."CO_EMPREGARE_CANDIDATO" as id
      from public."TB_FICHA_ANALISE" f
     where f."CO_VAGA" = p_vaga and f."TP_SITUACAO" in ('PENDENTE', 'EM_ANALISE')
  ),
  -- Lida = capturada por inteiro (as perguntas lidas, somadas, cobrem as colunas "Pergunta N")
  -- E capturada depois da "DATA DE RESPOSTA" da exportação (a partir do dia seguinte): a
  -- resposta editada na Empregare depois da captura mantém o número e só assim é relida.
  lidas as (
    select r."CO_EMPREGARE_CANDIDATO" as id,
           jsonb_agg(r."CO_RESPOSTA_QUESTIONARIO" order by r."CO_RESPOSTA_QUESTIONARIO") as lidas
      from public."TB_EMPREGARE_RESPOSTA" r
      join candidatos k on k.id = r."CO_EMPREGARE_CANDIDATO"
     where r."QT_PERGUNTA" > 0
       and (k.limite is null or r."DT_CAPTURA" >= k.limite)
     group by r."CO_EMPREGARE_CANDIDATO", k.perguntas
    having sum(r."QT_PERGUNTA") >= k.perguntas
  ),
  classificados as (
    select k.codigo,
           case
             when coalesce(p.no_lote, false) or f.id is not null then 1
             when k.situacao = 'CANCELADO'
               or (k.questionarios is not null and not ('FINALIZADO' = any (k.questionarios)))
               or coalesce(p.sem_questionario, false)
               then 0
             when coalesce(p.ranqueado, false) then 2
             else 3
           end as prioridade,
           coalesce(l.lidas, '[]'::jsonb) as lidas
      from candidatos k
      left join pre p on p.id = k.id
      left join fichas f on f.id = k.id
      left join lidas l on l.id = k.id
  )
  select jsonb_build_object(
           'vaga', p_vaga,
           'candidatos', coalesce(jsonb_agg(jsonb_build_object('codigo', x.codigo, 'prioridade', x.prioridade,
                                                               'lidas', x.lidas)
                                            order by x.prioridade, x.codigo), '[]'::jsonb))
    from classificados x;
$_$;

--
-- Name: FUNCTION listar_prioridade_anexos_empregare(p_vaga text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_prioridade_anexos_empregare(p_vaga text) IS 'Para o robô da Empregare com --anexos: os candidatos ativos da vaga com a prioridade de leitura do questionário (GetRespostaDetails) e as respostas já lidas por inteiro (QT_PERGUNTA somado >= colunas "Pergunta N" da exportação) E capturadas depois da "DATA DE RESPOSTA" da exportação (FC_LIMITE_DA_RESPOSTA_EMPREGARE: a partir do dia seguinte; a resposta editada depois da captura fica de fora e é relida). Prioridade 1: NO_LOTE na pré-classificação ou ficha PENDENTE/EM_ANALISE; 2: RANQUEADO; 3: os demais; 0: pular (questionário não finalizado na coluna "SITUAÇÃO - …", inscrição cancelada ou eliminado por QUESTIONARIO/CANCELADO). Só leitura; só service_role. {vaga, candidatos: [{codigo, prioridade, lidas: [resposta]}]}.';

--
-- Name: listar_relatorio_de_motivos(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_relatorio_de_motivos(p_edital uuid, p_filtros jsonb DEFAULT '{}'::jsonb) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
declare
  v_f jsonb := case when jsonb_typeof(p_filtros) = 'object' then p_filtros else '{}'::jsonb end;
  v_blocos text[];
  v_situacoes text[];
  v_motivo text := nullif(btrim(v_f ->> 'motivo'), '');
  v_ajustada boolean := coalesce((v_f ->> 'ajustada')::boolean, false);
  v_resultados text[];
  v_situacoes_ficha text[];
  v_vagas text[];
  v_avaliador uuid;
  v_de date;
  v_ate date;
  v_apos uuid;
  v_limite integer;
  v_com_bloco boolean;
  v_fichas json;
  v_ultimo uuid;
  v_n integer;
  v_total integer;
  v_avaliadores json;
begin
  perform private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 3);
  if private."FC_PAPEL_AVALIACAO"(p_edital) is distinct from 'COORDENADOR' then
    raise exception 'Só o administrador e a coordenação do edital tiram o relatório de motivos'
      using errcode = '42501';
  end if;

  begin
    select array_agg(x) filter (where nullif(btrim(x), '') is not null) into v_blocos
      from jsonb_array_elements_text(coalesce(v_f -> 'blocos', '[]')) x;
    select array_agg(upper(x)) into v_situacoes from jsonb_array_elements_text(coalesce(v_f -> 'situacoes', '[]')) x;
    select array_agg(upper(x)) into v_resultados from jsonb_array_elements_text(coalesce(v_f -> 'resultados', '[]')) x;
    select array_agg(upper(x)) into v_situacoes_ficha from jsonb_array_elements_text(coalesce(v_f -> 'situacoes_ficha', '[]')) x;
    select array_agg(x) into v_vagas from jsonb_array_elements_text(coalesce(v_f -> 'vagas', '[]')) x;
    v_avaliador := nullif(btrim(v_f ->> 'avaliador'), '')::uuid;
    v_de := nullif(btrim(v_f ->> 'de'), '')::date;
    v_ate := nullif(btrim(v_f ->> 'ate'), '')::date;
    v_apos := nullif(btrim(v_f ->> 'apos'), '')::uuid;
    v_limite := least(greatest(coalesce((v_f ->> 'limite')::integer, 500), 1), 500);
  exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow
                 or invalid_parameter_value or numeric_value_out_of_range then
    raise exception 'Filtros inválidos: %', sqlerrm using errcode = '22023';
  end;

  if v_situacoes is not null and not v_situacoes <@ array['CONFORME', 'NAO_CONFORME', 'NAO_ENVIADO', 'NAO_SE_APLICA'] then
    raise exception 'Situação do bloco inválida: use CONFORME, NAO_CONFORME, NAO_ENVIADO ou NAO_SE_APLICA'
      using errcode = '22023';
  end if;
  if v_resultados is not null and not v_resultados <@ array['APTO', 'INAPTO_REQUISITO', 'INAPTO_NOTA'] then
    raise exception 'Resultado inválido: use APTO, INAPTO_REQUISITO ou INAPTO_NOTA' using errcode = '22023';
  end if;
  if v_situacoes_ficha is not null
     and not v_situacoes_ficha <@ array['PENDENTE', 'EM_ANALISE', 'REVISAR', 'CONCLUIDA', 'FORA_LOTE'] then
    raise exception 'Situação da ficha inválida' using errcode = '22023';
  end if;
  if cardinality(v_blocos) > 50 or cardinality(v_vagas) > 500 then
    raise exception 'Filtros grandes demais (até 50 blocos e 500 vagas)' using errcode = '22023';
  end if;

  v_com_bloco := v_blocos is not null or v_situacoes is not null or v_motivo is not null or v_ajustada;

  with fichas as (
    select f."CO_FICHA_ANALISE" as id, f."CO_EMPREGARE_CANDIDATO", f."CO_VAGA", f."TP_SITUACAO",
           f."TP_RESULTADO", f."VL_NOTA_FINAL", f."DT_CONCLUSAO",
           coalesce(f."CO_USUARIO_CONCLUSAO", f."CO_USUARIO_RESPONSAVEL") as avaliador,
           case when jsonb_typeof(f."DS_LANCAMENTO" -> 'blocos') = 'object'
                then f."DS_LANCAMENTO" -> 'blocos' else '{}'::jsonb end as lancados
      from public."TB_FICHA_ANALISE" f
     where f."CO_MONITORAMENTO" = p_edital
       and (case when v_situacoes_ficha is null then f."TP_SITUACAO" <> 'FORA_LOTE'
                 else f."TP_SITUACAO" = any (v_situacoes_ficha) end)
       and (v_resultados is null or f."TP_RESULTADO" = any (v_resultados))
       and (v_vagas is null or f."CO_VAGA" = any (v_vagas))
       and (v_avaliador is null or coalesce(f."CO_USUARIO_CONCLUSAO", f."CO_USUARIO_RESPONSAVEL") = v_avaliador)
       and (v_de is null or (f."DT_CONCLUSAO" at time zone 'America/Sao_Paulo')::date >= v_de)
       and (v_ate is null or (f."DT_CONCLUSAO" at time zone 'America/Sao_Paulo')::date <= v_ate)
  ),
  -- Os blocos de cada ficha (com o bloco escolhido que falta na concluída como NAO_SE_APLICA).
  blocos as (
    select x.id, x.codigo, x.b,
           coalesce(nullif(x.b ->> 'situacao', ''), 'NAO_SE_APLICA') as situacao
      from (select fi.id, e.key as codigo, e.value as b
              from fichas fi, jsonb_each(fi.lancados) e
             where jsonb_typeof(e.value) = 'object'
               and (v_blocos is null or e.key = any (v_blocos))
            union all
            select fi.id, k, '{}'::jsonb
              from fichas fi, unnest(v_blocos) k
             where fi."TP_SITUACAO" = 'CONCLUIDA' and not (fi.lancados ? k)) x
  ),
  casados as (
    select bl.id, bl.codigo,
           jsonb_strip_nulls(jsonb_build_object(
             'situacao', bl.situacao,
             'motivos', case when jsonb_typeof(bl.b -> 'motivos') = 'array' and bl.b -> 'motivos' <> '[]'
                             then bl.b -> 'motivos' end,
             'motivo_livre', nullif(btrim(bl.b ->> 'motivo_livre'), ''),
             'justificativas', case when jsonb_typeof(bl.b -> 'justificativas') = 'array' and bl.b -> 'justificativas' <> '[]'
                                    then bl.b -> 'justificativas' end,
             'nota_ajustada', bl.b -> 'nota_ajustada')) as resumo
      from blocos bl
     where (v_situacoes is null or bl.situacao = any (v_situacoes))
       and (v_motivo is null
            or (jsonb_typeof(bl.b -> 'motivos') = 'array' and bl.b -> 'motivos' ? v_motivo)
            or (jsonb_typeof(bl.b -> 'justificativas') = 'array' and bl.b -> 'justificativas' ? v_motivo))
       and (not v_ajustada
            or (jsonb_typeof(bl.b -> 'justificativas') = 'array' and bl.b -> 'justificativas' <> '[]'))
       and (v_com_bloco
            or (jsonb_typeof(bl.b -> 'motivos') = 'array' and bl.b -> 'motivos' <> '[]')
            or (jsonb_typeof(bl.b -> 'justificativas') = 'array' and bl.b -> 'justificativas' <> '[]')
            or nullif(btrim(bl.b ->> 'motivo_livre'), '') is not null)
  ),
  por_ficha as (
    select c.id, jsonb_object_agg(c.codigo, c.resumo) as blocos
      from casados c
     group by c.id
  ),
  filtradas as (
    select fi.*, coalesce(pf.blocos, '{}'::jsonb) as blocos
      from fichas fi
      left join por_ficha pf on pf.id = fi.id
     where not v_com_bloco or pf.id is not null
  ),
  pagina as (
    select fl.* from filtradas fl
     where v_apos is null or fl.id > v_apos
     order by fl.id
     limit v_limite
  )
  select (select json_agg(json_build_object(
            'id', p.id,
            'codigo', c."CO_CANDIDATO_EMPREGARE",
            'nome', c."NO_CANDIDATO",
            'vaga', p."CO_VAGA",
            'cargo', pv."NO_CARGO",
            'lotacao', pv."NO_LOTACAO",
            'situacao', p."TP_SITUACAO",
            'resultado', p."TP_RESULTADO",
            'nota_final', p."VL_NOTA_FINAL",
            'avaliador', pu.nome,
            'concluida_em', p."DT_CONCLUSAO",
            'blocos', p.blocos)
            order by p.id)
            from pagina p
            join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = p."CO_EMPREGARE_CANDIDATO"
            left join public."TB_PRE_CLASSIF_VAGA" pv
              on pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" = p."CO_VAGA"
            left join public."TB_PERFIL_USUARIO" pu on pu.user_id = p.avaliador),
         (select max(p.id::text)::uuid from pagina p),
         (select count(*) from pagina),
         case when v_apos is null then (select count(*) from filtradas) end
    into v_fichas, v_ultimo, v_n, v_total;

  if v_apos is null then
    select coalesce(json_agg(json_build_object('usuario', a.avaliador, 'nome', coalesce(pu.nome, 'Sem cadastro'))
                             order by coalesce(pu.nome, 'Sem cadastro')), '[]'::json)
      into v_avaliadores
      from (select distinct coalesce(f."CO_USUARIO_CONCLUSAO", f."CO_USUARIO_RESPONSAVEL") as avaliador
              from public."TB_FICHA_ANALISE" f
             where f."CO_MONITORAMENTO" = p_edital
               and coalesce(f."CO_USUARIO_CONCLUSAO", f."CO_USUARIO_RESPONSAVEL") is not null) a
      left join public."TB_PERFIL_USUARIO" pu on pu.user_id = a.avaliador;
  end if;

  return json_build_object(
    'schema_version', 1,
    'fichas', coalesce(v_fichas, '[]'::json),
    'total', v_total,
    'avaliadores', v_avaliadores,
    -- Página cheia: pode haver mais (a próxima chamada passa apos = proximo).
    'proximo', case when v_n = v_limite then v_ultimo end
  );
end;
$$;

--
-- Name: FUNCTION listar_relatorio_de_motivos(p_edital uuid, p_filtros jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_relatorio_de_motivos(p_edital uuid, p_filtros jsonb) IS 'Relatório de motivos da avaliação documental (20261020120000): fichas do edital filtradas por bloco da regra, situação do bloco, motivo (OUTRO = Outro motivo), justificativa de nota, resultado, situação da ficha, vaga, avaliador e período de conclusão (p_filtros jsonb). Só as colunas do relatório: código e nome do candidato (sem CPF, e-mail ou telefone), vaga, cargo, lotação, situação, resultado, nota final, quem concluiu e quando, e os blocos reduzidos a situação, motivos, motivo_livre, justificativas e nota_ajustada. Páginas de até 500 pela chave da ficha (apos = proximo da anterior); total e avaliadores na primeira página. Só administrador e coordenação do edital (FC_PAPEL_AVALIACAO = COORDENADOR; 42501). Não grava nada.';

--
-- Name: listar_resumos_pergunta_pendentes(text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_resumos_pergunta_pendentes(p_editais text[] DEFAULT NULL::text[], p_forcar boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if cardinality(p_editais) > 200 then
    raise exception 'Até 200 editais' using errcode = '22023';
  end if;
  return (
    with com_carga as (
      select m.id, m.edital, private."FC_HASH_VAGA_EDITAL"(m.id) as hash
        from public."TB_MONITORAMENTO_INDIGENA" m
       where exists (select 1 from public."TB_EMPREGARE_VAGA" v
                      where v."CO_MONITORAMENTO" = m.id and v."TP_SITUACAO" = 'GRAVADA')
         and (p_editais is null or private."FC_NUMERO_EDITAL"(m.edital) = any (p_editais))
    )
    select jsonb_build_object('editais', coalesce(jsonb_agg(jsonb_build_object(
             'edital', e.id,
             'numero', private."FC_NUMERO_EDITAL"(e.edital),
             'hash', e.hash,
             'vagas', (select jsonb_agg(v."CO_VAGA" order by v."CO_VAGA")
                         from public."TB_EMPREGARE_VAGA" v
                        where v."CO_MONITORAMENTO" = e.id and v."TP_SITUACAO" = 'GRAVADA'),
             'colunas', coalesce((
               select jsonb_agg(distinct c.coluna)
                 from public."TB_EMPREGARE_VAGA" v,
                      lateral jsonb_array_elements_text(v."DS_COLUNA") c(coluna)
                where v."CO_MONITORAMENTO" = e.id and v."TP_SITUACAO" = 'GRAVADA'
                  and c.coluna ilike 'Pergunta %'), '[]'::jsonb))
             order by e.edital), '[]'::jsonb))
      from com_carga e
      left join public."TB_RESUMO_PERGUNTA_EDITAL" s on s."CO_MONITORAMENTO" = e.id
     where coalesce(p_forcar, false) or s."DS_HASH_VAGA" is distinct from e.hash);
end;
$$;

--
-- Name: FUNCTION listar_resumos_pergunta_pendentes(p_editais text[], p_forcar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_resumos_pergunta_pendentes(p_editais text[], p_forcar boolean) IS 'Robô da Empregare (resumo_das_perguntas.py): os editais com carga GRAVADA cujo resumo das perguntas falta ou está velho (assinatura das vagas mudou) — ou todos, com p_forcar —, filtrados pelos números (p_editais, até 200). Por edital: id, número, assinatura, vagas e as colunas de pergunta. Só service_role.';

--
-- Name: listar_roteiros_entrevista(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_roteiros_entrevista(p_area text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.pode_recurso('entrevistas', 1) then
    raise exception 'Sem permissão para Entrevistas' using errcode = '42501';
  end if;
  return coalesce((
    select json_agg(private."FC_ROTEIRO_JSON"(r."CO_ROTEIRO") order by r."NO_ROTEIRO")
      from public."TB_ROTEIRO_ENTREVISTA" r
     where r."ST_ATIVO" = 'S'
       and (p_area is null or r."CO_AREA" is null or r."CO_AREA" = p_area)), '[]'::json);
end;
$$;

--
-- Name: FUNCTION listar_roteiros_entrevista(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_roteiros_entrevista(p_area text) IS 'Roteiros de entrevista ativos (última versão de cada), da área pedida ou de qualquer área.';

--
-- Name: listar_solicitacoes_acesso(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_solicitacoes_acesso(p_status text DEFAULT 'pendente'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_gestor text := private."FC_EXIGIR_GESTOR_DE_ACESSOS"();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', s.id, 'user_id', s.user_id, 'email', s.email, 'nome', s.nome, 'setor', s.setor,
      'justificativa', s.justificativa, 'status', s.status, 'created_at', s.created_at,
      'updated_at', s.updated_at,
      'observacao_admin', s.observacao_admin, 'coordenacao', s."CO_COORDENACAO",
      'coordenacao_nome', c."NO_COORDENACAO", 'area', coalesce(s."CO_AREA", c."CO_AREA"),
      'area_nome', ar."NO_AREA",
      'cargo', s."CO_CARGO_SOLICITADO",
      'cargo_rotulo', private."FC_CARGO_SOLICITACAO_ACESSO"(null, s."CO_CARGO_SOLICITADO"),
      'cargo_outro', s."DS_CARGO_OUTRO",
      'reativacao', p.id is not null,
      'desativada_em', h.alterado_em,
      'desativada_por', h.autor,
      'motivo_desativacao', h.motivo,
      'grupo_anterior', p.perfil
    ) order by s.created_at)
      from public."TB_SOLICITACAO_ACESSO" s
      left join public."TB_COORDENACAO" c on c."CO_COORDENACAO" = s."CO_COORDENACAO"
      left join public."TB_AREA" ar on ar."CO_AREA" = coalesce(s."CO_AREA", c."CO_AREA")
      -- Pedido de quem tem conta desativada = pedido de reativação (com o histórico).
      left join lateral (
        select u.id, u.perfil from public."TB_PERFIL_USUARIO" u
         where not u.ativo
           and ((s.user_id is not null and u.user_id = s.user_id) or lower(u.email) = lower(s.email))
         order by u.updated_at desc limit 1) p on true
      left join lateral (
        select t.alterado_em, t.motivo,
               (select a.email from public."TB_PERFIL_USUARIO" a where a.user_id = t.alterado_por limit 1) autor
          from public."TH_PERMISSAO_RECURSO" t
         where p.id is not null and t.perfil_usuario_id = p.id and t.recurso = '#conta'
         order by t.alterado_em desc limit 1) h on true
     where s.status = coalesce(nullif(btrim(p_status), ''), 'pendente')
       and (v_gestor = 'admin' or s."CO_COORDENACAO" = private."FC_COORDENACAO_USUARIO"())
     limit 200), '[]'::jsonb);
end;
$$;

--
-- Name: FUNCTION listar_solicitacoes_acesso(p_status text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_solicitacoes_acesso(p_status text) IS 'Pedidos de acesso (admin global: todos; coordenador: os da própria coordenação), com área, cargo, lotação (setor), justificativa e dados da reativação.';

--
-- Name: listar_unidades_por_area(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_unidades_por_area() RETURNS TABLE(unidade text, area text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r."NO_UNIDADE", r."CO_AREA"
    from public."TA_UNIDADE_AREA" r
   where (select auth.uid()) is not null
   order by r."CO_AREA", r."NO_UNIDADE";
$$;

--
-- Name: FUNCTION listar_unidades_por_area(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_unidades_por_area() IS 'Unidades com área definida (TA_UNIDADE_AREA). Unidade do catálogo TD_UNIDADE fora daqui é da Saúde Indígena.';

--
-- Name: listar_vagas_dos_robos(uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_vagas_dos_robos(p_editais uuid[] DEFAULT NULL::uuid[], p_vagas text[] DEFAULT NULL::text[]) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_editais uuid[] := coalesce(p_editais, '{}');
  v_vagas text[] := coalesce(p_vagas, '{}');
begin
  if not private.is_master() then
    raise exception 'Somente o administrador global vê o painel dos robôs' using errcode = '42501';
  end if;
  if cardinality(v_editais) > 100 or cardinality(v_vagas) > 500 then
    raise exception 'Até 100 editais e 500 vagas por consulta' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_vagas) v where v !~ '^[0-9]{1,20}$') then
    raise exception 'Código de vaga inválido: use só dígitos' using errcode = '22023';
  end if;
  if cardinality(v_editais) = 0 and cardinality(v_vagas) = 0 then
    return '[]'::json;
  end if;

  return (
    with quadro as (
      select q.vaga, q.edital_id, q.cargo, 1 as prioridade
        from private."FC_EMPREGARE_VAGAS_DO_QUADRO"() q
    ),
    selecao as (
      select s."CO_VAGA" as vaga, s."CO_MONITORAMENTO" as edital_id, s."NO_CARGO" as cargo, 2 as prioridade
        from public."TB_SELECAO_VAGA" s
       where s."ST_REGISTRO_ATIVO" = 'S' and s."CO_VAGA" ~ '^[0-9]{1,20}$'
    ),
    carregadas as (
      select v."CO_VAGA" as vaga, v."CO_MONITORAMENTO" as edital_id, null::text as cargo, 3 as prioridade
        from public."TB_EMPREGARE_VAGA" v
    ),
    todas as (
      select distinct on (f.vaga) f.vaga, f.edital_id, f.cargo
        from (select * from quadro union all select * from selecao union all select * from carregadas) f
       order by f.vaga, (f.edital_id is null), f.prioridade
    )
    select coalesce(json_agg(json_build_object(
             'vaga', t.vaga, 'edital_id', t.edital_id,
             'cargo', coalesce(t.cargo, (select min(s."NO_CARGO") from public."TB_SELECAO_VAGA" s
                                          where s."CO_VAGA" = t.vaga)),
             'ultima_carga', ev."DT_ULTIMA_CARGA", 'situacao', ev."TP_SITUACAO",
             'ativos', ev."QT_CANDIDATO_ATIVO")
           order by t.vaga), '[]'::json)
      from todas t
      left join public."TB_EMPREGARE_VAGA" ev on ev."CO_VAGA" = t.vaga
     where t.edital_id = any (v_editais) or t.vaga = any (v_vagas)
  );
end;
$_$;

--
-- Name: FUNCTION listar_vagas_dos_robos(p_editais uuid[], p_vagas text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_vagas_dos_robos(p_editais uuid[], p_vagas text[]) IS 'Vagas da Empregare conhecidas dos editais pedidos (p_editais, ids) ou dos códigos pedidos (p_vagas, só dígitos), das mesmas fontes do robô (quadro do edital, Seleção) e das já carregadas (TB_EMPREGARE_VAGA): código, edital, cargo, última carga, situação e ativos. Sugestões do "Rodar com opções" (Status das atualizações, só administrador global). Até 100 editais e 500 vagas; sem filtro, lista vazia.';

--
-- Name: listar_vagas_empregare(text[], text[], integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_vagas_empregare(p_editais text[] DEFAULT NULL::text[], p_vagas text[] DEFAULT NULL::text[], p_limite integer DEFAULT 60, p_finalidade text DEFAULT 'carga'::text, p_liberacao uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_limite integer := least(greatest(coalesce(p_limite, 60), 1), 500);
  v_vagas text[] := coalesce(p_vagas, '{}');
  v_editais text[];
  v_modo text;
  v_finalidade text := coalesce(nullif(btrim(p_finalidade), ''), 'carga');
begin
  if v_finalidade not in ('carga', 'anexos') then
    raise exception 'Finalidade inválida: carga ou anexos' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_vagas) v where v !~ '^[0-9]{1,20}$') then
    raise exception 'Código de vaga inválido: use só dígitos' using errcode = '22023';
  end if;
  select coalesce(array_agg(distinct private."FC_NUMERO_EDITAL"(e)), '{}') into v_editais
    from unnest(coalesce(p_editais, '{}')) e;
  if exists (select 1 from unnest(v_editais) e where e is null) then
    raise exception 'Edital inválido: use o número, como 80/2026' using errcode = '22023';
  end if;
  v_modo := case when cardinality(v_vagas) > 0 then 'VAGAS'
                 when cardinality(v_editais) > 0 then 'EDITAIS'
                 else 'PADRAO' end;

  return (
    with quadro as (
      select q.vaga, m.id as edital_id, m.edital, m.unidade, q.cargo, m."CO_AREA" as area,
             m.ativo as edital_ativo, 'quadro'::text as origem
        from private."FC_EMPREGARE_VAGAS_DO_QUADRO"() q
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = q.edital_id
    ),
    selecao as (
      select distinct on (s."CO_VAGA")
             s."CO_VAGA" as vaga, s."CO_MONITORAMENTO" as edital_id, s."DS_EDITAL" as edital,
             s."NO_UNIDADE" as unidade, s."NO_CARGO" as cargo, s."CO_AREA" as area,
             m.ativo as edital_ativo, 'selecao'::text as origem
        from public."TB_SELECAO_VAGA" s
        left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = s."CO_MONITORAMENTO"
       where s."ST_REGISTRO_ATIVO" = 'S' and s."CO_VAGA" is not null
       order by s."CO_VAGA", (s."CO_MONITORAMENTO" is null), s."DT_ATUALIZACAO" desc
    ),
    -- Vagas já ligadas ao edital na Empregare (correção de dados ou carga anterior):
    -- o edital em inscrição ainda não tem análise (código do quadro) nem Seleção.
    ligadas as (
      select v."CO_VAGA" as vaga, m.id as edital_id, m.edital, m.unidade, null::text as cargo,
             m."CO_AREA" as area, m.ativo as edital_ativo, 'ligada'::text as origem
        from public."TB_EMPREGARE_VAGA" v
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = v."CO_MONITORAMENTO"
    ),
    -- Mesmo código em mais de uma fonte: fica a do quadro, depois a da Seleção.
    fontes as (
      select f.*,
             (select max(coalesce(c.data_fim, c.data_inicio)::date)
                from public."TB_CRONOGRAMA_MONIT_INDIG" c
               where c.monitoramento_id = f.edital_id) as fim_do_cronograma
        from (select * from quadro
              union all
              select s.* from selecao s where not exists (select 1 from quadro q where q.vaga = s.vaga)
              union all
              select l.* from ligadas l
               where not exists (select 1 from quadro q where q.vaga = l.vaga)
                 and not exists (select 1 from selecao s where s.vaga = l.vaga)) f
    ),
    escolhidas as (
      select s.vaga, s.edital_id, s.edital, s.unidade, s.cargo, s.area, s.origem
        from fontes s
       where (v_modo = 'VAGAS' and s.vaga = any (v_vagas))
          or (v_modo = 'EDITAIS' and private."FC_NUMERO_EDITAL"(s.edital) = any (v_editais))
          or (v_modo = 'PADRAO' and s.edital_ativo is true
              and not private."FC_EDITAL_EH_TREINAMENTO"(s.edital_id)
              and (s.fim_do_cronograma is null or s.fim_do_cronograma >= current_date - 30))
      union all
      -- Código pedido que não está em nenhuma fonte: vai mesmo assim, sem edital.
      select v, null::uuid, null, null, null, null, 'pedida'
        from unnest(v_vagas) v
       where v_modo = 'VAGAS' and not exists (select 1 from fontes s where s.vaga = v)
    ),
    -- [congeladas] Edital com inscrições congeladas (20261020170000): fica fora da carga,
    -- salvo liberação válida do administrador global; no modo "só anexos" nada sai.
    marcadas as (
      select e.*,
             e.edital_id is not null and private."FC_INSCRICOES_CONGELADAS"(e.edital_id) as congelada,
             e.edital_id is not null and private."FC_LIBERACAO_CONGELAMENTO_VALIDA"(p_liberacao, e.edital_id) as liberada
        from escolhidas e
    ),
    ordenadas as (
      select m.*, ev."DT_ULTIMA_CARGA" as ultima_carga
        from marcadas m
        left join public."TB_EMPREGARE_VAGA" ev on ev."CO_VAGA" = m.vaga
       where v_finalidade = 'anexos' or not m.congelada or m.liberada
       order by ev."DT_ULTIMA_CARGA" nulls first, m.edital nulls last, m.vaga
       limit v_limite
    )
    select jsonb_build_object(
      'modo', v_modo,
      'limite', v_limite,
      'finalidade', v_finalidade,
      'vagas', coalesce((
        select jsonb_agg(jsonb_build_object(
            'vaga', o.vaga, 'edital_id', o.edital_id, 'edital', o.edital, 'unidade', o.unidade,
            'cargo', o.cargo, 'area', o.area, 'ultima_carga', o.ultima_carga, 'origem', o.origem,
            'congelada', o.congelada, 'liberada', o.congelada and o.liberada
          ) order by o.ultima_carga nulls first, o.edital nulls last, o.vaga)
          from ordenadas o), '[]'::jsonb),
      -- O que ficou de fora: por edital, quantas vagas e se veio explícito no pedido.
      'congeladas', coalesce((
        select jsonb_agg(jsonb_build_object(
            'edital_id', c.edital_id, 'edital', c.edital, 'vagas', c.vagas, 'pedido', v_modo <> 'PADRAO')
          order by c.edital)
          from (select m.edital_id, min(m.edital) as edital, count(*) as vagas
                  from marcadas m
                 where v_finalidade = 'carga' and m.congelada and not m.liberada
                 group by m.edital_id) c), '[]'::jsonb)
    )
  );
end;
$_$;

--
-- Name: FUNCTION listar_vagas_empregare(p_editais text[], p_vagas text[], p_limite integer, p_finalidade text, p_liberacao uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.listar_vagas_empregare(p_editais text[], p_vagas text[], p_limite integer, p_finalidade text, p_liberacao uuid) IS 'Robô da Empregare (service_role): as vagas a carregar, de três fontes — o quadro de vagas do edital (código pelas análises do edital), a Seleção (TB_SELECAO_VAGA) e as vagas já ligadas ao edital em TB_EMPREGARE_VAGA (origem ligada). Sem filtro: editais ativos e em curso (fim do cronograma há até 30 dias), sem o treinamento; p_editais pelos números; p_vagas pelos códigos (fora das fontes: origem pedida, sem edital). As nunca carregadas e as mais antigas primeiro, até p_limite. Inscrições congeladas (20261020170000): com p_finalidade = carga (padrão), as vagas de edital congelado saem da lista e voltam em "congeladas" ({edital_id, edital, vagas, pedido}; pedido = veio explícito em p_editais/p_vagas, o robô recusa), salvo p_liberacao válida para o edital (override do administrador global); com p_finalidade = anexos (modo "só anexos") nada sai e cada vaga diz se está congelada.';

--
-- Name: mandar_fichas_revisao(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mandar_fichas_revisao(p_edital uuid, p_fichas jsonb, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_FICHAS"(p_edital);
  v_uid uuid := (select auth.uid());
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_item record;
  v_f public."TB_FICHA_ANALISE";
  v_qt integer;
  v_codigo text;
begin
  if jsonb_typeof(p_fichas) is distinct from 'array' or jsonb_array_length(p_fichas) not between 1 and 5000 then
    raise exception 'Escolha de 1 a 5.000 fichas.' using errcode = '22023';
  end if;
  if v_motivo is null or length(v_motivo) not between 10 and 2000 or not private."FC_MOTIVO_PARECE_TEXTO"(v_motivo, 2) then
    raise exception 'Informe o motivo para mandar para revisão (10 a 2.000 caracteres, com pelo menos 2 palavras).' using errcode = '22023';
  end if;
  begin
    select count(*) into v_qt
      from jsonb_to_recordset(p_fichas) x(ficha uuid, versao integer)
      left join public."TB_FICHA_ANALISE" f on f."CO_FICHA_ANALISE" = x.ficha and f."CO_MONITORAMENTO" = p_edital
     where f."CO_FICHA_ANALISE" is null or f."NU_VERSAO" is distinct from x.versao;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'Ficha com id ou versão inválida' using errcode = '22023';
  end;
  if v_qt > 0 then
    raise exception '% ficha(s) mudaram desde que você abriu a fila; atualize e confira.', v_qt using errcode = 'PT409';
  end if;
  for v_item in select x.ficha from jsonb_to_recordset(p_fichas) x(ficha uuid, versao integer) order by x.ficha loop
    select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = v_item.ficha for update;
    if v_f."TP_SITUACAO" not in ('PENDENTE', 'EM_ANALISE') then
      select c."CO_CANDIDATO_EMPREGARE" into v_codigo from public."TB_EMPREGARE_CANDIDATO" c
       where c."CO_EMPREGARE_CANDIDATO" = v_f."CO_EMPREGARE_CANDIDATO";
      raise exception 'A ficha % não está pendente nem em análise.', v_codigo using errcode = '22023';
    end if;
    update public."TB_FICHA_ANALISE" set
      "TP_SITUACAO" = 'REVISAR', "CO_USUARIO_RESERVA" = null, "DT_RESERVA" = null, "DT_RESERVA_EXPIRA" = null,
      "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
     where "CO_FICHA_ANALISE" = v_item.ficha;
    perform private."FC_HISTORICO_FICHA"(v_item.ficha, 'REVISAR', v_f."TP_SITUACAO", v_f."CO_USUARIO_RESPONSAVEL", v_motivo, v_uid);
  end loop;
  return json_build_object('alteradas', jsonb_array_length(p_fichas));
end;
$$;

--
-- Name: FUNCTION mandar_fichas_revisao(p_edital uuid, p_fichas jsonb, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mandar_fichas_revisao(p_edital uuid, p_fichas jsonb, p_motivo text) IS 'A coordenação manda fichas pendentes ou em análise para revisão (situação REVISAR; a reserva cai), com motivo de 10 a 2.000. p_fichas [{ficha, versao}]: versão velha em qualquer uma = 40001 e nada grava. A validação ou devolução pelo revisor é da fase F5.';

--
-- Name: manter_linha_da_pessoa_repetida(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manter_linha_da_pessoa_repetida(p_pendencia uuid, p_candidato uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_PENDENCIA_APROVADO"%rowtype;
  v_fica public."TB_CANDIDATO_APROVADO"%rowtype;
  v_alteracoes jsonb;
  v_contratado boolean;
begin
  v := private."FC_PENDENCIA_PARA_DECIDIR"(p_pendencia, array['PESSOA_REPETIDA'], p_motivo);
  -- Sem linha escolhida: são pessoas diferentes, todas ficam (a pendência não volta).
  if p_candidato is null then
    return private."FC_FECHAR_PENDENCIA"(p_pendencia, 'PESSOAS_DIFERENTES', p_motivo, '[]'::jsonb);
  end if;
  select * into v_fica from public."TB_CANDIDATO_APROVADO" c
   where c.id = p_candidato and c.id = any (v."CO_CANDIDATO_APROVADO");
  if not found then
    raise exception 'Escolha uma das linhas da pendência' using errcode = '22023';
  end if;
  if v_fica.status is null and exists (
       select 1 from public."TB_CANDIDATO_APROVADO" c
        where c.id = any (v."CO_CANDIDATO_APROVADO") and c.id <> p_candidato and c.status is not null) then
    raise exception 'A linha que sai tem status: mantenha a linha com status' using errcode = '22023';
  end if;

  select exists (select 1 from public."TB_CANDIDATO_APROVADO" c
                  where c.id = any (v."CO_CANDIDATO_APROVADO") and c.id <> p_candidato and c.status = 'Contratado')
    into v_contratado;
  -- A remoção lógica que a lista já tem: nada se apaga.
  with removidas as (
    update public."TB_CANDIDATO_APROVADO" c
       set removido_em = now(), removido_por = (select auth.uid()), updated_by = (select auth.uid()), updated_at = now()
     where c.id = any (v."CO_CANDIDATO_APROVADO") and c.id <> p_candidato and c.removido_em is null
    returning c.id
  )
  select coalesce(jsonb_agg(jsonb_build_object('candidato', r.id, 'campo', 'removido', 'antes', false, 'depois', true)
                            order by r.id), '[]'::jsonb)
    into v_alteracoes from removidas r;
  -- Saiu uma linha Contratado: a decisão do "Contratado em outra lista" do edital é refeita.
  if v_contratado then
    delete from public."TB_CONTRATACAO_APROVADO" x where x."CO_MONITORAMENTO" = v."CO_MONITORAMENTO"
       and x."DS_VINCULO" in (select private."FC_VINCULO_DA_MATRICULA"(c.matricula) from public."TB_CANDIDATO_APROVADO" c
                               where c.id = any (v."CO_CANDIDATO_APROVADO") and c.status = 'Contratado');
    perform private."FC_PEDIR_CONTRATACAO_DOS_APROVADOS"();
  end if;
  return private."FC_FECHAR_PENDENCIA"(p_pendencia, 'LINHA_MANTIDA', p_motivo, v_alteracoes);
end;
$$;

--
-- Name: FUNCTION manter_linha_da_pessoa_repetida(p_pendencia uuid, p_candidato uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.manter_linha_da_pessoa_repetida(p_pendencia uuid, p_candidato uuid, p_motivo text) IS 'Pendência "Pessoa repetida": a linha escolhida fica e as outras saem pela remoção lógica (removido_em/removido_por); sem linha escolhida, são pessoas diferentes e todas ficam (não volta). Não deixa sair a linha com status para ficar a sem status. Quem decide (FC_PODE_DECIDIR_PENDENCIA), com motivo; histórico e contratados. 20261026190000.';

--
-- Name: marcar_candidatos_convocados(uuid[], date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_candidatos_convocados(p_candidatos uuid[], p_data_convocacao date DEFAULT NULL::date, p_carta uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_data date := coalesce(p_data_convocacao, (now() at time zone 'America/Sao_Paulo')::date);
  v_ids uuid[];
  v_c record;
  v_marcados integer := 0;
  v_ignorados jsonb := '[]'::jsonb;
begin
  if not private.pode_recurso('aprovados', 2) then
    raise exception 'Perfil sem permissao para alterar status' using errcode = '42501';
  end if;
  select array_agg(distinct x) into v_ids from unnest(coalesce(p_candidatos, '{}'::uuid[])) x where x is not null;
  if coalesce(array_length(v_ids, 1), 0) = 0 then
    raise exception 'Escolha ao menos um candidato.' using errcode = '22023';
  end if;
  if array_length(v_ids, 1) > 500 then
    raise exception 'No máximo 500 candidatos por vez.' using errcode = '22023';
  end if;
  if v_data > v_hoje then
    raise exception 'A data da convocação não pode ser futura' using errcode = '22023';
  end if;
  if p_carta is not null and not exists (
    select 1 from public."TH_CARTA_CONVOCACAO" where "CO_CARTA_CONVOCACAO" = p_carta
  ) then
    raise exception 'Carta de convocação não encontrada' using errcode = '22023';
  end if;

  -- Área e recorte de cada edital antes de mudar qualquer um (tudo ou nada).
  perform private."FC_EXIGIR_AREA_EDITAL"(l.edital_id)
     from public."TB_CANDIDATO_APROVADO" c
     join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
    where c.id = any (v_ids);

  for v_c in
    select c.id, c.nome, c.status, c.lista_id, c."DT_CONVOCACAO", l.vigente, l.ativo
      from public."TB_CANDIDATO_APROVADO" c
      join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
     where c.id = any (v_ids) and c.removido_em is null
     order by c.id
       for update of c
  loop
    if not v_c.vigente or not v_c.ativo then
      v_ignorados := v_ignorados || jsonb_build_object('candidato_id', v_c.id, 'nome', v_c.nome, 'motivo', 'Lista inativa ou substituída');
    elsif v_c.status is not null and v_c.status <> 'Convocado' then
      v_ignorados := v_ignorados || jsonb_build_object('candidato_id', v_c.id, 'nome', v_c.nome, 'motivo', 'Já está como ' || v_c.status);
    else
      insert into public."TH_CANDIDATO_APROVADO"(
        candidato_id, lista_id, status_anterior, status_novo, alterado_por, "DT_CONVOCACAO", "CO_CARTA_CONVOCACAO"
      ) values (
        v_c.id, v_c.lista_id, v_c.status, 'Convocado', (select auth.uid()), v_data, p_carta
      );
      update public."TB_CANDIDATO_APROVADO"
         set status = 'Convocado', matricula = null, "DT_CONVOCACAO" = v_data,
             updated_by = (select auth.uid()), updated_at = now()
       where id = v_c.id;
      if p_carta is not null then
        update public."RL_CARTA_CANDIDATO"
           set "DT_CONVOCACAO_MARCADA" = v_data
         where "CO_CARTA_CONVOCACAO" = p_carta and "CO_CANDIDATO_APROVADO" = v_c.id;
      end if;
      v_marcados := v_marcados + 1;
    end if;
  end loop;

  -- O KPI de contratados de cada edital tocado (20261006070000).
  perform private."FC_ATUALIZAR_CONTRATADOS_DO_EDITAL"(e.edital_id::uuid)
     from (select distinct l.edital_id
             from public."TB_CANDIDATO_APROVADO" c
             join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
            where c.id = any (v_ids) and l.edital_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') e;

  -- Quem não existe (ou foi removido) também volta, para a tela dizer.
  v_ignorados := v_ignorados || coalesce((
    select jsonb_agg(jsonb_build_object('candidato_id', x, 'nome', null, 'motivo', 'Candidato não encontrado'))
      from unnest(v_ids) x
     where not exists (select 1 from public."TB_CANDIDATO_APROVADO" c where c.id = x and c.removido_em is null)
  ), '[]'::jsonb);

  return json_build_object('marcados', v_marcados, 'ignorados', v_ignorados, 'data_convocacao', v_data);
end;
$_$;

--
-- Name: FUNCTION marcar_candidatos_convocados(p_candidatos uuid[], p_data_convocacao date, p_carta uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.marcar_candidatos_convocados(p_candidatos uuid[], p_data_convocacao date, p_carta uuid) IS 'Marca como Convocado (com a data; padrão hoje, nunca futura) os candidatos sem status ou já convocados, de listas vigentes e ativas — os demais voltam em ignorados com o motivo. Com p_carta, liga a alteração à carta emitida (TH_CANDIDATO_APROVADO.CO_CARTA_CONVOCACAO e RL_CARTA_CANDIDATO.DT_CONVOCACAO_MARCADA). Aprovados >= editor na área/edital de todos; até 500 por vez.';

--
-- Name: marcar_encerramento_visto(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_encerramento_visto(p_edital uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
declare
  v_usuario uuid := auth.uid();
begin
  if v_usuario is null then
    raise exception using errcode = '42501', message = 'Sessão necessária.';
  end if;
  if not exists (select 1 from public."TB_PERFIL_USUARIO" p
                  where p.user_id = v_usuario and p.ativo is true) then
    raise exception using errcode = '42501', message = 'Sem permissão para este recurso';
  end if;
  if p_edital is null or not exists (
       select 1
         from private."FC_EDITAIS_ENCERRADOS"() e
        where e."CO_MONITORAMENTO" = p_edital
          and exists (select 1 from public."TB_FICHA_ANALISE" f
                       where f."CO_MONITORAMENTO" = p_edital
                         and f."TP_SITUACAO" = 'CONCLUIDA'
                         and f."CO_USUARIO_CONCLUSAO" = v_usuario)) then
    raise exception using errcode = '22023', message = 'Edital não encerrado ou sem ficha sua.';
  end if;
  insert into public."RL_ENCERRAMENTO_EDITAL_USUARIO" ("CO_MONITORAMENTO", "CO_USUARIO")
  values (p_edital, v_usuario)
  on conflict do nothing;
  return true;
end;
$$;

--
-- Name: FUNCTION marcar_encerramento_visto(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.marcar_encerramento_visto(p_edital uuid) IS 'Grava que quem chama viu a tela de encerramento do edital (RL_ENCERRAMENTO_EDITAL_USUARIO; repetir não muda nada). Só edital encerrado em que a pessoa concluiu ficha (22023). Sessão e perfil ativo (20261021180000).';

--
-- Name: marcar_etapa_recurso(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marcar_etapa_recurso(p_id uuid, p_etapa text, p_feita boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_atual public."TB_RECURSO_CANDIDATO";
  v_area text;
  v_antes timestamptz;
  v_em timestamptz;
  v_revisao integer;
begin
  if p_etapa is null or p_etapa not in ('download_empregare', 'processo_sei', 'upload_sei', 'resposta_candidato') then
    raise exception 'Etapa inválida' using errcode = '22023';
  end if;
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  select r.* into v_atual
  from public."TB_RECURSO_CANDIDATO" r
  where r."CO_RECURSO_CANDIDATO" = p_id and r."ST_ATIVO" = 'S'
  for update;
  if not found then
    raise exception 'Recurso não encontrado' using errcode = 'P0002';
  end if;
  select m."CO_AREA" into v_area from public."TB_MONITORAMENTO_INDIGENA" m where m.id = v_atual."CO_MONITORAMENTO";
  perform private."FC_EXIGIR_RECURSOS_NA_AREA"(v_area, 2);
  perform private."FC_EXIGIR_AREA_EDITAL"(v_atual."CO_MONITORAMENTO"::text);
  -- A etapa "resposta enviada" (quem edita) só com o recurso já decidido pelo jurídico.
  if p_etapa = 'resposta_candidato' then
    if coalesce(p_feita, false) and v_atual."TP_SITUACAO" not in ('DEFERIDO', 'INDEFERIDO', 'PARCIALMENTE_INDEFERIDO') then
      raise exception 'Registre a decisão antes de marcar a resposta enviada' using errcode = '22023';
    end if;
  end if;

  v_antes := case p_etapa
    when 'download_empregare' then v_atual."DT_DOWNLOAD_EMPREGARE"
    when 'processo_sei' then v_atual."DT_PROCESSO_SEI"
    when 'upload_sei' then v_atual."DT_UPLOAD_SEI"
    else v_atual."DT_RESPOSTA_CANDIDATO" end;
  if (v_antes is not null) = coalesce(p_feita, false) then
    return json_build_object('revisao', v_atual."NU_REVISAO", 'alterou', false, 'em', v_antes);
  end if;
  v_em := case when p_feita then now() end;

  update public."TB_RECURSO_CANDIDATO" set
    "DT_DOWNLOAD_EMPREGARE" = case when p_etapa = 'download_empregare' then v_em else "DT_DOWNLOAD_EMPREGARE" end,
    "CO_USUARIO_DOWNLOAD_EMPREGARE" = case when p_etapa = 'download_empregare' then case when p_feita then v_uid end else "CO_USUARIO_DOWNLOAD_EMPREGARE" end,
    "DT_PROCESSO_SEI" = case when p_etapa = 'processo_sei' then v_em else "DT_PROCESSO_SEI" end,
    "CO_USUARIO_PROCESSO_SEI" = case when p_etapa = 'processo_sei' then case when p_feita then v_uid end else "CO_USUARIO_PROCESSO_SEI" end,
    "DT_UPLOAD_SEI" = case when p_etapa = 'upload_sei' then v_em else "DT_UPLOAD_SEI" end,
    "CO_USUARIO_UPLOAD_SEI" = case when p_etapa = 'upload_sei' then case when p_feita then v_uid end else "CO_USUARIO_UPLOAD_SEI" end,
    "DT_RESPOSTA_CANDIDATO" = case when p_etapa = 'resposta_candidato' then v_em else "DT_RESPOSTA_CANDIDATO" end,
    "CO_USUARIO_RESPOSTA_CANDIDATO" = case when p_etapa = 'resposta_candidato' then case when p_feita then v_uid end else "CO_USUARIO_RESPOSTA_CANDIDATO" end,
    "NU_REVISAO" = "NU_REVISAO" + 1,
    "DT_ATUALIZACAO" = now(),
    "CO_USUARIO_ATUALIZACAO" = v_uid
  where "CO_RECURSO_CANDIDATO" = p_id
  returning "NU_REVISAO" into v_revisao;

  insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
  values (p_id, 'etapa', p_etapa, case when v_antes is null then 'N' else 'S' end, case when p_feita then 'S' else 'N' end, v_uid);

  return json_build_object('revisao', v_revisao, 'alterou', true, 'em', v_em);
end;
$$;

--
-- Name: FUNCTION marcar_etapa_recurso(p_id uuid, p_etapa text, p_feita boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.marcar_etapa_recurso(p_id uuid, p_etapa text, p_feita boolean) IS 'Marca (com quando e quem) ou desmarca uma etapa: download_empregare, processo_sei, upload_sei ou resposta_candidato. Marcar a resposta enviada exige o recurso decidido (pelo parecer jurídico). Registra no histórico e sobe a revisão. Exige recursos >= editor, a área e a coordenação do edital.';

--
-- Name: meu_usuario(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meu_usuario() RETURNS TABLE(id uuid, user_id uuid, email text, nome text, perfil text, ativo boolean, p_ind boolean, p_cores boolean, p_paineis boolean, p_config boolean, p_admin boolean, avatar_source text, avatar_url text, avatar_config jsonb, google_avatar_url text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'auth'
    SET statement_timeout TO '3s'
    AS $$
  select
    p.id,
    p.user_id,
    p.email,
    p.nome,
    p.perfil,
    p.ativo,
    p.p_ind,
    p.p_cores,
    p.p_paineis,
    p.p_config,
    p.p_admin,
    p.avatar_source,
    p.avatar_url,
    p.avatar_config,
    coalesce(
      p.google_avatar_url,
      auth.jwt() -> 'user_metadata' ->> 'avatar_url',
      auth.jwt() -> 'user_metadata' ->> 'picture'
    ) as google_avatar_url
  from public."TB_PERFIL_USUARIO" p
  where p.ativo = true
    and (
      p.user_id = auth.uid()
      or lower(p.email) = lower(coalesce(auth.jwt() ->> 'email', ''))
    )
  limit 1;
$$;

--
-- Name: minha_conta_desativada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.minha_conta_desativada() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
           select 1 from public."TB_PERFIL_USUARIO" u
            where not u.ativo
              and (u.user_id = (select auth.uid())
                   or lower(u.email) = lower(coalesce((select auth.jwt() ->> 'email'), '-'))))
     and not exists (
           select 1 from public."TB_PERFIL_USUARIO" u
            where u.ativo
              and (u.user_id = (select auth.uid())
                   or lower(u.email) = lower(coalesce((select auth.jwt() ->> 'email'), '-'))));
$$;

--
-- Name: FUNCTION minha_conta_desativada(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.minha_conta_desativada() IS 'true quando quem está logado tem conta no MONITORA e ela está desativada (nenhum perfil ativo). Usada pela tela de pedido de acesso.';

--
-- Name: mover_conta_para_coordenacoes(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mover_conta_para_coordenacoes(p_perfil_usuario_id uuid, p_area text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conta public."TB_PERFIL_USUARIO";
  v_codigo text;
  v_nome text;
begin
  if not private.is_master() then raise exception 'Somente administradores gerenciam coordenações' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then raise exception 'Informe um motivo entre 3 e 500 caracteres'; end if;
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then raise exception 'Área inválida'; end if;

  select * into v_conta from public."TB_PERFIL_USUARIO" where id = p_perfil_usuario_id and ativo for update;
  if v_conta.id is null then raise exception 'Conta ativa não encontrada'; end if;
  if v_conta.user_id = (select auth.uid()) or lower(v_conta.email) = lower(coalesce((select auth.jwt() ->> 'email'), '')) then
    raise exception 'Você não pode mover a sua própria conta' using errcode = '42501';
  end if;

  v_nome := left(coalesce(nullif(btrim(v_conta.nome), ''), split_part(v_conta.email, '@', 1)), 120);
  select c."CO_COORDENACAO" into v_codigo from public."TB_COORDENACAO" c where lower(c."NO_COORDENACAO") = lower(v_nome);
  if v_codigo is null then
    v_codigo := private."FC_CODIGO_DE_COORDENACAO"(v_nome);
    insert into public."TB_COORDENACAO" ("CO_COORDENACAO", "NO_COORDENACAO", "CO_AREA")
    values (v_codigo, v_nome, p_area);
    insert into public."TH_COORDENACAO" ("CO_COORDENACAO", "JS_ANTES", "JS_DEPOIS", "CO_ALTERADO_POR", "DS_MOTIVO")
    values (v_codigo, null, private."FC_COORDENACAO_JSON"(v_codigo), (select auth.uid()),
            btrim(p_motivo) || ' [criada a partir da conta ' || v_conta.email || ']');
  end if;

  update public."TB_PERFIL_USUARIO"
     set ativo = false, "CO_COORDENACAO" = null,
         p_ind = false, p_cores = false, p_paineis = false, p_config = false, p_admin = false, updated_at = now()
   where id = v_conta.id;

  insert into public."TH_PERMISSAO_RECURSO" (perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
  values (v_conta.id, '#grupo', v_conta.perfil, '(conta desativada: virou a coordenação ' || v_codigo || ')',
          (select auth.uid()), btrim(p_motivo));

  return private."FC_COORDENACAO_JSON"(v_codigo);
end;
$$;

--
-- Name: mover_edital_de_area(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mover_edital_de_area(p_id uuid, p_area text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
declare
  v_area text := nullif(btrim(p_area), '');
  v_motivo text := nullif(btrim(p_motivo), '');
  v_de text;
begin
  if not private.is_master() then
    raise exception 'Só administradores podem mover editais de área' using errcode = '42501';
  end if;
  if v_motivo is null then
    raise exception 'Informe o motivo da mudança de área' using errcode = '22023';
  end if;
  if v_area is null or not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Área inválida: %', coalesce(v_area, '(vazia)') using errcode = '22023';
  end if;

  select m."CO_AREA" into v_de
    from public."TB_MONITORAMENTO_INDIGENA" m
   where m.id = p_id
   for update;
  if not found then
    raise exception 'Edital não encontrado' using errcode = 'P0002';
  end if;
  if v_de = v_area then
    raise exception 'O edital já está nesta área' using errcode = '22023';
  end if;

  update public."TB_MONITORAMENTO_INDIGENA"
     set "CO_AREA" = v_area,
         updated_by = (select auth.uid()),
         updated_at = now()
   where id = p_id;

  insert into public."TH_MONITORAMENTO"(
    id_registro, usuario_id, usuario_email, evento,
    campo_alterado, valor_anterior, valor_novo, snapshot_json
  ) values (
    p_id,
    (select auth.uid()),
    nullif((select auth.jwt()) ->> 'email', ''),
    'atualizado',
    'CO_AREA',
    v_de,
    v_area,
    jsonb_build_object('acao', 'mover_edital_de_area', 'de', v_de, 'para', v_area, 'motivo', v_motivo)
  );

  return jsonb_build_object('ok', true, 'id', p_id, 'de', v_de, 'para', v_area);
end;
$$;

--
-- Name: FUNCTION mover_edital_de_area(p_id uuid, p_area text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mover_edital_de_area(p_id uuid, p_area text, p_motivo text) IS 'Só admin: muda a área (CO_AREA) de um edital, com motivo, e registra em TH_MONITORAMENTO (campo_alterado = CO_AREA). Não mexe em TA_UNIDADE_AREA.';

--
-- Name: obter_acompanhamento_inscricoes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_acompanhamento_inscricoes(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
  v_hoje constant date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  return json_build_object(
    'schema_version', 1,
    'hoje', v_hoje,
    'cronograma', coalesce((
      select json_agg(json_build_object('atividade', c.atividade, 'inicio', c.data_inicio, 'fim', c.data_fim) order by c.ordem)
        from public."TB_CRONOGRAMA_MONIT_INDIG" c where c.monitoramento_id = p_edital), '[]'::json),
    -- O cargo: o que o job da pré-classificação gravou com a vaga (TB_PRE_CLASSIF_VAGA); vaga
    -- ainda sem pré-classificação, o do quadro do edital; sem ele, o nome do questionário da
    -- Empregare (coluna "SITUAÇÃO - <questionário>" do arquivo).
    'vagas', coalesce((
      select json_agg(json_build_object(
               'codigo', v."CO_VAGA",
               'cargo', coalesce(
                          case when pv."CO_VAGA" is not null
                               then nullif(concat_ws(' — ', pv."NO_CARGO", pv."NO_LOTACAO"), '')
                               else (select nullif(concat_ws(' — ', q."NO_CARGO", q."NO_LOTACAO"), '')
                                       from private."FC_QUADRO_DA_VAGA_EMPREGARE"(p_edital, v."CO_VAGA") q)
                          end,
                          (select btrim(substr(x, length('SITUAÇÃO - ') + 1))
                             from jsonb_array_elements_text(v."DS_COLUNA") x
                            where upper(x) like 'SITUAÇÃO - %' limit 1)),
               'ultima_carga', v."DT_ULTIMA_CARGA")
             order by v."CO_VAGA")
        from public."TB_EMPREGARE_VAGA" v
        left join public."TB_PRE_CLASSIF_VAGA" pv on pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" = v."CO_VAGA"
       where v."CO_MONITORAMENTO" = p_edital), '[]'::json),
    'retratos', coalesce((
      select json_agg(json_build_object(
               'vaga', r."CO_VAGA", 'data', r."DT_RETRATO", 'inscritos', r."QT_INSCRITO",
               'finalizados', r."QT_FINALIZADO", 'aptos', r."QT_APTO", 'eliminados', r."QT_ELIMINADO",
               'previa', r."ST_PREVIA" = 'S', 'em', r."DT_ATUALIZACAO")
             order by r."DT_RETRATO", r."CO_VAGA")
        from public."TH_INSCRICAO_VAGA_EDITAL" r
       where r."CO_MONITORAMENTO" = p_edital and r."DT_RETRATO" >= v_hoje - 60), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION obter_acompanhamento_inscricoes(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_acompanhamento_inscricoes(p_edital uuid) IS 'Cartão Inscrições da aba Pré-classificação (20261009140000): quem lê a Avaliação documental do edital (FC_EXIGIR_AVALIACAO_EDITAL nível 1) recebe o cronograma, as vagas da Empregare do edital (código, cargo do quadro ou nome do questionário, última carga) e os retratos diários dos últimos 60 dias (TH_INSCRICAO_VAGA_EDITAL). Só contagens. 42501 sem permissão, 22023 edital inexistente.';

--
-- Name: obter_agenda_entrevista(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_agenda_entrevista(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private."FC_EXIGIR_AGENDA_ENTREVISTA"(p_edital, 1);
  return private."FC_AGENDA_ENTREVISTA_JSON"(p_edital);
end;
$$;

--
-- Name: FUNCTION obter_agenda_entrevista(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_agenda_entrevista(p_edital uuid) IS 'A agenda das entrevistas do edital (json): regra vigente e versões, horários por convocado, bancas, histórico; pode_editar. Exige entrevistas ou classificacao >= leitor, a área e o recorte da coordenação.';

--
-- Name: obter_ajustes_pontuacao_recurso(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_ajustes_pontuacao_recurso(p_recurso uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_r public."TB_RECURSO_CANDIDATO";
begin
  perform private."FC_EXIGIR_RECURSO_ACESSIVEL"(p_recurso, 1);
  select * into v_r from public."TB_RECURSO_CANDIDATO" where "CO_RECURSO_CANDIDATO" = p_recurso;
  return json_build_object(
    'recurso_id', p_recurso,
    'situacao', v_r."TP_SITUACAO",
    'pode_propor', private."FC_PODE_PARECER_RECURSO"() and v_r."ST_FORA_ANALISE" = 'N'
                   and v_r."TP_SITUACAO" in ('EM_ANALISE_JURIDICA', 'DEFERIDO', 'PARCIALMENTE_INDEFERIDO'),
    'pode_aprovar', private."FC_PODE_PARECER_RECURSO"() and v_r."TP_SITUACAO" in ('DEFERIDO', 'PARCIALMENTE_INDEFERIDO'),
    'pode_cancelar', private."FC_PODE_PARECER_RECURSO"(),
    'ajustes', coalesce((
      select json_agg(private."FC_AJUSTE_PONTUACAO_JSON"(j."CO_AJUSTE_PONTUACAO") order by j."NU_VERSAO" desc)
        from public."TB_AJUSTE_PONTUACAO_RECURSO" j
       where j."CO_RECURSO_CANDIDATO" = p_recurso), '[]'::json));
end;
$$;

--
-- Name: FUNCTION obter_ajustes_pontuacao_recurso(p_recurso uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_ajustes_pontuacao_recurso(p_recurso uuid) IS 'As versões do ajuste da pontuação de um recurso (json, da mais nova), com itens, prévias e quem/quando; pode_propor (parecer jurídico, recurso ligado à análise, em análise jurídica ou deferido), pode_aprovar (parecer jurídico, recurso deferido) e pode_cancelar. Exige Recursos >= leitor, a área e a coordenação do edital.';

--
-- Name: obter_apoio_regra_analise(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_apoio_regra_analise(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$

declare

  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);

  v_coordena boolean := coalesce(private."FC_PAPEL_AVALIACAO"(p_edital) = 'COORDENADOR', false);

  v_le_classificacao boolean := private.pode_recurso('classificacao', 1);

begin

  return json_build_object(

    'schema_version', 1,

    -- Só os nomes das colunas de pergunta, por vaga (nenhuma resposta de candidato).

    'perguntas_por_vaga', coalesce((

      select json_agg(json_build_object(

               'vaga', v."CO_VAGA",

               -- O cargo da vaga: a Seleção, a pré-classificação ou, sem elas, o nome

               -- do arquivo da carga da Empregare ("Candidatos da vaga N - <cargo> em Excel").

               'cargo', coalesce(

                 (select s."NO_CARGO" from public."TB_SELECAO_VAGA" s

                   where s."CO_VAGA" = v."CO_VAGA" and s."NO_CARGO" is not null

                   order by s."CO_MONITORAMENTO" = p_edital desc limit 1),

                 (select pv."NO_CARGO" from public."TB_PRE_CLASSIF_VAGA" pv

                   where pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" = v."CO_VAGA" and pv."NO_CARGO" is not null),

                 nullif(btrim(substring(v."NO_ARQUIVO" from '^Candidatos da vaga [0-9]+ - (.+) em Excel')), '')),

               'colunas', coalesce((

                 select json_agg(c.coluna order by c.ordem)

                   from jsonb_array_elements_text(v."DS_COLUNA") with ordinality c(coluna, ordem)

                  where c.coluna ilike 'Pergunta %'), '[]'::json))

             order by v."CO_VAGA")

        from public."TB_EMPREGARE_VAGA" v

       where v."CO_MONITORAMENTO" = p_edital and v."TP_SITUACAO" = 'GRAVADA'), '[]'::json),

    -- Os cargos do quadro de vagas do edital (as diferenças por cargo, 20261013130000).

    'cargos_do_quadro', coalesce((

      select json_agg(q."NO_CARGO" order by q.ordem)

        from (select qv."NO_CARGO", min(qv."NU_ORDEM") as ordem

                from public."TB_QUADRO_VAGA_EDITAL" qv

               where qv."CO_MONITORAMENTO" = p_edital and qv."ST_REGISTRO_ATIVO" = 'S'

               group by qv."NO_CARGO") q), '[]'::json),

    'regras_da_area', case when v_coordena then coalesce((

      select json_agg(json_build_object(

               'id', m.id, 'edital', m.edital, 'numero', private."FC_NUMERO_EDITAL"(m.edital), 'unidade', m.unidade,

               'versao', r."NU_VERSAO_VIGENTE", 'nome', h."NO_VERSAO", 'conferida_em', r."DT_CONFERENCIA",

               'configuracao', h."DS_CONFIGURACAO")

             order by r."DT_CONFERENCIA" desc, m.edital)

        from public."TB_REGRA_ANALISE" r

        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = r."CO_MONITORAMENTO"

        join public."TH_REGRA_ANALISE" h

          on h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"

       where r."TP_SITUACAO" = 'CONFERIDA' and m."CO_AREA" = v_area and m.id <> p_edital

         and private."FC_PODE_VER_EDITAL"(m.id)), '[]'::json) else '[]'::json end,

    'classificacao', json_build_object(

      'pode_ler', v_le_classificacao,

      'pode_editar', v_le_classificacao and private.pode_recurso('classificacao', 2),

      'regra', case when v_le_classificacao then (

        select json_build_object('versao', r."NU_VERSAO_VIGENTE", 'nome', h."NO_VERSAO", 'configuracao', h."DS_CONFIGURACAO",

                                 'atualizado_em', h."DT_CRIACAO", 'por', coalesce(p.nome, p.email))

          from public."TB_REGRA_CLASSIFICACAO" r

          join public."TH_REGRA_CLASSIFICACAO" h

            on h."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"

          left join public."TB_PERFIL_USUARIO" p on p.user_id = h."CO_USUARIO"

         where r."CO_MONITORAMENTO" = p_edital) end)

  );

end;

$$;

--
-- Name: FUNCTION obter_apoio_regra_analise(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_apoio_regra_analise(p_edital uuid) IS 'O que o assistente da regra da avaliação documental lê (json): os nomes das colunas de pergunta da última carga de cada vaga do edital (sem respostas) com o cargo (Seleção, pré-classificação ou o nome do arquivo da carga), os cargos do quadro de vagas (cargos_do_quadro, para as diferenças por cargo, desde 20261013130000), as regras conferidas dos outros editais da área que a pessoa vê (só para a coordenação do edital, para copiar; com o nome da versão) e a regra de classificação vigente (nota mínima, desempate e o nome da versão) para quem lê a Classificação, com pode_editar (Editor na Classificação). Desde 20261016130000, só a coordenação do edital (FC_EXIGIR_COORD_AVALIACAO: Editor, área e papel COORDENADOR ou admin global; os demais recebem 42501): a aba é só da coordenação.';

--
-- Name: obter_branding_acesso_publico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_branding_acesso_publico() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '3s'
    AS $$
  select coalesce(
    jsonb_object_agg(c.chave, c.valor)
      filter (where c.valor is not null and btrim(c.valor) <> ''),
    '{}'::jsonb
  )
  from public."TB_CONFIGURACAO" as c
  where c.chave in (
    'auth_access_background_url',
    'auth_access_logo_url',
    'auth_access_panel_color',
    'auth_access_greeting',
    'auth_access_instruction',
    'auth_google_button_text',
    'auth_access_texto_modo',
    'auth_access_painel_estilo'
  );
$$;

--
-- Name: FUNCTION obter_branding_acesso_publico(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_branding_acesso_publico() IS 'Identidade da tela de acesso para visitantes não autenticados. Lista de chaves fixa, sem dado de pessoa ou sessão (desde 20261112180000, também o estilo do painel: sólido ou vidro).';

--
-- Name: obter_calculo_classificacao(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_calculo_classificacao(p_pedido uuid, p_com_retrato boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_PEDIDO_CALCULO_CLASSIFICACAO";
begin
  select * into v from public."TB_PEDIDO_CALCULO_CLASSIFICACAO" p where p."CO_PEDIDO_CALCULO" = p_pedido;
  if v."CO_PEDIDO_CALCULO" is null then
    raise exception 'Pedido de cálculo não encontrado' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(v."CO_MONITORAMENTO", 2);
  return json_build_object(
    'pedido', v."CO_PEDIDO_CALCULO",
    'tipo', v."TP_LISTA",
    'versao_regra', v."NU_VERSAO_REGRA",
    'situacao', v."TP_SITUACAO",
    'mensagem', v."DS_MENSAGEM",
    'pedido_em', v."DT_PEDIDO",
    'atualizado_em', v."DT_ATUALIZACAO",
    'hash', v."DS_HASH",
    'lista_id', v."CO_LISTA_CLASSIFICACAO",
    'retrato', case when p_com_retrato and v."TP_SITUACAO" = 'PRONTO' then v."DS_RETRATO" end);
end;
$$;

--
-- Name: FUNCTION obter_calculo_classificacao(p_pedido uuid, p_com_retrato boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_calculo_classificacao(p_pedido uuid, p_com_retrato boolean) IS 'A tela acompanha o pedido de cálculo (20261023200000): situação, mensagem, quando, o hash e, com p_com_retrato e a situação PRONTO, o retrato calculado pelo Python (com os nomes, como a lista). Classificação editor do edital.';

--
-- Name: obter_casamento_da_lista(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_casamento_da_lista(p_pedido uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p public."TB_PEDIDO_CASAMENTO_LISTA";
  v_revisar jsonb;
begin
  select * into v_p from public."TB_PEDIDO_CASAMENTO_LISTA" where "CO_PEDIDO" = p_pedido;
  if v_p."CO_PEDIDO" is null
     or (v_p."CO_USUARIO" is distinct from (select auth.uid())
         and not private."FC_ADMIN_GLOBAL_ATIVO"((select auth.uid()))) then
    raise exception 'Pedido não encontrado.' using errcode = '22023';
  end if;
  v_revisar := coalesce(v_p."DS_PLANO" -> 'revisar', '[]'::jsonb);
  return json_build_object(
    'pedido_id', v_p."CO_PEDIDO",
    'edital_id', v_p."CO_MONITORAMENTO",
    'origem', v_p."TP_ORIGEM",
    'situacao', v_p."TP_SITUACAO",
    'erro', v_p."DS_ERRO",
    'disparo', (select d."TP_SITUACAO" from public."TL_DISPARO_ROBO" d where d."CO_DISPARO" = v_p."CO_DISPARO"),
    'pedido_em', v_p."DT_PEDIDO",
    'lista_vigente', v_p."CO_LISTA_APROVADO_ANTERIOR",
    'anteriores', (select count(*) from public."TB_CANDIDATO_APROVADO" c
                    where c.lista_id = v_p."CO_LISTA_APROVADO_ANTERIOR" and c.removido_em is null),
    'novos_total', jsonb_array_length(v_p."DS_NOVOS"),
    'exige_motivo', private."FC_EXIGE_MOTIVO_PARA_SUBSTITUIR"(v_p."CO_LISTA_APROVADO_ANTERIOR", v_p."TP_ORIGEM"),
    'pode_substituir', v_p."CO_LISTA_APROVADO_ANTERIOR" is null or private."FC_PODE_SUBSTITUIR_LISTA"(),
    'manuais', v_p."DS_MANUAIS",
    'plano', v_p."DS_PLANO",
    -- Para a revisão da Classificação: quem entra (nome, vaga, posição) e quem revisar.
    'novos', case when v_p."TP_ORIGEM" = 'CLASSIFICACAO' and v_p."DS_PLANO" is not null then (
               select coalesce(jsonb_agg(jsonb_build_object('chave', n.y ->> 'chave', 'nome', n.y ->> 'nome',
                                 'cargo', n.y ->> 'cargo', 'codigo_vaga', n.y ->> 'codigo_vaga',
                                 'posicao', n.y -> 'posicao', 'nota', n.y -> 'nota') order by (n.y ->> 'ordem')::bigint),
                               '[]'::jsonb)
                 from jsonb_array_elements(v_p."DS_NOVOS") n(y)) end,
    'revisar', (select coalesce(jsonb_agg(jsonb_build_object(
                  'candidato_id', c.id, 'nome', c.nome, 'cargo', c.cargo, 'codigo_vaga', c.codigo_vaga,
                  'classificacao', c.classificacao, 'status', c.status, 'matricula', c.matricula)
                  order by c.nome), '[]'::jsonb)
                  from public."TB_CANDIDATO_APROVADO" c
                 where c.id in (select (r.v #>> '{}')::uuid from jsonb_array_elements(v_revisar) r(v))
                   and c.lista_id = v_p."CO_LISTA_APROVADO_ANTERIOR")
  );
end;
$$;

--
-- Name: FUNCTION obter_casamento_da_lista(p_pedido uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_casamento_da_lista(p_pedido uuid) IS 'A prévia de uma nova versão da lista de aprovados: a situação do pedido (e do pedido ao GitHub), o plano do job Python (casados, entram, sem par, status sem dono, quem muda, pendências), se exige motivo e se a pessoa pode substituir; na Classificação, quem entra e quem revisar. Só quem pediu, ou o administrador global. 20261030090000.';

--
-- Name: obter_catalogo_dos_robos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_catalogo_dos_robos() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select auth.uid()) is null then
    raise exception 'Entre no MONITORA de novo.' using errcode = '28000';
  end if;
  if not private.is_master() then
    raise exception 'Somente o administrador global vê o catálogo dos robôs' using errcode = '42501';
  end if;
  return json_build_object(
    'schema_version', 1,
    'workflows', (
      select coalesce(json_agg(json_build_object(
          'workflow', w."NO_WORKFLOW",
          'nome', w."NO_ROBO",
          'chave', w."CO_CHAVE",
          'disparavel', w."ST_DISPARAVEL" = 'S'
        ) order by w."NO_WORKFLOW"), '[]'::json)
        from public."TB_ROBO_WORKFLOW" w),
    'tarefas', (
      select coalesce(json_agg(json_build_object(
          'tarefa', t."NO_TAREFA",
          'prefixo', t."ST_PREFIXO" = 'S',
          'rotulo', t."DS_ROTULO",
          'chave', t."CO_CHAVE",
          'workflow', t."NO_WORKFLOW"
        ) order by t."NO_TAREFA"), '[]'::json)
        from public."TB_TAREFA_AGENDADA" t)
  );
end;
$$;

--
-- Name: FUNCTION obter_catalogo_dos_robos(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_catalogo_dos_robos() IS 'Status das atualizações (20261109180000): o catálogo dos robôs — nome de cada workflow (TB_ROBO_WORKFLOW) e rótulo, chave e workflow de cada tarefa do pg_cron (TB_TAREFA_AGENDADA). Só o administrador global (28000 sem sessão, 42501 os demais).';

--
-- Name: obter_chaves_da_automacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_chaves_da_automacao() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tarefas jsonb;
  v_cron boolean := true;
begin
  if (select auth.uid()) is null then
    raise exception 'Entre no MONITORA de novo.' using errcode = '28000';
  end if;
  if not private.is_master() then
    raise exception 'Somente o administrador global vê as chaves da automação' using errcode = '42501';
  end if;

  -- As tarefas agsus_* do pg_cron, com a chave e a última execução.
  begin
    select coalesce(jsonb_agg(jsonb_build_object(
        'nome', j.jobname,
        'chave', private."FC_CHAVE_DA_TAREFA"(j.jobname),
        'agenda', j.schedule,
        'ativa', j.active,
        'ultima', (select jsonb_build_object('inicio', d.start_time, 'fim', d.end_time, 'situacao', d.status)
                     from cron.job_run_details d
                    where d.jobid = j.jobid
                    order by d.start_time desc limit 1)
      ) order by j.jobname), '[]'::jsonb)
      into v_tarefas
      from cron.job j
     where left(j.jobname, 6) = 'agsus_';
  exception when others then
    v_tarefas := '[]'::jsonb;
    v_cron := false;
  end;

  return json_build_object(
    'schema_version', 1,
    'gerado_em', now(),
    'cron_disponivel', v_cron,
    'chaves', (
      select coalesce(json_agg(json_build_object(
          'chave', c."CO_CHAVE",
          'nome', c."NO_CHAVE",
          'ligada', c."ST_LIGADA" = 'S',
          'motivo', c."DS_MOTIVO",
          'em', c."DT_ATUALIZACAO",
          'por', case when c."CO_USUARIO_ATUALIZACAO" is null then null
                      else private."FC_NOME_USUARIO"(c."CO_USUARIO_ATUALIZACAO") end,
          'tarefas', coalesce((select jsonb_agg(t) from jsonb_array_elements(v_tarefas) t
                                where t ->> 'chave' = c."CO_CHAVE"), '[]'::jsonb),
          -- O último pedido da agenda ao GitHub (as chaves de robô).
          'ultimo_pedido', (
            select json_build_object('inicio', d."DT_DISPARO", 'situacao', d."TP_SITUACAO")
              from public."TL_DISPARO_ROBO" d
             where d."TP_ORIGEM" = 'AGENDA'
               and private."FC_CHAVE_DO_WORKFLOW"(d."NO_WORKFLOW") = c."CO_CHAVE"
             order by d."DT_DISPARO" desc limit 1),
          -- A pré-classificação automática roda no fim do robô (TP_DISPARO = ROBO).
          'ultima_pre_classificacao', case when c."CO_CHAVE" = 'pre_classificacao' then (
            select json_build_object('inicio', p."DT_INICIO", 'fim', p."DT_FIM", 'situacao', p."TP_SITUACAO")
              from public."TL_PRE_CLASSIFICACAO" p
             where p."TP_DISPARO" = 'ROBO'
             order by p."DT_INICIO" desc limit 1) end
        ) order by c."NU_ORDEM"), '[]'::json)
        from public."TB_CHAVE_AUTOMACAO" c
    ),
    'sem_chave', coalesce((select jsonb_agg(t - 'chave') from jsonb_array_elements(v_tarefas) t
                            where t ->> 'chave' is null), '[]'::jsonb),
    'historico', (
      select coalesce(json_agg(json_build_object(
          'chave', h."CO_CHAVE",
          'ligada', h."ST_LIGADA" = 'S',
          'motivo', h."DS_MOTIVO",
          'em', h."DT_EVENTO",
          'por', case when h."CO_USUARIO" is null then null else private."FC_NOME_USUARIO"(h."CO_USUARIO") end,
          'tarefas', h."DS_TAREFAS"
        ) order by h."DT_EVENTO" desc, h."CO_EVENTO" desc), '[]'::json)
        from (select * from public."TH_CHAVE_AUTOMACAO" t
               order by t."DT_EVENTO" desc, t."CO_EVENTO" desc limit 50) h
    )
  );
end;
$$;

--
-- Name: FUNCTION obter_chaves_da_automacao(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_chaves_da_automacao() IS 'Configurações › Automação (20261022190000): as chaves da automação (ligada, motivo, em, por), as tarefas do pg_cron de cada uma (agenda, ativa, última execução), o último pedido da agenda ao GitHub, a última pré-classificação automática, as tarefas sem chave (sempre ligadas) e os 50 últimos eventos. Só o administrador global (28000 sem sessão, 42501 os demais).';

--
-- Name: obter_classificacao_do_edital(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_classificacao_do_edital(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 1);
begin
  return private."FC_DADOS_CLASSIFICACAO_EDITAL"(p_edital, v_area);
end;
$$;

--
-- Name: FUNCTION obter_classificacao_do_edital(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_classificacao_do_edital(p_edital uuid) IS 'Tudo o que o motor de classificação precisa de um edital (json): regra vigente e versões, catálogo de critérios, cronograma (data de corte), quadro de vagas, análises (sem CPF), entrevistas com notas por competência (ligadas por CO_ANALISE_CURRICULAR), listas geradas, desempates registrados, ajustes da pontuação aprovados em recurso (ajustes) e quando mudaram (ajustes_mudaram_em); pode_editar. Exige classificacao >= leitor, a área e o recorte da coordenação.';

--
-- Name: obter_classificacao_do_edital_se_mudou(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_classificacao_do_edital_se_mudou(p_edital uuid, p_versao text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_marca constant text := private."FC_MARCA_DA_RPC"('obter_classificacao_do_edital', p_edital => p_edital);
  v_dicionario constant text[] := array[
    'vaga', 'cargo', 'categoria', 'modalidade', 'pcd', 'status', 'etapa', 'quadro', 'hora_nascimento',
    'pontuacao_etnica'];
begin
  if v_marca is null then
    return private."FC_SE_MUDOU_EM_COLUNAS"(public.obter_classificacao_do_edital(p_edital)::jsonb, p_versao, 'candidatos', v_dicionario);
  end if;
  if p_versao = v_marca then
    return json_build_object('inalterado', true, 'versao', v_marca);
  end if;
  return private."FC_PAYLOAD_EM_COLUNAS"(public.obter_classificacao_do_edital(p_edital)::jsonb, 'candidatos', v_dicionario, v_marca);
end;
$$;

--
-- Name: FUNCTION obter_classificacao_do_edital_se_mudou(p_edital uuid, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_classificacao_do_edital_se_mudou(p_edital uuid, p_versao text) IS 'obter_classificacao_do_edital com versão e os candidatos em colunas (candidatos_em_colunas): a marca das fontes (FC_MARCA_DA_RPC) sai antes de montar; p_versao igual devolve só { inalterado, versao } (20261029170000). Mesma permissão.';

--
-- Name: obter_congelamento_inscricoes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_congelamento_inscricoes(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
begin
  return (
    select json_build_object(
      'schema_version', 1,
      'congelado', coalesce(c."ST_INSCRICOES_CONGELADAS" = 'S', false),
      'motivo', c."DS_MOTIVO",
      'em', c."DT_ATUALIZACAO",
      'por', case when c."CO_USUARIO_ATUALIZACAO" is null then null
                  else private."FC_NOME_USUARIO"(c."CO_USUARIO_ATUALIZACAO") end,
      'pode_alterar', public.pode_recalcular_pre_classificacao(p_edital),
      'historico', coalesce((
        select json_agg(json_build_object(
                 'tipo', h."TP_EVENTO",
                 'motivo', h."DS_MOTIVO",
                 'em', h."DT_EVENTO",
                 'por', private."FC_NOME_USUARIO"(h."CO_USUARIO")) order by h."DT_EVENTO" desc, h."CO_EVENTO" desc)
          from (select * from public."TH_CONGELAMENTO_INSCRICAO" t
                 where t."CO_MONITORAMENTO" = p_edital and t."TP_EVENTO" <> 'USO'
                 order by t."DT_EVENTO" desc, t."CO_EVENTO" desc limit 10) h), '[]'::json))
      from (select 1) x
      left join public."TB_CONGELAMENTO_INSCRICAO" c on c."CO_MONITORAMENTO" = p_edital);
end;
$$;

--
-- Name: FUNCTION obter_congelamento_inscricoes(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_congelamento_inscricoes(p_edital uuid) IS 'Trava "inscrições congeladas" do edital (20261020170000), para o cartão da aba Pré-classificação: congelado, motivo, em, por (nome), pode_alterar (coordenação da avaliação do edital ou administrador global) e os 10 últimos eventos (congelar, descongelar, liberação do administrador global). Quem lê a avaliação documental do edital (FC_EXIGIR_AVALIACAO_EDITAL).';

--
-- Name: obter_contexto_de_usuario(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_contexto_de_usuario(p_perfil_usuario_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  u public."TB_PERFIL_USUARIO";
  v_editais uuid[];
  v_areas text[];
begin
  select * into u from public."TB_PERFIL_USUARIO" where id = p_perfil_usuario_id and ativo;
  if u.id is null then raise exception 'Usuário ativo não encontrado'; end if;
  if private."FC_EXIGIR_GESTOR_DE_ACESSOS"() = 'coordenador'
     and u."CO_COORDENACAO" is distinct from private."FC_COORDENACAO_USUARIO"() then
    raise exception 'Usuário fora da sua coordenação' using errcode = '42501';
  end if;

  v_areas := coalesce(private."FC_AREAS_DO_PERFIL"(u.id), '{}');
  v_editais := case when exists (select 1 from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = u.perfil and a."ST_ADMIN_GLOBAL")
                    then null else private."FC_EDITAIS_DA_COORDENACAO"(u."CO_COORDENACAO") end;

  return jsonb_build_object(
    'profile', jsonb_build_object('id', u.id, 'user_id', u.user_id, 'email', u.email, 'nome', u.nome, 'perfil', u.perfil, 'ativo', u.ativo,
      'permissoes', (select jsonb_object_agg(m, private."FC_NIVEL_EFETIVO"(u.id, u.perfil, m)) from unnest(private."FC_RECURSOS_MODULO"()) m),
      'areas', to_jsonb(v_areas),
      'admin_global', coalesce((select a."ST_ADMIN_GLOBAL" from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = u.perfil), false),
      'grupo', (select jsonb_build_object('codigo', a."CO_GRUPO_ACESSO", 'nome', a."NO_GRUPO_ACESSO")
                          from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = u.perfil),
      'coordenacao', (select jsonb_build_object('codigo', c."CO_COORDENACAO", 'nome', c."NO_COORDENACAO", 'area', c."CO_AREA")
                        from public."TB_COORDENACAO" c where c."CO_COORDENACAO" = u."CO_COORDENACAO")),
    'panel_ids', coalesce((select jsonb_agg(e.id::text) from public."TB_PAINEL_EXTERNO" e
       where e.ativo
         and private."FC_RANK_NIVEL"(private."FC_NIVEL_EFETIVO"(u.id, u.perfil, 'paineis')) >= 1
         and private."FC_RANK_NIVEL"(private."FC_NIVEL_EFETIVO"(u.id, u.perfil, 'painel:' || e.id)) >= 1), '[]'::jsonb),
    'escopo', jsonb_build_object(
      'editais_da_area', (select count(*) from public."TB_MONITORAMENTO_INDIGENA" m where m.ativo and m."CO_AREA" = any (v_areas)),
      'editais_visiveis', case when v_editais is null
                               then (select count(*) from public."TB_MONITORAMENTO_INDIGENA" m where m.ativo and m."CO_AREA" = any (v_areas))
                               else (select count(*) from public."TB_MONITORAMENTO_INDIGENA" m where m.ativo and m.id = any (v_editais)) end,
      'recortado', v_editais is not null)
  );
end;
$$;

--
-- Name: obter_contexto_monitora(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_contexto_monitora() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select jsonb_build_object('profile', to_jsonb(p) || jsonb_build_object(
    'permissoes', (select jsonb_object_agg(m, private.nivel_recurso(m)) from unnest(private."FC_RECURSOS_MODULO"()) m),
    'areas', to_jsonb(private."FC_AREAS_USUARIO"()),
    'admin_global', private.is_master(),
    'grupo', (select jsonb_build_object('codigo', a."CO_GRUPO_ACESSO", 'nome', a."NO_GRUPO_ACESSO")
                        from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = p.perfil),
    'coordenacao', (select jsonb_build_object('codigo', c."CO_COORDENACAO", 'nome', c."NO_COORDENACAO", 'area', c."CO_AREA")
                      from public."TB_COORDENACAO" c where c."CO_COORDENACAO" = p."CO_COORDENACAO")),
  'panel_ids', coalesce((select jsonb_agg(e.id::text) from public."TB_PAINEL_EXTERNO" e
    where e.ativo and private.pode_recurso('paineis') and private.pode_recurso('painel:'||e.id)), '[]'::jsonb))
from private.current_profile() p where p.id is not null and p.ativo;
$$;

--
-- Name: FUNCTION obter_contexto_monitora(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_contexto_monitora() IS 'Resolve em uma chamada o perfil ativo, os modulos e os paineis externos permitidos ao usuario autenticado.';

--
-- Name: obter_dados_previa_ajuste(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_dados_previa_ajuste(p_recurso uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_RECURSO_ACESSIVEL"(p_recurso, 1);
  v_edital uuid;
begin
  perform private."FC_EXIGIR_PARECER_RECURSO"();
  select r."CO_MONITORAMENTO" into v_edital from public."TB_RECURSO_CANDIDATO" r where r."CO_RECURSO_CANDIDATO" = p_recurso;
  return private."FC_DADOS_CLASSIFICACAO_EDITAL"(v_edital, v_area);
end;
$$;

--
-- Name: FUNCTION obter_dados_previa_ajuste(p_recurso uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_dados_previa_ajuste(p_recurso uuid) IS 'Para a prévia do ajuste da pontuação: o mesmo json de obter_classificacao_do_edital, do edital do recurso (com os ajustes aprovados). Só o parecer jurídico (recursos_parecer; 42501), com Recursos >= leitor, a área e a coordenação do edital.';

--
-- Name: obter_desempate_da_lista(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_desempate_da_lista(p_lista uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_edital uuid;
  v_hash text;
  v_preparo json;
  v_relatorio json;
begin
  select l."CO_MONITORAMENTO", l."DS_HASH" into v_edital, v_hash
    from public."TB_LISTA_CLASSIFICACAO" l where l."CO_LISTA_CLASSIFICACAO" = p_lista;
  if v_edital is null then
    raise exception 'Lista não encontrada' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(v_edital, 1);
  select json_build_object('situacao', p."TP_SITUACAO", 'pedido_em', p."DT_PEDIDO",
                           'atualizado_em', p."DT_ATUALIZACAO", 'mensagem', p."DS_MENSAGEM")
    into v_preparo
    from public."TB_PREPARO_DESEMPATE" p where p."CO_LISTA_CLASSIFICACAO" = p_lista;
  select json_build_object(
           'versao', r."NU_VERSAO_RELATORIO",
           'gerado_em', r."DT_GERACAO",
           'da_lista_atual', r."DS_HASH_LISTA" = v_hash,
           'grupos', r."QT_GRUPO",
           'empatados', r."QT_EMPATE_FINAL",
           'pendentes', r."QT_PENDENCIA",
           'relatorio', r."DS_RELATORIO",
           'texto', r."DS_TEXTO")
    into v_relatorio
    from public."TB_RELATORIO_DESEMPATE" r where r."CO_LISTA_CLASSIFICACAO" = p_lista;
  if v_preparo is null and v_relatorio is null then
    return null;
  end if;
  return (jsonb_build_object('lista_id', p_lista, 'preparo', v_preparo)
          || coalesce(v_relatorio::jsonb, '{}'::jsonb))::json;
end;
$$;

--
-- Name: FUNCTION obter_desempate_da_lista(p_lista uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_desempate_da_lista(p_lista uuid) IS 'O relatório de desempate de uma lista gerada (json e texto, com nome e código dos candidatos) e o preparo dele (situação, pedido_em, atualizado_em, mensagem; 20261023170000), para Classificação › Listas; null quando a lista não tem nem relatório nem preparo. Exige classificacao >= leitor, a área e o recorte da coordenação do edital.';

--
-- Name: obter_encerramentos_do_edital(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_encerramentos_do_edital() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
declare
  v_usuario uuid := auth.uid();
begin
  if v_usuario is null then
    raise exception using errcode = '42501', message = 'Sessão necessária.';
  end if;
  if not exists (select 1 from public."TB_PERFIL_USUARIO" p
                  where p.user_id = v_usuario and p.ativo is true) then
    raise exception using errcode = '42501', message = 'Sem permissão para este recurso';
  end if;

  return jsonb_build_object(
    'gerado_em', now(),
    'editais', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', e."CO_MONITORAMENTO",
               'edital', e."NO_EDITAL",
               'numero', e."NU_EDITAL",
               'area', e."CO_AREA",
               'concluido_em', e."DT_CONCLUSAO",
               'inscritos', (select count(*) from public."TB_PRE_CLASSIFICACAO" p
                              where p."CO_MONITORAMENTO" = e."CO_MONITORAMENTO"),
               'fichas', e."QT_FICHAS",
               'dias', t.dias,
               'visto', exists (select 1 from public."RL_ENCERRAMENTO_EDITAL_USUARIO" v
                                 where v."CO_MONITORAMENTO" = e."CO_MONITORAMENTO"
                                   and v."CO_USUARIO" = v_usuario),
               'minha', jsonb_build_object(
                 'fichas', t.minhas,
                 'percentual', round(100.0 * t.minhas / nullif(e."QT_FICHAS", 0), 1),
                 'melhor_dia', (
                   select jsonb_build_object('dia', d.dia, 'qt', d.qt)
                     from (select (f."DT_CONCLUSAO" at time zone 'America/Sao_Paulo')::date as dia,
                                  count(*) as qt
                             from public."TB_FICHA_ANALISE" f
                            where f."CO_MONITORAMENTO" = e."CO_MONITORAMENTO"
                              and f."TP_SITUACAO" = 'CONCLUIDA'
                              and f."CO_USUARIO_CONCLUSAO" = v_usuario
                            group by 1) d
                    order by d.qt desc, d.dia
                    limit 1),
                 'fechou', e."CO_USUARIO_FECHOU" = v_usuario))
             order by e."DT_CONCLUSAO", e."NU_EDITAL")
        from private."FC_EDITAIS_ENCERRADOS"() e
        cross join lateral (
          select count(*) filter (where f."CO_USUARIO_CONCLUSAO" = v_usuario) as minhas,
                 count(distinct (f."DT_CONCLUSAO" at time zone 'America/Sao_Paulo')::date) as dias
            from public."TB_FICHA_ANALISE" f
           where f."CO_MONITORAMENTO" = e."CO_MONITORAMENTO"
             and f."TP_SITUACAO" = 'CONCLUIDA') t
       where t.minhas > 0), '[]'::jsonb));
end;
$$;

--
-- Name: FUNCTION obter_encerramentos_do_edital(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_encerramentos_do_edital() IS 'Tela de encerramento e selos do perfil (20261021180000): os editais encerrados (private."FC_EDITAIS_ENCERRADOS") em que quem chama concluiu ao menos uma ficha, com os totais (inscritos da pré-classificação, fichas concluídas, dias com conclusão em Brasília), se já viu a tela e só a contribuição de quem chama (fichas, % do total, melhor dia, se fechou o edital). Sessão e perfil ativo.';

--
-- Name: obter_entrevistas_do_edital(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_entrevistas_do_edital(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_ENTREVISTAS_EDITAL"(p_edital, 1);
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_cfg public."TB_ENTREVISTA_EDITAL";
  v_eu uuid;
  v_lista uuid := private."FC_LISTA_CONVOCACAO_VIGENTE"(p_edital);
begin
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital;
  select * into v_cfg from public."TB_ENTREVISTA_EDITAL" where "CO_MONITORAMENTO" = p_edital;
  select p.id into v_eu from private.current_profile() p;
  return json_build_object(
    'edital', json_build_object('id', v_m.id, 'edital', v_m.edital, 'unidade', v_m.unidade, 'area', v_area,
                               'treinamento', private."FC_EH_TREINAMENTO"(v_m."ST_TREINAMENTO")),
    'pode_editar', private.pode_recurso('entrevistas', 2),
    'pode_gerar_lista', private.pode_recurso('classificacao', 2),
    'admin_global', private.is_master(),
    'meu_perfil', v_eu,
    'configuracao', case when v_cfg."CO_MONITORAMENTO" is null then null else json_build_object(
        'roteiro', private."FC_ROTEIRO_JSON"(v_cfg."CO_ROTEIRO"), 'banca', v_cfg."DS_BANCA",
        'lancamento', v_cfg."TP_LANCAMENTO", 'atualizado_em', v_cfg."DT_ATUALIZACAO") end,
    'regra_classificacao', (
      select json_build_object('versao', r."NU_VERSAO_VIGENTE", 'convocacao', h."DS_CONFIGURACAO" -> 'convocacao',
                               'desempate', h."DS_CONFIGURACAO" -> 'desempate',
                               'empate_final', h."DS_CONFIGURACAO" -> 'empate_final')
        from public."TB_REGRA_CLASSIFICACAO" r
        join public."TH_REGRA_CLASSIFICACAO" h
          on h."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
       where r."CO_MONITORAMENTO" = p_edital),
    'lista_convocacao', case when v_lista is null then null else json_build_object(
        'lista', private."FC_LISTA_CLASSIFICACAO_JSON"(v_lista),
        'retrato', (select l."DS_RESULTADO" from public."TB_LISTA_CLASSIFICACAO" l
                     where l."CO_LISTA_CLASSIFICACAO" = v_lista)) end,
    'avaliadores', coalesce((
      select json_agg(json_build_object('id', b."CO_AVALIADOR", 'nome', b."NO_AVALIADOR", 'origem', b."NO_ORIGEM",
               'banca', b."NU_BANCA", 'perfil', b."CO_PERFIL_USUARIO", 'ativo', b."ST_ATIVO" = 'S',
               -- As competências que o membro avalia (do roteiro do edital); nulo = todas.
               'competencias', (select json_agg(l."CO_COMPETENCIA" order by k."NU_ORDEM")
                   from public."TB_ENTREVISTA_AVALIADOR_COMPETENCIA" l
                   join public."TB_ROTEIRO_COMPETENCIA" k on k."CO_COMPETENCIA" = l."CO_COMPETENCIA"
                  where l."CO_AVALIADOR" = b."CO_AVALIADOR" and k."CO_ROTEIRO" = v_cfg."CO_ROTEIRO"))
             order by b."NU_BANCA", b."NO_ORIGEM", b."NO_AVALIADOR")
        from public."TB_ENTREVISTA_AVALIADOR" b where b."CO_MONITORAMENTO" = p_edital), '[]'::json),
    'convocados', coalesce((
      select json_agg(json_build_object('id', e."CO_ENTREVISTA", 'analise_id', e."CO_ANALISE_CURRICULAR",
               'candidato', e."NO_CANDIDATO", 'codigo', e."CO_CANDIDATO", 'vaga', e."CO_VAGA", 'cargo', e."NO_CARGO",
               'modalidade', e."DS_MODALIDADE", 'banca', e."NU_BANCA", 'compareceu', e."ST_COMPARECEU",
               'nota', e."VL_NOTA_TOTAL", 'parecer', e."TP_PARECER", 'nota_analise', a.nota_final_ajustada,
               'justificativa', e."DS_JUSTIFICATIVA_BANCA",
               'observacoes', coalesce((select json_agg(json_build_object('avaliador', o."CO_AVALIADOR", 'texto', o."DS_OBSERVACAO",
                      'atualizado_em', o."DT_ATUALIZACAO") order by o."DT_ATUALIZACAO")
                   from public."TB_ENTREVISTA_OBSERVACAO_AVALIADOR" o where o."CO_ENTREVISTA" = e."CO_ENTREVISTA"), '[]'::json),
               'avaliacoes', coalesce((select json_agg(json_build_object('competencia', x."CO_COMPETENCIA",
                      'avaliador', x."CO_AVALIADOR", 'nota', x."VL_NOTA",
                      'aspectos', coalesce((select json_agg(json_build_object('aspecto', y."CO_ASPECTO", 'nota', y."VL_NOTA"))
                          from public."TB_ENTREVISTA_AVALIACAO_ASPECTO" y
                         where y."CO_ENTREVISTA" = x."CO_ENTREVISTA" and y."CO_COMPETENCIA" = x."CO_COMPETENCIA"
                           and y."CO_AVALIADOR" = x."CO_AVALIADOR"), '[]'::json)))
                   from public."TB_ENTREVISTA_AVALIACAO" x where x."CO_ENTREVISTA" = e."CO_ENTREVISTA"), '[]'::json),
               'notas', coalesce((select json_agg(json_build_array(n."NU_ORDEM", n."VL_NOTA") order by n."NU_ORDEM")
                   from public."TB_ENTREVISTA_NOTA" n where n."CO_ENTREVISTA" = e."CO_ENTREVISTA"), '[]'::json))
             order by e."CO_VAGA", e."NO_CANDIDATO")
        from public."TB_ENTREVISTA" e
        left join public."TB_ANALISE_CURRICULAR" a on a.id = e."CO_ANALISE_CURRICULAR"
       where e."CO_MONITORAMENTO" = p_edital and e."TP_ORIGEM" = 'sistema' and e."ST_ATIVO" = 'S'), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION obter_entrevistas_do_edital(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_entrevistas_do_edital(p_edital uuid) IS 'Condução da entrevista de um edital: configuração (roteiro, banca, lançamento), a lista de convocação vigente da Classificação com o retrato (lista_convocacao), a regra vigente da Classificação (convocação, desempate e empate final), banca (com as competências de cada membro; nulo = todas) e convocados com as notas, a justificativa da banca e as observações dos avaliadores; pode_editar, pode_gerar_lista, admin_global e meu_perfil.';

--
-- Name: obter_equipe_edital(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_equipe_edital(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_coordena boolean := coalesce(private."FC_PAPEL_AVALIACAO"(p_edital) = 'COORDENADOR', false);
  v_numero text;
begin
  select private."FC_NUMERO_EDITAL"(m.edital) into v_numero from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  return json_build_object(
    'papel', private."FC_PAPEL_AVALIACAO"(p_edital),
    'pode_coordenar', v_coordena,
    'gestores', coalesce((
      select json_agg(json_build_object('usuario', u.user_id, 'nome', coalesce(u.nome, u.email),
                                        'email', case when v_coordena then u.email end)
             order by coalesce(u.nome, u.email))
        from public."TB_PERFIL_USUARIO" u
       where u.ativo and u.user_id is not null and private."FC_GESTOR_DO_EDITAL"(u.id, p_edital)), '[]'::json),
    'equipe', coalesce((
      select json_agg(json_build_object(
               'id', r."CO_ANALISTA_EDITAL", 'usuario', r."CO_USUARIO", 'nome', coalesce(u.nome, u.email, 'Conta removida'),
               'email', case when v_coordena then u.email end, 'papel', r."TP_PAPEL", 'vaga', r."CO_VAGA",
               'limite', r."QT_LIMITE_FICHA", 'desde', r."DT_CRIACAO",
               'nivel', case when u.id is null then 0 else private."FC_NIVEL_AVALIACAO_DO_PERFIL"(u.id) end,
               'ativo_no_sistema', coalesce(u.ativo, false))
             order by r."TP_PAPEL", coalesce(u.nome, u.email), r."CO_VAGA" nulls first)
        from public."RL_ANALISTA_EDITAL" r
        left join public."TB_PERFIL_USUARIO" u on u.user_id = r."CO_USUARIO"
       where r."CO_MONITORAMENTO" = p_edital and r."ST_ATIVO" = 'S'), '[]'::json),
    -- Quem pode entrar na equipe: só para a coordenação.
    'pessoas', case when v_coordena then coalesce((
      select json_agg(json_build_object('usuario', u.user_id, 'nome', coalesce(u.nome, u.email), 'email', u.email,
                                        'nivel', private."FC_NIVEL_AVALIACAO_DO_PERFIL"(u.id),
                                        'gestor', private."FC_GESTOR_DO_EDITAL"(u.id, p_edital))
             order by coalesce(u.nome, u.email))
        from public."TB_PERFIL_USUARIO" u
       where u.ativo and u.user_id is not null
         and private."FC_NIVEL_AVALIACAO_DO_PERFIL"(u.id) >= 2
         and private."FC_PERFIL_VE_EDITAL"(u.id, p_edital)), '[]'::json) else '[]'::json end,
    'vagas', coalesce((
      select json_agg(x.vaga order by x.vaga)
        from (select s."CO_VAGA" as vaga from public."TB_SELECAO_VAGA" s
               where s."CO_MONITORAMENTO" = p_edital and s."CO_VAGA" ~ '^[0-9]{1,20}$'
              union
              select v."CO_VAGA" from public."TB_EMPREGARE_VAGA" v where v."CO_MONITORAMENTO" = p_edital
              union
              select a.codigo_vaga from public."TB_ANALISE_CURRICULAR" a
               where a."CO_AREA" = v_area and a.ativo and a.codigo_vaga ~ '^[0-9]{1,20}$'
                 and private."FC_NUMERO_EDITAL"(a.edital) = v_numero) x), '[]'::json)
  );
end;
$_$;

--
-- Name: FUNCTION obter_equipe_edital(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_equipe_edital(p_edital uuid) IS 'A equipe da avaliação documental do edital (json): gestores (coordenação automática), as linhas ativas de RL_ANALISTA_EDITAL com o nível de cada pessoa, as vagas do edital e, só para a coordenação, os e-mails e as pessoas que podem entrar (Editor ou mais em avaliacao_documental que veem o edital). Desde 20261016130000, só a coordenação do edital (FC_EXIGIR_COORD_AVALIACAO: Editor, área e papel COORDENADOR ou admin global; os demais recebem 42501): a aba é só da coordenação.';

--
-- Name: obter_espelhos_de_nota(uuid, text[], text, text[], text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_espelhos_de_nota(p_edital uuid, p_vagas text[] DEFAULT NULL::text[], p_filtro text DEFAULT 'TODOS'::text, p_codigos text[] DEFAULT NULL::text[], p_apos text DEFAULT NULL::text, p_limite integer DEFAULT 200, p_regras text[] DEFAULT NULL::text[]) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 3);
  v_limite integer := least(greatest(coalesce(p_limite, 200), 1), 200);
  v_filtro text := upper(coalesce(nullif(btrim(p_filtro), ''), 'TODOS'));
  v_codigos text[];
  v_apos uuid;
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_fichas json;
  v_regras json;
  v_ultimo uuid;
  v_n integer;
  v_nao_concluidos json;
begin
  if private."FC_PAPEL_AVALIACAO"(p_edital) is distinct from 'COORDENADOR' then
    raise exception 'Só o administrador e a coordenação do edital geram os espelhos de nota em massa'
      using errcode = '42501';
  end if;
  if v_filtro not in ('TODOS', 'APTOS', 'INAPTOS') then
    raise exception 'Filtro inválido: use TODOS, APTOS ou INAPTOS' using errcode = '22023';
  end if;
  if p_codigos is not null then
    select coalesce(array_agg(distinct btrim(c)), '{}') into v_codigos
      from unnest(p_codigos) c where nullif(btrim(c), '') is not null;
    if cardinality(v_codigos) > 5000 then
      raise exception 'No máximo 5.000 códigos por vez' using errcode = '22023';
    end if;
  end if;
  if nullif(btrim(p_apos), '') is not null then
    begin
      v_apos := btrim(p_apos)::uuid;
    exception when invalid_text_representation then
      raise exception 'p_apos inválido' using errcode = '22023';
    end;
  end if;

  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital;

  with pagina as (
    select f."CO_FICHA_ANALISE" as id, f."CO_VAGA", f."CO_REGRA_ANALISE", f."NU_VERSAO_REGRA",
           f."TP_RESULTADO", f."VL_NOTA_FINAL", f."DS_LANCAMENTO", f."DS_RESULTADO",
           c."CO_CANDIDATO_EMPREGARE", c."NO_CANDIDATO", f."CO_EMPREGARE_CANDIDATO"
      from public."TB_FICHA_ANALISE" f
      join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
     where f."CO_MONITORAMENTO" = p_edital
       and f."TP_SITUACAO" = 'CONCLUIDA'
       and (v_apos is null or f."CO_FICHA_ANALISE" > v_apos)
       and (case
              when v_codigos is not null then c."CO_CANDIDATO_EMPREGARE"::text = any (v_codigos)
              else (p_vagas is null or f."CO_VAGA" = any (p_vagas))
                   and (v_filtro = 'TODOS'
                        or (v_filtro = 'APTOS' and f."TP_RESULTADO" = 'APTO')
                        or (v_filtro = 'INAPTOS' and f."TP_RESULTADO" is distinct from 'APTO'))
            end)
     order by f."CO_FICHA_ANALISE"
     limit v_limite
  )
  select coalesce(json_agg(json_build_object(
           'id', p.id,
           'codigo', p."CO_CANDIDATO_EMPREGARE",
           'nome', p."NO_CANDIDATO",
           'vaga', p."CO_VAGA",
           'cargo', pv."NO_CARGO",
           'modalidade', pc."NO_MODALIDADE",
           'posicao', pc."NU_POSICAO",
           'art', pc."VL_ART",
           'resultado', p."TP_RESULTADO",
           'nota_final', p."VL_NOTA_FINAL",
           'regra', p."CO_REGRA_ANALISE" || ':' || p."NU_VERSAO_REGRA",
           'declarada', case when jsonb_typeof(p."DS_RESULTADO" -> 'declarada') = 'object'
                             then p."DS_RESULTADO" -> 'declarada' else '{}'::jsonb end,
           'lancamento', private."FC_LANCAMENTO_DO_ESPELHO"(p."DS_LANCAMENTO"))
           order by p.id), '[]'::json),
         max(p.id::text)::uuid,
         count(*),
         (select json_object_agg(r.chave, h."DS_CONFIGURACAO")
            from (select distinct p2."CO_REGRA_ANALISE", p2."NU_VERSAO_REGRA",
                         p2."CO_REGRA_ANALISE" || ':' || p2."NU_VERSAO_REGRA" as chave
                    from pagina p2) r
            join public."TH_REGRA_ANALISE" h
              on h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and h."NU_VERSAO" = r."NU_VERSAO_REGRA"
           where p_regras is null or not (r.chave = any (p_regras)))
    into v_fichas, v_ultimo, v_n, v_regras
    from pagina p
    left join public."TB_PRE_CLASSIFICACAO" pc
      on pc."CO_MONITORAMENTO" = p_edital and pc."CO_EMPREGARE_CANDIDATO" = p."CO_EMPREGARE_CANDIDATO"
    left join public."TB_PRE_CLASSIF_VAGA" pv
      on pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" = p."CO_VAGA";

  -- Os códigos colados com ficha no edital que ainda não está concluída (só na primeira página).
  if v_codigos is not null and v_apos is null then
    select coalesce(json_agg(json_build_object('codigo', c."CO_CANDIDATO_EMPREGARE", 'situacao', f."TP_SITUACAO")
                             order by c."CO_CANDIDATO_EMPREGARE"), '[]'::json)
      into v_nao_concluidos
      from public."TB_FICHA_ANALISE" f
      join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
     where f."CO_MONITORAMENTO" = p_edital
       and f."TP_SITUACAO" is distinct from 'CONCLUIDA'
       and c."CO_CANDIDATO_EMPREGARE"::text = any (v_codigos);
  end if;

  return json_build_object(
    'schema_version', 1,
    'edital', json_build_object('id', p_edital, 'rotulo', private."FC_ROTULO_DO_EDITAL"(v_m.edital),
                                'area', coalesce(v_m."CO_AREA", v_area)),
    'documental', private."FC_DOCUMENTAL_DO_EDITAL"(p_edital),
    'regras', coalesce(v_regras, '{}'::json),
    'fichas', v_fichas,
    'nao_concluidos', v_nao_concluidos,
    -- Página cheia: pode haver mais (a próxima chamada passa p_apos = proximo).
    'proximo', case when v_n = v_limite then v_ultimo end
  );
end;
$$;

--
-- Name: FUNCTION obter_espelhos_de_nota(p_edital uuid, p_vagas text[], p_filtro text, p_codigos text[], p_apos text, p_limite integer, p_regras text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_espelhos_de_nota(p_edital uuid, p_vagas text[], p_filtro text, p_codigos text[], p_apos text, p_limite integer, p_regras text[]) IS 'Espelhos de nota em massa (20261015180000): das fichas CONCLUÍDAS do edital, só o que a montagem do espelho individual usa (nome, código, vaga, cargo, modalidade e ART da pré-classificação, resultado e nota final gravados, a declarada por critério de DS_RESULTADO, o lançamento sem empregador nem nome de curso: FC_LANCAMENTO_DO_ESPELHO, e a chave regra:versão) e a configuração de cada regra usada que não está em p_regras. Páginas de até 200 pela chave da ficha (p_apos = "proximo" da anterior; nulo = acabou). Filtros: p_vagas (nulo = todas) e p_filtro TODOS/APTOS/INAPTOS, ou p_codigos (códigos do candidato na Empregare, até 5.000; ignora vagas e filtro; na primeira página, nao_concluidos = os códigos com ficha não concluída). Só administrador e coordenação do edital (FC_PAPEL_AVALIACAO = COORDENADOR; 42501). Não grava nada.';

--
-- Name: obter_ficha_analise(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_ficha_analise(p_ficha uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_papel text;
  v_uid uuid := (select auth.uid());
  v_regra record;
  v_vigente integer;
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_envio uuid;
begin
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha;
  v_papel := private."FC_EXIGIR_VER_FICHA"(v_f);
  select * into v_regra from private."FC_REGRA_VIGENTE_FICHA"(p_ficha);
  select r."NU_VERSAO_VIGENTE" into v_vigente from public."TB_REGRA_ANALISE" r where r."CO_REGRA_ANALISE" = v_f."CO_REGRA_ANALISE";
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = v_f."CO_MONITORAMENTO";
  v_envio := private."FC_RESPOSTA_VIGENTE_EMPREGARE"(v_f."CO_EMPREGARE_CANDIDATO");
  return json_build_object(
    'schema_version', 1,
    'gerado_em', now(),
    'edital', json_build_object('id', v_m.id, 'rotulo', private."FC_ROTULO_DO_EDITAL"(v_m.edital), 'area', v_m."CO_AREA"),
    'papel', v_papel,
    'eu', v_uid,
    'pode_editar', v_f."TP_SITUACAO" = 'EM_ANALISE' and v_f."CO_USUARIO_RESERVA" = v_uid and v_f."DT_RESERVA_EXPIRA" > now(),
    'pode_reabrir', v_f."TP_SITUACAO" = 'CONCLUIDA' and coalesce(v_papel, '') = 'COORDENADOR',
    'ficha', (private."FC_FICHA_ANALISE_JSON"(p_ficha)::jsonb || jsonb_build_object(
               'lancamento', v_f."DS_LANCAMENTO", 'resultado', v_f."DS_RESULTADO", 'parecer', v_f."DS_PARECER",
               'tp_resultado', v_f."TP_RESULTADO", 'nota_final', v_f."VL_NOTA_FINAL", 'nota_apurada', v_f."VL_NOTA_APURADA",
               'rascunho_em', v_f."DT_RASCUNHO", 'concluida_em', v_f."DT_CONCLUSAO",
               'concluida_por', (select coalesce(u.nome, u.email) from public."TB_PERFIL_USUARIO" u where u.user_id = v_f."CO_USUARIO_CONCLUSAO"))),
    'regra', json_build_object('versao', v_regra.p_versao, 'vigente', v_vigente, 'situacao', v_regra.p_situacao,
                               'configuracao', v_regra.p_configuracao),
    'documental', private."FC_DOCUMENTAL_DO_EDITAL"(v_f."CO_MONITORAMENTO"),
    'declarada_gravada', (select json_build_object('total', p."VL_NOTA_DECLARADA", 'parciais', p."DS_NOTA_DECLARADA" -> 'parciais',
                                                   'art', p."VL_ART", 'divergente', p."ST_DIVERGENTE" = 'S')
                            from public."TB_PRE_CLASSIFICACAO" p
                           where p."CO_MONITORAMENTO" = v_f."CO_MONITORAMENTO" and p."CO_EMPREGARE_CANDIDATO" = v_f."CO_EMPREGARE_CANDIDATO"),
    'respostas', private."FC_RESPOSTAS_DA_FICHA"(v_f."CO_EMPREGARE_CANDIDATO", v_regra.p_configuracao),
    -- O CPF que o candidato informou no questionário (20261015050000), para a identificação
    -- no cabeçalho da ficha: a resposta como veio (a tela formata 000.000.000-00), só a
    -- pergunta do CPF de DS_COLUNA_ORIGINAL ("Para fins de identificação de seu cadastro…").
    'cpf_informado', (select nullif(btrim(e.value), '')
                        from public."TB_EMPREGARE_CANDIDATO" c,
                             lateral jsonb_each_text(c."DS_COLUNA_ORIGINAL") e
                       where c."CO_EMPREGARE_CANDIDATO" = v_f."CO_EMPREGARE_CANDIDATO"
                         and e.key ~* '^\s*pergunta' and e.key ~* 'cpf'
                         and nullif(btrim(e.value), '') is not null
                       order by (e.key ~* 'identifica') desc, e.key
                       limit 1),
    -- As linhas que as respostas do candidato já dão (job Python, 20261009190000): a tela só exibe.
    'sugestoes', coalesce((select s."DS_SUGESTAO" from public."TB_SUGESTAO_FICHA" s
                            where s."CO_MONITORAMENTO" = v_f."CO_MONITORAMENTO"
                              and s."CO_EMPREGARE_CANDIDATO" = v_f."CO_EMPREGARE_CANDIDATO"), '{}'::jsonb),
    -- O que o robô leu dos anexos da resposta vigente (job Python, 20261009220000): a tela só exibe;
    -- quem decide é o avaliador. Sem o texto do documento, nem nome, nem CPF: só os booleanos.
    'leituras', coalesce((
      select json_agg(json_build_object('resposta', r."CO_RESPOSTA_QUESTIONARIO", 'pergunta', l."CO_PERGUNTA_EMPREGARE",
                                        'arquivo', l."NU_ARQUIVO", 'situacao', l."TP_SITUACAO", 'metodo', l."TP_METODO",
                                        'documento', l."TP_DOCUMENTO", 'paginas', l."QT_PAGINA",
                                        'nome_confere', case l."ST_NOME_CONFERE" when 'S' then true when 'N' then false end,
                                        'cpf_confere', case l."ST_CPF_CONFERE" when 'S' then true when 'N' then false end,
                                        'itens', l."DS_ITEM", 'alertas', l."DS_ALERTA", 'resumo', l."DS_RESUMO",
                                        'lido_em', l."DT_LEITURA")
                      order by l."CO_PERGUNTA_EMPREGARE", l."NU_ARQUIVO")
        from public."TB_LEITURA_ARQUIVO" l
        join public."TB_EMPREGARE_RESPOSTA" r on r."CO_EMPREGARE_RESPOSTA" = l."CO_EMPREGARE_RESPOSTA"
       where l."CO_EMPREGARE_RESPOSTA" = v_envio), '[]'::json),
    -- Links da Empregare (dado restrito, só aqui): o do candidato, o das candidaturas, os da resposta vigente
    -- do questionário e dos anexos dela (20261009210000) e, à parte, os dos envios anteriores.
    'empregare', (select json_build_object(
                           'link_candidato', c."DS_LINK_DETALHE",
                           'capturado_em', c."DT_CAPTURA_LINK",
                           'vaga_interno', ev."CO_VAGA_INTERNO",
                           'link_vaga', case when ev."CO_VAGA_INTERNO" is not null
                                             then 'https://corporate.empregare.com/empresa/vagas/candidaturas/' || ev."CO_VAGA_INTERNO" end,
                           'respostas', coalesce((
                             select json_agg(json_build_object('resposta', r."CO_RESPOSTA_QUESTIONARIO",
                                                               'link_impressao', r."DS_LINK_IMPRESSAO",
                                                               'perguntas', r."QT_PERGUNTA", 'anexos', r."QT_ANEXO",
                                                               'capturado_em', r."DT_CAPTURA")
                                             order by r."CO_RESPOSTA_QUESTIONARIO")
                               from public."TB_EMPREGARE_RESPOSTA" r
                              where r."CO_EMPREGARE_RESPOSTA" = v_envio), '[]'::json),
                           'anexos', coalesce((
                             select json_agg(json_build_object('resposta', r."CO_RESPOSTA_QUESTIONARIO",
                                                               'pergunta', a."CO_PERGUNTA_EMPREGARE",
                                                               'arquivo', a."NU_ARQUIVO", 'ordem', a."NU_ORDEM",
                                                               'enunciado', a."DS_ENUNCIADO",
                                                               'coluna', a."DS_COLUNA", 'tipo', a."TP_LINK",
                                                               'link', a."DS_LINK")
                                             order by r."CO_RESPOSTA_QUESTIONARIO", a."CO_PERGUNTA_EMPREGARE", a."NU_ARQUIVO")
                               from public."TB_EMPREGARE_ANEXO" a
                               join public."TB_EMPREGARE_RESPOSTA" r on r."CO_EMPREGARE_RESPOSTA" = a."CO_EMPREGARE_RESPOSTA"
                              where r."CO_EMPREGARE_RESPOSTA" = v_envio), '[]'::json),
                           -- As outras respostas com alguma pergunta lida, da mais nova para a mais antiga.
                           'envios_anteriores', coalesce((
                             select json_agg(json_build_object('resposta', r."CO_RESPOSTA_QUESTIONARIO",
                                                               'link_impressao', r."DS_LINK_IMPRESSAO",
                                                               'perguntas', r."QT_PERGUNTA",
                                                               'capturado_em', r."DT_CAPTURA",
                                                               'arquivos', coalesce((
                                                                 select json_agg(json_build_object('pergunta', a."CO_PERGUNTA_EMPREGARE",
                                                                                                   'arquivo', a."NU_ARQUIVO", 'ordem', a."NU_ORDEM",
                                                                                                   'enunciado', a."DS_ENUNCIADO",
                                                                                                   'coluna', a."DS_COLUNA", 'tipo', a."TP_LINK",
                                                                                                   'link', a."DS_LINK")
                                                                                 order by a."NU_ORDEM" nulls last, a."CO_PERGUNTA_EMPREGARE", a."NU_ARQUIVO")
                                                                   from public."TB_EMPREGARE_ANEXO" a
                                                                  where a."CO_EMPREGARE_RESPOSTA" = r."CO_EMPREGARE_RESPOSTA"), '[]'::json))
                                             order by r."CO_RESPOSTA_QUESTIONARIO"::numeric desc)
                               from public."TB_EMPREGARE_RESPOSTA" r
                              where r."CO_EMPREGARE_CANDIDATO" = c."CO_EMPREGARE_CANDIDATO"
                                and r."CO_EMPREGARE_RESPOSTA" is distinct from v_envio
                                and r."QT_PERGUNTA" > 0), '[]'::json))
                    from public."TB_EMPREGARE_CANDIDATO" c
                    left join public."TB_EMPREGARE_VAGA" ev on ev."CO_VAGA" = c."CO_VAGA"
                   where c."CO_EMPREGARE_CANDIDATO" = v_f."CO_EMPREGARE_CANDIDATO"),
    'historico', coalesce((
      select json_agg(json_build_object('versao', h."NU_VERSAO", 'acao', h."TP_ACAO", 'situacao', h."TP_SITUACAO",
                                        'quando', h."DT_REGISTRO", 'por', coalesce(u.nome, u.email), 'motivo', h."DS_MOTIVO",
                                        'resultado', h."TP_RESULTADO", 'nota_final', h."VL_NOTA_FINAL",
                                        'alteracao', h."DS_ALTERACAO")
                      order by h."CO_HISTORICO_FICHA" desc)
        from (select * from public."TH_FICHA_ANALISE" x where x."CO_FICHA_ANALISE" = p_ficha
               order by x."CO_HISTORICO_FICHA" desc limit 200) h
        left join public."TB_PERFIL_USUARIO" u on u.user_id = h."CO_USUARIO"), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION obter_ficha_analise(p_ficha uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_ficha_analise(p_ficha uuid) IS 'A ficha para analisar (json): o cabeçalho (sem CPF nem contato), o lançamento e o resultado gravados, a regra com que é analisada (a vigente; a da conclusão, se concluída — AM-2.3), a nota mínima e os níveis da regra de classificação, a nota declarada e a ART da pré-classificação, as respostas da Empregare SÓ das perguntas que a regra liga, os links da Empregare capturados pelo robô (empregare: link_candidato da página de detalhes, vaga_interno e link_vaga das candidaturas, respostas [{resposta, link_impressao, perguntas, anexos, capturado_em}] e anexos [{resposta, pergunta, arquivo, ordem, enunciado, coluna, tipo, link}] SÓ da resposta vigente do questionário — a mais nova com pergunta lida, FC_RESPOSTA_VIGENTE_EMPREGARE — e envios_anteriores [{resposta, link_impressao, perguntas, capturado_em, arquivos: [{pergunta, arquivo, ordem, enunciado, coluna, tipo, link}]}] com as outras, da mais nova para a mais antiga (20261009210000); dado restrito, só aqui), as sugestões de títulos, cursos e vínculos tiradas das respostas pelo job Python (20261009190000), as leituras dos anexos da resposta vigente feitas pelo robô (leituras [{resposta, pergunta, arquivo, situacao, metodo, documento, paginas, nome_confere, cpf_confere, itens, alertas, resumo, lido_em}], 20261009220000), o histórico (até 200, com as alterações) e se quem chama pode editar (reserva vigente, em análise) ou reabrir (coordenação, concluída). Vê: coordenação e revisão; o analista, só nas vagas dele; o leitor, só concluída.';

--
-- Name: obter_ficha_analise_leve(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_ficha_analise_leve(p_ficha uuid, p_regra_chave text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v json := public.obter_ficha_analise(p_ficha);
  v_chave text;
  v_omitir boolean;
begin
  if v is null or json_typeof(v -> 'regra') is distinct from 'object' then
    return v;
  end if;
  v_chave := md5(coalesce((v -> 'regra' -> 'configuracao')::text, 'null'));
  v_omitir := p_regra_chave is not null and p_regra_chave = v_chave;
  -- json (não jsonb): as chaves seguem na ordem de sempre.
  return (
    select json_object_agg(x.k, x.v order by x.o)
      from (
        select t.k,
               case when t.k <> 'regra' then t.v
                    else (select json_object_agg(r.k, r.v order by r.o)
                            from (select rr.k, case when rr.k = 'configuracao' and v_omitir then null::json else rr.v end as v, rr.o
                                    from json_each(t.v) with ordinality rr(k, v, o)
                                  union all
                                  select 'chave', to_json(v_chave), 100000) r)
               end as v,
               t.o
          from json_each(v) with ordinality t(k, v, o)
        union all
        select 'regra_omitida', to_json(v_omitir), 100000
      ) x);
end;
$$;

--
-- Name: FUNCTION obter_ficha_analise_leve(p_ficha uuid, p_regra_chave text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_ficha_analise_leve(p_ficha uuid, p_regra_chave text) IS 'obter_ficha_analise com regra.chave (md5 da configuração); com p_regra_chave igual, regra.configuracao vem null e regra_omitida true: a tela usa a que já guardou (≈29 KB a menos por ficha; 20261014231000). Mesma permissão.';

--
-- Name: obter_fila_avaliacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_fila_avaliacao(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return private."FC_FILA_AVALIACAO_JSON"(p_edital, null);
end;
$$;

--
-- Name: FUNCTION obter_fila_avaliacao(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_fila_avaliacao(p_edital uuid) IS 'A fila da avaliação documental do edital (json, schema_version 2): papel de quem está logado (coordena, pode pegar), a distribuição da regra, os inscritos do núcleo (no lote ou com ficha viva: FC_NO_NUCLEO_DA_FILA) com a entrada no lote, o motivo da decisão da coordenação e a ficha (situação, responsável, reserva vigente, versão, rascunho e, concluída, resultado e nota; nome do candidato, sem CPF nem contato), as contagens e a versão dos de fora do lote (fora_do_lote; as linhas vêm de obter_fila_fora_do_lote), as vagas, os analistas com as pendentes, quantos do lote ainda estão sem ficha e os filtros salvos de quem chama. O analista vê só as vagas que analisa (permissão avaliada por vaga). Exige avaliacao_documental >= leitor, a área e o recorte da coordenação.';

--
-- Name: obter_fila_avaliacao_desde(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_fila_avaliacao_desde(p_edital uuid, p_desde timestamp with time zone DEFAULT NULL::timestamp with time zone, p_marca text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_parcial boolean := p_desde is not null and p_marca is not null;
  v_uid uuid := (select auth.uid());
  v_papel text;
  v_vagas text[];
  v_vagas_json json;
  v_ids uuid[];
  v json;
  v_marca text;
  v_barata text;
  v_partes text[] := string_to_array(coalesce(p_marca, ''), '.');
  v_total bigint;
begin
  -- A permissão primeiro (a montagem confere de novo, lá dentro).
  perform private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);

  -- Marca barata (20261103171500): nenhuma fonte da fila mudou desde a leitura anterior
  -- (nem quem lê) e nenhuma reserva do edital venceu desde p_desde − 2 min: a parcial
  -- vazia, sem montar nada. Mesmo snapshot da montagem (função stable).
  v_barata := private."FC_MARCA_DA_LEITURA"('fila_avaliacao', p_edital::text);
  if v_parcial and v_barata is not null and cardinality(v_partes) = 3
     and v_partes[2] = v_barata and v_partes[3] ~ '^[0-9]{1,9}$'
     and not exists (
       select 1 from public."TB_FICHA_ANALISE" f
        where f."CO_MONITORAMENTO" = p_edital
          and f."DT_RESERVA_EXPIRA" >= p_desde - interval '2 minutes'
          and f."DT_RESERVA_EXPIRA" <= now()) then
    return json_build_object(
      'marca', p_marca, 'parcial', true, 'total_nucleo', v_partes[3]::bigint,
      'candidatos', '[]'::json, 'saiu', '[]'::json);
  end if;

  -- A marca de sempre, com o que a montagem usaria: papel, recorte de vagas do analista e
  -- as vagas no mesmo JSON da chave "vagas".
  v_papel := private."FC_PAPEL_AVALIACAO"(p_edital);
  if coalesce(v_papel, '') = 'ANALISTA' then
    v_vagas := private."FC_VAGAS_DO_ANALISTA"(p_edital, v_uid);
  end if;
  v_vagas_json := coalesce((
    select json_agg(json_build_object('codigo', pv."CO_VAGA", 'cargo', pv."NO_CARGO", 'lotacao', pv."NO_LOTACAO")
                    order by pv."CO_VAGA")
      from public."TB_PRE_CLASSIF_VAGA" pv
     where pv."CO_MONITORAMENTO" = p_edital
       and (v_vagas is null or pv."CO_VAGA" = any (v_vagas))), '[]'::json);
  select md5(concat_ws('|', count(*), max(a."DT_ATUALIZACAO"), max(a."CO_EXECUCAO"),
                       v_uid::text, v_papel, v_vagas_json::text))
    into v_marca
    from public."TB_PRE_CLASSIFICACAO" a
   where a."CO_MONITORAMENTO" = p_edital;

  -- Outra marca (pré-classificação regravada, outro recorte, papel ou pessoa): a inteira.
  if v_parcial and v_partes[1] is distinct from v_marca then
    v_parcial := false;
  end if;

  if v_parcial then
    -- As fichas que mudaram desde a leitura anterior (a margem de 2 min cobre as transações
    -- que gravaram com now() anterior à leitura e terminaram depois dela).
    select coalesce(array_agg(f."CO_EMPREGARE_CANDIDATO"), '{}'::uuid[])
      into v_ids
      from public."TB_FICHA_ANALISE" f
     where f."CO_MONITORAMENTO" = p_edital
       and (f."DT_ATUALIZACAO" >= p_desde - interval '2 minutes'
            or f."DT_RESERVA_EXPIRA" >= p_desde - interval '2 minutes');
  end if;

  -- Parcial: só as linhas desses inscritos e o total do núcleo; senão, a fila inteira.
  v := private."FC_FILA_AVALIACAO_JSON"(p_edital, case when v_parcial then v_ids end);
  if v is null then
    return null;
  end if;

  -- A marca que sai: a de sempre, a barata e o total do núcleo (o da parcial vazia).
  v_total := case when v_parcial then (v ->> 'total_nucleo')::bigint
                  else json_array_length(v -> 'candidatos') end;
  if v_barata is not null then
    v_marca := v_marca || '.' || v_barata || '.' || v_total::text;
  end if;

  if not v_parcial then
    return (
      select json_object_agg(x.k, x.v order by x.o)
        from (select t.k, t.v, t.o from json_each(v) with ordinality t(k, v, o)
              union all select 'marca', to_json(v_marca), 100000
              union all select 'parcial', to_json(false), 100001) x);
  end if;

  return (
    select json_object_agg(x.k, x.v order by x.o)
      from (select t.k, t.v, t.o
              from json_each(v) with ordinality t(k, v, o)
             where t.k not in ('candidatos', 'vagas', 'total_nucleo')
            union all select 'marca', to_json(v_marca), 100000
            union all select 'parcial', to_json(true), 100001
            union all select 'total_nucleo', v -> 'total_nucleo', 100002
            union all select 'candidatos', v -> 'candidatos', 100003
            union all
            select 'saiu', coalesce((
                     select json_agg(i)
                       from unnest(v_ids) i
                      where not exists (select 1 from json_array_elements(v -> 'candidatos') e
                                         where (e ->> 'id')::uuid = i)), '[]'::json), 100004) x);
end;
$_$;

--
-- Name: FUNCTION obter_fila_avaliacao_desde(p_edital uuid, p_desde timestamp with time zone, p_marca text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_fila_avaliacao_desde(p_edital uuid, p_desde timestamp with time zone, p_marca text) IS 'obter_fila_avaliacao só com o que mudou (20261014231000; sem montar a fila inteira desde 20261019150000; marca conferida antes de montar desde 20261022181000): sem p_desde ou com outra marca, a fila inteira com marca e parcial false; com o gerado_em e a marca da leitura anterior, só as linhas do núcleo cuja ficha mudou (ou cuja reserva vence) desde p_desde − 2 min, os ids que saíram do núcleo (saiu), total_nucleo e o resto da fila sem vagas. Desde 20261103171500 a marca leva a marca barata (fila_avaliacao) e o total do núcleo: sem fonte mudada e sem reserva vencida desde p_desde − 2 min, a parcial vazia (marca, parcial, total_nucleo, candidatos e saiu vazios) sem montar nada. Mesma permissão.';

--
-- Name: obter_fila_fora_do_lote(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_fila_fora_do_lote(p_edital uuid, p_apos uuid DEFAULT NULL::uuid, p_limite integer DEFAULT 1000) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
  v_papel text := private."FC_PAPEL_AVALIACAO"(p_edital);
  v_uid uuid := (select auth.uid());
  v_limite integer := least(greatest(coalesce(p_limite, 1000), 1), 2000);
  v_vagas text[];
  v_linhas json;
  v_ultimo uuid;
  v_n integer;
begin
  if coalesce(v_papel, '') = 'ANALISTA' then
    v_vagas := private."FC_VAGAS_DO_ANALISTA"(p_edital, v_uid);
  end if;
  select coalesce(json_agg(l.linha order by l.id), '[]'::json), max(l.id::text)::uuid, count(*)
    into v_linhas, v_ultimo, v_n
    from private."FC_LINHAS_DA_FILA"(p_edital, v_vagas, false, p_apos, v_limite) l;
  return json_build_object(
    'schema_version', 1,
    'edital', p_edital,
    'area', v_area,
    'candidatos', v_linhas,
    -- Página cheia: pode haver mais (a próxima chamada passa p_apos = proximo).
    'proximo', case when v_n = v_limite then v_ultimo end
  );
end;
$$;

--
-- Name: FUNCTION obter_fila_fora_do_lote(p_edital uuid, p_apos uuid, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_fila_fora_do_lote(p_edital uuid, p_apos uuid, p_limite integer) IS 'Os inscritos de fora do lote na fila da avaliação documental (eliminados e ranqueados sem ficha viva: FC_NO_NUCLEO_DA_FILA), no mesmo formato de obter_fila_avaliacao, em páginas de até 2.000 em ordem do id do inscrito: p_apos = o "proximo" da página anterior (nulo na primeira); "proximo" nulo = acabou. O analista vê só as vagas que analisa. Exige avaliacao_documental >= leitor, a área e o recorte da coordenação.';

--
-- Name: obter_inicio_da_sessao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_inicio_da_sessao() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Sessao nao localizada.' using errcode = '28000';
  end if;

  return jsonb_build_object(
    'configuracao', coalesce((
      select jsonb_agg(jsonb_build_object(
               'chave', c.chave, 'valor', c.valor, 'descricao', c.descricao))
        from public."TB_CONFIGURACAO" c
    ), '[]'::jsonb),
    'paineis', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id, 'codigo', p.codigo, 'titulo', p.titulo, 'icone', p.icone,
               'url', p.url, 'ordem', p.ordem, 'ativo', p.ativo,
               'em_manutencao', p.em_manutencao, 'tipo_abertura', p.tipo_abertura)
             order by p.ordem)
        from public."TB_PAINEL_EXTERNO" p
    ), '[]'::jsonb),
    'abas', public.listar_abas_do_menu()::jsonb,
    'situacao', public.obter_situacao_do_sistema()::jsonb,
    'unidades', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id_unidade', u.id_unidade, 'sigla', u.sigla,
               'nome_oficial', u.nome_oficial, 'tipo', u.tipo,
               'uf_sede', u.uf_sede, 'ativo', u.ativo)
             order by u.tipo, u.nome_oficial)
        from public."TD_UNIDADE" u
       where u.ativo = true
    ), '[]'::jsonb)
  );
end;
$$;

--
-- Name: FUNCTION obter_inicio_da_sessao(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_inicio_da_sessao() IS 'O que a entrada do app lê depois do perfil, numa chamada: configuração (TB_CONFIGURACAO), painéis externos (TB_PAINEL_EXTERNO), catálogo de abas (listar_abas_do_menu), situação do sistema (obter_situacao_do_sistema) e unidades ativas (TD_UNIDADE). SECURITY INVOKER: cada parte passa pela RLS de sempre.';

--
-- Name: obter_lista_classificacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_lista_classificacao(p_lista uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_l public."TB_LISTA_CLASSIFICACAO";
begin
  select * into v_l from public."TB_LISTA_CLASSIFICACAO" where "CO_LISTA_CLASSIFICACAO" = p_lista;
  if v_l."CO_LISTA_CLASSIFICACAO" is null then
    raise exception 'Lista não encontrada' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(v_l."CO_MONITORAMENTO", 1);
  return json_build_object('lista', private."FC_LISTA_CLASSIFICACAO_JSON"(p_lista), 'resultado', v_l."DS_RESULTADO");
end;
$$;

--
-- Name: FUNCTION obter_lista_classificacao(p_lista uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_lista_classificacao(p_lista uuid) IS 'Uma lista gerada com o retrato (para exportar de novo). Exige classificacao >= leitor no edital da lista.';

--
-- Name: obter_listas_pre_classificacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_listas_pre_classificacao(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
begin
  return (jsonb_build_object('schema_version', 1, 'edital', p_edital) || private."FC_PRE_LISTAS"(p_edital))::json;
end;
$$;

--
-- Name: FUNCTION obter_listas_pre_classificacao(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_listas_pre_classificacao(p_edital uuid) IS 'A aba Listas oficiais da Pré-classificação: regra de classificação, listas PROVISORIA/LOTE registradas e quantos há em cada lote. Coordenação do edital.';

--
-- Name: obter_marcos_da_area(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_marcos_da_area(p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_ano integer := extract(year from now() at time zone 'America/Sao_Paulo')::integer;
  v_escopos integer;
  v_no_ano bigint;
  v_total bigint;
begin
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if not private."FC_PODE_AREA"(p_area) then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;

  -- Concluídas de editais inativos (escopo 'inativo') e análises ativas de editais
  -- ativos (escopo 'ativo'), lidas do pacote do painel de análises.
  select count(distinct c."TP_ESCOPO"),
         coalesce(sum(x.value::bigint) filter (where x.key ~ '^\d+$' and x.key::integer >= v_ano), 0),
         coalesce(sum(x.value::bigint), 0)
    into v_escopos, v_no_ano, v_total
    from private."TA_PAINEL_ANALISE" c
    left join lateral json_each_text(c."DS_CONCLUIDAS_POR_ANO") x on true
   where c."CO_AREA" = p_area
     and c."TP_ESCOPO" in ('ativo', 'inativo')
     and c."DS_CONCLUIDAS_POR_ANO" is not null;

  if v_escopos < 2 then
    -- Sem o pacote (banco recém-reiniciado, área nova): conta na hora.
    select count(*) filter (where v.data_analise >= make_date(v_ano, 1, 1)), count(*)
      into v_no_ano, v_total
      from public."VW_ANALISES_DASHBOARD_BASE_TODOS" v
      join public."TB_ANALISE_CURRICULAR" a on a.id = v.id
     where a."CO_AREA" = p_area
       and (v.edital_ativo is false or v.ativo is true)
       and v.status_consolidado in ('Aprovado', 'Reprovado');
  end if;

  return json_build_object(
    'area', p_area,
    'ano', v_ano,
    'concluidas_no_ano', v_no_ano,
    'concluidas_total', v_total,
    'gerado_em', now());
end;
$_$;

--
-- Name: FUNCTION obter_marcos_da_area(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_marcos_da_area(p_area text) IS 'Marcos da área para a Visão geral: análises concluídas (Aprovado ou Reprovado) no ano e no total, de análises ativas e de editais inativos. Lê as concluídas por ano do pacote do painel de análises (TA_PAINEL_ANALISE.DS_CONCLUIDAS_POR_ANO, 20261007220000); sem o pacote, conta na hora.';

--
-- Name: obter_matriz_acessos(text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_matriz_acessos(p_busca text DEFAULT ''::text, p_offset integer DEFAULT 0, p_coordenacao text DEFAULT ''::text, p_grupo text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gestor text := private."FC_EXIGIR_GESTOR_DE_ACESSOS"();
  v_busca text := left(coalesce(p_busca, ''), 100);
  v_filtro text := coalesce(p_coordenacao, '');
  v_eu public."TB_PERFIL_USUARIO" := private.current_profile();
  resultado jsonb;
begin
  -- Coordenador vê só a própria coordenação, qualquer que seja o filtro pedido.
  if v_gestor = 'coordenador' then v_filtro := private."FC_COORDENACAO_USUARIO"(); end if;

  with filtrados as (
    select u.* from public."TB_PERFIL_USUARIO" u
     where u.ativo
       and (coalesce(u.nome, '') ilike '%' || v_busca || '%' or u.email ilike '%' || v_busca || '%')
       and (v_filtro = '' or (v_filtro = '__sem__' and u."CO_COORDENACAO" is null) or u."CO_COORDENACAO" = v_filtro)
       and (coalesce(p_grupo, '') = '' or u.perfil = p_grupo)
  ), usuarios as (
    -- Último acesso só das 30 pessoas da página (FC_ULTIMO_ACESSO: login, uso ou presença).
    select p.*, private."FC_ULTIMO_ACESSO"(p.user_id, p.email) as ultimo_acesso_real
      from (select f.* from filtrados f order by lower(f.email), f.id limit 30 offset greatest(p_offset, 0)) p
  ), recursos as (
    select m recurso from unnest(private."FC_RECURSOS_MODULO"()) m
    union all select 'painel:' || id from public."TB_PAINEL_EXTERNO" where ativo
    union all select 'area:' || a."CO_AREA" from public."TB_AREA" a
  )
  select jsonb_build_object(
    'usuarios', coalesce((select jsonb_agg(jsonb_build_object(
        'id', u.id, 'user_id', u.user_id, 'email', u.email, 'nome', u.nome, 'grupo', u.perfil, 'ativo', u.ativo,
        'coordenacao', u."CO_COORDENACAO",
        'revisao_conta', u.updated_at::text,
        'cadastrado_em', u.created_at,
        'ultimo_acesso', u.ultimo_acesso_real,
        'convite_pendente', u.ultimo_acesso_real is null,
        'admin_global', coalesce((select a."ST_ADMIN_GLOBAL" from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = u.perfil), false),
        'areas_efetivas', to_jsonb(private."FC_AREAS_DO_PERFIL"(u.id)),
        'permissoes', (select jsonb_object_agg(r.recurso,
            case when r.recurso like 'area:%' then jsonb_build_object(
                'nivel', case when exists (select 1 from public."RL_PERFIL_USUARIO_AREA" x
                                            where x."CO_PERFIL_USUARIO" = u.id and 'area:' || x."CO_AREA" = r.recurso)
                              then 'leitor' else 'sem_acesso' end,
                'origem', 'excecao', 'nivel_grupo', 'sem_acesso', 'revisao', 0)
            else jsonb_build_object(
                'nivel', coalesce(g.nivel, private."FC_NIVEL_DO_GRUPO"(u.perfil, r.recurso)),
                'origem', case when g.nivel is null then 'grupo' else 'excecao' end,
                'nivel_grupo', private."FC_NIVEL_DO_GRUPO"(u.perfil, r.recurso),
                'revisao', coalesce(g.revisao, 0))
            end)
          from recursos r
          left join public."TB_PERMISSAO_RECURSO" g on g.perfil_usuario_id = u.id and g.recurso = r.recurso)
      ) order by lower(u.email), u.id) from usuarios u), '[]'::jsonb),
    'total', (select count(*) from filtrados),
    'areas', coalesce((select jsonb_agg(jsonb_build_object('id', a."CO_AREA", 'titulo', a."NO_AREA") order by a."NU_ORDEM") from public."TB_AREA" a), '[]'::jsonb),
    'paineis', coalesce((select jsonb_agg(to_jsonb(e) order by e.ordem, e.titulo) from public."TB_PAINEL_EXTERNO" e where e.ativo), '[]'::jsonb),
    'grupos', coalesce((select jsonb_agg(private."FC_GRUPO_ACESSO_JSON"(a."CO_GRUPO_ACESSO") order by a."NU_ORDEM", a."NO_GRUPO_ACESSO")
                          from public."TB_GRUPO_ACESSO" a), '[]'::jsonb),
    'coordenacoes', coalesce((select jsonb_agg(private."FC_COORDENACAO_JSON"(c."CO_COORDENACAO") order by c."NO_COORDENACAO")
                                from public."TB_COORDENACAO" c
                               where v_gestor = 'admin' or c."CO_COORDENACAO" = private."FC_COORDENACAO_USUARIO"()), '[]'::jsonb),
    'teto', jsonb_build_object(
        'admin_global', v_gestor = 'admin',
        'usuario_id', v_eu.id,
        'coordenacao', private."FC_COORDENACAO_USUARIO"(),
        'niveis', (select jsonb_object_agg(m, private."FC_TETO_DO_GESTOR"(m)) from unnest(private."FC_RECURSOS_MODULO"()) m),
        'paineis', coalesce((select jsonb_agg(e.id::text) from public."TB_PAINEL_EXTERNO" e
                              where e.ativo and (v_gestor = 'admin' or private.pode_recurso('painel:' || e.id))), '[]'::jsonb)),
    'historico', coalesce((select jsonb_agg(to_jsonb(h)) from (
        select h.*, u.email, autor.email autor
          from public."TH_PERMISSAO_RECURSO" h
          left join public."TB_PERFIL_USUARIO" u on u.id = h.perfil_usuario_id
          left join lateral (select a.email from public."TB_PERFIL_USUARIO" a where a.user_id = h.alterado_por order by a.updated_at desc limit 1) autor on true
         where v_gestor = 'admin' or u."CO_COORDENACAO" = private."FC_COORDENACAO_USUARIO"()
         order by h.alterado_em desc, h.id desc limit 50) h), '[]'::jsonb)
  ) into resultado;
  return resultado;
end;
$$;

--
-- Name: FUNCTION obter_matriz_acessos(p_busca text, p_offset integer, p_coordenacao text, p_grupo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_matriz_acessos(p_busca text, p_offset integer, p_coordenacao text, p_grupo text) IS 'Configurações › Acessos: pessoas da página (30), níveis por módulo, áreas, grupos, coordenações, teto do gestor de acessos e histórico. ultimo_acesso = private."FC_ULTIMO_ACESSO" (login, uso ou presença); convite_pendente = nenhum acesso.';

--
-- Name: obter_meu_resumo_do_dia(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_meu_resumo_do_dia(p_data date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_data date := coalesce(p_data, (now() at time zone 'America/Sao_Paulo')::date);
  v_perfil public."TB_PERFIL_USUARIO";
  v_editais uuid[];
  v_demandas uuid[];
  v_itens jsonb;
begin
  if (select auth.uid()) is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;
  v_perfil := private.current_profile();
  if v_perfil.id is null then
    raise exception 'Perfil não encontrado.' using errcode = '42501';
  end if;

  -- Do que a pessoa é responsável e ainda vê.
  select coalesce(array_agg(m.id), '{}') into v_editais
    from public."RL_RESPONSAVEL_EDITAL" r
    join public."TB_MONITORAMENTO_INDIGENA" m on m.id = r."CO_MONITORAMENTO"
   where r."CO_PERFIL_USUARIO" = v_perfil.id and m.ativo
     and (private.is_master() or private."FC_PODE_VER_EDITAL"(m.id));
  select coalesce(array_agg(d."CO_DEMANDA_INTERNA"), '{}') into v_demandas
    from public."RL_DEMANDA_INTERNA_RESPONSAVEL" r
    join public."TB_DEMANDA_INTERNA" d on d."CO_DEMANDA_INTERNA" = r."CO_DEMANDA_INTERNA"
   where r."CO_PERFIL_USUARIO" = v_perfil.id and d."ST_ATIVO" = 'S'
     and private."FC_PODE_VER_DEMANDA"(d."CO_AREA", d."CO_MONITORAMENTO");

  with itens as (
    select 'etapa'::text as tipo, c.id::text as id, c.atividade as titulo,
           m.id as edital_id, m.edital, m.unidade, m."CO_AREA" as area,
           c.data_inicio as inicio, c.data_fim as fim, false as pode_concluir
      from public."TB_CRONOGRAMA_MONIT_INDIG" c
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = c.monitoramento_id
     where c.monitoramento_id = any (v_editais)
       and c.concluida is not true
       and (c.data_inicio between v_data and v_data + 7 or c.data_fim between v_data and v_data + 7)
    union all
    select 'demanda', d."CO_DEMANDA_INTERNA"::text, d."NO_DEMANDA"::text,
           d."CO_MONITORAMENTO", m.edital, m.unidade, d."CO_AREA",
           d."DT_INICIO", d."DT_FIM",
           private."FC_PODE_EDITAR_DEMANDA"(d."CO_AREA", d."CO_MONITORAMENTO")
      from public."TB_DEMANDA_INTERNA" d
      left join public."TB_MONITORAMENTO_INDIGENA" m on m.id = d."CO_MONITORAMENTO"
     where d."CO_DEMANDA_INTERNA" = any (v_demandas)
       and d."ST_CONCLUIDA" = 'N'
       and d."DT_INICIO" <= v_data + 7
  ),
  marcos as (
    select i.*, x.marco, x.dia
      from itens i
      cross join lateral (values
        (case when i.inicio = i.fim then 'dia_unico' else 'inicio' end, i.inicio),
        ('fim', i.fim)) x(marco, dia)
     where (x.marco <> 'fim' or i.fim <> i.inicio)
       and x.dia between v_data and v_data + 7
  ),
  linhas as (
    select case when m.dia = v_data then 'hoje' else 'proximos' end as grupo,
           m.dia as ordem, m.titulo,
           jsonb_build_object(
             'tipo', m.tipo, 'id', m.id, 'titulo', m.titulo,
             'edital_id', m.edital_id, 'edital', m.edital, 'unidade', m.unidade, 'area', m.area,
             'data_inicio', m.inicio, 'data_fim', m.fim,
             'marco', m.marco, 'data', m.dia, 'pode_concluir', m.pode_concluir) as item
      from marcos m
    union all
    select 'atrasadas', i.fim, i.titulo,
           jsonb_build_object(
             'tipo', i.tipo, 'id', i.id, 'titulo', i.titulo,
             'edital_id', i.edital_id, 'edital', i.edital, 'unidade', i.unidade, 'area', i.area,
             'data_inicio', i.inicio, 'data_fim', i.fim,
             'marco', 'fim', 'data', i.fim, 'pode_concluir', i.pode_concluir)
      from itens i
     where i.tipo = 'demanda' and i.fim < v_data
  )
  select jsonb_build_object(
           'hoje', coalesce(jsonb_agg(l.item order by l.ordem, l.titulo) filter (where l.grupo = 'hoje'), '[]'::jsonb),
           'proximos', coalesce(jsonb_agg(l.item order by l.ordem, l.titulo) filter (where l.grupo = 'proximos'), '[]'::jsonb),
           'atrasadas', coalesce(jsonb_agg(l.item order by l.ordem, l.titulo) filter (where l.grupo = 'atrasadas'), '[]'::jsonb))
    into v_itens
    from linhas l;

  return v_itens || jsonb_build_object(
    'data', v_data,
    'perfil', v_perfil.id,
    'nome', coalesce(nullif(btrim(v_perfil.nome), ''), split_part(coalesce(v_perfil.email, ''), '@', 1)),
    'responsavel', cardinality(v_editais) > 0 or cardinality(v_demandas) > 0,
    'editais', to_jsonb(v_editais),
    'demandas', to_jsonb(v_demandas),
    'mostrar_ao_entrar', coalesce((
      select p."ST_MOSTRAR_RESUMO_DIA" = 'S' from public."TB_PREFERENCIA_USUARIO" p
       where p."CO_PERFIL_USUARIO" = v_perfil.id), true));
end;
$$;

--
-- Name: FUNCTION obter_meu_resumo_do_dia(p_data date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_meu_resumo_do_dia(p_data date) IS 'Resumo do dia de quem chama (padrão: hoje em Brasília), só leitura: hoje, proximos (7 dias) e atrasadas (demandas), dos editais e demandas de que é responsável e ainda vê; editais/demandas dela, responsavel e mostrar_ao_entrar. 20261104130000.';

--
-- Name: obter_minha_solicitacao_acesso(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_minha_solicitacao_acesso() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object('id', s.id, 'status', s.status, 'nome', s.nome, 'setor', s.setor,
                            'justificativa', s.justificativa, 'created_at', s.created_at,
                            'updated_at', s.updated_at, 'avaliado_em', s.avaliado_em,
                            'observacao_admin', s.observacao_admin, 'coordenacao', s."CO_COORDENACAO",
                            'coordenacao_nome', c."NO_COORDENACAO",
                            'area', s."CO_AREA", 'area_nome', a."NO_AREA",
                            'cargo', s."CO_CARGO_SOLICITADO",
                            'cargo_rotulo', private."FC_CARGO_SOLICITACAO_ACESSO"(null, s."CO_CARGO_SOLICITADO"),
                            'cargo_outro', s."DS_CARGO_OUTRO",
                            'motivo_recusa', s."CO_MOTIVO_RECUSA")
    from public."TB_SOLICITACAO_ACESSO" s
    left join public."TB_COORDENACAO" c on c."CO_COORDENACAO" = s."CO_COORDENACAO"
    left join public."TB_AREA" a on a."CO_AREA" = s."CO_AREA"
   where s.user_id = (select auth.uid())
      or lower(s.email) = lower(coalesce((select auth.jwt() ->> 'email'), '-'))
   order by (s.status = 'pendente') desc, s.created_at desc
   limit 1;
$$;

--
-- Name: FUNCTION obter_minha_solicitacao_acesso(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_minha_solicitacao_acesso() IS 'Último pedido de acesso de quem está autenticado, com área, cargo, lotação (setor), coordenação e motivo da recusa.';

--
-- Name: obter_modelo_espelho_nota(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_modelo_espelho_nota(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_modelo public."TB_MODELO_ESPELHO_NOTA";
begin
  perform private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
  select * into v_modelo from public."TB_MODELO_ESPELHO_NOTA" m where m."CO_MONITORAMENTO" = p_edital;
  return json_build_object(
    'versao', coalesce(v_modelo."NU_VERSAO", 0),
    'textos', coalesce(v_modelo."DS_TEXTOS", '{}'::jsonb),
    'atualizado_em', v_modelo."DT_ATUALIZACAO",
    'atualizado_por', (select private."FC_NOME_E_SOBRENOME"(p.nome)
                         from public."TB_PERFIL_USUARIO" p
                        where p.user_id = v_modelo."CO_USUARIO_ATUALIZACAO"
                        limit 1),
    'pode_editar', coalesce(private."FC_PAPEL_AVALIACAO"(p_edital) = 'COORDENADOR', false));
end;
$$;

--
-- Name: FUNCTION obter_modelo_espelho_nota(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_modelo_espelho_nota(p_edital uuid) IS 'Modelo do espelho de nota do edital (20261019120000): versao (0 = nunca salvo), textos (só as diferenças do padrão do código; {} = padrão), atualizado_em, atualizado_por (nome e sobrenome do cadastro) e pode_editar (coordenação do edital). Para todos da avaliação documental do edital (FC_EXIGIR_AVALIACAO_EDITAL nível 1), porque o espelho da ficha usa o modelo. Não grava nada.';

--
-- Name: obter_modulos_e_abas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_modulos_e_abas() RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_master() then
    raise exception 'Somente o administrador global gerencia módulos e abas' using errcode = '42501';
  end if;
  return json_build_object(
    'sistema', (select json_build_object(
        'situacao', s."TP_SITUACAO", 'mensagem', s."DS_MENSAGEM_MANUTENCAO",
        'previsao', s."DT_PREVISAO_RETORNO", 'atualizado_em', s."DT_ATUALIZACAO",
        'comemoracoes', s."ST_COMEMORACAO" = 'S')
      from public."TB_SITUACAO_SISTEMA" s where s."CO_SITUACAO_SISTEMA" = 1),
    'areas', coalesce((select json_agg(json_build_object(
        'co_area', a."CO_AREA", 'no_area', a."NO_AREA", 'ativo', a."ST_ATIVO" = 'S',
        'situacao', a."TP_SITUACAO", 'mensagem', a."DS_MENSAGEM_MANUTENCAO",
        'previsao', a."DT_PREVISAO_RETORNO",
        'abas', coalesce((select json_agg(json_build_object(
            'co_aba', r."CO_ABA", 'ativo', r."ST_ATIVO" = 'S', 'situacao', r."TP_SITUACAO",
            'mensagem', r."DS_MENSAGEM_MANUTENCAO", 'previsao', r."DT_PREVISAO_RETORNO")
            order by coalesce(r."NU_ORDEM", b."NU_ORDEM"), r."CO_ABA")
          from public."RL_ABA_AREA" r join public."TB_ABA" b on b."CO_ABA" = r."CO_ABA"
          where r."CO_AREA" = a."CO_AREA"), '[]'::json))
        order by a."NU_ORDEM") from public."TB_AREA" a), '[]'::json),
    'abas', coalesce((select json_agg(json_build_object(
        'co_aba', b."CO_ABA", 'no_aba', b."NO_ABA", 'ds_icone', b."DS_ICONE", 'nu_ordem', b."NU_ORDEM",
        'ativo', b."ST_ATIVO" = 'S', 'situacao', b."TP_SITUACAO", 'mensagem', b."DS_MENSAGEM_MANUTENCAO",
        'previsao', b."DT_PREVISAO_RETORNO", 'beta', b."ST_BETA" = 'S')
        order by b."NU_ORDEM") from public."TB_ABA" b), '[]'::json),
    'paineis', coalesce((select json_agg(json_build_object(
        'id', p.id, 'titulo', p.titulo, 'ativo', p.ativo, 'em_manutencao', p.em_manutencao)
        order by p.ordem, p.titulo) from public."TB_PAINEL_EXTERNO" p), '[]'::json),
    'historico', coalesce((select json_agg(h order by h.quando desc) from (
        select t."TP_ESCOPO" escopo, t."CO_AREA" area, t."CO_ABA" aba, t."CO_PAINEL" painel,
               t."DS_CAMPO" campo, t."DS_VALOR_ANTERIOR" anterior, t."DS_VALOR_NOVO" novo,
               t."DS_MOTIVO" motivo, t."DT_ALTERACAO" quando,
               (select u.email from public."TB_PERFIL_USUARIO" u where u.user_id = t."CO_USUARIO" limit 1) autor
          from public."TH_SITUACAO_MODULO" t
         order by t."DT_ALTERACAO" desc, t."CO_HISTORICO_SITUACAO" desc limit 50) h), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION obter_modulos_e_abas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_modulos_e_abas() IS 'Árvore de Módulos e abas para Configurações (sistema, áreas com suas abas, abas, painéis externos e as 50 últimas mudanças). Só administrador global.';

--
-- Name: obter_perguntas_carga_analise(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_perguntas_carga_analise(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
  v_coordena boolean := coalesce(private."FC_PAPEL_AVALIACAO"(p_edital) = 'COORDENADOR', false);
  v_r public."TB_RESUMO_PERGUNTA_EDITAL";
  v_hash varchar;
begin
  -- Perguntas e respostas da última carga: só para a coordenação, que liga os blocos.
  if v_coordena then
    select * into v_r from public."TB_RESUMO_PERGUNTA_EDITAL" r where r."CO_MONITORAMENTO" = p_edital;
    v_hash := private."FC_HASH_VAGA_EDITAL"(p_edital);
  end if;
  return json_build_object(
    'schema_version', 1,
    'perguntas', coalesce(v_r."DS_PERGUNTA", '[]'::jsonb),
    'candidatos', v_r."QT_CANDIDATO",
    'atualizado_em', v_r."DT_ATUALIZACAO",
    'atual', v_r."CO_MONITORAMENTO" is not null and v_r."DS_HASH_VAGA" = v_hash);
end;
$$;

--
-- Name: FUNCTION obter_perguntas_carga_analise(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_perguntas_carga_analise(p_edital uuid) IS 'As perguntas da última carga da Empregare do edital com as respostas encontradas (json; do resumo TB_RESUMO_PERGUNTA_EDITAL, calculado em Python pelo robô ao fim de cada carga): só as respostas que aparecem 2+ vezes, até 30 por pergunta; as únicas viram "outras". atual = o resumo é da carga vigente. Só para a coordenação do edital (os demais recebem lista vazia). Exige avaliacao_documental >= leitor, a área e o recorte da coordenação.';

--
-- Name: obter_pre_classificacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_pre_classificacao(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET work_mem TO '16MB'
    AS $$
begin
  return (private."FC_PRE_CABECALHO"(p_edital)
          || (private."FC_PRE_LISTAS"(p_edital) - 'lotes')
          || jsonb_build_object('vagas', private."FC_PRE_VAGAS"(p_edital) , 'candidatos', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', a."CO_EMPREGARE_CANDIDATO", 'vaga', a."CO_VAGA",
               'codigo', c."CO_CANDIDATO_EMPREGARE", 'nome', c."NO_CANDIDATO",
               'situacao', a."TP_SITUACAO", 'motivo_codigo', a."CO_MOTIVO_ELIMINACAO", 'motivo', a."DS_MOTIVO_ELIMINACAO",
               'art', a."VL_ART", 'nota', a."VL_NOTA_ORDEM", 'origem_nota', a."TP_ORIGEM_NOTA",
               'declarada', a."VL_NOTA_DECLARADA", 'divergente', a."ST_DIVERGENTE" = 'S', 'modalidade', a."NO_MODALIDADE",
               'declarada_completa', (a."DS_NOTA_DECLARADA" ->> 'completa')::boolean,
               'declarada_congelada', a."VL_DECLARADA_CONGELADA", 'congelada_em', a."DT_CONGELAMENTO_DECLARADA",
               'posicao', a."NU_POSICAO", 'posicao_modalidade', a."NU_POSICAO_MODALIDADE",
               'lote', a."NU_LOTE", 'lista_lote', a."CO_LISTA_LOTE", 'entrada', a."TP_ENTRADA_LOTE",
               'motivo_entrada', a."DS_MOTIVO_ENTRADA", 'entrada_em', a."DT_ENTRADA_LOTE",
               'decisao', case when d."CO_DECISAO_LOTE" is not null then jsonb_build_object(
                 'motivo', d."DS_MOTIVO", 'por', coalesce(ud.nome, ud.email), 'em', d."DT_DECISAO",
                 'situacao_regra', d."TP_SITUACAO_REGRA", 'motivo_regra', d."DS_MOTIVO_ELIMINACAO_REGRA") end)
             order by a."CO_VAGA", a."TP_SITUACAO" = 'ELIMINADO', a."NU_POSICAO", c."CO_CANDIDATO_EMPREGARE")
        from public."TB_PRE_CLASSIFICACAO" a
        join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = a."CO_EMPREGARE_CANDIDATO"
        left join public."TB_DECISAO_LOTE" d
          on d."CO_MONITORAMENTO" = a."CO_MONITORAMENTO" and d."CO_EMPREGARE_CANDIDATO" = a."CO_EMPREGARE_CANDIDATO" and d."ST_ATIVO" = 'S'
        left join public."TB_PERFIL_USUARIO" ud on ud.user_id = d."CO_USUARIO_DECISAO"
       where a."CO_MONITORAMENTO" = p_edital), '[]'::jsonb)))::json;
end;
$$;

--
-- Name: FUNCTION obter_pre_classificacao(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_pre_classificacao(p_edital uuid) IS 'A pré-classificação do edital para a aba Pré-classificação (json): regra vigente, regra de classificação (textos do documento), última execução do job que tratou o edital, se há execução em andamento, cada vaga da Empregare com o resumo (quadro, tamanho do lote, linha de corte, divergências, avisos), os inscritos (código, nome, situação, motivo, ART, nota declarada — completa ou não, congelada e quando, desde 20261007170000 —, posição, lote e motivo da entrada e, desde 20261007200000, a decisão vigente da coordenação: motivo, quem, quando e a situação pela regra; sem CPF nem contato), por vaga quantos estão no lote pela regra e por decisão (desde 20261007200000) e as listas PROVISORIA e LOTE registradas. Desde 20261016130000, só a coordenação do edital (FC_EXIGIR_COORD_AVALIACAO: Editor, área e papel COORDENADOR ou admin global; os demais recebem 42501): a aba é só da coordenação.';

--
-- Name: obter_pre_classificacao_se_mudou(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_pre_classificacao_se_mudou(p_edital uuid, p_versao text DEFAULT NULL::text) RETURNS json
    LANGUAGE sql STABLE
    SET search_path TO ''
    SET work_mem TO '16MB'
    AS $$
  select private."FC_SE_MUDOU_EM_COLUNAS"(public.obter_pre_classificacao(p_edital)::jsonb, p_versao, 'candidatos', array[
    'vaga', 'situacao', 'motivo_codigo', 'motivo', 'origem_nota', 'divergente', 'modalidade',
    'declarada_completa', 'lista_lote', 'entrada', 'motivo_entrada', 'entrada_em', 'congelada_em',
    'lote', 'decisao']);
$$;

--
-- Name: FUNCTION obter_pre_classificacao_se_mudou(p_edital uuid, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_pre_classificacao_se_mudou(p_edital uuid, p_versao text) IS 'obter_pre_classificacao com versão (md5 sem gerado_em) e os inscritos em colunas (candidatos_em_colunas, FC_COLUNAS_JSON); com p_versao atual, só { inalterado, versao } (20261014230000). Mesma permissão.';

--
-- Name: obter_previsao_entrevista_edital(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_previsao_entrevista_edital(p_edital uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_estado text;
  v_motivo text;
begin
  if p_edital is null or not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id=p_edital) then
    raise exception 'Edital não encontrado' using errcode='22023';
  end if;
  if not (private.is_master() or
       (private.pode_recurso('entrevistas', 1) and coalesce(private."FC_PODE_VER_EDITAL"(p_edital),false))) then
    raise exception 'Sem permissão para consultar a etapa de entrevista' using errcode='42501';
  end if;
  select x."TP_PREVISAO", x."DS_MOTIVO" into v_estado,v_motivo
    from public."TB_PREVISAO_ENTREVISTA_EDITAL" x where x."CO_MONITORAMENTO"=p_edital;
  return jsonb_build_object(
    'situacao',coalesce(v_estado,'NAO_INFORMADA'),
    'motivo',v_motivo,
    'pode_alterar',private.is_master()
  );
end;
$$;

--
-- Name: obter_publicacao_lista_aprovados(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_publicacao_lista_aprovados(p_edital uuid, p_com_candidatos boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_global boolean := private."FC_ADMIN_GLOBAL_ATIVO"((select auth.uid()));
  v_pode_substituir boolean;
begin
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  if v_m.id is null then raise exception 'Edital não encontrado' using errcode = '22023'; end if;
  if not v_global then
    if not (private.pode_recurso('classificacao', 1) or private.pode_recurso('aprovados', 1)
            or private.pode_recurso('importacao', 2)) then
      raise exception 'Sem permissão para a lista de aprovados' using errcode = '42501';
    end if;
    if not private."FC_PODE_AREA"(v_m."CO_AREA") then
      raise exception 'Sem acesso a esta área' using errcode = '42501';
    end if;
    perform private."FC_EXIGIR_AREA_EDITAL"(p_edital::text);
  end if;
  -- A mesma regra de FC_EXIGIR_PODE_SUBSTITUIR_LISTA.
  v_pode_substituir := private."FC_PODE_SUBSTITUIR_LISTA"()
    or not exists (select 1 from public."TB_LISTA_APROVADO" l where l.edital_id = p_edital::text);

  return json_build_object(
    'edital_id', v_m.id,
    'pode_publicar', (v_global or private.pode_recurso('classificacao', 2)) and v_pode_substituir,
    'pode_substituir', v_pode_substituir,
    'tem_analises', exists (
      select 1 from public."TB_ANALISE_CURRICULAR" a
       where a."CO_AREA" = v_m."CO_AREA" and a.ativo
         and private."FC_NUMERO_EDITAL"(a.edital) = private."FC_NUMERO_EDITAL"(v_m.edital)),
    'resultado_final', (
      select json_build_object('id', l."CO_LISTA_CLASSIFICACAO", 'gerada_em', l."DT_GERACAO",
               'versao_regra', l."NU_VERSAO_REGRA", 'pendencias', l."QT_PENDENCIA",
               'elegiveis', l."QT_ELEGIVEL", 'publicada', l."ST_PUBLICADA" = 'S')
        from public."TB_LISTA_CLASSIFICACAO" l
       where l."CO_MONITORAMENTO" = p_edital and l."TP_LISTA" = 'FINAL'
       order by l."DT_GERACAO" desc limit 1),
    'vigente', (
      select json_build_object(
               'lista_id', l.id, 'origem', l."TP_ORIGEM", 'lista_classificacao_id', l."CO_LISTA_CLASSIFICACAO",
               'importado_em', l.importado_em, 'por', l."NO_USUARIO_IMPORTACAO", 'ativo', l.ativo,
               'arquivo_nome', l.arquivo_nome,
               'candidatos', case when p_com_candidatos then (
                 select coalesce(json_agg(json_build_object(
                          'candidato_id', c.id, 'analise_id', c."CO_ANALISE_CURRICULAR", 'nome', c.nome,
                          'cargo', c.cargo, 'codigo_vaga', c.codigo_vaga, 'classificacao', c.classificacao,
                          'nota', c.nota, 'modalidade', c.modalidade, 'status', c.status,
                          'processo_sei', c.processo_sei, 'matricula', c.matricula, 'sub_judice', c.sub_judice,
                          'alterado_judicialmente', c.alterado_judicialmente)
                        order by c.cargo, c.classificacao nulls last, c.nome), '[]'::json)
                   from public."TB_CANDIDATO_APROVADO" c
                  where c.lista_id = l.id and c.removido_em is null) end)
        from public."TB_LISTA_APROVADO" l
       where l.edital_id = p_edital::text and l.vigente is true),
    'publicacoes', (
      select coalesce(json_agg(json_build_object(
               'id', h."CO_PUBLICACAO", 'origem', h."TP_ORIGEM", 'em', h."DT_PUBLICACAO",
               'por', coalesce(h."NO_USUARIO", h."DS_EMAIL_USUARIO"), 'lista_classificacao_id', h."CO_LISTA_CLASSIFICACAO",
               'versao_regra', h."NU_VERSAO_REGRA", 'candidatos', h."QT_CANDIDATO", 'entram', h."QT_ENTRA",
               'saem', h."QT_SAI", 'mudam', h."QT_MUDA_POSICAO", 'preservados', h."QT_PRESERVADO",
               'sub_judice_mantidos', h."QT_SUB_JUDICE_MANTIDO", 'pendencias', h."DS_PENDENCIA",
               'motivo', h."DS_MOTIVO") order by h."DT_PUBLICACAO" desc), '[]'::json)
        from (select * from public."TH_PUBLICACAO_APROVADO" x
               where x."CO_MONITORAMENTO" = p_edital
               order by x."DT_PUBLICACAO" desc limit 20) h)
  );
end;
$$;

--
-- Name: FUNCTION obter_publicacao_lista_aprovados(p_edital uuid, p_com_candidatos boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_publicacao_lista_aprovados(p_edital uuid, p_com_candidatos boolean) IS 'A lista de aprovados vigente do edital (origem; com p_com_candidatos, os candidatos para a prévia da publicação), o último resultado final da Classificação, se o edital tem análises no sistema e as 20 últimas publicações. Classificação >= leitor, Aprovados >= leitor ou Importação >= editor, a área e o recorte do edital.';

--
-- Name: obter_quadro_de_vagas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_quadro_de_vagas(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_m public."TB_MONITORAMENTO_INDIGENA";
begin
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital;
  if v_m.id is null then raise exception 'Edital não encontrado' using errcode = '22023'; end if;
  if not (private.pode_recurso('nucleo', 1) or private.pode_recurso('calendario', 1) or private.pode_recurso('entrevistas', 1)) then
    raise exception 'Sem permissão para este recurso' using errcode = '42501';
  end if;
  perform private."FC_EXIGIR_AREA_EDITAL"(p_edital::text);
  return json_build_object(
    'edital', p_edital,
    'linhas', coalesce((
      select json_agg(json_build_object('id', q."CO_QUADRO_VAGA", 'ordem', q."NU_ORDEM", 'cargo', q."NO_CARGO",
               'lotacao', q."NO_LOTACAO", 'modalidades', q."DS_MODALIDADE_VAGA", 'vagas_imediatas', q."QT_VAGA_IMEDIATA",
               'cadastro_reserva', q."ST_CADASTRO_RESERVA" = 'S') order by q."NU_ORDEM")
        from public."TB_QUADRO_VAGA_EDITAL" q
       where q."CO_MONITORAMENTO" = p_edital and q."ST_REGISTRO_ATIVO" = 'S'), '[]'::json),
    'origem', (select json_build_object('tipo', q."TP_ORIGEM", 'arquivo', q."DS_ARQUIVO_ORIGEM", 'gravado_em', q."DT_CRIACAO")
                 from public."TB_QUADRO_VAGA_EDITAL" q
                where q."CO_MONITORAMENTO" = p_edital and q."ST_REGISTRO_ATIVO" = 'S' limit 1),
    'vinculos', coalesce((
      select json_agg(json_build_object('vaga', v.codigo_vaga, 'cargo', v.cargo,
               'quadro', private."FC_QUADRO_DA_VAGA"(p_edital, v.cargo)) order by v.cargo)
        from (select a.codigo_vaga, min(a.nome_vaga) cargo
                from public."TB_ANALISE_CURRICULAR" a
               where a."CO_AREA" = v_m."CO_AREA" and a.ativo
                 and private."FC_NUMERO_EDITAL"(a.edital) = private."FC_NUMERO_EDITAL"(v_m.edital)
               group by a.codigo_vaga) v), '[]'::json)
  );
end;
$$;

--
-- Name: FUNCTION obter_quadro_de_vagas(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_quadro_de_vagas(p_edital uuid) IS 'Quadro de vagas vigente do edital, de onde veio e a que linha cada vaga da análise se liga. Núcleo, Calendário ou Entrevistas (leitor) e o edital.';

--
-- Name: obter_rascunho_regra(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_rascunho_regra(p_tipo text, p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := private."FC_EXIGIR_RASCUNHO_REGRA"(p_tipo, p_edital);
begin
  return (
    select json_build_object('conteudo', r."DS_CONTEUDO", 'versao_base', r."NU_VERSAO_BASE",
                             'criado_em', r."DT_CRIACAO", 'atualizado_em', r."DT_ATUALIZACAO")
      from public."TB_RASCUNHO_REGRA" r
     where r."TP_REGRA" = p_tipo and r."CO_MONITORAMENTO" = p_edital and r."CO_USUARIO" = v_uid);
end;
$$;

--
-- Name: FUNCTION obter_rascunho_regra(p_tipo text, p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_rascunho_regra(p_tipo text, p_edital uuid) IS 'O rascunho não salvo de quem chama para a regra do tipo no edital: conteudo, versao_base, criado_em e atualizado_em; null sem rascunho. Só quem edita a regra.';

--
-- Name: obter_regra_analise(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_regra_analise(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_papel text := private."FC_PAPEL_AVALIACAO"(p_edital);
  v_coordena boolean := coalesce(v_papel = 'COORDENADOR', false);
  v_vagas integer;
begin
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital;
  select count(*) into v_vagas
    from public."TB_EMPREGARE_VAGA" v
   where v."CO_MONITORAMENTO" = p_edital and v."TP_SITUACAO" = 'GRAVADA';

  return json_build_object(
    'schema_version', 1,
    'edital', json_build_object('id', v_m.id, 'edital', v_m.edital, 'unidade', v_m.unidade, 'area', v_area,
                                'numero', private."FC_NUMERO_EDITAL"(v_m.edital), 'id_unidade', v_m.id_unidade),
    'papel', v_papel,
    'pode_coordenar', v_coordena,
    'origem', coalesce((select o."TP_ORIGEM" from public."TB_ORIGEM_ANALISE_EDITAL" o where o."CO_MONITORAMENTO" = p_edital), 'PLANILHA'),
    -- Quem não coordena: só o que a Fila usa (versão vigente, nome, situação e
    -- versões só com número e nome); sem configuração, modelos nem aldeias.
    'regra', case when v_coordena then private."FC_REGRA_ANALISE_JSON"(p_edital) else (
      select json_build_object(
               'versao', r."NU_VERSAO_VIGENTE", 'nome', v."NO_VERSAO", 'situacao', r."TP_SITUACAO",
               'versoes', coalesce((
                 select json_agg(json_build_object('versao', h."NU_VERSAO", 'nome', h."NO_VERSAO")
                        order by h."NU_VERSAO" desc)
                   from public."TH_REGRA_ANALISE" h
                  where h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE"), '[]'::json))
        from public."TB_REGRA_ANALISE" r
        join public."TH_REGRA_ANALISE" v
          on v."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and v."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
       where r."CO_MONITORAMENTO" = p_edital) end,
    'modelos', case when not v_coordena then '[]'::json else coalesce((
      select json_agg(json_build_object('codigo', d."CO_MODELO", 'nome', d."NO_MODELO", 'configuracao', d."DS_CONFIGURACAO")
             order by d."CO_MODELO")
        from public."TB_REGRA_ANALISE_MODELO" d where d."ST_ATIVO" = 'S'), '[]'::json) end,
    'nota_minima', (
      select json_build_object('nota_minima', h."DS_CONFIGURACAO" #> '{documental,nota_minima}',
                               'nota_minima_por_nivel', coalesce(h."DS_CONFIGURACAO" #> '{documental,nota_minima_por_nivel}', '{}'::jsonb),
                               'versao_regra_classificacao', r."NU_VERSAO_VIGENTE")
        from public."TB_REGRA_CLASSIFICACAO" r
        join public."TH_REGRA_CLASSIFICACAO" h
          on h."CO_REGRA_CLASSIFICACAO" = r."CO_REGRA_CLASSIFICACAO" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
       where r."CO_MONITORAMENTO" = p_edital),
    'aldeias', case when v_coordena then (
      select json_build_object('quantidade', count(*), 'atualizado_em', max(a."DT_ATUALIZACAO"),
                               'fonte', (array_agg(a."DS_FONTE" order by a."DT_ATUALIZACAO" desc))[1])
        from public."TD_ALDEIA_DSEI" a
       where v_m.id_unidade is not null and a."CO_UNIDADE" = v_m.id_unidade::text and a."ST_ATIVO" = 'S') end,
    'pode_carregar_aldeias', private.is_master(),
    'vagas_empregare', v_vagas,
    'fichas_concluidas', 0
  );
end;
$$;

--
-- Name: FUNCTION obter_regra_analise(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_regra_analise(p_edital uuid) IS 'A regra da avaliação documental do edital (json): vigente e versões, modelos para copiar, nota mínima da regra de classificação, aldeias do DSEI do edital, dono da avaliação, papel de quem está logado e quantas vagas da Empregare têm carga. As perguntas da carga saíram para obter_perguntas_carga_analise (20261009180000). fichas_concluidas fica 0 até as fichas da fase F3. Desde 20261016130000, quem não coordena recebe a resposta enxuta: regra só com versao, nome, situacao e versoes = [{versao, nome}]; modelos vazio; aldeias nulo (papel, pode_coordenar, edital e origem seguem). Exige avaliacao_documental >= leitor, a área e o recorte da coordenação.';

--
-- Name: obter_regra_analise_se_mudou(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_regra_analise_se_mudou(p_edital uuid, p_versao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_marca constant text := private."FC_MARCA_DA_RPC"('obter_regra_analise', p_edital => p_edital);
begin
  if v_marca is null then
    return private."FC_SE_MUDOU"(public.obter_regra_analise(p_edital)::jsonb, p_versao);
  end if;
  if p_versao = v_marca then
    return jsonb_build_object('inalterado', true, 'versao', v_marca);
  end if;
  return public.obter_regra_analise(p_edital)::jsonb || jsonb_build_object('versao', v_marca);
end;
$$;

--
-- Name: FUNCTION obter_regra_analise_se_mudou(p_edital uuid, p_versao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_regra_analise_se_mudou(p_edital uuid, p_versao text) IS 'obter_regra_analise com versão: a marca das fontes (FC_MARCA_DA_RPC) sai antes de montar; p_versao igual devolve só { inalterado, versao } (20261029170000). Mesma permissão.';

--
-- Name: obter_regra_triagem(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_regra_triagem(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 1);
  v_papel text := private."FC_PAPEL_AVALIACAO"(p_edital);
begin
  return json_build_object(
    'schema_version', 1,
    'edital', (select json_build_object('id', m.id, 'edital', m.edital, 'area', v_area,
                                        'numero', private."FC_NUMERO_EDITAL"(m.edital))
                 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital),
    'papel', v_papel,
    'pode_coordenar', coalesce(v_papel = 'COORDENADOR', false),
    'regra', private."FC_REGRA_TRIAGEM_JSON"(p_edital));
end;
$$;

--
-- Name: obter_reinicio_fichas_do_edital(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_reinicio_fichas_do_edital(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_usuario uuid := (select auth.uid());
  v_r json;
begin
  if not private."FC_ADMIN_GLOBAL_ATIVO"(v_usuario) then
    raise exception 'Só o administrador global vê o reinício das fichas do edital.' using errcode = '42501';
  end if;
  v_r := private."FC_LER_REINICIO_FICHAS"(p_edital, v_usuario);
  if v_r is null then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  return v_r;
end;
$$;

--
-- Name: FUNCTION obter_reinicio_fichas_do_edital(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_reinicio_fichas_do_edital(p_edital uuid) IS 'Só administrador global (42501): o reinício das fichas do edital (FC_LER_REINICIO_FICHAS) para o menu da Fila e o aviso de aprovação pendente (20261022210000).';

--
-- Name: obter_responsaveis_do_edital(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_responsaveis_do_edital(p_edital uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text;
begin
  if (select auth.uid()) is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;
  select m."CO_AREA" into v_area from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  if v_area is null then
    raise exception 'Edital não encontrado.' using errcode = 'P0002';
  end if;
  if not (private.is_master() or private."FC_PODE_VER_EDITAL"(p_edital)) then
    raise exception 'Sem permissão para editais desta área ou coordenação' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'area', v_area,
    'pode_editar', private."FC_PODE_EDITAR_DEMANDA"(v_area, p_edital),
    'responsaveis', private."FC_RESPONSAVEIS_DO_EDITAL_JSON"(p_edital));
end;
$$;

--
-- Name: FUNCTION obter_responsaveis_do_edital(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_responsaveis_do_edital(p_edital uuid) IS 'Responsáveis pelo edital ({area, pode_editar, responsaveis: [{id, nome}]}). Quem vê o edital. 20261104120000.';

--
-- Name: obter_resumo_pre_classificacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_resumo_pre_classificacao(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cabecalho jsonb := private."FC_PRE_CABECALHO"(p_edital);
begin
  return (v_cabecalho || jsonb_build_object(
    'totais', (
      select jsonb_build_object(
               'vagas', count(*),
               'vagas_sem_pre', count(*) filter (where pv."CO_VAGA" is null),
               'inscritos', coalesce(sum(pv."QT_INSCRITO"), 0),
               'eliminados', coalesce(sum(pv."QT_ELIMINADO"), 0),
               'ranqueados', coalesce(sum(pv."QT_RANQUEADO"), 0),
               'no_lote', coalesce(sum(pv."QT_LOTE"), 0),
               'divergencias', coalesce(sum(pv."QT_DIVERGENCIA"), 0),
               -- "N de M": a soma dos tamanhos das vagas pré-classificadas; vaga sem tamanho
               -- (sem quadro) deixa o total em aberto.
               'tamanho', case when count(pv."CO_VAGA") > 0
                                and count(pv."CO_VAGA") = count(pv."QT_TAMANHO_LOTE")
                               then sum(pv."QT_TAMANHO_LOTE") end,
               'no_lote_regra', (select count(*) from public."TB_PRE_CLASSIFICACAO" a
                                  where a."CO_MONITORAMENTO" = p_edital and a."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO')
                                    and a."TP_ENTRADA_LOTE" is distinct from 'DECISAO'),
               'no_lote_decisao', (select count(*) from public."TB_PRE_CLASSIFICACAO" a
                                    where a."CO_MONITORAMENTO" = p_edital and a."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO')
                                      and a."TP_ENTRADA_LOTE" = 'DECISAO'))
        from public."TB_EMPREGARE_VAGA" v
        left join public."TB_PRE_CLASSIF_VAGA" pv on pv."CO_MONITORAMENTO" = p_edital and pv."CO_VAGA" = v."CO_VAGA"
       where v."CO_MONITORAMENTO" = p_edital),
    -- As notas declaradas congeladas do edital: quantas e a primeira data.
    'congeladas', (
      select jsonb_build_object('quantidade', count(*), 'em', min(a."DT_CONGELAMENTO_DECLARADA"))
        from public."TB_PRE_CLASSIFICACAO" a
       where a."CO_MONITORAMENTO" = p_edital and a."VL_DECLARADA_CONGELADA" is not null),
    -- A trava das inscrições (o mesmo de obter_congelamento_inscricoes; banco sem ela: nulo).
    'congelamento', case when to_regprocedure('public.obter_congelamento_inscricoes(uuid)') is not null
                         then public.obter_congelamento_inscricoes(p_edital)::jsonb end))::json;
end;
$$;

--
-- Name: FUNCTION obter_resumo_pre_classificacao(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_resumo_pre_classificacao(p_edital uuid) IS 'Abertura da Pré-classificação, só o resumo do instantâneo: edital, papel, regra vigente, execução, totais, congeladas e a trava das inscrições. Vagas, listas e inscritos vêm cada um quando a aba abre. Coordenação do edital.';

--
-- Name: obter_ritmo_da_analise(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_ritmo_da_analise(p_area text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET statement_timeout TO '5s'
    AS $$
declare
  v_area text := lower(btrim(coalesce(p_area, '')));
  v_visiveis uuid[];
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_desde timestamptz;
  v_inicio_hoje timestamptz;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'Sessão necessária.';
  end if;
  if not private.pode_recurso('analises') then
    raise exception using errcode = '42501', message = 'Sem permissão para este recurso';
  end if;
  -- Área válida (22023) e da pessoa ou admin (42501), antes de qualquer leitura.
  perform private."FC_GRUPOS_ANALISES_DA_AREA"(v_area);
  v_visiveis := private."FC_EDITAIS_VISIVEIS"();
  v_desde := ((v_hoje - 14)::timestamp at time zone 'America/Sao_Paulo');
  v_inicio_hoje := (v_hoje::timestamp at time zone 'America/Sao_Paulo');

  return jsonb_build_object(
    'gerado_em', now(),
    'editais', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', m.id,
               'edital', m.edital,
               'situacoes', s.situacoes,
               'por_dia', coalesce((
                 select jsonb_agg(jsonb_build_object('dia', d.dia, 'qt', d.qt) order by d.dia)
                   from (select (f."DT_CONCLUSAO" at time zone 'America/Sao_Paulo')::date as dia,
                                count(*) as qt
                           from public."TB_FICHA_ANALISE" f
                          where f."CO_MONITORAMENTO" = m.id
                            and f."TP_SITUACAO" = 'CONCLUIDA'
                            and f."DT_CONCLUSAO" >= v_desde
                          group by 1) d), '[]'::jsonb),
               'qt_equipe', (
                 select count(distinct a."CO_USUARIO")
                   from public."RL_ANALISTA_EDITAL" a
                  where a."CO_MONITORAMENTO" = m.id
                    and a."ST_ATIVO" = 'S'
                    and a."TP_PAPEL" = 'ANALISTA'),
               'qt_avaliadores_recentes', (
                 select count(distinct f."CO_USUARIO_CONCLUSAO")
                   from public."TB_FICHA_ANALISE" f
                  where f."CO_MONITORAMENTO" = m.id
                    and f."TP_SITUACAO" = 'CONCLUIDA'
                    and f."DT_CONCLUSAO" >= now() - interval '7 days'),
               -- Destaques de hoje (20261021100000): quem concluiu fichas hoje
               -- (America/Sao_Paulo), só os do pódio (dense_rank ≤ 3) ou com o
               -- mínimo do selo (10); o front decide medalha e selo.
               'destaques', jsonb_build_object(
                 'dia', v_hoje,
                 'avaliadores', coalesce((
                   select jsonb_agg(jsonb_build_object(
                            'nome', x.nome, 'qt', x.qt, 'reabertas', x.reabertas)
                          order by x.qt desc, x.nome)
                     from (select coalesce(private."FC_NOME_E_SOBRENOME"(p.nome), 'Avaliador') as nome,
                                  c.qt,
                                  coalesce(r.qt, 0) as reabertas,
                                  dense_rank() over (order by c.qt desc) as posicao
                             from (select f."CO_USUARIO_CONCLUSAO" as usuario, count(*) as qt
                                     from public."TB_FICHA_ANALISE" f
                                    where f."CO_MONITORAMENTO" = m.id
                                      and f."TP_SITUACAO" = 'CONCLUIDA'
                                      and f."DT_CONCLUSAO" >= v_inicio_hoje
                                      and f."CO_USUARIO_CONCLUSAO" is not null
                                    group by 1) c
                             left join public."TB_PERFIL_USUARIO" p on p.user_id = c.usuario
                             -- Reabertas: REABRIR de hoje cuja conclusão anterior
                             -- (o CONCLUIR imediatamente antes) também é de hoje;
                             -- conta para quem concluiu. REINICIAR não conta.
                             left join (
                               select ant.usuario, count(distinct h."CO_FICHA_ANALISE") as qt
                                 from public."TH_FICHA_ANALISE" h
                                 join public."TB_FICHA_ANALISE" fa
                                   on fa."CO_FICHA_ANALISE" = h."CO_FICHA_ANALISE"
                                  and fa."CO_MONITORAMENTO" = m.id
                                 cross join lateral (
                                   select c2."CO_USUARIO" as usuario, c2."DT_REGISTRO" as em
                                     from public."TH_FICHA_ANALISE" c2
                                    where c2."CO_FICHA_ANALISE" = h."CO_FICHA_ANALISE"
                                      and c2."TP_ACAO" = 'CONCLUIR'
                                      and c2."DT_REGISTRO" < h."DT_REGISTRO"
                                    order by c2."DT_REGISTRO" desc
                                    limit 1) ant
                                where h."TP_ACAO" = 'REABRIR'
                                  and h."DT_REGISTRO" >= v_inicio_hoje
                                  and ant.em >= v_inicio_hoje
                                group by 1) r on r.usuario = c.usuario) x
                    where x.posicao <= 3 or x.qt >= 10), '[]'::jsonb)),
               'cronograma', coalesce((
                 select jsonb_agg(jsonb_build_object(
                          'ordem', c.ordem, 'atividade', c.atividade,
                          'tipo', c.tipo_atividade,
                          'inicio', c.data_inicio, 'fim', c.data_fim)
                        order by c.ordem)
                   from public."TB_CRONOGRAMA_MONIT_INDIG" c
                  where c.monitoramento_id = m.id), '[]'::jsonb))
             order by m.edital)
        from public."TB_MONITORAMENTO_INDIGENA" m
        cross join lateral (
          select jsonb_build_object(
                   'pendente',   count(*) filter (where f."TP_SITUACAO" = 'PENDENTE'),
                   'em_analise', count(*) filter (where f."TP_SITUACAO" = 'EM_ANALISE'),
                   'revisar',    count(*) filter (where f."TP_SITUACAO" = 'REVISAR'),
                   'concluida',  count(*) filter (where f."TP_SITUACAO" = 'CONCLUIDA'),
                   'fora_lote',  count(*) filter (where f."TP_SITUACAO" = 'FORA_LOTE')) as situacoes,
                 count(*) filter (where f."TP_SITUACAO" <> 'FORA_LOTE') as no_lote
            from public."TB_FICHA_ANALISE" f
           where f."CO_MONITORAMENTO" = m.id) s
        join public."TB_ORIGEM_ANALISE_EDITAL" o
          on o."CO_MONITORAMENTO" = m.id and o."TP_ORIGEM" = 'MONITORA'
       where m."CO_AREA" = v_area
         and m.ativo is true
         and coalesce(m."ST_TREINAMENTO", 'N') <> 'S'
         and (v_visiveis is null or m.id = any (v_visiveis))
         and s.no_lote > 0), '[]'::jsonb));
end;
$$;

--
-- Name: FUNCTION obter_ritmo_da_analise(p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_ritmo_da_analise(p_area text) IS 'Card "Ritmo da análise" do Painel das análises: por edital da área com a avaliação documental no MONITORA e fichas no lote, as contagens por situação, as concluídas por dia (últimos 14 dias, horário de Brasília), a equipe de analistas ativa, quem concluiu nos últimos 7 dias, o cronograma e os destaques de hoje (pódio e candidatos ao selo Precisão: nome, concluídas e reabertas hoje; 20261021100000). A conta do ritmo e das medalhas é do front (src/lib/ritmo-da-analise.ts). Só quem pode ler o Painel das análises da área (20261019170000).';

--
-- Name: obter_situacao_do_sistema(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_situacao_do_sistema() RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
    'admin_global', private.is_master(),
    'sistema', (select json_build_object(
        'situacao', s."TP_SITUACAO", 'mensagem', s."DS_MENSAGEM_MANUTENCAO",
        'previsao', s."DT_PREVISAO_RETORNO", 'atualizado_em', s."DT_ATUALIZACAO",
        'comemoracoes', s."ST_COMEMORACAO" = 'S')
      from public."TB_SITUACAO_SISTEMA" s where s."CO_SITUACAO_SISTEMA" = 1),
    'areas', coalesce((select json_agg(json_build_object(
        'co_area', a."CO_AREA", 'ativo', a."ST_ATIVO" = 'S', 'situacao', a."TP_SITUACAO",
        'mensagem', a."DS_MENSAGEM_MANUTENCAO", 'previsao', a."DT_PREVISAO_RETORNO")
        order by a."NU_ORDEM") from public."TB_AREA" a), '[]'::json)
  )
  where (select auth.uid()) is not null;
$$;

--
-- Name: FUNCTION obter_situacao_do_sistema(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_situacao_do_sistema() IS 'Situação do sistema inteiro e de cada área (ativo, manutenção, mensagem, previsão) para o menu e a tela de manutenção. Qualquer pessoa logada.';

--
-- Name: obter_situacao_pre_classificacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_situacao_pre_classificacao(p_edital uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
begin
  -- As mesmas chaves (e o mesmo cálculo) de obter_pre_classificacao.
  return json_build_object(
    'em_andamento', exists (select 1 from public."TL_PRE_CLASSIFICACAO" t
                             where t."TP_SITUACAO" = 'EM_ANDAMENTO' and t."DT_INICIO" > now() - interval '1 hour'),
    'ultima_execucao', (
      select json_build_object('id', t."CO_EXECUCAO", 'inicio', t."DT_INICIO", 'fim', t."DT_FIM", 'situacao', t."TP_SITUACAO",
                               'disparo', t."TP_DISPARO", 'refazer', t."ST_REFAZER_LOTE" = 'S', 'mensagem', t."DS_MENSAGEM",
                               'execucao', t."DS_URL_EXECUCAO")
        from public."TL_PRE_CLASSIFICACAO" t
       where t."DS_EDITAL" @> jsonb_build_array(jsonb_build_object('edital', p_edital::text))
       order by t."DT_INICIO" desc limit 1));
end;
$$;

--
-- Name: FUNCTION obter_situacao_pre_classificacao(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_situacao_pre_classificacao(p_edital uuid) IS 'Só em_andamento e ultima_execucao da pré-classificação do edital (as chaves de obter_pre_classificacao, ≈0,4 KB): o acompanhamento do Recalcular pergunta a cada 15 s e relê o pacote só no fim (20261014230000). Desde 20261016130000, só a coordenação do edital (FC_EXIGIR_COORD_AVALIACAO: Editor, área e papel COORDENADOR ou admin global; os demais recebem 42501): a aba é só da coordenação.';

--
-- Name: obter_ultima_conferencia(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.obter_ultima_conferencia(p_fonte text, p_area text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fonte text := lower(btrim(coalesce(p_fonte, '')));
  v_area text := nullif(btrim(coalesce(p_area, '')), '');
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'Sessão necessária.';
  end if;
  if v_fonte = 'analises' then
    if not private.pode_recurso('analises') then
      raise exception using errcode = '42501', message = 'Sem permissão para este recurso';
    end if;
    return greatest(
      (select max(s.finished_at)
         from public."TL_SYNC_ANALISE" s
        where s.status = 'processado'
          and (v_area is null or s."CO_PLANILHA" = v_area)),
      (select max(c."DT_GERACAO")
         from private."TA_PAINEL_ANALISE" c
        where v_area is null or c."CO_AREA" = v_area),
      -- A conferência do job do resumo (vale para todas as áreas), mesmo sem remontar.
      (select max(d.end_time)
         from cron.job_run_details d
         join cron.job j on j.jobid = d.jobid
        where j.jobname = 'agsus_analises_cache_do_painel'
          and d.status = 'succeeded'
          and d.start_time > now() - interval '1 day'));
  elsif v_fonte = 'selecao' then
    if not private.pode_recurso('selecao') then
      raise exception using errcode = '42501', message = 'Sem permissão para este recurso';
    end if;
    return (select max(s."DT_FIM")
              from public."TL_SYNC_SELECAO" s
             where s."TP_SITUACAO" = 'CONCLUIDA');
  elsif v_fonte = 'entrevistas' then
    if not private.pode_recurso('entrevistas') then
      raise exception using errcode = '42501', message = 'Sem permissão para este recurso';
    end if;
    return (select max(s."DT_FIM")
              from public."TL_SYNC_ENTREVISTA" s
             where s."TP_SITUACAO" = 'CONCLUIDA'
               and (v_area is null or s."CO_AREA" = v_area));
  end if;
  raise exception using errcode = '22023', message = 'Fonte inválida: use analises, selecao ou entrevistas.';
end;
$$;

--
-- Name: FUNCTION obter_ultima_conferencia(p_fonte text, p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_ultima_conferencia(p_fonte text, p_area text) IS 'Hora da última conferência da fonte, mostrada como "Conferido às" nas telas: análises = a mais recente entre a última carga da planilha, a última montagem do resumo do Painel da área e a última rodada bem-sucedida do job do resumo (conferência sem mudança); seleção e entrevistas = última carga que terminou bem. p_area recorta análises e entrevistas. Só quem pode ler a tela do módulo.';

