-- Name: FUNCTION obter_vagas_pre_classificacao(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.obter_vagas_pre_classificacao(p_edital uuid) IS 'O resumo por vaga da Pré-classificação (contagens do instantâneo, tamanho e corte do lote, avisos, lote pela regra e por decisão, fora do lote). Coordenação do edital.';

--
-- Name: paineis_gravar_pacote(text, text, timestamp with time zone, bigint[], json, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.paineis_gravar_pacote(p_cache text, p_area text, p_lido_em timestamp with time zone, p_marcas bigint[], p_pacote json, p_execucao text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    SET work_mem TO '16MB'
    AS $_$
declare
  v_cache text := upper(btrim(coalesce(p_cache, '')));
  v_area text := lower(btrim(coalesce(p_area, '')));
  v_versao text := (extract(epoch from p_lido_em) * 1000000)::bigint::text;
  v_ms integer := greatest(0, (extract(epoch from clock_timestamp() - p_lido_em) * 1000)::integer);
  v_escopo text;
  v_parte json;
  v_gravou integer := 0;
  v_marcas integer;
begin
  if v_cache not in ('ANALISES', 'APROVADOS', 'ENTREVISTAS') then
    raise exception 'Pacote desconhecido: %', left(p_cache, 30) using errcode = '22023';
  end if;
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Área inválida: %', left(p_area, 40) using errcode = '22023';
  end if;
  -- A leitura é a de agora há pouco: nem do futuro, nem de mais de 1 h (o job leva minutos).
  if p_lido_em is null or p_lido_em > clock_timestamp() + interval '1 minute'
     or p_lido_em < clock_timestamp() - interval '1 hour' then
    raise exception 'Leitura fora do prazo (lido_em).' using errcode = '22023';
  end if;
  if p_marcas is null or array_position(p_marcas, null) is not null then
    raise exception 'Marcas inválidas.' using errcode = '22023';
  end if;
  if coalesce(p_execucao, '') !~ '^[A-Za-z0-9_.:-]{1,80}$' then
    raise exception 'Execução inválida.' using errcode = '22023';
  end if;
  if p_pacote is null or json_typeof(p_pacote) <> 'object' then
    raise exception 'Pacote inválido.' using errcode = '22023';
  end if;

  -- Um gravador por pacote e área de cada vez (o job e a reserva no banco).
  perform pg_advisory_xact_lock(hashtext('paineis_gravar:' || v_cache || ':' || v_area)::bigint);

  if v_cache = 'ANALISES' then
    -- Os três escopos, cada um com as colunas de get_analises_dashboard_payload_v2 (15).
    foreach v_escopo in array array['ativo', 'inativo', 'desativadas'] loop
      v_parte := p_pacote -> v_escopo;
      if v_parte is null or json_typeof(v_parte) <> 'object'
         or not private."FC_LINHAS_VALIDAS"(v_parte -> 'linhas', array[15])
         or coalesce(json_typeof(v_parte -> 'editais'), '') <> 'array'
         or coalesce(json_typeof(v_parte -> 'concluidas_por_ano'), '') <> 'object'
         or coalesce(json_typeof(v_parte -> 'atualizado_em'), 'null') not in ('string', 'null') then
        raise exception 'Pacote das análises inválido no escopo %.', v_escopo using errcode = '22023';
      end if;
    end loop;
    foreach v_escopo in array array['ativo', 'inativo', 'desativadas'] loop
      v_parte := p_pacote -> v_escopo;
      insert into private."TA_PAINEL_ANALISE" as c (
        "CO_AREA", "TP_ESCOPO", "DS_LINHAS", "DS_EDITAIS", "QT_LINHAS", "DS_VERSAO_DADOS",
        "DT_GERACAO", "NU_DURACAO_MS", "DT_ULTIMA_ATUALIZACAO", "DS_CONCLUIDAS_POR_ANO")
      values (
        v_area, v_escopo, v_parte -> 'linhas', v_parte -> 'editais', json_array_length(v_parte -> 'linhas'),
        v_versao, p_lido_em, v_ms, (v_parte ->> 'atualizado_em')::timestamptz, v_parte -> 'concluidas_por_ano')
      on conflict ("CO_AREA", "TP_ESCOPO") do update set
        "DS_LINHAS" = excluded."DS_LINHAS",
        "DS_EDITAIS" = excluded."DS_EDITAIS",
        "QT_LINHAS" = excluded."QT_LINHAS",
        "DS_VERSAO_DADOS" = excluded."DS_VERSAO_DADOS",
        "DT_GERACAO" = excluded."DT_GERACAO",
        "NU_DURACAO_MS" = excluded."NU_DURACAO_MS",
        "DT_ULTIMA_ATUALIZACAO" = excluded."DT_ULTIMA_ATUALIZACAO",
        "DS_CONCLUIDAS_POR_ANO" = excluded."DS_CONCLUIDAS_POR_ANO"
      -- Nunca troca um pacote mais novo (a reserva no banco remontou depois desta leitura).
      where c."DT_GERACAO" < excluded."DT_GERACAO";
      if found then
        v_gravou := v_gravou + 1;
      end if;
    end loop;
  elsif v_cache = 'APROVADOS' then
    -- Linhas de 12 colunas (16 quando alterada judicialmente), listas de 7.
    if not private."FC_LINHAS_VALIDAS"(p_pacote -> 'linhas', array[12, 16])
       or not private."FC_LINHAS_VALIDAS"(p_pacote -> 'listas', array[7])
       or coalesce(json_typeof(p_pacote -> 'dicionarios'), '') <> 'object'
       or exists (select 1 from unnest(array['cargo', 'modalidade', 'status', 'codigo_vaga']) k
                   where coalesce(json_typeof(p_pacote -> 'dicionarios' -> k), '') <> 'array')
       or coalesce(json_typeof(p_pacote -> 'dicionarios' -> 'contratacao'), '') <> 'object' then
      raise exception 'Pacote da Lista de aprovados inválido.' using errcode = '22023';
    end if;
    insert into private."TA_CANDIDATO_APROVADO_AREA" as c (
      "CO_AREA", "DS_LISTAS", "DS_DICIONARIOS", "DS_LINHAS", "QT_CANDIDATOS",
      "DS_VERSAO_DADOS", "DT_GERACAO", "NU_DURACAO_MS")
    values (
      v_area, p_pacote -> 'listas', p_pacote -> 'dicionarios', p_pacote -> 'linhas',
      json_array_length(p_pacote -> 'linhas'), v_versao, p_lido_em, v_ms)
    on conflict ("CO_AREA") do update set
      "DS_LISTAS" = excluded."DS_LISTAS",
      "DS_DICIONARIOS" = excluded."DS_DICIONARIOS",
      "DS_LINHAS" = excluded."DS_LINHAS",
      "QT_CANDIDATOS" = excluded."QT_CANDIDATOS",
      "DS_VERSAO_DADOS" = excluded."DS_VERSAO_DADOS",
      "DT_GERACAO" = excluded."DT_GERACAO",
      "NU_DURACAO_MS" = excluded."NU_DURACAO_MS"
    where c."DT_GERACAO" < excluded."DT_GERACAO";
    if found then
      v_gravou := 1;
    end if;
  else
    -- O payload de FC_MONTAR_ENTREVISTAS_AREA (schema_version 1), da mesma área.
    if (p_pacote ->> 'schema_version') is distinct from '1'
       or (p_pacote ->> 'area') is distinct from v_area
       or coalesce(json_typeof(p_pacote -> 'gerado_em'), '') <> 'string'
       or coalesce(json_typeof(p_pacote -> 'criterios'), '') <> 'array'
       or not private."FC_LINHAS_VALIDAS"(
            coalesce((select json_agg(json_build_array(e ->> 'id')) from json_array_elements(p_pacote -> 'entrevistas') e
                       where json_typeof(e) = 'object'), '[]'::json), array[1])
       or coalesce(json_typeof(p_pacote -> 'aprovados_sem_entrevista'), '') <> 'array'
       or json_array_length(p_pacote -> 'aprovados_sem_entrevista') > 3000
       or coalesce(json_typeof(p_pacote -> 'ultima_carga'), 'null') not in ('object', 'null') then
      raise exception 'Pacote das entrevistas inválido.' using errcode = '22023';
    end if;
    insert into private."TA_PAINEL_ENTREVISTA" as c
      ("CO_AREA", "DS_PAYLOAD", "QT_ENTREVISTA", "DS_VERSAO_DADOS", "DT_GERACAO", "NU_DURACAO_MS")
    values (v_area, p_pacote, json_array_length(p_pacote -> 'entrevistas'), v_versao, p_lido_em, v_ms)
    on conflict ("CO_AREA") do update set
      "DS_PAYLOAD" = excluded."DS_PAYLOAD", "QT_ENTREVISTA" = excluded."QT_ENTREVISTA",
      "DS_VERSAO_DADOS" = excluded."DS_VERSAO_DADOS", "DT_GERACAO" = excluded."DT_GERACAO",
      "NU_DURACAO_MS" = excluded."NU_DURACAO_MS"
    where c."DT_GERACAO" < excluded."DT_GERACAO";
    if found then
      v_gravou := 1;
    end if;
  end if;

  -- Só as marcas que a leitura viu: as mudanças delas estão no pacote (este ou o mais novo).
  delete from private."TL_ALTERACAO_CACHE" t
   where t."TP_CACHE" = v_cache and t."CO_AREA" = v_area
     and t."CO_ALTERACAO_CACHE" = any (p_marcas);
  get diagnostics v_marcas = row_count;

  return jsonb_build_object('ok', true, 'cache', v_cache, 'area', v_area, 'gravados', v_gravou,
                            'marcas_apagadas', v_marcas, 'ms', v_ms);
end;
$_$;

--
-- Name: FUNCTION paineis_gravar_pacote(p_cache text, p_area text, p_lido_em timestamp with time zone, p_marcas bigint[], p_pacote json, p_execucao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.paineis_gravar_pacote(p_cache text, p_area text, p_lido_em timestamp with time zone, p_marcas bigint[], p_pacote json, p_execucao text) IS 'Job "Pacotes dos painéis" (Python, só service_role): só valida o formato e grava o pacote montado (TA_PAINEL_ANALISE, TA_CANDIDATO_APROVADO_AREA ou TA_PAINEL_ENTREVISTA), com DT_GERACAO = lido_em; nunca troca um pacote mais novo; apaga só as marcas que a leitura viu. 20261029180000.';

--
-- Name: paineis_ler_fontes(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.paineis_ler_fontes(p_cache text, p_area text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET work_mem TO '64MB'
    SET jit TO 'off'
    AS $$
declare
  v_cache text := upper(btrim(coalesce(p_cache, '')));
  v_area text := lower(btrim(coalesce(p_area, '')));
  v_lido_em timestamptz := clock_timestamp();
  v_marcas bigint[];
  v_grupo text;
  v_grupo_norm text;
begin
  if v_cache not in ('ANALISES', 'APROVADOS', 'ENTREVISTAS') then
    raise exception 'Pacote desconhecido: %', left(p_cache, 30) using errcode = '22023';
  end if;
  select a."NO_GRUPO_PLANILHA", public.analises_norm_key(a."NO_GRUPO_PLANILHA")
    into v_grupo, v_grupo_norm
    from public."TB_AREA" a where a."CO_AREA" = v_area;
  if not found then
    raise exception 'Área inválida: %', left(p_area, 40) using errcode = '22023';
  end if;

  -- As marcas ANTES das fontes: uma mudança confirmada entre as duas leituras aparece nas fontes
  -- e deixa a marca dela, que a gravação não apaga (a área volta na próxima rodada).
  select coalesce(array_agg(t."CO_ALTERACAO_CACHE" order by t."CO_ALTERACAO_CACHE"), '{}')
    into v_marcas
    from private."TL_ALTERACAO_CACHE" t
   where t."TP_CACHE" = v_cache and t."CO_AREA" = v_area;

  if v_cache = 'ANALISES' then
    -- As fontes de FC_MONTAR_PAINEL_ANALISE (sem recorte) e da VW_ANALISES_DASHBOARD_BASE_TODOS.
    return (
      with an as (
        select a.id, a.unidade, a.edital, a.codigo_vaga, a.nome_vaga, a.candidato, a.categoria,
               a.modalidade_concorrencia, a.status_consolidado, a.etapa, a.responsavel_analise,
               a.data_analise, a.nota_final_ajustada, a.pdf_status,
               nullif(btrim(a.link_pdf), '') is not null as tem_pdf,
               a.ativo, coalesce(a.updated_at, a.ultima_atualizacao) as atualizado_em,
               a.unidade_norm, a.edital_norm
          from public."TB_ANALISE_CURRICULAR" a
         where a.grupo_norm = v_grupo_norm
           and not private."FC_ANALISE_EH_TREINAMENTO"(a.origem_planilha)
           and a.status_consolidado is distinct from 'Fora do lote'
      ), ep as (
        select e.id, e.grupo, e.unidade, e.edital, e.ativo, e.data_inicio_analise, e.data_fim_analise,
               e.unidade_norm, e.edital_norm
          from public."TB_EDITAL_ANALISE" e
         where e.grupo_norm = v_grupo_norm
      ), em as (
        select m.id, m.unidade, m.edital, j.inicio, j.fim
          from public."TB_ORIGEM_ANALISE_EDITAL" o
          join public."TB_MONITORAMENTO_INDIGENA" m on m.id = o."CO_MONITORAMENTO"
         cross join lateral private."FC_JANELA_AVALIACAO_DOCUMENTAL"(m.id) j
         where o."TP_ORIGEM" = 'MONITORA'
           and m."CO_AREA" = v_area
           and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
      )
      select json_build_object(
        'schema_version', 1, 'cache', v_cache, 'area', v_area, 'lido_em', v_lido_em,
        'marcas', to_json(v_marcas), 'grupo', v_grupo,
        'analises', (select coalesce(json_agg(json_build_array(
            an.id, an.unidade, an.edital, an.codigo_vaga, an.nome_vaga, an.candidato, an.categoria,
            an.modalidade_concorrencia, an.status_consolidado, an.etapa, an.responsavel_analise,
            an.data_analise, an.nota_final_ajustada, an.pdf_status, an.tem_pdf, an.ativo,
            an.atualizado_em, an.unidade_norm, an.edital_norm)), '[]'::json) from an),
        'editais_planilha', (select coalesce(json_agg(json_build_array(
            ep.id, ep.grupo, ep.unidade, ep.edital, ep.ativo, ep.data_inicio_analise,
            ep.data_fim_analise, ep.unidade_norm, ep.edital_norm)), '[]'::json) from ep),
        'editais_monitora', (select coalesce(json_agg(json_build_array(
            em.id, em.unidade, em.edital, em.inicio, em.fim)), '[]'::json) from em),
        'vocabulario', (select coalesce(json_agg(x.v order by x.v), '[]'::json)
                          from (select an.unidade as v from an union select an.edital from an
                                union select an.codigo_vaga from an union select an.candidato from an
                                union select ep.unidade from ep union select ep.edital from ep
                                union select em.unidade from em union select em.edital from em) x
                         where x.v is not null)));
  elsif v_cache = 'APROVADOS' then
    -- As fontes de FC_MONTAR_APROVADOS_AREA (sem recorte).
    return (
      with li as (
        select l.id, l.edital_id, m.edital, m.unidade, l.ativo, l.arquivo_nome, l.importado_em
          from public."TB_LISTA_APROVADO" l
          join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
         where l.vigente is true
           and m."CO_AREA" = v_area
           and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
      ), ca as (
        select c.id, c.lista_id, c.cargo, c.classificacao, c.nota, c.nome, c.modalidade, c.status,
               c.processo_sei, c.matricula, c.sub_judice, c.codigo_vaga, c.alterado_judicialmente,
               c.nota_original, c.modalidade_original, c.classificacao_original
          from li join public."TB_CANDIDATO_APROVADO" c on c.lista_id = li.id
         where c.removido_em is null
      )
      select json_build_object(
        'schema_version', 1, 'cache', v_cache, 'area', v_area, 'lido_em', v_lido_em,
        'marcas', to_json(v_marcas),
        'listas', (select coalesce(json_agg(json_build_array(
            li.id, li.edital_id, li.edital, li.unidade, li.ativo, li.arquivo_nome, li.importado_em)),
            '[]'::json) from li),
        'candidatos', (select coalesce(json_agg(json_build_array(
            ca.id, ca.lista_id, ca.cargo, ca.classificacao, ca.nota, ca.nome, ca.modalidade, ca.status,
            ca.processo_sei, ca.matricula, ca.sub_judice, ca.codigo_vaga, ca.alterado_judicialmente,
            ca.nota_original, ca.modalidade_original, ca.classificacao_original)), '[]'::json) from ca),
        'contratacao', (select coalesce(json_agg(json_build_array(
            x."CO_CANDIDATO_APROVADO", x."TP_SITUACAO", x."DS_MOTIVO")), '[]'::json)
                          from public."TB_CONTRATACAO_APROVADO" x
                          join ca on ca.id = x."CO_CANDIDATO_APROVADO"
                         where ca.status = 'Contratado'),
        'vocabulario', (select coalesce(json_agg(x.v order by x.v), '[]'::json)
                          from (select li.edital as v from li union select ca.cargo from ca
                                union select ca.nome from ca union select ca.modalidade from ca
                                union select ca.status from ca union select ca.codigo_vaga from ca) x
                         where x.v is not null)));
  end if;

  -- ENTREVISTAS: as fontes de FC_MONTAR_ENTREVISTAS_AREA (sem recorte). As entrevistas ativas da
  -- área vão todas: a vigente de cada pessoa (FC_ENTREVISTAS_VIGENTES) é escolhida no Python.
  return (
    with en as (
      select e."CO_ENTREVISTA", e."CO_MONITORAMENTO", e."CO_ANALISE_CURRICULAR", e."TP_LIGACAO_ANALISE",
             e."NO_UNIDADE", e."DS_EDITAL", e."CO_VAGA", e."NO_CARGO", e."NO_CANDIDATO", e."CO_CANDIDATO",
             e."DS_MODALIDADE", e."VL_NOTA_TOTAL", e."TP_PARECER", e."ST_COMPARECEU", e."TP_ORIGEM",
             e."DT_ATUALIZACAO", e."DS_LINK_PLANILHA"
        from public."TB_ENTREVISTA" e
       where e."CO_AREA" = v_area and e."ST_ATIVO" = 'S'
    ), mo as (
      select m.id, m.edital, m.unidade, m.ativo, private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO") as treinamento
        from public."TB_MONITORAMENTO_INDIGENA" m
       where m.id in (select en."CO_MONITORAMENTO" from en)
    ), anl as (
      select a.id, a.nome_vaga, a.modalidade_concorrencia, a.nota_final_ajustada, a.status_consolidado,
             a.etapa, a.responsavel_analise, a.ativo
        from public."TB_ANALISE_CURRICULAR" a
       where a.id in (select en."CO_ANALISE_CURRICULAR" from en)
    ), sem as (
      select a.id, a.candidato, a.id_origem, a.codigo_vaga, a.nome_vaga, a.edital, a.unidade,
             a.nota_final_ajustada, a.modalidade_concorrencia
        from public."TB_ANALISE_CURRICULAR" a
       where a."CO_AREA" = v_area and a.ativo
         and not private."FC_ANALISE_EH_TREINAMENTO"(a.origem_planilha)
         and a.status_consolidado = 'Aprovado'
         and a.codigo_vaga in (select en."CO_VAGA" from en)
         and not exists (select 1 from public."TB_ENTREVISTA" x
                          where x."CO_ANALISE_CURRICULAR" = a.id and x."ST_ATIVO" = 'S')
    ), nt as (
      select n."CO_ENTREVISTA", n."NU_ORDEM", n."DS_CRITERIO", n."VL_NOTA"
        from public."TB_ENTREVISTA_NOTA" n
       where n."CO_ENTREVISTA" in (select en."CO_ENTREVISTA" from en) and n."VL_NOTA" is not null
    )
    select json_build_object(
      'schema_version', 1, 'cache', v_cache, 'area', v_area, 'lido_em', v_lido_em,
      'marcas', to_json(v_marcas),
      'ultima_carga', (
        select json_build_object('em', s."DT_FIM", 'linhas', s."QT_LINHA",
                                 'ligadas_analise', s."QT_LIGADA_ANALISE",
                                 'sem_analise', s."QT_SEM_ANALISE", 'sem_edital', s."QT_SEM_EDITAL")
          from public."TL_SYNC_ENTREVISTA" s
         where s."CO_AREA" = v_area and s."TP_SITUACAO" = 'CONCLUIDA'
         order by s."DT_FIM" desc limit 1),
      'entrevistas', (select coalesce(json_agg(json_build_array(
          en."CO_ENTREVISTA", en."CO_MONITORAMENTO", en."CO_ANALISE_CURRICULAR", en."TP_LIGACAO_ANALISE",
          en."NO_UNIDADE", en."DS_EDITAL", en."CO_VAGA", en."NO_CARGO", en."NO_CANDIDATO", en."CO_CANDIDATO",
          en."DS_MODALIDADE", en."VL_NOTA_TOTAL", en."TP_PARECER", en."ST_COMPARECEU", en."TP_ORIGEM",
          en."DT_ATUALIZACAO", en."DS_LINK_PLANILHA")), '[]'::json) from en),
      'notas', (select coalesce(json_agg(json_build_array(
          nt."CO_ENTREVISTA", nt."NU_ORDEM", nt."DS_CRITERIO", nt."VL_NOTA")), '[]'::json) from nt),
      'monitoramentos', (select coalesce(json_agg(json_build_array(
          mo.id, mo.edital, mo.unidade, mo.ativo, mo.treinamento)), '[]'::json) from mo),
      'analises', (select coalesce(json_agg(json_build_array(
          anl.id, anl.nome_vaga, anl.modalidade_concorrencia, anl.nota_final_ajustada, anl.status_consolidado,
          anl.etapa, anl.responsavel_analise, anl.ativo)), '[]'::json) from anl),
      'sem_entrevista', (select coalesce(json_agg(json_build_array(
          sem.id, sem.candidato, sem.id_origem, sem.codigo_vaga, sem.nome_vaga, sem.edital, sem.unidade,
          sem.nota_final_ajustada, sem.modalidade_concorrencia)), '[]'::json) from sem),
      'vocabulario', (select coalesce(json_agg(x.v order by x.v), '[]'::json)
                        from (select en."DS_EDITAL" as v from en union select en."CO_VAGA" from en
                              union select en."NO_CANDIDATO" from en union select mo.edital from mo
                              union select nt."DS_CRITERIO" from nt union select sem.edital from sem
                              union select sem.codigo_vaga from sem union select sem.candidato from sem) x
                       where x.v is not null)));
end;
$$;

--
-- Name: FUNCTION paineis_ler_fontes(p_cache text, p_area text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.paineis_ler_fontes(p_cache text, p_area text) IS 'Job "Pacotes dos painéis" (Python, só service_role): as fontes de um pacote (ANALISES, APROVADOS ou ENTREVISTAS) de uma área, em listas cruas, sem montar; marcas (TL_ALTERACAO_CACHE) lidas antes das fontes; lido_em; vocabulario = os textos que ordenam, na ordem da colação do banco. 20261029180000.';

--
-- Name: paineis_ler_pendentes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.paineis_ler_pendentes() RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select json_build_object(
    'schema_version', 1,
    'pendentes', coalesce((
      select json_agg(json_build_object('cache', c.cache, 'area', v."CO_AREA", 'motivo', v."TP_MOTIVO")
                      order by c.ordem, v."CO_AREA")
        from (values ('ANALISES', 1), ('APROVADOS', 2), ('ENTREVISTAS', 3)) c(cache, ordem)
       cross join lateral private."FC_PAINEIS_VENCIDOS"(c.cache) v), '[]'::json));
$$;

--
-- Name: FUNCTION paineis_ler_pendentes(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.paineis_ler_pendentes() IS 'Job "Pacotes dos painéis" (Python, só service_role): os pacotes desatualizados, { schema_version, pendentes: [{ cache, area, motivo }] }. 20261029180000.';

--
-- Name: pedir_calculo_classificacao(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pedir_calculo_classificacao(p_edital uuid, p_tipo text, p_versao integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_regra public."TB_REGRA_CLASSIFICACAO";
  v_id uuid;
  v_situacao text := 'PEDIDO';
  v_mensagem text;
  v_disparo bigint;
  v_estado text;
begin
  -- Chave desligada: nada é gravado nem pedido; a tela segue com o cálculo dela.
  if not private."FC_CALCULO_PELO_PYTHON"() then
    return json_build_object('ligada', false);
  end if;
  perform private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 2);
  if p_tipo is null or p_tipo not in ('PRELIMINAR', 'CONVOCACAO', 'ENTREVISTA', 'FINAL') then
    raise exception 'Tipo de lista inválido' using errcode = '22023';
  end if;
  select * into v_regra from public."TB_REGRA_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital;
  if v_regra."CO_REGRA_CLASSIFICACAO" is null then
    raise exception 'Salve a regra do edital antes de gerar a lista.' using errcode = '22023';
  end if;
  if p_versao is distinct from v_regra."NU_VERSAO_VIGENTE" then
    raise exception 'A regra mudou (versão %); gere de novo.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
  end if;

  -- O cálculo pronto e abandonado (há mais de 10 min) da mesma lista sai: o retrato não fica guardado.
  update public."TB_PEDIDO_CALCULO_CLASSIFICACAO" p
     set "TP_SITUACAO" = 'SUBSTITUIDO', "DS_RETRATO" = null, "DT_ATUALIZACAO" = now()
   where p."CO_MONITORAMENTO" = p_edital and p."TP_LISTA" = p_tipo
     and p."TP_SITUACAO" = 'PRONTO' and p."DT_ATUALIZACAO" < now() - interval '10 minutes';

  insert into public."TB_PEDIDO_CALCULO_CLASSIFICACAO"
    ("CO_MONITORAMENTO", "TP_LISTA", "NU_VERSAO_REGRA", "TP_SITUACAO", "CO_USUARIO")
  values (p_edital, p_tipo, p_versao, 'PEDIDO', (select auth.uid()))
  returning "CO_PEDIDO_CALCULO" into v_id;

  -- O job leva todos os pedidos que esperam: o workflow vai só com o modo.
  begin
    v_disparo := private."FC_DISPARAR_ROBO"('classificacao.yml', jsonb_build_object('modo', 'calculo'), (select auth.uid()));
    select d."TP_SITUACAO" into v_estado from public."TL_DISPARO_ROBO" d where d."CO_DISPARO" = v_disparo;
    if v_estado is distinct from 'PEDIDO' then
      v_situacao := 'SEM_DISPARO';
      v_mensagem := 'O pedido ao GitHub não saiu (' || coalesce(v_estado, 'sem registro') || ').';
    end if;
  exception when others then
    v_situacao := 'SEM_DISPARO';
    v_mensagem := 'O pedido ao GitHub não saiu (' || sqlstate || ').';
    v_disparo := null;
  end;
  update public."TB_PEDIDO_CALCULO_CLASSIFICACAO"
     set "TP_SITUACAO" = v_situacao, "DS_MENSAGEM" = v_mensagem, "CO_DISPARO" = v_disparo, "DT_ATUALIZACAO" = now()
   where "CO_PEDIDO_CALCULO" = v_id;

  return json_build_object('ligada', true, 'pedido', v_id, 'tipo', p_tipo, 'situacao', v_situacao,
                           'mensagem', v_mensagem, 'pedido_em', now());
end;
$$;

--
-- Name: FUNCTION pedir_calculo_classificacao(p_edital uuid, p_tipo text, p_versao integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pedir_calculo_classificacao(p_edital uuid, p_tipo text, p_versao integer) IS '"Gerar" da Classificação (20261023200000): com a chave "Gerar listas pelo Python" desligada, devolve {ligada: false} e não grava nada (a tela registra pelo cálculo dela, como antes). Ligada: confere o editor do edital, o tipo e a versão vigente da regra (PT409), troca para SUBSTITUIDO o cálculo pronto e abandonado da mesma lista, grava o pedido e pede classificacao.yml (modo calculo) por FC_DISPARAR_ROBO em nome de quem gerou; sem o pedido ao GitHub, SEM_DISPARO com a mensagem. Devolve {ligada, pedido, tipo, situacao, mensagem, pedido_em}. Classificação editor.';

--
-- Name: pedir_casamento_da_lista(uuid, text, jsonb, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pedir_casamento_da_lista(p_edital uuid, p_origem text, p_candidatos jsonb DEFAULT NULL::jsonb, p_lista_classificacao uuid DEFAULT NULL::uuid, p_lista_vigente uuid DEFAULT NULL::uuid, p_arquivo_nome text DEFAULT NULL::text, p_manuais jsonb DEFAULT '{}'::jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := (select auth.uid());
  v_anterior uuid;
  v_novos jsonb;
  v_manuais jsonb := coalesce(p_manuais, '{}'::jsonb);
  v_pedido uuid;
  v_disparo bigint;
  v_situacao text;
begin
  perform private."FC_EXIGIR_PEDIR_NOVA_VERSAO"(p_edital, p_origem);
  if not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital) then
    raise exception 'Edital nao encontrado' using errcode = '22023';
  end if;
  if jsonb_typeof(v_manuais) <> 'object'
     or exists (select 1 from jsonb_each(v_manuais) e
                 where e.key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    or jsonb_typeof(e.value) <> 'string') then
    raise exception 'Revisão inválida.' using errcode = '22023';
  end if;

  select l.id into v_anterior from public."TB_LISTA_APROVADO" l
   where l.edital_id = p_edital::text and l.vigente is true;
  if p_origem = 'CLASSIFICACAO' and v_anterior is distinct from p_lista_vigente then
    raise exception 'A lista de aprovados do edital mudou desde a prévia; abra a publicação de novo.' using errcode = 'PT409';
  end if;
  -- A mesma regra nos dois caminhos (o motivo é pedido ao aplicar).
  perform private."FC_EXIGIR_PODE_SUBSTITUIR_LISTA"(p_edital::text, v_anterior, p_origem, null, false);

  if p_origem = 'XLSX' then
    if p_lista_classificacao is not null then
      raise exception 'A planilha não traz resultado da Classificação.' using errcode = '22023';
    end if;
    if nullif(btrim(coalesce(p_arquivo_nome, '')), '') is null then
      raise exception 'Arquivo XLSX nao informado' using errcode = '22023';
    end if;
    if jsonb_typeof(p_candidatos) is distinct from 'array' or jsonb_array_length(p_candidatos) = 0 then
      raise exception 'A lista precisa conter pelo menos um candidato' using errcode = '22023';
    end if;
    if jsonb_array_length(p_candidatos) > 20000 then
      raise exception 'A planilha passa de 20.000 linhas.' using errcode = '22023';
    end if;
    select jsonb_agg(jsonb_build_object(
             'chave', x.linha::text, 'analise_id', null,
             'nome', nullif(btrim(x.valor ->> 'nome'), ''), 'cargo', nullif(btrim(x.valor ->> 'cargo'), ''),
             'codigo_vaga', nullif(btrim(x.valor ->> 'codigo_vaga'), ''),
             'posicao', (x.valor ->> 'classificacao')::integer, 'nota', (x.valor ->> 'nota')::numeric,
             'situacao', null, 'modalidade', nullif(btrim(x.valor ->> 'modalidade'), ''), 'ordem', x.linha)
           order by x.linha)
      into v_novos
      from jsonb_array_elements(p_candidatos) with ordinality x(valor, linha);
  else
    if p_lista_classificacao is null or p_candidatos is not null then
      raise exception 'Informe só o resultado final da Classificação.' using errcode = '22023';
    end if;
    if not exists (select 1 from public."TB_LISTA_CLASSIFICACAO" c
                    where c."CO_LISTA_CLASSIFICACAO" = p_lista_classificacao and c."CO_MONITORAMENTO" = p_edital) then
      raise exception 'Lista de classificação de outro edital.' using errcode = '22023';
    end if;
    v_novos := private."FC_NOVOS_DA_CLASSIFICACAO"(p_lista_classificacao, v_anterior);
  end if;

  -- Os pedidos velhos saem; os abertos da pessoa neste edital ficam para trás.
  delete from public."TB_PEDIDO_CASAMENTO_LISTA" p where p."DT_PEDIDO" < now() - interval '2 days';
  update public."TB_PEDIDO_CASAMENTO_LISTA" p set "TP_SITUACAO" = 'DESCARTADO', "DS_PLANO" = null
   where p."CO_MONITORAMENTO" = p_edital and p."CO_USUARIO" = v_uid
     and p."TP_SITUACAO" in ('PENDENTE', 'CALCULADO', 'ERRO');

  -- Sem lista vigente não há o que casar: o plano sai na hora.
  v_situacao := case when v_anterior is null then 'CALCULADO' else 'PENDENTE' end;
  insert into public."TB_PEDIDO_CASAMENTO_LISTA" (
    "CO_MONITORAMENTO", "CO_LISTA_APROVADO_ANTERIOR", "TP_ORIGEM", "CO_LISTA_CLASSIFICACAO", "DS_NOVOS",
    "DS_MANUAIS", "NO_ARQUIVO", "DS_BASE", "TP_SITUACAO", "DS_PLANO", "CO_EXECUCAO", "DT_CALCULO", "CO_USUARIO"
  ) values (
    p_edital, v_anterior, p_origem, p_lista_classificacao, v_novos, v_manuais,
    nullif(btrim(coalesce(p_arquivo_nome, '')), ''), private."FC_BASE_DA_LISTA"(v_anterior), v_situacao,
    case when v_anterior is null then jsonb_build_object(
      'versao', 1, 'vinculos', '[]'::jsonb, 'pendencias', '[]'::jsonb, 'mudam', '[]'::jsonb, 'revisar', '[]'::jsonb,
      'resumo', jsonb_build_object('casados', 0, 'entram', jsonb_array_length(v_novos), 'sem_par', 0, 'sem_dono', 0,
                                   'preservados', 0, 'mudam', 0, 'sub_judice_mantidos', 0, 'ambiguos', 0)) end,
    case when v_anterior is null then 'banco' end,
    case when v_anterior is null then now() end,
    v_uid
  ) returning "CO_PEDIDO" into v_pedido;

  if v_anterior is not null then
    v_disparo := private."FC_DISPARAR_ROBO"('casamento-da-lista.yml',
                   jsonb_build_object('modo', 'normal', 'pedido', v_pedido::text), v_uid);
    update public."TB_PEDIDO_CASAMENTO_LISTA" set "CO_DISPARO" = v_disparo where "CO_PEDIDO" = v_pedido;
  end if;

  return json_build_object('pedido_id', v_pedido, 'situacao', v_situacao,
                           'candidatos', jsonb_array_length(v_novos), 'lista_vigente', v_anterior);
end;
$_$;

--
-- Name: FUNCTION pedir_casamento_da_lista(p_edital uuid, p_origem text, p_candidatos jsonb, p_lista_classificacao uuid, p_lista_vigente uuid, p_arquivo_nome text, p_manuais jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pedir_casamento_da_lista(p_edital uuid, p_origem text, p_candidatos jsonb, p_lista_classificacao uuid, p_lista_vigente uuid, p_arquivo_nome text, p_manuais jsonb) IS 'A prévia de uma nova versão da lista de aprovados (XLSX: p_candidatos e p_arquivo_nome; Classificação: p_lista_classificacao e p_lista_vigente), com a revisão à mão (p_manuais). Guarda o pedido e pede o job Python do casamento; sem lista vigente, o plano sai na hora. Mesma permissão nos dois caminhos (FC_EXIGIR_PEDIR_NOVA_VERSAO, FC_EXIGIR_PODE_SUBSTITUIR_LISTA). 20261030090000.';

--
-- Name: pedir_reinicio_fichas_do_edital(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pedir_reinicio_fichas_do_edital(p_edital uuid, p_motivo text, p_confirmacao text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_usuario uuid := (select auth.uid());
  v_motivo text := btrim(regexp_replace(coalesce(p_motivo, ''), '\s+', ' ', 'g'));
  v_bloqueio text;
  v_impacto jsonb;
  v_pedido bigint;
  v_vencido record;
begin
  if not private."FC_ADMIN_GLOBAL_ATIVO"(v_usuario) then
    raise exception 'Só o administrador global pede o reinício das fichas do edital.' using errcode = '42501';
  end if;
  if length(v_motivo) not between 10 and 1000 then
    raise exception 'Informe o motivo do reinício (10 a 1.000 caracteres).' using errcode = '22023';
  end if;
  if not private."FC_MOTIVO_PARECE_TEXTO"(v_motivo, 3) then
    raise exception 'Escreva o motivo do reinício com pelo menos 3 palavras.' using errcode = '22023';
  end if;
  perform 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital for update;
  if not found then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  if not private."FC_CONFIRMACAO_DO_EDITAL"(p_edital, p_confirmacao) then
    raise exception 'O número digitado não confere com o do edital.' using errcode = '22023';
  end if;
  v_bloqueio := private."FC_BLOQUEIO_REINICIO_FICHAS"(p_edital);
  if v_bloqueio is not null then
    raise exception '%', v_bloqueio using errcode = '55000';
  end if;

  -- O pendente que passou da validade vira VENCIDO (abre lugar para o novo pedido).
  for v_vencido in
    update public."TB_PEDIDO_REINICIO_FICHA" p
       set "TP_SITUACAO" = 'VENCIDO', "DT_DECISAO" = now()
     where p."CO_MONITORAMENTO" = p_edital and p."TP_SITUACAO" = 'PENDENTE' and p."DT_VALIDADE" <= now()
    returning p."CO_PEDIDO_REINICIO", p."DT_VALIDADE"
  loop
    insert into public."TH_PEDIDO_REINICIO_FICHA" ("CO_PEDIDO_REINICIO", "CO_MONITORAMENTO", "TP_EVENTO", "DS_DETALHE")
    values (v_vencido."CO_PEDIDO_REINICIO", p_edital, 'VENCER', jsonb_build_object('validade', v_vencido."DT_VALIDADE"));
  end loop;
  if exists (select 1 from public."TB_PEDIDO_REINICIO_FICHA" p
              where p."CO_MONITORAMENTO" = p_edital and p."TP_SITUACAO" = 'PENDENTE') then
    raise exception 'Já há um pedido de reinício deste edital aguardando aprovação.' using errcode = '55000';
  end if;

  v_impacto := private."FC_IMPACTO_REINICIO_FICHAS"(p_edital);
  if (v_impacto ->> 'iniciadas')::integer = 0 then
    raise exception 'Nenhuma ficha deste edital foi iniciada: não há o que reiniciar.' using errcode = '55000';
  end if;

  insert into public."TB_PEDIDO_REINICIO_FICHA"
    ("CO_MONITORAMENTO", "DS_MOTIVO", "CO_USUARIO_PEDIDO", "DT_PEDIDO", "DT_VALIDADE",
     "QT_CONCLUIDAS", "QT_EM_ANALISE", "QT_INICIADAS")
  values (p_edital, v_motivo, v_usuario, now(), now() + interval '24 hours',
          (v_impacto ->> 'concluidas')::integer, (v_impacto ->> 'em_analise')::integer, (v_impacto ->> 'iniciadas')::integer)
  returning "CO_PEDIDO_REINICIO" into v_pedido;
  insert into public."TH_PEDIDO_REINICIO_FICHA" ("CO_PEDIDO_REINICIO", "CO_MONITORAMENTO", "TP_EVENTO", "CO_USUARIO", "DS_MOTIVO", "DS_DETALHE")
  values (v_pedido, p_edital, 'PEDIR', v_usuario, v_motivo, v_impacto);

  return private."FC_LER_REINICIO_FICHAS"(p_edital, v_usuario);
end;
$$;

--
-- Name: FUNCTION pedir_reinicio_fichas_do_edital(p_edital uuid, p_motivo text, p_confirmacao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pedir_reinicio_fichas_do_edital(p_edital uuid, p_motivo text, p_confirmacao text) IS 'Administrador global A pede o reinício das fichas do edital (20261022210000): motivo de 10 a 1.000 que pareça texto (3 palavras) e o número do edital digitado (22023). Recusa (55000) edital congelado ou encerrado, sem ficha iniciada ou com pedido pendente. Grava o pedido (impacto no momento, validade de 24 h) e o evento PEDIR; nada muda nas fichas. Devolve a leitura (FC_LER_REINICIO_FICHAS).';

--
-- Name: pegar_proxima_ficha(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pegar_proxima_ficha(p_edital uuid, p_vaga text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 2);
  v_uid uuid := (select auth.uid());
  v_vaga text := nullif(btrim(coalesce(p_vaga, '')), '');
  v_dist jsonb := private."FC_DISTRIBUICAO_DO_EDITAL"(p_edital);
  v_ficha uuid;
begin
  if not private."FC_PODE_ANALISAR_VAGA"(p_edital, v_uid, v_vaga) then
    raise exception 'Você não está na equipe deste edital como analista%', case when v_vaga is null then '' else ' da vaga ' || v_vaga end
      using errcode = '42501';
  end if;

  -- Primeiro as suas (a que já está em análise, depois as distribuídas), na ordem da Provisória.
  select f."CO_FICHA_ANALISE" into v_ficha
    from public."TB_FICHA_ANALISE" f
    join public."TB_PRE_CLASSIFICACAO" p
      on p."CO_MONITORAMENTO" = f."CO_MONITORAMENTO" and p."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
   where f."CO_MONITORAMENTO" = p_edital and f."CO_USUARIO_RESPONSAVEL" = v_uid
     and f."TP_SITUACAO" in ('PENDENTE', 'EM_ANALISE')
     and (v_vaga is null or f."CO_VAGA" = v_vaga)
     and (f."CO_USUARIO_RESERVA" is null or f."CO_USUARIO_RESERVA" = v_uid or f."DT_RESERVA_EXPIRA" <= now())
   order by f."TP_SITUACAO" = 'EM_ANALISE' desc, p."NU_POSICAO", f."CO_VAGA", f."CO_FICHA_ANALISE"
   limit 1
   for update of f skip locked;

  -- Depois a primeira livre (Pegar próximo, ou os que entram depois ficam livres).
  if v_ficha is null and (v_dist ->> 'modo' = 'PEGAR_PROXIMO' or v_dist ->> 'novos' = 'PEGAR_PROXIMO') then
    select f."CO_FICHA_ANALISE" into v_ficha
      from public."TB_FICHA_ANALISE" f
      join public."TB_PRE_CLASSIFICACAO" p
        on p."CO_MONITORAMENTO" = f."CO_MONITORAMENTO" and p."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
     where f."CO_MONITORAMENTO" = p_edital and f."CO_USUARIO_RESPONSAVEL" is null and f."TP_SITUACAO" = 'PENDENTE'
       and (v_vaga is null or f."CO_VAGA" = v_vaga)
       and exists (select 1 from public."RL_ANALISTA_EDITAL" r
                    where r."CO_MONITORAMENTO" = p_edital and r."CO_USUARIO" = v_uid and r."TP_PAPEL" = 'ANALISTA'
                      and r."ST_ATIVO" = 'S' and (r."CO_VAGA" is null or r."CO_VAGA" = f."CO_VAGA"))
     order by p."NU_POSICAO", f."CO_VAGA", f."CO_FICHA_ANALISE"
     limit 1
     for update of f skip locked;
  end if;

  if v_ficha is null then
    return json_build_object('ficha', null, 'reservada', false,
                             'motivo', case when v_dist ->> 'modo' = 'DISTRIBUICAO_INICIAL' and v_dist ->> 'novos' <> 'PEGAR_PROXIMO'
                                            then 'Nenhuma ficha sua na fila: a coordenação distribui as fichas deste edital.'
                                            else 'Nenhuma ficha livre na fila.' end);
  end if;
  perform private."FC_RESERVAR_FICHA"(v_ficha, v_uid, 'PEGAR');
  insert into public."TL_ACESSO_FICHA_ANALISE" ("CO_FICHA_ANALISE", "TP_ACESSO", "CO_USUARIO") values (v_ficha, 'ABRIR_FICHA', v_uid);
  return json_build_object('ficha', private."FC_FICHA_ANALISE_JSON"(v_ficha), 'reservada', true, 'motivo', null);
end;
$$;

--
-- Name: FUNCTION pegar_proxima_ficha(p_edital uuid, p_vaga text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pegar_proxima_ficha(p_edital uuid, p_vaga text) IS '"Pegar próximo": dá ao analista a próxima ficha na ordem da Provisória — primeiro as suas (em análise, depois as distribuídas), depois a primeira livre das vagas que ele analisa (no modo Pegar próximo, ou quando a regra deixa livres os que entram depois) — e a reserva por 15 minutos. for update skip locked: duas pessoas nunca recebem a mesma (AM-6.1). p_vaga restringe a uma vaga. Exige Editor e a linha ANALISTA na equipe.';

--
-- Name: pendencias_ler_aprovados(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pendencias_ler_aprovados(p_apos uuid DEFAULT NULL::uuid, p_limite integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    SET work_mem TO '16MB'
    AS $$
  -- 20261103181500: sem argumentos, a resposta de sempre; com p_limite, uma página.
  with listas as materialized (
    select l.id, l.edital_id::uuid as edital, m."CO_AREA" as area, coalesce(l.ativo, false) as ativo,
           (row_number() over (order by l.id) - 1)::integer as i
      from public."TB_LISTA_APROVADO" l
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id
     where l.vigente is true
       and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO")
  ), pagina as materialized (
    select c.id, li.i, c.codigo_vaga, c.modalidade, c.classificacao, c.status, c."DT_CONVOCACAO",
           c.nome, c.matricula, c."CO_ANALISE_CURRICULAR"
      from listas li
      join public."TB_CANDIDATO_APROVADO" c on c.lista_id = li.id and c.removido_em is null
     where p_apos is null or c.id > p_apos
     order by c.id
     limit case when p_limite is not null then least(greatest(p_limite, 1), 10000) end
  ), linhas as (
    -- Sem nome, CPF nem matrícula: hashes curtos do nome, do código do candidato e da matrícula.
    select p.id, p.i, p.codigo_vaga, p.modalidade, p.classificacao, p.status, p."DT_CONVOCACAO",
           left(encode(sha256(convert_to('pendencia:nome:' || lower(regexp_replace(btrim(p.nome), '\s+', ' ', 'g')),
                                         'UTF8')), 'hex'), 16) as nome,
           left(encode(sha256(convert_to('pendencia:cod:' || nullif(btrim(a.id_origem), ''), 'UTF8')), 'hex'), 16) as codigo,
           case when p.status = 'Contratado' then left(private."FC_VINCULO_DA_MATRICULA"(p.matricula), 16) end as vinculo,
           case when p.status = 'Contratado' then private."FC_EM_OUTRA_LISTA"(p.id) end as outra
      from pagina p
      left join public."TB_ANALISE_CURRICULAR" a on a.id = p."CO_ANALISE_CURRICULAR"
  )
  select jsonb_build_object(
    'schema_version', 1,
    'lido_em', now(),
    'listas', (select coalesce(jsonb_agg(jsonb_build_array(li.id, li.edital, li.area, li.ativo) order by li.i), '[]'::jsonb)
                 from listas li),
    'linhas', (select coalesce(jsonb_agg(jsonb_build_array(x.id, x.i, x.codigo_vaga, x.modalidade, x.classificacao,
                                                           x.status, x."DT_CONVOCACAO", x.nome, x.codigo, x.vinculo, x.outra)
                                         order by x.id), '[]'::jsonb)
                 from linhas x))
  -- Os AMBIGUO e as pendências gravadas, só na primeira página (ou na leitura inteira).
  || case when p_apos is null then jsonb_build_object(
    'ambiguos', (select coalesce(jsonb_agg(jsonb_build_array(x."CO_CANDIDATO_APROVADO", x."CO_MONITORAMENTO",
                                                             left(x."DS_VINCULO", 16), x."TP_MOTIVO")
                                           order by x."CO_CANDIDATO_APROVADO"), '[]'::jsonb)
                   from public."TB_CONTRATACAO_APROVADO" x
                   join public."TB_CANDIDATO_APROVADO" c on c.id = x."CO_CANDIDATO_APROVADO" and c.removido_em is null
                   join listas li on li.id = c.lista_id
                  where x."TP_SITUACAO" = 'AMBIGUO'),
    'pendencias', (select coalesce(jsonb_agg(jsonb_build_array(p."TP_PENDENCIA", p."DS_CHAVE", p."TP_SITUACAO", p."TP_DECISAO")
                                             order by p."TP_PENDENCIA", p."DS_CHAVE"), '[]'::jsonb)
                     from public."TB_PENDENCIA_APROVADO" p)) else '{}'::jsonb end
  -- O cursor da página seguinte: só com p_limite e a página cheia.
  || coalesce((select jsonb_build_object('proximo', max(p.id::text)::uuid)
                 from pagina p
                where p_limite is not null
               having count(*) = least(greatest(p_limite, 1), 10000)), '{}'::jsonb);
$$;

--
-- Name: FUNCTION pendencias_ler_aprovados(p_apos uuid, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pendencias_ler_aprovados(p_apos uuid, p_limite integer) IS 'Job "Pendências do edital" (Python, só service_role): as listas vigentes fora do treinamento (id, edital, área, ativa), as linhas delas em formato compacto (id, lista, vaga, modalidade, posição, status, data da convocação, hashes curtos do nome, do código do candidato e da matrícula do Contratado, em outra lista), os AMBIGUO do instantâneo TB_CONTRATACAO_APROVADO e as pendências já gravadas (tipo, chave, situação, decisão). Sem nome, CPF nem matrícula. 20261026190000. Com p_limite (20261103181500): uma página das linhas em ordem do id depois de p_apos (até 10000), proximo quando há mais; ambiguos e pendencias só na primeira página.';

