--
-- Name: pre_classificacao_ler_candidatos(uuid, text, uuid, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pre_classificacao_ler_candidatos(p_edital uuid, p_vaga text, p_apos uuid DEFAULT NULL::uuid, p_limite integer DEFAULT NULL::integer, p_colunas text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_candidatos jsonb;
  v_mais boolean;
  v_lido jsonb;
begin
  if not exists (select 1 from public."TB_EMPREGARE_VAGA" v where v."CO_VAGA" = p_vaga and v."CO_MONITORAMENTO" = p_edital) then
    raise exception 'A vaga % não é do edital', p_vaga using errcode = '22023';
  end if;
  if p_limite is not null and (p_limite < 1 or p_limite > 5000) then
    raise exception 'p_limite vai de 1 a 5000' using errcode = '22023';
  end if;
  if cardinality(p_colunas) > 500 then
    raise exception 'Até 500 colunas' using errcode = '22023';
  end if;

  -- Uma parte na ordem do id (o mesmo order by de antes), com um a mais para saber se há outra.
  select coalesce(jsonb_agg(
           case when p_colunas is null then
             jsonb_build_object(
               'id', p."CO_EMPREGARE_CANDIDATO",
               'codigo', coalesce(p."CO_CANDIDATO_EMPREGARE", left(p."DS_CHAVE_CANDIDATO", 12)),
               'ativo', p."ST_REGISTRO_ATIVO" = 'S',
               'nascimento', p."DT_NASCIMENTO",
               'candidatura', to_char(p."DT_CANDIDATURA" at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"'),
               -- As respostas do questionário e as colunas do processo, sem as do cadastro.
               'colunas', coalesce((
                 select jsonb_object_agg(k.key, k.value)
                   from jsonb_each(p."DS_COLUNA_ORIGINAL") k
                  where lower(k.key) like 'pergunta %'
                     or lower(k.key) !~ '(nome|e-?mail|cpf|telefone|celular|whatsapp|endere|logradouro|bairro|cep|nascimento|linkedin|^rg$|documento)'),
                 '{}'::jsonb))
           else
             -- [enxuto] Só as colunas pedidas que o inscrito tem, pela posição em p_colunas
             -- (a mesma regra do cadastro), e sem os campos nulos.
             jsonb_strip_nulls(jsonb_build_object(
               'id', p."CO_EMPREGARE_CANDIDATO",
               'codigo', coalesce(p."CO_CANDIDATO_EMPREGARE", left(p."DS_CHAVE_CANDIDATO", 12)),
               'ativo', p."ST_REGISTRO_ATIVO" = 'S',
               'nascimento', p."DT_NASCIMENTO",
               'candidatura', to_char(p."DT_CANDIDATURA" at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"+00:00"')))
             || jsonb_build_object('c', coalesce((
                  select jsonb_object_agg((u.i - 1)::text, p."DS_COLUNA_ORIGINAL" -> u.nome)
                    from unnest(p_colunas) with ordinality u(nome, i)
                   where p."DS_COLUNA_ORIGINAL" ? u.nome
                     and (lower(u.nome) like 'pergunta %'
                          or lower(u.nome) !~ '(nome|e-?mail|cpf|telefone|celular|whatsapp|endere|logradouro|bairro|cep|nascimento|linkedin|^rg$|documento)')),
                  '{}'::jsonb))
           end
         order by p."CO_EMPREGARE_CANDIDATO")
         filter (where p_limite is null or p.nu_ordem <= p_limite), '[]'::jsonb),
         p_limite is not null and count(*) > p_limite
    into v_candidatos, v_mais
    from (select c."CO_EMPREGARE_CANDIDATO", c."CO_CANDIDATO_EMPREGARE", c."DS_CHAVE_CANDIDATO", c."ST_REGISTRO_ATIVO",
                 c."DT_NASCIMENTO", c."DT_CANDIDATURA", c."DS_COLUNA_ORIGINAL",
                 row_number() over (order by c."CO_EMPREGARE_CANDIDATO") as nu_ordem
            from public."TB_EMPREGARE_CANDIDATO" c
           where c."CO_VAGA" = p_vaga
             and (p_apos is null or c."CO_EMPREGARE_CANDIDATO" > p_apos)
           order by c."CO_EMPREGARE_CANDIDATO"
           limit p_limite + 1) p;

  v_lido := jsonb_build_object('candidatos', v_candidatos, 'mais', v_mais);
  if p_apos is not null then
    return v_lido;
  end if;

  return v_lido || jsonb_build_object(
    -- A vaga: o cargo e a linha do quadro (a mesma de antes em pre_classificacao_ler_editais).
    'vaga', (select jsonb_build_object(
                      'cargo', q."NO_CARGO",
                      'quadro', case when q."CO_QUADRO_VAGA" is null then null else jsonb_build_object(
                        'id', q."CO_QUADRO_VAGA", 'vagas_imediatas', q."QT_VAGA_IMEDIATA",
                        'cadastro_reserva', q."ST_CADASTRO_RESERVA" = 'S', 'modalidades', q."DS_MODALIDADE_VAGA") end)
               from (select 1) x
               left join lateral (select * from private."FC_QUADRO_DA_VAGA_EMPREGARE"(p_edital, p_vaga)) q on true),
    'anterior', coalesce((
      select jsonb_object_agg(a."CO_EMPREGARE_CANDIDATO", jsonb_build_object(
               'situacao', a."TP_SITUACAO", 'posicao', a."NU_POSICAO", 'lote', a."NU_LOTE",
               'lista_lote', a."CO_LISTA_LOTE", 'entrada', a."TP_ENTRADA_LOTE", 'motivo_entrada', a."DS_MOTIVO_ENTRADA",
               -- A declarada congelada não se recalcula (o job usa o valor guardado).
               'declarada_congelada', case when a."VL_DECLARADA_CONGELADA" is not null
                                           then a."DS_DECLARADA_CONGELADA" || jsonb_build_object('total', a."VL_DECLARADA_CONGELADA") end))
        from public."TB_PRE_CLASSIFICACAO" a
       where a."CO_MONITORAMENTO" = p_edital and a."CO_VAGA" = p_vaga), '{}'::jsonb),
    -- As decisões da coordenação: ficam no lote (entrada DECISAO) em todo recálculo.
    'decisoes', coalesce((
      select jsonb_object_agg(d."CO_EMPREGARE_CANDIDATO", jsonb_build_object('motivo', d."DS_MOTIVO"))
        from public."TB_DECISAO_LOTE" d
       where d."CO_MONITORAMENTO" = p_edital and d."CO_VAGA" = p_vaga and d."ST_ATIVO" = 'S'), '{}'::jsonb)
  );
end;
$_$;

--
-- Name: FUNCTION pre_classificacao_ler_candidatos(p_edital uuid, p_vaga text, p_apos uuid, p_limite integer, p_colunas text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pre_classificacao_ler_candidatos(p_edital uuid, p_vaga text, p_apos uuid, p_limite integer, p_colunas text[]) IS 'Pré-classificação (job Python): os inscritos de uma vaga do edital em partes, na ordem do id (p_apos = último id da parte anterior; p_limite de 1 a 5.000, nulo = todos; "mais" = há outra parte) — id, código, ativo, nascimento, data da candidatura e as colunas do questionário e do processo SEM as do cadastro (nome, e-mail, CPF, telefone, endereço). Com p_colunas (desde 20261014220000), só essas colunas, em "c" = {"<posição em p_colunas, a partir de 0>": valor}, e sem os campos nulos; sem p_colunas, todas em "colunas" = {nome: valor}, como antes. Na primeira parte (sem p_apos) vêm também a vaga ({cargo, quadro}), a situação anterior de cada inscrito e as decisões vigentes da coordenação. Só service_role.';

--
-- Name: pre_classificacao_ler_colunas(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pre_classificacao_ler_colunas(p_edital uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select jsonb_build_object('colunas', coalesce(jsonb_agg(n.nome order by n.nome), '[]'::jsonb))
    from (select distinct k.nome
            from public."TB_EMPREGARE_VAGA" v
            join public."TB_EMPREGARE_CANDIDATO" c on c."CO_VAGA" = v."CO_VAGA"
           cross join lateral jsonb_object_keys(c."DS_COLUNA_ORIGINAL") k(nome)
           where v."CO_MONITORAMENTO" = p_edital
             and (lower(k.nome) like 'pergunta %'
                  or lower(k.nome) !~ '(nome|e-?mail|cpf|telefone|celular|whatsapp|endere|logradouro|bairro|cep|nascimento|linkedin|^rg$|documento)')) n;
$_$;

--
-- Name: FUNCTION pre_classificacao_ler_colunas(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pre_classificacao_ler_colunas(p_edital uuid) IS 'Pré-classificação (job Python): os nomes das colunas dos inscritos das vagas do edital, sem as do cadastro (nome, e-mail, CPF, telefone, endereço), uma vez. O job escolhe as que a regra usa e pede só elas em pre_classificacao_ler_candidatos(p_colunas). Desde 20261014220000. Só service_role.';

--
-- Name: pre_classificacao_ler_distribuicao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pre_classificacao_ler_distribuicao(p_edital uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital) then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  return private."FC_DISTRIBUICAO_DO_EDITAL"(p_edital) || jsonb_build_object(
    'distribuicao_iniciada', exists (
      select 1 from public."TH_FICHA_ANALISE" h
        join public."TB_FICHA_ANALISE" f on f."CO_FICHA_ANALISE" = h."CO_FICHA_ANALISE"
       where f."CO_MONITORAMENTO" = p_edital and h."TP_ACAO" in ('DISTRIBUIR', 'REDISTRIBUIR') and h."TP_ORIGEM" = 'TELA'),
    'analistas', private."FC_ANALISTAS_DO_EDITAL"(p_edital, false),
    'a_abrir', coalesce((
      select jsonb_agg(jsonb_build_object('candidato', p."CO_EMPREGARE_CANDIDATO", 'vaga', p."CO_VAGA",
                                          'posicao', p."NU_POSICAO", 'lote', p."NU_LOTE")
                       order by p."NU_POSICAO", p."CO_VAGA", p."CO_EMPREGARE_CANDIDATO")
        from public."TB_PRE_CLASSIFICACAO" p
       where p."CO_MONITORAMENTO" = p_edital and p."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO')
         and not exists (select 1 from public."TB_FICHA_ANALISE" f
                          where f."CO_MONITORAMENTO" = p_edital and f."CO_EMPREGARE_CANDIDATO" = p."CO_EMPREGARE_CANDIDATO")), '[]'::jsonb));
end;
$$;

--
-- Name: FUNCTION pre_classificacao_ler_distribuicao(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pre_classificacao_ler_distribuicao(p_edital uuid) IS 'Job da pré-classificação: a distribuição do edital (modo, critério, limite, destino dos novos), se a coordenação já distribuiu, os analistas que podem receber ficha (ids, vagas, limite, pendentes; sem nome) e quem está no lote sem ficha (id, vaga, posição, lote), na ordem da Provisória. Só service_role.';

--
-- Name: pre_classificacao_ler_editais(text[], boolean, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pre_classificacao_ler_editais(p_editais text[] DEFAULT NULL::text[], p_apos_robo boolean DEFAULT false, p_incluir_congelados boolean DEFAULT false, p_liberacao uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_pedidos text[] := array(select btrim(x) from unnest(coalesce(p_editais, '{}')) x where btrim(x) <> '');
  v_ids uuid[];
  v_sync text;
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_congelados uuid[] := '{}';
begin
  if cardinality(v_pedidos) > 100 then
    raise exception 'Até 100 editais por execução' using errcode = '22023';
  end if;
  if cardinality(v_pedidos) > 0 then
    -- Cada pedido é o id do edital, o número ("93/2026") ou, sem número, o nome ("FCC").
    select coalesce(array_agg(distinct m.id), '{}') into v_ids
      from public."TB_MONITORAMENTO_INDIGENA" m
      join unnest(v_pedidos) p(texto)
        on m.id::text = lower(p.texto)
        or private."FC_NUMERO_EDITAL"(m.edital) = p.texto
        or lower(btrim(m.edital)) = lower(p.texto);
  elsif p_apos_robo then
    -- Os editais das vagas gravadas na última execução fechada do robô.
    select s."CO_SYNC" into v_sync
      from public."TL_SYNC_EMPREGARE" s
     where s."TP_SITUACAO" in ('CONCLUIDA', 'PARCIAL')
     order by s."DT_INICIO" desc limit 1;
    select coalesce(array_agg(distinct v."CO_MONITORAMENTO"), '{}') into v_ids
      from public."TB_EMPREGARE_VAGA" v
     where v."CO_SYNC" = v_sync and v."CO_MONITORAMENTO" is not null
       and not private."FC_EDITAL_EH_TREINAMENTO"(v."CO_MONITORAMENTO");
  else
    select coalesce(array_agg(distinct v."CO_MONITORAMENTO"), '{}') into v_ids
      from public."TB_EMPREGARE_VAGA" v
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = v."CO_MONITORAMENTO"
     where coalesce(m.ativo, false) and not private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO");
  end if;

  -- [congeladas] Edital com inscrições congeladas (20261020170000): fica fora (após robô,
  -- normal e refazer lote), salvo liberação válida; o modo seco pede p_incluir_congelados.
  if not coalesce(p_incluir_congelados, false) then
    select coalesce(array_agg(x), '{}') into v_congelados
      from unnest(v_ids) x
     where private."FC_INSCRICOES_CONGELADAS"(x)
       and not private."FC_LIBERACAO_CONGELAMENTO_VALIDA"(p_liberacao, x);
    v_ids := array(select x from unnest(v_ids) x where not x = any (v_congelados));
  end if;

  return jsonb_build_object(
    'hoje', v_hoje,
    'sync', v_sync,
    'congelados', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', m.id, 'rotulo', private."FC_ROTULO_DO_EDITAL"(m.edital), 'pedido', cardinality(v_pedidos) > 0)
             order by private."FC_ROTULO_DO_EDITAL"(m.edital), m.id)
        from public."TB_MONITORAMENTO_INDIGENA" m
       where m.id = any (v_congelados)), '[]'::jsonb),
    'nao_encontrados', coalesce((
      select jsonb_agg(p.texto order by p.texto)
        from unnest(v_pedidos) p(texto)
       where not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m
                          where m.id::text = lower(p.texto)
                             or private."FC_NUMERO_EDITAL"(m.edital) = p.texto
                             or lower(btrim(m.edital)) = lower(p.texto))), '[]'::jsonb),
    'editais', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', m.id,
               'rotulo', private."FC_ROTULO_DO_EDITAL"(m.edital),
               'area', m."CO_AREA",
               'ativo', coalesce(m.ativo, false),
               'treinamento', private."FC_EH_TREINAMENTO"(m."ST_TREINAMENTO"),
               'congelado', private."FC_INSCRICOES_CONGELADAS"(m.id),
               'regra', (select jsonb_build_object('versao', r."NU_VERSAO_VIGENTE", 'situacao', r."TP_SITUACAO",
                                                   'configuracao', private."FC_REGRA_COM_DATA_LIMITE"(h."DS_CONFIGURACAO", m.id))
                           from public."TB_REGRA_ANALISE" r
                           join public."TH_REGRA_ANALISE" h
                             on h."CO_REGRA_ANALISE" = r."CO_REGRA_ANALISE" and h."NU_VERSAO" = r."NU_VERSAO_VIGENTE"
                          where r."CO_MONITORAMENTO" = m.id),
               'documental', private."FC_DOCUMENTAL_DO_EDITAL"(m.id),
               -- A regra própria da Triagem (20261029160000): é ela que o cálculo usa.
               'triagem', (select jsonb_build_object('versao', t."NU_VERSAO_VIGENTE", 'situacao', t."TP_SITUACAO",
                                                     'configuracao', ht."DS_CONFIGURACAO")
                             from public."TB_REGRA_TRIAGEM" t
                             join public."TH_REGRA_TRIAGEM" ht
                               on ht."CO_REGRA_TRIAGEM" = t."CO_REGRA_TRIAGEM" and ht."NU_VERSAO" = t."NU_VERSAO_VIGENTE"
                            where t."CO_MONITORAMENTO" = m.id),
               -- O cronograma: o job congela a declarada depois do fim das inscrições.
               'cronograma', coalesce((
                 select jsonb_agg(jsonb_build_object('atividade', c.atividade, 'inicio', c.data_inicio, 'fim', c.data_fim)
                        order by c.ordem)
                   from public."TB_CRONOGRAMA_MONIT_INDIG" c where c.monitoramento_id = m.id), '[]'::jsonb),
               -- Refazer o lote do zero: ninguém analisado e TODAS as fichas do edital intocadas
               -- (FC_FICHAS_INICIADAS = 0); fichas_iniciadas vai para a mensagem da recusa (20261013110000).
               'fichas_iniciadas', fi.n,
               'refazer_permitido', fi.n = 0
                                    and not exists (select 1 from public."TB_PRE_CLASSIFICACAO" a
                                                     where a."CO_MONITORAMENTO" = m.id and a."TP_SITUACAO" = 'ANALISADO'),
               -- [sem-mudanca] Só no fim do robô: nada mudou desde a última pré-classificação
               -- CONCLUÍDA de hoje que processou o edital (o job pula o edital).
               'sem_mudanca', p_apos_robo and cardinality(v_pedidos) = 0 and exists (
                 select 1
                   from public."TL_PRE_CLASSIFICACAO" l
                  where l."TP_SITUACAO" = 'CONCLUIDA'
                    and (l."DT_INICIO" at time zone 'America/Sao_Paulo')::date = v_hoje
                    and l."DS_EDITAL" @> jsonb_build_array(jsonb_build_object('edital', m.id, 'situacao', 'PROCESSADO'))
                    and l."DT_INICIO" > coalesce((
                          select max(c."DT_ATUALIZACAO")
                            from public."TB_EMPREGARE_VAGA" v
                            join public."TB_EMPREGARE_CANDIDATO" c on c."CO_VAGA" = v."CO_VAGA"
                           where v."CO_MONITORAMENTO" = m.id), '-infinity'::timestamptz)
                    and l."DT_INICIO" > coalesce((
                          select max(greatest(d."DT_CRIACAO", d."DT_ATUALIZACAO", d."DT_REVOGACAO"))
                            from public."TB_DECISAO_LOTE" d where d."CO_MONITORAMENTO" = m.id), '-infinity'::timestamptz)
                    and l."DT_INICIO" > coalesce((
                          select greatest(r."DT_CRIACAO", r."DT_ATUALIZACAO", r."DT_CONFERENCIA")
                            from public."TB_REGRA_ANALISE" r where r."CO_MONITORAMENTO" = m.id), '-infinity'::timestamptz)
                    and l."DT_INICIO" > coalesce((
                          select greatest(t."DT_CRIACAO", t."DT_ATUALIZACAO", t."DT_CONFERENCIA")
                            from public."TB_REGRA_TRIAGEM" t where t."CO_MONITORAMENTO" = m.id), '-infinity'::timestamptz)
                    and l."DT_INICIO" > coalesce((
                          select max(greatest(q."DT_CRIACAO", q."DT_DESATIVACAO"))
                            from public."TB_QUADRO_VAGA_EDITAL" q where q."CO_MONITORAMENTO" = m.id), '-infinity'::timestamptz)),
               -- Só os metadados da vaga: o cargo e a linha do quadro vêm com os inscritos
               -- (pre_classificacao_ler_candidatos, uma vaga por chamada, desde 20261014110000).
               'vagas', coalesce((
                 select jsonb_agg(jsonb_build_object(
                          'codigo', v."CO_VAGA",
                          'situacao_carga', v."TP_SITUACAO",
                          'candidatos_ativos', v."QT_CANDIDATO_ATIVO",
                          'ultima_carga', v."DT_ULTIMA_CARGA",
                          'ultimo_lote', coalesce(pv."NU_ULTIMO_LOTE", 0))
                        order by v."CO_VAGA")
                   from public."TB_EMPREGARE_VAGA" v
                   left join public."TB_PRE_CLASSIF_VAGA" pv on pv."CO_MONITORAMENTO" = m.id and pv."CO_VAGA" = v."CO_VAGA"
                  where v."CO_MONITORAMENTO" = m.id), '[]'::jsonb))
             order by private."FC_ROTULO_DO_EDITAL"(m.edital), m.id)
        from public."TB_MONITORAMENTO_INDIGENA" m
       cross join lateral (select private."FC_FICHAS_INICIADAS"(m.id) as n) fi
       where m.id = any (v_ids)), '[]'::jsonb)
  );
end;
$$;

--
-- Name: FUNCTION pre_classificacao_ler_editais(p_editais text[], p_apos_robo boolean, p_incluir_congelados boolean, p_liberacao uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pre_classificacao_ler_editais(p_editais text[], p_apos_robo boolean, p_incluir_congelados boolean, p_liberacao uuid) IS 'Job da pré-classificação (service_role): os editais a calcular — os pedidos (id, número ou nome), os das vagas da última carga do robô (p_apos_robo) ou os ativos com vagas da Empregare —, com a regra, o cronograma, as vagas e se o refazer é permitido. Inscrições congeladas (20261020170000): o edital congelado sai de "editais" e volta em "congelados" ({id, rotulo, pedido}; pedido = veio explícito, o job recusa), salvo p_liberacao válida (override do administrador global) ou p_incluir_congelados (modo seco, que não grava); cada edital traz "congelado".';

--
-- Name: preparar_sync_analises_incremental(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preparar_sync_analises_incremental(p_sync_id uuid, p_total_ativos_local integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '10s'
    SET lock_timeout TO '1s'
    AS $$
declare
  v_fato integer;
  v_editais integer;
  v_total integer;
  v_planilha text;
begin
  if p_sync_id is null then raise exception 'p_sync_id obrigatorio'; end if;
  if p_total_ativos_local is null or p_total_ativos_local < 0 then raise exception 'p_total_ativos_local invalido'; end if;
  if not exists(select 1 from public."TL_SYNC_ANALISE" where sync_id=p_sync_id and modo='INCREMENTAL_ACTIVE' and status in ('carregado','processando')) then
    raise exception 'Sync incremental indisponivel.';
  end if;

  select count(*) filter(where entidade='FATO_ANALISES')::integer,
         count(*) filter(where entidade='DIM_EDITAIS')::integer,
         count(*)::integer
    into v_fato,v_editais,v_total
  from public."TM_ANALISE_CURRICULAR"
  where sync_id=p_sync_id;

  if v_editais < 1 then raise exception 'DIM_EDITAIS nao foi enviada para o staging.'; end if;

  -- [por-planilha] porteiro: falha rápido, antes de qualquer lote.
  v_planilha := public."FC_PLANILHA_DO_SYNC_ANALISE"(p_sync_id);
  perform public."FC_VALIDAR_GRUPO_STAGING_ANALISE"(p_sync_id, v_planilha);

  update public."TL_SYNC_ANALISE"
  set linhas_staging=v_total,
      total_lidos=p_total_ativos_local,
      resultado=coalesce(resultado,'{}'::jsonb)||jsonb_build_object(
        'modo_processamento','incremental',
        'incremental_preparado',true,
        'incremental_total_ativos_local',p_total_ativos_local,
        'incremental_fato_alterados',v_fato,
        'incremental_editais',v_editais,
        'incremental_staging',v_total,
        'incremental_preparado_em',now(),
        'planilha',v_planilha,
        'planilha_validada',true
      ),
      updated_at=now()
  where sync_id=p_sync_id and modo='INCREMENTAL_ACTIVE';

  return jsonb_build_object('ok',true,'sync_id',p_sync_id,'total_ativos_local',p_total_ativos_local,'fato_alterados',v_fato,'editais',v_editais,'staging',v_total,'planilha',v_planilha);
end;
$$;

--
-- Name: processar_sync_analises(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.processar_sync_analises(p_sync_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    SET statement_timeout TO '5s'
    SET lock_timeout TO '1s'
    AS $$
begin
  raise exception 'Processamento monolitico desativado. Use processamento em lotes.';
end;
$$;

--
-- Name: processar_sync_analises_incremental_lote(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.processar_sync_analises_incremental_lote(p_sync_id uuid, p_limite integer DEFAULT 250) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '25s'
    SET lock_timeout TO '2s'
    AS $$
declare
  v_result jsonb;
  v_preparado boolean;
begin
  select coalesce((resultado->>'incremental_preparado')::boolean,false)
    into v_preparado
  from public."TL_SYNC_ANALISE"
  where sync_id=p_sync_id and modo='INCREMENTAL_ACTIVE' and status in ('carregado','processando')
  order by id desc limit 1;
  if not found then raise exception 'Sync incremental indisponivel.'; end if;
  if not v_preparado then raise exception 'Sync incremental ainda nao foi preparado.'; end if;

  -- [so-full] (20261022140000) Autoriza, só nesta chamada, o processamento do sync incremental
  -- por processar_sync_analises_lote (que recusa INCREMENTAL_ACTIVE vindo do fluxo FULL).
  perform set_config('agsus.sync_analise_incremental', p_sync_id::text, true);
  v_result := public.processar_sync_analises_lote(p_sync_id,p_limite);
  perform set_config('agsus.sync_analise_incremental', '', true);

  update public."TL_SYNC_ANALISE"
  set status='processando',
      resultado=coalesce(resultado,'{}'::jsonb)||jsonb_build_object('modo_processamento','incremental'),
      updated_at=now()
  where sync_id=p_sync_id and modo='INCREMENTAL_ACTIVE';

  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object('modo_processamento','incremental');
end;
$$;

--
-- Name: processar_sync_analises_lote(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.processar_sync_analises_lote(p_sync_id uuid, p_limite integer DEFAULT 250) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    SET statement_timeout TO '20s'
    SET lock_timeout TO '2s'
    SET work_mem TO '8MB'
    SET jit TO 'off'
    AS $$
declare
  v_limite integer := greatest(1, least(coalesce(p_limite,250),500));
  v_cursor integer := 0;
  v_novo_cursor integer := 0;
  v_lidas integer := 0;
  v_alteradas integer := 0;
  v_lidas_total integer := 0;
  v_alteradas_total integer := 0;
  v_planilha text;
  v_grupo_norm text;
  v_validada boolean := false;
  v_modo text;
  v_fora integer := 0;
  v_conflitos integer := 0;
  v_monitora integer := 0;
  v_monitora_total integer := 0;
begin
  if p_sync_id is null then raise exception 'p_sync_id obrigatorio'; end if;
  -- [por-planilha] planilha pela origem do sync; lock e checagens por planilha.
  v_planilha := public."FC_PLANILHA_DO_SYNC_ANALISE"(p_sync_id);
  if v_planilha is null then raise exception 'Sync % indisponivel para processamento em lotes.', p_sync_id; end if;
  if not pg_try_advisory_xact_lock(hashtext('public.processar_sync_analises:'||v_planilha)::bigint) then
    raise exception 'Outro processamento de analises ja esta em andamento.';
  end if;

  select coalesce(nullif(resultado->>'lote_cursor','')::integer,0),
         coalesce((resultado->>'planilha_validada')::boolean,false),
         modo
    into v_cursor,v_validada,v_modo
  from public."TL_SYNC_ANALISE"
  where sync_id=p_sync_id and status in ('carregado','processando')
  order by id desc limit 1;
  if not found then raise exception 'Sync % indisponivel para processamento em lotes.', p_sync_id; end if;

  -- [so-full] (20261022140000) Chamada direta (fluxo FULL) só processa sync FULL. Um sync
  -- INCREMENTAL_ACTIVE só passa por processar_sync_analises_incremental_lote, que marca a
  -- transação com agsus.sync_analise_incremental = sync_id antes de chamar esta função.
  if coalesce(v_modo, 'FULL') <> 'FULL'
     and not (v_modo = 'INCREMENTAL_ACTIVE'
              and coalesce(current_setting('agsus.sync_analise_incremental', true), '') = p_sync_id::text) then
    raise exception 'Sync % é % e não é processado pelo fluxo FULL (processar_sync_analises_lote). O incremental usa processar_sync_analises_incremental_lote.', p_sync_id, v_modo
      using errcode = '22023';
  end if;

  -- [por-planilha] porteiro: o staging inteiro, uma vez por sync.
  if not v_validada then
    perform public."FC_VALIDAR_GRUPO_STAGING_ANALISE"(p_sync_id, v_planilha);
  end if;

  select public.analises_norm_key(a."NO_GRUPO_PLANILHA") into v_grupo_norm
  from public."TB_PLANILHA_ANALISE" p join public."TB_AREA" a on a."CO_AREA"=p."CO_AREA"
  where p."CO_PLANILHA"=v_planilha;

  create temporary table tmp_lote on commit drop as
  select s.*
  from public."TM_ANALISE_CURRICULAR" s
  where s.sync_id=p_sync_id
    and s.entidade='FATO_ANALISES'
    and coalesce(s.linha_origem,0)>v_cursor
  order by s.linha_origem,s.id
  limit v_limite;

  select count(*)::integer, coalesce(max(linha_origem),v_cursor)::integer
    into v_lidas,v_novo_cursor
  from tmp_lote;

  if v_lidas=0 then
    return jsonb_build_object('ok',true,'sync_id',p_sync_id,'lidas',0,'alteradas',0,'cursor',v_cursor,'concluido_fato',true);
  end if;

  -- [por-planilha] o que este lote grava é do grupo da planilha e não é de outra planilha.
  select count(*)::integer into v_fora
  from tmp_lote s
  where coalesce(public.analises_norm_key(public.jsonb_text_or_null(s.payload,'grupo')),'') <> v_grupo_norm;
  if v_fora > 0 then
    raise exception 'Sync % recusado pelo porteiro: % linha(s) do lote com grupo diferente do grupo da planilha %. Nada foi gravado.', p_sync_id, v_fora, v_planilha
      using errcode = '22023';
  end if;

  -- [monitora] edital com a avaliação no MONITORA e linha publicada pela ficha: a planilha
  -- não grava nem muda (20261009200000). O cursor anda mesmo assim.
  delete from tmp_lote s
   where public."FC_EDITAL_ANALISE_NO_MONITORA"(v_planilha, public.jsonb_text_or_null(s.payload,'edital'))
      or exists (select 1 from public."TB_ANALISE_CURRICULAR" a
                  where a."TP_ORIGEM_REGISTRO" = 'MONITORA'
                    and a.chave_natural=public.analises_make_chave_natural(
                      public.jsonb_text_or_null(s.payload,'grupo'),
                      coalesce(public.jsonb_text_or_null(s.payload,'unidade'),'Nao informada'),
                      coalesce(public.jsonb_text_or_null(s.payload,'edital'),'Sem edital'),
                      public.jsonb_text_or_null(s.payload,'codigo_vaga'),
                      public.jsonb_text_or_null(s.payload,'id'),
                      public.jsonb_text_or_null(s.payload,'candidato')));
  get diagnostics v_monitora=row_count;

  select count(*)::integer into v_conflitos
  from tmp_lote s
  join public."TB_ANALISE_CURRICULAR" a
    on a.chave_natural=public.analises_make_chave_natural(
        public.jsonb_text_or_null(s.payload,'grupo'),
        coalesce(public.jsonb_text_or_null(s.payload,'unidade'),'Nao informada'),
        coalesce(public.jsonb_text_or_null(s.payload,'edital'),'Sem edital'),
        public.jsonb_text_or_null(s.payload,'codigo_vaga'),
        public.jsonb_text_or_null(s.payload,'id'),
        public.jsonb_text_or_null(s.payload,'candidato'))
  where a."CO_PLANILHA" <> v_planilha;
  if v_conflitos > 0 then
    raise exception 'Sync % recusado: % analise(s) do lote ja pertencem a outra planilha (mesma chave_natural). Nada foi gravado.', p_sync_id, v_conflitos
      using errcode = '22023';
  end if;

  with dados as (
    select
      public.analises_make_chave_natural(
        public.jsonb_text_or_null(s.payload,'grupo'),
        coalesce(public.jsonb_text_or_null(s.payload,'unidade'),'Nao informada'),
        coalesce(public.jsonb_text_or_null(s.payload,'edital'),'Sem edital'),
        public.jsonb_text_or_null(s.payload,'codigo_vaga'),
        public.jsonb_text_or_null(s.payload,'id'),
        public.jsonb_text_or_null(s.payload,'candidato')) as chave_natural,
      public.jsonb_text_or_null(s.payload,'grupo') as grupo,
      coalesce(public.jsonb_text_or_null(s.payload,'unidade'),'Nao informada') as unidade,
      coalesce(public.jsonb_text_or_null(s.payload,'edital'),'Sem edital') as edital,
      public.jsonb_text_or_null(s.payload,'codigo_vaga') as codigo_vaga,
      public.jsonb_text_or_null(s.payload,'nome_vaga') as nome_vaga,
      public.jsonb_text_or_null(s.payload,'regime') as regime,
      public.jsonb_text_or_null(s.payload,'carga_horaria') as carga_horaria,
      public.jsonb_text_or_null(s.payload,'categoria') as categoria,
      public.jsonb_text_or_null(s.payload,'candidato') as candidato,
      public.jsonb_text_or_null(s.payload,'id') as id_origem,
      public.jsonb_date_or_null(s.payload,'data_nascimento') as data_nascimento,
      public.jsonb_int_or_null(s.payload,'idade') as idade,
      public.jsonb_num_or_null(s.payload,'nota_empregare') as nota_empregare,
      public.jsonb_text_or_null(s.payload,'modalidade_concorrencia') as modalidade_concorrencia,
      public.jsonb_num_or_null(s.payload,'nota_final_ajustada') as nota_final_ajustada,
      public.jsonb_num_or_null(s.payload,'somatorio') as somatorio,
      public.jsonb_num_or_null(s.payload,'pontuacao_escolaridade') as pontuacao_escolaridade,
      public.jsonb_num_or_null(s.payload,'pontuacao_cursos_aperfeicoamento') as pontuacao_cursos_aperfeicoamento,
      public.jsonb_num_or_null(s.payload,'pontuacao_experiencia_profissional') as pontuacao_experiencia_profissional,
      public.jsonb_num_or_null(s.payload,'pontuacao_criterio_etnico') as pontuacao_criterio_etnico,
      public.jsonb_num_or_null(s.payload,'experiencia_saude_indigena_total') as experiencia_saude_indigena_total,
      public.jsonb_num_or_null(s.payload,'experiencia_atencao_basica_total') as experiencia_atencao_basica_total,
      public.jsonb_int_or_null(s.payload,'experiencia_profissional_anos') as experiencia_profissional_anos,
      public.jsonb_int_or_null(s.payload,'experiencia_profissional_meses') as experiencia_profissional_meses,
      public.jsonb_int_or_null(s.payload,'experiencia_profissional_dias') as experiencia_profissional_dias,
      public.jsonb_num_or_null(s.payload,'experiencia_profissional_total') as experiencia_profissional_total,
      public.jsonb_text_or_null(s.payload,'etapa') as etapa,
      public.jsonb_date_or_null(s.payload,'data_analise') as data_analise,
      public.jsonb_text_or_null(s.payload,'analise') as analise,
      public.jsonb_text_or_null(s.payload,'pcd') as pcd,
      -- [responsavel] nome e sobrenome do cadastro (FC_NOME_DO_RESPONSAVEL, 20261016120000). Só na gravação:
      -- hash_registro segue o do payload original (a comparação incremental não muda).
      private."FC_NOME_DO_RESPONSAVEL"(public.jsonb_text_or_null(s.payload,'responsavel_analise'),
                                       public.jsonb_text_or_null(s.payload,'grupo')) as responsavel_analise,
      public.jsonb_text_or_null(s.payload,'coord_demandante') as coord_demandante,
      public.jsonb_text_or_null(s.payload,'email_demandante') as email_demandante,
      coalesce(public.jsonb_text_or_null(s.payload,'status_consolidado'),'Pendente') as status_consolidado,
      public.jsonb_text_or_null(s.payload,'origem_planilha') as origem_planilha,
      public.jsonb_text_or_null(s.payload,'origem_arquivo_id') as origem_arquivo_id,
      coalesce(public.jsonb_timestamptz_or_null(s.payload,'ultima_atualizacao'),now()) as ultima_atualizacao,
      public.jsonb_text_or_null(s.payload,'pdf_gerado') as pdf_gerado,
      public.jsonb_text_or_null(s.payload,'link_pdf') as link_pdf,
      public.jsonb_timestamptz_or_null(s.payload,'data_geracao_pdf') as data_geracao_pdf,
      public.jsonb_text_or_null(s.payload,'erro_pdf') as erro_pdf,
      public.jsonb_text_or_null(s.payload,'pdf_status') as pdf_status,
      public.jsonb_text_or_null(s.payload,'pdf_file_id') as pdf_file_id,
      public.jsonb_timestamptz_or_null(s.payload,'pdf_ultima_tentativa') as pdf_ultima_tentativa,
      public.jsonb_text_or_null(s.payload,'pdf_hash_origem') as pdf_hash_origem,
      s.linha_origem,
      s.hash_registro
    from tmp_lote s
  )
  insert into public."TB_ANALISE_CURRICULAR"(
    chave_natural,grupo,unidade,edital,codigo_vaga,nome_vaga,regime,carga_horaria,categoria,candidato,
    id_origem,data_nascimento,idade,nota_empregare,modalidade_concorrencia,nota_final_ajustada,somatorio,
    pontuacao_escolaridade,pontuacao_cursos_aperfeicoamento,pontuacao_experiencia_profissional,
    pontuacao_criterio_etnico,experiencia_saude_indigena_total,experiencia_atencao_basica_total,
    experiencia_profissional_anos,experiencia_profissional_meses,experiencia_profissional_dias,experiencia_profissional_total,
    etapa,data_analise,analise,pcd,responsavel_analise,coord_demandante,email_demandante,status_consolidado,
    origem_planilha,origem_arquivo_id,ultima_atualizacao,pdf_gerado,link_pdf,data_geracao_pdf,erro_pdf,pdf_status,
    pdf_file_id,pdf_ultima_tentativa,pdf_hash_origem,linha_origem,hash_registro,ativo,updated_at,"CO_PLANILHA")
  select
    d.chave_natural,d.grupo,d.unidade,d.edital,d.codigo_vaga,d.nome_vaga,d.regime,d.carga_horaria,d.categoria,d.candidato,
    d.id_origem,d.data_nascimento,d.idade,d.nota_empregare,d.modalidade_concorrencia,d.nota_final_ajustada,d.somatorio,
    d.pontuacao_escolaridade,d.pontuacao_cursos_aperfeicoamento,d.pontuacao_experiencia_profissional,
    d.pontuacao_criterio_etnico,d.experiencia_saude_indigena_total,d.experiencia_atencao_basica_total,
    d.experiencia_profissional_anos,d.experiencia_profissional_meses,d.experiencia_profissional_dias,d.experiencia_profissional_total,
    d.etapa,d.data_analise,d.analise,d.pcd,d.responsavel_analise,d.coord_demandante,d.email_demandante,d.status_consolidado,
    d.origem_planilha,d.origem_arquivo_id,d.ultima_atualizacao,
    coalesce(d.pdf_gerado,a.pdf_gerado),coalesce(d.link_pdf,a.link_pdf),coalesce(d.data_geracao_pdf,a.data_geracao_pdf),
    coalesce(d.erro_pdf,a.erro_pdf),coalesce(d.pdf_status,a.pdf_status),coalesce(d.pdf_file_id,a.pdf_file_id),
    coalesce(d.pdf_ultima_tentativa,a.pdf_ultima_tentativa),coalesce(d.pdf_hash_origem,a.pdf_hash_origem),
    d.linha_origem,d.hash_registro,true,now(),v_planilha
  from dados d
  left join public."TB_ANALISE_CURRICULAR" a on a.chave_natural=d.chave_natural
  on conflict (chave_natural) do update set
    grupo=excluded.grupo,unidade=excluded.unidade,edital=excluded.edital,codigo_vaga=excluded.codigo_vaga,
    nome_vaga=excluded.nome_vaga,regime=excluded.regime,carga_horaria=excluded.carga_horaria,categoria=excluded.categoria,
    candidato=excluded.candidato,id_origem=excluded.id_origem,data_nascimento=excluded.data_nascimento,idade=excluded.idade,
    nota_empregare=excluded.nota_empregare,modalidade_concorrencia=excluded.modalidade_concorrencia,
    nota_final_ajustada=excluded.nota_final_ajustada,somatorio=excluded.somatorio,pontuacao_escolaridade=excluded.pontuacao_escolaridade,
    pontuacao_cursos_aperfeicoamento=excluded.pontuacao_cursos_aperfeicoamento,
    pontuacao_experiencia_profissional=excluded.pontuacao_experiencia_profissional,
    pontuacao_criterio_etnico=excluded.pontuacao_criterio_etnico,experiencia_saude_indigena_total=excluded.experiencia_saude_indigena_total,
    experiencia_atencao_basica_total=excluded.experiencia_atencao_basica_total,
    experiencia_profissional_anos=excluded.experiencia_profissional_anos,experiencia_profissional_meses=excluded.experiencia_profissional_meses,
    experiencia_profissional_dias=excluded.experiencia_profissional_dias,experiencia_profissional_total=excluded.experiencia_profissional_total,
    etapa=excluded.etapa,data_analise=excluded.data_analise,
    analise=excluded.analise,pcd=excluded.pcd,responsavel_analise=excluded.responsavel_analise,
    coord_demandante=excluded.coord_demandante,email_demandante=excluded.email_demandante,status_consolidado=excluded.status_consolidado,
    origem_planilha=excluded.origem_planilha,origem_arquivo_id=excluded.origem_arquivo_id,ultima_atualizacao=excluded.ultima_atualizacao,
    pdf_gerado=excluded.pdf_gerado,link_pdf=excluded.link_pdf,data_geracao_pdf=excluded.data_geracao_pdf,erro_pdf=excluded.erro_pdf,
    pdf_status=excluded.pdf_status,pdf_file_id=excluded.pdf_file_id,pdf_ultima_tentativa=excluded.pdf_ultima_tentativa,
    pdf_hash_origem=excluded.pdf_hash_origem,linha_origem=excluded.linha_origem,hash_registro=excluded.hash_registro,ativo=true,updated_at=now()
  where "TB_ANALISE_CURRICULAR"."CO_PLANILHA"=excluded."CO_PLANILHA"
    -- [monitora] linha publicada pela ficha nunca é sobrescrita pela planilha.
    and "TB_ANALISE_CURRICULAR"."TP_ORIGEM_REGISTRO"='PLANILHA';

  get diagnostics v_alteradas=row_count;

  select coalesce(nullif(resultado->>'lote_lidas','')::integer,0)+v_lidas,
         coalesce(nullif(resultado->>'lote_alteradas','')::integer,0)+v_alteradas,
         coalesce(nullif(resultado->>'lote_ignoradas_monitora','')::integer,0)+v_monitora
    into v_lidas_total,v_alteradas_total,v_monitora_total
  from public."TL_SYNC_ANALISE"
  where sync_id=p_sync_id
  order by id desc limit 1;

  update public."TL_SYNC_ANALISE"
  set status='processando',
      resultado=coalesce(resultado,'{}'::jsonb)||jsonb_build_object(
        'modo_processamento','lotes','lote_cursor',v_novo_cursor,'lote_lidas',v_lidas_total,
        'lote_alteradas',v_alteradas_total,'ultimo_lote_lidas',v_lidas,'ultimo_lote_alteradas',v_alteradas,
        'lote_ignoradas_monitora',v_monitora_total,
        'ultimo_lote_em',now(),'planilha',v_planilha,'planilha_validada',true),
      updated_at=now()
  where sync_id=p_sync_id;

  return jsonb_build_object('ok',true,'sync_id',p_sync_id,'lidas',v_lidas,'alteradas',v_alteradas,
    'ignoradas_monitora',v_monitora,
    'lidas_total',v_lidas_total,'alteradas_total',v_alteradas_total,'cursor',v_novo_cursor,'concluido_fato',v_lidas<v_limite);
end;
$$;

--
-- Name: propor_ajuste_pontuacao(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propor_ajuste_pontuacao(p_recurso uuid, p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := (select auth.uid());
  v_r public."TB_RECURSO_CANDIDATO";
  v_lista text := upper(btrim(coalesce(p_dados ->> 'lista', '')));
  v_justificativa text := nullif(btrim(coalesce(p_dados ->> 'justificativa', '')), '');
  v_itens jsonb := p_dados -> 'itens';
  v_previa jsonb := p_dados -> 'previa';
  v_versao integer;
  v_id uuid;
  v_anterior public."TB_AJUSTE_PONTUACAO_RECURSO";
  v_mudados integer;
  v_sem_justificativa integer;
begin
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  perform private."FC_EXIGIR_RECURSO_ACESSIVEL"(p_recurso, 1);
  perform private."FC_EXIGIR_PARECER_RECURSO"();

  select * into v_r from public."TB_RECURSO_CANDIDATO"
   where "CO_RECURSO_CANDIDATO" = p_recurso and "ST_ATIVO" = 'S'
   for update;
  if v_r."ST_FORA_ANALISE" = 'S' or v_r."CO_ANALISE_CURRICULAR" is null then
    raise exception 'O candidato não está ligado à análise: não há nota para ajustar' using errcode = '22023';
  end if;
  if v_r."TP_SITUACAO" not in ('EM_ANALISE_JURIDICA', 'DEFERIDO', 'PARCIALMENTE_INDEFERIDO') then
    raise exception 'O ajuste da pontuação é do recurso em análise jurídica ou deferido' using errcode = '22023';
  end if;
  if v_lista not in ('PRELIMINAR', 'ENTREVISTA', 'FINAL') then
    raise exception 'Lista da prévia inválida' using errcode = '22023';
  end if;
  if v_previa is not null and (jsonb_typeof(v_previa) <> 'object' or pg_column_size(v_previa) > 100000) then
    raise exception 'Prévia inválida' using errcode = '22023';
  end if;
  if jsonb_typeof(v_itens) is distinct from 'array' or jsonb_array_length(v_itens) not between 1 and 40 then
    raise exception 'Informe de 1 a 40 componentes' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_itens) i
     where case
             when jsonb_typeof(i) <> 'object' then true
             when coalesce(i ->> 'codigo', '') !~ '^(ETNICO|FORMACAO|CURSOS|EXPERIENCIA|DOCUMENTAL|ENTREVISTA|ART|COMPETENCIA_([1-9]|1[0-9]|20))$' then true
             when jsonb_typeof(i -> 'novo') is distinct from 'number' then true
             when (i ->> 'novo')::numeric not between 0 and 1000 then true
             when coalesce(jsonb_typeof(i -> 'anterior'), 'null') not in ('number', 'null') then true
             when jsonb_typeof(i -> 'anterior') = 'number' then (i ->> 'anterior')::numeric not between 0 and 1000
             else false
           end
        or length(coalesce(case when jsonb_typeof(i) = 'object' then i ->> 'justificativa' end, '')) > 2000) then
    raise exception 'Componente inválido: código conhecido, valor novo de 0 a 1000 e justificativa até 2.000 caracteres' using errcode = '22023';
  end if;
  if (select count(distinct i ->> 'codigo') from jsonb_array_elements(v_itens) i) <> jsonb_array_length(v_itens) then
    raise exception 'Componente repetido' using errcode = '22023';
  end if;
  select count(*),
         count(*) filter (where length(btrim(coalesce(i ->> 'justificativa', ''))) < 10)
    into v_mudados, v_sem_justificativa
    from jsonb_array_elements(v_itens) i
   where case when jsonb_typeof(i -> 'anterior') = 'number'
              then (i ->> 'anterior')::numeric <> (i ->> 'novo')::numeric
              else true end;
  if v_mudados = 0 then
    raise exception 'Nenhum valor mudou' using errcode = '22023';
  end if;
  if v_justificativa is not null and length(v_justificativa) not between 10 and 4000 then
    raise exception 'Justificativa geral de 10 a 4.000 caracteres' using errcode = '22023';
  end if;
  if v_justificativa is null and v_sem_justificativa > 0 then
    raise exception 'Escreva a justificativa geral ou a de cada componente alterado (10 caracteres ou mais)' using errcode = '22023';
  end if;

  select coalesce(max(j."NU_VERSAO"), 0) + 1 into v_versao
    from public."TB_AJUSTE_PONTUACAO_RECURSO" j where j."CO_RECURSO_CANDIDATO" = p_recurso;

  -- A proposta em aberto é substituída pela nova versão.
  select * into v_anterior from public."TB_AJUSTE_PONTUACAO_RECURSO"
   where "CO_RECURSO_CANDIDATO" = p_recurso and "TP_SITUACAO" = 'PROPOSTO'
   for update;
  if v_anterior."CO_AJUSTE_PONTUACAO" is not null then
    update public."TB_AJUSTE_PONTUACAO_RECURSO" set
      "TP_SITUACAO" = 'CANCELADO', "DT_CANCELAMENTO" = now(), "CO_USUARIO_CANCELAMENTO" = v_uid,
      "DS_MOTIVO_CANCELAMENTO" = format('Substituído pela versão %s.', v_versao)
    where "CO_AJUSTE_PONTUACAO" = v_anterior."CO_AJUSTE_PONTUACAO";
    insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "DS_MOTIVO", "CO_USUARIO")
    values (p_recurso, 'ajuste', 'cancelar', 'PROPOSTO', 'CANCELADO',
            format('Versão %s. Substituído pela versão %s.', v_anterior."NU_VERSAO", v_versao), v_uid);
  end if;

  insert into public."TB_AJUSTE_PONTUACAO_RECURSO"
    ("CO_RECURSO_CANDIDATO", "CO_MONITORAMENTO", "CO_ANALISE_CURRICULAR", "NU_VERSAO", "TP_LISTA",
     "DS_JUSTIFICATIVA", "DS_PREVIA", "CO_USUARIO_PROPOSTA")
  values (p_recurso, v_r."CO_MONITORAMENTO", v_r."CO_ANALISE_CURRICULAR", v_versao, v_lista,
          v_justificativa, v_previa, v_uid)
  returning "CO_AJUSTE_PONTUACAO" into v_id;

  insert into public."TB_ITEM_AJUSTE_PONTUACAO"
    ("CO_AJUSTE_PONTUACAO", "CO_ITEM", "NU_ORDEM", "VL_ANTERIOR", "VL_NOVO", "DS_JUSTIFICATIVA")
  select v_id, i.valor ->> 'codigo', i.ordem,
         case when jsonb_typeof(i.valor -> 'anterior') = 'number' then (i.valor ->> 'anterior')::numeric end,
         (i.valor ->> 'novo')::numeric,
         nullif(btrim(coalesce(i.valor ->> 'justificativa', '')), '')
    from jsonb_array_elements(v_itens) with ordinality i(valor, ordem);

  insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "DS_MOTIVO", "CO_USUARIO")
  values (p_recurso, 'ajuste', 'propor', null, 'PROPOSTO',
          format('Versão %s.%s', v_versao, coalesce(' ' || v_justificativa, '')), v_uid);

  return public.obter_ajustes_pontuacao_recurso(p_recurso);
end;
$_$;

--
-- Name: FUNCTION propor_ajuste_pontuacao(p_recurso uuid, p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.propor_ajuste_pontuacao(p_recurso uuid, p_dados jsonb) IS 'Propõe o ajuste da pontuação de um recurso (nova versão PROPOSTO; a proposta em aberto vira CANCELADO "substituído"). p_dados: lista (PRELIMINAR, ENTREVISTA, FINAL), justificativa geral, itens [{codigo, anterior, novo, justificativa}] e a prévia do motor. Justificativa geral ou a de cada componente alterado. Só o parecer jurídico (42501), recurso ligado à análise, em análise jurídica ou deferido (22023). Histórico em TH_RECURSO_CANDIDATO (ajuste).';

--
-- Name: publicar_lista_classificacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publicar_lista_classificacao(p_lista uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_l public."TB_LISTA_CLASSIFICACAO";
begin
  select * into v_l from public."TB_LISTA_CLASSIFICACAO" where "CO_LISTA_CLASSIFICACAO" = p_lista for update;
  if v_l."CO_LISTA_CLASSIFICACAO" is null then
    raise exception 'Lista não encontrada' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(v_l."CO_MONITORAMENTO", 2);
  if v_l."ST_PUBLICADA" = 'S' then
    return private."FC_LISTA_CLASSIFICACAO_JSON"(p_lista);
  end if;
  if v_l."QT_PENDENCIA" > 0 then
    raise exception 'A lista tem empate pendente de sorteio ou decisão; resolva e gere de novo.' using errcode = '22023';
  end if;
  update public."TB_LISTA_CLASSIFICACAO"
     set "ST_PUBLICADA" = 'S', "DT_PUBLICACAO" = now(), "CO_USUARIO_PUBLICACAO" = (select auth.uid())
   where "CO_LISTA_CLASSIFICACAO" = p_lista;
  return private."FC_LISTA_CLASSIFICACAO_JSON"(p_lista);
end;
$$;

--
-- Name: FUNCTION publicar_lista_classificacao(p_lista uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.publicar_lista_classificacao(p_lista uuid) IS 'Marca uma lista gerada como publicada (quem e quando). Lista com empate pendente não publica (22023). Exige classificacao >= editor no edital da lista.';

--
-- Name: reabrir_ficha(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reabrir_ficha(p_ficha uuid, p_versao integer, p_motivo text, p_complemento text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_uid uuid := (select auth.uid());
  v_codigo text := upper(btrim(coalesce(p_motivo, '')));
  v_rotulo text := private."FC_MOTIVO_REABERTURA"(upper(btrim(coalesce(p_motivo, ''))));
  v_complemento text := nullif(regexp_replace(btrim(coalesce(p_complemento, '')), '\s+', ' ', 'g'), '');
begin
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha for update;
  if v_f."CO_FICHA_ANALISE" is null then
    raise exception 'Ficha não encontrada' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_COORD_FICHAS"(v_f."CO_MONITORAMENTO");
  if v_f."TP_SITUACAO" not in ('CONCLUIDA', 'REVISAR') then
    raise exception 'Só fichas concluídas ou em revisão podem ser reabertas.' using errcode = '22023';
  end if;
  if p_versao is distinct from v_f."NU_VERSAO" then
    raise exception 'Esta ficha mudou desde que você abriu; recarregue.' using errcode = 'PT409';
  end if;
  -- Motivo da lista (20261021110000). Texto livre aqui é a tela antiga: recarregar mostra a lista.
  if v_rotulo is null then
    raise exception 'Escolha o motivo da reabertura na lista. Se a lista não aparece, recarregue a página.' using errcode = '22023';
  end if;
  if length(coalesce(v_complemento, '')) > 500 then
    raise exception 'Complemento com até 500 caracteres.' using errcode = '22023';
  end if;
  if v_codigo = 'OUTRO' then
    if length(coalesce(v_complemento, '')) < 15 or not private."FC_MOTIVO_PARECE_TEXTO"(v_complemento, 3) then
      raise exception 'Em "Outro", descreva o motivo com pelo menos 15 caracteres e 3 palavras.' using errcode = '22023';
    end if;
  elsif v_complemento is not null and not private."FC_MOTIVO_PARECE_TEXTO"(v_complemento, 1) then
    raise exception 'O complemento precisa ser escrito com palavras (ou fique em branco).' using errcode = '22023';
  end if;
  update public."TB_FICHA_ANALISE" set
    "TP_SITUACAO" = case
      when coalesce("CO_USUARIO_RESPONSAVEL", "CO_USUARIO_CONCLUSAO") is null then 'PENDENTE'
      else 'EM_ANALISE'
    end,
    "CO_USUARIO_RESPONSAVEL" = coalesce("CO_USUARIO_RESPONSAVEL", "CO_USUARIO_CONCLUSAO"),
    "DT_ATRIBUICAO" = coalesce("DT_ATRIBUICAO", now()),
    "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
   where "CO_FICHA_ANALISE" = p_ficha;
  perform private."FC_HISTORICO_CONTEUDO_FICHA"(p_ficha, 'REABRIR', v_f."TP_SITUACAO",
    v_rotulo || coalesce(' — ' || v_complemento, ''), v_uid,
    jsonb_build_array(jsonb_build_object('campo', 'motivo_reabertura', 'rotulo', 'Motivo da reabertura',
      'de', null, 'para', v_codigo, 'complemento', v_complemento)), null);
  return json_build_object('versao', v_f."NU_VERSAO" + 1);
end;
$$;

--
-- Name: FUNCTION reabrir_ficha(p_ficha uuid, p_versao integer, p_motivo text, p_complemento text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reabrir_ficha(p_ficha uuid, p_versao integer, p_motivo text, p_complemento text) IS 'A coordenação do edital reabre uma ficha concluída ou em revisão (volta a Em análise com responsável; sem responsável, volta a Pendente), com a versão que a tela abriu (PT409). p_motivo: código da lista (FC_MOTIVO_REABERTURA; texto livre da tela antiga é recusado com 22023 pedindo recarregar); p_complemento: opcional, até 500, obrigatório em OUTRO (15+ caracteres, 3 palavras). Histórico REABRIR com o rótulo no DS_MOTIVO e o código no DS_ALTERACAO (20261021110000).';

--
-- Name: reabrir_fichas(uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reabrir_fichas(p_edital uuid, p_fichas jsonb, p_motivo text, p_complemento text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_item record;
  v_qt integer;
begin
  perform private."FC_EXIGIR_COORD_FICHAS"(p_edital);
  if jsonb_typeof(p_fichas) is distinct from 'array' or jsonb_array_length(p_fichas) not between 1 and 5000 then
    raise exception 'Escolha de 1 a 5.000 fichas.' using errcode = '22023';
  end if;
  begin
    select count(*) into v_qt
      from jsonb_to_recordset(p_fichas) x(ficha uuid, versao integer)
      left join public."TB_FICHA_ANALISE" f on f."CO_FICHA_ANALISE" = x.ficha and f."CO_MONITORAMENTO" = p_edital
     where f."CO_FICHA_ANALISE" is null or f."NU_VERSAO" is distinct from x.versao;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'Ficha com id ou versão inválida' using errcode = '22023';
  end;
  if v_qt > 0 then
    raise exception '% ficha(s) mudaram desde que você abriu a fila; atualize e confira.', v_qt using errcode = 'PT409';
  end if;
  -- A regra de cada ficha (situação, motivo da lista, complemento, histórico) é a de reabrir_ficha.
  for v_item in select x.ficha, x.versao from jsonb_to_recordset(p_fichas) x(ficha uuid, versao integer) order by x.ficha loop
    perform public.reabrir_ficha(v_item.ficha, v_item.versao, p_motivo, p_complemento);
  end loop;
  return json_build_object('reabertas', jsonb_array_length(p_fichas));
end;
$$;

--
-- Name: FUNCTION reabrir_fichas(p_edital uuid, p_fichas jsonb, p_motivo text, p_complemento text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reabrir_fichas(p_edital uuid, p_fichas jsonb, p_motivo text, p_complemento text) IS 'A coordenação do edital reabre várias fichas concluídas ou em revisão de uma vez ([{ficha, versao}], 1 a 5.000, do mesmo edital, com controle otimista PT409). Cada uma passa por reabrir_ficha (motivo da lista, complemento, histórico REABRIR); uma que falhe desfaz o lote. 20261110140000.';

--
-- Name: reativar_acesso_usuario(uuid, text, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reativar_acesso_usuario(p_perfil_usuario_id uuid, p_grupo text, p_coordenacao text, p_areas text[], p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_alvo public."TB_PERFIL_USUARIO";
  v_admin boolean;
  v_coordenacao text := nullif(btrim(coalesce(p_coordenacao, '')), '');
  v_areas text[];
  v_nivel_acessos text;
begin
  if not private.is_master() then
    raise exception 'Somente o administrador global reativa contas' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then
    raise exception 'Informe o motivo da reativação (3 a 500 caracteres)' using errcode = '22023';
  end if;
  select * into v_alvo from public."TB_PERFIL_USUARIO" where id = p_perfil_usuario_id for update;
  if v_alvo.id is null then raise exception 'Conta não encontrada' using errcode = '22023'; end if;
  if v_alvo.ativo then raise exception 'Esta conta já está ativa' using errcode = '22023'; end if;
  if not exists (select 1 from public."TB_GRUPO_ACESSO" g where g."CO_GRUPO_ACESSO" = p_grupo) then
    raise exception 'Grupo inválido: %', p_grupo using errcode = '22023';
  end if;
  v_admin := exists (select 1 from public."TB_GRUPO_ACESSO" g where g."CO_GRUPO_ACESSO" = p_grupo and g."ST_ADMIN_GLOBAL");

  if v_admin then
    v_coordenacao := null;
    v_areas := '{}';
  else
    if v_coordenacao is not null and not exists (
         select 1 from public."TB_COORDENACAO" c where c."CO_COORDENACAO" = v_coordenacao and c."ST_ATIVO") then
      raise exception 'Coordenação inválida ou desativada' using errcode = '22023';
    end if;
    select coalesce(array_agg(distinct a."CO_AREA"), '{}') into v_areas
      from public."TB_AREA" a where a."CO_AREA" = any (coalesce(p_areas, '{}'));
    if v_coordenacao is null and cardinality(v_areas) = 0 then
      raise exception 'Sem coordenação, escolha ao menos uma área' using errcode = '23514';
    end if;
    v_nivel_acessos := private."FC_NIVEL_EFETIVO"(v_alvo.id, p_grupo, 'acessos');
    if v_coordenacao is null
       and private."FC_RANK_NIVEL"(v_nivel_acessos) >= private."FC_RANK_NIVEL"('editor') then
      raise exception 'O grupo % gerencia acessos: escolha a coordenação da pessoa', p_grupo using errcode = '23514';
    end if;
  end if;

  update public."TB_PERFIL_USUARIO"
     set ativo = true, perfil = p_grupo, "CO_COORDENACAO" = v_coordenacao,
         p_ind = true, p_cores = true, p_paineis = true, p_config = v_admin, p_admin = v_admin,
         updated_at = now()
   where id = v_alvo.id;

  delete from public."RL_PERFIL_USUARIO_AREA" where "CO_PERFIL_USUARIO" = v_alvo.id;
  insert into public."RL_PERFIL_USUARIO_AREA" ("CO_PERFIL_USUARIO", "CO_AREA")
  select v_alvo.id, x from unnest(v_areas) x;

  insert into public."TH_PERMISSAO_RECURSO"(perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
  values (v_alvo.id, '#conta', 'desativada', 'ativa', (select auth.uid()), btrim(p_motivo));
  if v_alvo.perfil is distinct from p_grupo then
    insert into public."TH_PERMISSAO_RECURSO"(perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
    values (v_alvo.id, '#grupo', v_alvo.perfil, p_grupo, (select auth.uid()), btrim(p_motivo));
  end if;

  -- Pedido pendente da pessoa (reativação ou comum) fica resolvido junto.
  update public."TB_SOLICITACAO_ACESSO" s
     set status = 'aprovado', avaliado_por = (select auth.uid()), avaliado_em = now(),
         observacao_admin = coalesce(nullif(btrim(s.observacao_admin), ''), 'Conta reativada pela aba Desativadas: ' || btrim(p_motivo)),
         updated_at = now()
   where s.status = 'pendente'
     and ((v_alvo.user_id is not null and s.user_id = v_alvo.user_id) or lower(s.email) = lower(v_alvo.email));

  return jsonb_build_object('ok', true, 'perfil_usuario_id', v_alvo.id, 'email', v_alvo.email,
    'grupo', p_grupo, 'coordenacao', v_coordenacao, 'areas', to_jsonb(v_areas));
end;
$$;

--
-- Name: FUNCTION reativar_acesso_usuario(p_perfil_usuario_id uuid, p_grupo text, p_coordenacao text, p_areas text[], p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reativar_acesso_usuario(p_perfil_usuario_id uuid, p_grupo text, p_coordenacao text, p_areas text[], p_motivo text) IS 'Reativa uma conta desativada com grupo, coordenação e áreas escolhidos (regras da matriz de acessos) e grava o histórico. Só administrador global.';

--
-- Name: recusar_reinicio_fichas_do_edital(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recusar_reinicio_fichas_do_edital(p_pedido bigint, p_confirmacao text, p_motivo text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_usuario uuid := (select auth.uid());
  v_p public."TB_PEDIDO_REINICIO_FICHA";
  v_motivo text := nullif(btrim(regexp_replace(coalesce(p_motivo, ''), '\s+', ' ', 'g')), '');
begin
  if not private."FC_ADMIN_GLOBAL_ATIVO"(v_usuario) then
    raise exception 'Só o administrador global recusa o reinício das fichas do edital.' using errcode = '42501';
  end if;
  select * into v_p from public."TB_PEDIDO_REINICIO_FICHA" p where p."CO_PEDIDO_REINICIO" = p_pedido for update;
  if not found then
    raise exception 'Pedido de reinício não encontrado.' using errcode = '22023';
  end if;
  if v_p."TP_SITUACAO" <> 'PENDENTE' then
    raise exception 'Este pedido de reinício não está mais pendente (%).', lower(v_p."TP_SITUACAO") using errcode = '55000';
  end if;
  if v_p."CO_USUARIO_PEDIDO" = v_usuario then
    raise exception 'Você pediu este reinício: use Cancelar pedido.' using errcode = '42501';
  end if;
  if not private."FC_CONFIRMACAO_DO_EDITAL"(v_p."CO_MONITORAMENTO", p_confirmacao) then
    raise exception 'O número digitado não confere com o do edital.' using errcode = '22023';
  end if;
  if v_motivo is not null and (length(v_motivo) not between 10 and 1000 or not private."FC_MOTIVO_PARECE_TEXTO"(v_motivo, 2)) then
    raise exception 'O motivo da recusa, se informado, tem de 10 a 1.000 caracteres e pelo menos 2 palavras.' using errcode = '22023';
  end if;

  update public."TB_PEDIDO_REINICIO_FICHA" set
    "TP_SITUACAO" = 'RECUSADO', "CO_USUARIO_DECISAO" = v_usuario, "DT_DECISAO" = now(), "DS_MOTIVO_DECISAO" = v_motivo
   where "CO_PEDIDO_REINICIO" = p_pedido;
  insert into public."TH_PEDIDO_REINICIO_FICHA" ("CO_PEDIDO_REINICIO", "CO_MONITORAMENTO", "TP_EVENTO", "CO_USUARIO", "DS_MOTIVO")
  values (p_pedido, v_p."CO_MONITORAMENTO", 'RECUSAR', v_usuario, v_motivo);

  return private."FC_LER_REINICIO_FICHAS"(v_p."CO_MONITORAMENTO", v_usuario);
end;
$$;

--
-- Name: FUNCTION recusar_reinicio_fichas_do_edital(p_pedido bigint, p_confirmacao text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recusar_reinicio_fichas_do_edital(p_pedido bigint, p_confirmacao text, p_motivo text) IS 'Outro administrador global recusa o pedido de reinício (20261022210000): quem pediu cancela, não recusa (42501); número do edital digitado (22023); motivo opcional (10 a 1.000, 2 palavras). Marca RECUSADO e grava RECUSAR. Nada muda nas fichas.';

--
-- Name: recusar_solicitacao_acesso(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recusar_solicitacao_acesso(p_solicitacao_id uuid, p_motivo text, p_complemento text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gestor text := private."FC_EXIGIR_GESTOR_DE_ACESSOS"();
  v_req public."TB_SOLICITACAO_ACESSO";
  v_rotulo text := private."FC_MOTIVO_RECUSA_SOLICITACAO"(p_motivo);
  v_complemento text := nullif(btrim(regexp_replace(coalesce(p_complemento, ''), '\s+', ' ', 'g')), '');
  v_texto text;
begin
  if v_rotulo is null then
    raise exception 'Escolha o motivo da recusa na lista.' using errcode = '22023';
  end if;
  if p_motivo = 'OUTRO' then
    if length(coalesce(v_complemento, '')) not between 15 and 500
       or not private."FC_MOTIVO_PARECE_TEXTO"(v_complemento, 3) then
      raise exception 'Descreva o motivo: de 15 a 500 caracteres, com pelo menos 3 palavras.' using errcode = '22023';
    end if;
    v_texto := v_complemento;
  else
    if v_complemento is not null
       and (length(v_complemento) > 500 or not private."FC_MOTIVO_PARECE_TEXTO"(v_complemento, 1)) then
      raise exception 'O complemento precisa ser um texto de até 500 caracteres.' using errcode = '22023';
    end if;
    v_texto := v_rotulo || coalesce(' — ' || v_complemento, '');
  end if;

  select * into v_req from public."TB_SOLICITACAO_ACESSO" where id = p_solicitacao_id for update;
  if v_req.id is null then raise exception 'Solicitação de acesso não encontrada'; end if;
  if v_req.status <> 'pendente' then raise exception 'Solicitação já avaliada (status atual: %)', v_req.status; end if;
  if v_gestor = 'coordenador' and v_req."CO_COORDENACAO" is distinct from private."FC_COORDENACAO_USUARIO"() then
    raise exception 'Solicitação de outra coordenação' using errcode = '42501';
  end if;
  update public."TB_SOLICITACAO_ACESSO"
     set status = 'recusado', avaliado_por = (select auth.uid()), avaliado_em = now(),
         "CO_MOTIVO_RECUSA" = p_motivo, observacao_admin = v_texto, updated_at = now()
   where id = p_solicitacao_id;
  return jsonb_build_object('ok', true, 'solicitacao_id', v_req.id, 'email', v_req.email, 'status', 'recusado',
                            'motivo', p_motivo, 'observacao_admin', v_texto);
end;
$$;

--
-- Name: FUNCTION recusar_solicitacao_acesso(p_solicitacao_id uuid, p_motivo text, p_complemento text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recusar_solicitacao_acesso(p_solicitacao_id uuid, p_motivo text, p_complemento text) IS 'Recusa o pedido de acesso com motivo da lista fixa (OUTRO pede descrição); grava quem avaliou, quando e o texto legível que a pessoa vê. Admin global ou coordenador da coordenação pedida.';

--
-- Name: registrar_acesso_ficha(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_acesso_ficha(p_ficha uuid, p_tipo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
begin
  if p_tipo is null or p_tipo not in ('ABRIR_EMPREGARE', 'COPIAR_CODIGO') then
    raise exception 'Tipo de acesso inválido.' using errcode = '22023';
  end if;
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha;
  perform private."FC_EXIGIR_VER_FICHA"(v_f);
  insert into public."TL_ACESSO_FICHA_ANALISE" ("CO_FICHA_ANALISE", "TP_ACESSO", "CO_USUARIO")
  values (p_ficha, p_tipo, (select auth.uid()));
  return json_build_object('registrado', true);
end;
$$;

--
-- Name: FUNCTION registrar_acesso_ficha(p_ficha uuid, p_tipo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_acesso_ficha(p_ficha uuid, p_tipo text) IS 'Registra (LGPD, AM-7.2) que quem vê a ficha abriu o candidato na Empregare (ABRIR_EMPREGARE) ou copiou o código para a busca de lá (COPIAR_CODIGO).';

--
-- Name: registrar_anexo_candidato_aprovado(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_anexo_candidato_aprovado(p_candidato_id uuid, p_arquivo_nome text, p_arquivo_base64 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text := private.papel_recurso('aprovados');
  v_nome text := nullif(btrim(coalesce(p_arquivo_nome, '')), '');
  v_arquivo bytea;
  v_ativo boolean;
  v_total integer;
  v_id uuid;
begin
  perform private."FC_EXIGIR_AREA_EDITAL"((select l.edital_id from public."TB_CANDIDATO_APROVADO" c join public."TB_LISTA_APROVADO" l on l.id = c.lista_id where c.id = p_candidato_id));
  if not (private.pode_recurso('aprovados',2)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  -- Anexos: só o admin do módulo (mesma regra da tela, canManageCandidateAttachments).
  if not private.pode_recurso('aprovados', 3) then
    raise exception 'Perfil sem permissão para anexar documentos' using errcode = '42501';
  end if;
  if v_nome is null or nullif(p_arquivo_base64, '') is null then
    raise exception 'Informe o arquivo do anexo';
  end if;

  begin
    v_arquivo := decode(p_arquivo_base64, 'base64');
  exception when others then
    raise exception 'Arquivo do anexo ilegível';
  end;
  if octet_length(v_arquivo) > 2097152 then
    raise exception 'O anexo deve ter no máximo 2 MB';
  end if;
  if octet_length(v_arquivo) < 5
     or substring(v_arquivo from 1 for 5) <> '\x255044462d'::bytea then
    raise exception 'O anexo deve ser PDF';
  end if;

  -- Trava o candidato: dois envios ao mesmo tempo não passam juntos do limite.
  select l.ativo into v_ativo
    from public."TB_CANDIDATO_APROVADO" c
    join public."TB_LISTA_APROVADO" l on l.id = c.lista_id and l.vigente is true
   where c.id = p_candidato_id and c.removido_em is null
   for update of c;
  if not found then raise exception 'Candidato não encontrado'; end if;
  if not v_ativo then
    raise exception 'A lista está inativa e não permite alterar candidatos';
  end if;

  select count(*) into v_total
    from public."TB_ANEXO_CANDIDATO_APROVADO"
   where "CO_CANDIDATO" = p_candidato_id;
  if v_total >= 5 then
    raise exception 'O candidato já tem 5 anexos, o limite';
  end if;

  insert into public."TB_ANEXO_CANDIDATO_APROVADO"(
    "CO_CANDIDATO", "NO_ARQUIVO", "IM_ARQUIVO", "QT_TAMANHO_BYTES", "CO_USUARIO_INCLUSAO"
  ) values (
    p_candidato_id, v_nome, v_arquivo, octet_length(v_arquivo), (select auth.uid())
  )
  returning "CO_ANEXO" into v_id;

  return jsonb_build_object('ok', true, 'anexo_id', v_id, 'total', v_total + 1);
end;
$$;

--
-- Name: registrar_anexo_recurso(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_anexo_recurso(p_recurso_id uuid, p_tipo text, p_nome text, p_caminho text, p_resposta_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_area text;
  v_nome text := btrim(coalesce(p_nome, ''));
  v_caminho text := coalesce(p_caminho, '');
  v_tamanho bigint;
  v_mime text;
  v_dono text;
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  if p_tipo is null or p_tipo not in ('recurso_candidato', 'resposta', 'documento', 'outro') then
    raise exception 'Tipo de anexo inválido' using errcode = '22023';
  end if;
  if length(v_nome) not between 1 and 200 then
    raise exception 'O nome do arquivo deve ter de 1 a 200 caracteres' using errcode = '22023';
  end if;
  v_area := private."FC_EXIGIR_RECURSO_ACESSIVEL"(p_recurso_id, 2);
  if length(v_caminho) > 400
     or v_caminho not like v_area || '/' || p_recurso_id::text || '/%'
     or cardinality(storage.foldername(v_caminho)) <> 2
     or position('..' in v_caminho) > 0 then
    raise exception 'Caminho do anexo não pertence a este recurso' using errcode = '22023';
  end if;
  if p_resposta_id is not null and not exists (
    select 1 from public."TB_RESPOSTA_RECURSO" s
    where s."CO_RESPOSTA_RECURSO" = p_resposta_id and s."CO_RECURSO_CANDIDATO" = p_recurso_id
  ) then
    raise exception 'A resposta não é deste recurso' using errcode = '22023';
  end if;

  select (o.metadata->>'size')::bigint, o.metadata->>'mimetype', o.owner_id
    into v_tamanho, v_mime, v_dono
  from storage.objects o
  where o.bucket_id = 'recursos-anexos' and o.name = v_caminho;
  if not found then
    raise exception 'Arquivo não encontrado no Storage' using errcode = 'P0002';
  end if;
  if v_dono is distinct from v_uid::text then
    raise exception 'O arquivo foi enviado por outra pessoa' using errcode = '42501';
  end if;
  if coalesce(v_tamanho, 0) not between 1 and 20971520 then
    raise exception 'O anexo deve ter até 20 MB' using errcode = '22023';
  end if;
  if v_mime is null or v_mime not in (
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/msword',
    'image/jpeg',
    'image/png',
    'application/vnd.oasis.opendocument.text') then
    raise exception 'Tipo de arquivo não aceito (PDF, DOCX, DOC, JPG, PNG ou ODT)' using errcode = '22023';
  end if;

  insert into public."TB_ANEXO_RECURSO" (
    "CO_RECURSO_CANDIDATO", "CO_RESPOSTA_RECURSO", "TP_ANEXO", "NO_ARQUIVO", "DS_CAMINHO",
    "QT_BYTES", "DS_MIME", "CO_USUARIO_INCLUSAO"
  ) values (p_recurso_id, p_resposta_id, p_tipo, v_nome, v_caminho, v_tamanho, v_mime, v_uid)
  returning "CO_ANEXO_RECURSO" into v_id;
  insert into public."TH_ANEXO_RECURSO" ("CO_ANEXO_RECURSO", "TP_ACAO", "CO_USUARIO")
  values (v_id, 'inclusao', v_uid);
  insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_NOVO", "CO_USUARIO")
  values (p_recurso_id, 'anexo', 'inclusao', v_nome, v_uid);
  return json_build_object('id', v_id, 'bytes', v_tamanho, 'mime', v_mime);
end;
$$;

--
-- Name: FUNCTION registrar_anexo_recurso(p_recurso_id uuid, p_tipo text, p_nome text, p_caminho text, p_resposta_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_anexo_recurso(p_recurso_id uuid, p_tipo text, p_nome text, p_caminho text, p_resposta_id uuid) IS 'Registra o arquivo que a pessoa acabou de enviar ao bucket recursos-anexos: o caminho é <área>/<recurso>/<arquivo>, o objeto existe, é dela, tem até 20 MB e tipo aceito (lidos do Storage, não do navegador). Exige recursos >= editor, a área e a coordenação do edital.';

--
-- Name: registrar_carta_convocacao(uuid, integer, uuid[], text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_carta_convocacao(p_modelo uuid, p_versao integer, p_candidatos uuid[], p_agrupamento text, p_saida text, p_campos jsonb DEFAULT '{}'::jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_modelo public."TB_MODELO_CARTA_CONVOCACAO";
  v_campos jsonb := coalesce(p_campos, '{}'::jsonb);
  v_agrupamento text := upper(btrim(coalesce(p_agrupamento, '')));
  v_saida text := upper(btrim(coalesce(p_saida, '')));
  v_limite date;
  v_local text;
  v_documentos text;
  v_contato text;
  v_qt integer;
  v_carta uuid;
  v_autor record;
  v_emitida timestamptz;
begin
  if not private.pode_recurso('aprovados', 2) then
    raise exception 'Sem permissão para emitir a carta de convocação' using errcode = '42501';
  end if;
  if v_agrupamento not in ('UNICO', 'POR_CANDIDATO') then
    raise exception 'Agrupamento inválido.' using errcode = '22023';
  end if;
  if v_saida not in ('SEI', 'DOCX', 'PDF') then
    raise exception 'Saída inválida.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_campos) is distinct from 'object' then
    raise exception 'Campos da emissão inválidos.' using errcode = '22023';
  end if;
  begin
    v_limite := nullif(btrim(coalesce(v_campos ->> 'data_limite', '')), '')::date;
  exception when others then
    raise exception 'Data limite inválida.' using errcode = '22023';
  end;
  v_local := nullif(btrim(coalesce(v_campos ->> 'local', '')), '');
  v_documentos := nullif(btrim(coalesce(v_campos ->> 'documentos', '')), '');
  v_contato := nullif(btrim(coalesce(v_campos ->> 'contato', '')), '');
  if length(coalesce(v_local, '')) > 500 or length(coalesce(v_contato, '')) > 500
     or length(coalesce(v_documentos, '')) > 5000 then
    raise exception 'Local e contato vão até 500 caracteres; documentos, até 5.000.' using errcode = '22023';
  end if;

  select * into v_modelo from public."TB_MODELO_CARTA_CONVOCACAO" where "CO_MODELO_CARTA" = p_modelo;
  if v_modelo."CO_MODELO_CARTA" is null then
    raise exception 'Modelo não encontrado' using errcode = '22023';
  end if;
  if not v_modelo."ST_ATIVO" then
    raise exception 'Modelo inativo.' using errcode = '22023';
  end if;
  if not exists (select 1 from public."TH_MODELO_CARTA_CONVOCACAO" v
                  where v."CO_MODELO_CARTA" = p_modelo and v."NU_VERSAO" = p_versao) then
    raise exception 'Versão do modelo não encontrada' using errcode = '22023';
  end if;
  if not (v_modelo."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])) then
    raise exception 'Sem permissão para esta área' using errcode = '42501';
  end if;

  -- Os candidatos: na ordem pedida, sem repetir, de listas vigentes e ativas da área do modelo.
  create temporary table if not exists tmp_carta_candidato (
    candidato_id uuid, ordem integer, nome text, status text, edital uuid, vigente boolean, ativo boolean, area text
  ) on commit drop;
  truncate pg_temp.tmp_carta_candidato;
  insert into pg_temp.tmp_carta_candidato
  select x.id, x.ordem, c.nome, c.status, m.id, l.vigente, l.ativo, m."CO_AREA"
    from (select distinct on (u.id) u.id, u.ordem
            from unnest(coalesce(p_candidatos, '{}'::uuid[])) with ordinality u(id, ordem)
           where u.id is not null
           order by u.id, u.ordem) x
    left join public."TB_CANDIDATO_APROVADO" c on c.id = x.id and c.removido_em is null
    left join public."TB_LISTA_APROVADO" l on l.id = c.lista_id
    left join public."TB_MONITORAMENTO_INDIGENA" m on m.id::text = l.edital_id;
  select count(*) into v_qt from pg_temp.tmp_carta_candidato;
  if v_qt = 0 then
    raise exception 'Escolha ao menos um candidato.' using errcode = '22023';
  end if;
  if v_qt > 500 then
    raise exception 'No máximo 500 candidatos por carta.' using errcode = '22023';
  end if;
  if exists (select 1 from pg_temp.tmp_carta_candidato where nome is null) then
    raise exception 'Candidato não encontrado.' using errcode = '22023';
  end if;
  if exists (select 1 from pg_temp.tmp_carta_candidato where not vigente or not ativo) then
    raise exception 'Há candidato de lista inativa ou substituída.' using errcode = '22023';
  end if;
  if exists (select 1 from pg_temp.tmp_carta_candidato where area is distinct from v_modelo."CO_AREA") then
    raise exception 'Há candidato de outra área que a do modelo.' using errcode = '22023';
  end if;
  if v_modelo."CO_MONITORAMENTO" is not null
     and exists (select 1 from pg_temp.tmp_carta_candidato where edital is distinct from v_modelo."CO_MONITORAMENTO") then
    raise exception 'O modelo é de outro edital que o de algum candidato.' using errcode = '22023';
  end if;
  if exists (select 1 from pg_temp.tmp_carta_candidato t where not private."FC_PODE_VER_EDITAL"(t.edital)) then
    raise exception 'Sem permissão para editais desta área ou coordenação' using errcode = '42501';
  end if;

  select * into v_autor from private.autor_da_sessao();
  insert into public."TH_CARTA_CONVOCACAO" (
    "CO_MODELO_CARTA", "NU_VERSAO_MODELO", "CO_AREA", "TP_AGRUPAMENTO", "TP_SAIDA", "DT_LIMITE",
    "DS_LOCAL", "DS_DOCUMENTOS", "DS_CONTATO", "QT_CANDIDATO", "CO_USUARIO", "NO_USUARIO", "DS_EMAIL_USUARIO"
  ) values (
    p_modelo, p_versao, v_modelo."CO_AREA", v_agrupamento, v_saida, v_limite,
    v_local, v_documentos, v_contato, v_qt, (select auth.uid()), v_autor.nome, v_autor.email
  ) returning "CO_CARTA_CONVOCACAO", "DT_EMISSAO" into v_carta, v_emitida;

  insert into public."RL_CARTA_CANDIDATO" (
    "CO_CARTA_CONVOCACAO", "CO_CANDIDATO_APROVADO", "CO_MONITORAMENTO", "NU_ORDEM", "NO_CANDIDATO", "DS_STATUS_ANTERIOR"
  )
  select v_carta, t.candidato_id, t.edital, (row_number() over (order by t.ordem))::smallint, left(t.nome, 255), t.status
    from pg_temp.tmp_carta_candidato t;

  return json_build_object('carta_id', v_carta, 'emitida_em', v_emitida, 'candidatos', v_qt);
end;
$$;

--
-- Name: FUNCTION registrar_carta_convocacao(p_modelo uuid, p_versao integer, p_candidatos uuid[], p_agrupamento text, p_saida text, p_campos jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_carta_convocacao(p_modelo uuid, p_versao integer, p_candidatos uuid[], p_agrupamento text, p_saida text, p_campos jsonb) IS 'Registra a emissão da carta de convocação: modelo ativo e versão, candidatos (1 a 500, na ordem do documento; de listas vigentes e ativas da área do modelo e, se o modelo é de um edital, desse edital), agrupamento (UNICO ou POR_CANDIDATO), saída (SEI, DOCX ou PDF) e os valores de prazo, local, documentos e contato. Grava TH_CARTA_CONVOCACAO e RL_CARTA_CANDIDATO. Aprovados >= editor, a área e o recorte dos editais.';

--
-- Name: registrar_desempate_classificacao(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_desempate_classificacao(p_edital uuid, p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_area text := private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 2);
  v_tipo text := upper(coalesce(p_dados ->> 'tipo_lista', ''));
  v_vaga text := btrim(coalesce(p_dados ->> 'vaga', ''));
  v_metodo text := upper(coalesce(p_dados ->> 'metodo', ''));
  v_just text := nullif(btrim(coalesce(p_dados ->> 'justificativa', '')), '');
  v_refazer boolean := coalesce(p_dados ->> 'refazer', 'false') = 'true';
  v_numero text;
  v_ids text[];
  v_chave text;
  v_semente text;
  v_origem text;
  v_ordem jsonb;
  v_atual public."TB_DESEMPATE_CLASSIFICACAO";
  v_id uuid;
  v_uid uuid := (select auth.uid());
begin
  if v_tipo not in ('PRELIMINAR', 'FINAL') then
    raise exception 'Lista inválida (PRELIMINAR ou FINAL)' using errcode = '22023';
  end if;
  if v_metodo not in ('SORTEIO', 'MANUAL') then
    raise exception 'Método inválido (SORTEIO ou MANUAL)' using errcode = '22023';
  end if;
  if length(v_vaga) not between 1 and 60 then
    raise exception 'Vaga inválida' using errcode = '22023';
  end if;
  if jsonb_typeof(p_dados -> 'candidatos') is distinct from 'array' then
    raise exception 'Informe os candidatos empatados' using errcode = '22023';
  end if;
  select array_agg(x order by x collate "C") into v_ids
    from (select distinct jsonb_array_elements_text(p_dados -> 'candidatos') x) s;
  if coalesce(cardinality(v_ids), 0) not between 2 and 200 then
    raise exception 'O empate tem de 2 a 200 candidatos' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_ids) x where x !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
    raise exception 'Candidato inválido' using errcode = '22023';
  end if;

  -- Os empatados são análises deste edital, desta área e desta vaga.
  select private."FC_NUMERO_EDITAL"(m.edital) into v_numero from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  if (select count(*) from public."TB_ANALISE_CURRICULAR" a
       where a.id = any (v_ids::uuid[]) and a."CO_AREA" = v_area and a.ativo
         and a.codigo_vaga = v_vaga and private."FC_NUMERO_EDITAL"(a.edital) = v_numero) <> cardinality(v_ids) then
    raise exception 'Há candidato fora deste edital ou desta vaga' using errcode = '22023';
  end if;

  v_chave := v_tipo || '|' || v_vaga || '|' || array_to_string(v_ids, ',');
  if p_dados ? 'chave' and p_dados ->> 'chave' is distinct from v_chave then
    raise exception 'O grupo de empate mudou; recarregue.' using errcode = 'PT409';
  end if;

  select * into v_atual from public."TB_DESEMPATE_CLASSIFICACAO"
   where "CO_MONITORAMENTO" = p_edital and "TP_LISTA" = v_tipo and "DS_CHAVE_GRUPO" = v_chave and "ST_ATIVO" = 'S'
   for update;

  if v_metodo = 'SORTEIO' then
    if v_atual."CO_DESEMPATE_CLASSIFICACAO" is not null and v_atual."TP_METODO" = 'SORTEIO' then
      if not v_refazer then
        raise exception 'Já há sorteio registrado para este empate.' using errcode = '23505';
      end if;
      if v_just is null or length(v_just) not between 10 and 2000 then
        raise exception 'Para refazer o sorteio, justifique (10 a 2.000 caracteres).' using errcode = '22023';
      end if;
    end if;
    v_semente := nullif(btrim(coalesce(p_dados ->> 'semente', '')), '');
    if v_semente is null then
      v_semente := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
      v_origem := 'SERVIDOR';
    else
      if length(v_semente) not between 4 and 200 or v_semente ~ '[[:cntrl:]]' then
        raise exception 'Semente de 4 a 200 caracteres.' using errcode = '22023';
      end if;
      v_origem := 'INFORMADA';
    end if;
    select jsonb_agg(x order by encode(sha256(convert_to(v_semente || ':' || x, 'UTF8')), 'hex') collate "C")
      into v_ordem
      from unnest(v_ids) x;
  else
    if v_just is null or length(v_just) not between 10 and 2000 then
      raise exception 'A decisão manual exige justificativa (10 a 2.000 caracteres).' using errcode = '22023';
    end if;
    v_ordem := p_dados -> 'ordem';
    if jsonb_typeof(v_ordem) is distinct from 'array' or jsonb_array_length(v_ordem) <> cardinality(v_ids)
       or (select array_agg(x order by x collate "C") from jsonb_array_elements_text(v_ordem) x) is distinct from v_ids then
      raise exception 'A ordem tem de trazer cada empatado uma vez.' using errcode = '22023';
    end if;
  end if;

  if v_atual."CO_DESEMPATE_CLASSIFICACAO" is not null then
    update public."TB_DESEMPATE_CLASSIFICACAO"
       set "ST_ATIVO" = 'N', "DT_DESATIVACAO" = now(), "CO_USUARIO_DESATIVACAO" = v_uid
     where "CO_DESEMPATE_CLASSIFICACAO" = v_atual."CO_DESEMPATE_CLASSIFICACAO";
  end if;
  insert into public."TB_DESEMPATE_CLASSIFICACAO"
    ("CO_MONITORAMENTO", "TP_LISTA", "CO_VAGA", "DS_CHAVE_GRUPO", "TP_METODO", "DS_SEMENTE", "TP_ORIGEM_SEMENTE",
     "DS_ORDEM", "DS_JUSTIFICATIVA", "CO_USUARIO")
  values (p_edital, v_tipo, v_vaga, v_chave, v_metodo, v_semente, v_origem, v_ordem, v_just, v_uid)
  returning "CO_DESEMPATE_CLASSIFICACAO" into v_id;

  return private."FC_DESEMPATE_CLASSIFICACAO_JSON"(v_id);
end;
$_$;

--
-- Name: FUNCTION registrar_desempate_classificacao(p_edital uuid, p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_desempate_classificacao(p_edital uuid, p_dados jsonb) IS 'Registra o empate final de um grupo: SORTEIO (semente do servidor ou informada; ordem = sha256(semente || '':'' || id) crescente; refazer exige justificativa) ou MANUAL (ordem + justificativa). p_dados: {tipo_lista, vaga, chave, metodo, candidatos, semente?, ordem?, justificativa?, refazer?}. Exige classificacao >= editor, a área e o recorte da coordenação; os candidatos têm de ser da vaga e do edital.';

--
-- Name: registrar_desfecho_da_pendencia(uuid, text, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_desfecho_da_pendencia(p_pendencia uuid, p_status text, p_matricula text, p_data_convocacao date, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_PENDENCIA_APROVADO"%rowtype;
  v_atual public."TB_CANDIDATO_APROVADO"%rowtype;
  v_status text := nullif(btrim(coalesce(p_status, '')), '');
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  v := private."FC_PENDENCIA_PARA_DECIDIR"(p_pendencia, array['CONVOCADO_SEM_DESFECHO'], p_motivo);
  select * into v_atual from public."TB_CANDIDATO_APROVADO" c where c.id = v."CO_CANDIDATO_APROVADO"[1];
  if v_atual.status is distinct from 'Convocado' then
    raise exception 'As linhas desta pendência mudaram: atualize a tela' using errcode = '55000';
  end if;
  if v_status is null or v_status not in ('Contratado', 'Migração', 'Desistente', 'Documentação Rejeitada', 'Convocado') then
    raise exception 'Desfecho inválido' using errcode = '22023';
  end if;
  if v_status in ('Contratado', 'Migração') and nullif(btrim(coalesce(p_matricula, '')), '') is null then
    raise exception 'Matrícula obrigatória para Contratado ou Migração' using errcode = '22023';
  end if;
  if v_status = 'Convocado' and (p_data_convocacao is null or p_data_convocacao > v_hoje
                                  or p_data_convocacao = v_atual."DT_CONVOCACAO") then
    raise exception 'Informe a nova data da convocação (diferente da atual e não futura)' using errcode = '22023';
  end if;
  if v_status <> 'Convocado' and p_data_convocacao is not null then
    raise exception 'A data da convocação só vale para a nova convocação' using errcode = '22023';
  end if;
  return private."FC_FECHAR_PENDENCIA"(
    p_pendencia, case when v_status = 'Convocado' then 'NOVA_DATA' else 'DESFECHO_REGISTRADO' end, p_motivo,
    jsonb_build_array(private."FC_STATUS_PELA_PENDENCIA"(v_atual.id, v_status, p_matricula, p_data_convocacao)));
end;
$$;

--
-- Name: FUNCTION registrar_desfecho_da_pendencia(p_pendencia uuid, p_status text, p_matricula text, p_data_convocacao date, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_desfecho_da_pendencia(p_pendencia uuid, p_status text, p_matricula text, p_data_convocacao date, p_motivo text) IS 'Pendência "Convocado sem desfecho": registra o desfecho (Contratado ou Migração com matrícula, Desistente, Documentação Rejeitada) ou a nova data da convocação (não futura). Quem decide (FC_PODE_DECIDIR_PENDENCIA), com motivo; histórico do status e da pendência, contratados e avisos. 20261026190000.';

--
-- Name: registrar_disparo_externo(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_disparo_externo(p_workflow text, p_ator text, p_url text, p_resumo text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_ator text := nullif(btrim(coalesce(p_ator, '')), '');
  v_resumo text := nullif(left(btrim(coalesce(p_resumo, '')), 300), '');
  v_disparo bigint;
begin
  if p_workflow is null or not exists (
       select 1 from public."TB_ROBO_WORKFLOW" w
        where w."NO_WORKFLOW" = p_workflow and w."ST_REGISTRO_EXTERNO" = 'S') then
    raise exception 'Workflow fora da lista fixa dos robôs' using errcode = '22023';
  end if;
  if p_url is null or length(p_url) > 300
     or p_url !~ '^https://github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+/actions/runs/[0-9]+$' then
    raise exception 'Endereço da execução inválido' using errcode = '22023';
  end if;
  -- Login do GitHub (letras, dígitos, hífen; robôs com [bot]); fora disso, sem ator.
  if v_ator is not null and v_ator !~ '^[A-Za-z0-9][A-Za-z0-9-]{0,38}(\[bot\])?$' then
    v_ator := null;
  end if;

  insert into public."TL_DISPARO_ROBO"
         ("NO_WORKFLOW", "TP_ORIGEM", "CO_USUARIO", "TP_SITUACAO", "NO_ATOR_GITHUB", "DS_URL_EXECUCAO", "DS_MENSAGEM")
  values (p_workflow, 'GITHUB', null, 'INICIADO', v_ator, p_url, v_resumo)
  on conflict ("DS_URL_EXECUCAO") where "TP_ORIGEM" = 'GITHUB' do nothing
  returning "CO_DISPARO" into v_disparo;
  if v_disparo is null then
    select d."CO_DISPARO" into v_disparo
      from public."TL_DISPARO_ROBO" d
     where d."TP_ORIGEM" = 'GITHUB' and d."DS_URL_EXECUCAO" = p_url;
  end if;
  return v_disparo;
end;
$_$;

--
-- Name: FUNCTION registrar_disparo_externo(p_workflow text, p_ator text, p_url text, p_resumo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_disparo_externo(p_workflow text, p_ator text, p_url text, p_resumo text) IS 'Workflows do GitHub Actions (service_role, 20261020170000): a execução iniciada direto no GitHub (Run workflow) se registra em TL_DISPARO_ROBO com origem GITHUB, o ator e o link; repetir não duplica. Só workflows do catálogo com ST_REGISTRO_EXTERNO = S (20261109180000; antes, lista fixa). 22023 para workflow fora do catálogo ou link inválido.';

--
-- Name: registrar_divergencia_do_calculo(uuid, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_divergencia_do_calculo(p_pedido uuid, p_total integer, p_caminhos text[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v public."TB_PEDIDO_CALCULO_CLASSIFICACAO";
  v_caminhos text[] := coalesce(p_caminhos, '{}');
begin
  select * into v from public."TB_PEDIDO_CALCULO_CLASSIFICACAO" p where p."CO_PEDIDO_CALCULO" = p_pedido for update;
  if v."CO_PEDIDO_CALCULO" is null then
    raise exception 'Pedido de cálculo não encontrado' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(v."CO_MONITORAMENTO", 2);
  if v."TP_SITUACAO" not in ('PRONTO', 'NAO_CONFERE') then
    raise exception 'Este cálculo não está pronto (%).', lower(v."TP_SITUACAO") using errcode = '55000';
  end if;
  if p_total is null or p_total not between 1 and 1000000 or cardinality(v_caminhos) > 20
     or exists (select 1 from unnest(v_caminhos) c
                 where c is null or c !~ '^[A-Za-z0-9_.\[\]-]{1,200}$' or c ~ '[0-9]{11}') then
    raise exception 'Divergência inválida (total de 1 a 1.000.000, até 20 caminhos sem valores)' using errcode = '22023';
  end if;
  update public."TB_PEDIDO_CALCULO_CLASSIFICACAO"
     set "TP_SITUACAO" = 'NAO_CONFERE',
         "DS_MENSAGEM" = 'O cálculo do Python não confere com o da tela (' || p_total || ' diferença(s)); a lista não foi registrada.',
         "DS_DIVERGENCIA" = jsonb_build_object('origem', 'TELA', 'total', p_total, 'caminhos', to_jsonb(v_caminhos)),
         "DT_ATUALIZACAO" = now()
   where "CO_PEDIDO_CALCULO" = p_pedido;
  return json_build_object('pedido', p_pedido, 'situacao', 'NAO_CONFERE');
end;
$_$;

--
-- Name: FUNCTION registrar_divergencia_do_calculo(p_pedido uuid, p_total integer, p_caminhos text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_divergencia_do_calculo(p_pedido uuid, p_total integer, p_caminhos text[]) IS 'A tela grava que o retrato do Python não confere com o do motor.ts (20261023200000): o pedido PRONTO vira NAO_CONFERE com o total e até 20 caminhos das diferenças (só letras, dígitos, _ . [ ] -; sem valores nem 11 dígitos seguidos). O retrato fica para a análise. Classificação editor do edital.';

--
-- Name: registrar_download_anexo_recurso(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_download_anexo_recurso(p_anexo_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_anexo public."TB_ANEXO_RECURSO";
begin
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  select x.* into v_anexo from public."TB_ANEXO_RECURSO" x where x."CO_ANEXO_RECURSO" = p_anexo_id;
  if not found then
    raise exception 'Anexo não encontrado' using errcode = 'P0002';
  end if;
  -- Arquivado continua baixável, mas só por quem edita.
  perform private."FC_EXIGIR_RECURSO_ACESSIVEL"(v_anexo."CO_RECURSO_CANDIDATO", case when v_anexo."ST_ATIVO" = 'S' then 1 else 2 end);
  insert into public."TH_ANEXO_RECURSO" ("CO_ANEXO_RECURSO", "TP_ACAO", "CO_USUARIO")
  values (p_anexo_id, 'download', v_uid);
  return json_build_object(
    'bucket', 'recursos-anexos',
    'caminho', v_anexo."DS_CAMINHO",
    'nome', v_anexo."NO_ARQUIVO",
    'mime', v_anexo."DS_MIME",
    'validade_segundos', 60
  );
end;
$$;

--
-- Name: FUNCTION registrar_download_anexo_recurso(p_anexo_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_download_anexo_recurso(p_anexo_id uuid) IS 'Confere o acesso (leitor; anexo arquivado, editor), registra o download no histórico do anexo e devolve o caminho. A política de leitura do bucket só libera a URL assinada (60 s) a quem tem este registro nos últimos 5 minutos.';

--
-- Name: registrar_evento_acesso(text, text, text, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_evento_acesso(p_evento text, p_tela text DEFAULT NULL::text, p_origem text DEFAULT NULL::text, p_detalhes jsonb DEFAULT '{}'::jsonb, p_client_session_id text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'auth'
    SET statement_timeout TO '1500ms'
    AS $$
declare
  v_id bigint;
  v_evento text;
begin
  v_evento := nullif(btrim(p_evento), '');

  if v_evento is null then
    raise exception 'Evento de acesso nao informado';
  end if;

  v_id := nextval('public.eventos_acesso_id_seq'::regclass);

  insert into public."TL_EVENTO_ACESSO"(
    id,
    user_id,
    evento,
    tela,
    origem,
    detalhes,
    client_session_id,
    user_agent,
    app_version
  )
  values (
    v_id,
    auth.uid(),
    left(v_evento, 200),
    nullif(btrim(p_tela), ''),
    nullif(btrim(p_origem), ''),
    coalesce(p_detalhes, '{}'::jsonb),
    nullif(btrim(p_client_session_id), ''),
    nullif(btrim(p_user_agent), ''),
    nullif(btrim(p_app_version), '')
  );

  return v_id;
end;
$$;

--
-- Name: FUNCTION registrar_evento_acesso(p_evento text, p_tela text, p_origem text, p_detalhes jsonb, p_client_session_id text, p_user_agent text, p_app_version text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_evento_acesso(p_evento text, p_tela text, p_origem text, p_detalhes jsonb, p_client_session_id text, p_user_agent text, p_app_version text) IS 'Registra eventos de acesso via RLS. Usuario autenticado grava user_id; chamada anonima grava user_id null para eventos pre-auth.';

--
-- Name: registrar_lista_calculada(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_lista_calculada(p_pedido uuid, p_resultado jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_PEDIDO_CALCULO_CLASSIFICACAO";
  v_lista uuid;
begin
  select * into v from public."TB_PEDIDO_CALCULO_CLASSIFICACAO" p where p."CO_PEDIDO_CALCULO" = p_pedido for update;
  if v."CO_PEDIDO_CALCULO" is null then
    raise exception 'Pedido de cálculo não encontrado' using errcode = '22023';
  end if;
  perform private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(v."CO_MONITORAMENTO", 2);
  if v."TP_SITUACAO" <> 'PRONTO' then
    raise exception 'Este cálculo não está pronto para registrar (%); gere de novo.', lower(v."TP_SITUACAO")
      using errcode = '55000';
  end if;

  -- O banco confere de novo: o retrato da tela tem de ser o do Python (jsonb a jsonb).
  if p_resultado is null or not (p_resultado = v."DS_RETRATO") then
    update public."TB_PEDIDO_CALCULO_CLASSIFICACAO"
       set "TP_SITUACAO" = 'NAO_CONFERE',
           "DS_MENSAGEM" = 'O retrato da tela não é o do Python; a lista não foi registrada.',
           "DS_DIVERGENCIA" = jsonb_build_object('origem', 'BANCO'),
           "DT_ATUALIZACAO" = now()
     where "CO_PEDIDO_CALCULO" = p_pedido;
    return json_build_object('nao_confere', true, 'pedido', p_pedido);
  end if;

  -- Registra o retrato do Python (o mesmo hash que ele recebeu no cálculo).
  v_lista := private."FC_REGISTRAR_LISTA_CLASSIFICACAO"(v."CO_MONITORAMENTO", v."TP_LISTA", v."NU_VERSAO_REGRA", v."DS_RETRATO");
  update public."TB_PEDIDO_CALCULO_CLASSIFICACAO"
     set "TP_SITUACAO" = 'REGISTRADO', "CO_LISTA_CLASSIFICACAO" = v_lista, "DS_RETRATO" = null,
         "DS_MENSAGEM" = null, "DT_ATUALIZACAO" = now()
   where "CO_PEDIDO_CALCULO" = p_pedido;
  return private."FC_LISTA_CLASSIFICACAO_JSON"(v_lista);
end;
$$;

--
-- Name: FUNCTION registrar_lista_calculada(p_pedido uuid, p_resultado jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_lista_calculada(p_pedido uuid, p_resultado jsonb) IS 'Registra a lista calculada pelo Python (20261023200000): só o pedido PRONTO (senão 55000) e só quando o retrato que a tela calculou com o motor.ts (p_resultado) é igual, jsonb a jsonb, ao do Python; então registra o retrato do Python (FC_REGISTRAR_LISTA_CLASSIFICACAO: versão da regra, candidatos, hash, relatório de desempate), marca REGISTRADO e devolve a lista como registrar_lista_classificacao. Diferente: marca NAO_CONFERE (origem BANCO), não registra e devolve {nao_confere: true}. Classificação editor do edital.';

--
-- Name: registrar_lista_classificacao(uuid, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_lista_classificacao(p_edital uuid, p_tipo text, p_versao integer, p_resultado jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 2);
  v_id uuid;
begin
  -- Chave "Gerar listas pelo Python" ligada (20261023200000): a lista vem do cálculo do Python.
  if private."FC_CALCULO_PELO_PYTHON"() then
    raise exception 'A lista agora é calculada pelo Python: recarregue a página e gere de novo.' using errcode = '55000';
  end if;
  -- Dois comandos: a leitura (STABLE) tem de ver a lista que o registro acabou de gravar.
  v_id := private."FC_REGISTRAR_LISTA_CLASSIFICACAO"(p_edital, p_tipo, p_versao, p_resultado);
  return private."FC_LISTA_CLASSIFICACAO_JSON"(v_id);
end;
$$;

--
-- Name: FUNCTION registrar_lista_classificacao(p_edital uuid, p_tipo text, p_versao integer, p_resultado jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_lista_classificacao(p_edital uuid, p_tipo text, p_versao integer, p_resultado jsonb) IS '"Gerar" da Classificação com o cálculo da tela (motor.ts): registra o retrato (FC_REGISTRAR_LISTA_CLASSIFICACAO: versão da regra, forma, candidatos, hash SHA-256 do banco) e pede o relatório de desempate. Com a chave "Gerar listas pelo Python" ligada (20261023200000), recusa (55000): a lista vem de registrar_lista_calculada. Classificação editor.';

--
-- Name: registrar_lista_pre_classificacao(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_lista_pre_classificacao(p_edital uuid, p_tipo text, p_lote integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text;
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_regra public."TB_REGRA_CLASSIFICACAO";
  v_resultado jsonb;
  v_id uuid;
  v_elegiveis integer;
  v_eliminados integer;
begin
  if private."FC_PAPEL_AVALIACAO"(p_edital) = 'COORDENADOR' then
    v_area := private."FC_EXIGIR_AVALIACAO_EDITAL"(p_edital, 3);
  else
    v_area := private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 2);
  end if;
  if p_tipo is null or p_tipo not in ('PROVISORIA', 'LOTE') then
    raise exception 'Tipo de lista inválido: PROVISORIA ou LOTE' using errcode = '22023';
  end if;
  if p_lote is not null and (p_tipo <> 'LOTE' or p_lote not between 1 and 999) then
    raise exception 'Número do lote só na lista LOTE, de 1 a 999' using errcode = '22023';
  end if;
  select * into v_regra from public."TB_REGRA_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital;
  if v_regra."CO_REGRA_CLASSIFICACAO" is null then
    raise exception 'Cadastre a regra de classificação do edital antes de registrar a lista.' using errcode = '22023';
  end if;
  if not exists (select 1 from public."TB_PRE_CLASSIFICACAO" a where a."CO_MONITORAMENTO" = p_edital) then
    raise exception 'O edital ainda não tem pré-classificação: rode o Recalcular.' using errcode = '22023';
  end if;
  if p_lote is not null and not exists (select 1 from public."TB_PRE_CLASSIFICACAO" a
                                         where a."CO_MONITORAMENTO" = p_edital and a."NU_LOTE" = p_lote) then
    raise exception 'Não há ninguém no lote %.', p_lote using errcode = '22023';
  end if;
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital;

  -- O retrato (formato de src/lib/classificacao/exportacao.js): só nome, posição, nota e motivo.
  select jsonb_build_object(
           'schema', 1,
           'tipo', p_tipo,
           'edital', jsonb_build_object('id', v_m.id, 'edital', v_m.edital, 'unidade', v_m.unidade),
           'regra_versao', v_regra."NU_VERSAO_VIGENTE",
           'regra_analise_versao', (select max(a."NU_VERSAO_REGRA") from public."TB_PRE_CLASSIFICACAO" a where a."CO_MONITORAMENTO" = p_edital),
           'lote', p_lote,
           'casas', 1,
           'modalidades', '[]'::jsonb,
           'vagas', coalesce(jsonb_agg(jsonb_build_object(
             'chave', pv."CO_VAGA",
             'codigo', pv."CO_VAGA",
             'cargo', pv."NO_CARGO",
             'lotacao', pv."NO_LOTACAO",
             'cabecalho', concat_ws(' - ', 'VAGA ' || pv."CO_VAGA", pv."NO_CARGO", pv."NO_LOTACAO",
                            case when coalesce(pv."QT_VAGA_IMEDIATA", 0) = 0 and pv."ST_CADASTRO_RESERVA" = 'S' then 'Cadastro reserva'
                                 when pv."QT_VAGA_IMEDIATA" is null then null
                                 else pv."QT_VAGA_IMEDIATA" || case when pv."QT_VAGA_IMEDIATA" = 1 then ' vaga' else ' vagas' end
                                      || case when pv."ST_CADASTRO_RESERVA" = 'S' then ' + CR' else '' end end),
             'total', pv."QT_VAGA_IMEDIATA",
             'cadastro_reserva', pv."ST_CADASTRO_RESERVA" = 'S',
             'geral', coalesce((
               select jsonb_agg(jsonb_build_object('posicao', a."NU_POSICAO", 'nome', c."NO_CANDIDATO",
                                                   'nota', a."VL_NOTA_ORDEM", 'modalidades', jsonb_build_array(a."NO_MODALIDADE"),
                                                   'situacao', a."TP_SITUACAO", 'lote', a."NU_LOTE",
                                                   -- Quem entrou no lote por decisão da coordenação: o motivo (nota no documento).
                                                   'decisao', case when a."TP_ENTRADA_LOTE" = 'DECISAO' then a."DS_MOTIVO_ENTRADA" end)
                                order by a."NU_POSICAO")
                 from public."TB_PRE_CLASSIFICACAO" a
                 join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = a."CO_EMPREGARE_CANDIDATO"
                where a."CO_MONITORAMENTO" = p_edital and a."CO_VAGA" = pv."CO_VAGA"
                  and case when p_tipo = 'PROVISORIA' then a."TP_SITUACAO" <> 'ELIMINADO'
                           else a."TP_SITUACAO" in ('NO_LOTE', 'ANALISADO') and (p_lote is null or a."NU_LOTE" = p_lote) end), '[]'::jsonb),
             'listas', '{}'::jsonb,
             'eliminados', case when p_tipo = 'PROVISORIA' then coalesce((
               select jsonb_agg(jsonb_build_object('nome', c."NO_CANDIDATO", 'motivo', a."DS_MOTIVO_ELIMINACAO", 'detalhe', '')
                                order by c."NO_CANDIDATO")
                 from public."TB_PRE_CLASSIFICACAO" a
                 join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = a."CO_EMPREGARE_CANDIDATO"
                where a."CO_MONITORAMENTO" = p_edital and a."CO_VAGA" = pv."CO_VAGA" and a."TP_SITUACAO" = 'ELIMINADO'), '[]'::jsonb)
               else '[]'::jsonb end)
             order by pv."CO_VAGA"), '[]'::jsonb),
           'avisos', '[]'::jsonb,
           'pendencias', '[]'::jsonb)
    into v_resultado
    from public."TB_PRE_CLASSIF_VAGA" pv
   where pv."CO_MONITORAMENTO" = p_edital;

  select coalesce(sum(jsonb_array_length(v -> 'geral')), 0), coalesce(sum(jsonb_array_length(v -> 'eliminados')), 0)
    into v_elegiveis, v_eliminados
    from jsonb_array_elements(v_resultado -> 'vagas') v;
  v_resultado := v_resultado || jsonb_build_object('totais', jsonb_build_object(
    'elegiveis', v_elegiveis, 'eliminados', v_eliminados, 'avisos', 0, 'pendencias', 0));

  insert into public."TB_LISTA_CLASSIFICACAO"
    ("CO_MONITORAMENTO", "TP_LISTA", "CO_REGRA_CLASSIFICACAO", "NU_VERSAO_REGRA", "DS_RESULTADO", "DS_HASH",
     "QT_ELEGIVEL", "QT_ELIMINADO", "QT_AVISO", "QT_PENDENCIA", "CO_USUARIO")
  values (p_edital, p_tipo, v_regra."CO_REGRA_CLASSIFICACAO", v_regra."NU_VERSAO_VIGENTE", v_resultado,
          private."FC_HASH_RETRATO_CLASSIFICACAO"(v_resultado), v_elegiveis, v_eliminados, 0, 0, (select auth.uid()))
  returning "CO_LISTA_CLASSIFICACAO" into v_id;

  return json_build_object('lista', private."FC_LISTA_CLASSIFICACAO_JSON"(v_id), 'resultado', v_resultado);
end;
$$;

--
-- Name: FUNCTION registrar_lista_pre_classificacao(p_edital uuid, p_tipo text, p_lote integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_lista_pre_classificacao(p_edital uuid, p_tipo text, p_lote integer) IS 'Registra a lista PROVISORIA (por vaga: classificação, nome e nota da ART; os eliminados automáticos com o motivo) ou LOTE (os do lote; com p_lote, só aquele lote — uma reposição) em TB_LISTA_CLASSIFICACAO, montando o retrato a partir de TB_PRE_CLASSIFICACAO (sem conta: só leitura e ordem já gravadas; desde 20261007200000, quem entrou no lote por decisão da coordenação leva o motivo em "decisao", que o documento mostra em nota). Exige a coordenação da avaliação do edital ou Editor na Classificação, a regra de classificação do edital e a pré-classificação já gravada. Devolve os metadados e o retrato. Hash do conteúdo: FC_HASH_RETRATO_CLASSIFICACAO (20261024130000).';

--
-- Name: registrar_navegacao_monitora(text, text, jsonb, text, text, text, text, boolean, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_navegacao_monitora(p_evento text DEFAULT NULL::text, p_tela text DEFAULT NULL::text, p_detalhes jsonb DEFAULT '{}'::jsonb, p_client_session_id text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text, p_origem text DEFAULT 'index'::text, p_presenca boolean DEFAULT true, p_current_view text DEFAULT NULL::text, p_eventos jsonb DEFAULT NULL::jsonb, p_listar boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    SET statement_timeout TO '3s'
    AS $$
declare
  v_evento_id bigint;
  v_eventos bigint[] := '{}';
  v_item jsonb;
  v_presenca jsonb := '{}'::jsonb;
  v_resposta jsonb;
begin
  if auth.uid() is null then
    raise exception 'Sessao nao localizada.' using errcode = '28000';
  end if;

  -- O mesmo registro de registrar_evento_acesso (TL_EVENTO_ACESSO).
  if nullif(btrim(p_evento), '') is not null then
    v_evento_id := public.registrar_evento_acesso(
      p_evento, p_tela, p_origem, p_detalhes,
      p_client_session_id, p_user_agent, p_app_version
    );
  end if;

  -- Eventos de carona (até 10), cada um a mesma linha; um recusado não desfaz o resto.
  if jsonb_typeof(p_eventos) = 'array' then
    for v_item in
      select t.e from jsonb_array_elements(p_eventos) with ordinality as t(e, n) where t.n <= 10
    loop
      continue when jsonb_typeof(v_item) <> 'object'
                 or nullif(btrim(v_item ->> 'evento'), '') is null;
      begin
        v_eventos := v_eventos || public.registrar_evento_acesso(
          v_item ->> 'evento',
          coalesce(nullif(btrim(v_item ->> 'tela'), ''), p_tela),
          coalesce(nullif(btrim(v_item ->> 'origem'), ''), p_origem),
          case when jsonb_typeof(v_item -> 'detalhes') = 'object' then v_item -> 'detalhes' else '{}'::jsonb end,
          coalesce(nullif(btrim(v_item ->> 'client_session_id'), ''), p_client_session_id),
          p_user_agent,
          coalesce(nullif(btrim(v_item ->> 'app_version'), ''), p_app_version)
        );
      exception when others then
        null;
      end;
    end loop;
  end if;

  -- A mesma linha de registrar_presenca_monitora; a falha dela não desfaz os eventos.
  if p_presenca then
    begin
      v_presenca := public.registrar_presenca_monitora(p_current_view);
    exception when others then
      v_presenca := jsonb_build_object(
        'presenca_erro', jsonb_build_object('codigo', sqlstate, 'mensagem', sqlerrm)
      );
    end;
  end if;

  v_resposta := coalesce(v_presenca, '{}'::jsonb) || jsonb_build_object('evento_id', v_evento_id);
  if cardinality(v_eventos) > 0 then
    v_resposta := v_resposta || jsonb_build_object('eventos_ids', to_jsonb(v_eventos));
  end if;

  -- "Pessoas online" de carona: a mesma função, com a mesma permissão.
  if p_listar then
    begin
      v_resposta := v_resposta
        || jsonb_build_object('pessoas', public.listar_presenca_online_monitora());
    exception when others then
      v_resposta := v_resposta || jsonb_build_object(
        'pessoas_erro', jsonb_build_object('codigo', sqlstate, 'mensagem', sqlerrm)
      );
    end;
  end if;

  return v_resposta;
end;
$$;

--
-- Name: FUNCTION registrar_navegacao_monitora(p_evento text, p_tela text, p_detalhes jsonb, p_client_session_id text, p_user_agent text, p_app_version text, p_origem text, p_presenca boolean, p_current_view text, p_eventos jsonb, p_listar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_navegacao_monitora(p_evento text, p_tela text, p_detalhes jsonb, p_client_session_id text, p_user_agent text, p_app_version text, p_origem text, p_presenca boolean, p_current_view text, p_eventos jsonb, p_listar boolean) IS 'A batida e a navegação numa chamada: o evento de auditoria (registrar_evento_acesso), até 10 eventos de carona (p_eventos), a presença (registrar_presenca_monitora, com a versão do catálogo de abas) e, com p_listar, a lista de Pessoas online (listar_presenca_online_monitora). Falha da presença volta em presenca_erro e a da lista em pessoas_erro; nenhuma desfaz os eventos.';

--
-- Name: registrar_presenca_monitora(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_presenca_monitora(p_current_view text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_email text := coalesce(auth.jwt() ->> 'email', '');
  v_foto text;
begin
  if v_user_id is null then
    raise exception 'Sessao nao localizada.' using errcode = '28000';
  end if;

  if not exists (
    select 1
    from public."TB_PERFIL_USUARIO" p
    where p.ativo is true
      and (
        p.user_id = v_user_id
        or lower(p.email) = lower(v_email)
      )
  ) then
    raise exception 'Perfil institucional nao localizado.' using errcode = 'P0002';
  end if;

  insert into public."TB_PRESENCA_ONLINE_MONITORA" (user_id, current_view, seen_at)
  values (v_user_id, left(nullif(trim(p_current_view), ''), 120), timezone('utc', now()))
  on conflict (user_id) do update
    set current_view = excluded.current_view,
        seen_at = excluded.seen_at;

  select private."FC_FOTO_DO_GOOGLE"(u.raw_user_meta_data)
    into v_foto
    from auth.users u
   where u.id = v_user_id;
  -- Só manda o UPDATE quando a foto mudou de fato (20261103150000): a batida
  -- de presença (~90 s por pessoa) não grava nada no perfil quando é a mesma.
  if v_foto is not null
     and exists (select 1 from public."TB_PERFIL_USUARIO" p
                  where p.user_id = v_user_id
                    and p.google_avatar_url is distinct from v_foto) then
    update public."TB_PERFIL_USUARIO" p
       set google_avatar_url = v_foto
     where p.user_id = v_user_id
       and p.google_avatar_url is distinct from v_foto;
  end if;

  return jsonb_build_object(
    'status', 'OK',
    'versao_do_catalogo', private."FC_VERSAO_DO_CATALOGO_DE_ABAS"()
  );
end;
$$;

--
-- Name: FUNCTION registrar_presenca_monitora(p_current_view text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_presenca_monitora(p_current_view text) IS 'Sinal de presença do MONITORA (Pessoas online); copia a foto do Google do login para TB_PERFIL_USUARIO.google_avatar_url quando ela mudou e devolve a versão do catálogo de abas (versao_do_catalogo), para a tela reler o menu só quando ele muda.';

--
-- Name: registrar_solicitacao_acesso(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_solicitacao_acesso(p_nome text, p_area text DEFAULT NULL::text, p_cargo text DEFAULT NULL::text, p_cargo_outro text DEFAULT NULL::text, p_lotacao text DEFAULT NULL::text, p_justificativa text DEFAULT NULL::text, p_coordenacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_email text := lower(coalesce((select auth.jwt() ->> 'email'), ''));
  v_nome text := btrim(coalesce(p_nome, ''));
  v_area text := nullif(btrim(coalesce(p_area, '')), '');
  v_cargo text := nullif(btrim(coalesce(p_cargo, '')), '');
  v_cargo_outro text := nullif(btrim(coalesce(p_cargo_outro, '')), '');
  v_lotacao text := nullif(btrim(coalesce(p_lotacao, '')), '');
  v_justificativa text := btrim(coalesce(p_justificativa, ''));
  v_justificativa_limpa text := btrim(regexp_replace(coalesce(p_justificativa, ''), '\s+', ' ', 'g'));
  v_coordenacao text := nullif(btrim(coalesce(p_coordenacao, '')), '');
  v_reativacao boolean;
  v_id uuid;
begin
  if v_uid is null or v_email = '' then raise exception 'Usuário não autenticado' using errcode = '42501'; end if;
  if length(v_nome) not between 2 and 120 then
    raise exception 'Informe seu nome completo (2 a 120 caracteres).' using errcode = '22023';
  end if;
  if length(v_justificativa_limpa) not between 20 and 2000
     or not private."FC_MOTIVO_PARECE_TEXTO"(v_justificativa_limpa, 3) then
    raise exception 'Explique por que precisa do acesso: de 20 a 2.000 caracteres, com pelo menos 3 palavras.' using errcode = '22023';
  end if;

  -- Conta desativada pede reativação: o administrador já sabe a área de antes.
  v_reativacao := exists (
    select 1 from public."TB_PERFIL_USUARIO" u
     where not u.ativo and (u.user_id = v_uid or lower(u.email) = v_email));

  if v_area is null and not v_reativacao then
    raise exception 'Escolha a área: Projetos, Saúde Indígena ou SEDE.' using errcode = '22023';
  end if;
  if v_area is not null and not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Área inválida: %', v_area using errcode = '22023';
  end if;
  if v_area is null then
    v_cargo := null; v_cargo_outro := null; v_lotacao := null;
  else
    if v_cargo is null or private."FC_CARGO_SOLICITACAO_ACESSO"(v_area, v_cargo) is null then
      raise exception 'Escolha o cargo ou a função na lista da área.' using errcode = '22023';
    end if;
    if v_cargo = 'OUTRO' then
      if length(coalesce(v_cargo_outro, '')) not between 3 and 120 then
        raise exception 'Descreva o cargo ou a função (3 a 120 caracteres).' using errcode = '22023';
      end if;
    else
      v_cargo_outro := null;
    end if;
    if v_lotacao is null or length(v_lotacao) > 200 then
      raise exception 'Informe a unidade ou a lotação (até 200 caracteres).' using errcode = '22023';
    end if;
    if v_area = 'saude-indigena' and not exists (
         select 1 from public."TD_UNIDADE" t where t.ativo and t.nome_oficial = v_lotacao) then
      raise exception 'Escolha o DSEI ou a CASAI na lista.' using errcode = '22023';
    end if;
    if v_area = 'projetos' and not exists (
         select 1 from public."TA_UNIDADE_AREA" x where x."CO_AREA" = 'projetos' and x."NO_UNIDADE" = v_lotacao) then
      raise exception 'Escolha o projeto na lista.' using errcode = '22023';
    end if;
  end if;
  if v_coordenacao is not null and not exists (
       select 1 from public."TB_COORDENACAO" c
        where c."CO_COORDENACAO" = v_coordenacao and c."ST_ATIVO"
          and (v_area is null or c."CO_AREA" = v_area)) then
    raise exception 'Coordenação inválida para a área escolhida.' using errcode = '22023';
  end if;

  -- Pedido pendente: editar (a pessoa corrige o que pediu enquanto aguarda).
  update public."TB_SOLICITACAO_ACESSO"
     set nome = v_nome, setor = v_lotacao, justificativa = v_justificativa,
         "CO_AREA" = v_area, "CO_CARGO_SOLICITADO" = v_cargo, "DS_CARGO_OUTRO" = v_cargo_outro,
         "CO_COORDENACAO" = v_coordenacao, updated_at = now()
   where user_id = v_uid and status = 'pendente'
  returning id into v_id;
  if v_id is not null then
    return jsonb_build_object('ok', true, 'id', v_id, 'status', 'pendente', 'atualizado', true);
  end if;

  insert into public."TB_SOLICITACAO_ACESSO" (user_id, email, nome, setor, justificativa, perfil_solicitado, status,
                                              "CO_COORDENACAO", "CO_AREA", "CO_CARGO_SOLICITADO", "DS_CARGO_OUTRO")
  values (v_uid, v_email, v_nome, v_lotacao, v_justificativa, 'usuario', 'pendente',
          v_coordenacao, v_area, v_cargo, v_cargo_outro)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id, 'status', 'pendente', 'atualizado', false);
end;
$$;

--
-- Name: FUNCTION registrar_solicitacao_acesso(p_nome text, p_area text, p_cargo text, p_cargo_outro text, p_lotacao text, p_justificativa text, p_coordenacao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_solicitacao_acesso(p_nome text, p_area text, p_cargo text, p_cargo_outro text, p_lotacao text, p_justificativa text, p_coordenacao text) IS 'Registra o pedido de acesso de quem está autenticado (área, cargo da lista, lotação, justificativa com 3 palavras) ou, com pedido pendente, o atualiza. Conta desativada (reativação): área opcional. Nunca concede acesso.';

--
-- Name: registrar_uso_liberacao_congelamento(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_uso_liberacao_congelamento(p_liberacao uuid, p_execucao text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if p_liberacao is null then
    raise exception 'Informe a liberação.' using errcode = '22023';
  end if;
  if p_execucao is null or p_execucao !~ '^[A-Za-z0-9_-]{8,80}$' then
    raise exception 'Execução inválida.' using errcode = '22023';
  end if;

  insert into public."TH_CONGELAMENTO_INSCRICAO"
         ("CO_MONITORAMENTO", "TP_EVENTO", "CO_USUARIO", "CO_LIBERACAO", "CO_DISPARO", "CO_EXECUCAO")
  select l."CO_MONITORAMENTO", 'USO', l."CO_USUARIO", l."CO_LIBERACAO", l."CO_DISPARO", p_execucao
    from public."TH_CONGELAMENTO_INSCRICAO" l
   where l."TP_EVENTO" = 'LIBERACAO' and l."CO_LIBERACAO" = p_liberacao and l."DT_VALIDADE" > now()
  on conflict ("CO_EXECUCAO", "CO_MONITORAMENTO") where "TP_EVENTO" = 'USO' do nothing;

  return json_build_object(
    'execucao', p_execucao,
    'editais', coalesce((
      select json_agg(coalesce(private."FC_NUMERO_EDITAL"(m.edital), m.edital) order by m.edital)
        from public."TH_CONGELAMENTO_INSCRICAO" u
        join public."TB_MONITORAMENTO_INDIGENA" m on m.id = u."CO_MONITORAMENTO"
       where u."TP_EVENTO" = 'USO' and u."CO_EXECUCAO" = p_execucao and u."CO_LIBERACAO" = p_liberacao), '[]'::json));
end;
$_$;

--
-- Name: FUNCTION registrar_uso_liberacao_congelamento(p_liberacao uuid, p_execucao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_uso_liberacao_congelamento(p_liberacao uuid, p_execucao text) IS 'Robô da Empregare e pré-classificação (service_role, 20261020170000): registra (USO) que a execução p_execucao usa a liberação p_liberacao (forcar_congelado do workflow) — só a LIBERACAO dentro da validade; idempotente. É o que deixa FC_EMPREGARE_ABRIR_VAGA gravar a vaga do edital congelado. Devolve os editais liberados nesta execução.';

--
-- Name: reiniciar_edital_treinamento(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reiniciar_edital_treinamento(p_edital uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_m public."TB_MONITORAMENTO_INDIGENA";
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_apagados jsonb;
  v_id uuid;
begin
  if not private.is_master() then
    raise exception 'Só o administrador global reinicia o edital de treinamento' using errcode = '42501';
  end if;
  select * into v_m from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  if v_m.id is null then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  if v_m."ST_TREINAMENTO" is distinct from 'S' then
    raise exception 'Só o edital de treinamento pode ser reiniciado' using errcode = '42501';
  end if;
  if v_m."CO_AREA" is null or v_m."CO_AREA" not in ('saude-indigena', 'projetos') then
    raise exception 'Edital de treinamento fora da Saúde Indígena e de Projetos: nada foi apagado' using errcode = '22023';
  end if;

  v_apagados := private."FC_APAGAR_DADOS_DO_TREINAMENTO"(p_edital);

  -- O edital volta ao cadastro inicial (o id fica: links e coordenações seguem valendo).
  if v_m."CO_AREA" = 'projetos' then
    update public."TB_MONITORAMENTO_INDIGENA"
       set processo = 'TREINAMENTO', edital = 'Treinamento – Projetos (992/2099)', unidade = 'Escritório Treinamento',
           sigla_unidade = 'TREINO', tipo_unidade = null, id_unidade = null, uf = 'RR', ciclo = '2099',
           cargos = 'Médico do Trabalho; Enfermeiro do Trabalho; Engenharia do Trabalho; Técnico de Enfermagem do Trabalho; Técnico de Segurança do Trabalho',
           vagas_total = 11, inscritos = 40, aptos_analise = 0, cancelados = 0, eliminados_nota = 0, reprovados_analise = 0,
           total_eliminados = 0, aprovados_analise = 0, aprovados_prova = 0, entrevistados = 0, contratados = 0,
           data_inicio = v_hoje - 24, data_fim = v_hoje + 50, status = 'Em andamento', etapa = 'Período de Análise Curricular',
           risco = 'Baixo', responsavel = 'Treinamento', ativo = true,
           status_override = null, etapa_override = null, status_override_motivo = null,
           status_override_data = null, status_override_previsao_retomada = null,
           updated_by = (select auth.uid()), updated_at = now()
     where id = p_edital and "ST_TREINAMENTO" = 'S';
  else
    update public."TB_MONITORAMENTO_INDIGENA"
       set processo = 'TREINAMENTO', edital = 'Treinamento – Saúde Indígena (991/2099)', unidade = 'DSEI Treinamento',
           sigla_unidade = 'TREINO', tipo_unidade = 'DSEI', id_unidade = null, uf = 'DF', ciclo = '2099',
           cargos = 'Enfermeiro; Técnico de Enfermagem; Agente Indígena de Saúde (AIS)', vagas_total = 7,
           inscritos = 30, aptos_analise = 30, cancelados = 0, eliminados_nota = 0, reprovados_analise = 0,
           total_eliminados = 0, aprovados_analise = 0, aprovados_prova = 0, entrevistados = 0, contratados = 0,
           data_inicio = v_hoje - 45, data_fim = v_hoje + 30, status = 'Em andamento', etapa = 'Entrevistas',
           risco = 'Baixo', responsavel = 'Treinamento', ativo = true,
           status_override = null, etapa_override = null, status_override_motivo = null,
           status_override_data = null, status_override_previsao_retomada = null,
           updated_by = (select auth.uid()), updated_at = now()
     where id = p_edital and "ST_TREINAMENTO" = 'S';
  end if;
  -- A área fica a do edital: o gatilho da área recalcula pela unidade quando ela muda.
  update public."TB_MONITORAMENTO_INDIGENA" set "CO_AREA" = v_m."CO_AREA"
   where id = p_edital and "ST_TREINAMENTO" = 'S' and "CO_AREA" is distinct from v_m."CO_AREA";

  v_id := private."FC_PREPARAR_EDITAL_TREINAMENTO"(v_m."CO_AREA");
  if v_id is distinct from p_edital then
    raise exception 'O reinício não reencontrou o edital de treinamento' using errcode = 'P0001';
  end if;
  return json_build_object('edital', p_edital, 'apagados', v_apagados, 'reiniciado_em', now());
end;
$$;

--
-- Name: FUNCTION reiniciar_edital_treinamento(p_edital uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reiniciar_edital_treinamento(p_edital uuid) IS 'Só admin global: volta o edital de TREINAMENTO (ST_TREINAMENTO = S) da Saúde Indígena ou de Projetos ao estado inicial — apaga fisicamente os dados dele (exceção documentada à exclusão lógica) e recria os fictícios com as duas etapas prontas (avaliação documental com pré-classificação e fichas; entrevista configurada, convocados e agenda a partir de hoje). Edital real: 42501 e nada muda.';

--
-- Name: reiniciar_fichas_do_edital(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reiniciar_fichas_do_edital(p_edital uuid, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_impacto jsonb;
begin
  if not private.is_master() then
    raise exception 'Só o administrador global reinicia as fichas do edital' using errcode = '42501';
  end if;
  -- Trava as fichas antes de contar: ninguém conclui no meio do caminho.
  perform 1 from public."TB_FICHA_ANALISE" f where f."CO_MONITORAMENTO" = p_edital for update;
  v_impacto := private."FC_IMPACTO_REINICIO_FICHAS"(p_edital);
  if (v_impacto ->> 'exige_aprovacao')::boolean then
    raise exception 'Este edital tem % ficha(s) concluída(s) e % em análise com lançamento. O reinício precisa de dois administradores: peça o reinício e outro administrador global aprova.',
      v_impacto ->> 'concluidas', v_impacto ->> 'com_lancamento'
      using errcode = '55000';
  end if;
  return private."FC_REINICIAR_FICHAS_DO_EDITAL"(p_edital, p_motivo, (select auth.uid()));
end;
$$;

--
-- Name: FUNCTION reiniciar_fichas_do_edital(p_edital uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reiniciar_fichas_do_edital(p_edital uuid, p_motivo text) IS 'Só admin global: volta ao início toda ficha iniciada do edital SEM ficha trabalhada (20261022210000): com ficha CONCLUIDA ou EM_ANALISE/REVISAR com lançamento, recusa (55000) e orienta o pedido com dois administradores (pedir/aprovar_reinicio_fichas_do_edital). Motivo de 10 a 2.000 e histórico REINICIAR por ficha; recusa edital congelado ou encerrado (FC_REINICIAR_FICHAS_DO_EDITAL).';

--
-- Name: remover_anexo_candidato_aprovado(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remover_anexo_candidato_aprovado(p_anexo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text := private.papel_recurso('aprovados');
  v_ativo boolean;
begin
  perform private."FC_EXIGIR_AREA_EDITAL"((select l.edital_id from public."TB_ANEXO_CANDIDATO_APROVADO" a join public."TB_CANDIDATO_APROVADO" c on c.id = a."CO_CANDIDATO" join public."TB_LISTA_APROVADO" l on l.id = c.lista_id where a."CO_ANEXO" = p_anexo_id));
  if not (private.pode_recurso('aprovados',2)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  -- Anexos: só o admin do módulo (mesma regra da tela, canManageCandidateAttachments).
  if not private.pode_recurso('aprovados', 3) then
    raise exception 'Perfil sem permissão para remover anexos' using errcode = '42501';
  end if;

  select l.ativo into v_ativo
    from public."TB_ANEXO_CANDIDATO_APROVADO" a
    join public."TB_CANDIDATO_APROVADO" c on c.id = a."CO_CANDIDATO"
    join public."TB_LISTA_APROVADO" l on l.id = c.lista_id and l.vigente is true
   where a."CO_ANEXO" = p_anexo_id
   for update of a;
  if not found then raise exception 'Anexo não encontrado'; end if;
  if not v_ativo then
    raise exception 'A lista está inativa e não permite alterar candidatos';
  end if;

  delete from public."TB_ANEXO_CANDIDATO_APROVADO" where "CO_ANEXO" = p_anexo_id;

  return jsonb_build_object('ok', true);
end;
$$;

--
-- Name: remover_grupo_acesso(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remover_grupo_acesso(p_codigo text, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_atual public."TB_GRUPO_ACESSO"; v_antes jsonb;
begin
  if not private.is_master() then raise exception 'Somente administradores gerenciam grupos' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then raise exception 'Informe um motivo entre 3 e 500 caracteres'; end if;
  select * into v_atual from public."TB_GRUPO_ACESSO" where "CO_GRUPO_ACESSO" = p_codigo for update;
  if v_atual."CO_GRUPO_ACESSO" is null then raise exception 'Grupo não encontrado'; end if;
  if v_atual."ST_SISTEMA" then raise exception 'Grupo do sistema não pode ser removido'; end if;
  if exists (select 1 from public."TB_PERFIL_USUARIO" u where u.perfil = p_codigo) then
    raise exception 'Há usuários neste grupo. Troque o grupo deles antes de remover.';
  end if;
  if exists (select 1 from public."TB_SOLICITACAO_ACESSO" s where s.perfil_solicitado = p_codigo) then
    raise exception 'Há solicitações de acesso com este grupo.';
  end if;
  v_antes := private."FC_GRUPO_ACESSO_JSON"(p_codigo);
  delete from public."TB_GRUPO_ACESSO" where "CO_GRUPO_ACESSO" = p_codigo;
  insert into public."TH_GRUPO_ACESSO" ("CO_GRUPO_ACESSO", "JS_ANTES", "JS_DEPOIS", "CO_ALTERADO_POR", "DS_MOTIVO")
  values (p_codigo, v_antes, null, (select auth.uid()), btrim(p_motivo));
  return jsonb_build_object('ok', true, 'codigo', p_codigo);
end;
$$;

--
-- Name: remover_lista_aprovados(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remover_lista_aprovados(p_lista_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_edital_id text;
  v_autor record;
begin
  -- Quem substitui remove (admin global ou Importação nível 3 na matriz de Acessos).
  if not private."FC_PODE_SUBSTITUIR_LISTA"() then
    raise exception 'Sem permissão para remover a lista de aprovados (Importação nível administrador).' using errcode = '42501';
  end if;
  if not private."FC_ADMIN_GLOBAL_ATIVO"((select auth.uid())) then
    perform private."FC_EXIGIR_AREA_EDITAL"((select l.edital_id from public."TB_LISTA_APROVADO" l where l.id = p_lista_id));
  end if;
  select * into v_autor from private.autor_da_sessao();
  update public."TB_LISTA_APROVADO"
  set vigente = false, ativo = false, substituido_por = (select auth.uid()),
      substituido_em = now(), updated_at = now(),
      "DS_EMAIL_SUBSTITUICAO" = v_autor.email,
      "NO_USUARIO_SUBSTITUICAO" = v_autor.nome
  where id = p_lista_id and vigente is true
  returning edital_id into v_edital_id;
  if not found then raise exception 'Lista vigente nao encontrada'; end if;
  -- Sem lista vigente, os contratados do edital voltam a zero.
  perform private."FC_ATUALIZAR_CONTRATADOS_DO_EDITAL"(v_edital_id::uuid);
  return jsonb_build_object('ok', true, 'lista_id', p_lista_id, 'edital_id', v_edital_id);
end;
$$;

--
-- Name: remover_modelo_convocacao(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remover_modelo_convocacao(p_modelo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_editais integer := 0;
begin
  if not (private.pode_recurso('importacao',2)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not private.pode_recurso('importacao',2) then
    raise exception 'Perfil sem permissao para configurar a convocacao';
  end if;
  if p_modelo_id is null then raise exception 'Modelo nao informado'; end if;

  select count(*) into v_editais
  from public."TB_CONVOCACAO_EDITAL"
  where "CO_MODELO" = p_modelo_id;

  delete from public."TB_MODELO_CONVOCACAO" where "CO_MODELO" = p_modelo_id;
  if not found then raise exception 'Modelo nao encontrado'; end if;

  return jsonb_build_object('ok', true, 'editais_afetados', v_editais);
end;
$$;

--
-- Name: remover_sub_judice(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remover_sub_judice(p_candidato_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v public."TB_CANDIDATO_APROVADO"%rowtype;
  v_ativo boolean;
begin
  perform private."FC_EXIGIR_AREA_EDITAL"((select l.edital_id from public."TB_CANDIDATO_APROVADO" c join public."TB_LISTA_APROVADO" l on l.id = c.lista_id where c.id = p_candidato_id));
  if not (private.pode_recurso('aprovados', 2)) then raise exception 'Sem permissão para este recurso' using errcode = '42501'; end if;

  select c.* into v
    from public."TB_CANDIDATO_APROVADO" c
    join public."TB_LISTA_APROVADO" l on l.id = c.lista_id and l.vigente is true
   where c.id = p_candidato_id and c.sub_judice is true and c.removido_em is null
     for update of c, l;
  if not found then raise exception 'Candidato sub judice vigente nao encontrado'; end if;
  select l.ativo into v_ativo from public."TB_LISTA_APROVADO" l where l.id = v.lista_id;
  if not v_ativo then raise exception 'A lista esta inativa e nao permite remover sub judice'; end if;
  if v.alterado_judicialmente then
    raise exception 'Candidato com nota ou modalidade alterada por decisao judicial: use Desfazer alteracao' using errcode = '22023';
  end if;

  update public."TB_CANDIDATO_APROVADO"
     set removido_em = now(), removido_por = (select auth.uid()),
         updated_by = (select auth.uid()), updated_at = now()
   where id = p_candidato_id;
  perform private."FC_RECOLOCAR_NA_CLASSIFICACAO"(p_candidato_id, v.modalidade);

  insert into public."TH_CANDIDATO_SUB_JUDICE" (
    "CO_CANDIDATO", "CO_LISTA", "TP_EVENTO", "VL_NOTA_ANTERIOR", "DS_MODALIDADE_ANTERIOR",
    "NU_CLASSIFICACAO_ANTERIOR", "CO_USUARIO"
  ) values (
    p_candidato_id, v.lista_id, 'REMOCAO', v.nota, v.modalidade, v.classificacao, (select auth.uid())
  );

  return jsonb_build_object('ok', true, 'candidato_id', p_candidato_id, 'lista_id', v.lista_id);
end;
$$;

--
-- Name: renomear_versao_regra_analise(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renomear_versao_regra_analise(p_edital uuid, p_versao integer, p_nome text, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_regra uuid;
  v_antes varchar;
  v_nome varchar := private."FC_NOME_DA_VERSAO"(p_nome);
  v_motivo text := btrim(coalesce(p_motivo, ''));
begin
  if length(v_motivo) not between 10 and 500 then
    raise exception 'Informe o motivo da troca do nome (10 a 500 caracteres).' using errcode = '22023';
  end if;
  select r."CO_REGRA_ANALISE" into v_regra from public."TB_REGRA_ANALISE" r where r."CO_MONITORAMENTO" = p_edital for update;
  select h."NO_VERSAO" into v_antes
    from public."TH_REGRA_ANALISE" h
   where h."CO_REGRA_ANALISE" = v_regra and h."NU_VERSAO" = p_versao;
  if not found then
    raise exception 'Versão % da regra não encontrada.', p_versao using errcode = '22023';
  end if;
  if v_antes is not distinct from v_nome then
    raise exception 'O nome não mudou.' using errcode = '22023';
  end if;
  update public."TH_REGRA_ANALISE" set "NO_VERSAO" = v_nome
   where "CO_REGRA_ANALISE" = v_regra and "NU_VERSAO" = p_versao;
  insert into public."TH_NOME_VERSAO_REGRA" ("TP_REGRA", "CO_REGRA", "NU_VERSAO", "NO_VERSAO_ANTERIOR", "NO_VERSAO_NOVO", "DS_MOTIVO", "CO_USUARIO")
  values ('ANALISE', v_regra, p_versao, v_antes, v_nome, v_motivo, (select auth.uid()));
  return json_build_object('regra', private."FC_REGRA_ANALISE_JSON"(p_edital));
end;
$$;

--
-- Name: FUNCTION renomear_versao_regra_analise(p_edital uuid, p_versao integer, p_nome text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.renomear_versao_regra_analise(p_edital uuid, p_versao integer, p_nome text, p_motivo text) IS 'Troca só o nome de uma versão da regra da avaliação documental (p_nome vazio tira o nome), com motivo de 10 a 500 (histórico em TH_NOME_VERSAO_REGRA). Configuração, hash e situação (conferida ou não) não mudam. Devolve a regra. Quem muda a regra: a coordenação do edital (e o administrador global).';

--
-- Name: renomear_versao_regra_classificacao(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renomear_versao_regra_classificacao(p_edital uuid, p_versao integer, p_nome text, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 2);
  v_regra uuid;
  v_antes varchar;
  v_nome varchar := private."FC_NOME_DA_VERSAO"(p_nome);
  v_motivo text := btrim(coalesce(p_motivo, ''));
begin
  if length(v_motivo) not between 10 and 500 then
    raise exception 'Informe o motivo da troca do nome (10 a 500 caracteres).' using errcode = '22023';
  end if;
  select r."CO_REGRA_CLASSIFICACAO" into v_regra from public."TB_REGRA_CLASSIFICACAO" r where r."CO_MONITORAMENTO" = p_edital for update;
  select h."NO_VERSAO" into v_antes
    from public."TH_REGRA_CLASSIFICACAO" h
   where h."CO_REGRA_CLASSIFICACAO" = v_regra and h."NU_VERSAO" = p_versao;
  if not found then
    raise exception 'Versão % da regra não encontrada.', p_versao using errcode = '22023';
  end if;
  if v_antes is not distinct from v_nome then
    raise exception 'O nome não mudou.' using errcode = '22023';
  end if;
  update public."TH_REGRA_CLASSIFICACAO" set "NO_VERSAO" = v_nome
   where "CO_REGRA_CLASSIFICACAO" = v_regra and "NU_VERSAO" = p_versao;
  insert into public."TH_NOME_VERSAO_REGRA" ("TP_REGRA", "CO_REGRA", "NU_VERSAO", "NO_VERSAO_ANTERIOR", "NO_VERSAO_NOVO", "DS_MOTIVO", "CO_USUARIO")
  values ('CLASSIFICACAO', v_regra, p_versao, v_antes, v_nome, v_motivo, (select auth.uid()));
  return private."FC_REGRA_CLASSIFICACAO_JSON"(p_edital);
end;
$$;

--
-- Name: FUNCTION renomear_versao_regra_classificacao(p_edital uuid, p_versao integer, p_nome text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.renomear_versao_regra_classificacao(p_edital uuid, p_versao integer, p_nome text, p_motivo text) IS 'Troca só o nome de uma versão da regra de classificação (p_nome vazio tira o nome), com motivo de 10 a 500 (histórico em TH_NOME_VERSAO_REGRA). A configuração não muda. Devolve a regra. Exige classificacao >= editor, a área e o recorte da coordenação.';

--
-- Name: renomear_versao_roteiro_entrevista(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renomear_versao_roteiro_entrevista(p_roteiro uuid, p_nome text, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_r public."TB_ROTEIRO_ENTREVISTA";
  v_nome varchar := private."FC_NOME_DA_VERSAO"(p_nome);
  v_motivo text := btrim(coalesce(p_motivo, ''));
begin
  if not private.pode_recurso('entrevistas', 2) then
    raise exception 'Sem permissão para editar roteiros de entrevista' using errcode = '42501';
  end if;
  select * into v_r from public."TB_ROTEIRO_ENTREVISTA" where "CO_ROTEIRO" = p_roteiro for update;
  if v_r."CO_ROTEIRO" is null then
    raise exception 'Roteiro não encontrado' using errcode = '22023';
  end if;
  if v_r."CO_AREA" is not null and not private."FC_PODE_AREA"(v_r."CO_AREA") then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;
  if length(v_motivo) not between 10 and 500 then
    raise exception 'Informe o motivo da troca do nome (10 a 500 caracteres).' using errcode = '22023';
  end if;
  if v_r."NO_VERSAO" is not distinct from v_nome then
    raise exception 'O nome não mudou.' using errcode = '22023';
  end if;
  update public."TB_ROTEIRO_ENTREVISTA" set "NO_VERSAO" = v_nome where "CO_ROTEIRO" = p_roteiro;
  insert into public."TH_NOME_VERSAO_REGRA" ("TP_REGRA", "CO_REGRA", "NU_VERSAO", "NO_VERSAO_ANTERIOR", "NO_VERSAO_NOVO", "DS_MOTIVO", "CO_USUARIO")
  values ('ROTEIRO', v_r."CO_ROTEIRO_ORIGEM", v_r."NU_VERSAO", v_r."NO_VERSAO", v_nome, v_motivo, (select auth.uid()));
  return private."FC_ROTEIRO_JSON"(p_roteiro);
end;
$$;

--
-- Name: FUNCTION renomear_versao_roteiro_entrevista(p_roteiro uuid, p_nome text, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.renomear_versao_roteiro_entrevista(p_roteiro uuid, p_nome text, p_motivo text) IS 'Troca só o nome de uma versão do roteiro de entrevista (p_roteiro = CO_ROTEIRO da versão; p_nome vazio tira o nome), com motivo de 10 a 500 (histórico em TH_NOME_VERSAO_REGRA). Competências, escala e editais que a usam não mudam. Devolve o roteiro. entrevistas >= editor e a área do roteiro.';

--
-- Name: renovar_reserva(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.renovar_reserva(p_ficha uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_uid uuid := (select auth.uid());
  v_area text;
begin
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha;
  if v_f."CO_FICHA_ANALISE" is null then
    raise exception 'Ficha não encontrada' using errcode = '22023';
  end if;
  v_area := private."FC_EXIGIR_AVALIACAO_EDITAL"(v_f."CO_MONITORAMENTO", 2);
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha for update;
  if v_f."CO_USUARIO_RESERVA" = v_uid and v_f."DT_RESERVA_EXPIRA" > now() then
    -- Renovar não muda a versão nem vai ao histórico.
    update public."TB_FICHA_ANALISE" set "DT_RESERVA_EXPIRA" = now() + private."FC_PRAZO_RESERVA_FICHA"()
     where "CO_FICHA_ANALISE" = p_ficha;
  elsif (v_f."DT_RESERVA_EXPIRA" is null or v_f."DT_RESERVA_EXPIRA" <= now())
        and v_f."CO_USUARIO_RESPONSAVEL" = v_uid and v_f."TP_SITUACAO" in ('PENDENTE', 'EM_ANALISE')
        and private."FC_PODE_ANALISAR_VAGA"(v_f."CO_MONITORAMENTO", v_uid, v_f."CO_VAGA") then
    -- Reserva vencida, mesmo responsável: reserva de novo sem subir a versão
    -- (a tela aberta segue salvando). Só PENDENTE → EM_ANALISE sobe.
    update public."TB_FICHA_ANALISE" set
      "DT_ATRIBUICAO" = coalesce("DT_ATRIBUICAO", now()),
      "TP_SITUACAO" = case when "TP_SITUACAO" = 'PENDENTE' then 'EM_ANALISE' else "TP_SITUACAO" end,
      "CO_USUARIO_RESERVA" = v_uid, "DT_RESERVA" = now(),
      "DT_RESERVA_EXPIRA" = now() + private."FC_PRAZO_RESERVA_FICHA"(),
      "NU_VERSAO" = "NU_VERSAO" + case when "TP_SITUACAO" = 'PENDENTE' then 1 else 0 end,
      "DT_ATUALIZACAO" = now()
     where "CO_FICHA_ANALISE" = p_ficha;
    perform private."FC_HISTORICO_FICHA"(p_ficha, 'RESERVAR', v_f."TP_SITUACAO", v_f."CO_USUARIO_RESPONSAVEL", null, v_uid);
  else
    raise exception 'A ficha não está mais com você (reserva liberada ou com outra pessoa); abra de novo.' using errcode = 'PT409';
  end if;
  return json_build_object('ficha', private."FC_FICHA_ANALISE_JSON"(p_ficha));
end;
$$;

--
-- Name: FUNCTION renovar_reserva(p_ficha uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.renovar_reserva(p_ficha uuid) IS 'Renova por mais 15 minutos a reserva de quem está com a ficha aberta (sem mudar a versão). Reserva vencida e ninguém no lugar: o responsável reserva de novo, também sem mudar a versão (só PENDENTE → EM_ANALISE sobe). Com outra pessoa ou liberada pela coordenação: PT409. Exige Editor no edital da ficha.';

--
-- Name: reservar_ficha(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reservar_ficha(p_ficha uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_uid uuid := (select auth.uid());
  v_area text;
  v_dist jsonb;
  v_reservada boolean := false;
  v_motivo text;
begin
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha;
  if v_f."CO_FICHA_ANALISE" is null then
    raise exception 'Ficha não encontrada' using errcode = '22023';
  end if;
  v_area := private."FC_EXIGIR_AVALIACAO_EDITAL"(v_f."CO_MONITORAMENTO", 1);
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha for update;
  v_dist := private."FC_DISTRIBUICAO_DO_EDITAL"(v_f."CO_MONITORAMENTO");

  if v_f."TP_SITUACAO" in ('CONCLUIDA', 'FORA_LOTE', 'REVISAR') then
    v_motivo := case v_f."TP_SITUACAO" when 'CONCLUIDA' then 'Ficha concluída.' when 'FORA_LOTE' then 'Fora do lote.'
                                       else 'Ficha em revisão.' end;
  elsif v_f."DT_RESERVA_EXPIRA" > now() and v_f."CO_USUARIO_RESERVA" <> v_uid then
    v_motivo := 'Em uso por outra pessoa.';
  elsif v_f."CO_USUARIO_RESPONSAVEL" = v_uid
        and private."FC_PODE_ANALISAR_VAGA"(v_f."CO_MONITORAMENTO", v_uid, v_f."CO_VAGA") then
    perform private."FC_RESERVAR_FICHA"(p_ficha, v_uid, 'RESERVAR');
    v_reservada := true;
  elsif v_f."CO_USUARIO_RESPONSAVEL" is null
        and (v_dist ->> 'modo' = 'PEGAR_PROXIMO' or v_dist ->> 'novos' = 'PEGAR_PROXIMO')
        and private."FC_PODE_ANALISAR_VAGA"(v_f."CO_MONITORAMENTO", v_uid, v_f."CO_VAGA") then
    perform private."FC_RESERVAR_FICHA"(p_ficha, v_uid, 'PEGAR');
    v_reservada := true;
  else
    v_motivo := case
                  when v_f."CO_USUARIO_RESPONSAVEL" is not null and v_f."CO_USUARIO_RESPONSAVEL" <> v_uid
                    then 'Ficha de outra pessoa.'
                  when not private."FC_PODE_ANALISAR_VAGA"(v_f."CO_MONITORAMENTO", v_uid, v_f."CO_VAGA")
                    then 'Você não está na equipe de análise desta vaga.'
                  else 'Ficha livre: a coordenação distribui as fichas deste edital.'
                end;
  end if;

  insert into public."TL_ACESSO_FICHA_ANALISE" ("CO_FICHA_ANALISE", "TP_ACESSO", "CO_USUARIO") values (p_ficha, 'ABRIR_FICHA', v_uid);
  return json_build_object('ficha', private."FC_FICHA_ANALISE_JSON"(p_ficha), 'reservada', v_reservada,
                           'somente_leitura', not v_reservada, 'motivo', v_motivo);
end;
$$;

--
-- Name: FUNCTION reservar_ficha(p_ficha uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reservar_ficha(p_ficha uuid) IS 'Abre a ficha: o responsável (ou um analista da vaga que pega uma livre, quando a regra deixa) fica com a reserva por 15 minutos; quem abre uma ficha em uso, de outra pessoa, concluída, em revisão ou fora do lote vê só para leitura, com o motivo e o "Em uso por … desde …" (AM-12.2). Registra o acesso (TL_ACESSO_FICHA_ANALISE). Exige avaliacao_documental >= leitor no edital da ficha.';

--
-- Name: restaurar_configuracoes_versao(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restaurar_configuracoes_versao(p_versao_id uuid, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
declare
  r jsonb;
  v_target public."TH_CONFIGURACAO"%rowtype;
  v_id uuid;
  v_config_antes jsonb;
  v_config_depois jsonb;
  v_paineis_antes jsonb;
  v_paineis_depois jsonb;
  v_alteracoes jsonb;
  v_total integer;
begin
  if not (private.pode_recurso('configuracoes',2)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not private.has_perm('config') then
    raise exception 'Sem permissao para restaurar "TB_CONFIGURACAO"';
  end if;

  if p_versao_id is null then
    raise exception 'Versao obrigatoria';
  end if;

  if not pg_try_advisory_xact_lock(hashtext('public.salvar_configuracoes_e_paineis_v2')::bigint) then
    raise exception 'Outra publicacao de "TB_CONFIGURACAO" esta em andamento. Aguarde e tente novamente.';
  end if;

  select * into v_target
  from public."TH_CONFIGURACAO"
  where id = p_versao_id;

  if not found then
    raise exception 'Versao de "TB_CONFIGURACAO" nao encontrada';
  end if;

  v_config_antes := private.snapshot_configuracoes();
  v_paineis_antes := private.snapshot_paineis_externos();
  v_alteracoes := private.diff_configuracoes_e_paineis(v_target.config_depois, v_target.paineis_depois);
  v_total := jsonb_array_length(v_alteracoes);

  if v_total = 0 then
    return jsonb_build_object(
      'ok', true,
      'sem_alteracoes', true,
      'total_alteracoes', 0,
      'versao_id', null,
      'restaurada_de', p_versao_id
    );
  end if;

  for r in select * from jsonb_array_elements(v_target.config_depois) loop
    insert into public."TB_CONFIGURACAO"(chave, valor, descricao)
    values (r ->> 'chave', r ->> 'valor', r ->> 'descricao')
    on conflict (chave) do update
      set valor = excluded.valor,
          descricao = excluded.descricao,
          updated_at = now();
  end loop;

  for r in select * from jsonb_array_elements(v_target.paineis_depois) loop
    update public."TB_PAINEL_EXTERNO"
    set titulo = coalesce(nullif(r ->> 'titulo', ''), titulo),
        url = r ->> 'url',
        ativo = coalesce((r ->> 'ativo')::boolean, ativo),
        em_manutencao = coalesce((r ->> 'em_manutencao')::boolean, em_manutencao),
        updated_at = now()
    where id = nullif(r ->> 'id', '')::uuid;
  end loop;

  v_config_depois := private.snapshot_configuracoes();
  v_paineis_depois := private.snapshot_paineis_externos();

  insert into public."TH_CONFIGURACAO"(
    acao,
    motivo,
    created_by,
    created_by_email,
    restaurada_de,
    config_antes,
    config_depois,
    paineis_antes,
    paineis_depois,
    alteracoes,
    total_alteracoes
  ) values (
    'restaurar',
    coalesce(nullif(btrim(p_motivo), ''), 'Restauração de versão anterior'),
    auth.uid(),
    nullif(auth.jwt() ->> 'email', ''),
    p_versao_id,
    v_config_antes,
    v_config_depois,
    v_paineis_antes,
    v_paineis_depois,
    v_alteracoes,
    v_total
  ) returning id into v_id;

  return jsonb_build_object(
    'ok', true,
    'sem_alteracoes', false,
    'total_alteracoes', v_total,
    'versao_id', v_id,
    'restaurada_de', p_versao_id,
    'alteracoes', v_alteracoes,
    'restaurado_em', now()
  );
end;
$$;

--
-- Name: revisar_ficha_concluida_com_pendencia(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revisar_ficha_concluida_com_pendencia(p_ficha uuid, p_versao integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_cargo text;
  v_lanc jsonb;
  v_pend text[];
  v_motivo text;
begin
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha for update;
  if v_f."CO_FICHA_ANALISE" is null then
    return jsonb_build_object('alterada', false, 'motivo', 'ficha não encontrada');
  end if;
  if v_f."TP_SITUACAO" <> 'CONCLUIDA' or v_f."NU_VERSAO" is distinct from p_versao then
    return jsonb_build_object('alterada', false, 'motivo', 'a ficha mudou desde a leitura');
  end if;
  if jsonb_typeof(v_f."DS_LANCAMENTO") is distinct from 'object' or jsonb_typeof(v_f."DS_RESULTADO") is distinct from 'object' then
    return jsonb_build_object('alterada', false, 'motivo', 'ficha sem lançamento ou resultado');
  end if;
  v_cargo := (select pv."NO_CARGO" from public."TB_PRE_CLASSIF_VAGA" pv
               where pv."CO_MONITORAMENTO" = v_f."CO_MONITORAMENTO" and pv."CO_VAGA" = v_f."CO_VAGA");
  v_lanc := v_f."DS_LANCAMENTO" || jsonb_build_object('vaga', v_f."CO_VAGA", 'cargo', v_cargo);
  select private."FC_PENDENCIAS_FICHA"(
           private."FC_REGRA_DA_VAGA"(r.p_configuracao, v_f."CO_VAGA", v_cargo, v_lanc ->> 'nivel'), v_lanc, v_f."DS_RESULTADO")
    into v_pend
    from private."FC_REGRA_VIGENTE_FICHA"(p_ficha) r;
  if coalesce(cardinality(v_pend), 0) = 0 then
    return jsonb_build_object('alterada', false, 'motivo', 'sem pendência no banco');
  end if;
  v_motivo := left('Conferência automática: a ficha concluída tem pendência pela regra vigente — '
                   || array_to_string(v_pend[1:5], '; ')
                   || case when cardinality(v_pend) > 5 then format(' (e mais %s)', cardinality(v_pend) - 5) else '' end
                   || '.', 2000);
  update public."TB_FICHA_ANALISE" set
    "TP_SITUACAO" = 'REVISAR', "CO_USUARIO_RESERVA" = null, "DT_RESERVA" = null, "DT_RESERVA_EXPIRA" = null,
    "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
   where "CO_FICHA_ANALISE" = p_ficha;
  perform private."FC_HISTORICO_FICHA"(p_ficha, 'REVISAR', 'CONCLUIDA', v_f."CO_USUARIO_RESPONSAVEL", v_motivo, null);
  return jsonb_build_object('alterada', true, 'versao', v_f."NU_VERSAO" + 1, 'pendencias', to_jsonb(v_pend));
end;
$$;

--
-- Name: FUNCTION revisar_ficha_concluida_com_pendencia(p_ficha uuid, p_versao integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.revisar_ficha_concluida_com_pendencia(p_ficha uuid, p_versao integer) IS 'Job de conferências (service_role): passa para REVISAR a ficha CONCLUIDA (na versão lida) que tem pendência pela regra vigente (FC_PENDENCIAS_FICHA, conferida de novo aqui), sem mudar nota nem resultado; histórico TP_ORIGEM JOB com "Conferência automática: …". Devolve {alterada, versao | motivo}.';

--
-- Name: revogar_decisao_lote(uuid, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revogar_decisao_lote(p_edital uuid, p_codigos text[], p_motivo text, p_vaga text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_motivo text := btrim(coalesce(p_motivo, ''));
  v_uid uuid := (select auth.uid());
  v_item record;
  v_a public."TB_PRE_CLASSIFICACAO";
  v_d public."TB_DECISAO_LOTE";
  v_vagas text[] := '{}';
  v_vaga text;
  v_qt integer := 0;
  v_fichas jsonb;
begin
  perform private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  if length(v_motivo) not between 10 and 250 then
    raise exception 'Diga o motivo da revogação (de 10 a 250 caracteres).' using errcode = '22023';
  end if;
  if exists (select 1 from public."TL_PRE_CLASSIFICACAO" t
              where t."TP_SITUACAO" = 'EM_ANDAMENTO' and t."DT_INICIO" > now() - interval '1 hour') then
    raise exception 'Há uma pré-classificação rodando: revogue quando ela terminar.' using errcode = '55P03';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('avaliacao-documental:fichas:' || p_edital::text, 0));

  for v_item in select * from private."FC_INSCRITOS_DA_DECISAO"(p_edital, p_codigos, p_vaga) loop
    select * into v_d from public."TB_DECISAO_LOTE"
     where "CO_MONITORAMENTO" = p_edital and "CO_EMPREGARE_CANDIDATO" = v_item.candidato and "ST_ATIVO" = 'S'
     for update;
    if v_d."CO_DECISAO_LOTE" is null then
      raise exception 'O candidato % não tem decisão vigente.', v_item.codigo using errcode = '22023';
    end if;
    select * into v_a from public."TB_PRE_CLASSIFICACAO"
     where "CO_MONITORAMENTO" = p_edital and "CO_EMPREGARE_CANDIDATO" = v_item.candidato
     for update;
    if v_a."TP_SITUACAO" = 'ANALISADO' or exists (
         select 1 from public."TB_FICHA_ANALISE" f
          where f."CO_MONITORAMENTO" = p_edital and f."CO_EMPREGARE_CANDIDATO" = v_item.candidato
            and f."TP_SITUACAO" = 'CONCLUIDA') then
      raise exception 'O candidato % já tem a ficha concluída: a decisão não se revoga.', v_item.codigo using errcode = '22023';
    end if;

    -- A decisão sai antes (o gatilho do lote confere que não há decisão vigente).
    update public."TB_DECISAO_LOTE" set
      "ST_ATIVO" = 'N', "DS_MOTIVO_REVOGACAO" = v_motivo, "CO_USUARIO_REVOGACAO" = v_uid,
      "DT_REVOGACAO" = now(), "DT_ATUALIZACAO" = now()
     where "CO_DECISAO_LOTE" = v_d."CO_DECISAO_LOTE";
    insert into public."TH_DECISAO_LOTE" ("CO_DECISAO_LOTE", "TP_ACAO", "DS_MOTIVO", "CO_USUARIO")
    values (v_d."CO_DECISAO_LOTE", 'REVOGAR', v_motivo, v_uid);

    -- Quem entrou por decisão volta à situação da regra (o próximo recálculo confere).
    if v_a."TP_SITUACAO" = 'NO_LOTE' and v_a."TP_ENTRADA_LOTE" = 'DECISAO' then
      update public."TB_PRE_CLASSIFICACAO" set
        "TP_SITUACAO" = v_d."TP_SITUACAO_REGRA",
        "CO_MOTIVO_ELIMINACAO" = v_d."CO_MOTIVO_ELIMINACAO_REGRA",
        "DS_MOTIVO_ELIMINACAO" = v_d."DS_MOTIVO_ELIMINACAO_REGRA",
        "NU_POSICAO" = case when v_d."TP_SITUACAO_REGRA" = 'ELIMINADO' then null else "NU_POSICAO" end,
        "NU_POSICAO_MODALIDADE" = case when v_d."TP_SITUACAO_REGRA" = 'ELIMINADO' then null else "NU_POSICAO_MODALIDADE" end,
        "NU_LOTE" = null, "CO_LISTA_LOTE" = null, "TP_ENTRADA_LOTE" = null, "DS_MOTIVO_ENTRADA" = null,
        "DT_ENTRADA_LOTE" = null, "DT_ATUALIZACAO" = now()
       where "CO_MONITORAMENTO" = p_edital and "CO_EMPREGARE_CANDIDATO" = v_item.candidato;
      insert into public."TH_PRE_CLASSIFICACAO"
        ("CO_EXECUCAO", "CO_USUARIO", "CO_MONITORAMENTO", "CO_EMPREGARE_CANDIDATO", "CO_VAGA", "TP_SITUACAO_ANTERIOR",
         "TP_SITUACAO", "NU_LOTE_ANTERIOR", "NU_LOTE", "NU_POSICAO", "DS_MOTIVO")
      values (null, v_uid, p_edital, v_item.candidato, v_a."CO_VAGA", 'NO_LOTE', v_d."TP_SITUACAO_REGRA", v_a."NU_LOTE", null,
              case when v_d."TP_SITUACAO_REGRA" = 'ELIMINADO' then null else v_a."NU_POSICAO" end,
              left('Decisão da coordenação revogada: ' || v_motivo, 300));
      if not (v_a."CO_VAGA" = any (v_vagas)) then
        v_vagas := v_vagas || v_a."CO_VAGA"::text;
      end if;
    end if;
    v_qt := v_qt + 1;
  end loop;

  foreach v_vaga in array v_vagas loop
    perform private."FC_RECONTAR_PRE_CLASSIF_VAGA"(p_edital, v_vaga);
  end loop;
  -- A ficha não concluída de quem saiu fica FORA_LOTE (com o motivo, sem reserva).
  v_fichas := private."FC_ABRIR_FICHAS"(p_edital, '[]'::jsonb, v_uid);
  return json_build_object('revogadas', v_qt, 'fichas_fora_do_lote', coalesce((v_fichas ->> 'fora_do_lote')::integer, 0));
end;
$$;

--
-- Name: FUNCTION revogar_decisao_lote(p_edital uuid, p_codigos text[], p_motivo text, p_vaga text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.revogar_decisao_lote(p_edital uuid, p_codigos text[], p_motivo text, p_vaga text) IS 'A coordenação da avaliação do edital revoga decisões de lote (exclusão lógica em TB_DECISAO_LOTE, com motivo de 10 a 250 caracteres, quem e quando, e o histórico): quem entrou por decisão volta à situação da regra (eliminado com o motivo de antes, ou ranqueado) e a ficha não concluída fica FORA_LOTE (FC_ABRIR_FICHAS). Recusa (22023) sem decisão vigente ou com a ficha concluída (ou ANALISADO); 55P03 com pré-classificação rodando. Só a coordenação (FC_EXIGIR_COORD_AVALIACAO).';

--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;

--
-- Name: salvar_agenda_entrevista(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_agenda_entrevista(p_edital uuid, p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_area text := private."FC_EXIGIR_AGENDA_ENTREVISTA"(p_edital, 2);
  v_acao text := upper(coalesce(p_dados ->> 'acao', ''));
  v_itens jsonb := coalesce(p_dados -> 'itens', '[]'::jsonb);
  v_motivo text := nullif(btrim(coalesce(p_dados ->> 'motivo', '')), '');
  v_lista uuid;
  v_regra public."TB_REGRA_AGENDA_ENTREVISTA";
  v_numero text;
  v_ultimo uuid;
  v_n integer;
  v_alteracoes jsonb;
  v_qt_alteracao integer;
  v_uid uuid := (select auth.uid());
  v_uuid constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_hora constant text := '^([01][0-9]|2[0-3]):[0-5][0-9]$';
begin
  if v_acao not in ('GERAR', 'AJUSTAR', 'LIMPAR') then
    raise exception 'Ação inválida (GERAR, AJUSTAR ou LIMPAR).' using errcode = '22023';
  end if;
  if jsonb_typeof(v_itens) is distinct from 'array' or jsonb_array_length(v_itens) > 3000 then
    raise exception 'Agenda inválida (até 3.000 horários).' using errcode = '22023';
  end if;
  if v_acao = 'LIMPAR' and jsonb_array_length(v_itens) > 0 then
    raise exception 'Limpar não leva horários.' using errcode = '22023';
  end if;
  if v_motivo is not null and length(v_motivo) not between 3 and 500 then
    raise exception 'Motivo entre 3 e 500 caracteres.' using errcode = '22023';
  end if;

  -- Uma gravação por vez no edital; a tela tem de estar na última.
  perform pg_advisory_xact_lock(hashtextextended('agenda_entrevista:' || p_edital::text, 0));
  select h."CO_HISTORICO_AGENDA" into v_ultimo from public."TH_AGENDA_ENTREVISTA" h
   where h."CO_MONITORAMENTO" = p_edital
   order by h."DT_REGISTRO" desc, h."CO_HISTORICO_AGENDA" limit 1;
  if nullif(p_dados ->> 'ultimo_registro', '') is distinct from v_ultimo::text then
    raise exception 'A agenda mudou desde que você abriu; recarregue.' using errcode = 'PT409';
  end if;

  select * into v_regra from public."TB_REGRA_AGENDA_ENTREVISTA" where "CO_MONITORAMENTO" = p_edital;
  if v_acao <> 'LIMPAR' then
    if v_regra."CO_REGRA_AGENDA" is null then
      raise exception 'Salve a regra da agenda antes de gerar.' using errcode = '22023';
    end if;
    if (p_dados ->> 'versao_regra') is distinct from v_regra."NU_VERSAO_VIGENTE"::text then
      raise exception 'A regra da agenda mudou (versão %); gere de novo.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
    end if;
  end if;

  if nullif(p_dados ->> 'lista', '') is not null then
    if p_dados ->> 'lista' !~ v_uuid then
      raise exception 'Lista de convocação inválida.' using errcode = '22023';
    end if;
    v_lista := (p_dados ->> 'lista')::uuid;
    if not exists (select 1 from public."TB_LISTA_CLASSIFICACAO" l
                    where l."CO_LISTA_CLASSIFICACAO" = v_lista and l."CO_MONITORAMENTO" = p_edital
                      and l."TP_LISTA" = 'CONVOCACAO') then
      raise exception 'A lista não é uma convocação deste edital.' using errcode = '22023';
    end if;
  end if;

  -- Cada horário: análise, dia, início e fim (HH:MM, Brasília), banca e origem.
  if exists (select 1 from jsonb_array_elements(v_itens) e
              where case
                      when jsonb_typeof(e) <> 'object'
                        or coalesce(e ->> 'analise', '') !~ v_uuid
                        or coalesce(e ->> 'data', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                        or coalesce(e ->> 'inicio', '') !~ v_hora
                        or coalesce(e ->> 'fim', '') !~ v_hora
                        or coalesce(e ->> 'banca', '') !~ '^[0-9]{1,2}$'
                        or coalesce(e ->> 'origem', 'GERADA') not in ('GERADA', 'MANUAL') then true
                      else (e ->> 'banca')::integer not between 1 and 20
                        or (e ->> 'inicio')::time >= (e ->> 'fim')::time
                    end) then
    raise exception 'Horário inválido: análise, dia (AAAA-MM-DD), início antes do fim (HH:MM) e banca de 1 a 20.' using errcode = '22023';
  end if;
  begin
    perform (e ->> 'data')::date from jsonb_array_elements(v_itens) e;
  exception when others then
    raise exception 'Horário com dia inválido.' using errcode = '22023';
  end;

  create temporary table "TM_AGENDA_NOVA" on commit drop as
  select (e ->> 'analise')::uuid as analise, (e ->> 'data')::date as data,
         (e ->> 'inicio')::time as inicio, (e ->> 'fim')::time as fim,
         (e ->> 'banca')::smallint as banca, coalesce(e ->> 'origem', 'GERADA') as origem
    from jsonb_array_elements(v_itens) e;

  if (select count(*) from pg_temp."TM_AGENDA_NOVA") <> (select count(distinct analise) from pg_temp."TM_AGENDA_NOVA") then
    raise exception 'Candidato repetido na agenda.' using errcode = '22023';
  end if;
  if exists (select 1 from pg_temp."TM_AGENDA_NOVA" a join pg_temp."TM_AGENDA_NOVA" b
               on a.data = b.data and a.banca = b.banca and a.analise < b.analise
              and a.inicio < b.fim and b.inicio < a.fim) then
    raise exception 'Conflito: dois candidatos na mesma banca com horários que se sobrepõem.' using errcode = '22023';
  end if;

  -- Os candidatos são análises ativas deste edital e desta área.
  select private."FC_NUMERO_EDITAL"(m.edital) into v_numero from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  select count(*) into v_n
    from pg_temp."TM_AGENDA_NOVA" t
    join public."TB_ANALISE_CURRICULAR" a on a.id = t.analise
   where a."CO_AREA" = v_area and a.ativo and private."FC_NUMERO_EDITAL"(a.edital) = v_numero;
  if v_n <> (select count(*) from pg_temp."TM_AGENDA_NOVA") then
    raise exception 'Há candidato fora deste edital.' using errcode = '22023';
  end if;

  -- O que mudou: entrou, saiu ou trocou de dia, hora ou banca.
  with antes as (
    select g."CO_ANALISE_CURRICULAR" as analise, g."DT_ENTREVISTA" as data, g."HR_INICIO" as inicio,
           g."HR_FIM" as fim, g."NU_BANCA" as banca
      from public."TB_AGENDA_ENTREVISTA" g where g."CO_MONITORAMENTO" = p_edital
  ),
  mudou as (
    select coalesce(n.analise, a.analise) as analise,
           case when a.analise is null then null else json_build_object(
             'data', a.data, 'inicio', to_char(a.inicio, 'HH24:MI'), 'fim', to_char(a.fim, 'HH24:MI'), 'banca', a.banca) end as antes,
           case when n.analise is null then null else json_build_object(
             'data', n.data, 'inicio', to_char(n.inicio, 'HH24:MI'), 'fim', to_char(n.fim, 'HH24:MI'), 'banca', n.banca) end as depois
      from pg_temp."TM_AGENDA_NOVA" n
      full join antes a on a.analise = n.analise
     where a.analise is null or n.analise is null
        or (a.data, a.inicio, a.fim, a.banca) is distinct from (n.data, n.inicio, n.fim, n.banca)
  )
  select count(*)::integer,
         coalesce((select jsonb_agg(jsonb_build_object('analise', x.analise, 'nome', an.candidato,
                                                       'antes', x.antes, 'depois', x.depois))
                     from (select * from mudou order by analise limit 500) x
                     left join public."TB_ANALISE_CURRICULAR" an on an.id = x.analise), '[]'::jsonb)
    into v_qt_alteracao, v_alteracoes
    from mudou;

  delete from public."TB_AGENDA_ENTREVISTA" where "CO_MONITORAMENTO" = p_edital;
  insert into public."TB_AGENDA_ENTREVISTA"
    ("CO_MONITORAMENTO", "CO_ANALISE_CURRICULAR", "DT_ENTREVISTA", "HR_INICIO", "HR_FIM", "NU_BANCA",
     "TP_ORIGEM", "NU_VERSAO_REGRA", "CO_LISTA_CLASSIFICACAO", "CO_USUARIO_ATUALIZACAO")
  select p_edital, t.analise, t.data, t.inicio, t.fim, t.banca, t.origem, v_regra."NU_VERSAO_VIGENTE", v_lista, v_uid
    from pg_temp."TM_AGENDA_NOVA" t;

  insert into public."TH_AGENDA_ENTREVISTA"
    ("CO_MONITORAMENTO", "TP_ACAO", "NU_VERSAO_REGRA", "CO_LISTA_CLASSIFICACAO", "QT_ITEM", "QT_ALTERACAO",
     "DS_ALTERACAO", "DS_MOTIVO", "CO_USUARIO")
  values (p_edital, v_acao, v_regra."NU_VERSAO_VIGENTE", v_lista, (select count(*) from pg_temp."TM_AGENDA_NOVA"),
          v_qt_alteracao, v_alteracoes, v_motivo, v_uid);

  drop table pg_temp."TM_AGENDA_NOVA";
  return private."FC_AGENDA_ENTREVISTA_JSON"(p_edital);
end;
$_$;

--
-- Name: FUNCTION salvar_agenda_entrevista(p_edital uuid, p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_agenda_entrevista(p_edital uuid, p_dados jsonb) IS 'Grava a agenda das entrevistas do edital inteira (substitui a anterior) e registra no histórico o que mudou. p_dados: {acao: GERAR|AJUSTAR|LIMPAR, itens: [{analise, data, inicio, fim, banca, origem}], versao_regra (a vigente, senão 40001), lista (convocação registrada, opcional), ultimo_registro (a última gravação que a tela viu, senão 40001), motivo?}. Recusa candidato repetido, fora do edital e mesma banca com horários sobrepostos (22023). Exige entrevistas ou classificacao >= editor, a área e o recorte da coordenação.';

--
-- Name: salvar_aldeias_dsei(text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_aldeias_dsei(p_unidade text, p_aldeias jsonb, p_fonte text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_unidade text := btrim(coalesce(p_unidade, ''));
  v_fonte text := btrim(coalesce(p_fonte, ''));
  v_uid uuid := (select auth.uid());
  v_desativadas integer;
  v_incluidas integer;
  v_reativadas integer;
  v_novas jsonb;
begin
  if not private.is_master() then
    raise exception 'Só o administrador global carrega a lista de aldeias' using errcode = '42501';
  end if;
  if v_unidade = '' or length(v_unidade) > 60
     or not exists (select 1 from public."TD_UNIDADE" u where u.id_unidade::text = v_unidade) then
    raise exception 'DSEI não encontrado no catálogo de unidades' using errcode = '22023';
  end if;
  if length(v_fonte) not between 3 and 300 then
    raise exception 'Informe a fonte da lista (3 a 300 caracteres).' using errcode = '22023';
  end if;
  if jsonb_typeof(p_aldeias) is distinct from 'array' or jsonb_array_length(p_aldeias) not between 1 and 3000
     or exists (select 1 from jsonb_array_elements(p_aldeias) a
                 where jsonb_typeof(a) <> 'string' or btrim(a #>> '{}') = '' or length(btrim(a #>> '{}')) > 230) then
    raise exception 'Envie de 1 a 3.000 aldeias, uma por texto ("NOME" ou "NOME-(polo)", até 230 caracteres).' using errcode = '22023';
  end if;

  -- A lista enviada, sem repetição: "NOME-(polo)" separa o polo.
  select jsonb_agg(jsonb_build_object(
           'exibicao', y.exibicao,
           'nome', left(btrim(coalesce(substring(y.exibicao from '^(.*)-\([^()]{1,20}\)$'), y.exibicao)), 200),
           'polo', substring(y.exibicao from '-\(([^()]{1,20})\)$')))
    into v_novas
    from (select distinct regexp_replace(btrim(a #>> '{}'), '\s+', ' ', 'g') as exibicao
            from jsonb_array_elements(p_aldeias) a) y;

  update public."TD_ALDEIA_DSEI" a
     set "ST_ATIVO" = 'N', "CO_USUARIO_ATUALIZACAO" = v_uid, "DT_ATUALIZACAO" = now()
   where a."CO_UNIDADE" = v_unidade and a."ST_ATIVO" = 'S'
     and not exists (select 1 from jsonb_to_recordset(v_novas) n(exibicao text, nome text, polo text)
                      where n.exibicao = a."NO_EXIBICAO");
  get diagnostics v_desativadas = row_count;
  update public."TD_ALDEIA_DSEI" a
     set "ST_ATIVO" = 'S', "DS_FONTE" = v_fonte, "CO_USUARIO_ATUALIZACAO" = v_uid, "DT_ATUALIZACAO" = now()
    from jsonb_to_recordset(v_novas) n(exibicao text, nome text, polo text)
   where a."CO_UNIDADE" = v_unidade and a."NO_EXIBICAO" = n.exibicao
     and (a."ST_ATIVO" = 'N' or a."DS_FONTE" is distinct from v_fonte);
  get diagnostics v_reativadas = row_count;
  insert into public."TD_ALDEIA_DSEI" ("CO_UNIDADE", "NO_ALDEIA", "CO_POLO", "NO_EXIBICAO", "DS_FONTE", "CO_USUARIO_ATUALIZACAO")
  select v_unidade, n.nome, n.polo, n.exibicao, v_fonte, v_uid
    from jsonb_to_recordset(v_novas) n(exibicao text, nome text, polo text)
   where not exists (select 1 from public."TD_ALDEIA_DSEI" a where a."CO_UNIDADE" = v_unidade and a."NO_EXIBICAO" = n.exibicao);
  get diagnostics v_incluidas = row_count;

  return json_build_object(
    'unidade', v_unidade,
    'ativas', (select count(*) from public."TD_ALDEIA_DSEI" a where a."CO_UNIDADE" = v_unidade and a."ST_ATIVO" = 'S'),
    'incluidas', v_incluidas, 'atualizadas', v_reativadas, 'desativadas', v_desativadas);
end;
$_$;

--
-- Name: FUNCTION salvar_aldeias_dsei(p_unidade text, p_aldeias jsonb, p_fonte text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_aldeias_dsei(p_unidade text, p_aldeias jsonb, p_fonte text) IS 'Carrega a lista oficial de aldeias de um DSEI (TD_UNIDADE.id_unidade): a lista enviada passa a ser a vigente; as que saíram são desativadas, as que voltaram são reativadas. "NOME-(polo)" separa o polo. Só o administrador global.';

--
-- Name: salvar_configuracao_convocacao(text, boolean, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_configuracao_convocacao(p_edital_id text, p_proporcionalidade boolean, p_modelo_id uuid, p_padrao_imediata integer, p_vagas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_edital text := btrim(p_edital_id);
  v_tipo text := case
    when coalesce(p_proporcionalidade, true) then 'COM_PROPORCIONALIDADE'
    else 'SEM_PROPORCIONALIDADE'
  end;
  v_total integer := 0;
begin
  perform private."FC_EXIGIR_AREA_EDITAL"(p_edital_id);
  if not (private.pode_recurso('importacao',2)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not private.pode_recurso('importacao',2) then
    raise exception 'Perfil sem permissao para configurar a convocacao';
  end if;
  if nullif(v_edital, '') is null then
    raise exception 'Edital nao informado';
  end if;
  if not exists (
    select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id::text = v_edital
  ) then
    raise exception 'Edital nao encontrado na Equipe Nucleo';
  end if;
  if p_modelo_id is not null and not exists (
    select 1 from public."TB_MODELO_CONVOCACAO" where "CO_MODELO" = p_modelo_id
  ) then
    raise exception 'Modelo de convocacao nao encontrado';
  end if;
  if p_vagas is not null and jsonb_typeof(p_vagas) <> 'array' then
    raise exception 'A lista de vagas precisa ser um arranjo';
  end if;

  insert into public."TB_CONVOCACAO_EDITAL"(
    "CO_EDITAL", "TP_CONVOCACAO", "CO_MODELO",
    "QT_PADRAO_IMEDIATA", "CO_USUARIO_ATUALIZACAO"
  ) values (
    v_edital, v_tipo, p_modelo_id,
    greatest(coalesce(p_padrao_imediata, 0), 0),
    (select auth.uid())
  )
  on conflict ("CO_EDITAL") do update
  set "TP_CONVOCACAO" = excluded."TP_CONVOCACAO",
      "CO_MODELO" = excluded."CO_MODELO",
      "QT_PADRAO_IMEDIATA" = excluded."QT_PADRAO_IMEDIATA",
      "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO",
      "DT_ATUALIZACAO" = now();

  delete from public."TB_VAGA_IMEDIATA" where "CO_EDITAL" = v_edital;

  if p_vagas is not null and jsonb_array_length(p_vagas) > 0 then
    insert into public."TB_VAGA_IMEDIATA"(
      "CO_EDITAL", "CO_VAGA", "NO_CARGO",
      "QT_VAGA_IMEDIATA", "ST_QUADRO_MANUAL", "DS_QUADRO_MANUAL",
      "CO_USUARIO_ATUALIZACAO"
    )
    select v_edital,
           btrim(x.codigo_vaga),
           nullif(btrim(x.cargo), ''),
           greatest(coalesce(x.imediatas, 0), 0),
           case when coalesce(x.manual, false) then 'S' else 'N' end,
           case when jsonb_typeof(coalesce(x.quadro, '{}'::jsonb)) = 'object'
                then coalesce(x.quadro, '{}'::jsonb) else '{}'::jsonb end,
           (select auth.uid())
    from jsonb_to_recordset(p_vagas) as x(
      codigo_vaga text,
      cargo text,
      imediatas integer,
      manual boolean,
      quadro jsonb
    )
    where nullif(btrim(x.codigo_vaga), '') is not null;
    get diagnostics v_total = row_count;
  end if;

  return jsonb_build_object(
    'ok', true,
    'edital_id', v_edital,
    'modelo_id', p_modelo_id,
    'vagas', v_total
  );
end;
$$;

--
-- Name: salvar_configuracoes_e_paineis_v2(jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_configuracoes_e_paineis_v2(p_config_rows jsonb, p_paineis jsonb, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
declare
  r jsonb;
  v_id uuid;
  v_config_antes jsonb;
  v_config_depois jsonb;
  v_paineis_antes jsonb;
  v_paineis_depois jsonb;
  v_alteracoes jsonb;
  v_total integer;
begin
  if not (private.pode_recurso('configuracoes',2)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not private.has_perm('config') then
    raise exception 'Sem permissao para salvar "TB_CONFIGURACAO"';
  end if;

  if not pg_try_advisory_xact_lock(hashtext('public.salvar_configuracoes_e_paineis_v2')::bigint) then
    raise exception 'Outra publicacao de "TB_CONFIGURACAO" esta em andamento. Aguarde e tente novamente.';
  end if;

  v_config_antes := private.snapshot_configuracoes();
  v_paineis_antes := private.snapshot_paineis_externos();
  v_alteracoes := private.diff_configuracoes_e_paineis(p_config_rows, p_paineis);
  v_total := jsonb_array_length(v_alteracoes);

  if v_total = 0 then
    return jsonb_build_object(
      'ok', true,
      'sem_alteracoes', true,
      'total_alteracoes', 0,
      'versao_id', null
    );
  end if;

  for r in select * from jsonb_array_elements(coalesce(p_config_rows, '[]'::jsonb)) loop
    if nullif(r ->> 'chave', '') is null then
      continue;
    end if;

    insert into public."TB_CONFIGURACAO"(chave, valor, descricao)
    values (r ->> 'chave', r ->> 'valor', r ->> 'descricao')
    on conflict (chave) do update
      set valor = excluded.valor,
          descricao = excluded.descricao,
          updated_at = now()
    where public."TB_CONFIGURACAO".valor is distinct from excluded.valor
       or public."TB_CONFIGURACAO".descricao is distinct from excluded.descricao;
  end loop;

  for r in select * from jsonb_array_elements(coalesce(p_paineis, '[]'::jsonb)) loop
    update public."TB_PAINEL_EXTERNO"
    set titulo = coalesce(nullif(r ->> 'titulo', ''), titulo),
        url = r ->> 'url',
        ativo = coalesce((r ->> 'ativo')::boolean, ativo),
        em_manutencao = coalesce((r ->> 'em_manutencao')::boolean, em_manutencao),
        updated_at = now()
    where id = nullif(r ->> 'id', '')::uuid
      and (
        titulo is distinct from coalesce(nullif(r ->> 'titulo', ''), titulo)
        or url is distinct from (r ->> 'url')
        or ativo is distinct from coalesce((r ->> 'ativo')::boolean, ativo)
        or em_manutencao is distinct from coalesce((r ->> 'em_manutencao')::boolean, em_manutencao)
      );
  end loop;

  v_config_depois := private.snapshot_configuracoes();
  v_paineis_depois := private.snapshot_paineis_externos();

  insert into public."TH_CONFIGURACAO"(
    acao,
    motivo,
    created_by,
    created_by_email,
    config_antes,
    config_depois,
    paineis_antes,
    paineis_depois,
    alteracoes,
    total_alteracoes
  ) values (
    'salvar',
    nullif(btrim(p_motivo), ''),
    auth.uid(),
    nullif(auth.jwt() ->> 'email', ''),
    v_config_antes,
    v_config_depois,
    v_paineis_antes,
    v_paineis_depois,
    v_alteracoes,
    v_total
  ) returning id into v_id;

  return jsonb_build_object(
    'ok', true,
    'sem_alteracoes', false,
    'total_alteracoes', v_total,
    'versao_id', v_id,
    'alteracoes', v_alteracoes,
    'salvo_em', now()
  );
end;
$$;

--
-- Name: salvar_coordenacao(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_coordenacao(p_coordenacao jsonb, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_codigo text := lower(btrim(coalesce(p_coordenacao ->> 'codigo', '')));
  v_nome text := btrim(coalesce(p_coordenacao ->> 'nome', ''));
  v_area text := btrim(coalesce(p_coordenacao ->> 'area', ''));
  v_responsavel text := nullif(upper(btrim(coalesce(p_coordenacao ->> 'responsavel', ''))), '');
  v_ativo boolean := coalesce((p_coordenacao ->> 'ativo')::boolean, true);
  v_atual public."TB_COORDENACAO";
  v_antes jsonb;
  v_unidade text;
  v_edital text;
begin
  if not private.is_master() then raise exception 'Somente administradores gerenciam coordenações' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then raise exception 'Informe um motivo entre 3 e 500 caracteres'; end if;
  if v_codigo !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'Código inválido: use letras minúsculas, números e hífen'; end if;
  if length(v_nome) not between 2 and 120 then raise exception 'Informe um nome entre 2 e 120 caracteres'; end if;
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then raise exception 'Área inválida'; end if;
  if v_responsavel is not null and v_responsavel not in ('USI', 'CORES') then raise exception 'Responsável inválido'; end if;
  if jsonb_typeof(coalesce(p_coordenacao -> 'unidades', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_coordenacao -> 'editais', '[]'::jsonb)) <> 'array' then
    raise exception 'Unidades e editais devem ser listas';
  end if;

  perform pg_advisory_xact_lock(73923124155);
  select * into v_atual from public."TB_COORDENACAO" where "CO_COORDENACAO" = v_codigo for update;
  if v_atual."CO_COORDENACAO" is not null then
    if (p_coordenacao ->> 'revisao') is null or (p_coordenacao ->> 'revisao')::integer <> v_atual."NU_REVISAO" then
      raise exception 'Coordenação alterada por outra pessoa. Recarregue.' using errcode = 'PT409';
    end if;
    if not v_ativo and exists (select 1 from public."TB_PERFIL_USUARIO" u where u."CO_COORDENACAO" = v_codigo and u.ativo) then
      raise exception 'Há usuários nesta coordenação. Mude-os de coordenação antes de desativar.';
    end if;
    v_antes := private."FC_COORDENACAO_JSON"(v_codigo);
    update public."TB_COORDENACAO"
       set "NO_COORDENACAO" = v_nome, "CO_AREA" = v_area, "TP_RESPONSAVEL" = v_responsavel, "ST_ATIVO" = v_ativo,
           "NU_REVISAO" = "NU_REVISAO" + 1, "DT_ATUALIZACAO" = now()
     where "CO_COORDENACAO" = v_codigo;
  else
    if (p_coordenacao ->> 'revisao') is not null then raise exception 'Coordenação não encontrada. Recarregue.' using errcode = 'PT409'; end if;
    insert into public."TB_COORDENACAO" ("CO_COORDENACAO", "NO_COORDENACAO", "CO_AREA", "TP_RESPONSAVEL", "ST_ATIVO")
    values (v_codigo, v_nome, v_area, v_responsavel, v_ativo);
  end if;

  delete from public."RL_COORDENACAO_UNIDADE" where "CO_COORDENACAO" = v_codigo;
  for v_unidade in select distinct btrim(value) from jsonb_array_elements_text(coalesce(p_coordenacao -> 'unidades', '[]'::jsonb)) where btrim(value) <> '' loop
    if private."FC_AREA_DA_UNIDADE"(v_unidade) is distinct from v_area then
      raise exception 'A unidade % não é da área escolhida', v_unidade;
    end if;
    insert into public."RL_COORDENACAO_UNIDADE" ("CO_COORDENACAO", "NO_UNIDADE") values (v_codigo, v_unidade);
  end loop;

  delete from public."RL_COORDENACAO_EDITAL" where "CO_COORDENACAO" = v_codigo;
  for v_edital in select distinct value from jsonb_array_elements_text(coalesce(p_coordenacao -> 'editais', '[]'::jsonb)) loop
    if not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id::text = v_edital and m."CO_AREA" = v_area) then
      raise exception 'Edital % não encontrado nesta área', v_edital;
    end if;
    insert into public."RL_COORDENACAO_EDITAL" ("CO_COORDENACAO", "CO_EDITAL") values (v_codigo, v_edital::uuid);
  end loop;

  insert into public."TH_COORDENACAO" ("CO_COORDENACAO", "JS_ANTES", "JS_DEPOIS", "CO_ALTERADO_POR", "DS_MOTIVO")
  values (v_codigo, v_antes, private."FC_COORDENACAO_JSON"(v_codigo), (select auth.uid()), btrim(p_motivo));
  return private."FC_COORDENACAO_JSON"(v_codigo);
end;
$_$;

--
-- Name: salvar_coordenada_mapa_projetos(text, double precision, double precision, double precision, double precision, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_coordenada_mapa_projetos(p_lugar text, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_conferido boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null or not private."FC_PODE_EDITAR_COORDENADA"() then
    raise exception using errcode = '42501', message = 'Somente administrador ou gestor pode corrigir coordenadas.';
  end if;
  return private."FC_APLICAR_COORDENADA_LOCAL"(
    p_lugar, p_latitude, p_longitude, p_latitude_anterior, p_longitude_anterior, p_motivo,
    case when coalesce(p_conferido, false) then 'CONFERENCIA' else 'CORRECAO' end,
    case when coalesce(p_conferido, false) then 'S' end,
    null);
end;
$$;

--
-- Name: FUNCTION salvar_coordenada_mapa_projetos(p_lugar text, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_conferido boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_coordenada_mapa_projetos(p_lugar text, p_latitude double precision, p_longitude double precision, p_latitude_anterior double precision, p_longitude_anterior double precision, p_motivo text, p_conferido boolean) IS 'Corrige a coordenada de um lugar do mapa de Projetos (cria a linha se o lugar ainda não tinha) e/ou, com p_conferido, marca o lugar pendente como conferido (a posição pode ficar igual). Só administrador global ou gestor; confere a posição anterior e registra o histórico privado.';

