--
-- Name: salvar_demanda_interna(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_demanda_interna(p_demanda jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
declare
  v_usuario uuid := (select auth.uid());
  v_id uuid;
  v_area text;
  v_edital uuid;
  v_titulo text;
  v_descricao text;
  v_inicio date;
  v_fim date;
  v_responsaveis uuid[];
  v_atual public."TB_DEMANDA_INTERNA";
  v_antes jsonb;
  v_depois jsonb;
begin
  if v_usuario is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;
  if jsonb_typeof(p_demanda) is distinct from 'object' then
    raise exception 'Demanda inválida.' using errcode = '22023';
  end if;
  if p_demanda ? 'responsaveis' and jsonb_typeof(p_demanda -> 'responsaveis') not in ('array', 'null') then
    raise exception 'Responsáveis inválidos.' using errcode = '22023';
  end if;

  begin
    v_id := nullif(btrim(p_demanda ->> 'id'), '')::uuid;
    v_edital := nullif(btrim(p_demanda ->> 'edital_id'), '')::uuid;
    v_inicio := nullif(btrim(p_demanda ->> 'data_inicio'), '')::date;
    v_fim := coalesce(nullif(btrim(p_demanda ->> 'data_fim'), '')::date, v_inicio);
    select coalesce(array_agg(distinct x::uuid), '{}')
      into v_responsaveis
      from jsonb_array_elements_text(
             case when jsonb_typeof(p_demanda -> 'responsaveis') = 'array'
                  then p_demanda -> 'responsaveis' else '[]'::jsonb end) x;
  exception when invalid_text_representation or invalid_datetime_format
                 or datetime_field_overflow then
    raise exception 'Demanda com campo inválido (id, edital, data ou responsável).' using errcode = '22023';
  end;

  v_area := nullif(btrim(p_demanda ->> 'area'), '');
  v_titulo := nullif(btrim(regexp_replace(coalesce(p_demanda ->> 'titulo', ''), '\s+', ' ', 'g')), '');
  v_descricao := nullif(btrim(p_demanda ->> 'descricao'), '');

  if v_area is null or not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
    raise exception 'Informe a área da demanda.' using errcode = '22023';
  end if;
  if v_titulo is null or length(v_titulo) < 3 or length(v_titulo) > 200 then
    raise exception 'O título precisa ter de 3 a 200 caracteres.' using errcode = '22023';
  end if;
  if length(coalesce(v_descricao, '')) > 2000 then
    raise exception 'A descrição pode ter até 2.000 caracteres.' using errcode = '22023';
  end if;
  if v_inicio is null then
    raise exception 'Informe a data da demanda.' using errcode = '22023';
  end if;
  if v_fim < v_inicio then
    raise exception 'O fim não pode ser antes do início.' using errcode = '22023';
  end if;
  if v_inicio < date '2020-01-01' or v_fim > date '2100-12-31' then
    raise exception 'Data fora do intervalo aceito.' using errcode = '22023';
  end if;
  if cardinality(v_responsaveis) > 20 then
    raise exception 'No máximo 20 responsáveis.' using errcode = '22023';
  end if;

  if not private."FC_PODE_EDITAR_CRONOGRAMA_AREA"(v_area) then
    raise exception 'Sem permissão para demandas desta área.' using errcode = '42501';
  end if;
  if v_edital is not null then
    if not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m
                    where m.id = v_edital and m."CO_AREA" = v_area) then
      raise exception 'O edital não é desta área.' using errcode = '22023';
    end if;
    if not private."FC_PODE_EDITAR_DEMANDA"(v_area, v_edital) then
      raise exception 'Sem acesso a este edital.' using errcode = '42501';
    end if;
  end if;

  if v_id is not null then
    select * into v_atual from public."TB_DEMANDA_INTERNA" d
     where d."CO_DEMANDA_INTERNA" = v_id for update;
    if v_atual."CO_DEMANDA_INTERNA" is null or v_atual."ST_ATIVO" <> 'S' then
      raise exception 'Demanda não encontrada.' using errcode = 'P0002';
    end if;
    if not private."FC_PODE_EDITAR_DEMANDA"(v_atual."CO_AREA", v_atual."CO_MONITORAMENTO") then
      raise exception 'Sem permissão para esta demanda.' using errcode = '42501';
    end if;
    v_antes := private."FC_DEMANDA_INTERNA_JSON"(v_id);
  end if;

  if exists (select 1 from unnest(v_responsaveis) r
              where not private."FC_PERFIL_PODE_SER_RESPONSAVEL"(r, v_area, v_edital)) then
    raise exception 'Há responsável sem acesso à área ou ao edital da demanda.' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public."TB_DEMANDA_INTERNA" (
      "CO_AREA", "CO_MONITORAMENTO", "NO_DEMANDA", "DS_DEMANDA", "DT_INICIO", "DT_FIM",
      "CO_USUARIO_CRIACAO", "CO_USUARIO_ATUALIZACAO")
    values (v_area, v_edital, v_titulo, v_descricao, v_inicio, v_fim, v_usuario, v_usuario)
    returning "CO_DEMANDA_INTERNA" into v_id;
  else
    update public."TB_DEMANDA_INTERNA" d
       set "CO_AREA" = v_area,
           "CO_MONITORAMENTO" = v_edital,
           "NO_DEMANDA" = v_titulo,
           "DS_DEMANDA" = v_descricao,
           "DT_INICIO" = v_inicio,
           "DT_FIM" = v_fim,
           "CO_USUARIO_ATUALIZACAO" = v_usuario,
           "DT_ATUALIZACAO" = now()
     where d."CO_DEMANDA_INTERNA" = v_id;
  end if;

  delete from public."RL_DEMANDA_INTERNA_RESPONSAVEL" r
   where r."CO_DEMANDA_INTERNA" = v_id and not (r."CO_PERFIL_USUARIO" = any (v_responsaveis));
  insert into public."RL_DEMANDA_INTERNA_RESPONSAVEL" ("CO_DEMANDA_INTERNA", "CO_PERFIL_USUARIO", "CO_USUARIO_INCLUSAO")
  select v_id, r, v_usuario from unnest(v_responsaveis) r
  on conflict do nothing;

  v_depois := private."FC_DEMANDA_INTERNA_JSON"(v_id);
  if v_antes is null or v_antes is distinct from v_depois then
    insert into public."TH_DEMANDA_INTERNA" ("CO_DEMANDA_INTERNA", "TP_ACAO", "DS_ANTES", "DS_DEPOIS", "CO_USUARIO")
    values (v_id, case when v_antes is null then 'CRIACAO' else 'EDICAO' end, v_antes, v_depois, v_usuario);
  end if;

  return v_depois || jsonb_build_object('pode_editar', true);
end;
$$;

--
-- Name: FUNCTION salvar_demanda_interna(p_demanda jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_demanda_interna(p_demanda jsonb) IS 'Cria (sem id) ou edita uma demanda interna: {id?, area, edital_id?, titulo, descricao?, data_inicio, data_fim?, responsaveis: [perfil]}. Gestor da área ou administrador global; grava TH_DEMANDA_INTERNA. 20261104120000.';

--
-- Name: salvar_equipe_edital(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_equipe_edital(p_edital uuid, p_equipe jsonb, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_uid uuid := (select auth.uid());
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_item record;
  v_usuario uuid;
  v_papel text;
  v_vaga text;
  v_limite integer;
  v_perfil public."TB_PERFIL_USUARIO";
  v_nivel integer;
  v_nome text;
  v_chaves text[] := '{}';
  v_chave text;
  v_saem integer;
  v_novos jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(p_equipe) is distinct from 'array' or jsonb_array_length(p_equipe) > 300 then
    raise exception 'Envie a equipe como lista (até 300 linhas).' using errcode = '22023';
  end if;
  if v_motivo is not null and length(v_motivo) > 500 then
    raise exception 'Motivo com até 500 caracteres.' using errcode = '22023';
  end if;

  for v_item in select e.value, e.ordinality from jsonb_array_elements(p_equipe) with ordinality e loop
    if jsonb_typeof(v_item.value) <> 'object'
       or coalesce(v_item.value ->> 'usuario', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'Linha %: escolha a pessoa.', v_item.ordinality using errcode = '22023';
    end if;
    v_usuario := (v_item.value ->> 'usuario')::uuid;
    v_papel := upper(coalesce(v_item.value ->> 'papel', ''));
    if v_papel not in ('ANALISTA', 'REVISOR', 'COORDENADOR') then
      raise exception 'Linha %: papel ANALISTA, REVISOR ou COORDENADOR.', v_item.ordinality using errcode = '22023';
    end if;
    v_vaga := nullif(btrim(coalesce(v_item.value ->> 'vaga', '')), '');
    if v_vaga is not null and v_vaga !~ '^[0-9]{1,20}$' then
      raise exception 'Linha %: código da vaga só com dígitos.', v_item.ordinality using errcode = '22023';
    end if;
    if v_papel = 'COORDENADOR' and v_vaga is not null then
      raise exception 'Linha %: a coordenação é do edital todo, sem vaga.', v_item.ordinality using errcode = '22023';
    end if;
    if coalesce(jsonb_typeof(v_item.value -> 'limite'), 'null') <> 'null' then
      if not private."FC_JSON_NUMERO_OBRIGATORIO"(v_item.value -> 'limite', 1, 5000) or (v_item.value ->> 'limite')::numeric % 1 <> 0 then
        raise exception 'Linha %: limite de fichas de 1 a 5.000.', v_item.ordinality using errcode = '22023';
      end if;
      v_limite := (v_item.value ->> 'limite')::integer;
    else
      v_limite := null;
    end if;

    select * into v_perfil from public."TB_PERFIL_USUARIO" u where u.user_id = v_usuario;
    v_nome := coalesce(v_perfil.nome, v_perfil.email, 'a pessoa da linha ' || v_item.ordinality);
    if v_perfil.id is null or v_perfil.ativo is not true then
      raise exception '%: conta inexistente ou desativada.', v_nome using errcode = '22023';
    end if;
    v_nivel := private."FC_NIVEL_AVALIACAO_DO_PERFIL"(v_perfil.id);
    if v_papel in ('ANALISTA', 'REVISOR') and v_nivel < 2 then
      raise exception '% não tem Editor em Avaliação documental (tem %); peça em Configurações › Acessos.', v_nome,
        case v_nivel when 1 then 'Leitor' else 'Sem acesso' end using errcode = '42501';
    end if;
    if v_papel = 'COORDENADOR' and v_nivel < 3 then
      raise exception '% não tem Administrador em Avaliação documental (tem %); peça em Configurações › Acessos.', v_nome,
        case v_nivel when 2 then 'Editor' when 1 then 'Leitor' else 'Sem acesso' end using errcode = '42501';
    end if;
    if not private."FC_PERFIL_VE_EDITAL"(v_perfil.id, p_edital) then
      raise exception '% não vê este edital (área ou coordenação).', v_nome using errcode = '42501';
    end if;
    if v_papel = 'COORDENADOR' and private."FC_GESTOR_DO_EDITAL"(v_perfil.id, p_edital) then
      raise exception '% é gestor do edital e já coordena.', v_nome using errcode = '22023';
    end if;
    v_chave := v_usuario::text || '|' || v_papel || '|' || coalesce(v_vaga, '');
    if v_chave = any (v_chaves) then
      raise exception 'Linha %: repetida.', v_item.ordinality using errcode = '22023';
    end if;
    v_chaves := v_chaves || v_chave;
    v_novos := v_novos || jsonb_build_object('usuario', v_usuario, 'papel', v_papel, 'vaga', v_vaga, 'limite', v_limite);
  end loop;

  select count(*) into v_saem
    from public."RL_ANALISTA_EDITAL" r
   where r."CO_MONITORAMENTO" = p_edital and r."ST_ATIVO" = 'S'
     and not exists (select 1 from jsonb_to_recordset(v_novos) n(usuario uuid, papel text, vaga text, limite integer)
                      where n.usuario = r."CO_USUARIO" and n.papel = r."TP_PAPEL"
                        and coalesce(n.vaga, '') = coalesce(r."CO_VAGA", ''));
  if v_saem > 0 and (v_motivo is null or length(v_motivo) < 10) then
    raise exception 'Informe o motivo para tirar % pessoa(s) da equipe (10 a 500 caracteres).', v_saem using errcode = '22023';
  end if;

  -- Quem sai: desativa (a linha fica). As fichas em análise de quem sai são tratadas na fase F3.
  update public."RL_ANALISTA_EDITAL" r
     set "ST_ATIVO" = 'N', "DS_MOTIVO_ATUALIZACAO" = v_motivo, "CO_USUARIO_ATUALIZACAO" = v_uid, "DT_ATUALIZACAO" = now()
   where r."CO_MONITORAMENTO" = p_edital and r."ST_ATIVO" = 'S'
     and not exists (select 1 from jsonb_to_recordset(v_novos) n(usuario uuid, papel text, vaga text, limite integer)
                      where n.usuario = r."CO_USUARIO" and n.papel = r."TP_PAPEL"
                        and coalesce(n.vaga, '') = coalesce(r."CO_VAGA", ''));
  -- Quem fica: só o limite pode mudar.
  update public."RL_ANALISTA_EDITAL" r
     set "QT_LIMITE_FICHA" = n.limite, "DS_MOTIVO_ATUALIZACAO" = coalesce(v_motivo, r."DS_MOTIVO_ATUALIZACAO"),
         "CO_USUARIO_ATUALIZACAO" = v_uid, "DT_ATUALIZACAO" = now()
    from jsonb_to_recordset(v_novos) n(usuario uuid, papel text, vaga text, limite integer)
   where r."CO_MONITORAMENTO" = p_edital and r."ST_ATIVO" = 'S'
     and n.usuario = r."CO_USUARIO" and n.papel = r."TP_PAPEL" and coalesce(n.vaga, '') = coalesce(r."CO_VAGA", '')
     and r."QT_LIMITE_FICHA" is distinct from n.limite;
  -- Quem entra.
  insert into public."RL_ANALISTA_EDITAL"
    ("CO_MONITORAMENTO", "CO_USUARIO", "TP_PAPEL", "CO_VAGA", "QT_LIMITE_FICHA", "DS_MOTIVO_ATUALIZACAO", "CO_USUARIO_ATUALIZACAO")
  select p_edital, n.usuario, n.papel, n.vaga, n.limite, v_motivo, v_uid
    from jsonb_to_recordset(v_novos) n(usuario uuid, papel text, vaga text, limite integer)
   where not exists (select 1 from public."RL_ANALISTA_EDITAL" r
                      where r."CO_MONITORAMENTO" = p_edital and r."ST_ATIVO" = 'S'
                        and r."CO_USUARIO" = n.usuario and r."TP_PAPEL" = n.papel
                        and coalesce(r."CO_VAGA", '') = coalesce(n.vaga, ''));

  return public.obter_equipe_edital(p_edital);
end;
$_$;

--
-- Name: FUNCTION salvar_equipe_edital(p_edital uuid, p_equipe jsonb, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_equipe_edital(p_edital uuid, p_equipe jsonb, p_motivo text) IS 'Grava a equipe da avaliação documental do edital. p_equipe = a lista inteira [{usuario, papel, vaga, limite}]: quem não está mais é desativado (motivo obrigatório, 10 a 500), quem entra é incluído e quem fica pode mudar o limite. Analista e revisor precisam de Editor em avaliacao_documental; coordenador, de Administrador (a mensagem diz qual permissão falta, 42501); todos precisam ver o edital; o gestor do edital já coordena. Só a coordenação do edital.';

--
-- Name: salvar_filtro_fila(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_filtro_fila(p_nome text, p_filtro jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_nome text := btrim(coalesce(p_nome, ''));
begin
  if v_uid is null or not private.pode_recurso('avaliacao_documental', 1) then
    raise exception 'Sem permissão para a Avaliação documental' using errcode = '42501';
  end if;
  if length(v_nome) not between 1 and 60 then
    raise exception 'Nome do filtro de 1 a 60 caracteres.' using errcode = '22023';
  end if;
  if jsonb_typeof(p_filtro) is distinct from 'object' or length(p_filtro::text) > 2000 then
    raise exception 'Filtro inválido.' using errcode = '22023';
  end if;
  update public."TB_FILTRO_FILA_ANALISE" set "DS_FILTRO" = p_filtro, "NO_FILTRO" = v_nome, "DT_ATUALIZACAO" = now()
   where "CO_USUARIO" = v_uid and "ST_ATIVO" = 'S' and lower(btrim("NO_FILTRO")) = lower(v_nome);
  if not found then
    if (select count(*) from public."TB_FILTRO_FILA_ANALISE" where "CO_USUARIO" = v_uid and "ST_ATIVO" = 'S') >= 30 then
      raise exception 'Até 30 filtros salvos: exclua um antes.' using errcode = '22023';
    end if;
    insert into public."TB_FILTRO_FILA_ANALISE" ("CO_USUARIO", "NO_FILTRO", "DS_FILTRO") values (v_uid, v_nome, p_filtro);
  end if;
  return private."FC_FILTROS_FILA_JSON"(v_uid);
end;
$$;

--
-- Name: FUNCTION salvar_filtro_fila(p_nome text, p_filtro jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_filtro_fila(p_nome text, p_filtro jsonb) IS 'Salva (ou troca, pelo mesmo nome) um filtro da fila de quem chama; até 30 por pessoa. Devolve os filtros salvos. Exige avaliacao_documental >= leitor.';

--
-- Name: salvar_grupo_acesso(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_grupo_acesso(p_grupo jsonb, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_codigo text := lower(btrim(coalesce(p_grupo ->> 'codigo', '')));
  v_nome text := btrim(coalesce(p_grupo ->> 'nome', ''));
  v_niveis jsonb := coalesce(p_grupo -> 'niveis', '{}'::jsonb);
  v_atual public."TB_GRUPO_ACESSO";
  v_antes jsonb;
  v_recurso text;
  v_nivel text;
begin
  if not private.is_master() then raise exception 'Somente administradores gerenciam grupos' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then raise exception 'Informe um motivo entre 3 e 500 caracteres'; end if;
  if v_codigo !~ '^[a-z]+(_[a-z]+)*$' then raise exception 'Código inválido: use letras minúsculas e _'; end if;
  if length(v_nome) not between 2 and 80 then raise exception 'Informe um nome entre 2 e 80 caracteres'; end if;
  if jsonb_typeof(v_niveis) <> 'object' then raise exception 'Níveis inválidos'; end if;

  perform pg_advisory_xact_lock(73923124154);
  select * into v_atual from public."TB_GRUPO_ACESSO" where "CO_GRUPO_ACESSO" = v_codigo for update;
  if v_atual."CO_GRUPO_ACESSO" is not null then
    if v_atual."ST_ADMIN_GLOBAL" then raise exception 'O grupo de administrador global não é editável'; end if;
    if (p_grupo ->> 'revisao') is null or (p_grupo ->> 'revisao')::integer <> v_atual."NU_REVISAO" then
      raise exception 'Grupo alterado por outra pessoa. Recarregue.' using errcode = 'PT409';
    end if;
    v_antes := private."FC_GRUPO_ACESSO_JSON"(v_codigo);
    update public."TB_GRUPO_ACESSO"
       set "NO_GRUPO_ACESSO" = v_nome,
           "DS_GRUPO_ACESSO" = nullif(btrim(coalesce(p_grupo ->> 'descricao', '')), ''),
           "NU_ORDEM" = coalesce((p_grupo ->> 'ordem')::smallint, "NU_ORDEM"),
           "NU_REVISAO" = "NU_REVISAO" + 1,
           "DT_ATUALIZACAO" = now()
     where "CO_GRUPO_ACESSO" = v_codigo;
  else
    if (p_grupo ->> 'revisao') is not null then raise exception 'Grupo não encontrado. Recarregue.' using errcode = 'PT409'; end if;
    insert into public."TB_GRUPO_ACESSO" ("CO_GRUPO_ACESSO", "NO_GRUPO_ACESSO", "DS_GRUPO_ACESSO", "NU_ORDEM")
    values (v_codigo, v_nome, nullif(btrim(coalesce(p_grupo ->> 'descricao', '')), ''), coalesce((p_grupo ->> 'ordem')::smallint, 100));
  end if;

  -- Todo módulo tem nível no grupo; o que não veio fica sem acesso.
  delete from public."TA_GRUPO_ACESSO_RECURSO" where "CO_GRUPO_ACESSO" = v_codigo;
  foreach v_recurso in array private."FC_RECURSOS_MODULO"() loop
    v_nivel := coalesce(v_niveis ->> v_recurso, 'sem_acesso');
    insert into public."TA_GRUPO_ACESSO_RECURSO" ("CO_GRUPO_ACESSO", "NO_RECURSO", "TP_NIVEL") values (v_codigo, v_recurso, v_nivel);
  end loop;

  insert into public."TH_GRUPO_ACESSO" ("CO_GRUPO_ACESSO", "JS_ANTES", "JS_DEPOIS", "CO_ALTERADO_POR", "DS_MOTIVO")
  values (v_codigo, v_antes, private."FC_GRUPO_ACESSO_JSON"(v_codigo), (select auth.uid()), btrim(p_motivo));
  return private."FC_GRUPO_ACESSO_JSON"(v_codigo);
end;
$_$;

--
-- Name: salvar_hora_nascimento_candidato(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_hora_nascimento_candidato(p_edital uuid, p_analise uuid, p_hora text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_area text := private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 2);
  v_uid uuid := (select auth.uid());
  v_texto text := nullif(btrim(coalesce(p_hora, '')), '');
  v_hora time(0);
  v_anterior time(0);
begin
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  if not exists (
    select 1
      from public."TB_ANALISE_CURRICULAR" a
      join public."TB_MONITORAMENTO_INDIGENA" m on m.id = p_edital
     where a.id = p_analise and a.ativo and a."CO_AREA" = v_area
       and private."FC_NUMERO_EDITAL"(a.edital) = private."FC_NUMERO_EDITAL"(m.edital)) then
    raise exception 'A análise não é deste edital' using errcode = '22023';
  end if;
  if v_texto is not null then
    if v_texto !~ '^([01]?[0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' then
      raise exception 'Hora inválida: use HH:MM ou HH:MM:SS (00:00 a 23:59:59)' using errcode = '22023';
    end if;
    v_hora := v_texto::time(0);
  end if;

  select h."HR_NASCIMENTO" into v_anterior
    from public."TB_HORA_NASCIMENTO_CANDIDATO" h
   where h."CO_ANALISE_CURRICULAR" = p_analise
   for update;

  if v_anterior is not distinct from v_hora then
    return json_build_object('analise_id', p_analise, 'hora_nascimento', to_char(v_hora, 'HH24:MI:SS'), 'mudou', false);
  end if;
  if v_hora is null then
    delete from public."TB_HORA_NASCIMENTO_CANDIDATO" where "CO_ANALISE_CURRICULAR" = p_analise;
  else
    insert into public."TB_HORA_NASCIMENTO_CANDIDATO"
      ("CO_ANALISE_CURRICULAR", "CO_MONITORAMENTO", "HR_NASCIMENTO", "CO_USUARIO_ATUALIZACAO", "DT_ATUALIZACAO")
    values (p_analise, p_edital, v_hora, v_uid, now())
    on conflict ("CO_ANALISE_CURRICULAR") do update
      set "CO_MONITORAMENTO" = excluded."CO_MONITORAMENTO", "HR_NASCIMENTO" = excluded."HR_NASCIMENTO",
          "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO", "DT_ATUALIZACAO" = excluded."DT_ATUALIZACAO";
  end if;
  insert into public."TH_HORA_NASCIMENTO_CANDIDATO"
    ("CO_ANALISE_CURRICULAR", "CO_MONITORAMENTO", "HR_ANTERIOR", "HR_NOVA", "CO_USUARIO")
  values (p_analise, p_edital, v_anterior, v_hora, v_uid);

  return json_build_object('analise_id', p_analise, 'hora_nascimento', to_char(v_hora, 'HH24:MI:SS'), 'mudou', true);
end;
$_$;

--
-- Name: FUNCTION salvar_hora_nascimento_candidato(p_edital uuid, p_analise uuid, p_hora text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_hora_nascimento_candidato(p_edital uuid, p_analise uuid, p_hora text) IS 'Grava, troca ou tira (p_hora vazio: volta a valer 23:59:59) a hora de nascimento da certidão de um candidato, para o desempate por maior idade (93/2026, 6.11.5 e 6.11.6). Classificação editor, a área e o recorte do edital (42501); a análise tem de ser do edital e a hora HH:MM[:SS] (22023). Histórico em TH_HORA_NASCIMENTO_CANDIDATO. Devolve {analise_id, hora_nascimento, mudou}.';

--
-- Name: salvar_matriz_acessos(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_matriz_acessos(p_alteracoes jsonb, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gestor text := private."FC_EXIGIR_GESTOR_DE_ACESSOS"();
  item jsonb; alvo public."TB_PERFIL_USUARIO"; v_tipo text; v_sem_area text;
  anterior text; revisao_atual integer; recurso_atual text; novo text; v_nivel_grupo text;
  quantidade integer := 0;
begin
  if jsonb_typeof(p_alteracoes) is distinct from 'array' or jsonb_array_length(p_alteracoes) not between 1 and 500 then raise exception 'Alterações inválidas'; end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then raise exception 'Informe um motivo entre 3 e 500 caracteres'; end if;
  -- Serializa inserções de linhas ausentes e updates; a revisão evita perda de alteração.
  perform pg_advisory_xact_lock(73923124153);
  for item in select value from jsonb_array_elements(p_alteracoes) loop
    select * into alvo from public."TB_PERFIL_USUARIO" where id = (item ->> 'usuario_id')::uuid and ativo for update;
    perform private."FC_EXIGIR_GESTAO_DO_USUARIO"(alvo);
    v_tipo := coalesce(item ->> 'tipo', 'nivel');

    -- Grupo de acesso ----------------------------------------------------------
    if v_tipo = 'grupo' then
      novo := item ->> 'grupo';
      if not exists (select 1 from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = novo) then raise exception 'Grupo inválido'; end if;
      if item ->> 'revisao' is distinct from alvo.updated_at::text and alvo.updated_at <> now() then
        raise exception 'Conta alterada por outra pessoa. Recarregue a matriz.' using errcode = 'PT409';
      end if;
      if not private."FC_GRUPO_CABE_NO_TETO"(novo) then
        raise exception 'O grupo % dá mais acesso do que você tem', novo using errcode = '42501';
      end if;
      if alvo.perfil = novo then continue; end if;
      anterior := alvo.perfil;
      update public."TB_PERFIL_USUARIO"
         set perfil = novo,
             "CO_COORDENACAO" = case when exists (select 1 from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = novo and a."ST_ADMIN_GLOBAL")
                                     then null else "CO_COORDENACAO" end,
             p_config = exists (select 1 from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = novo and a."ST_ADMIN_GLOBAL"),
             p_admin = exists (select 1 from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = novo and a."ST_ADMIN_GLOBAL"),
             updated_at = now()
       where id = alvo.id;
      insert into public."TH_PERMISSAO_RECURSO"(perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
      values (alvo.id, '#grupo', anterior, novo, (select auth.uid()), btrim(p_motivo));
      quantidade := quantidade + 1;
      continue;
    end if;

    -- Coordenação (só admin) --------------------------------------------------------
    if v_tipo = 'coordenacao' then
      if v_gestor <> 'admin' then raise exception 'Só o administrador muda a coordenação de alguém' using errcode = '42501'; end if;
      novo := nullif(btrim(coalesce(item ->> 'coordenacao', '')), '');
      if item ->> 'revisao' is distinct from alvo.updated_at::text and alvo.updated_at <> now() then
        raise exception 'Conta alterada por outra pessoa. Recarregue a matriz.' using errcode = 'PT409';
      end if;
      if novo is not null and not exists (select 1 from public."TB_COORDENACAO" c where c."CO_COORDENACAO" = novo and c."ST_ATIVO") then
        raise exception 'Coordenação inválida ou desativada';
      end if;
      if novo is not null and exists (select 1 from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = alvo.perfil and a."ST_ADMIN_GLOBAL") then
        raise exception 'Administrador global não fica em coordenação';
      end if;
      if alvo."CO_COORDENACAO" is not distinct from novo then continue; end if;
      anterior := coalesce(alvo."CO_COORDENACAO", '(sem coordenação)');
      update public."TB_PERFIL_USUARIO" set "CO_COORDENACAO" = novo, updated_at = now() where id = alvo.id;
      insert into public."TH_PERMISSAO_RECURSO"(perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
      values (alvo.id, '#coordenacao', anterior, coalesce(novo, '(sem coordenação)'), (select auth.uid()), btrim(p_motivo));
      quantidade := quantidade + 1;
      continue;
    end if;

    if v_tipo <> 'nivel' then raise exception 'Tipo de alteração inválido'; end if;
    recurso_atual := item ->> 'recurso';
    novo := item ->> 'nivel';

    -- Área (só admin) ---------------------------------------------------------------
    if recurso_atual like 'area:%' then
      if v_gestor <> 'admin' then raise exception 'Só o administrador muda as áreas de alguém' using errcode = '42501'; end if;
      if not exists (select 1 from public."TB_AREA" a where 'area:' || a."CO_AREA" = recurso_atual) then raise exception 'Área inválida'; end if;
      if novo is null or novo not in ('sem_acesso', 'leitor') then raise exception 'Área aceita apenas Sim ou Não'; end if;
      if exists (select 1 from public."TB_GRUPO_ACESSO" a where a."CO_GRUPO_ACESSO" = alvo.perfil and a."ST_ADMIN_GLOBAL") then
        raise exception 'Administrador já vê todas as áreas';
      end if;
      anterior := case when exists (select 1 from public."RL_PERFIL_USUARIO_AREA" x
                                     where x."CO_PERFIL_USUARIO" = alvo.id and 'area:' || x."CO_AREA" = recurso_atual)
                       then 'leitor' else 'sem_acesso' end;
      if anterior = novo then continue; end if;
      if novo = 'leitor' then
        insert into public."RL_PERFIL_USUARIO_AREA"("CO_PERFIL_USUARIO", "CO_AREA") values (alvo.id, substr(recurso_atual, 6));
      else
        delete from public."RL_PERFIL_USUARIO_AREA" where "CO_PERFIL_USUARIO" = alvo.id and "CO_AREA" = substr(recurso_atual, 6);
      end if;
      insert into public."TH_PERMISSAO_RECURSO"(perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
      values (alvo.id, recurso_atual, anterior, novo, (select auth.uid()), btrim(p_motivo));
      quantidade := quantidade + 1;
      continue;
    end if;

    -- Módulo ou painel ------------------------------------------------------------------
    if recurso_atual is null or (recurso_atual <> all (private."FC_RECURSOS_MODULO"())
        and not exists (select 1 from public."TB_PAINEL_EXTERNO" where 'painel:' || id = recurso_atual and ativo)) then
      raise exception 'Recurso inválido';
    end if;
    if novo is not null and novo not in ('sem_acesso', 'leitor', 'editor', 'admin') then raise exception 'Nível inválido'; end if;
    if recurso_atual = 'configuracoes' and novo = 'leitor' then raise exception 'Configurações exige Editor ou Administrador'; end if;
    if recurso_atual = 'acessos' and novo not in ('sem_acesso', 'editor') then raise exception 'Acessos aceita Sem acesso ou Editor'; end if;
    if recurso_atual like 'painel:%' and novo not in ('sem_acesso', 'leitor') then raise exception 'Painel externo permite apenas acesso de leitura no portal'; end if;

    select g.nivel, g.revisao into anterior, revisao_atual
      from public."TB_PERMISSAO_RECURSO" g where g.perfil_usuario_id = alvo.id and g.recurso = recurso_atual;
    if item ->> 'revisao' is null or coalesce(revisao_atual, 0) <> (item ->> 'revisao')::integer then
      raise exception 'Permissão alterada por outra pessoa. Recarregue a matriz.' using errcode = 'PT409';
    end if;
    v_nivel_grupo := private."FC_NIVEL_DO_GRUPO"(alvo.perfil, recurso_atual);

    -- Administrador global segue o grupo: uma exceção de módulo nele (ex.: um
    -- select que mostrou "Leitor" por engano) o rebaixaria sem ninguém perceber.
    -- Para mudar um administrador, troca-se o grupo, de forma explícita.
    if novo is not null and novo is distinct from v_nivel_grupo
       and exists (select 1 from public."TB_GRUPO_ACESSO" a
                    where a."CO_GRUPO_ACESSO" = alvo.perfil and a."ST_ADMIN_GLOBAL") then
      raise exception 'Administrador global segue o grupo: para mudar o acesso de %, troque o grupo da pessoa.', coalesce(alvo.email, 'esta pessoa')
        using errcode = '42501';
    end if;

    -- Teto do coordenador: o nível resultante (exceção ou padrão do grupo).
    if v_gestor = 'coordenador' then
      if recurso_atual = 'acessos' then raise exception 'Só o administrador concede Acessos' using errcode = '42501'; end if;
      if private."FC_RANK_NIVEL"(coalesce(novo, v_nivel_grupo)) > private."FC_RANK_NIVEL"(private."FC_TETO_DO_GESTOR"(recurso_atual)) then
        raise exception 'Você não pode conceder mais do que o seu próprio nível em %', recurso_atual using errcode = '42501';
      end if;
    end if;

    if novo is null then
      -- Voltar ao padrão do grupo: apaga a exceção.
      if anterior is null then continue; end if;
      delete from public."TB_PERMISSAO_RECURSO" where perfil_usuario_id = alvo.id and recurso = recurso_atual;
      insert into public."TH_PERMISSAO_RECURSO"(perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
      values (alvo.id, recurso_atual, anterior, v_nivel_grupo, (select auth.uid()), btrim(p_motivo) || ' [padrão do grupo]');
      quantidade := quantidade + 1;
      continue;
    end if;

    if anterior is not distinct from novo then continue; end if;
    insert into public."TB_PERMISSAO_RECURSO" (perfil_usuario_id, recurso, nivel, updated_by) values (alvo.id, recurso_atual, novo, (select auth.uid()))
    on conflict (perfil_usuario_id, recurso) do update
      set nivel = excluded.nivel, revisao = "TB_PERMISSAO_RECURSO".revisao + 1, updated_at = now(), updated_by = excluded.updated_by;
    insert into public."TH_PERMISSAO_RECURSO"(perfil_usuario_id, recurso, nivel_anterior, nivel_novo, alterado_por, motivo)
    values (alvo.id, recurso_atual, coalesce(anterior, v_nivel_grupo), novo, (select auth.uid()), btrim(p_motivo));
    quantidade := quantidade + 1;
  end loop;

  -- Ninguém ativo termina o lote sem área: quem não é administrador global só
  -- vê as áreas marcadas (ou a da coordenação). Em 30/09 uma conta saiu de
  -- Administrador para Usuário sem área e entrou num sistema vazio.
  for v_sem_area in
    select coalesce(nullif(btrim(u.nome), ''), u.email)
      from public."TB_PERFIL_USUARIO" u
     where u.ativo
       and u.id in (select (x ->> 'usuario_id')::uuid from jsonb_array_elements(p_alteracoes) x
                     where x ->> 'usuario_id' is not null)
       and cardinality(coalesce(private."FC_AREAS_DO_PERFIL"(u.id), '{}')) = 0
  loop
    raise exception '% ficaria sem nenhuma área e não veria nada no sistema. Marque ao menos uma área (ou uma coordenação) junto com a troca de grupo.', v_sem_area
      using errcode = '23514';
  end loop;

  -- Quem gerencia acessos sem ser administrador global precisa de coordenação:
  -- o coordenador só gerencia a própria. Sem ela, o menu mostrava Acessos e o
  -- banco recusava a leitura (42501) — 30/09.
  for v_sem_area in
    select coalesce(nullif(btrim(u.nome), ''), u.email)
      from public."TB_PERFIL_USUARIO" u
      join public."TB_GRUPO_ACESSO" g on g."CO_GRUPO_ACESSO" = u.perfil
     where u.ativo
       and not g."ST_ADMIN_GLOBAL"
       and u."CO_COORDENACAO" is null
       and u.id in (select (x ->> 'usuario_id')::uuid from jsonb_array_elements(p_alteracoes) x
                     where x ->> 'usuario_id' is not null)
       and private."FC_RANK_NIVEL"(private."FC_NIVEL_EFETIVO"(u.id, u.perfil, 'acessos')) >= private."FC_RANK_NIVEL"('editor')
  loop
    raise exception '% gerenciaria acessos sem coordenação. Escolha a coordenação dela (o coordenador gerencia só a própria) ou use outro grupo.', v_sem_area
      using errcode = '23514';
  end loop;

  return jsonb_build_object('alteradas', quantidade);
end;
$$;

--
-- Name: salvar_minha_preferencia_do_resumo(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_minha_preferencia_do_resumo(p_mostrar boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_perfil uuid;
begin
  if (select auth.uid()) is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;
  if p_mostrar is null then
    raise exception 'Informe se o resumo abre ao entrar.' using errcode = '22023';
  end if;
  select p.id into v_perfil from private.current_profile() p;
  if v_perfil is null then
    raise exception 'Perfil não encontrado.' using errcode = '42501';
  end if;
  insert into public."TB_PREFERENCIA_USUARIO" ("CO_PERFIL_USUARIO", "ST_MOSTRAR_RESUMO_DIA")
  values (v_perfil, case when p_mostrar then 'S' else 'N' end)
  on conflict ("CO_PERFIL_USUARIO") do update
    set "ST_MOSTRAR_RESUMO_DIA" = excluded."ST_MOSTRAR_RESUMO_DIA", "DT_ATUALIZACAO" = now();
  return jsonb_build_object('mostrar_ao_entrar', p_mostrar);
end;
$$;

--
-- Name: FUNCTION salvar_minha_preferencia_do_resumo(p_mostrar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_minha_preferencia_do_resumo(p_mostrar boolean) IS 'Liga (true) ou desliga (false) o resumo do dia ao entrar, para quem chama (o sininho continua). 20261104130000.';

--
-- Name: salvar_modelo_carta_convocacao(uuid, text, uuid, jsonb, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_modelo_carta_convocacao(p_modelo uuid, p_area text, p_edital uuid, p_conteudo jsonb, p_versao_atual integer DEFAULT NULL::integer, p_motivo text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_modelo public."TB_MODELO_CARTA_CONVOCACAO";
  v_area text := lower(btrim(coalesce(p_area, '')));
  v_nome text := btrim(coalesce(p_conteudo ->> 'nome', ''));
  v_titulo text := btrim(coalesce(p_conteudo ->> 'titulo', ''));
  v_texto text := btrim(coalesce(p_conteudo ->> 'texto', ''));
  v_local text := nullif(btrim(coalesce(p_conteudo ->> 'local', '')), '');
  v_documentos text := nullif(btrim(coalesce(p_conteudo ->> 'documentos', '')), '');
  v_contato text := nullif(btrim(coalesce(p_conteudo ->> 'contato', '')), '');
  v_prazo integer;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_versao integer;
  v_autor record;
begin
  if not private.pode_recurso('aprovados', 2) then
    raise exception 'Sem permissão para editar os modelos da carta' using errcode = '42501';
  end if;
  if jsonb_typeof(p_conteudo) is distinct from 'object' then
    raise exception 'Conteúdo do modelo inválido.' using errcode = '22023';
  end if;
  if length(v_nome) not between 3 and 120 then
    raise exception 'O nome do modelo deve ter de 3 a 120 caracteres.' using errcode = '22023';
  end if;
  if length(v_titulo) not between 1 and 300 then
    raise exception 'O título deve ter de 1 a 300 caracteres.' using errcode = '22023';
  end if;
  if length(v_texto) not between 1 and 20000 then
    raise exception 'O texto da carta deve ter de 1 a 20.000 caracteres.' using errcode = '22023';
  end if;
  if length(coalesce(v_local, '')) > 500 or length(coalesce(v_contato, '')) > 500
     or length(coalesce(v_documentos, '')) > 5000 then
    raise exception 'Local e contato vão até 500 caracteres; documentos, até 5.000.' using errcode = '22023';
  end if;
  if jsonb_typeof(p_conteudo -> 'prazo_dias') = 'number' then
    v_prazo := (p_conteudo ->> 'prazo_dias')::numeric::integer;
    if v_prazo not between 0 and 90 then
      raise exception 'O prazo padrão vai de 0 a 90 dias.' using errcode = '22023';
    end if;
  elsif p_conteudo ? 'prazo_dias' and jsonb_typeof(p_conteudo -> 'prazo_dias') <> 'null' then
    raise exception 'O prazo padrão deve ser um número de dias.' using errcode = '22023';
  end if;
  if v_motivo is not null and length(v_motivo) not between 3 and 500 then
    raise exception 'O motivo deve ter de 3 a 500 caracteres.' using errcode = '22023';
  end if;

  select * into v_autor from private.autor_da_sessao();

  if p_modelo is null then
    if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
      raise exception 'Área inválida: %', p_area using errcode = '22023';
    end if;
    if not (v_area = any ((select private."FC_AREAS_USUARIO"())::text[])) then
      raise exception 'Sem permissão para esta área' using errcode = '42501';
    end if;
    if p_edital is not null then
      if not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital and m."CO_AREA" = v_area) then
        raise exception 'O edital não é desta área.' using errcode = '22023';
      end if;
      perform private."FC_EXIGIR_AREA_EDITAL"(p_edital::text);
    end if;
    if exists (select 1 from public."TB_MODELO_CARTA_CONVOCACAO" t
                where t."ST_ATIVO" and t."CO_AREA" = v_area
                  and t."CO_MONITORAMENTO" is not distinct from p_edital
                  and lower(btrim(t."NO_MODELO")) = lower(v_nome)) then
      raise exception 'Já existe um modelo ativo com este nome.' using errcode = '23505';
    end if;
    insert into public."TB_MODELO_CARTA_CONVOCACAO" (
      "CO_AREA", "CO_MONITORAMENTO", "NO_MODELO", "NU_VERSAO_VIGENTE", "CO_USUARIO_CRIACAO", "CO_USUARIO_ATUALIZACAO"
    ) values (v_area, p_edital, v_nome, 1, (select auth.uid()), (select auth.uid()))
    returning * into v_modelo;
    v_versao := 1;
  else
    select * into v_modelo from public."TB_MODELO_CARTA_CONVOCACAO"
     where "CO_MODELO_CARTA" = p_modelo for update;
    if v_modelo."CO_MODELO_CARTA" is null then
      raise exception 'Modelo não encontrado' using errcode = '22023';
    end if;
    if not (v_modelo."CO_AREA" = any ((select private."FC_AREAS_USUARIO"())::text[])) then
      raise exception 'Sem permissão para esta área' using errcode = '42501';
    end if;
    perform private."FC_EXIGIR_AREA_EDITAL"(v_modelo."CO_MONITORAMENTO"::text);
    if not v_modelo."ST_ATIVO" then
      raise exception 'Modelo inativo: reative antes de editar.' using errcode = '22023';
    end if;
    if p_versao_atual is distinct from v_modelo."NU_VERSAO_VIGENTE" then
      raise exception 'O modelo mudou desde que você o abriu (versão %); abra de novo.', v_modelo."NU_VERSAO_VIGENTE" using errcode = 'PT409';
    end if;
    if v_motivo is null then
      raise exception 'Informe o motivo da alteração do modelo.' using errcode = '22023';
    end if;
    if exists (select 1 from public."TB_MODELO_CARTA_CONVOCACAO" t
                where t."ST_ATIVO" and t."CO_MODELO_CARTA" <> v_modelo."CO_MODELO_CARTA"
                  and t."CO_AREA" = v_modelo."CO_AREA"
                  and t."CO_MONITORAMENTO" is not distinct from v_modelo."CO_MONITORAMENTO"
                  and lower(btrim(t."NO_MODELO")) = lower(v_nome)) then
      raise exception 'Já existe um modelo ativo com este nome.' using errcode = '23505';
    end if;
    v_versao := v_modelo."NU_VERSAO_VIGENTE" + 1;
    update public."TB_MODELO_CARTA_CONVOCACAO"
       set "NO_MODELO" = v_nome, "NU_VERSAO_VIGENTE" = v_versao,
           "CO_USUARIO_ATUALIZACAO" = (select auth.uid()), "DT_ATUALIZACAO" = now()
     where "CO_MODELO_CARTA" = v_modelo."CO_MODELO_CARTA";
  end if;

  insert into public."TH_MODELO_CARTA_CONVOCACAO" (
    "CO_MODELO_CARTA", "NU_VERSAO", "NO_MODELO", "DS_TITULO", "DS_TEXTO", "DS_LOCAL", "DS_DOCUMENTOS",
    "DS_CONTATO", "NU_PRAZO_DIAS", "DS_MOTIVO", "CO_USUARIO", "NO_USUARIO", "DS_EMAIL_USUARIO"
  ) values (
    v_modelo."CO_MODELO_CARTA", v_versao, v_nome, v_titulo, v_texto, v_local, v_documentos,
    v_contato, v_prazo, v_motivo, (select auth.uid()), v_autor.nome, v_autor.email
  );

  return json_build_object('modelo_id', v_modelo."CO_MODELO_CARTA", 'versao', v_versao);
end;
$$;

--
-- Name: FUNCTION salvar_modelo_carta_convocacao(p_modelo uuid, p_area text, p_edital uuid, p_conteudo jsonb, p_versao_atual integer, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_modelo_carta_convocacao(p_modelo uuid, p_area text, p_edital uuid, p_conteudo jsonb, p_versao_atual integer, p_motivo text) IS 'Cria o modelo da carta de convocação (área e, se quiser, edital da área) ou grava a próxima versão do modelo ativo: p_versao_atual tem de ser a vigente (senão 40001) e o motivo (3 a 500) é obrigatório a partir da versão 2. Nome único entre os ativos da área/edital. Aprovados >= editor e a área (e o recorte do edital).';

--
-- Name: salvar_modelo_convocacao(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_modelo_convocacao(p_modelo jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid := nullif(btrim(p_modelo->>'id'), '')::uuid;
  v_nome text := btrim(coalesce(p_modelo->>'nome', ''));
  v_categorias jsonb := coalesce(p_modelo->'categorias', '[]'::jsonb);
  v_amplas integer;
  v_total integer := 0;
begin
  if not (private.pode_recurso('importacao',2)) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not private.pode_recurso('importacao',2) then
    raise exception 'Perfil sem permissao para configurar a convocacao';
  end if;
  if nullif(v_nome, '') is null then
    raise exception 'Informe um nome para o modelo';
  end if;
  if jsonb_typeof(v_categorias) <> 'array' or jsonb_array_length(v_categorias) = 0 then
    raise exception 'O modelo precisa de pelo menos uma categoria';
  end if;

  select count(*) into v_amplas
  from jsonb_array_elements(v_categorias) as x
  where coalesce((x->>'ampla')::boolean, false);
  if v_amplas <> 1 then
    raise exception 'O modelo precisa de exatamente uma categoria de ampla concorrencia (encontradas: %)', v_amplas;
  end if;

  insert into public."TB_MODELO_CONVOCACAO"(
    "CO_MODELO", "NO_MODELO",
    "TP_DISTRIBUICAO", "TP_COTA_MULTIPLA",
    "CO_USUARIO_ATUALIZACAO"
  ) values (
    coalesce(v_id, gen_random_uuid()),
    v_nome,
    upper(coalesce(nullif(btrim(p_modelo->>'distribuicao'), ''), 'proporcional')),
    upper(coalesce(nullif(btrim(p_modelo->>'cotaMultipla'), ''), 'maior_percentual')),
    (select auth.uid())
  )
  on conflict ("CO_MODELO") do update
  set "NO_MODELO" = excluded."NO_MODELO",
      "TP_DISTRIBUICAO" = excluded."TP_DISTRIBUICAO",
      "TP_COTA_MULTIPLA" = excluded."TP_COTA_MULTIPLA",
      "CO_USUARIO_ATUALIZACAO" = excluded."CO_USUARIO_ATUALIZACAO",
      "DT_ATUALIZACAO" = now()
  returning "CO_MODELO" into v_id;

  delete from public."TB_CATEGORIA_CONVOCACAO" where "CO_MODELO" = v_id;

  insert into public."TB_CATEGORIA_CONVOCACAO"(
    "CO_MODELO", "CO_CATEGORIA", "NO_CATEGORIA", "SG_CATEGORIA",
    "ST_AMPLA", "ST_ACUMULAVEL", "TX_RESERVA", "TP_ARREDONDAMENTO", "TX_TETO",
    "QT_MINIMA_RESERVA", "DS_TERMO", "DS_POSICAO", "QT_INTERVALO", "DS_CASCATA", "NU_ORDEM"
  )
  select v_id,
         btrim(x.id),
         btrim(x.rotulo),
         left(btrim(x.sigla), 10),
         case when coalesce(x.ampla, false) then 'S' else 'N' end,
         case when coalesce(x.acumulavel, false) then 'S' else 'N' end,
         least(greatest(coalesce(x.percentual, 0), 0), 100),
         upper(coalesce(nullif(btrim(x.arredondamento), ''), 'meio_acima')),
         least(greatest(coalesce(x.teto, 0), 0), 100),
         greatest(coalesce(x.minimo, 0), 0),
         coalesce(x.termos, ''),
         coalesce(x.posicoes, ''),
         greatest(coalesce(x.intervalo, 0), 0),
         coalesce(x.cascata, ''),
         greatest(coalesce(x.ordem, 0), 0)
  from jsonb_to_recordset(v_categorias) as x(
    id text,
    rotulo text,
    sigla text,
    ampla boolean,
    acumulavel boolean,
    percentual numeric,
    arredondamento text,
    teto numeric,
    minimo integer,
    termos text,
    posicoes text,
    intervalo integer,
    cascata text,
    ordem integer
  )
  where nullif(btrim(x.id), '') is not null;

  get diagnostics v_total = row_count;
  return jsonb_build_object('ok', true, 'modelo_id', v_id, 'categorias', v_total);
end;
$$;

--
-- Name: salvar_modelo_espelho_nota(uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_modelo_espelho_nota(p_edital uuid, p_textos jsonb, p_versao_atual integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_textos jsonb := coalesce(p_textos, '{}'::jsonb);
  v_modelo public."TB_MODELO_ESPELHO_NOTA";
  v_existe boolean;
begin
  perform private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  perform private."FC_VALIDAR_MODELO_ESPELHO_NOTA"(v_textos);
  if p_versao_atual is null or p_versao_atual < 0 then
    raise exception 'Versão aberta do modelo inválida' using errcode = '22023';
  end if;

  -- Um salvamento por edital de cada vez (a primeira versão ainda não tem linha para travar).
  perform pg_advisory_xact_lock(hashtextextended('TB_MODELO_ESPELHO_NOTA|' || p_edital::text, 0));
  select * into v_modelo from public."TB_MODELO_ESPELHO_NOTA" m
   where m."CO_MONITORAMENTO" = p_edital
   for update;
  v_existe := found;

  -- Concorrência: a versão que a tela abriu tem de ser a vigente (0 = nunca salvo).
  if coalesce(v_modelo."NU_VERSAO", 0) <> p_versao_atual then
    raise exception using errcode = 'PT409',
      message = 'O modelo do espelho foi alterado por outra pessoa. Recarregue e tente de novo.';
  end if;
  if coalesce(v_modelo."DS_TEXTOS", '{}'::jsonb) = v_textos then
    raise exception 'O modelo do espelho não mudou' using errcode = '22023';
  end if;

  if v_existe then
    update public."TB_MODELO_ESPELHO_NOTA" m
       set "NU_VERSAO" = m."NU_VERSAO" + 1, "DS_TEXTOS" = v_textos,
           "CO_USUARIO_ATUALIZACAO" = auth.uid(), "DT_ATUALIZACAO" = now()
     where m."CO_MODELO_ESPELHO_NOTA" = v_modelo."CO_MODELO_ESPELHO_NOTA"
    returning * into v_modelo;
  else
    insert into public."TB_MODELO_ESPELHO_NOTA"
      ("CO_MONITORAMENTO", "NU_VERSAO", "DS_TEXTOS", "CO_USUARIO_CRIACAO", "CO_USUARIO_ATUALIZACAO")
    values (p_edital, 1, v_textos, auth.uid(), auth.uid())
    returning * into v_modelo;
  end if;
  insert into public."TH_MODELO_ESPELHO_NOTA"
    ("CO_MODELO_ESPELHO_NOTA", "NU_VERSAO", "DS_TEXTOS", "TP_ACAO", "CO_USUARIO")
  values (v_modelo."CO_MODELO_ESPELHO_NOTA", v_modelo."NU_VERSAO", v_textos,
          case when v_textos = '{}'::jsonb then 'RESTAURAR' else 'SALVAR' end, auth.uid());

  return public.obter_modelo_espelho_nota(p_edital);
end;
$$;

--
-- Name: FUNCTION salvar_modelo_espelho_nota(p_edital uuid, p_textos jsonb, p_versao_atual integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_modelo_espelho_nota(p_edital uuid, p_textos jsonb, p_versao_atual integer) IS 'Salva o modelo do espelho de nota do edital (20261019120000): p_textos = só as diferenças do padrão ({} = Restaurar padrão), validados por FC_VALIDAR_MODELO_ESPELHO_NOTA (22023); p_versao_atual = a versão que a tela abriu (0 = nunca salvo; outra = PT409). Só a coordenação do edital (FC_EXIGIR_COORD_AVALIACAO, 42501). Grava a versão nova em TB_MODELO_ESPELHO_NOTA e TH_MODELO_ESPELHO_NOTA e devolve obter_modelo_espelho_nota.';

--
-- Name: salvar_modelo_resposta_recurso(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_modelo_resposta_recurso(p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_id uuid := nullif(p_dados->>'id', '')::uuid;
  v_area text := nullif(btrim(coalesce(p_dados->>'area', '')), '');
  v_origem text := nullif(btrim(coalesce(p_dados->>'origem', '')), '');
  v_situacao text := p_dados->>'situacao';
  v_nome text := btrim(coalesce(p_dados->>'nome', ''));
  v_corpo text := btrim(coalesce(p_dados->>'corpo', ''));
  v_atual public."TB_MODELO_RESPOSTA_RECURSO";
  v_desconhecidos text[];
begin
  if not private.pode_recurso('recursos', 3) then
    raise exception 'Só a administração de Recursos gerencia os modelos de resposta' using errcode = '42501';
  end if;
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  if v_area is not null then
    if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
      raise exception 'Área inválida' using errcode = '22023';
    end if;
    if not private."FC_PODE_AREA"(v_area) then
      raise exception 'Sem acesso a esta área' using errcode = '42501';
    end if;
  end if;
  if v_origem is not null and not exists (select 1 from public."TB_ORIGEM_RECURSO" o where o."CO_ORIGEM_RECURSO" = v_origem) then
    raise exception 'Origem inválida' using errcode = '22023';
  end if;
  if v_situacao is null or v_situacao not in ('DEFERIDO', 'INDEFERIDO', 'PARCIALMENTE_INDEFERIDO') then
    raise exception 'Situação inválida' using errcode = '22023';
  end if;
  if length(v_nome) not between 3 and 150 then
    raise exception 'O nome do modelo deve ter de 3 a 150 caracteres' using errcode = '22023';
  end if;
  if length(v_corpo) not between 20 and 20000 then
    raise exception 'O texto do modelo deve ter de 20 a 20.000 caracteres' using errcode = '22023';
  end if;
  select array_agg(distinct m[1] order by m[1]) into v_desconhecidos
  from regexp_matches(v_corpo, '\{([a-z_]+)\}', 'g') m
  where m[1] <> all (private."FC_MARCADORES_MODELO_RESPOSTA"());
  if v_desconhecidos is not null then
    raise exception 'Marcador desconhecido no modelo: %', array_to_string(v_desconhecidos, ', ') using errcode = '22023';
  end if;

  if v_id is null then
    v_id := gen_random_uuid();
    insert into public."TB_MODELO_RESPOSTA_RECURSO" (
      "CO_MODELO_RESPOSTA", "NU_VERSAO", "CO_AREA", "CO_ORIGEM_RECURSO", "TP_SITUACAO",
      "NO_MODELO", "DS_CORPO", "CO_USUARIO_CRIACAO"
    ) values (v_id, 1, v_area, v_origem, v_situacao, v_nome, v_corpo, v_uid);
    return json_build_object('id', v_id, 'versao', 1, 'criou_versao', true);
  end if;

  select t.* into v_atual
  from public."TB_MODELO_RESPOSTA_RECURSO" t
  where t."CO_MODELO_RESPOSTA" = v_id and t."ST_VIGENTE" = 'S'
  for update;
  if not found then
    raise exception 'Modelo não encontrado' using errcode = 'P0002';
  end if;
  if v_atual."CO_AREA" is not null and not private."FC_PODE_AREA"(v_atual."CO_AREA") then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;
  if p_dados->>'versao' is null or (p_dados->>'versao')::integer <> v_atual."NU_VERSAO" then
    raise exception 'Outra pessoa alterou este modelo. Recarregue e tente de novo.' using errcode = 'PT409';
  end if;
  if v_atual."ST_ATIVO" = 'S'
     and v_atual."CO_AREA" is not distinct from v_area
     and v_atual."CO_ORIGEM_RECURSO" is not distinct from v_origem
     and v_atual."TP_SITUACAO" = v_situacao
     and v_atual."NO_MODELO" = v_nome
     and v_atual."DS_CORPO" = v_corpo then
    return json_build_object('id', v_id, 'versao', v_atual."NU_VERSAO", 'criou_versao', false);
  end if;

  update public."TB_MODELO_RESPOSTA_RECURSO" set "ST_VIGENTE" = 'N'
  where "CO_MODELO_RESPOSTA" = v_id and "NU_VERSAO" = v_atual."NU_VERSAO";
  insert into public."TB_MODELO_RESPOSTA_RECURSO" (
    "CO_MODELO_RESPOSTA", "NU_VERSAO", "CO_AREA", "CO_ORIGEM_RECURSO", "TP_SITUACAO",
    "NO_MODELO", "DS_CORPO", "CO_USUARIO_CRIACAO"
  ) values (v_id, v_atual."NU_VERSAO" + 1, v_area, v_origem, v_situacao, v_nome, v_corpo, v_uid);
  return json_build_object('id', v_id, 'versao', v_atual."NU_VERSAO" + 1, 'criou_versao', true);
end;
$$;

--
-- Name: FUNCTION salvar_modelo_resposta_recurso(p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_modelo_resposta_recurso(p_dados jsonb) IS 'Cria um modelo (sem id) ou grava a versão seguinte (id + versao atual; 40001 se outra pessoa gravou antes). Sem mudança, não cria versão; salvar um arquivado o reativa. Confere área, origem, situação, tamanhos e marcadores. Exige recursos = admin.';

--
-- Name: salvar_monitoramento_com_cronograma(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_monitoramento_com_cronograma(p_payload jsonb, p_cronograma jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
declare
  v_id uuid;
  v_row public."TB_MONITORAMENTO_INDIGENA"%rowtype;
  v_item jsonb;
  v_ordem integer := 0;
  v_auto boolean := coalesce((p_payload ->> 'cronograma_automatico')::boolean, false);
  v_total integer := jsonb_array_length(coalesce(p_cronograma,'[]'::jsonb));
  v_inicio date;
  v_fim date;
  v_estado jsonb;
begin
  perform private."FC_EXIGIR_AREA_SALVAR_EDITAL"(p_payload);
  if not ((private.pode_recurso('nucleo',2) or private.pode_recurso('calendario',2))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not private.has_perm('cores') then
    raise exception 'Sem permissao para salvar monitoramento indigena';
  end if;

  v_id := nullif(p_payload ->> 'id','')::uuid;

  if v_id is null then
    insert into public."TB_MONITORAMENTO_INDIGENA"(
      processo, edital, id_unidade, sigla_unidade, tipo_unidade, unidade, uf, ciclo,
      vagas_total, data_inicio, data_fim, status, etapa, risco, responsavel,
      link_edital, observacoes, observacoes_internas, ativo, created_by, updated_by,
      cronograma_automatico, cronograma_pdf_path, cronograma_pdf_nome, cronograma_origem,
      cronograma_revisado_at, cronograma_revisado_por, status_override, etapa_override
    ) values (
      nullif(p_payload ->> 'processo',''),
      nullif(p_payload ->> 'edital',''),
      nullif(p_payload ->> 'id_unidade',''),
      nullif(p_payload ->> 'sigla_unidade',''),
      nullif(p_payload ->> 'tipo_unidade',''),
      nullif(p_payload ->> 'unidade',''),
      nullif(upper(p_payload ->> 'uf'),''),
      nullif(p_payload ->> 'ciclo',''),
      coalesce(nullif(p_payload ->> 'vagas_total','')::integer,0),
      nullif(p_payload ->> 'data_inicio','')::date,
      nullif(p_payload ->> 'data_fim','')::date,
      nullif(p_payload ->> 'status',''),
      nullif(p_payload ->> 'etapa',''),
      coalesce(nullif(p_payload ->> 'risco',''),'Baixo'),
      nullif(p_payload ->> 'responsavel',''),
      nullif(p_payload ->> 'link_edital',''),
      nullif(p_payload ->> 'observacoes',''),
      nullif(p_payload ->> 'observacoes_internas',''),
      true,
      auth.uid(), auth.uid(),
      v_auto,
      nullif(p_payload ->> 'cronograma_pdf_path',''),
      nullif(p_payload ->> 'cronograma_pdf_nome',''),
      nullif(p_payload ->> 'cronograma_origem',''),
      case when v_total > 0 then now() else null end,
      case when v_total > 0 then auth.uid() else null end,
      nullif(p_payload ->> 'status_override',''),
      nullif(p_payload ->> 'etapa_override','')
    ) returning * into v_row;
    v_id := v_row.id;
  else
    update public."TB_MONITORAMENTO_INDIGENA"
    set processo = nullif(p_payload ->> 'processo',''),
        edital = nullif(p_payload ->> 'edital',''),
        id_unidade = nullif(p_payload ->> 'id_unidade',''),
        sigla_unidade = nullif(p_payload ->> 'sigla_unidade',''),
        tipo_unidade = nullif(p_payload ->> 'tipo_unidade',''),
        unidade = nullif(p_payload ->> 'unidade',''),
        uf = nullif(upper(p_payload ->> 'uf'),''),
        ciclo = nullif(p_payload ->> 'ciclo',''),
        vagas_total = coalesce(nullif(p_payload ->> 'vagas_total','')::integer,0),
        data_inicio = nullif(p_payload ->> 'data_inicio','')::date,
        data_fim = nullif(p_payload ->> 'data_fim','')::date,
        status = nullif(p_payload ->> 'status',''),
        etapa = nullif(p_payload ->> 'etapa',''),
        risco = coalesce(nullif(p_payload ->> 'risco',''),'Baixo'),
        responsavel = nullif(p_payload ->> 'responsavel',''),
        link_edital = nullif(p_payload ->> 'link_edital',''),
        observacoes = nullif(p_payload ->> 'observacoes',''),
        observacoes_internas = nullif(p_payload ->> 'observacoes_internas',''),
        updated_by = auth.uid(),
        updated_at = now(),
        cronograma_automatico = v_auto,
        cronograma_pdf_path = coalesce(nullif(p_payload ->> 'cronograma_pdf_path',''), cronograma_pdf_path),
        cronograma_pdf_nome = coalesce(nullif(p_payload ->> 'cronograma_pdf_nome',''), cronograma_pdf_nome),
        cronograma_origem = nullif(p_payload ->> 'cronograma_origem',''),
        cronograma_revisado_at = case when v_total > 0 then now() else cronograma_revisado_at end,
        cronograma_revisado_por = case when v_total > 0 then auth.uid() else cronograma_revisado_por end,
        status_override = nullif(p_payload ->> 'status_override',''),
        etapa_override = nullif(p_payload ->> 'etapa_override','')
    where id = v_id
    returning * into v_row;
  end if;

  if v_row.id is null then
    raise exception 'Registro nao encontrado ou nao salvo';
  end if;

  if p_cronograma is not null then
    delete from public."TB_CRONOGRAMA_MONIT_INDIG" where monitoramento_id = v_id;
    for v_item in select * from jsonb_array_elements(coalesce(p_cronograma,'[]'::jsonb)) loop
      v_ordem := v_ordem + 1;
      insert into public."TB_CRONOGRAMA_MONIT_INDIG"(
        monitoramento_id, ordem, atividade, tipo_atividade, data_inicio, data_fim,
        concluida, observacao, origem, confianca_extracao, created_by, updated_by
      ) values (
        v_id,
        coalesce(nullif(v_item ->> 'ordem','')::integer, v_ordem),
        nullif(v_item ->> 'atividade',''),
        nullif(v_item ->> 'tipo_atividade',''),
        (v_item ->> 'data_inicio')::date,
        (v_item ->> 'data_fim')::date,
        nullif(v_item ->> 'concluida','')::boolean,
        nullif(v_item ->> 'observacao',''),
        coalesce(nullif(upper(v_item ->> 'origem'),''),'MANUAL'),
        nullif(v_item ->> 'confianca_extracao','')::numeric,
        auth.uid(), auth.uid()
      );
    end loop;
  end if;

  if v_auto and v_total > 0 then
    select min(data_inicio), max(data_fim)
    into v_inicio, v_fim
    from public."TB_CRONOGRAMA_MONIT_INDIG"
    where monitoramento_id = v_id;

    update public."TB_MONITORAMENTO_INDIGENA"
    set data_inicio = v_inicio,
        data_fim = v_fim,
        updated_at = now()
    where id = v_id;
  end if;

  v_estado := public.get_monitoramento_cronograma_estado(v_id, current_date);

  update public."TB_MONITORAMENTO_INDIGENA"
  set status = coalesce(v_estado ->> 'status', status),
      etapa = coalesce(v_estado ->> 'etapa', etapa),
      updated_at = now()
  where id = v_id
  returning * into v_row;

  return jsonb_build_object(
    'ok', true,
    'registro', to_jsonb(v_row),
    'estado', v_estado,
    'cronograma_total', v_total
  );
end;
$$;

--
-- Name: salvar_monitoramento_com_cronograma_v2(jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_monitoramento_com_cronograma_v2(p_payload jsonb, p_cronograma jsonb DEFAULT '[]'::jsonb, p_motivo text DEFAULT NULL::text, p_numero_errata text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'auth', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
declare
  v_id uuid := nullif(p_payload ->> 'id', '')::uuid;
  v_result jsonb;
  v_antes jsonb := '[]'::jsonb;
  v_depois jsonb := '[]'::jsonb;
  v_alteracoes jsonb := '[]'::jsonb;
  v_total integer := 0;
  v_versao_id uuid;
  v_motivo text := nullif(btrim(p_motivo), '');
  v_errata text := nullif(btrim(p_numero_errata), '');
  v_override text := nullif(btrim(p_payload ->> 'status_override'), '');
  v_override_motivo text := nullif(btrim(p_payload ->> 'status_override_motivo'), '');
  v_override_data date := nullif(p_payload ->> 'status_override_data', '')::date;
  v_area text;
begin
  perform private."FC_EXIGIR_AREA_SALVAR_EDITAL"(p_payload);
  if not ((private.pode_recurso('nucleo',2) or private.pode_recurso('calendario',2))) then raise exception 'Sem permissão para este recurso' using errcode='42501'; end if;
  if not private.has_perm('cores') then
    raise exception 'Sem permissao para salvar monitoramento indigena';
  end if;

  /*
    Edital novo não tem cronograma anterior a justificar: o histórico registra
    "Cadastro do edital". Edital existente continua exigindo o motivo.
  */
  if v_motivo is null then
    if v_id is null then
      v_motivo := 'Cadastro do edital';
    else
      raise exception 'Informe o motivo da alteração do cronograma';
    end if;
  end if;

  if jsonb_typeof(coalesce(p_cronograma, '[]'::jsonb)) <> 'array' then
    raise exception 'Cronograma inválido';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_cronograma, '[]'::jsonb)) as x(
      ordem integer, atividade text, data_inicio date, data_fim date
    )
    where nullif(btrim(atividade), '') is null
       or data_inicio is null
       or data_fim is null
       or data_fim < data_inicio
  ) then
    raise exception 'Existem etapas incompletas ou com período inválido';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_cronograma, '[]'::jsonb)) as x(atividade text)
    group by lower(btrim(atividade))
    having count(*) > 1
  ) then
    raise exception 'Existem atividades duplicadas no cronograma';
  end if;

  if v_override is not null and (v_override_motivo is null or v_override_data is null) then
    raise exception 'Status excepcional exige motivo e data da decisão';
  end if;

  if not pg_try_advisory_xact_lock(hashtext('cronograma:' || coalesce(v_id::text, auth.uid()::text, 'novo'))::bigint) then
    raise exception 'Outra alteração deste cronograma está em andamento';
  end if;

  -- Área pretendida (p_payload.co_area): confere a unidade e registra a nova. Sem ela, NULL.
  v_area := private."FC_ACERTAR_AREA_EDITAL"(p_payload);

  if v_id is not null then
    v_antes := private.snapshot_monitoramento_cronograma(v_id);
  end if;

  v_result := public.salvar_monitoramento_com_cronograma(p_payload, p_cronograma);
  v_id := nullif(v_result #>> '{registro,id}', '')::uuid;

  if v_id is null then
    raise exception 'O salvamento não retornou o identificador do edital';
  end if;

  -- Validade do processo seletivo: só quando vem no payload (o front antigo não manda).
  update public."TB_MONITORAMENTO_INDIGENA"
  set status_override_motivo = v_override_motivo,
      status_override_data = v_override_data,
      status_override_previsao_retomada = nullif(p_payload ->> 'status_override_previsao_retomada', '')::date,
      cronograma_ultima_errata = coalesce(v_errata, cronograma_ultima_errata),
      "CO_AREA" = coalesce(v_area, "CO_AREA"),
      "NU_ANOS_VALIDADE" = case when p_payload ? 'nu_anos_validade'
        then coalesce(nullif(p_payload ->> 'nu_anos_validade', '')::smallint, 0) else "NU_ANOS_VALIDADE" end,
      "NU_MESES_VALIDADE" = case when p_payload ? 'nu_meses_validade'
        then coalesce(nullif(p_payload ->> 'nu_meses_validade', '')::smallint, 0) else "NU_MESES_VALIDADE" end,
      "ST_PRORROGADO" = case when p_payload ? 'st_prorrogado'
        then coalesce((p_payload ->> 'st_prorrogado')::boolean, false) else "ST_PRORROGADO" end,
      updated_by = auth.uid(),
      updated_at = now()
  where id = v_id;

  -- Prazo já vencido (ou data de encerramento antiga): a lista inativa agora, não só de madrugada.
  perform private."FC_INATIVAR_LISTAS_VENCIDAS"(v_id);

  if v_area is not null then
    v_result := jsonb_set(v_result, '{registro,CO_AREA}', to_jsonb(v_area));
  end if;

  v_depois := private.snapshot_monitoramento_cronograma(v_id);
  v_alteracoes := private.diff_monitoramento_cronograma(v_antes, v_depois);
  v_total := jsonb_array_length(v_alteracoes);

  insert into public."TH_CRONOGRAMA_MONIT_INDIG"(
    monitoramento_id,
    acao,
    motivo,
    numero_errata,
    created_by,
    created_by_email,
    cronograma_antes,
    cronograma_depois,
    alteracoes,
    total_alteracoes
  ) values (
    v_id,
    case when v_errata is null then 'salvar' else 'errata' end,
    v_motivo,
    v_errata,
    auth.uid(),
    nullif(auth.jwt() ->> 'email', ''),
    v_antes,
    v_depois,
    v_alteracoes,
    v_total
  ) returning id into v_versao_id;

  return v_result || jsonb_build_object(
    'versao_id', v_versao_id,
    'total_alteracoes', v_total,
    'alteracoes', v_alteracoes,
    'motivo', v_motivo,
    'numero_errata', v_errata
  );
end;
$$;

--
-- Name: salvar_quadro_de_vagas(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_quadro_de_vagas(p_edital uuid, p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_linhas jsonb := coalesce(p_dados -> 'linhas', '[]'::jsonb);
  v_origem text := coalesce(nullif(upper(p_dados ->> 'origem'), ''), 'PDF');
  v_arquivo text := left(nullif(btrim(p_dados ->> 'arquivo'), ''), 300);
begin
  if not exists (select 1 from public."TB_MONITORAMENTO_INDIGENA" where id = p_edital) then
    raise exception 'Edital não encontrado' using errcode = '22023';
  end if;
  if not (private.pode_recurso('nucleo', 2) or private.pode_recurso('calendario', 2)) then
    raise exception 'Sem permissão para este recurso' using errcode = '42501';
  end if;
  perform private."FC_EXIGIR_AREA_EDITAL"(p_edital::text);
  if jsonb_typeof(v_linhas) <> 'array' or jsonb_array_length(v_linhas) > 500 then
    raise exception 'Quadro de vagas inválido (até 500 linhas)' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(v_linhas) l
              where length(btrim(coalesce(l ->> 'cargo', ''))) not between 1 and 300
                 or coalesce(nullif(l ->> 'vagas_imediatas', '')::integer, 0) not between 0 and 9999
                 or jsonb_typeof(coalesce(l -> 'modalidades', '{}'::jsonb)) <> 'object') then
    raise exception 'Há linha do quadro sem cargo ou com quantidade inválida' using errcode = '22023';
  end if;

  update public."TB_QUADRO_VAGA_EDITAL"
     set "ST_REGISTRO_ATIVO" = 'N', "DT_DESATIVACAO" = now()
   where "CO_MONITORAMENTO" = p_edital and "ST_REGISTRO_ATIVO" = 'S';

  insert into public."TB_QUADRO_VAGA_EDITAL" ("CO_MONITORAMENTO", "NU_ORDEM", "NO_CARGO", "NO_LOTACAO", "DS_MODALIDADE_VAGA",
    "QT_VAGA_IMEDIATA", "ST_CADASTRO_RESERVA", "TP_ORIGEM", "DS_ARQUIVO_ORIGEM", "CO_USUARIO_ATUALIZACAO")
  select p_edital, l.ordem, btrim(l.valor ->> 'cargo'), left(nullif(btrim(l.valor ->> 'lotacao'), ''), 300),
         coalesce(l.valor -> 'modalidades', '{}'::jsonb), coalesce(nullif(l.valor ->> 'vagas_imediatas', '')::integer, 0),
         case when (l.valor ->> 'cadastro_reserva')::boolean then 'S' else 'N' end,
         v_origem, v_arquivo, (select auth.uid())
    from jsonb_array_elements(v_linhas) with ordinality l(valor, ordem);

  return public.obter_quadro_de_vagas(p_edital);
end;
$$;

--
-- Name: FUNCTION salvar_quadro_de_vagas(p_edital uuid, p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_quadro_de_vagas(p_edital uuid, p_dados jsonb) IS 'Substitui o quadro de vagas do edital (o anterior fica desativado). p_dados: {origem PDF|MANUAL, arquivo, linhas:[{cargo, lotacao, modalidades, vagas_imediatas, cadastro_reserva}]}. Núcleo ou Calendário (editor) e o edital.';

--
-- Name: salvar_rascunho_ficha(uuid, integer, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_rascunho_ficha(p_ficha uuid, p_versao integer, p_lancamento jsonb, p_resultado jsonb, p_parecer text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_f public."TB_FICHA_ANALISE";
  v_uid uuid := (select auth.uid());
  v_regra record;
  v_alt jsonb;
  v_cargo text;
  v_conf jsonb;
begin
  select * into v_f from public."TB_FICHA_ANALISE" where "CO_FICHA_ANALISE" = p_ficha for update;
  perform private."FC_EXIGIR_GRAVAR_FICHA"(v_f, p_versao);
  select * into v_regra from private."FC_REGRA_VIGENTE_FICHA"(p_ficha);
  -- A vaga e o cargo são os da ficha (o lançamento grava os dois) e a regra é a
  -- da vaga: a diferença do cargo por cima do nível (20261013130000).
  v_cargo := (select pv."NO_CARGO" from public."TB_PRE_CLASSIF_VAGA" pv
               where pv."CO_MONITORAMENTO" = v_f."CO_MONITORAMENTO" and pv."CO_VAGA" = v_f."CO_VAGA");
  if jsonb_typeof(p_lancamento) = 'object' then
    p_lancamento := p_lancamento || jsonb_build_object('vaga', v_f."CO_VAGA", 'cargo', v_cargo);
  end if;
  v_conf := private."FC_REGRA_DA_VAGA"(v_regra.p_configuracao, v_f."CO_VAGA", v_cargo, p_lancamento ->> 'nivel');
  perform private."FC_VALIDAR_LANCAMENTO_FICHA"(v_conf, p_lancamento);
  perform private."FC_VALIDAR_RESULTADO_FICHA"(v_conf, p_lancamento, p_resultado,
                                                private."FC_DOCUMENTAL_DO_EDITAL"(v_f."CO_MONITORAMENTO"));
  if length(coalesce(p_parecer, '')) > 8000 then
    raise exception 'Parecer com até 8.000 caracteres.' using errcode = '22023';
  end if;
  v_alt := private."FC_ALTERACOES_FICHA"(v_conf, v_f."DS_LANCAMENTO", v_f."DS_RESULTADO", p_lancamento, p_resultado);
  update public."TB_FICHA_ANALISE" set
    "DS_LANCAMENTO" = p_lancamento, "DS_RESULTADO" = p_resultado, "DS_PARECER" = nullif(btrim(coalesce(p_parecer, '')), ''),
    "CO_USUARIO_RASCUNHO" = v_uid, "DT_RASCUNHO" = now(),
    "DT_RESERVA_EXPIRA" = now() + private."FC_PRAZO_RESERVA_FICHA"(),
    "NU_VERSAO" = "NU_VERSAO" + 1, "DT_ATUALIZACAO" = now()
   where "CO_FICHA_ANALISE" = p_ficha;
  -- O histórico do rascunho é leve: o que mudou (de → para), sem o retrato
  -- inteiro, que fica na própria ficha (20261023220000).
  if jsonb_array_length(v_alt) > 0 then
    perform private."FC_HISTORICO_CONTEUDO_FICHA"(p_ficha, 'SALVAR', v_f."TP_SITUACAO", null, v_uid, v_alt, null);
  end if;
  return json_build_object('versao', v_f."NU_VERSAO" + 1, 'salvo_em', now(), 'alteracoes', jsonb_array_length(v_alt),
                           'versao_regra', v_regra.p_versao);
end;
$$;

--
-- Name: FUNCTION salvar_rascunho_ficha(p_ficha uuid, p_versao integer, p_lancamento jsonb, p_resultado jsonb, p_parecer text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_rascunho_ficha(p_ficha uuid, p_versao integer, p_lancamento jsonb, p_resultado jsonb, p_parecer text) IS 'Salva o rascunho da ficha (o salvamento automático da tela): lançamento (com a vaga e o cargo da ficha, desde 20261013130000), resultado da conta e parecer gerado, conferidos contra a regra vigente da vaga (a diferença do cargo por cima do nível, FC_REGRA_DA_VAGA; estrutura, limites e coerência do resultado; nada é recalculado). Exige a reserva vigente de quem chama, em análise, e a versão que a tela abriu (40001); renova a reserva; sobe a versão. Alteração de conteúdo vai ao histórico como SALVAR leve: o que mudou, de quanto para quanto, sem o retrato (que fica na ficha; 20261023220000). Devolve a versão nova e a hora.';

--
-- Name: salvar_rascunho_regra(text, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_rascunho_regra(p_tipo text, p_edital uuid, p_conteudo jsonb, p_versao_base integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := private."FC_EXIGIR_RASCUNHO_REGRA"(p_tipo, p_edital);
  v_em timestamptz;
begin
  if jsonb_typeof(p_conteudo) is distinct from 'object' then
    raise exception 'Rascunho inválido.' using errcode = '22023';
  end if;
  if octet_length(p_conteudo::text) > 1048576 then
    raise exception 'Rascunho grande demais (até 1 MB).' using errcode = '22023';
  end if;
  if p_versao_base is null or p_versao_base < 0 then
    raise exception 'Versão base inválida.' using errcode = '22023';
  end if;
  insert into public."TB_RASCUNHO_REGRA" ("TP_REGRA", "CO_MONITORAMENTO", "CO_USUARIO", "DS_CONTEUDO", "NU_VERSAO_BASE")
  values (p_tipo, p_edital, v_uid, p_conteudo, p_versao_base)
  on conflict ("TP_REGRA", "CO_MONITORAMENTO", "CO_USUARIO")
  do update set "DS_CONTEUDO" = excluded."DS_CONTEUDO", "NU_VERSAO_BASE" = excluded."NU_VERSAO_BASE",
                "DT_ATUALIZACAO" = now()
  returning "DT_ATUALIZACAO" into v_em;
  return json_build_object('atualizado_em', v_em, 'versao_base', p_versao_base);
end;
$$;

--
-- Name: FUNCTION salvar_rascunho_regra(p_tipo text, p_edital uuid, p_conteudo jsonb, p_versao_base integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_rascunho_regra(p_tipo text, p_edital uuid, p_conteudo jsonb, p_versao_base integer) IS 'Guarda (ou troca) o rascunho não salvo da regra do tipo (ANALISE ou CLASSIFICACAO) no edital, de quem chama: objeto json de até 1 MB e a versão vigente de onde ele partiu. Devolve atualizado_em. Só quem edita a regra.';

--
-- Name: salvar_recurso_candidato(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_recurso_candidato(p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_id uuid;
  v_edital_id uuid;
  v_edital text;
  v_area text;
  v_origem text;
  v_fora boolean;
  v_analise_id uuid;
  v_nota numeric;
  v_resultado text;
  v_responsavel text;
  v_duplicado bigint;
  v_atual public."TB_RECURSO_CANDIDATO";
  v_novo public."TB_RECURSO_CANDIDATO";
  v_texto text;
begin
  if jsonb_typeof(p_dados) is distinct from 'object' then
    raise exception 'Dados inválidos' using errcode = '22023';
  end if;
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  v_id := nullif(p_dados->>'id', '')::uuid;

  if v_id is null then
    -- Cadastro: nasce REGISTRADO; a situação muda só pelo fluxo do parecer.
    v_edital_id := nullif(p_dados->>'edital_id', '')::uuid;
    select m.edital, m."CO_AREA" into v_edital, v_area
    from public."TB_MONITORAMENTO_INDIGENA" m
    where m.id = v_edital_id;
    if v_area is null then
      raise exception 'Edital não encontrado' using errcode = '22023';
    end if;
    perform private."FC_EXIGIR_RECURSOS_NA_AREA"(v_area, 2);
    perform private."FC_EXIGIR_AREA_EDITAL"(v_edital_id::text);

    if coalesce(nullif(p_dados->>'situacao', ''), 'REGISTRADO') <> 'REGISTRADO' then
      raise exception 'O recurso nasce registrado; a decisão é do parecer jurídico' using errcode = '22023';
    end if;
    v_origem := nullif(p_dados->>'origem', '');
    if not exists (select 1 from public."TB_ORIGEM_RECURSO" o where o."CO_ORIGEM_RECURSO" = v_origem and o."ST_ATIVO" = 'S') then
      raise exception 'Origem do recurso inválida' using errcode = '22023';
    end if;
    v_fora := coalesce((p_dados->>'fora_analise')::boolean, false);

    if not v_fora then
      select a.id, a.nota_final_ajustada, a.status_consolidado, a.responsavel_analise
        into v_analise_id, v_nota, v_resultado, v_responsavel
      from public."TB_ANALISE_CURRICULAR" a
      where a.id = nullif(p_dados->>'analise_id', '')::uuid
        and private."FC_ANALISE_DO_EDITAL"(a.edital, v_edital)
        and a."CO_AREA" = v_area;
      if v_analise_id is null then
        raise exception 'Candidato não encontrado nas análises deste edital' using errcode = '22023';
      end if;
      select r."NU_RECURSO" into v_duplicado
      from public."TB_RECURSO_CANDIDATO" r
      where r."CO_ANALISE_CURRICULAR" = v_analise_id
        and r."CO_MONITORAMENTO" = v_edital_id
        and r."CO_ORIGEM_RECURSO" = v_origem
        and r."ST_ATIVO" = 'S'
        and r."TP_SITUACAO" in ('REGISTRADO', 'EM_ANALISE_JURIDICA')
      order by r."NU_RECURSO"
      limit 1;
    else
      v_texto := btrim(coalesce(p_dados->>'nome_informado', ''));
      if length(v_texto) not between 3 and 200 then
        raise exception 'Informe o nome do candidato (3 a 200 caracteres)' using errcode = '22023';
      end if;
      select r."NU_RECURSO" into v_duplicado
      from public."TB_RECURSO_CANDIDATO" r
      where r."ST_FORA_ANALISE" = 'S'
        and private."FC_TEXTO_BUSCA_RECURSO"(r."NO_CANDIDATO_INFORMADO") = private."FC_TEXTO_BUSCA_RECURSO"(v_texto)
        and r."CO_MONITORAMENTO" = v_edital_id
        and r."CO_ORIGEM_RECURSO" = v_origem
        and r."ST_ATIVO" = 'S'
        and r."TP_SITUACAO" in ('REGISTRADO', 'EM_ANALISE_JURIDICA')
      order by r."NU_RECURSO"
      limit 1;
    end if;

    if v_duplicado is not null and not coalesce((p_dados->>'permitir_duplicado')::boolean, false) then
      raise exception 'Já existe o recurso nº % sem decisão para este candidato, edital e origem', v_duplicado
        using errcode = '23505', hint = 'duplicado:' || v_duplicado;
    end if;

    insert into public."TB_RECURSO_CANDIDATO" (
      "CO_MONITORAMENTO", "CO_ORIGEM_RECURSO", "CO_ANALISE_CURRICULAR", "ST_FORA_ANALISE",
      "NO_CANDIDATO_INFORMADO", "CO_CANDIDATO_INFORMADO", "NO_CARGO_INFORMADO", "CO_VAGA_INFORMADA",
      "VL_NOTA_ANTERIOR", "DS_RESULTADO_ANTERIOR", "NO_ANALISTA", "TP_SITUACAO",
      "NU_PROCESSO_SEI", "ST_MUDOU_CLASSIFICACAO", "DS_OBSERVACAO",
      "DT_PROCESSO_SEI", "CO_USUARIO_PROCESSO_SEI",
      "CO_USUARIO_CRIACAO", "CO_USUARIO_ATUALIZACAO"
    ) values (
      v_edital_id, v_origem,
      v_analise_id,
      case when v_fora then 'S' else 'N' end,
      case when v_fora then v_texto end,
      case when v_fora then nullif(btrim(p_dados->>'codigo_informado'), '') end,
      case when v_fora then nullif(btrim(p_dados->>'cargo_informado'), '') end,
      case when v_fora then nullif(btrim(p_dados->>'vaga_informada'), '') end,
      v_nota,
      v_resultado,
      coalesce(nullif(btrim(p_dados->>'analista'), ''), nullif(btrim(v_responsavel), '')),
      'REGISTRADO',
      nullif(btrim(p_dados->>'processo_sei'), ''),
      case when coalesce((p_dados->>'mudou_classificacao')::boolean, false) then 'S' else 'N' end,
      nullif(btrim(p_dados->>'observacao'), ''),
      case when nullif(btrim(p_dados->>'processo_sei'), '') is not null then now() end,
      case when nullif(btrim(p_dados->>'processo_sei'), '') is not null then v_uid end,
      v_uid, v_uid
    )
    returning * into v_novo;

    insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_VALOR_NOVO", "CO_USUARIO")
    values (v_novo."CO_RECURSO_CANDIDATO", 'criacao', v_novo."TP_SITUACAO", v_uid);

    return json_build_object('id', v_novo."CO_RECURSO_CANDIDATO", 'nu', v_novo."NU_RECURSO", 'revisao', v_novo."NU_REVISAO");
  end if;

  -- Edição -------------------------------------------------------------------
  select r.* into v_atual
  from public."TB_RECURSO_CANDIDATO" r
  where r."CO_RECURSO_CANDIDATO" = v_id and r."ST_ATIVO" = 'S'
  for update;
  if not found then
    raise exception 'Recurso não encontrado' using errcode = 'P0002';
  end if;
  select m."CO_AREA" into v_area from public."TB_MONITORAMENTO_INDIGENA" m where m.id = v_atual."CO_MONITORAMENTO";
  perform private."FC_EXIGIR_RECURSOS_NA_AREA"(v_area, 2);
  perform private."FC_EXIGIR_AREA_EDITAL"(v_atual."CO_MONITORAMENTO"::text);
  if (p_dados->>'revisao') is null or (p_dados->>'revisao')::integer <> v_atual."NU_REVISAO" then
    raise exception 'O recurso foi alterado por outra pessoa. Recarregue e tente de novo.' using errcode = 'PT409';
  end if;
  if p_dados ? 'situacao' and coalesce(nullif(p_dados->>'situacao', ''), v_atual."TP_SITUACAO") <> v_atual."TP_SITUACAO" then
    raise exception 'A situação do recurso muda só pelo fluxo do parecer jurídico' using errcode = '22023';
  end if;

  v_novo := v_atual;
  if p_dados ? 'origem' then
    v_novo."CO_ORIGEM_RECURSO" := nullif(p_dados->>'origem', '');
    if v_novo."CO_ORIGEM_RECURSO" is distinct from v_atual."CO_ORIGEM_RECURSO"
       and not exists (select 1 from public."TB_ORIGEM_RECURSO" o where o."CO_ORIGEM_RECURSO" = v_novo."CO_ORIGEM_RECURSO" and o."ST_ATIVO" = 'S') then
      raise exception 'Origem do recurso inválida' using errcode = '22023';
    end if;
  end if;
  if p_dados ? 'analista' then v_novo."NO_ANALISTA" := nullif(btrim(p_dados->>'analista'), ''); end if;
  if p_dados ? 'processo_sei' then v_novo."NU_PROCESSO_SEI" := nullif(btrim(p_dados->>'processo_sei'), ''); end if;
  if p_dados ? 'mudou_classificacao' then
    v_novo."ST_MUDOU_CLASSIFICACAO" := case when coalesce((p_dados->>'mudou_classificacao')::boolean, false) then 'S' else 'N' end;
  end if;
  if p_dados ? 'observacao' then v_novo."DS_OBSERVACAO" := nullif(btrim(p_dados->>'observacao'), ''); end if;
  if v_atual."ST_FORA_ANALISE" = 'S' then
    if p_dados ? 'nome_informado' then
      v_novo."NO_CANDIDATO_INFORMADO" := btrim(coalesce(p_dados->>'nome_informado', ''));
      if length(v_novo."NO_CANDIDATO_INFORMADO") not between 3 and 200 then
        raise exception 'Informe o nome do candidato (3 a 200 caracteres)' using errcode = '22023';
      end if;
    end if;
    if p_dados ? 'codigo_informado' then v_novo."CO_CANDIDATO_INFORMADO" := nullif(btrim(p_dados->>'codigo_informado'), ''); end if;
    if p_dados ? 'cargo_informado' then v_novo."NO_CARGO_INFORMADO" := nullif(btrim(p_dados->>'cargo_informado'), ''); end if;
    if p_dados ? 'vaga_informada' then v_novo."CO_VAGA_INFORMADA" := nullif(btrim(p_dados->>'vaga_informada'), ''); end if;
  end if;

  -- Informar o número do processo SEI marca a etapa "processo SEI criado".
  if v_novo."NU_PROCESSO_SEI" is not null and v_novo."DT_PROCESSO_SEI" is null then
    v_novo."DT_PROCESSO_SEI" := now();
    v_novo."CO_USUARIO_PROCESSO_SEI" := v_uid;
  end if;

  insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
  select v_id, c.acao, c.campo, c.antes, c.depois, v_uid
  from (values
    ('edicao', 'origem', v_atual."CO_ORIGEM_RECURSO", v_novo."CO_ORIGEM_RECURSO"),
    ('edicao', 'analista', v_atual."NO_ANALISTA", v_novo."NO_ANALISTA"),
    ('edicao', 'processo_sei', v_atual."NU_PROCESSO_SEI", v_novo."NU_PROCESSO_SEI"),
    ('edicao', 'mudou_classificacao', v_atual."ST_MUDOU_CLASSIFICACAO", v_novo."ST_MUDOU_CLASSIFICACAO"),
    ('edicao', 'observacao', v_atual."DS_OBSERVACAO", v_novo."DS_OBSERVACAO"),
    ('edicao', 'nome_informado', v_atual."NO_CANDIDATO_INFORMADO", v_novo."NO_CANDIDATO_INFORMADO"),
    ('edicao', 'codigo_informado', v_atual."CO_CANDIDATO_INFORMADO", v_novo."CO_CANDIDATO_INFORMADO"),
    ('edicao', 'cargo_informado', v_atual."NO_CARGO_INFORMADO", v_novo."NO_CARGO_INFORMADO"),
    ('edicao', 'vaga_informada', v_atual."CO_VAGA_INFORMADA", v_novo."CO_VAGA_INFORMADA"),
    ('etapa', 'processo_sei', case when v_atual."DT_PROCESSO_SEI" is null then 'N' else 'S' end, case when v_novo."DT_PROCESSO_SEI" is null then 'N' else 'S' end)
  ) as c(acao, campo, antes, depois)
  where c.antes is distinct from c.depois;
  if not found then
    return json_build_object('id', v_atual."CO_RECURSO_CANDIDATO", 'nu', v_atual."NU_RECURSO", 'revisao', v_atual."NU_REVISAO");
  end if;

  update public."TB_RECURSO_CANDIDATO" set
    "CO_ORIGEM_RECURSO" = v_novo."CO_ORIGEM_RECURSO",
    "NO_ANALISTA" = v_novo."NO_ANALISTA",
    "NU_PROCESSO_SEI" = v_novo."NU_PROCESSO_SEI",
    "ST_MUDOU_CLASSIFICACAO" = v_novo."ST_MUDOU_CLASSIFICACAO",
    "DS_OBSERVACAO" = v_novo."DS_OBSERVACAO",
    "NO_CANDIDATO_INFORMADO" = v_novo."NO_CANDIDATO_INFORMADO",
    "CO_CANDIDATO_INFORMADO" = v_novo."CO_CANDIDATO_INFORMADO",
    "NO_CARGO_INFORMADO" = v_novo."NO_CARGO_INFORMADO",
    "CO_VAGA_INFORMADA" = v_novo."CO_VAGA_INFORMADA",
    "DT_PROCESSO_SEI" = v_novo."DT_PROCESSO_SEI",
    "CO_USUARIO_PROCESSO_SEI" = v_novo."CO_USUARIO_PROCESSO_SEI",
    "NU_REVISAO" = v_atual."NU_REVISAO" + 1,
    "DT_ATUALIZACAO" = now(),
    "CO_USUARIO_ATUALIZACAO" = v_uid
  where "CO_RECURSO_CANDIDATO" = v_id
  returning * into v_novo;

  return json_build_object('id', v_novo."CO_RECURSO_CANDIDATO", 'nu', v_novo."NU_RECURSO", 'revisao', v_novo."NU_REVISAO");
end;
$$;

--
-- Name: FUNCTION salvar_recurso_candidato(p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_recurso_candidato(p_dados jsonb) IS 'Cadastra (sem id; nasce REGISTRADO) ou edita (com id e revisão) um recurso. Cadastro: edital, origem ativa e o candidato das análises do mesmo edital (ou fora_analise com nome); guarda a nota e o resultado do dia; duplicado sem decisão (mesmo candidato, edital e origem) dá 23505 salvo permitir_duplicado. Edição: origem, analista, processo SEI, mudou a classificação, observação e, fora das análises, os dados digitados; revisão desatualizada dá 40001. A situação não muda aqui (22023): é de transicionar_recurso_candidato. Tudo vai para TH_RECURSO_CANDIDATO. Exige recursos >= editor, a área e a coordenação do edital.';

--
-- Name: salvar_regra_agenda_entrevista(uuid, jsonb, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_regra_agenda_entrevista(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_AGENDA_ENTREVISTA"(p_edital, 2);
  v_regra public."TB_REGRA_AGENDA_ENTREVISTA";
  v_nova integer;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_uid uuid := (select auth.uid());
begin
  perform private."FC_VALIDAR_REGRA_AGENDA"(p_configuracao);
  if v_motivo is not null and length(v_motivo) not between 3 and 500 then
    raise exception 'Motivo da alteração entre 3 e 500 caracteres.' using errcode = '22023';
  end if;

  select * into v_regra from public."TB_REGRA_AGENDA_ENTREVISTA" where "CO_MONITORAMENTO" = p_edital for update;
  if v_regra."CO_REGRA_AGENDA" is null then
    if coalesce(p_versao_atual, 0) <> 0 then
      raise exception 'A regra da agenda mudou desde que você abriu; recarregue.' using errcode = 'PT409';
    end if;
    insert into public."TB_REGRA_AGENDA_ENTREVISTA" ("CO_MONITORAMENTO", "NU_VERSAO_VIGENTE", "CO_USUARIO_ATUALIZACAO")
    values (p_edital, 1, v_uid)
    returning * into v_regra;
    v_nova := 1;
  else
    if p_versao_atual is distinct from v_regra."NU_VERSAO_VIGENTE" then
      raise exception 'A regra da agenda mudou desde que você abriu (versão %); recarregue.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
    end if;
    if v_motivo is null then
      raise exception 'Informe o motivo da alteração.' using errcode = '22023';
    end if;
    v_nova := v_regra."NU_VERSAO_VIGENTE" + 1;
    update public."TB_REGRA_AGENDA_ENTREVISTA"
       set "NU_VERSAO_VIGENTE" = v_nova, "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = v_uid
     where "CO_REGRA_AGENDA" = v_regra."CO_REGRA_AGENDA";
  end if;

  insert into public."TH_REGRA_AGENDA_ENTREVISTA" ("CO_REGRA_AGENDA", "NU_VERSAO", "DS_CONFIGURACAO", "DS_MOTIVO", "CO_USUARIO")
  values (v_regra."CO_REGRA_AGENDA", v_nova, p_configuracao, v_motivo, v_uid);

  return private."FC_REGRA_AGENDA_JSON"(p_edital);
end;
$$;

--
-- Name: FUNCTION salvar_regra_agenda_entrevista(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_regra_agenda_entrevista(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text) IS 'Salva a regra da agenda das entrevistas do edital como versão nova (a anterior fica no histórico). p_versao_atual = a versão que a tela abriu (0 sem regra; outra = 40001). Motivo obrigatório a partir da versão 2. Exige entrevistas ou classificacao >= editor, a área e o recorte da coordenação.';

--
-- Name: salvar_regra_analise(uuid, jsonb, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_regra_analise(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text, p_nome text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_regra public."TB_REGRA_ANALISE";
  v_nova integer;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_nome varchar := private."FC_NOME_DA_VERSAO"(p_nome);
  v_uid uuid := (select auth.uid());
begin
  perform private."FC_VALIDAR_REGRA_ANALISE"(p_configuracao);
  if v_motivo is not null and length(v_motivo) > 2000 then
    raise exception 'Motivo com até 2.000 caracteres.' using errcode = '22023';
  end if;

  select * into v_regra from public."TB_REGRA_ANALISE" where "CO_MONITORAMENTO" = p_edital for update;
  if v_regra."CO_REGRA_ANALISE" is null then
    if coalesce(p_versao_atual, 0) <> 0 then
      raise exception 'A regra mudou desde que você abriu; recarregue.' using errcode = 'PT409';
    end if;
    insert into public."TB_REGRA_ANALISE" ("CO_MONITORAMENTO", "NU_VERSAO_VIGENTE", "CO_USUARIO_ATUALIZACAO")
    values (p_edital, 1, v_uid)
    returning * into v_regra;
    v_nova := 1;
  else
    if p_versao_atual is distinct from v_regra."NU_VERSAO_VIGENTE" then
      raise exception 'A regra mudou desde que você abriu (versão %); recarregue.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
    end if;
    if v_motivo is null or length(v_motivo) < 10 then
      raise exception 'Informe o motivo da alteração (10 a 2.000 caracteres).' using errcode = '22023';
    end if;
    v_nova := v_regra."NU_VERSAO_VIGENTE" + 1;
  end if;

  insert into public."TH_REGRA_ANALISE" ("CO_REGRA_ANALISE", "NU_VERSAO", "DS_CONFIGURACAO", "DS_HASH", "DS_MOTIVO", "CO_USUARIO", "NO_VERSAO")
  values (v_regra."CO_REGRA_ANALISE", v_nova, p_configuracao,
          encode(sha256(convert_to(p_configuracao::text, 'UTF8')), 'hex'), coalesce(v_motivo, 'Regra criada do zero'), v_uid, v_nome);

  update public."TB_REGRA_ANALISE"
     set "NU_VERSAO_VIGENTE" = v_nova, "TP_SITUACAO" = 'CONFERIR', "CO_USUARIO_CONFERENCIA" = null, "DT_CONFERENCIA" = null,
         "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = v_uid
   where "CO_REGRA_ANALISE" = v_regra."CO_REGRA_ANALISE";

  return json_build_object(
    'regra', private."FC_REGRA_ANALISE_JSON"(p_edital),
    'fichas_afetadas', coalesce((
      select json_agg(json_build_object('ficha', f."CO_FICHA_ANALISE", 'codigo', c."CO_CANDIDATO_EMPREGARE", 'vaga', f."CO_VAGA",
                                        'versao_regra', f."NU_VERSAO_REGRA", 'resultado', f."TP_RESULTADO", 'nota_final', f."VL_NOTA_FINAL")
                      order by f."CO_VAGA", c."CO_CANDIDATO_EMPREGARE")
        from public."TB_FICHA_ANALISE" f
        join public."TB_EMPREGARE_CANDIDATO" c on c."CO_EMPREGARE_CANDIDATO" = f."CO_EMPREGARE_CANDIDATO"
       where f."CO_REGRA_ANALISE" = v_regra."CO_REGRA_ANALISE" and f."TP_SITUACAO" = 'CONCLUIDA' and f."NU_VERSAO_REGRA" < v_nova), '[]'::json));
end;
$$;

--
-- Name: FUNCTION salvar_regra_analise(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text, p_nome text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_regra_analise(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text, p_nome text) IS 'Salva a regra da avaliação documental do edital como versão nova (a anterior fica no histórico, imutável) e volta a situação para Conferir. p_versao_atual = a versão que a tela abriu (0 sem regra; outra = 40001). Motivo obrigatório da versão 2 em diante (10 a 2.000). p_nome (opcional, 3 a 80): o nome desta versão. fichas_afetadas: as fichas concluídas com versão anterior (código, vaga, versão, resultado e nota) — nenhuma nota muda (AM-2.3); as pendentes e em análise passam a seguir a versão nova. Só a coordenação do edital.';

--
-- Name: salvar_regra_classificacao(uuid, jsonb, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_regra_classificacao(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text, p_nome text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_CLASSIFICACAO_EDITAL"(p_edital, 2);
  v_regra public."TB_REGRA_CLASSIFICACAO";
  v_nova integer;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_nome varchar := private."FC_NOME_DA_VERSAO"(p_nome);
  v_uid uuid := (select auth.uid());
begin
  perform private."FC_VALIDAR_REGRA_CLASSIFICACAO"(p_configuracao);
  if v_motivo is not null and length(v_motivo) not between 3 and 500 then
    raise exception 'Motivo da alteração entre 3 e 500 caracteres.' using errcode = '22023';
  end if;

  select * into v_regra from public."TB_REGRA_CLASSIFICACAO" where "CO_MONITORAMENTO" = p_edital for update;
  if v_regra."CO_REGRA_CLASSIFICACAO" is null then
    if coalesce(p_versao_atual, 0) <> 0 then
      raise exception 'A regra mudou desde que você abriu; recarregue.' using errcode = 'PT409';
    end if;
    insert into public."TB_REGRA_CLASSIFICACAO" ("CO_MONITORAMENTO", "NU_VERSAO_VIGENTE", "CO_USUARIO_ATUALIZACAO")
    values (p_edital, 1, v_uid)
    returning * into v_regra;
    v_nova := 1;
  else
    if p_versao_atual is distinct from v_regra."NU_VERSAO_VIGENTE" then
      raise exception 'A regra mudou desde que você abriu (versão %); recarregue.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
    end if;
    if v_motivo is null then
      raise exception 'Informe o motivo da alteração.' using errcode = '22023';
    end if;
    v_nova := v_regra."NU_VERSAO_VIGENTE" + 1;
  end if;

  insert into public."TH_REGRA_CLASSIFICACAO"
    ("CO_REGRA_CLASSIFICACAO", "NU_VERSAO", "DS_CONFIGURACAO", "TP_EMPATE_FINAL", "DS_MOTIVO", "CO_USUARIO", "NO_VERSAO")
  values (v_regra."CO_REGRA_CLASSIFICACAO", v_nova, p_configuracao, p_configuracao #>> '{empate_final,metodo}', v_motivo, v_uid, v_nome);

  insert into public."RL_REGRA_CRITERIO_DESEMPATE"
    ("CO_REGRA_CLASSIFICACAO", "NU_VERSAO", "NU_ORDEM", "CO_CRITERIO", "TP_DIRECAO")
  select v_regra."CO_REGRA_CLASSIFICACAO", v_nova, d.ordem, upper(d.valor ->> 'criterio'), d.valor ->> 'direcao'
    from jsonb_array_elements(coalesce(p_configuracao -> 'desempate', '[]'::jsonb)) with ordinality d(valor, ordem);

  update public."TB_REGRA_CLASSIFICACAO"
     set "NU_VERSAO_VIGENTE" = v_nova, "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = v_uid
   where "CO_REGRA_CLASSIFICACAO" = v_regra."CO_REGRA_CLASSIFICACAO";

  return private."FC_REGRA_CLASSIFICACAO_JSON"(p_edital);
end;
$$;

--
-- Name: FUNCTION salvar_regra_classificacao(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text, p_nome text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_regra_classificacao(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text, p_nome text) IS 'Salva a regra de classificação do edital como versão nova (a anterior fica no histórico). p_versao_atual = a versão que a tela abriu (0 sem regra; outra = 40001). Motivo obrigatório a partir da versão 2. p_nome (opcional, 3 a 80): o nome desta versão. Exige classificacao >= editor, a área e o recorte da coordenação.';

--
-- Name: salvar_regra_triagem(uuid, jsonb, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_regra_triagem(p_edital uuid, p_configuracao jsonb, p_versao_atual integer, p_motivo text, p_nome text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_area text := private."FC_EXIGIR_COORD_AVALIACAO"(p_edital);
  v_regra public."TB_REGRA_TRIAGEM";
  v_nova integer;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_nome varchar := private."FC_NOME_DA_VERSAO"(p_nome);
  v_uid uuid := (select auth.uid());
begin
  perform private."FC_VALIDAR_REGRA_TRIAGEM"(p_configuracao);
  if v_motivo is null or length(v_motivo) not between 10 and 2000 then
    raise exception 'Informe o motivo da alteração (10 a 2.000 caracteres).' using errcode = '22023';
  end if;
  select * into v_regra from public."TB_REGRA_TRIAGEM" where "CO_MONITORAMENTO" = p_edital for update;
  if v_regra."CO_REGRA_TRIAGEM" is null then
    if coalesce(p_versao_atual, 0) <> 0 then
      raise exception 'A regra da Triagem mudou desde que você abriu; recarregue.' using errcode = 'PT409';
    end if;
    insert into public."TB_REGRA_TRIAGEM" ("CO_MONITORAMENTO", "NU_VERSAO_VIGENTE", "CO_USUARIO_ATUALIZACAO")
    values (p_edital, 1, v_uid)
    returning * into v_regra;
    v_nova := 1;
  else
    if p_versao_atual is distinct from v_regra."NU_VERSAO_VIGENTE" then
      raise exception 'A regra da Triagem mudou desde que você abriu (versão %); recarregue.', v_regra."NU_VERSAO_VIGENTE" using errcode = 'PT409';
    end if;
    v_nova := v_regra."NU_VERSAO_VIGENTE" + 1;
  end if;

  insert into public."TH_REGRA_TRIAGEM" ("CO_REGRA_TRIAGEM", "NU_VERSAO", "DS_CONFIGURACAO", "DS_HASH", "DS_MOTIVO", "CO_USUARIO", "NO_VERSAO")
  values (v_regra."CO_REGRA_TRIAGEM", v_nova, p_configuracao,
          encode(sha256(convert_to(p_configuracao::text, 'UTF8')), 'hex'), v_motivo, v_uid, v_nome);

  -- Versão nova volta a "conferir": o cálculo só usa regra conferida (dupla conferência).
  update public."TB_REGRA_TRIAGEM"
     set "NU_VERSAO_VIGENTE" = v_nova, "TP_SITUACAO" = 'CONFERIR', "CO_USUARIO_CONFERENCIA" = null, "DT_CONFERENCIA" = null,
         "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = v_uid
   where "CO_REGRA_TRIAGEM" = v_regra."CO_REGRA_TRIAGEM";

  return json_build_object('regra', private."FC_REGRA_TRIAGEM_JSON"(p_edital));
end;
$$;

--
-- Name: salvar_responsaveis_do_edital(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_responsaveis_do_edital(p_edital uuid, p_responsaveis uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
declare
  v_usuario uuid := (select auth.uid());
  v_area text;
  v_responsaveis uuid[];
  v_antes jsonb;
  v_depois jsonb;
begin
  if v_usuario is null then
    raise exception 'Sessão não localizada.' using errcode = '28000';
  end if;
  select m."CO_AREA" into v_area from public."TB_MONITORAMENTO_INDIGENA" m where m.id = p_edital;
  if v_area is null then
    raise exception 'Edital não encontrado.' using errcode = 'P0002';
  end if;
  if not private."FC_PODE_EDITAR_DEMANDA"(v_area, p_edital) then
    raise exception 'Sem permissão para editar este edital.' using errcode = '42501';
  end if;
  -- Duas gravações do mesmo edital ao mesmo tempo: uma espera a outra (sem travar a linha do edital).
  perform pg_advisory_xact_lock(hashtext('responsaveis_do_edital:' || p_edital::text)::bigint);

  select coalesce(array_agg(distinct r), '{}') into v_responsaveis
    from unnest(coalesce(p_responsaveis, '{}')) r where r is not null;
  if cardinality(v_responsaveis) > 20 then
    raise exception 'No máximo 20 responsáveis.' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_responsaveis) r
              where not private."FC_PERFIL_PODE_SER_RESPONSAVEL"(r, v_area, p_edital)) then
    raise exception 'Há responsável sem acesso a este edital.' using errcode = '22023';
  end if;

  v_antes := private."FC_RESPONSAVEIS_DO_EDITAL_JSON"(p_edital);

  delete from public."RL_RESPONSAVEL_EDITAL" r
   where r."CO_MONITORAMENTO" = p_edital and not (r."CO_PERFIL_USUARIO" = any (v_responsaveis));
  insert into public."RL_RESPONSAVEL_EDITAL" ("CO_MONITORAMENTO", "CO_PERFIL_USUARIO", "CO_USUARIO_INCLUSAO")
  select p_edital, r, v_usuario from unnest(v_responsaveis) r
  on conflict do nothing;

  v_depois := private."FC_RESPONSAVEIS_DO_EDITAL_JSON"(p_edital);
  if v_antes is distinct from v_depois then
    insert into public."TH_RESPONSAVEL_EDITAL" ("CO_MONITORAMENTO", "DS_ANTES", "DS_DEPOIS", "CO_USUARIO")
    values (p_edital, jsonb_build_object('responsaveis', v_antes),
            jsonb_build_object('responsaveis', v_depois), v_usuario);
  end if;

  return public.obter_responsaveis_do_edital(p_edital);
end;
$$;

--
-- Name: FUNCTION salvar_responsaveis_do_edital(p_edital uuid, p_responsaveis uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_responsaveis_do_edital(p_edital uuid, p_responsaveis uuid[]) IS 'Grava os responsáveis pelo edital (a lista inteira; vazia tira todos). Gestor da área ou administrador global; grava TH_RESPONSAVEL_EDITAL quando muda. 20261104120000.';

--
-- Name: salvar_resposta_recurso(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_resposta_recurso(p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_recurso uuid := nullif(p_dados->>'recurso_id', '')::uuid;
  v_modelo uuid := nullif(p_dados->>'modelo_id', '')::uuid;
  v_versao integer := nullif(p_dados->>'modelo_versao', '')::integer;
  v_fundamentacao text := coalesce(p_dados->>'fundamentacao', '');
  v_texto text := coalesce(p_dados->>'texto_final', '');
  v_area text;
  v_rec public."TB_RECURSO_CANDIDATO";
  v_modelo_linha public."TB_MODELO_RESPOSTA_RECURSO";
  v_atual public."TB_RESPOSTA_RECURSO";
  v_id uuid;
  v_revisao integer;
begin
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  if v_recurso is null then
    raise exception 'Informe o recurso' using errcode = '22023';
  end if;
  v_area := private."FC_EXIGIR_RECURSO_ACESSIVEL"(v_recurso, 2);
  select r.* into v_rec from public."TB_RECURSO_CANDIDATO" r
  where r."CO_RECURSO_CANDIDATO" = v_recurso for update;
  if length(v_fundamentacao) > 20000 then
    raise exception 'A fundamentação passa de 20.000 caracteres' using errcode = '22023';
  end if;
  if length(btrim(v_texto)) not between 1 and 60000 then
    raise exception 'O texto da resposta deve ter de 1 a 60.000 caracteres' using errcode = '22023';
  end if;

  select s.* into v_atual from public."TB_RESPOSTA_RECURSO" s
  where s."CO_RECURSO_CANDIDATO" = v_recurso for update;

  select t.* into v_modelo_linha from public."TB_MODELO_RESPOSTA_RECURSO" t
  where t."CO_MODELO_RESPOSTA" = v_modelo and t."NU_VERSAO" = v_versao;
  if not found then
    raise exception 'Modelo de resposta não encontrado' using errcode = '22023';
  end if;
  -- Modelo novo na resposta: só a versão vigente, ativa, da área e da origem do recurso.
  if v_atual."CO_RESPOSTA_RECURSO" is null
     or v_atual."CO_MODELO_RESPOSTA" <> v_modelo
     or v_atual."NU_VERSAO_MODELO" <> v_versao then
    if v_modelo_linha."ST_VIGENTE" <> 'S' or v_modelo_linha."ST_ATIVO" <> 'S' then
      raise exception 'Este modelo foi alterado ou arquivado. Escolha de novo.' using errcode = '22023';
    end if;
    if v_modelo_linha."CO_AREA" is not null and v_modelo_linha."CO_AREA" <> v_area then
      raise exception 'O modelo é de outra área' using errcode = '22023';
    end if;
    if v_modelo_linha."CO_ORIGEM_RECURSO" is not null and v_modelo_linha."CO_ORIGEM_RECURSO" <> v_rec."CO_ORIGEM_RECURSO" then
      raise exception 'O modelo é de outra origem de recurso' using errcode = '22023';
    end if;
  end if;

  if v_atual."CO_RESPOSTA_RECURSO" is null then
    insert into public."TB_RESPOSTA_RECURSO" (
      "CO_RECURSO_CANDIDATO", "CO_MODELO_RESPOSTA", "NU_VERSAO_MODELO", "DS_FUNDAMENTACAO",
      "DS_TEXTO_FINAL", "CO_USUARIO_AUTOR", "CO_USUARIO_CRIACAO", "CO_USUARIO_ATUALIZACAO"
    ) values (v_recurso, v_modelo, v_versao, v_fundamentacao, v_texto, v_uid, v_uid, v_uid)
    returning "CO_RESPOSTA_RECURSO", "NU_REVISAO" into v_id, v_revisao;
    insert into public."TH_RESPOSTA_RECURSO" (
      "CO_RESPOSTA_RECURSO", "TP_ACAO", "TP_ESTADO_ANTERIOR", "TP_ESTADO_NOVO",
      "CO_MODELO_RESPOSTA", "NU_VERSAO_MODELO", "DS_TEXTO_FINAL", "NU_REVISAO", "CO_USUARIO"
    ) values (v_id, 'criacao', null, 'rascunho', v_modelo, v_versao, v_texto, v_revisao, v_uid);
    insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_NOVO", "CO_USUARIO")
    values (v_recurso, 'resposta', 'criacao', 'rascunho', v_uid);
    return json_build_object('id', v_id, 'revisao', v_revisao, 'estado', 'rascunho');
  end if;

  if p_dados->>'revisao' is null or (p_dados->>'revisao')::integer <> v_atual."NU_REVISAO" then
    raise exception 'Outra pessoa alterou esta resposta. Recarregue e tente de novo.' using errcode = 'PT409';
  end if;
  if v_atual."TP_ESTADO" not in ('rascunho', 'devolvida') then
    raise exception 'A resposta só pode ser editada em rascunho ou devolvida' using errcode = '22023';
  end if;
  update public."TB_RESPOSTA_RECURSO" set
    "CO_MODELO_RESPOSTA" = v_modelo,
    "NU_VERSAO_MODELO" = v_versao,
    "DS_FUNDAMENTACAO" = v_fundamentacao,
    "DS_TEXTO_FINAL" = v_texto,
    "TP_ESTADO" = 'rascunho',
    "CO_USUARIO_AUTOR" = v_uid,
    "NU_REVISAO" = "NU_REVISAO" + 1,
    "DT_ATUALIZACAO" = now(),
    "CO_USUARIO_ATUALIZACAO" = v_uid
  where "CO_RESPOSTA_RECURSO" = v_atual."CO_RESPOSTA_RECURSO"
  returning "NU_REVISAO" into v_revisao;
  insert into public."TH_RESPOSTA_RECURSO" (
    "CO_RESPOSTA_RECURSO", "TP_ACAO", "TP_ESTADO_ANTERIOR", "TP_ESTADO_NOVO",
    "CO_MODELO_RESPOSTA", "NU_VERSAO_MODELO", "DS_TEXTO_FINAL", "NU_REVISAO", "CO_USUARIO"
  ) values (v_atual."CO_RESPOSTA_RECURSO", 'edicao', v_atual."TP_ESTADO", 'rascunho', v_modelo, v_versao, v_texto, v_revisao, v_uid);
  return json_build_object('id', v_atual."CO_RESPOSTA_RECURSO", 'revisao', v_revisao, 'estado', 'rascunho');
end;
$$;

--
-- Name: FUNCTION salvar_resposta_recurso(p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_resposta_recurso(p_dados jsonb) IS 'Cria ou grava o rascunho da resposta de um recurso (modelo + versão, fundamentação e texto final). Edita só em rascunho ou devolvida (volta a rascunho); revisão → 40001. Modelo novo: vigente, ativo, da área e da origem do recurso. Exige recursos >= editor, a área e a coordenação do edital.';

--
-- Name: salvar_roteiro_entrevista(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_roteiro_entrevista(p_dados jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_origem uuid := nullif(p_dados ->> 'origem', '')::uuid;
  v_versao integer := 1;
  v_id uuid := gen_random_uuid();
  v_area text := nullif(p_dados ->> 'area', '');
  v_escala text := coalesce(nullif(p_dados ->> 'escala', ''), 'FAIXA');
  v_nome_versao varchar := private."FC_NOME_DA_VERSAO"(p_dados ->> 'nome_versao');
  k jsonb;
  v_ordem integer := 0;
  v_aspectos text[];
begin
  if not private.pode_recurso('entrevistas', 2) then
    raise exception 'Sem permissão para editar roteiros de entrevista' using errcode = '42501';
  end if;
  if v_area is not null and not private."FC_PODE_AREA"(v_area) then
    raise exception 'Sem acesso a esta área' using errcode = '42501';
  end if;
  if jsonb_typeof(p_dados -> 'competencias') is distinct from 'array'
     or jsonb_array_length(p_dados -> 'competencias') not between 1 and 20 then
    raise exception 'Informe de 1 a 20 competências' using errcode = '22023';
  end if;
  if v_escala = 'LISTA' and jsonb_array_length(coalesce(p_dados -> 'notas_permitidas', '[]')) = 0 then
    raise exception 'Escala em lista precisa das notas permitidas' using errcode = '22023';
  end if;
  if v_escala = 'NIVEIS' and jsonb_array_length(coalesce(p_dados -> 'niveis', '[]')) = 0 then
    raise exception 'Escala por níveis precisa dos níveis' using errcode = '22023';
  end if;

  -- Aspectos (opcionais): [{nome}] ou ["nome"], na ordem; nomes únicos.
  if p_dados ? 'aspectos' and jsonb_typeof(p_dados -> 'aspectos') not in ('array', 'null') then
    raise exception 'Aspectos: informe uma lista' using errcode = '22023';
  end if;
  select coalesce(array_agg(btrim(case when jsonb_typeof(a.valor) = 'string' then a.valor #>> '{}' else a.valor ->> 'nome' end)
                            order by a.ordem), '{}')
    into v_aspectos
    from jsonb_array_elements(case when jsonb_typeof(p_dados -> 'aspectos') = 'array' then p_dados -> 'aspectos' else '[]'::jsonb end)
         with ordinality a(valor, ordem);
  if cardinality(v_aspectos) > 10 then
    raise exception 'Informe até 10 aspectos' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(v_aspectos) n where coalesce(length(n), 0) not between 2 and 60) then
    raise exception 'Nome do aspecto: de 2 a 60 caracteres' using errcode = '22023';
  end if;
  if (select count(distinct lower(n)) from unnest(v_aspectos) n) <> cardinality(v_aspectos) then
    raise exception 'Dois aspectos com o mesmo nome' using errcode = '22023';
  end if;

  if v_origem is not null then
    select coalesce(max(r."NU_VERSAO"), 0) + 1 into v_versao from public."TB_ROTEIRO_ENTREVISTA" r where r."CO_ROTEIRO_ORIGEM" = v_origem;
    if v_versao = 1 then raise exception 'Roteiro de origem não encontrado' using errcode = '22023'; end if;
    update public."TB_ROTEIRO_ENTREVISTA" set "ST_ATIVO" = 'N' where "CO_ROTEIRO_ORIGEM" = v_origem and "ST_ATIVO" = 'S';
  else
    v_origem := v_id;
  end if;

  insert into public."TB_ROTEIRO_ENTREVISTA" ("CO_ROTEIRO", "CO_ROTEIRO_ORIGEM", "NU_VERSAO", "CO_AREA", "NO_ROTEIRO",
    "DS_DESCRICAO", "NO_ETAPA", "TP_ESCALA", "VL_PASSO", "DS_NOTAS_PERMITIDAS", "VL_NOTA_MINIMA_TOTAL",
    "DS_NOTAS_ELIMINATORIAS", "ST_AUSENCIA_ELIMINA", "DS_DESEMPATE", "ST_SOMA_ANALISE", "DS_CONVOCACAO_PADRAO",
    "DS_BANCA_PADRAO", "CO_USUARIO_CRIACAO", "NO_VERSAO")
  values (v_id, v_origem, v_versao, v_area, btrim(p_dados ->> 'nome'), nullif(btrim(coalesce(p_dados ->> 'descricao', '')), ''),
    coalesce(nullif(btrim(coalesce(p_dados ->> 'etapa', '')), ''), 'Entrevista'), v_escala,
    coalesce(nullif(p_dados ->> 'passo', '')::numeric, 0.5), coalesce(p_dados -> 'notas_permitidas', '[]'),
    nullif(p_dados ->> 'nota_minima_total', '')::numeric,
    -- Com aspectos, a eliminação é pelo mínimo da competência: sem notas eliminatórias.
    case when cardinality(v_aspectos) > 0 then '[]'::jsonb else coalesce(p_dados -> 'notas_eliminatorias', '[]') end,
    case when coalesce((p_dados ->> 'ausencia_elimina')::boolean, true) then 'S' else 'N' end,
    coalesce(p_dados -> 'desempate', '[]'),
    case when coalesce((p_dados ->> 'soma_analise')::boolean, true) then 'S' else 'N' end,
    coalesce(p_dados -> 'convocacao_padrao', '{}'), coalesce(p_dados -> 'banca_padrao', '[]'), (select auth.uid()), v_nome_versao);

  for k in select value from jsonb_array_elements(p_dados -> 'competencias') loop
    v_ordem := v_ordem + 1;
    insert into public."TB_ROTEIRO_COMPETENCIA" ("CO_ROTEIRO", "NU_ORDEM", "NO_COMPETENCIA", "DS_DESCRICAO",
      "VL_NOTA_MAXIMA", "VL_PESO", "VL_MINIMO", "TP_MINIMO", "TP_AVALIACAO")
    values (v_id, v_ordem, btrim(k ->> 'nome'), nullif(btrim(coalesce(k ->> 'descricao', '')), ''),
      (k ->> 'nota_maxima')::numeric, coalesce(nullif(k ->> 'peso', '')::numeric, 1), nullif(k ->> 'minimo', '')::numeric,
      coalesce(nullif(k ->> 'tipo_minimo', ''), 'VALOR'), coalesce(nullif(k ->> 'avaliacao', ''), 'INDIVIDUAL'));
  end loop;

  insert into public."TB_ROTEIRO_NIVEL" ("CO_ROTEIRO", "VL_NOTA", "NO_NIVEL", "DS_DESCRICAO")
  select v_id, (n ->> 'nota')::numeric, btrim(n ->> 'nome'), nullif(btrim(coalesce(n ->> 'descricao', '')), '')
    from jsonb_array_elements(coalesce(p_dados -> 'niveis', '[]')) n;

  insert into public."TB_ROTEIRO_ASPECTO" ("CO_ROTEIRO", "NU_ORDEM", "NO_ASPECTO")
  select v_id, a.ordem, a.nome from unnest(v_aspectos) with ordinality a(nome, ordem);

  return private."FC_ROTEIRO_JSON"(v_id);
end;
$$;

--
-- Name: FUNCTION salvar_roteiro_entrevista(p_dados jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_roteiro_entrevista(p_dados jsonb) IS 'Cria um roteiro ou uma versão nova de um roteiro (p_dados.origem); a versão anterior deixa de ser oferecida, mas os editais que a usam continuam nela. p_dados.nome_versao (opcional, 3 a 80): o nome desta versão. p_dados.aspectos (opcional, até 10): cada avaliador dá uma nota por aspecto; com aspectos, as notas eliminatórias gravam vazias. entrevistas >= editor.';

--
-- Name: salvar_situacao_modulos(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_situacao_modulos(p_alteracoes jsonb, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  item jsonb;
  v_escopo text;
  v_area text;
  v_aba text;
  v_painel uuid;
  v_campo text;
  v_valor text;
  v_anterior text;
  v_qt integer := 0;
  v_uid uuid := (select auth.uid());
begin
  if not private.is_master() then
    raise exception 'Somente o administrador global gerencia módulos e abas' using errcode = '42501';
  end if;
  if jsonb_typeof(p_alteracoes) is distinct from 'array' or jsonb_array_length(p_alteracoes) not between 1 and 200 then
    raise exception 'Alterações inválidas' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_motivo, ''))) not between 3 and 500 then
    raise exception 'Informe um motivo entre 3 e 500 caracteres' using errcode = '22023';
  end if;

  for item in select value from jsonb_array_elements(p_alteracoes) loop
    v_escopo := item ->> 'escopo';
    v_area := nullif(item ->> 'area', '');
    v_aba := nullif(item ->> 'aba', '');
    v_painel := nullif(item ->> 'painel', '')::uuid;
    v_campo := item ->> 'campo';
    v_valor := nullif(btrim(coalesce(item ->> 'valor', '')), '');

    if v_campo not in ('ativo', 'situacao', 'mensagem', 'previsao', 'beta', 'comemoracoes') then
      raise exception 'Campo inválido: %', v_campo using errcode = '22023';
    end if;
    if v_campo in ('ativo', 'beta', 'comemoracoes') and v_valor not in ('S', 'N') then
      raise exception 'Use S ou N em %', v_campo using errcode = '22023';
    end if;
    if v_campo = 'situacao' and v_valor not in ('ATIVA', 'MANUTENCAO') then
      raise exception 'Situação inválida: %', v_valor using errcode = '22023';
    end if;
    if v_campo = 'mensagem' and length(coalesce(v_valor, '')) > 500 then
      raise exception 'Mensagem com mais de 500 caracteres' using errcode = '22023';
    end if;
    if v_campo = 'previsao' and v_valor is not null and v_valor !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'Previsão deve ser uma data (aaaa-mm-dd)' using errcode = '22023';
    end if;
    if v_campo = 'beta' and v_escopo <> 'aba' then
      raise exception 'O selo BETA é da aba' using errcode = '22023';
    end if;

    if v_escopo = 'sistema' then
      if v_campo not in ('situacao', 'mensagem', 'previsao', 'comemoracoes') then
        raise exception 'O sistema inteiro só entra ou sai de manutenção (ou liga/desliga as comemorações)' using errcode = '22023';
      end if;
      select case v_campo when 'situacao' then s."TP_SITUACAO" when 'mensagem' then s."DS_MENSAGEM_MANUTENCAO"
                          when 'comemoracoes' then s."ST_COMEMORACAO"
                          else s."DT_PREVISAO_RETORNO"::text end
        into v_anterior from public."TB_SITUACAO_SISTEMA" s where s."CO_SITUACAO_SISTEMA" = 1;
      if v_anterior is not distinct from v_valor then continue; end if;
      update public."TB_SITUACAO_SISTEMA" set
        "TP_SITUACAO" = case when v_campo = 'situacao' then v_valor else "TP_SITUACAO" end,
        "DS_MENSAGEM_MANUTENCAO" = case when v_campo = 'mensagem' then v_valor else "DS_MENSAGEM_MANUTENCAO" end,
        "DT_PREVISAO_RETORNO" = case when v_campo = 'previsao' then v_valor::date else "DT_PREVISAO_RETORNO" end,
        "ST_COMEMORACAO" = case when v_campo = 'comemoracoes' then v_valor else "ST_COMEMORACAO" end,
        "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = v_uid
       where "CO_SITUACAO_SISTEMA" = 1;

    elsif v_escopo = 'area' then
      if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = v_area) then
        raise exception 'Área inválida' using errcode = '22023';
      end if;
      select case v_campo when 'ativo' then a."ST_ATIVO" when 'situacao' then a."TP_SITUACAO"
                          when 'mensagem' then a."DS_MENSAGEM_MANUTENCAO" else a."DT_PREVISAO_RETORNO"::text end
        into v_anterior from public."TB_AREA" a where a."CO_AREA" = v_area;
      if v_anterior is not distinct from v_valor then continue; end if;
      update public."TB_AREA" set
        "ST_ATIVO" = case when v_campo = 'ativo' then v_valor else "ST_ATIVO" end,
        "TP_SITUACAO" = case when v_campo = 'situacao' then v_valor else "TP_SITUACAO" end,
        "DS_MENSAGEM_MANUTENCAO" = case when v_campo = 'mensagem' then v_valor else "DS_MENSAGEM_MANUTENCAO" end,
        "DT_PREVISAO_RETORNO" = case when v_campo = 'previsao' then v_valor::date else "DT_PREVISAO_RETORNO" end
       where "CO_AREA" = v_area;

    elsif v_escopo = 'aba' then
      if not exists (select 1 from public."TB_ABA" b where b."CO_ABA" = v_aba) then
        raise exception 'Aba inválida' using errcode = '22023';
      end if;
      select case v_campo when 'ativo' then b."ST_ATIVO" when 'situacao' then b."TP_SITUACAO"
                          when 'mensagem' then b."DS_MENSAGEM_MANUTENCAO" when 'beta' then b."ST_BETA"
                          else b."DT_PREVISAO_RETORNO"::text end
        into v_anterior from public."TB_ABA" b where b."CO_ABA" = v_aba;
      if v_anterior is not distinct from v_valor then continue; end if;
      update public."TB_ABA" set
        "ST_ATIVO" = case when v_campo = 'ativo' then v_valor else "ST_ATIVO" end,
        "TP_SITUACAO" = case when v_campo = 'situacao' then v_valor else "TP_SITUACAO" end,
        "DS_MENSAGEM_MANUTENCAO" = case when v_campo = 'mensagem' then v_valor else "DS_MENSAGEM_MANUTENCAO" end,
        "DT_PREVISAO_RETORNO" = case when v_campo = 'previsao' then v_valor::date else "DT_PREVISAO_RETORNO" end,
        "ST_BETA" = case when v_campo = 'beta' then v_valor else "ST_BETA" end,
        "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = v_uid
       where "CO_ABA" = v_aba;

    elsif v_escopo = 'aba_area' then
      if not exists (select 1 from public."RL_ABA_AREA" r where r."CO_ABA" = v_aba and r."CO_AREA" = v_area) then
        raise exception 'Aba % não existe na área %', v_aba, v_area using errcode = '22023';
      end if;
      select case v_campo when 'ativo' then r."ST_ATIVO" when 'situacao' then r."TP_SITUACAO"
                          when 'mensagem' then r."DS_MENSAGEM_MANUTENCAO" else r."DT_PREVISAO_RETORNO"::text end
        into v_anterior from public."RL_ABA_AREA" r where r."CO_ABA" = v_aba and r."CO_AREA" = v_area;
      if v_anterior is not distinct from v_valor then continue; end if;
      update public."RL_ABA_AREA" set
        "ST_ATIVO" = case when v_campo = 'ativo' then v_valor else "ST_ATIVO" end,
        "TP_SITUACAO" = case when v_campo = 'situacao' then v_valor else "TP_SITUACAO" end,
        "DS_MENSAGEM_MANUTENCAO" = case when v_campo = 'mensagem' then v_valor else "DS_MENSAGEM_MANUTENCAO" end,
        "DT_PREVISAO_RETORNO" = case when v_campo = 'previsao' then v_valor::date else "DT_PREVISAO_RETORNO" end,
        "DT_ATUALIZACAO" = now(), "CO_USUARIO_ATUALIZACAO" = v_uid
       where "CO_ABA" = v_aba and "CO_AREA" = v_area;

    elsif v_escopo = 'painel' then
      if v_campo not in ('ativo', 'situacao') then
        raise exception 'Painel externo aceita só ativo e situação' using errcode = '22023';
      end if;
      select case v_campo when 'ativo' then case when p.ativo then 'S' else 'N' end
                          else case when p.em_manutencao then 'MANUTENCAO' else 'ATIVA' end end
        into v_anterior from public."TB_PAINEL_EXTERNO" p where p.id = v_painel;
      if not found then raise exception 'Painel inválido' using errcode = '22023'; end if;
      if v_anterior is not distinct from v_valor then continue; end if;
      update public."TB_PAINEL_EXTERNO" set
        ativo = case when v_campo = 'ativo' then v_valor = 'S' else ativo end,
        em_manutencao = case when v_campo = 'situacao' then v_valor = 'MANUTENCAO' else em_manutencao end,
        updated_at = now()
       where id = v_painel;

    else
      raise exception 'Escopo inválido: %', v_escopo using errcode = '22023';
    end if;

    insert into public."TH_SITUACAO_MODULO"
      ("TP_ESCOPO", "CO_AREA", "CO_ABA", "CO_PAINEL", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "DS_MOTIVO", "CO_USUARIO")
    values (v_escopo, v_area, v_aba, v_painel, v_campo, v_anterior, v_valor, btrim(p_motivo), v_uid);
    v_qt := v_qt + 1;
  end loop;

  -- Guarda: pelo menos uma área ativa (senão ninguém teria menu).
  if not exists (select 1 from public."TB_AREA" a where a."ST_ATIVO" = 'S') then
    raise exception 'Pelo menos uma área precisa ficar ativa' using errcode = '23514';
  end if;

  return jsonb_build_object('alteradas', v_qt);
end;
$_$;

--
-- Name: FUNCTION salvar_situacao_modulos(p_alteracoes jsonb, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.salvar_situacao_modulos(p_alteracoes jsonb, p_motivo text) IS 'Grava, em lote, ativo/situação/mensagem/previsão/beta de sistema, áreas, abas, abas por área e painéis externos, com histórico em TH_SITUACAO_MODULO. Itens: {escopo, area?, aba?, painel?, campo, valor}. Só administrador global.';

--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

--
-- Name: sincronizar_entrevistas(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sincronizar_entrevistas(p_sync text, p_area text, p_linhas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_qt integer;
begin
  if p_sync is null or p_sync !~ '^[A-Za-z0-9_-]{8,80}$' then
    raise exception 'Identificador de carga inválido' using errcode = '22023';
  end if;
  if not exists (select 1 from public."TB_AREA" a where a."CO_AREA" = p_area) then
    raise exception 'Área inválida' using errcode = '22023';
  end if;
  if jsonb_typeof(p_linhas) is distinct from 'array' or jsonb_array_length(p_linhas) not between 1 and 1000 then
    raise exception 'Envie de 1 a 1000 linhas por lote' using errcode = '22023';
  end if;

  insert into public."TL_SYNC_ENTREVISTA" ("CO_SYNC", "CO_AREA")
  values (p_sync, p_area)
  on conflict ("CO_SYNC") do nothing;
  if exists (select 1 from public."TL_SYNC_ENTREVISTA" s
              where s."CO_SYNC" = p_sync and (s."CO_AREA" <> p_area or s."TP_SITUACAO" <> 'EM_ANDAMENTO')) then
    raise exception 'Carga % já fechada ou de outra área', p_sync using errcode = '22023';
  end if;

  create temporary table if not exists pg_temp.tmp_entrevista_lote (
    chave text, unidade text, edital text, vaga text, candidato text, codigo text,
    modalidade text, cargo text, nota numeric, parecer text, compareceu text,
    link text, notas jsonb
  ) on commit drop;
  truncate pg_temp.tmp_entrevista_lote;

  insert into pg_temp.tmp_entrevista_lote
  select distinct on (x.chave) x.*
    from (
      select
        p_area || '|' || coalesce(private."FC_NUMERO_EDITAL"(l.edital), lower(l.edital)) || '|' || l.vaga || '|' ||
          coalesce(nullif(l.codigo, ''), 'nome:' || private."FC_TEXTO_BUSCA_RECURSO"(l.candidato)) as chave,
        l.unidade, l.edital, l.vaga, l.candidato, nullif(l.codigo, '') as codigo,
        nullif(array_to_string(array(
          select btrim(t) from unnest(string_to_array(replace(coalesce(l.modalidade, ''), '"', ''), ',')) t
           where btrim(t) <> ''), ' / '), '') as modalidade,
        nullif(l.cargo, '') as cargo,
        case when l.nota ~ '^-?\d+([.,]\d+)?$' then replace(l.nota, ',', '.')::numeric end as nota,
        case
          when private."FC_TEXTO_BUSCA_RECURSO"(l.parecer) ~ '(inapto|reprovad|nao apto)' then 'INAPTO'
          when private."FC_TEXTO_BUSCA_RECURSO"(l.parecer) ~ 'apto' then 'APTO'
          else 'SEM_PARECER' end as parecer,
        case
          when private."FC_TEXTO_BUSCA_RECURSO"(l.compareceu) ~ '^(nao|n|ausente|faltou)' then 'N'
          when private."FC_TEXTO_BUSCA_RECURSO"(l.compareceu) ~ '^(sim|s|compareceu|presente)' then 'S'
          end as compareceu,
        nullif(l.link, '') as link,
        coalesce(l.notas, '[]'::jsonb) as notas
      from jsonb_to_recordset(p_linhas) as l(
        unidade text, edital text, vaga text, candidato text, codigo text, modalidade text,
        cargo text, nota text, parecer text, compareceu text, link text, notas jsonb)
      where btrim(coalesce(l.candidato, '')) <> ''
        and btrim(coalesce(l.vaga, '')) <> ''
        and btrim(coalesce(l.edital, '')) <> ''
    ) x
   order by x.chave;

  insert into public."TB_ENTREVISTA" as e (
    "CO_AREA", "NO_UNIDADE", "DS_EDITAL", "CO_VAGA", "NO_CANDIDATO", "CO_CANDIDATO",
    "DS_MODALIDADE", "NO_CARGO", "VL_NOTA_TOTAL", "TP_PARECER", "ST_COMPARECEU",
    "DS_LINK_PLANILHA", "TP_ORIGEM", "DS_CHAVE_ORIGEM", "CO_SYNC", "ST_ATIVO")
  select p_area, left(coalesce(t.unidade, ''), 200), left(t.edital, 120), left(t.vaga, 60),
         left(t.candidato, 200), left(t.codigo, 60), left(t.modalidade, 300), left(t.cargo, 400),
         t.nota, t.parecer, t.compareceu, left(t.link, 500), 'planilha', t.chave, p_sync, 'S'
    from pg_temp.tmp_entrevista_lote t
  on conflict ("DS_CHAVE_ORIGEM") do update set
    "NO_UNIDADE" = excluded."NO_UNIDADE",
    "DS_EDITAL" = excluded."DS_EDITAL",
    "NO_CANDIDATO" = excluded."NO_CANDIDATO",
    "CO_CANDIDATO" = excluded."CO_CANDIDATO",
    "DS_MODALIDADE" = excluded."DS_MODALIDADE",
    "NO_CARGO" = excluded."NO_CARGO",
    "VL_NOTA_TOTAL" = excluded."VL_NOTA_TOTAL",
    "TP_PARECER" = excluded."TP_PARECER",
    "ST_COMPARECEU" = excluded."ST_COMPARECEU",
    "DS_LINK_PLANILHA" = excluded."DS_LINK_PLANILHA",
    "CO_SYNC" = excluded."CO_SYNC",
    "ST_ATIVO" = 'S',
    "DT_ATUALIZACAO" = now()
  where e."TP_ORIGEM" = 'planilha'
    -- Só a entrevista que mudou (20261103150000): a carga regravava todas a cada
    -- rodada (92 mil updates em 4,6 mil linhas). A linha igual fica com o CO_SYNC
    -- antigo; quem diz que ela veio nesta carga é private."TL_CHAVE_DA_CARGA".
    and (e."NO_UNIDADE", e."DS_EDITAL", e."NO_CANDIDATO", e."CO_CANDIDATO", e."DS_MODALIDADE",
         e."NO_CARGO", e."VL_NOTA_TOTAL", e."TP_PARECER", e."ST_COMPARECEU", e."DS_LINK_PLANILHA",
         e."ST_ATIVO")
        is distinct from
        (excluded."NO_UNIDADE", excluded."DS_EDITAL", excluded."NO_CANDIDATO", excluded."CO_CANDIDATO",
         excluded."DS_MODALIDADE", excluded."NO_CARGO", excluded."VL_NOTA_TOTAL", excluded."TP_PARECER",
         excluded."ST_COMPARECEU", excluded."DS_LINK_PLANILHA", 'S');

  -- As chaves vistas nesta carga: finalizar_sync_entrevistas desativa só quem não veio.
  insert into private."TL_CHAVE_DA_CARGA" ("TP_CARGA", "CO_SYNC", "DS_CHAVE_ORIGEM")
  select 'ENTREVISTA', p_sync, t.chave from pg_temp.tmp_entrevista_lote t
  on conflict do nothing;

  -- Notas: upsert por ordem; ordem que sumiu fica com nota nula (nada é apagado).
  with n as (
    select e."CO_ENTREVISTA", (c.ord)::smallint as ordem,
           left(private."FC_CRITERIO_ENTREVISTA"(c.item->>'criterio'), 600) as criterio,
           case when (c.item->>'nota') ~ '^-?\d+([.,]\d+)?$' then replace(c.item->>'nota', ',', '.')::numeric end as nota
      from pg_temp.tmp_entrevista_lote t
      join public."TB_ENTREVISTA" e on e."DS_CHAVE_ORIGEM" = t.chave and e."TP_ORIGEM" = 'planilha'
      cross join lateral jsonb_array_elements(t.notas) with ordinality c(item, ord)
     where c.ord between 1 and 20 and btrim(coalesce(c.item->>'criterio', '')) <> ''
  )
  insert into public."TB_ENTREVISTA_NOTA" ("CO_ENTREVISTA", "NU_ORDEM", "DS_CRITERIO", "VL_NOTA")
  select "CO_ENTREVISTA", ordem, criterio, nota from n
  on conflict ("CO_ENTREVISTA", "NU_ORDEM") do update set
    "DS_CRITERIO" = excluded."DS_CRITERIO", "VL_NOTA" = excluded."VL_NOTA"
  -- Só a nota que mudou (20261009110000): a carga de hora em hora regravava todas
  -- (~100 mil linhas/dia, ~45 MB/dia de WAL que o Realtime decodifica).
  where ("TB_ENTREVISTA_NOTA"."DS_CRITERIO", "TB_ENTREVISTA_NOTA"."VL_NOTA")
        is distinct from (excluded."DS_CRITERIO", excluded."VL_NOTA");

  update public."TB_ENTREVISTA_NOTA" en set "VL_NOTA" = null
    from pg_temp.tmp_entrevista_lote t
    join public."TB_ENTREVISTA" e on e."DS_CHAVE_ORIGEM" = t.chave and e."TP_ORIGEM" = 'planilha'
   where en."CO_ENTREVISTA" = e."CO_ENTREVISTA"
     and en."NU_ORDEM" > (select count(*) from jsonb_array_elements(t.notas) x
                           where btrim(coalesce(x->>'criterio', '')) <> '')
     and en."VL_NOTA" is not null;

  select count(*) into v_qt from pg_temp.tmp_entrevista_lote;
  update public."TL_SYNC_ENTREVISTA" set "QT_LINHA" = "QT_LINHA" + v_qt where "CO_SYNC" = p_sync;
  return jsonb_build_object('recebidas', jsonb_array_length(p_linhas), 'gravadas', v_qt);
end;
$_$;

--
-- Name: FUNCTION sincronizar_entrevistas(p_sync text, p_area text, p_linhas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sincronizar_entrevistas(p_sync text, p_area text, p_linhas jsonb) IS 'Recebe um lote (até 1000) de linhas da aba Entrevistados e faz upsert em TB_ENTREVISTA/TB_ENTREVISTA_NOTA, só do que mudou; as chaves do lote vão para private."TL_CHAVE_DA_CARGA" (20261103150000). Só service_role (Apps Script). Fechar com finalizar_sync_entrevistas.';

--
-- Name: sincronizar_selecao(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sincronizar_selecao(p_sync text, p_linhas jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_qt integer;
begin
  if p_sync is null or p_sync !~ '^[A-Za-z0-9_-]{8,80}$' then
    raise exception 'Identificador de carga inválido' using errcode = '22023';
  end if;
  if jsonb_typeof(p_linhas) is distinct from 'array' or jsonb_array_length(p_linhas) not between 1 and 1000 then
    raise exception 'Envie de 1 a 1000 linhas por lote' using errcode = '22023';
  end if;

  insert into public."TL_SYNC_SELECAO" ("CO_SYNC") values (p_sync) on conflict ("CO_SYNC") do nothing;
  if exists (select 1 from public."TL_SYNC_SELECAO" s
              where s."CO_SYNC" = p_sync and s."TP_SITUACAO" <> 'EM_ANDAMENTO') then
    raise exception 'Carga % já fechada', p_sync using errcode = '22023';
  end if;

  create temporary table if not exists pg_temp.tmp_selecao_lote (
    chave text, edital text, vaga text, co_vaga text, unidade text, cargo text,
    inscritos integer, aptos integer, cancelados integer, reprovados_questionario integer,
    eliminados_nota integer, reprovados_analise integer, triados integer,
    total_eliminados integer, convocados integer, observacao text
  ) on commit drop;
  truncate pg_temp.tmp_selecao_lote;

  -- Números: o script já manda inteiros; aqui só se aceita inteiro (ou nulo).
  insert into pg_temp.tmp_selecao_lote
  select distinct on (x.chave) x.*
    from (
      select
        coalesce(private."FC_NUMERO_EDITAL"(l.edital), private."FC_TEXTO_BUSCA_RECURSO"(l.edital)) || '|' ||
          case when btrim(l.vaga) ~ '^[0-9]{1,20}$' then btrim(l.vaga)
               else 'cargo:' || private."FC_TEXTO_BUSCA_RECURSO"(l.vaga) end ||
          -- Vaga de mesmo nome e números diferentes (outras bancas): 2ª, 3ª…
          case when l.repeticao ~ '^[0-9]{1,3}$' and l.repeticao::integer > 1 then '#' || l.repeticao else '' end as chave,
        btrim(l.edital) as edital,
        btrim(l.vaga) as vaga,
        case when btrim(l.vaga) ~ '^[0-9]{1,20}$' then btrim(l.vaga) end as co_vaga,
        nullif(btrim(l.unidade), '') as unidade,
        coalesce(nullif(btrim(l.cargo), ''), btrim(l.vaga)) as cargo,
        case when l.inscritos ~ '^-?[0-9]{1,9}$' then l.inscritos::integer end,
        case when l.aptos ~ '^-?[0-9]{1,9}$' then l.aptos::integer end,
        case when l.cancelados ~ '^-?[0-9]{1,9}$' then l.cancelados::integer end,
        case when l.reprovados_questionario ~ '^-?[0-9]{1,9}$' then l.reprovados_questionario::integer end,
        case when l.eliminados_nota ~ '^-?[0-9]{1,9}$' then l.eliminados_nota::integer end,
        case when l.reprovados_analise ~ '^-?[0-9]{1,9}$' then l.reprovados_analise::integer end,
        case when l.triados ~ '^-?[0-9]{1,9}$' then l.triados::integer end,
        case when l.total_eliminados ~ '^-?[0-9]{1,9}$' then l.total_eliminados::integer end,
        case when l.convocados ~ '^-?[0-9]{1,9}$' then l.convocados::integer end,
        nullif(btrim(l.observacao), '') as observacao
      from jsonb_to_recordset(p_linhas) as l(
        edital text, vaga text, unidade text, cargo text, inscritos text, aptos text,
        cancelados text, reprovados_questionario text, eliminados_nota text,
        reprovados_analise text, triados text, total_eliminados text, convocados text,
        observacao text, repeticao text)
      where btrim(coalesce(l.edital, '')) <> '' and btrim(coalesce(l.vaga, '')) <> ''
    ) x
   order by x.chave;

  insert into public."TB_SELECAO_VAGA" as s (
    "CO_AREA", "DS_EDITAL", "CO_VAGA", "DS_VAGA_PLANILHA", "NO_UNIDADE", "NO_CARGO",
    "QT_INSCRITO", "QT_APTO_ANALISE", "QT_CANCELADO", "QT_REPROVADO_QUESTIONARIO",
    "QT_ELIMINADO_NOTA", "QT_REPROVADO_ANALISE", "QT_TRIADO", "QT_TOTAL_ELIMINADO",
    "QT_CONVOCADO_PLANILHA", "DS_OBSERVACAO", "DS_CHAVE_ORIGEM", "CO_SYNC", "ST_REGISTRO_ATIVO")
  select
    -- Área provisória pela unidade; finalizar_sync_selecao acerta pelo edital.
    coalesce((select u."CO_AREA" from public."TA_UNIDADE_AREA" u
               where private."FC_TEXTO_BUSCA_RECURSO"(u."NO_UNIDADE") = private."FC_TEXTO_BUSCA_RECURSO"(t.unidade)
               limit 1), 'saude-indigena'),
    left(t.edital, 120), t.co_vaga, left(t.vaga, 400), left(t.unidade, 200), left(t.cargo, 400),
    t.inscritos, t.aptos, t.cancelados, t.reprovados_questionario, t.eliminados_nota,
    t.reprovados_analise, t.triados, t.total_eliminados, t.convocados, left(t.observacao, 1000),
    t.chave, p_sync, 'S'
    from pg_temp.tmp_selecao_lote t
  on conflict ("DS_CHAVE_ORIGEM") do update set
    "DS_EDITAL" = excluded."DS_EDITAL",
    "DS_VAGA_PLANILHA" = excluded."DS_VAGA_PLANILHA",
    "NO_UNIDADE" = excluded."NO_UNIDADE",
    "NO_CARGO" = excluded."NO_CARGO",
    "QT_INSCRITO" = excluded."QT_INSCRITO",
    "QT_APTO_ANALISE" = excluded."QT_APTO_ANALISE",
    "QT_CANCELADO" = excluded."QT_CANCELADO",
    "QT_REPROVADO_QUESTIONARIO" = excluded."QT_REPROVADO_QUESTIONARIO",
    "QT_ELIMINADO_NOTA" = excluded."QT_ELIMINADO_NOTA",
    "QT_REPROVADO_ANALISE" = excluded."QT_REPROVADO_ANALISE",
    "QT_TRIADO" = excluded."QT_TRIADO",
    "QT_TOTAL_ELIMINADO" = excluded."QT_TOTAL_ELIMINADO",
    "QT_CONVOCADO_PLANILHA" = excluded."QT_CONVOCADO_PLANILHA",
    "DS_OBSERVACAO" = excluded."DS_OBSERVACAO",
    "CO_SYNC" = excluded."CO_SYNC",
    "ST_REGISTRO_ATIVO" = 'S',
    "DT_ATUALIZACAO" = now()
  -- Só a vaga que mudou (20261103150000): a carga regravava todas a cada rodada
  -- (76 mil updates em 3,4 mil linhas). A linha igual fica com o CO_SYNC antigo;
  -- quem diz que ela veio nesta carga é private."TL_CHAVE_DA_CARGA" (abaixo).
  where (s."DS_EDITAL", s."DS_VAGA_PLANILHA", s."NO_UNIDADE", s."NO_CARGO",
         s."QT_INSCRITO", s."QT_APTO_ANALISE", s."QT_CANCELADO", s."QT_REPROVADO_QUESTIONARIO",
         s."QT_ELIMINADO_NOTA", s."QT_REPROVADO_ANALISE", s."QT_TRIADO", s."QT_TOTAL_ELIMINADO",
         s."QT_CONVOCADO_PLANILHA", s."DS_OBSERVACAO", s."ST_REGISTRO_ATIVO")
        is distinct from
        (excluded."DS_EDITAL", excluded."DS_VAGA_PLANILHA", excluded."NO_UNIDADE", excluded."NO_CARGO",
         excluded."QT_INSCRITO", excluded."QT_APTO_ANALISE", excluded."QT_CANCELADO", excluded."QT_REPROVADO_QUESTIONARIO",
         excluded."QT_ELIMINADO_NOTA", excluded."QT_REPROVADO_ANALISE", excluded."QT_TRIADO", excluded."QT_TOTAL_ELIMINADO",
         excluded."QT_CONVOCADO_PLANILHA", excluded."DS_OBSERVACAO", 'S');

  -- As chaves vistas nesta carga: finalizar_sync_selecao desativa só quem não veio.
  insert into private."TL_CHAVE_DA_CARGA" ("TP_CARGA", "CO_SYNC", "DS_CHAVE_ORIGEM")
  select 'SELECAO', p_sync, t.chave from pg_temp.tmp_selecao_lote t
  on conflict do nothing;

  select count(*) into v_qt from pg_temp.tmp_selecao_lote;
  update public."TL_SYNC_SELECAO" set "QT_LINHA" = "QT_LINHA" + v_qt where "CO_SYNC" = p_sync;
  return jsonb_build_object('recebidas', jsonb_array_length(p_linhas), 'gravadas', v_qt);
end;
$_$;

--
-- Name: FUNCTION sincronizar_selecao(p_sync text, p_linhas jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sincronizar_selecao(p_sync text, p_linhas jsonb) IS 'Recebe um lote (até 1000) de linhas da aba Resultado da planilha "Auditoria" e faz upsert em TB_SELECAO_VAGA, só da vaga que mudou; as chaves do lote vão para private."TL_CHAVE_DA_CARGA" (20261103150000). Só service_role (scripts/sincronizar-selecao.mjs). Fechar com finalizar_sync_selecao.';

--
-- Name: situacao_do_disparo_robo(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.situacao_do_disparo_robo(p_disparo bigint) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'Entre no MONITORA de novo.' using errcode = '28000';
  end if;
  if not exists (
    select 1 from public."TL_DISPARO_ROBO" d
     where d."CO_DISPARO" = p_disparo
       and (d."CO_USUARIO" = v_uid or private.is_master())) then
    raise exception 'Pedido não encontrado.' using errcode = 'P0002';
  end if;
  perform private."FC_CONFERIR_DISPAROS_ROBO"(p_disparo);
  return (
    select json_build_object(
      'disparo', d."CO_DISPARO",
      'workflow', d."NO_WORKFLOW",
      'inicio', d."DT_DISPARO",
      'fim', d."DT_RESPOSTA",
      'situacao', d."TP_SITUACAO",
      'http', d."NU_STATUS_HTTP",
      'mensagem', d."DS_MENSAGEM")
      from public."TL_DISPARO_ROBO" d
     where d."CO_DISPARO" = p_disparo);
end;
$$;

--
-- Name: FUNCTION situacao_do_disparo_robo(p_disparo bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.situacao_do_disparo_robo(p_disparo bigint) IS 'Situação de um pedido de disparar_robo (20261008140000), para a tela acompanhar: fecha o pedido pela resposta do GitHub em net._http_response, se já chegou, e devolve {disparo, workflow, inicio, fim, situacao (PEDIDO, ACEITO, FALHOU, SEM_TOKEN), http, mensagem}. Só quem pediu ou o administrador global (P0002 para os demais).';

--
-- Name: transicionar_recurso_candidato(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transicionar_recurso_candidato(p_id uuid, p_acao text, p_revisao integer, p_texto text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_atual public."TB_RECURSO_CANDIDATO";
  v_texto text := nullif(btrim(coalesce(p_texto, '')), '');
  v_decisao boolean := p_acao in ('deferir', 'deferir_parcialmente', 'indeferir');
  v_novo text;
  v_revisao integer;
begin
  if p_acao is null or p_acao not in ('enviar_parecer', 'devolver', 'deferir', 'deferir_parcialmente', 'indeferir', 'reabrir') then
    raise exception 'Ação inválida' using errcode = '22023';
  end if;
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  -- Enviar para parecer: quem edita. Devolver, decidir e reabrir: o parecer jurídico.
  perform private."FC_EXIGIR_RECURSO_ACESSIVEL"(p_id, case when p_acao = 'enviar_parecer' then 2 else 1 end);
  if p_acao <> 'enviar_parecer' then
    perform private."FC_EXIGIR_PARECER_RECURSO"();
  end if;

  select r.* into v_atual from public."TB_RECURSO_CANDIDATO" r
  where r."CO_RECURSO_CANDIDATO" = p_id and r."ST_ATIVO" = 'S'
  for update;
  if not found then
    raise exception 'Recurso não encontrado' using errcode = 'P0002';
  end if;
  if p_revisao is null or p_revisao <> v_atual."NU_REVISAO" then
    raise exception 'O recurso foi alterado por outra pessoa. Recarregue e tente de novo.' using errcode = 'PT409';
  end if;

  if v_decisao then
    if length(coalesce(v_texto, '')) not between 10 and 20000 then
      raise exception 'Escreva o parecer jurídico (10 a 20.000 caracteres)' using errcode = '22023';
    end if;
  elsif p_acao in ('devolver', 'reabrir') then
    if length(coalesce(v_texto, '')) not between 3 and 2000 then
      raise exception 'Informe o motivo (3 a 2.000 caracteres)' using errcode = '22023';
    end if;
  elsif length(coalesce(v_texto, '')) > 2000 then
    raise exception 'A observação passa de 2.000 caracteres' using errcode = '22023';
  end if;

  if p_acao = 'enviar_parecer' then
    if v_atual."TP_SITUACAO" <> 'REGISTRADO' then
      raise exception 'Só recurso registrado vai para parecer jurídico' using errcode = '22023';
    end if;
    v_novo := 'EM_ANALISE_JURIDICA';
  elsif p_acao = 'reabrir' then
    if v_atual."TP_SITUACAO" not in ('DEFERIDO', 'INDEFERIDO', 'PARCIALMENTE_INDEFERIDO') then
      raise exception 'Só recurso decidido pode ser reaberto' using errcode = '22023';
    end if;
    if v_atual."DT_RESPOSTA_CANDIDATO" is not null or exists (
      select 1 from public."TB_RESPOSTA_RECURSO" s
      where s."CO_RECURSO_CANDIDATO" = p_id and s."TP_ESTADO" = 'enviada') then
      raise exception 'A resposta já foi enviada ao candidato: a decisão não reabre' using errcode = '22023';
    end if;
    v_novo := 'EM_ANALISE_JURIDICA';
  else
    if v_atual."TP_SITUACAO" <> 'EM_ANALISE_JURIDICA' then
      raise exception 'O recurso não está em análise jurídica' using errcode = '22023';
    end if;
    v_novo := case p_acao
      when 'devolver' then 'REGISTRADO'
      when 'deferir' then 'DEFERIDO'
      when 'deferir_parcialmente' then 'PARCIALMENTE_INDEFERIDO'
      else 'INDEFERIDO' end;
  end if;

  update public."TB_RECURSO_CANDIDATO" set
    "TP_SITUACAO" = v_novo,
    "DT_DECISAO" = case when v_decisao then now() when p_acao = 'reabrir' then null else "DT_DECISAO" end,
    "CO_USUARIO_DECISAO" = case when v_decisao then v_uid when p_acao = 'reabrir' then null else "CO_USUARIO_DECISAO" end,
    "DS_PARECER_JURIDICO" = case when v_decisao then v_texto when p_acao = 'reabrir' then null else "DS_PARECER_JURIDICO" end,
    "DT_ENVIO_PARECER" = case when p_acao in ('enviar_parecer', 'reabrir') then now() when p_acao = 'devolver' then null else "DT_ENVIO_PARECER" end,
    "CO_USUARIO_ENVIO_PARECER" = case when p_acao in ('enviar_parecer', 'reabrir') then v_uid when p_acao = 'devolver' then null else "CO_USUARIO_ENVIO_PARECER" end,
    "DT_DEVOLUCAO" = case when p_acao = 'devolver' then now() when p_acao = 'enviar_parecer' then null else "DT_DEVOLUCAO" end,
    "CO_USUARIO_DEVOLUCAO" = case when p_acao = 'devolver' then v_uid when p_acao = 'enviar_parecer' then null else "CO_USUARIO_DEVOLUCAO" end,
    "DS_COMENTARIO_DEVOLUCAO" = case when p_acao = 'devolver' then v_texto when p_acao = 'enviar_parecer' then null else "DS_COMENTARIO_DEVOLUCAO" end,
    "NU_REVISAO" = "NU_REVISAO" + 1,
    "DT_ATUALIZACAO" = now(),
    "CO_USUARIO_ATUALIZACAO" = v_uid
  where "CO_RECURSO_CANDIDATO" = p_id
  returning "NU_REVISAO" into v_revisao;

  insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "DS_MOTIVO", "CO_USUARIO")
  values (p_id, 'parecer', p_acao, v_atual."TP_SITUACAO", v_novo, v_texto, v_uid);

  return json_build_object('id', p_id, 'situacao', v_novo, 'revisao', v_revisao);
end;
$$;

--
-- Name: FUNCTION transicionar_recurso_candidato(p_id uuid, p_acao text, p_revisao integer, p_texto text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transicionar_recurso_candidato(p_id uuid, p_acao text, p_revisao integer, p_texto text) IS 'Fluxo do parecer jurídico: enviar_parecer (REGISTRADO → EM_ANALISE_JURIDICA; recursos >= editor), devolver (comentário; volta a REGISTRADO), deferir / deferir_parcialmente / indeferir (parecer de 10 a 20.000 caracteres; grava quem e quando) e reabrir (motivo; só sem resposta enviada) — estas exigem recursos_parecer. Revisão desatualizada → 40001. Tudo vai para TH_RECURSO_CANDIDATO (parecer). Área e coordenação do edital conferidas.';

--
-- Name: transicionar_resposta_recurso(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transicionar_resposta_recurso(p_resposta_id uuid, p_acao text, p_revisao integer, p_comentario text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_atual public."TB_RESPOSTA_RECURSO";
  v_rec public."TB_RECURSO_CANDIDATO";
  v_situacao_modelo text;
  v_comentario text := nullif(btrim(coalesce(p_comentario, '')), '');
  v_novo text;
  v_revisao integer;
  v_etapa_em timestamptz;
begin
  if p_acao is null or p_acao not in ('enviar_revisao', 'aprovar', 'devolver', 'reabrir', 'marcar_enviada') then
    raise exception 'Ação inválida' using errcode = '22023';
  end if;
  if v_uid is null then
    raise exception 'Sessão inválida' using errcode = '42501';
  end if;
  if length(coalesce(v_comentario, '')) > 2000 then
    raise exception 'O comentário passa de 2.000 caracteres' using errcode = '22023';
  end if;
  select s.* into v_atual from public."TB_RESPOSTA_RECURSO" s where s."CO_RESPOSTA_RECURSO" = p_resposta_id;
  if not found then
    raise exception 'Resposta não encontrada' using errcode = 'P0002';
  end if;
  perform private."FC_EXIGIR_RECURSO_ACESSIVEL"(v_atual."CO_RECURSO_CANDIDATO", 2);
  -- Aprovar ou devolver o texto da resposta (a revisão final): o parecer jurídico.
  if p_acao in ('aprovar', 'devolver') then
    perform private."FC_EXIGIR_PARECER_RECURSO"();
  end if;
  -- Mesma ordem de trava de salvar_resposta_recurso: o recurso, depois a resposta.
  select r.* into v_rec from public."TB_RECURSO_CANDIDATO" r
  where r."CO_RECURSO_CANDIDATO" = v_atual."CO_RECURSO_CANDIDATO" for update;
  select s.* into v_atual from public."TB_RESPOSTA_RECURSO" s
  where s."CO_RESPOSTA_RECURSO" = p_resposta_id for update;
  if p_revisao is null or p_revisao <> v_atual."NU_REVISAO" then
    raise exception 'Outra pessoa alterou esta resposta. Recarregue e tente de novo.' using errcode = 'PT409';
  end if;

  if p_acao = 'enviar_revisao' then
    if v_atual."TP_ESTADO" not in ('rascunho', 'devolvida') then
      raise exception 'Só rascunho ou devolvida vai para revisão' using errcode = '22023';
    end if;
    v_novo := 'em_revisao';
  elsif p_acao = 'aprovar' then
    if v_atual."TP_ESTADO" not in ('rascunho', 'em_revisao') then
      raise exception 'Só rascunho ou resposta em revisão pode ser aprovada' using errcode = '22023';
    end if;
    if (v_atual."TP_ESTADO" = 'em_revisao' or v_atual."ST_PASSOU_REVISAO" = 'S')
       and (v_uid = v_atual."CO_USUARIO_AUTOR" or v_uid is not distinct from v_atual."CO_USUARIO_ENVIO_REVISAO") then
      raise exception 'Quem escreveu ou enviou a resposta para revisão não pode aprová-la' using errcode = '42501';
    end if;
    select t."TP_SITUACAO" into v_situacao_modelo from public."TB_MODELO_RESPOSTA_RECURSO" t
    where t."CO_MODELO_RESPOSTA" = v_atual."CO_MODELO_RESPOSTA" and t."NU_VERSAO" = v_atual."NU_VERSAO_MODELO";
    if v_rec."TP_SITUACAO" not in ('DEFERIDO', 'INDEFERIDO', 'PARCIALMENTE_INDEFERIDO') then
      raise exception 'Registre a decisão do recurso antes de aprovar a resposta' using errcode = '22023';
    end if;
    if v_rec."TP_SITUACAO" <> v_situacao_modelo then
      raise exception 'A situação do recurso não é a do modelo usado na resposta' using errcode = '22023';
    end if;
    v_novo := 'aprovada';
  elsif p_acao = 'devolver' then
    if v_atual."TP_ESTADO" <> 'em_revisao' then
      raise exception 'Só resposta em revisão pode ser devolvida' using errcode = '22023';
    end if;
    if v_uid = v_atual."CO_USUARIO_AUTOR" then
      raise exception 'Quem escreveu a resposta não pode devolvê-la' using errcode = '42501';
    end if;
    if length(coalesce(v_comentario, '')) < 3 then
      raise exception 'Informe o que precisa ser ajustado (3 caracteres ou mais)' using errcode = '22023';
    end if;
    v_novo := 'devolvida';
  elsif p_acao = 'reabrir' then
    if v_atual."TP_ESTADO" <> 'aprovada' then
      raise exception 'Só resposta aprovada pode ser reaberta' using errcode = '22023';
    end if;
    if length(coalesce(v_comentario, '')) < 3 then
      raise exception 'Informe o motivo da reabertura (3 caracteres ou mais)' using errcode = '22023';
    end if;
    v_novo := 'rascunho';
  else
    if v_atual."TP_ESTADO" <> 'aprovada' then
      raise exception 'Só resposta aprovada pode ser marcada como enviada' using errcode = '22023';
    end if;
    -- Quem edita marca enviada, mas só com o recurso decidido (a decisão pode ter sido reaberta depois da aprovação).
    if v_rec."TP_SITUACAO" not in ('DEFERIDO', 'INDEFERIDO', 'PARCIALMENTE_INDEFERIDO') then
      raise exception 'O recurso não está decidido: a resposta não pode ser enviada' using errcode = '22023';
    end if;
    v_novo := 'enviada';
  end if;

  update public."TB_RESPOSTA_RECURSO" set
    "TP_ESTADO" = v_novo,
    "ST_PASSOU_REVISAO" = case when p_acao = 'enviar_revisao' then 'S' else "ST_PASSOU_REVISAO" end,
    "DT_ENVIO_REVISAO" = case when p_acao = 'enviar_revisao' then now() else "DT_ENVIO_REVISAO" end,
    "CO_USUARIO_ENVIO_REVISAO" = case when p_acao = 'enviar_revisao' then v_uid else "CO_USUARIO_ENVIO_REVISAO" end,
    "DT_REVISAO" = case when p_acao in ('aprovar', 'devolver') then now() else "DT_REVISAO" end,
    "CO_USUARIO_REVISOR" = case when p_acao in ('aprovar', 'devolver') then v_uid else "CO_USUARIO_REVISOR" end,
    "DS_COMENTARIO_REVISAO" = case when p_acao in ('aprovar', 'devolver', 'reabrir') then v_comentario else "DS_COMENTARIO_REVISAO" end,
    "DT_ENVIO" = case when p_acao = 'marcar_enviada' then now() else "DT_ENVIO" end,
    "CO_USUARIO_ENVIO" = case when p_acao = 'marcar_enviada' then v_uid else "CO_USUARIO_ENVIO" end,
    "NU_REVISAO" = "NU_REVISAO" + 1,
    "DT_ATUALIZACAO" = now(),
    "CO_USUARIO_ATUALIZACAO" = v_uid
  where "CO_RESPOSTA_RECURSO" = p_resposta_id
  returning "NU_REVISAO" into v_revisao;

  insert into public."TH_RESPOSTA_RECURSO" (
    "CO_RESPOSTA_RECURSO", "TP_ACAO", "TP_ESTADO_ANTERIOR", "TP_ESTADO_NOVO", "DS_COMENTARIO",
    "CO_MODELO_RESPOSTA", "NU_VERSAO_MODELO", "DS_TEXTO_FINAL", "NU_REVISAO", "CO_USUARIO"
  ) values (
    p_resposta_id, p_acao, v_atual."TP_ESTADO", v_novo, v_comentario,
    v_atual."CO_MODELO_RESPOSTA", v_atual."NU_VERSAO_MODELO", v_atual."DS_TEXTO_FINAL", v_revisao, v_uid
  );
  insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "DS_MOTIVO", "CO_USUARIO")
  values (v_rec."CO_RECURSO_CANDIDATO", 'resposta', p_acao, v_atual."TP_ESTADO", v_novo, v_comentario, v_uid);

  -- Resposta enviada: a etapa do recurso acompanha (se ainda não estava marcada).
  v_etapa_em := v_rec."DT_RESPOSTA_CANDIDATO";
  if p_acao = 'marcar_enviada' and v_rec."DT_RESPOSTA_CANDIDATO" is null then
    v_etapa_em := now();
    update public."TB_RECURSO_CANDIDATO" set
      "DT_RESPOSTA_CANDIDATO" = v_etapa_em,
      "CO_USUARIO_RESPOSTA_CANDIDATO" = v_uid,
      "NU_REVISAO" = "NU_REVISAO" + 1,
      "DT_ATUALIZACAO" = now(),
      "CO_USUARIO_ATUALIZACAO" = v_uid
    where "CO_RECURSO_CANDIDATO" = v_rec."CO_RECURSO_CANDIDATO";
    insert into public."TH_RECURSO_CANDIDATO" ("CO_RECURSO_CANDIDATO", "TP_ACAO", "DS_CAMPO", "DS_VALOR_ANTERIOR", "DS_VALOR_NOVO", "CO_USUARIO")
    values (v_rec."CO_RECURSO_CANDIDATO", 'etapa', 'resposta_candidato', 'N', 'S', v_uid);
  end if;

  return json_build_object('id', p_resposta_id, 'estado', v_novo, 'revisao', v_revisao, 'resposta_candidato_em', v_etapa_em);
end;
$$;

--
-- Name: FUNCTION transicionar_resposta_recurso(p_resposta_id uuid, p_acao text, p_revisao integer, p_comentario text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transicionar_resposta_recurso(p_resposta_id uuid, p_acao text, p_revisao integer, p_comentario text) IS 'Transição da resposta: enviar_revisao, reabrir (com comentário) e marcar_enviada (só com o recurso decidido; marca também a etapa resposta_candidato) por quem edita; aprovar e devolver (com comentário) só com o parecer jurídico (recursos_parecer). Em revisão (ou depois de passar por ela), quem escreveu ou enviou não aprova; aprovar exige o recurso decidido com a situação do modelo. Revisão → 40001. Exige recursos >= editor, a área e a coordenação do edital.';

--
-- Name: usuario_pode_ler_analises(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usuario_pode_ler_analises() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ select private.pode_recurso('analises'); $$;

--
-- Name: verificar_sync_analises_incremental(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verificar_sync_analises_incremental(p_total_ativos_local integer, p_origem text DEFAULT 'apps_script_analises_incremental_v1'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    SET statement_timeout TO '10s'
    AS $$
declare
  v_planilha text;
  v_qtd integer;
begin
  -- [por-planilha]
  v_planilha := public."FC_PLANILHA_DA_ORIGEM_ANALISE"(p_origem, null);

  select count(*)::integer into v_qtd
  from public."TB_ANALISE_CURRICULAR" a
  join public."TB_EDITAL_ANALISE" e
    on a.grupo_norm=e.grupo_norm
   and a.unidade_norm=e.unidade_norm
   and a.edital_norm=e.edital_norm
  where a.ativo is true and e.ativo is true
    and a."CO_PLANILHA"=v_planilha
    and e."CO_PLANILHA"=v_planilha;

  return jsonb_build_object(
    'ok',true,
    'planilha',v_planilha,
    'total_ativos_local',greatest(coalesce(p_total_ativos_local,0),0),
    'total_ativos_remoto',v_qtd,
    'reconciliacao_full_recomendada',v_qtd <> greatest(coalesce(p_total_ativos_local,0),0)
  );
end;
$$;

