    "DS_MIME" character varying(100) NOT NULL,
    "QT_BYTES" integer NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "ST_REGISTRO_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    CONSTRAINT "CK_ANEXOMENSAGEM_DSCAMINHO" CHECK ((("DS_CAMINHO")::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[a-z0-9]{2,5}$'::text)),
    CONSTRAINT "CK_ANEXOMENSAGEM_DSMIME" CHECK ((("DS_MIME")::text = ANY (ARRAY[('application/pdf'::character varying)::text, ('image/png'::character varying)::text, ('image/jpeg'::character varying)::text, ('image/webp'::character varying)::text, ('image/gif'::character varying)::text, ('text/csv'::character varying)::text, ('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'::character varying)::text, ('application/vnd.ms-excel'::character varying)::text, ('application/vnd.oasis.opendocument.spreadsheet'::character varying)::text]))),
    CONSTRAINT "CK_ANEXOMENSAGEM_NOARQUIVO" CHECK (((length(btrim(("NO_ARQUIVO")::text)) >= 1) AND (length(btrim(("NO_ARQUIVO")::text)) <= 200))),
    CONSTRAINT "CK_ANEXOMENSAGEM_QTBYTES" CHECK ((("QT_BYTES" >= 1) AND ("QT_BYTES" <= 10485760))),
    CONSTRAINT "CK_ANEXOMENSAGEM_STREGATIVO" CHECK ((("ST_REGISTRO_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text])))
);

