--
-- Name: TB_CONVERSA; Type: TABLE; Schema: arquivo; Owner: -
--

CREATE TABLE arquivo."TB_CONVERSA" (
    "CO_CONVERSA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "TP_CONVERSA" character varying(10) NOT NULL,
    "NO_CONVERSA" character varying(120),
    "CO_MONITORAMENTO" uuid,
    "DS_CHAVE_DIRETA" character varying(73),
    "CO_USUARIO_CRIADOR" uuid NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ULTIMA_MENSAGEM" timestamp with time zone,
    "ST_REGISTRO_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    CONSTRAINT "CK_CONVERSA_CHAVEDIRETA" CHECK ((("DS_CHAVE_DIRETA" IS NULL) OR (("DS_CHAVE_DIRETA")::text ~ '^[0-9a-f-]{36}:[0-9a-f-]{36}$'::text))),
    CONSTRAINT "CK_CONVERSA_FORMATO" CHECK ((((("TP_CONVERSA")::text = 'GRUPO'::text) = ("NO_CONVERSA" IS NOT NULL)) AND ((("TP_CONVERSA")::text = 'EDITAL'::text) = ("CO_MONITORAMENTO" IS NOT NULL)) AND ((("TP_CONVERSA")::text = 'DIRETA'::text) = ("DS_CHAVE_DIRETA" IS NOT NULL)))),
    CONSTRAINT "CK_CONVERSA_NOCONVERSA" CHECK ((("NO_CONVERSA" IS NULL) OR ((length(btrim(("NO_CONVERSA")::text)) >= 1) AND (length(btrim(("NO_CONVERSA")::text)) <= 120)))),
    CONSTRAINT "CK_CONVERSA_STREGISTROATIVO" CHECK ((("ST_REGISTRO_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_CONVERSA_TPCONVERSA" CHECK ((("TP_CONVERSA")::text = ANY (ARRAY[('DIRETA'::character varying)::text, ('GRUPO'::character varying)::text, ('EDITAL'::character varying)::text])))
);

--
-- Name: TABLE "TB_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON TABLE arquivo."TB_CONVERSA" IS 'Conversas do chat do MONITORA: DIRETA (uma por par), GRUPO (nome e participantes de quem cria) ou EDITAL (uma por edital, aberta a quem vê o edital). Escrita só pelas RPCs *_chat.';

--
-- Name: COLUMN "TB_CONVERSA"."CO_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."CO_CONVERSA" IS 'Identificador da conversa.';

--
-- Name: COLUMN "TB_CONVERSA"."TP_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."TP_CONVERSA" IS 'DIRETA, GRUPO ou EDITAL.';

--
-- Name: COLUMN "TB_CONVERSA"."NO_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."NO_CONVERSA" IS 'Nome do grupo (só GRUPO; 1 a 120 caracteres). DIRETA e EDITAL tiram o nome da pessoa e do edital.';

--
-- Name: COLUMN "TB_CONVERSA"."CO_MONITORAMENTO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."CO_MONITORAMENTO" IS 'Edital da conversa (TB_MONITORAMENTO_INDIGENA.id; só EDITAL).';

--
-- Name: COLUMN "TB_CONVERSA"."DS_CHAVE_DIRETA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."DS_CHAVE_DIRETA" IS 'Par da conversa direta: menor uuid, dois-pontos, maior uuid (auth.users.id). Garante uma conversa por par.';

--
-- Name: COLUMN "TB_CONVERSA"."CO_USUARIO_CRIADOR"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."CO_USUARIO_CRIADOR" IS 'Quem criou (auth.users.id).';

--
-- Name: COLUMN "TB_CONVERSA"."DT_CRIACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."DT_CRIACAO" IS 'Quando foi criada.';

--
-- Name: COLUMN "TB_CONVERSA"."DT_ATUALIZACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."DT_ATUALIZACAO" IS 'Última alteração (mensagem nova, participante).';

--
-- Name: COLUMN "TB_CONVERSA"."DT_ULTIMA_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."DT_ULTIMA_MENSAGEM" IS 'Quando chegou a última mensagem (ordem da lista de conversas).';

--
-- Name: COLUMN "TB_CONVERSA"."ST_REGISTRO_ATIVO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_CONVERSA"."ST_REGISTRO_ATIVO" IS 'S: ativa. N: desativada (some da lista e não aceita mensagem).';

--
-- Name: CONSTRAINT "CK_CONVERSA_CHAVEDIRETA" ON "TB_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_CONVERSA_CHAVEDIRETA" ON arquivo."TB_CONVERSA" IS 'Chave do par no formato uuid:uuid.';

--
-- Name: CONSTRAINT "CK_CONVERSA_FORMATO" ON "TB_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_CONVERSA_FORMATO" ON arquivo."TB_CONVERSA" IS 'GRUPO tem nome; EDITAL tem edital; DIRETA tem a chave do par — e só eles.';

--
-- Name: CONSTRAINT "CK_CONVERSA_NOCONVERSA" ON "TB_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_CONVERSA_NOCONVERSA" ON arquivo."TB_CONVERSA" IS 'Nome do grupo com 1 a 120 caracteres.';

--
-- Name: CONSTRAINT "CK_CONVERSA_STREGISTROATIVO" ON "TB_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_CONVERSA_STREGISTROATIVO" ON arquivo."TB_CONVERSA" IS 'Flag S/N.';

--
-- Name: CONSTRAINT "CK_CONVERSA_TPCONVERSA" ON "TB_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_CONVERSA_TPCONVERSA" ON arquivo."TB_CONVERSA" IS 'Tipos de conversa válidos.';

--
-- Name: TB_EXPURGO_ANEXO_CHAT; Type: TABLE; Schema: arquivo; Owner: -
--

CREATE TABLE arquivo."TB_EXPURGO_ANEXO_CHAT" (
    "DS_CAMINHO" character varying(200) NOT NULL,
    "TP_ORIGEM" character varying(8) NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_EXPURGO" timestamp with time zone,
    CONSTRAINT "CK_EXPURGOANEXO_DSCAMINHO" CHECK ((("DS_CAMINHO")::text ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.[a-z0-9]{2,5}$'::text)),
    CONSTRAINT "CK_EXPURGOANEXO_TPORIGEM" CHECK ((("TP_ORIGEM")::text = ANY (ARRAY[('RETENCAO'::character varying)::text, ('ORFAO'::character varying)::text])))
);

--
-- Name: TABLE "TB_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON TABLE arquivo."TB_EXPURGO_ANEXO_CHAT" IS 'Fila de objetos do bucket chat-anexos a tirar do Storage: os da retenção e do "Zerar" (sem nenhuma linha em TB_ANEXO_MENSAGEM) e os enviados e nunca anexados. Só o caminho (uuid), nunca nome ou conteúdo. O Storage não aceita DELETE pelo SQL: a seção Configurações › Mensagens (chat) do administrador global remove pela API e confirma.';

--
-- Name: COLUMN "TB_EXPURGO_ANEXO_CHAT"."DS_CAMINHO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_EXPURGO_ANEXO_CHAT"."DS_CAMINHO" IS 'Objeto no bucket chat-anexos (<conversa>/<uuid>.<extensão>).';

--
-- Name: COLUMN "TB_EXPURGO_ANEXO_CHAT"."TP_ORIGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_EXPURGO_ANEXO_CHAT"."TP_ORIGEM" IS 'RETENCAO (a retenção ou o "Zerar" apagaram as mensagens) ou ORFAO (enviado e nunca anexado, mais de 1 dia).';

--
-- Name: COLUMN "TB_EXPURGO_ANEXO_CHAT"."DT_CRIACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_EXPURGO_ANEXO_CHAT"."DT_CRIACAO" IS 'Quando o objeto entrou na fila.';

--
-- Name: COLUMN "TB_EXPURGO_ANEXO_CHAT"."DT_EXPURGO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_EXPURGO_ANEXO_CHAT"."DT_EXPURGO" IS 'Quando o objeto saiu do Storage (confirmado). Nula: ainda na fila.';

--
-- Name: CONSTRAINT "CK_EXPURGOANEXO_DSCAMINHO" ON "TB_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXPURGOANEXO_DSCAMINHO" ON arquivo."TB_EXPURGO_ANEXO_CHAT" IS 'Caminho no formato do bucket (só uuids).';

--
-- Name: CONSTRAINT "CK_EXPURGOANEXO_TPORIGEM" ON "TB_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXPURGOANEXO_TPORIGEM" ON arquivo."TB_EXPURGO_ANEXO_CHAT" IS 'Origens válidas.';

--
-- Name: TB_MENSAGEM; Type: TABLE; Schema: arquivo; Owner: -
--

CREATE TABLE arquivo."TB_MENSAGEM" (
    "CO_MENSAGEM" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_CONVERSA" uuid NOT NULL,
    "CO_USUARIO_AUTOR" uuid NOT NULL,
    "DS_TEXTO" text NOT NULL,
    "DS_LINK_TELA" jsonb,
    "CO_USUARIOS_MENCIONADOS" uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_EDICAO" timestamp with time zone,
    "ST_APAGADA" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "DT_APAGADA" timestamp with time zone,
    "CO_MENSAGEM_RESPOSTA" uuid,
    "ST_ENCAMINHADA" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "QT_ANEXO" smallint DEFAULT 0 NOT NULL,
    CONSTRAINT "CK_MENSAGEM_APAGADA" CHECK ((((("ST_APAGADA")::text = 'S'::text) = ("DT_APAGADA" IS NOT NULL)) AND ((("ST_APAGADA")::text = 'N'::text) OR (("DS_TEXTO" = ''::text) AND ("DS_LINK_TELA" IS NULL) AND (cardinality("CO_USUARIOS_MENCIONADOS") = 0) AND ("QT_ANEXO" = 0))))),
    CONSTRAINT "CK_MENSAGEM_DSTEXTO" CHECK (((("ST_APAGADA")::text = 'S'::text) OR ((length("DS_TEXTO") <= 4000) AND ((length(btrim("DS_TEXTO")) >= 1) OR ("QT_ANEXO" > 0) OR ("DS_LINK_TELA" IS NOT NULL))))),
    CONSTRAINT "CK_MENSAGEM_LINKTELA" CHECK ((("DS_LINK_TELA" IS NULL) OR ((jsonb_typeof("DS_LINK_TELA") = 'object'::text) AND (length(("DS_LINK_TELA")::text) <= 1000)))),
    CONSTRAINT "CK_MENSAGEM_MENCIONADOS" CHECK ((cardinality("CO_USUARIOS_MENCIONADOS") <= 50)),
    CONSTRAINT "CK_MENSAGEM_QTANEXO" CHECK ((("QT_ANEXO" >= 0) AND ("QT_ANEXO" <= 5))),
    CONSTRAINT "CK_MENSAGEM_RESPOSTA" CHECK ((("CO_MENSAGEM_RESPOSTA" IS NULL) OR ("CO_MENSAGEM_RESPOSTA" <> "CO_MENSAGEM"))),
    CONSTRAINT "CK_MENSAGEM_STAPAGADA" CHECK ((("ST_APAGADA")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_MENSAGEM_STENCAMINHADA" CHECK ((("ST_ENCAMINHADA")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text])))
);

--
-- Name: TABLE "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON TABLE arquivo."TB_MENSAGEM" IS 'Mensagens do chat. Editar guarda DT_EDICAO; apagar pelo autor é lógico (ST_APAGADA = S: texto, link e menções saem, a linha fica como "mensagem apagada"). A retenção (TB_RETENCAO_CHAT) e o "Zerar mensagens" das Configurações apagam de fato, com auditoria em TH_LIMPEZA_CHAT.';

--
-- Name: COLUMN "TB_MENSAGEM"."CO_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."CO_MENSAGEM" IS 'Identificador da mensagem. Pode vir do navegador (uuid): reenviar o mesmo id não duplica.';

--
-- Name: COLUMN "TB_MENSAGEM"."CO_CONVERSA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."CO_CONVERSA" IS 'Conversa (TB_CONVERSA).';

--
-- Name: COLUMN "TB_MENSAGEM"."CO_USUARIO_AUTOR"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."CO_USUARIO_AUTOR" IS 'Autor (auth.users.id). Só ele edita e apaga.';

--
-- Name: COLUMN "TB_MENSAGEM"."DS_TEXTO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."DS_TEXTO" IS 'Texto (1 a 4.000 caracteres); vazio só na mensagem apagada.';

--
-- Name: COLUMN "TB_MENSAGEM"."DS_LINK_TELA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."DS_LINK_TELA" IS 'Link interno da tela compartilhada: {view, area?, secao?, edital?: {id, titulo}, rotulo?}. Nunca URL; a navegação é dentro do app.';

--
-- Name: COLUMN "TB_MENSAGEM"."CO_USUARIOS_MENCIONADOS"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."CO_USUARIOS_MENCIONADOS" IS 'Pessoas mencionadas com @ (auth.users.id; participantes da conversa; até 50).';

--
-- Name: COLUMN "TB_MENSAGEM"."DT_CRIACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."DT_CRIACAO" IS 'Quando foi enviada.';

--
-- Name: COLUMN "TB_MENSAGEM"."DT_EDICAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."DT_EDICAO" IS 'Última edição pelo autor; nula se nunca editada.';

--
-- Name: COLUMN "TB_MENSAGEM"."ST_APAGADA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."ST_APAGADA" IS 'S: apagada pelo autor (apagar lógico).';

--
-- Name: COLUMN "TB_MENSAGEM"."DT_APAGADA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."DT_APAGADA" IS 'Quando foi apagada.';

--
-- Name: COLUMN "TB_MENSAGEM"."CO_MENSAGEM_RESPOSTA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."CO_MENSAGEM_RESPOSTA" IS 'Mensagem citada (Responder), da mesma conversa. Fica nula se a retenção apagar a original.';

--
-- Name: COLUMN "TB_MENSAGEM"."ST_ENCAMINHADA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."ST_ENCAMINHADA" IS 'S: cópia encaminhada de outra conversa (texto, cartão e anexos; sem menções e sem a origem).';

--
-- Name: COLUMN "TB_MENSAGEM"."QT_ANEXO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_MENSAGEM"."QT_ANEXO" IS 'Quantos anexos a mensagem tem (0 a 5; TB_ANEXO_MENSAGEM). Com anexo ou cartão, o texto pode ficar vazio.';

--
-- Name: CONSTRAINT "CK_MENSAGEM_APAGADA" ON "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_MENSAGEM_APAGADA" ON arquivo."TB_MENSAGEM" IS 'Apagada tem data e fica sem texto, link, menções e anexos.';

--
-- Name: CONSTRAINT "CK_MENSAGEM_DSTEXTO" ON "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_MENSAGEM_DSTEXTO" ON arquivo."TB_MENSAGEM" IS 'Até 4.000 caracteres; vazio só com anexo ou cartão (fora a apagada).';

--
-- Name: CONSTRAINT "CK_MENSAGEM_LINKTELA" ON "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_MENSAGEM_LINKTELA" ON arquivo."TB_MENSAGEM" IS 'Link da tela é um objeto pequeno (até 1.000 caracteres).';

--
-- Name: CONSTRAINT "CK_MENSAGEM_MENCIONADOS" ON "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_MENSAGEM_MENCIONADOS" ON arquivo."TB_MENSAGEM" IS 'Até 50 menções.';

--
-- Name: CONSTRAINT "CK_MENSAGEM_QTANEXO" ON "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_MENSAGEM_QTANEXO" ON arquivo."TB_MENSAGEM" IS 'De 0 a 5 anexos por mensagem.';

--
-- Name: CONSTRAINT "CK_MENSAGEM_RESPOSTA" ON "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_MENSAGEM_RESPOSTA" ON arquivo."TB_MENSAGEM" IS 'A mensagem não cita a si mesma.';

--
-- Name: CONSTRAINT "CK_MENSAGEM_STAPAGADA" ON "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_MENSAGEM_STAPAGADA" ON arquivo."TB_MENSAGEM" IS 'Flag S/N.';

--
-- Name: CONSTRAINT "CK_MENSAGEM_STENCAMINHADA" ON "TB_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_MENSAGEM_STENCAMINHADA" ON arquivo."TB_MENSAGEM" IS 'Flag S/N.';

--
-- Name: TB_RETENCAO_CHAT; Type: TABLE; Schema: arquivo; Owner: -
--

CREATE TABLE arquivo."TB_RETENCAO_CHAT" (
    "CO_RETENCAO_CHAT" smallint DEFAULT 1 NOT NULL,
    "QT_DIAS_RETENCAO" integer,
    "CO_USUARIO_ATUALIZACAO" uuid,
    "DS_EMAIL_ATUALIZACAO" character varying(320),
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_RETENCAOCHAT_LINHAUNICA" CHECK (("CO_RETENCAO_CHAT" = 1)),
    CONSTRAINT "CK_RETENCAOCHAT_QTDIASRETENCAO" CHECK ((("QT_DIAS_RETENCAO" IS NULL) OR (("QT_DIAS_RETENCAO" >= 7) AND ("QT_DIAS_RETENCAO" <= 3650))))
);

--
-- Name: TABLE "TB_RETENCAO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON TABLE arquivo."TB_RETENCAO_CHAT" IS 'Prazo de retenção das mensagens do chat (linha única). Nulo: guardar para sempre. Escrita só por salvar_retencao_chat; lida por obter_retencao_chat e pela tarefa agsus_chat_retencao_diaria.';

--
-- Name: COLUMN "TB_RETENCAO_CHAT"."CO_RETENCAO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_RETENCAO_CHAT"."CO_RETENCAO_CHAT" IS 'Sempre 1: a tabela tem uma linha só.';

--
-- Name: COLUMN "TB_RETENCAO_CHAT"."QT_DIAS_RETENCAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_RETENCAO_CHAT"."QT_DIAS_RETENCAO" IS 'Prazo em dias (7 a 3.650): mensagens mais antigas que isso são apagadas de fato. Nulo: guardar para sempre.';

--
-- Name: COLUMN "TB_RETENCAO_CHAT"."CO_USUARIO_ATUALIZACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_RETENCAO_CHAT"."CO_USUARIO_ATUALIZACAO" IS 'Quem definiu o prazo (auth.users.id); nulo enquanto ninguém mudou.';

--
-- Name: COLUMN "TB_RETENCAO_CHAT"."DS_EMAIL_ATUALIZACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_RETENCAO_CHAT"."DS_EMAIL_ATUALIZACAO" IS 'E-mail de quem definiu o prazo, no momento da mudança.';

--
-- Name: COLUMN "TB_RETENCAO_CHAT"."DT_ATUALIZACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_RETENCAO_CHAT"."DT_ATUALIZACAO" IS 'Quando o prazo foi definido.';

--
-- Name: CONSTRAINT "CK_RETENCAOCHAT_LINHAUNICA" ON "TB_RETENCAO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_RETENCAOCHAT_LINHAUNICA" ON arquivo."TB_RETENCAO_CHAT" IS 'Só a linha 1.';

--
-- Name: CONSTRAINT "CK_RETENCAOCHAT_QTDIASRETENCAO" ON "TB_RETENCAO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_RETENCAOCHAT_QTDIASRETENCAO" ON arquivo."TB_RETENCAO_CHAT" IS 'Prazo nulo (para sempre) ou de 7 a 3.650 dias.';

--
-- Name: TB_STATUS_PRESENCA_CHAT; Type: TABLE; Schema: arquivo; Owner: -
--

CREATE TABLE arquivo."TB_STATUS_PRESENCA_CHAT" (
    "CO_USUARIO" uuid NOT NULL,
    "TP_STATUS" character varying(10) DEFAULT 'DISPONIVEL'::character varying NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_STATUSPRESENCA_TPSTATUS" CHECK ((("TP_STATUS")::text = ANY (ARRAY[('DISPONIVEL'::character varying)::text, ('OCUPADO'::character varying)::text, ('AUSENTE'::character varying)::text])))
);

--
-- Name: TABLE "TB_STATUS_PRESENCA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON TABLE arquivo."TB_STATUS_PRESENCA_CHAT" IS 'Status escolhido pela pessoa no chat (Disponível, Ocupado ou Ausente), além do online automático (TB_PRESENCA_ONLINE_MONITORA). Sem linha: Disponível. Escrita só por definir_status_chat.';

--
-- Name: COLUMN "TB_STATUS_PRESENCA_CHAT"."CO_USUARIO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_STATUS_PRESENCA_CHAT"."CO_USUARIO" IS 'A pessoa (auth.users.id).';

--
-- Name: COLUMN "TB_STATUS_PRESENCA_CHAT"."TP_STATUS"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_STATUS_PRESENCA_CHAT"."TP_STATUS" IS 'DISPONIVEL, OCUPADO ou AUSENTE.';

--
-- Name: COLUMN "TB_STATUS_PRESENCA_CHAT"."DT_ATUALIZACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TB_STATUS_PRESENCA_CHAT"."DT_ATUALIZACAO" IS 'Quando a pessoa mudou o status.';

--
-- Name: CONSTRAINT "CK_STATUSPRESENCA_TPSTATUS" ON "TB_STATUS_PRESENCA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_STATUSPRESENCA_TPSTATUS" ON arquivo."TB_STATUS_PRESENCA_CHAT" IS 'Status válidos.';

--
-- Name: TH_LIMPEZA_CHAT; Type: TABLE; Schema: arquivo; Owner: -
--

CREATE TABLE arquivo."TH_LIMPEZA_CHAT" (
    "CO_LIMPEZA_CHAT" uuid DEFAULT gen_random_uuid() NOT NULL,
    "TP_LIMPEZA" character varying(5) NOT NULL,
    "TP_ORIGEM" character varying(6) NOT NULL,
    "QT_DIAS_RETENCAO" integer,
    "DT_CORTE" timestamp with time zone,
    "QT_MENSAGEM_APAGADA" integer DEFAULT 0 NOT NULL,
    "QT_REACAO_APAGADA" integer DEFAULT 0 NOT NULL,
    "QT_CONVERSA_APAGADA" integer DEFAULT 0 NOT NULL,
    "DS_MOTIVO" character varying(500),
    "CO_USUARIO_RESPONSAVEL" uuid,
    "DS_EMAIL_RESPONSAVEL" character varying(320),
    "DT_CRIACAO" timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    "QT_ANEXO_APAGADO" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "CK_LIMPEZACHAT_CORTE" CHECK ((((("TP_LIMPEZA")::text = 'ZERAR'::text) AND ("DT_CORTE" IS NULL)) OR ((("TP_LIMPEZA")::text = 'PRAZO'::text) AND (("QT_DIAS_RETENCAO" IS NULL) = ("DT_CORTE" IS NULL))))),
    CONSTRAINT "CK_LIMPEZACHAT_DSMOTIVO" CHECK ((("DS_MOTIVO" IS NULL) OR ((length(btrim(("DS_MOTIVO")::text)) >= 3) AND (length(btrim(("DS_MOTIVO")::text)) <= 500)))),
    CONSTRAINT "CK_LIMPEZACHAT_ORIGEM" CHECK ((((("TP_ORIGEM")::text = 'ADMIN'::text) AND ("CO_USUARIO_RESPONSAVEL" IS NOT NULL) AND ("DS_MOTIVO" IS NOT NULL)) OR ((("TP_ORIGEM")::text = 'AGENDA'::text) AND (("TP_LIMPEZA")::text = 'PRAZO'::text) AND ("CO_USUARIO_RESPONSAVEL" IS NULL)))),
    CONSTRAINT "CK_LIMPEZACHAT_QTANEXOAPAGADO" CHECK (("QT_ANEXO_APAGADO" >= 0)),
    CONSTRAINT "CK_LIMPEZACHAT_QTDIASRETENCAO" CHECK ((("QT_DIAS_RETENCAO" IS NULL) OR (("QT_DIAS_RETENCAO" >= 7) AND ("QT_DIAS_RETENCAO" <= 3650)))),
    CONSTRAINT "CK_LIMPEZACHAT_QUANTIDADES" CHECK ((("QT_MENSAGEM_APAGADA" >= 0) AND ("QT_REACAO_APAGADA" >= 0) AND ("QT_CONVERSA_APAGADA" >= 0))),
    CONSTRAINT "CK_LIMPEZACHAT_TPLIMPEZA" CHECK ((("TP_LIMPEZA")::text = ANY (ARRAY[('PRAZO'::character varying)::text, ('ZERAR'::character varying)::text]))),
    CONSTRAINT "CK_LIMPEZACHAT_TPORIGEM" CHECK ((("TP_ORIGEM")::text = ANY (ARRAY[('ADMIN'::character varying)::text, ('AGENDA'::character varying)::text])))
);

--
-- Name: TABLE "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON TABLE arquivo."TH_LIMPEZA_CHAT" IS 'Histórico das limpezas das mensagens do chat: prazo de retenção (salvo pelo administrador ou aplicado pela tarefa diária) e "Zerar mensagens". Só contagens, corte, motivo e responsável — nunca o conteúdo das mensagens. Escrita só pelas RPCs e pela tarefa.';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."CO_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."CO_LIMPEZA_CHAT" IS 'Identificador da limpeza.';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."TP_LIMPEZA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."TP_LIMPEZA" IS 'PRAZO (retenção: salvar o prazo ou a tarefa diária) ou ZERAR (todas as mensagens).';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."TP_ORIGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."TP_ORIGEM" IS 'ADMIN (o administrador global, com motivo) ou AGENDA (tarefa agsus_chat_retencao_diaria).';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."QT_DIAS_RETENCAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."QT_DIAS_RETENCAO" IS 'Prazo em vigor depois desta ação (nulo: guardar para sempre).';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."DT_CORTE"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."DT_CORTE" IS 'Mensagens enviadas antes deste instante foram apagadas (PRAZO com dias). Nulo no ZERAR e no "guardar para sempre".';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."QT_MENSAGEM_APAGADA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."QT_MENSAGEM_APAGADA" IS 'Quantas mensagens foram apagadas.';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."QT_REACAO_APAGADA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."QT_REACAO_APAGADA" IS 'Quantas linhas de reação foram apagadas (as das mensagens apagadas).';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."QT_CONVERSA_APAGADA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."QT_CONVERSA_APAGADA" IS 'Quantas conversas sem mensagem e sem participante ativo foram apagadas (só no ZERAR com conversas).';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."DS_MOTIVO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."DS_MOTIVO" IS 'Motivo informado pelo administrador (3 a 500 caracteres); nulo na tarefa diária.';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."CO_USUARIO_RESPONSAVEL"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."CO_USUARIO_RESPONSAVEL" IS 'Quem pediu (auth.users.id); nulo na tarefa diária.';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."DS_EMAIL_RESPONSAVEL"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."DS_EMAIL_RESPONSAVEL" IS 'E-mail de quem pediu, no momento da ação.';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."DT_CRIACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."DT_CRIACAO" IS 'Quando a limpeza rodou (hora real, clock_timestamp: duas ações na mesma transação ficam em ordem).';

--
-- Name: COLUMN "TH_LIMPEZA_CHAT"."QT_ANEXO_APAGADO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TH_LIMPEZA_CHAT"."QT_ANEXO_APAGADO" IS 'Quantos anexos (linhas de TB_ANEXO_MENSAGEM) saíram com as mensagens. Só a contagem: nem nome nem caminho.';

--
-- Name: CONSTRAINT "CK_LIMPEZACHAT_CORTE" ON "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_LIMPEZACHAT_CORTE" ON arquivo."TH_LIMPEZA_CHAT" IS 'ZERAR não tem corte; PRAZO tem corte se e só se tem dias.';

--
-- Name: CONSTRAINT "CK_LIMPEZACHAT_DSMOTIVO" ON "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_LIMPEZACHAT_DSMOTIVO" ON arquivo."TH_LIMPEZA_CHAT" IS 'Motivo com 3 a 500 caracteres.';

--
-- Name: CONSTRAINT "CK_LIMPEZACHAT_ORIGEM" ON "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_LIMPEZACHAT_ORIGEM" ON arquivo."TH_LIMPEZA_CHAT" IS 'ADMIN tem responsável e motivo; AGENDA só aplica o prazo e não tem responsável.';

--
-- Name: CONSTRAINT "CK_LIMPEZACHAT_QTANEXOAPAGADO" ON "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_LIMPEZACHAT_QTANEXOAPAGADO" ON arquivo."TH_LIMPEZA_CHAT" IS 'Contagem não negativa.';

--
-- Name: CONSTRAINT "CK_LIMPEZACHAT_QTDIASRETENCAO" ON "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_LIMPEZACHAT_QTDIASRETENCAO" ON arquivo."TH_LIMPEZA_CHAT" IS 'Prazo nulo ou de 7 a 3.650 dias (o mesmo de TB_RETENCAO_CHAT).';

--
-- Name: CONSTRAINT "CK_LIMPEZACHAT_QUANTIDADES" ON "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_LIMPEZACHAT_QUANTIDADES" ON arquivo."TH_LIMPEZA_CHAT" IS 'Contagens não negativas.';

--
-- Name: CONSTRAINT "CK_LIMPEZACHAT_TPLIMPEZA" ON "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_LIMPEZACHAT_TPLIMPEZA" ON arquivo."TH_LIMPEZA_CHAT" IS 'Tipos de limpeza válidos.';

--
-- Name: CONSTRAINT "CK_LIMPEZACHAT_TPORIGEM" ON "TH_LIMPEZA_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_LIMPEZACHAT_TPORIGEM" ON arquivo."TH_LIMPEZA_CHAT" IS 'Origens válidas.';

--
-- Name: TL_EXPURGO_ANEXO_CHAT; Type: TABLE; Schema: arquivo; Owner: -
--

CREATE TABLE arquivo."TL_EXPURGO_ANEXO_CHAT" (
    "CO_EXECUCAO" text NOT NULL,
    "DT_INICIO" timestamp with time zone NOT NULL,
    "DT_FIM" timestamp with time zone DEFAULT now() NOT NULL,
    "TP_SITUACAO" text NOT NULL,
    "TP_DISPARO" text NOT NULL,
    "CO_USUARIO_DISPARO" uuid,
    "QT_LOTE" integer DEFAULT 0 NOT NULL,
    "QT_REMOVIDO" integer DEFAULT 0 NOT NULL,
    "QT_CONFIRMADO" integer DEFAULT 0 NOT NULL,
    "QT_FALHA" integer DEFAULT 0 NOT NULL,
    "QT_PENDENTE" integer,
    "DS_MENSAGEM" text,
    "DS_URL_EXECUCAO" text,
    CONSTRAINT "CK_EXECEXPURGO_COEXECUCAO" CHECK (("CO_EXECUCAO" ~ '^[A-Za-z0-9_-]{8,80}$'::text)),
    CONSTRAINT "CK_EXECEXPURGO_DATAS" CHECK (("DT_FIM" >= "DT_INICIO")),
    CONSTRAINT "CK_EXECEXPURGO_QT" CHECK ((("QT_LOTE" >= 0) AND ("QT_REMOVIDO" >= 0) AND ("QT_CONFIRMADO" >= 0) AND ("QT_FALHA" >= 0) AND (COALESCE("QT_PENDENTE", 0) >= 0))),
    CONSTRAINT "CK_EXECEXPURGO_TAMANHOS" CHECK (((COALESCE(length("DS_MENSAGEM"), 0) <= 500) AND (("DS_URL_EXECUCAO" IS NULL) OR (("DS_URL_EXECUCAO" ~ '^https://github\.com/'::text) AND (length("DS_URL_EXECUCAO") <= 300))))),
    CONSTRAINT "CK_EXECEXPURGO_TPDISPARO" CHECK (("TP_DISPARO" = ANY (ARRAY['AGENDA'::text, 'MONITORA'::text, 'GITHUB'::text]))),
    CONSTRAINT "CK_EXECEXPURGO_TPSITUACAO" CHECK (("TP_SITUACAO" = ANY (ARRAY['CONCLUIDA'::text, 'PARCIAL'::text, 'FALHOU'::text]))),
    CONSTRAINT "CK_EXECEXPURGO_USUARIO" CHECK ((("TP_DISPARO" = 'MONITORA'::text) = ("CO_USUARIO_DISPARO" IS NOT NULL)))
);

--
-- Name: TABLE "TL_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON TABLE arquivo."TL_EXPURGO_ANEXO_CHAT" IS 'Log das execuções do job diário que tira do Storage os arquivos da fila TB_EXPURGO_ANEXO_CHAT (scripts/expurgo_anexos_chat/): uma linha por execução, só contagens (nunca caminho, nome de arquivo ou conteúdo). Escrita só por registrar_expurgo_anexos_chat (service_role); leitura pelo Status das atualizações (get_saude_das_cargas).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."CO_EXECUCAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."CO_EXECUCAO" IS 'Identificador da execução (gerado pelo job: expurgo-<data>-<sufixo>).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."DT_INICIO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."DT_INICIO" IS 'Início da execução (informado pelo job).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."DT_FIM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."DT_FIM" IS 'Fim da execução (quando o job registrou).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."TP_SITUACAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."TP_SITUACAO" IS 'CONCLUIDA (tudo o que tentou saiu); PARCIAL (algum arquivo ficou na fila); FALHOU (erro geral).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."TP_DISPARO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."TP_DISPARO" IS 'Quem disparou: AGENDA (6h30 de Brasília), MONITORA (Rodar agora) ou GITHUB (Run workflow na aba Actions).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."CO_USUARIO_DISPARO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."CO_USUARIO_DISPARO" IS 'Usuário do MONITORA (auth.users.id) que clicou em Rodar agora; nulo nos outros disparos.';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."QT_LOTE"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."QT_LOTE" IS 'Lotes pedidos a preparar_expurgo_anexos_chat (até 100 caminhos cada).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."QT_REMOVIDO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."QT_REMOVIDO" IS 'Arquivos que a API do Storage disse ter removido.';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."QT_CONFIRMADO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."QT_CONFIRMADO" IS 'Caminhos que confirmar_expurgo_anexos_chat marcou como expurgados (já fora de storage.objects).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."QT_FALHA"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."QT_FALHA" IS 'Caminhos tentados que não saíram (continuam na fila para a próxima execução).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."QT_PENDENTE"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."QT_PENDENTE" IS 'Arquivos na fila ao fim da execução; nulo se o job não chegou a ler a fila.';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."DS_MENSAGEM"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."DS_MENSAGEM" IS 'Erro geral (sem caminho, nome de arquivo nem dado pessoal; o que parecer é omitido).';

--
-- Name: COLUMN "TL_EXPURGO_ANEXO_CHAT"."DS_URL_EXECUCAO"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON COLUMN arquivo."TL_EXPURGO_ANEXO_CHAT"."DS_URL_EXECUCAO" IS 'Endereço da execução no GitHub Actions.';

--
-- Name: CONSTRAINT "CK_EXECEXPURGO_COEXECUCAO" ON "TL_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXECEXPURGO_COEXECUCAO" ON arquivo."TL_EXPURGO_ANEXO_CHAT" IS 'Identificador de 8 a 80 caracteres seguros.';

--
-- Name: CONSTRAINT "CK_EXECEXPURGO_DATAS" ON "TL_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXECEXPURGO_DATAS" ON arquivo."TL_EXPURGO_ANEXO_CHAT" IS 'O fim não vem antes do início.';

--
-- Name: CONSTRAINT "CK_EXECEXPURGO_QT" ON "TL_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXECEXPURGO_QT" ON arquivo."TL_EXPURGO_ANEXO_CHAT" IS 'Contagens não negativas.';

--
-- Name: CONSTRAINT "CK_EXECEXPURGO_TAMANHOS" ON "TL_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXECEXPURGO_TAMANHOS" ON arquivo."TL_EXPURGO_ANEXO_CHAT" IS 'Mensagem até 500 caracteres; endereço só do GitHub, até 300.';

--
-- Name: CONSTRAINT "CK_EXECEXPURGO_TPDISPARO" ON "TL_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXECEXPURGO_TPDISPARO" ON arquivo."TL_EXPURGO_ANEXO_CHAT" IS 'Disparos válidos.';

--
-- Name: CONSTRAINT "CK_EXECEXPURGO_TPSITUACAO" ON "TL_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXECEXPURGO_TPSITUACAO" ON arquivo."TL_EXPURGO_ANEXO_CHAT" IS 'Situações válidas.';

--
-- Name: CONSTRAINT "CK_EXECEXPURGO_USUARIO" ON "TL_EXPURGO_ANEXO_CHAT"; Type: COMMENT; Schema: arquivo; Owner: -
--

COMMENT ON CONSTRAINT "CK_EXECEXPURGO_USUARIO" ON arquivo."TL_EXPURGO_ANEXO_CHAT" IS 'Usuário só (e sempre) no disparo pelo MONITORA.';

--
-- Name: TA_CANDIDATO_APROVADO_AREA; Type: TABLE; Schema: private; Owner: -
--

CREATE UNLOGGED TABLE private."TA_CANDIDATO_APROVADO_AREA" (
    "CO_AREA" text NOT NULL,
    "DS_LISTAS" json NOT NULL,
    "DS_DICIONARIOS" json NOT NULL,
    "DS_LINHAS" json NOT NULL,
    "QT_CANDIDATOS" integer NOT NULL,
    "DS_VERSAO_DADOS" text NOT NULL,
    "DT_GERACAO" timestamp with time zone NOT NULL,
    "NU_DURACAO_MS" integer NOT NULL
);

--
-- Name: TABLE "TA_CANDIDATO_APROVADO_AREA"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private."TA_CANDIDATO_APROVADO_AREA" IS 'Pacote pronto (formato 2) da lista de aprovados por área, para quem vê a área inteira. Só funções SECURITY DEFINER leem.';

--
-- Name: COLUMN "TA_CANDIDATO_APROVADO_AREA"."CO_AREA"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_CANDIDATO_APROVADO_AREA"."CO_AREA" IS 'Área do pacote (TB_AREA.CO_AREA).';

--
-- Name: COLUMN "TA_CANDIDATO_APROVADO_AREA"."DS_LISTAS"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_CANDIDATO_APROVADO_AREA"."DS_LISTAS" IS 'Listas vigentes da área (array de arrays, colunas_da_lista do formato 2).';

--
-- Name: COLUMN "TA_CANDIDATO_APROVADO_AREA"."DS_DICIONARIOS"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_CANDIDATO_APROVADO_AREA"."DS_DICIONARIOS" IS 'Valores distintos de cargo, modalidade, status e codigo_vaga; as linhas levam o índice.';

--
-- Name: COLUMN "TA_CANDIDATO_APROVADO_AREA"."DS_LINHAS"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_CANDIDATO_APROVADO_AREA"."DS_LINHAS" IS 'Candidatos em linhas posicionais (colunas do formato 2).';

--
-- Name: COLUMN "TA_CANDIDATO_APROVADO_AREA"."QT_CANDIDATOS"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_CANDIDATO_APROVADO_AREA"."QT_CANDIDATOS" IS 'Quantidade de linhas (campo total).';

--
-- Name: COLUMN "TA_CANDIDATO_APROVADO_AREA"."DS_VERSAO_DADOS"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_CANDIDATO_APROVADO_AREA"."DS_VERSAO_DADOS" IS 'Instante da montagem em microssegundos desde 1970 (20261007220000). Se o pacote está em dia diz a TL_ALTERACAO_CACHE.';

--
-- Name: COLUMN "TA_CANDIDATO_APROVADO_AREA"."DT_GERACAO"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_CANDIDATO_APROVADO_AREA"."DT_GERACAO" IS 'Início da montagem.';

--
-- Name: COLUMN "TA_CANDIDATO_APROVADO_AREA"."NU_DURACAO_MS"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_CANDIDATO_APROVADO_AREA"."NU_DURACAO_MS" IS 'Quanto a montagem levou, em milissegundos.';

--
-- Name: TA_PAINEL_ANALISE; Type: TABLE; Schema: private; Owner: -
--

CREATE UNLOGGED TABLE private."TA_PAINEL_ANALISE" (
    "CO_AREA" text NOT NULL,
    "TP_ESCOPO" text NOT NULL,
    "DS_LINHAS" json NOT NULL,
    "DS_EDITAIS" json NOT NULL,
    "QT_LINHAS" integer NOT NULL,
    "DS_VERSAO_DADOS" text NOT NULL,
    "DT_GERACAO" timestamp with time zone NOT NULL,
    "NU_DURACAO_MS" integer NOT NULL,
    "DT_ULTIMA_ATUALIZACAO" timestamp with time zone,
    "DS_CONCLUIDAS_POR_ANO" json,
    CONSTRAINT "CK_PAINEL_ANALISE_TPESCOPO" CHECK (("TP_ESCOPO" = ANY (ARRAY['ativo'::text, 'inativo'::text, 'desativadas'::text, 'todos'::text])))
);

--
-- Name: TABLE "TA_PAINEL_ANALISE"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private."TA_PAINEL_ANALISE" IS 'Cache do painel de análises: linhas (lista enxuta) e editais já montados por área e escopo (ativo, inativo, desativadas). Só funções SECURITY DEFINER leem.';

--
-- Name: COLUMN "TA_PAINEL_ANALISE"."CO_AREA"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_PAINEL_ANALISE"."CO_AREA" IS 'Área do pacote (TB_AREA.CO_AREA).';

--
-- Name: COLUMN "TA_PAINEL_ANALISE"."TP_ESCOPO"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_PAINEL_ANALISE"."TP_ESCOPO" IS 'Escopo do pacote: ativo, inativo ou desativadas.';

--
-- Name: COLUMN "TA_PAINEL_ANALISE"."DS_LINHAS"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_PAINEL_ANALISE"."DS_LINHAS" IS 'Linhas do payload (array de arrays, na ordem de "columns" de get_analises_dashboard_payload_v2).';

--
-- Name: COLUMN "TA_PAINEL_ANALISE"."DS_EDITAIS"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TA_PAINEL_ANALISE"."DS_EDITAIS" IS 'Editais do payload.';

--
-- Name: COLUMN "TA_PAINEL_ANALISE"."QT_LINHAS"; Type: COMMENT; Schema: private; Owner: -
--

