--
-- Name: TB_PENDENCIA_COORDENADA_LOCAL; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private."TB_PENDENCIA_COORDENADA_LOCAL" (
    "CO_SEQ_PENDENCIA" bigint NOT NULL,
    "DS_CHAVE_LUGAR" character varying(160) NOT NULL,
    "NO_LUGAR" character varying(160) NOT NULL,
    "CO_MUNICIPIO_IBGE" integer,
    "SG_UF" character varying(2) NOT NULL,
    "TP_MOTIVO" character varying(20) NOT NULL,
    "DS_MOTIVO" text NOT NULL,
    "DS_CANDIDATO" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "ST_CONFERIDO" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "DT_CONFERENCIA" timestamp with time zone,
    "CO_USUARIO_CONFERENCIA" uuid,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_PENDLOCAL_CANDIDATO" CHECK ((jsonb_typeof("DS_CANDIDATO") = 'array'::text)),
    CONSTRAINT "CK_PENDLOCAL_CONFERENCIA" CHECK ((((("ST_CONFERIDO")::text = 'S'::text) = ("DT_CONFERENCIA" IS NOT NULL)) AND ((("ST_CONFERIDO")::text = 'S'::text) = ("CO_USUARIO_CONFERENCIA" IS NOT NULL)))),
    CONSTRAINT "CK_PENDLOCAL_CONFERIDO" CHECK ((("ST_CONFERIDO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_PENDLOCAL_MOTIVO" CHECK ((("TP_MOTIVO")::text = ANY (ARRAY[('SEM_COORDENADA'::character varying)::text, ('MUNICIPIO_DIVERGE'::character varying)::text, ('LUGAR_DIVERGE'::character varying)::text, ('FORA_DO_BRASIL'::character varying)::text, ('ESCRITORIO_SO_UF'::character varying)::text, ('SO_UF'::character varying)::text, ('SEDE_MUNICIPAL'::character varying)::text, ('OUTRO'::character varying)::text])))
);

--
-- Name: TABLE "TB_PENDENCIA_COORDENADA_LOCAL"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private."TB_PENDENCIA_COORDENADA_LOCAL" IS 'Lugares do mapa de Projetos com coordenada duvidosa, com posições candidatas e a conferência do administrador global. Sem acesso direto: só as RPCs do editor.';

--
-- Name: COLUMN "TB_PENDENCIA_COORDENADA_LOCAL"."CO_SEQ_PENDENCIA"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TB_PENDENCIA_COORDENADA_LOCAL"."CO_SEQ_PENDENCIA" IS 'Identificador sequencial da pendência (identity).';

