-- Name: COLUMN "TB_PENDENCIA_COORDENADA_LOCAL"."DT_CRIACAO"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TB_PENDENCIA_COORDENADA_LOCAL"."DT_CRIACAO" IS 'Data e hora da carga da pendência.';

--
-- Name: TB_PENDENCIA_COORDENADA_LOCAL_CO_SEQ_PENDENCIA_seq; Type: SEQUENCE; Schema: private; Owner: -
--

ALTER TABLE private."TB_PENDENCIA_COORDENADA_LOCAL" ALTER COLUMN "CO_SEQ_PENDENCIA" ADD GENERATED ALWAYS AS IDENTITY (
