--
-- Name: TB_PENDENCIA_COORDENADA_MAPA; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private."TB_PENDENCIA_COORDENADA_MAPA" (
    "CO_SEQ_PENDENCIA" bigint NOT NULL,
    "TP_FONTE" character varying(9) NOT NULL,
    "TP_PONTO" character varying(4) NOT NULL,
    "NO_DSEI" text NOT NULL,
    "CO_PONTO" character varying(20) NOT NULL,
    "NO_PONTO" text NOT NULL,
    "NO_MUNICIPIO" text,
    "TP_MOTIVO" character varying(20) NOT NULL,
    "DS_MOTIVO" text NOT NULL,
    "DS_CANDIDATO" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "ST_CONFERIDO" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "DT_CONFERENCIA" timestamp with time zone,
    "CO_USUARIO_CONFERENCIA" uuid,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_PENDCOORD_CANDIDATO" CHECK ((jsonb_typeof("DS_CANDIDATO") = 'array'::text)),
    CONSTRAINT "CK_PENDCOORD_CONFERENCIA" CHECK ((((("ST_CONFERIDO")::text = 'S'::text) = ("DT_CONFERENCIA" IS NOT NULL)) AND ((("ST_CONFERIDO")::text = 'S'::text) = ("CO_USUARIO_CONFERENCIA" IS NOT NULL)))),
    CONSTRAINT "CK_PENDCOORD_CONFERIDO" CHECK ((("ST_CONFERIDO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_PENDCOORD_MOTIVO" CHECK ((("TP_MOTIVO")::text = ANY (ARRAY[('FONTES_DIVERGEM'::character varying)::text, ('HOMONIMO_FORA'::character varying)::text, ('NOME_MUNICIPIO'::character varying)::text, ('PONTO_COLETOR'::character varying)::text, ('SEDE_MUNICIPAL'::character varying)::text, ('SEM_CANDIDATO'::character varying)::text, ('UMA_FONTE'::character varying)::text, ('CNES'::character varying)::text, ('OUTRO'::character varying)::text]))),
    CONSTRAINT "CK_PENDCOORD_PONTO" CHECK ((((("TP_FONTE")::text = 'lmap'::text) AND (("TP_PONTO")::text = 'polo'::text)) OR ((("TP_FONTE")::text = 'rede_cnes'::text) AND (("TP_PONTO")::text = ANY (ARRAY[('u'::character varying)::text, ('c'::character varying)::text])))))
);

--
