-- Name: COLUMN "TL_CHAVE_DA_CARGA"."CO_SYNC"; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON COLUMN private."TL_CHAVE_DA_CARGA"."CO_SYNC" IS 'A carga (CO_SYNC de TL_SYNC_SELECAO ou TL_SYNC_ENTREVISTA).';

