--
-- Name: RL_ANALISTA_EDITAL; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."RL_ANALISTA_EDITAL" (
    "CO_ANALISTA_EDITAL" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_USUARIO" uuid NOT NULL,
    "TP_PAPEL" character varying(12) NOT NULL,
    "CO_VAGA" character varying(20),
    "QT_LIMITE_FICHA" integer,
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DS_MOTIVO_ATUALIZACAO" character varying(500),
    "CO_USUARIO_ATUALIZACAO" uuid NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_ANALISTAEDT_COORDVAGA" CHECK (((("TP_PAPEL")::text <> 'COORDENADOR'::text) OR ("CO_VAGA" IS NULL))),
    CONSTRAINT "CK_ANALISTAEDT_COVAGA" CHECK ((("CO_VAGA" IS NULL) OR (("CO_VAGA")::text ~ '^[0-9]{1,20}$'::text))),
    CONSTRAINT "CK_ANALISTAEDT_LIMITE" CHECK ((("QT_LIMITE_FICHA" IS NULL) OR (("QT_LIMITE_FICHA" >= 1) AND ("QT_LIMITE_FICHA" <= 5000)))),
    CONSTRAINT "CK_ANALISTAEDT_STATIVO" CHECK ((("ST_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_ANALISTAEDT_TPPAPEL" CHECK ((("TP_PAPEL")::text = ANY (ARRAY[('ANALISTA'::character varying)::text, ('REVISOR'::character varying)::text, ('COORDENADOR'::character varying)::text])))
);

--
-- Name: TABLE "RL_ANALISTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."RL_ANALISTA_EDITAL" IS 'Equipe da avaliação documental do edital (substitui a DIM_RESPONSAVEIS das planilhas): analista, revisor ou coordenador, no edital todo ou numa vaga. O gestor do edital já é coordenação, sem linha aqui. Sair da equipe desativa a linha; nada se apaga.';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."CO_ANALISTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."CO_ANALISTA_EDITAL" IS 'Identificador da linha.';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id).';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."CO_USUARIO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."CO_USUARIO" IS 'Pessoa (auth.users.id).';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."TP_PAPEL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."TP_PAPEL" IS 'ANALISTA (analisa as suas fichas), REVISOR (valida ou devolve as fichas de outras pessoas) ou COORDENADOR (regra, equipe, lote, distribuição e revisão).';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."CO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."CO_VAGA" IS 'Código da vaga (só dígitos); nulo = todas as vagas do edital.';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."QT_LIMITE_FICHA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."QT_LIMITE_FICHA" IS 'Limite de fichas na distribuição inicial (1 a 5.000); nulo = sem limite.';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."ST_ATIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."ST_ATIVO" IS 'S: está na equipe. N: saiu (a linha fica como histórico).';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."DS_MOTIVO_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."DS_MOTIVO_ATUALIZACAO" IS 'Motivo informado na última mudança da linha (obrigatório ao tirar alguém da equipe).';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."CO_USUARIO_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."CO_USUARIO_ATUALIZACAO" IS 'Quem incluiu ou mudou a linha por último (auth.users.id).';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."DT_CRIACAO" IS 'Quando a pessoa entrou com este papel.';

--
-- Name: COLUMN "RL_ANALISTA_EDITAL"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."RL_ANALISTA_EDITAL"."DT_ATUALIZACAO" IS 'Última mudança da linha.';

--
-- Name: CONSTRAINT "CK_ANALISTAEDT_COORDVAGA" ON "RL_ANALISTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ANALISTAEDT_COORDVAGA" ON public."RL_ANALISTA_EDITAL" IS 'A coordenação é do edital todo, sem vaga.';

--
-- Name: CONSTRAINT "CK_ANALISTAEDT_COVAGA" ON "RL_ANALISTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ANALISTAEDT_COVAGA" ON public."RL_ANALISTA_EDITAL" IS 'Código da vaga só com dígitos.';

--
-- Name: CONSTRAINT "CK_ANALISTAEDT_LIMITE" ON "RL_ANALISTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ANALISTAEDT_LIMITE" ON public."RL_ANALISTA_EDITAL" IS 'Limite de fichas entre 1 e 5.000.';

--
-- Name: CONSTRAINT "CK_ANALISTAEDT_STATIVO" ON "RL_ANALISTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ANALISTAEDT_STATIVO" ON public."RL_ANALISTA_EDITAL" IS 'Flag S/N.';

--
-- Name: CONSTRAINT "CK_ANALISTAEDT_TPPAPEL" ON "RL_ANALISTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ANALISTAEDT_TPPAPEL" ON public."RL_ANALISTA_EDITAL" IS 'Papéis válidos.';

