--
-- Name: TB_AJUSTE_PONTUACAO_RECURSO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_AJUSTE_PONTUACAO_RECURSO" (
    "CO_AJUSTE_PONTUACAO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_RECURSO_CANDIDATO" uuid NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_ANALISE_CURRICULAR" uuid NOT NULL,
    "NU_VERSAO" integer NOT NULL,
    "TP_SITUACAO" character varying(10) DEFAULT 'PROPOSTO'::character varying NOT NULL,
    "TP_LISTA" character varying(20) NOT NULL,
    "DS_JUSTIFICATIVA" text,
    "DS_PREVIA" jsonb,
    "DS_PREVIA_APROVACAO" jsonb,
    "ST_MUDOU_POSICAO" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "DT_PROPOSTA" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_PROPOSTA" uuid NOT NULL,
    "DT_APROVACAO" timestamp with time zone,
    "CO_USUARIO_APROVACAO" uuid,
    "DT_CANCELAMENTO" timestamp with time zone,
    "CO_USUARIO_CANCELAMENTO" uuid,
    "DS_MOTIVO_CANCELAMENTO" text,
    CONSTRAINT "CK_AJUSTEPONTREC_FLUXO" CHECK (((("DT_APROVACAO" IS NULL) = ("CO_USUARIO_APROVACAO" IS NULL)) AND (("DT_CANCELAMENTO" IS NULL) = ("CO_USUARIO_CANCELAMENTO" IS NULL)) AND (("DT_CANCELAMENTO" IS NULL) = ("DS_MOTIVO_CANCELAMENTO" IS NULL)) AND ((("TP_SITUACAO")::text <> 'PROPOSTO'::text) OR (("DT_APROVACAO" IS NULL) AND ("DT_CANCELAMENTO" IS NULL))) AND ((("TP_SITUACAO")::text <> 'APROVADO'::text) OR (("DT_APROVACAO" IS NOT NULL) AND ("DT_CANCELAMENTO" IS NULL))) AND ((("TP_SITUACAO")::text <> 'CANCELADO'::text) OR ("DT_CANCELAMENTO" IS NOT NULL)) AND ((("ST_MUDOU_POSICAO")::text = 'N'::text) OR ("DT_APROVACAO" IS NOT NULL)))),
    CONSTRAINT "CK_AJUSTEPONTREC_NUVERSAO" CHECK (("NU_VERSAO" >= 1)),
    CONSTRAINT "CK_AJUSTEPONTREC_PREVIA" CHECK (((("DS_PREVIA" IS NULL) OR (jsonb_typeof("DS_PREVIA") = 'object'::text)) AND (("DS_PREVIA_APROVACAO" IS NULL) OR (jsonb_typeof("DS_PREVIA_APROVACAO") = 'object'::text)))),
    CONSTRAINT "CK_AJUSTEPONTREC_STMUDOUPOSICAO" CHECK ((("ST_MUDOU_POSICAO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_AJUSTEPONTREC_TEXTOS" CHECK (((("DS_JUSTIFICATIVA" IS NULL) OR ((length("DS_JUSTIFICATIVA") >= 10) AND (length("DS_JUSTIFICATIVA") <= 4000))) AND (("DS_MOTIVO_CANCELAMENTO" IS NULL) OR ((length("DS_MOTIVO_CANCELAMENTO") >= 3) AND (length("DS_MOTIVO_CANCELAMENTO") <= 2000))))),
    CONSTRAINT "CK_AJUSTEPONTREC_TPLISTA" CHECK ((("TP_LISTA")::text = ANY (ARRAY[('PRELIMINAR'::character varying)::text, ('ENTREVISTA'::character varying)::text, ('FINAL'::character varying)::text]))),
    CONSTRAINT "CK_AJUSTEPONTREC_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY (ARRAY[('PROPOSTO'::character varying)::text, ('APROVADO'::character varying)::text, ('CANCELADO'::character varying)::text])))
);

--
-- Name: TABLE "TB_AJUSTE_PONTUACAO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_AJUSTE_PONTUACAO_RECURSO" IS 'Ajuste da pontuação de um candidato decidido em recurso (deferido total ou parcialmente): cada proposta é uma versão; os valores não mudam, só a situação (PROPOSTO, APROVADO, CANCELADO). A nota da análise e da entrevista nunca é sobrescrita; a Classificação aplica os aprovados por cima.';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."CO_AJUSTE_PONTUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."CO_AJUSTE_PONTUACAO" IS 'Identificador da versão do ajuste.';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."CO_RECURSO_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."CO_RECURSO_CANDIDATO" IS 'Recurso que originou o ajuste (TB_RECURSO_CANDIDATO).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."CO_MONITORAMENTO" IS 'Edital do recurso (TB_MONITORAMENTO_INDIGENA.id), para a Classificação ler os ajustes do edital.';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."CO_ANALISE_CURRICULAR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."CO_ANALISE_CURRICULAR" IS 'Candidato ajustado: a linha da análise curricular ligada ao recurso (TB_ANALISE_CURRICULAR.id).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."NU_VERSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."NU_VERSAO" IS 'Versão do ajuste no recurso (1, 2, …); cada proposta cria a seguinte.';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."TP_SITUACAO" IS 'PROPOSTO (não vale na classificação), APROVADO (vale) ou CANCELADO (substituído, cancelado ou desfeito pela reabertura do recurso).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."TP_LISTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."TP_LISTA" IS 'Lista da etapa em que a prévia foi calculada: PRELIMINAR (documental), ENTREVISTA ou FINAL.';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."DS_JUSTIFICATIVA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."DS_JUSTIFICATIVA" IS 'Justificativa geral (10 a 4.000 caracteres). Nula só quando cada item alterado tem a sua.';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."DS_PREVIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."DS_PREVIA" IS 'Prévia calculada pelo motor da Classificação ao propor: nota e posição antes e depois e quem muda de posição (resumo).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."DS_PREVIA_APROVACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."DS_PREVIA_APROVACAO" IS 'Prévia recalculada no momento da aprovação (base de ST_MUDOU_POSICAO).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."ST_MUDOU_POSICAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."ST_MUDOU_POSICAO" IS 'S: a prévia da aprovação mostrou mudança de posição ou de situação do candidato. Marca ST_MUDOU_CLASSIFICACAO do recurso.';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."DT_PROPOSTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."DT_PROPOSTA" IS 'Quando foi proposto.';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."CO_USUARIO_PROPOSTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."CO_USUARIO_PROPOSTA" IS 'Quem propôs (auth.users.id; parecer jurídico).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."DT_APROVACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."DT_APROVACAO" IS 'Quando foi aprovado (passa a valer na Classificação).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."CO_USUARIO_APROVACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."CO_USUARIO_APROVACAO" IS 'Quem aprovou (auth.users.id; parecer jurídico).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."DT_CANCELAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."DT_CANCELAMENTO" IS 'Quando foi cancelado (ou substituído, ou desfeito pela reabertura).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."CO_USUARIO_CANCELAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."CO_USUARIO_CANCELAMENTO" IS 'Quem cancelou (auth.users.id).';

--
-- Name: COLUMN "TB_AJUSTE_PONTUACAO_RECURSO"."DS_MOTIVO_CANCELAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AJUSTE_PONTUACAO_RECURSO"."DS_MOTIVO_CANCELAMENTO" IS 'Por que saiu (3 a 2.000 caracteres): motivo informado, "Substituído pela versão N" ou a mudança do recurso.';

--
-- Name: CONSTRAINT "CK_AJUSTEPONTREC_FLUXO" ON "TB_AJUSTE_PONTUACAO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_AJUSTEPONTREC_FLUXO" ON public."TB_AJUSTE_PONTUACAO_RECURSO" IS 'Aprovação e cancelamento guardam quando e quem juntos; cada situação tem os passos coerentes; mudança de posição só depois de aprovado.';

--
-- Name: CONSTRAINT "CK_AJUSTEPONTREC_NUVERSAO" ON "TB_AJUSTE_PONTUACAO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_AJUSTEPONTREC_NUVERSAO" ON public."TB_AJUSTE_PONTUACAO_RECURSO" IS 'Versão a partir de 1.';

--
-- Name: CONSTRAINT "CK_AJUSTEPONTREC_PREVIA" ON "TB_AJUSTE_PONTUACAO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_AJUSTEPONTREC_PREVIA" ON public."TB_AJUSTE_PONTUACAO_RECURSO" IS 'Prévias são objetos json.';

--
-- Name: CONSTRAINT "CK_AJUSTEPONTREC_STMUDOUPOSICAO" ON "TB_AJUSTE_PONTUACAO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_AJUSTEPONTREC_STMUDOUPOSICAO" ON public."TB_AJUSTE_PONTUACAO_RECURSO" IS 'Flag S/N.';

--
-- Name: CONSTRAINT "CK_AJUSTEPONTREC_TEXTOS" ON "TB_AJUSTE_PONTUACAO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_AJUSTEPONTREC_TEXTOS" ON public."TB_AJUSTE_PONTUACAO_RECURSO" IS 'Justificativa de 10 a 4.000 e motivo do cancelamento de 3 a 2.000 caracteres.';

--
-- Name: CONSTRAINT "CK_AJUSTEPONTREC_TPLISTA" ON "TB_AJUSTE_PONTUACAO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_AJUSTEPONTREC_TPLISTA" ON public."TB_AJUSTE_PONTUACAO_RECURSO" IS 'Listas em que a prévia é calculada.';

--
-- Name: CONSTRAINT "CK_AJUSTEPONTREC_TPSITUACAO" ON "TB_AJUSTE_PONTUACAO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_AJUSTEPONTREC_TPSITUACAO" ON public."TB_AJUSTE_PONTUACAO_RECURSO" IS 'Situações do ajuste.';

--
-- Name: TB_ANALISE_CURRICULAR; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ANALISE_CURRICULAR" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    grupo text,
    unidade text NOT NULL,
    edital text NOT NULL,
    codigo_vaga text,
    nome_vaga text,
    candidato text,
    cpf_hash text,
    categoria text,
    modalidade_concorrencia text,
    status_consolidado text DEFAULT 'Pendente'::text NOT NULL,
    etapa text,
    responsavel_analise text,
    data_analise date,
    nota_final_ajustada numeric,
    pontuacao_escolaridade numeric,
    pontuacao_cursos_aperfeicoamento numeric,
    pontuacao_experiencia_profissional numeric,
    pontuacao_criterio_etnico numeric,
    experiencia_saude_indigena_total numeric,
    experiencia_atencao_basica_total numeric,
    analise text,
    link_pdf text,
    pdf_status text,
    erro_pdf text,
    origem_url text,
    ativo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    ultima_atualizacao timestamp with time zone DEFAULT now() NOT NULL,
    id_origem text,
    data_nascimento date,
    idade integer,
    regime text,
    carga_horaria text,
    nota_empregare numeric,
    somatorio numeric,
    pcd text,
    coord_demandante text,
    email_demandante text,
    origem_planilha text,
    origem_arquivo_id text,
    pdf_gerado text,
    data_geracao_pdf timestamp with time zone,
    pdf_file_id text,
    pdf_ultima_tentativa timestamp with time zone,
    pdf_hash_origem text,
    linha_origem integer,
    hash_registro text,
    chave_natural text NOT NULL,
    grupo_norm text GENERATED ALWAYS AS (COALESCE(public.analises_norm_key(grupo), ''::text)) STORED,
    unidade_norm text GENERATED ALWAYS AS (COALESCE(public.analises_norm_key(unidade), ''::text)) STORED,
    edital_norm text GENERATED ALWAYS AS (COALESCE(public.analises_norm_key(edital), ''::text)) STORED,
    "CO_AREA" text,
    "CO_PLANILHA" text NOT NULL,
    experiencia_profissional_anos integer,
    experiencia_profissional_meses integer,
    experiencia_profissional_dias integer,
    experiencia_profissional_total numeric,
    "TP_ORIGEM_REGISTRO" character varying(10) DEFAULT 'PLANILHA'::character varying NOT NULL,
    CONSTRAINT "CK_ANALISECURRIC_TPORIGEMREG" CHECK ((("TP_ORIGEM_REGISTRO")::text = ANY (ARRAY[('PLANILHA'::character varying)::text, ('MONITORA'::character varying)::text])))
);

--
-- Name: COLUMN "TB_ANALISE_CURRICULAR"."CO_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANALISE_CURRICULAR"."CO_AREA" IS 'Área da análise, a partir do grupo da planilha (TB_AREA.NO_GRUPO_PLANILHA). Nulo se o grupo não for de área conhecida.';

--
-- Name: COLUMN "TB_ANALISE_CURRICULAR"."CO_PLANILHA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANALISE_CURRICULAR"."CO_PLANILHA" IS 'Planilha que enviou a análise (TB_PLANILHA_ANALISE). Só o sync dessa planilha altera ou desativa a linha.';

--
-- Name: COLUMN "TB_ANALISE_CURRICULAR".experiencia_profissional_anos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANALISE_CURRICULAR".experiencia_profissional_anos IS 'Anos de experiência profissional informados na planilha (Projetos, Edital 30/2026).';

--
-- Name: COLUMN "TB_ANALISE_CURRICULAR".experiencia_profissional_meses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANALISE_CURRICULAR".experiencia_profissional_meses IS 'Meses de experiência profissional informados na planilha.';

--
-- Name: COLUMN "TB_ANALISE_CURRICULAR".experiencia_profissional_dias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANALISE_CURRICULAR".experiencia_profissional_dias IS 'Dias de experiência profissional informados na planilha.';

--
-- Name: COLUMN "TB_ANALISE_CURRICULAR".experiencia_profissional_total; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANALISE_CURRICULAR".experiencia_profissional_total IS 'Total de experiência profissional (mesmo tipo de experiencia_saude_indigena_total).';

--
-- Name: COLUMN "TB_ANALISE_CURRICULAR"."TP_ORIGEM_REGISTRO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANALISE_CURRICULAR"."TP_ORIGEM_REGISTRO" IS 'Quem escreve a linha: PLANILHA (sincronização do Apps Script) ou MONITORA (publicada pela ficha da Avaliação documental, edital com TB_ORIGEM_ANALISE_EDITAL = MONITORA). A sincronização da planilha nunca grava, muda nem inativa uma linha MONITORA.';

--
-- Name: CONSTRAINT "CK_ANALISECURRIC_TPORIGEMREG" ON "TB_ANALISE_CURRICULAR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ANALISECURRIC_TPORIGEMREG" ON public."TB_ANALISE_CURRICULAR" IS 'Origens válidas da linha.';

--
-- Name: TB_ANEXO_CANDIDATO_APROVADO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ANEXO_CANDIDATO_APROVADO" (
    "CO_ANEXO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_CANDIDATO" uuid NOT NULL,
    "NO_ARQUIVO" text NOT NULL,
    "QT_TAMANHO_BYTES" integer NOT NULL,
    "CO_USUARIO_INCLUSAO" uuid NOT NULL,
    "DT_INCLUSAO" timestamp with time zone DEFAULT now() NOT NULL,
    "IM_ARQUIVO" bytea NOT NULL,
    CONSTRAINT "CK_ANEXO_CAND_IMARQUIVO" CHECK (((octet_length("IM_ARQUIVO") >= 5) AND (octet_length("IM_ARQUIVO") <= 2097152) AND (SUBSTRING("IM_ARQUIVO" FROM 1 FOR 5) = '\x255044462d'::bytea))),
    CONSTRAINT "CK_ANEXO_CAND_NOARQUIVO" CHECK ((NULLIF(btrim("NO_ARQUIVO"), ''::text) IS NOT NULL)),
    CONSTRAINT "CK_ANEXO_CAND_QTTAMANHOBYTES" CHECK ((("QT_TAMANHO_BYTES" >= 1) AND ("QT_TAMANHO_BYTES" <= 2097152)))
);
ALTER TABLE ONLY public."TB_ANEXO_CANDIDATO_APROVADO" ALTER COLUMN "IM_ARQUIVO" SET STORAGE EXTERNAL;

--
-- Name: TABLE "TB_ANEXO_CANDIDATO_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_ANEXO_CANDIDATO_APROVADO" IS 'Documentos PDF anexados a um candidato da lista de aprovados (ate 5 por candidato, 2 MB cada), com o arquivo em IM_ARQUIVO.';

--
-- Name: COLUMN "TB_ANEXO_CANDIDATO_APROVADO"."CO_ANEXO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANEXO_CANDIDATO_APROVADO"."CO_ANEXO" IS 'Identificador do anexo.';

--
-- Name: COLUMN "TB_ANEXO_CANDIDATO_APROVADO"."CO_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANEXO_CANDIDATO_APROVADO"."CO_CANDIDATO" IS 'Candidato da lista de aprovados (TB_CANDIDATO_APROVADO.id).';

--
-- Name: COLUMN "TB_ANEXO_CANDIDATO_APROVADO"."NO_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANEXO_CANDIDATO_APROVADO"."NO_ARQUIVO" IS 'Nome original do arquivo, como a pessoa o enviou.';

--
-- Name: COLUMN "TB_ANEXO_CANDIDATO_APROVADO"."QT_TAMANHO_BYTES"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANEXO_CANDIDATO_APROVADO"."QT_TAMANHO_BYTES" IS 'Tamanho de IM_ARQUIVO em bytes, gravado junto para a listagem nao precisar ler o arquivo.';

--
-- Name: COLUMN "TB_ANEXO_CANDIDATO_APROVADO"."CO_USUARIO_INCLUSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANEXO_CANDIDATO_APROVADO"."CO_USUARIO_INCLUSAO" IS 'Usuário (auth.uid()) que anexou.';

--
-- Name: COLUMN "TB_ANEXO_CANDIDATO_APROVADO"."DT_INCLUSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANEXO_CANDIDATO_APROVADO"."DT_INCLUSAO" IS 'Quando foi anexado.';

--
-- Name: COLUMN "TB_ANEXO_CANDIDATO_APROVADO"."IM_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANEXO_CANDIDATO_APROVADO"."IM_ARQUIVO" IS 'Conteudo do PDF. Comeca por %PDF- e tem ate 2 MB. Nunca vai na listagem: sai um por vez por baixar_anexo_candidato_aprovado.';

--
-- Name: TB_ANEXO_RECURSO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ANEXO_RECURSO" (
    "CO_ANEXO_RECURSO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_RECURSO_CANDIDATO" uuid NOT NULL,
    "CO_RESPOSTA_RECURSO" uuid,
    "TP_ANEXO" text NOT NULL,
    "NO_ARQUIVO" text NOT NULL,
    "DS_CAMINHO" text NOT NULL,
    "QT_BYTES" bigint NOT NULL,
    "DS_MIME" text NOT NULL,
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DS_MOTIVO_ARQUIVAMENTO" text,
    "DT_ARQUIVAMENTO" timestamp with time zone,
    "CO_USUARIO_ARQUIVAMENTO" uuid,
    "DT_INCLUSAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_INCLUSAO" uuid NOT NULL,
    CONSTRAINT "CK_ANEXORECURSO_ARQUIVAMENTO" CHECK ((((("ST_ATIVO")::text = 'S'::text) = ("DT_ARQUIVAMENTO" IS NULL)) AND (("DT_ARQUIVAMENTO" IS NULL) = ("DS_MOTIVO_ARQUIVAMENTO" IS NULL)) AND (("DT_ARQUIVAMENTO" IS NULL) = ("CO_USUARIO_ARQUIVAMENTO" IS NULL)))),
    CONSTRAINT "CK_ANEXORECURSO_DSMIME" CHECK (("DS_MIME" = ANY (ARRAY['application/pdf'::text, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'::text, 'application/msword'::text, 'image/jpeg'::text, 'image/png'::text, 'application/vnd.oasis.opendocument.text'::text]))),
    CONSTRAINT "CK_ANEXORECURSO_QTBYTES" CHECK ((("QT_BYTES" >= 1) AND ("QT_BYTES" <= 20971520))),
    CONSTRAINT "CK_ANEXORECURSO_STATIVO" CHECK ((("ST_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_ANEXORECURSO_TAMANHOS" CHECK (((length(btrim("NO_ARQUIVO")) >= 1) AND (length(btrim("NO_ARQUIVO")) <= 200) AND (length("DS_CAMINHO") <= 400) AND (COALESCE(length("DS_MOTIVO_ARQUIVAMENTO"), 0) <= 500))),
    CONSTRAINT "CK_ANEXORECURSO_TPANEXO" CHECK (("TP_ANEXO" = ANY (ARRAY['recurso_candidato'::text, 'resposta'::text, 'documento'::text, 'outro'::text])))
);

--
-- Name: TABLE "TB_ANEXO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_ANEXO_RECURSO" IS 'Arquivos anexados a um recurso (o recurso do candidato, a resposta, documentos). O arquivo fica no bucket privado recursos-anexos; aqui ficam os metadados. Arquivar não apaga o arquivo.';

--
-- Name: COLUMN "TB_ANEXO_RECURSO"."CO_ANEXO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ANEXO_RECURSO"."CO_ANEXO_RECURSO" IS 'Identificador do anexo.';

--
-- Name: COLUMN "TB_ANEXO_RECURSO"."CO_RECURSO_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

