-- Name: COLUMN "TB_APELIDO_RESPONSAVEL"."ST_ATIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_APELIDO_RESPONSAVEL"."ST_ATIVO" IS 'S: vale; N: ignorado.';

