-- Name: COLUMN "TB_APELIDO_RESPONSAVEL"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_APELIDO_RESPONSAVEL"."DT_CRIACAO" IS 'Criação do registro.';

