-- Name: COLUMN "TB_AREA"."NU_ORDEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_AREA"."NU_ORDEM" IS 'Ordem de exibição no menu.';

