--
-- Name: TB_CANDIDATO_APROVADO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_CANDIDATO_APROVADO" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lista_id uuid NOT NULL,
    codigo_vaga text,
    cargo text NOT NULL,
    classificacao integer,
    nota numeric NOT NULL,
    nome text NOT NULL,
    modalidade text,
    status text,
    processo_sei text,
    matricula text,
    sub_judice boolean DEFAULT false NOT NULL,
    removido_em timestamp with time zone,
    removido_por uuid,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    alterado_judicialmente boolean DEFAULT false NOT NULL,
    nota_original numeric,
    modalidade_original text,
    classificacao_original integer,
    sub_judice_original boolean,
    "CO_ANALISE_CURRICULAR" uuid,
    "TP_SITUACAO_CLASSIFICACAO" character varying(4),
    "CO_CANDIDATO_ANTERIOR" uuid,
    "DT_CONVOCACAO" date,
    CONSTRAINT "CK_CANDAPROVADO_DTCONVOCACAO" CHECK (((("DT_CONVOCACAO" IS NULL) OR (status IS NOT NULL)) AND ((status IS DISTINCT FROM 'Convocado'::text) OR ("DT_CONVOCACAO" IS NOT NULL)))),
    CONSTRAINT "CK_CANDAPROVADO_TPSITUACAO" CHECK ((("TP_SITUACAO_CLASSIFICACAO" IS NULL) OR (("TP_SITUACAO_CLASSIFICACAO")::text = ANY (ARRAY[('VAGA'::character varying)::text, ('CR'::character varying)::text])))),
    CONSTRAINT "CK_CANDIDATO_APROVADO_STATUS" CHECK (((status IS NULL) OR (status = ANY (ARRAY['Convocado'::text, 'Contratado'::text, 'Contratado em outra lista'::text, 'Desistente'::text, 'Migração'::text, 'Documentação Rejeitada'::text])))),
    CONSTRAINT lista_aprovados_classificacao_check CHECK (((classificacao IS NULL) OR (classificacao > 0))),
    CONSTRAINT lista_aprovados_importado_campos_check CHECK (((sub_judice IS TRUE) OR ((NULLIF(btrim(codigo_vaga), ''::text) IS NOT NULL) AND (classificacao IS NOT NULL) AND (NULLIF(btrim(modalidade), ''::text) IS NOT NULL)))),
    CONSTRAINT lista_aprovados_matricula_status_check CHECK (((status <> ALL (ARRAY['Contratado'::text, 'Migração'::text])) OR (NULLIF(btrim(matricula), ''::text) IS NOT NULL))),
    CONSTRAINT lista_aprovados_nota_check CHECK ((nota >= (0)::numeric))
);

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO".status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO".status IS 'Situação do candidato: Convocado (chamado para a contratação, aguardando apresentação e documentos; leva DT_CONVOCACAO), Contratado, Contratado em outra lista (fixado pela equipe: a mesma pessoa foi contratada pela outra linha do edital, ampla ou cota; não conta nos contratados nem ocupa vaga), Desistente, Migração ou Documentação Rejeitada. Nulo = sem status. Contratados (Seleção e KPIs) são Contratado e Migração, menos os Contratado que o instantâneo TB_CONTRATACAO_APROVADO dá como em outra lista.';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO".alterado_judicialmente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO".alterado_judicialmente IS 'Nota e/ou modalidade alteradas por decisão judicial (alterar_candidato_sub_judice).';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO".nota_original; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO".nota_original IS 'Nota do resultado publicado, gravada na primeira alteração judicial.';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO".modalidade_original; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO".modalidade_original IS 'Modalidade do resultado publicado, gravada na primeira alteração judicial.';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO".classificacao_original; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO".classificacao_original IS 'Classificação do resultado publicado, gravada na primeira alteração judicial (desempate e desfazer).';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO".sub_judice_original; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO".sub_judice_original IS 'Se já era sub judice (inclusão) antes da primeira alteração; volta no desfazer.';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO"."CO_ANALISE_CURRICULAR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO"."CO_ANALISE_CURRICULAR" IS 'Análise curricular do candidato (TB_ANALISE_CURRICULAR.id), nas listas publicadas da Classificação; nula nas de planilha.';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO"."TP_SITUACAO_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO"."TP_SITUACAO_CLASSIFICACAO" IS 'No resultado final da Classificação: VAGA (dentro das vagas) ou CR (cadastro reserva); nula nas listas de planilha.';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO"."CO_CANDIDATO_ANTERIOR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO"."CO_CANDIDATO_ANTERIOR" IS 'O mesmo candidato na lista anterior do edital, de onde vieram status, matrícula, processo, sub judice e anexos na publicação.';

--
-- Name: COLUMN "TB_CANDIDATO_APROVADO"."DT_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CANDIDATO_APROVADO"."DT_CONVOCACAO" IS 'Data em que o candidato foi convocado para a contratação. Fica depois que ele segue para Contratado, Desistente ou Documentação Rejeitada; some quando o status volta a nulo. A publicação de uma lista nova a herda do candidato anterior (TG_CANDAPROVADO_CONVOCACAO).';

--
-- Name: CONSTRAINT "CK_CANDAPROVADO_DTCONVOCACAO" ON "TB_CANDIDATO_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CANDAPROVADO_DTCONVOCACAO" ON public."TB_CANDIDATO_APROVADO" IS 'Data da convocação só com status; Convocado sempre com a data.';

--
-- Name: CONSTRAINT "CK_CANDAPROVADO_TPSITUACAO" ON "TB_CANDIDATO_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CANDAPROVADO_TPSITUACAO" ON public."TB_CANDIDATO_APROVADO" IS 'Situações do resultado final.';

--
-- Name: CONSTRAINT "CK_CANDIDATO_APROVADO_STATUS" ON "TB_CANDIDATO_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CANDIDATO_APROVADO_STATUS" ON public."TB_CANDIDATO_APROVADO" IS 'Status válidos (Fim de Fila saiu em 20261005180000; Contratado em outra lista entrou em 20261024120000).';

--
-- Name: TB_CASO_AVISO_CONFERENCIA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_CASO_AVISO_CONFERENCIA" (
    "CO_AVISO_CONFERENCIA" uuid NOT NULL,
    "NU_CASO" integer NOT NULL,
    "CO_ANALISE_CURRICULAR" uuid,
    "CO_CANDIDATO_EMPREGARE" character varying(80),
    "DS_REFERENCIA" character varying(80),
    "DS_DETALHE" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "TP_REFERENCIA" character varying(30),
    CONSTRAINT "CK_CASOAVISO_CODIGOS" CHECK (((("CO_CANDIDATO_EMPREGARE" IS NULL) OR ((("CO_CANDIDATO_EMPREGARE")::text ~ '^[A-Za-z0-9._:/-]{1,80}$'::text) AND (("CO_CANDIDATO_EMPREGARE")::text !~ '[0-9]{11}'::text))) AND (("DS_REFERENCIA" IS NULL) OR ((("DS_REFERENCIA")::text ~ '^[A-Za-z0-9._:/-]{1,80}$'::text) AND (("DS_REFERENCIA")::text !~ '[0-9]{11}'::text))))),
    CONSTRAINT "CK_CASOAVISO_DSDETALHE" CHECK (((jsonb_typeof("DS_DETALHE") = 'object'::text) AND (length(("DS_DETALHE")::text) <= 1000) AND (("DS_DETALHE")::text !~ '@'::text) AND (("DS_DETALHE")::text !~ '[0-9]{11}'::text))),
    CONSTRAINT "CK_CASOAVISO_IDENTIFICA" CHECK ((num_nonnulls("CO_ANALISE_CURRICULAR", "CO_CANDIDATO_EMPREGARE", "DS_REFERENCIA") >= 1)),
    CONSTRAINT "CK_CASOAVISO_NUCASO" CHECK ((("NU_CASO" >= 1) AND ("NU_CASO" <= 5000))),
    CONSTRAINT "CK_CASOAVISO_TPREFERENCIA" CHECK ((("TP_REFERENCIA" IS NULL) OR (("TP_REFERENCIA")::text = ANY (ARRAY[('candidato_aprovado'::character varying)::text, ('entrevista'::character varying)::text, ('lista_classificacao'::character varying)::text, ('ajuste_recurso'::character varying)::text, ('vaga'::character varying)::text, ('vaga_empregare'::character varying)::text]))))
);

--
-- Name: TABLE "TB_CASO_AVISO_CONFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_CASO_AVISO_CONFERENCIA" IS 'Casos de cada aviso de conferência (job Python scripts/conferencias/): até 5000 por aviso, só ids, códigos e o dado que motivou o aviso. Nome, edital, vaga e responsável vêm da análise na leitura (listar_casos_aviso_conferencia).';

--
-- Name: COLUMN "TB_CASO_AVISO_CONFERENCIA"."CO_AVISO_CONFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CASO_AVISO_CONFERENCIA"."CO_AVISO_CONFERENCIA" IS 'Aviso (TB_AVISO_CONFERENCIA) do caso.';

--
-- Name: COLUMN "TB_CASO_AVISO_CONFERENCIA"."NU_CASO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CASO_AVISO_CONFERENCIA"."NU_CASO" IS 'Posição do caso no aviso (1 a 5000), na ordem em que o job achou.';

--
-- Name: COLUMN "TB_CASO_AVISO_CONFERENCIA"."CO_ANALISE_CURRICULAR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CASO_AVISO_CONFERENCIA"."CO_ANALISE_CURRICULAR" IS 'Análise curricular do caso (TB_ANALISE_CURRICULAR.id), quando o caso é uma análise. Sem chave estrangeira: a análise pode sair na carga das planilhas e o aviso fica até a próxima conferência.';

--
-- Name: COLUMN "TB_CASO_AVISO_CONFERENCIA"."CO_CANDIDATO_EMPREGARE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CASO_AVISO_CONFERENCIA"."CO_CANDIDATO_EMPREGARE" IS 'Código do candidato na Empregare (TB_ANALISE_CURRICULAR.id_origem), quando o caso é o candidato (ex.: analisado em dois editais).';

--
-- Name: COLUMN "TB_CASO_AVISO_CONFERENCIA"."DS_REFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CASO_AVISO_CONFERENCIA"."DS_REFERENCIA" IS 'Outro identificador do caso (entrevista, lista, vaga, aprovado), quando não é análise nem candidato.';

--
-- Name: COLUMN "TB_CASO_AVISO_CONFERENCIA"."DS_DETALHE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CASO_AVISO_CONFERENCIA"."DS_DETALHE" IS 'O dado que motivou o aviso (objeto json: data_analise, inscricao, motivo, nota, corte, soma, experiencia, teto…). Sem nome, CPF ou e-mail.';

--
-- Name: COLUMN "TB_CASO_AVISO_CONFERENCIA"."TP_REFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CASO_AVISO_CONFERENCIA"."TP_REFERENCIA" IS 'O que DS_REFERENCIA identifica: candidato_aprovado (TB_CANDIDATO_APROVADO.id), entrevista (TB_ENTREVISTA), lista_classificacao (TB_LISTA_CLASSIFICACAO), ajuste_recurso (TB_AJUSTE_PONTUACAO_RECURSO), vaga (código da vaga nas análises) ou vaga_empregare (TB_EMPREGARE_VAGA). Nulo nos casos gravados antes: a leitura deduz pelo código da conferência.';

--
-- Name: CONSTRAINT "CK_CASOAVISO_CODIGOS" ON "TB_CASO_AVISO_CONFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CASOAVISO_CODIGOS" ON public."TB_CASO_AVISO_CONFERENCIA" IS 'Código e referência só com caracteres de identificador, sem 11 dígitos seguidos (CPF).';

--
-- Name: CONSTRAINT "CK_CASOAVISO_DSDETALHE" ON "TB_CASO_AVISO_CONFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CASOAVISO_DSDETALHE" ON public."TB_CASO_AVISO_CONFERENCIA" IS 'Detalhe em objeto json de até 1000 caracteres, sem @ (e-mail) e sem 11 dígitos seguidos (CPF).';

--
-- Name: CONSTRAINT "CK_CASOAVISO_IDENTIFICA" ON "TB_CASO_AVISO_CONFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CASOAVISO_IDENTIFICA" ON public."TB_CASO_AVISO_CONFERENCIA" IS 'O caso aponta para uma análise, um candidato ou outra referência.';

--
-- Name: CONSTRAINT "CK_CASOAVISO_NUCASO" ON "TB_CASO_AVISO_CONFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CASOAVISO_NUCASO" ON public."TB_CASO_AVISO_CONFERENCIA" IS 'Até 5000 casos por aviso.';

--
-- Name: CONSTRAINT "CK_CASOAVISO_TPREFERENCIA" ON "TB_CASO_AVISO_CONFERENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CASOAVISO_TPREFERENCIA" ON public."TB_CASO_AVISO_CONFERENCIA" IS 'Tipo da referência entre os conhecidos pela leitura (listar_casos_aviso_conferencia).';

--
-- Name: TB_CATEGORIA_CONVOCACAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_CATEGORIA_CONVOCACAO" (
    "CO_MODELO" uuid NOT NULL,
    "CO_CATEGORIA" text NOT NULL,
    "NO_CATEGORIA" text NOT NULL,
    "SG_CATEGORIA" character varying(10) NOT NULL,
    "ST_AMPLA" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "ST_ACUMULAVEL" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "TX_RESERVA" numeric(5,2) DEFAULT 0 NOT NULL,
    "TP_ARREDONDAMENTO" character varying(20) DEFAULT 'MEIO_ACIMA'::character varying NOT NULL,
    "TX_TETO" numeric(5,2) DEFAULT 0 NOT NULL,
    "QT_MINIMA_RESERVA" integer DEFAULT 0 NOT NULL,
    "DS_TERMO" text DEFAULT ''::text NOT NULL,
    "DS_POSICAO" text DEFAULT ''::text NOT NULL,
    "QT_INTERVALO" integer DEFAULT 0 NOT NULL,
    "DS_CASCATA" text DEFAULT ''::text NOT NULL,
    "NU_ORDEM" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "CK_CATEG_CONVOC_ACUMULAVEL" CHECK ((("ST_ACUMULAVEL")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_CATEG_CONVOC_AMPLA" CHECK ((("ST_AMPLA")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_CATEG_CONVOC_ARREDOND" CHECK ((("TP_ARREDONDAMENTO")::text = ANY (ARRAY[('MEIO_ACIMA'::character varying)::text, ('SEMPRE_ACIMA'::character varying)::text]))),
    CONSTRAINT "CK_CATEG_CONVOC_INTERVALO" CHECK (("QT_INTERVALO" >= 0)),
    CONSTRAINT "CK_CATEG_CONVOC_MINIMA" CHECK (("QT_MINIMA_RESERVA" >= 0)),
    CONSTRAINT "CK_CATEG_CONVOC_TAXA" CHECK ((("TX_RESERVA" >= (0)::numeric) AND ("TX_RESERVA" <= (100)::numeric) AND (("TX_TETO" >= (0)::numeric) AND ("TX_TETO" <= (100)::numeric))))
);

--
-- Name: TABLE "TB_CATEGORIA_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_CATEGORIA_CONVOCACAO" IS 'Categorias de um modelo de convocacao: ampla concorrencia e cada reserva, com as suas regras proprias.';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."CO_MODELO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."CO_MODELO" IS 'Modelo de convocação da categoria (TB_MODELO_CONVOCACAO).';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."CO_CATEGORIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."CO_CATEGORIA" IS 'Identificador da categoria dentro do modelo, em minusculas com underscore (ex.: pretos_pardos).';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."NO_CATEGORIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."NO_CATEGORIA" IS 'Nome da categoria como aparece na tela e no quadro de vagas.';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."SG_CATEGORIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."SG_CATEGORIA" IS 'Sigla da categoria (até 10 caracteres), usada nas colunas do quadro.';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."ST_AMPLA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."ST_AMPLA" IS 'S na unica categoria que recebe o resto das vagas. Sem ela nao haveria para onde reverter reserva vazia.';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."ST_ACUMULAVEL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."ST_ACUMULAVEL" IS 'S na categoria que pode somar-se a outra na mesma pessoa quando o modelo usa ACUMULA_COM_ACUMULAVEL. Edital 91/2026 item 5.13: e a de PCD.';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."TX_RESERVA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."TX_RESERVA" IS 'Percentual das vagas reservado a esta categoria. Zero na ampla, que e o resto.';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."TP_ARREDONDAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."TP_ARREDONDAMENTO" IS 'MEIO_ACIMA: fracao >= 0,5 sobe. SEMPRE_ACIMA: qualquer fracao sobe (edital 91/2026 para PCD).';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."TX_TETO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."TX_TETO" IS 'Percentual maximo que esta reserva pode ocupar depois do arredondamento. Zero significa sem teto.';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."QT_MINIMA_RESERVA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_CATEGORIA_CONVOCACAO"."QT_MINIMA_RESERVA" IS 'Vagas minimas na vaga para ESTA reserva se aplicar. Zero significa sempre. Edital FGV: 2 nas cotas raciais (7.1.3) e 5 no PCD (6.5) - o mesmo edital, dois minimos, e por isso o campo e da categoria e nao do modelo.';

--
-- Name: COLUMN "TB_CATEGORIA_CONVOCACAO"."DS_TERMO"; Type: COMMENT; Schema: public; Owner: -
--

