--
-- Name: TB_COORDENADA_LOCAL_VAGA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_COORDENADA_LOCAL_VAGA" (
    "CO_SEQ_COORDENADA_LOCAL" bigint NOT NULL,
    "DS_CHAVE_LUGAR" character varying(160) NOT NULL,
    "CO_MUNICIPIO_IBGE" integer,
    "NO_MUNICIPIO" character varying(100),
    "SG_UF" character varying(2) NOT NULL,
    "CG_LATITUDE" double precision NOT NULL,
    "CG_LONGITUDE" double precision NOT NULL,
    "TP_ORIGEM" character varying(9) NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid,
    CONSTRAINT "CK_COORDLOCAL_LUGAR" CHECK ((((("DS_CHAVE_LUGAR")::text ~ '^uf:[A-Z]{2}$'::text) AND (("DS_CHAVE_LUGAR")::text = ('uf:'::text || ("SG_UF")::text)) AND ("CO_MUNICIPIO_IBGE" IS NULL)) OR ((("DS_CHAVE_LUGAR")::text ~ '^[^/A-Z]+/[A-Z]{2}$'::text) AND ("right"(("DS_CHAVE_LUGAR")::text, 2) = ("SG_UF")::text)))),
    CONSTRAINT "CK_COORDLOCAL_MANUAL" CHECK (((("TP_ORIGEM")::text = 'MANUAL'::text) = ("CO_USUARIO_ATUALIZACAO" IS NOT NULL))),
    CONSTRAINT "CK_COORDLOCAL_MUNICIPIO" CHECK ((("CO_MUNICIPIO_IBGE" >= 1100000) AND ("CO_MUNICIPIO_IBGE" <= 5399999))),
    CONSTRAINT "CK_COORDLOCAL_ORIGEM" CHECK ((("TP_ORIGEM")::text = ANY (ARRAY[('SEDE_IBGE'::character varying)::text, ('CENTRO_UF'::character varying)::text, ('MANUAL'::character varying)::text]))),
    CONSTRAINT "CK_COORDLOCAL_POSICAO" CHECK ((("CG_LATITUDE" >= ('-90'::integer)::double precision) AND ("CG_LATITUDE" <= (90)::double precision) AND (("CG_LONGITUDE" >= ('-180'::integer)::double precision) AND ("CG_LONGITUDE" <= (180)::double precision)))),
    CONSTRAINT "CK_COORDLOCAL_UF" CHECK ((("SG_UF")::text = ANY (ARRAY[('RO'::character varying)::text, ('AC'::character varying)::text, ('AM'::character varying)::text, ('RR'::character varying)::text, ('PA'::character varying)::text, ('AP'::character varying)::text, ('TO'::character varying)::text, ('MA'::character varying)::text, ('PI'::character varying)::text, ('CE'::character varying)::text, ('RN'::character varying)::text, ('PB'::character varying)::text, ('PE'::character varying)::text, ('AL'::character varying)::text, ('SE'::character varying)::text, ('BA'::character varying)::text, ('MG'::character varying)::text, ('ES'::character varying)::text, ('RJ'::character varying)::text, ('SP'::character varying)::text, ('PR'::character varying)::text, ('SC'::character varying)::text, ('RS'::character varying)::text, ('MS'::character varying)::text, ('MT'::character varying)::text, ('GO'::character varying)::text, ('DF'::character varying)::text])))
);

