-- Name: TB_CRONOGRAMA_MONIT_INDIG; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_CRONOGRAMA_MONIT_INDIG" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    monitoramento_id uuid NOT NULL,
    ordem integer NOT NULL,
    atividade text NOT NULL,
    tipo_atividade text,
    data_inicio date NOT NULL,
    data_fim date NOT NULL,
    concluida boolean,
    observacao text,
    origem text DEFAULT 'MANUAL'::text NOT NULL,
    confianca_extracao numeric(5,2),
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_CRONOG_MONIT_DATA_ETAPA" CHECK (((data_inicio >= '2015-01-01'::date) AND (data_inicio <= '2100-12-31'::date) AND ((data_fim IS NULL) OR ((data_fim >= '2015-01-01'::date) AND (data_fim <= '2100-12-31'::date))))),
    CONSTRAINT monitoramento_cronograma_confianca_valida CHECK (((confianca_extracao IS NULL) OR ((confianca_extracao >= (0)::numeric) AND (confianca_extracao <= (100)::numeric)))),
    CONSTRAINT monitoramento_cronograma_datas_validas CHECK ((data_fim >= data_inicio)),
    CONSTRAINT monitoramento_cronograma_origem_valida CHECK ((origem = ANY (ARRAY['PDF'::text, 'MANUAL'::text, 'AJUSTE'::text, 'ERRATA'::text])))
);

--
-- Name: CONSTRAINT "CK_CRONOG_MONIT_DATA_ETAPA" ON "TB_CRONOGRAMA_MONIT_INDIG"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_CRONOG_MONIT_DATA_ETAPA" ON public."TB_CRONOGRAMA_MONIT_INDIG" IS 'Datas da etapa com ano entre 2015 e 2100 (os mesmos limites da tela).';

--
-- Name: TB_DECISAO_LOTE; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_DECISAO_LOTE" (
    "CO_DECISAO_LOTE" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_EMPREGARE_CANDIDATO" uuid NOT NULL,
    "CO_VAGA" character varying(20) NOT NULL,
    "DS_MOTIVO" character varying(250) NOT NULL,
    "CO_USUARIO_DECISAO" uuid NOT NULL,
    "DT_DECISAO" timestamp with time zone DEFAULT now() NOT NULL,
    "TP_SITUACAO_REGRA" character varying(12) NOT NULL,
    "CO_MOTIVO_ELIMINACAO_REGRA" character varying(30),
    "DS_MOTIVO_ELIMINACAO_REGRA" character varying(200),
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DS_MOTIVO_REVOGACAO" character varying(250),
    "CO_USUARIO_REVOGACAO" uuid,
    "DT_REVOGACAO" timestamp with time zone,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_DECISAOLOTE_MOTIVO" CHECK (((length(btrim(("DS_MOTIVO")::text)) >= 5) AND (length(btrim(("DS_MOTIVO")::text)) <= 250))),
    CONSTRAINT "CK_DECISAOLOTE_REVOGACAO" CHECK (
CASE
    WHEN (("ST_ATIVO")::text = 'S'::text) THEN (("DS_MOTIVO_REVOGACAO" IS NULL) AND ("CO_USUARIO_REVOGACAO" IS NULL) AND ("DT_REVOGACAO" IS NULL))
    ELSE ((length(btrim((COALESCE("DS_MOTIVO_REVOGACAO", ''::character varying))::text)) >= 10) AND (length(btrim((COALESCE("DS_MOTIVO_REVOGACAO", ''::character varying))::text)) <= 250) AND ("CO_USUARIO_REVOGACAO" IS NOT NULL) AND ("DT_REVOGACAO" IS NOT NULL))
END),
    CONSTRAINT "CK_DECISAOLOTE_SITREGRA" CHECK (((("TP_SITUACAO_REGRA")::text = ANY (ARRAY[('ELIMINADO'::character varying)::text, ('RANQUEADO'::character varying)::text])) AND ((("TP_SITUACAO_REGRA")::text = 'ELIMINADO'::text) = ("CO_MOTIVO_ELIMINACAO_REGRA" IS NOT NULL)) AND (("CO_MOTIVO_ELIMINACAO_REGRA" IS NULL) = ("DS_MOTIVO_ELIMINACAO_REGRA" IS NULL)))),
    CONSTRAINT "CK_DECISAOLOTE_STATIVO" CHECK ((("ST_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text])))
);

--
-- Name: TABLE "TB_DECISAO_LOTE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_DECISAO_LOTE" IS 'Inclusões no lote de convocação por decisão da coordenação da avaliação documental (ex.: "Critério CORES"): o candidato fica no lote (TP_ENTRADA_LOTE DECISAO) mesmo que a regra o elimine ou o deixe abaixo do corte, em todo recálculo, até a revogação. Revogar é exclusão lógica (ST_ATIVO N, com motivo); nada se apaga. Histórico em TH_DECISAO_LOTE.';

