CREATE TABLE public."TB_DEMANDA_INTERNA" (
    "CO_DEMANDA_INTERNA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_AREA" text NOT NULL,
    "CO_MONITORAMENTO" uuid,
    "NO_DEMANDA" character varying(200) NOT NULL,
    "DS_DEMANDA" character varying(2000),
    "DT_INICIO" date NOT NULL,
    "DT_FIM" date NOT NULL,
    "ST_CONCLUIDA" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "DT_CONCLUSAO" timestamp with time zone,
    "CO_USUARIO_CONCLUSAO" uuid,
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "CO_USUARIO_CRIACAO" uuid,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_DEMANDAINTERNA_CONCLUSAO" CHECK (((("ST_CONCLUIDA")::text = 'S'::text) = ("DT_CONCLUSAO" IS NOT NULL))),
    CONSTRAINT "CK_DEMANDAINTERNA_NODEMANDA" CHECK (((length(btrim(("NO_DEMANDA")::text)) >= 3) AND (length(btrim(("NO_DEMANDA")::text)) <= 200))),
    CONSTRAINT "CK_DEMANDAINTERNA_PERIODO" CHECK (("DT_FIM" >= "DT_INICIO")),
    CONSTRAINT "CK_DEMANDAINTERNA_STATIVO" CHECK ((("ST_ATIVO")::text = ANY ((ARRAY['S'::character varying, 'N'::character varying])::text[]))),
    CONSTRAINT "CK_DEMANDAINTERNA_STCONCLUIDA" CHECK ((("ST_CONCLUIDA")::text = ANY ((ARRAY['S'::character varying, 'N'::character varying])::text[])))
);

--
-- Name: TABLE "TB_DEMANDA_INTERNA"; Type: COMMENT; Schema: public; Owner: -
