--
-- Name: TB_EDITAL_ANALISE; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_EDITAL_ANALISE" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    grupo text,
    unidade text NOT NULL,
    edital text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    data_inicio_analise date,
    data_fim_analise date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    grupo_norm text GENERATED ALWAYS AS (COALESCE(public.analises_norm_key(grupo), ''::text)) STORED,
    unidade_norm text GENERATED ALWAYS AS (COALESCE(public.analises_norm_key(unidade), ''::text)) STORED,
    edital_norm text GENERATED ALWAYS AS (COALESCE(public.analises_norm_key(edital), ''::text)) STORED,
    "CO_PLANILHA" text NOT NULL
);

--
-- Name: COLUMN "TB_EDITAL_ANALISE"."CO_PLANILHA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EDITAL_ANALISE"."CO_PLANILHA" IS 'Planilha que enviou o edital (TB_PLANILHA_ANALISE). Só o sync dessa planilha altera ou desativa a linha.';

--
-- Name: TB_EMPREGARE_ANEXO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_EMPREGARE_ANEXO" (
    "CO_EMPREGARE_ANEXO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_EMPREGARE_RESPOSTA" uuid NOT NULL,
    "CO_PERGUNTA_EMPREGARE" character varying(20) NOT NULL,
    "NU_ARQUIVO" smallint DEFAULT 1 NOT NULL,
    "NU_ORDEM" smallint,
    "DS_ENUNCIADO" character varying(2000),
    "DS_COLUNA" character varying(1000),
    "TP_LINK" character varying(20) DEFAULT 'ARQUIVO_EMPREGARE'::character varying NOT NULL,
    "DS_LINK" character varying(1500) NOT NULL,
    "DT_CAPTURA" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_EMPREGANEXO_COPERGUNTA" CHECK ((("CO_PERGUNTA_EMPREGARE")::text ~ '^[0-9]{1,20}$'::text)),
    CONSTRAINT "CK_EMPREGANEXO_DSLINK" CHECK ((("DS_LINK")::text ~ '^https://corporate\.empregare\.com/Company/VacancyTests/GetViewerLogArquivo\?[A-Za-z0-9_.~=&%|+/:-]+$'::text)),
    CONSTRAINT "CK_EMPREGANEXO_NUARQUIVO" CHECK ((("NU_ARQUIVO" >= 1) AND ("NU_ARQUIVO" <= 50))),
    CONSTRAINT "CK_EMPREGANEXO_NUORDEM" CHECK ((("NU_ORDEM" IS NULL) OR (("NU_ORDEM" >= 1) AND ("NU_ORDEM" <= 999)))),
    CONSTRAINT "CK_EMPREGANEXO_TPLINK" CHECK ((("TP_LINK")::text = 'ARQUIVO_EMPREGARE'::text))
);

--
-- Name: TABLE "TB_EMPREGARE_ANEXO"; Type: COMMENT; Schema: public; Owner: -
