-- Name: COLUMN "TB_EMPREGARE_ANEXO"."TP_LINK"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_ANEXO"."TP_LINK" IS 'ARQUIVO_EMPREGARE: abre o visualizador da Empregare com login (não expira).';

--
