-- Name: COLUMN "TB_EMPREGARE_CANDIDATO"."CO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_CANDIDATO"."CO_VAGA" IS 'Vaga da Empregare (TB_EMPREGARE_VAGA).';

