-- Name: CONSTRAINT "CK_EMPREGCAND_STATIVO" ON "TB_EMPREGARE_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_EMPREGCAND_STATIVO" ON public."TB_EMPREGARE_CANDIDATO" IS 'Flag S/N.';

