-- Name: CONSTRAINT "CK_EMPREGCAND_TPCHAVE" ON "TB_EMPREGARE_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_EMPREGCAND_TPCHAVE" ON public."TB_EMPREGARE_CANDIDATO" IS 'Tipo da chave confere com o prefixo.';

--
-- Name: TB_EMPREGARE_RESPOSTA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_EMPREGARE_RESPOSTA" (
    "CO_EMPREGARE_RESPOSTA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_EMPREGARE_CANDIDATO" uuid NOT NULL,
    "CO_RESPOSTA_QUESTIONARIO" character varying(20) NOT NULL,
    "DS_LINK_IMPRESSAO" character varying(1500),
    "QT_PERGUNTA" integer DEFAULT 0 NOT NULL,
    "QT_ANEXO" integer DEFAULT 0 NOT NULL,
    "CO_SYNC" text,
    "DT_CAPTURA" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_EMPREGRESP_CORESPOSTA" CHECK ((("CO_RESPOSTA_QUESTIONARIO")::text ~ '^[0-9]{1,20}$'::text)),
    CONSTRAINT "CK_EMPREGRESP_DSLINKIMPRESSAO" CHECK ((("DS_LINK_IMPRESSAO" IS NULL) OR (("DS_LINK_IMPRESSAO")::text ~ '^https://corporate\.empregare\.com/Company/VacancyTests/PrintResult\?[A-Za-z0-9_.~=&%|+/:-]+$'::text))),
    CONSTRAINT "CK_EMPREGRESP_QUANTIDADES" CHECK ((("QT_PERGUNTA" >= 0) AND ("QT_PERGUNTA" <= 10000) AND (("QT_ANEXO" >= 0) AND ("QT_ANEXO" <= 10000))))
);

--
-- Name: TABLE "TB_EMPREGARE_RESPOSTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_EMPREGARE_RESPOSTA" IS 'Resposta de um candidato a um questionário da vaga na Empregare (data-resposta da lista de candidaturas), lida pelo robô em GetRespostaDetails. DADO RESTRITO: o link de impressão leva o token da pessoa; só a RPC da ficha devolve.';

--
-- Name: COLUMN "TB_EMPREGARE_RESPOSTA"."CO_EMPREGARE_RESPOSTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_RESPOSTA"."CO_EMPREGARE_RESPOSTA" IS 'Identificador da linha.';

