-- Name: COLUMN "TB_EMPREGARE_RESPOSTA"."QT_ANEXO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_RESPOSTA"."QT_ANEXO" IS 'Anexos (links Visualizar Arquivo) lidos na resposta.';

--
-- Name: COLUMN "TB_EMPREGARE_RESPOSTA"."CO_SYNC"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_RESPOSTA"."CO_SYNC" IS 'Execução do robô que leu (TL_SYNC_EMPREGARE).';

--
-- Name: COLUMN "TB_EMPREGARE_RESPOSTA"."DT_CAPTURA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_RESPOSTA"."DT_CAPTURA" IS 'Quando o robô leu pela última vez.';

--
-- Name: TB_EMPREGARE_VAGA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_EMPREGARE_VAGA" (
    "CO_VAGA" text NOT NULL,
    "CO_MONITORAMENTO" uuid,
    "TP_SITUACAO" text DEFAULT 'EM_CARGA'::text NOT NULL,
    "DS_COLUNA" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "NO_ARQUIVO" character varying(300),
    "QT_CANDIDATO_ATIVO" integer DEFAULT 0 NOT NULL,
    "QT_LINHA_ARQUIVO" integer,
    "QT_RECEBIDA" integer DEFAULT 0 NOT NULL,
    "DS_MENSAGEM" text,
    "CO_SYNC" text,
    "DT_ULTIMA_CARGA" timestamp with time zone,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_VAGA_INTERNO" character varying(100),
    "DT_CAPTURA_LINK" timestamp with time zone,
    CONSTRAINT "CK_EMPREGVAGA_COVAGA" CHECK (("CO_VAGA" ~ '^[0-9]{1,20}$'::text)),
    CONSTRAINT "CK_EMPREGVAGA_COVAGAINTERNO" CHECK ((("CO_VAGA_INTERNO" IS NULL) OR ((("CO_VAGA_INTERNO")::text ~ '^[A-Za-z0-9_.~=-]{1,96}[|]{0,3}$'::text) AND (("CO_VAGA_INTERNO")::text !~ '^[0-9]+[|]*$'::text)))),
    CONSTRAINT "CK_EMPREGVAGA_DSCOLUNA" CHECK ((jsonb_typeof("DS_COLUNA") = 'array'::text)),
    CONSTRAINT "CK_EMPREGVAGA_MENSAGEM" CHECK ((COALESCE(length("DS_MENSAGEM"), 0) <= 1000)),
    CONSTRAINT "CK_EMPREGVAGA_QT" CHECK ((("QT_CANDIDATO_ATIVO" >= 0) AND ("QT_RECEBIDA" >= 0) AND (COALESCE("QT_LINHA_ARQUIVO", 0) >= 0))),
    CONSTRAINT "CK_EMPREGVAGA_TPSITUACAO" CHECK (("TP_SITUACAO" = ANY (ARRAY['EM_CARGA'::text, 'GRAVADA'::text, 'RECUSADA'::text, 'INCOMPLETA'::text])))
);

--
-- Name: TABLE "TB_EMPREGARE_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_EMPREGARE_VAGA" IS 'Última carga de cada vaga da Empregare pelo robô: situação, colunas do Excel e candidatos ativos.';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."CO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."CO_VAGA" IS 'Código da vaga na Empregare (ex.: 177979): do quadro do edital (pelas análises do edital) ou o CO_VAGA de TB_SELECAO_VAGA.';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id): pelo quadro de vagas do edital, senão pela vaga ativa de TB_SELECAO_VAGA; nulo sem ligação.';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."TP_SITUACAO" IS 'EM_CARGA (recebendo lotes); GRAVADA; RECUSADA (trava da metade); INCOMPLETA (a execução terminou no meio da vaga: nada foi desativado).';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."DS_COLUNA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."DS_COLUNA" IS 'Nomes das colunas do último Excel gravado, na ordem do arquivo (o jsonb das linhas não guarda ordem).';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."NO_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."NO_ARQUIVO" IS 'Nome do último Excel gravado.';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."QT_CANDIDATO_ATIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."QT_CANDIDATO_ATIVO" IS 'Candidatos ativos da vaga depois da última carga gravada.';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."QT_LINHA_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."QT_LINHA_ARQUIVO" IS 'Candidatos com chave no último arquivo recebido (gravado ou recusado).';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."QT_RECEBIDA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."QT_RECEBIDA" IS 'Candidatos recebidos na carga em curso (soma dos lotes).';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."DS_MENSAGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."DS_MENSAGEM" IS 'Motivo da recusa ou da carga incompleta.';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."CO_SYNC"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."CO_SYNC" IS 'Última execução (TL_SYNC_EMPREGARE) que mexeu na vaga.';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."DT_ULTIMA_CARGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."DT_ULTIMA_CARGA" IS 'Quando a vaga foi gravada pela última vez (situação GRAVADA).';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_EMPREGARE_VAGA"."DT_CRIACAO" IS 'Primeira carga da vaga.';

--
-- Name: COLUMN "TB_EMPREGARE_VAGA"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

