--
-- Name: TB_ENTREVISTA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ENTREVISTA" (
    "CO_ENTREVISTA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_AREA" text NOT NULL,
    "CO_MONITORAMENTO" uuid,
    "CO_ANALISE_CURRICULAR" uuid,
    "TP_LIGACAO_ANALISE" text,
    "NO_UNIDADE" text NOT NULL,
    "DS_EDITAL" text NOT NULL,
    "CO_VAGA" text NOT NULL,
    "NO_CANDIDATO" text NOT NULL,
    "CO_CANDIDATO" text,
    "DS_MODALIDADE" text,
    "NO_CARGO" text,
    "VL_NOTA_TOTAL" numeric(6,2),
    "TP_PARECER" text DEFAULT 'SEM_PARECER'::text NOT NULL,
    "ST_COMPARECEU" character varying(1),
    "DS_LINK_PLANILHA" text,
    "TP_ORIGEM" text DEFAULT 'planilha'::text NOT NULL,
    "DS_CHAVE_ORIGEM" text NOT NULL,
    "CO_SYNC" text,
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_ROTEIRO" uuid,
    "NU_BANCA" smallint,
    "DS_JUSTIFICATIVA_BANCA" text,
    CONSTRAINT "CK_ENTREVISTA_DSJUSTIFICATIVABANCA" CHECK ((COALESCE(length("DS_JUSTIFICATIVA_BANCA"), 0) <= 4000)),
    CONSTRAINT "CK_ENTREVISTA_STATIVO" CHECK ((("ST_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_ENTREVISTA_STCOMPARECEU" CHECK ((("ST_COMPARECEU")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_ENTREVISTA_TAMANHOS" CHECK (((length("NO_UNIDADE") <= 200) AND (length("DS_EDITAL") <= 120) AND (length("CO_VAGA") <= 60) AND (length("NO_CANDIDATO") <= 200) AND (COALESCE(length("CO_CANDIDATO"), 0) <= 60) AND (COALESCE(length("DS_MODALIDADE"), 0) <= 300) AND (COALESCE(length("NO_CARGO"), 0) <= 400) AND (COALESCE(length("DS_LINK_PLANILHA"), 0) <= 500))),
    CONSTRAINT "CK_ENTREVISTA_TPLIGACAO" CHECK (((("CO_ANALISE_CURRICULAR" IS NULL) AND ("TP_LIGACAO_ANALISE" IS NULL)) OR (("CO_ANALISE_CURRICULAR" IS NOT NULL) AND ("TP_LIGACAO_ANALISE" = ANY (ARRAY['codigo'::text, 'nome'::text]))))),
    CONSTRAINT "CK_ENTREVISTA_TPORIGEM" CHECK (("TP_ORIGEM" = ANY (ARRAY['planilha'::text, 'sistema'::text]))),
    CONSTRAINT "CK_ENTREVISTA_TPPARECER" CHECK (("TP_PARECER" = ANY (ARRAY['APTO'::text, 'INAPTO'::text, 'SEM_PARECER'::text])))
);

--
-- Name: TABLE "TB_ENTREVISTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_ENTREVISTA" IS 'Candidato entrevistado numa vaga de um edital (aba Entrevistas). Na fase 1 vem da planilha "[dash] entrevistados" (TP_ORIGEM planilha); liga ao edital e à análise curricular do candidato.';

--
-- Name: COLUMN "TB_ENTREVISTA"."CO_ENTREVISTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."CO_ENTREVISTA" IS 'Identificador da entrevista.';

--
-- Name: COLUMN "TB_ENTREVISTA"."CO_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."CO_AREA" IS 'Área (TB_AREA) de onde veio a carga.';

--
-- Name: COLUMN "TB_ENTREVISTA"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id), achado pelo número do edital + área (desempate pela unidade). Nulo: edital não cadastrado.';

--
-- Name: COLUMN "TB_ENTREVISTA"."CO_ANALISE_CURRICULAR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."CO_ANALISE_CURRICULAR" IS 'Análise curricular do candidato na vaga (TB_ANALISE_CURRICULAR.id). Nula: candidato não achado nas análises.';

--
-- Name: COLUMN "TB_ENTREVISTA"."TP_LIGACAO_ANALISE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."TP_LIGACAO_ANALISE" IS 'Como a análise foi achada: codigo (código do candidato + vaga) ou nome (nome sem acento + vaga).';

--
-- Name: COLUMN "TB_ENTREVISTA"."NO_UNIDADE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."NO_UNIDADE" IS 'Unidade (DSEI) como veio da planilha.';

--
-- Name: COLUMN "TB_ENTREVISTA"."DS_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."DS_EDITAL" IS 'Edital como veio da planilha (ex.: 39/2026 (sanitarista)).';

--
-- Name: COLUMN "TB_ENTREVISTA"."CO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."CO_VAGA" IS 'Código da vaga.';

--
-- Name: COLUMN "TB_ENTREVISTA"."NO_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."NO_CANDIDATO" IS 'Nome do candidato como veio da planilha.';

--
-- Name: COLUMN "TB_ENTREVISTA"."CO_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."CO_CANDIDATO" IS 'Código do candidato (o id_origem da análise curricular).';

--
-- Name: COLUMN "TB_ENTREVISTA"."DS_MODALIDADE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."DS_MODALIDADE" IS 'Modalidade de concorrência (várias separadas por " / ").';

--
-- Name: COLUMN "TB_ENTREVISTA"."NO_CARGO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."NO_CARGO" IS 'Cargo da vaga como veio da planilha.';

--
-- Name: COLUMN "TB_ENTREVISTA"."VL_NOTA_TOTAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ENTREVISTA"."VL_NOTA_TOTAL" IS 'Nota total da entrevista (soma das médias dos critérios; máximo 20 no roteiro da Saúde Indígena).';

