    CONSTRAINT "CK_ENTREVISTAAVALIADOR_TAMANHOS" CHECK (((length("NO_AVALIADOR") >= 2) AND (length("NO_AVALIADOR") <= 150) AND ((length("NO_ORIGEM") >= 2) AND (length("NO_ORIGEM") <= 80)) AND (("NU_BANCA" >= 1) AND ("NU_BANCA" <= 20))))
);

