--

COMMENT ON COLUMN public."TB_HORA_NASCIMENTO_CANDIDATO"."DT_ATUALIZACAO" IS 'Quando foi informada por último.';

--
-- Name: TB_ITEM_AJUSTE_PONTUACAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ITEM_AJUSTE_PONTUACAO" (
    "CO_AJUSTE_PONTUACAO" uuid NOT NULL,
    "CO_ITEM" character varying(20) NOT NULL,
    "NU_ORDEM" smallint NOT NULL,
    "VL_ANTERIOR" numeric,
    "VL_NOVO" numeric NOT NULL,
    "DS_JUSTIFICATIVA" text,
    CONSTRAINT "CK_ITEMAJUSTEPONT_COITEM" CHECK ((("CO_ITEM")::text ~ '^(ETNICO|FORMACAO|CURSOS|EXPERIENCIA|DOCUMENTAL|ENTREVISTA|ART|COMPETENCIA_([1-9]|1[0-9]|20))$'::text)),
    CONSTRAINT "CK_ITEMAJUSTEPONT_JUSTIFICATIVA" CHECK ((COALESCE(length("DS_JUSTIFICATIVA"), 0) <= 2000)),
    CONSTRAINT "CK_ITEMAJUSTEPONT_NUORDEM" CHECK ((("NU_ORDEM" >= 1) AND ("NU_ORDEM" <= 40))),
    CONSTRAINT "CK_ITEMAJUSTEPONT_VALORES" CHECK ((("VL_NOVO" >= (0)::numeric) AND ("VL_NOVO" <= (1000)::numeric) AND (("VL_ANTERIOR" IS NULL) OR (("VL_ANTERIOR" >= (0)::numeric) AND ("VL_ANTERIOR" <= (1000)::numeric)))))
);

--
-- Name: TABLE "TB_ITEM_AJUSTE_PONTUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_ITEM_AJUSTE_PONTUACAO" IS 'Componentes da nota ajustados numa versão do ajuste do recurso: valor de antes (o da análise/entrevista, com os ajustes aprovados de outros recursos), valor novo e justificativa. Não mudam depois de gravados.';

--
-- Name: COLUMN "TB_ITEM_AJUSTE_PONTUACAO"."CO_AJUSTE_PONTUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ITEM_AJUSTE_PONTUACAO"."CO_AJUSTE_PONTUACAO" IS 'Versão do ajuste (TB_AJUSTE_PONTUACAO_RECURSO).';

--
-- Name: COLUMN "TB_ITEM_AJUSTE_PONTUACAO"."CO_ITEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ITEM_AJUSTE_PONTUACAO"."CO_ITEM" IS 'Componente: ETNICO, FORMACAO, CURSOS, EXPERIENCIA (parciais da documental), DOCUMENTAL (nota documental), ENTREVISTA (nota da entrevista), COMPETENCIA_n (competência n da entrevista) ou ART.';

--
-- Name: COLUMN "TB_ITEM_AJUSTE_PONTUACAO"."NU_ORDEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ITEM_AJUSTE_PONTUACAO"."NU_ORDEM" IS 'Ordem do componente na tela.';

--
-- Name: COLUMN "TB_ITEM_AJUSTE_PONTUACAO"."VL_ANTERIOR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ITEM_AJUSTE_PONTUACAO"."VL_ANTERIOR" IS 'Valor do componente quando o ajuste foi proposto (nulo se a análise não tinha).';

--
-- Name: COLUMN "TB_ITEM_AJUSTE_PONTUACAO"."VL_NOVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ITEM_AJUSTE_PONTUACAO"."VL_NOVO" IS 'Valor do componente depois do recurso (0 a 1000). Substitui o da análise na Classificação quando o ajuste é aprovado.';

--
-- Name: COLUMN "TB_ITEM_AJUSTE_PONTUACAO"."DS_JUSTIFICATIVA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ITEM_AJUSTE_PONTUACAO"."DS_JUSTIFICATIVA" IS 'Justificativa do item (até 2.000 caracteres).';

--
-- Name: CONSTRAINT "CK_ITEMAJUSTEPONT_COITEM" ON "TB_ITEM_AJUSTE_PONTUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ITEMAJUSTEPONT_COITEM" ON public."TB_ITEM_AJUSTE_PONTUACAO" IS 'Componentes da nota conhecidos.';

--
-- Name: CONSTRAINT "CK_ITEMAJUSTEPONT_JUSTIFICATIVA" ON "TB_ITEM_AJUSTE_PONTUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ITEMAJUSTEPONT_JUSTIFICATIVA" ON public."TB_ITEM_AJUSTE_PONTUACAO" IS 'Justificativa do item até 2.000 caracteres.';

--
-- Name: CONSTRAINT "CK_ITEMAJUSTEPONT_NUORDEM" ON "TB_ITEM_AJUSTE_PONTUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ITEMAJUSTEPONT_NUORDEM" ON public."TB_ITEM_AJUSTE_PONTUACAO" IS 'Ordem de 1 a 40.';

--
-- Name: CONSTRAINT "CK_ITEMAJUSTEPONT_VALORES" ON "TB_ITEM_AJUSTE_PONTUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ITEMAJUSTEPONT_VALORES" ON public."TB_ITEM_AJUSTE_PONTUACAO" IS 'Valores entre 0 e 1000.';

--
-- Name: TB_LEITURA_ARQUIVO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_LEITURA_ARQUIVO" (
    "CO_LEITURA_ARQUIVO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_EMPREGARE_RESPOSTA" uuid NOT NULL,
    "CO_PERGUNTA_EMPREGARE" character varying(20) NOT NULL,
    "NU_ARQUIVO" smallint NOT NULL,
    "TP_SITUACAO" character varying(15) NOT NULL,
    "TP_METODO" character varying(5),
    "TP_FORMATO" character varying(6),
    "TP_DOCUMENTO" character varying(30),
    "QT_PAGINA" smallint,
    "VL_CONFIANCA_OCR" numeric(4,3),
    "ST_NOME_CONFERE" character varying(1),
    "ST_CPF_CONFERE" character varying(1),
    "DS_ITEM" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "DS_ALERTA" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "DS_RESUMO" character varying(200),
    "CO_ERRO" character varying(60),
    "DS_HASH_ARQUIVO" character varying(64),
    "NU_VERSAO_EXTRATOR" character varying(20) NOT NULL,
    "CO_EXECUCAO" character varying(60),
    "DT_LEITURA" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_LEITARQ_COERRO" CHECK ((("CO_ERRO" IS NULL) OR (("CO_ERRO")::text ~ '^[a-z0-9_]{1,60}$'::text))),
    CONSTRAINT "CK_LEITARQ_COEXECUCAO" CHECK ((("CO_EXECUCAO" IS NULL) OR (("CO_EXECUCAO")::text ~ '^[A-Za-z0-9_.:-]{1,60}$'::text))),
    CONSTRAINT "CK_LEITARQ_COPERGUNTA" CHECK ((("CO_PERGUNTA_EMPREGARE")::text ~ '^[0-9]{1,20}$'::text)),
    CONSTRAINT "CK_LEITARQ_DSALERTA" CHECK (((jsonb_typeof("DS_ALERTA") = 'array'::text) AND (jsonb_array_length("DS_ALERTA") <= 40))),
    CONSTRAINT "CK_LEITARQ_DSHASHARQUIVO" CHECK ((("DS_HASH_ARQUIVO" IS NULL) OR (("DS_HASH_ARQUIVO")::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT "CK_LEITARQ_DSITEM" CHECK (((jsonb_typeof("DS_ITEM") = 'array'::text) AND (jsonb_array_length("DS_ITEM") <= 60))),
    CONSTRAINT "CK_LEITARQ_NUARQUIVO" CHECK ((("NU_ARQUIVO" >= 1) AND ("NU_ARQUIVO" <= 50))),
    CONSTRAINT "CK_LEITARQ_NUVERSAOEXTRATOR" CHECK ((("NU_VERSAO_EXTRATOR")::text ~ '^[0-9A-Za-z._-]{1,20}$'::text)),
    CONSTRAINT "CK_LEITARQ_QTPAGINA" CHECK ((("QT_PAGINA" IS NULL) OR (("QT_PAGINA" >= 0) AND ("QT_PAGINA" <= 10000)))),
    CONSTRAINT "CK_LEITARQ_STCPFCONFERE" CHECK ((("ST_CPF_CONFERE" IS NULL) OR (("ST_CPF_CONFERE")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text])))),
    CONSTRAINT "CK_LEITARQ_STNOMECONFERE" CHECK ((("ST_NOME_CONFERE" IS NULL) OR (("ST_NOME_CONFERE")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text])))),
    CONSTRAINT "CK_LEITARQ_TPDOCUMENTO" CHECK ((("TP_DOCUMENTO" IS NULL) OR (("TP_DOCUMENTO")::text ~ '^[A-Z][A-Z0-9_]{1,29}$'::text))),
    CONSTRAINT "CK_LEITARQ_TPFORMATO" CHECK ((("TP_FORMATO" IS NULL) OR (("TP_FORMATO")::text = ANY (ARRAY[('PDF'::character varying)::text, ('IMAGEM'::character varying)::text, ('DOCX'::character varying)::text, ('TXT'::character varying)::text, ('OUTRO'::character varying)::text])))),
    CONSTRAINT "CK_LEITARQ_TPMETODO" CHECK ((("TP_METODO" IS NULL) OR (("TP_METODO")::text = ANY (ARRAY[('TEXTO'::character varying)::text, ('OCR'::character varying)::text])))),
    CONSTRAINT "CK_LEITARQ_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY (ARRAY[('LIDO'::character varying)::text, ('ILEGIVEL'::character varying)::text, ('ERRO'::character varying)::text, ('NAO_SUPORTADO'::character varying)::text]))),
    CONSTRAINT "CK_LEITARQ_VLCONFIANCAOCR" CHECK ((("VL_CONFIANCA_OCR" IS NULL) OR (("VL_CONFIANCA_OCR" >= (0)::numeric) AND ("VL_CONFIANCA_OCR" <= (1)::numeric))))
);

--
-- Name: TABLE "TB_LEITURA_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_LEITURA_ARQUIVO" IS 'Leitura automática dos anexos do questionário da Empregare pelo robô (Python, leitura_de_arquivos): por anexo, a situação, o método, os itens achados (cursos, títulos, vínculos, identidade, registro) e os alertas, para AJUDAR o avaliador na ficha da Avaliação documental — quem decide é ele. Não guarda o texto do documento, o nome nem o CPF lidos (só se conferem). Só a RPC da ficha devolve.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."CO_LEITURA_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."CO_LEITURA_ARQUIVO" IS 'Identificador da leitura.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."CO_EMPREGARE_RESPOSTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."CO_EMPREGARE_RESPOSTA" IS 'Resposta do questionário a que o anexo pertence (TB_EMPREGARE_RESPOSTA). O anexo é (resposta, pergunta, arquivo): TB_EMPREGARE_ANEXO é regravada a cada captura e muda de id.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."CO_PERGUNTA_EMPREGARE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."CO_PERGUNTA_EMPREGARE" IS 'PerguntaID da Empregare do anexo (como em TB_EMPREGARE_ANEXO).';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."NU_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."NU_ARQUIVO" IS 'Posição do arquivo na pergunta (1 a 50, como em TB_EMPREGARE_ANEXO).';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."TP_SITUACAO" IS 'LIDO, ILEGIVEL (texto e OCR não trouxeram o bastante), ERRO (download ou arquivo corrompido: o robô tenta de novo) ou NAO_SUPORTADO (ZIP, RAR, DOC antigo…).';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."TP_METODO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."TP_METODO" IS 'TEXTO (texto selecionável do PDF, DOCX, TXT) ou OCR (Tesseract em português, PDF escaneado e imagem).';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."TP_FORMATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."TP_FORMATO" IS 'Formato real do arquivo, pelos primeiros bytes: PDF, IMAGEM, DOCX, TXT ou OUTRO.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."TP_DOCUMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."TP_DOCUMENTO" IS 'Tipo achado: CERTIFICADO, DIPLOMA, CTPS, DECLARACAO, CONTRATO, CERTIDAO, HOLERITE, RG, CIN, CNH, PASSAPORTE, REGISTRO_<CONSELHO>, OUTRO.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."QT_PAGINA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."QT_PAGINA" IS 'Páginas do arquivo.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."VL_CONFIANCA_OCR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."VL_CONFIANCA_OCR" IS 'Confiança média do OCR (0 a 1); null sem OCR.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."ST_NOME_CONFERE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."ST_NOME_CONFERE" IS 'S se o nome do candidato aparece no documento, N se não aparece, null se não deu para saber.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."ST_CPF_CONFERE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."ST_CPF_CONFERE" IS 'S se um CPF do documento é o do candidato, N se há CPF e nenhum é, null sem CPF no documento. O número nunca é guardado.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."DS_ITEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."DS_ITEM" IS 'Itens achados: [{tipo CURSO|TITULO|VINCULO|IDENTIDADE|REGISTRO, campos do tipo (curso, horas, instituicao, conclusao; titulo, curso, instituicao, data; empregador, cargo, inicio, fim, atual, carga_semanal, dias, documento; documento; conselho, ativo, validade), pagina, nome_confere, alertas [{codigo, texto}]}].';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."DS_ALERTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."DS_ALERTA" IS 'Alertas do arquivo inteiro: [{codigo, texto}] (DOCUMENTO_ILEGIVEL, NOME_DIVERGENTE, CPF_DIVERGENTE, NADA_ENCONTRADO, PAGINAS_NAO_LIDAS, LEITURA_DUVIDOSA).';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."DS_RESUMO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."DS_RESUMO" IS 'Uma linha para a ficha ("3 certificados · 145 h, 60 h, 40 h · nome confere").';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."CO_ERRO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."CO_ERRO" IS 'Código curto do erro (situação ERRO), sem dado pessoal.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."DS_HASH_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."DS_HASH_ARQUIVO" IS 'sha256 do arquivo lido (o arquivo não é guardado; o hash mostra se mudou).';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."NU_VERSAO_EXTRATOR"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."NU_VERSAO_EXTRATOR" IS 'Versão do extrator (VERSAO_DO_EXTRATOR): versão nova relê.';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."CO_EXECUCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."CO_EXECUCAO" IS 'Execução do robô que leu (GitHub Actions).';

--
-- Name: COLUMN "TB_LEITURA_ARQUIVO"."DT_LEITURA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LEITURA_ARQUIVO"."DT_LEITURA" IS 'Quando foi lido.';

--
-- Name: CONSTRAINT "CK_LEITARQ_DSALERTA" ON "TB_LEITURA_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LEITARQ_DSALERTA" ON public."TB_LEITURA_ARQUIVO" IS 'Alertas numa lista de até 40.';

--
-- Name: CONSTRAINT "CK_LEITARQ_DSITEM" ON "TB_LEITURA_ARQUIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LEITARQ_DSITEM" ON public."TB_LEITURA_ARQUIVO" IS 'Itens numa lista de até 60.';

--
-- Name: TB_LISTA_APROVADO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_LISTA_APROVADO" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    edital_id text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    vigente boolean DEFAULT true NOT NULL,
    arquivo_nome text NOT NULL,
    arquivo_path text NOT NULL,
    importado_por uuid NOT NULL,
    importado_em timestamp with time zone DEFAULT now() NOT NULL,
    substituido_por uuid,
    substituido_em timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    "DS_EMAIL_IMPORTACAO" character varying(320),
    "NO_USUARIO_IMPORTACAO" character varying(255),
    "DS_EMAIL_SUBSTITUICAO" character varying(320),
    "NO_USUARIO_SUBSTITUICAO" character varying(255),
    "TP_ORIGEM" character varying(15) DEFAULT 'XLSX'::character varying NOT NULL,
    "CO_LISTA_CLASSIFICACAO" uuid,
    CONSTRAINT "CK_LISTAAPROVADO_ORIGEM" CHECK (((("TP_ORIGEM")::text = 'CLASSIFICACAO'::text) = ("CO_LISTA_CLASSIFICACAO" IS NOT NULL))),
    CONSTRAINT "CK_LISTAAPROVADO_TPORIGEM" CHECK ((("TP_ORIGEM")::text = ANY (ARRAY[('XLSX'::character varying)::text, ('CLASSIFICACAO'::character varying)::text])))
);

--
-- Name: COLUMN "TB_LISTA_APROVADO"."DS_EMAIL_IMPORTACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_APROVADO"."DS_EMAIL_IMPORTACAO" IS 'E-mail de quem importou a lista, copiado da sessao no momento da importacao. Complementa importado_por (UUID), que perde o sentido se o usuario for apagado.';

--
-- Name: COLUMN "TB_LISTA_APROVADO"."NO_USUARIO_IMPORTACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_APROVADO"."NO_USUARIO_IMPORTACAO" IS 'Nome de quem importou a lista, copiado de TB_PERFIL_USUARIO no momento da importacao.';

--
-- Name: COLUMN "TB_LISTA_APROVADO"."DS_EMAIL_SUBSTITUICAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_APROVADO"."DS_EMAIL_SUBSTITUICAO" IS 'E-mail de quem substituiu ou removeu a lista, copiado da sessao no momento da acao. Complementa substituido_por (UUID).';

--
-- Name: COLUMN "TB_LISTA_APROVADO"."NO_USUARIO_SUBSTITUICAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_APROVADO"."NO_USUARIO_SUBSTITUICAO" IS 'Nome de quem substituiu ou removeu a lista, copiado de TB_PERFIL_USUARIO no momento da acao.';

--
-- Name: COLUMN "TB_LISTA_APROVADO"."TP_ORIGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_APROVADO"."TP_ORIGEM" IS 'De onde veio a lista: XLSX (planilha importada, posição e nota digitadas) ou CLASSIFICACAO (resultado final publicado da aba Classificação).';

--
-- Name: COLUMN "TB_LISTA_APROVADO"."CO_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_APROVADO"."CO_LISTA_CLASSIFICACAO" IS 'Lista FINAL da Classificação publicada como esta lista (TB_LISTA_CLASSIFICACAO); nula nas listas de planilha.';

--
-- Name: CONSTRAINT "CK_LISTAAPROVADO_ORIGEM" ON "TB_LISTA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LISTAAPROVADO_ORIGEM" ON public."TB_LISTA_APROVADO" IS 'Lista da Classificação tem a lista de classificação; a de planilha, não.';

--
-- Name: CONSTRAINT "CK_LISTAAPROVADO_TPORIGEM" ON "TB_LISTA_APROVADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LISTAAPROVADO_TPORIGEM" ON public."TB_LISTA_APROVADO" IS 'Origens válidas.';

--
-- Name: TB_LISTA_CLASSIFICACAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_LISTA_CLASSIFICACAO" (
    "CO_LISTA_CLASSIFICACAO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "TP_LISTA" character varying(20) NOT NULL,
    "CO_REGRA_CLASSIFICACAO" uuid NOT NULL,
    "NU_VERSAO_REGRA" integer NOT NULL,
    "DS_RESULTADO" jsonb NOT NULL,
    "DS_HASH" character varying(64) NOT NULL,
    "QT_ELEGIVEL" integer DEFAULT 0 NOT NULL,
    "QT_ELIMINADO" integer DEFAULT 0 NOT NULL,
    "QT_AVISO" integer DEFAULT 0 NOT NULL,
    "QT_PENDENCIA" integer DEFAULT 0 NOT NULL,
    "CO_USUARIO" uuid NOT NULL,
    "DT_GERACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "ST_PUBLICADA" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "CO_USUARIO_PUBLICACAO" uuid,
    "DT_PUBLICACAO" timestamp with time zone,
    CONSTRAINT "CK_LISTACLASSIF_DSHASH" CHECK ((("DS_HASH")::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT "CK_LISTACLASSIF_PUBLICACAO" CHECK ((((("ST_PUBLICADA")::text = 'S'::text) = ("DT_PUBLICACAO" IS NOT NULL)) AND (("DT_PUBLICACAO" IS NULL) = ("CO_USUARIO_PUBLICACAO" IS NULL)) AND ((("ST_PUBLICADA")::text = 'N'::text) OR ("QT_PENDENCIA" = 0)))),
    CONSTRAINT "CK_LISTACLASSIF_QUANTIDADES" CHECK ((("QT_ELEGIVEL" >= 0) AND ("QT_ELIMINADO" >= 0) AND ("QT_AVISO" >= 0) AND ("QT_PENDENCIA" >= 0))),
    CONSTRAINT "CK_LISTACLASSIF_RESULTADO" CHECK ((jsonb_typeof("DS_RESULTADO") = 'object'::text)),
    CONSTRAINT "CK_LISTACLASSIF_STPUBLICADA" CHECK ((("ST_PUBLICADA")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_LISTACLASSIF_TPLISTA" CHECK ((("TP_LISTA")::text = ANY (ARRAY[('PROVISORIA'::character varying)::text, ('LOTE'::character varying)::text, ('PRELIMINAR'::character varying)::text, ('CONVOCACAO'::character varying)::text, ('ENTREVISTA'::character varying)::text, ('FINAL'::character varying)::text])))
);

--
-- Name: TABLE "TB_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_LISTA_CLASSIFICACAO" IS 'Cada lista de classificação gerada (preliminar, convocação para entrevista, resultado final): versão da regra usada, quem, quando, o retrato da lista e o hash. Nada é apagado; publicar marca a lista.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."CO_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."CO_LISTA_CLASSIFICACAO" IS 'Identificador da geração.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id).';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."TP_LISTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."TP_LISTA" IS 'PROVISORIA (Lista Geral de Classificação Provisória por ART) e LOTE (Lote de Convocação), registradas a partir de TB_PRE_CLASSIFICACAO; PRELIMINAR (avaliação documental), CONVOCACAO (para entrevista), ENTREVISTA (resultado da entrevista) ou FINAL (resultado final).';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."CO_REGRA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."CO_REGRA_CLASSIFICACAO" IS 'Regra usada.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."NU_VERSAO_REGRA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."NU_VERSAO_REGRA" IS 'Versão da regra usada na geração.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."DS_RESULTADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."DS_RESULTADO" IS 'Retrato da lista: por vaga, as listas (geral e por modalidade) com posição, nome e nota, os eliminados com motivo, os avisos e o rodapé. Só nome — sem CPF, nascimento ou contato.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."DS_HASH"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."DS_HASH" IS 'SHA-256 (hex) do CONTEÚDO de DS_RESULTADO, calculado no banco na gravação (FC_HASH_RETRATO_CLASSIFICACAO: números sem zeros à direita, 20261024130000; antes, sha256 de DS_RESULTADO::text).';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."QT_ELEGIVEL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."QT_ELEGIVEL" IS 'Candidatos nas listas.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."QT_ELIMINADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."QT_ELIMINADO" IS 'Candidatos eliminados ou fora da lista, com motivo.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."QT_AVISO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."QT_AVISO" IS 'Avisos da geração (dados faltando, entrevista sem análise…).';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."QT_PENDENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."QT_PENDENCIA" IS 'Empates que esperavam sorteio ou decisão na geração. Com pendência, não publica.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."CO_USUARIO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."CO_USUARIO" IS 'Quem gerou (auth.users.id).';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."DT_GERACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."DT_GERACAO" IS 'Quando gerou.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."ST_PUBLICADA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."ST_PUBLICADA" IS 'S: marcada como publicada.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."CO_USUARIO_PUBLICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."CO_USUARIO_PUBLICACAO" IS 'Quem marcou como publicada.';

--
-- Name: COLUMN "TB_LISTA_CLASSIFICACAO"."DT_PUBLICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LISTA_CLASSIFICACAO"."DT_PUBLICACAO" IS 'Quando foi marcada como publicada.';

--
-- Name: CONSTRAINT "CK_LISTACLASSIF_DSHASH" ON "TB_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LISTACLASSIF_DSHASH" ON public."TB_LISTA_CLASSIFICACAO" IS 'SHA-256 em hexadecimal minúsculo.';

--
-- Name: CONSTRAINT "CK_LISTACLASSIF_PUBLICACAO" ON "TB_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LISTACLASSIF_PUBLICACAO" ON public."TB_LISTA_CLASSIFICACAO" IS 'Publicada tem quando e quem; lista com empate pendente não é publicada.';

--
-- Name: CONSTRAINT "CK_LISTACLASSIF_QUANTIDADES" ON "TB_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LISTACLASSIF_QUANTIDADES" ON public."TB_LISTA_CLASSIFICACAO" IS 'Quantidades não negativas.';

--
-- Name: CONSTRAINT "CK_LISTACLASSIF_RESULTADO" ON "TB_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LISTACLASSIF_RESULTADO" ON public."TB_LISTA_CLASSIFICACAO" IS 'Retrato é um objeto json.';

--
-- Name: CONSTRAINT "CK_LISTACLASSIF_STPUBLICADA" ON "TB_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LISTACLASSIF_STPUBLICADA" ON public."TB_LISTA_CLASSIFICACAO" IS 'Flag S/N.';

--
-- Name: CONSTRAINT "CK_LISTACLASSIF_TPLISTA" ON "TB_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_LISTACLASSIF_TPLISTA" ON public."TB_LISTA_CLASSIFICACAO" IS 'Tipos de lista válidos: PROVISORIA (por ART, item 8.3.1) e LOTE (lote de convocação, item 8.4), vindos da pré-classificação; PRELIMINAR, CONVOCACAO, ENTREVISTA e FINAL, do motor da Classificação.';

--
-- Name: TB_LOCAL_VAGA_EDITAL; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_LOCAL_VAGA_EDITAL" (
    "CO_LOCAL_VAGA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_MUNICIPIO_IBGE" integer,
    "NO_MUNICIPIO" character varying(100),
    "SG_UF" character varying(2) NOT NULL,
    "NO_CARGO" character varying(300),
    "NO_LOTACAO" character varying(300),
    "QT_VAGA" integer,
    "ST_CADASTRO_RESERVA" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "TP_ORIGEM" character varying(10) DEFAULT 'PDF'::character varying NOT NULL,
    "DS_ARQUIVO_ORIGEM" character varying(500),
    "DS_PAGINA_ORIGEM" character varying(100),
    "DS_OBSERVACAO" character varying(300),
    "ST_REGISTRO_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_DESATIVACAO" timestamp with time zone,
    CONSTRAINT "CK_LOCALVAGA_MUNICIPIO" CHECK ((("CO_MUNICIPIO_IBGE" >= 1100000) AND ("CO_MUNICIPIO_IBGE" <= 5399999))),
    CONSTRAINT "CK_LOCALVAGA_MUNICIPIOUF" CHECK ((("CO_MUNICIPIO_IBGE" IS NULL) OR (("SG_UF")::text =
CASE ("CO_MUNICIPIO_IBGE" / 100000)
    WHEN 11 THEN 'RO'::text
    WHEN 12 THEN 'AC'::text
    WHEN 13 THEN 'AM'::text
    WHEN 14 THEN 'RR'::text
    WHEN 15 THEN 'PA'::text
    WHEN 16 THEN 'AP'::text
    WHEN 17 THEN 'TO'::text
    WHEN 21 THEN 'MA'::text
    WHEN 22 THEN 'PI'::text
    WHEN 23 THEN 'CE'::text
    WHEN 24 THEN 'RN'::text
    WHEN 25 THEN 'PB'::text
    WHEN 26 THEN 'PE'::text
    WHEN 27 THEN 'AL'::text
    WHEN 28 THEN 'SE'::text
    WHEN 29 THEN 'BA'::text
    WHEN 31 THEN 'MG'::text
    WHEN 32 THEN 'ES'::text
    WHEN 33 THEN 'RJ'::text
    WHEN 35 THEN 'SP'::text
    WHEN 41 THEN 'PR'::text
    WHEN 42 THEN 'SC'::text
    WHEN 43 THEN 'RS'::text
    WHEN 50 THEN 'MS'::text
    WHEN 51 THEN 'MT'::text
    WHEN 52 THEN 'GO'::text
    WHEN 53 THEN 'DF'::text
    ELSE NULL::text
END))),
    CONSTRAINT "CK_LOCALVAGA_NOMUNICIPIO" CHECK ((("CO_MUNICIPIO_IBGE" IS NULL) = ("NO_MUNICIPIO" IS NULL))),
    CONSTRAINT "CK_LOCALVAGA_QT" CHECK ((("QT_VAGA" >= 0) AND ("QT_VAGA" <= 9999))),
    CONSTRAINT "CK_LOCALVAGA_STATIVO" CHECK ((("ST_REGISTRO_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_LOCALVAGA_STCR" CHECK ((("ST_CADASTRO_RESERVA")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_LOCALVAGA_TPORIGEM" CHECK ((("TP_ORIGEM")::text = ANY (ARRAY[('PDF'::character varying)::text, ('NOME_VAGA'::character varying)::text, ('MANUAL'::character varying)::text]))),
    CONSTRAINT "CK_LOCALVAGA_UF" CHECK ((("SG_UF")::text = ANY (ARRAY[('RO'::character varying)::text, ('AC'::character varying)::text, ('AM'::character varying)::text, ('RR'::character varying)::text, ('PA'::character varying)::text, ('AP'::character varying)::text, ('TO'::character varying)::text, ('MA'::character varying)::text, ('PI'::character varying)::text, ('CE'::character varying)::text, ('RN'::character varying)::text, ('PB'::character varying)::text, ('PE'::character varying)::text, ('AL'::character varying)::text, ('SE'::character varying)::text, ('BA'::character varying)::text, ('MG'::character varying)::text, ('ES'::character varying)::text, ('RJ'::character varying)::text, ('SP'::character varying)::text, ('PR'::character varying)::text, ('SC'::character varying)::text, ('RS'::character varying)::text, ('MS'::character varying)::text, ('MT'::character varying)::text, ('GO'::character varying)::text, ('DF'::character varying)::text])))
);

--
-- Name: TABLE "TB_LOCAL_VAGA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_LOCAL_VAGA_EDITAL" IS 'Onde ficam as vagas de cada edital (município do IBGE ou só a UF), com a prova no PDF. Alimenta o mapa da Visão geral de Projetos.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."CO_LOCAL_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."CO_LOCAL_VAGA" IS 'Identificador da linha.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA); o projeto é a unidade dele.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."CO_MUNICIPIO_IBGE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."CO_MUNICIPIO_IBGE" IS 'Código do município no IBGE (7 dígitos); nulo quando o edital só diz a UF.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."NO_MUNICIPIO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."NO_MUNICIPIO" IS 'Nome do município como no IBGE ("São Luís"), mesmo que o edital escreva diferente.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."SG_UF"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."SG_UF" IS 'Sigla da UF.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."NO_CARGO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."NO_CARGO" IS 'Cargo como publicado; nulo quando a linha vale para todos os cargos do lugar.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."NO_LOTACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."NO_LOTACAO" IS 'Lotação como publicada ("Escritório Distrital Yanomami", "UBS móvel Irati/PR").';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."QT_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."QT_VAGA" IS 'Vagas de provimento imediato publicadas; nulo = o edital não informa ou só há cadastro reserva.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."ST_CADASTRO_RESERVA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."ST_CADASTRO_RESERVA" IS 'S: o edital prevê cadastro reserva (CR) para o lugar.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."TP_ORIGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."TP_ORIGEM" IS 'PDF (lido do edital), NOME_VAGA (lido do nome da vaga nas análises) ou MANUAL.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."DS_ARQUIVO_ORIGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."DS_ARQUIVO_ORIGEM" IS 'Endereço do PDF de onde a linha foi lida.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."DS_PAGINA_ORIGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."DS_PAGINA_ORIGEM" IS 'Página(s) e item do PDF que provam a linha ("4-6 (quadro do item 4.1)").';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."DS_OBSERVACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."DS_OBSERVACAO" IS 'Nota de leitura (ex.: "o edital só diz a UF").';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."ST_REGISTRO_ATIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."ST_REGISTRO_ATIVO" IS 'S: vigente. N: desativada (exclusão lógica).';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."DT_CRIACAO" IS 'Quando a linha foi gravada.';

--
-- Name: COLUMN "TB_LOCAL_VAGA_EDITAL"."DT_DESATIVACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_LOCAL_VAGA_EDITAL"."DT_DESATIVACAO" IS 'Quando a linha foi desativada.';

--
-- Name: TB_MODELO_CARTA_CONVOCACAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_MODELO_CARTA_CONVOCACAO" (
    "CO_MODELO_CARTA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_AREA" text NOT NULL,
    "CO_MONITORAMENTO" uuid,
    "NO_MODELO" character varying(120) NOT NULL,
    "NU_VERSAO_VIGENTE" integer NOT NULL,
    "ST_ATIVO" boolean DEFAULT true NOT NULL,
    "DS_MOTIVO_SITUACAO" character varying(500),
    "CO_USUARIO_CRIACAO" uuid,
    "CO_USUARIO_ATUALIZACAO" uuid,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_MODELOCARTA_MOTIVO" CHECK ((("DS_MOTIVO_SITUACAO" IS NULL) OR ((length(("DS_MOTIVO_SITUACAO")::text) >= 3) AND (length(("DS_MOTIVO_SITUACAO")::text) <= 500)))),
    CONSTRAINT "CK_MODELOCARTA_NOMODELO" CHECK (((length(btrim(("NO_MODELO")::text)) >= 3) AND (length(btrim(("NO_MODELO")::text)) <= 120))),
    CONSTRAINT "CK_MODELOCARTA_NUVERSAO" CHECK (("NU_VERSAO_VIGENTE" >= 1))
);

--
-- Name: TABLE "TB_MODELO_CARTA_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_MODELO_CARTA_CONVOCACAO" IS 'Modelo da carta de convocação para contratação, da área (CO_MONITORAMENTO nulo) ou de um edital. O texto fica em cada versão (TH_MODELO_CARTA_CONVOCACAO); aqui, a versão vigente e se está ativo. Nada se apaga: inativa-se.';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."CO_MODELO_CARTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."CO_MODELO_CARTA" IS 'Identificador do modelo.';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."CO_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."CO_AREA" IS 'Área dona do modelo (TB_AREA).';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."CO_MONITORAMENTO" IS 'Edital do modelo (TB_MONITORAMENTO_INDIGENA.id); nulo = vale para todos os editais da área.';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."NO_MODELO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."NO_MODELO" IS 'Nome do modelo (3 a 120 caracteres), único entre os ativos da área/edital.';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."NU_VERSAO_VIGENTE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."NU_VERSAO_VIGENTE" IS 'Versão vigente (TH_MODELO_CARTA_CONVOCACAO.NU_VERSAO). Salvar cria a próxima.';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."ST_ATIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."ST_ATIVO" IS 'Ativo: aparece para emitir. Inativo continua no histórico das cartas.';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."DS_MOTIVO_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."DS_MOTIVO_SITUACAO" IS 'Por que foi inativado ou reativado (3 a 500 caracteres).';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."CO_USUARIO_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."CO_USUARIO_CRIACAO" IS 'Quem criou (auth.users.id).';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."CO_USUARIO_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."CO_USUARIO_ATUALIZACAO" IS 'Quem salvou a última versão ou mudou a situação (auth.users.id).';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."DT_CRIACAO" IS 'Primeira versão.';

--
-- Name: COLUMN "TB_MODELO_CARTA_CONVOCACAO"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CARTA_CONVOCACAO"."DT_ATUALIZACAO" IS 'Última versão salva ou mudança de situação.';

--
-- Name: CONSTRAINT "CK_MODELOCARTA_MOTIVO" ON "TB_MODELO_CARTA_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELOCARTA_MOTIVO" ON public."TB_MODELO_CARTA_CONVOCACAO" IS 'Motivo da situação entre 3 e 500 caracteres.';

--
-- Name: CONSTRAINT "CK_MODELOCARTA_NOMODELO" ON "TB_MODELO_CARTA_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELOCARTA_NOMODELO" ON public."TB_MODELO_CARTA_CONVOCACAO" IS 'Nome entre 3 e 120 caracteres.';

--
-- Name: CONSTRAINT "CK_MODELOCARTA_NUVERSAO" ON "TB_MODELO_CARTA_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELOCARTA_NUVERSAO" ON public."TB_MODELO_CARTA_CONVOCACAO" IS 'Versões começam em 1.';

--
-- Name: TB_MODELO_CONVOCACAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_MODELO_CONVOCACAO" (
    "CO_MODELO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "NO_MODELO" text NOT NULL,
    "TP_DISTRIBUICAO" character varying(20) DEFAULT 'PROPORCIONAL'::character varying NOT NULL,
    "TP_COTA_MULTIPLA" character varying(30) DEFAULT 'MAIOR_PERCENTUAL'::character varying NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_MODELO_CONVOC_DISTRIB" CHECK ((("TP_DISTRIBUICAO")::text = ANY (ARRAY[('PROPORCIONAL'::character varying)::text, ('POSICAO_FIXA'::character varying)::text, ('SERIE_MGI'::character varying)::text]))),
    CONSTRAINT "CK_MODELO_CONVOC_MULTIPLA" CHECK ((("TP_COTA_MULTIPLA")::text = ANY (ARRAY[('MAIOR_PERCENTUAL'::character varying)::text, ('ACUMULA_COM_ACUMULAVEL'::character varying)::text, ('TODAS'::character varying)::text]))),
    CONSTRAINT "CK_MODELO_CONVOC_NOME" CHECK ((NULLIF(btrim("NO_MODELO"), ''::text) IS NOT NULL))
);

--
-- Name: TABLE "TB_MODELO_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_MODELO_CONVOCACAO" IS 'Conjunto nomeado de regras de convocacao de um edital, reutilizavel entre editais. O nome identifica a regra (ex.: Lei 15.142/2025 - 25/3/2 e 5% PCD); nao ha campo de descricao separado.';

--
-- Name: COLUMN "TB_MODELO_CONVOCACAO"."CO_MODELO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CONVOCACAO"."CO_MODELO" IS 'Identificador do modelo.';

--
-- Name: COLUMN "TB_MODELO_CONVOCACAO"."NO_MODELO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CONVOCACAO"."NO_MODELO" IS 'Nome do modelo; identifica a regra (ex.: Lei 15.142/2025 - 25/3/2 e 5% PCD).';

--
-- Name: COLUMN "TB_MODELO_CONVOCACAO"."TP_DISTRIBUICAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CONVOCACAO"."TP_DISTRIBUICAO" IS 'PROPORCIONAL espalha as vagas de reserva pela sequencia; POSICAO_FIXA usa as posicoes publicadas no edital; SERIE_MGI segue o simulador de reserva de vagas do MGI (posicoes informadas, senao a cada 100/percentual posicoes).';

--
-- Name: COLUMN "TB_MODELO_CONVOCACAO"."TP_COTA_MULTIPLA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CONVOCACAO"."TP_COTA_MULTIPLA" IS 'O que fazer com quem declara mais de uma reserva: so a de maior percentual, acumular com a categoria acumulavel, ou todas.';

--
-- Name: COLUMN "TB_MODELO_CONVOCACAO"."CO_USUARIO_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CONVOCACAO"."CO_USUARIO_ATUALIZACAO" IS 'Usuário (auth.uid()) da última alteração.';

--
-- Name: COLUMN "TB_MODELO_CONVOCACAO"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CONVOCACAO"."DT_CRIACAO" IS 'Quando o modelo foi criado.';

--
-- Name: COLUMN "TB_MODELO_CONVOCACAO"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_CONVOCACAO"."DT_ATUALIZACAO" IS 'Quando o modelo foi alterado pela última vez.';

--
-- Name: CONSTRAINT "CK_MODELO_CONVOC_DISTRIB" ON "TB_MODELO_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELO_CONVOC_DISTRIB" ON public."TB_MODELO_CONVOCACAO" IS 'Formas de distribuir as vagas de reserva: PROPORCIONAL, POSICAO_FIXA ou SERIE_MGI.';

--
-- Name: TB_MODELO_ESPELHO_NOTA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_MODELO_ESPELHO_NOTA" (
    "CO_MODELO_ESPELHO_NOTA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "NU_VERSAO" integer DEFAULT 1 NOT NULL,
    "DS_TEXTOS" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "CO_USUARIO_CRIACAO" uuid NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_MODELOESPELHO_NUVERSAO" CHECK (("NU_VERSAO" >= 1)),
    CONSTRAINT "CK_MODELOESPELHO_TEXTOS" CHECK (((jsonb_typeof("DS_TEXTOS") = 'object'::text) AND (pg_column_size("DS_TEXTOS") <= 32768)))
);

--
-- Name: TABLE "TB_MODELO_ESPELHO_NOTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_MODELO_ESPELHO_NOTA" IS 'Modelo do espelho de nota da avaliação documental, um por edital: os textos da folha que a coordenação ajusta (título, subtítulo, saudação, abertura, nomes dos quadros, rótulos das notas, "Não se aplica", "Sem observação registrada.", rodapé e se a nota autodeclarada aparece). Só textos: o conteúdo do espelho é da montagem no front. Sem linha = o padrão do código. Cada versão em TH_MODELO_ESPELHO_NOTA. Desde 20261019120000.';

--
-- Name: COLUMN "TB_MODELO_ESPELHO_NOTA"."CO_MODELO_ESPELHO_NOTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_ESPELHO_NOTA"."CO_MODELO_ESPELHO_NOTA" IS 'Identificador do modelo.';

--
-- Name: COLUMN "TB_MODELO_ESPELHO_NOTA"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_ESPELHO_NOTA"."CO_MONITORAMENTO" IS 'Edital do modelo (TB_MONITORAMENTO_INDIGENA.id); um modelo por edital.';

--
-- Name: COLUMN "TB_MODELO_ESPELHO_NOTA"."NU_VERSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_ESPELHO_NOTA"."NU_VERSAO" IS 'Versão vigente (TH_MODELO_ESPELHO_NOTA.NU_VERSAO). Salvar cria a próxima; a tela manda a que abriu (concorrência otimista, PT409).';

--
-- Name: COLUMN "TB_MODELO_ESPELHO_NOTA"."DS_TEXTOS"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_ESPELHO_NOTA"."DS_TEXTOS" IS 'Só os textos que diferem do padrão do código (chaves de FC_VALIDAR_MODELO_ESPELHO_NOTA); {} = o padrão (Restaurar padrão). Até 32 KB.';

--
-- Name: COLUMN "TB_MODELO_ESPELHO_NOTA"."CO_USUARIO_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_ESPELHO_NOTA"."CO_USUARIO_CRIACAO" IS 'Quem salvou a primeira versão (auth.users.id).';

--
-- Name: COLUMN "TB_MODELO_ESPELHO_NOTA"."CO_USUARIO_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_ESPELHO_NOTA"."CO_USUARIO_ATUALIZACAO" IS 'Quem salvou a versão vigente (auth.users.id).';

--
-- Name: COLUMN "TB_MODELO_ESPELHO_NOTA"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_ESPELHO_NOTA"."DT_CRIACAO" IS 'Primeira versão.';

--
-- Name: COLUMN "TB_MODELO_ESPELHO_NOTA"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_ESPELHO_NOTA"."DT_ATUALIZACAO" IS 'Versão vigente.';

--
-- Name: CONSTRAINT "CK_MODELOESPELHO_NUVERSAO" ON "TB_MODELO_ESPELHO_NOTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELOESPELHO_NUVERSAO" ON public."TB_MODELO_ESPELHO_NOTA" IS 'Versões começam em 1.';

--
-- Name: CONSTRAINT "CK_MODELOESPELHO_TEXTOS" ON "TB_MODELO_ESPELHO_NOTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELOESPELHO_TEXTOS" ON public."TB_MODELO_ESPELHO_NOTA" IS 'Os textos são um objeto JSON de até 32 KB (o conteúdo é validado por FC_VALIDAR_MODELO_ESPELHO_NOTA).';

--
-- Name: TB_MODELO_RESPOSTA_RECURSO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_MODELO_RESPOSTA_RECURSO" (
    "CO_MODELO_RESPOSTA" uuid NOT NULL,
    "NU_VERSAO" integer NOT NULL,
    "CO_AREA" text,
    "CO_ORIGEM_RECURSO" text,
    "TP_SITUACAO" text NOT NULL,
    "NO_MODELO" text NOT NULL,
    "DS_CORPO" text NOT NULL,
    "ST_VIGENTE" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DS_MOTIVO_ARQUIVAMENTO" text,
    "DT_ARQUIVAMENTO" timestamp with time zone,
    "CO_USUARIO_ARQUIVAMENTO" uuid,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_CRIACAO" uuid,
    CONSTRAINT "CK_MODELORESPOSTA_ARQUIVAMENTO" CHECK ((((("ST_ATIVO")::text = 'S'::text) = ("DT_ARQUIVAMENTO" IS NULL)) AND (("DT_ARQUIVAMENTO" IS NULL) = ("DS_MOTIVO_ARQUIVAMENTO" IS NULL)) AND (("DT_ARQUIVAMENTO" IS NULL) = ("CO_USUARIO_ARQUIVAMENTO" IS NULL)))),
    CONSTRAINT "CK_MODELORESPOSTA_NUVERSAO" CHECK (("NU_VERSAO" >= 1)),
    CONSTRAINT "CK_MODELORESPOSTA_STATIVO" CHECK ((("ST_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_MODELORESPOSTA_STVIGENTE" CHECK ((("ST_VIGENTE")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_MODELORESPOSTA_TAMANHOS" CHECK (((length(btrim("NO_MODELO")) >= 3) AND (length(btrim("NO_MODELO")) <= 150) AND ((length(btrim("DS_CORPO")) >= 20) AND (length(btrim("DS_CORPO")) <= 20000)) AND (COALESCE(length("DS_MOTIVO_ARQUIVAMENTO"), 0) <= 500))),
    CONSTRAINT "CK_MODELORESPOSTA_TPSITUACAO" CHECK (("TP_SITUACAO" = ANY (ARRAY['DEFERIDO'::text, 'INDEFERIDO'::text, 'PARCIALMENTE_INDEFERIDO'::text])))
);

--
-- Name: TABLE "TB_MODELO_RESPOSTA_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_MODELO_RESPOSTA_RECURSO" IS 'Modelos de resposta a recurso, uma linha por versão. Editar cria a versão seguinte (a anterior fica, não vigente); a resposta guarda modelo e versão usados.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."CO_MODELO_RESPOSTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."CO_MODELO_RESPOSTA" IS 'Identificador do modelo (o mesmo em todas as versões).';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."NU_VERSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."NU_VERSAO" IS 'Versão do modelo (1, 2, …).';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."CO_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."CO_AREA" IS 'Área em que o modelo vale (TB_AREA). Nula: todas as áreas.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."CO_ORIGEM_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."CO_ORIGEM_RECURSO" IS 'Origem de recurso em que o modelo vale (TB_ORIGEM_RECURSO). Nula: todas as origens.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."TP_SITUACAO" IS 'Decisão a que o modelo responde: DEFERIDO, INDEFERIDO ou PARCIALMENTE_INDEFERIDO.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."NO_MODELO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."NO_MODELO" IS 'Nome do modelo na lista.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."DS_CORPO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."DS_CORPO" IS 'Texto do modelo, com marcadores entre chaves ({nome_candidato}, {fundamentacao}…); só os de FC_MARCADORES_MODELO_RESPOSTA.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."ST_VIGENTE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."ST_VIGENTE" IS 'S: a versão atual do modelo (uma por modelo); N: versão anterior, mantida para as respostas que a usaram.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."ST_ATIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."ST_ATIVO" IS 'S: pode ser escolhido; N: arquivado (continua nas respostas que o usaram). Salvar de novo reativa, numa versão nova.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."DS_MOTIVO_ARQUIVAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."DS_MOTIVO_ARQUIVAMENTO" IS 'Motivo do arquivamento.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."DT_ARQUIVAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."DT_ARQUIVAMENTO" IS 'Quando foi arquivado.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."CO_USUARIO_ARQUIVAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."CO_USUARIO_ARQUIVAMENTO" IS 'Quem arquivou (auth.users.id).';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."DT_CRIACAO" IS 'Quando a versão foi criada.';

--
-- Name: COLUMN "TB_MODELO_RESPOSTA_RECURSO"."CO_USUARIO_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_MODELO_RESPOSTA_RECURSO"."CO_USUARIO_CRIACAO" IS 'Quem criou a versão (auth.users.id). Nulo nos modelos iniciais, semeados pela migration.';

--
-- Name: CONSTRAINT "CK_MODELORESPOSTA_ARQUIVAMENTO" ON "TB_MODELO_RESPOSTA_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELORESPOSTA_ARQUIVAMENTO" ON public."TB_MODELO_RESPOSTA_RECURSO" IS 'Arquivado guarda quando, quem e motivo juntos; ativo não guarda nenhum.';

--
-- Name: CONSTRAINT "CK_MODELORESPOSTA_NUVERSAO" ON "TB_MODELO_RESPOSTA_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELORESPOSTA_NUVERSAO" ON public."TB_MODELO_RESPOSTA_RECURSO" IS 'Versão começa em 1.';

--
-- Name: CONSTRAINT "CK_MODELORESPOSTA_STATIVO" ON "TB_MODELO_RESPOSTA_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELORESPOSTA_STATIVO" ON public."TB_MODELO_RESPOSTA_RECURSO" IS 'Flag S/N.';

--
-- Name: CONSTRAINT "CK_MODELORESPOSTA_STVIGENTE" ON "TB_MODELO_RESPOSTA_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELORESPOSTA_STVIGENTE" ON public."TB_MODELO_RESPOSTA_RECURSO" IS 'Flag S/N.';

--
-- Name: CONSTRAINT "CK_MODELORESPOSTA_TAMANHOS" ON "TB_MODELO_RESPOSTA_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_MODELORESPOSTA_TAMANHOS" ON public."TB_MODELO_RESPOSTA_RECURSO" IS 'Nome de 3 a 150, corpo de 20 a 20.000 e motivo até 500 caracteres.';

