--
-- Name: TB_PEDIDO_CALCULO_CLASSIFICACAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_PEDIDO_CALCULO_CLASSIFICACAO" (
    "CO_PEDIDO_CALCULO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "TP_LISTA" character varying(20) NOT NULL,
    "NU_VERSAO_REGRA" integer NOT NULL,
    "TP_SITUACAO" character varying(20) DEFAULT 'PEDIDO'::character varying NOT NULL,
    "DS_MENSAGEM" character varying(300),
    "DS_RETRATO" jsonb,
    "DS_HASH" character varying(64),
    "DS_DIVERGENCIA" jsonb,
    "CO_LISTA_CLASSIFICACAO" uuid,
    "CO_DISPARO" bigint,
    "CO_EXECUCAO" character varying(80),
    "CO_USUARIO" uuid NOT NULL,
    "DT_PEDIDO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_PEDCALCCLASSIF_COEXECUCAO" CHECK ((("CO_EXECUCAO" IS NULL) OR (("CO_EXECUCAO")::text ~ '^[A-Za-z0-9_.:-]{1,80}$'::text))),
    CONSTRAINT "CK_PEDCALCCLASSIF_DSHASH" CHECK ((("DS_HASH" IS NULL) OR (("DS_HASH")::text ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT "CK_PEDCALCCLASSIF_DSMENSAGEM" CHECK ((("DS_MENSAGEM" IS NULL) OR (("DS_MENSAGEM")::text !~ '@|[0-9]{11}'::text))),
    CONSTRAINT "CK_PEDCALCCLASSIF_DSRETRATO" CHECK ((("DS_RETRATO" IS NULL) OR (jsonb_typeof("DS_RETRATO") = 'object'::text))),
    CONSTRAINT "CK_PEDCALCCLASSIF_PRONTO" CHECK (((("TP_SITUACAO")::text <> 'PRONTO'::text) OR (("DS_RETRATO" IS NOT NULL) AND ("DS_HASH" IS NOT NULL)))),
    CONSTRAINT "CK_PEDCALCCLASSIF_REGISTRADO" CHECK (((("TP_SITUACAO")::text <> 'REGISTRADO'::text) OR ("CO_LISTA_CLASSIFICACAO" IS NOT NULL))),
    CONSTRAINT "CK_PEDCALCCLASSIF_TPLISTA" CHECK ((("TP_LISTA")::text = ANY ((ARRAY['PRELIMINAR'::character varying, 'CONVOCACAO'::character varying, 'ENTREVISTA'::character varying, 'FINAL'::character varying])::text[]))),
    CONSTRAINT "CK_PEDCALCCLASSIF_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY ((ARRAY['PEDIDO'::character varying, 'CALCULANDO'::character varying, 'PRONTO'::character varying, 'FALHOU'::character varying, 'NAO_CONFERE'::character varying, 'REGISTRADO'::character varying, 'SEM_DISPARO'::character varying, 'SUBSTITUIDO'::character varying])::text[])))
);

--
-- Name: TABLE "TB_PEDIDO_CALCULO_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_PEDIDO_CALCULO_CLASSIFICACAO" IS 'Pedidos de cálculo de uma lista de classificação pelo Python (20261023200000, chave classificacao_calculo): o "Gerar" da tela pede (pedir_calculo_classificacao), o job calcula e grava o retrato (classificacao_gravar_calculo), a tela confere com o motor.ts e registra (registrar_lista_calculada) ou grava a divergência (registrar_divergencia_do_calculo). O retrato leva os nomes, como a lista registrada; sai daqui quando a lista é registrada ou o pedido é substituído.';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_PEDIDO_CALCULO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_PEDIDO_CALCULO" IS 'Identificador do pedido.';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id).';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."TP_LISTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."TP_LISTA" IS 'PRELIMINAR, CONVOCACAO, ENTREVISTA ou FINAL.';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."NU_VERSAO_REGRA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."NU_VERSAO_REGRA" IS 'Versão da regra que a tela usou ao pedir (a do cálculo e a do registro).';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."TP_SITUACAO" IS 'PEDIDO (o workflow foi pedido), CALCULANDO (o job começou), PRONTO (retrato gravado), FALHOU (erro no job), NAO_CONFERE (o retrato do Python não é o da tela), REGISTRADO (a lista foi registrada), SEM_DISPARO (o pedido ao GitHub não saiu), SUBSTITUIDO (pronto e abandonado: um pedido mais novo da mesma lista o trocou).';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."DS_MENSAGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."DS_MENSAGEM" IS 'Mensagem curta para a tela (até 300 caracteres, sem "@" nem 11 dígitos seguidos; nunca nome).';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."DS_RETRATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."DS_RETRATO" IS 'O retrato da lista calculado pelo Python (o mesmo formato de TB_LISTA_CLASSIFICACAO.DS_RESULTADO); nulo depois do registro ou da substituição.';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."DS_HASH"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."DS_HASH" IS 'SHA-256 do conteúdo do retrato (FC_HASH_RETRATO_CLASSIFICACAO, 20261024130000; o mesmo que a lista registrada recebe).';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."DS_DIVERGENCIA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."DS_DIVERGENCIA" IS 'Quando não confere: origem (TELA ou BANCO), total e até 20 caminhos das diferenças, sem os valores.';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_LISTA_CLASSIFICACAO" IS 'A lista registrada a partir deste pedido.';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_DISPARO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_DISPARO" IS 'Pedido ao GitHub (TL_DISPARO_ROBO.CO_DISPARO), quando houve.';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_EXECUCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_EXECUCAO" IS 'Execução do job que mexeu por último (monitora.execucao.identificador).';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_USUARIO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."CO_USUARIO" IS 'Quem clicou em Gerar (auth.users.id).';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."DT_PEDIDO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."DT_PEDIDO" IS 'Quando foi pedido.';

--
-- Name: COLUMN "TB_PEDIDO_CALCULO_CLASSIFICACAO"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_CALCULO_CLASSIFICACAO"."DT_ATUALIZACAO" IS 'Última mudança de situação.';

--
-- Name: CONSTRAINT "CK_PEDCALCCLASSIF_COEXECUCAO" ON "TB_PEDIDO_CALCULO_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PEDCALCCLASSIF_COEXECUCAO" ON public."TB_PEDIDO_CALCULO_CLASSIFICACAO" IS 'Identificador de execução seguro para log.';

--
-- Name: CONSTRAINT "CK_PEDCALCCLASSIF_DSHASH" ON "TB_PEDIDO_CALCULO_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

