-- Name: TB_PEDIDO_CASAMENTO_LISTA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_PEDIDO_CASAMENTO_LISTA" (
    "CO_PEDIDO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_LISTA_APROVADO_ANTERIOR" uuid,
    "TP_ORIGEM" character varying(13) NOT NULL,
    "CO_LISTA_CLASSIFICACAO" uuid,
    "DS_NOVOS" jsonb NOT NULL,
    "DS_MANUAIS" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "NO_ARQUIVO" text,
    "DS_BASE" text NOT NULL,
    "TP_SITUACAO" character varying(10) DEFAULT 'PENDENTE'::character varying NOT NULL,
    "DS_PLANO" jsonb,
    "DS_ERRO" text,
    "CO_EXECUCAO" text,
    "CO_DISPARO" bigint,
    "CO_LISTA_APROVADO" uuid,
    "CO_USUARIO" uuid NOT NULL,
    "DT_PEDIDO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_CALCULO" timestamp with time zone,
    "DT_APLICACAO" timestamp with time zone,
    CONSTRAINT "CK_PEDCASAMENTO_COEXECUCAO" CHECK ((("CO_EXECUCAO" IS NULL) OR ("CO_EXECUCAO" ~ '^(casam-[0-9]{8}T[0-9]{6}-[0-9a-f]{8}|banco)$'::text))),
    CONSTRAINT "CK_PEDCASAMENTO_DSERRO" CHECK ((("DS_ERRO" IS NULL) OR ((length("DS_ERRO") >= 1) AND (length("DS_ERRO") <= 300)))),
    CONSTRAINT "CK_PEDCASAMENTO_JSON" CHECK (((jsonb_typeof("DS_NOVOS") = 'array'::text) AND (jsonb_typeof("DS_MANUAIS") = 'object'::text) AND (("DS_PLANO" IS NULL) OR (jsonb_typeof("DS_PLANO") = 'object'::text)))),
    CONSTRAINT "CK_PEDCASAMENTO_ORIGEM" CHECK (((("TP_ORIGEM")::text = 'CLASSIFICACAO'::text) = ("CO_LISTA_CLASSIFICACAO" IS NOT NULL))),
    CONSTRAINT "CK_PEDCASAMENTO_PLANO" CHECK (((("TP_SITUACAO")::text = ANY ((ARRAY['CALCULADO'::character varying, 'APLICADO'::character varying])::text[])) = ("DS_PLANO" IS NOT NULL))),
    CONSTRAINT "CK_PEDCASAMENTO_TPORIGEM" CHECK ((("TP_ORIGEM")::text = ANY ((ARRAY['XLSX'::character varying, 'CLASSIFICACAO'::character varying])::text[]))),
    CONSTRAINT "CK_PEDCASAMENTO_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY ((ARRAY['PENDENTE'::character varying, 'CALCULADO'::character varying, 'ERRO'::character varying, 'APLICADO'::character varying, 'DESCARTADO'::character varying])::text[])))
);

--
-- Name: TABLE "TB_PEDIDO_CASAMENTO_LISTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_PEDIDO_CASAMENTO_LISTA" IS 'Instantâneo do casamento da lista de aprovados (20261030090000): o pedido da prévia de uma nova versão (XLSX ou Classificação) — quem entra, a lista vigente de referência e a assinatura dela — e o plano que o job Python (scripts/aprovados/casamento_da_lista.py) grava: quem da lista vigente é quem entra, o resumo e as pendências. aplicar_casamento_da_lista confere e aplica. Pedidos de mais de 2 dias saem no próximo pedido. Só pelas RPCs.';

