--
-- Name: TB_PEDIDO_REINICIO_FICHA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_PEDIDO_REINICIO_FICHA" (
    "CO_PEDIDO_REINICIO" bigint NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "TP_SITUACAO" character varying(10) DEFAULT 'PENDENTE'::character varying NOT NULL,
    "DS_MOTIVO" character varying(1000) NOT NULL,
    "CO_USUARIO_PEDIDO" uuid NOT NULL,
    "DT_PEDIDO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_VALIDADE" timestamp with time zone NOT NULL,
    "QT_CONCLUIDAS" integer NOT NULL,
    "QT_EM_ANALISE" integer NOT NULL,
    "QT_INICIADAS" integer NOT NULL,
    "CO_USUARIO_DECISAO" uuid,
    "DT_DECISAO" timestamp with time zone,
    "DS_MOTIVO_DECISAO" character varying(1000),
    "QT_REINICIADAS" integer,
    CONSTRAINT "CK_PEDREINFICHA_DECISAO" CHECK ((((("TP_SITUACAO")::text = 'PENDENTE'::text) AND ("CO_USUARIO_DECISAO" IS NULL) AND ("DT_DECISAO" IS NULL) AND ("QT_REINICIADAS" IS NULL)) OR ((("TP_SITUACAO")::text = 'EXECUTADO'::text) AND ("CO_USUARIO_DECISAO" IS NOT NULL) AND ("DT_DECISAO" IS NOT NULL) AND ("CO_USUARIO_DECISAO" <> "CO_USUARIO_PEDIDO") AND ("QT_REINICIADAS" IS NOT NULL)) OR ((("TP_SITUACAO")::text = 'RECUSADO'::text) AND ("CO_USUARIO_DECISAO" IS NOT NULL) AND ("DT_DECISAO" IS NOT NULL) AND ("CO_USUARIO_DECISAO" <> "CO_USUARIO_PEDIDO") AND ("QT_REINICIADAS" IS NULL)) OR ((("TP_SITUACAO")::text = 'CANCELADO'::text) AND ("CO_USUARIO_DECISAO" = "CO_USUARIO_PEDIDO") AND ("DT_DECISAO" IS NOT NULL) AND ("QT_REINICIADAS" IS NULL)) OR ((("TP_SITUACAO")::text = 'VENCIDO'::text) AND ("CO_USUARIO_DECISAO" IS NULL) AND ("DT_DECISAO" IS NOT NULL) AND ("QT_REINICIADAS" IS NULL)))),
    CONSTRAINT "CK_PEDREINFICHA_DSMOTIVO" CHECK (((length(btrim(("DS_MOTIVO")::text)) >= 10) AND (length(btrim(("DS_MOTIVO")::text)) <= 1000))),
    CONSTRAINT "CK_PEDREINFICHA_DSMOTIVODEC" CHECK ((("DS_MOTIVO_DECISAO" IS NULL) OR ((length(btrim(("DS_MOTIVO_DECISAO")::text)) >= 10) AND (length(btrim(("DS_MOTIVO_DECISAO")::text)) <= 1000)))),
    CONSTRAINT "CK_PEDREINFICHA_DTVALIDADE" CHECK (("DT_VALIDADE" > "DT_PEDIDO")),
    CONSTRAINT "CK_PEDREINFICHA_QUANTIDADES" CHECK ((("QT_CONCLUIDAS" >= 0) AND ("QT_EM_ANALISE" >= 0) AND ("QT_INICIADAS" >= 0) AND (COALESCE("QT_REINICIADAS", 0) >= 0))),
    CONSTRAINT "CK_PEDREINFICHA_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY ((ARRAY['PENDENTE'::character varying, 'EXECUTADO'::character varying, 'RECUSADO'::character varying, 'CANCELADO'::character varying, 'VENCIDO'::character varying])::text[])))
);

--
-- Name: TABLE "TB_PEDIDO_REINICIO_FICHA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_PEDIDO_REINICIO_FICHA" IS 'Pedidos de reinício das fichas de um edital (20261022210000): um administrador global pede (motivo e o número do edital digitado), outro administrador global, diferente, aprova e só então o reinício roda (FC_REINICIAR_FICHAS_DO_EDITAL). Vale 24 h; quem pediu pode cancelar; outro pode recusar. Um PENDENTE por edital. Escrita só pelas RPCs pedir/aprovar/recusar/cancelar_reinicio_fichas_do_edital.';

--
-- Name: COLUMN "TB_PEDIDO_REINICIO_FICHA"."CO_PEDIDO_REINICIO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_REINICIO_FICHA"."CO_PEDIDO_REINICIO" IS 'Número do pedido (sequencial).';

--
-- Name: COLUMN "TB_PEDIDO_REINICIO_FICHA"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_REINICIO_FICHA"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id).';

--
-- Name: COLUMN "TB_PEDIDO_REINICIO_FICHA"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_REINICIO_FICHA"."TP_SITUACAO" IS 'PENDENTE, EXECUTADO (aprovado e reiniciado), RECUSADO, CANCELADO (por quem pediu) ou VENCIDO (passou da validade sem decisão).';

--
-- Name: COLUMN "TB_PEDIDO_REINICIO_FICHA"."DS_MOTIVO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_REINICIO_FICHA"."DS_MOTIVO" IS 'Motivo do pedido (10 a 1.000 caracteres, parece texto).';

--
-- Name: COLUMN "TB_PEDIDO_REINICIO_FICHA"."CO_USUARIO_PEDIDO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_REINICIO_FICHA"."CO_USUARIO_PEDIDO" IS 'Administrador global que pediu (auth.users.id).';

--
-- Name: COLUMN "TB_PEDIDO_REINICIO_FICHA"."DT_PEDIDO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PEDIDO_REINICIO_FICHA"."DT_PEDIDO" IS 'Quando pediu.';

--
