--
-- Name: TB_PREPARO_DESEMPATE; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_PREPARO_DESEMPATE" (
    "CO_LISTA_CLASSIFICACAO" uuid NOT NULL,
    "TP_SITUACAO" character varying(20) NOT NULL,
    "DS_MENSAGEM" character varying(300),
    "CO_DISPARO" bigint,
    "CO_EXECUCAO" character varying(80),
    "DT_PEDIDO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_PREPARODESEMP_COEXECUCAO" CHECK ((("CO_EXECUCAO" IS NULL) OR (("CO_EXECUCAO")::text ~ '^[A-Za-z0-9_.:-]{1,80}$'::text))),
    CONSTRAINT "CK_PREPARODESEMP_DSMENSAGEM" CHECK ((("DS_MENSAGEM" IS NULL) OR (("DS_MENSAGEM")::text !~ '@|[0-9]{11}'::text))),
    CONSTRAINT "CK_PREPARODESEMP_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY ((ARRAY['PEDIDO'::character varying, 'PREPARANDO'::character varying, 'PRONTO'::character varying, 'NAO_CONFERE'::character varying, 'FALHOU'::character varying, 'DESLIGADA'::character varying, 'SEM_DISPARO'::character varying])::text[])))
);

--
-- Name: TABLE "TB_PREPARO_DESEMPATE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_PREPARO_DESEMPATE" IS 'Preparo do relatório de desempate de cada lista gerada (20261023170000): registrar_lista_classificacao pede (FC_PEDIR_DESEMPATE), o job da classificação em Python marca PREPARANDO, NAO_CONFERE ou FALHOU (classificacao_marcar_preparo) e a gravação do relatório marca PRONTO (classificacao_gravar_desempate). A tela lê por obter_desempate_da_lista. Sem dado pessoal.';

--
-- Name: COLUMN "TB_PREPARO_DESEMPATE"."CO_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PREPARO_DESEMPATE"."CO_LISTA_CLASSIFICACAO" IS 'Lista gerada (TB_LISTA_CLASSIFICACAO).';

--
-- Name: COLUMN "TB_PREPARO_DESEMPATE"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PREPARO_DESEMPATE"."TP_SITUACAO" IS 'PEDIDO (o workflow foi pedido), PREPARANDO (o job começou), PRONTO (relatório gravado), NAO_CONFERE (o retrato calculado pelo Python não é o da lista registrada), FALHOU (erro no job), DESLIGADA (chave "classificacao" desligada ao gerar), SEM_DISPARO (o pedido ao GitHub não saiu).';

--
-- Name: COLUMN "TB_PREPARO_DESEMPATE"."DS_MENSAGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PREPARO_DESEMPATE"."DS_MENSAGEM" IS 'Mensagem curta para a tela (até 300 caracteres, sem "@" nem 11 dígitos seguidos; nunca nome).';

--
-- Name: COLUMN "TB_PREPARO_DESEMPATE"."CO_DISPARO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PREPARO_DESEMPATE"."CO_DISPARO" IS 'Pedido ao GitHub (TL_DISPARO_ROBO.CO_DISPARO), quando houve.';

--
-- Name: COLUMN "TB_PREPARO_DESEMPATE"."CO_EXECUCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PREPARO_DESEMPATE"."CO_EXECUCAO" IS 'Execução do job que mexeu por último (monitora.execucao.identificador).';

--
-- Name: COLUMN "TB_PREPARO_DESEMPATE"."DT_PEDIDO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PREPARO_DESEMPATE"."DT_PEDIDO" IS 'Quando o relatório foi pedido (a geração da lista).';

--
-- Name: COLUMN "TB_PREPARO_DESEMPATE"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PREPARO_DESEMPATE"."DT_ATUALIZACAO" IS 'Última mudança de situação.';

--
-- Name: CONSTRAINT "CK_PREPARODESEMP_COEXECUCAO" ON "TB_PREPARO_DESEMPATE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PREPARODESEMP_COEXECUCAO" ON public."TB_PREPARO_DESEMPATE" IS 'Identificador de execução seguro para log.';

--
-- Name: CONSTRAINT "CK_PREPARODESEMP_DSMENSAGEM" ON "TB_PREPARO_DESEMPATE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PREPARODESEMP_DSMENSAGEM" ON public."TB_PREPARO_DESEMPATE" IS 'Mensagem sem e-mail nem 11 dígitos seguidos.';

--
-- Name: CONSTRAINT "CK_PREPARODESEMP_TPSITUACAO" ON "TB_PREPARO_DESEMPATE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_PREPARODESEMP_TPSITUACAO" ON public."TB_PREPARO_DESEMPATE" IS 'Situações da lista fixa.';

