    CONSTRAINT "TB_PREVISAO_ENTREVISTA_EDITAL_TP_PREVISAO_check" CHECK (("TP_PREVISAO" = ANY (ARRAY['PREVISTA'::text, 'NAO_PREVISTA'::text, 'NAO_INFORMADA'::text])))
);

--
-- Name: TB_PRE_CLASSIFICACAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_PRE_CLASSIFICACAO" (
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_EMPREGARE_CANDIDATO" uuid NOT NULL,
    "CO_VAGA" character varying(20) NOT NULL,
    "NU_VERSAO_REGRA" integer NOT NULL,
    "TP_SITUACAO" character varying(12) NOT NULL,
    "CO_MOTIVO_ELIMINACAO" character varying(30),
    "DS_MOTIVO_ELIMINACAO" character varying(200),
    "VL_ART" numeric(8,4),
    "VL_NOTA_ORDEM" numeric(8,4),
    "TP_ORIGEM_NOTA" character varying(10),
    "VL_NOTA_DECLARADA" numeric(8,4),
    "DS_NOTA_DECLARADA" jsonb,
    "ST_DIVERGENTE" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "NO_MODALIDADE" character varying(10) DEFAULT 'AC'::character varying NOT NULL,
    "NU_POSICAO" integer,
    "NU_POSICAO_MODALIDADE" integer,
    "NU_LOTE" smallint,
    "CO_LISTA_LOTE" character varying(12),
    "TP_ENTRADA_LOTE" character varying(10),
    "DS_MOTIVO_ENTRADA" character varying(300),
    "DT_ENTRADA_LOTE" timestamp with time zone,
    "CO_EXECUCAO" text NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "VL_DECLARADA_CONGELADA" numeric(8,4),
    "DS_DECLARADA_CONGELADA" jsonb,
    "DT_CONGELAMENTO_DECLARADA" timestamp with time zone,
    "DS_MODALIDADES" jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT "CK_PRECLASSIF_COMOTIVO" CHECK ((("CO_MOTIVO_ELIMINACAO" IS NULL) OR (("CO_MOTIVO_ELIMINACAO")::text ~ '^[A-Z][A-Z0-9_]{1,29}$'::text))),
    CONSTRAINT "CK_PRECLASSIF_DECLARADA" CHECK ((("DS_NOTA_DECLARADA" IS NULL) OR (jsonb_typeof("DS_NOTA_DECLARADA") = 'object'::text))),
    CONSTRAINT "CK_PRECLASSIF_DECLCONGELADA" CHECK (((("VL_DECLARADA_CONGELADA" IS NULL) = ("DS_DECLARADA_CONGELADA" IS NULL)) AND (("VL_DECLARADA_CONGELADA" IS NULL) = ("DT_CONGELAMENTO_DECLARADA" IS NULL)) AND (("VL_DECLARADA_CONGELADA" IS NULL) OR (("VL_DECLARADA_CONGELADA" >= (0)::numeric) AND ("VL_DECLARADA_CONGELADA" <= (1000)::numeric))) AND (("DS_DECLARADA_CONGELADA" IS NULL) OR (jsonb_typeof("DS_DECLARADA_CONGELADA") = 'object'::text)))),
    CONSTRAINT "CK_PRECLASSIF_DSMODALIDADES" CHECK (((jsonb_typeof("DS_MODALIDADES") = 'array'::text) AND (jsonb_array_length("DS_MODALIDADES") <= 10))),
    CONSTRAINT "CK_PRECLASSIF_ELIMINADO" CHECK ((((("TP_SITUACAO")::text = 'ELIMINADO'::text) = ("CO_MOTIVO_ELIMINACAO" IS NOT NULL)) AND (("CO_MOTIVO_ELIMINACAO" IS NULL) = ("DS_MOTIVO_ELIMINACAO" IS NULL)))),
    CONSTRAINT "CK_PRECLASSIF_ENTRADA" CHECK ((("TP_ENTRADA_LOTE" IS NULL) OR (("TP_ENTRADA_LOTE")::text = ANY (ARRAY[('INICIAL'::character varying)::text, ('REPOSICAO'::character varying)::text, ('AMPLIACAO'::character varying)::text, ('DECISAO'::character varying)::text])))),
    CONSTRAINT "CK_PRECLASSIF_LISTALOTE" CHECK ((("CO_LISTA_LOTE" IS NULL) OR (("CO_LISTA_LOTE")::text ~ '^(GERAL|[A-Z]{2,10})$'::text))),
    CONSTRAINT "CK_PRECLASSIF_LOTE" CHECK (
CASE
    WHEN (("TP_SITUACAO")::text = ANY (ARRAY[('NO_LOTE'::character varying)::text, ('ANALISADO'::character varying)::text])) THEN (("NU_LOTE" >= 1) AND ("NU_LOTE" <= 999) AND ("CO_LISTA_LOTE" IS NOT NULL) AND ("TP_ENTRADA_LOTE" IS NOT NULL))
    ELSE (("NU_LOTE" IS NULL) AND ("CO_LISTA_LOTE" IS NULL) AND ("TP_ENTRADA_LOTE" IS NULL) AND ("DS_MOTIVO_ENTRADA" IS NULL) AND ("DT_ENTRADA_LOTE" IS NULL))
END),
    CONSTRAINT "CK_PRECLASSIF_MODALIDADE" CHECK ((("NO_MODALIDADE")::text ~ '^[A-Z]{2,10}$'::text)),
    CONSTRAINT "CK_PRECLASSIF_NUVERSAO" CHECK (("NU_VERSAO_REGRA" >= 1)),
    CONSTRAINT "CK_PRECLASSIF_ORIGEMNOTA" CHECK ((("TP_ORIGEM_NOTA" IS NULL) OR (("TP_ORIGEM_NOTA")::text = ANY (ARRAY[('ART'::character varying)::text, ('DECLARADA'::character varying)::text])))),
    CONSTRAINT "CK_PRECLASSIF_POSICAO" CHECK (
CASE
    WHEN (("TP_SITUACAO")::text = 'ELIMINADO'::text) THEN (("NU_POSICAO" IS NULL) AND ("NU_POSICAO_MODALIDADE" IS NULL))
    ELSE (("NU_POSICAO" >= 1) AND ("NU_POSICAO_MODALIDADE" >= 1))
END),
    CONSTRAINT "CK_PRECLASSIF_STDIVERGENTE" CHECK ((("ST_DIVERGENTE")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_PRECLASSIF_TPSITUACAO" CHECK ((("TP_SITUACAO")::text = ANY (ARRAY[('ELIMINADO'::character varying)::text, ('RANQUEADO'::character varying)::text, ('NO_LOTE'::character varying)::text, ('ANALISADO'::character varying)::text])))
);

--
-- Name: TABLE "TB_PRE_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_PRE_CLASSIFICACAO" IS 'Lista provisória por ART (item 8.3.1) e lote de convocação (item 8.4) de cada vaga, gravados prontos pelo job Python: eliminados automáticos com motivo, ranqueados, os do lote e os já analisados. Fonte das listas PROVISORIA e LOTE e dos contadores da aba Pré-classificação. Nada se apaga.';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."CO_EMPREGARE_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."CO_EMPREGARE_CANDIDATO" IS 'Inscrito na vaga (TB_EMPREGARE_CANDIDATO: um candidato por vaga).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."CO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."CO_VAGA" IS 'Código da vaga da Empregare (o mesmo do inscrito).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."NU_VERSAO_REGRA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."NU_VERSAO_REGRA" IS 'Versão (conferida) da regra da avaliação usada (TH_REGRA_ANALISE.NU_VERSAO).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."TP_SITUACAO" IS 'ELIMINADO (eliminação automática, com motivo), RANQUEADO (na Provisória, fora do lote), NO_LOTE (no lote de convocação) ou ANALISADO (já tem ficha; nunca muda por recálculo).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."CO_MOTIVO_ELIMINACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."CO_MOTIVO_ELIMINACAO" IS 'Código da regra de eliminação automática (CANCELADO, QUESTIONARIO, REPROVADO_EMPREGARE, TERMO…) ou SAIU_DA_EMPREGARE.';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."DS_MOTIVO_ELIMINACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."DS_MOTIVO_ELIMINACAO" IS 'Motivo da eliminação, como a regra escreve (vai para a lista).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."VL_ART"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."VL_ART" IS 'Nota da Autodeclaração de Requisitos e Títulos: a nota do questionário da Empregare ("24,0/30,0" → 24). Nula quando o arquivo não traz número.';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."VL_NOTA_ORDEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."VL_NOTA_ORDEM" IS 'Nota que ordena a Provisória: a ART ou, sem ela, a nota declarada (TP_ORIGEM_NOTA).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."TP_ORIGEM_NOTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."TP_ORIGEM_NOTA" IS 'ART ou DECLARADA (sem ART, vale a nota declarada, com aviso); nula sem as duas.';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."VL_NOTA_DECLARADA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."VL_NOTA_DECLARADA" IS 'Nota declarada recalculada pela regra a partir das respostas (só confere a ART).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."DS_NOTA_DECLARADA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."DS_NOTA_DECLARADA" IS 'Parciais da nota declarada e quantas respostas ficaram fora do mapa da regra ({"parciais": {...}, "sem_mapa": n}).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."ST_DIVERGENTE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."ST_DIVERGENTE" IS 'S: a ART difere da nota declarada além da tolerância da regra (aviso para a coordenação; a ordem segue a ART).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."NO_MODALIDADE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."NO_MODALIDADE" IS 'Modalidade declarada (AC, PP, PI, PQ, PCD, TRANS), pelo bloco MODALIDADE da regra.';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."NU_POSICAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."NU_POSICAO" IS 'Posição na Provisória da vaga (nula para eliminado).';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."NU_POSICAO_MODALIDADE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."NU_POSICAO_MODALIDADE" IS 'Posição entre os da mesma modalidade.';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."NU_LOTE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_PRE_CLASSIFICACAO"."NU_LOTE" IS '1 = lote inicial; 2, 3… = as reposições ("a linha anda"). Nulo fora do lote.';

--
-- Name: COLUMN "TB_PRE_CLASSIFICACAO"."CO_LISTA_LOTE"; Type: COMMENT; Schema: public; Owner: -
--

