--

COMMENT ON CONSTRAINT "CK_RASCUNHOREGRA_TPREGRA" ON public."TB_RASCUNHO_REGRA" IS 'Tipos de regra válidos.';

--
-- Name: TB_RECURSO_CANDIDATO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_RECURSO_CANDIDATO" (
    "CO_RECURSO_CANDIDATO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "NU_RECURSO" bigint NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_ORIGEM_RECURSO" text NOT NULL,
    "CO_ANALISE_CURRICULAR" uuid,
    "ST_FORA_ANALISE" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "NO_CANDIDATO_INFORMADO" text,
    "CO_CANDIDATO_INFORMADO" text,
    "NO_CARGO_INFORMADO" text,
    "CO_VAGA_INFORMADA" text,
    "VL_NOTA_ANTERIOR" numeric,
    "DS_RESULTADO_ANTERIOR" text,
    "NO_ANALISTA" text,
    "TP_SITUACAO" text DEFAULT 'REGISTRADO'::text NOT NULL,
    "NU_PROCESSO_SEI" text,
    "ST_MUDOU_CLASSIFICACAO" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "DS_OBSERVACAO" text,
    "DT_DOWNLOAD_EMPREGARE" timestamp with time zone,
    "CO_USUARIO_DOWNLOAD_EMPREGARE" uuid,
    "DT_PROCESSO_SEI" timestamp with time zone,
    "CO_USUARIO_PROCESSO_SEI" uuid,
    "DT_UPLOAD_SEI" timestamp with time zone,
    "CO_USUARIO_UPLOAD_SEI" uuid,
    "DT_RESPOSTA_CANDIDATO" timestamp with time zone,
    "CO_USUARIO_RESPOSTA_CANDIDATO" uuid,
    "DT_DECISAO" timestamp with time zone,
    "CO_USUARIO_DECISAO" uuid,
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "NU_REVISAO" integer DEFAULT 1 NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_CRIACAO" uuid NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid NOT NULL,
    "DS_PARECER_JURIDICO" text,
    "DT_ENVIO_PARECER" timestamp with time zone,
    "CO_USUARIO_ENVIO_PARECER" uuid,
    "DT_DEVOLUCAO" timestamp with time zone,
    "CO_USUARIO_DEVOLUCAO" uuid,
    "DS_COMENTARIO_DEVOLUCAO" text,
    CONSTRAINT "CK_RECURSOCANDIDATO_CANDIDATO" CHECK ((((("ST_FORA_ANALISE")::text = 'N'::text) AND ("CO_ANALISE_CURRICULAR" IS NOT NULL) AND ("NO_CANDIDATO_INFORMADO" IS NULL) AND ("CO_CANDIDATO_INFORMADO" IS NULL) AND ("NO_CARGO_INFORMADO" IS NULL) AND ("CO_VAGA_INFORMADA" IS NULL)) OR ((("ST_FORA_ANALISE")::text = 'S'::text) AND ("CO_ANALISE_CURRICULAR" IS NULL) AND ((length(btrim("NO_CANDIDATO_INFORMADO")) >= 3) AND (length(btrim("NO_CANDIDATO_INFORMADO")) <= 200))))),
    CONSTRAINT "CK_RECURSOCANDIDATO_DECISAO" CHECK (((("TP_SITUACAO" = ANY (ARRAY['DEFERIDO'::text, 'INDEFERIDO'::text, 'PARCIALMENTE_INDEFERIDO'::text])) = ("DT_DECISAO" IS NOT NULL)) AND (("DT_DECISAO" IS NULL) = ("CO_USUARIO_DECISAO" IS NULL)) AND (("DT_DECISAO" IS NULL) = ("DS_PARECER_JURIDICO" IS NULL)))),
    CONSTRAINT "CK_RECURSOCANDIDATO_ETAPAS" CHECK (((("DT_DOWNLOAD_EMPREGARE" IS NULL) = ("CO_USUARIO_DOWNLOAD_EMPREGARE" IS NULL)) AND (("DT_PROCESSO_SEI" IS NULL) = ("CO_USUARIO_PROCESSO_SEI" IS NULL)) AND (("DT_UPLOAD_SEI" IS NULL) = ("CO_USUARIO_UPLOAD_SEI" IS NULL)) AND (("DT_RESPOSTA_CANDIDATO" IS NULL) = ("CO_USUARIO_RESPOSTA_CANDIDATO" IS NULL)))),
    CONSTRAINT "CK_RECURSOCANDIDATO_PARECER" CHECK (((("DT_ENVIO_PARECER" IS NULL) = ("CO_USUARIO_ENVIO_PARECER" IS NULL)) AND (("TP_SITUACAO" <> 'EM_ANALISE_JURIDICA'::text) OR ("DT_ENVIO_PARECER" IS NOT NULL)) AND (("DT_DEVOLUCAO" IS NULL) = ("CO_USUARIO_DEVOLUCAO" IS NULL)) AND (("DT_DEVOLUCAO" IS NULL) = ("DS_COMENTARIO_DEVOLUCAO" IS NULL)) AND (("DT_DEVOLUCAO" IS NULL) OR ("TP_SITUACAO" = 'REGISTRADO'::text)))),
    CONSTRAINT "CK_RECURSOCANDIDATO_STATIVO" CHECK ((("ST_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_RECURSOCANDIDATO_STFORAANALISE" CHECK ((("ST_FORA_ANALISE")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_RECURSOCANDIDATO_STMUDOUCLASSIFICACAO" CHECK ((("ST_MUDOU_CLASSIFICACAO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_RECURSOCANDIDATO_TAMANHOS" CHECK (((COALESCE(length("CO_CANDIDATO_INFORMADO"), 0) <= 60) AND (COALESCE(length("NO_CARGO_INFORMADO"), 0) <= 200) AND (COALESCE(length("CO_VAGA_INFORMADA"), 0) <= 60) AND (COALESCE(length("NO_ANALISTA"), 0) <= 200) AND (COALESCE(length("NU_PROCESSO_SEI"), 0) <= 60) AND (COALESCE(length("DS_OBSERVACAO"), 0) <= 2000))),
    CONSTRAINT "CK_RECURSOCANDIDATO_TAMPARECER" CHECK (((COALESCE(length("DS_PARECER_JURIDICO"), 0) <= 20000) AND (COALESCE(length("DS_COMENTARIO_DEVOLUCAO"), 0) <= 2000))),
    CONSTRAINT "CK_RECURSOCANDIDATO_TPSITUACAO" CHECK (("TP_SITUACAO" = ANY (ARRAY['REGISTRADO'::text, 'EM_ANALISE_JURIDICA'::text, 'DEFERIDO'::text, 'INDEFERIDO'::text, 'PARCIALMENTE_INDEFERIDO'::text])))
);

--
-- Name: TABLE "TB_RECURSO_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_RECURSO_CANDIDATO" IS 'Recurso de um candidato contra uma etapa de um edital (aba Recursos). Candidato, cargo, vaga, nota e resultado vêm da análise curricular ligada; os campos *_INFORMADO só existem quando o candidato está fora das análises. A área é a do edital.';

