--
-- Name: TB_REGRA_AGENDA_ENTREVISTA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_REGRA_AGENDA_ENTREVISTA" (
    "CO_REGRA_AGENDA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "NU_VERSAO_VIGENTE" integer NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
