-- Name: TB_RELATORIO_DESEMPATE; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_RELATORIO_DESEMPATE" (
    "CO_LISTA_CLASSIFICACAO" uuid NOT NULL,
    "NU_VERSAO_RELATORIO" smallint NOT NULL,
    "DS_RELATORIO" jsonb NOT NULL,
    "DS_TEXTO" text NOT NULL,
    "DS_HASH_LISTA" character varying(64) NOT NULL,
    "QT_GRUPO" integer DEFAULT 0 NOT NULL,
    "QT_EMPATE_FINAL" integer DEFAULT 0 NOT NULL,
    "QT_PENDENCIA" integer DEFAULT 0 NOT NULL,
    "CO_EXECUCAO" character varying(80) NOT NULL,
    "DT_GERACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_RELATDESEMP_EXECUCAO" CHECK ((("CO_EXECUCAO")::text ~ '^[A-Za-z0-9_.:-]{1,80}$'::text)),
    CONSTRAINT "CK_RELATDESEMP_HASH" CHECK ((("DS_HASH_LISTA")::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT "CK_RELATDESEMP_QUANTIDADES" CHECK ((("QT_GRUPO" >= 0) AND ("QT_EMPATE_FINAL" >= 0) AND ("QT_PENDENCIA" >= 0))),
    CONSTRAINT "CK_RELATDESEMP_RELATORIO" CHECK ((jsonb_typeof("DS_RELATORIO") = 'object'::text)),
    CONSTRAINT "CK_RELATDESEMP_TAMANHO" CHECK (((octet_length(("DS_RELATORIO")::text) <= 8000000) AND (octet_length("DS_TEXTO") <= 8000000))),
    CONSTRAINT "CK_RELATDESEMP_VERSAO" CHECK (("NU_VERSAO_RELATORIO" >= 1))
);

--
-- Name: TABLE "TB_RELATORIO_DESEMPATE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_RELATORIO_DESEMPATE" IS 'Relatório de desempate de uma lista de classificação gerada (TB_LISTA_CLASSIFICACAO), calculado pelo Python: por vaga, lista e nota, os grupos de empate, os critérios aplicados, o valor de cada candidato, o critério que decidiu cada par e quem ficou empatado até o fim. Candidato = id da análise, código de inscrição e nome (documento interno da comissão, 20261023170000); sem CPF, contato nem data de nascimento. Grava classificacao_gravar_desempate; a tela lê por obter_desempate_da_lista.';

--
-- Name: COLUMN "TB_RELATORIO_DESEMPATE"."CO_LISTA_CLASSIFICACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_RELATORIO_DESEMPATE"."CO_LISTA_CLASSIFICACAO" IS 'Lista gerada a que o relatório pertence (TB_LISTA_CLASSIFICACAO).';

