--

COMMENT ON COLUMN public."TB_RELATORIO_DESEMPATE"."DT_GERACAO" IS 'Quando o relatório foi gravado.';

--
-- Name: TB_RESPOSTA_RECURSO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_RESPOSTA_RECURSO" (
    "CO_RESPOSTA_RECURSO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_RECURSO_CANDIDATO" uuid NOT NULL,
    "CO_MODELO_RESPOSTA" uuid NOT NULL,
    "NU_VERSAO_MODELO" integer NOT NULL,
    "DS_FUNDAMENTACAO" text DEFAULT ''::text NOT NULL,
    "DS_TEXTO_FINAL" text NOT NULL,
    "TP_ESTADO" text DEFAULT 'rascunho'::text NOT NULL,
    "ST_PASSOU_REVISAO" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "CO_USUARIO_AUTOR" uuid NOT NULL,
    "DT_ENVIO_REVISAO" timestamp with time zone,
    "CO_USUARIO_ENVIO_REVISAO" uuid,
    "DT_REVISAO" timestamp with time zone,
    "CO_USUARIO_REVISOR" uuid,
    "DS_COMENTARIO_REVISAO" text,
    "DT_ENVIO" timestamp with time zone,
    "CO_USUARIO_ENVIO" uuid,
    "NU_REVISAO" integer DEFAULT 1 NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_CRIACAO" uuid NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid NOT NULL,
    CONSTRAINT "CK_RESPOSTARECURSO_ENVIO" CHECK (((("TP_ESTADO" = 'enviada'::text) = ("DT_ENVIO" IS NOT NULL)) AND (("DT_ENVIO" IS NULL) = ("CO_USUARIO_ENVIO" IS NULL)))),
    CONSTRAINT "CK_RESPOSTARECURSO_REVISAO" CHECK (((("DT_ENVIO_REVISAO" IS NULL) = ("CO_USUARIO_ENVIO_REVISAO" IS NULL)) AND (("DT_REVISAO" IS NULL) = ("CO_USUARIO_REVISOR" IS NULL)) AND (("TP_ESTADO" <> 'em_revisao'::text) OR ("DT_ENVIO_REVISAO" IS NOT NULL)) AND (("TP_ESTADO" <> ALL (ARRAY['aprovada'::text, 'devolvida'::text, 'enviada'::text])) OR ("CO_USUARIO_REVISOR" IS NOT NULL)) AND (("TP_ESTADO" <> 'devolvida'::text) OR ("DS_COMENTARIO_REVISAO" IS NOT NULL)))),
    CONSTRAINT "CK_RESPOSTARECURSO_STPASSOUREVISAO" CHECK ((("ST_PASSOU_REVISAO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_RESPOSTARECURSO_TAMANHOS" CHECK (((length("DS_FUNDAMENTACAO") <= 20000) AND ((length(btrim("DS_TEXTO_FINAL")) >= 1) AND (length(btrim("DS_TEXTO_FINAL")) <= 60000)) AND (COALESCE(length("DS_COMENTARIO_REVISAO"), 0) <= 2000))),
    CONSTRAINT "CK_RESPOSTARECURSO_TPESTADO" CHECK (("TP_ESTADO" = ANY (ARRAY['rascunho'::text, 'em_revisao'::text, 'aprovada'::text, 'devolvida'::text, 'enviada'::text])))
);

