-- Name: TB_RESUMO_PERGUNTA_EDITAL; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_RESUMO_PERGUNTA_EDITAL" (
    "CO_MONITORAMENTO" uuid NOT NULL,
    "DS_PERGUNTA" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "QT_CANDIDATO" integer DEFAULT 0 NOT NULL,
    "DS_HASH_VAGA" character varying(32) NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_RESPERGEDT_DSPERGUNTA" CHECK ((jsonb_typeof("DS_PERGUNTA") = 'array'::text)),
    CONSTRAINT "CK_RESPERGEDT_QTCANDIDATO" CHECK (("QT_CANDIDATO" >= 0))
);

--
-- Name: TABLE "TB_RESUMO_PERGUNTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_RESUMO_PERGUNTA_EDITAL" IS 'Instantâneo das perguntas da última carga da Empregare por edital (o que a coordenação liga aos blocos da regra da avaliação documental). Calculado em Python pelo robô da Empregare ao fim de cada carga (scripts/robo-empregare/resumo_das_perguntas.py → gravar_resumo_pergunta_edital) e lido por obter_perguntas_carga_analise. Sem acesso direto do cliente.';

--
-- Name: COLUMN "TB_RESUMO_PERGUNTA_EDITAL"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_RESUMO_PERGUNTA_EDITAL"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id).';

--
-- Name: COLUMN "TB_RESUMO_PERGUNTA_EDITAL"."DS_PERGUNTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_RESUMO_PERGUNTA_EDITAL"."DS_PERGUNTA" IS 'Lista [{coluna, respostas: [{valor, quantidade}], outras, distintas}] das colunas "Pergunta N" das vagas GRAVADA do edital, na ordem do número. Só respostas que aparecem 2+ vezes (até 30 por pergunta, 200 caracteres cada); as que aparecem uma vez entram só na contagem "outras".';

--
-- Name: COLUMN "TB_RESUMO_PERGUNTA_EDITAL"."QT_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_RESUMO_PERGUNTA_EDITAL"."QT_CANDIDATO" IS 'Candidatos ativos (TB_EMPREGARE_CANDIDATO) das vagas lidas.';

--
-- Name: COLUMN "TB_RESUMO_PERGUNTA_EDITAL"."DS_HASH_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_RESUMO_PERGUNTA_EDITAL"."DS_HASH_VAGA" IS 'md5 das vagas GRAVADA do edital com a execução que as gravou (FC_HASH_VAGA_EDITAL): mudou, o resumo está velho.';

--
-- Name: COLUMN "TB_RESUMO_PERGUNTA_EDITAL"."DT_ATUALIZACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_RESUMO_PERGUNTA_EDITAL"."DT_ATUALIZACAO" IS 'Quando o resumo foi calculado.';

--
-- Name: CONSTRAINT "CK_RESPERGEDT_DSPERGUNTA" ON "TB_RESUMO_PERGUNTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_RESPERGEDT_DSPERGUNTA" ON public."TB_RESUMO_PERGUNTA_EDITAL" IS 'O resumo é uma lista.';

--
-- Name: CONSTRAINT "CK_RESPERGEDT_QTCANDIDATO" ON "TB_RESUMO_PERGUNTA_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_RESPERGEDT_QTCANDIDATO" ON public."TB_RESUMO_PERGUNTA_EDITAL" IS 'Contagem não negativa.';

--
-- Name: TB_ROBO_WORKFLOW; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ROBO_WORKFLOW" (
    "NO_WORKFLOW" character varying(60) NOT NULL,
    "NO_ROBO" character varying(80) NOT NULL,
    "CO_CHAVE" character varying(40),
    "DS_INPUT_ACEITO" text[] DEFAULT '{}'::text[] NOT NULL,
    "ST_DISPARAVEL" character varying(1) NOT NULL,
    "ST_REGISTRO_EXTERNO" character varying(1) NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_ROBOWKF_DSINPUTACEITO" CHECK (((cardinality("DS_INPUT_ACEITO") <= 20) AND (array_to_string("DS_INPUT_ACEITO", ','::text) ~ '^([a-z_]+(,[a-z_]+)*)?$'::text) AND (NOT ('disparado_por'::text = ANY ("DS_INPUT_ACEITO"))) AND ((("ST_DISPARAVEL")::text = 'S'::text) OR (cardinality("DS_INPUT_ACEITO") = 0)))),
    CONSTRAINT "CK_ROBOWKF_NOWORKFLOW" CHECK ((("NO_WORKFLOW")::text ~ '^[a-z0-9]+(-[a-z0-9]+)*\.yml$'::text)),
    CONSTRAINT "CK_ROBOWKF_STDISPARAVEL" CHECK ((("ST_DISPARAVEL")::text = ANY ((ARRAY['S'::character varying, 'N'::character varying])::text[]))),
    CONSTRAINT "CK_ROBOWKF_STREGEXTERNO" CHECK ((("ST_REGISTRO_EXTERNO")::text = ANY ((ARRAY['S'::character varying, 'N'::character varying])::text[])))
);

--
-- Name: TABLE "TB_ROBO_WORKFLOW"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_ROBO_WORKFLOW" IS 'Catálogo dos workflows do GitHub Actions que o banco conhece (20261109180000): os que FC_DISPARAR_ROBO pode pedir (ST_DISPARAVEL), com os inputs aceitos e a chave da automação que manda nos pedidos da agenda, e os que podem se registrar por registrar_disparo_externo (ST_REGISTRO_EXTERNO). Substitui as listas fixas de FC_DISPARAR_ROBO, CK_DISPROBO_NOWORKFLOW, FC_CHAVE_DO_WORKFLOW e registrar_disparo_externo. Escrita só por migration.';

--
-- Name: COLUMN "TB_ROBO_WORKFLOW"."NO_WORKFLOW"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROBO_WORKFLOW"."NO_WORKFLOW" IS 'Arquivo do workflow em .github/workflows (ex.: conferencias.yml).';

--
-- Name: COLUMN "TB_ROBO_WORKFLOW"."NO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROBO_WORKFLOW"."NO_ROBO" IS 'Nome do robô na tela (Status das atualizações).';

--
-- Name: COLUMN "TB_ROBO_WORKFLOW"."CO_CHAVE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROBO_WORKFLOW"."CO_CHAVE" IS 'Chave da automação (TB_CHAVE_AUTOMACAO) que, desligada, impede os pedidos da agenda (origem AGENDA); nulo = sem chave.';

--
-- Name: COLUMN "TB_ROBO_WORKFLOW"."DS_INPUT_ACEITO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROBO_WORKFLOW"."DS_INPUT_ACEITO" IS 'Inputs do workflow_dispatch que o banco aceita mandar (além de disparado_por, que o banco sempre põe).';

--
-- Name: COLUMN "TB_ROBO_WORKFLOW"."ST_DISPARAVEL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROBO_WORKFLOW"."ST_DISPARAVEL" IS 'S = FC_DISPARAR_ROBO pode pedir este workflow; N = só registro (ex.: leitura-de-arquivos.yml) ou histórico.';

--
-- Name: COLUMN "TB_ROBO_WORKFLOW"."ST_REGISTRO_EXTERNO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROBO_WORKFLOW"."ST_REGISTRO_EXTERNO" IS 'S = a execução iniciada direto no GitHub pode se registrar (registrar_disparo_externo, origem GITHUB).';

--
-- Name: COLUMN "TB_ROBO_WORKFLOW"."DT_CRIACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROBO_WORKFLOW"."DT_CRIACAO" IS 'Quando entrou no catálogo.';

--
-- Name: CONSTRAINT "CK_ROBOWKF_DSINPUTACEITO" ON "TB_ROBO_WORKFLOW"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ROBOWKF_DSINPUTACEITO" ON public."TB_ROBO_WORKFLOW" IS 'Até 20 inputs em snake_case, sem disparado_por; workflow que o banco não pede não aceita input.';

--
-- Name: CONSTRAINT "CK_ROBOWKF_NOWORKFLOW" ON "TB_ROBO_WORKFLOW"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ROBOWKF_NOWORKFLOW" ON public."TB_ROBO_WORKFLOW" IS 'Nome de arquivo .yml em kebab-case (vai na URL da API do GitHub).';

--
-- Name: CONSTRAINT "CK_ROBOWKF_STDISPARAVEL" ON "TB_ROBO_WORKFLOW"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ROBOWKF_STDISPARAVEL" ON public."TB_ROBO_WORKFLOW" IS 'S ou N.';

--
-- Name: CONSTRAINT "CK_ROBOWKF_STREGEXTERNO" ON "TB_ROBO_WORKFLOW"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ROBOWKF_STREGEXTERNO" ON public."TB_ROBO_WORKFLOW" IS 'S ou N.';

--
-- Name: TB_ROTEIRO_ASPECTO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ROTEIRO_ASPECTO" (
    "CO_ASPECTO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_ROTEIRO" uuid NOT NULL,
    "NU_ORDEM" smallint NOT NULL,
    "NO_ASPECTO" text NOT NULL,
    CONSTRAINT "CK_ROTEIROASPECTO_ORDEM" CHECK ((("NU_ORDEM" >= 1) AND ("NU_ORDEM" <= 10))),
    CONSTRAINT "CK_ROTEIROASPECTO_TAMANHOS" CHECK (((length("NO_ASPECTO") >= 2) AND (length("NO_ASPECTO") <= 60)))
);

