--

COMMENT ON COLUMN public."TB_ROTEIRO_ASPECTO"."NO_ASPECTO" IS 'Nome do aspecto (ex.: Conceitua, Propriedade, Profundidade).';

--
-- Name: CONSTRAINT "CK_ROTEIROASPECTO_ORDEM" ON "TB_ROTEIRO_ASPECTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ROTEIROASPECTO_ORDEM" ON public."TB_ROTEIRO_ASPECTO" IS 'Até 10 aspectos.';

--
-- Name: CONSTRAINT "CK_ROTEIROASPECTO_TAMANHOS" ON "TB_ROTEIRO_ASPECTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_ROTEIROASPECTO_TAMANHOS" ON public."TB_ROTEIRO_ASPECTO" IS 'Nome de 2 a 60 caracteres.';

--
-- Name: TB_ROTEIRO_COMPETENCIA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ROTEIRO_COMPETENCIA" (
    "CO_COMPETENCIA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_ROTEIRO" uuid NOT NULL,
    "NU_ORDEM" smallint NOT NULL,
    "NO_COMPETENCIA" text NOT NULL,
    "DS_DESCRICAO" text,
    "VL_NOTA_MAXIMA" numeric(5,2) NOT NULL,
    "VL_PESO" numeric(5,2) DEFAULT 1 NOT NULL,
    "VL_MINIMO" numeric(6,2),
    "TP_MINIMO" text DEFAULT 'VALOR'::text NOT NULL,
    "TP_AVALIACAO" text DEFAULT 'INDIVIDUAL'::text NOT NULL,
    CONSTRAINT "CK_ROTEIROCOMPETENCIA_NOTAS" CHECK ((("VL_NOTA_MAXIMA" > (0)::numeric) AND ("VL_NOTA_MAXIMA" <= (100)::numeric) AND ("VL_PESO" > (0)::numeric) AND ("VL_PESO" <= (10)::numeric))),
    CONSTRAINT "CK_ROTEIROCOMPETENCIA_TAMANHOS" CHECK (((length("NO_COMPETENCIA") >= 2) AND (length("NO_COMPETENCIA") <= 200) AND (COALESCE(length("DS_DESCRICAO"), 0) <= 3000))),
    CONSTRAINT "CK_ROTEIROCOMPETENCIA_TPAVALIACAO" CHECK (("TP_AVALIACAO" = ANY (ARRAY['INDIVIDUAL'::text, 'GRUPO'::text]))),
    CONSTRAINT "CK_ROTEIROCOMPETENCIA_TPMINIMO" CHECK (("TP_MINIMO" = ANY (ARRAY['VALOR'::text, 'PERCENTUAL'::text])))
);

--
-- Name: TABLE "TB_ROTEIRO_COMPETENCIA"; Type: COMMENT; Schema: public; Owner: -
