--
-- Name: TB_ROTEIRO_ENTREVISTA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ROTEIRO_ENTREVISTA" (
    "CO_ROTEIRO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_ROTEIRO_ORIGEM" uuid NOT NULL,
    "NU_VERSAO" integer DEFAULT 1 NOT NULL,
    "CO_AREA" text,
    "NO_ROTEIRO" text NOT NULL,
    "DS_DESCRICAO" text,
    "NO_ETAPA" text DEFAULT 'Entrevista'::text NOT NULL,
    "TP_ESCALA" text DEFAULT 'FAIXA'::text NOT NULL,
    "VL_PASSO" numeric(4,2) DEFAULT 0.5 NOT NULL,
    "DS_NOTAS_PERMITIDAS" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "VL_NOTA_MINIMA_TOTAL" numeric(6,2),
    "DS_NOTAS_ELIMINATORIAS" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "ST_AUSENCIA_ELIMINA" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DS_DESEMPATE" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "ST_SOMA_ANALISE" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DS_CONVOCACAO_PADRAO" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "DS_BANCA_PADRAO" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_CRIACAO" uuid,
    "NO_VERSAO" character varying(80),
    CONSTRAINT "CK_ROTEIROENTREVISTA_JSON" CHECK (((jsonb_typeof("DS_NOTAS_PERMITIDAS") = 'array'::text) AND (jsonb_typeof("DS_NOTAS_ELIMINATORIAS") = 'array'::text) AND (jsonb_typeof("DS_DESEMPATE") = 'array'::text) AND (jsonb_typeof("DS_CONVOCACAO_PADRAO") = 'object'::text) AND (jsonb_typeof("DS_BANCA_PADRAO") = 'array'::text))),
    CONSTRAINT "CK_ROTEIROENTREVISTA_NOVERSAO" CHECK ((("NO_VERSAO" IS NULL) OR ((length(("NO_VERSAO")::text) >= 3) AND (length(("NO_VERSAO")::text) <= 80) AND (("NO_VERSAO")::text = btrim(("NO_VERSAO")::text))))),
    CONSTRAINT "CK_ROTEIROENTREVISTA_STATIVO" CHECK ((("ST_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_ROTEIROENTREVISTA_STAUSENCIA" CHECK ((("ST_AUSENCIA_ELIMINA")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_ROTEIROENTREVISTA_STSOMA" CHECK ((("ST_SOMA_ANALISE")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_ROTEIROENTREVISTA_TAMANHOS" CHECK (((length("NO_ROTEIRO") >= 3) AND (length("NO_ROTEIRO") <= 150) AND ((length("NO_ETAPA") >= 3) AND (length("NO_ETAPA") <= 80)) AND (COALESCE(length("DS_DESCRICAO"), 0) <= 2000))),
    CONSTRAINT "CK_ROTEIROENTREVISTA_TPESCALA" CHECK (("TP_ESCALA" = ANY (ARRAY['FAIXA'::text, 'LISTA'::text, 'NIVEIS'::text]))),
    CONSTRAINT "CK_ROTEIROENTREVISTA_VLPASSO" CHECK ((("VL_PASSO" > (0)::numeric) AND ("VL_PASSO" <= (5)::numeric)))
);

--
-- Name: TABLE "TB_ROTEIRO_ENTREVISTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_ROTEIRO_ENTREVISTA" IS 'Roteiro de entrevista (modelo reutilizável por edital): competências, escala, aprovação e desempate. Editar grava uma versão nova (CO_ROTEIRO_ORIGEM + NU_VERSAO); o edital aponta para a versão exata.';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."CO_ROTEIRO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."CO_ROTEIRO" IS 'Identificador desta versão do roteiro.';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."CO_ROTEIRO_ORIGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."CO_ROTEIRO_ORIGEM" IS 'Roteiro de origem (a primeira versão); agrupa as versões.';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."NU_VERSAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."NU_VERSAO" IS 'Número da versão (1, 2, …).';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."CO_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."CO_AREA" IS 'Área a que o roteiro se destina (nulo = qualquer área).';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."NO_ROTEIRO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."NO_ROTEIRO" IS 'Nome do roteiro.';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."DS_DESCRICAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."DS_DESCRICAO" IS 'Descrição / referência ao edital.';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."NO_ETAPA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."NO_ETAPA" IS 'Nome da etapa no edital (Entrevista, Análise Comportamental…).';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."TP_ESCALA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."TP_ESCALA" IS 'FAIXA (0 até o máximo, de VL_PASSO em VL_PASSO), LISTA (DS_NOTAS_PERMITIDAS) ou NIVEIS (TB_ROTEIRO_NIVEL).';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."VL_PASSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."VL_PASSO" IS 'Passo das notas na escala FAIXA (ex.: 0,5).';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."DS_NOTAS_PERMITIDAS"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."DS_NOTAS_PERMITIDAS" IS 'Notas aceitas na escala LISTA (array de números).';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."VL_NOTA_MINIMA_TOTAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."VL_NOTA_MINIMA_TOTAL" IS 'Nota total mínima para ser apto (nulo = sem mínimo).';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."DS_NOTAS_ELIMINATORIAS"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."DS_NOTAS_ELIMINATORIAS" IS 'Notas de competência (média) que eliminam, ex.: [0, 1].';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."ST_AUSENCIA_ELIMINA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."ST_AUSENCIA_ELIMINA" IS 'S: faltar elimina.';

--
-- Name: COLUMN "TB_ROTEIRO_ENTREVISTA"."DS_DESEMPATE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_ENTREVISTA"."DS_DESEMPATE" IS 'Critérios de desempate do resultado final, em ordem (array de textos).';

