-- Name: TB_ROTEIRO_NIVEL; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_ROTEIRO_NIVEL" (
    "CO_ROTEIRO" uuid NOT NULL,
    "VL_NOTA" numeric(5,2) NOT NULL,
    "NO_NIVEL" text NOT NULL,
    "DS_DESCRICAO" text,
    CONSTRAINT "CK_ROTEIRONIVEL_TAMANHOS" CHECK (((length("NO_NIVEL") >= 2) AND (length("NO_NIVEL") <= 80) AND (COALESCE(length("DS_DESCRICAO"), 0) <= 1000)))
);

--
-- Name: TABLE "TB_ROTEIRO_NIVEL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_ROTEIRO_NIVEL" IS 'Níveis descritos da escala (escala NIVEIS): a nota e o que ela significa, mostrados ao avaliador.';

