-- Name: COLUMN "TB_ROTEIRO_NIVEL"."VL_NOTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_ROTEIRO_NIVEL"."VL_NOTA" IS 'Nota do nível.';

