--
-- Name: TB_SELECAO_VAGA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_SELECAO_VAGA" (
    "CO_SELECAO_VAGA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_AREA" text NOT NULL,
    "CO_MONITORAMENTO" uuid,
    "DS_EDITAL" text NOT NULL,
    "CO_VAGA" text,
    "DS_VAGA_PLANILHA" text NOT NULL,
    "NO_UNIDADE" text,
    "NO_CARGO" text,
    "QT_INSCRITO" integer,
    "QT_APTO_ANALISE" integer,
    "QT_CANCELADO" integer,
    "QT_REPROVADO_QUESTIONARIO" integer,
    "QT_ELIMINADO_NOTA" integer,
    "QT_REPROVADO_ANALISE" integer,
    "QT_TRIADO" integer,
    "QT_TOTAL_ELIMINADO" integer,
    "QT_CONVOCADO_PLANILHA" integer,
    "DS_OBSERVACAO" text,
    "DS_CHAVE_ORIGEM" text NOT NULL,
    "CO_SYNC" text,
    "ST_REGISTRO_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_SELECAOVAGA_COVAGA" CHECK ((("CO_VAGA" IS NULL) OR ("CO_VAGA" ~ '^[0-9]{1,20}$'::text))),
    CONSTRAINT "CK_SELECAOVAGA_STREGATIVO" CHECK ((("ST_REGISTRO_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_SELECAOVAGA_TAMANHOS" CHECK (((length("DS_EDITAL") <= 120) AND (length("DS_VAGA_PLANILHA") <= 400) AND (COALESCE(length("NO_UNIDADE"), 0) <= 200) AND (COALESCE(length("NO_CARGO"), 0) <= 400) AND (COALESCE(length("DS_OBSERVACAO"), 0) <= 1000)))
);

--
-- Name: TABLE "TB_SELECAO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_SELECAO_VAGA" IS 'Uma vaga da aba Resultado da planilha "Auditoria" (aba Seleção): o funil da vaga (inscritos, aptos, eliminados, triados) e os convocados antigos. Convocados atuais, aprovados e contratados são calculados na leitura (get_selecao_da_area).';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."CO_SELECAO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."CO_SELECAO_VAGA" IS 'Identificador da linha.';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."CO_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."CO_AREA" IS 'Área da vaga: a do edital ligado; sem edital, a da unidade (TA_UNIDADE_AREA; fora dela, saude-indigena).';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA.id) de mesmo número, de preferência na mesma área e unidade. Nulo: edital não cadastrado.';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."DS_EDITAL"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."DS_EDITAL" IS 'Edital como veio da planilha (coluna B; ex.: 39/2026 (sanitarista), FGV 2025).';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."CO_VAGA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."CO_VAGA" IS 'Código numérico da vaga (coluna A). Nulo nas outras bancas, que trazem o nome do cargo na coluna A.';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."DS_VAGA_PLANILHA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."DS_VAGA_PLANILHA" IS 'Coluna A como veio (código da vaga ou, nas outras bancas, o nome do cargo).';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."NO_UNIDADE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."NO_UNIDADE" IS 'Nome da unidade (coluna C).';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."NO_CARGO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."NO_CARGO" IS 'Nome do cargo (coluna U; sem ela, a coluna A).';

