-- Name: COLUMN "TB_SELECAO_VAGA"."QT_REPROVADO_ANALISE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."QT_REPROVADO_ANALISE" IS 'Reprovados na análise (coluna K).';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."QT_TRIADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."QT_TRIADO" IS 'Triados (coluna L).';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."QT_TOTAL_ELIMINADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SELECAO_VAGA"."QT_TOTAL_ELIMINADO" IS 'Total de eliminados (coluna P).';

--
-- Name: COLUMN "TB_SELECAO_VAGA"."QT_CONVOCADO_PLANILHA"; Type: COMMENT; Schema: public; Owner: -
