CREATE TABLE public."TB_SITUACAO_SISTEMA" (
    "CO_SITUACAO_SISTEMA" smallint DEFAULT 1 NOT NULL,
    "TP_SITUACAO" text DEFAULT 'ATIVA'::text NOT NULL,
    "DS_MENSAGEM_MANUTENCAO" text,
    "DT_PREVISAO_RETORNO" date,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid,
    "ST_COMEMORACAO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    CONSTRAINT "CK_SITUACAOSISTEMA_MENSAGEM" CHECK ((COALESCE(length("DS_MENSAGEM_MANUTENCAO"), 0) <= 500)),
    CONSTRAINT "CK_SITUACAOSISTEMA_STCOMEMORACAO" CHECK ((("ST_COMEMORACAO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_SITUACAOSISTEMA_TPSITUACAO" CHECK (("TP_SITUACAO" = ANY (ARRAY['ATIVA'::text, 'MANUTENCAO'::text]))),
    CONSTRAINT "CK_SITUACAOSISTEMA_UMA" CHECK (("CO_SITUACAO_SISTEMA" = 1))
);

