--
-- Name: TB_SOLICITACAO_ACESSO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_SOLICITACAO_ACESSO" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    email text NOT NULL,
    nome text,
    setor text,
    justificativa text,
    perfil_solicitado text DEFAULT 'usuario'::text NOT NULL,
    status text DEFAULT 'pendente'::text NOT NULL,
    avaliado_por uuid,
    avaliado_em timestamp with time zone,
    observacao_admin text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    "CO_COORDENACAO" text,
    "CO_AREA" text,
    "CO_CARGO_SOLICITADO" text,
    "DS_CARGO_OUTRO" text,
    "CO_MOTIVO_RECUSA" text,
    CONSTRAINT "CK_SOLICACESSO_CARGO" CHECK ((("CO_CARGO_SOLICITADO" IS NULL) OR (("CO_AREA" IS NOT NULL) AND ("CO_CARGO_SOLICITADO" = ANY (ARRAY['AVALIADOR'::text, 'GESTOR'::text, 'CONTRATACAO'::text, 'COORDENACAO_DSEI'::text, 'COORDENACAO_PROJETO'::text, 'COORDENACAO_SEDE'::text, 'JURIDICO'::text, 'APOIO'::text, 'CONSULTA'::text, 'OUTRO'::text]))))),
    CONSTRAINT "CK_SOLICACESSO_CARGOOUTRO" CHECK (
CASE
    WHEN ("CO_CARGO_SOLICITADO" = 'OUTRO'::text) THEN ((length(btrim(COALESCE("DS_CARGO_OUTRO", ''::text))) >= 3) AND (length(btrim(COALESCE("DS_CARGO_OUTRO", ''::text))) <= 120))
    ELSE ("DS_CARGO_OUTRO" IS NULL)
END),
    CONSTRAINT "CK_SOLICACESSO_MOTIVORECUSA" CHECK ((("CO_MOTIVO_RECUSA" IS NULL) OR ((status = 'recusado'::text) AND ("CO_MOTIVO_RECUSA" = ANY (ARRAY['FORA_DO_PUBLICO'::text, 'VINCULO_NAO_CONFIRMADO'::text, 'AREA_OU_LOTACAO'::text, 'JA_TEM_ACESSO'::text, 'JUSTIFICATIVA_INSUFICIENTE'::text, 'OUTRO'::text]))))),
    CONSTRAINT solicitacoes_acesso_status_check CHECK ((status = ANY (ARRAY['pendente'::text, 'aprovado'::text, 'recusado'::text, 'cancelado'::text])))
);

--
-- Name: TABLE "TB_SOLICITACAO_ACESSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_SOLICITACAO_ACESSO" IS 'Pedidos de acesso ao MONITORA de quem entrou com Google e não tem perfil ativo (só por aprovação). Status: pendente, aprovado, recusado, cancelado.';

--
-- Name: COLUMN "TB_SOLICITACAO_ACESSO".setor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SOLICITACAO_ACESSO".setor IS 'Unidade ou lotação informada: DSEI/CASAI (Saúde Indígena), projeto (Projetos) ou setor/diretoria (SEDE); nos pedidos anteriores a 20261021140000, "Área / setor" livre.';

--
-- Name: COLUMN "TB_SOLICITACAO_ACESSO"."CO_COORDENACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SOLICITACAO_ACESSO"."CO_COORDENACAO" IS 'Coordenação pedida. O coordenador dela pode aprovar; null só o admin global.';

--
-- Name: COLUMN "TB_SOLICITACAO_ACESSO"."CO_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SOLICITACAO_ACESSO"."CO_AREA" IS 'Área do pedido (aba da tela): projetos, saude-indigena ou sede. Nulo nos pedidos antigos e na reativação sem área.';

--
-- Name: COLUMN "TB_SOLICITACAO_ACESSO"."CO_CARGO_SOLICITADO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SOLICITACAO_ACESSO"."CO_CARGO_SOLICITADO" IS 'Cargo/função da lista fixa da área (private."FC_CARGO_SOLICITACAO_ACESSO"); sugere o grupo na aprovação.';

--
-- Name: COLUMN "TB_SOLICITACAO_ACESSO"."DS_CARGO_OUTRO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SOLICITACAO_ACESSO"."DS_CARGO_OUTRO" IS 'Descrição do cargo quando "CO_CARGO_SOLICITADO" = OUTRO (3 a 120 caracteres).';

--
-- Name: COLUMN "TB_SOLICITACAO_ACESSO"."CO_MOTIVO_RECUSA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SOLICITACAO_ACESSO"."CO_MOTIVO_RECUSA" IS 'Motivo da recusa (private."FC_MOTIVO_RECUSA_SOLICITACAO"); o texto legível fica em observacao_admin.';

--
-- Name: TB_SUGESTAO_FICHA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_SUGESTAO_FICHA" (
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_EMPREGARE_CANDIDATO" uuid NOT NULL,
    "DS_SUGESTAO" jsonb NOT NULL,
    "CO_EXECUCAO" text,
    "DT_CALCULO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_SUGFICHA_DSSUGESTAO" CHECK ((jsonb_typeof("DS_SUGESTAO") = 'object'::text))
);

--
-- Name: TABLE "TB_SUGESTAO_FICHA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TB_SUGESTAO_FICHA" IS 'Sugestões da ficha da avaliação documental: as linhas de título, curso e vínculo que as respostas do questionário de um inscrito já dão, calculadas pelo job Python da pré-classificação (sugestoes_da_ficha.py). A tela só exibe; nada aqui pontua. Só a RPC da ficha devolve.';

--
-- Name: COLUMN "TB_SUGESTAO_FICHA"."CO_MONITORAMENTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TB_SUGESTAO_FICHA"."CO_MONITORAMENTO" IS 'Edital (TB_MONITORAMENTO_INDIGENA).';

