-- Name: TB_VAGA_IMEDIATA; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TB_VAGA_IMEDIATA" (
    "CO_EDITAL" text NOT NULL,
    "CO_VAGA" text NOT NULL,
    "NO_CARGO" text,
    "QT_VAGA_IMEDIATA" integer DEFAULT 0 NOT NULL,
