    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_VAGA_IMEDIATA_COVAGA" CHECK ((NULLIF(btrim("CO_VAGA"), ''::text) IS NOT NULL)),
