--
-- Name: TD_ALDEIA_DSEI; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TD_ALDEIA_DSEI" (
    "CO_ALDEIA_DSEI" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_UNIDADE" character varying(60) NOT NULL,
    "NO_ALDEIA" character varying(200) NOT NULL,
    "CO_POLO" character varying(20),
    "NO_EXIBICAO" character varying(230) NOT NULL,
    "ST_ATIVO" character varying(1) DEFAULT 'S'::character varying NOT NULL,
    "DS_FONTE" character varying(300) NOT NULL,
    "CO_USUARIO_ATUALIZACAO" uuid NOT NULL,
    "DT_ATUALIZACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_ALDEIADSEI_FONTE" CHECK (((length(btrim(("DS_FONTE")::text)) >= 3) AND (length(btrim(("DS_FONTE")::text)) <= 300))),
    CONSTRAINT "CK_ALDEIADSEI_NOME" CHECK (((length(btrim(("NO_ALDEIA")::text)) >= 1) AND (length(btrim(("NO_ALDEIA")::text)) <= 200) AND ((length(btrim(("NO_EXIBICAO")::text)) >= 1) AND (length(btrim(("NO_EXIBICAO")::text)) <= 230)))),
    CONSTRAINT "CK_ALDEIADSEI_STATIVO" CHECK ((("ST_ATIVO")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text])))
);

