--
-- Name: TH_CONGELAMENTO_INSCRICAO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TH_CONGELAMENTO_INSCRICAO" (
    "CO_EVENTO" bigint NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "TP_EVENTO" character varying(12) NOT NULL,
    "DS_MOTIVO" character varying(500),
    "CO_USUARIO" uuid,
    "CO_LIBERACAO" uuid,
    "CO_DISPARO" bigint,
    "CO_EXECUCAO" character varying(80),
    "DT_VALIDADE" timestamp with time zone,
    "DT_EVENTO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_HISTCONGELINSCR_CAMPOS" CHECK ((((("TP_EVENTO")::text = ANY ((ARRAY['CONGELAR'::character varying, 'DESCONGELAR'::character varying])::text[])) AND ("CO_USUARIO" IS NOT NULL) AND ("DS_MOTIVO" IS NOT NULL) AND ("CO_LIBERACAO" IS NULL) AND ("CO_EXECUCAO" IS NULL) AND ("DT_VALIDADE" IS NULL)) OR ((("TP_EVENTO")::text = 'LIBERACAO'::text) AND ("CO_USUARIO" IS NOT NULL) AND ("DS_MOTIVO" IS NOT NULL) AND ("CO_LIBERACAO" IS NOT NULL) AND ("DT_VALIDADE" IS NOT NULL) AND ("CO_EXECUCAO" IS NULL)) OR ((("TP_EVENTO")::text = 'USO'::text) AND ("CO_LIBERACAO" IS NOT NULL) AND ("CO_EXECUCAO" IS NOT NULL)))),
    CONSTRAINT "CK_HISTCONGELINSCR_COEXECUCAO" CHECK ((("CO_EXECUCAO" IS NULL) OR (("CO_EXECUCAO")::text ~ '^[A-Za-z0-9_-]{8,80}$'::text))),
    CONSTRAINT "CK_HISTCONGELINSCR_DSMOTIVO" CHECK ((("DS_MOTIVO" IS NULL) OR ((length(btrim(("DS_MOTIVO")::text)) >= 10) AND (length(btrim(("DS_MOTIVO")::text)) <= 500)))),
    CONSTRAINT "CK_HISTCONGELINSCR_TPEVENTO" CHECK ((("TP_EVENTO")::text = ANY ((ARRAY['CONGELAR'::character varying, 'DESCONGELAR'::character varying, 'LIBERACAO'::character varying, 'USO'::character varying])::text[])))
);

--
