--

CREATE TABLE public."TH_FICHA_ANALISE" (
    "CO_HISTORICO_FICHA" bigint NOT NULL,
    "CO_FICHA_ANALISE" uuid NOT NULL,
    "NU_VERSAO" integer NOT NULL,
    "TP_ACAO" character varying(16) NOT NULL,
    "TP_SITUACAO_ANTERIOR" character varying(12),
    "TP_SITUACAO" character varying(12) NOT NULL,
    "CO_USUARIO_RESP_ANTERIOR" uuid,
    "CO_USUARIO_RESPONSAVEL" uuid,
    "DS_MOTIVO" character varying(2000),
    "TP_ORIGEM" character varying(6) NOT NULL,
    "CO_USUARIO" uuid,
    "DT_REGISTRO" timestamp with time zone DEFAULT now() NOT NULL,
    "TP_RESULTADO" character varying(16),
    "VL_NOTA_FINAL" numeric(8,4),
    "DS_ALTERACAO" jsonb,
    "DS_RETRATO" jsonb,
    CONSTRAINT "CK_THFICHA_CONTEUDO" CHECK (((("TP_RESULTADO" IS NULL) OR (("TP_RESULTADO")::text = ANY ((ARRAY['APTO'::character varying, 'INAPTO_REQUISITO'::character varying, 'INAPTO_NOTA'::character varying])::text[]))) AND ((COALESCE("VL_NOTA_FINAL", (0)::numeric) >= (0)::numeric) AND (COALESCE("VL_NOTA_FINAL", (0)::numeric) <= (1000)::numeric)) AND (("DS_ALTERACAO" IS NULL) OR (jsonb_typeof("DS_ALTERACAO") = 'array'::text)) AND (("DS_RETRATO" IS NULL) OR (jsonb_typeof("DS_RETRATO") = 'object'::text)) AND ((("TP_ACAO")::text <> 'CONCLUIR'::text) OR ("DS_RETRATO" IS NOT NULL)))),
    CONSTRAINT "CK_THFICHA_MOTIVO" CHECK (((("TP_ACAO")::text <> ALL (ARRAY[('REDISTRIBUIR'::character varying)::text, ('DEVOLVER_FILA'::character varying)::text, ('LIBERAR_RESERVA'::character varying)::text, ('REVISAR'::character varying)::text, ('REABRIR'::character varying)::text, ('REINICIAR'::character varying)::text, ('REFAZER_LOTE'::character varying)::text])) OR ((length(btrim((COALESCE("DS_MOTIVO", ''::character varying))::text)) >= 10) AND (length(btrim((COALESCE("DS_MOTIVO", ''::character varying))::text)) <= 2000)))),
    CONSTRAINT "CK_THFICHA_ORIGEM" CHECK (((("TP_ORIGEM")::text = ANY (ARRAY[('TELA'::character varying)::text, ('JOB'::character varying)::text])) AND ((("TP_ORIGEM")::text = 'JOB'::text) = ("CO_USUARIO" IS NULL)))),
    CONSTRAINT "CK_THFICHA_SITUACOES" CHECK (((("TP_SITUACAO")::text = ANY (ARRAY[('PENDENTE'::character varying)::text, ('EM_ANALISE'::character varying)::text, ('REVISAR'::character varying)::text, ('CONCLUIDA'::character varying)::text, ('FORA_LOTE'::character varying)::text])) AND (("TP_SITUACAO_ANTERIOR" IS NULL) OR (("TP_SITUACAO_ANTERIOR")::text = ANY (ARRAY[('PENDENTE'::character varying)::text, ('EM_ANALISE'::character varying)::text, ('REVISAR'::character varying)::text, ('CONCLUIDA'::character varying)::text, ('FORA_LOTE'::character varying)::text]))))),
    CONSTRAINT "CK_THFICHA_TPACAO" CHECK ((("TP_ACAO")::text = ANY (ARRAY['CRIAR'::text, 'PEGAR'::text, 'RESERVAR'::text, 'LIBERAR'::text, 'LIBERAR_RESERVA'::text, 'DISTRIBUIR'::text, 'REDISTRIBUIR'::text, 'DEVOLVER_FILA'::text, 'REVISAR'::text, 'SAIR_LOTE'::text, 'VOLTAR_LOTE'::text, 'SALVAR'::text, 'CONCLUIR'::text, 'REABRIR'::text, 'REINICIAR'::text, 'REFAZER_LOTE'::text, 'MODALIDADE'::text, 'CORRIGIR'::text])))
);

--
-- Name: TABLE "TH_FICHA_ANALISE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TH_FICHA_ANALISE" IS 'Histórico imutável da ficha: criação, pegar, reservar e liberar, distribuição e redistribuição (com motivo), devolução à fila, envio à revisão, saída ou volta ao lote e, do conteúdo, cada rascunho com alteração (o que mudou), a conclusão (com o retrato do lançamento) e a reabertura (com motivo).';

