CREATE TABLE public."TH_MODELO_CARTA_CONVOCACAO" (
    "CO_MODELO_CARTA" uuid NOT NULL,
    "NU_VERSAO" integer NOT NULL,
    "NO_MODELO" character varying(120) NOT NULL,
    "DS_TITULO" character varying(300) NOT NULL,
    "DS_TEXTO" text NOT NULL,
    "DS_LOCAL" character varying(500),
    "DS_DOCUMENTOS" character varying(5000),
    "DS_CONTATO" character varying(500),
    "NU_PRAZO_DIAS" smallint,
    "DS_MOTIVO" character varying(500),
    "CO_USUARIO" uuid,
    "NO_USUARIO" character varying(255),
    "DS_EMAIL_USUARIO" character varying(320),
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_HISTMODCARTA_MOTIVO" CHECK (((("DS_MOTIVO" IS NULL) OR ((length(("DS_MOTIVO")::text) >= 3) AND (length(("DS_MOTIVO")::text) <= 500))) AND (("NU_VERSAO" = 1) OR ("DS_MOTIVO" IS NOT NULL)))),
    CONSTRAINT "CK_HISTMODCARTA_NUVERSAO" CHECK (("NU_VERSAO" >= 1)),
    CONSTRAINT "CK_HISTMODCARTA_PRAZO" CHECK ((("NU_PRAZO_DIAS" IS NULL) OR (("NU_PRAZO_DIAS" >= 0) AND ("NU_PRAZO_DIAS" <= 90)))),
    CONSTRAINT "CK_HISTMODCARTA_TEXTO" CHECK (((length(btrim("DS_TEXTO")) >= 1) AND (length(btrim("DS_TEXTO")) <= 20000))),
    CONSTRAINT "CK_HISTMODCARTA_TITULO" CHECK (((length(btrim(("DS_TITULO")::text)) >= 1) AND (length(btrim(("DS_TITULO")::text)) <= 300)))
);

--
-- Name: TABLE "TH_MODELO_CARTA_CONVOCACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TH_MODELO_CARTA_CONVOCACAO" IS 'Versões do modelo da carta de convocação. Cada alteração cria uma linha (nada é sobrescrito); a carta emitida guarda a versão usada. Motivo obrigatório a partir da versão 2.';

