--
-- Name: TH_PENDENCIA_APROVADO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TH_PENDENCIA_APROVADO" (
    "CO_EVENTO_PENDENCIA" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_PENDENCIA_APROVADO" uuid NOT NULL,
    "TP_EVENTO" character varying(10) NOT NULL,
    "TP_DECISAO" character varying(30),
    "DS_MOTIVO" character varying(500),
    "DS_ALTERACAO" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "CO_USUARIO" uuid,
    "DS_EMAIL_USUARIO" character varying(320),
    "NO_USUARIO" character varying(200),
    "CO_EXECUCAO" text,
    "DT_EVENTO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_HISTPENDAPROV_ALTERACAO" CHECK (((jsonb_typeof("DS_ALTERACAO") = 'array'::text) AND (jsonb_array_length("DS_ALTERACAO") <= 50))),
    CONSTRAINT "CK_HISTPENDAPROV_AUTOR" CHECK (
CASE
    WHEN (("TP_EVENTO")::text = ANY ((ARRAY['DECISAO'::character varying, 'CORRECAO'::character varying])::text[])) THEN (("CO_USUARIO" IS NOT NULL) AND ("TP_DECISAO" IS NOT NULL) AND ((length(btrim(("DS_MOTIVO")::text)) >= 3) AND (length(btrim(("DS_MOTIVO")::text)) <= 500)))
    ELSE (("CO_USUARIO" IS NULL) AND ("CO_EXECUCAO" IS NOT NULL))
END),
    CONSTRAINT "CK_HISTPENDAPROV_TPEVENTO" CHECK ((("TP_EVENTO")::text = ANY ((ARRAY['ABERTA'::character varying, 'REABERTA'::character varying, 'DECISAO'::character varying, 'CORRECAO'::character varying, 'SANEADA'::character varying])::text[])))
);

