    "CO_VAGA" character varying(20) NOT NULL,
    "TP_SITUACAO_ANTERIOR" character varying(12),
    "TP_SITUACAO" character varying(12) NOT NULL,
    "NU_LOTE_ANTERIOR" smallint,
    "NU_LOTE" smallint,
    "NU_POSICAO" integer,
    "DS_MOTIVO" character varying(300),
    "DT_REGISTRO" timestamp with time zone DEFAULT now() NOT NULL,
    "CO_USUARIO" uuid,
    CONSTRAINT "CK_THPRECLASSIF_ORIGEM" CHECK ((("CO_EXECUCAO" IS NOT NULL) OR ("CO_USUARIO" IS NOT NULL))),
    CONSTRAINT "CK_THPRECLASSIF_SITUACOES" CHECK (((("TP_SITUACAO")::text = ANY (ARRAY[('ELIMINADO'::character varying)::text, ('RANQUEADO'::character varying)::text, ('NO_LOTE'::character varying)::text, ('ANALISADO'::character varying)::text])) AND (("TP_SITUACAO_ANTERIOR" IS NULL) OR (("TP_SITUACAO_ANTERIOR")::text = ANY (ARRAY[('ELIMINADO'::character varying)::text, ('RANQUEADO'::character varying)::text, ('NO_LOTE'::character varying)::text, ('ANALISADO'::character varying)::text])))))
);

