-- Name: TH_PUBLICACAO_APROVADO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TH_PUBLICACAO_APROVADO" (
    "CO_PUBLICACAO" uuid DEFAULT gen_random_uuid() NOT NULL,
    "CO_MONITORAMENTO" uuid NOT NULL,
    "CO_LISTA_APROVADO" uuid NOT NULL,
    "CO_LISTA_APROVADO_ANTERIOR" uuid,
    "TP_ORIGEM" character varying(15) NOT NULL,
    "CO_LISTA_CLASSIFICACAO" uuid,
    "CO_REGRA_CLASSIFICACAO" uuid,
    "NU_VERSAO_REGRA" integer,
    "DS_HASH_CLASSIFICACAO" character varying(64),
    "QT_CANDIDATO" integer DEFAULT 0 NOT NULL,
    "QT_ENTRA" integer DEFAULT 0 NOT NULL,
    "QT_SAI" integer DEFAULT 0 NOT NULL,
    "QT_MUDA_POSICAO" integer DEFAULT 0 NOT NULL,
    "QT_PRESERVADO" integer DEFAULT 0 NOT NULL,
    "QT_SUB_JUDICE_MANTIDO" integer DEFAULT 0 NOT NULL,
    "DS_VINCULO" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "DS_PENDENCIA" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "DS_MOTIVO" text,
    "CO_USUARIO" uuid NOT NULL,
    "DS_EMAIL_USUARIO" character varying(320),
    "NO_USUARIO" character varying(255),
    "DT_PUBLICACAO" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "CK_PUBAPROVADO_DSMOTIVO" CHECK ((("DS_MOTIVO" IS NULL) OR ((length("DS_MOTIVO") >= 3) AND (length("DS_MOTIVO") <= 500)))),
    CONSTRAINT "CK_PUBAPROVADO_JSON" CHECK (((jsonb_typeof("DS_VINCULO") = 'array'::text) AND (jsonb_typeof("DS_PENDENCIA") = 'array'::text))),
    CONSTRAINT "CK_PUBAPROVADO_ORIGEM" CHECK ((((("TP_ORIGEM")::text = 'CLASSIFICACAO'::text) = ("CO_LISTA_CLASSIFICACAO" IS NOT NULL)) AND ((("TP_ORIGEM")::text = 'XLSX'::text) OR (("CO_REGRA_CLASSIFICACAO" IS NOT NULL) AND ("NU_VERSAO_REGRA" IS NOT NULL) AND ("DS_HASH_CLASSIFICACAO" IS NOT NULL))))),
    CONSTRAINT "CK_PUBAPROVADO_QUANTIDADES" CHECK ((("QT_CANDIDATO" >= 0) AND ("QT_ENTRA" >= 0) AND ("QT_SAI" >= 0) AND ("QT_MUDA_POSICAO" >= 0) AND ("QT_PRESERVADO" >= 0) AND ("QT_SUB_JUDICE_MANTIDO" >= 0))),
    CONSTRAINT "CK_PUBAPROVADO_TPORIGEM" CHECK ((("TP_ORIGEM")::text = ANY (ARRAY[('XLSX'::character varying)::text, ('CLASSIFICACAO'::character varying)::text])))
);

