    CONSTRAINT "CK_HISTRECURSO_TPACAO" CHECK (("TP_ACAO" = ANY (ARRAY['criacao'::text, 'edicao'::text, 'etapa'::text, 'exclusao'::text, 'anexo'::text, 'resposta'::text, 'parecer'::text, 'ajuste'::text])))
);

--
-- Name: TABLE "TH_RECURSO_CANDIDATO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TH_RECURSO_CANDIDATO" IS 'Histórico (auditoria) dos recursos: criação, cada campo editado, cada etapa marcada ou desmarcada e a exclusão.';

--
-- Name: COLUMN "TH_RECURSO_CANDIDATO"."CO_HISTORICO_RECURSO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TH_RECURSO_CANDIDATO"."CO_HISTORICO_RECURSO" IS 'Identificador do registro de histórico.';

