--

COMMENT ON CONSTRAINT "CK_HISTRECURSO_TPACAO" ON public."TH_RECURSO_CANDIDATO" IS 'Ações registradas: criacao, edicao, etapa, exclusao, anexo, resposta, parecer (fluxo jurídico) e ajuste (ajuste da pontuação).';

--
-- Name: TH_RECURSO_CANDIDATO_CO_HISTORICO_RECURSO_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public."TH_RECURSO_CANDIDATO" ALTER COLUMN "CO_HISTORICO_RECURSO" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public."TH_RECURSO_CANDIDATO_CO_HISTORICO_RECURSO_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

