--

CREATE TABLE public."TH_REGRA_ANALISE" (
    "CO_REGRA_ANALISE" uuid NOT NULL,
    "NU_VERSAO" integer NOT NULL,
    "DS_CONFIGURACAO" jsonb NOT NULL,
    "DS_HASH" character varying(64) NOT NULL,
    "DS_MOTIVO" character varying(2000),
    "CO_USUARIO" uuid NOT NULL,
    "DT_CRIACAO" timestamp with time zone DEFAULT now() NOT NULL,
    "NO_VERSAO" character varying(80),
    CONSTRAINT "CK_THREGRAANALISE_CONFIG" CHECK ((jsonb_typeof("DS_CONFIGURACAO") = 'object'::text)),
    CONSTRAINT "CK_THREGRAANALISE_DSHASH" CHECK ((("DS_HASH")::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT "CK_THREGRAANALISE_MOTIVO" CHECK ((("NU_VERSAO" = 1) OR ((length(btrim((COALESCE("DS_MOTIVO", ''::character varying))::text)) >= 10) AND (length(btrim((COALESCE("DS_MOTIVO", ''::character varying))::text)) <= 2000)))),
    CONSTRAINT "CK_THREGRAANALISE_NOVERSAO" CHECK ((("NO_VERSAO" IS NULL) OR ((length(("NO_VERSAO")::text) >= 3) AND (length(("NO_VERSAO")::text) <= 80) AND (("NO_VERSAO")::text = btrim(("NO_VERSAO")::text))))),
    CONSTRAINT "CK_THREGRAANALISE_NUVERSAO" CHECK (("NU_VERSAO" >= 1))
);

