    CONSTRAINT "CK_CONFER_LISTAS" CHECK (((jsonb_typeof("DS_CONFERENCIA") = 'array'::text) AND (jsonb_typeof("DS_FALHA") = 'array'::text))),
    CONSTRAINT "CK_CONFER_QT" CHECK ((("QT_AVISO_NOVO" >= 0) AND ("QT_AVISO_ABERTO" >= 0) AND ("QT_AVISO_RESOLVIDO" >= 0))),
    CONSTRAINT "CK_CONFER_TAMANHOS" CHECK (((COALESCE(length("DS_MENSAGEM"), 0) <= 2000) AND (("DS_URL_EXECUCAO" IS NULL) OR (("DS_URL_EXECUCAO" ~ '^https://github\.com/'::text) AND (length("DS_URL_EXECUCAO") <= 300))))),
    CONSTRAINT "CK_CONFER_TPDISPARO" CHECK (("TP_DISPARO" = ANY (ARRAY['AGENDA'::text, 'MONITORA'::text, 'GITHUB'::text]))),
    CONSTRAINT "CK_CONFER_TPSITUACAO" CHECK (("TP_SITUACAO" = ANY (ARRAY['EM_ANDAMENTO'::text, 'CONCLUIDA'::text, 'PARCIAL'::text, 'FALHOU'::text]))),
    CONSTRAINT "CK_CONFER_USUARIO" CHECK ((("TP_DISPARO" = 'MONITORA'::text) = ("CO_USUARIO_DISPARO" IS NOT NULL)))
);

