-- Name: COLUMN "TL_CONFERENCIA"."QT_AVISO_ABERTO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_CONFERENCIA"."QT_AVISO_ABERTO" IS 'Avisos abertos ao fim da execução (todas as conferências).';

