--
-- Name: TL_DISPARO_ROBO; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TL_DISPARO_ROBO" (
    "CO_DISPARO" bigint NOT NULL,
    "NO_WORKFLOW" text NOT NULL,
    "DT_DISPARO" timestamp with time zone DEFAULT now() NOT NULL,
    "TP_ORIGEM" text NOT NULL,
    "CO_USUARIO" uuid,
    "CO_PEDIDO_HTTP" bigint,
    "TP_SITUACAO" text NOT NULL,
    "NU_STATUS_HTTP" integer,
    "DT_RESPOSTA" timestamp with time zone,
    "DS_MENSAGEM" text,
    "NO_ATOR_GITHUB" character varying(100),
    "DS_URL_EXECUCAO" character varying(300),
    CONSTRAINT "CK_DISPROBO_DSMENSAGEM" CHECK ((COALESCE(length("DS_MENSAGEM"), 0) <= 300)),
    CONSTRAINT "CK_DISPROBO_DSURL" CHECK ((("DS_URL_EXECUCAO" IS NULL) OR (("DS_URL_EXECUCAO")::text ~ '^https://github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+/actions/runs/[0-9]+$'::text))),
    CONSTRAINT "CK_DISPROBO_GITHUB" CHECK (((("TP_ORIGEM" = 'GITHUB'::text) = ("TP_SITUACAO" = 'INICIADO'::text)) AND (("TP_ORIGEM" = 'GITHUB'::text) = ("DS_URL_EXECUCAO" IS NOT NULL)) AND (("TP_ORIGEM" = 'GITHUB'::text) OR ("NO_ATOR_GITHUB" IS NULL)))),
    CONSTRAINT "CK_DISPROBO_NUSTATUS" CHECK ((("NU_STATUS_HTTP" IS NULL) OR (("NU_STATUS_HTTP" >= 100) AND ("NU_STATUS_HTTP" <= 599)))),
    CONSTRAINT "CK_DISPROBO_PEDIDO" CHECK (((("TP_SITUACAO" = ANY (ARRAY['SEM_TOKEN'::text, 'INICIADO'::text])) AND ("CO_PEDIDO_HTTP" IS NULL)) OR (("TP_SITUACAO" = ANY (ARRAY['PEDIDO'::text, 'ACEITO'::text])) AND ("CO_PEDIDO_HTTP" IS NOT NULL)) OR ("TP_SITUACAO" = 'FALHOU'::text))),
    CONSTRAINT "CK_DISPROBO_TPORIGEM" CHECK (("TP_ORIGEM" = ANY (ARRAY['AGENDA'::text, 'MONITORA'::text, 'MANUAL'::text, 'GITHUB'::text]))),
    CONSTRAINT "CK_DISPROBO_TPSITUACAO" CHECK (("TP_SITUACAO" = ANY (ARRAY['PEDIDO'::text, 'ACEITO'::text, 'FALHOU'::text, 'SEM_TOKEN'::text, 'INICIADO'::text]))),
    CONSTRAINT "CK_DISPROBO_USUARIO" CHECK ((("TP_ORIGEM" = 'MONITORA'::text) = ("CO_USUARIO" IS NOT NULL)))
);

--
-- Name: TABLE "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TL_DISPARO_ROBO" IS 'Pedidos de execução dos robôs (workflow_dispatch do GitHub) feitos pelo banco — na hora da agenda (pg_cron, AGENDA), no Rodar agora / Opções / Recalcular do MONITORA (disparar_robo, MONITORA) e chamados direto pelo SQL sem usuário (MANUAL, 20261020170000), sempre por FC_DISPARAR_ROBO — e as execuções iniciadas direto no GitHub (GITHUB, registradas pelo próprio workflow por registrar_disparo_externo, 20261020170000). Uma linha por pedido ou execução; nunca guarda a chave. Os pedidos são fechados por FC_CONFERIR_DISPAROS_ROBO (net._http_response); linhas com mais de 30 dias saem. Leitura só por get_saude_das_cargas e situacao_do_disparo_robo.';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."CO_DISPARO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."CO_DISPARO" IS 'Identificador do pedido (sequencial).';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."NO_WORKFLOW"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."NO_WORKFLOW" IS 'Arquivo do workflow (catálogo TB_ROBO_WORKFLOW, 20261109180000).';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."DT_DISPARO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."DT_DISPARO" IS 'Quando o banco fez o pedido.';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."TP_ORIGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."TP_ORIGEM" IS 'AGENDA (tarefa do pg_cron), MONITORA (Rodar agora, Opções ou Recalcular de quem está logado), MANUAL (FC_DISPARAR_ROBO chamado direto pelo SQL, sem usuário) ou GITHUB (Run workflow / gh workflow run, registrada pelo workflow).';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."CO_USUARIO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."CO_USUARIO" IS 'Quem pediu pelo MONITORA (auth.users.id; vai ao workflow como disparado_por); nulo nas outras origens.';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."CO_PEDIDO_HTTP"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."CO_PEDIDO_HTTP" IS 'Id do pedido no pg_net (net._http_response.id); nulo em SEM_TOKEN.';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."TP_SITUACAO" IS 'PEDIDO (aguardando a resposta), ACEITO (o GitHub respondeu 2xx — 204), FALHOU (outro código, tempo esgotado ou sem resposta), SEM_TOKEN (sem a chave github_disparo_robos no Vault; nada foi pedido) ou INICIADO (execução iniciada direto no GitHub, origem GITHUB).';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."NU_STATUS_HTTP"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."NU_STATUS_HTTP" IS 'Código HTTP da resposta do GitHub (204 = aceito; 401 = chave inválida ou expirada; 403/404 = chave sem permissão no repositório; 422 = input recusado).';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."DT_RESPOSTA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."DT_RESPOSTA" IS 'Quando a resposta chegou (ou quando o pedido foi dado como sem resposta).';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."DS_MENSAGEM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."DS_MENSAGEM" IS 'Motivo curto da falha (a mensagem do GitHub, "tempo esgotado"…); nunca a chave.';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."NO_ATOR_GITHUB"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."NO_ATOR_GITHUB" IS 'Origem GITHUB: quem iniciou a execução no GitHub (github.triggering_actor).';

--
-- Name: COLUMN "TL_DISPARO_ROBO"."DS_URL_EXECUCAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_DISPARO_ROBO"."DS_URL_EXECUCAO" IS 'Origem GITHUB: endereço da execução no GitHub Actions (uma linha por execução).';

--
-- Name: CONSTRAINT "CK_DISPROBO_DSMENSAGEM" ON "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_DISPROBO_DSMENSAGEM" ON public."TL_DISPARO_ROBO" IS 'Mensagem até 300 caracteres.';

--
-- Name: CONSTRAINT "CK_DISPROBO_DSURL" ON "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_DISPROBO_DSURL" ON public."TL_DISPARO_ROBO" IS 'Endereço de execução do GitHub Actions.';

--
-- Name: CONSTRAINT "CK_DISPROBO_GITHUB" ON "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_DISPROBO_GITHUB" ON public."TL_DISPARO_ROBO" IS 'Origem GITHUB ⇔ situação INICIADO ⇔ endereço da execução; ator só na origem GITHUB.';

--
-- Name: CONSTRAINT "CK_DISPROBO_NUSTATUS" ON "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_DISPROBO_NUSTATUS" ON public."TL_DISPARO_ROBO" IS 'Código HTTP entre 100 e 599.';

--
-- Name: CONSTRAINT "CK_DISPROBO_PEDIDO" ON "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_DISPROBO_PEDIDO" ON public."TL_DISPARO_ROBO" IS 'SEM_TOKEN e INICIADO não têm pedido no pg_net; PEDIDO e ACEITO sempre têm.';

--
-- Name: CONSTRAINT "CK_DISPROBO_TPORIGEM" ON "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_DISPROBO_TPORIGEM" ON public."TL_DISPARO_ROBO" IS 'Origens válidas.';

--
-- Name: CONSTRAINT "CK_DISPROBO_TPSITUACAO" ON "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_DISPROBO_TPSITUACAO" ON public."TL_DISPARO_ROBO" IS 'Situações válidas.';

--
-- Name: CONSTRAINT "CK_DISPROBO_USUARIO" ON "TL_DISPARO_ROBO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT "CK_DISPROBO_USUARIO" ON public."TL_DISPARO_ROBO" IS 'Usuário só (e sempre) no pedido pelo MONITORA.';

--
-- Name: TL_DISPARO_ROBO_CO_DISPARO_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public."TL_DISPARO_ROBO" ALTER COLUMN "CO_DISPARO" ADD GENERATED ALWAYS AS IDENTITY (
