--
-- Name: TL_SYNC_EMPREGARE; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."TL_SYNC_EMPREGARE" (
    "CO_SYNC" text NOT NULL,
    "DT_INICIO" timestamp with time zone DEFAULT now() NOT NULL,
    "DT_FIM" timestamp with time zone,
    "TP_SITUACAO" text DEFAULT 'EM_ANDAMENTO'::text NOT NULL,
    "TP_DISPARO" text NOT NULL,
    "CO_USUARIO_DISPARO" uuid,
    "ST_FORCADA" character varying(1) DEFAULT 'N'::character varying NOT NULL,
    "DS_FILTRO" jsonb DEFAULT '{}'::jsonb NOT NULL,
    "QT_VAGA_PEDIDA" integer DEFAULT 0 NOT NULL,
    "QT_VAGA_BAIXADA" integer DEFAULT 0 NOT NULL,
    "QT_VAGA_FALHA" integer DEFAULT 0 NOT NULL,
    "QT_VAGA_RECUSADA" integer DEFAULT 0 NOT NULL,
    "QT_LINHA" integer DEFAULT 0 NOT NULL,
    "QT_DESATIVADA" integer DEFAULT 0 NOT NULL,
    "DS_MENSAGEM" text,
    "DS_URL_EXECUCAO" text,
    CONSTRAINT "CK_SYNCEMPREG_COSYNC" CHECK (("CO_SYNC" ~ '^[A-Za-z0-9_-]{8,80}$'::text)),
    CONSTRAINT "CK_SYNCEMPREG_FILTRO" CHECK ((jsonb_typeof("DS_FILTRO") = 'object'::text)),
    CONSTRAINT "CK_SYNCEMPREG_QT" CHECK ((("QT_VAGA_PEDIDA" >= 0) AND ("QT_VAGA_BAIXADA" >= 0) AND ("QT_VAGA_FALHA" >= 0) AND ("QT_VAGA_RECUSADA" >= 0) AND ("QT_LINHA" >= 0) AND ("QT_DESATIVADA" >= 0))),
    CONSTRAINT "CK_SYNCEMPREG_STFORCADA" CHECK ((("ST_FORCADA")::text = ANY (ARRAY[('S'::character varying)::text, ('N'::character varying)::text]))),
    CONSTRAINT "CK_SYNCEMPREG_TAMANHOS" CHECK (((COALESCE(length("DS_MENSAGEM"), 0) <= 2000) AND (("DS_URL_EXECUCAO" IS NULL) OR (("DS_URL_EXECUCAO" ~ '^https://github\.com/'::text) AND (length("DS_URL_EXECUCAO") <= 300))))),
    CONSTRAINT "CK_SYNCEMPREG_TPDISPARO" CHECK (("TP_DISPARO" = ANY (ARRAY['AGENDA'::text, 'MONITORA'::text, 'GITHUB'::text]))),
    CONSTRAINT "CK_SYNCEMPREG_TPSITUACAO" CHECK (("TP_SITUACAO" = ANY (ARRAY['EM_ANDAMENTO'::text, 'CONCLUIDA'::text, 'PARCIAL'::text, 'FALHOU'::text]))),
    CONSTRAINT "CK_SYNCEMPREG_USUARIO" CHECK ((("TP_DISPARO" = 'MONITORA'::text) = ("CO_USUARIO_DISPARO" IS NOT NULL)))
);

--
-- Name: TABLE "TL_SYNC_EMPREGARE"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public."TL_SYNC_EMPREGARE" IS 'Log das execuções do robô da Empregare (scripts/robo-empregare/): uma linha por execução.';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."CO_SYNC"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_SYNC_EMPREGARE"."CO_SYNC" IS 'Identificador da execução (gerado pelo robô: gh-<data>-<sufixo>).';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."DT_INICIO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_SYNC_EMPREGARE"."DT_INICIO" IS 'Início da execução.';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."DT_FIM"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_SYNC_EMPREGARE"."DT_FIM" IS 'Fechamento (finalizar_sync_empregare). Nulo enquanto roda.';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."TP_SITUACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_SYNC_EMPREGARE"."TP_SITUACAO" IS 'EM_ANDAMENTO; CONCLUIDA (todas as vagas gravadas); PARCIAL (alguma vaga falhou ou foi recusada pela trava); FALHOU (erro geral ou nenhuma vaga baixada).';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."TP_DISPARO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_SYNC_EMPREGARE"."TP_DISPARO" IS 'Quem disparou: AGENDA (horário do workflow), MONITORA (botão Rodar agora) ou GITHUB (Run workflow na aba Actions).';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."CO_USUARIO_DISPARO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_SYNC_EMPREGARE"."CO_USUARIO_DISPARO" IS 'Usuário do MONITORA (auth.users.id) que clicou em Rodar agora; nulo nos outros disparos.';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."ST_FORCADA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_SYNC_EMPREGARE"."ST_FORCADA" IS 'S: rodou com forçar (a trava de metade dos candidatos não vale).';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."DS_FILTRO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public."TL_SYNC_EMPREGARE"."DS_FILTRO" IS 'Filtro pedido: {"editais": [...], "vagas": [...], "limite": n}; vazio = vagas dos editais em curso.';

--
-- Name: COLUMN "TL_SYNC_EMPREGARE"."QT_VAGA_PEDIDA"; Type: COMMENT; Schema: public; Owner: -
--

