--
-- Name: migracoes_aplicadas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.migracoes_aplicadas (
    caminho text NOT NULL,
    hash text NOT NULL,
    origem text DEFAULT 'arquivo'::text NOT NULL,
    aplicada_em timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_migracoes_aplicadas_caminho CHECK ((caminho ~ '^(migrations|correcoes)/[^/]+\.sql$'::text)),
    CONSTRAINT ck_migracoes_aplicadas_origem CHECK ((origem = ANY (ARRAY['arquivo'::text, 'registro-historico'::text])))
);

--
-- Name: TABLE migracoes_aplicadas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.migracoes_aplicadas IS 'Histórico do que já foi aplicado no banco, mantido por scripts/estado-das-migrations.mjs. Sem policy de RLS: só alcançável com credencial de servidor.';

--
-- Name: COLUMN migracoes_aplicadas.caminho; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.migracoes_aplicadas.caminho IS 'Caminho do ficheiro a partir de supabase/, por exemplo migrations/20260921130000_x.sql.';

--
-- Name: COLUMN migracoes_aplicadas.hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.migracoes_aplicadas.hash IS 'sha256 do conteúdo do ficheiro no momento da aplicação. Divergência significa que o ficheiro mudou depois de aplicado.';

--
-- Name: COLUMN migracoes_aplicadas.origem; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.migracoes_aplicadas.origem IS 'arquivo: o script viu correr. registro-historico: marcado como já aplicado, sem executar.';

--
-- Name: CONSTRAINT ck_migracoes_aplicadas_caminho ON migracoes_aplicadas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT ck_migracoes_aplicadas_caminho ON public.migracoes_aplicadas IS 'O caminho como o disco o escreve: migrations/<arquivo>.sql ou correcoes/<arquivo>.sql (sem o prefixo supabase/). 20261022151000.';

