--
-- Name: POLICY "PL_ABA_AREA_LEITURA" ON "RL_ABA_AREA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY "PL_ABA_AREA_LEITURA" ON public."RL_ABA_AREA" IS 'Abas por área: todo autenticado lê. Escrita só pela futura RPC de manutenção.';

--
-- Name: TB_ABA PL_ABA_LEITURA; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "PL_ABA_LEITURA" ON public."TB_ABA" FOR SELECT TO authenticated USING (true);

--
-- Name: POLICY "PL_ABA_LEITURA" ON "TB_ABA"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY "PL_ABA_LEITURA" ON public."TB_ABA" IS 'Catálogo do menu: todo autenticado lê. Escrita só pela futura RPC de manutenção.';

--
-- Name: TB_ANALISE_CURRICULAR PL_ANALISE_CURRICULAR_AREA; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "PL_ANALISE_CURRICULAR_AREA" ON public."TB_ANALISE_CURRICULAR" AS RESTRICTIVE FOR SELECT TO authenticated USING ((( SELECT private.is_master() AS is_master) OR (("CO_AREA" = ANY (( SELECT private."FC_AREAS_USUARIO"() AS "FC_AREAS_USUARIO")::text[])) AND ((( SELECT private."FC_EDITAIS_VISIVEIS"() AS "FC_EDITAIS_VISIVEIS") IS NULL) OR (edital_norm = ANY (( SELECT private."FC_EDITAIS_NORM_VISIVEIS"() AS "FC_EDITAIS_NORM_VISIVEIS")::text[])) OR (unidade_norm = ANY (( SELECT private."FC_UNIDADES_NORM_VISIVEIS"() AS "FC_UNIDADES_NORM_VISIVEIS")::text[]))))));

--
-- Name: TB_AREA PL_AREA_LEITURA; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "PL_AREA_LEITURA" ON public."TB_AREA" FOR SELECT TO authenticated USING (true);

