CREATE POLICY "PL_CONFIGURACAO_LEITURA_HOOK_AUTH" ON public."TB_CONFIGURACAO" FOR SELECT TO supabase_auth_admin USING ((chave = 'auth_google_allowed_domains'::text));

--
-- Name: POLICY "PL_CONFIGURACAO_LEITURA_HOOK_AUTH" ON "TB_CONFIGURACAO"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY "PL_CONFIGURACAO_LEITURA_HOOK_AUTH" ON public."TB_CONFIGURACAO" IS 'O Supabase Auth (supabase_auth_admin) lê só a lista de domínios institucionais, para o hook FC_HOOK_ANTES_CRIAR_USUARIO.';

--
-- Name: TB_CONVOCACAO_EDITAL PL_CONVOCACAO_EDITAL_AREA; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "PL_CONVOCACAO_EDITAL_AREA" ON public."TB_CONVOCACAO_EDITAL" AS RESTRICTIVE FOR SELECT TO authenticated USING (("CO_EDITAL" IN ( SELECT (m.id)::text AS id
   FROM public."TB_MONITORAMENTO_INDIGENA" m)));

--
-- Name: TB_EDITAL_ANALISE PL_EDITAL_ANALISE_AREA; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "PL_EDITAL_ANALISE_AREA" ON public."TB_EDITAL_ANALISE" AS RESTRICTIVE FOR SELECT TO authenticated USING ((( SELECT private.is_master() AS is_master) OR ((grupo_norm IN ( SELECT public.analises_norm_key(a."NO_GRUPO_PLANILHA") AS analises_norm_key
   FROM public."TB_AREA" a
  WHERE (a."CO_AREA" = ANY (( SELECT private."FC_AREAS_USUARIO"() AS "FC_AREAS_USUARIO")::text[])))) AND ((( SELECT private."FC_EDITAIS_VISIVEIS"() AS "FC_EDITAIS_VISIVEIS") IS NULL) OR (edital_norm = ANY (( SELECT private."FC_EDITAIS_NORM_VISIVEIS"() AS "FC_EDITAIS_NORM_VISIVEIS")::text[])) OR (unidade_norm = ANY (( SELECT private."FC_UNIDADES_NORM_VISIVEIS"() AS "FC_UNIDADES_NORM_VISIVEIS")::text[]))))));

